				Color color = ((currentMapPoint == bossMapPoint || currentMapPoint == secondBossMapPoint) ? act.MapTraveledColor : act.MapUntraveledColor);
				shaderMaterial.SetShaderParameter(_tintColor, new Godot.Vector3(color.R, color.G, color.B));
				shaderMaterial2.SetShaderParameter(_tintColor, new Godot.Vector3(color.R, color.G, color.B));
			}
		}

