	/// <summary>
	/// TEMPORARY: This class handles the one-time migration of user data from before profiles existed.
	///
	/// This migrator is designed to help existing playtesters transition their save data, replays,
	/// and console history to the new platform-specific, user-scoped directory structure without
	/// losing their progress.
	///
	/// This class should be removed a few months after the user profile feature has been
	/// released to playtesters, once we're confident that all active users have migrated their data.
	///
	/// The migration moves all data from user://{platform}/{userId}/saves/ -&gt; user://{platform}/{userId}/profile1/saves/
	/// </summary>
	public static class ProfileAccountScopeMigrator
	{
		private static bool _migrationPerformed;

		public static void MigrateToProfileScopedDirectories()
		{
			if (!HasLegacyData())
			{
				Log.VeryDebug("No legacy unscoped data found, skipping migration");
				return;
			}
			Log.Info("Starting migration of account-scoped data to profile-scoped directories");
			string text = ProjectSettings.GlobalizePath(UserDataPathProvider.GetAccountScopedBasePath(""));
			string text2 = ProjectSettings.GlobalizePath(UserDataPathProvider.GetProfileScopedBasePath(1));
			Directory.CreateDirectory(text2);
			bool flag = MigrationUtil.MigrateFile("settings.save", text + "/saves", text);
			bool flag2 = MigrationUtil.MigrateDirectory("saves", text, text2);
			bool flag3 = MigrationUtil.MigrateDirectory("replays", text, text2);
			bool flag4 = MigrationUtil.MigrateFile("console_history.log", text, text2);
			_migrationPerformed = flag | flag2 | flag3 | flag4;
			if (_migrationPerformed)
			{
				Log.Info("Migration to profile-scoped directories completed successfully");
			}
			else
			{
				Log.Info("No items were migrated (all destinations already existed)");
			}
		}

		private static bool HasLegacyData()
		{
			if (!DirAccess.DirExistsAbsolute(UserDataPathProvider.GetAccountScopedBasePath("saves")))
			{
				return DirAccess.DirExistsAbsolute(UserDataPathProvider.GetAccountScopedBasePath("replays"));
			}
			return true;
		}

		public static void ArchiveLegacyData()
		{
			if (!_migrationPerformed)
			{
				Log.VeryDebug("No migration was performed, skipping archival of legacy data");
			}
			else if (HasLegacyData())
			{
				Log.Info("Archiving account-scoped data after successful profile-scoped migration");
				string path = ProjectSettings.GlobalizePath(UserDataPathProvider.GetAccountScopedBasePath(""));
				string text = Path.Combine(path, "legacy_backup");
				if (Directory.Exists(text))
				{
					Log.Warn("Deleting legacy data archive that already exists");
					Directory.Delete(text, recursive: true);
				}
				Directory.CreateDirectory(text);
				MigrationUtil.ArchiveLegacyDirectory(Path.Combine(path, "saves"), text);
				MigrationUtil.ArchiveLegacyDirectory(Path.Combine(path, "replays"), text);
				MigrationUtil.ArchiveLegacyFile(Path.Combine(path, "console_history.log"), text);
				string path2 = ProjectSettings.GlobalizePath(UserDataPathProvider.GetProfileScopedBasePath(1));
				File.Delete(Path.Combine(path2, "saves/settings.save"));
				Log.Info("Legacy data archived to 'legacy_backup' folder");
			}
		}
	}
	/// <summary>
	/// Domain type for player progress. Separates runtime representation from the JSON wire format
	/// (<see cref="T:MegaCrit.Sts2.Core.Saves.SerializableProgress" />). Uses dictionaries for stat lookups and hashsets for deduplication
	/// of discovered content.
	/// </summary>
	public class ProgressState
	{
		private static readonly System.Collections.Generic.Dictionary<string, Achievement> _achievementsByName = BuildAchievementLookup();

		private readonly System.Collections.Generic.Dictionary<ModelId, CharacterStats> _characterStats = new System.Collections.Generic.Dictionary<ModelId, CharacterStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, CardStats> _cardStats = new System.Collections.Generic.Dictionary<ModelId, CardStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, EncounterStats> _encounterStats = new System.Collections.Generic.Dictionary<ModelId, EncounterStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, EnemyStats> _enemyStats = new System.Collections.Generic.Dictionary<ModelId, EnemyStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, AncientStats> _ancientStats = new System.Collections.Generic.Dictionary<ModelId, AncientStats>();

		private readonly HashSet<ModelId> _discoveredCards = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _discoveredRelics = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _discoveredPotions = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _discoveredEvents = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _discoveredActs = new HashSet<ModelId>();

		private readonly List<SerializableEpoch> _epochs = new List<SerializableEpoch>();

		private readonly System.Collections.Generic.Dictionary<Achievement, long> _unlockedAchievements = new System.Collections.Generic.Dictionary<Achievement, long>();

		private readonly System.Collections.Generic.Dictionary<ModelId, CharacterStats> _unknownCharacterStats = new System.Collections.Generic.Dictionary<ModelId, CharacterStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, CardStats> _unknownCardStats = new System.Collections.Generic.Dictionary<ModelId, CardStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, EncounterStats> _unknownEncounterStats = new System.Collections.Generic.Dictionary<ModelId, EncounterStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, EnemyStats> _unknownEnemyStats = new System.Collections.Generic.Dictionary<ModelId, EnemyStats>();

		private readonly System.Collections.Generic.Dictionary<ModelId, AncientStats> _unknownAncientStats = new System.Collections.Generic.Dictionary<ModelId, AncientStats>();

		private readonly HashSet<ModelId> _unknownDiscoveredCards = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _unknownDiscoveredRelics = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _unknownDiscoveredPotions = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _unknownDiscoveredEvents = new HashSet<ModelId>();

		private readonly HashSet<ModelId> _unknownDiscoveredActs = new HashSet<ModelId>();

		private readonly List<SerializableEpoch> _unknownEpochs = new List<SerializableEpoch>();

		private readonly List<SerializableUnlockedAchievement> _unknownUnlockedAchievements = new List<SerializableUnlockedAchievement>();

		private readonly HashSet<string> _ftueCompleted = new HashSet<string>();

		public IReadOnlyDictionary<ModelId, CharacterStats> CharacterStats => _characterStats;

		public IReadOnlyDictionary<ModelId, CardStats> CardStats => _cardStats;

		public IReadOnlyDictionary<ModelId, EncounterStats> EncounterStats => _encounterStats;

		public IReadOnlyDictionary<ModelId, EnemyStats> EnemyStats => _enemyStats;

		public IReadOnlyDictionary<ModelId, AncientStats> AncientStats => _ancientStats;

		public IReadOnlySet<ModelId> DiscoveredCards => _discoveredCards;

		public IReadOnlySet<ModelId> DiscoveredRelics => _discoveredRelics;

		public IReadOnlySet<ModelId> DiscoveredPotions => _discoveredPotions;

		public IReadOnlySet<ModelId> DiscoveredEvents => _discoveredEvents;

		public IReadOnlySet<ModelId> DiscoveredActs => _discoveredActs;

		public IReadOnlyList<SerializableEpoch> Epochs => _epochs;

		public IReadOnlyDictionary<Achievement, long> UnlockedAchievements => _unlockedAchievements;

		public IReadOnlySet<string> FtueCompleted => _ftueCompleted;

		public string UniqueId { get; init; } = "";

		public bool EnableFtues { get; set; } = true;

		public long TotalPlaytime { get; set; }

		public int CurrentScore { get; set; }

		public long FloorsClimbed { get; set; }

		public long ArchitectDamage { get; set; }

		public int WongoPoints { get; set; }

		public int PreferredMultiplayerAscension { get; set; }

		public int MaxMultiplayerAscension { get; set; }

		public int TestSubjectKills { get; set; }

		public ModelId PendingCharacterUnlock { get; set; } = ModelId.none;

		/// <summary>
		/// How many end-of-run score bar unlocks the player has earned.
		/// </summary>
		/// <remarks>
		/// Counted from the epochs themselves rather than stored, so the count and the grants cannot
		/// disagree. Storing it separately is what caused PRG-7234: the counter advanced, the grant did
		/// not, and because the counter was the only record of how far the player had got, the epoch it
		/// skipped could never be handed out again.
		/// </remarks>
		public int TotalUnlocks => EpochModel.AgnosticUnlockOrder.Count(IsEpochObtained);

		public int Wins => _characterStats.Values.Sum((CharacterStats c) => c.TotalWins);

		public int Losses => _characterStats.Values.Sum((CharacterStats c) => c.TotalLosses);

		public long FastestVictory
		{
			get
			{
				if (_characterStats.Count == 0)
				{
					return 999999999L;
				}
				return _characterStats.Values.Min((CharacterStats c) => (c.FastestWinTime != -1) ? c.FastestWinTime : 999999999);
			}
		}

		public long BestWinStreak
		{
			get
			{
				if (_characterStats.Count == 0)
				{
					return 0L;
				}
				return _characterStats.Values.Max((CharacterStats c) => c.BestWinStreak);
			}
		}

		public int NumberOfRuns => Wins + Losses;

		/// <summary>
		/// Creates an empty ProgressState. Used for new save files and test setup.
		/// </summary>
		public static ProgressState CreateDefault()
		{
			return FromSerializable(new SerializableProgress(), new DeserializationContext());
		}

		public static ProgressState FromSerializable(SerializableProgress save, DeserializationContext ctx)
		{
			ArgumentNullException.ThrowIfNull(save, "save");
			ArgumentNullException.ThrowIfNull(ctx, "ctx");
			ProgressState progressState = new ProgressState
			{
				UniqueId = save.UniqueId,
				EnableFtues = save.EnableFtues,
				TotalPlaytime = ClampNonNegative(save.TotalPlaytime, "TotalPlaytime", ctx),
				CurrentScore = ClampNonNegativeInt(save.CurrentScore, "CurrentScore", ctx),
				FloorsClimbed = ClampNonNegative(save.FloorsClimbed, "FloorsClimbed", ctx),
				ArchitectDamage = ClampNonNegative(save.ArchitectDamage, "ArchitectDamage", ctx),
				WongoPoints = ClampNonNegativeInt(save.WongoPoints, "WongoPoints", ctx),
				PreferredMultiplayerAscension = ClampAscension(save.PreferredMultiplayerAscension, "PreferredMultiplayerAscension", ctx),
				MaxMultiplayerAscension = ClampAscension(save.MaxMultiplayerAscension, "MaxMultiplayerAscension", ctx),
				TestSubjectKills = ClampNonNegativeInt(save.TestSubjectKills, "TestSubjectKills", ctx),
				PendingCharacterUnlock = ValidateModelId<CharacterModel>(save.PendingCharacterUnlock, "PendingCharacterUnlock", ctx)
			};
			ParseCharacterStats(save.CharStats, progressState._characterStats, progressState._unknownCharacterStats, ctx);
			ParseCardStats(save.CardStats, progressState._cardStats, progressState._unknownCardStats, ctx);
			ParseEncounterStats(save.EncounterStats, progressState._encounterStats, progressState._unknownEncounterStats, ctx);
			ParseEnemyStats(save.EnemyStats, progressState._enemyStats, progressState._unknownEnemyStats, ctx);
			ParseAncientStats(save.AncientStats, progressState._ancientStats, progressState._unknownAncientStats, ctx);
			ParseDiscoveredSet<CardModel>(save.DiscoveredCards, progressState._discoveredCards, progressState._unknownDiscoveredCards, "DiscoveredCards", ctx);
			ParseDiscoveredSet<RelicModel>(save.DiscoveredRelics, progressState._discoveredRelics, progressState._unknownDiscoveredRelics, "DiscoveredRelics", ctx);
			ParseDiscoveredSet<PotionModel>(save.DiscoveredPotions, progressState._discoveredPotions, progressState._unknownDiscoveredPotions, "DiscoveredPotions", ctx);
			ParseDiscoveredSet<EventModel>(save.DiscoveredEvents, progressState._discoveredEvents, progressState._unknownDiscoveredEvents, "DiscoveredEvents", ctx);
			ParseDiscoveredSet<ActModel>(save.DiscoveredActs, progressState._discoveredActs, progressState._unknownDiscoveredActs, "DiscoveredActs", ctx);
			ParseEpochs(save.Epochs, progressState._epochs, progressState._unknownEpochs, ctx);
			FixMissingSlots(progressState._epochs, ctx);
			ParseFtues(save.FtueCompleted, progressState._ftueCompleted, ctx);
			ParseAchievements(save.UnlockedAchievements, progressState._unlockedAchievements, progressState._unknownUnlockedAchievements, ctx);
			progressState.FilterAndSortEpochs();
			return progressState;
		}

		public SerializableProgress ToSerializable()
		{
			return new SerializableProgress
			{
				UniqueId = UniqueId,
				SchemaVersion = 0,
				EnableFtues = EnableFtues,
				TotalPlaytime = TotalPlaytime,
				TotalUnlocks = TotalUnlocks,
				CurrentScore = CurrentScore,
				FloorsClimbed = FloorsClimbed,
				ArchitectDamage = ArchitectDamage,
				WongoPoints = WongoPoints,
				PreferredMultiplayerAscension = PreferredMultiplayerAscension,
				MaxMultiplayerAscension = MaxMultiplayerAscension,
				TestSubjectKills = TestSubjectKills,
				PendingCharacterUnlock = PendingCharacterUnlock,
				CharStats = _characterStats.Values.Concat(_unknownCharacterStats.Values).ToList(),
				CardStats = _cardStats.Values.Concat(_unknownCardStats.Values).ToList(),
				EncounterStats = _encounterStats.Values.Concat(_unknownEncounterStats.Values).ToList(),
				EnemyStats = _enemyStats.Values.Concat(_unknownEnemyStats.Values).ToList(),
				AncientStats = _ancientStats.Values.Concat(_unknownAncientStats.Values).ToList(),
				DiscoveredCards = _discoveredCards.Concat(_unknownDiscoveredCards).ToList(),
				DiscoveredRelics = _discoveredRelics.Concat(_unknownDiscoveredRelics).ToList(),
				DiscoveredPotions = _discoveredPotions.Concat(_unknownDiscoveredPotions).ToList(),
				DiscoveredEvents = _discoveredEvents.Concat(_unknownDiscoveredEvents).ToList(),
				DiscoveredActs = _discoveredActs.Concat(_unknownDiscoveredActs).ToList(),
				Epochs = _epochs.Concat(_unknownEpochs).ToList(),
				FtueCompleted = _ftueCompleted.ToList(),
				UnlockedAchievements = _unlockedAchievements.Select((KeyValuePair<Achievement, long> kvp) => new SerializableUnlockedAchievement
				{
					Achievement = JsonNamingPolicy.SnakeCaseLower.ConvertName(kvp.Key.ToString()),
					UnlockTime = kvp.Value
				}).Concat(_unknownUnlockedAchievements).ToList()
			};
		}

