				return value;
			}
			AncientStats ancientStats = new AncientStats
			{
				Id = ancientId
			};
			_ancientStats[ancientId] = ancientStats;
			return ancientStats;
		}

		public AncientStats? GetStatsForAncient(ModelId ancientId)
		{
			_ancientStats.TryGetValue(ancientId, out AncientStats value);
			return value;
		}

		public void ResetFtues()
		{
			EnableFtues = true;
			_ftueCompleted.Clear();
		}

		public bool HasEpoch(string epochId)
		{
			return _epochs.Any((SerializableEpoch e) => e.Id == epochId);
		}

		public bool IsEpochObtained(string epochId)
		{
			SerializableEpoch serializableEpoch = _epochs.FirstOrDefault((SerializableEpoch e) => e.Id == epochId);
			if (serializableEpoch == null)
			{
				return false;
			}
			return serializableEpoch.State >= EpochState.ObtainedNoSlot;
		}

		public bool IsEpochRevealed(string epochId)
		{
			SerializableEpoch serializableEpoch = _epochs.FirstOrDefault((SerializableEpoch e) => e.Id == epochId);
			if (serializableEpoch == null)
			{
				return false;
			}
			return serializableEpoch.State >= EpochState.Revealed;
		}

		private static void ParseCharacterStats(List<CharacterStats> source, System.Collections.Generic.Dictionary<ModelId, CharacterStats> target, System.Collections.Generic.Dictionary<ModelId, CharacterStats> unknown, DeserializationContext ctx)
		{
			ctx.PushPath("CharStats");
			for (int i = 0; i < source.Count; i++)
			{
				CharacterStats characterStats = source[i];
				ctx.PushPath($"[{i}]");
				ModelId id = characterStats.Id;
				if ((object)id == null || id == ModelId.none)
				{
					ctx.Warn("Null or none character ID, skipping");
					ctx.PopPath();
				}
				else if (ModelDb.GetByIdOrNull<CharacterModel>(id) == null)
				{
					ctx.Warn($"Unknown character ID: {id}");
					AddCharacterStats(characterStats, unknown, ctx);
					ctx.PopPath();
				}
				else
				{
					AddCharacterStats(characterStats, target, ctx);
					ClampCharacterStatsFields(characterStats, ctx);
					ctx.PopPath();
				}
			}
			ctx.PopPath();
		}

		private static void AddCharacterStats(CharacterStats entry, System.Collections.Generic.Dictionary<ModelId, CharacterStats> target, DeserializationContext ctx)
		{
			if (!target.TryAdd(entry.Id, entry))
			{
				ctx.Warn($"Duplicate character stats for {entry.Id}, merging");
				MergeCharacterStats(target[entry.Id], entry);
			}
		}

