		/// Obtains a act by ID, or falls back to the deprecated act if it's not found.
		/// This should only be used in save loading where it's okay to fall back to deprecated content.
		/// </summary>
		public static ActModel ActOrDeprecated(ModelId id)
		{
			return ModelDb.GetByIdOrNull<ActModel>(id) ?? ModelDb.Act<DeprecatedAct>();
		}
	}
	/// <summary>
	/// Holds progress data on a per Epoch basis.
	/// If a SerializableEpoch is NOT in the list of epochs in SerializableProgress,
	/// it means the player has not revealed that Epoch's Slot via Timeline Expansion.
	/// </summary>
	public class SerializableEpoch
	{
		[JsonPropertyName("id")]
		public string Id { get; }

		[JsonPropertyName("state")]
		public EpochState State { get; set; }

		[JsonPropertyName("obtain_date")]
		public long ObtainDate { get; set; }

		public SerializableEpoch(string id, EpochState state)
		{
			Id = id;
			State = EpochState.NotObtained;
			if ((uint)(state - 3) <= 2u)
			{
				SetObtained(state);
			}
		}

		public void SetObtained(EpochState state)
		{
			if (State != EpochState.ObtainedNoSlot && State != EpochState.Obtained && State != EpochState.Revealed)
			{
				ObtainDate = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
				State = state;
			}
		}
	}
	public class SerializableExtraPlayerFields : IPacketSerializable
	{
		[JsonPropertyName("card_shop_removals_used")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
		public int CardShopRemovalsUsed { get; set; }

		[JsonPropertyName("wongo_points")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
		public int WongoPoints { get; set; }

		[JsonPropertyName("ccccombo_badge_unlocked")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
		public bool CccomboBadgeUnlocked { get; set; }

		[JsonPropertyName("damage_dealt")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
		public int DamageDealt { get; set; }

		[JsonPropertyName("debuffs_applied")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
		public int DebuffsApplied { get; set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(CardShopRemovalsUsed);
			writer.WriteInt(WongoPoints);
			writer.WriteBool(CccomboBadgeUnlocked);
			writer.WriteInt(DamageDealt);
			writer.WriteInt(DebuffsApplied);
		}

		public void Deserialize(PacketReader reader)
		{
			CardShopRemovalsUsed = reader.ReadInt();
