	public class SerializablePlayerRngSet : IPacketSerializable
	{
		[JsonPropertyName("seed")]
		public ulong Seed { get; set; }

		[JsonPropertyName("rngs")]
		public System.Collections.Generic.Dictionary<PlayerRngType, SerializableRng> Rngs { get; set; } = new System.Collections.Generic.Dictionary<PlayerRngType, SerializableRng>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteULong(Seed);
			writer.WriteInt(Rngs.Count, 8);
			PlayerRngType[] values = Enum.GetValues<PlayerRngType>();
			foreach (PlayerRngType playerRngType in values)
			{
				if (Rngs.TryGetValue(playerRngType, out SerializableRng value))
				{
					writer.WriteEnum(playerRngType);
					writer.Write(value);
				}
			}
		}

		public void Deserialize(PacketReader reader)
		{
			Seed = reader.ReadULong();
			int num = reader.ReadInt(8);
			for (int i = 0; i < num; i++)
			{
				PlayerRngType key = reader.ReadEnum<PlayerRngType>();
				SerializableRng value = reader.Read<SerializableRng>();
				Rngs[key] = value;
			}
		}
	}
	/// <summary>
	/// The player's gameplay progress for Slay the Spire 2.
	/// This would be considered the most important save file and is synced across devices/platforms.
	/// There would be a progress.save in each respective profile's folder and contains data such as:
	/// - Total wins, losses, playtime, and progress per character
	/// - Which cards/relics/potions/etc have been seen or unlocked
	/// - Which enemies/elites/bosses have been encountered and defeated
	/// - Character data
	/// - Timeline and Unlock progress (meta progression)
	/// - Unlocked achievements
	/// - Which FTUEs this player has seen
	/// </summary>
	public class SerializableProgress : ISaveSchema
	{
		/// <summary>
		/// The schema version of this save.
		/// </summary>
		[JsonPropertyName("schema_version")]
		public int SchemaVersion { get; set; }

		[JsonPropertyName("unique_id")]
		public string UniqueId { get; init; }

		[JsonPropertyName("character_stats")]
		public List<CharacterStats> CharStats { get; set; } = new List<CharacterStats>();

		[JsonPropertyName("card_stats")]
		public List<CardStats> CardStats { get; set; } = new List<CardStats>();

		/// <summary>
		/// Tracks how often each character has encountered, won, and lost against each Encounter.
		/// </summary>
		[JsonPropertyName("encounter_stats")]
		public List<EncounterStats> EncounterStats { get; set; } = new List<EncounterStats>();

		/// <summary>
		/// Tracks how often each character has encountered, won, and lost against each Enemy Creature.
		/// </summary>
		[JsonPropertyName("enemy_stats")]
		public List<EnemyStats> EnemyStats { get; set; } = new List<EnemyStats>();

		/// <summary>
		/// Tracks how often each character has encountered, won, and lost after encountering each ancient.
		/// </summary>
		[JsonPropertyName("ancient_stats")]
		public List<AncientStats> AncientStats { get; set; } = new List<AncientStats>();

		[JsonPropertyName("enable_ftues")]
		public bool EnableFtues { get; set; } = true;

		[JsonPropertyName("epochs")]
		public List<SerializableEpoch> Epochs { get; set; } = new List<SerializableEpoch>();

		[JsonPropertyName("ftue_completed")]
		public List<string> FtueCompleted { get; set; } = new List<string>();

		[JsonPropertyName("unlocked_achievements")]
		public List<SerializableUnlockedAchievement> UnlockedAchievements { get; set; } = new List<SerializableUnlockedAchievement>();

		[JsonPropertyName("discovered_cards")]
		public List<ModelId> DiscoveredCards { get; set; } = new List<ModelId>();

		[JsonPropertyName("discovered_relics")]
		public List<ModelId> DiscoveredRelics { get; set; } = new List<ModelId>();

		[JsonPropertyName("discovered_events")]
		public List<ModelId> DiscoveredEvents { get; set; } = new List<ModelId>();

		[JsonPropertyName("discovered_potions")]
		public List<ModelId> DiscoveredPotions { get; set; } = new List<ModelId>();

		[JsonPropertyName("discovered_acts")]
		public List<ModelId> DiscoveredActs { get; set; } = new List<ModelId>();

		[JsonPropertyName("total_playtime")]
		public long TotalPlaytime { get; set; }

		/// <summary>
		/// The amount of agnostic unlocks via score system this player has unlocked.
		/// </summary>
		[JsonPropertyName("total_unlocks")]
		public int TotalUnlocks { get; set; }

		/// <summary>
		/// How much score this player has (is not cumulative).
		/// </summary>
		[JsonPropertyName("current_score")]
		public int CurrentScore { get; set; }

		[JsonPropertyName("floors_climbed")]
		public long FloorsClimbed { get; set; }

		[JsonPropertyName("architect_damage")]
		public long ArchitectDamage { get; set; }

		[JsonPropertyName("wongo_points")]
		public int WongoPoints { get; set; }

		/// <summary> Which multiplayer ascension we had selected the last time we started a multiplayer run. </summary>
		[JsonPropertyName("preferred_multiplayer_ascension")]
		public int PreferredMultiplayerAscension { get; set; }

		/// <summary>
		/// The maximum unlocked ascension in multiplayer.
		/// In singleplayer runs, we use character stats. In multiplayer runs, all characters share an ascension.
		/// </summary>
		[JsonPropertyName("max_multiplayer_ascension")]
		public int MaxMultiplayerAscension { get; set; }

		[JsonPropertyName("test_subject_kills")]
		public int TestSubjectKills { get; set; }

		/// <summary>
		/// Characters that have been unlocked between the last run and the next time the player opens the character
		/// select screen.
		/// Used to show an animation on the character select screen.
		/// </summary>
		[JsonPropertyName("pending_character_unlock")]
		public ModelId PendingCharacterUnlock { get; set; } = ModelId.none;

		[JsonIgnore]
		public int Wins => CharStats.Sum((CharacterStats character) => character.TotalWins);

		[JsonIgnore]
		public int Losses => CharStats.Sum((CharacterStats character) => character.TotalLosses);

		[JsonIgnore]
		public long FastestVictory
		{
			get
			{
				if (CharStats.Count == 0)
				{
					return 999999999L;
				}
				return CharStats.Min((CharacterStats c) => (c.FastestWinTime != -1) ? c.FastestWinTime : 999999999);
			}
		}

		[JsonIgnore]
		public long BestWinStreak
		{
			get
			{
				if (CharStats.Count == 0)
				{
					return 0L;
				}
				return CharStats.Max((CharacterStats c) => c.BestWinStreak);
			}
		}

		[JsonIgnore]
		public int NumberOfRuns => Wins + Losses;

		public SerializableProgress()
		{
			UniqueId = GenerateUniqueId();
			static string GenerateUniqueId(int length = 7)
			{
				return new string((from s in Enumerable.Repeat("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", length)
					select s[Rng.Chaotic.NextInt(s.Length)]).ToArray());
			}
		}

		/// <summary>
		/// Get the stats for the specified character.
		/// </summary>
		public CharacterStats? GetStatsForCharacter(ModelId characterId)
		{
			return CharStats.FirstOrDefault((CharacterStats c) => c.Id == characterId);
		}

		/// <summary>
		/// Get the stats for the specified ancient.
		/// </summary>
		public AncientStats? GetStatsForAncient(ModelId ancientId)
		{
			return AncientStats.FirstOrDefault((AncientStats a) => a.Id == ancientId);
		}
	}
	public record SerializableRng : IPacketSerializable
	{
		[JsonPropertyName("counter")]
		public int counter;

		[JsonPropertyName("s0")]
		public ulong state0;

		[JsonPropertyName("s1")]
		public ulong state1;

		[JsonPropertyName("s2")]
		public ulong state2;

		[JsonPropertyName("s3")]
		public ulong state3;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(counter);
			writer.WriteULong(state0);
			writer.WriteULong(state1);
			writer.WriteULong(state2);
			writer.WriteULong(state3);
		}

		public void Deserialize(PacketReader reader)
		{
			counter = reader.ReadInt();
			state0 = reader.ReadULong();
			state1 = reader.ReadULong();
			state2 = reader.ReadULong();
			state3 = reader.ReadULong();
		}

		public override string ToString()
		{
			return $"Counter: {counter} State: {state0} {state1} {state2} {state3}";
		}
	}
	public class SerializableRun : ISaveSchema, IPacketSerializable
	{
		/// <summary>
		/// The schema version of this save.
		/// </summary>
		[JsonPropertyName("schema_version")]
		public int SchemaVersion { get; set; }

		[JsonPropertyName("acts")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<SerializableActModel> Acts { get; set; } = new List<SerializableActModel>();

		[JsonPropertyName("modifiers")]
		public List<SerializableModifier> Modifiers { get; set; } = new List<SerializableModifier>();

		/// <summary>
		/// This is null if the run is not a daily.
		/// Otherwise, it contains the date from the time server of the daily.
		/// </summary>
		[JsonPropertyName("dailyTime")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotTypeDefault)]
		public DateTimeOffset? DailyTime { get; set; }

		[JsonPropertyName("current_act_index")]
		public int CurrentActIndex { get; set; }

		[JsonPropertyName("events_seen")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<ModelId> EventsSeen { get; set; } = new List<ModelId>();

		[JsonPropertyName("pre_finished_room")]
		public SerializableRoom? PreFinishedRoom { get; set; }

		[JsonPropertyName("odds")]
		public SerializableRunOddsSet SerializableOdds { get; set; }

		[JsonPropertyName("shared_relic_grab_bag")]
		public SerializableRelicGrabBag SerializableSharedRelicGrabBag { get; set; }

		[JsonPropertyName("players")]
		public List<SerializablePlayer> Players { get; set; }

		[JsonPropertyName("rng")]
		public SerializableRunRngSet SerializableRng { get; set; }

		/// <summary>
		/// The map coordinates you've visited in the current Act.
		/// </summary>
		[JsonPropertyName("visited_map_coords")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<MapCoord> VisitedMapCoords { get; set; } = new List<MapCoord>();

		[JsonPropertyName("map_point_history")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<List<MapPointHistoryEntry>> MapPointHistory { get; set; } = new List<List<MapPointHistoryEntry>>();

		/// <summary>
		/// When this save was created or last updated.
		/// </summary>
		[JsonPropertyName("save_time")]
		public long SaveTime { get; set; }

		[JsonPropertyName("start_time")]
		public long StartTime { get; set; }

		/// <summary>
		/// The amount of seconds that has elapsed for this run.
		/// </summary>
		[JsonPropertyName("run_time")]
		public long RunTime { get; set; }

		/// <summary>
		/// The exact moment when a Win was clocked on the RunTime. (Currently when you beat the Act 3 boss)
		/// </summary>
		[JsonPropertyName("win_time")]
		public long WinTime { get; set; }

		[JsonPropertyName("ascension")]
		public int Ascension { get; set; }

		[JsonPropertyName("num_reloads")]
		public int NumReloads { get; set; }

		[JsonPropertyName("platform_type")]
		public PlatformType PlatformType { get; set; }

		[JsonConverter(typeof(SerializableMapDrawingsJsonConverter))]
		[JsonPropertyName("map_drawings")]
		public SerializableMapDrawings? MapDrawings { get; set; }

		[JsonPropertyName("extra_fields")]
		public SerializableExtraRunFields ExtraFields { get; set; } = new SerializableExtraRunFields();

		[JsonPropertyName("game_mode")]
		public GameMode GameMode { get; set; }

		/// <summary>
		/// The furthest floor count reached during this run.
		/// Used when uploading the "floor" value when uploading to the daily leaderboards.
		/// </summary>
		[JsonIgnore]
		public int FloorReached => MapPointHistory.Sum((List<MapPointHistoryEntry> c) => c.Count);

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(SchemaVersion);
			writer.WriteList(Acts);
			writer.WriteList(Modifiers);
			writer.WriteBool(DailyTime.HasValue);
			if (DailyTime.HasValue)
			{
				writer.WriteLong(DailyTime.Value.ToUnixTimeSeconds());
			}
			writer.WriteEnum(GameMode);
			writer.WriteInt(CurrentActIndex, 4);
			writer.WriteModelEntriesInList(EventsSeen);
			writer.WriteBool(PreFinishedRoom != null);
			if (PreFinishedRoom != null)
			{
				writer.Write(PreFinishedRoom);
			}
			writer.Write(SerializableOdds);
			writer.WriteList(Players);
			writer.Write(SerializableRng);
			writer.Write(SerializableSharedRelicGrabBag);
			writer.WriteList(VisitedMapCoords);
			writer.WriteInt(MapPointHistory.Count);
			foreach (List<MapPointHistoryEntry> item in MapPointHistory)
			{
				writer.WriteList(item);
			}
			writer.WriteLong(SaveTime);
			writer.WriteLong(StartTime);
			writer.WriteLong(RunTime);
			writer.WriteLong(WinTime);
			writer.WriteInt(Ascension, 8);
			writer.WriteBool(MapDrawings != null);
			if (MapDrawings != null)
			{
				writer.Write(MapDrawings);
			}
			writer.Write(ExtraFields);
			writer.WriteInt(NumReloads);
		}

		public void Deserialize(PacketReader reader)
		{
			SchemaVersion = reader.ReadInt();
			Acts = reader.ReadList<SerializableActModel>();
			Modifiers = reader.ReadList<SerializableModifier>();
			if (reader.ReadBool())
			{
				DailyTime = DateTimeOffset.FromUnixTimeSeconds(reader.ReadLong());
			}
			GameMode = reader.ReadEnum<GameMode>();
			CurrentActIndex = reader.ReadInt(4);
			EventsSeen = reader.ReadModelIdListAssumingType<EventModel>();
			if (reader.ReadBool())
			{
				PreFinishedRoom = reader.Read<SerializableRoom>();
			}
			SerializableOdds = reader.Read<SerializableRunOddsSet>();
			Players = reader.ReadList<SerializablePlayer>();
			SerializableRng = reader.Read<SerializableRunRngSet>();
			SerializableSharedRelicGrabBag = reader.Read<SerializableRelicGrabBag>();
			VisitedMapCoords = reader.ReadList<MapCoord>();
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				List<MapPointHistoryEntry> item = reader.ReadList<MapPointHistoryEntry>();
				MapPointHistory.Add(item);
			}
			SaveTime = reader.ReadLong();
			StartTime = reader.ReadLong();
			RunTime = reader.ReadLong();
			WinTime = reader.ReadLong();
			Ascension = reader.ReadInt(8);
			if (reader.ReadBool())
			{
				MapDrawings = reader.Read<SerializableMapDrawings>();
			}
			ExtraFields = reader.Read<SerializableExtraRunFields>();
			NumReloads = reader.ReadInt();
		}

		public SerializableRun Anonymized()
		{
			return new SerializableRun
			{
				SchemaVersion = SchemaVersion,
				Acts = Acts,
				Modifiers = Modifiers,
				DailyTime = DailyTime,
				CurrentActIndex = CurrentActIndex,
				EventsSeen = EventsSeen,
				GameMode = GameMode,
				PreFinishedRoom = PreFinishedRoom,
				SerializableOdds = SerializableOdds,
				SerializableSharedRelicGrabBag = SerializableSharedRelicGrabBag,
				Players = Players.Select((SerializablePlayer p) => p.Anonymized()).ToList(),
				SerializableRng = SerializableRng,
				VisitedMapCoords = VisitedMapCoords,
				MapPointHistory = MapPointHistory.Select((List<MapPointHistoryEntry> l) => l.Select((MapPointHistoryEntry h) => h.Anonymized()).ToList()).ToList(),
				SaveTime = SaveTime,
				StartTime = StartTime,
				RunTime = RunTime,
				WinTime = WinTime,
				Ascension = Ascension,
				PlatformType = PlatformType,
				MapDrawings = MapDrawings?.Anonymized(),
				ExtraFields = ExtraFields
			};
		}
	}
	/// <summary>
