	public static class UserDataPathProvider
	{
		public static string SavesDir => "saves";

		public static bool IsRunningModded { get; set; }

		public static string GetProfileScopedPath(int profileId, string dataType, PlatformType? platformOverride = null, ulong? userIdOverride = null)
		{
			PlatformType platformType = platformOverride ?? PlatformUtil.PrimaryPlatform;
			ulong value = userIdOverride ?? PlatformUtil.GetLocalPlayerId(platformType);
			string platformDirectoryName = GetPlatformDirectoryName(platformType);
			return $"user://{platformDirectoryName}/{value}/{GetProfileDir(profileId)}/{dataType}";
		}

		public static string GetProfileScopedBasePath(int profileId, PlatformType? platformOverride = null, ulong? userIdOverride = null)
		{
			PlatformType platformType = platformOverride ?? PlatformUtil.PrimaryPlatform;
			ulong value = userIdOverride ?? PlatformUtil.GetLocalPlayerId(platformType);
			string platformDirectoryName = GetPlatformDirectoryName(platformType);
			return $"user://{platformDirectoryName}/{value}/{GetProfileDir(profileId)}";
		}

		public static string GetAccountScopedBasePath(string? dataType, PlatformType? platformOverride = null, ulong? userIdOverride = null)
		{
			PlatformType platformType = platformOverride ?? PlatformUtil.PrimaryPlatform;
			ulong value = userIdOverride ?? PlatformUtil.GetLocalPlayerId(platformType);
			string platformDirectoryName = GetPlatformDirectoryName(platformType);
			string text = $"user://{platformDirectoryName}/{value}";
			if (dataType != null)
			{
				text = text.PathJoin(dataType);
			}
			return text;
		}

		public static string GetAccountDir(bool? forceModState = null)
		{
			if (!(forceModState ?? IsRunningModded))
			{
				return "";
			}
			return "modded";
		}

		public static string GetProfileDir(int profileId)
		{
			return GetProfileDir(profileId, null);
		}

		public static string GetProfileDir(int profileId, bool? forceModState)
		{
			return GetAccountDir(forceModState).PathJoin($"profile{profileId}");
		}

		public static string GetLegacyPreAccountPath(string dataType)
		{
			return "user://" + dataType;
		}

		public static string GetPlatformDirectoryName(PlatformType platform)
		{
			if (platform == PlatformType.Steam)
			{
				return "steam";
			}
			return OS.HasFeature("editor") ? "editor" : "default";
		}

		public static bool IsLegacyPath(string path)
		{
			if (!path.Contains("/steam/") && !path.Contains("/default/"))
			{
				return !path.Contains("/editor/");
			}
			return false;
		}
	}
}
namespace MegaCrit.Sts2.Core.Saves.Validation
{
	/// <summary>
	/// Collects validation errors during save deserialization.
	/// Threaded through FromSerializable methods to accumulate structured errors with path tracking.
	/// </summary>
	public sealed class DeserializationContext
	{
		private readonly List<ValidationError> _errors = new List<ValidationError>();

		private readonly Stack<string> _pathSegments = new Stack<string>();

		private string CurrentPath => string.Join(".", _pathSegments.Reverse());

		/// <summary>
		/// All validation errors collected so far, in insertion order.
		/// </summary>
		public IReadOnlyList<ValidationError> Errors => _errors;

		/// <summary>
		/// Whether any fatal errors have been recorded.
		/// </summary>
		public bool HasFatal => _errors.Any((ValidationError e) => e.IsFatal);

		/// <summary>
		/// Number of warning-severity errors.
		/// </summary>
		public int WarningCount => _errors.Count((ValidationError e) => !e.IsFatal);

		/// <summary>
		/// Number of fatal-severity errors.
		/// </summary>
		public int FatalCount => _errors.Count((ValidationError e) => e.IsFatal);

		/// <summary>
		/// Pushes a path segment onto the stack (e.g. "Players[0]", "Deck[3]", "Id").
		/// </summary>
		public void PushPath(string segment)
		{
			_pathSegments.Push(segment);
		}

		/// <summary>
		/// Pops the most recent path segment from the stack.
		/// </summary>
		public void PopPath()
		{
			_pathSegments.Pop();
		}

		/// <summary>
		/// Records a warning at the current path. Warnings indicate degraded data but the save is still loadable.
		/// </summary>
		public void Warn(string message)
		{
			_errors.Add(new ValidationError(ValidationSeverity.Warning, CurrentPath, message));
		}

		/// <summary>
		/// Records a fatal error at the current path. Fatal errors mean the save cannot be loaded.
		/// </summary>
		public void Fatal(string message)
		{
			_errors.Add(new ValidationError(ValidationSeverity.Fatal, CurrentPath, message));
		}
	}
	/// <summary>
	/// Severity levels for save validation errors.
	/// </summary>
	public enum ValidationSeverity
	{
		/// <summary>
		/// The save loaded but data was degraded (e.g. deprecated content replaced with fallback).
		/// </summary>
		Warning,
		/// <summary>
		/// The save cannot be loaded due to invalid or missing data.
		/// </summary>
		Fatal
	}
	/// <summary>
	/// A single validation error found during save deserialization.
	/// </summary>
	/// <param name="Severity">Whether this error is fatal or a warning</param>
	/// <param name="Path">Dot-separated field path where the error occurred (e.g. "Players[0].Deck[3].Id")</param>
	/// <param name="Message">Human-readable description of the error</param>
	public sealed record ValidationError(ValidationSeverity Severity, string Path, string Message)
	{
		/// <summary>
		/// Whether this error is fatal (the save cannot be loaded).
		/// </summary>
		public bool IsFatal => Severity == ValidationSeverity.Fatal;
	}
}
