	public class SerializableRelicGrabBag : IPacketSerializable
	{
		[JsonPropertyName("relic_id_lists")]
		public System.Collections.Generic.Dictionary<RelicRarity, List<ModelId>> RelicIdLists { get; set; } = new System.Collections.Generic.Dictionary<RelicRarity, List<ModelId>>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(RelicIdLists.Count);
			RelicRarity[] values = Enum.GetValues<RelicRarity>();
			foreach (RelicRarity relicRarity in values)
			{
				if (RelicIdLists.TryGetValue(relicRarity, out List<ModelId> value))
				{
					writer.WriteEnum(relicRarity);
					writer.WriteModelEntriesInList(value);
				}
			}
		}

		public void Deserialize(PacketReader reader)
		{
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				RelicRarity key = reader.ReadEnum<RelicRarity>();
				List<ModelId> value = reader.ReadModelIdListAssumingType<RelicModel>();
				RelicIdLists[key] = value;
			}
		}
	}
	public class SerializableReward : IPacketSerializable
	{
		[JsonPropertyName("reward_type")]
		public RewardType RewardType { get; set; }

		/// <summary>
		/// The model ID that this reward is predetermined to be.
		/// This is used for rewards that are predetermined to be a specific model, such as
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Encounters.FakeMerchantEventEncounter" /> granting the specific relics that were originally being sold by
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Events.FakeMerchant" />.
		///
		/// Note: If you want to set a pre-determined CardModel reward, you should probably use
		/// <see cref="T:MegaCrit.Sts2.Core.Rewards.SpecialCardReward" /> and the <see cref="P:MegaCrit.Sts2.Core.Saves.Runs.SerializableReward.SpecialCard" /> property instead.
		///
		/// TODO: This only supports RelicModel right now. Add support for PotionModel later if necessary.
		/// </summary>
		[JsonPropertyName("predetermined_model_id")]
		public ModelId PredeterminedModelId { get; set; } = ModelId.none;

		/// <summary>
		/// The card for a <see cref="T:MegaCrit.Sts2.Core.Rewards.SpecialCardReward" />.
		/// This has to be a full serialized card instead of just an ID, because <see cref="T:MegaCrit.Sts2.Core.Models.Monsters.ThievingHopper" /> steals a card
		/// from you and then returns it via this reward. This card may have modifications (upgrade, enchantment, etc.), so
		/// we need to be able to fully reconstruct it.
		/// Only non-null when RewardType is SpecialCard.
		/// </summary>
		[JsonPropertyName("special_card")]
		public SerializableCard? SpecialCard { get; set; }

		/// <summary>
		/// These properties are only used for gold rewards.
		/// </summary>
		[JsonPropertyName("gold_amount")]
		public int GoldAmount { get; set; }

		/// <summary>
		/// Whether or not the gold was "stolen back".
		/// Usually false, but true in situations where an enemy/event "stole" some of your gold (such as
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Encounters.GremlinMercNormal" />), and this reward represents you taking it back.
		/// </summary>
		[JsonPropertyName("was_gold_stolen_back")]
		public bool WasGoldStolenBack { get; set; }

		/// <summary>
		/// These properties are only used for randomized card rewards.
		/// </summary>
		[JsonPropertyName("source")]
		public CardCreationSource Source { get; set; }

		[JsonPropertyName("rarity_odds")]
		public CardRarityOddsType RarityOdds { get; set; }

		/// <summary>
		/// The IDs of the card pools that this card reward can be rolled from.
		/// </summary>
		[JsonPropertyName("card_pools")]
		public List<ModelId> CardPoolIds { get; set; } = new List<ModelId>();

		/// <summary>
		/// The number of cards that should be available to choose from in this card reward.
		/// </summary>
		[JsonPropertyName("option_count")]
		public int OptionCount { get; set; }

		/// <summary>
		/// See <see cref="P:MegaCrit.Sts2.Core.Models.EncounterModel.CustomRewardDescription" /> for details.
		/// </summary>
		[JsonPropertyName("custom_description_encounter_source_id")]
		public ModelId CustomDescriptionEncounterSourceId { get; set; } = ModelId.none;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt((int)RewardType);
			writer.WriteFullModelId(PredeterminedModelId);
			if (RewardType == RewardType.SpecialCard)
			{
				writer.Write(SpecialCard);
			}
			writer.WriteInt(GoldAmount);
			writer.WriteBool(WasGoldStolenBack);
			writer.WriteEnum(Source);
			writer.WriteEnum(RarityOdds);
			writer.WriteModelEntriesInList(CardPoolIds);
			writer.WriteInt(OptionCount);
			writer.WriteModelEntry(CustomDescriptionEncounterSourceId);
		}

		public void Deserialize(PacketReader reader)
		{
			RewardType = (RewardType)reader.ReadInt();
			PredeterminedModelId = reader.ReadFullModelId();
			if (RewardType == RewardType.SpecialCard)
			{
				SpecialCard = reader.Read<SerializableCard>();
			}
			GoldAmount = reader.ReadInt();
			WasGoldStolenBack = reader.ReadBool();
			Source = reader.ReadEnum<CardCreationSource>();
			RarityOdds = reader.ReadEnum<CardRarityOddsType>();
			CardPoolIds = reader.ReadModelIdListAssumingType<CardPoolModel>();
			OptionCount = reader.ReadInt();
			CustomDescriptionEncounterSourceId = reader.ReadModelIdAssumingType<EncounterModel>();
		}
	}
	public class SerializableRoom : IPacketSerializable
	{
		[JsonPropertyName("room_type")]
		public RoomType RoomType { get; set; }

		[JsonPropertyName("encounter_id")]
		public ModelId? EncounterId { get; set; }

		[JsonPropertyName("event_id")]
		public ModelId? EventId { get; set; }

		[JsonPropertyName("is_pre_finished")]
		public bool IsPreFinished { get; set; }

		[JsonPropertyName("reward_proportion")]
		public float GoldProportion { get; set; }

		[JsonPropertyName("extra_rewards")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public System.Collections.Generic.Dictionary<ulong, List<SerializableReward>> ExtraRewards { get; set; } = new System.Collections.Generic.Dictionary<ulong, List<SerializableReward>>();

		[JsonPropertyName("parent_event_id")]
		public ModelId? ParentEventId { get; set; }

		[JsonPropertyName("should_resume_parent_event")]
		public bool ShouldResumeParentEvent { get; set; } = true;

		[JsonPropertyName("encounter_state")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public System.Collections.Generic.Dictionary<string, string> EncounterState { get; set; } = new System.Collections.Generic.Dictionary<string, string>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt((int)RoomType);
			writer.WriteBool(EncounterId != null);
			if (EncounterId != null)
			{
				writer.WriteModelEntry(EncounterId);
			}
			writer.WriteBool(EventId != null);
			if (EventId != null)
			{
				writer.WriteModelEntry(EventId);
			}
			writer.WriteFloat(GoldProportion);
			writer.WriteBool(IsPreFinished);
			writer.WriteInt(ExtraRewards.Count);
			foreach (var (val, list2) in ExtraRewards)
			{
				writer.WriteULong(val);
				writer.WriteList(list2);
			}
			writer.WriteBool(ParentEventId != null);
			if (ParentEventId != null)
			{
				writer.WriteModelEntry(ParentEventId);
			}
			writer.WriteBool(ShouldResumeParentEvent);
			writer.WriteInt(EncounterState.Count);
			foreach (var (str, str2) in EncounterState)
			{
				writer.WriteString(str);
				writer.WriteString(str2);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			RoomType = (RoomType)reader.ReadInt();
			if (reader.ReadBool())
			{
				EncounterId = reader.ReadModelIdAssumingType<EncounterModel>();
			}
			if (reader.ReadBool())
			{
				EventId = reader.ReadModelIdAssumingType<EventModel>();
			}
			GoldProportion = reader.ReadFloat();
			IsPreFinished = reader.ReadBool();
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				ulong key = reader.ReadULong();
				ExtraRewards[key] = reader.ReadList<SerializableReward>();
			}
			if (reader.ReadBool())
			{
				ParentEventId = reader.ReadModelIdAssumingType<EventModel>();
			}
			ShouldResumeParentEvent = reader.ReadBool();
			int num2 = reader.ReadInt();
			EncounterState = new System.Collections.Generic.Dictionary<string, string>(num2);
			for (int j = 0; j < num2; j++)
			{
				string key2 = reader.ReadString();
				string value = reader.ReadString();
				EncounterState[key2] = value;
			}
		}
	}
	public class SerializableRoomSet : IPacketSerializable
	{
		[JsonPropertyName("event_ids")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<ModelId> EventIds { get; set; }

		[JsonPropertyName("events_visited")]
		public int EventsVisited { get; set; }

		[JsonPropertyName("normal_encounter_ids")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<ModelId> NormalEncounterIds { get; set; }

		[JsonPropertyName("normal_encounters_visited")]
		public int NormalEncountersVisited { get; set; }

		[JsonPropertyName("elite_encounter_ids")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<ModelId> EliteEncounterIds { get; set; }

		[JsonPropertyName("elite_encounters_visited")]
		public int EliteEncountersVisited { get; set; }

		[JsonPropertyName("boss_encounters_visited")]
		public int BossEncountersVisited { get; set; }

		[JsonPropertyName("boss_id")]
		public ModelId? BossId { get; set; }

		[JsonPropertyName("second_boss_id")]
		public ModelId? SecondBossId { get; set; }

		[JsonPropertyName("ancient_id")]
		public ModelId? AncientId { get; set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteModelEntriesInList(EventIds);
			writer.WriteInt(EventsVisited);
			writer.WriteModelEntriesInList(NormalEncounterIds);
			writer.WriteInt(NormalEncountersVisited);
			writer.WriteModelEntriesInList(EliteEncounterIds);
			writer.WriteInt(EliteEncountersVisited);
			writer.WriteInt(BossEncountersVisited);
			writer.WriteBool(BossId != null);
			if (BossId != null)
			{
				writer.WriteModelEntry(BossId);
			}
			writer.WriteBool(SecondBossId != null);
			if (SecondBossId != null)
			{
				writer.WriteModelEntry(SecondBossId);
			}
			writer.WriteBool(AncientId != null);
			if (AncientId != null)
			{
				writer.WriteModelEntry(AncientId);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			EventIds = reader.ReadModelIdListAssumingType<EventModel>();
			EventsVisited = reader.ReadInt();
			NormalEncounterIds = reader.ReadModelIdListAssumingType<EncounterModel>();
			NormalEncountersVisited = reader.ReadInt();
			EliteEncounterIds = reader.ReadModelIdListAssumingType<EncounterModel>();
			EliteEncountersVisited = reader.ReadInt();
			BossEncountersVisited = reader.ReadInt();
			if (reader.ReadBool())
			{
				BossId = reader.ReadModelIdAssumingType<EncounterModel>();
			}
			if (reader.ReadBool())
			{
				SecondBossId = reader.ReadModelIdAssumingType<EncounterModel>();
			}
			if (reader.ReadBool())
			{
				AncientId = reader.ReadModelIdAssumingType<AncientEventModel>();
			}
		}
	}
