	public class SerializableRunRngSet : IPacketSerializable
	{
		[JsonPropertyName("seed")]
		public string? Seed { get; set; }

		[JsonPropertyName("rngs")]
		public System.Collections.Generic.Dictionary<RunRngType, SerializableRng> Rngs { get; set; } = new System.Collections.Generic.Dictionary<RunRngType, SerializableRng>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(Seed);
			writer.WriteInt(Rngs.Count, 8);
			RunRngType[] values = Enum.GetValues<RunRngType>();
			foreach (RunRngType runRngType in values)
			{
				if (Rngs.TryGetValue(runRngType, out SerializableRng value))
				{
					writer.WriteEnum(runRngType);
					writer.Write(value);
				}
			}
		}

		public void Deserialize(PacketReader reader)
		{
			Seed = reader.ReadString();
			int num = reader.ReadInt(8);
			for (int i = 0; i < num; i++)
			{
				RunRngType key = reader.ReadEnum<RunRngType>();
				SerializableRng value = reader.Read<SerializableRng>();
				Rngs[key] = value;
			}
		}
	}
	public enum SerializationCondition
	{
		/// <summary>
		/// Property is always serialized and deserialized no matter what.
		/// </summary>
		AlwaysSave,
		/// <summary>
		/// Property is only serialized and deserialized if Object.Equals returns false when comparing the current value of
		/// the property and the default value of the property when the declaring type's default constructor is called.
		/// </summary>
		SaveIfNotPropertyDefault,
		/// <summary>
		/// Property is only serialized and deserialized if Object.Equals returns false when comparing the current value of
		/// the property and default(T), where T is the property of the type.
		/// </summary>
		SaveIfNotTypeDefault,
		/// <summary>
		/// Property is only serialized and deserialized if it is a collection that is not empty, or if it is not null.
		/// </summary>
		SaveIfNotCollectionEmptyOrNull
	}
	public static class SerializationConditionExtensions
	{
		private static readonly System.Collections.Generic.Dictionary<Type, object?> _defaultTypeCache = new System.Collections.Generic.Dictionary<Type, object>();

		private static object? GetTypeDefaultValue([DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicParameterlessConstructor)] Type t)
		{
			if (t.IsValueType)
			{
				return Activator.CreateInstance(t);
			}
			return null;
		}

		private static object? GetMemberDefaultValue(MemberInfo info)
		{
			if (!_defaultTypeCache.TryGetValue(info.DeclaringType, out object value))
			{
				value = Activator.CreateInstance(info.DeclaringType);
				_defaultTypeCache[info.DeclaringType] = value;
			}
			return info.MemberType switch
			{
				MemberTypes.Field => ((FieldInfo)info).GetValue(value), 
				MemberTypes.Property => ((System.Reflection.PropertyInfo)info).GetValue(value), 
				_ => throw new ArgumentException($"Input MemberInfo must be of type FieldInfo or PropertyInfo. It was {info.MemberType} ({info.GetType()})"), 
			};
		}

		[return: DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicParameterlessConstructor)]
		private static Type GetUnderlyingType(this MemberInfo member)
		{
			return member.MemberType switch
			{
				MemberTypes.Field => ((FieldInfo)member).FieldType, 
				MemberTypes.Property => ((System.Reflection.PropertyInfo)member).PropertyType, 
				_ => throw new ArgumentException($"Input MemberInfo must be of type FieldInfo or PropertyInfo. It was {member.MemberType} ({member.GetType()})"), 
			};
		}

		public static bool ShouldSerialize(this SerializationCondition condition, object? candidate, MemberInfo memberInfo)
		{
			switch (condition)
			{
			case SerializationCondition.AlwaysSave:
				return true;
			case SerializationCondition.SaveIfNotPropertyDefault:
				return !object.Equals(candidate, GetMemberDefaultValue(memberInfo));
			case SerializationCondition.SaveIfNotTypeDefault:
				return !object.Equals(candidate, GetTypeDefaultValue(memberInfo.GetUnderlyingType()));
			case SerializationCondition.SaveIfNotCollectionEmptyOrNull:
				if (!(candidate is ICollection collection))
				{
					return false;
				}
				if (collection.Count == 0)
				{
					return false;
				}
				return true;
			default:
				throw new InvalidEnumArgumentException("Invalid condition passed!");
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Saves.Migrations
{
	/// <summary>
	/// Base interface for all migrations.
	/// </summary>
	[GenerateSubtypes(DynamicallyAccessedMemberTypes = DynamicallyAccessedMemberTypes.PublicParameterlessConstructor)]
	public interface IMigration
	{
		/// <summary>
		/// The version to migrate from.
		/// </summary>
		int FromVersion { get; }

		/// <summary>
		/// The version to migrate to.
		/// </summary>
		int ToVersion { get; }

		/// <summary>
		/// The type of save that this migration operates on.
		/// </summary>
		Type SaveType { get; }

		/// <summary>
		/// Migrates the JsonObject from the old version to the new version.
		/// </summary>
		/// <param name="saveData">The JsonObject to migrate</param>
		/// <returns>The migrated JsonObject</returns>
		MigratingData Migrate(MigratingData saveData);
	}
	/// <summary>
	/// Strongly typed interface for migrations that operate on a specific save type.
	/// </summary>
	/// <typeparam name="T">The save type to migrate</typeparam>
	public interface IMigration<T> : IMigration where T : ISaveSchema
	{
	}
	/// <summary>
	/// A mutable JSON representation of the data being migrated. It serves as a loosely typed mutable blob we can
	/// deserialize into and modify with our migration classes until finally parsing into the latest structured save schema.
	/// This implementation uses System.Text.Json's JsonNode instead of a custom implementation.
	/// </summary>
	public class MigratingData
	{
		private readonly JsonObject _data;

		/// <summary>
		/// Gets a property in the JSON object.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The property value</returns>
		public object? this[string key]
		{
			get
			{
				if (!_data.TryGetPropertyValue(key, out JsonNode jsonNode))
				{
					return null;
				}
				return ConvertJsonNodeToObject(jsonNode);
			}
		}

		/// <summary>
		/// Creates a JSON object from a JsonDocument.
		/// </summary>
		/// <param name="document">The JsonDocument to convert</param>
		public MigratingData(JsonDocument document)
		{
			_data = document.Deserialize(JsonSerializationUtility.GetTypeInfo<JsonObject>());
		}

		/// <summary>
		/// Creates a JSON object from a JSON string.
		/// </summary>
		/// <param name="json">The JSON string</param>
		public MigratingData(string json)
		{
			_data = (JsonObject)JsonNode.Parse(json);
		}

		/// <summary>
		/// Creates a JSON object from a JsonObject.
		/// </summary>
		/// <param name="jsonObject">The JsonObject</param>
		public MigratingData(JsonObject jsonObject)
		{
			_data = jsonObject;
		}

		/// <summary>
		/// Parses this JsonObject to a strongly typed object.
		/// </summary>
		/// <typeparam name="T">The type to convert to</typeparam>
		/// <returns>An instance of the specified type</returns>
		public T ToObject<T>() where T : new()
		{
			string json = _data.ToJsonString();
			T val = JsonSerializer.Deserialize(json, JsonSerializationUtility.GetTypeInfo<T>());
			if (val == null)
			{
				return new T();
			}
			return val;
		}

		/// <summary>
		/// Removes a property from the JSON object.
		/// </summary>
		/// <param name="key">The property name to remove</param>
		public void Remove(string key)
		{
			if (_data.ContainsKey(key))
			{
				_data.Remove(key);
			}
		}

		/// <summary>
		/// Renames a property in the JSON object.
		/// </summary>
		/// <param name="oldKey">The current property name</param>
		/// <param name="newKey">The new property name</param>
		public void Rename(string oldKey, string newKey)
		{
			if (_data.TryGetPropertyValue(oldKey, out JsonNode jsonNode))
			{
				_data[newKey] = jsonNode?.DeepClone();
				_data.Remove(oldKey);
				return;
			}
			throw new MigrationException("Cannot rename a key that doesn't exist. Key=" + oldKey);
		}

		/// <summary>
		/// Checks if the JSON object has a property.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>True if the property exists</returns>
		public bool Has(string key)
		{
			return _data.ContainsKey(key);
		}

		/// <summary>
		/// Helper method to convert JsonNode to .NET objects
		/// </summary>
		private static object? ConvertJsonNodeToObject(JsonNode? node)
		{
			if (node != null)
			{
				if (!(node is JsonObject))
				{
					if (!(node is JsonArray))
					{
						if (node is JsonValue jsonValue)
						{
							JsonValue jsonValue2 = jsonValue;
							if (jsonValue2.TryGetValue<string>(out string value))
							{
								return value;
							}
							JsonValue jsonValue3 = jsonValue;
							if (jsonValue3.TryGetValue<int>(out var value2))
							{
								return value2;
							}
							JsonValue jsonValue4 = jsonValue;
							if (jsonValue4.TryGetValue<long>(out var value3))
							{
								return value3;
							}
							JsonValue jsonValue5 = jsonValue;
							if (jsonValue5.TryGetValue<float>(out var value4))
							{
								return value4;
							}
							JsonValue jsonValue6 = jsonValue;
							if (jsonValue6.TryGetValue<double>(out var value5))
							{
								return value5;
							}
							JsonValue jsonValue7 = jsonValue;
							if (jsonValue7.TryGetValue<bool>(out var value6))
							{
								return value6;
							}
							JsonValue jsonValue8 = jsonValue;
							return jsonValue8.ToString();
						}
						return null;
					}
					return node.Deserialize(JsonSerializationUtility.GetTypeInfo<List<JsonNode>>());
				}
				return node.Deserialize(JsonSerializationUtility.GetTypeInfo<System.Collections.Generic.Dictionary<string, object>>());
			}
			return null;
		}

		public T? GetAsOrNull<T>(string key) where T : struct
		{
			if (!Has(key))
			{
				return null;
			}
			return GetAs<T>(key);
		}

		/// <summary>
		/// Gets a property as a specific type.
		/// </summary>
		/// <typeparam name="T">The type to convert to</typeparam>
		/// <param name="key">The property name</param>
		/// <returns>The property value as the specified type</returns>
		public T GetAs<T>(string key)
		{
			if (!_data.TryGetPropertyValue(key, out JsonNode jsonNode) || jsonNode == null)
			{
				throw new MigrationException("Cannot get value of key=" + key);
			}
			try
			{
				Type typeFromHandle = typeof(T);
				if (typeFromHandle == typeof(MigratingData) && jsonNode is JsonObject jsonObject)
				{
					return (T)(object)new MigratingData(jsonObject);
				}
				if (typeFromHandle == typeof(List<MigratingData>) && jsonNode is JsonArray jsonArray)
				{
					List<MigratingData> list = new List<MigratingData>();
					foreach (JsonNode item in jsonArray)
					{
						if (item is JsonObject jsonObject2)
						{
							list.Add(new MigratingData(jsonObject2));
							continue;
						}
						throw new MigrationException($"Cannot convert array item to MigratingData: {item}");
					}
					return (T)(object)list;
				}
				if (typeFromHandle == typeof(ModelId))
				{
					string value = jsonNode.GetValue<string>();
					if (string.IsNullOrEmpty(value))
					{
						return (T)(object)ModelId.none;
					}
					return (T)(object)ModelId.Deserialize(value);
				}
				if (typeFromHandle == typeof(string))
				{
					return (T)(object)jsonNode.GetValue<string>();
				}
				if (typeFromHandle == typeof(int))
				{
					return (T)(object)jsonNode.GetValue<int>();
				}
				if (typeFromHandle == typeof(long))
				{
					return (T)(object)jsonNode.GetValue<long>();
				}
				if (typeFromHandle == typeof(double))
				{
					return (T)(object)jsonNode.GetValue<double>();
				}
				if (typeFromHandle == typeof(float))
				{
					return (T)(object)jsonNode.GetValue<float>();
				}
				if (typeFromHandle == typeof(bool))
				{
					return (T)(object)jsonNode.GetValue<bool>();
				}
				if (typeFromHandle == typeof(DateTime))
				{
					return (T)(object)jsonNode.GetValue<DateTime>();
				}
				T val = jsonNode.Deserialize(JsonSerializationUtility.GetTypeInfo<T>());
				if (val == null)
				{
					throw new MigrationException("Unable to convert " + key + " to " + typeof(T).Name);
				}
				return val;
			}
			catch (Exception ex) when (!(ex is MigrationException))
			{
				throw new MigrationException($"Cannot convert value of key={key} to {typeof(T)}: {ex.Message}");
			}
		}

		/// <summary>
		/// Gets a string value from the JSON object.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The string value</returns>
		public string GetString(string key)
		{
			return GetAs<string>(key);
		}

		/// <summary>
		/// Gets a boolean value from the JSON object.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The boolean value</returns>
		public bool GetBool(string key)
		{
			return GetAs<bool>(key);
		}

		/// <summary>
		/// Gets an integer value from the JSON object.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The integer value</returns>
		public int GetInt(string key)
		{
			return GetAs<int>(key);
		}

		/// <summary>
		/// Gets a nested JSON object from the JSON object.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The nested JSON object</returns>
		public MigratingData GetObject(string key)
		{
			return GetAs<MigratingData>(key);
		}

		/// <summary>
		/// Sets a value in the JSON object.
		/// </summary>
		/// <param name="key">The key to set.</param>
		/// <param name="value">The value to set.</param>
		public void Set<T>(string key, T value)
		{
			if (value is List<MigratingData> items)
			{
				SetList(key, items);
			}
			if (value is MigratingData)
			{
				throw new NotImplementedException();
			}
			_data[key] = ((value != null) ? JsonValue.Create(value, JsonSerializationUtility.GetTypeInfo<T>()) : null);
		}

		/// <summary>
		/// Sets a nested object property in the JSON object.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <param name="value">The MigratingData object to set</param>
		public void SetObject(string key, MigratingData value)
		{
			_data[key] = value._data.DeepClone();
		}

		/// <summary>
		/// Gets a list of objects from the JSON array.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The list of objects</returns>
		public List<MigratingData> GetList(string key)
		{
			return GetAs<List<MigratingData>>(key);
		}

		/// <summary>
		/// Gets the raw JsonNode for a property, useful for direct manipulation in migrations.
		/// </summary>
		/// <param name="key">The property name</param>
		/// <returns>The JsonNode or null if not found</returns>
		public JsonNode? GetRawNode(string key)
		{
			if (!_data.TryGetPropertyValue(key, out JsonNode jsonNode))
			{
				return null;
			}
			return jsonNode;
		}

		public JsonObject GetRawNode()
		{
			return _data;
		}

		/// <summary>
		/// Sets an array property in the JSON object.
		/// </summary>
		/// <typeparam name="T">The type of items in the array</typeparam>
		/// <param name="key">The property name</param>
		/// <param name="items">The collection of items to set</param>
		public void SetList<T>(string key, IEnumerable<T> items)
		{
			if (typeof(T) == typeof(MigratingData))
			{
				JsonArray jsonArray = new JsonArray();
				foreach (T item in items)
				{
					if (item is MigratingData migratingData)
					{
						jsonArray.Add(migratingData._data.DeepClone());
					}
				}
				_data[key] = jsonArray;
			}
			else
			{
				string json = JsonSerializer.Serialize(items, JsonSerializationUtility.GetTypeInfo<List<T>>());
				_data[key] = JsonNode.Parse(json);
			}
		}
	}
	/// <summary>
	/// Attribute used to mark a class as a migration.
	/// </summary>
	[AttributeUsage(AttributeTargets.Class, Inherited = false)]
	public class MigrationAttribute : Attribute
	{
		/// <summary>
		/// The type of save that this migration operates on.
		/// </summary>
		public Type SaveType { get; }

		/// <summary>
		/// The version to migrate from.
		/// </summary>
		public int FromVersion { get; }

		/// <summary>
		/// The version to migrate to.
		/// </summary>
		public int ToVersion { get; }

		/// <summary>
		/// Creates a new migration attribute.
		/// </summary>
		/// <param name="saveType">The type of save that this migration operates on</param>
		/// <param name="fromVersion">The version to migrate from</param>
		/// <param name="toVersion">The version to migrate to</param>
		public MigrationAttribute(Type saveType, int fromVersion, int toVersion)
		{
			SaveType = saveType;
			FromVersion = fromVersion;
			ToVersion = toVersion;
		}
	}
	/// <summary>
	/// Base class for migrations that automatically derives migration properties from the Migration attribute
	/// and uses JsonObject for migration operations.
	/// </summary>
	/// <typeparam name="T">The save type to migrate</typeparam>
	public abstract class MigrationBase<T> : IMigration<T>, IMigration where T : ISaveSchema
	{
		private readonly Lazy<MigrationAttribute> _migrationAttribute;

		/// <summary>
		/// The version to migrate from. Derived from the Migration attribute.
		/// </summary>
		public int FromVersion => _migrationAttribute.Value.FromVersion;

		/// <summary>
		/// The version to migrate to. Derived from the Migration attribute.
		/// </summary>
		public int ToVersion => _migrationAttribute.Value.ToVersion;

		/// <summary>
		/// The type of save that this migration operates on. Derived from the Migration attribute.
		/// </summary>
		public Type SaveType => _migrationAttribute.Value.SaveType;

		protected MigrationBase()
		{
			_migrationAttribute = new Lazy<MigrationAttribute>(delegate
			{
				object[] customAttributes = GetType().GetCustomAttributes(typeof(MigrationAttribute), inherit: false);
				if (customAttributes.Length == 0)
				{
					throw new InvalidOperationException(GetType().Name + " is missing the [Migration] attribute");
				}
				return (MigrationAttribute)customAttributes[0];
			});
		}

		/// <summary>
		/// Migrates the JSON object from the old version to the new version.
		/// </summary>
		/// <param name="saveData">The JSON object to migrate</param>
		/// <returns>The migrated JSON object</returns>
		public MigratingData Migrate(MigratingData saveData)
		{
			ApplyMigration(saveData);
			saveData.Set("schema_version", ToVersion);
			return saveData;
		}

		/// <summary>
		/// Implement this in derived classes to modify the JSON object.
		/// </summary>
		/// <param name="saveData">The JSON object to modify</param>
		protected abstract void ApplyMigration(MigratingData saveData);
	}
