namespace MegaCrit.Sts2.Core.Saves.MapDrawing
{
	/// <summary>
	/// A serializable form of a single line that a player has drawn on the map.
	/// </summary>
	public class SerializableMapDrawingLine : IPacketSerializable
	{
		private static readonly QuantizeParams _quantizeParamsX = new QuantizeParams(-3f, 3f, 13);

		private static readonly QuantizeParams _quantizeParamsY = new QuantizeParams(-2f, 2f, 16);

		public bool isEraser;

		public List<Godot.Vector2> mapPoints = new List<Godot.Vector2>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteBool(isEraser);
			writer.WriteInt(mapPoints.Count, 16);
			foreach (Godot.Vector2 mapPoint in mapPoints)
			{
				writer.WriteVector2(mapPoint, _quantizeParamsX, _quantizeParamsY);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			isEraser = reader.ReadBool();
			int num = reader.ReadInt(16);
			for (int i = 0; i < num; i++)
			{
				mapPoints.Add(reader.ReadVector2(_quantizeParamsX, _quantizeParamsY));
			}
		}
	}
	/// <summary>
	/// A serializable form of the drawings that all players have drawn on the map.
	/// </summary>
	public class SerializableMapDrawings : IPacketSerializable
	{
		public List<SerializablePlayerMapDrawings> drawings = new List<SerializablePlayerMapDrawings>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteList(drawings);
		}

		public void Deserialize(PacketReader reader)
		{
			drawings = reader.ReadList<SerializablePlayerMapDrawings>();
		}

		public SerializableMapDrawings Anonymized()
		{
			return new SerializableMapDrawings
			{
				drawings = drawings.Select((SerializablePlayerMapDrawings d) => d.Anonymized()).ToList()
			};
		}
	}
	/// <summary>
	/// Converts a SerializableMapDrawings instance into a base64-encoded string that can be saved into the JSON save file.
	/// When we serialize the map drawings to a multiplayer client, we serialize it directly as a binary blob. JSON can't
	/// do this and so this class exists as an adapter.
	/// The gains from gzipping the output haven't really been measured, so if we find that it's causing performance problems
	/// we can remove it.
	/// </summary>
	public class SerializableMapDrawingsJsonConverter : JsonConverter<SerializableMapDrawings>
	{
		private static readonly PacketWriter _packetWriter = new PacketWriter();

		public override SerializableMapDrawings Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
		{
			using MemoryStream memoryStream = new MemoryStream();
			using (MemoryStream stream = new MemoryStream(Convert.FromBase64String(reader.GetString())))
			{
				using GZipStream gZipStream = new GZipStream(stream, CompressionMode.Decompress);
				gZipStream.CopyTo(memoryStream);
			}
			PacketReader packetReader = new PacketReader();
			packetReader.Reset(memoryStream.ToArray());
			return packetReader.Read<SerializableMapDrawings>();
		}

		public override void Write(Utf8JsonWriter writer, SerializableMapDrawings mapDrawings, JsonSerializerOptions options)
		{
			string value;
			lock (_packetWriter)
			{
				_packetWriter.Reset();
				_packetWriter.Write(mapDrawings);
				using MemoryStream memoryStream = new MemoryStream();
				using (GZipStream gZipStream = new GZipStream(memoryStream, CompressionLevel.Fastest, leaveOpen: true))
				{
					gZipStream.Write(_packetWriter.Buffer, 0, _packetWriter.BytePosition);
				}
				value = Convert.ToBase64String(memoryStream.ToArray());
			}
			writer.WriteStringValue(value);
		}
	}
	/// <summary>
	/// A serializable form of the drawings that a single player has drawn on the map.
	/// There are multiple of these in the save in multiplayer.
	/// </summary>
	public class SerializablePlayerMapDrawings : IPacketSerializable
	{
		public ulong playerId;

		public List<SerializableMapDrawingLine> lines = new List<SerializableMapDrawingLine>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteULong(playerId);
			writer.WriteList(lines);
		}

		public void Deserialize(PacketReader reader)
		{
			playerId = reader.ReadULong();
			lines = reader.ReadList<SerializableMapDrawingLine>();
		}

		public SerializablePlayerMapDrawings Anonymized()
		{
			return new SerializablePlayerMapDrawings
			{
				playerId = IdAnonymizer.Anonymize(playerId),
				lines = lines
			};
		}
	}
}
namespace MegaCrit.Sts2.Core.Saves.Managers
{
	public class PrefsSaveManager
	{
		public const string fileName = "prefs.save";

		private readonly ISaveStore _saveStore;

		private readonly MigrationManager _migrationManager;

		private readonly IProfileIdProvider _profileIdProvider;

		public PrefsSave Prefs { get; set; }

		/// <summary>
		/// Whether <see cref="P:MegaCrit.Sts2.Core.Saves.Managers.PrefsSaveManager.Prefs" /> has been read. It is null until <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.PrefsSaveManager.LoadPrefs" /> runs despite
		/// the non-nullable annotation, so early-boot callers have to check this first.
		/// </summary>
		public bool IsLoaded { get; private set; }

		public PrefsSaveManager(int profileId, ISaveStore saveStore, MigrationManager migrationManager)
			: this(saveStore, migrationManager, new StaticProfileIdProvider(profileId))
		{
		}

		public PrefsSaveManager(ISaveStore saveStore, MigrationManager migrationManager, IProfileIdProvider profileIdProvider)
		{
			_saveStore = saveStore;
			_migrationManager = migrationManager;
			_profileIdProvider = profileIdProvider;
		}

		public static string GetPrefsPath(int profileId, bool? forceModState = null)
		{
			return UserDataPathProvider.GetProfileDir(profileId, forceModState).PathJoin(UserDataPathProvider.SavesDir).PathJoin("prefs.save");
		}

		public void SavePrefs()
		{
			Prefs.SchemaVersion = _migrationManager.GetLatestVersion<PrefsSave>();
			string content = JsonSerializationUtility.ToJson(Prefs);
			_saveStore.WriteFile(GetPrefsPath(_profileIdProvider.CurrentProfileId), content);
		}

		public ReadSaveResult<PrefsSave> LoadPrefs()
		{
			ReadSaveResult<PrefsSave> readSaveResult = _migrationManager.LoadSave<PrefsSave>(GetPrefsPath(_profileIdProvider.CurrentProfileId));
			if (!readSaveResult.Success || readSaveResult.SaveData == null)
			{
				Prefs = _migrationManager.CreateNewSave<PrefsSave>();
				SavePrefs();
			}
			else
			{
				Prefs = readSaveResult.SaveData;
			}
			IsLoaded = true;
			return readSaveResult;
		}
	}
