	public class ProgressSaveManager
	{
		public const string fileName = "progress.save";

		private readonly ISaveStore _saveStore;

		private readonly MigrationManager _migrationManager;

		private readonly IProfileIdProvider _profileIdProvider;

		private static HashSet<ModelId>? _eliteEncounters;

		public ProgressState Progress { get; set; } = ProgressState.CreateDefault();

		public ProgressSaveManager(int profileId, ISaveStore saveStore, MigrationManager migrationManager)
			: this(saveStore, migrationManager, new StaticProfileIdProvider(profileId))
		{
		}

		public ProgressSaveManager(ISaveStore saveStore, MigrationManager migrationManager, IProfileIdProvider profileIdProvider)
		{
			_saveStore = saveStore;
			_migrationManager = migrationManager;
			_profileIdProvider = profileIdProvider;
		}

		public static string GetProgressPathForProfile(int profileId, bool? forceModState = null)
		{
			return UserDataPathProvider.GetProfileDir(profileId, forceModState).PathJoin(UserDataPathProvider.SavesDir).PathJoin("progress.save");
		}

		public void SaveProgress()
		{
			try
			{
				SerializableProgress serializableProgress = Progress.ToSerializable();
				serializableProgress.SchemaVersion = _migrationManager.GetLatestVersion<SerializableProgress>();
				string content = JsonSerializationUtility.ToJson(serializableProgress);
				_saveStore.WriteFile(GetProgressPathForProfile(_profileIdProvider.CurrentProfileId), content);
			}
			catch (Exception ex)
			{
				Log.Error($"Failed to save progress: {ex}");
				SentryService.CaptureException(ex);
			}
		}

		public ReadSaveResult<SerializableProgress> LoadProgress()
		{
			ReadSaveResult<SerializableProgress> readSaveResult = _migrationManager.LoadSave<SerializableProgress>(GetProgressPathForProfile(_profileIdProvider.CurrentProfileId));
			if (!readSaveResult.Success || readSaveResult.SaveData == null)
			{
				Progress = ProgressState.CreateDefault();
				Ironclad ironclad = ModelDb.Character<Ironclad>();
				foreach (CardModel item in ironclad.StartingDeck)
				{
					Progress.MarkCardAsSeen(item.Id);
				}
				foreach (RelicModel startingRelic in ironclad.StartingRelics)
				{
					Progress.MarkRelicAsSeen(startingRelic.Id);
				}
				SaveProgress();
			}
			else
			{
				DeserializationContext deserializationContext = new DeserializationContext();
				Progress = ProgressState.FromSerializable(readSaveResult.SaveData, deserializationContext);
				foreach (ValidationError error in deserializationContext.Errors)
				{
					Log.Warn($"Progress parse: {error}");
				}
			}
			return readSaveResult;
		}

		/// <summary>
		/// Generate an unlock state from the current progress save.
		/// </summary>
		public UnlockState GenerateUnlockState()
		{
			return new UnlockState(Progress);
		}

		/// <summary>
		/// Called after a loss. Marks the player as having lost to an encounter (not a monster).
		/// </summary>
		private void IncrementEncounterLoss(ModelId characterId, ModelId encounterId)
		{
			EncounterStats orCreateEncounterStats = Progress.GetOrCreateEncounterStats(encounterId);
			FightStats fightStats = orCreateEncounterStats.FightStats.FirstOrDefault((FightStats f) => f.Character == characterId);
			if (fightStats == null)
			{
				Log.Info($"{characterId} fought {encounterId} for the first time and LOST :(");
				FightStats item = new FightStats
				{
					Character = characterId,
					Wins = 0,
					Losses = 1
				};
				orCreateEncounterStats.FightStats.Add(item);
			}
			else
			{
				orCreateEncounterStats.IncrementLoss(characterId);
			}
		}

		/// <summary>
		/// Called after a loss. Marks the player as having lost to a specific monster in an encounter.
		/// </summary>
		private void IncrementEnemyFightLoss(ModelId characterId, ModelId monster)
		{
			EnemyStats orCreateEnemyStats = Progress.GetOrCreateEnemyStats(monster);
			FightStats fightStats = orCreateEnemyStats.FightStats.FirstOrDefault((FightStats f) => f.Character == characterId);
			if (fightStats == null)
			{
				Log.Info($"{characterId} fought {monster} for the first time and LOST >:(");
				FightStats item = new FightStats
				{
					Character = characterId,
					Wins = 0,
					Losses = 1
				};
				orCreateEnemyStats.FightStats.Add(item);
			}
			else
			{
				orCreateEnemyStats.IncrementLoss(characterId);
			}
		}

		public void MarkPotionAsSeen(PotionModel potion)
		{
			if (Progress.MarkPotionAsSeen(potion.Id) && LocalContext.IsMine(potion))
			{
				potion.Owner.DiscoveredPotions.Add(potion.Id);
			}
		}

		public void MarkCardAsSeen(CardModel card)
		{
			if (Progress.MarkCardAsSeen(card.Id) && LocalContext.IsMine(card))
			{
				card.Owner.DiscoveredCards.Add(card.Id);
			}
		}

		public void MarkRelicAsSeen(RelicModel relic)
		{
			if (Progress.MarkRelicAsSeen(relic.Id) && LocalContext.IsMine(relic))
			{
				relic.Owner.DiscoveredRelics.Add(relic.Id);
			}
		}

		/// <summary>
		/// Called whenever a run is completed. This could be Death, Victory, or Abandon.
		/// </summary>
		public void UpdateWithRunData(SerializableRun serializableRun, bool victory)
		{
			bool flag = serializableRun.Players.Count == 1;
			bool flag2 = serializableRun.GameMode == GameMode.Daily;
			bool flag3 = serializableRun.GameMode == GameMode.Custom;
			SerializablePlayer serializablePlayer;
			if (flag)
			{
				serializablePlayer = serializableRun.Players.First();
			}
			else
			{
				ulong playerId = PlatformUtil.GetLocalPlayerId(serializableRun.PlatformType);
				serializablePlayer = serializableRun.Players.FirstOrDefault((SerializablePlayer p) => p.NetId == playerId);
				if (serializablePlayer == null)
				{
					Log.Warn($"Local player with net id {playerId} not found in run! Progress will not be updated");
					return;
				}
			}
			for (int num = 0; num < serializableRun.MapPointHistory.Count; num++)
			{
				if (num >= serializableRun.Acts.Count)
				{
					Log.Warn($"There are {serializableRun.MapPointHistory.Count} acts in the map point history, but {serializableRun.Acts.Count} acts in the act array! This is unexpected");
				}
				else
				{
					ModelId id = serializableRun.Acts[num].Id;
					Progress.MarkActAsSeen(id);
				}
			}
			List<MapPointHistoryEntry> list = serializableRun.MapPointHistory.SelectMany((List<MapPointHistoryEntry> act) => act).ToList();
			Progress.TotalPlaytime += ((serializableRun.WinTime > 0) ? serializableRun.WinTime : serializableRun.RunTime);
			Progress.WongoPoints += serializablePlayer.ExtraFields.WongoPoints;
			Progress.TestSubjectKills += serializableRun.ExtraFields.TestSubjectKills;
			Progress.FloorsClimbed += list.Count;
			CharacterStats orCreateCharacterStats = Progress.GetOrCreateCharacterStats(serializablePlayer.CharacterId);
			orCreateCharacterStats.Playtime += ((serializableRun.WinTime > 0) ? serializableRun.WinTime : serializableRun.RunTime);
			if (victory)
			{
				int num2 = ScoreUtility.CalculateScore(serializableRun, victory);
				Progress.ArchitectDamage += num2;
				if (!flag2 && !flag3)
				{
					if (flag)
					{
						IncrementSingleplayerAscension(serializableRun, orCreateCharacterStats);
					}
					else
					{
						IncrementMultiplayerAscension(serializableRun);
					}
					orCreateCharacterStats.TotalWins++;
					orCreateCharacterStats.CurrentWinStreak++;
					orCreateCharacterStats.BestWinStreak = Math.Max(orCreateCharacterStats.BestWinStreak, orCreateCharacterStats.CurrentWinStreak);
					if (orCreateCharacterStats.FastestWinTime < 0 || orCreateCharacterStats.FastestWinTime > serializableRun.RunTime)
					{
						orCreateCharacterStats.FastestWinTime = serializableRun.RunTime;
					}
				}
			}
			else
			{
				if (!flag2 && !flag3)
				{
					orCreateCharacterStats.CurrentWinStreak = 0L;
					orCreateCharacterStats.TotalLosses++;
				}
				MapPointHistoryEntry mapPointHistoryEntry = serializableRun.MapPointHistory.LastOrDefault()?.LastOrDefault();
				if (mapPointHistoryEntry != null)
				{
					RoomType roomType = mapPointHistoryEntry.Rooms.Last().RoomType;
					if (roomType.IsCombatRoom())
					{
						ModelId modelId = mapPointHistoryEntry.Rooms.Last().ModelId;
						ModelId characterId = serializablePlayer.CharacterId;
						IncrementEncounterLoss(characterId, modelId);
						foreach (ModelId monsterId in mapPointHistoryEntry.Rooms.Last().MonsterIds)
						{
							IncrementEnemyFightLoss(characterId, monsterId);
						}
					}
				}
			}
			foreach (MapPointHistoryEntry item in list)
			{
				MapPointRoomHistoryEntry mapPointRoomHistoryEntry = item.FirstRoomOfType(RoomType.Event);
				if (mapPointRoomHistoryEntry != null)
				{
					Progress.MarkEventAsSeen(mapPointRoomHistoryEntry.ModelId);
				}
			}
			if (!flag2 && !flag3)
			{
				HashSet<ModelId> hashSet = serializablePlayer.Deck.Select((SerializableCard c) => c.Id).ToHashSet();
				foreach (ModelId item2 in hashSet)
				{
					CardStats orCreateCardStats = Progress.GetOrCreateCardStats(item2);
					if (victory)
					{
						orCreateCardStats.TimesWon++;
					}
					else
					{
						orCreateCardStats.TimesLost++;
					}
				}
				foreach (MapPointHistoryEntry item3 in list)
				{
					PlayerMapPointHistoryEntry entry = item3.GetEntry(serializablePlayer.NetId);
					foreach (CardChoiceHistoryEntry cardChoice in entry.CardChoices)
					{
						CardStats orCreateCardStats2 = Progress.GetOrCreateCardStats(cardChoice.Card.Id);
						if (cardChoice.wasPicked)
						{
							orCreateCardStats2.TimesPicked++;
						}
						else
						{
							orCreateCardStats2.TimesSkipped++;
						}
					}
					if (item3.MapPointType == MapPointType.Ancient)
					{
						MapPointRoomHistoryEntry mapPointRoomHistoryEntry2 = item3.FirstRoomOfType(RoomType.Event);
						AncientStats orCreateAncientStats = Progress.GetOrCreateAncientStats(mapPointRoomHistoryEntry2.ModelId);
						if (victory)
						{
							orCreateAncientStats.IncrementWin(serializablePlayer.CharacterId);
						}
						else
						{
							orCreateAncientStats.IncrementLoss(serializablePlayer.CharacterId);
						}
					}
				}
			}
			UpdateEpochsPostRun(serializablePlayer, serializableRun, victory);
			SaveProgress();
		}

		/// <summary>
		/// Check for Epoch-related unlocks at the end of each run.
		/// Singleplayer only.
		/// </summary>
		private void UpdateEpochsPostRun(SerializablePlayer serializablePlayer, SerializableRun serializableRun, bool victory)
		{
			TryObtainEpochPostRun(EpochModel.Get<NeowEpoch>(), serializablePlayer, serializableRun);
			PostRunUnlockCharacterEpochCheck(serializablePlayer, serializableRun);
			PostRunCharacterEpochChecks(serializablePlayer, serializableRun, victory);
			int num = ModelDb.AllCharacters.Count();
			if (victory && Progress.CharacterStats.Count >= num)
			{
				TryObtainEpochPostRun(EpochModel.Get<DailyRunEpoch>(), serializablePlayer, serializableRun);
			}
			if (Progress.CharacterStats.Count >= num)
			{
				TryObtainEpochPostRun(EpochModel.Get<OrobasEpoch>(), serializablePlayer, serializableRun);
			}
			if (ModelDb.AllAncients.All((AncientEventModel a) => Progress.AncientStats.ContainsKey(a.Id) || a is Darv))
			{
				TryObtainEpochPostRun(EpochModel.Get<DarvEpoch>(), serializablePlayer, serializableRun);
			}
		}

		/// <summary>
		/// If you complete a run with a character for the first time,
		/// there's generally an unlock for another character.
		/// </summary>
		private void PostRunUnlockCharacterEpochCheck(SerializablePlayer serializablePlayer, SerializableRun serializableRun)
		{
			CharacterModel byId = ModelDb.GetById<CharacterModel>(serializablePlayer.CharacterId);
			string text = ((byId is Silent) ? EpochModel.GetId<Regent1Epoch>() : ((byId is Regent) ? EpochModel.GetId<Necrobinder1Epoch>() : ((!(byId is Necrobinder)) ? null : EpochModel.GetId<Defect1Epoch>())));
			string text2 = text;
			if (text2 != null && TryObtainEpochPostRun(EpochModel.Get(text2), serializablePlayer, serializableRun))
			{
				Log.Info($"Epoch obtained for playing a run as {serializablePlayer.CharacterId}");
			}
		}

		private void PostRunCharacterEpochChecks(SerializablePlayer serializablePlayer, SerializableRun serializableRun, bool victory)
		{
			if (victory)
			{
				CheckAscensionOneCompleted(serializablePlayer, serializableRun);
				string id = EpochModel.GetId<CustomAndSeedsEpoch>();
				if (Progress.Wins >= 3)
				{
					TryObtainEpochPostRun(EpochModel.Get(id), serializablePlayer, serializableRun);
				}
			}
		}

		/// <summary>
		/// When the player completes Ascension 1 they unlock Character Epoch 7.
		/// This unlock grants the player the means to Kill the Architect and 3 cards.
		/// </summary>
		private void CheckAscensionOneCompleted(SerializablePlayer serializablePlayer, SerializableRun serializableRun)
		{
			if (serializableRun.Ascension == 1)
			{
				CharacterModel byId = ModelDb.GetById<CharacterModel>(serializablePlayer.CharacterId);
				string text = ((byId is Ironclad) ? EpochModel.GetId<Ironclad7Epoch>() : ((byId is Silent) ? EpochModel.GetId<Silent7Epoch>() : ((byId is Regent) ? EpochModel.GetId<Regent7Epoch>() : ((byId is Defect) ? EpochModel.GetId<Defect7Epoch>() : ((!(byId is Necrobinder)) ? null : EpochModel.GetId<Necrobinder7Epoch>())))));
				string text2 = text;
				if (text2 != null)
				{
					TryObtainEpochPostRun(EpochModel.Get(text2), serializablePlayer, serializableRun);
				}
			}
		}

		/// <summary>
		/// Checks for Character5Epoch for all characters.
		/// Requires defeating 15 Elites in the game with the character.
		/// </summary>
		private void CheckFifteenElitesDefeatedEpoch(Player localPlayer)
		{
			CharacterModel character = localPlayer.Character;
			EpochModel epochModel;
			if (!(character is Ironclad))
			{
				if (!(character is Silent))
				{
					if (!(character is Regent))
					{
						if (!(character is Defect))
						{
							if (!(character is Necrobinder))
							{
								if (!(character is Deprived))
								{
									throw new ArgumentOutOfRangeException("character", character, null);
								}
								epochModel = null;
							}
							else
							{
								epochModel = EpochModel.Get(EpochModel.GetId<Necrobinder5Epoch>());
							}
						}
						else
						{
							epochModel = EpochModel.Get(EpochModel.GetId<Defect5Epoch>());
						}
					}
					else
					{
						epochModel = EpochModel.Get(EpochModel.GetId<Regent5Epoch>());
					}
				}
				else
				{
					epochModel = EpochModel.Get(EpochModel.GetId<Silent5Epoch>());
				}
			}
			else
			{
				epochModel = EpochModel.Get(EpochModel.GetId<Ironclad5Epoch>());
			}
			EpochModel epochModel2 = epochModel;
			if (epochModel2 == null)
			{
				return;
			}
			HashSet<ModelId> eliteEncounters = GetEliteEncounters();
			int num = 0;
			foreach (EncounterStats value in Progress.EncounterStats.Values)
			{
				if (!eliteEncounters.Contains(value.Id))
				{
					continue;
				}
				foreach (FightStats fightStat in value.FightStats)
				{
					if (fightStat.Character == character.Id)
					{
						num += fightStat.Wins;
						break;
					}
				}
			}
			Log.Info($"Elites Defeated: {num}/{eliteEncounters.Count}");
			if (num >= 15)
			{
				TryObtainEpochMidRun(epochModel2, localPlayer);
			}
		}

		/// <summary>
		/// Checks for Character6Epoch for all characters.
		/// Requires defeating 15 Bosses in the game with the character.
		/// </summary>
		private void CheckFifteenBossesDefeatedEpoch(Player localPlayer)
		{
			CharacterModel character = localPlayer.Character;
			EpochModel epochModel;
			if (!(character is Ironclad))
			{
				if (!(character is Silent))
				{
					if (!(character is Regent))
					{
						if (!(character is Defect))
						{
							if (!(character is Necrobinder))
							{
								if (!(character is Deprived))
								{
									throw new ArgumentOutOfRangeException("character", character, null);
								}
								epochModel = null;
							}
							else
							{
								epochModel = EpochModel.Get(EpochModel.GetId<Necrobinder6Epoch>());
							}
						}
						else
						{
							epochModel = EpochModel.Get(EpochModel.GetId<Defect6Epoch>());
						}
					}
					else
					{
						epochModel = EpochModel.Get(EpochModel.GetId<Regent6Epoch>());
					}
				}
				else
				{
					epochModel = EpochModel.Get(EpochModel.GetId<Silent6Epoch>());
				}
			}
			else
			{
				epochModel = EpochModel.Get(EpochModel.GetId<Ironclad6Epoch>());
			}
			EpochModel epochModel2 = epochModel;
			if (epochModel2 == null)
			{
				return;
			}
			HashSet<ModelId> hashSet = ModelDb.Acts.SelectMany((ActModel a) => a.AllBossEncounters.Select((EncounterModel e) => e.Id)).ToHashSet();
			int num = 0;
			foreach (EncounterStats value in Progress.EncounterStats.Values)
			{
				if (!hashSet.Contains(value.Id))
				{
					continue;
				}
				foreach (FightStats fightStat in value.FightStats)
				{
					if (fightStat.Character == character.Id)
					{
						num += fightStat.Wins;
						break;
					}
				}
			}
			if (num >= 15)
			{
				TryObtainEpochMidRun(epochModel2, localPlayer);
			}
		}

		/// <summary>
		/// Helper function to obtain character unlocks 1, 2, and 3.
		/// Requires the player to defeat a boss in an act for the first time (for each character!)
		/// </summary>
		private void ObtainCharUnlockEpoch(Player localPlayer, int act)
		{
			if (localPlayer.Character.IsPlayable)
			{
				string text = localPlayer.Character.Id.Entry.ToUpperInvariant();
				EpochModel epochModel = null;
				switch (act)
				{
				case 0:
					epochModel = EpochModel.Get(text + "2_EPOCH");
					break;
				case 1:
					epochModel = EpochModel.Get(text + "3_EPOCH");
					break;
				case 2:
					epochModel = EpochModel.Get(text + "4_EPOCH");
					break;
				case 3:
					Log.Error($"Act {act + 1} is not yet implemented.");
					break;
				default:
					Log.Error($"Unsupported Act: {act}");
					break;
				}
				if (epochModel == null)
				{
					Log.Error("EpochModel was not found :(");
				}
				else if (TryObtainEpochMidRun(epochModel, localPlayer))
				{
					Log.Info($"Epoch obtained for completing Act {act + 1}");
				}
			}
		}

		/// <summary>
		/// Called mid-run (like when you kill a boss that unlocks an Epoch).
		/// If this Epoch's slot is available, we obtain it and return true.
		/// We return a bool so callers can log or show VFX accordingly.
		/// </summary>
		/// <param name="epoch">Epoch to try to obtain.</param>
		/// <param name="localPlayer">The local player's Player instance.</param>
		/// <returns>
		/// True if you Obtained a new Epoch, false if not (you already have it OR the slot is unavailable).
		/// </returns>
		private bool TryObtainEpochMidRun(EpochModel epoch, Player localPlayer)
		{
			if (localPlayer.RunState.GameMode.AreAchievementsAndEpochsLocked())
			{
				return false;
			}
			if (!TryObtainEpochInternal(epoch))
			{
				return false;
			}
			localPlayer.DiscoveredEpochs.Add(epoch.Id);
			return true;
		}

		/// <summary>
		/// Called post-run (like after abandoning your first run, which unlocks the Silent).
		/// If this Epoch's slot is available, we obtain it and return true.
		/// We return a bool so callers can log or show VFX accordingly.
		/// </summary>
		/// <param name="epoch">Epoch to try to obtain.</param>
		/// <param name="serializablePlayer">The serializable version of the local player's Player instance.</param>
		/// <param name="serializableRun">The serializable version of the run.</param>
		/// <returns>
		/// True if you Obtained a new Epoch, false if not (you already have it OR the slot is unavailable).
		/// </returns>
		private bool TryObtainEpochPostRun(EpochModel epoch, SerializablePlayer serializablePlayer, SerializableRun serializableRun)
		{
			if (serializableRun.GameMode.AreAchievementsAndEpochsLocked())
			{
				return false;
			}
			if (!TryObtainEpochInternal(epoch))
			{
				return false;
			}
			serializablePlayer.DiscoveredEpochs.Add(epoch.Id);
			return true;
		}

		/// <summary>
		/// WARNING: This should only be called by <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.TryObtainEpochMidRun(MegaCrit.Sts2.Core.Timeline.EpochModel,MegaCrit.Sts2.Core.Entities.Players.Player)" /> and
		/// <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.TryObtainEpochPostRun(MegaCrit.Sts2.Core.Timeline.EpochModel,MegaCrit.Sts2.Core.Saves.Runs.SerializablePlayer,MegaCrit.Sts2.Core.Saves.SerializableRun)" />.
		/// If this Epoch's slot is available, we obtain it and return true.
		/// We return a bool so callers can log or show VFX accordingly.
		/// </summary>
		/// <param name="epoch">Epoch to try to obtain.</param>
		/// <returns>
		/// True if you Obtained a new Epoch, false if not (you already have it OR the slot is unavailable).
		/// </returns>
		private bool TryObtainEpochInternal(EpochModel epoch)
		{
			if (Progress.IsEpochObtained(epoch.Id))
			{
				Log.Info("Player already has Epoch: " + epoch.Id);
				return false;
			}
			Progress.ObtainEpoch(epoch.Id);
			NGame.Instance?.AddChildSafely(NGainEpochVfx.Create(epoch));
			if (GetRevealableEpochs().All((SerializableEpoch e) => e.Id != epoch.Id))
			{
				string text = "Epoch " + epoch.Id + " was obtained, but is not yet revealable by the player!";
				Log.Warn(text);
				SentryService.CaptureMessage(text, SentryLevel.Info, delegate(Scope scope)
				{
					string text2 = JsonSerializer.Serialize(Progress.Epochs, JsonSerializationUtility.GetTypeInfo<List<SerializableEpoch>>());
					scope.AddCompressedAttachment(text2, "epochs.txt.gz");
				});
			}
			return true;
		}

		/// <summary>
		/// Returns the set of epochs that the player has both obtained and may reveal.
		/// In certain (buggy) scenarios, the player may end up obtaining epochs that are still hidden. An example scenario
		/// (though this may be fixed in the future) is:
		///  - The player joins a multiplayer daily, which allows them to play a character they have not unlocked
		///  - The player obtains an epoch for that character which they can't see on the timeline
		///
		/// This method skips those sorts of epochs. However, it still returns epochs that are in ObtainedNoSlot state but
		/// are about to be revealed by another epoch the player has obtained.
		/// </summary>
		public IEnumerable<SerializableEpoch> GetRevealableEpochs()
		{
			HashSet<string> satisfiedEpochIds = new HashSet<string>(from e in Progress.Epochs.Where(delegate(SerializableEpoch e)
				{
					EpochState state2 = e.State;
					return (uint)(state2 - 3) <= 1u;
				})
				select e.Id);
			HashSet<string> reachableSet = new HashSet<string>();
			Queue<string> queue = new Queue<string>();
			string id = EpochModel.Get<NeowEpoch>().Id;
			reachableSet.Add(id);
			queue.Enqueue(id);
			foreach (SerializableEpoch epoch in Progress.Epochs)
			{
				bool flag = epoch.Id == id;
				bool flag2 = flag;
				if (!flag2)
				{
					EpochState state = epoch.State;
					bool flag3 = ((state == EpochState.None || (uint)(state - 2) <= 1u) ? true : false);
					flag2 = flag3;
				}
				if (!flag2)
				{
					reachableSet.Add(epoch.Id);
					queue.Enqueue(epoch.Id);
				}
			}
			while (queue.Count > 0)
			{
				string id2 = queue.Dequeue();
				EpochModel[] timelineExpansion = EpochModel.Get(id2).GetTimelineExpansion();
				foreach (EpochModel epochModel in timelineExpansion)
				{
					if (!reachableSet.Contains(epochModel.Id))
					{
						reachableSet.Add(epochModel.Id);
						if (satisfiedEpochIds.Contains(epochModel.Id))
						{
							queue.Enqueue(epochModel.Id);
						}
					}
				}
			}
			return Progress.Epochs.Where((SerializableEpoch e) => satisfiedEpochIds.Contains(e.Id) && reachableSet.Contains(e.Id));
		}

		/// <summary>
		/// Lots of checks and update of the progress save file after the end of each combat.
		/// </summary>
		public void UpdateAfterCombatWon(Player localPlayer, CombatRoom room)
		{
			CombatState combatState = room.CombatState;
			IRunState runState = combatState.RunState;
			CharacterModel character = localPlayer.Character;
			ModelId id = combatState.Encounter.Id;
			EncounterStats orCreateEncounterStats = Progress.GetOrCreateEncounterStats(id);
			FightStats fightStats = orCreateEncounterStats.FightStats.FirstOrDefault((FightStats f) => f.Character == character.Id);
			if (fightStats == null)
			{
				Log.Info($"{character.Id} fought {id} for the first time and WON >:)");
				FightStats item = new FightStats
				{
					Character = character.Id,
					Wins = 1,
					Losses = 0
				};
				orCreateEncounterStats.FightStats.Add(item);
			}
			else
			{
				orCreateEncounterStats.IncrementWin(character.Id);
			}
			if (room.RoomType == RoomType.Boss)
			{
				ObtainCharUnlockEpoch(localPlayer, runState.CurrentActIndex);
				CheckFifteenBossesDefeatedEpoch(localPlayer);
			}
			else if (room.RoomType == RoomType.Elite)
			{
				CheckFifteenElitesDefeatedEpoch(localPlayer);
			}
			foreach (MonsterModel spawnedEnemy in room.Encounter.SpawnedEnemies)
			{
				EnemyStats orCreateEnemyStats = Progress.GetOrCreateEnemyStats(spawnedEnemy.Id);
				bool flag = orCreateEnemyStats.FightStats.Count == 0;
				FightStats fightStats2 = orCreateEnemyStats.FightStats.FirstOrDefault((FightStats f) => f.Character == character.Id);
				if (fightStats2 == null)
				{
					Log.Info($"{character.Id} fought {spawnedEnemy.Id} for the first time and WON >:(");
					FightStats item2 = new FightStats
					{
						Character = character.Id,
						Wins = 1,
						Losses = 0
					};
					orCreateEnemyStats.FightStats.Add(item2);
					if (flag)
					{
						localPlayer.DiscoveredEnemies.Add(spawnedEnemy.Id);
					}
				}
				else
				{
					orCreateEnemyStats.IncrementWin(character.Id);
				}
			}
		}

		/// <summary>
		/// If the player wins a singleplayer run, this logic checks if they're playing on Max Ascension.
		/// If so, increment it by 1.
		/// </summary>
		private static void IncrementSingleplayerAscension(SerializableRun run, CharacterStats charStats)
		{
			if (run.Ascension == charStats.MaxAscension)
			{
				if (charStats.MaxAscension < 10)
				{
					charStats.MaxAscension++;
					charStats.PreferredAscension = charStats.MaxAscension;
				}
			}
			else
			{
				Log.Info($"Not playing on max singleplayer ascension ({charStats.MaxAscension})");
			}
		}

		/// <summary>
		/// If the player wins a multiplayer run, this logic checks if they're playing on Max Ascension.
		/// If so, increment it by 1.
		/// </summary>
		private void IncrementMultiplayerAscension(SerializableRun run)
		{
			if (run.Ascension == Progress.MaxMultiplayerAscension)
			{
				if (Progress.MaxMultiplayerAscension < 10)
				{
					Progress.MaxMultiplayerAscension++;
					Progress.PreferredMultiplayerAscension = Progress.MaxMultiplayerAscension;
				}
			}
			else
			{
				Log.Info($"Not playing on max multiplayer ascension ({Progress.MaxMultiplayerAscension})");
			}
		}

		/// <summary>
		/// Returns true if all ftues are disabled OR if the given ftue key exists (seen by the player before).
		/// Is also disabled if there's no game (test mode)
		/// </summary>
		public bool SeenFtue(string ftueKey)
		{
			if (!Progress.EnableFtues)
			{
				return true;
			}
			return Progress.FtueCompleted.Contains(ftueKey);
		}

		/// <summary>
		/// Checks if a one-time popup has been seen before or not.
		/// This is only used by the "Ascension Unlocked" popups for now.
		/// </summary>
		public bool SeenPopup(string popupKey)
		{
			if (TestMode.IsOn)
			{
				return true;
			}
			return Progress.FtueCompleted.Contains(popupKey);
		}

		public void MarkFtueAsComplete(string ftueId)
		{
			if (Progress.MarkFtueAsComplete(ftueId))
			{
				Log.Info("Player has seen ftue " + ftueId + "!");
				SaveProgress();
			}
		}

		public void SetFtuesEnabled(bool enabled)
		{
			if (Progress.EnableFtues != enabled)
			{
				Log.Info($"Player has set FTUEs enabled: {enabled}");
				Progress.EnableFtues = enabled;
				SaveProgress();
			}
		}

		public void ResetFtues()
		{
			Log.Info("Player has reset FTUEs to enabled");
			Progress.ResetFtues();
			SaveProgress();
		}

		private static HashSet<ModelId> GetEliteEncounters()
		{
			return _eliteEncounters ?? (_eliteEncounters = (from e in ModelDb.AllEncounters
				where e.RoomType == RoomType.Elite
				select e.Id).Distinct().ToHashSet());
		}
	}
	public class RunHistorySaveManager
	{
		public const int maxCloudBytes = 5242880;

		public const int maxCloudFileCount = 100;

		private const string _historyDirName = "history";

		private readonly ISaveStore _saveStore;

		private readonly MigrationManager _migrationManager;

		private readonly IProfileIdProvider _profileIdProvider;

		private string HistoryPath => GetHistoryPath(_profileIdProvider.CurrentProfileId);

		public RunHistorySaveManager(int profileId, ISaveStore saveStore, MigrationManager migrationManager)
			: this(saveStore, migrationManager, new StaticProfileIdProvider(profileId))
		{
		}

		public RunHistorySaveManager(ISaveStore saveStore, MigrationManager migrationManager, IProfileIdProvider profileIdProvider)
		{
			_saveStore = saveStore;
			_migrationManager = migrationManager;
			_profileIdProvider = profileIdProvider;
		}

		/// <summary>
		/// This should be called right after the profile ID is initialized so that there is a directory we can save run
		/// histories to.
		/// </summary>
		public void CreateRunHistoryDirectory()
		{
			_saveStore.CreateDirectory(HistoryPath);
		}

		public static string GetHistoryPath(int profileId, bool? forceModState = null)
		{
			return UserDataPathProvider.GetProfileDir(profileId, forceModState).PathJoin(UserDataPathProvider.SavesDir).PathJoin("history");
		}

		public void SaveHistory(RunHistory history)
		{
			history.SchemaVersion = _migrationManager.GetLatestVersion<RunHistory>();
			string content = JsonSerializationUtility.ToJson(history);
			string path = Path.Combine(HistoryPath, $"{history.StartTime}.run");
			SaveHistoryInternal(path, content);
			Log.Info($"Saved run history: {history.StartTime}.run");
		}

		private void SaveHistoryInternal(string path, string content)
		{
			if (_saveStore is CloudSaveStore cloudSaveStore)
			{
				int byteCount = Encoding.UTF8.GetByteCount(content);
				cloudSaveStore.ForgetFilesInDirectoryBeforeWritingIfNecessary(HistoryPath, byteCount, 5242880, 100);
			}
			_saveStore.WriteFile(path, content);
		}

		public int GetHistoryCount()
		{
			if (!_saveStore.DirectoryExists(HistoryPath))
			{
				return 0;
			}
			return _saveStore.GetFilesInDirectory(HistoryPath).Length;
		}

		/// <summary>
		/// Loads a single run history file with migration support.
		/// </summary>
		/// <param name="fileName">The history file name (e.g., "1234567890.run")</param>
		/// <returns>The result of the load operation</returns>
		public ReadSaveResult<RunHistory> LoadHistory(string fileName)
		{
			string filePath = Path.Combine(HistoryPath, fileName);
			ReadSaveResult<RunHistory> readSaveResult = _migrationManager.LoadSave<RunHistory>(filePath);
			if (readSaveResult.Success)
			{
				Log.Info("Successfully loaded run history: " + fileName);
			}
			else
			{
				Log.Warn($"Failed to load run history {fileName}: {readSaveResult.Status}");
			}
			return readSaveResult;
		}

		/// <summary>
		/// Returns a list of all the run histories that we have available to load.
		/// To actually load the history, use <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.RunHistorySaveManager.LoadHistory(System.String)" />.
		/// </summary>
		public List<string> LoadAllRunHistoryNames()
		{
			string[] filesInDirectory = _saveStore.GetFilesInDirectory(HistoryPath);
			int num = 0;
			List<string> list = new List<string>();
			string[] array = filesInDirectory;
			foreach (string text in array)
			{
				if (text.EndsWith(".corrupt"))
				{
					num++;
				}
				else if (!text.EndsWith(".backup"))
				{
					list.Add(text);
				}
			}
			if (num > 0)
			{
				Log.Warn($"Skipping {num} corrupt save files in history directory");
			}
			Log.Debug($"Found {list.Count} run history files");
			return list;
		}
	}
	public class RunSaveManager
	{
		public const string runSaveFileName = "current_run.save";

		public const string multiplayerRunSaveFileName = "current_run_mp.save";

		private readonly ISaveStore _saveStore;

		private readonly MigrationManager _migrationManager;

		private readonly bool _forceSynchronous;

		private readonly IProfileIdProvider _profileIdProvider;

		private string CurrentRunSavePath => GetRunSavePath(_profileIdProvider.CurrentProfileId, "current_run.save");

		private string CurrentMultiplayerRunSavePath => GetRunSavePath(_profileIdProvider.CurrentProfileId, "current_run_mp.save");

		public bool HasRunSave
		{
			get
			{
				if (!_saveStore.FileExists(CurrentRunSavePath))
				{
					return _saveStore.FileExists(CurrentRunSavePath + ".backup");
				}
				return true;
			}
		}

		public bool HasMultiplayerRunSave
		{
			get
			{
				if (!_saveStore.FileExists(CurrentMultiplayerRunSavePath))
				{
					return _saveStore.FileExists(CurrentMultiplayerRunSavePath + ".backup");
				}
				return true;
			}
		}

		public int SchemaVersion => _migrationManager.GetLatestVersion<SerializableRun>();

		public event Action? Saved;

		public RunSaveManager(int profileId, ISaveStore saveStore, MigrationManager migrationManager, bool forceSynchronous = false)
			: this(saveStore, migrationManager, new StaticProfileIdProvider(profileId), forceSynchronous)
		{
		}

		public RunSaveManager(ISaveStore saveStore, MigrationManager migrationManager, IProfileIdProvider profileIdProvider, bool forceSynchronous = false)
		{
			_saveStore = saveStore;
			_migrationManager = migrationManager;
			_forceSynchronous = forceSynchronous;
			_profileIdProvider = profileIdProvider;
		}

		/// <summary>
		/// Save a run while one is currently in progress.
		/// </summary>
		/// <param name="preFinishedRoom"></param>
		public async Task SaveRun(AbstractRoom? preFinishedRoom)
		{
			if (RunManager.Instance.ShouldSave && (RunManager.Instance.NetService.Type == NetGameType.Singleplayer || RunManager.Instance.NetService.Type == NetGameType.Host))
			{
				SerializableRun save = RunManager.Instance.ToSave(preFinishedRoom);
				await SaveRun(save, RunManager.Instance.NetService.Type == NetGameType.Host);
			}
		}

		/// <summary>
		/// Save a run when you just have a SerializableRun field, independent of whether run manager has been set up yet.
		/// WARNING: Only use this if you know what you are doing
		/// This exists so we can resave a serializable run without already having a run in progress
		/// Important for resaving SerializableRun.NumReloads right after we've started a run.
		/// in most cases you should call the other SaveRun overload.
		/// </summary>
		public async Task SaveRun(SerializableRun save, bool isMultiplayer)
		{
			string savePath = (isMultiplayer ? CurrentMultiplayerRunSavePath : CurrentRunSavePath);
			using MemoryStream stream = new MemoryStream();
			if (!_forceSynchronous)
			{
				await JsonSerializer.SerializeAsync((Stream)stream, save, JsonSerializationUtility.GetTypeInfo<SerializableRun>(), default(CancellationToken));
				stream.Seek(0L, SeekOrigin.Begin);
				await _saveStore.WriteFileAsync(savePath, stream.ToArray());
			}
			else
			{
				JsonSerializer.Serialize(stream, save, JsonSerializationUtility.GetTypeInfo<SerializableRun>());
				stream.Seek(0L, SeekOrigin.Begin);
				_saveStore.WriteFile(savePath, stream.ToArray());
			}
			Saved?.Invoke();
		}

		public ReadSaveResult<SerializableRun> LoadRunSave()
		{
			ReadSaveResult<SerializableRun> readSaveResult = _migrationManager.LoadSave<SerializableRun>(CurrentRunSavePath);
			if (readSaveResult.Success)
			{
				return readSaveResult;
			}
			if (readSaveResult.Status == ReadSaveStatus.FileNotFound)
			{
				Log.Info("Run save file not found at " + CurrentRunSavePath);
			}
			else if (!readSaveResult.Status.IsRecoverable())
			{
				Log.Error($"Failed to load run save: status={readSaveResult.Status} msg={readSaveResult.ErrorMessage}");
			}
			else
			{
				Log.Warn($"Run save had recoverable issues: status={readSaveResult.Status} msg={readSaveResult.ErrorMessage}");
			}
			return readSaveResult;
		}

		public ReadSaveResult<SerializableRun> LoadMultiplayerRunSave()
		{
			ReadSaveResult<SerializableRun> readSaveResult = _migrationManager.LoadSave<SerializableRun>(CurrentMultiplayerRunSavePath);
			if (readSaveResult.Success)
			{
				return readSaveResult;
			}
			if (readSaveResult.Status == ReadSaveStatus.FileNotFound)
			{
				Log.Info("Multiplayer run save file not found at " + CurrentMultiplayerRunSavePath);
			}
			else if (!readSaveResult.Status.IsRecoverable())
			{
				Log.Error($"Failed to load multiplayer run save: status={readSaveResult.Status} msg={readSaveResult.ErrorMessage}");
			}
			else
			{
				Log.Warn($"Multiplayer run save had recoverable issues: status={readSaveResult.Status} msg={readSaveResult.ErrorMessage}");
			}
			return readSaveResult;
		}

		/// <summary>
		/// Loads the multiplayer run and canonicalizes it.
		/// In this case, "canonicalize" means that we load the save, detect any deprecated content, and replace it with
		/// the deprecated version of that model (e.g. <see cref="T:MegaCrit.Sts2.Core.Models.Events.DeprecatedEvent" />.)
		/// </summary>
		/// <param name="localPlayerId">The local player ID who is loading the save.</param>
		public ReadSaveResult<SerializableRun> LoadAndCanonicalizeMultiplayerRunSave(ulong localPlayerId)
		{
			ReadSaveResult<SerializableRun> readSaveResult = LoadMultiplayerRunSave();
			if (readSaveResult != null && readSaveResult.Success && readSaveResult.SaveData != null)
			{
				try
				{
					SerializableRun data = RunManager.CanonicalizeSave(readSaveResult.SaveData, localPlayerId);
					return new ReadSaveResult<SerializableRun>(data, ReadSaveStatus.Success);
				}
				catch (Exception value)
				{
					Log.Error($"Multiplayer run save validation failed: {value}");
					RenameBrokenMultiplayerRunSave(ReadSaveStatus.ValidationFailed);
					return new ReadSaveResult<SerializableRun>(ReadSaveStatus.ValidationFailed, $"Save file validation failed: {value}");
				}
			}
			return readSaveResult;
		}

		public void DeleteCurrentRun()
		{
			_saveStore.DeleteFile(CurrentRunSavePath);
			_saveStore.DeleteFile(CurrentRunSavePath + ".backup");
		}

		public void DeleteCurrentMultiplayerRun()
		{
			_saveStore.DeleteFile(CurrentMultiplayerRunSavePath);
			_saveStore.DeleteFile(CurrentMultiplayerRunSavePath + ".backup");
		}

		public void RenameBrokenMultiplayerRunSave(ReadSaveStatus status)
		{
			try
			{
				if (HasMultiplayerRunSave)
				{
					if (_saveStore.FileExists(CurrentMultiplayerRunSavePath))
					{
						string text = CorruptFileHandler.GenerateCorruptFilePath(CurrentMultiplayerRunSavePath, status);
						_saveStore.RenameFile(CurrentMultiplayerRunSavePath, text);
						Log.Error($"Corrupt multiplayer run save detected: Renamed '{CurrentMultiplayerRunSavePath}' to '{text}'");
					}
					string text2 = CurrentMultiplayerRunSavePath + ".backup";
					if (_saveStore.FileExists(text2))
					{
						string text3 = CorruptFileHandler.GenerateCorruptFilePath(text2, status);
						_saveStore.RenameFile(text2, text3);
						Log.Error($"Corrupt multiplayer run backup detected: Renamed '{text2}' to '{text3}'");
					}
				}
			}
			catch (Exception ex)
			{
				Log.Warn("Failed to rename broken multiplayer run save: " + ex.Message);
			}
		}

		public static string GetRunSavePath(int profileId, string fileName, bool? forceModState = null)
		{
			return UserDataPathProvider.GetProfileDir(profileId, forceModState).PathJoin(UserDataPathProvider.SavesDir).PathJoin(fileName);
		}
	}
	public class SettingsSaveManager
	{
		public const string settingsSaveFileName = "settings.save";

		private readonly ISaveStore _saveStore;

		private readonly MigrationManager _migrationManager;

		private string SettingsPath => "settings.save";

		public SettingsSave Settings { get; set; }

		public SettingsSaveManager(ISaveStore saveStore, MigrationManager migrationManager)
		{
			_saveStore = saveStore;
			_migrationManager = migrationManager;
		}

		public void SaveSettings()
		{
			Settings.SchemaVersion = _migrationManager.GetLatestVersion<SettingsSave>();
			string content = JsonSerializationUtility.ToJson(Settings);
			_saveStore.WriteFile(SettingsPath, content);
		}

		public ReadSaveResult<SettingsSave> LoadSettings()
		{
			ReadSaveResult<SettingsSave> readSaveResult = _migrationManager.LoadSave<SettingsSave>(SettingsPath);
			if (!readSaveResult.Success || readSaveResult.SaveData == null)
			{
				Settings = _migrationManager.CreateNewSave<SettingsSave>();
				ApplyPlatformDefaults(Settings);
				SaveSettings();
			}
			else
			{
				Settings = readSaveResult.SaveData;
			}
			return readSaveResult;
		}

		/// <summary>
		/// Applies platform-specific default settings when a settings file is recreated.
		/// </summary>
		/// <param name="settings">The settings object to apply defaults to</param>
		private void ApplyPlatformDefaults(SettingsSave settings)
		{
			if (SteamInitializer.Initialized && SteamUtils.IsSteamRunningOnSteamDeck())
			{
				settings.Fullscreen = true;
				settings.WindowPosition = new Vector2I(0, 0);
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Runs
{
	/// <summary>
	/// Various flags which can be passed to the CardCreationOptions to control card generation behavior.
	/// This controls both built-in behavior (rolling for upgrades in rewards) as well as hook behavior (Molten Egg, Ruby
	/// Earrings).
	/// </summary>
	[Flags]
	public enum CardCreationFlags
	{
		/// <summary>
		/// Indicates that rarity should not be modified.
		/// This should be used when an event option specifies the rarity. For example, <see cref="T:MegaCrit.Sts2.Core.Models.Events.RoomFullOfCheese" />
		/// specifies that its rewards are uncommon, so no relics should modify the rarities.
		/// </summary>
		NoRarityModification = 1,
		/// <summary>
		/// Indicates that the built-in reward upgrade should not be applied.
		/// When offering combat rewards, there is a chance that cards are offered upgraded. This should not apply to most
		/// event rewards, but it does for some other rewards like those offered from <see cref="T:MegaCrit.Sts2.Core.Models.Relics.Orrery" />.
		/// </summary>
		NoUpgradeRoll = 2,
		/// <summary>
		/// Indicates that all modify hooks that upgrade cards should not apply their effect.
		/// Applies to things like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.MoltenEgg" />.
		/// </summary>
		NoHookUpgrades = 4,
		/// <summary>
		/// Indicates that no modify hooks should be run.
		/// This is used when a modify hook itself generates a card, to prevent infinite looping. For example,
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Relics.LastingCandy" /> uses this when generating new rewards so that it itself doesn't apply to the reward
		/// it generates.
		/// </summary>
		NoModifyHooks = 8,
		/// <summary>
		/// Indicates that the card pool passed to the reward generation should not be modified.
		/// Relics like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.PrismaticGem" /> can modify the reward pool passed into the reward generation. However,
		/// relics like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.LastingCandy" /> generate a card from a pool of only powers, which should not be modified
		/// by hooks.
		/// </summary>
		NoCardPoolModifications = 0x10,
		/// <summary>
		/// Indicates that the cards passed to the reward generation should not be modified.
		/// FTUE can manually set the cards that are offered to the player. <see cref="T:MegaCrit.Sts2.Core.Models.Relics.SilverCrucible" /> should be allowed
		/// to upgraded these cards (the player can get it if they're playing their first run in multiplayer), but Prismatic
		/// Shard should not be allowed to change the cards.
		/// </summary>
		NoCardModelModifications = 0x20,
		/// <summary>
		/// Indicates that the odds of rolling rare cards should be modified and that we should use the modified odds, even
		/// if this is not an encounter roll.
		/// </summary>
		ForceRarityOddsChange = 0x40,
		/// <summary>
		/// Indicates that the cards created other specifically for a card reward. It is explicitly added in  <see cref="T:MegaCrit.Sts2.Core.Rewards.CardReward" />.
		/// Important for relics like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.PrismaticGem" /> or <see cref="T:MegaCrit.Sts2.Core.Models.Relics.DingyRug" /> that only affect card rewards.
		/// </summary>
		IsCardReward = 0x80,
		/// <summary>
		/// Indicates that the cards created are specifically for a card reward from a combat.
		/// Important for relics like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.LastingCandy" /> that should only apply to combat card rewards.
		/// </summary>
		IsFromCombat = 0x100,
		/// <summary>
		/// Indicates that no upgrades should be applied to the generated card at all.
		/// </summary>
		NoUpgrades = NoUpgradeRoll | NoHookUpgrades,
		/// <summary>
		/// Specifies that the pool and cards generated may not be modified.
		/// </summary>
		NoModifications = -1
	}
	/// <summary>
	/// Options passed when creating cards for rewards.
	/// Various combinations of these options will do different things, so read carefully when you are using this for a
	/// new circumstance.
	/// </summary>
	public record CardCreationOptions
	{
		/// <summary>
		/// The card pools from which rewards will be pulled.
		/// </summary>
		public IReadOnlyCollection<CardPoolModel> CardPools => _cardPools;

		/// <summary>
		/// The filter to apply to the card pool when generating rewards.
		/// We use this instead of a custom card pool because it allows effects that modify the available card pools (like
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Relics.PrismaticGem" />) to properly apply the same filter.
		/// WARNING: This cannot be serialized, so don't use this when adding extra rewards to combat rewards.
		/// </summary>
		public Func<CardModel, bool>? CardPoolFilter { get; private set; }

		/// <summary>
		/// The source from which this reward is being generated from.
		/// Used to indicate to modification hooks whether they should apply to this reward or not. For example, some relics
		/// specify that they only apply to encounter rewards, and not to rewards from events or shops.
		/// </summary>
		public CardCreationSource Source { get; private set; }

		/// <summary>
		/// The odds to use when generating the rarity of the cards in the reward.
		/// Hooks should look at the source to determine where the cards come from, not this.
		/// </summary>
		public CardRarityOddsType RarityOdds { get; private set; }

		/// <summary>
		/// Restrictions applied when determining what can modify the generated rewards.
		/// </summary>
		public CardCreationFlags Flags { get; private set; }

		/// <summary>
		/// If set, we use this override over the default one in the factory
		/// Used in the Crystal Sphere Items so that we can pass the event rng to be used and not hit state divergences in multiplayer
		/// since we don't sync the player rng sets in that case
		/// </summary>
		public Rng? RngOverride { get; private set; }

		private readonly List<CardPoolModel> _cardPools = new List<CardPoolModel>();

		/// <summary>
		/// Constructor which takes a card pool model.
		/// </summary>
		/// <param name="cardPools">The card pools from which rewards will be generated.</param>
		/// <param name="source">The purpose for which the rewards are being generated.</param>
		/// <param name="rarityOdds">The odds to apply when rolling card rarities.</param>
		/// <param name="cardPoolFilter">A filter to apply to the card pool when generating rewards.</param>
		public CardCreationOptions(IEnumerable<CardPoolModel> cardPools, CardCreationSource source, CardRarityOddsType rarityOdds, Func<CardModel, bool>? cardPoolFilter = null)
		{
			_cardPools.AddRange(cardPools);
			Source = source;
			RarityOdds = rarityOdds;
			CardPoolFilter = cardPoolFilter;
		}

		/// <summary>
		/// Creates a default instance of CardCreationOptions for use in generating end-of-combat rewards or shop rewards for
		/// the given room type.
		/// Do not use this in events or relics.
		/// </summary>
		public static CardCreationOptions ForRoom(Player player, RoomType roomType)
		{
			CardCreationSource cardCreationSource;
			switch (roomType)
			{
			case RoomType.Monster:
			case RoomType.Elite:
			case RoomType.Boss:
				cardCreationSource = CardCreationSource.Encounter;
				break;
			case RoomType.Shop:
				cardCreationSource = CardCreationSource.Shop;
				break;
			case RoomType.Event:
				throw new InvalidOperationException("ForRoom should not be used in event rooms");
			default:
				cardCreationSource = CardCreationSource.Other;
				break;
			}
			CardCreationSource source = cardCreationSource;
			return new CardCreationOptions(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(player.Character.CardPool), source, roomType switch
			{
				RoomType.Monster => CardRarityOddsType.RegularEncounter, 
				RoomType.Elite => CardRarityOddsType.EliteEncounter, 
				RoomType.Boss => CardRarityOddsType.BossEncounter, 
				RoomType.Shop => CardRarityOddsType.Shop, 
				_ => CardRarityOddsType.RegularEncounter, 
			});
		}

		/// <summary>
		/// Generates an instance of CardCreationOptions which can be used when generating rewards for events or relics.
		/// This uses CardRarityOddsType.RegularEncounter to generate card rarities, meaning that common cards will be far
		/// more likely to show up than rare ones.
		/// </summary>
		public static CardCreationOptions ForNonCombatWithDefaultOdds(IEnumerable<CardPoolModel> cardPools, Func<CardModel, bool>? cardPoolFilter = null)
		{
			return new CardCreationOptions(cardPools, CardCreationSource.Other, CardRarityOddsType.RegularEncounter, cardPoolFilter).WithFlags(CardCreationFlags.NoUpgradeRoll);
		}

		/// <summary>
		/// Generates an instance of CardCreationOptions which can be used when generating rewards for events or relics.
		/// This uses CardRarityOddsType.Uniform to generate card rarities, meaning that all cards in the pool will have an
		/// even chance of being rolled.
		/// </summary>
		public static CardCreationOptions ForNonCombatWithUniformOdds(IEnumerable<CardPoolModel> cardPools, Func<CardModel, bool>? cardPoolFilter = null)
		{
			return new CardCreationOptions(cardPools, CardCreationSource.Other, CardRarityOddsType.Uniform, cardPoolFilter).WithFlags(CardCreationFlags.NoUpgradeRoll);
		}

		/// <summary>
		/// Get all the cards that could be created for the specified player based on this set of options.
		/// </summary>
		public IEnumerable<CardModel> GetPossibleCards(Player player)
		{
			return from c in CardPools.SelectMany((CardPoolModel p) => p.GetUnlockedCards(player.UnlockState, player.RunState.CardMultiplayerConstraint))
				where CardPoolFilter == null || CardPoolFilter(c)
				select c;
		}

		/// <summary>
		/// Sets the card pool on this instance of CardCreationOptions.
		/// </summary>
		public CardCreationOptions WithCardPools(IEnumerable<CardPoolModel> pools)
		{
			List<CardPoolModel> collection = pools.ToList();
			_cardPools.Clear();
			_cardPools.AddRange(collection);
			return this;
		}

		/// <summary>
		/// Sets the card pool filter on this instance of CardCreationOptions.
		/// </summary>
		public CardCreationOptions WithFilter(Func<CardModel, bool> filter)
		{
			CardPoolFilter = filter;
			return this;
		}

		/// <summary>
		/// Sets flags on this instance of CardCreationOptions.
		/// </summary>
		public CardCreationOptions WithFlags(CardCreationFlags flag)
		{
			Flags |= flag;
			return this;
		}

		/// <summary>
		/// Sets the rarity odds on this instance of CardCreationOptions.
		/// </summary>
		public CardCreationOptions WithRarityOdds(CardRarityOddsType rarityOdds)
		{
			RarityOdds = rarityOdds;
			return this;
		}

		public CardCreationOptions WithRngOverride(Rng rng)
		{
			RngOverride = rng;
			return this;
		}

		public CardRarity? TryGetSingleRarityInPool()
		{
			List<CardModel> source = CardPools.SelectMany((CardPoolModel c) => c.AllCards).ToList();
			if (CardPoolFilter != null)
			{
				source = source.Where((CardModel c) => CardPoolFilter(c)).ToList();
			}
			CardModel first = source.FirstOrDefault();
			if (first != null && source.All((CardModel c) => c.Rarity == first.Rarity))
			{
				return first.Rarity;
			}
			return null;
		}

		[CompilerGenerated]
		public override int GetHashCode()
		{
			return (((((EqualityComparer<Type>.Default.GetHashCode(EqualityContract) * -1521134295 + EqualityComparer<List<CardPoolModel>>.Default.GetHashCode(_cardPools)) * -1521134295 + EqualityComparer<Func<CardModel, bool>>.Default.GetHashCode(CardPoolFilter)) * -1521134295 + EqualityComparer<CardCreationSource>.Default.GetHashCode(Source)) * -1521134295 + EqualityComparer<CardRarityOddsType>.Default.GetHashCode(RarityOdds)) * -1521134295 + EqualityComparer<CardCreationFlags>.Default.GetHashCode(Flags)) * -1521134295 + EqualityComparer<Rng>.Default.GetHashCode(RngOverride);
		}

