	public static class RunHistoryUtilities
	{
		public static void CreateRunHistoryEntry(SerializableRun run, bool victory, bool isAbandoned, PlatformType platformType)
		{
			ModelId killedByEncounter = ModelId.none;
			ModelId killedByEvent = ModelId.none;
			MapPointHistoryEntry mapPointHistoryEntry = run.MapPointHistory.LastOrDefault()?.LastOrDefault();
			if (!victory && mapPointHistoryEntry != null)
			{
				MapPointRoomHistoryEntry mapPointRoomHistoryEntry = mapPointHistoryEntry.Rooms.Last();
				RoomType roomType = mapPointRoomHistoryEntry.RoomType;
				if (roomType.IsCombatRoom())
				{
					killedByEncounter = mapPointRoomHistoryEntry.ModelId;
				}
				else if (roomType == RoomType.Event)
				{
					killedByEvent = mapPointRoomHistoryEntry.ModelId;
				}
			}
			List<RunHistoryPlayer> list = new List<RunHistoryPlayer>();
			foreach (SerializablePlayer player in run.Players)
			{
				RunHistoryPlayer item = new RunHistoryPlayer
				{
					Id = player.NetId,
					Character = player.CharacterId,
					Deck = player.Deck,
					Relics = player.Relics,
					Potions = player.Potions,
					Badges = GetBadgesForPlayer(run, player, victory, isAbandoned),
					MaxPotionSlotCount = player.MaxPotionSlotCount
				};
				list.Add(item);
			}
			RunHistory history = new RunHistory
			{
				BuildId = (ReleaseInfoManager.Instance.ReleaseInfo?.Version ?? "NON-RELEASE-VERSION"),
				PlatformType = platformType,
				Players = list,
				GameMode = GetGameMode(run),
				Win = victory,
				KilledByEncounter = killedByEncounter,
				KilledByEvent = killedByEvent,
				WasAbandoned = isAbandoned,
				Seed = run.SerializableRng.Seed,
				StartTime = run.StartTime,
				RunTime = ((run.WinTime > 0) ? run.WinTime : run.RunTime),
				MapPointHistory = run.MapPointHistory,
				Ascension = run.Ascension,
				Acts = run.Acts.Select((SerializableActModel a) => a.Id).ToList(),
				Modifiers = run.Modifiers
			};
			SaveManager.Instance.SaveRunHistory(history);
			Log.Info("Created Run History entry!");
			if (RunManager.Instance.IsInProgress)
			{
				RunManager.Instance.History = history;
			}
		}

		private static IEnumerable<SerializableBadge> GetBadgesForPlayer(SerializableRun run, SerializablePlayer player, bool won, bool isAbandoned)
		{
			List<SerializableBadge> list = new List<SerializableBadge>();
			if (isAbandoned)
			{
				return list;
			}
			List<Badge> badges = ScoreUtility.GetBadges(run, player.NetId, won);
			foreach (Badge item in badges)
			{
				list.Add(item.ToSerializable());
			}
			return list;
		}

		private static GameMode GetGameMode(SerializableRun run)
		{
			return run.GameMode;
		}
	}
	/// <summary>
	/// Uniquely identifies a location within a run for RunLocationTargetedMessageBuffer.
	/// This location takes into account which room the player is in, which is important for multi-room locations, like
	/// those that happen in combat events.
	/// Make sure you look at <see cref="T:MegaCrit.Sts2.Core.Runs.MapLocation" /> as well, which identifies locations on the map without considering
	/// the room.
	/// </summary>
	public struct RunLocation : IEquatable<RunLocation>, IComparable<RunLocation>, IPacketSerializable
	{
		/// <summary>
		/// The act and map coordinate that the location is at.
		/// </summary>
		public MapLocation mapLocation;

		/// <summary>
		/// The room index that this location is in.
		/// Zero is the root room. Any room other than zero is a sub-room, entered using RunManager.EnterRoomWithoutExitingCurrentRoom.
		/// </summary>
		public int? roomId;

		public RunLocation(MapLocation mapLocation, int? roomId)
		{
			this.mapLocation = mapLocation;
			this.roomId = roomId;
		}

		public RunLocation(int actIndex, MapCoord? coord, int? roomId)
		{
			mapLocation = new MapLocation(coord, actIndex);
			this.roomId = roomId;
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteBool(roomId.HasValue);
			if (roomId.HasValue)
			{
				writer.WriteInt(roomId.Value, 4);
			}
			writer.Write(mapLocation);
		}

		public void Deserialize(PacketReader reader)
		{
			if (reader.ReadBool())
			{
				roomId = reader.ReadInt(4);
			}
			mapLocation = reader.Read<MapLocation>();
		}

		public static bool operator ==(RunLocation first, RunLocation second)
		{
			return first.Equals(second);
		}

		public static bool operator !=(RunLocation first, RunLocation second)
		{
			return !(first == second);
		}

		public bool Equals(RunLocation other)
		{
			if (roomId == other.roomId)
			{
				return mapLocation == other.mapLocation;
			}
			return false;
		}

		public override bool Equals(object? obj)
		{
			if (obj is RunLocation other)
			{
				return Equals(other);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (roomId, mapLocation.actIndex, mapLocation.coord?.col, mapLocation.coord?.row).GetHashCode();
		}

		public int CompareTo(RunLocation other)
		{
			if (mapLocation != other.mapLocation)
			{
				return mapLocation.CompareTo(other.mapLocation);
			}
			return Comparer<int?>.Default.Compare(roomId, other.roomId);
		}

		public override string ToString()
		{
			return $"{mapLocation} room {roomId}";
		}
	}
	public class RunManager : IRunLobbyListener
	{
		private long _startTime;

		/// <summary>
		/// previous session's run time before reload
		/// </summary>
		private long _prevSessionRunTime;

		/// <summary>
		/// Accumulated run time not spent in the pause menu
		/// </summary>
		private long _activeRunTime;

		/// <summary>
		/// When the current active run time began
		/// Which is either the start of the session OR the time from when you last closed the pause menu
		/// </summary>
		private long _startOfCurrentActiveRunTime;

		private bool _isPaused;

		private bool _runHistoryWasUploaded;

		private int _numReloads;

		public Action? debugAfterCombatRewardsOverride;

		public static RunManager Instance { get; } = new RunManager();

		/// <summary>
		/// The ascension manager for this run.
		/// </summary>
		public AscensionManager AscensionManager { get; private set; }

		/// <summary>
		/// Whether or not this run should be saved.
		/// This will always be true for normal players.
		/// For developers, it will be true when starting/continuing a run from the main menu, but false when starting
		/// from SceneBootstrapper or from tests.
		/// </summary>
		public bool ShouldSave { get; private set; }

		/// <summary>
		/// If set to true, the final run score will be uploaded to the daily run leaderboard for today.
		/// </summary>
		public DateTimeOffset? DailyTime { get; private set; }

		/// <summary>
		/// Is there currently a run in progress?
		/// True when in a run, false when on the main menu or submenus.
		/// You shouldn't usually have to check this, because most run-dependent things are only executed within the
		/// context of a run, but this is a good escape valve if you need it.
		/// </summary>
		public bool IsInProgress => State != null;

		/// <summary>
		/// Is the run currently being cleaned up? Only true in the brief period of time after the player hits Save and Quit
		/// or abandon and IsInProgress is still true.
		/// IsInProgress maybe should also check this, but I'm scared because we're about to launch.
		/// </summary>
		public bool IsCleaningUp { get; private set; }

		/// <summary>
		/// Discovery order modifications (e.g. boss order or enemy order) is usually disabled in multiplayer and tests.
		/// Set this to true to force them to be applied.
		/// </summary>
		public bool ForceDiscoveryOrderModifications { get; set; }

		public bool IsGameOver
		{
			get
			{
				if (IsInProgress)
				{
					return State.IsGameOver;
				}
				return false;
			}
		}

		public bool IsAbandoned { get; private set; }

		public bool IsPaused
		{
			get
			{
				return _isPaused;
			}
			set
			{
				_isPaused = value;
				RunState state = State;
				if (state == null)
				{
					return;
				}
				IReadOnlyList<Player> players = state.Players;
				if (players != null && players.Count == 1)
				{
					if (_isPaused)
					{
						_activeRunTime += DateTimeOffset.UtcNow.ToUnixTimeSeconds() - _startOfCurrentActiveRunTime;
					}
					else
					{
						_startOfCurrentActiveRunTime = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
					}
				}
			}
		}

		public RunHistory? History { get; set; }

		public INetGameService NetService { get; private set; }

		public ChecksumTracker ChecksumTracker { get; private set; }

		public RunLocationTargetedMessageBuffer RunLocationTargetedBuffer { get; private set; }

		public CombatReplayWriter CombatReplayWriter { get; private set; }

		public RunLobby? RunLobby { get; private set; }

		public CombatStateSynchronizer CombatStateSynchronizer { get; private set; }

		public MapSelectionSynchronizer MapSelectionSynchronizer { get; private set; }

		public ActChangeSynchronizer ActChangeSynchronizer { get; private set; }

		public PlayerChoiceSynchronizer PlayerChoiceSynchronizer { get; private set; }

		public EventSynchronizer EventSynchronizer { get; private set; }

		public RewardSynchronizer RewardSynchronizer { get; private set; }

		public RewardsSetSynchronizer RewardsSetSynchronizer { get; private set; }

		public RestSiteSynchronizer RestSiteSynchronizer { get; private set; }

		public OneOffSynchronizer OneOffSynchronizer { get; private set; }

		public TreasureRoomRelicSynchronizer TreasureRoomRelicSynchronizer { get; private set; }

		public FlavorSynchronizer FlavorSynchronizer { get; private set; }

		public PeerInputSynchronizer InputSynchronizer { get; private set; }

		public HoveredModelTracker HoveredModelTracker { get; private set; }

		public ActionQueueSet ActionQueueSet { get; private set; }

		public ActionExecutor ActionExecutor { get; private set; }

		public ActionQueueSynchronizer ActionQueueSynchronizer { get; private set; }

		/// <summary>
		/// The run time when you beat the Act 3 boss.
		/// </summary>
		public long WinTime { get; set; }

		/// <summary>
		/// The total play time of the current run. If the run has been won, will use the WinTime instead.
		/// </summary>
		public long RunTime
		{
			get
			{
				if (WinTime > 0)
				{
					return WinTime;
				}
				if (IsPaused)
				{
					RunState state = State;
					if (state != null)
					{
						IReadOnlyList<Player> players = state.Players;
						if (players != null && players.Count == 1)
						{
							return _activeRunTime + _prevSessionRunTime;
						}
					}
				}
				return DateTimeOffset.UtcNow.ToUnixTimeSeconds() - _startOfCurrentActiveRunTime + _activeRunTime + _prevSessionRunTime;
			}
		}

		/// <summary>
		/// This flag returns true if we are in a singleplayer session or we are faking a multiplayer session.
		/// Sometimes, for testing, we add dummy players through the bootstrapper. In those cases, we still want end turn
		/// and other functions not to wait for multiple players, because there's only one acting player.
		/// </summary>
		public bool IsSingleplayerOrFakeMultiplayer
		{
			get
			{
				if (IsInProgress)
				{
					return NetService.Type == NetGameType.Singleplayer;
				}
				return false;
			}
		}

		public SerializableMapDrawings? MapDrawingsToLoad { get; set; }

		/// <summary>
		/// Saved maps from a loaded run, indexed by act index.
