namespace MegaCrit.Sts2.Core.Runs.History
{
	/// <summary>
	/// Ancient choice logs are used exclusively to to make Ancient Metrics to send to our metrics site. This makes them a
	/// bit more flexible to use than the MapPointHistoryEntry.EventChoices which are required to be LocStrings.
	/// </summary>
	[Serializable]
	public class AncientChoiceHistoryEntry : IPacketSerializable
	{
		[JsonPropertyName("title")]
		public LocString Title { get; set; }

		[JsonPropertyName("was_chosen")]
		public bool WasChosen { get; set; }

		[JsonPropertyName("TextKey")]
		public string TextKey => Title.LocEntryKey.Split(".")[^2];

		/// <summary>
		/// For serialization only
		/// </summary>
		public AncientChoiceHistoryEntry()
		{
			Title = new LocString(string.Empty, string.Empty);
		}

		public AncientChoiceHistoryEntry(LocString title, bool wasChosen)
		{
			Title = title;
			WasChosen = wasChosen;
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(Title.LocTable);
			writer.WriteString(Title.LocEntryKey);
			writer.WriteBool(WasChosen);
		}

		public void Deserialize(PacketReader reader)
		{
			string locTable = reader.ReadString();
			string locEntryKey = reader.ReadString();
			Title = new LocString(locTable, locEntryKey);
			WasChosen = reader.ReadBool();
		}
	}
	[Serializable]
	public struct CardChoiceHistoryEntry
	{
		[JsonPropertyName("was_picked")]
		public bool wasPicked;

		[JsonPropertyName("card")]
		public SerializableCard Card { get; set; }

		public CardChoiceHistoryEntry(CardModel card, bool wasPicked)
		{
			Card = card.ToSerializable();
			this.wasPicked = wasPicked;
		}

		public void Serialize<T>(PacketWriter writer) where T : AbstractModel
		{
			writer.Write(Card);
			writer.WriteBool(wasPicked);
		}

		public void Deserialize<T>(PacketReader reader) where T : AbstractModel
		{
			Card = reader.Read<SerializableCard>();
			wasPicked = reader.ReadBool();
		}
	}
	public struct CardEnchantmentHistoryEntry(CardModel card, ModelId enchantment) : IPacketSerializable
	{
		[JsonPropertyName("card")]
		public SerializableCard Card { get; set; } = card.ToSerializable();

		[JsonPropertyName("enchantment")]
		public ModelId Enchantment { get; set; } = enchantment;

		public void Serialize(PacketWriter writer)
		{
			writer.Write(Card);
			writer.WriteModelEntry(Enchantment);
		}

		public void Deserialize(PacketReader reader)
		{
			Card = reader.Read<SerializableCard>();
			Enchantment = reader.ReadModelIdAssumingType<EnchantmentModel>();
		}
	}
	public struct CardTransformationHistoryEntry(CardModel originalCard, CardModel finalCard) : IPacketSerializable
	{
		[JsonPropertyName("original_card")]
		public SerializableCard OriginalCard { get; set; } = originalCard.ToSerializable();

		[JsonPropertyName("final_card")]
		public SerializableCard FinalCard { get; set; } = finalCard.ToSerializable();

		public void Serialize(PacketWriter writer)
		{
			writer.Write(OriginalCard);
			writer.Write(FinalCard);
		}

		public void Deserialize(PacketReader reader)
		{
			OriginalCard = reader.Read<SerializableCard>();
			FinalCard = reader.Read<SerializableCard>();
		}
	}
	public struct EventOptionHistoryEntry : IPacketSerializable
	{
		[JsonPropertyName("title")]
		public LocString Title { get; set; }

		[JsonInclude]
		[JsonPropertyName("variables")]
		[JsonConverter(typeof(LocStringVariablesJsonConverter))]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public System.Collections.Generic.Dictionary<string, object>? Variables { get; set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(Title.LocTable);
			writer.WriteString(Title.LocEntryKey);
			writer.WriteBool(Variables != null);
			if (Variables == null)
			{
				return;
			}
			List<(string, SerializableDynamicVar)> list = new List<(string, SerializableDynamicVar)>();
			foreach (KeyValuePair<string, object> variable in Variables)
			{
				SerializableDynamicVar? serializableDynamicVar = SerializableDynamicVar.FromDynamicVar(variable.Value);
				if (serializableDynamicVar.HasValue)
				{
					list.Add((variable.Key, serializableDynamicVar.Value));
				}
			}
			writer.WriteInt(list.Count);
			foreach (var (str, val) in list)
			{
				writer.WriteString(str);
				writer.Write(val);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			string locTable = reader.ReadString();
			string locEntryKey = reader.ReadString();
			Title = new LocString(locTable, locEntryKey);
			if (reader.ReadBool())
			{
				Variables = new System.Collections.Generic.Dictionary<string, object>();
				int num = reader.ReadInt();
				for (int i = 0; i < num; i++)
				{
					string text = reader.ReadString();
					Variables[text] = reader.Read<SerializableDynamicVar>().ToDynamicVar(text);
				}
			}
		}
	}
	public class MapPointHistoryEntry : IPacketSerializable
	{
		[JsonPropertyName("map_point_type")]
		public MapPointType MapPointType { get; set; }

		/// <summary>
		/// All the rooms entered in this map point. Usually contains just 1, but can contain more when one type of
		/// room transitions into another (like when the Dense Vegetation event transitions into the Wrigglers combat).
		/// Accessing index 0 will usually give you what you want, but keep an eye out for cases where you may care
		/// about other rooms entered in the same map point.
		/// </summary>
		[JsonPropertyName("rooms")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<MapPointRoomHistoryEntry> Rooms { get; set; } = new List<MapPointRoomHistoryEntry>();

		[JsonPropertyName("player_stats")]
		public List<PlayerMapPointHistoryEntry> PlayerStats { get; set; } = new List<PlayerMapPointHistoryEntry>();

		public MapPointHistoryEntry()
		{
		}

		public MapPointHistoryEntry(MapPointType mapPointType, IPlayerCollection playerCollection)
		{
			MapPointType = mapPointType;
			foreach (Player player in playerCollection.Players)
			{
				PlayerStats.Add(new PlayerMapPointHistoryEntry
				{
					PlayerId = player.NetId
				});
			}
		}

		public PlayerMapPointHistoryEntry GetEntry(ulong playerId)
		{
			PlayerMapPointHistoryEntry playerMapPointHistoryEntry = PlayerStats.FirstOrDefault((PlayerMapPointHistoryEntry e) => e.PlayerId == playerId);
			if (playerMapPointHistoryEntry == null)
			{
				throw new InvalidOperationException($"Player with ID {playerId} not found in player stats for this run history! We have {string.Join(",", PlayerStats.Select((PlayerMapPointHistoryEntry p) => p.PlayerId))}");
			}
			return playerMapPointHistoryEntry;
		}

		public bool HasRoomOfType(RoomType roomType)
		{
			foreach (MapPointRoomHistoryEntry room in Rooms)
			{
				if (room.RoomType == roomType)
				{
					return true;
				}
			}
			return false;
		}

		public IEnumerable<MapPointRoomHistoryEntry> GetRoomsOfType(RoomType roomType)
		{
			foreach (MapPointRoomHistoryEntry room in Rooms)
			{
				if (room.RoomType == roomType)
				{
					yield return room;
				}
			}
		}

		public MapPointRoomHistoryEntry? FirstRoomOfType(RoomType roomType)
		{
			foreach (MapPointRoomHistoryEntry room in Rooms)
			{
				if (room.RoomType == roomType)
				{
					return room;
				}
			}
			return null;
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteEnum(MapPointType);
			writer.WriteList(Rooms);
			writer.WriteList(PlayerStats);
		}

		public void Deserialize(PacketReader reader)
		{
			MapPointType = reader.ReadEnum<MapPointType>();
			Rooms = reader.ReadList<MapPointRoomHistoryEntry>();
			PlayerStats = reader.ReadList<PlayerMapPointHistoryEntry>();
		}

		public MapPointHistoryEntry Anonymized()
		{
			return new MapPointHistoryEntry
			{
				MapPointType = MapPointType,
				Rooms = Rooms,
				PlayerStats = PlayerStats.Select((PlayerMapPointHistoryEntry p) => p.Anonymized()).ToList()
			};
		}
	}
	/// <summary>
	/// Represents a room in a map point.
	/// Since each map point can contain multiple rooms (e.g. <see cref="T:MegaCrit.Sts2.Core.Models.Events.DenseVegetation" />'s
	/// <see cref="T:MegaCrit.Sts2.Core.Models.Encounters.DenseVegetationEventEncounter" />), we need multiple of these per map point.
	/// </summary>
	public class MapPointRoomHistoryEntry : IPacketSerializable
	{
		/// <summary>
		/// The type of room this is. Tells us what type of model ModelId refers to.
		/// </summary>
		[JsonPropertyName("room_type")]
		public RoomType RoomType { get; set; }

		/// <summary>
		/// The model id of the encounter or event at each room in this map point. ie CEREMONIAL_BEAST
		/// </summary>
		[JsonPropertyName("model_id")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotTypeDefault)]
		public ModelId? ModelId { get; set; }

		/// <summary>
		/// The model IDs of the monsters in the encounter, if this was an encounter.
		/// This contains the actual monsters that the encounter resolved to, if the encounter has random monsters.
		/// </summary>
		[JsonPropertyName("monster_ids")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<ModelId> MonsterIds { get; set; } = new List<ModelId>();

		[JsonPropertyName("turns_taken")]
		public int TurnsTaken { get; set; }

		public void Serialize(PacketWriter writer)
		{
			writer.WriteEnum(RoomType);
			writer.WriteBool(ModelId != null);
			if (ModelId != null)
			{
				writer.WriteFullModelId(ModelId);
			}
			writer.WriteModelEntriesInList(MonsterIds);
			writer.WriteInt(TurnsTaken);
		}

		public void Deserialize(PacketReader reader)
		{
			RoomType = reader.ReadEnum<RoomType>();
			if (reader.ReadBool())
			{
				ModelId = reader.ReadFullModelId();
			}
			MonsterIds = reader.ReadModelIdListAssumingType<MonsterModel>();
			TurnsTaken = reader.ReadInt();
		}
	}
	[Serializable]
	public struct ModelChoiceHistoryEntry(ModelId choice, bool wasPicked)
	{
		[JsonPropertyName("choice")]
		public ModelId choice = choice;

		[JsonPropertyName("was_picked")]
		public bool wasPicked = wasPicked;

		public void Serialize<T>(PacketWriter writer) where T : AbstractModel
		{
			writer.WriteModelEntry(choice);
			writer.WriteBool(wasPicked);
		}

		public void Deserialize<T>(PacketReader reader) where T : AbstractModel
		{
			choice = reader.ReadModelIdAssumingType<T>();
			wasPicked = reader.ReadBool();
		}
	}
}
namespace MegaCrit.Sts2.Core.Rooms
{
	public abstract class AbstractRoom
	{
		public abstract RoomType RoomType { get; }

		/// <summary>
		/// The model ID associated with this room. Non-null for combat rooms and event rooms.
		/// </summary>
		public abstract ModelId? ModelId { get; }

		/// <summary>
		/// Whether or not this room should load in as already finished.
		/// Used by the save/load system when the player saves after finishing a room, but before choosing a new map
		/// location to visit.
		/// </summary>
		public virtual bool IsPreFinished => false;

		/// <summary>
		/// The ID of the room within the current map coordinate.
		/// This id is only unique within each map coordinate. You usually shouldn't have to use this directly; look at
		/// <see cref="P:MegaCrit.Sts2.Core.Runs.IRunState.RunLocation" /> instead.
		/// This is not stable across save/load.
		/// </summary>
		public int? Id { get; private set; }

		/// <summary>
		/// Is this the "Victory" room where the player meets the Architect and the run ends?
		/// </summary>
		public bool IsVictoryRoom
		{
			get
			{
				if (this is EventRoom eventRoom)
				{
					return eventRoom.CanonicalEvent is TheArchitect;
				}
				return false;
			}
		}

		/// <summary>
		/// Called when this room is being entered.
		/// </summary>
		/// <param name="runState">The state of the run that this room is being entered in.</param>
		/// <param name="isRestoringRoomStackBase">
		/// If true, skip hooks and room visit tracking. Used when reconstructing the base of the room stack on load
		/// (e.g., pushing a parent EventRoom underneath a pre-finished CombatRoom).
		/// </param>
		public Task Enter(IRunState? runState, bool isRestoringRoomStackBase)
		{
			Id = runState?.GetAndIncrementNextRoomId();
			return EnterInternal(runState, isRestoringRoomStackBase);
		}

		/// <summary>
		/// Override this in implementors.
		/// </summary>
		/// <param name="runState">The state of the run that this room is being entered in.</param>
		/// <param name="isRestoringRoomStackBase">
		/// If true, skip hooks and room visit tracking. Used when reconstructing the base of the room stack on load
		/// (e.g., pushing a parent EventRoom underneath a pre-finished CombatRoom).
		/// </param>
		public abstract Task EnterInternal(IRunState? runState, bool isRestoringRoomStackBase);

		/// <summary>
		/// Called when this room is being exited.
		/// </summary>
		/// <param name="runState">The state of the run that this room is being exited in.</param>
		public abstract Task Exit(IRunState? runState);

		/// <summary>
		/// Called when another room is popped off the room stack, causing this to become the current room again.
		/// </summary>
		/// <param name="exitedRoom">The room that was exited before this was called.</param>
		/// <param name="runState">The state of the run that this room is being resumed in.</param>
		public abstract Task Resume(AbstractRoom exitedRoom, IRunState? runState);

		public virtual SerializableRoom ToSerializable()
		{
			return new SerializableRoom
			{
				RoomType = RoomType
			};
		}

		public static AbstractRoom? FromSerializable(SerializableRoom? serializableRoom, IRunState? runState)
		{
			if (serializableRoom == null)
			{
				return null;
			}
			switch (serializableRoom.RoomType)
			{
			case RoomType.Monster:
			case RoomType.Elite:
			case RoomType.Boss:
				return CombatRoom.FromSerializable(serializableRoom, runState);
			case RoomType.Event:
				return new EventRoom(serializableRoom);
			default:
				throw new ArgumentOutOfRangeException();
			}
		}
	}
	public class BackgroundAssets
	{
		public string BackgroundScenePath { get; }

		public List<string> BgLayers { get; }

		public string? FgLayer { get; }

		public IEnumerable<string> AssetPaths => from s in new string[2]
			{
				BackgroundScenePath,
				FgLayer ?? string.Empty
			}.Concat(BgLayers)
			where !string.IsNullOrWhiteSpace(s)
			select s;

		/// Creates the combat background for a particular encounter. If this encounter doesn't have a unique background,
		/// automatically pull the one for the act. Otherwise scrub through the the corresponding filepath and set up the
		/// background dynamically.
		/// file structure:
		/// -&gt;scenes/backgrounds/{title}
		/// --&gt; layers
		/// ---&gt; {title}_bg_00_a.tscn
		/// ---&gt; {title}_bg_01_a.tscn
		/// ---&gt; {title}_bg_01_b.tscn
		/// ---&gt; {title}_bg_02_a.tscn
		/// ---&gt; {title}_bg_02_b.tscn
		/// ---&gt; {title}_fg_a.tscn
		/// --&gt; {title}_background.tscn
		///
		/// notes:
		/// - the {title}_background.tscn file helps visually define how the layers are set up
		/// - the layer scenes (in the layer folder) are an asset optimization.
		/// - {title} must be exactly the same as the class name
		/// - layer files that share the same prefix (_bg_##, _fg_) are grouped together, and will be randomly chosen for the combat's background
		/// - you can have as many _bg_ layers as you want.
		/// - _bg_ layers are stacked from least to most
		/// - there is only 1 fg layer currently
		public BackgroundAssets(string title, Rng rng)
		{
			string text = "res://scenes/backgrounds/" + title + "/layers";
			using DirAccess dirAccess = DirAccess.Open(text);
			if (dirAccess == null)
			{
				throw new InvalidOperationException("could not find directory " + text);
			}
			System.Collections.Generic.Dictionary<string, List<string>> dictionary = new System.Collections.Generic.Dictionary<string, List<string>>();
			List<string> list = new List<string>();
			dirAccess.ListDirBegin();
			string next = dirAccess.GetNext();
			while (next != "")
			{
				if (dirAccess.CurrentIsDir())
				{
					throw new InvalidOperationException("there should be no other directories within the layers directory");
				}
				if (next.Contains("_fg_"))
				{
					list.Add(text + "/" + next);
				}
				else
				{
					if (!next.Contains("_bg_"))
					{
						throw new InvalidOperationException("files must either contain '_fg_' or '_bg_'");
					}
					string text2 = next.Split("_bg_")[1];
					string key = text2.Split("_")[0];
					if (!dictionary.ContainsKey(key))
					{
						dictionary.Add(key, new List<string>());
					}
					dictionary[key].Add(text + "/" + next);
				}
				next = dirAccess.GetNext();
			}
			string scenePath = SceneHelper.GetScenePath($"backgrounds/{title}/{title}_background");
			BackgroundScenePath = scenePath;
			BgLayers = SelectRandomBackgroundAssetLayers(rng, dictionary);
			FgLayer = SelectRandomForegroundAssetLayer(rng, list.ToArray());
		}

		private static List<string> SelectRandomBackgroundAssetLayers(Rng rng, System.Collections.Generic.Dictionary<string, List<string>> bgLayers)
		{
			List<string> list = new List<string>();
			foreach (var (_, items) in bgLayers.OrderBy<KeyValuePair<string, List<string>>, string>((KeyValuePair<string, List<string>> kv) => kv.Key))
			{
				string item = rng.NextItem(items);
				list.Add(item);
			}
			return list;
		}

		private static string? SelectRandomForegroundAssetLayer(Rng rng, IEnumerable<string> fgLayer)
		{
			return rng.NextItem(fgLayer);
		}
	}
	/// <summary>
	/// Represents the visuals that should be used for a combat-style event.
	/// </summary>
	public class CombatEventVisuals : ICombatRoomVisuals
	{
		public EncounterModel Encounter { get; }

		public IEnumerable<Creature> Allies { get; }

		public IEnumerable<Creature> Enemies => Encounter.MonstersWithSlots.Select<(MonsterModel, string), Creature>(((MonsterModel, string) m) => m.Item1.Creature);

		public ActModel Act { get; }

		public CombatEventVisuals(EncounterModel encounter, IEnumerable<Player> players, ActModel act)
		{
			Encounter = encounter;
			Allies = players.Select((Player p) => p.Creature);
			Act = act;
		}
	}
	public class CombatRoom : AbstractRoom, ICombatRoomVisuals
	{
		private bool _isPreFinished;

		private readonly System.Collections.Generic.Dictionary<Player, List<Reward>> _extraRewards = new System.Collections.Generic.Dictionary<Player, List<Reward>>();

		public override RoomType RoomType => Encounter.RoomType;

		public override ModelId ModelId => Encounter.Id;

		/// <summary>
		/// The mutable encounter that the player is facing in this room.
		/// </summary>
		public EncounterModel Encounter => CombatState.Encounter;

		/// <summary>
		/// The state of the combat that is currently in progress in this room.
		/// </summary>
		public CombatState CombatState { get; }

		public IEnumerable<Creature> Allies => CombatState.Allies;

		public IEnumerable<Creature> Enemies => CombatState.Enemies;

		public ActModel Act => CombatState.RunState.Act;

		public override bool IsPreFinished => _isPreFinished;

		public float GoldProportion { get; private set; } = 1f;

		public IReadOnlyDictionary<Player, List<Reward>> ExtraRewards => _extraRewards;

		/// <summary>
		/// Whether to create a combat room node for this combat room.
		/// Usually true, but false for "delayed-start" combats, like events with combat-style layouts that can transition
		/// to combats if certain options are selected.
		/// </summary>
		public bool ShouldCreateCombat { get; init; } = true;

		/// <summary>
		/// If this combat room is nested within an event room, should we resume the parent event after combat ends?
		/// Usually true, but false for some combat-style events. In many of these cases, you transition from a visual-only
		/// combat room into a real combat, and then you just proceed to the next map point after combat ends.
		/// </summary>
		public bool ShouldResumeParentEventAfterCombat { get; init; } = true;

		/// <summary>
		/// If this combat room is nested within an event room that should resume after combat,
		/// this stores the parent event's ID so the event room can be recreated on load.
		/// </summary>
		public ModelId? ParentEventId { get; init; }

		/// <summary>
		/// Creates a combat room for the given encounter.
		/// </summary>
		/// <param name="encounter">Encounter that is taking place in this combat room.</param>
		/// <param name="runState">State of the run that this combat room is a part of.</param>
		public CombatRoom(EncounterModel encounter, IRunState? runState)
		{
			encounter.AssertMutable();
			CombatState = new CombatState(encounter, runState, runState?.Modifiers, runState?.BadgeModels, runState?.MultiplayerScalingModel);
		}

		public CombatRoom(CombatState combatState)
		{
			CombatState = combatState;
		}

		public new static CombatRoom FromSerializable(SerializableRoom serializableRoom, IRunState? runState)
		{
			if (serializableRoom.ExtraRewards.Count > 0 && runState == null)
			{
				throw new InvalidOperationException("Cannot load extra rewards without a run state.");
			}
			EncounterModel encounterModel = SaveUtil.EncounterOrDeprecated(serializableRoom.EncounterId).ToMutable();
			encounterModel.LoadCustomState(serializableRoom.EncounterState);
			CombatRoom combatRoom = new CombatRoom(encounterModel, runState)
			{
				GoldProportion = serializableRoom.GoldProportion,
				_isPreFinished = serializableRoom.IsPreFinished,
				ShouldResumeParentEventAfterCombat = serializableRoom.ShouldResumeParentEvent,
				ParentEventId = serializableRoom.ParentEventId
			};
			foreach (var (netId, source) in serializableRoom.ExtraRewards)
			{
				Player player = runState.GetPlayer(netId);
				List<Reward> value = source.Select((SerializableReward sr) => Reward.FromSerializable(sr, player)).ToList();
				combatRoom._extraRewards.Add(player, value);
			}
			if (serializableRoom.IsPreFinished)
			{
				combatRoom.MarkPreFinished();
			}
			return combatRoom;
		}

		public override async Task EnterInternal(IRunState? runState, bool isRestoringRoomStackBase)
		{
			if (isRestoringRoomStackBase)
			{
				throw new InvalidOperationException("CombatRoom does not support room stack reconstruction.");
			}
			if (CombatState.Players.Count == 0)
			{
				foreach (Player item in runState?.Players ?? System.Array.Empty<Player>())
				{
					CombatState.AddPlayer(item);
				}
			}
			if (IsPreFinished)
			{
				await StartPreFinishedCombat();
			}
			else
			{
				await StartCombat(runState);
			}
		}

		public override Task Exit(IRunState? runState)
		{
			CombatManager.Instance.Reset(graceful: true);
			if (IsPreFinished)
			{
				foreach (Creature item in CombatState.PlayerCreatures.ToList())
				{
					CombatState.RemoveCreature(item);
				}
			}
			return Task.CompletedTask;
		}

		public override Task Resume(AbstractRoom _, IRunState? runState)
		{
			throw new NotImplementedException();
		}

		public override SerializableRoom ToSerializable()
		{
			if (ParentEventId != null && !IsPreFinished)
			{
				throw new InvalidOperationException("Cannot serialize a CombatRoom with a ParentEventId that is not pre-finished.");
			}
			SerializableRoom serializableRoom = base.ToSerializable();
			serializableRoom.EncounterId = Encounter.Id;
			serializableRoom.IsPreFinished = IsPreFinished;
			serializableRoom.GoldProportion = GoldProportion;
			serializableRoom.ParentEventId = ParentEventId;
			serializableRoom.ShouldResumeParentEvent = ShouldResumeParentEventAfterCombat;
			serializableRoom.EncounterState = Encounter.SaveCustomState();
			foreach (var (player2, source) in ExtraRewards)
			{
				serializableRoom.ExtraRewards[player2.NetId] = source.Select((Reward r) => r.ToSerializable()).ToList();
			}
			return serializableRoom;
		}

		public void MarkPreFinished()
		{
			_isPreFinished = true;
		}

		public void AddExtraReward(Player player, Reward reward)
		{
			if (!ExtraRewards.ContainsKey(player))
			{
				_extraRewards.Add(player, new List<Reward>());
			}
			ExtraRewards[player].Add(reward);
		}

		private async Task StartCombat(IRunState? runState)
		{
			if (!Encounter.HaveMonstersBeenGenerated)
			{
				Encounter.GenerateMonstersWithSlots(CombatState.RunState);
			}
			if (ShouldCreateCombat)
			{
				await PreloadManager.LoadRoomCombatAssets(Encounter, CombatState.RunState);
			}
			foreach (var (monsterModel, slot) in Encounter.MonstersWithSlots)
			{
				monsterModel.AssertMutable();
				if (ShouldCreateCombat)
				{
					Creature creature = CombatState.CreateCreature(monsterModel, CombatSide.Enemy, slot);
					CombatState.AddCreature(creature);
				}
				CombatState.RunState.CurrentMapPointHistoryEntry?.Rooms.Last().MonsterIds.Add(monsterModel.Id);
			}
			if (ShouldCreateCombat)
			{
				NRun.Instance?.SetCurrentRoom(NCombatRoom.Create(this, CombatRoomMode.ActiveCombat));
			}
			else
			{
				NCombatRoom.Instance?.TransitionToActiveCombat(this);
			}
			CombatManager.Instance.SetUpCombat(CombatState);
			if (runState != null)
			{
				await Hook.AfterRoomEntered(runState, this);
			}
			CombatManager.Instance.AfterCombatRoomLoaded();
		}

		public void OnCombatEnded()
		{
			GoldProportion = Encounter.CalculateGoldProportion(CombatState);
		}

		private async Task StartPreFinishedCombat()
		{
			Encounter.GenerateMonstersWithSlots(CombatState.RunState);
			await PreloadManager.LoadRoomCombatAssets(Encounter, CombatState.RunState);
			NCombatRoom nCombatRoom = NCombatRoom.Create(this, CombatRoomMode.FinishedCombat);
			NRun.Instance?.SetCurrentRoom(nCombatRoom);
			nCombatRoom?.SetUpBackground(CombatState.RunState);
			NMapScreen.Instance?.SetTravelEnabled(enabled: true);
			foreach (Player player in CombatState.RunState.Players)
			{
				player.ResetCombatState();
			}
			RunManager.Instance.ActionExecutor.Unpause();
			if (Encounter.ShouldGiveRewards)
			{
				await OfferRoomEndRewards();
			}
			else if (nCombatRoom != null)
			{
				await nCombatRoom.Ui.ProceedWithoutRewards();
			}
		}

		public async Task OfferRoomEndRewards()
		{
			List<RewardsSet> rewards = new List<RewardsSet>();
			foreach (Player player in CombatState.Players)
			{
				List<RewardsSet> list = rewards;
				list.Add(await RewardsCmd.GenerateForRoomEnd(player, this));
			}
			foreach (RewardsSet reward in rewards)
			{
				await Hook.BeforeCombatRewardOffered(reward, CombatState.RunState, this);
				TaskHelper.RunSafely(reward.Offer());
			}
		}
	}
	/// <summary>
	/// The mode that the combat room is in.
	/// This allows for combat rooms to be used in many different scenarios. See the specific options for details.
	/// </summary>
	public enum CombatRoomMode
	{
		/// <summary>
		/// Full combat - shows all creatures, combat UI, enables interactivity, runs hooks.
		/// </summary>
		ActiveCombat,
		/// <summary>
		/// Finished combat - shows players only, no combat UI, no interactivity, no hooks.
		/// Used when loading a save after combat ended but before leaving the room.
		/// </summary>
		FinishedCombat,
		/// <summary>
		/// Visual only - shows all creatures (allies and enemies) but no combat UI, no interactivity, no hooks.
		/// Used for combat-style events where enemies are visible but not yet fightable.
		/// </summary>
		VisualOnly
	}
	public class EventRoom : AbstractRoom
	{
		private bool _isPreFinished;

		public override RoomType RoomType => RoomType.Event;

		public override ModelId ModelId => CanonicalEvent.Id;

		/// <summary>
		/// The canonical version of the event that the player is doing in this room.
		/// Unlike CombatRoom.Encounter, we want this to be canonical, because we create a separate mutable copy for each
		/// player.
		/// </summary>
		public EventModel CanonicalEvent { get; }

		/// <summary>
		/// The mutable version of the event that the local player is doing in this room.
		/// When using this, keep in mind that the
		/// </summary>
		public EventModel LocalMutableEvent => RunManager.Instance.EventSynchronizer.GetLocalEvent();

		public Action<EventModel>? OnStart { private get; init; }

		public override bool IsPreFinished => _isPreFinished;

		public EventRoom(EventModel eventModel)
		{
			eventModel.AssertCanonical();
			CanonicalEvent = eventModel;
		}

		public EventRoom(SerializableRoom serializableRoom)
		{
			CanonicalEvent = SaveUtil.EventOrDeprecated(serializableRoom.EventId);
			if (serializableRoom.IsPreFinished)
			{
				MarkPreFinished();
			}
		}

		public override async Task EnterInternal(IRunState? runState, bool isRestoringRoomStackBase)
		{
			bool preloadsAfterCombatState = CanonicalEvent.LayoutType == EventLayoutType.Combat;
			if (!preloadsAfterCombatState)
			{
				await PreloadManager.LoadRoomEventAssets(CanonicalEvent, runState ?? NullRunState.Instance);
			}
			RunManager.Instance.EventSynchronizer.BeginEvent(CanonicalEvent, IsPreFinished, OnStart);
			foreach (EventModel @event in RunManager.Instance.EventSynchronizer.Events)
			{
				@event.StateChanged += OnEventStateChanged;
				if (@event.IsFinished && !IsPreFinished)
				{
					OnEventStateChanged(@event);
				}
			}
			EventModel localEvent = RunManager.Instance.EventSynchronizer.GetLocalEvent();
			RunManager.Instance.EventSynchronizer.GenerateInternalCombatStateIfNecessary(localEvent);
			if (preloadsAfterCombatState)
			{
				await PreloadManager.LoadRoomEventAssets(localEvent, runState ?? NullRunState.Instance);
			}
			if (!isRestoringRoomStackBase)
			{
				NEventRoom currentRoom = NEventRoom.Create(localEvent, runState, _isPreFinished);
				NRun.Instance?.SetCurrentRoom(currentRoom);
			}
			if (runState != null)
			{
				await Hook.AfterRoomEntered(runState, this);
			}
			await localEvent.AfterEventStarted();
		}

		public override async Task Exit(IRunState? runState)
		{
			await RunManager.Instance.EventSynchronizer.AwaitPendingOptionTasks();
			EventModel localEvent = RunManager.Instance.EventSynchronizer.GetLocalEvent();
			if (localEvent.IsDeterministic)
			{
				RunManager.Instance.ChecksumTracker.GenerateChecksum($"Exiting event room {localEvent.Id}", null);
			}
			RunManager.Instance.EventSynchronizer.BeforeExitingRoom();
			foreach (EventModel @event in RunManager.Instance.EventSynchronizer.Events)
			{
				@event.StateChanged -= OnEventStateChanged;
				@event.EnsureCleanup();
			}
		}

		public override Task Resume(AbstractRoom exitedRoom, IRunState? runState)
		{
			RunManager.Instance.EventSynchronizer.ResumeEvents(exitedRoom);
			EventModel localEvent = RunManager.Instance.EventSynchronizer.GetLocalEvent();
			NRun.Instance?.SetCurrentRoom(NEventRoom.Create(localEvent, runState, _isPreFinished));
			return Task.CompletedTask;
		}

		public override SerializableRoom ToSerializable()
		{
			SerializableRoom serializableRoom = base.ToSerializable();
			serializableRoom.EventId = CanonicalEvent.Id;
			serializableRoom.IsPreFinished = IsPreFinished;
			return serializableRoom;
		}

		public void MarkPreFinished()
		{
			_isPreFinished = true;
		}

		private void OnEventStateChanged(EventModel eventModel)
		{
			if (!(eventModel is AncientEventModel))
			{
				return;
			}
			foreach (EventModel @event in RunManager.Instance.EventSynchronizer.Events)
			{
				if (!@event.IsFinished)
				{
					return;
				}
			}
			MarkPreFinished();
			TaskHelper.RunSafely(SaveManager.Instance.SaveRun(this));
		}
	}
