	public class CardReward : Reward
	{
		private readonly PlayerChoiceSynchronizer _synchronizer;

		private readonly List<CardCreationResult> _cards = new List<CardCreationResult>();

		/// <summary>
		/// This is true if cards were manually set through the constructor, and Options has an empty card pool. The intent
		/// when this is set to true is that _cards is a static list that should not be re-populated nor changed.
		/// </summary>
		private bool _cardsWereManuallySet;

		private bool _hasBeenRerolled;

		private NCardRewardSelectionScreen? _currentlyShownScreen;

		private static string RareRewardIcon => ImageHelper.GetImagePath("ui/reward_screen/reward_icon_rare.png");

		private static string UncommonRewardIcon => ImageHelper.GetImagePath("ui/reward_screen/reward_icon_uncommon.png");

		private static string RewardIcon => ImageHelper.GetImagePath("ui/reward_screen/reward_icon_card.png");

		protected override RewardType RewardType => RewardType.Card;

		public override int RewardsSetIndex => 5;

		protected override string IconPath
		{
			get
			{
				CardCreationOptions options = Options;
				if ((object)options != null && options.Source == CardCreationSource.Encounter && options.RarityOdds == CardRarityOddsType.BossEncounter)
				{
					return RareRewardIcon;
				}
				if (Options.TryGetSingleRarityInPool().HasValue)
				{
					return _cards[0].Card.Rarity switch
					{
						CardRarity.Rare => RareRewardIcon, 
						CardRarity.Uncommon => UncommonRewardIcon, 
						_ => RewardIcon, 
					};
				}
				return RewardIcon;
			}
		}

		public static IEnumerable<string> AssetPaths => new global::<>z__ReadOnlyArray<string>(new string[3] { RareRewardIcon, UncommonRewardIcon, RewardIcon });

		public override LocString Description => new LocString("gameplay_ui", "COMBAT_REWARD_ADD_CARD");

		public IEnumerable<CardModel> Cards => _cards.Select((CardCreationResult e) => e.Card);

		private int OptionCount { get; }

		private CardCreationOptions Options { get; }

		private CardCreationOptions RerollOptions { get; }

		public bool CanReroll { get; set; }

		public bool CanSkip { get; init; } = true;

		public override bool IsPopulated => _cards.Count > 0;

		public event Action? AfterGenerated;

		/// <summary>
		/// Create a card reward from a specified source, using the current character's card pool and the source's
		/// rarity-rolling logic.
		/// This is the typical way one would generate a card reward for something like the end of combat.
		/// </summary>
		/// <param name="options">Options used to generate the card rewards.</param>
		/// <param name="cardCount">How many choices to offer (usually 3).</param>
		/// <param name="player">The player that this reward is for.</param>
		/// <param name="synchronizer">PlayerChoiceSynchronizer, for injection in tests.</param>
		public CardReward(CardCreationOptions options, int cardCount, Player player, PlayerChoiceSynchronizer? synchronizer = null)
			: base(player)
		{
			OptionCount = cardCount;
			Options = options.WithFlags(CardCreationFlags.IsCardReward);
			RerollOptions = options.WithFlags(CardCreationFlags.IsCardReward);
			_synchronizer = synchronizer ?? RunManager.Instance.PlayerChoiceSynchronizer;
			player.RelicObtained += OnRelicObtained;
		}

		/// <summary>
		/// Create a card reward with specific cards in it. This is for exceptionally rare cases where we want to offer a
		/// very specific set of cards that ignores modification, like during the tutorial run.
		/// Note that <see cref="M:MegaCrit.Sts2.Core.Rewards.CardReward.Populate" /> will do nothing if called after this method.
		/// </summary>
		/// <param name="cardsToOffer">List of cards to offer as rewards.</param>
		/// <param name="source">The source of the reward.</param>
		/// <param name="player">The player that this reward is for.</param>
		/// <param name="rerollOptions">If the options are rerolled with <see cref="T:MegaCrit.Sts2.Core.Models.Relics.Driftwood" />, then these options will
		/// be used to generate a new set of cards.</param>
		/// <param name="synchronizer">PlayerChoiceSynchronizer, for injection in tests.</param>
		public CardReward(IEnumerable<CardModel> cardsToOffer, CardCreationSource source, Player player, CardCreationOptions rerollOptions, PlayerChoiceSynchronizer? synchronizer = null)
			: base(player)
		{
			Options = new CardCreationOptions(System.Array.Empty<CardPoolModel>(), source, CardRarityOddsType.Uniform).WithFlags(CardCreationFlags.NoCardPoolModifications | CardCreationFlags.NoCardModelModifications | CardCreationFlags.IsCardReward);
			RerollOptions = rerollOptions;
			_cardsWereManuallySet = true;
			_cards = cardsToOffer.Select((CardModel c) => new CardCreationResult(c)).ToList();
			OptionCount = _cards.Count;
			_synchronizer = synchronizer ?? RunManager.Instance.PlayerChoiceSynchronizer;
		}

		/// <summary>
		/// Called when the CardReward rolls options for the first time, and may be called again afterward to generate a new
		/// set of the same type of rewards.
		/// </summary>
		public override void Populate()
		{
			CardCreationOptions cardCreationOptions = (_hasBeenRerolled ? RerollOptions : Options);
			if (_cardsWereManuallySet && !_hasBeenRerolled)
			{
				if (Hook.TryModifyCardRewardOptions(base.Player.RunState, base.Player, _cards, cardCreationOptions, out List<AbstractModel> modifiers))
				{
					TaskHelper.RunSafely(Hook.AfterModifyingCardRewardOptions(base.Player.RunState, modifiers));
				}
			}
			else if (_cards.Count <= 0)
			{
				IEnumerable<CardCreationResult> collection = CardFactory.CreateForReward(base.Player, OptionCount, cardCreationOptions);
				_cards.Clear();
				_cards.AddRange(collection);
				IReadOnlyList<CardRewardAlternative> extraOptions = CardRewardAlternative.Generate(this);
				AfterGenerated?.Invoke();
				_currentlyShownScreen?.RefreshOptions(_cards, extraOptions);
			}
		}

		private void OnRelicObtained(RelicModel relic)
		{
			if (_cards == null)
			{
				throw new InvalidOperationException("cards must be set first before you can update them");
			}
			if (relic.TryModifyCardRewardOptions(base.Player, _cards, Options))
			{
				TaskHelper.RunSafely(relic.AfterModifyingRewards());
			}
			if (relic.TryModifyCardRewardOptionsLate(base.Player, _cards, Options))
			{
				TaskHelper.RunSafely(relic.AfterModifyingRewards());
			}
		}

		protected override async Task<bool> OnSelect()
		{
			Log.Info($"Player {base.Player.NetId} selected card reward");
			bool rewardComplete = false;
			bool endSelection = false;
			List<CardModel> chosenCardIds = new List<CardModel>();
			IReadOnlyList<CardRewardAlternative> cardRewardOption = CardRewardAlternative.Generate(this);
			if (LocalContext.IsMe(base.Player))
			{
				_currentlyShownScreen = NCardRewardSelectionScreen.ShowScreen(_cards, cardRewardOption);
			}
			while (!endSelection)
			{
				uint choiceId = _synchronizer.ReserveChoiceId(base.Player);
				int? num;
				CardModel obtainedCard;
				if (LocalContext.IsMe(base.Player))
				{
					if (_currentlyShownScreen != null)
					{
						num = await _currentlyShownScreen.OptionSelected();
					}
					else
					{
						CardRewardSelection? selection = CardSelectCmd.Selector?.GetSelectedCardReward(_cards, cardRewardOption);
						if (!selection.HasValue)
						{
							throw new InvalidOperationException("Card selector unset during test!");
						}
						if (selection.Value.alternative != null)
						{
							num = _cards.Count + cardRewardOption.FirstIndex((CardRewardAlternative r) => r == selection.Value.alternative);
						}
						else
						{
							obtainedCard = selection.Value.card;
							num = ((obtainedCard != null) ? new int?(_cards.FirstIndex((CardCreationResult c) => c.Card == selection.Value.card)) : ((int?)null));
						}
					}
					PlayerChoiceResult result = PlayerChoiceResult.FromIndex(num);
					_synchronizer.SyncLocalChoice(base.Player, choiceId, result);
				}
				else
				{
					num = (await _synchronizer.WaitForRemoteChoice(base.Player, choiceId)).AsIndexOrNull();
				}
				NCardHolder cardHolder;
				CardRewardAlternative cardRewardAlternative;
				if (num.HasValue)
				{
					if (num < _cards.Count)
					{
						obtainedCard = _cards[num.Value].Card;
						rewardComplete = true;
						endSelection = !Hook.ShouldAllowSelectingMoreCardRewards(base.Player.RunState, base.Player, this);
						cardHolder = _currentlyShownScreen?.GetCardHolder(obtainedCard);
						cardRewardAlternative = null;
					}
					else
					{
						if (!(num < _cards.Count + cardRewardOption.Count))
						{
							Log.Error($"Received bad player choice index {num} for a card reward with {_cards.Count} cards and {cardRewardOption.Count} alternatives!");
							continue;
						}
						cardRewardAlternative = cardRewardOption[num.Value - _cards.Count];
						rewardComplete = cardRewardAlternative.AfterSelected == PostAlternateCardRewardAction.EndSelectionAndCompleteReward;
						PostAlternateCardRewardAction afterSelected = cardRewardAlternative.AfterSelected;
						bool flag = (uint)(afterSelected - 1) <= 1u;
						endSelection = flag;
						cardHolder = null;
						obtainedCard = null;
					}
				}
				else
				{
					rewardComplete = false;
					endSelection = true;
					cardHolder = null;
					obtainedCard = null;
					cardRewardAlternative = null;
				}
				if (!((obtainedCard != null || cardRewardAlternative != null) | rewardComplete))
				{
					continue;
				}
				if (obtainedCard != null)
				{
					CardPileAddResult cardPileAddResult = await CardPileCmd.Add(obtainedCard, PileType.Deck);
					if (cardPileAddResult.success)
					{
						obtainedCard = cardPileAddResult.cardAdded;
						chosenCardIds.Add(obtainedCard);
						_cards.RemoveAll((CardCreationResult c) => c.Card == obtainedCard);
						if (cardHolder != null)
						{
							NCard cardNode = cardHolder.CardNode;
							NRun.Instance.GlobalUi.ReparentCard(cardNode);
							cardHolder.QueueFreeSafely();
							NRun.Instance.GlobalUi.TopBar.TrailContainer.AddChildSafely(NCardFlyVfx.Create(cardNode, PileType.Deck, isAddingToPile: true, obtainedCard.Owner.Character.TrailPath));
						}
						Log.Info($"Player {base.Player.NetId} obtained {obtainedCard.Id} from card reward");
					}
				}
				else if (cardRewardAlternative != null)
				{
					await cardRewardAlternative.OnSelect();
				}
			}
			base.Player.RelicObtained -= OnRelicObtained;
			foreach (CardModel item in chosenCardIds)
			{
				base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).CardChoices.Add(new CardChoiceHistoryEntry(item, wasPicked: true));
			}
			if (rewardComplete)
			{
				foreach (CardCreationResult card in _cards)
				{
					base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).CardChoices.Add(new CardChoiceHistoryEntry(card.Card, wasPicked: false));
				}
			}
			if (_currentlyShownScreen != null)
			{
				NOverlayStack.Instance?.Remove(_currentlyShownScreen);
				_currentlyShownScreen = null;
			}
			return rewardComplete;
		}

		public override void OnSkipped()
		{
			foreach (CardCreationResult card in _cards)
			{
				base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).CardChoices.Add(new CardChoiceHistoryEntry(card.Card, wasPicked: false));
			}
			base.Player.RelicObtained -= OnRelicObtained;
		}

		public void Reroll()
		{
			CanReroll = false;
			foreach (CardCreationResult card in _cards)
			{
				base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).CardChoices.Add(new CardChoiceHistoryEntry(card.Card, wasPicked: false));
			}
			_hasBeenRerolled = true;
			_cards.Clear();
			Populate();
		}

		public override SerializableReward ToSerializable()
		{
			if (Options.CardPools.Count <= 0)
			{
				throw new NotImplementedException("Tried to serialize a CardReward without any card pools! This is not currently supported.");
			}
			if (Options.CardPoolFilter != null)
			{
				throw new NotImplementedException("Tried to serialize a CardReward with a card pool filter! This is not currently supported.");
			}
			CardCreationFlags cardCreationFlags = Options.Flags & ~CardCreationFlags.IsCardReward;
			if (cardCreationFlags != 0)
			{
				throw new NotImplementedException("Tried to serialize a CardReward with card creation flags! " + $"This is not currently supported. Flags: {cardCreationFlags}");
			}
			return new SerializableReward
			{
				RewardType = RewardType.Card,
				Source = Options.Source,
				RarityOdds = Options.RarityOdds,
				CardPoolIds = Options.CardPools.Select((CardPoolModel p) => p.Id).ToList(),
				OptionCount = OptionCount
			};
		}

		public override void MarkContentAsSeen()
		{
		}
	}
	public class GoldReward : Reward
	{
		public const int defaultMinGoldAmount = 10;

		public const int defaultMaxGoldAmount = 20;

		private readonly bool _wasGoldStolenBack;

		private readonly int _min;

		private readonly int _max;

		private static string RewardIcon => ImageHelper.GetImagePath("ui/reward_screen/reward_icon_money.png");

		public static IEnumerable<string> AssetPaths => new global::<>z__ReadOnlySingleElementList<string>(RewardIcon);

		protected override RewardType RewardType => RewardType.Gold;

		public override int RewardsSetIndex => 1;

		protected override string IconPath => RewardIcon;

		public override Godot.Vector2 IconPosition => new Godot.Vector2(0f, -5f);

		public int Amount { get; private set; } = -1;

		public override LocString Description
		{
			get
			{
				LocString locString = new LocString("gameplay_ui", _wasGoldStolenBack ? "COMBAT_REWARD_GOLD_STOLEN" : "COMBAT_REWARD_GOLD");
				locString.Add("gold", Amount);
				return locString;
			}
		}

		public override bool IsPopulated => Amount >= 0;

		public GoldReward(int amount, Player player, bool wasGoldStolenBack = false)
			: base(player)
		{
			_min = amount;
			_max = amount;
			Amount = amount;
			_wasGoldStolenBack = wasGoldStolenBack;
		}

		public GoldReward(int min, int max, Player player, bool wasGoldStolenBack = false)
			: base(player)
		{
			_min = min;
			_max = max;
			_wasGoldStolenBack = wasGoldStolenBack;
		}

		public override void Populate()
		{
			Rng rng = _rngOverride ?? base.Player.PlayerRng.Rewards;
			Amount = rng.NextInt(_min, _max + 1);
		}

		protected override async Task<bool> OnSelect()
		{
			await PlayerCmd.GainGold(Amount, base.Player, _wasGoldStolenBack);
			Log.Info($"Player {base.Player.NetId} obtained {Amount} gold from reward");
			return true;
		}

		public override SerializableReward ToSerializable()
		{
			return new SerializableReward
			{
				RewardType = RewardType.Gold,
				GoldAmount = Amount,
				WasGoldStolenBack = _wasGoldStolenBack
			};
		}

		public override void MarkContentAsSeen()
		{
		}
	}
	public class LinkedRewardSet : Reward
	{
		private readonly List<Reward> _rewards;

		protected override RewardType RewardType => RewardType.None;

		public override int RewardsSetIndex => Rewards.Max((Reward r) => r.RewardsSetIndex);

		private static LocString HoverTipTitle => new LocString("static_hover_tips", "LINKED_REWARDS.title");

		private static LocString HoverTipDesc => new LocString("static_hover_tips", "LINKED_REWARDS.description");

		public static HoverTip HoverTip => new HoverTip(HoverTipTitle, HoverTipDesc);

		public IReadOnlyList<Reward> Rewards => _rewards.ToList();

		public override bool IsPopulated => _rewards.All((Reward r) => r.IsPopulated);

		public override LocString Description => new LocString("gameplay_ui", "COMBAT_REWARD_LINKED");

		public LinkedRewardSet(List<Reward> rewards, Player player)
			: base(player)
		{
			_rewards = rewards;
			foreach (Reward reward in _rewards)
			{
				reward.ParentRewardSet = this;
			}
		}

		public override void Populate()
		{
			foreach (Reward reward in _rewards)
			{
				reward.Populate();
			}
		}

		public void RemoveReward(Reward reward)
		{
			_rewards.Remove(reward);
		}

		protected override Task<bool> OnSelect()
		{
			return Task.FromResult(result: true);
		}

		public override void OnSkipped()
		{
			foreach (Reward reward in _rewards)
			{
				reward.OnSkipped();
			}
		}

		public override void MarkContentAsSeen()
		{
			foreach (Reward reward in _rewards)
			{
				reward.MarkContentAsSeen();
			}
		}
	}
	public class PotionReward : Reward
	{
		private bool _wasTaken;

		private Control? _icon;

		protected override RewardType RewardType => RewardType.Potion;

		public override int RewardsSetIndex => 2;

		public PotionModel? Potion { get; private set; }

		public override Godot.Vector2 IconPosition => new Godot.Vector2(0f, -2f);

		public override LocString Description => Potion.Title;

		public PotionModel? ClaimedPotion { get; private set; }

		protected override IEnumerable<IHoverTip> ExtraHoverTips => Potion.HoverTips;

		public override bool IsPopulated => Potion != null;

		public PotionReward(Player player)
			: base(player)
		{
		}

		public PotionReward(PotionModel potion, Player player)
			: base(player)
		{
			potion.AssertMutable();
			Potion = potion;
		}

		public override void Populate()
		{
			Rng rng = _rngOverride ?? base.Player.PlayerRng.Rewards;
			if (Potion == null)
			{
				PotionModel potionModel = (Potion = PotionFactory.CreateRandomPotionOutOfCombat(base.Player, rng).ToMutable());
			}
		}

		public override Control? CreateIcon()
		{
			if (TestMode.IsOn)
			{
				return null;
			}
			if (_icon == null)
			{
				_icon = NPotion.Create(Potion);
			}
			return _icon;
		}

		protected override async Task<bool> OnSelect()
		{
			PotionProcureResult potionProcureResult = await PotionCmd.TryToProcure(Potion, base.Player);
			if (potionProcureResult.success)
			{
				Log.Info($"Player {base.Player.NetId} obtained {potionProcureResult.potion.Id} from potion reward");
				ClaimedPotion = Potion;
				_wasTaken = true;
				return true;
			}
			if (potionProcureResult.failureReason == PotionProcureFailureReason.TooFull)
			{
				return false;
			}
			ClaimedPotion = Potion;
			_wasTaken = true;
			return true;
		}

		public override void OnSkipped()
		{
			if (!_wasTaken)
			{
				base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).PotionChoices.Add(new ModelChoiceHistoryEntry(Potion.Id, wasPicked: false));
			}
		}

		public override void MarkContentAsSeen()
		{
			SaveManager.Instance.MarkPotionAsSeen(Potion);
		}
	}
	public class RelicReward : Reward
	{
		private readonly RelicRarity _rarity;

		/// <summary>
		/// The relic that this reward gives, if it's predetermined.
		/// For randomly-rolled relic rewards (like from Elite combats), this is null.
		/// For predetermined relic rewards (like from <see cref="T:MegaCrit.Sts2.Core.Models.Events.FakeMerchant" />), this is set to the predetermined relic.
		/// </summary>
		private RelicModel? _predeterminedRelic;

		/// <summary>
		/// The relic that this reward gives.
		/// For randomly-rolled relic rewards (like from Elite combats), this starts out null, and is populated by
		/// <see cref="M:MegaCrit.Sts2.Core.Rewards.RelicReward.Populate" />.
		/// For predetermined relic rewards (like from <see cref="T:MegaCrit.Sts2.Core.Models.Events.FakeMerchant" />), this is set to the predetermined relic.
		/// </summary>
		private RelicModel? _relic;

		private bool _wasTaken;

		protected override RewardType RewardType => RewardType.Relic;

		public override int RewardsSetIndex => 3;

		public RelicRarity Rarity => _rarity;

		public RelicModel? ClaimedRelic { get; private set; }

		public RelicModel? Relic => _relic;

		public override LocString Description => _relic.Title;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => _relic.HoverTips;

		public override bool IsPopulated => _relic != null;

		public RelicReward(Player player)
			: base(player)
		{
		}

		public RelicReward(RelicModel relic, Player player)
			: base(player)
		{
			relic.AssertMutable();
			_predeterminedRelic = relic;
			_relic = relic;
		}

		public RelicReward(RelicRarity rarity, Player player)
			: base(player)
		{
			_rarity = rarity;
		}

		public override void Populate()
		{
			if (_relic != null)
			{
				return;
			}
			if (_rarity == RelicRarity.None)
			{
				if (_rngOverride != null)
				{
					_relic = RelicFactory.PullNextRelicFromFront(base.Player, _rngOverride).ToMutable();
				}
				else
				{
					_relic = RelicFactory.PullNextRelicFromFront(base.Player).ToMutable();
				}
			}
			else
			{
				_relic = RelicFactory.PullNextRelicFromFront(base.Player, _rarity).ToMutable();
			}
		}

		public override TextureRect CreateIcon()
		{
			TextureRect textureRect = new TextureRect();
			textureRect.Texture = _relic.BigIcon;
			textureRect.Material = (ShaderMaterial)PreloadManager.Cache.GetMaterial("res://materials/ui/relic_mat.tres").Duplicate(deep: true);
			_relic.UpdateTexture(textureRect);
			textureRect.SetAnchorsPreset(Control.LayoutPreset.FullRect);
			textureRect.ExpandMode = TextureRect.ExpandModeEnum.IgnoreSize;
			return textureRect;
		}

		protected override async Task<bool> OnSelect()
		{
			Log.Info($"Player {base.Player.NetId} obtained {_relic.Id} from relic reward");
			ClaimedRelic = await RelicCmd.Obtain(_relic, base.Player);
			_wasTaken = true;
			return true;
		}

		public override void OnSkipped()
		{
			if (!_wasTaken)
			{
				base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).RelicChoices.Add(new ModelChoiceHistoryEntry(_relic.Id, wasPicked: false));
			}
		}

		public override void MarkContentAsSeen()
		{
			SaveManager.Instance.MarkRelicAsSeen(_relic);
		}

		public override SerializableReward ToSerializable()
		{
			SerializableReward serializableReward = base.ToSerializable();
			if (_predeterminedRelic != null)
			{
				serializableReward.PredeterminedModelId = _predeterminedRelic.Id;
			}
			return serializableReward;
		}
	}
	public abstract class Reward
	{
		/// <summary>
		/// If this is set, uses this rng rather than the default one used by the particular reward (Typically a player RNG)
		/// Used in the Crystal Sphere Items so that we can pass the event rng to be used and not hit state divergences in multiplayer
		/// since we don't sync the player rng sets in that case
		/// </summary>
		protected Rng? _rngOverride;

		/// <summary>
		/// The player that this reward is for.
		/// </summary>
		public Player Player { get; }

		protected abstract RewardType RewardType { get; }

		/// <summary>
		/// The index to use for this reward when ordering the rewards displayed in a <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardsSet" />.
		/// Lower indexes are displayed first.
		/// </summary>
		public abstract int RewardsSetIndex { get; }

		public abstract LocString Description { get; }

		/// <summary>
		/// Whether this reward has been populated.
		/// </summary>
		public abstract bool IsPopulated { get; }

		/// <summary>
		/// Whether the reward has successfully been taken.
		/// </summary>
		public bool SuccessfullySelected { get; private set; }

		protected virtual string? IconPath => null;

		public virtual Godot.Vector2 IconPosition => Godot.Vector2.Zero;

		protected virtual IEnumerable<IHoverTip> ExtraHoverTips => System.Array.Empty<IHoverTip>();

		public virtual IEnumerable<IHoverTip> HoverTips
		{
			get
			{
				List<IHoverTip> list = ExtraHoverTips.ToList();
				if (ParentRewardSet != null)
				{
					list.Add(LinkedRewardSet.HoverTip);
				}
				return list;
			}
		}

		public LinkedRewardSet? ParentRewardSet { get; set; }

		protected Reward(Player player)
		{
			Player = player;
		}

		/// <summary>
		/// Logic to run to populate this reward with options.
		/// For example, calling this on a CardReward would generate 3 cards for the player to choose from.
		/// </summary>
		public abstract void Populate();

		/// <summary>
		/// Logic to run when this reward is selected.
		/// </summary>
		/// <returns>
		/// Whether the reward was received. Usually true, but false in certain cases (like if the player tries to
		/// take a potion when they have no more room for potions).
		/// </returns>
		protected abstract Task<bool> OnSelect();

		/// <summary>
		/// Create an icon node representing this reward.
		/// Null if we're in test mode.
		/// </summary>
		public virtual Control? CreateIcon()
		{
			if (TestMode.IsOn)
			{
				return null;
			}
			TextureRect textureRect = new TextureRect();
			textureRect.Texture = PreloadManager.Cache.GetCompressedTexture2D(IconPath);
			textureRect.SetAnchorsPreset(Control.LayoutPreset.FullRect);
			textureRect.ExpandMode = TextureRect.ExpandModeEnum.IgnoreSize;
			return textureRect;
		}

		public virtual void OnSkipped()
		{
		}

		/// <summary>
		/// YOU SHOULD MOST LIKELY NOT BE CALLING THIS!
		/// See <see cref="M:MegaCrit.Sts2.Core.Multiplayer.Game.RewardsSetSynchronizer.SelectLocalReward(MegaCrit.Sts2.Core.Rewards.Reward)" />.
		/// This only selects the reward on the local machine.
		/// </summary>
		public async Task<bool> SelectUnsynchronized()
		{
			bool success = await OnSelect();
			if (success)
			{
				await Hook.AfterRewardTaken(Player.RunState, Player, this);
				SuccessfullySelected = true;
			}
			if (ParentRewardSet != null)
			{
				ParentRewardSet.RemoveReward(this);
				await ParentRewardSet.OnSelect();
			}
			return success;
		}

		public abstract void MarkContentAsSeen();

		public virtual SerializableReward ToSerializable()
		{
			return new SerializableReward
			{
				RewardType = RewardType
			};
		}

		public Reward SetRng(Rng rng)
		{
			_rngOverride = rng;
			return this;
		}

		public static Reward FromSerializable(SerializableReward save, Player player)
		{
			switch (save.RewardType)
			{
			case RewardType.RemoveCard:
				return new CardRemovalReward(player);
			case RewardType.SpecialCard:
			{
				CardModel cardModel = CardModel.FromSerializable(save.SpecialCard);
				player.RunState.AddCard(cardModel, player);
				SpecialCardReward specialCardReward = new SpecialCardReward(cardModel, player);
				if (save.CustomDescriptionEncounterSourceId != ModelId.none)
				{
					specialCardReward.SetCustomDescriptionEncounterSource(save.CustomDescriptionEncounterSourceId);
				}
				return specialCardReward;
			}
			case RewardType.Gold:
				return new GoldReward(save.GoldAmount, player, save.WasGoldStolenBack);
			case RewardType.Potion:
				return new PotionReward(player);
			case RewardType.Relic:
				if (save.PredeterminedModelId != ModelId.none)
				{
					return new RelicReward(ModelDb.GetById<RelicModel>(save.PredeterminedModelId).ToMutable(), player);
				}
				return new RelicReward(player);
			case RewardType.Card:
			{
				CardCreationOptions options = new CardCreationOptions(save.CardPoolIds.Select(ModelDb.GetById<CardPoolModel>), save.Source, save.RarityOdds);
				return new CardReward(options, save.OptionCount, player);
			}
			default:
				throw new NotImplementedException("Serializing these types of rewards hasn't been implemented yet");
			}
		}
	}
	/// <summary>
	/// Represents a set of rewards that can be presented to the player.
	/// One of these is always generated at the end of combat, but events and relics can also present rewards.
	/// This class will always apply reward modifications from relics and other hooks.
	/// There are currently no cases in which you need to use this class directly. In the future, if there are complicated
	/// reward cases that are hard to build into RewardsCmd, change this class to support them.
	/// </summary>
	public class RewardsSet
	{
		public static Func<RewardsSet, Task>? testSelector;

		private bool _allowEmptyRewards;

		private bool _disallowSkipping;

		private bool _isGenerated;

		private readonly RewardsSetSynchronizer _synchronizer;

		public AbstractRoom? Room { get; private set; }

		public Player Player { get; }

		public List<Reward> Rewards { get; } = new List<Reward>();

		public bool ThrowInTestIfRewardsNotTaken { get; set; } = true;

		public bool DisallowSkipping => _disallowSkipping;

		public bool AllRewardsSuccessfullySelected => Rewards.All((Reward r) => r.SuccessfullySelected);

		/// <summary>
		/// Set by RewardsSetSynchronizer.
		/// </summary>
		public int Id { get; set; } = -1;

		public RewardsSet(Player player, RewardsSetSynchronizer? synchronizer = null)
		{
			Player = player;
			_synchronizer = synchronizer ?? RunManager.Instance.RewardsSetSynchronizer;
		}

		/// <summary>
		/// Associates this rewards set with a room without generating rewards for it, and allows the rewards screen
		/// to be shown even with no rewards. This determines whether the rewards screen is terminal (has a proceed
		/// button). Use <see cref="M:MegaCrit.Sts2.Core.Rewards.RewardsSet.WithRewardsFromRoom(MegaCrit.Sts2.Core.Rooms.AbstractRoom)" /> to both associate a room and generate its rewards.
		/// </summary>
		public RewardsSet EmptyForRoom(AbstractRoom room)
		{
			Room = room;
			_allowEmptyRewards = true;
			return this;
		}

		/// <summary>
		/// Generate a list of rewards to offer for the specified room.
		/// Should only be used with combat or treasure rooms.
		/// </summary>
		/// <param name="room">Room to generate rewards for.</param>
		public RewardsSet WithRewardsFromRoom(AbstractRoom room)
		{
			Room = room;
			if (room.RoomType == RoomType.Boss && Player.RunState.CurrentActIndex >= Player.RunState.Acts.Count - 1)
			{
				return this;
			}
			if (!TryGenerateTutorialRewards(Player, room))
			{
				Rewards.AddRange(GenerateRewardsFor(Player, room));
			}
			if (Room is CombatRoom combatRoom && combatRoom.ExtraRewards.TryGetValue(Player, out List<Reward> value))
			{
				Rewards.AddRange(value);
			}
			return this;
		}

		/// <summary>
		/// Used when custom rewards are offered, like in an event or by a relic.
		/// </summary>
		public RewardsSet WithCustomRewards(List<Reward> rewards)
		{
			Rewards.AddRange(rewards);
			return this;
		}

		/// <summary>
		/// Call this to disallow skipping the rewards. The player must take all the rewards before the screen is dismissed.
		/// </summary>
		public RewardsSet WithSkippingDisallowed()
		{
			_disallowSkipping = true;
			return this;
		}

		/// <summary>
		/// Populates the reward instances in Rewards, calls modify hooks on them, and returns the result.
		/// Usually you want to use Offer instead. This is mostly for tests where we inspect the rewards that are generated.
		/// </summary>
		public async Task GenerateWithoutOffering()
		{
			if (_isGenerated)
			{
				return;
			}
			List<Reward> second = Rewards.ToList();
			foreach (Reward reward in Rewards)
			{
				reward.Populate();
			}
			IEnumerable<AbstractModel> modifiers = Hook.ModifyRewards(Player.RunState, Player, Rewards, Room);
			foreach (Reward item in Rewards.Except(second))
			{
				if (!item.IsPopulated)
				{
					item.Populate();
				}
			}
			await Hook.AfterModifyingRewards(Player.RunState, modifiers);
			Rewards.Sort((Reward x, Reward y) => x.RewardsSetIndex.CompareTo(y.RewardsSetIndex));
			_isGenerated = true;
		}

		/// <summary>
		/// Populates the reward instances in Rewards, calls modify hooks on them, and offers the rewards to the player.
		/// If the player is not the local player, then rewards are only generated on the backend and not shown to the player.
		/// </summary>
		public async Task Offer()
		{
			if (Player.Creature.IsDead)
			{
				return;
			}
			await GenerateWithoutOffering();
			bool flag = Room is CombatRoom;
			Task task = _synchronizer.BeginRewardsSet(this);
			if (Rewards.Count <= 0 && !flag && !_allowEmptyRewards)
			{
				return;
			}
			if (!Rewards.All((Reward r) => r.IsPopulated) && Rewards.Any((Reward r) => r.IsPopulated))
			{
				Log.Warn("Some rewards are populated and others are not when calling RewardsCmd.Offer! This might lead to hooks getting called twice");
			}
			if (LocalContext.IsMe(Player))
			{
				if (TestMode.IsOn)
				{
					if (testSelector != null)
					{
						await testSelector(this);
					}
					else
					{
						foreach (Reward reward in Rewards)
						{
							await _synchronizer.SelectLocalReward(reward);
						}
					}
					if (!_synchronizer.IsRewardsSetCompleted(this) && ThrowInTestIfRewardsNotTaken)
					{
						throw new InvalidOperationException("The RewardsSet is not complete after rewards were selected!");
					}
				}
				else
				{
					NRewardsScreen.ShowScreen(this, flag, Player.RunState);
				}
			}
			await task;
		}

		/// <summary>
		/// Generates a list of default rewards to offer at the end of the specified room.
		/// This does _not_ include hook modifications, like from Prayer Wheel.
		/// Calling this may increment RNG counters and make other run state changes.
		/// </summary>
		/// <param name="player">Player to generate rewards for.</param>
		/// <param name="room">Room to generate rewards for.</param>
		/// <returns>List of rewards.</returns>
		private List<Reward> GenerateRewardsFor(Player player, AbstractRoom room)
		{
			if (RunManager.Instance == null)
			{
				throw new InvalidOperationException("Only valid during a run.");
			}
			List<Reward> list = new List<Reward>();
			if (!(room is CombatRoom combatRoom))
			{
				if (!(room is TreasureRoom))
				{
					throw new InvalidOperationException("Tried to generate a reward for invalid room type: " + room.GetType().Name);
				}
			}
			else
			{
				switch (room.RoomType)
				{
				case RoomType.Monster:
					if (combatRoom.GoldProportion > 0f)
					{
						list.Add(new GoldReward((int)Math.Round((float)combatRoom.Encounter.MinGoldReward * combatRoom.GoldProportion), (int)Math.Round((float)combatRoom.Encounter.MaxGoldReward * combatRoom.GoldProportion), player));
					}
					RollForPotionAndAddTo(list, player, room.RoomType);
					list.Add(new CardReward(CardCreationOptions.ForRoom(player, room.RoomType).WithFlags(CardCreationFlags.IsFromCombat), 3, player));
					break;
				case RoomType.Elite:
					list.Add(new GoldReward(combatRoom.Encounter.MinGoldReward, combatRoom.Encounter.MaxGoldReward, player));
					RollForPotionAndAddTo(list, player, room.RoomType);
					list.Add(new CardReward(CardCreationOptions.ForRoom(player, room.RoomType).WithFlags(CardCreationFlags.IsFromCombat), 3, player));
					list.Add(new RelicReward(player));
					break;
				case RoomType.Boss:
					list.Add(new GoldReward(combatRoom.Encounter.MinGoldReward, combatRoom.Encounter.MaxGoldReward, player));
					RollForPotionAndAddTo(list, player, room.RoomType);
					list.Add(new CardReward(CardCreationOptions.ForRoom(player, room.RoomType).WithFlags(CardCreationFlags.IsFromCombat), 3, player));
					break;
				}
			}
			return list;
		}

		private void RollForPotionAndAddTo(ICollection<Reward> rewards, Player player, RoomType roomType)
		{
			PotionRewardOdds potionReward = player.PlayerOdds.PotionReward;
			AscensionManager ascensionManager = RunManager.Instance.AscensionManager;
			if (potionReward.Roll(player, roomType))
			{
				rewards.Add(new PotionReward(player));
			}
		}

		private bool TryGenerateTutorialRewards(Player player, AbstractRoom room)
		{
			CardCreationOptions rerollOptions = CardCreationOptions.ForRoom(player, room.RoomType);
			if (player.UnlockState.NumberOfRuns == 0 && player.UnlockState.EpochUnlockCount() == 0 && player.Character is Ironclad && room is CombatRoom combatRoom)
			{
				int num = player.RunState.MapPointHistory.SelectMany((IReadOnlyList<MapPointHistoryEntry> p) => p).Count((MapPointHistoryEntry e) => e.Rooms.FindIndex((MapPointRoomHistoryEntry r) => r.RoomType == RoomType.Monster) >= 0);
				if (room.RoomType == RoomType.Monster && num <= 7)
				{
					(CardModel[], PotionModel)? tutorialMonsterRewards = GetTutorialMonsterRewards(player, num - 1);
					if (tutorialMonsterRewards.HasValue)
					{
						(CardModel[], PotionModel) valueOrDefault = tutorialMonsterRewards.GetValueOrDefault();
						Rewards.Add(new GoldReward(10, 20, player));
						if (valueOrDefault.Item2 != null)
						{
							Rewards.Add(new PotionReward(valueOrDefault.Item2, player));
						}
						Rewards.Add(new CardReward(valueOrDefault.Item1, CardCreationSource.Encounter, player, rerollOptions));
						return true;
					}
					return false;
				}
				if (room.RoomType == RoomType.Elite)
				{
					switch (player.RunState.MapPointHistory.SelectMany((IReadOnlyList<MapPointHistoryEntry> l) => l).Count((MapPointHistoryEntry e) => e.MapPointType == MapPointType.Elite))
					{
					case 1:
					{
						CardModel[] cardsToOffer2 = new CardModel[3]
						{
							player.RunState.CreateCard<Bludgeon>(player),
							player.RunState.CreateCard<Pyre>(player),
							player.RunState.CreateCard<EvilEye>(player)
						};
						Rewards.Add(new GoldReward(combatRoom.Encounter.MinGoldReward, combatRoom.Encounter.MaxGoldReward, player));
						Rewards.Add(new PotionReward(ModelDb.Potion<BlockPotion>().ToMutable(), player));
						Rewards.Add(GetTutorialRelicReward<Vajra>(player));
						Rewards.Add(new CardReward(cardsToOffer2, CardCreationSource.Encounter, player, rerollOptions));
						return true;
					}
					case 2:
					{
						CardModel[] cardsToOffer = new CardModel[3]
						{
							player.RunState.CreateCard<Pillage>(player),
							player.RunState.CreateCard<Rampage>(player),
							player.RunState.CreateCard<FlameBarrier>(player)
						};
						Rewards.Add(new GoldReward(combatRoom.Encounter.MinGoldReward, combatRoom.Encounter.MaxGoldReward, player));
						Rewards.Add(GetTutorialRelicReward<OrnamentalFan>(player));
						Rewards.Add(new CardReward(cardsToOffer, CardCreationSource.Encounter, player, rerollOptions));
						return true;
					}
					}
				}
				else if (room.RoomType == RoomType.Boss && player.RunState.MapPointHistory.SelectMany((IReadOnlyList<MapPointHistoryEntry> l) => l).Count((MapPointHistoryEntry e) => e.MapPointType == MapPointType.Boss) == 1)
				{
					CardModel[] cardsToOffer3 = new CardModel[3]
					{
						player.RunState.CreateCard<PrimalForce>(player),
						player.RunState.CreateCard<DemonForm>(player),
						player.RunState.CreateCard<Thrash>(player)
					};
					Rewards.Add(new GoldReward(combatRoom.Encounter.MinGoldReward, combatRoom.Encounter.MaxGoldReward, player));
					Rewards.Add(new CardReward(cardsToOffer3, CardCreationSource.Encounter, player, rerollOptions));
					return true;
				}
			}
			return false;
		}

		private static RelicReward GetTutorialRelicReward<T>(Player player) where T : RelicModel
		{
			if (player.RelicGrabBag.Contains(ModelDb.Relic<T>()))
			{
				return new RelicReward(ModelDb.Relic<T>().ToMutable(), player);
			}
			return new RelicReward(player);
		}

		public static (CardModel[] Cards, PotionModel? Potion)? GetTutorialMonsterRewards(Player player, int index)
		{
			return index switch
			{
				0 => (new CardModel[3]
				{
					player.RunState.CreateCard<SetupStrike>(player),
					player.RunState.CreateCard<Tremble>(player),
					player.RunState.CreateCard<BloodWall>(player)
				}, null), 
				1 => (new CardModel[3]
				{
					player.RunState.CreateCard<Breakthrough>(player),
					player.RunState.CreateCard<Inflame>(player),
					player.RunState.CreateCard<Anger>(player)
				}, null), 
				2 => (new CardModel[3]
				{
					player.RunState.CreateCard<IronWave>(player),
					player.RunState.CreateCard<Dismantle>(player),
					player.RunState.CreateCard<Cinder>(player)
				}, ModelDb.Potion<FirePotion>().ToMutable()), 
				3 => (new CardModel[3]
				{
					player.RunState.CreateCard<Stomp>(player),
					player.RunState.CreateCard<ShrugItOff>(player),
					player.RunState.CreateCard<Armaments>(player)
				}, null), 
				4 => (new CardModel[3]
				{
					player.RunState.CreateCard<Thunderclap>(player),
					player.RunState.CreateCard<SetupStrike>(player),
					player.RunState.CreateCard<Rage>(player)
				}, ModelDb.Potion<StrengthPotion>().ToMutable()), 
				5 => (new CardModel[3]
				{
					player.RunState.CreateCard<BattleTrance>(player),
					player.RunState.CreateCard<TrueGrit>(player),
					player.RunState.CreateCard<Uppercut>(player)
				}, null), 
				6 => (new CardModel[3]
				{
					player.RunState.CreateCard<Bloodletting>(player),
					player.RunState.CreateCard<Whirlwind>(player),
					player.RunState.CreateCard<Tremble>(player)
				}, ModelDb.Potion<EnergyPotion>().ToMutable()), 
				_ => null, 
			};
		}

		public override string ToString()
		{
			return $"Id: {Id} Owner: {Player.NetId} Rewards: {string.Join(",", Rewards)}";
		}
	}
	public enum RewardType
	{
		None,
		Card,
		Gold,
		Potion,
		Relic,
		RemoveCard,
		SpecialCard
	}
	public static class RewardTypeExtensions
	{
		public static IEnumerable<string> GetAssetPaths(this RewardType rewardType)
		{
			return rewardType switch
			{
				RewardType.Card => CardReward.AssetPaths, 
				RewardType.Gold => GoldReward.AssetPaths, 
				RewardType.RemoveCard => CardRemovalReward.AssetPaths, 
				RewardType.SpecialCard => SpecialCardReward.AssetPaths, 
				_ => System.Array.Empty<string>(), 
			};
		}
	}
	/// <summary>
	/// A reward that adds a specific card to the player's deck.
	/// Good for events like <see cref="T:MegaCrit.Sts2.Core.Models.Events.TheLanternKey" /> that give specific quest cards, and for other miscellaneous spots
	/// that offer specific cards as rewards (like <see cref="T:MegaCrit.Sts2.Core.Models.Monsters.ThievingHopper" /> giving you your stolen card back as a reward).
	/// </summary>
	public class SpecialCardReward : Reward
	{
		private bool _wasTaken;

		private readonly CardModel? _card;

		private ModelId _customDescriptionEncounterSourceId = ModelId.none;

		private static string RewardIcon => ImageHelper.GetImagePath("ui/reward_screen/reward_icon_special_card.png");

		public static IEnumerable<string> AssetPaths => new global::<>z__ReadOnlySingleElementList<string>(RewardIcon);

		protected override RewardType RewardType => RewardType.SpecialCard;

		public override int RewardsSetIndex => 4;

		protected override string IconPath => RewardIcon;

		public override LocString Description
		{
			get
			{
				LocString locString = null;
				if (_customDescriptionEncounterSourceId != ModelId.none)
				{
					locString = ModelDb.GetById<EncounterModel>(_customDescriptionEncounterSourceId).CustomRewardDescription;
				}
				if (locString == null)
				{
					locString = new LocString("gameplay_ui", "COMBAT_REWARD_ADD_SPECIAL_CARD");
				}
				locString.Add("Card", _card.Title);
				return locString;
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromCard(_card));

		public override bool IsPopulated => _card != null;

		public SpecialCardReward(CardModel card, Player player)
			: base(player)
		{
			card.AssertMutable();
			_card = card;
		}

		/// <summary>
		/// Set an encounter to use for this reward's description.
		/// If this is not set, the default description will be used.
		/// </summary>
		public void SetCustomDescriptionEncounterSource(ModelId encounterId)
		{
			if (ModelDb.GetByIdOrNull<EncounterModel>(encounterId) == null)
			{
				throw new ArgumentException($"Encounter {encounterId} does not exist!");
			}
			_customDescriptionEncounterSourceId = encounterId;
		}

		public override void Populate()
		{
		}

		protected override async Task<bool> OnSelect()
		{
			Log.Info($"Player {base.Player.NetId} obtained {_card.Id} from special card reward");
			CardPileAddResult result = await CardPileCmd.Add(_card, PileType.Deck);
			if (result.success)
			{
				CardCmd.PreviewCardPileAdd(result, 2f);
			}
			_wasTaken = true;
			return true;
		}

		public override void OnSkipped()
		{
			if (!_wasTaken)
			{
				base.Player.RunState.CurrentMapPointHistoryEntry.GetEntry(base.Player.NetId).CardChoices.Add(new CardChoiceHistoryEntry(_card, wasPicked: false));
			}
		}

		public override SerializableReward ToSerializable()
		{
			return new SerializableReward
			{
				RewardType = RewardType,
				SpecialCard = _card.ToSerializable(),
				CustomDescriptionEncounterSourceId = _customDescriptionEncounterSourceId
			};
		}

		public override void MarkContentAsSeen()
		{
		}
	}
}
