	public sealed class MegaRandom
	{
		private const double _incrDouble = 1.1102230246251565E-16;

		private const float _incrFloat = 5.9604645E-08f;

		private ulong _s0;

		private ulong _s1;

		private ulong _s2;

		private ulong _s3;

		/// <summary>
		/// Initializes a new instance with the provided seed.
		/// </summary>
		/// <param name="seed">Seed value.</param>
		public MegaRandom(ulong seed)
		{
			Reinitialise(seed);
		}

		/// <summary>
		/// Initializes a new instance from a serialized instance.
		/// </summary>
		public MegaRandom(SerializableRng serializable)
		{
			Reinitialise(serializable);
		}

		/// <summary>
		/// Splitmix64 PRNG.
		/// </summary>
		/// <param name="x">PRNG state. This can take any value, including zero.</param>
		/// <returns>A new random UInt64.</returns>
		public static ulong Splitmix64(ref ulong x)
		{
			ulong num = (x += 11400714819323198485uL);
			num = (num ^ (num >> 30)) * 13787848793156543929uL;
			num = (num ^ (num >> 27)) * 10723151780598845931uL;
			return num ^ (num >> 31);
		}

		/// <summary>
		/// Re-initialises the random number generator state using the provided seed value.
		/// </summary>
		/// <param name="seed">Seed value.</param>
		public void Reinitialise(ulong seed)
		{
			_s0 = Splitmix64(ref seed);
			_s1 = Splitmix64(ref seed);
			_s2 = Splitmix64(ref seed);
			_s3 = Splitmix64(ref seed);
		}

		/// <summary>
		/// Initializes the RNG state from a serializable object round-tripped from ToSerializable.
		/// </summary>
		public void Reinitialise(SerializableRng serializable)
		{
			_s0 = serializable.state0;
			_s1 = serializable.state1;
			_s2 = serializable.state2;
			_s3 = serializable.state3;
		}

		/// <summary>
		/// Fills the provided span with random byte values, sampled from the uniform distribution with interval [0, 255].
		/// </summary>
		/// <param name="span">The byte span to fill with random samples.</param>
		public unsafe void NextBytes(Span<byte> span)
		{
			ulong num = _s0;
			ulong num2 = _s1;
			ulong num3 = _s2;
			ulong num4 = _s3;
			while (span.Length >= 8)
			{
				Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(span), BitOperations.RotateLeft(num2 * 5, 7) * 9);
				ulong num5 = num2 << 17;
				num3 ^= num;
				num4 ^= num2;
				num2 ^= num3;
				num ^= num4;
				num3 ^= num5;
				num4 = BitOperations.RotateLeft(num4, 45);
				span = span.Slice(8);
			}
			if (!span.IsEmpty)
			{
				ulong num6 = BitOperations.RotateLeft(num2 * 5, 7) * 9;
				byte* ptr = (byte*)(&num6);
				for (int i = 0; i < span.Length; i++)
				{
					span[i] = ptr[i];
				}
				ulong num7 = num2 << 17;
				num3 ^= num;
				num4 ^= num2;
				num2 ^= num3;
				num ^= num4;
				num3 ^= num7;
				num4 = BitOperations.RotateLeft(num4, 45);
			}
			_s0 = num;
			_s1 = num2;
			_s2 = num3;
			_s3 = num4;
		}

		/// <summary>
		/// Get the next 64 random bits from the underlying PRNG. This method forms the foundation for most of the methods of each
		/// Next* implementation, which take these 64 bits and manipulate them to provide random values of various
		/// data types, such as integers, byte arrays, floating point values, etc.
		/// </summary>
		/// <returns>A <see cref="T:System.UInt64" /> containing random bits from the underlying PRNG algorithm.</returns>
		private ulong NextULongInner()
		{
			ulong s = _s0;
			ulong s2 = _s1;
			ulong s3 = _s2;
			ulong s4 = _s3;
			ulong result = BitOperations.RotateLeft(s2 * 5, 7) * 9;
			ulong num = s2 << 17;
			s3 ^= s;
			s4 ^= s2;
			s2 ^= s3;
			s ^= s4;
			s3 ^= num;
			s4 = BitOperations.RotateLeft(s4, 45);
			_s0 = s;
			_s1 = s2;
			_s2 = s3;
			_s3 = s4;
			return result;
		}

		/// <summary>
		/// Returns a random integer sampled from the uniform distribution with interval [0, maxValue),
		/// i.e., exclusive of <paramref name="maxValue" />.
		/// </summary>
		/// <param name="maxValue">The maximum value to be sampled (exclusive).</param>
		/// <returns>A new random sample.</returns>
		public int Next(int maxValue)
		{
			if (maxValue < 1)
			{
				throw new ArgumentOutOfRangeException("maxValue", maxValue, "maxValue must be > 0");
			}
			return NextInner(maxValue);
		}

		/// <summary>
		/// Returns a random integer sampled from the uniform distribution with interval [minValue, maxValue),
		/// i.e., inclusive of <paramref name="minValue" /> and exclusive of <paramref name="maxValue" />.
		/// </summary>
		/// <param name="minValue">The minimum value to be sampled (inclusive).</param>
		/// <param name="maxValue">The maximum value to be sampled (exclusive).</param>
		/// <returns>A new random sample.</returns>
		/// <remarks>
		/// maxValue must be greater than minValue. minValue may be negative.
		/// </remarks>
		public int Next(int minValue, int maxValue)
		{
			if (minValue >= maxValue)
			{
				throw new ArgumentOutOfRangeException("maxValue", maxValue, "maxValue must be > minValue");
			}
			long num = (long)maxValue - (long)minValue;
			if (num <= int.MaxValue)
			{
				return NextInner((int)num) + minValue;
			}
			return (int)(NextInner(num) + minValue);
		}

		/// <summary>
		/// Returns a random <see cref="T:System.Double" /> sampled from the uniform distribution with interval [0, 1),
		/// i.e., inclusive of 0.0 and exclusive of 1.0.
		/// </summary>
		/// <returns>A new random sample, of type <see cref="T:System.Double" />.</returns>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public double NextDouble()
		{
			return (double)(NextULongInner() >> 11) * 1.1102230246251565E-16;
		}

		/// <summary>
		/// Returns a random integer sampled from the uniform distribution with interval [0, int.MaxValue],
		/// i.e., <b>inclusive</b> of <see cref="F:System.Int32.MaxValue" />.
		/// </summary>
		/// <returns>A new random sample.</returns>
		/// <remarks>
		/// This method differs from <see cref="M:System.Random.Next" />, in the following way; the uniform distribution that
		/// is sampled from includes the value <see cref="F:System.Int32.MaxValue" />.
		/// </remarks>
		public int NextInt()
		{
			return (int)(NextULongInner() >> 33);
		}

		/// <summary>
		/// Returns a random <see cref="T:System.UInt32" /> sampled from the uniform distribution with interval [0, uint.MaxValue],
		/// i.e., over the full range of possible uint values.
		/// </summary>
		/// <returns>A new random sample.</returns>
		public uint NextUInt()
		{
			return (uint)NextULongInner();
		}

		/// <summary>
		/// Returns a random <see cref="T:System.UInt64" /> sampled from the uniform distribution with interval [0, ulong.MaxValue],
		/// i.e., over the full range of possible ulong values.
		/// </summary>
		/// <returns>A new random sample.</returns>
		public ulong NextULong()
		{
			return NextULongInner();
		}

		/// <summary>
		/// Returns a random boolean sampled from the uniform discrete distribution {false, true}, i.e., a fair coin flip.
		/// </summary>
		/// <returns>A new random sample.</returns>
		/// <remarks>
		/// Returns a sample the Bernoulli distribution with p = 0.5; also known as a a fair coin flip.
		/// </remarks>
		public bool NextBool()
		{
			return (NextULongInner() & 0x8000000000000000uL) != 0;
		}

		/// <summary>
		/// Returns a random <see cref="T:System.Single" /> sampled from the uniform distribution with interval [0, 1),
		/// i.e., inclusive of 0.0 and exclusive of 1.0.
		/// </summary>
		/// <returns>A new random sample, of type <see cref="T:System.Single" />.</returns>
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public float NextFloat()
		{
			return (float)(NextULongInner() >> 40) * 5.9604645E-08f;
		}

		private int NextInner(int maxValue)
		{
			return (int)(NextDouble() * (double)maxValue);
		}

		private long NextInner(long maxValue)
		{
			return (long)(NextDouble() * (double)maxValue);
		}

		public void FillSerializableState(SerializableRng rng)
		{
			rng.state0 = _s0;
			rng.state1 = _s1;
			rng.state2 = _s2;
			rng.state3 = _s3;
		}
	}
	public class PlayerRngSet
	{
		private readonly System.Collections.Generic.Dictionary<PlayerRngType, Rng> _rngs = new System.Collections.Generic.Dictionary<PlayerRngType, Rng>();

		/// <summary>
		/// Determines per-player reward generation. This means:
		/// * What cards are generated for rewards.
		/// * What potions are generated for rewards.
		/// * Whether or not the player gets a potion reward at all.
		/// </summary>
		public Rng Rewards => GetRng(PlayerRngType.Rewards);

		/// <summary>
		/// Determines what the different shops are selling.
		/// </summary>
		public Rng Shops => GetRng(PlayerRngType.Shops);

		/// <summary>
		/// Determines what a transformed card will roll into,
		/// </summary>
		public Rng Transformations => GetRng(PlayerRngType.Transformations);

		public ulong Seed { get; }

		public PlayerRngSet(ulong seed)
		{
			Seed = seed;
			PlayerRngType[] values = Enum.GetValues<PlayerRngType>();
			foreach (PlayerRngType playerRngType in values)
			{
				_rngs[playerRngType] = CreateRng(playerRngType);
			}
		}

		private Rng CreateRng(PlayerRngType rngType)
		{
			string name = StringHelper.SnakeCase(rngType.ToString());
			return new Rng(Seed, name);
		}

		public SerializablePlayerRngSet ToSerializable()
		{
			SerializablePlayerRngSet serializablePlayerRngSet = new SerializablePlayerRngSet
			{
				Seed = Seed
			};
			foreach (var (key, rng2) in _rngs)
			{
				serializablePlayerRngSet.Rngs[key] = rng2.ToSerializable();
			}
			return serializablePlayerRngSet;
		}

		public static PlayerRngSet FromSerializable(SerializablePlayerRngSet save)
		{
			PlayerRngSet playerRngSet = new PlayerRngSet(save.Seed);
			foreach (var (key, serializable) in save.Rngs)
			{
				playerRngSet._rngs[key] = new Rng(serializable);
			}
			return playerRngSet;
		}

		public void LoadFromSerializable(SerializablePlayerRngSet save)
		{
			if (Seed != save.Seed)
			{
				throw new NotImplementedException("RngSet seed should not change during the run!");
			}
			foreach (var (key, serializable) in save.Rngs)
			{
				_rngs[key].LoadFromSerializable(serializable);
			}
		}

		public Rng GetRng(PlayerRngType rngType)
		{
			return _rngs[rngType];
		}
	}
	/// <summary>
	/// A custom random class which allows predictable results when utilizing seeds.
	/// </summary>
	public class Rng
	{
		private int _counter;

		private readonly MegaRandom _random;

		/// <summary>
		/// A non-deterministic RNG instance. This will not produce the same results after saving and loading.
		/// Good for when we need to randomize things that don't impact gameplay.
		/// We use this instead of the GD.Rand functions because they're extremely slow when called from C#.
		/// </summary>
		public static Rng Chaotic { get; } = new Rng((ulong)DateTimeOffset.Now.ToUnixTimeSeconds());

		public Rng(ulong seed = 0uL)
		{
			_random = new MegaRandom(seed);
		}

		public Rng(SerializableRng serializable)
		{
			_counter = serializable.counter;
			_random = new MegaRandom(serializable);
		}

		/// <summary>
		/// An ergonomic constructor for creating an RNG for a specific piece of content during a run.
		/// This RNG will be unique among:
		///  - The run (using player.RunState.Rng)
		///  - The player SLOT
		///  - The ID of the content passed
		///
		/// This uses the player _slot index_, rather than the NetId, to ensure consistent results when playing a daily run.
		/// Because it only uses the three things above, if the player sees the same piece of content again this run, the
		/// RNG will return the same results. If that is a possibility, pass in a <paramref name="mixin" />.
		/// </summary>
		public Rng(Player player, ModelId id, ulong mixin = 0uL)
			: this((ulong)((long)player.RunState.Rng.Seed + (long)player.RunState.GetPlayerSlotIndex(player) + (long)StringHelper.GetDeterministicHashCode(id.Entry)) + mixin)
		{
		}

		public Rng(ulong seed, string name)
			: this(seed + StringHelper.GetDeterministicHashCode(name))
		{
		}

		/// <summary>
		/// Load RNG state from serializable.
		/// Use this when you need to keep the old instance's references intact.
		/// </summary>
		public void LoadFromSerializable(SerializableRng serializable)
		{
			_counter = serializable.counter;
			_random.Reinitialise(serializable);
		}

		/// <summary>
		/// Returns true or false. 50/50
		/// </summary>
		public bool NextBool()
		{
			_counter++;
			return _random.Next(2) == 0;
		}

		/// <summary>
		/// Get a random integer between 0 (inclusive) and maxExclusive.
		/// </summary>
		/// <param name="maxExclusive">1 higher than the highest allowed int.</param>
		/// <returns>Random integer.</returns>
		public int NextInt(int maxExclusive = int.MaxValue)
		{
			_counter++;
			return _random.Next(maxExclusive);
		}

		/// <summary>
		/// Get a random integer between minInclusive and maxExclusive.
		/// </summary>
		/// <param name="minInclusive">Lowest allowed number.</param>
		/// <param name="maxExclusive">1 higher than the maximum allowed number.</param>
		/// <returns>Random integer.</returns>
		public int NextInt(int minInclusive, int maxExclusive)
		{
			if (minInclusive >= maxExclusive)
			{
				throw new ArgumentOutOfRangeException("minInclusive", "Minimum must be lower than maximum.");
			}
			_counter++;
			return _random.Next(minInclusive, maxExclusive);
		}

		/// <summary>
		/// Get a random integer between 0 (inclusive) and maxExclusive.
		/// </summary>
		/// <param name="maxExclusive">1 higher than the highest allowed int.</param>
		/// <returns>Random integer.</returns>
		public uint NextUnsignedInt(uint maxExclusive = uint.MaxValue)
		{
			return NextUnsignedInt(0u, maxExclusive);
		}

		/// <summary>
		/// Get a random integer between minInclusive and maxInclusive.
		/// </summary>
		/// <param name="minInclusive">Lowest allowed number.</param>
		/// <param name="maxExclusive">1 higher than the maximum allowed number.</param>
		/// <returns>Random integer.</returns>
		public uint NextUnsignedInt(uint minInclusive, uint maxExclusive)
		{
			if (minInclusive >= maxExclusive)
			{
				throw new ArgumentOutOfRangeException("minInclusive", "Minimum must be lower than maximum.");
			}
			_counter++;
			double num = _random.NextDouble();
			double num2 = maxExclusive - minInclusive;
			uint num3 = (uint)(num * num2);
			return minInclusive + num3;
		}

		public ulong NextUnsignedLong()
		{
			_counter++;
			return _random.NextULong();
		}

		public ulong NextUnsignedLong(ulong maxExclusive)
		{
			if (maxExclusive == ulong.MaxValue)
			{
				return NextUnsignedLong();
			}
			return NextUnsignedLong(0uL, maxExclusive);
		}

		public ulong NextUnsignedLong(ulong minInclusive, ulong maxExclusive)
		{
			if (minInclusive >= maxExclusive)
			{
				throw new ArgumentOutOfRangeException("minInclusive", "Minimum must be lower than maximum.");
			}
			_counter++;
			double num = _random.NextDouble();
			double num2 = maxExclusive - minInclusive;
			ulong num3 = (ulong)(num * num2);
			return minInclusive + num3;
		}

		/// <summary>
		/// Get a random floating-point between 0 and max.
		/// </summary>
		/// <param name="max">Highest allowed number.</param>
		/// <returns>Random float.</returns>
		public float NextFloat(float max = 1f)
		{
			return NextFloat(0f, max);
		}

		/// <summary>
		/// Get a random floating-point number between min and max.
		/// </summary>
		/// <param name="min">Lowest allowed number.</param>
		/// <param name="max">Highest allowed number.</param>
		/// <returns>Random float.</returns>
		public float NextFloat(float min, float max)
		{
			if (min > max)
			{
				throw new ArgumentOutOfRangeException("min", "Minimum must not be higher than maximum.");
			}
			_counter++;
			return (float)(_random.NextDouble() * (double)(max - min) + (double)min);
		}

		/// <summary>
		/// Get a random double-precision (double) between 0.0 (inclusive) and 1.0 (exclusive).
		/// </summary>
		/// <returns>Random double.</returns>
		public double NextDouble()
		{
			_counter++;
			return _random.NextDouble();
		}

		/// <summary>
		/// Get a random double-precision floating-point number between 0 and 1.
		/// </summary>
		/// <returns>Random double.</returns>
		public double NextDouble(double min, double max)
		{
			if (min > max)
			{
				throw new ArgumentOutOfRangeException("min", "Minimum must not be higher than maximum.");
			}
			_counter++;
			return _random.NextDouble() * (max - min) + min;
		}

		public float NextGaussianFloat(float mean = 0f, float stdDev = 1f, float min = 0f, float max = 1f)
		{
			return (float)NextGaussianDouble(mean, stdDev, min, max);
		}

		/// <summary>
		/// Generate a random floating-point number with a Gaussian distribution between min and max with the specified mean
		/// and standard deviation.
		/// See https://en.wikipedia.org/wiki/Normal_distribution for more on Gaussian distributions.
		/// </summary>
		/// <param name="mean">Mean for the Gaussian distribution.</param>
		/// <param name="stdDev">Standard deviation for the Gaussian distribution.</param>
		/// <param name="min">Lowest allowed number.</param>
		/// <param name="max">Highest allowed number.</param>
		/// <returns>Random double with a Gaussian distribution.</returns>
		public double NextGaussianDouble(double mean = 0.0, double stdDev = 1.0, double min = 0.0, double max = 1.0)
		{
			if (min > max)
			{
				throw new ArgumentOutOfRangeException("min", "Minimum must not be higher than maximum.");
			}
			if ((mean < 0.0 || mean > 1.0) ? true : false)
			{
				throw new ArgumentOutOfRangeException("mean", mean, "Mean must be within [0, 1].");
			}
			double num4;
			do
			{
				double d = 1.0 - NextDouble();
				double num = 1.0 - NextDouble();
				double num2 = Math.Sqrt(-2.0 * Math.Log(d));
				double d2 = Math.PI * 2.0 * num;
				double num3 = num2 * Math.Cos(d2);
				num4 = mean + num3 * stdDev;
			}
			while ((num4 < 0.0 || num4 > 1.0) ? true : false);
			return num4 * (max - min) + min;
		}

		/// <summary>
		/// Returns a random number within a normal distribution.
		/// This is used as part of the algorithm for location assignment.
		/// <param name="mean">Mean for the Gaussian distribution.</param>
		/// <param name="stdDev">Standard deviation for the Gaussian distribution.</param>
		/// <param name="min">Lowest allowed number.</param>
		/// <param name="max">Highest allowed number.</param>
		/// <returns></returns>
		/// </summary>
		public int NextGaussianInt(int mean, int stdDev, int min, int max)
		{
			if (min > max)
			{
				throw new ArgumentOutOfRangeException("min", "Minimum must not be higher than maximum.");
			}
			if (mean < min || mean > max)
			{
				throw new ArgumentOutOfRangeException("mean", mean, "Mean must be within [min, max].");
			}
			int num3;
			do
			{
				double d = 1.0 - NextDouble();
				double num = 1.0 - NextDouble();
				double num2 = Math.Sqrt(-2.0 * Math.Log(d)) * Math.Sin(Math.PI * 2.0 * num);
				double a = (double)mean + (double)stdDev * num2;
				num3 = (int)Math.Round(a);
			}
			while (num3 < min || num3 > max);
			return num3;
		}

		/// <summary>
		/// Get a random item from the specified set of items.
		/// </summary>
		/// <param name="items">Set of items to pull from.</param>
		/// <typeparam name="T">Type of items contained in the set.</typeparam>
		/// <returns>Random item.</returns>
		public T? NextItem<T>(IEnumerable<T> items)
		{
			IEnumerable<T> source = (items as T[]) ?? items.ToArray();
			int num = source.Count();
			if (num == 0)
			{
				return default(T);
			}
			int index = NextInt(0, num);
			return source.ElementAt(index);
		}

		/// <summary>
		/// Get a random item from the specified set of items, respecting a specified weighting function.
		/// </summary>
		/// <param name="items">Set of items to pull from.</param>
		/// <param name="weightFetcher">Function to determine which items should be returned more/less often.</param>
		/// <typeparam name="T">Type of items contained in the set.</typeparam>
		/// <returns>Random item.</returns>
		public T? WeightedNextItem<T>(IEnumerable<T> items, Func<T?, float> weightFetcher)
		{
			return WeightedNextItem<T>(NextFloat(), items, weightFetcher, default(T));
		}

		/// <summary>
		/// Get a random item from the specified set of items, respecting a specified weighting function.
		/// </summary>
		/// <param name="randInput">Floating-point number between 0 and 1 to use for randomness.</param>
		/// <param name="items">Set of items to pull from.</param>
		/// <param name="weightFetcher">Function to determine which items should be returned more/less often.</param>
		/// <param name="fallback">Element to return if the weighting function fails to grab an item.</param>
		/// <typeparam name="T">Type of items contained in the set.</typeparam>
		/// <returns>Random item.</returns>
		public static T WeightedNextItem<T>(float randInput, IEnumerable<T> items, Func<T, float> weightFetcher, T fallback)
		{
			float num = items.Sum(weightFetcher);
			float num2 = randInput * num;
			foreach (T item in items)
			{
				num2 -= weightFetcher(item);
				if (num2 <= 0f)
				{
					return item;
				}
			}
			return fallback;
		}

		/// <summary>
		/// Shuffles a list in place using the Fisher-Yates algorithm.
		/// </summary>
		/// <param name="list">The list to shuffle.</param>
		/// <typeparam name="T">Type of items in the list.</typeparam>
		public void Shuffle<T>(IList<T> list)
		{
			for (int num = list.Count - 1; num > 0; num--)
			{
				int num2 = NextInt(num + 1);
				int index = num;
				int index2 = num2;
				T value = list[num2];
				T value2 = list[num];
				list[index] = value;
				list[index2] = value2;
			}
		}

		public SerializableRng ToSerializable()
		{
			SerializableRng serializableRng = new SerializableRng
			{
				counter = _counter
			};
			_random.FillSerializableState(serializableRng);
			return serializableRng;
		}
	}
}
namespace MegaCrit.Sts2.Core.Platform
{
	/// <summary>
	/// Controls achievement unlocking.
	/// </summary>
	public static class AchievementsUtil
	{
		private static readonly IAchievementStrategy _platform = new NullAchievementStrategy();

		public static event Action? AchievementsChanged;

		/// <summary>
		/// Unlocks an achievement on the current platform and profile.
		/// Remember that the player can have multiple profiles per platform account. This unlocks the achievement on the
		/// profile's progress.save, as well as on the platform account if the account does not yet have it.
		/// </summary>
		/// <param name="achievement">Achievement to unlock.</param>
		/// <param name="localPlayer">
		/// Optional local player from when the achievement was unlocked.
		/// Will be null when unlocked outside a run (like on the main menu or after game over).
		/// </param>
		public static void Unlock(Achievement achievement, Player? localPlayer)
		{
		}

		/// <summary>
		/// Revokes an achievement from the current player profile.
		/// Should only be used for debugging.
		/// </summary>
		public static void Revoke(Achievement achievement)
		{
			if (IsUnlocked(achievement))
			{
				Log.Debug($"Revoking achievement: {achievement}");
				_platform.Revoke(achievement);
				if (SaveManager.Instance.Progress.RemoveUnlockedAchievement(achievement))
				{
					SaveManager.Instance.SaveProgressFile();
				}
				AchievementsChanged?.Invoke();
			}
		}

		/// <summary>
		/// Returns whether an achievement is unlocked on the current player profile.
		/// Note that this does _not_ tell you whether the achievement is unlocked on the player's platform account. There
		/// is likely no scenario in which we need that, but if we do, add a new API.
		/// </summary>
		public static bool IsUnlocked(Achievement achievement)
		{
