namespace MegaCrit.Sts2.Core.Platform.Steam
{
	public enum SteamDisconnectionReason
	{
		None = 0,
		AppGeneric = 1000,
		AppInternalError = 1202,
		AppException = 2000,
		LocalMin = 3000,
		RunningInOfflineMode = 3001,
		ManyRelayConnectivity = 3002,
		HostedServerPrimaryRelay = 3003,
		NetworkConfig = 3004,
		LocalRights = 3005,
		LocalMax = 3999,
		RemoteTimeout = 4001,
		BadCrypt = 4002,
		BadCert = 4003,
		NotLoggedIn = 4004,
		NotRunningApp = 4005,
		BadProtocolVersion = 4006,
		MiscGeneric = 5001,
		InternalError = 5002,
		MiscTimeout = 5003,
		RelayConnectivity = 5004,
		SteamConnectivity = 5005,
		NoRelaySessions = 5006,
		RendezvousTimeout = 5008,
		RelayReceivedUnexpectedNoConnectionPacket = 5010
	}
	public static class SteamDisconnectionReasonExtensions
	{
		public static SteamDisconnectionReason ToSteam(this NetError reason)
		{
			return (SteamDisconnectionReason)(1000 + reason);
		}

		public static NetError ToApp(this SteamDisconnectionReason steamReason)
		{
			if (steamReason >= SteamDisconnectionReason.AppGeneric && steamReason <= (SteamDisconnectionReason)1999)
			{
				NetError netError = (NetError)(steamReason - 1000);
				if (!Enum.IsDefined(netError))
				{
					Log.Error($"Received unknown application error from Steam: {steamReason}");
					return NetError.UnknownNetworkError;
				}
				return netError;
			}
			if (steamReason >= SteamDisconnectionReason.LocalMin)
			{
				if (steamReason > SteamDisconnectionReason.LocalMax)
				{
					switch (steamReason)
					{
					case SteamDisconnectionReason.RelayConnectivity:
					case SteamDisconnectionReason.SteamConnectivity:
						break;
					case SteamDisconnectionReason.RemoteTimeout:
					case SteamDisconnectionReason.MiscTimeout:
						return NetError.Timeout;
					case SteamDisconnectionReason.RendezvousTimeout:
					case SteamDisconnectionReason.RelayReceivedUnexpectedNoConnectionPacket:
						return NetError.TryAgainLater;
					case SteamDisconnectionReason.BadCrypt:
					case SteamDisconnectionReason.BadCert:
						return NetError.SecureConnectionFailed;
					default:
						goto IL_00c0;
					}
				}
				return NetError.NoInternet;
			}
			if (steamReason == SteamDisconnectionReason.None)
			{
				return NetError.None;
			}
			goto IL_00c0;
			IL_00c0:
			return NetError.UnknownNetworkError;
		}
	}
	public static class SteamInitializer
	{
		public const ulong steamAppId = 2868840uL;

		private static CancellationTokenSource _disconnectCts = new CancellationTokenSource();

		public static bool Initialized { get; private set; }

		/// <summary>
		/// Initialization result. Failure code if Initialization was called and Initialized is false.
		/// </summary>
		public static ESteamAPIInitResult? InitResult { get; private set; }

		public static string? InitErrorMessage { get; private set; }

		/// <summary>
		/// Cancellation token that is cancelled when Steam disconnects. Pass this to SteamCallResult
		/// to prevent async Steam API calls from hanging indefinitely when the callback pump stops.
		/// </summary>
		public static CancellationToken DisconnectToken => _disconnectCts.Token;

		public static event Action? SteamNoLongerRunning;

		private static nint SteamDebugResolver(string libraryName, Assembly assembly, DllImportSearchPath? searchPath)
		{
			if (libraryName != "steam_api" && libraryName != "steam_api64")
			{
				return IntPtr.Zero;
			}
			if (OS.HasFeature("editor"))
			{
				string text;
				switch (OS.GetName())
				{
				case "Windows":
					text = "steam/SteamApi/steam_api64.dll";
					break;
				case "macOS":
					text = "steam/SteamApi/libsteam_api.dylib";
					break;
				case "FreeBSD":
				case "OpenBSD":
				case "Linux":
				case "NetBSD":
				case "BSD":
					text = "steam/SteamApi/libsteam_api.so";
					break;
				default:
					text = null;
					break;
				}
				string text2 = text;
				if (text2 != null)
				{
					return NativeLibrary.Load(text2);
				}
			}
			return IntPtr.Zero;
		}

		public static bool Initialize(Node node)
		{
			NativeLibrary.SetDllImportResolver(Assembly.GetAssembly(typeof(SteamAPI)), SteamDebugResolver);
			Log.Info("Steamworks: attempting initialization...");
			for (int i = 0; i < 3; i++)
			{
				if (i > 0)
				{
					Thread.Sleep(100);
					Log.Info($"Steam initialization retry attempt {i}");
				}
				Initialized = InitializeInternal();
				if (Initialized)
				{
					break;
				}
			}
			if (Initialized)
			{
				SteamNetworkingUtils.InitRelayNetworkAccess();
				TaskHelper.RunSafely(RunCallbacksAsync(node));
			}
			return Initialized;
		}

		private static bool InitializeInternal()
		{
			try
			{
				Log.Info($"Steam is running: {SteamAPI.IsSteamRunning()}");
				InitResult = SteamAPI.InitEx(out var OutSteamErrMsg);
				InitErrorMessage = OutSteamErrMsg;
				if (InitResult == ESteamAPIInitResult.k_ESteamAPIInitResult_OK)
				{
					Log.Info("Steamworks initialization succeeded!");
					return true;
				}
				Log.Error($"Steamworks initialization failed! Result: {InitResult}, message: {InitErrorMessage}");
			}
			catch (Exception ex)
			{
				Log.Error($"Steamworks initialization threw an exception: {ex}");
				InitResult = null;
				InitErrorMessage = ex.Message;
			}
			return false;
		}

		private static async Task RunCallbacksAsync(Node node)
		{
			while (Initialized)
			{
				await node.AwaitProcessFrame();
				if (!SteamAPI.IsSteamRunning())
				{
					Log.Warn("Steam is no longer running. Stopping callbacks.");
					Initialized = false;
					_disconnectCts.Cancel();
					SteamNoLongerRunning?.Invoke();
					break;
				}
				SteamAPI.RunCallbacks();
			}
		}

		public static void Uninitialize()
		{
			if (!Initialized)
			{
				return;
			}
			Log.Info("Steamworks: shutting down...");
			try
			{
				SteamAPI.Shutdown();
				Log.Info("Steamworks shutdown succeeded!");
			}
			catch (Exception value)
			{
				Log.Error($"Steamworks shutdown threw an exception: {value}");
			}
			finally
			{
				Initialized = false;
			}
		}
	}
	/// <summary>
	/// Responsible for handling Steam-related requests to join multiplayer sessions coming from outside the game.
	/// </summary>
	public class SteamJoinCallbackHandler : IDisposable
	{
		private readonly Callback<GameLobbyJoinRequested_t> _steamJoinCallback;

		public SteamJoinCallbackHandler()
		{
			_steamJoinCallback = new Callback<GameLobbyJoinRequested_t>(OnSteamLobbyJoinRequested);
		}

		/// <summary>
		/// If the game is not yet launched and the player accepts an invite, Steam launches the game with a specific command
		/// line argument. This method handles joining the multiplayer session. It should be called relatively early after
		/// the game is launched.
		/// </summary>
		public void CheckForCommandLineJoin()
		{
			if (CommandLineHelper.TryGetValue("+connect_lobby", out string value))
			{
				ulong num = ulong.Parse(value);
				Log.Info($"Joining to host via Steam invite that caused the game to launch. Lobby id: {num}");
				TaskHelper.RunSafely(JoinToHost(num, null));
			}
		}

		public void Dispose()
		{
			_steamJoinCallback.Dispose();
		}

		private void OnSteamLobbyJoinRequested(GameLobbyJoinRequested_t lobbyJoinRequest)
		{
			Log.Info($"Joining to host via Steam invite. Lobby: {lobbyJoinRequest.m_steamIDLobby.m_SteamID} player: {lobbyJoinRequest.m_steamIDFriend.m_SteamID}");
			TaskHelper.RunSafely(JoinToHost(lobbyJoinRequest.m_steamIDLobby.m_SteamID, lobbyJoinRequest.m_steamIDFriend.m_SteamID));
		}

		private static async Task JoinToHost(ulong lobbyId, ulong? playerId, IClientConnectionInitializer? connInitializer = null)
		{
			if (NGame.Instance.RootSceneContainer.CurrentScene is NMultiplayerTest nMultiplayerTest)
			{
				if (connInitializer == null)
				{
					connInitializer = SteamClientConnectionInitializer.FromLobby(lobbyId);
				}
				await nMultiplayerTest.JoinToHost(connInitializer);
				return;
			}
			if (RunManager.Instance.IsInProgress)
			{
				LocString locString = new LocString("gameplay_ui", "QUIT_AND_JOIN_CONFIRMATION.body");
				playerId.GetValueOrDefault();
				if (!playerId.HasValue)
				{
					ulong steamID = SteamMatchmaking.GetLobbyOwner(new CSteamID(lobbyId)).m_SteamID;
					playerId = steamID;
				}
				locString.Add("host", PlatformUtil.GetPlayerName(PlatformType.Steam, playerId.Value));
				NGenericPopup nGenericPopup = NGenericPopup.Create();
				NModalContainer.Instance.Add(nGenericPopup);
				if (!(await nGenericPopup.WaitForConfirmation(locString, new LocString("gameplay_ui", "QUIT_AND_JOIN_CONFIRMATION.header"), new LocString("gameplay_ui", "QUIT_AND_JOIN_CONFIRMATION.cancel"), new LocString("gameplay_ui", "QUIT_AND_JOIN_CONFIRMATION.confirm"))))
				{
					return;
				}
			}
			if (NGame.Instance.MainMenu == null)
			{
				await NGame.Instance.ReturnToMainMenu();
			}
			while (NGame.Instance.MainMenu?.SubmenuStack.Peek() != null)
			{
				NGame.Instance.MainMenu?.SubmenuStack.Pop();
			}
			if (connInitializer == null)
			{
				connInitializer = SteamClientConnectionInitializer.FromLobby(lobbyId);
			}
			await NGame.Instance.MainMenu.JoinGame(connInitializer);
		}
	}
