	public class SteamLeaderboardStrategy : ILeaderboardStrategy
	{
		private readonly PacketWriter _writer = new PacketWriter();

		private readonly int[] _cachedUserDetails = new int[64];

		private readonly CSteamID[] _cachedUsers = new CSteamID[10];

		public PlatformType Platform => PlatformType.Steam;

		public async Task<ILeaderboardHandle> GetOrCreateLeaderboard(string name, CancellationToken cancelToken)
		{
			SteamAPICall_t call = SteamUserStats.FindOrCreateLeaderboard(name, ELeaderboardSortMethod.k_ELeaderboardSortMethodDescending, ELeaderboardDisplayType.k_ELeaderboardDisplayTypeNumeric);
			using SteamCallResult<LeaderboardFindResult_t> callResult = new SteamCallResult<LeaderboardFindResult_t>(call, cancelToken);
			LeaderboardFindResult_t leaderboardFindResult_t = await callResult.Task;
			if (cancelToken.IsCancellationRequested)
			{
				throw new TaskCanceledException();
			}
			if (leaderboardFindResult_t.m_bLeaderboardFound == 0)
			{
				throw new InvalidOperationException("Steam FindOrCreateLeaderboard returned 0 from leaderboard found!");
			}
			return new SteamLeaderboardHandle
			{
				leaderboard = leaderboardFindResult_t.m_hSteamLeaderboard
			};
		}

		public async Task<ILeaderboardHandle?> GetLeaderboard(string name, CancellationToken cancelToken)
		{
			SteamAPICall_t call = SteamUserStats.FindLeaderboard(name);
			using SteamCallResult<LeaderboardFindResult_t> callResult = new SteamCallResult<LeaderboardFindResult_t>(call, cancelToken);
			LeaderboardFindResult_t leaderboardFindResult_t = await callResult.Task;
			if (cancelToken.IsCancellationRequested || leaderboardFindResult_t.m_bLeaderboardFound == 0)
			{
				return null;
			}
			return new SteamLeaderboardHandle
			{
				leaderboard = leaderboardFindResult_t.m_hSteamLeaderboard
			};
		}

		public async Task UploadLocalScore(ILeaderboardHandle handleInterface, int score, IReadOnlyList<ulong> userIds)
		{
			int[] pScoreDetails = PackScoreDetails(userIds, out var scoreDetailsCount);
			SteamLeaderboardHandle steamLeaderboardHandle = (SteamLeaderboardHandle)handleInterface;
			SteamAPICall_t call = SteamUserStats.UploadLeaderboardScore(steamLeaderboardHandle.leaderboard, ELeaderboardUploadScoreMethod.k_ELeaderboardUploadScoreMethodForceUpdate, score, pScoreDetails, scoreDetailsCount);
			using SteamCallResult<LeaderboardScoreUploaded_t> callResult = new SteamCallResult<LeaderboardScoreUploaded_t>(call, SteamInitializer.DisconnectToken);
			if ((await callResult.Task).m_bSuccess == 0)
			{
				throw new IOException("Steam score upload failed!");
			}
		}

		public async Task<List<LeaderboardEntry>> QueryLeaderboard(ILeaderboardHandle handleInterface, LeaderboardQueryType type, int startIndex, int count, CancellationToken cancelToken = default(CancellationToken))
		{
			SteamLeaderboardHandle steamLeaderboardHandle = (SteamLeaderboardHandle)handleInterface;
			int num = startIndex;
			if (type == LeaderboardQueryType.Global)
			{
				num++;
			}
			SteamAPICall_t call = SteamUserStats.DownloadLeaderboardEntries(steamLeaderboardHandle.leaderboard, LeaderboardDataRequestTypeFrom(type), num, num + count - 1);
			using SteamCallResult<LeaderboardScoresDownloaded_t> callResult = new SteamCallResult<LeaderboardScoresDownloaded_t>(call, cancelToken);
			LeaderboardScoresDownloaded_t leaderboardScoresDownloaded_t = await callResult.Task;
			List<LeaderboardEntry> list = new List<LeaderboardEntry>();
			if (cancelToken.IsCancellationRequested)
			{
				return new List<LeaderboardEntry>();
			}
			int num2 = 0;
			int num3 = leaderboardScoresDownloaded_t.m_cEntryCount;
			if (type == LeaderboardQueryType.FriendsOnly)
			{
				num2 = startIndex;
				num3 = Math.Min(startIndex + count, leaderboardScoresDownloaded_t.m_cEntryCount);
			}
			if (num2 >= num3)
			{
				return new List<LeaderboardEntry>();
			}
			for (int i = num2; i < num3; i++)
			{
				if (!SteamUserStats.GetDownloadedLeaderboardEntry(leaderboardScoresDownloaded_t.m_hSteamLeaderboardEntries, i, out var pLeaderboardEntry, _cachedUserDetails, _cachedUserDetails.Length))
				{
					throw new InvalidOperationException($"Failed to download leaderboard entry at index {i}. Start result index: {num2}. result count: {num3}");
				}
				list.Add(LeaderboardEntryFromSteamType(pLeaderboardEntry));
			}
			return list;
		}

		public async Task<List<LeaderboardEntry>> QueryLeaderboardForUsers(ILeaderboardHandle handleInterface, IReadOnlyList<ulong> userIds, CancellationToken cancelToken = default(CancellationToken))
		{
			SteamLeaderboardHandle steamLeaderboardHandle = (SteamLeaderboardHandle)handleInterface;
			for (int i = 0; i < userIds.Count; i++)
			{
				_cachedUsers[i] = new CSteamID(userIds[i]);
			}
			SteamAPICall_t call = SteamUserStats.DownloadLeaderboardEntriesForUsers(steamLeaderboardHandle.leaderboard, _cachedUsers, userIds.Count);
			using SteamCallResult<LeaderboardScoresDownloaded_t> callResult = new SteamCallResult<LeaderboardScoresDownloaded_t>(call, cancelToken);
			LeaderboardScoresDownloaded_t leaderboardScoresDownloaded_t = await callResult.Task;
			List<LeaderboardEntry> list = new List<LeaderboardEntry>();
			if (cancelToken.IsCancellationRequested)
			{
				return new List<LeaderboardEntry>();
			}
			for (int j = 0; j < leaderboardScoresDownloaded_t.m_cEntryCount; j++)
			{
				if (!SteamUserStats.GetDownloadedLeaderboardEntry(leaderboardScoresDownloaded_t.m_hSteamLeaderboardEntries, j, out var pLeaderboardEntry, _cachedUserDetails, _cachedUserDetails.Length))
				{
					throw new InvalidOperationException($"Failed to download leaderboard entry at index {j}");
				}
				list.Add(LeaderboardEntryFromSteamType(pLeaderboardEntry));
			}
			return list;
		}

		public int GetLeaderboardEntryCount(ILeaderboardHandle handleInterface)
		{
			SteamLeaderboardHandle steamLeaderboardHandle = (SteamLeaderboardHandle)handleInterface;
			return SteamUserStats.GetLeaderboardEntryCount(steamLeaderboardHandle.leaderboard);
		}

		private LeaderboardEntry LeaderboardEntryFromSteamType(LeaderboardEntry_t entry)
		{
			return new LeaderboardEntry
			{
				id = entry.m_steamIDUser.m_SteamID,
				name = SteamFriends.GetFriendPersonaName(entry.m_steamIDUser),
				rank = entry.m_nGlobalRank - 1,
				score = entry.m_nScore,
				userIds = UnpackScoreDetails(_cachedUserDetails, entry.m_cDetails)
			};
		}

		private ELeaderboardDataRequest LeaderboardDataRequestTypeFrom(LeaderboardQueryType type)
		{
			return type switch
			{
				LeaderboardQueryType.Global => ELeaderboardDataRequest.k_ELeaderboardDataRequestGlobal, 
				LeaderboardQueryType.AroundUser => ELeaderboardDataRequest.k_ELeaderboardDataRequestGlobalAroundUser, 
				LeaderboardQueryType.FriendsOnly => ELeaderboardDataRequest.k_ELeaderboardDataRequestFriends, 
				LeaderboardQueryType.None => throw new InvalidOperationException("LeaderboardQueryType.None should never be passed to an API!"), 
			};
		}

		private int[] PackScoreDetails(IReadOnlyList<ulong> userIds, out int scoreDetailsCount)
		{
			_writer.Reset();
			foreach (ulong userId in userIds)
			{
				_writer.WriteULong(userId);
			}
			scoreDetailsCount = (int)Math.Ceiling((float)_writer.BitPosition / 32f);
			if (scoreDetailsCount > 64)
			{
				throw new InvalidOperationException($"Tried to write {userIds.Count} user IDs into {scoreDetailsCount} integers, exceeding the max limit ({64})!");
			}
			for (int i = 0; i < scoreDetailsCount; i++)
			{
				_cachedUserDetails[i] = BitConverter.ToInt32(_writer.Buffer, i * 4);
			}
			return _cachedUserDetails;
		}

		private List<ulong> UnpackScoreDetails(int[] scoreDetails, int scoreDetailsCount)
		{
			_writer.Reset();
			for (int i = 0; i < scoreDetailsCount; i++)
			{
				_writer.WriteInt(scoreDetails[i]);
			}
			PacketReader packetReader = new PacketReader();
			packetReader.Reset(_writer.Buffer);
			int num = (int)Math.Floor((float)_writer.BitPosition / 64f);
			List<ulong> list = new List<ulong>();
			for (int j = 0; j < num; j++)
			{
				list.Add(packetReader.ReadULong());
			}
			return list;
		}
	}
	public class SteamPlatformUtilStrategy : IPlatformUtilStrategy
	{
		private const string _richPresenceDisplayKey = "steam_display";

		private const string _richPresenceGroupKey = "steam_player_group";

		private const string _richPresenceGroupSizeKey = "steam_player_group_size";

		private PlatformBranch? _branch;

		private bool _isPlatformOverlayOpen;

		private Callback<GameOverlayActivated_t>? _steamOverlayCallback;

		public bool SupportsInviteDialog => true;

		public bool IsPlatformOverlayOpen => _isPlatformOverlayOpen;

		public SteamPlatformUtilStrategy()
		{
			_steamOverlayCallback = Callback<GameOverlayActivated_t>.Create(OnSteamOverlayToggled);
		}

		~SteamPlatformUtilStrategy()
		{
			_steamOverlayCallback?.Dispose();
		}

		public string GetPlayerName(ulong playerId)
		{
			string text = ((playerId != SteamUser.GetSteamID().m_SteamID) ? SteamFriends.GetFriendPersonaName(new CSteamID(playerId)) : SteamFriends.GetPersonaName());
			if (!string.IsNullOrEmpty(text))
			{
				return text;
			}
			return playerId.ToString();
		}

		public ulong GetLocalPlayerId()
		{
			return SteamUser.GetSteamID().m_SteamID;
		}

		public Task<IEnumerable<ulong>> GetFriendsWithOpenLobbies()
		{
			List<ulong> list = new List<ulong>();
			int friendCount = SteamFriends.GetFriendCount(EFriendFlags.k_EFriendFlagImmediate);
			for (int i = 0; i < friendCount; i++)
			{
				CSteamID friendByIndex = SteamFriends.GetFriendByIndex(i, EFriendFlags.k_EFriendFlagImmediate);
				if (SteamFriends.GetFriendGamePlayed(friendByIndex, out var pFriendGameInfo) && pFriendGameInfo.m_gameID.m_GameID == 2868840 && pFriendGameInfo.m_steamIDLobby.IsValid())
				{
					list.Add(friendByIndex.m_SteamID);
				}
			}
			return Task.FromResult((IEnumerable<ulong>)list);
		}

		public bool TryOpenInviteDialog(INetGameService netService)
		{
			if (!SteamUtils.IsOverlayEnabled())
			{
				Log.Warn("Tried to open invite dialog, but the player has disabled the steam overlay");
				return false;
			}
			CSteamID value;
			if (netService is INetHostGameService { NetHost: SteamHost { LobbyId: var lobbyId } netHost })
			{
				if (!lobbyId.HasValue)
				{
					Log.Warn("Tried to open invite dialog but steam host is not yet in a lobby");
					return false;
				}
				value = netHost.LobbyId.Value;
			}
			else
			{
				if (!(netService is INetClientGameService { NetClient: MegaCrit.Sts2.Core.Multiplayer.Transport.Steam.SteamClient { LobbyId: var lobbyId2 } netClient }))
				{
					throw new InvalidOperationException($"Tried to open invite dialog for non-steam net service {netService}");
				}
				if (!lobbyId2.HasValue)
				{
					Log.Warn("Tried to open invite dialog but steam client is not yet in a lobby");
					return false;
				}
				value = netClient.LobbyId.Value;
			}
			SteamFriends.ActivateGameOverlayInviteDialog(value);
			return true;
		}

		public void OpenUrl(string url)
		{
			if (SteamUtils.IsOverlayEnabled())
			{
				SteamFriends.ActivateGameOverlayToWebPage(url);
			}
			else
			{
				OS.ShellOpen(url);
			}
		}

