		public List<NullLeaderboardFileEntry> entries = new List<NullLeaderboardFileEntry>();
	}
	public class NullLeaderboardFile : ISaveSchema
	{
		[JsonPropertyName("leaderboards")]
		public List<NullLeaderboard> leaderboards = new List<NullLeaderboard>();

		[JsonPropertyName("version")]
		public int SchemaVersion { get; set; }
	}
	public class NullLeaderboardFileEntry
	{
		[JsonPropertyName("name")]
		public required string name;

		[JsonPropertyName("score")]
		public int score;

		[JsonPropertyName("id")]
		public ulong id;

		[JsonPropertyName("other_ids")]
		public List<ulong> userIds = new List<ulong>();
