namespace MegaCrit.Sts2.Core.Odds
{
	public abstract class AbstractOdds(float initialValue, Rng rng)
	{
		protected readonly Rng _rng = rng;

		public float CurrentValue { get; protected set; } = initialValue;

		/// <summary>
		/// Sets CurrentValue. Should be used only in instances where we're loading the player from another source, such as
		/// multiplayer host.
		/// </summary>
		/// <param name="newValue">The new value.</param>
		public void OverrideCurrentValue(float newValue)
		{
			CurrentValue = newValue;
		}
	}
	public class CardRarityOdds : AbstractOdds
	{
		public static float regularCommonOdds = AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.615f, 0.6f);

		public const float regularUncommonOdds = 0.37f;

		public const float eliteUncommonOdds = 0.4f;

		public const float bossCommonOdds = 0f;

		public const float bossUncommonOdds = 0f;

		public const float bossRareOdds = 1f;

		public const float shopUncommonOdds = 0.37f;

		private const float _baseRarityOffset = -0.05f;

		private const float _maxRarityOffset = 0.4f;

		public float RarityGrowth => AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.005f, 0.01f);

		public static float RegularRareOdds => AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.0149f, 0.03f);

		public static float EliteCommonOdds => AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.549f, 0.5f);

		public static float EliteRareOdds => AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.05f, 0.1f);

		public static float ShopCommonOdds => AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.585f, 0.54f);

		public static float ShopRareOdds => AscensionHelper.GetValueIfAscension(AscensionLevel.Scarcity, 0.045f, 0.09f);

		/// <summary>
		/// For creating at the start of a run.
		/// </summary>
		/// <param name="rng">RNG to use for rolls.</param>
		public CardRarityOdds(Rng rng)
			: base(-0.05f, rng)
		{
		}

		/// <summary>
		/// For restoring from save.
		/// </summary>
		/// <param name="initialValue">Restored value at the saved spot in the run.</param>
		/// <param name="rng">RNG to use for rolls.</param>
		public CardRarityOdds(float initialValue, Rng rng)
			: base(initialValue, rng)
		{
		}

		/// <summary>
		/// Roll for what rarity of card should be generated.
		/// Using this will modify the odds of future generated card rarities.
		/// Use for things like encounter rewards.
		/// </summary>
		/// <param name="type">Odds type to roll for.</param>
		/// <returns>What rarity a generated card should be.</returns>
		public CardRarity Roll(CardRarityOddsType type)
		{
			CardRarity cardRarity = RollWithoutChangingFutureOdds(type, (type == CardRarityOddsType.BossEncounter) ? 0f : base.CurrentValue);
			if (cardRarity == CardRarity.Rare)
			{
				base.CurrentValue = -0.05f;
			}
			else
			{
				base.CurrentValue = Math.Min(base.CurrentValue + RarityGrowth, 0.4f);
			}
			return cardRarity;
		}

		public CardRarity RollWithoutChangingFutureOdds(CardRarityOddsType oddsType)
		{
			return RollWithoutChangingFutureOdds(oddsType, base.CurrentValue);
		}

		/// <summary>
		/// Roll for what rarity of card should be generated.
		/// Using this will NOT modify the odds of future generated card rarities.
		/// Use for things like shops.
		/// </summary>
		/// <param name="type">Odds type to roll for.</param>
		/// <param name="offset">offset for rare odds</param>
		/// <returns>What rarity a generated card should be.</returns>
		public CardRarity RollWithoutChangingFutureOdds(CardRarityOddsType type, float offset)
		{
			float num = _rng.NextFloat();
			float num2 = GetBaseOdds(type, CardRarity.Rare) + offset;
			float baseOdds = GetBaseOdds(type, CardRarity.Uncommon);
			Log.Info($"Card rarity: Rolled {num}, need < {num2} for rare (offset = {offset})");
			if (num < num2)
			{
				return CardRarity.Rare;
			}
			if (num < baseOdds + num2)
			{
				return CardRarity.Uncommon;
			}
			return CardRarity.Common;
		}

		/// <summary>
		/// Roll for what rarity of card should be generated.
		/// Using this will use only the base odds for the given card source.
		/// Used for some events.
		/// </summary>
		/// <param name="type">Odds type to roll for.</param>
		/// <returns>What rarity a generated card should be.</returns>
		public CardRarity RollWithBaseOdds(CardRarityOddsType type)
		{
			float baseOdds = GetBaseOdds(type, CardRarity.Rare);
			float baseOdds2 = GetBaseOdds(type, CardRarity.Uncommon);
			float num = _rng.NextFloat();
			if (num < baseOdds)
			{
				return CardRarity.Rare;
			}
			if (num < baseOdds2 + baseOdds)
			{
				return CardRarity.Uncommon;
			}
			return CardRarity.Common;
		}

		private static float GetBaseOdds(CardRarityOddsType type, CardRarity rarity)
		{
			return type switch
			{
				CardRarityOddsType.EliteEncounter => rarity switch
				{
					CardRarity.Common => EliteCommonOdds, 
					CardRarity.Uncommon => 0.4f, 
					CardRarity.Rare => EliteRareOdds, 
					_ => throw new ArgumentOutOfRangeException("rarity"), 
				}, 
				CardRarityOddsType.BossEncounter => rarity switch
				{
					CardRarity.Common => 0f, 
					CardRarity.Uncommon => 0f, 
					CardRarity.Rare => 1f, 
					_ => throw new ArgumentOutOfRangeException("rarity"), 
				}, 
				CardRarityOddsType.Shop => rarity switch
				{
					CardRarity.Common => ShopCommonOdds, 
					CardRarity.Uncommon => 0.37f, 
					CardRarity.Rare => ShopRareOdds, 
					_ => throw new ArgumentOutOfRangeException("rarity"), 
				}, 
				CardRarityOddsType.RegularEncounter => rarity switch
				{
					CardRarity.Common => regularCommonOdds, 
					CardRarity.Uncommon => 0.37f, 
					CardRarity.Rare => RegularRareOdds, 
					_ => throw new ArgumentOutOfRangeException("rarity"), 
				}, 
				CardRarityOddsType.Uniform => rarity switch
				{
					CardRarity.Common => 0.33f, 
					CardRarity.Uncommon => 0.33f, 
					CardRarity.Rare => 0.33f, 
					_ => throw new ArgumentOutOfRangeException("rarity"), 
				}, 
				_ => throw new ArgumentOutOfRangeException("type"), 
			};
		}
	}
	public class PlayerOddsSet
	{
		/// <summary>
		/// Manages the odds of rolling various rarities when generating cards (encounter rewards, shops, etc.) for each player.
		/// </summary>
		public CardRarityOdds CardRarity { get; private init; }

		/// <summary>
		/// Manages the odds of whether or not a potion drops after beating an encounter for each player.
		/// </summary>
		public PotionRewardOdds PotionReward { get; private init; }

		private PlayerOddsSet()
		{
		}

		public PlayerOddsSet(PlayerRngSet rng)
		{
			CardRarity = new CardRarityOdds(rng.Rewards);
			PotionReward = new PotionRewardOdds(rng.Rewards);
		}

		public SerializablePlayerOddsSet ToSerializable()
		{
			return new SerializablePlayerOddsSet
			{
				CardRarityOddsValue = CardRarity.CurrentValue,
				PotionRewardOddsValue = PotionReward.CurrentValue
			};
		}

		public static PlayerOddsSet FromSerializable(SerializablePlayerOddsSet save, PlayerRngSet rng)
		{
			return new PlayerOddsSet
			{
				CardRarity = new CardRarityOdds(save.CardRarityOddsValue, rng.Rewards),
				PotionReward = new PotionRewardOdds(save.PotionRewardOddsValue, rng.Rewards)
			};
		}

		public void LoadFromSerializable(SerializablePlayerOddsSet save)
		{
			CardRarity.OverrideCurrentValue(save.CardRarityOddsValue);
			PotionReward.OverrideCurrentValue(save.PotionRewardOddsValue);
		}
	}
	public class PotionRewardOdds : AbstractOdds
	{
		/// <summary>
		/// The percentage of normal combats that we expect to roll potions over the course of a run.
		/// While our rolling logic is more complex than this (to avoid streakiness and other game-feel reasons), we should
		/// converge on this percentage.
		/// </summary>
		public const float targetOdds = 0.5f;

		public const float eliteBonus = 0.25f;

		private const float _basePotionRewardOdds = 0.4f;

		/// <summary>
		/// For creating at the start of a run.
		/// </summary>
		/// <param name="rng">RNG to use for rolls.</param>
		public PotionRewardOdds(Rng rng)
			: base(0.4f, rng)
		{
		}

		/// <summary>
		/// For restoring from save.
		/// </summary>
		/// <param name="initialValue">Restored value at the saved spot in the run.</param>
		/// <param name="rng">RNG to use for rolls.</param>
		public PotionRewardOdds(float initialValue, Rng rng)
			: base(initialValue, rng)
		{
		}

		/// <summary>
		/// Roll for whether or not a potion should be included in a set of rewards.
		/// Using this will modify the odds of future potion rewards.
		/// </summary>
		/// <param name="player">The player who will receive the potential potion reward.</param>
		/// <param name="roomType">Room type for roll, affects bonus chance for potions.</param>
		/// <returns>Whether or not to give a potion reward.</returns>
		/// <remarks>
		/// This method implements a pity system where:
		/// - If a potion is rolled, future potion chances decrease by 10%
		/// - If a potion is not rolled, future potion chances increase by 10%
		/// - Elite rooms provide a 25% bonus chance for potions
		/// - The HookBus allows for external modification of potion reward odds
		/// </remarks>
		public bool Roll(Player player, RoomType roomType)
		{
			float currentValue = base.CurrentValue;
			if (Hook.ShouldForcePotionReward(player.RunState, player, roomType))
			{
				return true;
			}
			float num = ((roomType != RoomType.Elite) ? 0f : 0.25f);
			float num2 = num;
			float num3 = currentValue + num2 * 0.5f;
			float num4 = _rng.NextFloat();
			if (num4 < num3)
			{
				base.CurrentValue -= 0.1f;
				return true;
			}
			base.CurrentValue += 0.1f;
			return false;
		}
	}
	public class RunOddsSet
	{
		/// <summary>
		/// Manages the odds of what types of rooms are rolled when entering an unknown point.
		/// </summary>
		public UnknownMapPointOdds UnknownMapPoint { get; private init; }

		private RunOddsSet()
		{
		}

		public RunOddsSet(Rng unknownMapPointRng)
		{
			UnknownMapPoint = new UnknownMapPointOdds(unknownMapPointRng);
		}

		public SerializableRunOddsSet ToSerializable()
		{
			return new SerializableRunOddsSet
			{
				UnknownMapPointMonsterOddsValue = UnknownMapPoint.MonsterOdds,
				UnknownMapPointEliteOddsValue = UnknownMapPoint.EliteOdds,
				UnknownMapPointTreasureOddsValue = UnknownMapPoint.TreasureOdds,
				UnknownMapPointShopOddsValue = UnknownMapPoint.ShopOdds
			};
		}

		public static RunOddsSet FromSerializable(SerializableRunOddsSet save, Rng unknownMapPointRng)
		{
			return new RunOddsSet
			{
				UnknownMapPoint = new UnknownMapPointOdds(unknownMapPointRng)
				{
					MonsterOdds = save.UnknownMapPointMonsterOddsValue,
					EliteOdds = save.UnknownMapPointEliteOddsValue,
					TreasureOdds = save.UnknownMapPointTreasureOddsValue,
					ShopOdds = save.UnknownMapPointShopOddsValue
				}
			};
		}
	}
	/// <summary>
	/// Keeps track of the odds for different room types to be rolled when the player visits an unknown map point type.
	///
	/// Note: If a room type has negative odds, that means it should NEVER be rolled, and its odds shouldn't increase as
	/// other types are rolled. This is relevant for effects like the Deadly Enemies modifier.
	/// </summary>
	public class UnknownMapPointOdds : AbstractOdds
	{
		public const float baseMonsterOdds = 0.1f;

		public const float baseEliteOdds = -1f;

		public const float baseTreasureOdds = 0.02f;

		public const float baseShopOdds = 0.03f;

		private readonly System.Collections.Generic.Dictionary<RoomType, float> _baseOdds = new System.Collections.Generic.Dictionary<RoomType, float>
		{
			[RoomType.Monster] = 0.1f,
			[RoomType.Elite] = -1f,
			[RoomType.Treasure] = 0.02f,
			[RoomType.Shop] = 0.03f
		};

		/// <summary>
		/// Contains the odds of all non-Event rooms being rolled.
		/// If we roll higher than the sum of all these odds, the result will be considered an Event room.
		/// </summary>
		private readonly System.Collections.Generic.Dictionary<RoomType, float> _nonEventOdds = new System.Collections.Generic.Dictionary<RoomType, float>
		{
			[RoomType.Monster] = 0.1f,
			[RoomType.Elite] = -1f,
			[RoomType.Treasure] = 0.02f,
			[RoomType.Shop] = 0.03f
		};

		public float MonsterOdds
		{
			get
			{
				return _nonEventOdds[RoomType.Monster];
			}
			set
			{
				_nonEventOdds[RoomType.Monster] = value;
			}
		}

		public float EliteOdds
		{
			get
			{
				return _nonEventOdds[RoomType.Elite];
			}
			set
			{
				_nonEventOdds[RoomType.Elite] = value;
			}
		}

		public float TreasureOdds
		{
			get
			{
				return _nonEventOdds[RoomType.Treasure];
			}
			set
			{
				_nonEventOdds[RoomType.Treasure] = value;
			}
		}

		public float ShopOdds
		{
			get
			{
				return _nonEventOdds[RoomType.Shop];
			}
			set
			{
				_nonEventOdds[RoomType.Shop] = value;
			}
		}

		public float EventOdds => Math.Max(0f, 1f - _nonEventOdds.Values.Where((float v) => v > 0f).Sum());

		/// <summary>
		/// For creating at the start of a run.
		/// </summary>
		/// <param name="rng">RNG to use for rolls.</param>
		public UnknownMapPointOdds(Rng rng)
			: base(0f, rng)
		{
		}

		/// <summary>
		/// Sets the base odds for a room type.
		/// Note that this does not set the _current_ odds. It only sets what the odds get reset to when that room is rolled.
		/// </summary>
		public void SetBaseOdds(RoomType roomType, float baseOdds)
		{
			_baseOdds[roomType] = baseOdds;
		}

		/// <summary>
		/// Roll for the next room type and update future odds based on what's rolled.
		/// </summary>
		/// <param name="blacklist">Room types that we shouldn't be able to roll.</param>
		/// <param name="runState">The state of the run that this room is being entered in.</param>
		/// <returns>A RoomType.</returns>
		public RoomType Roll(IEnumerable<RoomType> blacklist, IRunState runState)
		{
			if (runState.UnlockState.NumberOfRuns == 0)
			{
				int num = runState.MapPointHistory.SelectMany((IReadOnlyList<MapPointHistoryEntry> l) => l).Count((MapPointHistoryEntry p) => p.MapPointType == MapPointType.Unknown);
				if (num < 2)
				{
					return RoomType.Event;
				}
				if (num == 2)
				{
					return RoomType.Monster;
				}
			}
			IReadOnlySet<RoomType> roomTypes = _nonEventOdds.Keys.Append(RoomType.Event).Except(blacklist).ToHashSet();
			roomTypes = Hook.ModifyUnknownMapPointRoomTypes(runState, roomTypes);
			RoomType roomType = (roomTypes.Contains(RoomType.Event) ? RoomType.Event : roomTypes.Order().First());
			float num2 = _rng.NextFloat();
			float num3 = 0f;
			RoomType key;
			float value;
			foreach (KeyValuePair<RoomType, float> nonEventOdd in _nonEventOdds)
			{
				nonEventOdd.Deconstruct(out key, out value);
				RoomType roomType2 = key;
				float num4 = value;
				if (roomTypes.Contains(roomType2) && !(num4 < 0f))
				{
					num3 += num4;
					if (num2 <= num3)
					{
						roomType = roomType2;
						break;
					}
				}
			}
			foreach (KeyValuePair<RoomType, float> baseOdd in _baseOdds)
			{
				baseOdd.Deconstruct(out key, out value);
				RoomType roomType3 = key;
				float num5 = value;
				if (roomType == roomType3)
				{
					_nonEventOdds[roomType3] = num5;
				}
				else if (roomTypes.Contains(roomType3))
				{
					float num6 = Hook.ModifyOddsIncreaseForUnrolledRoomType(runState, roomType3, num5);
					System.Collections.Generic.Dictionary<RoomType, float> nonEventOdds = _nonEventOdds;
					key = roomType3;
					nonEventOdds[key] += num6;
				}
			}
			return roomType;
		}

		/// <summary>
		/// Reset the odds for all room types to their base level.
		/// Called between acts.
		/// </summary>
		public void ResetToBase()
		{
			foreach (var (key, value) in _baseOdds)
			{
				_nonEventOdds[key] = value;
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer
{
	/// <summary>
	/// Responsible for synchronizing all players' combat states before combat begins.
	/// </summary>
	public class CombatStateSynchronizer : IDisposable
	{
		private readonly INetGameService _netService;

		private readonly RunState _runState;

		private readonly RunLobby? _runLobby;

		private readonly System.Collections.Generic.Dictionary<ulong, SerializablePlayer> _syncData = new System.Collections.Generic.Dictionary<ulong, SerializablePlayer>();

		private SerializableRunRngSet? _rngSet;

		private SerializableRelicGrabBag? _sharedRelicGrabBag;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("CombatStateSynchronizer", LogType.GameSync);

		private TaskCompletionSource? _syncCompletionSource;

		public bool IsDisabled { get; set; }

		public CombatStateSynchronizer(INetGameService netService, RunLobby? runLobby, RunState runState)
		{
			_netService = netService;
			_runState = runState;
			_runLobby = runLobby;
			_netService.RegisterMessageHandler<SyncPlayerDataMessage>(OnSyncPlayerMessageReceived);
			_netService.RegisterMessageHandler<SyncRngMessage>(OnSyncRngMessageReceived);
			if (_runLobby != null)
			{
				_runLobby.RemotePlayerDisconnected += OnPeerDisconnected;
			}
		}

		public void Dispose()
		{
			_netService.UnregisterMessageHandler<SyncPlayerDataMessage>(OnSyncPlayerMessageReceived);
			_netService.UnregisterMessageHandler<SyncRngMessage>(OnSyncRngMessageReceived);
			if (_runLobby != null)
			{
				_runLobby.RemotePlayerDisconnected -= OnPeerDisconnected;
			}
		}

		/// <summary>
		/// Handles a combat synchronization message from another peer.
		/// Remember that this can be called even before StartSync and must queue the data for the next time we sync.
		/// </summary>
		private void OnSyncPlayerMessageReceived(SyncPlayerDataMessage syncMessage, ulong senderId)
		{
			_logger.Debug($"Received sync player message from {senderId}");
			if (_syncData.ContainsKey(senderId))
			{
				_logger.Error($"Received two player sync messages from {senderId}! Ignoring the second one");
			}
			else
			{
				_syncData[senderId] = syncMessage.player;
				CheckSyncCompleted();
			}
		}

		/// <summary>
		/// Handles a RNG synchronization message from the host.
		/// Remember that this can be called even before StartSync and must queue the data for the next time we sync.
		/// </summary>
		private void OnSyncRngMessageReceived(SyncRngMessage syncMessage, ulong senderId)
		{
			_logger.Debug($"Received sync RNG message from {senderId}");
			if (_rngSet != null)
			{
				_logger.Error($"Received two RNG sync messages from {senderId}! Ignoring the second one");
			}
			else
			{
				_rngSet = syncMessage.rng;
				_sharedRelicGrabBag = syncMessage.sharedRelicGrabBag;
				CheckSyncCompleted();
			}
		}

		/// <summary>
		/// Called when a peer disconnects from the lobby.
		/// Used to check if we should complete the sync now that they've been disconnected.
		/// </summary>
		private void OnPeerDisconnected(ulong peerId)
		{
			TaskCompletionSource? syncCompletionSource = _syncCompletionSource;
			if (syncCompletionSource != null && !syncCompletionSource.Task.IsCompleted)
			{
				_logger.Debug($"Peer {peerId} disconnected, checking if sync is complete");
				CheckSyncCompleted();
			}
		}

		/// <summary>
		/// Sends a message syncing our combat state to all other players.
		/// This should be called early before beginning animations for entering a combat room. Then, WaitForSync should be
		/// called just before entering the combat room.
		/// Between this and WaitForSync, no player or RNG state should be modified.
		/// </summary>
		public void StartSync()
		{
			_logger.Debug("Broadcasting combat sync message to all peers");
			if (_netService.Type != NetGameType.Singleplayer && !IsDisabled)
			{
				if (_syncCompletionSource != null)
				{
					throw new InvalidOperationException("StartSync called twice before WaitForSync!");
				}
				SyncPlayerDataMessage message = default(SyncPlayerDataMessage);
				Player me = LocalContext.GetMe(_runState);
				message.player = me.ToSerializable();
				_netService.SendMessage(message);
				_syncData[message.player.NetId] = message.player;
				_syncCompletionSource = new TaskCompletionSource();
				if (_netService.Type == NetGameType.Host)
				{
					_rngSet = me.RunState.Rng.ToSerializable();
					_sharedRelicGrabBag = me.RunState.SharedRelicGrabBag.ToSerializable();
					SyncRngMessage message2 = new SyncRngMessage
					{
						rng = _rngSet,
						sharedRelicGrabBag = _sharedRelicGrabBag
					};
					_netService.SendMessage(message2);
				}
				CheckSyncCompleted();
			}
		}

		/// <summary>
		/// Waits for all other players' combat data to be received. StartSync must be called exactly once before this is called.
		/// </summary>
		public async Task WaitForSync()
		{
			_logger.Debug("Waiting to receive all sync messages from all clients");
			if (_netService.Type == NetGameType.Singleplayer || IsDisabled)
			{
				return;
			}
			if (_syncCompletionSource == null)
			{
				throw new InvalidOperationException("StartSync must be called before WaitForSync!");
			}
			await _syncCompletionSource.Task;
			foreach (KeyValuePair<ulong, SerializablePlayer> syncDatum in _syncData)
			{
				if (_runLobby != null && !_runLobby.PlayerIds.Contains(syncDatum.Key))
				{
					_logger.Debug($"Skipping sync for disconnected player {syncDatum.Key}");
					continue;
				}
				Player player = _runState.GetPlayer(syncDatum.Key);
				if (!LocalContext.IsMe(player))
				{
					player.SyncWithSerializedPlayer(syncDatum.Value);
				}
			}
			if (_netService.Type != NetGameType.Host)
			{
				if (_rngSet != null)
				{
					_runState.Rng.LoadFromSerializable(_rngSet);
				}
				else if (_runState.Players.Count > 1)
				{
					_logger.Error("There are two or more players and we are a client, but we never received the RNG set!");
				}
				if (_sharedRelicGrabBag != null)
				{
					_runState.SharedRelicGrabBag.LoadFromSerializable(_sharedRelicGrabBag);
				}
				else if (_runState.Players.Count > 1)
				{
					_logger.Error("There are two or more players and we are a client, but we never received the shared relic grab bag!");
				}
			}
			_syncData.Clear();
			_rngSet = null;
			_sharedRelicGrabBag = null;
			_syncCompletionSource = null;
		}

		/// <summary>
		/// Checks if synchronization is complete and sets the result on the sync completion source if we are all done.
		/// This should be called every time we receive some sync data from a peer.
		/// </summary>
		private void CheckSyncCompleted()
		{
			if (_syncCompletionSource == null)
			{
				return;
			}
			if (_runLobby == null)
			{
				throw new InvalidOperationException("Tried to combat sync without a valid run lobby!");
			}
			if (_netService.Type == NetGameType.Singleplayer || IsDisabled)
			{
				_syncCompletionSource.SetResult();
				return;
			}
			foreach (ulong playerId in _runLobby.PlayerIds)
			{
				if (!_syncData.ContainsKey(playerId))
				{
					return;
				}
			}
			if (_rngSet != null)
			{
				_syncCompletionSource.SetResult();
			}
		}
	}
	public static class MultiplayerDebugUtil
	{
		private static IEnumerable<BigInteger> Chunk(IReadOnlyList<byte> source, int size)
		{
			return from e in source.Select((byte _, int index) => source.Skip(size * index).Take(size).ToArray()).TakeWhile((byte[] bucket) => bucket.Length != 0)
				select new BigInteger(e);
		}

		private static byte ReplaceControlCharacterWithDot(byte character)
		{
			if ((character >= 31 && character < 127) || 1 == 0)
			{
				return character;
			}
			return 46;
		}

		private static byte[] ReplaceControlCharactersWithDots(byte[] characters)
		{
			return characters.Select(ReplaceControlCharacterWithDot).ToArray();
		}

		public static string FormatAsHex(ReadOnlySpan<byte> data, int lineWidth = 16, int byteWidth = 1)
		{
			StringBuilder stringBuilder = new StringBuilder();
			byte[] array;
			for (int i = 0; i < data.Length; i += array.Length)
			{
				array = data.Slice(i, Math.Min(lineWidth * byteWidth, data.Length - i)).ToArray();
				string text = string.Join(" ", from v in Chunk(array, byteWidth)
					select v.ToString("X" + byteWidth * 2, CultureInfo.InvariantCulture));
				text += new string(' ', lineWidth * (byteWidth * 2 + 1) - 1 - text.Length);
				string value = Encoding.ASCII.GetString(ReplaceControlCharactersWithDots(array));
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(3, 3, stringBuilder2);
				handler.AppendFormatted(i, "X4");
				handler.AppendLiteral(" ");
				handler.AppendFormatted(text);
				handler.AppendLiteral(" ");
				handler.AppendFormatted(value);
				handler.AppendLiteral("\n");
				stringBuilder2.Append(ref handler);
			}
			return stringBuilder.ToString();
		}

		public static byte[] StringToByteArray(string hex)
		{
			if (hex.Length % 2 == 1)
			{
				throw new Exception("The binary key cannot have an odd number of digits");
			}
			byte[] array = new byte[hex.Length >> 1];
			for (int i = 0; i < hex.Length >> 1; i++)
			{
				array[i] = (byte)((GetHexVal(hex[i << 1]) << 4) + GetHexVal(hex[(i << 1) + 1]));
			}
			return array;
		}

		private static int GetHexVal(char hex)
		{
			return hex - ((hex < ':') ? 48 : ((hex < 'a') ? 55 : 87));
		}
	}
	public class NetClientGameService : INetClientHandler, INetHandler, INetClientGameService, INetGameService, IHandshakeHandler
	{
		private readonly PacketReader _reader = new PacketReader();

		private readonly PacketWriter _writer = new PacketWriter();

		private readonly NetMessageBus _messageBus;

		private readonly NetQualityTracker _qualityTracker;

		private readonly HandshakeManager _handshakeManager;

		public NetClient? NetClient { get; private set; }

		public bool IsConnected { get; private set; }

		public ulong NetId => (NetClient ?? throw new InvalidOperationException("Tried to get NetId while not connected!")).NetId;

		public ulong HostNetId => (NetClient ?? throw new InvalidOperationException("Tried to get HostNetId while not connected!")).HostNetId;

		public bool IsGameLoading => _qualityTracker.IsGameLoading;

		public PlatformType Platform { get; private set; }

		public PeerVersionInfo LocalVersion { get; }

		public NetGameType Type => NetGameType.Client;

		public event Action? ConnectedToHost;

		public event Action<NetErrorInfo>? ConnectionFailed;

		public event Action<NetErrorInfo>? Disconnected;

		public NetClientGameService(PeerVersionInfo versionInfo)
		{
			LocalVersion = versionInfo;
			_messageBus = new NetMessageBus(_reader, _writer);
			_handshakeManager = new HandshakeManager(this, versionInfo, _writer);
			_qualityTracker = new NetQualityTracker(this);
		}

		public void Initialize(NetClient client, PlatformType platform)
		{
			NetClient = client;
			Platform = platform;
		}

		public void Update()
		{
			NetClient? netClient = NetClient;
			if (netClient != null && netClient.IsConnected)
			{
				NetClient.Update();
			}
			if (IsConnected)
			{
				_qualityTracker.Update();
			}
		}

		public void SendMessage<T>(T message, ulong playerId) where T : INetMessage
		{
			if (playerId != NetClient?.HostNetId)
			{
				throw new NotImplementedException("Cannot send messages to non-host players as client!");
			}
			SendMessage(message);
		}

		public void SendMessage<T>(T message) where T : INetMessage
		{
			if (!IsConnected)
			{
				Log.Error($"Attempted to send message {message} while {this} is not connected!");
			}
			else
			{
				byte[] bytes = _messageBus.SerializeMessage(NetClient.NetId, message, out var length);
				NetClient.SendMessageToHost(bytes, length, message.Mode, message.Mode.ToChannelId());
			}
		}

		public void RegisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage
		{
			_messageBus.RegisterMessageHandler(handler);
		}

		public void UnregisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage
		{
			_messageBus.UnregisterMessageHandler(handler);
		}

		public void OnPacketReceived(ulong senderId, byte[] packetBytes, NetTransferMode mode, int channel)
		{
			NetClient? netClient = NetClient;
			if (netClient != null)
			{
				_ = netClient.HostNetId;
				if (true && _handshakeManager.IsHandshaking(NetClient.HostNetId))
				{
					_reader.Reset(packetBytes);
					_handshakeManager.HandshakeMessageReceived(senderId, _reader);
					return;
				}
			}
			if (_messageBus.TryDeserializeMessage(packetBytes, out INetMessage message, out ulong? overrideSenderId))
			{
				senderId = overrideSenderId ?? senderId;
				_messageBus.SendMessageToAllHandlers(message, senderId);
			}
		}

		public void Disconnect(NetError reason, bool now = false)
		{
			NetClient? netClient = NetClient;
			if (netClient != null && netClient.IsConnected)
			{
				NetClient.DisconnectFromHost(reason, now);
			}
		}

		public void OnConnectedToHost()
		{
			_handshakeManager.BeginHandshakeFor(HostNetId);
		}

		public void SendHandshakeMessage(ulong peerId, PacketWriter writer)
		{
			if (peerId != HostNetId)
			{
				throw new InvalidOperationException($"Tried to send handshake message as client to {peerId}, who is not the host!");
			}
			NetClient.SendMessageToHost(writer.Buffer, writer.BytePosition, NetTransferMode.Reliable, NetTransferMode.Reliable.ToChannelId());
		}

		public void HandshakeFailed(ulong peerId, NetErrorInfo info)
		{
			Disconnect(info.GetReason());
			ConnectionFailed?.Invoke(info);
		}

		public void HandshakeSucceeded(ulong peerId, PeerVersionInfo versionInfo)
		{
			IsConnected = true;
			_qualityTracker.OnPeerConnected(peerId);
			ConnectedToHost?.Invoke();
		}

		public void OnDisconnectedFromHost(ulong hostNetId, NetErrorInfo info)
		{
			_qualityTracker.OnPeerDisconnected(hostNetId);
			_qualityTracker.Dispose();
			if (IsConnected)
			{
				IsConnected = false;
				Disconnected?.Invoke(info);
			}
			else if (_handshakeManager.IsHandshaking(hostNetId))
			{
				_handshakeManager.AbortHandshake(hostNetId);
				ConnectionFailed?.Invoke(info);
			}
		}

		public ConnectionStats? GetStatsForPeer(ulong peerId)
		{
			return _qualityTracker.GetStatsForPeer(peerId);
		}

		public void SetGameLoading(bool isLoading)
		{
			_qualityTracker.SetIsLoading(isLoading);
		}

		public void SetBufferMessages(bool bufferMessages)
		{
			_messageBus.SetBufferMessages(bufferMessages);
		}

		public string? GetRawLobbyIdentifier()
		{
			return NetClient?.GetRawLobbyIdentifier();
		}
	}
	public static class NetConst
	{
		public const int timeoutMsec = 20000;
	}
	public class NetHostGameService : INetHostHandler, INetHandler, INetHostGameService, INetGameService, IHandshakeHandler
	{
		private NetHost? _netHost;

		private readonly PacketReader _reader = new PacketReader();

		private readonly PacketWriter _writer = new PacketWriter();

		private readonly NetMessageBus _messageBus;

		private readonly HandshakeManager _handshakeManager;

		private readonly NetQualityTracker _qualityTracker;

		private readonly List<NetClientData> _connectedPeers = new List<NetClientData>();

		public bool IsConnected => _netHost?.IsConnected ?? false;

		public ulong NetId => (_netHost ?? throw new InvalidOperationException("Tried to get NetId while not connected!")).NetId;

		public bool IsGameLoading => _qualityTracker.IsGameLoading;

		public List<NetClientData> ConnectedPeers => _connectedPeers;

		public PlatformType Platform { get; private set; }

		public PeerVersionInfo LocalVersion { get; }

		public NetHost? NetHost => _netHost;

		public NetGameType Type => NetGameType.Host;

		public event Action<NetErrorInfo>? Disconnected;

		public event Action<ulong>? ClientConnected;

		public event Action<ulong, NetErrorInfo>? ClientDisconnected;

		public event Action<ulong, NetErrorInfo>? ClientConnectionFailed;

		public NetHostGameService(PeerVersionInfo versionInfo)
		{
			LocalVersion = versionInfo;
			_messageBus = new NetMessageBus(_reader, _writer);
			_handshakeManager = new HandshakeManager(this, versionInfo, _writer);
			_qualityTracker = new NetQualityTracker(this);
		}

		public NetErrorInfo? StartENetHost(ushort port, int maxClients)
		{
			return ((ENetHost)(_netHost = new ENetHost(this))).StartHost(port, maxClients);
		}

		public Task<NetErrorInfo?> StartSteamHost(int maxClients)
		{
			SteamHost steamHost = (SteamHost)(_netHost = new SteamHost(this));
			Platform = PlatformType.Steam;
			return steamHost.StartHost(maxClients);
		}

		public Task<NetErrorInfo?> StartTestHost(AbstractTestNetHost host, int maxClients)
		{
			_netHost = host;
			Platform = PlatformType.None;
			return host.StartHost(maxClients);
		}

		public void Update()
		{
			NetHost? netHost = _netHost;
			if (netHost != null && netHost.IsConnected)
			{
				_netHost.Update();
				_qualityTracker.Update();
			}
		}

		public void SendMessage<T>(T message, ulong peerId) where T : INetMessage
		{
			SendMessageToClientInternal(message, peerId, message.Mode.ToChannelId(), null);
		}

		private void SendMessageToClientInternal<T>(T message, ulong peerId, int channel, ulong? overrideSenderId) where T : INetMessage
		{
			if (!IsConnected)
			{
				Log.Error($"Attempted to send message {message} while {this} is not connected!");
			}
			else
			{
				byte[] bytes = _messageBus.SerializeMessage(overrideSenderId ?? _netHost.NetId, message, out var length);
				_netHost.SendMessageToClient(peerId, bytes, length, message.Mode, channel);
			}
		}

		public void SendMessage<T>(T message) where T : INetMessage
		{
			if (!IsConnected)
			{
				Log.Error($"Attempted to send message {message} while {this} is not connected!");
				return;
			}
			byte[] bytes = _messageBus.SerializeMessage(_netHost.NetId, message, out var length);
			foreach (NetClientData connectedPeer in _connectedPeers)
			{
				if (connectedPeer.readyForBroadcasting)
				{
					_netHost.SendMessageToClient(connectedPeer.peerId, bytes, length, message.Mode, message.Mode.ToChannelId());
				}
			}
		}

		public void RegisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage
		{
			_messageBus.RegisterMessageHandler(handler);
		}

		public void UnregisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage
		{
			_messageBus.UnregisterMessageHandler(handler);
		}

		public void OnPacketReceived(ulong senderId, byte[] packetBytes, NetTransferMode mode, int channel)
		{
			if (_handshakeManager.IsHandshaking(senderId))
			{
				_reader.Reset(packetBytes);
				_handshakeManager.HandshakeMessageReceived(senderId, _reader);
				return;
			}
			int num = _connectedPeers.FindIndex((NetClientData p) => p.peerId == senderId);
			INetMessage message;
			ulong? overrideSenderId;
			if (num < 0)
			{
				Log.Warn($"Received {packetBytes.Length} bytes from unknown peer {senderId}!");
			}
			else if (_messageBus.TryDeserializeMessage(packetBytes, out message, out overrideSenderId))
			{
				if (message.ShouldBroadcast)
				{
					BroadcastMessage(message, senderId, channel, overrideSenderId.Value);
				}
				senderId = overrideSenderId.GetValueOrDefault(senderId);
				_messageBus.SendMessageToAllHandlers(message, senderId);
			}
		}

		public void HandshakeSucceeded(ulong senderId, PeerVersionInfo versionInfo)
		{
			_connectedPeers.Add(new NetClientData
			{
				peerId = senderId,
				readyForBroadcasting = false,
				versionInfo = versionInfo
			});
			_qualityTracker.OnPeerConnected(senderId);
			ClientConnected?.Invoke(senderId);
		}

		public void HandshakeFailed(ulong senderId, NetErrorInfo info)
		{
			ClientConnectionFailed?.Invoke(senderId, info);
			DisconnectClient(senderId, info.GetReason());
		}

		private void BroadcastMessage<T>(T message, ulong excludePeerId, int channel, ulong overrideSenderId) where T : INetMessage
		{
			foreach (NetClientData connectedPeer in _connectedPeers)
			{
				if (connectedPeer.readyForBroadcasting && connectedPeer.peerId != excludePeerId)
				{
					SendMessageToClientInternal(message, connectedPeer.peerId, channel, overrideSenderId);
				}
			}
		}

		/// <summary>
		/// Starts sending broadcasted messages to a peer.
		/// When a peer first connects, messages that have ShouldBroadcast set are not sent to that peer. They are only sent
		/// to the newly connected peer after this method is called, passing the newly connected peer's ID.
		/// This is used to prevent messages from being sent to a peer until the game-level connection flow has been completed.
		/// </summary>
		public void SetPeerReadyForBroadcasting(ulong peerId)
		{
			for (int i = 0; i < _connectedPeers.Count; i++)
			{
				if (_connectedPeers[i].peerId == peerId)
				{
					NetClientData value = _connectedPeers[i];
					value.readyForBroadcasting = true;
					_connectedPeers[i] = value;
				}
			}
		}

		public PeerVersionInfo? GetVersionInfoForPeer(ulong peerId)
		{
			int num = _connectedPeers.FindIndex((NetClientData p) => p.peerId == peerId);
			if (num < 0)
			{
				return null;
			}
			return _connectedPeers[num].versionInfo;
		}

		public void DisconnectClient(ulong peerId, NetError reason, bool now = false)
		{
			_netHost.DisconnectClient(peerId, reason, now);
		}

		public void Disconnect(NetError reason, bool now = false)
		{
			NetHost? netHost = _netHost;
			if (netHost != null && netHost.IsConnected)
			{
				_netHost.StopHost(reason, now);
				_qualityTracker.Dispose();
			}
		}

		public void OnDisconnected(NetErrorInfo info)
		{
			Disconnected?.Invoke(info);
		}

		public void SendHandshakeMessage(ulong peerId, PacketWriter writer)
		{
			_netHost.SendMessageToClient(peerId, _writer.Buffer, _writer.BytePosition, NetTransferMode.Reliable, NetTransferMode.Reliable.ToChannelId());
		}

		public void OnPeerConnected(ulong peerId)
		{
			_handshakeManager.BeginHandshakeFor(peerId);
		}

		public void OnPeerDisconnected(ulong peerId, NetErrorInfo info)
		{
			int num = _connectedPeers.RemoveAll((NetClientData p) => p.peerId == peerId);
			_qualityTracker.OnPeerDisconnected(peerId);
			if (num > 0)
			{
				ClientDisconnected?.Invoke(peerId, info);
			}
			if (_handshakeManager.IsHandshaking(peerId))
			{
				_handshakeManager.AbortHandshake(peerId);
				ClientConnectionFailed?.Invoke(peerId, info);
			}
		}

		public ConnectionStats? GetStatsForPeer(ulong peerId)
		{
			return _qualityTracker.GetStatsForPeer(peerId);
		}

		public void SetGameLoading(bool isLoading)
		{
			_qualityTracker.SetIsLoading(isLoading);
		}

		public void SetBufferMessages(bool bufferMessages)
		{
			_messageBus.SetBufferMessages(bufferMessages);
		}

		public string? GetRawLobbyIdentifier()
		{
			return NetHost?.GetRawLobbyIdentifier();
		}
	}
	public class NetMessageBus
	{
		private delegate void AnonymizedMessageHandlerDelegate(INetMessage message, ulong senderId);

		private struct CallbackPair
		{
			public AnonymizedMessageHandlerDelegate handler;

			public object originalHandler;
		}

		private readonly PacketReader _reader;

		private readonly PacketWriter _writer;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("NetMessageBus", LogType.Network);

		private readonly System.Collections.Generic.Dictionary<Type, List<CallbackPair>> _messageHandlers = new System.Collections.Generic.Dictionary<Type, List<CallbackPair>>();

		private readonly List<CallbackPair> _cachedPairList = new List<CallbackPair>();

		private bool _isBufferingMessages;

		private readonly HashSet<byte> _warnedMessageTypes = new HashSet<byte>();

		private readonly List<(INetMessage, ulong)> _bufferedMessages = new List<(INetMessage, ulong)>();

		public NetMessageBus(PacketReader reader, PacketWriter writer)
		{
			_reader = reader;
			_writer = writer;
		}

		public byte[] SerializeMessage<T>(ulong senderId, T message, out int length) where T : INetMessage
		{
			_writer.Reset();
			_writer.WriteByte((byte)message.ToId());
			_writer.WriteULong(senderId);
			message.Serialize(_writer);
			length = _writer.BytePosition;
			return _writer.Buffer;
		}

		public bool TryDeserializeMessage(byte[] packetBytes, out INetMessage? message, out ulong? overrideSenderId)
		{
			overrideSenderId = null;
			message = null;
			_reader.Reset(packetBytes);
			byte b = _reader.ReadByte();
			if (!MessageTypes.TryGetMessageType(b, out Type type))
			{
				if (ModManager.IsRunningModded() && b >= MessageTypes.Count && !_warnedMessageTypes.Contains(b))
				{
					Log.Warn($"Received message with length {packetBytes.Length} and first byte {b} that is outside the bounds of our known messages ({MessageTypes.Count}). Since we are modded, we are assuming this is a message that does not affect gameplay and will not warn about this again.");
					_warnedMessageTypes.Add(b);
				}
				else
				{
					Log.Error($"Received message with length {packetBytes.Length} and first byte {b} that is not a valid message ID!");
				}
				return false;
			}
			overrideSenderId = _reader.ReadULong();
			message = (INetMessage)Activator.CreateInstance(type);
			message.Deserialize(_reader);
			return true;
		}

		public void SendMessageToAllHandlers(INetMessage message, ulong senderId)
		{
			if (_isBufferingMessages && message.ShouldBuffer)
			{
				_logger.Debug($"Received message of type {message.GetType()} but we are currently buffering messages.");
				_bufferedMessages.Add((message, senderId));
				return;
			}
			if (!_messageHandlers.TryGetValue(message.GetType(), out List<CallbackPair> value) || value.Count == 0)
			{
				Log.Error($"Received message of type {message.GetType()}, but no message handlers are registered for that type!");
				return;
			}
			_cachedPairList.Clear();
			_cachedPairList.AddRange(value);
			_logger.LogMessage(message.LogLevel, $"Received message {message}, sending to {_cachedPairList.Count} handlers", 0);
			foreach (CallbackPair cachedPair in _cachedPairList)
			{
				try
				{
					cachedPair.handler(message, senderId);
				}
				catch (Exception value2)
				{
					_logger.Error($"Exception encountered while processing message {message}: {value2}");
				}
			}
		}

		public void SetBufferMessages(bool bufferMessages)
		{
			if (_isBufferingMessages == bufferMessages)
			{
				return;
			}
			_isBufferingMessages = bufferMessages;
			if (bufferMessages)
			{
				_logger.Debug("NetMessageBus is starting to buffer messages.");
				return;
			}
			_logger.Debug($"NetMessageBus is releasing {_bufferedMessages.Count} buffered messages.");
			foreach (var (message, senderId) in _bufferedMessages)
			{
				SendMessageToAllHandlers(message, senderId);
			}
			_bufferedMessages.Clear();
		}

		public void RegisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage
		{
			if (typeof(T) == typeof(INetMessage))
			{
				throw new InvalidOperationException("RegisterMessageHandler must be called with a concrete implementation of INetMessage!");
			}
			if (!_messageHandlers.TryGetValue(typeof(T), out List<CallbackPair> value))
			{
				value = new List<CallbackPair>();
				_messageHandlers[typeof(T)] = value;
			}
			CallbackPair item = new CallbackPair
			{
				handler = delegate(INetMessage message, ulong senderId)
				{
					handler((T)message, senderId);
				},
				originalHandler = handler
			};
			value.Add(item);
		}

		public void UnregisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage
		{
			if (typeof(T) == typeof(INetMessage))
			{
				throw new InvalidOperationException("UnregisterMessageHandler must be called with a concrete implementation of INetMessage!");
			}
			if (_messageHandlers.TryGetValue(typeof(T), out List<CallbackPair> value))
			{
				value.RemoveAll((CallbackPair p) => (Delegate?)(MessageHandlerDelegate<T>)p.originalHandler == (Delegate?)handler);
			}
		}
	}
