	/// <summary>
	/// Sent during the handshake between host and client.
	/// This is the only struct of its kind that must NOT change format significantly. It must stay stable enough between
	/// versions that we can detect version mismatches, i.e. we should only add to this and never remove.
	/// </summary>
	public struct PeerVersionInfo
	{
		/// <summary>
		/// The version of the game the host is running.
		/// </summary>
		public string version;

		/// <summary>
		/// The steam branch that the host is playing on.
		/// DO NOT compare this to the client's when joining to check versions. The same game version might be on different
		/// steam branches. Only compare <see cref="F:MegaCrit.Sts2.Core.Multiplayer.PeerVersionInfo.version" /> and only use this for diagnostic purposes.
		/// </summary>
		public PlatformBranch branch;

		/// <summary>
		/// A hash of all the IDs in the model database.
		/// </summary>
		public uint idDatabaseHash;

		/// <summary>
		/// A list of all the gameplay-affecting mods that the host has installed, if any.
		/// </summary>
		public List<string>? gameplayAffectingMods;

		/// <summary>
		/// A list of all the non-gameplay-affecting mods that the host has installed, if any.
		/// </summary>
		public List<string>? otherMods;

		/// <summary>
		/// Returns a PeerVersionInfo with data filled in from various singletons.
		/// </summary>
		public static PeerVersionInfo LocalDefault()
		{
			return new PeerVersionInfo
			{
				version = NGame.GetGameVersion(),
				branch = PlatformUtil.GetPlatformBranch(),
				idDatabaseHash = ModelIdSerializationCache.Hash,
				gameplayAffectingMods = ModManager.GetGameplayRelevantModNameList(),
				otherMods = ModManager.GetNonGameplayRelevantModNameList()
			};
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(version);
			writer.WriteEnum(branch);
			writer.WriteUInt(idDatabaseHash);
			writer.WriteBool(gameplayAffectingMods != null);
			if (gameplayAffectingMods != null)
			{
				writer.WriteInt(gameplayAffectingMods.Count);
				foreach (string gameplayAffectingMod in gameplayAffectingMods)
				{
					writer.WriteString(gameplayAffectingMod);
				}
			}
			writer.WriteBool(otherMods != null);
			if (otherMods == null)
			{
				return;
			}
			writer.WriteInt(otherMods.Count);
			foreach (string otherMod in otherMods)
			{
				writer.WriteString(otherMod);
			}
		}

		public bool TryDeserialize(PacketReader reader)
		{
			try
			{
				version = reader.ReadString();
				if (!SemanticVersion.TryFromString(version, out SemanticVersion _) && !OS.HasFeature("editor"))
				{
					return false;
				}
				branch = reader.ReadEnum<PlatformBranch>();
				idDatabaseHash = reader.ReadUInt();
				if (reader.ReadBool())
				{
					int num = reader.ReadInt();
					gameplayAffectingMods = new List<string>();
					for (int i = 0; i < num; i++)
					{
						gameplayAffectingMods.Add(reader.ReadString());
					}
				}
				if (reader.ReadBool())
				{
					int num2 = reader.ReadInt();
					otherMods = new List<string>();
					for (int j = 0; j < num2; j++)
					{
						otherMods.Add(reader.ReadString());
					}
				}
				return true;
			}
			catch (Exception value)
			{
				Log.Error($"Failed to deserialize ${"PeerVersionInfo"}! Attempting to proceed with a partial read. Exception: {value}");
				return false;
			}
		}

		public bool IsModded()
		{
			List<string>? list = gameplayAffectingMods;
			if (list == null || list.Count <= 0)
			{
				List<string>? list2 = otherMods;
				if (list2 == null)
				{
					return false;
				}
				return list2.Count > 0;
			}
			return true;
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Transport
{
	public interface INetClientHandler : INetHandler
	{
		void Initialize(NetClient client, PlatformType platformType);

		void OnConnectedToHost();

		void OnDisconnectedFromHost(ulong hostNetId, NetErrorInfo info);
	}
	public interface INetHandler
	{
		void OnPacketReceived(ulong senderId, byte[] packetBytes, NetTransferMode mode, int channel);
	}
	public interface INetHostHandler : INetHandler
	{
		void OnPeerConnected(ulong peerId);

		void OnPeerDisconnected(ulong peerId, NetErrorInfo info);

		void OnDisconnected(NetErrorInfo info);
	}
	public abstract class NetClient
	{
		/// <summary>
		/// Delegate to notify about events.
		/// </summary>
		protected INetClientHandler _handler;

		/// <summary>
		/// True this client is connected to a host, false otherwise.
		/// </summary>
		public abstract bool IsConnected { get; }

		/// <summary>
		/// The network ID of the client.
		/// </summary>
		public abstract ulong NetId { get; }

		/// <summary>
		/// The network ID of the host we are connected to.
		/// </summary>
		public abstract ulong HostNetId { get; }

		protected NetClient(INetClientHandler handler)
		{
			_handler = handler;
		}

		/// <summary>
		/// Should be called at regular intervals to send and receive messages.
		/// </summary>
		public abstract void Update();

		/// <summary>
		/// Sends a message to the host.
		/// </summary>
		/// <param name="bytes">The byte content of the message.</param>
		/// <param name="length">The amount of bytes, starting from index 0, to send from bytes.</param>
		/// <param name="mode">Method of transfer (reliable or unreliable).</param>
		/// <param name="channel">The channel to use to send the message.</param>
		public abstract void SendMessageToHost(byte[] bytes, int length, NetTransferMode mode, int channel = 0);

		/// <summary>
		/// Disconnects from the host.
		/// </summary>
		/// <param name="reason">THe reason to send to the client accompanying the disconnection.</param>
		/// <param name="now">If true, we will be forcibly and immediately disconnected. If false, we are disconnected at
		/// some point in the near future.</param>
		public abstract void DisconnectFromHost(NetError reason, bool now = false);

		/// <summary>
		/// Returns a unique identifier for the lobby that the client is connected to.
		/// Returns null if the client is not yet connected or has been disconnected.
		/// This returns a platform-specific identifier for use with rich presence. Feel free to refactor later if more
		/// info or more specific info is needed.
		/// </summary>
		public abstract string? GetRawLobbyIdentifier();
	}
	public abstract class NetHost
	{
		/// <summary>
		/// Delegate to notify about events.
		/// </summary>
		protected INetHostHandler _handler;

		/// <summary>
		/// The IDs of currently connected clients.
		/// </summary>
		public abstract IEnumerable<ulong> ConnectedPeerIds { get; }

		/// <summary>
		/// True if clients are able to connect and receive messages, false otherwise.
		/// </summary>
		public abstract bool IsConnected { get; }

		/// <summary>
		/// The network ID of the host.
		/// </summary>
		public abstract ulong NetId { get; }

		protected NetHost(INetHostHandler handler)
		{
			_handler = handler;
		}

		/// <summary>
		/// Should be called at regular intervals to send and receive messages.
		/// </summary>
		public abstract void Update();

		/// <summary>
		/// If called with true, the host will be considered closed.
		/// What this means is platform-dependent. On Steam, this prevents other people from seeing the lobby, but existing
		/// clients are unaffected.
		/// </summary>
		public abstract void SetHostIsClosed(bool isClosed);

		/// <summary>
		/// Sends a message to a specific client.
		/// </summary>
		/// <param name="peerId">The ID of the client to send to.</param>
		/// <param name="bytes">The byte content of the message.</param>
		/// <param name="length">The amount of bytes, starting from index 0, to send from bytes.</param>
		/// <param name="mode">Method of transfer (reliable or unreliable).</param>
		/// <param name="channel">The channel to use to send the message.</param>
		public abstract void SendMessageToClient(ulong peerId, byte[] bytes, int length, NetTransferMode mode, int channel = 0);

		/// <summary>
		/// Broadcasts a message to all clients.
		/// </summary>
		/// <param name="bytes">The byte content of the message.</param>
		/// <param name="length">The amount of bytes, starting from index 0, to send from bytes.</param>
		/// <param name="mode">Method of transfer (reliable or unreliable).</param>
		/// <param name="channel">The channel to use to send the message.</param>
		public abstract void SendMessageToAll(byte[] bytes, int length, NetTransferMode mode, int channel = 0);

		/// <summary>
		/// Disconnects a client.
		/// </summary>
		/// <param name="peerId">The ID of the client to disconnect.</param>
		/// <param name="reason">THe reason to send to the client accompanying the disconnection.</param>
		/// <param name="now">If true, the client will be forcibly and immediately disconnected. If false, the client is
		/// disconnected at some point in the near future.</param>
		public abstract void DisconnectClient(ulong peerId, NetError reason, bool now = false);

		/// <summary>
		/// Disconnecst all clients and stops listening for new connections.
		/// </summary>
		/// <param name="reason">The reason that the host is shutting down. Sent to connected clients.</param>
		/// <param name="now">If true, all clients will be forcibly and immediately disconnected. If false, clients are
		/// disconnected at some point in the near future.</param>
		public abstract void StopHost(NetError reason, bool now = false);

		/// <summary>
		/// Returns a unique identifier for the lobby that this host is advertising.
		/// Returns null if the host has stopped or not yet started hosting.
		/// This returns a platform-specific identifier for use with rich presence. Feel free to refactor later if more
		/// info or more specific info is needed.
		/// </summary>
		public abstract string? GetRawLobbyIdentifier();
	}
	public enum NetTransferMode
	{
		None,
		Unreliable,
		Reliable
	}
	public static class NetTransferModeExtensions
	{
		/// <summary>
		/// Returns the channel that should be used to send a message with the given mode.
		/// ENet uses the channel ID to denote priority: https://www.linuxjournal.com/content/network-programming-enet
		/// Our reliable messages should be considered higher priority than our unreliable messages.
		/// </summary>
		public static int ToChannelId(this NetTransferMode mode)
		{
			return mode switch
			{
				NetTransferMode.Unreliable => 1, 
				NetTransferMode.Reliable => 0, 
				_ => throw new ArgumentOutOfRangeException("mode", mode, null), 
			};
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Transport.Steam
{
	public class SteamCallResult<T> : IDisposable where T : struct
	{
		private readonly TaskCompletionSource<T> _completionSource = new TaskCompletionSource<T>();

		private readonly CallResult<T> _callResult;

		private readonly CancellationTokenRegistration? _cancelTokenRegistration;

		public Task<T> Task => _completionSource.Task;

		public SteamCallResult(SteamAPICall_t call, CancellationToken cancelToken = default(CancellationToken))
		{
			_callResult = CallResult<T>.Create(OnCallResult);
			_callResult.Set(call);
			if (cancelToken.CanBeCanceled)
			{
				_cancelTokenRegistration = cancelToken.Register(Cancel);
			}
		}

		public void Cancel()
		{
			_callResult.Cancel();
			_completionSource.TrySetCanceled();
			_cancelTokenRegistration?.Dispose();
		}

		private void OnCallResult(T result, bool ioError)
		{
			if (ioError)
			{
				_completionSource.SetException(new IOException($"Got IO failure from CallResult of type {typeof(T)}!"));
			}
			else
			{
				_completionSource.SetResult(result);
			}
			_cancelTokenRegistration?.Dispose();
		}

		public void Dispose()
		{
			_callResult.Dispose();
			_cancelTokenRegistration?.Dispose();
		}
	}
	public class SteamClient : NetClient
	{
		private struct ConnectionResult
		{
			public HSteamNetConnection? connection;

			public SteamDisconnectionReason? disconnectionReason;

			public string? debugReason;
		}

		private CSteamID? _lobbyId;

		private CSteamID _hostNetId;

		private HSteamNetConnection? _conn;

		private bool _isConnected;

		private TaskCompletionSource<ConnectionResult>? _connectingTaskCompletionSource;

		private Callback<SteamNetConnectionStatusChangedCallback_t>? _netStatusChangedCallback;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("SteamClient", LogType.Network);

		public override bool IsConnected => _isConnected;

		public override ulong NetId => SteamUser.GetSteamID().m_SteamID;

		public override ulong HostNetId => _hostNetId.m_SteamID;

		public CSteamID? LobbyId => _lobbyId;

		public SteamClient(INetClientHandler handler)
			: base(handler)
		{
		}

		public Task<NetErrorInfo?> ConnectToLobbyOwnedByFriend(ulong steamPlayerId, CancellationToken cancelToken = default(CancellationToken))
		{
			_logger.Info($"Attempting to connect to lobby. Our player id: {NetId}. Other player's id: {steamPlayerId}.");
			if (!SteamFriends.GetFriendGamePlayed(new CSteamID(steamPlayerId), out var pFriendGameInfo))
			{
				Log.Warn("Tried to join a friend's Steam game, but they're not playing any game. Likely a stale invite");
				return Task.FromResult((NetErrorInfo?)new NetErrorInfo(NetError.InvalidJoin, selfInitiated: false));
			}
			if (pFriendGameInfo.m_gameID != new CGameID(2868840uL) || pFriendGameInfo.m_steamIDLobby.m_SteamID == 0L)
			{
				Log.Warn("Tried to join a friend's Steam game, but they are not playing STS2 or they are not in a lobby. Likely a stale invite");
				return Task.FromResult((NetErrorInfo?)new NetErrorInfo(NetError.InvalidJoin, selfInitiated: false));
			}
			return ConnectToLobby(pFriendGameInfo.m_steamIDLobby.m_SteamID, cancelToken);
		}

		public async Task<NetErrorInfo?> ConnectToLobby(ulong lobbyId, CancellationToken cancelToken = default(CancellationToken))
		{
			NetErrorInfo? result;
			await using (cancelToken.Register(CancelConnection))
			{
				SteamAPICall_t call = SteamMatchmaking.JoinLobby(new CSteamID(lobbyId));
				using SteamCallResult<LobbyEnter_t> callResult = new SteamCallResult<LobbyEnter_t>(call, cancelToken);
				_logger.Debug($"Attempting to enter lobby {lobbyId}");
				LobbyEnter_t lobbyEnter_t = await callResult.Task;
				if (lobbyEnter_t.m_ulSteamIDLobby != lobbyId)
				{
					_logger.Error("Joined incorrect lobby?");
					result = new NetErrorInfo(NetError.InternalError, selfInitiated: false);
				}
				else
				{
					EChatRoomEnterResponse eChatRoomEnterResponse = (EChatRoomEnterResponse)lobbyEnter_t.m_EChatRoomEnterResponse;
					if (eChatRoomEnterResponse != EChatRoomEnterResponse.k_EChatRoomEnterResponseSuccess)
					{
						_logger.Error($"Failed to enter lobby, response: {eChatRoomEnterResponse}");
						result = new NetErrorInfo(eChatRoomEnterResponse);
					}
					else
					{
						_lobbyId = new CSteamID(lobbyEnter_t.m_ulSteamIDLobby);
						CSteamID lobbyOwnerId = SteamMatchmaking.GetLobbyOwner(_lobbyId.Value);
						SteamNetworkingIdentity identityRemote = lobbyOwnerId.ToNetId();
						_netStatusChangedCallback = new Callback<SteamNetConnectionStatusChangedCallback_t>(OnNetStatusChanged);
						_connectingTaskCompletionSource = new TaskCompletionSource<ConnectionResult>();
						_conn = SteamNetworkingSockets.ConnectP2P(ref identityRemote, 0, 0, null);
						_logger.Debug($"Connecting to user {lobbyOwnerId.m_SteamID}");
						ConnectionResult connectionResult = await _connectingTaskCompletionSource.Task;
						if (connectionResult.disconnectionReason.HasValue)
						{
							CleanupConnection((int)connectionResult.disconnectionReason.Value, connectionResult.debugReason);
							result = new NetErrorInfo(connectionResult.disconnectionReason.Value, connectionResult.debugReason, selfInitiated: false);
						}
						else if (_conn.Value.m_HSteamNetConnection != connectionResult.connection.Value.m_HSteamNetConnection)
						{
							_logger.Error("Got different connection back from OnNetStatusChanged than we expected!");
							SteamNetworkingSockets.CloseConnection(connectionResult.connection.Value, 0, null, bEnableLinger: false);
							CleanupConnection(1202, "Invalid OnNetStatusChanged hConn");
							result = new NetErrorInfo(NetError.InternalError, selfInitiated: false);
						}
						else
						{
							_connectingTaskCompletionSource = null;
							_isConnected = true;
							_hostNetId = lobbyOwnerId;
							_handler.OnConnectedToHost();
							_logger.Debug($"Successfully connected to host {lobbyOwnerId.m_SteamID}");
							result = null;
						}
					}
				}
			}
			return result;
		}

		private void OnNetStatusChanged(SteamNetConnectionStatusChangedCallback_t data)
		{
			_logger.Debug($"Connection status changed: {data.m_eOldState} -> {data.m_info.m_eState}");
			if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_Connected)
			{
				_logger.Debug("Steam connection accepted.");
				if (_connectingTaskCompletionSource == null)
				{
					_logger.Error("Connection was accepted while we were not waiting for it!");
					DisconnectFromHostInternal(SteamDisconnectionReason.InternalError, "Not Connecting", now: true, selfInitiated: false);
				}
				else
				{
					_connectingTaskCompletionSource.SetResult(new ConnectionResult
					{
						connection = data.m_hConn
					});
				}
			}
			else if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_ProblemDetectedLocally)
			{
				_logger.Info($"Steam connection closed because of problem. Reason: {data.m_info.m_eEndReason}, {data.m_info.m_szEndDebug}");
				HandleDisconnection((SteamDisconnectionReason)data.m_info.m_eEndReason, data.m_info.m_szEndDebug);
			}
			else if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_ClosedByPeer)
			{
				_logger.Info($"Steam connection closed by host. Reason: {data.m_info.m_eEndReason}, {data.m_info.m_szEndDebug}");
				HandleDisconnection((SteamDisconnectionReason)data.m_info.m_eEndReason, data.m_info.m_szEndDebug);
			}
		}

		private void HandleDisconnection(SteamDisconnectionReason reason, string debugReason)
		{
			if (_connectingTaskCompletionSource != null)
			{
				_connectingTaskCompletionSource.SetResult(new ConnectionResult
				{
					disconnectionReason = reason,
					debugReason = debugReason
				});
			}
			else
			{
				DisconnectFromHostInternal(reason, debugReason, now: true, selfInitiated: false);
			}
		}

		public override void Update()
		{
			SteamUtil.ProcessMessages(_conn.Value, _handler, _logger);
		}

		public override void SendMessageToHost(byte[] bytes, int length, NetTransferMode mode, int channel = 0)
		{
			_logger.VeryDebug($"Sending {length} bytes to host");
			GCHandle gCHandle = GCHandle.Alloc(bytes, GCHandleType.Pinned);
			try
			{
				EResult eResult = SteamNetworkingSockets.SendMessageToConnection(_conn.Value, gCHandle.AddrOfPinnedObject(), (uint)length, SteamUtil.FlagsFromMode(mode), out var _);
				if (eResult != EResult.k_EResultOK)
				{
					_logger.Warn($"Failed to send message length {length}: {eResult}");
				}
			}
			finally
			{
				gCHandle.Free();
			}
		}

		public override void DisconnectFromHost(NetError reason, bool now = false)
		{
			DisconnectFromHostInternal(reason.ToSteam(), string.Empty, now, selfInitiated: true);
		}

		private void CleanupLobby()
		{
			SteamMatchmaking.LeaveLobby(_lobbyId.Value);
			_lobbyId = null;
			_netStatusChangedCallback?.Dispose();
			_netStatusChangedCallback = null;
		}

		private void CleanupConnection(int closeReason, string? debugReason)
		{
			SteamNetworkingSockets.CloseConnection(_conn.Value, closeReason, debugReason, bEnableLinger: false);
			_conn = null;
			_connectingTaskCompletionSource = null;
			CleanupLobby();
		}

		private void DisconnectFromHostInternal(SteamDisconnectionReason reason, string? debugReason, bool now, bool selfInitiated)
		{
			_logger.Debug($"Disconnecting from host (now: {now} reason: {reason} debug: {debugReason})");
			SteamNetworkingSockets.CloseConnection(_conn.Value, (int)reason, debugReason, !now);
			SteamMatchmaking.LeaveLobby(_lobbyId.Value);
			ulong steamID = _hostNetId.m_SteamID;
			_conn = null;
			_lobbyId = null;
			_connectingTaskCompletionSource = null;
			_netStatusChangedCallback?.Dispose();
			_netStatusChangedCallback = null;
			_isConnected = false;
			_hostNetId = CSteamID.Nil;
			_handler.OnDisconnectedFromHost(steamID, new NetErrorInfo(reason, debugReason, selfInitiated));
		}

		private void CancelConnection()
		{
			_connectingTaskCompletionSource?.SetCanceled();
			if (_conn.HasValue)
			{
				DisconnectFromHost(NetError.Quit);
			}
			else if (_lobbyId.HasValue)
			{
				CleanupLobby();
			}
		}

		public override string? GetRawLobbyIdentifier()
		{
			return _lobbyId?.m_SteamID.ToString();
		}
	}
	public class SteamHost : NetHost
	{
		private struct ClientConnection
		{
			public HSteamNetConnection conn;

			public SteamNetworkingIdentity netId;
		}

		private static readonly List<ClientConnection> _connectionsCache = new List<ClientConnection>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("SteamHost", LogType.Network);

		private Callback<SteamNetConnectionStatusChangedCallback_t>? _netStatusChangedCallback;

		private CSteamID? _lobbyId;

		private HSteamListenSocket _socket;

		private readonly List<ClientConnection> _connections = new List<ClientConnection>();

		private bool _isConnected;

		public override bool IsConnected => _isConnected;

		public override ulong NetId => SteamUser.GetSteamID().m_SteamID;

		public override IEnumerable<ulong> ConnectedPeerIds => _connections.Select((ClientConnection c) => c.netId.GetSteamID64());

		public CSteamID? LobbyId => _lobbyId;

		public SteamHost(INetHostHandler handler)
			: base(handler)
		{
		}

		public async Task<NetErrorInfo?> StartHost(int maxPlayers)
		{
			_logger.Info($"Initializing Steam host. Our player id: {NetId}");
			SteamAPICall_t call = SteamMatchmaking.CreateLobby(ELobbyType.k_ELobbyTypeFriendsOnly, maxPlayers);
			using SteamCallResult<LobbyCreated_t> callResult = new SteamCallResult<LobbyCreated_t>(call, SteamInitializer.DisconnectToken);
			LobbyCreated_t lobbyCreated_t = await callResult.Task;
			if (lobbyCreated_t.m_eResult != EResult.k_EResultOK)
			{
				_logger.Error($"Error creating steam lobby! {lobbyCreated_t.m_eResult}");
				return new NetErrorInfo(lobbyCreated_t.m_eResult);
			}
			_lobbyId = new CSteamID(lobbyCreated_t.m_ulSteamIDLobby);
			_socket = SteamNetworkingSockets.CreateListenSocketP2P(0, 0, new SteamNetworkingConfigValue_t[2]
			{
				new SteamNetworkingConfigValue_t
				{
					m_eValue = ESteamNetworkingConfigValue.k_ESteamNetworkingConfig_TimeoutInitial,
					m_eDataType = ESteamNetworkingConfigDataType.k_ESteamNetworkingConfig_Int32,
					m_val = new SteamNetworkingConfigValue_t.OptionValue
					{
						m_int32 = 20000
					}
				},
				new SteamNetworkingConfigValue_t
				{
					m_eValue = ESteamNetworkingConfigValue.k_ESteamNetworkingConfig_TimeoutConnected,
					m_eDataType = ESteamNetworkingConfigDataType.k_ESteamNetworkingConfig_Int32,
					m_val = new SteamNetworkingConfigValue_t.OptionValue
					{
						m_int32 = 20000
					}
				}
			});
			_netStatusChangedCallback = new Callback<SteamNetConnectionStatusChangedCallback_t>(OnNetStatusChanged);
			_isConnected = true;
			return null;
		}

		public override void Update()
		{
			_connectionsCache.Clear();
			_connectionsCache.AddRange(_connections);
			foreach (ClientConnection item in _connectionsCache)
			{
				SteamUtil.ProcessMessages(item.conn, _handler, _logger);
			}
		}

		public override void SetHostIsClosed(bool isClosed)
		{
			SteamMatchmaking.SetLobbyType(_lobbyId.Value, (!isClosed) ? ELobbyType.k_ELobbyTypeFriendsOnly : ELobbyType.k_ELobbyTypePrivate);
		}

		private void OnNetStatusChanged(SteamNetConnectionStatusChangedCallback_t data)
		{
			_logger.Debug($"Connection status changed: ({data.m_info.m_identityRemote.GetSteamID64()}: {data.m_eOldState} -> {data.m_info.m_eState}");
			if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_Connecting)
			{
				if (!IsInLobby(data.m_info.m_identityRemote))
				{
					_logger.Warn($"Player with steam id {data.m_info.m_identityRemote.GetSteamID64()} attempted to join the game, but they are not in the lobby (id {_lobbyId.Value})");
					CloseConnectionAndRemove(data.m_hConn, NetError.TryAgainLater.ToSteam(), "Player is not in the lobby!", now: true, selfInitiated: false);
					return;
				}
				_logger.Info($"Accepting new connection with user {data.m_info.m_identityRemote.GetSteamID64()}");
				EResult eResult = SteamNetworkingSockets.AcceptConnection(data.m_hConn);
				if (eResult != EResult.k_EResultOK)
				{
					_logger.Error($"Tried to accept connection with user {data.m_info.m_identityRemote.GetSteamID64()} but it returned result {eResult}!");
					CloseConnectionAndRemove(data.m_hConn, SteamDisconnectionReason.AppInternalError, $"Connection accept failure: {eResult}", now: true, selfInitiated: false);
				}
			}
			else if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_Connected)
			{
				_connections.Add(new ClientConnection
				{
					conn = data.m_hConn,
					netId = data.m_info.m_identityRemote
				});
				_handler.OnPeerConnected(data.m_info.m_identityRemote.GetSteamID64());
			}
			else if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_ProblemDetectedLocally)
			{
				_logger.Info($"Steam connection closed because of problem. Reason: {data.m_info.m_eEndReason}, {data.m_info.m_szEndDebug}");
				CloseConnectionAndRemove(data.m_hConn, (SteamDisconnectionReason)data.m_info.m_eEndReason, data.m_info.m_szEndDebug, now: true, selfInitiated: false);
			}
			else if (data.m_info.m_eState == ESteamNetworkingConnectionState.k_ESteamNetworkingConnectionState_ClosedByPeer)
			{
				_logger.Info($"Steam connection closed by peer. Reason: {data.m_info.m_eEndReason}, {data.m_info.m_szEndDebug}");
				CloseConnectionAndRemove(data.m_hConn, (SteamDisconnectionReason)data.m_info.m_eEndReason, data.m_info.m_szEndDebug, now: true, selfInitiated: false);
			}
		}

		public override void SendMessageToClient(ulong peerId, byte[] bytes, int length, NetTransferMode mode, int channel = 0)
		{
			_logger.VeryDebug($"Sending {length} bytes to client {peerId}");
			default(SteamNetworkingIdentity).SetSteamID64(peerId);
			ClientConnection? connectionForNetId = GetConnectionForNetId(peerId);
			if (!connectionForNetId.HasValue)
			{
				throw new InvalidOperationException($"Could not find connection for peer {peerId}!");
			}
			GCHandle gCHandle = GCHandle.Alloc(bytes, GCHandleType.Pinned);
			try
			{
				EResult eResult = SteamNetworkingSockets.SendMessageToConnection(connectionForNetId.Value.conn, gCHandle.AddrOfPinnedObject(), (uint)length, SteamUtil.FlagsFromMode(mode), out var _);
				if (eResult != EResult.k_EResultOK)
				{
					_logger.Warn($"Failed to send message length {length} to peer {peerId}: {eResult}");
				}
			}
			finally
			{
				gCHandle.Free();
			}
		}

		public override void SendMessageToAll(byte[] bytes, int length, NetTransferMode mode, int channel = 0)
		{
			foreach (ClientConnection connection in _connections)
			{
				SteamNetworkingIdentity netId = connection.netId;
				SendMessageToClient(netId.GetSteamID64(), bytes, length, mode, channel);
			}
		}

		private ClientConnection? GetConnectionForNetId(ulong peerId)
		{
			foreach (ClientConnection connection in _connections)
			{
				SteamNetworkingIdentity netId = connection.netId;
				if (netId.GetSteamID64() == peerId)
				{
					return connection;
				}
			}
			return null;
		}

		public override void DisconnectClient(ulong peerId, NetError reason, bool now = false)
		{
			HSteamNetConnection? hSteamNetConnection = null;
			_logger.Debug($"Disconnecting peer {peerId}, reason: {reason}");
			foreach (ClientConnection connection in _connections)
			{
				SteamNetworkingIdentity netId = connection.netId;
				if (netId.GetSteamID64() == peerId)
				{
					hSteamNetConnection = connection.conn;
					break;
				}
			}
			if (hSteamNetConnection.HasValue)
			{
				CloseConnectionAndRemove(hSteamNetConnection.Value, reason.ToSteam(), null, now, selfInitiated: true);
			}
		}

		private void CloseConnectionAndRemove(HSteamNetConnection conn, SteamDisconnectionReason reason, string? debugReason, bool now, bool selfInitiated)
		{
			SteamNetworkingSockets.CloseConnection(conn, (int)reason, debugReason, !now);
			int num = _connections.FindIndex((ClientConnection c) => c.conn == conn);
			if (num >= 0)
			{
				ClientConnection clientConnection = _connections[num];
				_connections.RemoveAt(num);
				_handler.OnPeerDisconnected(clientConnection.netId.GetSteamID64(), new NetErrorInfo(reason, debugReason, selfInitiated));
			}
		}

		public override void StopHost(NetError reason, bool now = false)
		{
			_logger.Debug("Stopping host");
			foreach (ClientConnection connection in _connections)
			{
				SteamNetworkingSockets.CloseConnection(connection.conn, (int)reason.ToSteam(), null, !now);
			}
			_connections.Clear();
			SteamMatchmaking.LeaveLobby(_lobbyId.Value);
			if (now)
			{
				SteamNetworkingSockets.CloseListenSocket(_socket);
			}
			else
			{
				TaskHelper.RunSafely(CloseSocketAfterDelay(_socket));
			}
			_lobbyId = null;
			_isConnected = false;
			_netStatusChangedCallback?.Dispose();
			_netStatusChangedCallback = null;
			_handler.OnDisconnected(new NetErrorInfo(reason, selfInitiated: true));
		}

		private async Task CloseSocketAfterDelay(HSteamListenSocket socket)
		{
			await Task.Delay(1000);
			_logger.Debug("Closing socket after delay.");
			SteamNetworkingSockets.CloseListenSocket(socket);
		}

		private bool IsInLobby(SteamNetworkingIdentity id)
		{
			CSteamID steamID = id.GetSteamID();
			if (steamID == CSteamID.Nil)
			{
				return false;
			}
			int numLobbyMembers = SteamMatchmaking.GetNumLobbyMembers(_lobbyId.Value);
			for (int i = 0; i < numLobbyMembers; i++)
			{
				CSteamID lobbyMemberByIndex = SteamMatchmaking.GetLobbyMemberByIndex(_lobbyId.Value, i);
				if (steamID == lobbyMemberByIndex)
				{
					return true;
				}
			}
			return false;
		}

		public override string? GetRawLobbyIdentifier()
		{
			return _lobbyId?.m_SteamID.ToString();
		}
	}
	public static class SteamUtil
	{
		private static readonly nint[] _messageBuffer = new nint[64];

		public static NetTransferMode ModeFromFlags(int flags)
		{
			if ((flags & 8) > 0)
			{
				return NetTransferMode.Reliable;
			}
			if (flags == 0)
			{
				return NetTransferMode.Unreliable;
			}
			throw new ArgumentOutOfRangeException();
		}

		public static int FlagsFromMode(NetTransferMode mode)
		{
			return mode switch
			{
				NetTransferMode.Unreliable => 0, 
				NetTransferMode.Reliable => 8, 
				_ => throw new ArgumentOutOfRangeException("mode", mode, null), 
			};
		}

		public static SteamNetworkingIdentity ToNetId(this CSteamID id)
		{
			SteamNetworkingIdentity result = default(SteamNetworkingIdentity);
			result.SetSteamID(id);
			return result;
		}

		public static SteamNetworkingIdentity ToNetId64(this ulong id)
		{
			SteamNetworkingIdentity result = default(SteamNetworkingIdentity);
			result.SetSteamID64(id);
			return result;
		}

		public static void ProcessMessages(HSteamNetConnection conn, INetHandler handler, MegaCrit.Sts2.Core.Logging.Logger logger)
		{
			int num;
			do
			{
				num = SteamNetworkingSockets.ReceiveMessagesOnConnection(conn, _messageBuffer, _messageBuffer.Length);
				if (num > 0)
				{
					logger.VeryDebug($"Processing {num} packets");
				}
				for (int i = 0; i < num; i++)
				{
					nint num2 = _messageBuffer[i];
					try
					{
						SteamNetworkingMessage_t steamNetworkingMessage_t = Marshal.PtrToStructure<SteamNetworkingMessage_t>(num2);
						byte[] array = new byte[steamNetworkingMessage_t.m_cbSize];
						Marshal.Copy(steamNetworkingMessage_t.m_pData, array, 0, steamNetworkingMessage_t.m_cbSize);
						NetTransferMode netTransferMode = ModeFromFlags(steamNetworkingMessage_t.m_nFlags);
						logger.VeryDebug($"Received packet of size {array.Length} from sender {steamNetworkingMessage_t.m_identityPeer.GetSteamID64()} ({netTransferMode}, {steamNetworkingMessage_t.m_nChannel})");
						handler.OnPacketReceived(steamNetworkingMessage_t.m_identityPeer.GetSteamID().m_SteamID, array, netTransferMode, steamNetworkingMessage_t.m_nChannel);
					}
					catch (Exception value)
					{
						logger.Error($"Failed to handle packet {i + 1} of {num}: {value}");
					}
					finally
					{
						SteamNetworkingMessage_t.Release(num2);
					}
				}
			}
			while (num == _messageBuffer.Length);
		}
	}
	[Flags]
	public enum SteamNetworkingSend
	{
		Unreliable = 0,
		Reliable = 8,
		NoNagle = 1,
		NoDelay = 4
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Transport.ENet
{
	public class ENetClient : NetClient
	{
		private const int _handshakeTimeoutMsec = 10000;

		private const int _handshakeUpdateRateMsec = 100;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("ENetClient", LogType.Network);

		private ENetConnection? _connection;

		private ENetPacketPeer? _peer;

		private bool _isConnected;

		private ulong _netId;

		public override bool IsConnected => _isConnected;

		public override ulong NetId => _netId;

		public override ulong HostNetId => 1uL;

		public ENetClient(INetClientHandler handler)
			: base(handler)
		{
		}

		public async Task<NetErrorInfo?> ConnectToHost(ulong netId, string ip, ushort port, CancellationToken cancelToken = default(CancellationToken))
		{
			_connection = new ENetConnection();
			_connection.CreateHost();
			_peer = _connection.ConnectToHost(ip, port);
			int timeoutTimer = 0;
			ENetServiceData? output;
			while (!_connection.TryService(out output) || output.Value.type != ENetConnection.EventType.Connect)
			{
				await Task.Delay(100, cancelToken);
				if (cancelToken.IsCancellationRequested)
				{
					DisconnectFromHost(NetError.CancelledJoin);
					_logger.Warn("User cancelled join flow");
					return null;
				}
				timeoutTimer += 100;
				if (timeoutTimer > 10000)
				{
					_peer.Reset();
					_logger.Error("Connection timed out!");
					return new NetErrorInfo(NetError.Timeout, selfInitiated: false);
				}
			}
			if (_peer.GetState() != ENetPacketPeer.PeerState.Connected)
			{
				_logger.Error($"Connection to {ip}:{port} failed!");
				return new NetErrorInfo(NetError.UnknownNetworkError, selfInitiated: false);
			}
			List<ENetServiceData> bufferedPackets = new List<ENetServiceData>();
			NetErrorInfo? result = await SendAndWaitForNetIdAck(netId, bufferedPackets, cancelToken);
			if (result.HasValue)
			{
				_peer.PeerDisconnect();
				return result;
			}
			_netId = netId;
			_isConnected = true;
			_handler.OnConnectedToHost();
			foreach (ENetServiceData item in bufferedPackets)
			{
				HandleMessageReceived(item);
			}
			return null;
		}

		private async Task<NetErrorInfo?> SendAndWaitForNetIdAck(ulong netId, List<ENetServiceData> bufferedPackets, CancellationToken cancelToken = default(CancellationToken))
		{
			_logger.Info($"Sending handshake with net ID {netId}");
			ENetPacket eNetPacket = ENetPacket.FromHandshakeRequest(new ENetHandshakeRequest
			{
				netId = netId
			});
			_peer.Send(0, eNetPacket.AllBytes, 1);
			bool receivedAck = false;
			int timeoutTimer = 0;
			while (!receivedAck)
			{
				await Task.Delay(100, cancelToken);
				if (cancelToken.IsCancellationRequested)
				{
					_logger.Warn("User cancelled join flow");
					DisconnectFromHost(NetError.CancelledJoin);
					return null;
				}
				if (_connection.TryService(out var output) && output.Value.type == ENetConnection.EventType.Receive)
				{
					byte[] packetData = output.Value.packetData;
					ENetPacket eNetPacket2 = new ENetPacket(packetData);
					if (eNetPacket2.PacketType == ENetPacketType.ApplicationMessage)
					{
						bufferedPackets.Add(output.Value);
						continue;
					}
					ENetHandshakeResponse eNetHandshakeResponse = eNetPacket2.AsHandshakeResponse();
					if (eNetHandshakeResponse.netId != netId)
					{
						_logger.Error($"Received net ID ({eNetHandshakeResponse.netId}) during handshake that did not match ours!");
						return new NetErrorInfo(NetError.InternalError, selfInitiated: false);
					}
					if (eNetHandshakeResponse.status != ENetHandshakeStatus.Success)
					{
						_logger.Error($"Received non-success code during handshake ({eNetHandshakeResponse.status})!");
						return new NetErrorInfo(NetError.Kicked, selfInitiated: false);
					}
					receivedAck = true;
				}
				timeoutTimer += 100;
				if (timeoutTimer > 10000)
				{
					_logger.Error("Timed out waiting for handshake ack!");
					DisconnectFromHost(NetError.Timeout);
					return new NetErrorInfo(NetError.Timeout, selfInitiated: false);
				}
			}
			return null;
		}

		public override void Update()
		{
			AssertClientStarted();
			while (true)
			{
				ENetPacketPeer? peer = _peer;
				if (peer == null || !peer.IsActive())
				{
					break;
				}
				ENetConnection? connection = _connection;
				if (connection == null || !connection.TryService(out var output))
				{
					break;
				}
				ENetConnection.EventType type = output.Value.type;
				ENetConnection.EventType num = type - -1;
				if ((ulong)num <= 4uL)
				{
					switch ((int)num)
					{
					case 0:
						_logger.Error($"Got error from ENetConnection! Error: {output.Value.error} TODO: Expand me");
						continue;
					case 2:
						_logger.Debug("Received connect on client");
						continue;
					case 3:
						_logger.Debug($"Received disconnect on client. Already disconnected: {!_isConnected}");
						if (_isConnected)
						{
							_isConnected = false;
							_handler.OnDisconnectedFromHost(HostNetId, new NetErrorInfo(NetError.UnknownNetworkError, selfInitiated: false));
						}
						continue;
					case 4:
						HandleMessageReceived(output.Value);
						continue;
					}
				}
				throw new ArgumentOutOfRangeException();
			}
		}

		private void HandleMessageReceived(ENetServiceData data)
		{
			if (_isConnected)
			{
				_logger.VeryDebug($"Received packet of length {data.packetData.Length}");
				ENetPacket eNetPacket = new ENetPacket(data.packetData);
				if (eNetPacket.PacketType == ENetPacketType.ApplicationMessage)
				{
					_handler.OnPacketReceived(1uL, eNetPacket.AsAppMessage(), data.mode, data.channel);
				}
				else if (eNetPacket.PacketType == ENetPacketType.Disconnection)
				{
					ENetDisconnection eNetDisconnection = eNetPacket.AsDisconnection();
					_logger.Debug($"Received disconnection packet with reason: {eNetDisconnection.reason}");
					_handler.OnDisconnectedFromHost(HostNetId, new NetErrorInfo(eNetDisconnection.reason, selfInitiated: false));
					_isConnected = false;
				}
				else
				{
					_logger.Error($"Got unexpected packet of type {eNetPacket.PacketType} while we were connected to the host!");
				}
			}
		}

		public override void DisconnectFromHost(NetError reason, bool now = false)
		{
			if (now)
			{
				_peer?.PeerDisconnectNow();
			}
			else
			{
				ENetPacket eNetPacket = ENetPacket.FromDisconnection(new ENetDisconnection
				{
					reason = reason
				});
				_peer?.Send(0, eNetPacket.AllBytes, 8);
				_peer?.PeerDisconnectLater();
			}
			_connection?.Flush();
			if (_isConnected)
			{
				_isConnected = false;
				_handler.OnDisconnectedFromHost(HostNetId, new NetErrorInfo(reason, selfInitiated: true));
				_connection?.Destroy();
			}
		}

		public override void SendMessageToHost(byte[] bytes, int length, NetTransferMode mode, int channel = 0)
		{
			if (!_isConnected)
			{
				throw new InvalidOperationException("Tried to send message to host while disconnected!");
			}
			AssertClientStarted();
			ENetPacket eNetPacket = ENetPacket.FromAppMessage(bytes, length);
			_logger.VeryDebug($"Sending packet of length {eNetPacket.AllBytes.Length}");
			_peer?.Send(channel, eNetPacket.AllBytes, ENetUtil.FlagsFromMode(mode));
		}

		private void AssertClientStarted()
		{
			if (_connection == null)
			{
				throw new InvalidOperationException("Must call ConnectToHost first and wait for connection!");
			}
		}

		public override string? GetRawLobbyIdentifier()
		{
			return null;
		}
	}
	public static class ENetConnectionExtension
	{
		/// <summary>
		/// Polls an ENetConnection, returning the events that have occurred since the last poll.
		/// This wraps ENet.Service into a more digestible method.
		/// </summary>
		/// <param name="connection">The connection to poll.</param>
		/// <param name="output">The event we polled from the connection, if any.</param>
		/// <returns></returns>
		public static bool TryService(this ENetConnection connection, out ENetServiceData? output)
		{
			Godot.Collections.Array array = connection.Service();
			output = null;
			if (array == null)
			{
				return false;
			}
			ENetConnection.EventType eventType = array[0].As<ENetConnection.EventType>();
			if (eventType == ENetConnection.EventType.None)
			{
				return false;
			}
			ENetServiceData value = new ENetServiceData
			{
				type = eventType,
				peer = array[1].As<ENetPacketPeer>(),
				originalData = array
			};
			if (eventType == ENetConnection.EventType.Receive)
			{
				value.channel = array[3].As<int>();
				value.packetData = value.peer.GetPacket();
				value.error = value.peer.GetPacketError();
				value.mode = NetTransferMode.None;
			}
			output = value;
			return true;
		}
	}
	public struct ENetServiceData
	{
		public ENetConnection.EventType type;

		public ENetPacketPeer peer;

		public int channel;

		public NetTransferMode mode;

		public byte[] packetData;

		public Error error;

		public Godot.Collections.Array originalData;
	}
	public struct ENetDisconnection
	{
		public NetError reason;
	}
	public struct ENetHandshakeRequest
	{
		public ulong netId;
	}
	public struct ENetHandshakeResponse
	{
		public ENetHandshakeStatus status;

		public ulong netId;
	}
	public enum ENetHandshakeStatus : byte
	{
		Success,
		IdCollision
	}
	public class ENetHost : NetHost
	{
		private record struct ClientConnection
		{
			public ulong netId;

			public ENetPacketPeer peer;
		}

		private struct HandshakeAwaitingResponse
		{
			public ulong receivedMsec;

			public ClientConnection conn;
		}

		private const int _handshakeTimeoutMsec = 10000;

		private const int _handshakeUpdateRateMsec = 100;

		private readonly List<ClientConnection> _connectedPeers = new List<ClientConnection>();

		private ENetConnection? _connection;

		private bool _isConnected;

		private readonly List<HandshakeAwaitingResponse> _receivedHandshakes = new List<HandshakeAwaitingResponse>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("ENetHost", LogType.Network);

		public override bool IsConnected => _isConnected;

		public override IEnumerable<ulong> ConnectedPeerIds => _connectedPeers.Select((ClientConnection c) => c.netId);

		public override ulong NetId => 1uL;

		public ENetHost(INetHostHandler handler)
			: base(handler)
		{
		}

		public NetErrorInfo? StartHost(ushort port, int maxClients)
		{
			_connection = new ENetConnection();
			Error error = _connection.CreateHostBound("0.0.0.0", port, maxClients);
			if (error != Error.Ok)
			{
				_logger.Error($"Failed to create host! {error}");
				return new NetErrorInfo(error);
			}
			_isConnected = true;
			return null;
		}

		private async Task DoClientHandshake(ENetPacketPeer peer)
		{
			peer.SetTimeout(24, 20000, 20000);
			int timeoutTimer = 0;
			HandshakeAwaitingResponse? handshake = null;
			while (!handshake.HasValue)
			{
				foreach (HandshakeAwaitingResponse receivedHandshake in _receivedHandshakes)
				{
					if (receivedHandshake.conn.peer == peer)
					{
						handshake = receivedHandshake;
						break;
					}
				}
				if (!handshake.HasValue)
				{
					await Task.Delay(100);
					timeoutTimer += 100;
					if (timeoutTimer >= 10000)
					{
						_logger.Error("Timed out waiting for handshake!");
						peer.Reset();
						return;
					}
				}
			}
			if (GetConnectionById(handshake.Value.conn.netId).HasValue)
			{
				_logger.Info($"Second client attempted to connect with peer ID {handshake.Value.conn.netId}, disconnecting them");
				ENetPacket eNetPacket = ENetPacket.FromHandshakeResponse(new ENetHandshakeResponse
				{
					netId = handshake.Value.conn.netId,
					status = ENetHandshakeStatus.IdCollision
				});
				handshake.Value.conn.peer.Send(0, eNetPacket.AllBytes, 1);
				handshake.Value.conn.peer.PeerDisconnect();
			}
			else
			{
				_logger.Debug($"Acknowledging handshake for peer with ID {handshake.Value.conn.netId}");
				ENetPacket eNetPacket2 = ENetPacket.FromHandshakeResponse(new ENetHandshakeResponse
				{
					netId = handshake.Value.conn.netId,
					status = ENetHandshakeStatus.Success
				});
				handshake.Value.conn.peer.Send(0, eNetPacket2.AllBytes, 1);
				_connectedPeers.Add(handshake.Value.conn);
				_handler.OnPeerConnected(handshake.Value.conn.netId);
			}
		}

		private void HandleClientDisconnection(ClientConnection conn, NetError reason, bool notifyHandler = true)
		{
			_logger.Debug($"Peer ID {conn.netId} disconnected, reason: {reason}");
			_connectedPeers.Remove(conn);
			if (notifyHandler)
			{
				_handler.OnPeerDisconnected(conn.netId, new NetErrorInfo(reason, selfInitiated: false));
			}
		}

		private ClientConnection? GetConnectionByPeer(ENetPacketPeer peer)
		{
			foreach (ClientConnection connectedPeer in _connectedPeers)
			{
				if (connectedPeer.peer == peer)
				{
					return connectedPeer;
				}
			}
			return null;
		}

		private ClientConnection? GetConnectionById(ulong id)
		{
			foreach (ClientConnection connectedPeer in _connectedPeers)
			{
				if (connectedPeer.netId == id)
				{
					return connectedPeer;
				}
			}
			return null;
		}

		public override void Update()
		{
			AssertHostStarted();
			ENetServiceData? output;
			while (_connection.TryService(out output))
			{
				ENetConnection.EventType type = output.Value.type;
				ENetConnection.EventType num = type - -1;
				if ((ulong)num <= 4uL)
				{
					switch ((int)num)
					{
					case 3:
						continue;
					case 0:
						_logger.Error("Got error from ENetConnection! TODO: Expand me");
						continue;
					case 2:
						TaskHelper.RunSafely(DoClientHandshake(output.Value.peer));
						continue;
					case 4:
						HandlePacketReceived(output.Value);
						continue;
					}
				}
				throw new ArgumentOutOfRangeException();
			}
		}

		private void HandlePacketReceived(ENetServiceData data)
		{
			byte[] packetData = data.packetData;
			_logger.VeryDebug($"Received packet of length {packetData.Length}");
			ENetPacketPeer peer = data.peer;
			ENetPacket eNetPacket = new ENetPacket(packetData);
			if (eNetPacket.PacketType == ENetPacketType.HandshakeRequest)
			{
				ENetHandshakeRequest eNetHandshakeRequest = eNetPacket.AsHandshakeRequest();
				ClientConnection conn = new ClientConnection
				{
					peer = peer,
					netId = eNetHandshakeRequest.netId
				};
				HandshakeAwaitingResponse item = new HandshakeAwaitingResponse
				{
					conn = conn,
					receivedMsec = Time.GetTicksMsec()
				};
				_logger.Debug($"Received handshake packet containing peer ID {conn.netId}");
				_receivedHandshakes.Add(item);
			}
			else if (eNetPacket.PacketType == ENetPacketType.Disconnection)
			{
				ENetDisconnection eNetDisconnection = eNetPacket.AsDisconnection();
				ClientConnection? connectionByPeer = GetConnectionByPeer(peer);
				if (connectionByPeer.HasValue)
				{
					HandleClientDisconnection(connectionByPeer.Value, eNetDisconnection.reason);
				}
			}
			else
			{
				ClientConnection? connectionByPeer2 = GetConnectionByPeer(peer);
				if (!connectionByPeer2.HasValue)
				{
					_logger.Error($"Received a non-handshake packet length {packetData.Length} for a peer, but no connection exists!");
				}
				else
				{
					_handler.OnPacketReceived(connectionByPeer2.Value.netId, eNetPacket.AsAppMessage(), data.mode, data.channel);
				}
			}
		}

		public override void SendMessageToClient(ulong peerId, byte[] bytes, int length, NetTransferMode mode, int channel = 0)
		{
			AssertHostStarted();
			ClientConnection? connectionById = GetConnectionById(peerId);
			if (!connectionById.HasValue)
			{
				_logger.Error($"Tried to send message to client with ID {peerId}, but no client with that ID is connected!");
			}
			else
			{
				ENetPacket eNetPacket = ENetPacket.FromAppMessage(bytes, length);
				_logger.VeryDebug($"Sending packet of length {eNetPacket.AllBytes.Length}");
				connectionById.Value.peer.Send(channel, eNetPacket.AllBytes, ENetUtil.FlagsFromMode(mode));
			}
		}

		public override void DisconnectClient(ulong peerId, NetError reason, bool now = false)
		{
			DisconnectClientInternal(peerId, reason, now);
		}

		private void DisconnectClientInternal(ulong peerId, NetError reason, bool now = false, bool notifyHandler = true)
		{
			_logger.Info($"Disconnecting client {peerId}, reason: {reason}. Now: {now}");
			AssertHostStarted();
			ClientConnection? connectionById = GetConnectionById(peerId);
			if (connectionById.HasValue)
			{
				if (now)
				{
					connectionById.Value.peer.PeerDisconnectNow();
				}
				else
				{
					ENetPacket eNetPacket = ENetPacket.FromDisconnection(new ENetDisconnection
					{
						reason = reason
					});
					connectionById.Value.peer.Send(0, eNetPacket.AllBytes, 1);
					connectionById.Value.peer.PeerDisconnectLater();
				}
				HandleClientDisconnection(connectionById.Value, reason, notifyHandler);
			}
		}

		public override void SendMessageToAll(byte[] bytes, int length, NetTransferMode mode, int channel = 0)
		{
			AssertHostStarted();
			foreach (ClientConnection connectedPeer in _connectedPeers)
			{
				SendMessageToClient(connectedPeer.netId, bytes, length, mode, channel);
			}
		}

		public override void SetHostIsClosed(bool isClosed)
		{
		}

		public override void StopHost(NetError reason, bool now = false)
		{
			Log.Info($"Stopping host. Reason: {reason}. Now: {now}");
			foreach (ClientConnection item in _connectedPeers.ToList())
			{
				DisconnectClientInternal(item.netId, reason, now, notifyHandler: false);
			}
			_connectedPeers.Clear();
			_connection.Flush();
			_connection.Destroy();
			_isConnected = false;
			_handler.OnDisconnected(new NetErrorInfo(reason, selfInitiated: true));
		}

		private void AssertHostStarted()
		{
			if (_connection == null)
			{
				throw new InvalidOperationException("Must call StartHost first!");
			}
		}

		public override string? GetRawLobbyIdentifier()
		{
			return null;
		}
	}
	public class ENetPacket
	{
		private readonly byte[] _packetBytes;

		public ENetPacketType PacketType => (ENetPacketType)_packetBytes[0];

		public byte[] AllBytes => _packetBytes;

		public ENetPacket(byte[] bytes)
		{
			_packetBytes = bytes;
		}

		public static ENetPacket FromHandshakeRequest(ENetHandshakeRequest request)
		{
			byte[] array = new byte[9] { 0, 0, 0, 0, 0, 0, 0, 0, 0 };
			Span<byte> span = array.AsSpan();
			BinaryPrimitives.WriteUInt64BigEndian(span.Slice(1, span.Length - 1), request.netId);
			return new ENetPacket(array);
		}

		public ENetHandshakeRequest AsHandshakeRequest()
		{
			if (PacketType != ENetPacketType.HandshakeRequest)
			{
				throw new InvalidOperationException($"Attempted to interpret ENet packet of type {PacketType} as handshake request");
			}
			ulong netId = BinaryPrimitives.ReadUInt64BigEndian(_packetBytes[1..]);
			return new ENetHandshakeRequest
			{
				netId = netId
			};
		}

		public static ENetPacket FromHandshakeResponse(ENetHandshakeResponse response)
		{
			byte[] array = new byte[10]
			{
				1,
				(byte)response.status,
				0,
				0,
				0,
				0,
				0,
				0,
				0,
				0
			};
			Span<byte> span = array.AsSpan();
			BinaryPrimitives.WriteUInt64BigEndian(span.Slice(2, span.Length - 2), response.netId);
			return new ENetPacket(array);
		}

		public ENetHandshakeResponse AsHandshakeResponse()
		{
			if (PacketType != ENetPacketType.HandshakeResponse)
			{
				throw new InvalidOperationException($"Attempted to interpret ENet packet of type {PacketType} as handshake response");
			}
			ENetHandshakeStatus status = (ENetHandshakeStatus)_packetBytes[1];
			ulong netId = BinaryPrimitives.ReadUInt64BigEndian(_packetBytes[2..]);
			return new ENetHandshakeResponse
			{
				netId = netId,
				status = status
			};
		}

		public static ENetPacket FromDisconnection(ENetDisconnection disconnection)
		{
			return new ENetPacket(new byte[2]
			{
				2,
				(byte)disconnection.reason
			});
		}

		public ENetDisconnection AsDisconnection()
		{
			if (PacketType != ENetPacketType.Disconnection)
			{
				throw new InvalidOperationException($"Attempted to interpret ENet packet of type {PacketType} as disconnection");
			}
			NetError reason = (NetError)_packetBytes[1];
			return new ENetDisconnection
			{
				reason = reason
			};
		}

		public static ENetPacket FromAppMessage(byte[] messageBytes, int count)
		{
			byte[] array = new byte[count + 1];
			array[0] = 3;
			System.Array.Copy(messageBytes, 0, array, 1, count);
			return new ENetPacket(array);
		}

		public byte[] AsAppMessage()
		{
			if (PacketType != ENetPacketType.ApplicationMessage)
			{
				throw new InvalidOperationException($"Attempted to interpret ENet packet of type {PacketType} as disconnection");
			}
			return _packetBytes[1..];
		}
	}
	public enum ENetPacketType : byte
	{
		HandshakeRequest,
		HandshakeResponse,
		Disconnection,
		ApplicationMessage
	}
	public static class ENetUtil
	{
		public static NetTransferMode ModeFromFlags(int flags)
		{
			if ((long)((ulong)flags & 1uL) > 0L)
			{
				return NetTransferMode.Reliable;
			}
			if ((long)((ulong)flags & 8uL) > 0L)
			{
				return NetTransferMode.Unreliable;
			}
			throw new ArgumentOutOfRangeException($"Flags {flags} cannot be mapped to NetTransferMode!");
		}

		public static int FlagsFromMode(NetTransferMode mode)
		{
			return mode switch
			{
				NetTransferMode.Unreliable => 8, 
				NetTransferMode.Reliable => 1, 
				_ => throw new ArgumentOutOfRangeException("mode", mode, null), 
			};
		}
	}
