	/// <summary>
	/// Bidirectional map of types to unique integer IDs, for use in serialization.
	/// </summary>
	/// <typeparam name="TBase">All classes which implement this type will automatically be mapped by this class.</typeparam>
	public class NetTypeCache<[DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.Interfaces)] TBase> where TBase : class
	{
		private readonly System.Collections.Generic.Dictionary<Type, int> _typeToId = new System.Collections.Generic.Dictionary<Type, int>();

		private readonly List<Type> _idToType;

		public int Count => _idToType.Count;

		public NetTypeCache(List<Type> types)
		{
			IEnumerable<ContentSorter<string>.Item> source = ContentSorter<string>.Sort(types, (Type t) => t.Name);
			_idToType = source.Select((ContentSorter<string>.Item i) => i.type).ToList();
			for (int num = 0; num < _idToType.Count; num++)
			{
				Type type = _idToType[num];
				if (!Enumerable.Contains<Type>(type.GetInterfaces(), typeof(TBase)))
				{
					throw new InvalidOperationException($"Type {_idToType[num]} does not implement interface {typeof(TBase)}!");
				}
				_typeToId[type] = num;
			}
		}

		/// <summary>
		/// Obtain the ID for a given type.
		/// </summary>
		/// <typeparam name="T">The type to map.</typeparam>
		/// <returns>The integer ID for the type T.</returns>
		/// <exception cref="T:System.InvalidOperationException">Thrown if T does not implement TBase.</exception>
		public int TypeToId<T>() where T : TBase
		{
			return TypeToId(typeof(T));
		}

		/// <summary>
		/// Obtain the ID for a given type.
		/// </summary>
		/// <param name="type">The type to map.</param>
		/// <returns>The integer ID for the given type.</returns>
		/// <exception cref="T:System.InvalidOperationException">Thrown if type does not implement TBase.</exception>
		public int TypeToId(Type type)
		{
			return _typeToId[type];
		}

		/// <summary>
		/// Obtain the type for a given integer ID.
		/// </summary>
		/// <param name="id">The ID to map to a type.</param>
		/// <param name="type">The type for the given ID.</param>
		/// <returns>True if a type was found for the ID, false otherwise.</returns>
		public bool TryGetTypeFromId(int id, out Type? type)
		{
			if (id < 0 || id >= _idToType.Count)
			{
				type = null;
				return false;
			}
			type = _idToType[id];
			return true;
		}
	}
	public class PacketReader
	{
		private readonly byte[] _tempBuffer = new byte[16];

		private byte[] _stringBuffer = new byte[64];

		public int BitPosition { get; private set; }

		public byte[] Buffer { get; private set; }

		public void Reset(byte[] buffer)
		{
			BitPosition = 0;
			Buffer = buffer;
		}

		public bool ReadBool()
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, 1);
			BitPosition++;
			return _tempBuffer[0] != 0;
		}

		public byte ReadByte(int bits = 8)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return _tempBuffer[0];
		}

		public void ReadBytes(byte[] destinationBuffer, int byteCount)
		{
			BitSerializationUtil.ReadBits(Buffer, BitPosition, destinationBuffer, byteCount * 8);
			BitPosition += byteCount * 8;
		}

		public short ReadShort(int bits = 16)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return BinaryPrimitives.ReadInt16LittleEndian(_tempBuffer.AsSpan());
		}

		public ushort ReadUShort(int bits = 16)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return BinaryPrimitives.ReadUInt16LittleEndian(_tempBuffer.AsSpan());
		}

		public T ReadEnum<T>() where T : struct, Enum
		{
			if (!typeof(int).IsAssignableFrom(Enum.GetUnderlyingType(typeof(T))))
			{
				throw new InvalidOperationException($"Trying to write enum type {typeof(T)} that is not assignable to int!");
			}
			int bits = Mathf.CeilToInt(Math.Log2(MaxEnumValueCache.Get<T>()) + 1.0);
			int value = ReadInt(bits);
			return (T)Enum.ToObject(typeof(T), value);
		}

		public int ReadInt(int bits = 32)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return BinaryPrimitives.ReadInt32LittleEndian(_tempBuffer.AsSpan());
		}

		public uint ReadUInt(int bits = 32)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return BinaryPrimitives.ReadUInt32LittleEndian(_tempBuffer.AsSpan());
		}

		public float ReadFloat(QuantizeParams? quantizeParams = null)
		{
			System.Array.Clear(_tempBuffer);
			if (quantizeParams.HasValue)
			{
				uint value = ReadUInt(quantizeParams.Value.bits);
				return Unquantize(value, quantizeParams.Value.min, quantizeParams.Value.max, quantizeParams.Value.bits);
			}
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, 32);
			BitPosition += 32;
			return BinaryPrimitives.ReadSingleLittleEndian(_tempBuffer.AsSpan());
		}

		public long ReadLong(int bits = 64)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return BinaryPrimitives.ReadInt64LittleEndian(_tempBuffer.AsSpan());
		}

		public ulong ReadULong(int bits = 64)
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, bits);
			BitPosition += bits;
			return BinaryPrimitives.ReadUInt64LittleEndian(_tempBuffer.AsSpan());
		}

		public double ReadDouble()
		{
			System.Array.Clear(_tempBuffer);
			BitSerializationUtil.ReadBits(Buffer, BitPosition, _tempBuffer, 64);
			BitPosition += 64;
			return BinaryPrimitives.ReadDoubleLittleEndian(_tempBuffer.AsSpan());
		}

		public Godot.Vector2 ReadVector2(QuantizeParams? quantizeParamsX = null, QuantizeParams? quantizeParamsY = null)
		{
			float x = ReadFloat(quantizeParamsX);
			float y = ReadFloat(quantizeParamsY);
			return new Godot.Vector2(x, y);
		}

		public List<T> ReadList<T>(int lengthBits = 32) where T : IPacketSerializable, new()
		{
			List<T> list = new List<T>();
			int num = ReadInt(lengthBits);
			for (int i = 0; i < num; i++)
			{
				list.Add(Read<T>());
			}
			return list;
		}

		public string ReadString()
		{
			int num = ReadInt();
			if (_stringBuffer.Length < num)
			{
				int num2 = (int)Math.Pow(2.0, Math.Ceiling(Math.Log2(num)));
				_stringBuffer = new byte[num2];
			}
			ReadBytes(_stringBuffer, num);
			return Encoding.UTF8.GetString(_stringBuffer, 0, num);
		}

		public T Read<T>() where T : IPacketSerializable, new()
		{
			T result = new T();
			result.Deserialize(this);
			return result;
		}

		public static float Unquantize(uint value, float min, float max, int bitLength)
		{
			return (float)((double)value / Math.Pow(2.0, bitLength) * (double)(max - min) + (double)min);
		}
	}
	public static class PacketReaderExtensions
	{
		public static T ReadModel<T>(this PacketReader reader) where T : AbstractModel
		{
			if (typeof(T) == typeof(AbstractModel))
			{
				throw new ArgumentException("T must not be AbstractModel!");
			}
			return ModelDb.GetById<T>(reader.ReadModelIdAssumingType<T>());
		}

		public static ModelId ReadModelIdAssumingType<T>(this PacketReader reader) where T : AbstractModel
		{
			if (typeof(T) == typeof(AbstractModel))
			{
				throw new ArgumentException("T must not be AbstractModel!");
			}
			string entryForNetId = ModelIdSerializationCache.GetEntryForNetId(reader.ReadInt(ModelIdSerializationCache.EntryIdBitSize));
			if (entryForNetId == ModelId.none.Entry)
			{
				return ModelId.none;
			}
			return new ModelId(ModelId.SlugifyCategory(ModelDb.GetCategoryType(typeof(T)).Name), entryForNetId);
		}

		public static ModelId ReadFullModelId(this PacketReader reader)
		{
			string categoryForNetId = ModelIdSerializationCache.GetCategoryForNetId(reader.ReadInt(ModelIdSerializationCache.CategoryIdBitSize));
			string entryForNetId = ModelIdSerializationCache.GetEntryForNetId(reader.ReadInt(ModelIdSerializationCache.EntryIdBitSize));
			if (entryForNetId == ModelId.none.Entry || categoryForNetId == ModelId.none.Category)
			{
				return ModelId.none;
			}
			return new ModelId(categoryForNetId, entryForNetId);
		}

		public static EpochModel ReadEpoch(this PacketReader reader)
		{
			return EpochModel.Get(reader.ReadEpochId());
		}

		public static string ReadEpochId(this PacketReader reader)
		{
			return ModelIdSerializationCache.GetEpochIdForNetId(reader.ReadInt(ModelIdSerializationCache.EpochIdBitSize));
		}

		public static List<ModelId> ReadFullModelIdList(this PacketReader reader)
		{
			List<ModelId> list = new List<ModelId>();
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				list.Add(reader.ReadFullModelId());
			}
			return list;
		}

		public static List<T> ReadModelList<T>(this PacketReader reader) where T : AbstractModel
		{
			List<T> list = new List<T>();
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				list.Add(reader.ReadModel<T>());
			}
			return list;
		}

		public static List<ModelId> ReadModelIdListAssumingType<T>(this PacketReader reader) where T : AbstractModel
		{
			List<ModelId> list = new List<ModelId>();
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				list.Add(reader.ReadModelIdAssumingType<T>());
			}
			return list;
		}
	}
	public class PacketWriter
	{
		private readonly byte[] _tempBuffer = new byte[16];

		private byte[] _stringBuffer = new byte[64];

		public int BitPosition { get; private set; }

		public int BytePosition => Mathf.CeilToInt((float)BitPosition / 8f);

		public byte[] Buffer { get; private set; } = new byte[1024];

		public bool WarnOnGrow { get; set; } = true;

		public void Reset()
		{
			BitPosition = 0;
		}

		public void WriteBool(bool val)
		{
			_tempBuffer[0] = (val ? ((byte)1) : ((byte)0));
			ResizeBufferIfNecessary(1);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, 1);
			BitPosition++;
		}

		public void WriteByte(byte val, int bits = 8)
		{
			_tempBuffer[0] = val;
			ResizeBufferIfNecessary(bits);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteBytes(byte[] bytes, int byteCount)
		{
			ResizeBufferIfNecessary(byteCount * 8);
			BitSerializationUtil.WriteBytes(bytes, Buffer, BitPosition, byteCount * 8);
			BitPosition += byteCount * 8;
		}

		public void WriteShort(short val, int bits = 16)
		{
			ResizeBufferIfNecessary(bits);
			BinaryPrimitives.WriteInt16LittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteUShort(ushort val, int bits = 16)
		{
			ResizeBufferIfNecessary(bits);
			BinaryPrimitives.WriteUInt16LittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteEnum<T>(T val) where T : struct, Enum
		{
			if (!typeof(int).IsAssignableFrom(Enum.GetUnderlyingType(typeof(T))))
			{
				throw new InvalidOperationException($"Trying to write enum type {typeof(T)} that is not assignable to int!");
			}
			int bits = Mathf.CeilToInt(Math.Log2(MaxEnumValueCache.Get<T>()) + 1.0);
			int val2 = Convert.ToInt32(val);
			WriteInt(val2, bits);
		}

		public void WriteInt(int val, int bits = 32)
		{
			ResizeBufferIfNecessary(bits);
			BinaryPrimitives.WriteInt32LittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteUInt(uint val, int bits = 32)
		{
			ResizeBufferIfNecessary(bits);
			BinaryPrimitives.WriteUInt32LittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteFloat(float val, QuantizeParams? quantizeParams = null)
		{
			if (quantizeParams.HasValue)
			{
				ResizeBufferIfNecessary(quantizeParams.Value.bits);
				uint val2 = Quantize(val, quantizeParams.Value.min, quantizeParams.Value.max, quantizeParams.Value.bits);
				WriteUInt(val2, quantizeParams.Value.bits);
			}
			else
			{
				ResizeBufferIfNecessary(32);
				BinaryPrimitives.WriteSingleLittleEndian(_tempBuffer.AsSpan(), val);
				BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, 32);
				BitPosition += 32;
			}
		}

		public void WriteLong(long val, int bits = 64)
		{
			ResizeBufferIfNecessary(64);
			BinaryPrimitives.WriteInt64LittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteULong(ulong val, int bits = 64)
		{
			ResizeBufferIfNecessary(64);
			BinaryPrimitives.WriteUInt64LittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, bits);
			BitPosition += bits;
		}

		public void WriteDouble(double val)
		{
			ResizeBufferIfNecessary(64);
			BinaryPrimitives.WriteDoubleLittleEndian(_tempBuffer.AsSpan(), val);
			BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, 64);
			BitPosition += 64;
		}

		public void WriteVector2(Godot.Vector2 val, QuantizeParams? quantizeParamsX = null, QuantizeParams? quantizeParamsY = null)
		{
			WriteFloat(val.X, quantizeParamsX);
			WriteFloat(val.Y, quantizeParamsY);
		}

		public void WriteList<T>(IReadOnlyList<T> list, int lengthBits = 32) where T : IPacketSerializable, new()
		{
			if ((ulong)list.Count >= (ulong)(1L << lengthBits))
			{
				throw new IndexOutOfRangeException($"List length {list.Count} is too large to fit in bit size {lengthBits}!");
			}
			WriteInt(list.Count, lengthBits);
			foreach (T item in list)
			{
				Write(item);
			}
		}

		public void WriteString(string str)
		{
			int byteCount = Encoding.UTF8.GetByteCount(str);
			if (_stringBuffer.Length < byteCount)
			{
				int num = (int)Math.Pow(2.0, Math.Ceiling(Math.Log2(byteCount)));
				_stringBuffer = new byte[num];
			}
			int bytes = Encoding.UTF8.GetBytes(str, _stringBuffer);
			WriteInt(bytes);
			WriteBytes(_stringBuffer, bytes);
		}

		public void Write<T>(T val) where T : IPacketSerializable
		{
			val.Serialize(this);
		}

		public void ZeroByteRemainder()
		{
			int num = 8 - BitPosition % 8;
			if (num != 8)
			{
				_tempBuffer[0] = 0;
				BitSerializationUtil.WriteBytes(_tempBuffer, Buffer, BitPosition, num);
			}
		}

		private void ResizeBufferIfNecessary(int bitsBeingWritten)
		{
			int num = Mathf.CeilToInt((float)(BitPosition + bitsBeingWritten) / 8f);
			int num2 = Buffer.Length;
			while (num >= num2)
			{
				num2 *= 2;
			}
			if (num2 != Buffer.Length)
			{
				byte[] array = new byte[num2];
				System.Array.Copy(Buffer, array, Buffer.Length);
				if (WarnOnGrow)
				{
					Log.Warn($"Warning: Packet writer is growing from {Buffer.Length} bytes to {array.Length} bytes!");
				}
				Buffer = array;
			}
		}

		public static uint Quantize(float value, float min, float max, int bitLength)
		{
			return (uint)((double)((value - min) / (max - min)) * Math.Pow(2.0, bitLength));
		}
	}
	public static class PacketWriterExtensions
	{
		public static void WriteModel<T>(this PacketWriter writer, T model) where T : AbstractModel
		{
			if (model.IsMutable)
			{
				throw new ArgumentException("Cannot serialize mutable models");
			}
			writer.WriteModelEntry(model.Id);
		}

		public static void WriteModelEntry(this PacketWriter writer, ModelId id)
		{
			if (string.IsNullOrEmpty(id.Category) || string.IsNullOrEmpty(id.Entry))
			{
				throw new InvalidOperationException("Tried to serialize an empty ModelId!");
			}
			if (!ModelIdSerializationCache.TryGetNetIdForEntry(id.Entry, out var netId))
			{
				Log.Warn($"Unknown ModelId entry '{id}' during serialization, writing NONE");
				netId = ModelIdSerializationCache.GetNetIdForEntry(ModelId.none.Entry);
			}
			writer.WriteInt(netId, ModelIdSerializationCache.EntryIdBitSize);
		}

		public static void WriteEpoch<T>(this PacketWriter writer) where T : EpochModel
		{
			writer.WriteInt(ModelIdSerializationCache.GetNetIdForEpochId(EpochModel.GetId<T>()), ModelIdSerializationCache.EpochIdBitSize);
		}

		public static void WriteEpoch(this PacketWriter writer, EpochModel epochModel)
		{
			writer.WriteInt(ModelIdSerializationCache.GetNetIdForEpochId(epochModel.Id), ModelIdSerializationCache.EpochIdBitSize);
		}

		public static void WriteEpochId(this PacketWriter writer, string epochId)
		{
			writer.WriteInt(ModelIdSerializationCache.GetNetIdForEpochId(epochId), ModelIdSerializationCache.EpochIdBitSize);
		}

		public static void WriteFullModelId(this PacketWriter writer, ModelId id)
		{
			bool flag = ModelIdSerializationCache.TryGetNetIdForCategory(id.Category, out var netId);
			bool flag2 = ModelIdSerializationCache.TryGetNetIdForEntry(id.Entry, out var netId2);
			if (!flag || !flag2)
			{
				Log.Warn($"Unknown ModelId '{id}' during serialization, writing NONE");
				netId = ModelIdSerializationCache.GetNetIdForCategory(ModelId.none.Category);
				netId2 = ModelIdSerializationCache.GetNetIdForEntry(ModelId.none.Entry);
			}
			writer.WriteInt(netId, ModelIdSerializationCache.CategoryIdBitSize);
			writer.WriteInt(netId2, ModelIdSerializationCache.EntryIdBitSize);
		}

		public static void WriteFullModelIdList(this PacketWriter writer, IReadOnlyCollection<ModelId> models)
		{
			writer.WriteInt(models.Count);
			foreach (ModelId model in models)
			{
				writer.WriteFullModelId(model);
			}
		}

		public static void WriteModelList<T>(this PacketWriter writer, IReadOnlyCollection<T> models) where T : AbstractModel
		{
			writer.WriteInt(models.Count);
			foreach (T model in models)
			{
				writer.WriteModel(model);
			}
		}

		public static void WriteModelEntriesInList(this PacketWriter writer, IReadOnlyCollection<ModelId> modelIds)
		{
			writer.WriteInt(modelIds.Count);
			foreach (ModelId modelId in modelIds)
			{
				writer.WriteModelEntry(modelId);
			}
		}
	}
