namespace MegaCrit.Sts2.Core.Multiplayer.Replay
{
	public class CombatReplay : IPacketSerializable
	{
		public string version;

		public string gitCommit;

		public uint modelIdHash;

		public List<uint> choiceIds = new List<uint>();

		public List<int> rewardIds = new List<int>();

		public uint nextActionId;

		public uint nextChecksumId;

		public uint nextHookId;

		public SerializableRun serializableRun;

		public List<CombatReplayEvent> events = new List<CombatReplayEvent>();

		public List<ReplayChecksumData> checksumData = new List<ReplayChecksumData>();

		public void Serialize(PacketWriter writer)
		{
			writer.WriteString(version);
			writer.WriteString(gitCommit);
			writer.WriteUInt(modelIdHash);
			writer.WriteInt(choiceIds.Count);
			foreach (uint choiceId in choiceIds)
			{
				writer.WriteUInt(choiceId);
			}
			writer.WriteInt(rewardIds.Count);
			foreach (int rewardId in rewardIds)
			{
				writer.WriteInt(rewardId);
			}
			writer.WriteUInt(nextActionId);
			writer.WriteUInt(nextChecksumId);
			writer.WriteUInt(nextHookId);
			writer.Write(serializableRun);
			writer.WriteList(events);
			writer.WriteList(checksumData);
		}

		public void Deserialize(PacketReader reader)
		{
			version = reader.ReadString();
			gitCommit = reader.ReadString();
			modelIdHash = reader.ReadUInt();
			int num = reader.ReadInt();
			for (int i = 0; i < num; i++)
			{
				choiceIds.Add(reader.ReadUInt());
			}
			int num2 = reader.ReadInt();
			for (int j = 0; j < num2; j++)
			{
				rewardIds.Add(reader.ReadInt());
			}
			nextActionId = reader.ReadUInt();
			nextChecksumId = reader.ReadUInt();
			nextHookId = reader.ReadUInt();
			serializableRun = reader.Read<SerializableRun>();
			events = reader.ReadList<CombatReplayEvent>();
			checksumData = reader.ReadList<ReplayChecksumData>();
		}

		public CombatReplay Anonymized()
		{
			return new CombatReplay
			{
				version = version,
				gitCommit = gitCommit,
				modelIdHash = modelIdHash,
				choiceIds = choiceIds,
				rewardIds = rewardIds,
				nextActionId = nextActionId,
				nextChecksumId = nextChecksumId,
				nextHookId = nextHookId,
				serializableRun = serializableRun.Anonymized(),
				events = events.Select((CombatReplayEvent e) => e.Anonymized()).ToList(),
				checksumData = checksumData.Select((ReplayChecksumData c) => c.Anonymized()).ToList()
			};
		}
	}
	public struct CombatReplayEvent : IPacketSerializable
	{
		public CombatReplayEventType eventType;

		public ulong? playerId;

		public INetAction? action;

		public uint? hookId;

		public uint? actionId;

		public GameActionType? gameActionType;

		public uint? choiceId;

		public NetPlayerChoiceResult? playerChoiceResult;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt((int)eventType, 3);
			switch (eventType)
			{
			case CombatReplayEventType.GameAction:
				writer.WriteULong(playerId.Value);
				writer.WriteByte((byte)action.ToId());
				writer.Write(action);
				break;
			case CombatReplayEventType.HookAction:
				writer.WriteULong(playerId.Value);
				writer.WriteUInt(hookId.Value);
				writer.WriteEnum(gameActionType.Value);
				break;
			case CombatReplayEventType.ResumeAction:
				writer.WriteUInt(actionId.Value);
				break;
			case CombatReplayEventType.PlayerChoice:
				writer.WriteULong(playerId.Value);
				writer.WriteUInt(choiceId.Value);
				writer.Write(playerChoiceResult.Value);
				break;
			default:
				throw new ArgumentOutOfRangeException("eventType");
			}
		}

		public void Deserialize(PacketReader reader)
		{
			eventType = (CombatReplayEventType)reader.ReadInt(3);
			switch (eventType)
			{
			case CombatReplayEventType.GameAction:
			{
				playerId = reader.ReadULong();
				int num = reader.ReadByte();
				if (!ActionTypes.TryGetActionType(num, out Type type))
				{
					throw new InvalidOperationException($"Received net action of type {num} that does not map to any type!");
				}
				action = (INetAction)Activator.CreateInstance(type);
				action.Deserialize(reader);
				break;
			}
			case CombatReplayEventType.HookAction:
				playerId = reader.ReadULong();
				hookId = reader.ReadUInt();
				gameActionType = reader.ReadEnum<GameActionType>();
				break;
			case CombatReplayEventType.ResumeAction:
				actionId = reader.ReadUInt();
				break;
			case CombatReplayEventType.PlayerChoice:
				playerId = reader.ReadULong();
				choiceId = reader.ReadUInt();
				playerChoiceResult = reader.Read<NetPlayerChoiceResult>();
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}

		public CombatReplayEvent Anonymized()
		{
			CombatReplayEvent result = this;
			result.playerId = (playerId.HasValue ? new ulong?(IdAnonymizer.Anonymize(playerId.Value)) : ((ulong?)null));
			return result;
		}
	}
	public enum CombatReplayEventType
	{
		None,
		GameAction,
		HookAction,
		ResumeAction,
		PlayerChoice
	}
	public class CombatReplayWriter : IDisposable
	{
		private CombatReplay? _replay;

		private readonly PacketWriter _writer = new PacketWriter();

		private readonly ActionQueueSet _actionQueueSet;

		private readonly ActionQueueSynchronizer _actionQueueSynchronizer;

		private readonly PlayerChoiceSynchronizer _playerChoiceSynchronizer;

		private readonly RewardsSetSynchronizer _rewardsSetSynchronizer;

		private readonly ChecksumTracker _checksumTracker;

		public bool IsEnabled { get; set; } = true;

		public bool IsRecordingReplay => _replay != null;

		public CombatReplayWriter(PlayerChoiceSynchronizer playerChoiceSynchronizer, RewardsSetSynchronizer rewardsSetSynchronizer, ActionQueueSet actionQueueSet, ActionQueueSynchronizer actionQueueSynchronizer, ChecksumTracker checksumTracker)
		{
			_actionQueueSet = actionQueueSet;
			_actionQueueSynchronizer = actionQueueSynchronizer;
			_playerChoiceSynchronizer = playerChoiceSynchronizer;
			_rewardsSetSynchronizer = rewardsSetSynchronizer;
			_checksumTracker = checksumTracker;
			actionQueueSet.ActionEnqueued += RecordGameAction;
			actionQueueSet.ActionResumed += RecordActionResume;
			playerChoiceSynchronizer.PlayerChoiceReceived += RecordPlayerChoice;
			checksumTracker.ChecksumGenerated += RecordChecksum;
		}

		public void Dispose()
		{
			_actionQueueSet.ActionEnqueued -= RecordGameAction;
			_actionQueueSet.ActionResumed -= RecordActionResume;
			_playerChoiceSynchronizer.PlayerChoiceReceived -= RecordPlayerChoice;
			_checksumTracker.ChecksumGenerated -= RecordChecksum;
		}

		public void RecordInitialState(SerializableRun serializableRun)
		{
			if (IsEnabled)
			{
				_replay = new CombatReplay
				{
					version = (ReleaseInfoManager.Instance.ReleaseInfo?.Version ?? "UNRELEASED"),
					gitCommit = (ReleaseInfoManager.Instance.ReleaseInfo?.Commit ?? GitHelper.ShortCommitId ?? "UNKNOWN"),
					modelIdHash = ModelIdSerializationCache.Hash,
					choiceIds = _playerChoiceSynchronizer.ChoiceIds.ToList(),
					rewardIds = _rewardsSetSynchronizer.GetNextRewardIds().ToList(),
					nextActionId = _actionQueueSet.NextActionId,
					nextChecksumId = _checksumTracker.NextId,
					nextHookId = _actionQueueSynchronizer.NextHookId,
					serializableRun = serializableRun
				};
				_replay.events.Clear();
			}
		}

		private void RecordGameAction(GameAction gameAction)
		{
			if (!IsEnabled || !CombatManager.Instance.IsInProgress)
			{
				return;
			}
			if (_replay == null)
			{
				throw new InvalidOperationException("RecordInitialState must be called first");
			}
			if (gameAction is GenericHookGameAction genericHookGameAction)
			{
				_replay.events.Add(new CombatReplayEvent
				{
					playerId = gameAction.OwnerId,
					eventType = CombatReplayEventType.HookAction,
					hookId = genericHookGameAction.HookId,
					gameActionType = genericHookGameAction.ActionType
				});
				return;
			}
			if (!gameAction.RecordableToReplay)
			{
				throw new InvalidOperationException($"Found unrecordable game action: {gameAction}");
			}
			_replay.events.Add(new CombatReplayEvent
			{
				playerId = gameAction.OwnerId,
				eventType = CombatReplayEventType.GameAction,
				action = gameAction.ToNetAction()
			});
		}

		private void RecordActionResume(uint actionId)
		{
			if (IsEnabled && CombatManager.Instance.IsInProgress)
			{
				if (_replay == null)
				{
					throw new InvalidOperationException("RecordInitialState must be called first");
				}
				_replay.events.Add(new CombatReplayEvent
				{
					eventType = CombatReplayEventType.ResumeAction,
					actionId = actionId
				});
			}
		}

		private void RecordPlayerChoice(Player player, uint choiceId, NetPlayerChoiceResult result)
		{
			if (IsEnabled && CombatManager.Instance.IsInProgress)
			{
				if (_replay == null)
				{
					throw new InvalidOperationException("RecordInitialState must be called first");
				}
				_replay.events.Add(new CombatReplayEvent
				{
					eventType = CombatReplayEventType.PlayerChoice,
					playerId = player.NetId,
					choiceId = choiceId,
					playerChoiceResult = result
				});
			}
		}

		private void RecordChecksum(NetChecksumData checksum, string context, NetFullCombatState fullCombatState)
		{
			if (IsEnabled && CombatManager.Instance.IsInProgress)
			{
				if (_replay == null)
				{
					throw new InvalidOperationException("RecordInitialState must be called first");
				}
				_replay.checksumData.Add(new ReplayChecksumData
				{
					checksumData = checksum,
					context = context,
					fullState = fullCombatState
				});
			}
		}

		public void WriteReplay(string filePath, bool stopRecording)
		{
			if (!IsEnabled)
			{
				return;
			}
			if (_replay == null)
			{
				throw new InvalidOperationException("RecordInitialState must be called first");
			}
			_writer.Reset();
			_writer.Write(_replay.Anonymized());
			try
			{
				DirAccess.MakeDirRecursiveAbsolute(filePath.Substring(0, filePath.LastIndexOf('/')));
				using FileAccessStream fileAccessStream = new FileAccessStream(filePath, Godot.FileAccess.ModeFlags.Write);
				fileAccessStream.Write(_writer.Buffer.AsSpan().Slice(0, _writer.BytePosition));
			}
			catch (Exception value)
			{
				Log.Warn($"Exception while writing replay: {value}");
			}
			if (stopRecording)
			{
				StopRecording();
			}
		}

		public void StopRecording()
		{
			_replay = null;
		}
	}
	public struct ReplayChecksumData : IPacketSerializable
	{
		public NetChecksumData checksumData;

		public string context;

		public NetFullCombatState fullState;

		public void Serialize(PacketWriter writer)
		{
			writer.Write(checksumData);
			writer.WriteString(context);
			writer.Write(fullState);
		}

		public void Deserialize(PacketReader reader)
		{
			checksumData = reader.Read<NetChecksumData>();
			context = reader.ReadString();
			fullState = reader.Read<NetFullCombatState>();
		}

		public ReplayChecksumData Anonymized()
		{
			ReplayChecksumData result = this;
			result.fullState = fullState.Anonymized();
			return result;
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Quality
{
	/// <summary>
	/// Holds statistics about a particular connection to a network peer.
	/// See <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Quality.NetQualityTracker" /> for how this class is generally used.
	/// </summary>
	public class ConnectionStats
	{
		public const int ringBufferSize = 20;

		private const float _weightedAverageFactor = 0.2f;

		/// <summary>
		/// A ring buffer of heartbeat statuses.
		/// Heartbeats use a monotonically increasing counter for identification. We use that index to overwrite old
		/// heartbeat statuses in this buffer for tracking.
		/// </summary>
		private HeartbeatStatus?[] _statuses = new HeartbeatStatus?[20];

		private int _nextIndex;

		/// <summary>
		/// Logger object for this connection
		/// </summary>
		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		/// <summary>
		/// The peer for which this object gathers statistics.
		/// </summary>
		public ulong PeerId { get; private set; }

		/// <summary>
		/// The estimated average round-trip time to the peer.
		/// </summary>
		public float PingMsec { get; private set; }

		/// <summary>
		/// The estimated average packet loss to the peer.
		/// Note that this is the sum of both outbound and inbound packet loss.
		/// </summary>
		public float PacketLoss { get; private set; }

		/// <summary>
		/// The last time (msec) we received a packet from the peer.
		/// If the difference between the current time and this is a large value, then we might be about to time out.
		/// </summary>
		public ulong? LastReceivedTime { get; private set; }

		/// <summary>
		/// True if the remote end is currently loading, and we should not expect consistent packets.
		/// Used in conjunction with LastReceivedTime to determine whether we should show a "connection interrupted" overlay.
		/// </summary>
		public bool RemoteIsLoading { get; private set; }

		public ConnectionStats(ulong peerId)
		{
			PeerId = peerId;
			_logger = new MegaCrit.Sts2.Core.Logging.Logger($"{"ConnectionStats"} ({peerId})", LogType.Network);
		}

		/// <summary>
		/// Generates a heartbeat request to be sent to the peer.
		/// </summary>
		/// <param name="timeMsec">The current time in milliseconds.</param>
		public HeartbeatRequestMessage GenerateHeartbeat(ulong timeMsec)
		{
			_logger.VeryDebug($"Generating heartbeat {_nextIndex} for time {timeMsec}");
			int num = _nextIndex % 20;
			HeartbeatStatus value = new HeartbeatStatus
			{
				counter = _nextIndex,
				sentMsec = timeMsec
			};
			HeartbeatStatus? heartbeatStatus = _statuses[num];
			if (heartbeatStatus.HasValue && !heartbeatStatus.Value.receivedMsec.HasValue)
			{
				_logger.VeryDebug($"Heartbeat {heartbeatStatus.Value.counter} ({heartbeatStatus.Value.sentMsec}) was never received, marking as lost");
				OnPacketLost();
			}
			_statuses[num] = value;
			HeartbeatRequestMessage result = new HeartbeatRequestMessage
			{
				counter = _nextIndex
			};
			_nextIndex++;
			return result;
		}

		/// <summary>
		/// Call me when we receive a heartbeat message for the peer.
		/// </summary>
		/// <param name="message">The message that was received.</param>
		/// <param name="timeMsec">The current time in milliseconds.</param>
		public void OnHeartbeatReceived(HeartbeatResponseMessage message, ulong timeMsec)
		{
			_logger.VeryDebug($"Received heartbeat for {message.counter}");
			int num = _nextIndex - 20;
			if (message.counter < num || message.counter >= _nextIndex)
			{
				_logger.VeryDebug($"Counter {message.counter} is less than {num} and greater than {_nextIndex}");
				return;
			}
			int num2 = message.counter % 20;
			if (num2 >= _statuses.Length)
			{
				return;
			}
			HeartbeatStatus valueOrDefault = _statuses[num2].GetValueOrDefault();
			if (valueOrDefault.counter != message.counter)
			{
				_logger.VeryDebug($"Counter in message {message.counter} does not match counter at index {num2}, which is {valueOrDefault.counter}");
				return;
			}
			if (valueOrDefault.receivedMsec.HasValue)
			{
				_logger.VeryDebug($"Already received message for index {message.counter}");
				return;
			}
			valueOrDefault.receivedMsec = timeMsec;
			_statuses[num2] = valueOrDefault;
			if (!message.isLoading)
			{
				int num3 = (int)(valueOrDefault.receivedMsec.Value - valueOrDefault.sentMsec);
				PingMsec = Mathf.Lerp(PingMsec, num3, 0.2f);
			}
			else
			{
				Log.Debug("Not updating ping because sender is loading");
			}
			PacketLoss = Mathf.Lerp(PacketLoss, 0f, 0.2f);
			LastReceivedTime = valueOrDefault.receivedMsec.Value;
			RemoteIsLoading = message.isLoading;
		}

		/// <summary>
		/// Called when we're about to overwrite a heartbeat status in the ring buffer, and a response to it was never
		/// received.
		/// </summary>
		private void OnPacketLost()
		{
			PacketLoss = Mathf.Lerp(PacketLoss, 1f, 0.2f);
		}
	}
	/// <summary>
	/// Represents the status of a heartbeat message. See <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Quality.NetQualityTracker" />.
	/// </summary>
	public struct HeartbeatStatus
	{
		/// <summary>
		/// The heartbeat index this is tracking.
		/// </summary>
		public int counter;

		/// <summary>
		/// The time at which this heartbeat was sent.
		/// </summary>
		public ulong sentMsec;

		/// <summary>
		/// The time at which this heartbeat was received, or null if it has not been received.
		/// </summary>
		public ulong? receivedMsec;
	}
	/// <summary>
	/// Keeps track of the quality of the connection to each peer, for use in displaying "poor connection" notifications to
	/// the user.
	///
	/// To estimate connection quality, the following strategy is used:
	/// - At regular intervals, a "heartbeat" message is generated and sent to each peer. We record the time at which the
	///   message is sent.
	/// - When it is received, the peer echoes the heartbeat message back to us.
	/// - When we receive the response, we check when it was sent, and adjust our estimated round-trip time (ping) to the
	///   peer accordingly (in <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Quality.ConnectionStats" />).
	/// - If we go some time without seeing the echoed message, then we assume the packet is lost. We adjust our estimated
	///   packet loss to the peer accordingly.
	///
	/// Further work can be done here to estimate jitter, but I don't think we need it for this game.
	/// </summary>
	public class NetQualityTracker : IDisposable
	{
		/// <summary>
		/// The time that must elapse before sending another heartbeat packet.
		/// </summary>
		public const int sendRateMsec = 200;

		/// <summary>
		/// The time that must elapse before we log the connection statistics to the log.
		/// </summary>
		public const int logRateMsec = 20000;

		private readonly INetGameService _netService;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("NetQualityTracker", LogType.Network);

		/// <summary>
		/// Connection statistics objects, one per peer.
		/// </summary>
		private readonly List<ConnectionStats> _stats = new List<ConnectionStats>();

		/// <summary>
		/// The last time we sent a heartbeat packet.
		/// </summary>
		private ulong? _lastUpdateMsec;

		/// <summary>
		/// The last time we logged the connection statistics.
		/// </summary>
		private ulong? _lastLogMsec;

		/// <summary>
		/// True if the game is in a loading state. See <see cref="M:MegaCrit.Sts2.Core.Multiplayer.Quality.NetQualityTracker.SetIsLoading(System.Boolean)" />.
		/// </summary>
		private bool _isLoading;

		/// <summary>
		/// This is called when to get the current time. Used to mock time in tests. If null, Time.GetTicksMsec is used.
		/// </summary>
		public Func<ulong>? getTimeMsec;

		public bool IsGameLoading => _isLoading;

		public NetQualityTracker(INetGameService netService)
		{
			_netService = netService;
			netService.RegisterMessageHandler<HeartbeatRequestMessage>(HandleHeartbeatRequestMessage);
			netService.RegisterMessageHandler<HeartbeatResponseMessage>(HandleHeartbeatResponseMessage);
		}

		public void Dispose()
		{
			_netService.UnregisterMessageHandler<HeartbeatRequestMessage>(HandleHeartbeatRequestMessage);
			_netService.UnregisterMessageHandler<HeartbeatResponseMessage>(HandleHeartbeatResponseMessage);
		}

		/// <summary>
		/// Gets the current time.
		/// Pulls from godot or a mock time source.
		/// </summary>
		private ulong GetCurrentTime()
		{
			return getTimeMsec?.Invoke() ?? Time.GetTicksMsec();
		}

		/// <summary>
		/// Should be called whenever a peer connects. Begins tracking their connection statistics.
		/// </summary>
		public void OnPeerConnected(ulong peerId)
		{
			_stats.Add(new ConnectionStats(peerId));
		}

		/// <summary>
		/// Should be called whenever a peer connects. Stops tracking their connection statistics.
		/// </summary>
		public void OnPeerDisconnected(ulong peerId)
		{
			_stats.RemoveAll((ConnectionStats s) => s.PeerId == peerId);
		}

		/// <summary>
		/// Called when the game enters or exits a loading state.
		/// This is important to know because, in the middle of loading, NetService.Update can be called at irregular
		/// intervals, leading to a much larger-than-normal round-trip time even though the network connection is stable.
		/// This info is sent through the HeartbeatResponseMessage, and when it is true, the receiver should not update
		/// ping, but still update last received time.
		/// </summary>
		/// <param name="isLoading">True if the game is in a loading state, false otherwise.</param>
		public void SetIsLoading(bool isLoading)
		{
			Log.Debug($"Loading set to {isLoading}");
			_isLoading = isLoading;
		}

		/// <summary>
		/// Should be called on a regular basis to send heartbeat messages.
		/// </summary>
		public void Update()
		{
			ulong currentTime = GetCurrentTime();
			if (!_lastUpdateMsec.HasValue)
			{
				_lastUpdateMsec = currentTime;
			}
			else if (currentTime - _lastUpdateMsec.Value >= 200)
			{
				foreach (ConnectionStats stat in _stats)
				{
					HeartbeatRequestMessage message = stat.GenerateHeartbeat(currentTime);
					_netService.SendMessage(message, stat.PeerId);
				}
				_lastUpdateMsec = currentTime;
			}
			if (!_logger.WillLog(LogLevel.Debug))
			{
				return;
			}
			if (!_lastLogMsec.HasValue)
			{
				_lastLogMsec = currentTime;
			}
			else
			{
				if (!(currentTime - _lastLogMsec >= 20000) || _stats.Count <= 0)
				{
					return;
				}
				_lastLogMsec = currentTime;
				_logger.Debug("Connection statistics at " + Log.Timestamp + ":");
				foreach (ConnectionStats stat2 in _stats)
				{
					_logger.Debug($"\t{stat2.PeerId} - Ping: {stat2.PingMsec}. Packet Loss: {stat2.PacketLoss}.");
				}
			}
		}

		/// <summary>
		/// Called whenever a heartbeat request comes in.
		/// This just echoes the heartbeat response back to the sender.
		/// </summary>
		private void HandleHeartbeatRequestMessage(HeartbeatRequestMessage message, ulong senderId)
		{
			_netService.SendMessage(new HeartbeatResponseMessage
			{
				counter = message.counter,
				isLoading = _isLoading
			}, senderId);
		}

		/// <summary>
		/// Called whenever a response to our heartbeat request comes back.
		/// Processes the message and updates our statistics.
		/// </summary>
		private void HandleHeartbeatResponseMessage(HeartbeatResponseMessage message, ulong senderId)
		{
			GetStatsForPeer(senderId)?.OnHeartbeatReceived(message, GetCurrentTime());
		}

		/// <summary>
		/// Returns the statistics for a given peer.
		/// </summary>
		public ConnectionStats? GetStatsForPeer(ulong peerId)
		{
			foreach (ConnectionStats stat in _stats)
			{
				if (stat.PeerId == peerId)
				{
					return stat;
				}
			}
			return null;
		}
	}
}
