namespace MegaCrit.Sts2.Core.Multiplayer.Messages.Game.Checksums
{
	/// <summary>
	/// Sent from clients to host when a checksum is generated. The host should validate the checksum. No action is needed
	/// if the checksum matches the host's, but if it does not, a StateDivergenceMessage should be generated and sent to
	/// the client.
	/// </summary>
	public struct ChecksumDataMessage : INetMessage, IPacketSerializable
	{
		public NetChecksumData checksumData;

		public bool ShouldBroadcast => false;

		public NetTransferMode Mode => NetTransferMode.Reliable;

		public LogLevel LogLevel => LogLevel.VeryDebug;

		public bool ShouldBuffer => true;

		public void Serialize(PacketWriter writer)
		{
			writer.Write(checksumData);
		}

		public void Deserialize(PacketReader reader)
		{
			checksumData = reader.Read<NetChecksumData>();
		}
	}
	/// <summary>
	/// Sent when a state divergence is detected due to the host and client checksums mismatching.
	/// First this is sent from host to client, then it is sent from client to host.
	/// </summary>
	public struct StateDivergenceMessage : INetMessage, IPacketSerializable
	{
		public NetChecksumData senderChecksum;

		public NetFullCombatState senderCombatState;

		public bool ShouldBroadcast => false;

		public NetTransferMode Mode => NetTransferMode.Reliable;

		public LogLevel LogLevel => LogLevel.Info;

		public bool ShouldBuffer => true;

		public void Serialize(PacketWriter writer)
		{
			writer.Write(senderChecksum);
			writer.Write(senderCombatState);
		}

		public void Deserialize(PacketReader reader)
		{
			senderChecksum = reader.Read<NetChecksumData>();
			senderCombatState = reader.Read<NetFullCombatState>();
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Game
{
	public class ActChangeSynchronizer
	{
		private readonly RunState _runState;

		private readonly List<bool> _readyPlayers = new List<bool>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("ActChangeSynchronizer", LogType.GameSync);

		/// <summary>
		/// The last act index we transitioned away from.
		/// All attempts to vote to transition away from this act again will be ignored.
		/// </summary>
		private int _lastTransitioningActIndex = -1;

		public ActChangeSynchronizer(RunState runState)
		{
			_runState = runState;
			for (int i = 0; i < runState.Players.Count; i++)
			{
				_readyPlayers.Add(item: false);
			}
		}

		public void SetLocalPlayerReady()
		{
			_logger.Info("Local player ready to move to next act");
			Player me = LocalContext.GetMe(_runState);
			if (me != null)
			{
				RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue(new VoteToMoveToNextActAction(me, _runState.CurrentActIndex));
			}
		}

		public bool IsWaitingForOtherPlayers()
		{
			int playerSlotIndex = _runState.GetPlayerSlotIndex(LocalContext.NetId.Value);
			for (int i = 0; i < _readyPlayers.Count; i++)
			{
				if (!_readyPlayers[i] && i != playerSlotIndex)
				{
					return true;
				}
			}
			return false;
		}

		public void OnPlayerReady(Player player, int actIndex)
		{
			_logger.Debug($"Player {player.NetId} ready to move to next act from {actIndex}");
			AbstractRoom currentRoom = _runState.CurrentRoom;
			if ((currentRoom == null || !currentRoom.IsVictoryRoom) && (actIndex < _runState.CurrentActIndex || actIndex <= _lastTransitioningActIndex))
			{
				_logger.Warn($"Player {player.NetId} tried to transition to next act from index {actIndex}, but the current index is {_runState.CurrentActIndex} and we last transitioned from {_lastTransitioningActIndex}. Ignoring.");
			}
			else
			{
				int playerSlotIndex = _runState.GetPlayerSlotIndex(player);
				_readyPlayers[playerSlotIndex] = true;
				if (_readyPlayers.All((bool x) => x))
				{
					MoveToNextAct();
				}
			}
		}

		private void MoveToNextAct()
		{
			for (int i = 0; i < _readyPlayers.Count; i++)
			{
				_readyPlayers[i] = false;
			}
			_logger.Info("All players ready to move to next act, beginning transition");
			_lastTransitioningActIndex = _runState.CurrentActIndex;
			_runState.ActFloor++;
			TaskHelper.RunSafely(RunManager.Instance.EnterNextAct());
			if (NOverlayStack.Instance?.Peek() is NRewardsScreen nRewardsScreen)
			{
				nRewardsScreen.HideWaitingForPlayersScreen();
			}
		}
	}
	/// <summary>
	/// Calculates checksums, sends them to peers, and validates received checksums to ensure there are no state divergences
	/// during deterministic execution (currently: during combat, after events, and after rest sites).
	/// </summary>
	public class ChecksumTracker : IDisposable
	{
		private struct TrackedChecksum
		{
			public NetChecksumData data;

			public string context;

			public string fingerprintContext;

			public NetFullCombatState fullState;
		}

		private struct QueuedRemoteChecksum
		{
			public NetChecksumData data;

			public ulong senderId;
		}

		private const int _checksumsToSave = 20;

		private readonly List<TrackedChecksum> _checksums = new List<TrackedChecksum>();

		private readonly List<QueuedRemoteChecksum> _queuedRemoteChecksums = new List<QueuedRemoteChecksum>();

		private readonly INetGameService _netService;

		private readonly IRunState _runState;

		private readonly PacketWriter _packetWriter = new PacketWriter();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("ChecksumTracker", LogType.GameSync);

		private List<ReplayChecksumData>? _replayChecksums;

		public uint NextId { get; private set; }

		public bool IsEnabled { get; set; } = true;

		public event Action<ulong, NetFullCombatState>? StateDiverged;

		public event Action<NetChecksumData, string, NetFullCombatState>? ChecksumGenerated;

		public ChecksumTracker(INetGameService netService, IRunState runState)
		{
			_netService = netService;
			_runState = runState;
			_netService.RegisterMessageHandler<ChecksumDataMessage>(OnReceivedChecksumDataMessage);
			_netService.RegisterMessageHandler<StateDivergenceMessage>(OnReceivedStateDivergenceMessage);
		}

		public void Dispose()
		{
			_netService.UnregisterMessageHandler<ChecksumDataMessage>(OnReceivedChecksumDataMessage);
			_netService.UnregisterMessageHandler<StateDivergenceMessage>(OnReceivedStateDivergenceMessage);
		}

		/// <summary>
		/// Main entry point for this class. Generates a checksum of the full combat state for validation against peers'.
		/// On host, the checksum is saved for comparison against those received from clients.
		/// On clients, the checksum is saved and sent to the host for validation.
		/// This should be called the exact same amount of times for every peer, otherwise false positive mismatches will be
		/// generated.
		/// </summary>
		public NetChecksumData GenerateChecksum(string context, GameAction? action)
		{
			if (!IsEnabled)
			{
				return default(NetChecksumData);
			}
			_logger.Debug($"Generating checksum for context: {context} action: {action} id: {NextId}");
			NetChecksumData netChecksumData = ObtainAndTrackChecksum(context, action);
			if (_netService.Type == NetGameType.Client)
			{
				_netService.SendMessage(new ChecksumDataMessage
				{
					checksumData = netChecksumData
				});
			}
			CheckAgainstReplayChecksum(netChecksumData, context);
			return netChecksumData;
		}

		/// <summary>
		/// Called on the host when a client sends a message containing the checksum for their current game state.
		/// </summary>
		private void OnReceivedChecksumDataMessage(ChecksumDataMessage message, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ChecksumDataMessage as non-host player!");
			}
			NetChecksumData remoteChecksumData = message.checksumData;
			int num = _checksums.FindIndex((TrackedChecksum c) => c.data.id == remoteChecksumData.id);
			if (num < 0)
			{
				_queuedRemoteChecksums.Add(new QueuedRemoteChecksum
				{
					data = remoteChecksumData,
					senderId = senderId
				});
			}
			else
			{
				TrackedChecksum localChecksum = _checksums[num];
				CompareChecksums(localChecksum, remoteChecksumData, senderId);
			}
		}

		/// <summary>
		/// Called on client when the host sends a message indicating that the client's state has diverged from the host's.
		/// Also called on the host when the client receives the host's message, so that the host knows what state the client
		/// was in and can log both.
		/// </summary>
		private void OnReceivedStateDivergenceMessage(StateDivergenceMessage message, ulong senderId)
		{
			NetChecksumData remoteChecksumData = message.senderChecksum;
			int num = _checksums.FindIndex((TrackedChecksum c) => c.data.id == remoteChecksumData.id);
			if (num < 0)
			{
				Log.Error($"Received state divergence message for checksum ID {remoteChecksumData.id} that has fallen out of our list! (Our next ID: {NextId})");
			}
			else
			{
				TrackedChecksum localChecksum = _checksums[num];
				LogStateDivergence(localChecksum, message, senderId, num);
			}
			if (_netService.Type == NetGameType.Host)
			{
				(_netService as NetHostGameService)?.DisconnectClient(senderId, NetError.StateDivergence);
			}
		}

		/// <summary>
		/// Call this to obtain checksum data that may be sent over the network with a message.
		/// </summary>
		private NetChecksumData ObtainAndTrackChecksum(string context, GameAction? action)
		{
			NetFullCombatState netFullCombatState = NetFullCombatState.FromRun(_runState, action);
			uint checksum = GenerateChecksum(netFullCombatState);
			NetChecksumData netChecksumData = new NetChecksumData
			{
				id = NextId,
				checksum = checksum
			};
			NextId++;
			TrackedChecksum trackedChecksum = new TrackedChecksum
			{
				data = netChecksumData,
				context = context,
				fingerprintContext = ((action != null) ? action.GetType().Name : context),
				fullState = netFullCombatState
			};
			ChecksumGenerated?.Invoke(netChecksumData, context, netFullCombatState);
			_checksums.Add(trackedChecksum);
			if (_checksums.Count > 20)
			{
				_checksums.RemoveAt(0);
			}
			for (int i = 0; i < _queuedRemoteChecksums.Count; i++)
			{
				if (_queuedRemoteChecksums[i].data.id == trackedChecksum.data.id)
				{
					CompareChecksums(trackedChecksum, _queuedRemoteChecksums[i].data, _queuedRemoteChecksums[i].senderId);
					_queuedRemoteChecksums.RemoveAt(i);
					i--;
				}
			}
			return netChecksumData;
		}

		private void CompareChecksums(TrackedChecksum localChecksum, NetChecksumData remoteChecksum, ulong remoteId)
		{
			if (localChecksum.data.id != remoteChecksum.id)
			{
				throw new InvalidOperationException("Trying to compare two checksums with different IDs!");
			}
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("CompareChecksums should only be called on the host!");
			}
			if (localChecksum.data.checksum != remoteChecksum.checksum)
			{
				if (!TestMode.IsOn)
				{
					Log.Error($"State divergence detected! Checksum with ID {localChecksum.data.id} for client {remoteId} doesn't match host's!\nContext: {localChecksum.context}. Local: {localChecksum.data.checksum}. Remote: {remoteChecksum.checksum}.");
				}
				StateDivergenceMessage message = new StateDivergenceMessage
				{
					senderChecksum = localChecksum.data,
					senderCombatState = localChecksum.fullState
				};
				_netService.SendMessage(message, remoteId);
			}
		}

		private void LogStateDivergence(TrackedChecksum localChecksum, StateDivergenceMessage message, ulong remoteId, int checksumIndex)
		{
			if (localChecksum.data.id != message.senderChecksum.id)
			{
				throw new InvalidOperationException("Trying to compare two checksums with different IDs!");
			}
			if (!TestMode.IsOn)
			{
				Log.Error($"State divergence message received for player {remoteId} checksum ID {localChecksum.data.id}! (We are {_netService.Type} {_netService.NetId})\nContext: {localChecksum.context}. Local: {localChecksum.data.checksum}. Remote: {message.senderChecksum.checksum}.\nLOCAL STATE DUMP\n{localChecksum.fullState}\nREMOTE STATE DUMP\n{message.senderCombatState}\n");
				ReportDivergenceToSentry(localChecksum, message, remoteId, checksumIndex);
			}
			if (_netService.Type == NetGameType.Client)
			{
				StateDivergenceMessage message2 = new StateDivergenceMessage
				{
					senderChecksum = localChecksum.data,
					senderCombatState = localChecksum.fullState
				};
				_netService.SendMessage(message2);
			}
			StateDiverged?.Invoke(remoteId, message.senderCombatState);
		}

		private void ReportDivergenceToSentry(TrackedChecksum localChecksum, StateDivergenceMessage message, ulong remoteId, int checksumIndex)
		{
			string role = _netService.Type.ToString();
			string message2 = "Multiplayer state divergence: " + localChecksum.fingerprintContext;
			string localState = localChecksum.fullState.ToString();
			string remoteState = message.senderCombatState.ToString();
			SentryService.CaptureException(new StateDivergenceException(message2), delegate(Scope scope)
			{
				scope.SetFingerprint("StateDivergence", localChecksum.fingerprintContext);
				scope.SetTag("net.role", role);
				scope.SetTag("divergence.type", localChecksum.fingerprintContext);
				scope.SetExtra("divergence.context", localChecksum.context);
				scope.SetExtra("divergence.checksum_id", localChecksum.data.id);
				scope.SetExtra("divergence.local_checksum", localChecksum.data.checksum);
				scope.SetExtra("divergence.remote_checksum", message.senderChecksum.checksum);
				scope.SetExtra("divergence.local_net_id", _netService.NetId);
				scope.SetExtra("divergence.remote_net_id", remoteId);
				scope.SetExtra("divergence.lobby_id", _netService.GetRawLobbyIdentifier() ?? "unknown");
				scope.AddCompressedAttachment(localState, "local_state.txt.gz");
				scope.AddCompressedAttachment(remoteState, "remote_state.txt.gz");
				if (checksumIndex > 0)
				{
					string text = _checksums[checksumIndex - 1].fullState.ToString();
					scope.AddCompressedAttachment(text, "previous_state.txt.gz");
				}
			});
		}

		public void LoadReplayChecksums(List<ReplayChecksumData> replayChecksums, uint nextId)
		{
			NextId = nextId;
			_replayChecksums = replayChecksums;
		}

		private void CheckAgainstReplayChecksum(NetChecksumData localData, string context)
		{
			if (_replayChecksums == null)
			{
				return;
			}
			int num = _replayChecksums.FindIndex((ReplayChecksumData c) => c.checksumData.id == localData.id);
			if (num == -1)
			{
				Log.Error($"Replay state diverged! Generated checksum for {context} with id {localData.id} that doesn't exist in the replay data");
				return;
			}
			ReplayChecksumData replayChecksumData = _replayChecksums[num];
			uint num2 = GenerateChecksum(replayChecksumData.fullState);
			if (num2 != localData.checksum)
			{
				Log.Error($"Replay state divergence! Checksum ID {localData.id}!\nLocal context: {context}. Replay context: {replayChecksumData.context}. Local: {localData.checksum}. Replay: {num2}.\nLOCAL STATE DUMP\n{_checksums.Find((TrackedChecksum c) => c.data.id == localData.id).fullState}\nREPLAY STATE DUMP\n{replayChecksumData.fullState}\n");
			}
		}

		public uint GenerateChecksum(NetFullCombatState state)
		{
			_packetWriter.Reset();
			_packetWriter.Write(state);
			_packetWriter.ZeroByteRemainder();
			ReadOnlySpan<byte> source = _packetWriter.Buffer.AsSpan().Slice(0, _packetWriter.BytePosition);
			return XxHash32.HashToUInt32(source);
		}
	}
	/// <summary>
	/// Handles entering combat from events.
	/// This isn't a synchronizer per se, as it doesn't pass any messages.
	/// </summary>
	public class EventCombatSynchronizer
	{
		private class EventCombatState
		{
			public required EncounterModel canonicalEncounter;

			public required IReadOnlyList<Reward> extraRewards;

			public bool shouldResumeAfterCombat;
		}

		private readonly IRunState _runState;

		private readonly List<EventCombatState?> _states = new List<EventCombatState>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("EventCombatSynchronizer", LogType.GameSync);

		private EventModel? _canonicalEvent;

		/// <summary>
		/// The mutable encounter that will be used when we transition to combat.
		/// This is only set if the event used to initialize the object has LayoutType == EventLayoutType.Combat.
		/// </summary>
		public EncounterModel? MutableEncounterForLayout { get; private set; }

		/// <summary>
		/// The combat state that will be used when we transition to combat.
		/// This is only set if the event used to initialize the object has LayoutType == EventLayoutType.Combat.
		/// </summary>
		public CombatState? CombatStateForLayout { get; private set; }

		public EventCombatSynchronizer(IPlayerCollection playerCollection, IRunState runState)
		{
			_runState = runState;
			foreach (Player player in playerCollection.Players)
			{
				_states.Add(null);
			}
		}

		/// <summary>
		/// Should be called whenever an event is entered that can transition to combat.
		/// </summary>
		public void InitializeForEvent(EventModel localEvent)
		{
			_canonicalEvent = localEvent.CanonicalInstance;
			if (localEvent.LayoutType != EventLayoutType.Combat)
			{
				return;
			}
			if (localEvent.CanonicalEncounter == null)
			{
				throw new InvalidOperationException($"Canonical encounter is not set for event {localEvent.Id} with combat layout!");
			}
			MutableEncounterForLayout = localEvent.CanonicalEncounter.ToMutable();
			MutableEncounterForLayout.GenerateMonstersWithSlots(_runState);
			CombatStateForLayout = CreateCombatState(MutableEncounterForLayout);
			foreach (Player player in _runState.Players)
			{
				CombatStateForLayout.AddPlayer(player);
			}
			foreach (var monstersWithSlot in CombatStateForLayout.Encounter.MonstersWithSlots)
			{
				MonsterModel item = monstersWithSlot.Item1;
				string item2 = monstersWithSlot.Item2;
				Creature creature = CombatStateForLayout.CreateCreature(item, CombatSide.Enemy, item2);
				CombatStateForLayout.AddCreature(creature);
			}
		}

		/// <summary>
		/// Called when an individual event instance is prepared to enter combat.
		/// When a shared event is in-progress, there is one EventModel instance per player. Each one calls this method
		/// individually to match the semantics of how events normally work. Once all event instances have called in, this
		/// object automatically does the transition to combat.
		/// </summary>
		/// <param name="canonicalEncounter">The canonical encounter to transition to. This must match among all calls to
		/// this method in a single shared event.</param>
		/// <param name="player">The player to which the event belongs.</param>
		/// <param name="extraRewards">Any extra rewards that should be granted to the player.</param>
		/// <param name="shouldResumeAfterCombat">Whether to resume the event post-combat or not. Must be the same among all
		/// calls to this method in a single shared event.</param>
		public void ReadyToEnterCombat(EncounterModel canonicalEncounter, Player player, IReadOnlyList<Reward> extraRewards, bool shouldResumeAfterCombat)
		{
			_logger.Debug($"Player {player.NetId} is ready to enter combat {canonicalEncounter.Id} (extra rewards: {extraRewards.Count}, should resume after: {shouldResumeAfterCombat})");
			int playerSlotIndex = _runState.GetPlayerSlotIndex(player);
			if (_states[playerSlotIndex] != null)
			{
				throw new InvalidOperationException($"Player {player.NetId} became ready to enter combat {canonicalEncounter.Id},but they are already set to ready for {_states[playerSlotIndex].canonicalEncounter.Id}!");
			}
			_states[playerSlotIndex] = new EventCombatState
			{
				canonicalEncounter = canonicalEncounter,
				extraRewards = extraRewards,
				shouldResumeAfterCombat = shouldResumeAfterCombat
			};
			if (_states.All((EventCombatState s) => s != null))
			{
				EnterCombat();
			}
		}

		/// <summary>
		/// Called after all event instances call <see cref="M:MegaCrit.Sts2.Core.Multiplayer.Game.EventCombatSynchronizer.ReadyToEnterCombat(MegaCrit.Sts2.Core.Models.EncounterModel,MegaCrit.Sts2.Core.Entities.Players.Player,System.Collections.Generic.IReadOnlyList{MegaCrit.Sts2.Core.Rewards.Reward},System.Boolean)" />.
		/// Does the actual transition into combat.
		/// </summary>
		private void EnterCombat()
		{
			if (_canonicalEvent == null)
			{
				throw new InvalidOperationException("GenerateInternalCombatState must be called before EnterCombat!");
			}
			EncounterModel canonicalEncounter = _states[0].canonicalEncounter;
			bool shouldResumeAfterCombat = _states[0].shouldResumeAfterCombat;
			for (int i = 0; i < _states.Count; i++)
			{
				if (_states[i].shouldResumeAfterCombat != shouldResumeAfterCombat)
				{
					throw new InvalidOperationException($"Event for player {_runState.Players[i].NetId} tried to start event combatwith shouldResumeAfterCombat set to {_states[i].shouldResumeAfterCombat}, but the host says it should be {shouldResumeAfterCombat}!");
				}
				if (_states[i].canonicalEncounter != canonicalEncounter)
				{
					throw new InvalidOperationException($"Event for player {_runState.Players[i].NetId} tried to start event combatwith encounter {_states[i].canonicalEncounter.Id}, but the host says it should be {canonicalEncounter.Id}!");
				}
			}
			_logger.Debug($"Entering combat {canonicalEncounter.Id} from event");
			CombatState combatState = CombatStateForLayout ?? CreateCombatState(canonicalEncounter.ToMutable());
			CombatRoom combatRoom = new CombatRoom(combatState)
			{
				ShouldCreateCombat = (_canonicalEvent.LayoutType != EventLayoutType.Combat),
				ShouldResumeParentEventAfterCombat = shouldResumeAfterCombat,
				ParentEventId = _canonicalEvent.Id
			};
			foreach (EventCombatState state in _states)
			{
				foreach (Reward extraReward in state.extraRewards)
				{
					combatRoom.AddExtraReward(extraReward.Player, extraReward);
				}
			}
			TaskHelper.RunSafely(RunManager.Instance.EnterRoomWithoutExitingCurrentRoom(combatRoom, _canonicalEvent.LayoutType != EventLayoutType.Combat));
		}

		/// <summary>
		/// Resets the combat synchronizer state for the next combat.
		/// This must be called before another event combat can begin.
		/// </summary>
		public void ResetState()
		{
			foreach (Creature item in CombatStateForLayout?.Creatures ?? System.Array.Empty<Creature>())
			{
				CombatStateForLayout?.RemoveCreature(item);
			}
			_canonicalEvent = null;
			MutableEncounterForLayout = null;
			CombatStateForLayout = null;
			for (int i = 0; i < _states.Count; i++)
			{
				_states[i] = null;
			}
		}

		private CombatState CreateCombatState(EncounterModel mutableEncounter)
		{
			return new CombatState(mutableEncounter, _runState, _runState.Modifiers, _runState.BadgeModels, _runState.MultiplayerScalingModel);
		}
	}
	public class EventSynchronizer : IDisposable
	{
		private readonly INetGameService _netService;

		private readonly RunLocationTargetedMessageBuffer _messageBuffer;

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private readonly List<EventModel> _events = new List<EventModel>();

		/// <summary>
		/// The canonical event we are currently in the middle of.
		/// </summary>
		private EventModel? _canonicalEvent;

		/// <summary>
		/// Votes received from players on which option to choose. Only set during shared events.
		/// </summary>
		private readonly List<uint?> _playerVotes = new List<uint?>();

		/// <summary>
		/// The "page" of options we are on. Increments every time an option is chosen.
		/// </summary>
		private uint _pageIndex;

		/// <summary>
		/// Tracks in-flight event option tasks so we can await them before room exit.
		/// Option handlers run as fire-and-forget tasks via TaskHelper.RunSafely. Without tracking,
		/// the room can exit (and checksum) before a slow handler (e.g. Shatter's per-card loop)
		/// finishes on the peer whose local event completed first, causing state divergence.
		/// </summary>
		private readonly List<Task> _pendingOptionTasks = new List<Task>();

		/// <summary>
		/// Determines what event option is chosen in multiplayer when multiple options have the same number of votes.
		/// This is only rolled on the host. Do not depend on the RNG being deterministic across peers.
		/// </summary>
		private readonly Rng _multiplayerOptionSelectionRng;

		private readonly EventCombatSynchronizer _combatSynchronizer;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("EventSynchronizer", LogType.GameSync);

		public IReadOnlyList<EventModel> Events => _events;

		public bool IsShared => (_canonicalEvent ?? throw new InvalidOperationException("Event is not in progress!")).IsShared;

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		public event Action<Player>? PlayerVoteChanged;

		public EventSynchronizer(RunLocationTargetedMessageBuffer messageBuffer, INetGameService netService, IPlayerCollection playerCollection, IRunState runState, ulong localPlayerId, ulong seed)
		{
			_netService = netService;
			_messageBuffer = messageBuffer;
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			_multiplayerOptionSelectionRng = new Rng(seed, "event_synchronizer");
			_combatSynchronizer = new EventCombatSynchronizer(playerCollection, runState);
			_messageBuffer.RegisterMessageHandler<OptionIndexChosenMessage>(HandleEventOptionChosenMessage);
			_messageBuffer.RegisterMessageHandler<VotedForSharedEventOptionMessage>(HandleVotedForSharedEventOptionMessage);
			_messageBuffer.RegisterMessageHandler<SharedEventOptionChosenMessage>(HandleSharedEventOptionChosenMessage);
		}

		public void Dispose()
		{
			_messageBuffer.UnregisterMessageHandler<OptionIndexChosenMessage>(HandleEventOptionChosenMessage);
			_messageBuffer.UnregisterMessageHandler<VotedForSharedEventOptionMessage>(HandleVotedForSharedEventOptionMessage);
			_messageBuffer.UnregisterMessageHandler<SharedEventOptionChosenMessage>(HandleSharedEventOptionChosenMessage);
		}

		/// <summary>
		/// Called when an event room is entered.
		/// </summary>
		/// <param name="canonicalEvent">The canonical version of the event that will be started.</param>
		/// <param name="isPrefinished">If the event is already pre-finished</param>
		/// <param name="debugOnStart">A method to call to inject some debug code right after the model is cloned. The mutable
		/// model instances will be passed to the method.</param>
		public void BeginEvent(EventModel canonicalEvent, bool isPrefinished = false, Action<EventModel>? debugOnStart = null)
		{
			_logger.Debug($"Beginning event {canonicalEvent.Id}, shared: {canonicalEvent.IsShared}");
			for (int i = _playerVotes.Count; i < _playerCollection.Players.Count; i++)
			{
				_playerVotes.Add(null);
			}
			foreach (EventModel @event in _events)
			{
				if (!@event.IsFinished)
				{
					_logger.Warn($"Beginning new event {canonicalEvent}, but event {@event} for player {@event.Owner.NetId} is not yet finished!");
					@event.EnsureCleanup();
				}
			}
			_events.Clear();
			_pendingOptionTasks.Clear();
			ClearPlayerVotes();
			_pageIndex = 0u;
			_canonicalEvent = canonicalEvent;
			foreach (Player player in _playerCollection.Players)
			{
				EventModel eventModel = canonicalEvent.ToMutable();
				debugOnStart?.Invoke(eventModel);
				_events.Add(eventModel);
				TaskHelper.RunSafely(eventModel.BeginEvent(player, _combatSynchronizer, isPrefinished));
				_logger.VeryDebug($"Event {eventModel.Id} began for player {player.NetId} with options: {string.Join(",", eventModel.CurrentOptions)}");
			}
		}

		/// <summary>Received during shared events. Records a player's vote for a given event option. </summary>
		private void HandleVotedForSharedEventOptionMessage(VotedForSharedEventOptionMessage message, ulong senderId)
		{
			_logger.Debug($"Received {"VotedForSharedEventOptionMessage"} from player {senderId} for option {message.optionIndex} on page {message.pageIndex}");
			if (!IsShared)
			{
				throw new InvalidOperationException("Received VotedForSharedEventOptionMessage during a non-shared event!");
			}
			Player player = _playerCollection.GetPlayer(senderId);
			if (player == null)
			{
				throw new InvalidOperationException($"Received {"VotedForSharedEventOptionMessage"} for player {senderId} that doesn't exist!");
			}
			PlayerVotedForSharedOptionIndex(player, message.optionIndex, message.pageIndex);
		}

		/// <summary> Records a player's vote. Called in response to a remote player's message, or immediately when the
		/// local player votes for a shared event option. </summary>
		private void PlayerVotedForSharedOptionIndex(Player player, uint optionIndex, uint pageIndex)
		{
			if (pageIndex < _pageIndex)
			{
				_logger.Warn($"Received message from player {player.NetId} voting for option {optionIndex} on page {pageIndex}, but we are on greater page {_pageIndex}. Ignoring vote");
			}
			else if (pageIndex > _pageIndex)
			{
				_logger.Error($"Received message from player {player.NetId} voting for option {optionIndex} on page {pageIndex}, but we are on lesser page {_pageIndex}. This is a bug!");
			}
			else
			{
				int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
				_playerVotes[playerSlotIndex] = optionIndex;
				PlayerVoteChanged?.Invoke(player);
				if (_playerVotes.All((uint? p) => p.HasValue) && _netService.Type != NetGameType.Client)
				{
					_logger.Debug("All votes received and we are host. Choosing shared event option");
					ChooseSharedEventOption();
				}
			}
		}

		/// <summary> Called on the host when all votes for a shared event page are received. Decides which event option
		/// should be chosen and notifies all clients of the option chosen. </summary>
		private void ChooseSharedEventOption()
		{
			if (_netService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Only host should be choosing shared event option!");
			}
			_logger.Debug($"All votes received on host for shared event {_canonicalEvent}, choosing option");
			uint value = _multiplayerOptionSelectionRng.NextItem(_playerVotes).Value;
			_logger.Debug($"Shared event option {value} was chosen");
			SharedEventOptionChosenMessage message = new SharedEventOptionChosenMessage
			{
				optionIndex = value,
				pageIndex = _pageIndex,
				location = _messageBuffer.CurrentLocation
			};
			_netService.SendMessage(message);
			ChooseOptionForSharedEvent(value);
		}

		/// <summary> Called on clients when the host receives all player votes and decides on an event option to choose. </summary>
		private void HandleSharedEventOptionChosenMessage(SharedEventOptionChosenMessage message, ulong senderId)
		{
			_logger.Debug($"Received {"SharedEventOptionChosenMessage"} for option {message.optionIndex} on page {message.pageIndex}");
			if (_netService.Type != NetGameType.Client)
			{
				throw new InvalidOperationException($"Received {"SharedEventOptionChosenMessage"} on non-client! {_netService.Type}");
			}
			if (_pageIndex != message.pageIndex)
			{
				throw new InvalidOperationException($"Received {"SharedEventOptionChosenMessage"} for page {message.pageIndex} while we were on page {_pageIndex}!");
			}
			ChooseOptionForSharedEvent(message.optionIndex);
		}

		/// <summary> Called on all peers during non-shared events when one peer selects an event option. </summary>
		private void HandleEventOptionChosenMessage(OptionIndexChosenMessage message, ulong senderId)
		{
			if (message.type == OptionIndexType.Event)
			{
				_logger.Debug($"Received {"OptionIndexChosenMessage"} from player {senderId} for event option index {message.optionIndex}");
				if (IsShared)
				{
					throw new InvalidOperationException("Received OptionIndexChosenMessage during a shared event!");
				}
				Player player = _playerCollection.GetPlayer(senderId);
				if (player == null)
				{
					throw new InvalidOperationException($"Received EventOptionChosenMessage for player {senderId} that doesn't exist!");
				}
				ChooseOptionForEvent(player, (int)message.optionIndex);
			}
		}

		/// <summary>
		/// Called when the local player selects an event option button.
		/// During shared events, this votes for the event option.
		/// During non-shared events, this immediately executes the option and sends the event option to all other peers.
		/// </summary>
		/// <param name="index">The index of the event option that was chosen.</param>
		public void ChooseLocalOption(int index)
		{
			if (IsShared)
			{
				_logger.Debug($"Local player voted for shared event option index {index}");
				PlayerVotedForSharedOptionIndex(LocalPlayer, (uint)index, _pageIndex);
				VotedForSharedEventOptionMessage message = new VotedForSharedEventOptionMessage
				{
					optionIndex = (uint)index,
					pageIndex = _pageIndex,
					location = _messageBuffer.CurrentLocation
				};
				_netService.SendMessage(message);
			}
			else
			{
				_logger.Debug($"Local player chose event option index {index}");
				ChooseOptionForEvent(LocalPlayer, index);
				OptionIndexChosenMessage message2 = new OptionIndexChosenMessage
				{
					type = OptionIndexType.Event,
					optionIndex = (uint)index,
					location = _messageBuffer.CurrentLocation
				};
				_netService.SendMessage(message2);
			}
		}

		/// <summary> Executes the shared event option on all players' event model instances and clears player votes. </summary>
		private void ChooseOptionForSharedEvent(uint optionIndex)
		{
			if (!IsShared)
			{
				throw new InvalidOperationException("ChooseOptionForSharedEvent called during non-shared event!");
			}
			_logger.Debug($"Choosing option index {optionIndex} for shared event on page {_pageIndex}");
			ClearPlayerVotes();
			_pageIndex++;
			foreach (Player player in _playerCollection.Players)
			{
				ChooseOptionForEvent(player, (int)optionIndex);
			}
		}

		/// <summary>
		/// Executes the given event option for a given player.
		/// </summary>
		private void ChooseOptionForEvent(Player player, int optionIndex)
		{
			EventModel eventForPlayer = GetEventForPlayer(player);
			if (eventForPlayer.IsFinished)
			{
				throw new InvalidOperationException($"Option chosen for player {player} on {eventForPlayer}, but it is already finished!");
			}
			if (optionIndex >= eventForPlayer.CurrentOptions.Count)
			{
				throw new InvalidOperationException($"Player {player.NetId} attempted to choose option index {optionIndex} in event {eventForPlayer.Id}, but there were only {eventForPlayer.CurrentOptions.Count} options available!");
			}
			_logger.Debug($"Option index {optionIndex} chosen for player {player.NetId} in event {eventForPlayer.Id}. Choice key: {eventForPlayer.CurrentOptions[optionIndex].TextKey}");
			EventOption eventOption = eventForPlayer.CurrentOptions[optionIndex];
			_pendingOptionTasks.Add(TaskHelper.RunSafely(eventOption.Chosen()));
			SaveEventOptionToHistory(player, eventOption);
		}

		private void SaveEventOptionToHistory(Player player, EventOption option)
		{
			if (!option.ShouldSaveChoiceToHistory)
			{
				return;
			}
			EventOptionHistoryEntry item = new EventOptionHistoryEntry
			{
				Title = option.HistoryName,
				Variables = new System.Collections.Generic.Dictionary<string, object>()
			};
			if (option.ShouldSaveVariablesToHistory)
			{
				foreach (KeyValuePair<string, object> variable in option.HistoryName.Variables)
				{
					item.Variables[variable.Key] = variable.Value;
				}
			}
			player.RunState.CurrentMapPointHistoryEntry?.GetEntry(player.NetId).EventChoices.Add(item);
		}

		private void ClearPlayerVotes()
		{
			for (int i = 0; i < _playerVotes.Count; i++)
			{
				_playerVotes[i] = null;
			}
		}

		public uint? GetPlayerVote(Player player)
		{
			return _playerVotes[_playerCollection.GetPlayerSlotIndex(player)];
		}

		public EventModel GetLocalEvent()
		{
			return GetEventForPlayer(LocalPlayer);
		}

		public EventModel GetEventForPlayer(Player player)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
			return _events[playerSlotIndex];
		}

		public void ResumeEvents(AbstractRoom exitedRoom)
		{
			foreach (EventModel @event in _events)
			{
				TaskHelper.RunSafely(@event.Resume(exitedRoom));
			}
		}

		/// <summary>
		/// Called when the room is entered to ensure that state necessary for the event layout is generated.
		/// </summary>
		/// <param name="localEvent"></param>
		public void GenerateInternalCombatStateIfNecessary(EventModel localEvent)
		{
			_combatSynchronizer.InitializeForEvent(localEvent);
		}

		/// <summary>
		/// Called before the room is exited to ensure combat synchronizer state is reset.
		/// If we end up supporting multiple event combats in a single event, this will likely have to be refactored.
		/// </summary>
		public void BeforeExitingRoom()
		{
			_combatSynchronizer.ResetState();
		}

		/// <summary>
		/// Awaits all in-flight event option tasks. Called before the room exit checksum to ensure that all
		/// players' event handlers have finished mutating state. Without this, a peer whose local event
		/// finished quickly (e.g. Touch a Mirror) can exit the room while a remote player's slow handler
		/// (e.g. Shatter's per-card deck duplication loop) is still running, causing the checksum to
		/// capture incomplete state.
		/// </summary>
		public async Task AwaitPendingOptionTasks()
		{
			try
			{
				await Task.WhenAll(_pendingOptionTasks);
			}
			catch (Exception)
			{
			}
			_pendingOptionTasks.Clear();
		}
	}
	/// <summary>
	/// Handles miscellaneous multiplayer messages that are for game feel and fun.
	/// </summary>
	public class FlavorSynchronizer : IDisposable
	{
		private const ulong _pingDebounceMsec = 1000uL;

		private const ulong _mapPingDebounceMsec = 200uL;

		private readonly INetGameService _gameService;

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private ulong _nextAllowedPingTime;

		private readonly System.Collections.Generic.Dictionary<Player, NSpeechBubbleVfx?> _endTurnPingDialogues = new System.Collections.Generic.Dictionary<Player, NSpeechBubbleVfx>();

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		public event Action<ulong>? OnEndTurnPingReceived;

		public FlavorSynchronizer(INetGameService gameService, IPlayerCollection playerCollection, ulong localPlayerId)
		{
			_gameService = gameService;
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			_gameService.RegisterMessageHandler<EndTurnPingMessage>(HandleEndTurnPingMessage);
			_gameService.RegisterMessageHandler<MapPingMessage>(HandleMapPingMessage);
		}

		public void Dispose()
		{
			_gameService.UnregisterMessageHandler<EndTurnPingMessage>(HandleEndTurnPingMessage);
			_gameService.UnregisterMessageHandler<MapPingMessage>(HandleMapPingMessage);
		}

		public void SendEndTurnPing()
		{
			if (Time.GetTicksMsec() >= _nextAllowedPingTime)
			{
				_gameService.SendMessage(default(EndTurnPingMessage));
				_nextAllowedPingTime = Time.GetTicksMsec() + 1000;
				CreateEndTurnPingDialogueIfNecessary(LocalPlayer);
			}
		}

		public void SendMapPing(MapCoord coord)
		{
			if (Time.GetTicksMsec() >= _nextAllowedPingTime)
			{
				_gameService.SendMessage(new MapPingMessage
				{
					coord = coord
				});
				_nextAllowedPingTime = Time.GetTicksMsec() + 200;
				CreateMapPing(coord, LocalPlayer);
			}
		}

		private void HandleEndTurnPingMessage(EndTurnPingMessage message, ulong senderId)
		{
			OnEndTurnPingReceived?.Invoke(senderId);
			CreateEndTurnPingDialogueIfNecessary(_playerCollection.GetPlayer(senderId));
		}

		private void CreateEndTurnPingDialogueIfNecessary(Player player)
		{
			if (NRun.Instance != null)
			{
				_endTurnPingDialogues.TryGetValue(player, out NSpeechBubbleVfx value);
				if (value != null && GodotObject.IsInstanceValid(value))
				{
					value.QueueFreeSafely();
				}
				string text = (player.Creature.IsDead ? "dead" : "alive");
				LocString locString = new LocString("characters", player.Character.Id.Entry + ".banter." + text + ".endTurnPing");
				value = NSpeechBubbleVfx.Create(locString.GetFormattedText(), player.Creature, 1.5, player.Character.SpeechBubbleColor);
				NCombatRoom.Instance?.CombatVfxContainer.AddChildSafely(value);
				_endTurnPingDialogues[player] = value;
			}
		}

		private void HandleMapPingMessage(MapPingMessage message, ulong senderId)
		{
			CreateMapPing(message.coord, _playerCollection.GetPlayer(senderId));
		}

		private void CreateMapPing(MapCoord coord, Player player)
		{
			if (NRun.Instance != null)
			{
				NRun.Instance.GlobalUi.MapScreen.PingMapCoord(coord, player);
			}
		}
	}
	/// <summary>
	/// Provides additional client-related methods on top of the default game service.
	/// </summary>
	public interface INetClientGameService : INetGameService, INetClientHandler, INetHandler
	{
		NetClient? NetClient { get; }

		event Action<NetErrorInfo>? ConnectionFailed;
	}
	/// <summary>
	/// Represents an abstraction of the networking API used to send and receive messages.
	/// Host/join methods are specific to the game manager type on purpose, as those cannot be abstracted. However, once
	/// connected, this interface can be used as a generic way to send/receive messages regardless of whether we are a
	/// host or a client.
	/// </summary>
	public interface INetGameService
	{
		/// <summary>
		/// The player ID of the local player.
		/// </summary>
		ulong NetId { get; }

		/// <summary>
		/// True when the net service is in a state where it can send messages.
		/// </summary>
		bool IsConnected { get; }

		/// <summary>
		/// True if the last call to SetGameLoading was called with true, false otherwise.
		/// </summary>
		bool IsGameLoading { get; }

		/// <summary>
		/// The type of manager this is (host, client, or singleplayer).
		/// </summary>
		NetGameType Type { get; }

		/// <summary>
		/// The networking backend we are using to connect to players.
		/// Note that if we ever consider cross-platform, this likely needs to be contained in the player ID, not here.
		/// </summary>
		PlatformType Platform { get; }

		/// <summary>
		/// The local version of the game we're running.
		/// </summary>
		PeerVersionInfo LocalVersion { get; }

		/// <summary>
		/// Called when the network connection is disconnected and the sockets are disposed.
		/// On host, this occurs when we stop hosting. On clients, this can occur when we quit, our connection drops, or the
		/// host disconnects from us.
		/// </summary>
		event Action<NetErrorInfo>? Disconnected;

		/// <summary>
		/// Sends a message to a specific peer. Note that this should only be used as a host.
		/// </summary>
		/// <param name="message">The message to send.</param>
		/// <param name="playerId">The specific player to send to.</param>
		void SendMessage<T>(T message, ulong playerId) where T : INetMessage;

		/// <summary>
		/// Sends a message to all connected peers.
		/// On the host, this sends a message to all clients. On a client, this sends a message to only the host, but if the
		/// message has the broadcast flag set, the host will replicate it to all other clients.
		/// </summary>
		/// <param name="message">The message to send.</param>
		void SendMessage<T>(T message) where T : INetMessage;

		/// <summary>
		/// Registers a message handler delegate which will be called when a message of type T is received.
		/// </summary>
		/// <param name="messageHandlerDelegate">The delegate to call.</param>
		void RegisterMessageHandler<T>(MessageHandlerDelegate<T> messageHandlerDelegate) where T : INetMessage;

		/// <summary>
		/// Unregisters a message handler delegate that was previously registered. Does nothing if it was not registered.
		/// </summary>
		/// <param name="messageHandlerDelegate">The delegate to unregister.</param>
		void UnregisterMessageHandler<T>(MessageHandlerDelegate<T> messageHandlerDelegate) where T : INetMessage;

		/// <summary>
		/// Method which should be called at regular intervals.
		/// Messages, connections, or disconnections will not be processed unless this is called.
		/// </summary>
		void Update();

		/// <summary>
		/// Disconnects us from all connected peers.
		/// </summary>
		/// <param name="reason">The reason to pass to the remote end to indicate why we quit.</param>
		/// <param name="now">If false, then the connection is allowed to wait until messages are finished sending.
		/// Otherwise, the connection is terminated immediately.</param>
		void Disconnect(NetError reason, bool now = false);

		/// <summary>
		/// Returns the connection statistics for a given peer.
		/// </summary>
		ConnectionStats? GetStatsForPeer(ulong peerId);

		/// <summary>
		/// DO NOT use this directly in most circumstances! Instead, use NetLoadingHandle.
		/// Tells the net service that the game is in a loading state, and that Update may be called irregularly.
		/// See <see cref="M:MegaCrit.Sts2.Core.Multiplayer.Quality.NetQualityTracker.SetIsLoading(System.Boolean)" /> for why this is needed.
		/// </summary>
		void SetGameLoading(bool isLoading);

		/// <summary>
		/// Begins buffering all messages.
		/// When the game is transitioning from one state to another, it will unregister and register message handlers. If
		/// this takes time, then there's a chance that a message will be sent during this window that the game doesn't know
		/// how to handle yet. This method should be called with true after a sync point and then false after the game is
		/// ready to handle messages again.
		/// </summary>
		void SetBufferMessages(bool bufferMessages);

		/// <summary>
		/// Returns a unique identifier for the lobby that this service is connected to.
		/// Returns null if the net service is not yet connected.
		/// This returns a platform-specific identifier for use with rich presence. Feel free to refactor later if more
		/// info or more specific info is needed.
		/// </summary>
		string? GetRawLobbyIdentifier();
	}
	/// <summary>
	/// Delegate which is called when a message is received.
	/// </summary>
	/// <typeparam name="T">The message type.</typeparam>
	/// <param name="message">The message that was received.</param>
	/// <param name="senderId">The sender of the message.</param>
	public delegate void MessageHandlerDelegate<in T>(T message, ulong senderId) where T : INetMessage;
	/// <summary>
	/// Provides additional host-related methods on top of the default game service.
	/// </summary>
	public interface INetHostGameService : INetGameService
	{
		NetHost? NetHost { get; }

		/// <summary>
		/// Event called when a new client connects to the host.
		/// </summary>
		event Action<ulong>? ClientConnected;

		/// <summary>
		/// Event called when a client disconnects from the host, either voluntarily or because we disconnected them.
		/// </summary>
		event Action<ulong, NetErrorInfo>? ClientDisconnected;

		/// <summary>
		/// Event called when a client successfully made a socket connection but we disconnected them during the handshake.
		/// Usually due to version mismatch.
		/// </summary>
		event Action<ulong, NetErrorInfo>? ClientConnectionFailed;

		/// <summary>
		/// Disconnects a client from the host.
		/// </summary>
		/// <param name="peerId">The client to disconnect.</param>
		/// <param name="reason">Why the client is being disconnected.</param>
		/// <param name="now">If true, the client will be forcibly disconnected. The reason may not make it to the client.</param>
		void DisconnectClient(ulong peerId, NetError reason, bool now = false);

		/// <summary>
		/// Marks a client as ready to receive broadcasted messages.
		/// During the initial setup process, we don't want clients to receive broadcast messages as they may not be ready
		/// for them. Call this when initial setup is done.
		/// </summary>
		void SetPeerReadyForBroadcasting(ulong peerId);

		/// <returns>Peer's version info. Null if the peer is not connected, or if they have not yet completed the handshake.
		/// </returns>
		PeerVersionInfo? GetVersionInfoForPeer(ulong peerId);
	}
	/// <summary>
	/// Object which manages the join flow for the local player, who joins as a client.
	/// </summary>
	public class JoinFlow
	{
		private TaskCompletionSource<InitialGameInfoMessage>? _connectCompletion;

		private TaskCompletionSource<ClientRejoinResponseMessage>? _rejoinCompletion;

		private TaskCompletionSource<ClientLoadJoinResponseMessage>? _loadJoinCompletion;

		private TaskCompletionSource<ClientLobbyJoinResponseMessage>? _joinCompletion;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("JoinFlow", LogType.Network);

		public INetClientGameService NetService { get; }

		public CancellationTokenSource CancelToken { get; } = new CancellationTokenSource();

		public JoinFlow(INetClientGameService netService)
		{
			NetService = netService;
		}

		/// <summary>
		/// Begins the join flow.
		/// This task returns either a JoinResult with the final message in the join flow, for use initializing the run or
		/// the Lobby in the case of a rejoin or a join, respectively.
		/// </summary>
		/// <param name="initializer">The object to use when initializing the connection.</param>
		/// <param name="sceneTree">Scene tree to use for hooking into update.
		/// If null, NetService.Update is NOT called and the caller needs to do it manually.</param>
		/// <throws>ClientConnectionFailedException if the join fails. In this case, you should not use NetService. An error
		/// should be shown to the user and they may try to join again.</throws>
		public async Task<JoinResult> Begin(IClientConnectionInitializer initializer, SceneTree? sceneTree)
		{
			MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[LogType.Network] = LogLevel.Debug;
			MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[LogType.Actions] = LogLevel.VeryDebug;
			MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[LogType.GameSync] = LogLevel.VeryDebug;
			if (_connectCompletion != null)
			{
				throw new InvalidOperationException("JoinFlow object can only be used once!");
			}
			_logger.Info($"Beginning join with initializer {initializer}");
			CancelToken.Token.Register(Cancel);
			CancellationTokenSource updateLoopCancelSource = new CancellationTokenSource();
			if (sceneTree != null)
			{
				TaskHelper.RunSafely(NetServiceUpdateLoop(updateLoopCancelSource, sceneTree));
			}
			JoinResult result;
			try
			{
				_ = 4;
				try
				{
					NetService.RegisterMessageHandler<InitialGameInfoMessage>(HandleInitialGameInfoMessage);
					NetService.RegisterMessageHandler<ClientLobbyJoinResponseMessage>(HandleJoinResponseMessage);
					NetService.RegisterMessageHandler<ClientLoadJoinResponseMessage>(HandleLoadJoinResponseMessage);
					NetService.RegisterMessageHandler<ClientRejoinResponseMessage>(HandleRejoinResponseMessage);
					NetService.Disconnected += OnDisconnected;
					NetService.ConnectionFailed += OnFailedToConnectToHost;
					_connectCompletion = new TaskCompletionSource<InitialGameInfoMessage>();
					NetErrorInfo? value = await initializer.Connect(NetService, CancelToken.Token);
					if (value.HasValue)
					{
						_logger.Info($"Connection failed: {value}");
						throw new ClientConnectionFailedException("Could not connect", value.Value);
					}
					_logger.Info("Initializer connection completed, awaiting initial game info message");
					InitialGameInfoMessage initialMessage = await _connectCompletion.Task;
					RunSessionState state = initialMessage.sessionState;
					switch (state)
					{
					case RunSessionState.InLobby:
					{
						ClientLobbyJoinResponseMessage value4 = await AttemptJoin();
						result = new JoinResult
						{
							gameMode = initialMessage.gameMode,
							sessionState = state,
							joinResponse = value4
						};
						break;
					}
					case RunSessionState.InLoadedLobby:
					{
						ClientLoadJoinResponseMessage value3 = await AttemptLoadJoin();
						result = new JoinResult
						{
							gameMode = initialMessage.gameMode,
							sessionState = state,
							loadJoinResponse = value3
						};
						break;
					}
					case RunSessionState.Running:
					{
						ClientRejoinResponseMessage value2 = await AttemptRejoin();
						result = new JoinResult
						{
							gameMode = initialMessage.gameMode,
							sessionState = state,
							rejoinResponse = value2
						};
						break;
					}
					default:
						NetService.Disconnect(NetError.InternalError, now: true);
						throw new InvalidOperationException($"Received invalid state {state} from connection!");
					}
				}
				catch (Exception ex)
				{
					if (NetService.IsConnected)
					{
						NetError reason = ((!(ex is ClientConnectionFailedException ex2)) ? ((ex is OperationCanceledException) ? NetError.CancelledJoin : NetError.InternalError) : ex2.info.GetReason());
						NetService.Disconnected -= OnDisconnected;
						SetDisconnectionException(ex);
						NetService.Disconnect(reason);
					}
					MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[LogType.Network] = LogLevel.Info;
					MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[LogType.Actions] = LogLevel.Info;
					MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[LogType.GameSync] = LogLevel.Info;
					throw;
				}
			}
			finally
			{
				await updateLoopCancelSource.CancelAsync();
				NetService.UnregisterMessageHandler<InitialGameInfoMessage>(HandleInitialGameInfoMessage);
				NetService.UnregisterMessageHandler<ClientLobbyJoinResponseMessage>(HandleJoinResponseMessage);
				NetService.UnregisterMessageHandler<ClientLoadJoinResponseMessage>(HandleLoadJoinResponseMessage);
				NetService.UnregisterMessageHandler<ClientRejoinResponseMessage>(HandleRejoinResponseMessage);
				NetService.Disconnected -= OnDisconnected;
			}
			return result;
		}

		private async Task NetServiceUpdateLoop(CancellationTokenSource token, SceneTree sceneTree)
		{
			while (!token.IsCancellationRequested)
			{
				try
				{
					NetService.Update();
				}
				catch (Exception ex)
				{
					Log.Error(ex.ToString());
				}
				await sceneTree.ToSignal(sceneTree, SceneTree.SignalName.ProcessFrame);
			}
		}

		private async Task<ClientLobbyJoinResponseMessage> AttemptJoin()
		{
			_joinCompletion = new TaskCompletionSource<ClientLobbyJoinResponseMessage>();
			_logger.Info("Sending ClientLobbyJoinRequestMessage and waiting for response message");
			UnlockState unlockState = SaveManager.Instance.GenerateUnlockStateFromProgress();
			ClientLobbyJoinRequestMessage message = new ClientLobbyJoinRequestMessage
			{
				maxAscensionUnlocked = SaveManager.Instance.Progress.MaxMultiplayerAscension,
				unlockState = unlockState.ToSerializable()
			};
			NetService.SendMessage(message);
			ClientLobbyJoinResponseMessage clientLobbyJoinResponseMessage = await _joinCompletion.Task;
			_logger.Info($"Received {"ClientLobbyJoinResponseMessage"}: {clientLobbyJoinResponseMessage}");
			return clientLobbyJoinResponseMessage;
		}

		private async Task<ClientLoadJoinResponseMessage> AttemptLoadJoin()
		{
			_loadJoinCompletion = new TaskCompletionSource<ClientLoadJoinResponseMessage>();
			_logger.Info("Sending ClientLoadJoinRequestMessage and waiting for rejoin response message");
			NetService.SendMessage(default(ClientLoadJoinRequestMessage));
			ClientLoadJoinResponseMessage clientLoadJoinResponseMessage = await _loadJoinCompletion.Task;
			_logger.Info($"Received ClientLoadJoinResponseMessage: {clientLoadJoinResponseMessage}");
			return clientLoadJoinResponseMessage;
		}

		private async Task<ClientRejoinResponseMessage> AttemptRejoin()
		{
			_rejoinCompletion = new TaskCompletionSource<ClientRejoinResponseMessage>();
			_logger.Info("Sending ClientRequestRejoinMessage and waiting for rejoin response message");
			NetService.SendMessage(default(ClientRejoinRequestMessage));
			ClientRejoinResponseMessage clientRejoinResponseMessage = await _rejoinCompletion.Task;
			_logger.Info($"Received ClientRejoinResponseMessage: {clientRejoinResponseMessage}");
			return clientRejoinResponseMessage;
		}

		private void HandleInitialGameInfoMessage(InitialGameInfoMessage message, ulong _)
		{
			if (_connectCompletion == null || _connectCompletion.Task.IsCompleted)
			{
				_logger.Warn($"Received {"InitialGameInfoMessage"} when we weren't expecting it! Completion status: {_connectCompletion}");
			}
			else
			{
				_connectCompletion.SetResult(message);
			}
		}

		private void HandleRejoinResponseMessage(ClientRejoinResponseMessage message, ulong senderId)
		{
			if (_rejoinCompletion == null || _rejoinCompletion.Task.IsCompleted)
			{
				_logger.Warn($"Received {"ClientRejoinResponseMessage"} when we weren't expecting it! Completion status: {_connectCompletion}");
			}
			else
			{
				_rejoinCompletion.SetResult(message);
			}
		}

		private void HandleLoadJoinResponseMessage(ClientLoadJoinResponseMessage message, ulong senderId)
		{
			if (_loadJoinCompletion == null || _loadJoinCompletion.Task.IsCompleted)
			{
				_logger.Warn($"Received {"ClientLoadJoinResponseMessage"} when we weren't expecting it! Completion status: {_connectCompletion}");
			}
			else
			{
				_loadJoinCompletion.SetResult(message);
			}
		}

		private void HandleJoinResponseMessage(ClientLobbyJoinResponseMessage message, ulong senderId)
		{
			if (_joinCompletion == null || _joinCompletion.Task.IsCompleted)
			{
				_logger.Warn($"Received {"ClientLobbyJoinResponseMessage"} when we weren't expecting it! Completion status: {_connectCompletion}");
			}
			else
			{
				_joinCompletion.SetResult(message);
			}
		}

		private void OnDisconnected(NetErrorInfo info)
		{
			_logger.Info($"Disconnected during join flow, reason: {info.GetReason()}. Failing with an exception");
			ClientConnectionFailedException disconnectionException = new ClientConnectionFailedException($"Unexpectedly disconnected from host while joining. Reason: {info.GetReason()}", info);
			SetDisconnectionException(disconnectionException);
		}

		private void OnFailedToConnectToHost(NetErrorInfo info)
		{
			_logger.Info($"Failed to connect to the host. Reason: {info.GetReason()}.");
			ClientConnectionFailedException disconnectionException = new ClientConnectionFailedException($"Failed to connect to the host. Reason: {info.GetReason()}", info);
			SetDisconnectionException(disconnectionException);
		}

		private void SetDisconnectionException(Exception exception)
		{
			TaskCompletionSource<InitialGameInfoMessage> connectCompletion = _connectCompletion;
			if (connectCompletion != null)
			{
				Task<InitialGameInfoMessage> task = connectCompletion.Task;
				if (task != null && !task.IsCompleted)
				{
					_connectCompletion.SetException(exception);
				}
			}
			TaskCompletionSource<ClientLobbyJoinResponseMessage> joinCompletion = _joinCompletion;
			if (joinCompletion != null)
			{
				Task<ClientLobbyJoinResponseMessage> task2 = joinCompletion.Task;
				if (task2 != null && !task2.IsCompleted)
				{
					_joinCompletion?.SetException(exception);
				}
			}
			TaskCompletionSource<ClientLoadJoinResponseMessage> loadJoinCompletion = _loadJoinCompletion;
			if (loadJoinCompletion != null)
			{
				Task<ClientLoadJoinResponseMessage> task3 = loadJoinCompletion.Task;
				if (task3 != null && !task3.IsCompleted)
				{
					_loadJoinCompletion?.SetException(exception);
				}
			}
			TaskCompletionSource<ClientRejoinResponseMessage> rejoinCompletion = _rejoinCompletion;
			if (rejoinCompletion != null)
			{
				Task<ClientRejoinResponseMessage> task4 = rejoinCompletion.Task;
				if (task4 != null && !task4.IsCompleted)
				{
					_rejoinCompletion?.SetException(exception);
				}
			}
		}

		private void Cancel()
		{
			TaskCompletionSource<InitialGameInfoMessage> connectCompletion = _connectCompletion;
			if (connectCompletion != null)
			{
				Task<InitialGameInfoMessage> task = connectCompletion.Task;
				if (task != null && !task.IsCompleted)
				{
					_connectCompletion.SetCanceled();
				}
			}
			TaskCompletionSource<ClientLobbyJoinResponseMessage> joinCompletion = _joinCompletion;
			if (joinCompletion != null)
			{
				Task<ClientLobbyJoinResponseMessage> task2 = joinCompletion.Task;
				if (task2 != null && !task2.IsCompleted)
				{
					_joinCompletion?.SetCanceled();
				}
			}
			TaskCompletionSource<ClientLoadJoinResponseMessage> loadJoinCompletion = _loadJoinCompletion;
			if (loadJoinCompletion != null)
			{
				Task<ClientLoadJoinResponseMessage> task3 = loadJoinCompletion.Task;
				if (task3 != null && !task3.IsCompleted)
				{
					_loadJoinCompletion?.SetCanceled();
				}
			}
			TaskCompletionSource<ClientRejoinResponseMessage> rejoinCompletion = _rejoinCompletion;
			if (rejoinCompletion != null)
			{
				Task<ClientRejoinResponseMessage> task4 = rejoinCompletion.Task;
				if (task4 != null && !task4.IsCompleted)
				{
					_rejoinCompletion?.SetCanceled();
				}
			}
		}
	}
	public struct JoinResult
	{
		public GameMode gameMode;

		public RunSessionState? sessionState;

		public ClientRejoinResponseMessage? rejoinResponse;

		public ClientLoadJoinResponseMessage? loadJoinResponse;

		public ClientLobbyJoinResponseMessage? joinResponse;
	}
	public class MapSelectionSynchronizer
	{
		private readonly INetGameService _netService;

		private readonly ActionQueueSynchronizer _actionQueueSynchronizer;

		private readonly RunState _runState;

		private MapLocation _acceptingVotesFromSource;

		private readonly List<MapVote?> _votes = new List<MapVote?>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("MapSelectionSynchronizer", LogType.GameSync);

		private readonly Rng _multiplayerMapPointSelection;

		/// <summary>
		/// Each time we generate a map, this counter goes up. It is used to keep track of multiplayer map votes and to
		/// discard map votes that are for old maps.
		/// </summary>
		public int MapGenerationCount { get; private set; }

		public event Action<Player, MapVote?, MapVote?>? PlayerVoteChanged;

		public event Action<Player>? PlayerVoteCancelled;

		public event Action? PlayerVotesCleared;

		public MapSelectionSynchronizer(INetGameService netService, ActionQueueSynchronizer actionQueueSynchronizer, RunState runState)
		{
			_netService = netService;
			_actionQueueSynchronizer = actionQueueSynchronizer;
			_runState = runState;
			_multiplayerMapPointSelection = new Rng(_runState.Rng.Seed, "map_point_selection");
			OnLocationChanged(_runState.MapLocation);
		}

		public void PlayerVotedForMapCoord(Player player, MapLocation source, MapVote? destination)
		{
			if (_acceptingVotesFromSource != source)
			{
				_logger.Warn($"Received map vote from player {player.NetId} for source {source}, but we're currently accepting votes for {_acceptingVotesFromSource}");
				return;
			}
			if (destination?.mapGenerationCount < MapGenerationCount)
			{
				_logger.Warn($"Received map vote from player {player.NetId} for destination {destination}, but the map generation count is lower than our current: {MapGenerationCount}");
				return;
			}
			int playerSlotIndex = _runState.GetPlayerSlotIndex(player);
			MapVote? arg = _votes[playerSlotIndex];
			_votes[playerSlotIndex] = destination;
			PlayerVoteChanged?.Invoke(player, arg, destination);
			if (destination.HasValue)
			{
				_logger.Debug($"Received vote to move to {destination} from player {player.NetId} (slot {playerSlotIndex})");
			}
			else
			{
				_logger.Debug($"Received cancellation of vote from player {player.NetId} (slot {playerSlotIndex})");
			}
			if (_votes.All((MapVote? p) => p.HasValue && p.Value.mapGenerationCount == MapGenerationCount) && _netService.Type != NetGameType.Client)
			{
				_logger.Debug("All votes received and we are host, choosing coordinate");
				MoveToMapCoord();
			}
		}

		public MapVote? GetVote(Player player)
		{
			return _votes[_runState.GetPlayerSlotIndex(player)];
		}

		private void MoveToMapCoord()
		{
			if (_netService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Only host should be moving to new map point!");
			}
			MapCoord coord = _multiplayerMapPointSelection.NextItem(_votes).Value.coord;
			_acceptingVotesFromSource.coord = coord;
			_logger.Debug($"Moving to coordinate {coord}");
			MoveToMapCoordAction action = new MoveToMapCoordAction(LocalContext.GetMe(_runState), coord);
			_actionQueueSynchronizer.RequestEnqueue(action);
		}

		public void OnLocationChanged(MapLocation location)
		{
			_acceptingVotesFromSource = location;
			_votes.Clear();
			for (int i = 0; i < _runState.Players.Count; i++)
			{
				_votes.Add(null);
			}
			PlayerVotesCleared?.Invoke();
		}

		public void BeforeMapGenerated()
		{
			MapGenerationCount++;
			for (int i = 0; i < _votes.Count; i++)
			{
				MapVote? mapVote = _votes[i];
				if (mapVote.HasValue && mapVote.Value.mapGenerationCount < MapGenerationCount)
				{
					Player player = _runState.Players[i];
					_logger.Debug($"Cancelling map vote for player {player.NetId} because the map has re-generated and their vote is old");
					_votes[i] = null;
					PlayerVoteCancelled?.Invoke(player);
				}
			}
		}
	}
	/// <summary>
	/// Represents a player's vote for the map coordinate to move to next.
	/// Used in multiplayer to tally player votes and move on to the one that the majority have voted for.
	/// </summary>
	public struct MapVote : IPacketSerializable
	{
		/// <summary>
		/// How many map generations have occurred before this map vote was received.
		/// Used to invalidate map votes for old maps, in the case that a map was generated multiple times for the same act.
		/// See Golden Compass.
		/// </summary>
		public int mapGenerationCount;

		/// <summary>
		/// The coordinate within the map the player has voted for.
		/// </summary>
		public MapCoord coord;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(mapGenerationCount, 4);
			writer.Write(coord);
		}

		public void Deserialize(PacketReader reader)
		{
			mapGenerationCount = reader.ReadInt(4);
			coord = reader.Read<MapCoord>();
		}

		public override string ToString()
		{
			return $"{"MapVote"} (gen: {mapGenerationCount} coord: ({coord.col}, {coord.row}))";
		}
	}
	public enum NetGameType
	{
		None,
		Singleplayer,
		Host,
		Client,
		Replay
	}
	public static class NetGameTypeExtensions
	{
		public static bool IsMultiplayer(this NetGameType type)
		{
			if ((uint)(type - 2) <= 1u)
			{
				return true;
			}
			return false;
		}
	}
	/// <summary>
	/// A utility class for marking the start and end of a loading sequence. Basically just equivalent of calling
	/// NetService.SetGameLoading with true, and then false at the end of the scope.
	/// Construct one of these with a using statement any time we enter a long loading sequence to let the networking layer
	/// know that the game's framerate might dip. If you don't do this, we might accidentally display a "waiting for
	/// connection from host" overlay because messages aren't being processed.
	/// </summary>
	public class NetLoadingHandle : IDisposable
	{
		private static readonly System.Collections.Generic.Dictionary<INetGameService, int> _loadCounts = new System.Collections.Generic.Dictionary<INetGameService, int>();

		private readonly INetGameService _netService;

		public NetLoadingHandle(INetGameService netService)
		{
			_netService = netService;
			if (!_loadCounts.TryGetValue(_netService, out var value) || value == 0)
			{
				_netService.SetGameLoading(isLoading: true);
			}
			_loadCounts[_netService] = value + 1;
		}

		public void Dispose()
		{
			if (_loadCounts[_netService] == 1)
			{
				_netService.SetGameLoading(isLoading: false);
			}
			_loadCounts[_netService]--;
		}

		public static void Release(INetGameService netService)
		{
			_loadCounts.Remove(netService);
		}
	}
	/// <summary>
	/// A synchronizer for a few one-off scenarios that don't fit in any other synchronizer.
	/// This should be used pretty rarely, and we should be on the lookout for patterns that emerge with new content.
	/// </summary>
	public class OneOffSynchronizer : IDisposable
	{
		private readonly RunLocationTargetedMessageBuffer _messageBuffer;

		private readonly INetGameService _gameService;

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		public OneOffSynchronizer(RunLocationTargetedMessageBuffer messageBuffer, INetGameService gameService, IPlayerCollection playerCollection, ulong localPlayerId)
		{
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			_gameService = gameService;
			_messageBuffer = messageBuffer;
			messageBuffer.RegisterMessageHandler<MerchantCardRemovalMessage>(HandleMerchantCardRemoval);
			messageBuffer.RegisterMessageHandler<TreasureChestOpenedMessage>(HandleTreasureChestOpenedMessage);
			messageBuffer.RegisterMessageHandler<CrystalSphereRewardsMessage>(HandleCrystalSphereRewardsMessage);
		}

		public void Dispose()
		{
			_messageBuffer.UnregisterMessageHandler<MerchantCardRemovalMessage>(HandleMerchantCardRemoval);
			_messageBuffer.UnregisterMessageHandler<TreasureChestOpenedMessage>(HandleTreasureChestOpenedMessage);
			_messageBuffer.UnregisterMessageHandler<CrystalSphereRewardsMessage>(HandleCrystalSphereRewardsMessage);
		}

		/// <summary>
		/// Does merchant card removal for the local player.
		/// </summary>
		/// <param name="goldCost">The cost, in gold, that we should deduct from the player's gold count.</param>
		/// <param name="cancelable">If false, you are required to remove a card</param>
		/// <returns>A task that completes when the player finishes the removal flow. Result is true if the player removed
		/// a card, false otherwise.</returns>
		public Task<bool> DoLocalMerchantCardRemoval(int goldCost, bool cancelable = true)
		{
			MerchantCardRemovalMessage message = new MerchantCardRemovalMessage
			{
				goldCost = goldCost,
				Location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
			return DoMerchantCardRemoval(LocalPlayer, goldCost, cancelable);
		}

		private void HandleMerchantCardRemoval(MerchantCardRemovalMessage message, ulong senderId)
		{
			Player player = _playerCollection.GetPlayer(senderId);
			if (player == LocalPlayer)
			{
				throw new InvalidOperationException("MerchantCardRemovalMessage should not be sent to the player removing the card!");
			}
			TaskHelper.RunSafely(DoMerchantCardRemoval(player, message.goldCost));
		}

		private async Task<bool> DoMerchantCardRemoval(Player player, int goldCost, bool cancelable = true)
		{
			CardSelectorPrefs prefs = new CardSelectorPrefs(CardSelectorPrefs.RemoveSelectionPrompt, 1)
			{
				Cancelable = cancelable,
				RequireManualConfirmation = true
			};
			CardModel card = (await CardSelectCmd.FromDeckForRemoval(player, prefs)).FirstOrDefault();
			if (card != null)
			{
				await PlayerCmd.LoseGold(goldCost, player, GoldLossType.Spent);
				await CardPileCmd.RemoveFromDeck(card);
				player.ExtraFields.CardShopRemovalsUsed++;
			}
			return card != null;
		}

		/// <summary>
		/// Should be called after a player opens the chest in the treasure room to synchronize gold gain and other effects.
		/// </summary>
		/// <returns>The amount of gold given to the player.</returns>
		public Task<int> DoLocalTreasureRoomRewards()
		{
			TreasureChestOpenedMessage message = new TreasureChestOpenedMessage
			{
				Location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
			return DoTreasureRoomRewards(LocalPlayer);
		}

		private void HandleTreasureChestOpenedMessage(TreasureChestOpenedMessage message, ulong senderId)
		{
			Player player = _playerCollection.GetPlayer(senderId);
			if (player == LocalPlayer)
			{
				throw new InvalidOperationException("TreasureChestOpenedMessage should not be sent to the player who opened the treasure chest!");
			}
			TaskHelper.RunSafely(DoTreasureRoomRewards(player));
		}

		private async Task<int> DoTreasureRoomRewards(Player player)
		{
			if (!Hook.ShouldGenerateTreasure(player.RunState, player))
			{
				return 0;
			}
			double gold = player.PlayerRng.Rewards.NextInt(42, 53);
			if (AscensionHelper.HasAscension(AscensionLevel.Poverty))
			{
				gold *= AscensionHelper.PovertyAscensionGoldMultiplier;
			}
			await PlayerCmd.GainGold((int)gold, player);
			double num = gold;
			gold = num + (double)(await TryHandleSpoilsMap(player));
			return (int)gold;
		}

		/// <summary>
		/// Special one-off logic for Spoils Map. If more stuff ends up going here, make this a hook
		/// </summary>
		/// <returns>The amount of gold given by spoils map, if any.</returns>
		private async Task<int> TryHandleSpoilsMap(Player player)
		{
			MapPoint mapPoint = (player.RunState.CurrentMapCoord.HasValue ? player.RunState.Map.GetPoint(player.RunState.CurrentMapCoord.Value) : null);
			if (mapPoint == null)
			{
				return 0;
			}
			if (!mapPoint.Quests.Any((AbstractModel q) => q is SpoilsMap))
			{
				return 0;
			}
			List<SpoilsMap> list = player.Deck.Cards.OfType<SpoilsMap>().ToList();
			int num = 0;
			foreach (SpoilsMap item in list)
			{
				int num2 = num;
				num = num2 + await item.OnQuestComplete();
			}
			return num;
		}

		/// <summary>
		/// Special one-off logic for presenting crystal sphere rewards to the player, and notifying other players that
		/// crystal sphere rewards are beginning for the local player.
		/// </summary>
		public async Task DoLocalCrystalSphereRewards(Player owner, Rng rng, List<CrystalSphereItem> revealed)
		{
			if (owner != LocalContext.GetMe(_playerCollection))
			{
				throw new InvalidOperationException($"Trying to sync crystal sphere rewards for non-local player {owner.NetId}!");
			}
			List<SerializableCrystalSphereItem> rewards = revealed.Select((CrystalSphereItem r) => r.ToSerializable()).ToList();
			CrystalSphereRewardsMessage message = new CrystalSphereRewardsMessage
			{
				Location = _messageBuffer.CurrentLocation,
				rewards = rewards
			};
			_gameService.SendMessage(message);
			await OfferCrystalSphereRewards(owner, revealed, rng);
		}

		private void HandleCrystalSphereRewardsMessage(CrystalSphereRewardsMessage message, ulong senderId)
		{
			Player player = _playerCollection.GetPlayer(senderId);
			if (player == LocalPlayer)
			{
				throw new InvalidOperationException("CrystalSphereRewardsMessage should not be sent to the player who completed the event!");
			}
			EventModel eventForPlayer = RunManager.Instance.EventSynchronizer.GetEventForPlayer(player);
			if (!(eventForPlayer is CrystalSphere crystalSphere))
			{
				throw new InvalidOperationException($"Received {"CrystalSphereRewardsMessage"} for player {player.NetId} while the player was in event {eventForPlayer.Id}!");
			}
			List<CrystalSphereItem> revealed = message.rewards.Select((SerializableCrystalSphereItem r) => CrystalSphereItem.FromSerializable(r, player)).ToList();
			TaskHelper.RunSafely(OfferCrystalSphereRewards(player, revealed, crystalSphere.Rng));
		}

		private async Task OfferCrystalSphereRewards(Player owner, List<CrystalSphereItem> revealed, Rng rng)
		{
			List<Reward> rewards = revealed.Select((CrystalSphereItem r) => r.ToReward(owner, rng)).OfType<Reward>().ToList();
			await RewardsCmd.OfferCustom(owner, rewards);
		}
	}
	/// <summary>
	/// Handles miscellaneous multiplayer messages that are for game feel and fun.
	/// </summary>
	public class ReactionSynchronizer : IDisposable
	{
		private readonly NReactionContainer _container;

		public INetGameService NetService { get; }

		public ReactionSynchronizer(INetGameService netService, NReactionContainer container)
		{
			NetService = netService;
			_container = container;
			NetService.RegisterMessageHandler<ReactionMessage>(HandleReactionMessage);
		}

		public void Dispose()
		{
			NetService.UnregisterMessageHandler<ReactionMessage>(HandleReactionMessage);
		}

		public void SendLocalReaction(ReactionType type, Godot.Vector2 mouseScreenPos)
		{
			ReactionMessage message = new ReactionMessage
			{
				type = type,
				normalizedPosition = NetCursorHelper.GetNormalizedPosition(mouseScreenPos, _container)
			};
			NetService.SendMessage(message);
		}

		private void HandleReactionMessage(ReactionMessage message, ulong senderId)
		{
			_container.DoRemoteReaction(message.type, NetCursorHelper.GetControlSpacePosition(message.normalizedPosition, _container));
		}
	}
	public class RestSiteSynchronizer : IDisposable
	{
		private class PlayerRestSite
		{
			public List<RestSiteOption> options;

			public uint? lastChosenOptionIndex;

			public uint? hoveredOptionIndex;

			public TaskCompletionSource completionTaskSource = new TaskCompletionSource();
		}

		public const int minHoverMessageMsec = 50;

		private readonly INetGameService _netService;

		private readonly RunLocationTargetedMessageBuffer _messageBuffer;

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private readonly RunLobby? _runLobby;

		private readonly List<PlayerRestSite> _restSites = new List<PlayerRestSite>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("RestSiteSynchronizer", LogType.GameSync);

		private ulong _lastHoverMessageMsec;

		private RestSiteOptionHoveredMessage? _hoveredMessage;

		private Task? _hoverMessageTask;

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		public event Action<ulong>? PlayerHoverChanged;

		public event Action<RestSiteOption, ulong>? BeforePlayerOptionChosen;

		public event Action<RestSiteOption, bool, ulong>? AfterPlayerOptionChosen;

		public RestSiteSynchronizer(RunLocationTargetedMessageBuffer messageBuffer, INetGameService netService, IPlayerCollection playerCollection, ulong localPlayerId, RunLobby? runLobby)
		{
			_netService = netService;
			_messageBuffer = messageBuffer;
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			_runLobby = runLobby;
			_messageBuffer.RegisterMessageHandler<OptionIndexChosenMessage>(HandleRestSiteOptionChosenMessage);
			_messageBuffer.RegisterMessageHandler<RestSiteOptionHoveredMessage>(HandleRestSiteOptionHoveredMessage);
			_messageBuffer.RegisterMessageHandler<RestSiteSkippedMessage>(HandleRestSiteSkippedMessage);
			if (_runLobby != null)
			{
				_runLobby.RemotePlayerDisconnected += OnPeerDisconnected;
			}
		}

		public void Dispose()
		{
			_messageBuffer.UnregisterMessageHandler<OptionIndexChosenMessage>(HandleRestSiteOptionChosenMessage);
			_messageBuffer.UnregisterMessageHandler<RestSiteOptionHoveredMessage>(HandleRestSiteOptionHoveredMessage);
			_messageBuffer.UnregisterMessageHandler<RestSiteSkippedMessage>(HandleRestSiteSkippedMessage);
			if (_runLobby != null)
			{
				_runLobby.RemotePlayerDisconnected -= OnPeerDisconnected;
			}
			_hoverMessageTask?.Dispose();
			_hoverMessageTask = null;
		}

		public void BeginRestSite()
		{
			_logger.Debug("Beginning rest site");
			_restSites.Clear();
			foreach (Player player in _playerCollection.Players)
			{
				List<RestSiteOption> list = RestSiteOption.Generate(player);
				_restSites.Add(new PlayerRestSite
				{
					options = list
				});
				_logger.VeryDebug($"Rest site began for player {player.NetId} with options: {string.Join(",", list)}");
			}
		}

		private void HandleRestSiteOptionChosenMessage(OptionIndexChosenMessage message, ulong senderId)
		{
			if (message.type == OptionIndexType.RestSite)
			{
				_logger.Debug($"Player {senderId} chose rest site option index {message.optionIndex}");
				Player player = _playerCollection.GetPlayer(senderId);
				if (player == null)
				{
					throw new InvalidOperationException($"Received EventOptionChosenMessage for player {senderId} that doesn't exist!");
				}
				TaskHelper.RunSafely(ChooseOption(player, (int)message.optionIndex));
			}
		}

		private void HandleRestSiteOptionHoveredMessage(RestSiteOptionHoveredMessage message, ulong senderId)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(_playerCollection.GetPlayer(senderId));
			_restSites[playerSlotIndex].hoveredOptionIndex = message.optionIndex;
			PlayerHoverChanged?.Invoke(senderId);
		}

		private void HandleRestSiteSkippedMessage(RestSiteSkippedMessage message, ulong senderId)
		{
			_logger.Debug($"Player {senderId} skipped remaining options at rest site");
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(_playerCollection.GetPlayer(senderId));
			PlayerRestSite playerRestSite = _restSites[playerSlotIndex];
			if (!playerRestSite.completionTaskSource.Task.IsCompleted)
			{
				_logger.Debug($"Skipping {playerRestSite.options.Count} options");
				playerRestSite.options.Clear();
				playerRestSite.completionTaskSource.TrySetResult();
			}
		}

		/// <summary>
		/// Called when a remote player disconnects. If they still had rest site options remaining, they will never send us a
		/// skip or final option-chosen message, so we complete their rest site here. Otherwise a room exit that is waiting
		/// on <see cref="M:MegaCrit.Sts2.Core.Multiplayer.Game.RestSiteSynchronizer.AfterAllRestSitesCompleted" /> would hang forever.
		/// </summary>
		private void OnPeerDisconnected(ulong peerId)
		{
			Player player = _playerCollection.GetPlayer(peerId);
			if (player == null)
			{
				return;
			}
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
			if (playerSlotIndex < _restSites.Count)
			{
				PlayerRestSite playerRestSite = _restSites[playerSlotIndex];
				if (!playerRestSite.completionTaskSource.Task.IsCompleted)
				{
					_logger.Debug($"Player {peerId} disconnected with {playerRestSite.options.Count} rest site options remaining; completing their rest site");
					playerRestSite.options.Clear();
					playerRestSite.completionTaskSource.SetResult();
				}
			}
		}

		public Task<bool> ChooseLocalOption(int index)
		{
			_logger.Debug($"Local player chose rest site option index {index}");
			OptionIndexChosenMessage message = new OptionIndexChosenMessage
			{
				type = OptionIndexType.RestSite,
				optionIndex = (uint)index,
				location = _messageBuffer.CurrentLocation
			};
			_netService.SendMessage(message);
			return ChooseOption(LocalPlayer, index);
		}

		private async Task<bool> ChooseOption(Player player, int optionIndex)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
			PlayerRestSite restSite = _restSites[playerSlotIndex];
			if (restSite.completionTaskSource.Task.IsCompleted)
			{
				throw new InvalidOperationException($"Player {player.NetId} attempted to choose rest site option index {optionIndex}, but the rest site has already been completed!");
			}
			if (optionIndex >= restSite.options.Count)
			{
				throw new InvalidOperationException($"Player {player.NetId} attempted to choose rest site option index {optionIndex}, but there were only {restSite.options.Count} options available!");
			}
			RestSiteOption option = restSite.options[optionIndex];
			BeforePlayerOptionChosen?.Invoke(option, player.NetId);
			bool flag = await option.OnSelect();
			_logger.Debug($"Rest site option index {optionIndex} chosen for player {player.NetId} with success {flag}. Option: {option.OptionId}");
			restSite.lastChosenOptionIndex = (uint)optionIndex;
			AfterPlayerOptionChosen?.Invoke(option, flag, player.NetId);
			if (!flag)
			{
				return false;
			}
			player.RunState.CurrentMapPointHistoryEntry?.GetEntry(player.NetId).RestSiteChoices.Add(option.OptionId);
			if (restSite.completionTaskSource.Task.IsCompleted)
			{
				return true;
			}
			if (Hook.ShouldDisableRemainingRestSiteOptions(player.RunState, player))
			{
				_logger.Debug($"Clearing all remaining rest site options for player {player.NetId}");
				restSite.options.Clear();
			}
			else
			{
				_logger.Debug($"Leaving remaining rest site options enabled for player {player.NetId}");
				restSite.options.RemoveAt(optionIndex);
			}
			if (restSite.options.Count == 0)
			{
				_logger.Debug($"Completing rest site for player {player.NetId} because there are no options left");
				restSite.completionTaskSource.SetResult();
			}
			return true;
		}

		/// <summary>
		/// Called by <see cref="T:MegaCrit.Sts2.Core.Rooms.RestSiteRoom" /> when the room is exited.
		/// If there are still options remaining for the local player, those options are cleared and the room is completed.
		/// This completion is synced to other players.
		/// </summary>
		public void BeforeLocalRestSiteExited()
		{
			Player me = LocalContext.GetMe(_playerCollection);
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(me);
			PlayerRestSite playerRestSite = _restSites[playerSlotIndex];
			if (playerRestSite.options.Count > 0)
			{
				_logger.Debug($"Skipping remaining options ({playerRestSite.options.Count}) in rest site for local player {me.NetId} because we're exiting the rest site");
				playerRestSite.options.Clear();
				playerRestSite.completionTaskSource.SetResult();
				_netService.SendMessage(new RestSiteSkippedMessage
				{
					Location = _messageBuffer.CurrentLocation
				});
			}
		}

		/// <summary>
		/// Waits for all players' rest sites to be completed.
		/// This must be awaited before the room-exit checksum is generated so that we know that we won't be receiving any
		/// more OptionIndexChosenMessages for this room.
		/// </summary>
		public async Task AfterAllRestSitesCompleted()
		{
			foreach (PlayerRestSite restSite in _restSites)
			{
				await restSite.completionTaskSource.Task;
			}
		}

		public void LocalOptionHovered(RestSiteOption? option)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(LocalContext.GetMe(_playerCollection));
			PlayerRestSite playerRestSite = _restSites[playerSlotIndex];
			if (option != null)
			{
				playerRestSite.hoveredOptionIndex = (uint)playerRestSite.options.IndexOf(option);
			}
			else
			{
				playerRestSite.hoveredOptionIndex = null;
			}
			RestSiteOptionHoveredMessage valueOrDefault = _hoveredMessage.GetValueOrDefault();
			if (!_hoveredMessage.HasValue)
			{
				valueOrDefault = new RestSiteOptionHoveredMessage
				{
					Location = _messageBuffer.CurrentLocation,
					optionIndex = playerRestSite.hoveredOptionIndex
				};
				_hoveredMessage = valueOrDefault;
			}
			TrySendHoverMessage();
			PlayerHoverChanged?.Invoke(LocalContext.NetId.Value);
		}

		public int? GetHoveredOptionIndex(ulong playerId)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(_playerCollection.GetPlayer(playerId));
			return (int?)_restSites[playerSlotIndex].hoveredOptionIndex;
		}

		public int? GetChosenOptionIndex(ulong playerId)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(_playerCollection.GetPlayer(playerId));
			return (int?)_restSites[playerSlotIndex].lastChosenOptionIndex;
		}

		public IReadOnlyList<RestSiteOption> GetLocalOptions()
		{
			return GetOptionsForPlayer(LocalPlayer);
		}

		public IReadOnlyList<RestSiteOption> GetOptionsForPlayer(ulong playerId)
		{
			return GetOptionsForPlayer(_playerCollection.GetPlayer(playerId));
		}

		public IReadOnlyList<RestSiteOption> GetOptionsForPlayer(Player player)
		{
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
			return _restSites[playerSlotIndex].options;
		}

		/// <summary>
		/// Sends a hover message if enough time has passed since the last one, or buffers it to be sent otherwise.
		/// </summary>
		private void TrySendHoverMessage()
		{
			if (_hoverMessageTask == null)
			{
				int num = (int)(_lastHoverMessageMsec + 50 - Time.GetTicksMsec());
				if (num <= 0)
				{
					_hoverMessageTask = TaskHelper.RunSafely(SendHoverMessageAfterSmallDelay());
				}
				else
				{
					_hoverMessageTask = TaskHelper.RunSafely(QueueHoverMessage(num));
				}
			}
		}

		private async Task QueueHoverMessage(int delayMsec)
		{
			await Task.Delay(delayMsec);
			SendHoverMessage();
		}

		private async Task SendHoverMessageAfterSmallDelay()
		{
			await Task.Yield();
			SendHoverMessage();
		}

		private void SendHoverMessage()
		{
			if (_netService.IsConnected)
			{
				_netService.SendMessage(_hoveredMessage.Value);
				_lastHoverMessageMsec = Time.GetTicksMsec();
				_hoveredMessage = null;
				_hoverMessageTask = null;
			}
		}
	}
	/// <summary>
	/// Synchronizer responsible for executing reward set behavior for each player.
	/// When any player generates a reward from any source (end of combat, relics, events), the RewardsSet calls into this
	/// synchronizer. Then, as the owning player selects or skips rewards, they send messages to all other players
	/// indicating which rewards they took. This synchronizer handles those messages.
	/// </summary>
	public class RewardsSetSynchronizer : IDisposable
	{
		/// <summary>
		/// Denotes how a reward set was completed.
		/// </summary>
		private enum RewardSetCompleteState
		{
			None,
			/// <summary>
			/// All the rewards in the set were taken.
			/// </summary>
			Completed,
			/// <summary>
			/// Some (or all) of the rewards in the set were skipped.
			/// </summary>
			Skipped
		}

		/// <summary>
		/// Represents a message that was sent for a remote player about a reward set that has not yet spawned for the local
		/// player.
		/// For example, if players have differing combat speeds, one player may reach the end of combat before us, and
		/// begin taking their rewards. This will start sending messages, but our local NCombatUi will not have begun the
		/// rewards process yet, so we need to buffer the remote messages for when it does.
		/// </summary>
		private record struct BufferedMessage
		{
			public int SetId => selectedMessage?.setId ?? (skippedMessage ?? throw new InvalidOperationException()).setId;

			public RewardSelectedMessage? selectedMessage;

			public RewardSetSkippedMessage? skippedMessage;

			public ulong senderId;
		}

		/// <summary>
		/// Reward state for a given player. Contains a stack of reward sets.
		/// </summary>
		private class PlayerRewardState
		{
			/// <summary>
			/// The reward sets the player is currently choosing from.
			/// Players can have multiple rewards screens up because relics, when taken from a rewards screen, may themselves
			/// spawn new rewards screens. This acts like a stack.
			/// </summary>
			public required List<RewardsSetState> rewardsStack;

			/// <summary>
			/// If messages are received for a reward before it is started locally, then they will be buffered here until
			/// the reward set is spawned.
			/// </summary>
			public required List<BufferedMessage> bufferedMessages;

			/// <summary>
			/// Completed reward IDs, for bookkeeping purposes.
			/// </summary>
			public readonly System.Collections.Generic.Dictionary<int, RewardSetCompleteState> completedRewards = new System.Collections.Generic.Dictionary<int, RewardSetCompleteState>();

			/// <summary>
			/// The next ID to assign the rewards set for the given player.
			/// </summary>
			public int nextId;
		}

		/// <summary>
		/// State of a single reward set.
		/// </summary>
		private class RewardsSetState
		{
			/// <summary>
			/// The set of rewards.
			/// </summary>
			public required RewardsSet set;

			/// <summary>
			/// The completion source to complete when the rewards are all taken, or when they are skipped.
			/// </summary>
			public required TaskCompletionSource completionSource;
		}

		private readonly RunLocationTargetedMessageBuffer _messageBuffer;

		private readonly INetGameService _netService;

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("RewardsSetSynchronizer", LogType.GameSync);

		/// <summary>
		/// Reward state for each player.
		/// There is one for each player in _playerCollection, in the same order.
		/// </summary>
		private readonly List<PlayerRewardState> _rewardStates = new List<PlayerRewardState>();

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		/// <summary>
		/// Called when we skip all rewards just before leaving the room.
		/// </summary>
		public event Action? RewardsSkippedDuringRoomExit;

		public RewardsSetSynchronizer(RunLocationTargetedMessageBuffer messageBuffer, INetGameService netService, IPlayerCollection playerCollection, ulong localPlayerId)
		{
			_netService = netService;
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			for (int i = 0; i < playerCollection.Players.Count; i++)
			{
				_rewardStates.Add(new PlayerRewardState
				{
					rewardsStack = new List<RewardsSetState>(),
					bufferedMessages = new List<BufferedMessage>()
				});
			}
			_messageBuffer = messageBuffer;
			_messageBuffer.RegisterMessageHandler<RewardSelectedMessage>(HandleRewardSelectedMessage);
			_messageBuffer.RegisterMessageHandler<RewardSetSkippedMessage>(HandleRewardSetSkippedMessage);
		}

		public void Dispose()
		{
			_messageBuffer.UnregisterMessageHandler<RewardSelectedMessage>(HandleRewardSelectedMessage);
			_messageBuffer.UnregisterMessageHandler<RewardSetSkippedMessage>(HandleRewardSetSkippedMessage);
		}

		private PlayerRewardState GetRewardStateForPlayer(Player player)
		{
			for (int i = _rewardStates.Count; i <= _playerCollection.GetPlayerSlotIndex(player); i++)
			{
				_rewardStates.Add(new PlayerRewardState
				{
					rewardsStack = new List<RewardsSetState>(),
					bufferedMessages = new List<BufferedMessage>()
				});
			}
			return _rewardStates[_playerCollection.GetPlayerSlotIndex(player)];
		}

		/// <summary>
		/// Begin tracking a rewards set.
		/// This is called when a reward set is spawned and offered to the owning player.
		/// </summary>
		/// <param name="set">The rewards set to track.</param>
		/// <returns>A Task which completes when the player is done taking the rewards.</returns>
		public Task BeginRewardsSet(RewardsSet set)
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(set.Player);
			set.Id = rewardStateForPlayer.nextId;
			rewardStateForPlayer.nextId++;
			_logger.Debug($"Beginning rewards set {set}");
			TaskCompletionSource taskCompletionSource = new TaskCompletionSource();
			RewardsSetState rewardsSetState = new RewardsSetState
			{
				set = set,
				completionSource = taskCompletionSource
			};
			rewardStateForPlayer.rewardsStack.Add(rewardsSetState);
			foreach (BufferedMessage item in rewardStateForPlayer.bufferedMessages.ToList())
			{
				if (set.Id == item.SetId)
				{
					if (item.selectedMessage != null)
					{
						_logger.Debug("Handling buffered RewardSelectedMessage");
						HandleRewardSelectedMessage(item.selectedMessage, item.senderId);
					}
					else if (item.skippedMessage != null)
					{
						_logger.Debug("Handling buffered RewardSetSkippedMessage");
						HandleRewardSetSkippedMessage(item.skippedMessage, item.senderId);
					}
					rewardStateForPlayer.bufferedMessages.Remove(item);
				}
			}
			CompleteRewardsSetIfNecessary(rewardsSetState);
			return taskCompletionSource.Task;
		}

		/// <summary>
		/// Selects a reward locally.
		/// Throws if the reward is not owned by the local player.
		/// </summary>
		/// <param name="reward">The reward to select.</param>
		/// <returns>A Task which completes when the player finishes with the reward. See <see cref="M:MegaCrit.Sts2.Core.Rewards.Reward.SelectUnsynchronized" />.</returns>
		public async Task<bool> SelectLocalReward(Reward reward)
		{
			if (reward.Player != LocalPlayer)
			{
				throw new InvalidOperationException($"{"SelectLocalReward"} called for reward {reward} with non-local player {reward.Player.NetId}! This is not allowed");
			}
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(LocalPlayer);
			if (rewardStateForPlayer.rewardsStack.Count <= 0)
			{
				throw new InvalidOperationException("Tried to sync reward for local player, but they are not currently viewing any reward set!");
			}
			RewardsSetState rewardsSetState = rewardStateForPlayer.rewardsStack.Last();
			RewardsSet set = rewardsSetState.set;
			int rewardIndex = set.Rewards.IndexOf(reward);
			RewardSelectedMessage message = new RewardSelectedMessage
			{
				location = _messageBuffer.CurrentLocation,
				setId = rewardsSetState.set.Id,
				rewardIndex = rewardIndex
			};
			_netService.SendMessage(message);
			return await SelectRewardForPlayer(rewardsSetState, reward);
		}

		/// <summary>
		/// Skips the current rewards that the local player is looking at.
		/// </summary>
		public void SkipLocalRewardsSet()
		{
			_logger.Debug("Skipping local RewardsSet");
			RewardsSetState rewardsSetState = SkipRewardsSetOnStackTopForPlayer(LocalPlayer);
			RewardSetSkippedMessage message = new RewardSetSkippedMessage
			{
				location = _messageBuffer.CurrentLocation,
				setId = rewardsSetState.set.Id
			};
			_netService.SendMessage(message);
		}

		/// <summary>
		/// Called when a remote player selects a reward.
		/// </summary>
		public void HandleRewardSelectedMessage(RewardSelectedMessage message, ulong senderId)
		{
			_logger.Debug($"Received {"RewardSelectedMessage"} from player {senderId}, set id: {message.setId} reward index: {message.rewardIndex}");
			Player player = _playerCollection.GetPlayer(senderId);
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(player);
			if (rewardStateForPlayer.nextId <= message.setId)
			{
				_logger.Debug($"Buffering {"RewardSelectedMessage"} because RewardsSet id {message.setId} hasn't been created yet");
				rewardStateForPlayer.bufferedMessages.Add(new BufferedMessage
				{
					selectedMessage = message,
					senderId = senderId
				});
			}
			else
			{
				TaskHelper.RunSafely(SelectRewardForPlayer(player, message.rewardIndex));
			}
		}

		/// <summary>
		/// Called when a remote player skips the remaining the rewards in a set.
		/// Occurs both when leaving a room as a result of <see cref="M:MegaCrit.Sts2.Core.Multiplayer.Game.RewardsSetSynchronizer.BeforeLeavingRoom" /> and pressing the skip button on
		/// non-terminal rewards.
		/// </summary>
		public void HandleRewardSetSkippedMessage(RewardSetSkippedMessage message, ulong senderId)
		{
			_logger.Debug($"Received {"RewardSetSkippedMessage"} from player {senderId}, set id: {message.setId}");
			Player player = _playerCollection.GetPlayer(senderId);
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(player);
			if (rewardStateForPlayer.nextId <= message.setId)
			{
				_logger.Debug($"Buffering {"RewardSetSkippedMessage"} because RewardsSet id {message.setId} hasn't been created yet");
				rewardStateForPlayer.bufferedMessages.Add(new BufferedMessage
				{
					skippedMessage = message,
					senderId = senderId
				});
			}
			else
			{
				SkipRewardsSetOnStackTopForPlayer(_playerCollection.GetPlayer(senderId));
			}
		}

		/// <summary>
		/// Selects the reward at the specified index for the given player's top-most rewards screen.
		/// </summary>
		private async Task SelectRewardForPlayer(Player player, int rewardIndex)
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(player);
			if (rewardStateForPlayer.rewardsStack.Count <= 0)
			{
				throw new InvalidOperationException($"Tried to select reward for player {player.NetId}, but they are not currently viewing any reward set!");
			}
			RewardsSetState rewardsSetState = rewardStateForPlayer.rewardsStack.Last();
			RewardsSet set = rewardsSetState.set;
			if (rewardIndex < 0 || rewardIndex >= set.Rewards.Count)
			{
				throw new InvalidOperationException($"Tried to select reward index {rewardIndex} for player {player.NetId}, but it is out of bounds in their current rewards set {set}!");
			}
			Reward reward = set.Rewards[rewardIndex];
			await SelectRewardForPlayer(rewardsSetState, reward);
		}

		/// <summary>
		/// Selects the passed reward for the given reward set.
		/// Takes care of completing the reward set if all rewards have been obtained.
		/// </summary>
		private async Task<bool> SelectRewardForPlayer(RewardsSetState setState, Reward reward)
		{
			_logger.Debug($"Selecting reward {reward} for player {reward.Player.NetId}");
			bool result = await reward.SelectUnsynchronized();
			CompleteRewardsSetIfNecessary(setState);
			return result;
		}

		/// <summary>
		/// If all rewards in the passed state are successfully complete, then the set is marked as complete.
		/// </summary>
		private void CompleteRewardsSetIfNecessary(RewardsSetState setState)
		{
			if (setState.set.AllRewardsSuccessfullySelected)
			{
				CompleteRewardsSet(setState, RewardSetCompleteState.Completed);
			}
		}

		/// <summary>
		/// Skips all rewards in reward set on the top of the stack for the given player, completing the reward set.
		/// </summary>
		private RewardsSetState SkipRewardsSetOnStackTopForPlayer(Player player)
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(player);
			if (rewardStateForPlayer.rewardsStack.Count <= 0)
			{
				throw new InvalidOperationException($"Tried to skip reward set for player {player.NetId}, but they are not currently viewing any reward set!");
			}
			List<RewardsSetState> rewardsStack = rewardStateForPlayer.rewardsStack;
			RewardsSetState rewardsSetState = rewardsStack[rewardsStack.Count - 1];
			SkipRewardsSet(rewardsSetState);
			return rewardsSetState;
		}

		/// <summary>
		/// Skips all rewards in the passed reward set, completing the reward set.
		/// </summary>
		private void SkipRewardsSet(RewardsSetState setState)
		{
			foreach (Reward reward in setState.set.Rewards)
			{
				if (!reward.SuccessfullySelected)
				{
					reward.OnSkipped();
				}
			}
			CompleteRewardsSet(setState, RewardSetCompleteState.Skipped);
		}

		/// <summary>
		/// Marks a rewards set as complete (or skipped), popping it off the owning player's stack.
		/// </summary>
		private void CompleteRewardsSet(RewardsSetState setState, RewardSetCompleteState completeState)
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(setState.set.Player);
			if (IsRewardsSetCompleted(setState.set))
			{
				_logger.Error($"Reward set with id {setState.set} is already finished (state {rewardStateForPlayer.completedRewards[setState.set.Id]})!");
			}
			else
			{
				rewardStateForPlayer.rewardsStack.Remove(setState);
				rewardStateForPlayer.completedRewards[setState.set.Id] = completeState;
				setState.completionSource.SetResult();
				_logger.Debug($"Reward set {setState.set} completed with state: {completeState}");
			}
		}

		/// <summary>
		/// Returns true if the passed reward set has been completed.
		/// </summary>
		public bool IsRewardsSetCompleted(RewardsSet set)
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(set.Player);
			if (set.Id < 0)
			{
				return false;
			}
			return rewardStateForPlayer.completedRewards.ContainsKey(set.Id);
		}

		/// <summary>
		/// Returns true if the passed reward set ID has been completed for the given player.
		/// </summary>
		public bool IsRewardsSetCompleted(Player player, int id)
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(player);
			return rewardStateForPlayer.completedRewards.ContainsKey(id);
		}

		/// <summary>
		/// Skips all remaining rewards for the local player.
		/// </summary>
		public void BeforeLeavingRoom()
		{
			PlayerRewardState rewardStateForPlayer = GetRewardStateForPlayer(LocalPlayer);
			if (rewardStateForPlayer.rewardsStack.Count > 0)
			{
				_logger.Debug($"Skipping remaining rewards for local player {LocalPlayer.NetId} because we're exiting the room");
			}
			for (int num = rewardStateForPlayer.rewardsStack.Count - 1; num >= 0; num--)
			{
				RewardsSetState rewardsSetState = rewardStateForPlayer.rewardsStack[num];
				SkipRewardsSet(rewardStateForPlayer.rewardsStack[num]);
				RewardSetSkippedMessage message = new RewardSetSkippedMessage
				{
					location = _messageBuffer.CurrentLocation,
					setId = rewardsSetState.set.Id
				};
				_netService.SendMessage(message);
			}
			rewardStateForPlayer.rewardsStack.Clear();
			RewardsSkippedDuringRoomExit?.Invoke();
		}

		/// <summary>
		/// Gets all the next reward IDs in player slot order.
		/// </summary>
		public IEnumerable<int> GetNextRewardIds()
		{
			foreach (PlayerRewardState rewardState in _rewardStates)
			{
				yield return rewardState.nextId;
			}
		}

		public void FastForwardRewardIds(List<int> rewardIds)
		{
			for (int i = 0; i < rewardIds.Count; i++)
			{
				_logger.Debug($"Fast-forwarded reward set ID for {i} to {rewardIds[i]}");
				_rewardStates[i].nextId = rewardIds[i];
			}
		}
	}
	/// <summary>
	/// Temporary synchronizer that tells other players about rewards that a player receives in non-deterministic contexts
	/// Currently only used at the merchant.
	/// </summary>
	public class RewardSynchronizer : IDisposable
	{
		private struct BufferedMessage
		{
			public ulong senderId;

			public RewardObtainedMessage? rewardMessage;

			public GoldLostMessage? goldLostMessage;

			public CardRemovedMessage? cardRemovedMessage;
		}

		private readonly RunLocationTargetedMessageBuffer _messageBuffer;

		private readonly INetGameService _gameService;

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private readonly List<BufferedMessage> _bufferedMessages = new List<BufferedMessage>();

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		public RewardSynchronizer(RunLocationTargetedMessageBuffer messageBuffer, INetGameService gameService, IPlayerCollection playerCollection, ulong localPlayerId)
		{
			_gameService = gameService;
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			_messageBuffer = messageBuffer;
			_messageBuffer.RegisterMessageHandler<RewardObtainedMessage>(HandleRewardObtainedMessage);
			_messageBuffer.RegisterMessageHandler<GoldLostMessage>(HandleGoldLostMessage);
			_messageBuffer.RegisterMessageHandler<CardRemovedMessage>(HandleCardRemovedMessage);
			CombatManager.Instance.CombatEnded += OnCombatEnded;
		}

		public void Dispose()
		{
			_messageBuffer.UnregisterMessageHandler<RewardObtainedMessage>(HandleRewardObtainedMessage);
			_messageBuffer.UnregisterMessageHandler<GoldLostMessage>(HandleGoldLostMessage);
			_messageBuffer.UnregisterMessageHandler<CardRemovedMessage>(HandleCardRemovedMessage);
			CombatManager.Instance.CombatEnded -= OnCombatEnded;
		}

		public void SyncLocalObtainedCard(CardModel card)
		{
			SyncLocalCardEvent(card, skipped: false);
		}

		public void SyncLocalSkippedCard(CardModel card)
		{
			SyncLocalCardEvent(card, skipped: true);
		}

		private void SyncLocalCardEvent(CardModel card, bool skipped)
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer && CombatManager.Instance.IsInProgress)
			{
				throw new InvalidOperationException($"Tried to sync card event {card} during combat! This is not allowed");
			}
			RewardObtainedMessage message = new RewardObtainedMessage
			{
				rewardType = RewardType.Card,
				cardModel = card,
				wasSkipped = skipped,
				location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
		}

		public void SyncLocalObtainedRelic(RelicModel relic)
		{
			SyncLocalRelicEvent(relic, skipped: false);
		}

		public void SyncLocalSkippedRelic(RelicModel relic)
		{
			SyncLocalRelicEvent(relic, skipped: true);
		}

		private void SyncLocalRelicEvent(RelicModel relic, bool skipped)
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer && CombatManager.Instance.IsInProgress)
			{
				throw new InvalidOperationException($"Tried to sync relic event {relic} during combat! This is not allowed");
			}
			RewardObtainedMessage message = new RewardObtainedMessage
			{
				rewardType = RewardType.Relic,
				relicModel = relic,
				wasSkipped = skipped,
				location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
		}

		public void SyncLocalObtainedPotion(PotionModel potion)
		{
			SyncLocalPotionEvent(potion, skipped: false);
		}

		public void SyncLocalSkippedPotion(PotionModel potion)
		{
			SyncLocalPotionEvent(potion, skipped: true);
		}

		private void SyncLocalPotionEvent(PotionModel potion, bool skipped)
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer && CombatManager.Instance.IsInProgress)
			{
				throw new InvalidOperationException($"Tried to sync potion event {potion} during combat! This is not allowed");
			}
			RewardObtainedMessage message = new RewardObtainedMessage
			{
				rewardType = RewardType.Potion,
				potionModel = potion,
				wasSkipped = skipped,
				location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
		}

		public void SyncLocalObtainedGold(int goldAmount)
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer && CombatManager.Instance.IsInProgress)
			{
				throw new InvalidOperationException($"Tried to sync obtaining {goldAmount} gold during combat! This is not allowed");
			}
			RewardObtainedMessage message = new RewardObtainedMessage
			{
				rewardType = RewardType.Gold,
				goldAmount = goldAmount,
				wasSkipped = false,
				location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
		}

		public void SyncLocalGoldLost(int goldLost)
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer && CombatManager.Instance.IsInProgress)
			{
				throw new InvalidOperationException($"Tried to sync losing {goldLost} gold during combat! This is not allowed");
			}
			GoldLostMessage message = new GoldLostMessage
			{
				goldLost = goldLost,
				location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
		}

		public async Task<bool> DoLocalCardRemoval()
		{
			CardRemovedMessage message = new CardRemovedMessage
			{
				Location = _messageBuffer.CurrentLocation
			};
			_gameService.SendMessage(message);
			return await DoUnsyncedCardRemoval(LocalPlayer);
		}

		private void HandleRewardObtainedMessage(RewardObtainedMessage message, ulong senderId)
		{
			if (CombatManager.Instance.IsInProgress)
			{
				BufferedMessage item = new BufferedMessage
				{
					senderId = senderId,
					rewardMessage = message
				};
				_bufferedMessages.Add(item);
				return;
			}
			Player player = _playerCollection.GetPlayer(senderId);
			MapPointHistoryEntry historyEntryFor = player.RunState.GetHistoryEntryFor(message.location.mapLocation);
			PlayerMapPointHistoryEntry playerMapPointHistoryEntry = null;
			if (historyEntryFor != null)
			{
				playerMapPointHistoryEntry = historyEntryFor.GetEntry(player.NetId);
			}
			switch (message.rewardType)
			{
			case RewardType.Card:
			{
				CardModel cardModel = message.cardModel;
				if (!message.wasSkipped)
				{
					player.RunState.AddCard(cardModel, player);
					TaskHelper.RunSafely(CardPileCmd.Add(cardModel, PileType.Deck));
					Log.Debug($"Player {player.NetId} obtained {cardModel.Id} from card reward");
				}
				else
				{
					Log.Debug($"Player {player.NetId} skipped {cardModel.Id} from card reward");
				}
				playerMapPointHistoryEntry?.CardChoices.Add(new CardChoiceHistoryEntry(message.cardModel, !message.wasSkipped));
				break;
			}
			case RewardType.Gold:
				if (message.wasSkipped)
				{
					throw new NotImplementedException("Cannot handle skip gold reward message!");
				}
				TaskHelper.RunSafely(PlayerCmd.GainGold(message.goldAmount.Value, player));
				Log.Debug($"Player {player.NetId} obtained {message.goldAmount} gold from gold reward");
				break;
			case RewardType.Potion:
				if (!message.wasSkipped)
				{
					TaskHelper.RunSafely(PotionCmd.TryToProcure(message.potionModel.ToMutable(), player));
					Log.Debug($"Player {player.NetId} obtained {message.potionModel?.Id} from potion reward");
				}
				else
				{
					Log.Debug($"Player {player.NetId} skipped {message.potionModel?.Id} from potion reward");
					playerMapPointHistoryEntry?.PotionChoices.Add(new ModelChoiceHistoryEntry(message.potionModel.Id, !message.wasSkipped));
				}
				break;
			case RewardType.Relic:
				if (!message.wasSkipped)
				{
					TaskHelper.RunSafely(RelicCmd.Obtain(message.relicModel, player));
					Log.Debug($"Player {player.NetId} obtained {message.relicModel?.Id} from relic reward");
				}
				else
				{
					Log.Debug($"Player {player.NetId} skipped {message.relicModel?.Id} from relic reward");
					playerMapPointHistoryEntry?.RelicChoices.Add(new ModelChoiceHistoryEntry(message.relicModel.Id, !message.wasSkipped));
				}
				break;
			default:
				throw new ArgumentOutOfRangeException("rewardType", message.rewardType, null);
			}
		}

		private void HandleGoldLostMessage(GoldLostMessage message, ulong senderId)
		{
			if (CombatManager.Instance.IsInProgress)
			{
				BufferedMessage item = new BufferedMessage
				{
					senderId = senderId,
					goldLostMessage = message
				};
				_bufferedMessages.Add(item);
				return;
			}
			Player player = _playerCollection.GetPlayer(senderId);
			TaskHelper.RunSafely(PlayerCmd.LoseGold(message.goldLost, player));
			Log.Debug($"Player {player.NetId} lost {message.goldLost} gold");
		}

		private void HandleCardRemovedMessage(CardRemovedMessage message, ulong senderId)
		{
			if (CombatManager.Instance.IsInProgress)
			{
				BufferedMessage item = new BufferedMessage
				{
					senderId = senderId,
					cardRemovedMessage = message
				};
				_bufferedMessages.Add(item);
				return;
			}
			Player player = _playerCollection.GetPlayer(senderId);
			if (player == LocalPlayer)
			{
				throw new InvalidOperationException("CardRemovedMessage should not be sent to the player removing the card!");
			}
			TaskHelper.RunSafely(DoUnsyncedCardRemoval(player));
		}

		private void OnCombatEnded(CombatRoom _)
		{
			foreach (BufferedMessage bufferedMessage in _bufferedMessages)
			{
				if (bufferedMessage.rewardMessage.HasValue)
				{
					HandleRewardObtainedMessage(bufferedMessage.rewardMessage.Value, bufferedMessage.senderId);
				}
				else if (bufferedMessage.goldLostMessage.HasValue)
				{
					HandleGoldLostMessage(bufferedMessage.goldLostMessage.Value, bufferedMessage.senderId);
				}
				else if (bufferedMessage.cardRemovedMessage != null)
				{
					HandleCardRemovedMessage(bufferedMessage.cardRemovedMessage, bufferedMessage.senderId);
				}
			}
			_bufferedMessages.Clear();
		}

		/// <summary>
		/// Does card removal for the given player WITHOUT syncing it.
		/// This is a temporary bridge method for things that already execute deterministically (card removal rewards) and
		/// things that don't (merchant card removal).
		/// </summary>
		public async Task<bool> DoUnsyncedCardRemoval(Player player)
		{
			CardSelectorPrefs prefs = new CardSelectorPrefs(new LocString("gameplay_ui", "COMBAT_REWARD_CARD_REMOVAL.selectionScreenPrompt"), 1)
			{
				Cancelable = true,
				RequireManualConfirmation = true
			};
			CardModel card = (await CardSelectCmd.FromDeckForRemoval(player, prefs)).FirstOrDefault();
			if (card != null)
			{
				await CardPileCmd.RemoveFromDeck(card);
				Log.Debug($"Player {player.NetId} removed {card.Id} from deck");
				return true;
			}
			return false;
		}
	}
	/// <summary>
	/// Responsible for holding messages that are not destined for the current map point, and waiting until that map point
	/// is entered before processing those messages.
	/// We may be slow to transition to a new map point (e.g. because of loading delays), and messages from other peers may
	/// come in before we're ready to receive them.
	/// Note that it is important that queued messages are sent out in the order that they were received.
	/// </summary>
	public class RunLocationTargetedMessageBuffer
	{
		private delegate void AnonymizedMessageHandlerDelegate(INetMessage message, ulong senderId);

		private struct TypeAndMessageHandlers
		{
			public Type messageType;

			public object netServiceHandler;

			public List<MessageHandler> handlers;
		}

		private struct MessageHandler
		{
			public object originalHandler;

			public AnonymizedMessageHandlerDelegate anonymizedHandler;
		}

		private struct BlockedMessage
		{
			public RunLocation location;

			public INetMessage message;

			public ulong senderId;

			public Type messageType;
		}

		private readonly INetGameService _gameService;

		private readonly List<BlockedMessage> _messagesWaitingOnLocationChange = new List<BlockedMessage>();

		private readonly List<TypeAndMessageHandlers> _messageHandlers = new List<TypeAndMessageHandlers>();

		private readonly HashSet<RunLocation> _visitedLocations = new HashSet<RunLocation>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("RunLocationTargetedMessageBuffer", LogType.GameSync);

		public RunLocation CurrentLocation { get; private set; }

		public RunLocationTargetedMessageBuffer(INetGameService gameService)
		{
			_gameService = gameService;
			_visitedLocations.Add(CurrentLocation);
		}

		/// <summary>
		/// This should be called whenever the run location changes. If messages are blocked waiting for a location change,
		/// then they will be sent to registered message handlers in the order that they were received.
		/// </summary>
		public void OnLocationChanged(RunLocation location)
		{
			_logger.Debug($"Run location changed to {location} (previously at: {CurrentLocation}), checking if we have enqueued messages");
			CurrentLocation = location;
			_visitedLocations.Add(CurrentLocation);
			for (int i = 0; i < _messagesWaitingOnLocationChange.Count; i++)
			{
				BlockedMessage blockedMessage = _messagesWaitingOnLocationChange[i];
				if (_visitedLocations.Contains(blockedMessage.location))
				{
					_logger.Debug($"Handling enqueued message {blockedMessage.message} of type {blockedMessage.messageType} from {blockedMessage.senderId}");
					CallHandlersOfType(blockedMessage.messageType, blockedMessage.message, blockedMessage.senderId);
					_messagesWaitingOnLocationChange.RemoveAt(i);
					i--;
				}
			}
			if (_messagesWaitingOnLocationChange.Count > 0)
			{
				_logger.Error($"After transitioning to {location}, there are still {_messagesWaitingOnLocationChange.Count} messages for other locations. This is likely indicates a bug. Messages:\n{string.Join("\n", _messagesWaitingOnLocationChange)}");
			}
		}

		private void CallHandlersOfType(Type type, INetMessage message, ulong senderId)
		{
			foreach (TypeAndMessageHandlers messageHandler in _messageHandlers)
			{
				if (!(messageHandler.messageType == type))
				{
					continue;
				}
				foreach (MessageHandler handler in messageHandler.handlers)
				{
					handler.anonymizedHandler(message, senderId);
				}
			}
		}

		/// <summary>
		/// Registers a message handler for map targeted messages.
		/// <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Messages.Game.IRunLocationTargetedMessage" />s should be registered here instead of directly to the INetGameHandler; otherwise,
		/// they may be received at the wrong time.
		/// </summary>
		/// <param name="handler">
		/// The delegate to call when the message type is received or when we enter a new location and a message for that
		/// location is enqueued.
		/// </param>
		public void RegisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage, IRunLocationTargetedMessage
		{
			_logger.VeryDebug($"Register message handler {handler} for {typeof(T)}");
			TypeAndMessageHandlers? typeAndMessageHandlers = null;
			foreach (TypeAndMessageHandlers messageHandler in _messageHandlers)
			{
				if (messageHandler.messageType == typeof(T))
				{
					typeAndMessageHandlers = messageHandler;
				}
			}
			if (!typeAndMessageHandlers.HasValue)
			{
				MessageHandlerDelegate<T> messageHandlerDelegate = HandleMessage;
				typeAndMessageHandlers = new TypeAndMessageHandlers
				{
					messageType = typeof(T),
					netServiceHandler = messageHandlerDelegate,
					handlers = new List<MessageHandler>()
				};
				_gameService.RegisterMessageHandler(messageHandlerDelegate);
				_messageHandlers.Add(typeAndMessageHandlers.Value);
			}
			typeAndMessageHandlers.Value.handlers.Add(new MessageHandler
			{
				anonymizedHandler = AnonymousDelegate,
				originalHandler = handler
			});
			void AnonymousDelegate(INetMessage message, ulong senderId)
			{
				handler((T)message, senderId);
			}
		}

		/// <summary>
		/// Unregisters a message handler for map targeted messages.
		/// </summary>
		public void UnregisterMessageHandler<T>(MessageHandlerDelegate<T> handler) where T : INetMessage, IRunLocationTargetedMessage
		{
			for (int i = 0; i < _messageHandlers.Count; i++)
			{
				TypeAndMessageHandlers typeAndMessageHandlers = _messageHandlers[i];
				if (typeAndMessageHandlers.messageType != typeof(T))
				{
					continue;
				}
				for (int j = 0; j < typeAndMessageHandlers.handlers.Count; j++)
				{
					if (typeAndMessageHandlers.handlers[j].originalHandler is MessageHandlerDelegate<T> messageHandlerDelegate && (Delegate?)messageHandlerDelegate == (Delegate?)handler)
					{
						typeAndMessageHandlers.handlers.RemoveAt(j);
						j--;
					}
				}
				if (typeAndMessageHandlers.handlers.Count <= 0)
				{
					_gameService.UnregisterMessageHandler((MessageHandlerDelegate<T>)typeAndMessageHandlers.netServiceHandler);
					_messageHandlers.RemoveAt(i);
					i--;
				}
			}
		}

		/// <summary>
		/// Internal method which either sends the message to the handler, or enqueues it if the message is not destined
		/// for a location we have already visited.
		/// </summary>
		private void HandleMessage<T>(T message, ulong senderId) where T : INetMessage, IRunLocationTargetedMessage
		{
			_logger.VeryDebug($"Handling map-targeted message {message} from {senderId} for location {message.Location}");
			if (_visitedLocations.Contains(message.Location))
			{
				CallHandlersOfType(typeof(T), message, senderId);
				return;
			}
			_logger.Debug($"Message {message} from {senderId} is for location {message.Location}, enqueueing it because we are currently at location {CurrentLocation}");
			BlockedMessage item = new BlockedMessage
			{
				location = message.Location,
				message = message,
				messageType = message.GetType(),
				senderId = senderId
			};
			_messagesWaitingOnLocationChange.Add(item);
		}
	}
	public class StateDivergenceException : Exception
	{
		public StateDivergenceException(string message)
			: base(message)
		{
		}
	}
	/// <summary>
	/// Synchronizes treasure room shared relic picking in multiplayer.
	/// After opening the treasure chest, players are presented with multiple relics. They may vote on any one of the relics
	/// to take. After all players cast a vote:
	/// - If only one player votes for a relic, then that player gets the relic.
	/// - If multiple players have voted for a relic, they play rock-paper-scissors. The winning player gets the relic.
	/// - If no one has voted for a relic, a random loser of a rock-paper-scissors game gets the relic.
	/// </summary>
	public class TreasureRoomRelicSynchronizer
	{
		public class PlayerVote
		{
			/// <summary>
			/// Index of relic voted on. If null, then player skipped.
			/// </summary>
			public int? index;

			/// <summary>
			/// If true, then the player has voted. False if the player has not yet picked an option.
			/// </summary>
			public bool voteReceived;
		}

		private readonly IPlayerCollection _playerCollection;

		private readonly ulong _localPlayerId;

		private readonly RelicGrabBag _sharedGrabBag;

		private readonly ActionQueueSynchronizer _actionQueueSynchronizer;

		private readonly Rng _rng;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("TreasureRoomRelicSynchronizer", LogType.GameSync);

		private List<RelicModel>? _currentRelics;

		private readonly List<PlayerVote> _votes = new List<PlayerVote>();

		private PlayerVote? _predictedVote;

		/// <summary>
		/// Set to true if the player skips the relic in singleplayer.
		/// </summary>
		private bool _singleplayerSkipped;

		public IReadOnlyList<RelicModel>? CurrentRelics => _currentRelics;

		private Player LocalPlayer => _playerCollection.GetPlayer(_localPlayerId);

		public event Action? VotesChanged;

		public event Action<List<RelicPickingResult>>? RelicsAwarded;

		public TreasureRoomRelicSynchronizer(IPlayerCollection playerCollection, ulong localPlayerId, ActionQueueSynchronizer actionQueueSynchronizer, RelicGrabBag sharedGrabBag, Rng rng)
		{
			_playerCollection = playerCollection;
			_localPlayerId = localPlayerId;
			_actionQueueSynchronizer = actionQueueSynchronizer;
			_sharedGrabBag = sharedGrabBag;
			_rng = rng;
		}

		/// <summary>
		/// Call this when the treasure room is opened to generate the relics that are selected.
		/// CurrentRelics will be null until this is called.
		/// </summary>
		public void BeginRelicPicking()
		{
			if (CurrentRelics != null)
			{
				throw new InvalidOperationException("Attempted to start new relic picking session while one was already occurring!");
			}
			_currentRelics = new List<RelicModel>();
			_votes.Clear();
			_predictedVote = null;
			foreach (Player player in _playerCollection.Players)
			{
				_votes.Add(new PlayerVote
				{
					voteReceived = false
				});
				IRunState runState = player.RunState;
				if (Hook.ShouldGenerateTreasure(runState, player))
				{
					RelicRarity rarity = RelicFactory.RollRarity(_rng);
					RelicModel item = TryGetRelicForTutorial(player) ?? _sharedGrabBag.PullFromFront(rarity, runState) ?? RelicFactory.FallbackRelic;
					_currentRelics.Add(item);
				}
			}
			if (_currentRelics.Count > 0)
			{
				if (RunManager.Instance.IsSingleplayerOrFakeMultiplayer && _playerCollection.Players.Count > 1)
				{
					foreach (Player player2 in _playerCollection.Players)
					{
						if (player2 != LocalPlayer)
						{
							PlayerVote playerVote = _votes[_playerCollection.GetPlayerSlotIndex(player2)];
							playerVote.index = _rng.NextInt(_currentRelics.Count);
							playerVote.voteReceived = true;
						}
					}
				}
				VotesChanged?.Invoke();
			}
			else
			{
				EndRelicVoting();
			}
		}

		/// <summary>
		/// Little semantic sugar which calls PickRelicLocally with null.
		/// </summary>
		public void SkipRelicLocally()
		{
			PickRelicLocally(null);
		}

		/// <summary>
		/// Called when the local player chooses a relic to vote for.
		/// Note that this immediately invokes `VotesChanged` with the new vote. However, the vote is not confirmed until
		/// the resulting action round-trips to the host.
		/// </summary>
		/// <param name="index">The index of the relic in CurrentRelics that the player voted for, or null if the player
		/// chose to skip.</param>
		public void PickRelicLocally(int? index)
		{
			if (index.HasValue)
			{
				_logger.Debug($"Relic index {index} ({_currentRelics?[index.Value]}) is being picked by local player {LocalPlayer.NetId}");
			}
			else
			{
				_logger.Debug($"Relic has been skipped by local player {LocalPlayer.NetId}");
			}
			if (_currentRelics == null)
			{
				_logger.Warn("Attempted to pick relic while relic picking is not active!");
				return;
			}
			_predictedVote = new PlayerVote
			{
				index = index,
				voteReceived = true
			};
			_actionQueueSynchronizer.RequestEnqueue(new PickRelicAction(LocalPlayer, index));
			VotesChanged?.Invoke();
		}

		/// <summary>
		/// Called when any player (local or remote) has voted for a relic.
		/// </summary>
		/// <param name="player">The player that voted.</param>
		/// <param name="index">The index of the relic in CurrentRelics that the player voted for.</param>
		public void OnPicked(Player player, int? index)
		{
			if (index.HasValue)
			{
				_logger.Debug($"Player {player} picked relic at index {index}: {_currentRelics?[index.Value]}");
			}
			else
			{
				_logger.Debug($"Player {player} skipped relic");
			}
			if (_currentRelics == null)
			{
				_logger.Warn("Attempted to pick relic while relic picking is not active!");
				return;
			}
			if (index >= _currentRelics.Count)
			{
				throw new IndexOutOfRangeException($"Attempted to pick relic at index {index}, but there are only {_currentRelics.Count} to choose from!");
			}
			if (!index.HasValue && _playerCollection.Players.Count == 1)
			{
				_singleplayerSkipped = true;
				return;
			}
			PlayerVote playerVote = _votes[_playerCollection.GetPlayerSlotIndex(player)];
			playerVote.index = index;
			playerVote.voteReceived = true;
			VotesChanged?.Invoke();
			if (!_votes.All((PlayerVote v) => v.voteReceived))
			{
				return;
			}
			if (_predictedVote != null)
			{
				PlayerVote predictedVote = _predictedVote;
				_predictedVote = null;
				if (_votes[_playerCollection.GetPlayerSlotIndex(LocalPlayer)].index != predictedVote.index)
				{
					VotesChanged?.Invoke();
				}
			}
			AwardRelics();
			EndRelicVoting();
		}

		private void AwardRelics()
		{
			System.Collections.Generic.Dictionary<int, List<Player>> dictionary = new System.Collections.Generic.Dictionary<int, List<Player>>();
			for (int i = 0; i < _currentRelics.Count; i++)
			{
				dictionary[i] = new List<Player>();
			}
			for (int j = 0; j < _votes.Count; j++)
			{
				Player item = _playerCollection.Players[j];
				PlayerVote playerVote = _votes[j];
				if (playerVote.index.HasValue)
				{
					List<Player> valueOrDefault = dictionary.GetValueOrDefault(playerVote.index.Value, new List<Player>());
					valueOrDefault.Add(item);
					dictionary[playerVote.index.Value] = valueOrDefault;
				}
			}
			List<RelicPickingResult> results = new List<RelicPickingResult>();
			List<RelicModel> list = new List<RelicModel>();
			foreach (KeyValuePair<int, List<Player>> item2 in dictionary)
			{
				RelicModel relicModel = _currentRelics[item2.Key];
				if (item2.Value.Count == 0)
				{
					list.Add(relicModel);
				}
				else if (item2.Value.Count == 1)
				{
					results.Add(new RelicPickingResult
					{
						type = RelicPickingResultType.OnlyOnePlayerVoted,
						relic = relicModel,
						player = item2.Value[0]
					});
				}
				else if (item2.Value.Count > 1)
				{
					RelicPickingFightMove[] possibleMoves = Enum.GetValues<RelicPickingFightMove>();
					results.Add(RelicPickingResult.GenerateRelicFight(item2.Value, relicModel, () => _rng.NextItem(possibleMoves)));
				}
			}
			List<Player> list2 = _playerCollection.Players.Where(delegate(Player p)
			{
				bool flag = results.Find((RelicPickingResult r) => r.player == p) != null;
				PlayerVote playerVote2 = _votes[_playerCollection.GetPlayerSlotIndex(p)];
				bool flag2 = playerVote2.voteReceived && !playerVote2.index.HasValue;
				return !flag && !flag2;
			}).ToList();
			list.StableShuffle(_rng);
			for (int num = 0; num < list.Count; num++)
			{
				if (num < list2.Count)
				{
					results.Add(new RelicPickingResult
					{
						type = RelicPickingResultType.ConsolationPrize,
						player = list2[num],
						relic = list[num]
					});
				}
				else
				{
					results.Add(new RelicPickingResult
					{
						type = RelicPickingResultType.Skipped,
						player = null,
						relic = list[num]
					});
				}
			}
			RelicsAwarded?.Invoke(results);
		}

		/// <summary>
		/// Called when the room is exited.
		/// Used to avoid emitting an error in the legitimate case where the player never completes relic picking in singleplayer.
		/// </summary>
		public void OnRoomExited()
		{
			if (_singleplayerSkipped)
			{
				EndRelicVoting();
			}
		}

		private void EndRelicVoting()
		{
			_currentRelics = null;
			_singleplayerSkipped = false;
		}

		/// <summary>
		/// Returns the relic that the player is currently voting for.
		/// If the player has not yet voted for a relic, then null is returned.
		/// </summary>
		public PlayerVote GetPlayerVote(Player player)
		{
			if (player == LocalPlayer && _predictedVote != null)
			{
				return _predictedVote;
			}
			return _votes[_playerCollection.GetPlayerSlotIndex(player)];
		}

		/// <summary>
		/// Completes relic picking immediately with no relics awarded.
		/// Called when the chest is empty (e.g., due to SilverCrucible).
		/// </summary>
		public void CompleteWithNoRelics()
		{
			_logger.Debug("Completing relic picking with no relics (empty chest)");
			RelicsAwarded?.Invoke(new List<RelicPickingResult>());
			_currentRelics = null;
		}

		/// <summary>
		/// If treasure room rarity should be forced because the player is currently playing a tutorial run, this returns
		/// a non-null rarity. Otherwise, the rarity is randomized.
		/// </summary>
		private RelicModel? TryGetRelicForTutorial(Player player)
		{
			if (_playerCollection.Players.Count == 1 && player.UnlockState.NumberOfRuns == 0 && player.RunState.MapPointHistory.SelectMany((IReadOnlyList<MapPointHistoryEntry> l) => l).Count((MapPointHistoryEntry p) => p.HasRoomOfType(RoomType.Treasure)) == 1 && player.RelicGrabBag.Contains(ModelDb.Relic<Gorget>()))
			{
				Log.Info("Forcing specific relic because it's the player's first treasure chest ever");
				player.RelicGrabBag.Remove<Gorget>();
				_sharedGrabBag.Remove<Gorget>();
				return ModelDb.Relic<Gorget>();
			}
			return null;
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Game.PeerInput
{
	/// <summary>
	/// A bundle of data that resolves to a model that a player is hovering.
	/// This intermediate structure is necessary because references to models may not yet be available at the time that we
	/// receive the hover data. For example:
	/// - Player 1 is in fast mode, plays Alchemize, and hovers the resulting potion
	/// - Player 2 is in slow mode, and is still in the middle of the enemy turn when player 1 hovers the potion
	/// </summary>
	public struct HoveredModelData : IPacketSerializable, IEquatable<HoveredModelData>
	{
		public HoveredModelType type;

		public NetCombatCard? hoveredCombatCard;

		public int? hoveredRelicIndex;

		public int? hoveredPotionIndex;

		public ModelId? hoveredModelId;

		public bool Equals(HoveredModelData other)
		{
			if (type == other.type)
			{
				NetCombatCard? netCombatCard = hoveredCombatCard;
				NetCombatCard? netCombatCard2 = other.hoveredCombatCard;
				if (netCombatCard.HasValue == netCombatCard2.HasValue && (!netCombatCard.HasValue || netCombatCard.GetValueOrDefault() == netCombatCard2.GetValueOrDefault()) && hoveredRelicIndex == other.hoveredRelicIndex && hoveredPotionIndex == other.hoveredPotionIndex)
				{
					return hoveredModelId == other.hoveredModelId;
				}
			}
			return false;
		}

		public static HoveredModelData FromModel(AbstractModel? model)
		{
			if (model == null)
			{
				return default(HoveredModelData);
			}
			HoveredModelData result = default(HoveredModelData);
			if (!(model is CardModel card))
			{
				if (!(model is RelicModel relicModel))
				{
					if (!(model is PotionModel potionModel))
					{
						throw new InvalidOperationException($"Model {model} has unsupported type for hovering");
					}
					result.type = HoveredModelType.Potion;
					result.hoveredPotionIndex = potionModel.Owner.GetPotionSlotIndex(potionModel);
				}
				else
				{
					result.type = HoveredModelType.Relic;
					result.hoveredRelicIndex = relicModel.Owner.Relics.IndexOf(relicModel);
				}
			}
			else
			{
				result.type = HoveredModelType.Card;
				result.hoveredCombatCard = NetCombatCard.FromModel(card);
			}
			result.hoveredModelId = model.Id;
			return result;
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteEnum(type);
			switch (type)
			{
			case HoveredModelType.Card:
				writer.Write(hoveredCombatCard.Value);
				break;
			case HoveredModelType.Relic:
				writer.WriteInt(hoveredRelicIndex.Value, 8);
				break;
			case HoveredModelType.Potion:
				writer.WriteInt(hoveredPotionIndex.Value, 4);
				break;
			}
			if (type != HoveredModelType.None)
			{
				writer.WriteModelEntry(hoveredModelId);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			type = reader.ReadEnum<HoveredModelType>();
			switch (type)
			{
			case HoveredModelType.Card:
				hoveredCombatCard = reader.Read<NetCombatCard>();
				hoveredModelId = reader.ReadModelIdAssumingType<CardModel>();
				break;
			case HoveredModelType.Relic:
				hoveredRelicIndex = reader.ReadInt(8);
				hoveredModelId = reader.ReadModelIdAssumingType<RelicModel>();
				break;
			case HoveredModelType.Potion:
				hoveredPotionIndex = reader.ReadInt(4);
				hoveredModelId = reader.ReadModelIdAssumingType<PotionModel>();
				break;
			}
		}

		public override string ToString()
		{
			return type switch
			{
				HoveredModelType.None => "HoveredModelData none", 
				HoveredModelType.Card => $"HoveredModelData {hoveredCombatCard}", 
				HoveredModelType.Relic => $"HoveredModelData relic index {hoveredRelicIndex}", 
				HoveredModelType.Potion => $"HoveredModelData potion index {hoveredPotionIndex}", 
				_ => throw new ArgumentOutOfRangeException(), 
			};
		}
	}
	/// <summary>
	/// Works with the PeerInputSynchronizer to synchronize the intent shown over the player's head during combat.
	/// Note that this doesn't do any message sending itself - PeerInputSynchronizer does the message sending and handling
	/// to reduce bandwidth. This is here only to separate out some of the state tracking from PeerInputSynchronizer.
	/// </summary>
	public class HoveredModelTracker
	{
		private readonly PeerInputSynchronizer _inputSynchronizer;

		private CardModel? _localSelectedCard;

		private PotionModel? _localSelectedPotion;

		private CardModel? _localHoveredCard;

		private RelicModel? _localHoveredRelic;

		private PotionModel? _localHoveredPotion;

		private readonly List<AbstractModel?> _hoveredModels = new List<AbstractModel>();

		private readonly IPlayerCollection _playerCollection;

		public event Action<ulong>? HoverChanged;

		public HoveredModelTracker(PeerInputSynchronizer inputSynchronizer, IPlayerCollection playerCollection)
		{
			_inputSynchronizer = inputSynchronizer;
			_playerCollection = playerCollection;
			foreach (Player player in playerCollection.Players)
			{
				_hoveredModels.Add(null);
			}
			_inputSynchronizer.StateChanged += OnPlayerStateChanged;
			_inputSynchronizer.StateRemoved += OnPlayerStateRemoved;
		}

		private void OnPlayerStateChanged(ulong playerId)
		{
			Player player = _playerCollection.GetPlayer(playerId);
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
			if (playerSlotIndex < _hoveredModels.Count)
			{
				HoveredModelData hoveredModelData = _inputSynchronizer.GetHoveredModelData(playerId);
				AbstractModel abstractModel = hoveredModelData.type switch
				{
					HoveredModelType.None => null, 
					HoveredModelType.Card => hoveredModelData.hoveredCombatCard?.ToCardModelOrNull(), 
					HoveredModelType.Relic => (hoveredModelData.hoveredRelicIndex < player.Relics.Count) ? player.Relics[hoveredModelData.hoveredRelicIndex.Value] : null, 
					HoveredModelType.Potion => (hoveredModelData.hoveredPotionIndex < player.PotionSlots.Count && hoveredModelData.hoveredPotionIndex >= 0) ? player.GetPotionAtSlotIndex(hoveredModelData.hoveredPotionIndex.Value) : null, 
					_ => throw new InvalidOperationException($"Unsupported hover type {hoveredModelData.type}"), 
				};
				if (abstractModel == null && hoveredModelData.type != HoveredModelType.None)
				{
					abstractModel = ModelDb.GetById<AbstractModel>(hoveredModelData.hoveredModelId);
				}
				AbstractModel abstractModel2 = _hoveredModels[playerSlotIndex];
				if (abstractModel2 != abstractModel)
				{
					_hoveredModels[playerSlotIndex] = abstractModel;
					HoverChanged?.Invoke(playerId);
				}
			}
		}

		private void OnPlayerStateRemoved(ulong playerId)
		{
			Player player = _playerCollection.GetPlayer(playerId);
			int playerSlotIndex = _playerCollection.GetPlayerSlotIndex(player);
			if (_hoveredModels[playerSlotIndex] != null)
			{
				_hoveredModels[playerSlotIndex] = null;
				HoverChanged?.Invoke(playerId);
			}
		}

		public AbstractModel? GetHoveredModel(ulong playerId)
		{
			return _hoveredModels[_playerCollection.GetPlayerSlotIndex(_playerCollection.GetPlayer(playerId))];
		}

		public void OnLocalCardSelected(CardModel cardModel)
		{
			_localSelectedCard = cardModel;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalCardDeselected()
		{
			_localSelectedCard = null;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalPotionSelected(PotionModel potionModel)
		{
			_localSelectedPotion = potionModel;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalPotionDeselected()
		{
			_localSelectedPotion = null;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalCardHovered(CardModel cardModel)
		{
			_localHoveredCard = cardModel;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalCardUnhovered()
		{
			_localHoveredCard = null;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalRelicHovered(RelicModel relicModel)
		{
			_localHoveredRelic = relicModel;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalRelicUnhovered()
		{
			_localHoveredRelic = null;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalPotionHovered(PotionModel potionModel)
		{
			_localHoveredPotion = potionModel;
			SynchronizeLocalHoveredModel();
		}

		public void OnLocalPotionUnhovered()
		{
			_localHoveredPotion = null;
			SynchronizeLocalHoveredModel();
		}

		private void SynchronizeLocalHoveredModel()
		{
			AbstractModel model = (AbstractModel)(_localSelectedCard ?? _localSelectedPotion ?? _localHoveredCard ?? ((object)_localHoveredPotion) ?? ((object)_localHoveredRelic));
			_inputSynchronizer.SyncLocalHoveredModel(model);
		}
	}
	public enum HoveredModelType
	{
		None,
		Card,
		Relic,
		Potion
	}
	public interface INetCursorPositionTranslator
	{
		Godot.Vector2 GetNetPositionFromScreenPosition(Godot.Vector2 screenPosition);

		Godot.Vector2 GetScreenPositionFromNetPosition(Godot.Vector2 netPosition);
	}
	public enum MapDrawingEventType
	{
		None,
		BeginLine,
		ContinueLine,
		EndLine
	}
	/// <summary>
	/// Utilities to help with transforming mouse position from screen coordinates to a normalized position suitable for
	/// syncing mouse positions across various aspect ratios.
	/// </summary>
	public static class NetCursorHelper
	{
		public static readonly QuantizeParams quantizeParams = new QuantizeParams(-3f, 3f, 16);

		public static Godot.Vector2 GetNormalizedPosition(Godot.Vector2 mouseScreenPos, Control? rootNode)
		{
			if (rootNode == null)
			{
				if (TestMode.IsOn)
				{
					return mouseScreenPos;
				}
				throw new InvalidOperationException("Root node should only be null in tests!");
			}
			Godot.Vector2 vector = rootNode.GetGlobalTransformWithCanvas() * mouseScreenPos;
			Godot.Vector2 vector2 = new Godot.Vector2(960f, 540f);
			return (vector - rootNode.Size / 2f) / vector2;
		}

		public static Godot.Vector2 GetControlSpacePosition(Godot.Vector2 normalizedCursorPosition, Control? rootNode)
		{
			if (rootNode == null)
			{
				if (TestMode.IsOn)
				{
					return normalizedCursorPosition;
				}
				throw new InvalidOperationException("Root node should only be null in tests!");
			}
			Godot.Vector2 vector = new Godot.Vector2(960f, 540f);
			return normalizedCursorPosition * vector + rootNode.Size / 2f;
		}
	}
	public struct NetMapDrawingEvent : IPacketSerializable
	{
		private static readonly QuantizeParams _quantizeParamsX = new QuantizeParams(-3f, 3f, 16);

		private static readonly QuantizeParams _quantizeParamsY = new QuantizeParams(-2f, 2f, 24);

		public MapDrawingEventType type;

		public DrawingMode? overrideDrawingMode;

		public Godot.Vector2 position;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteEnum(type);
			writer.WriteBool(overrideDrawingMode.HasValue);
			if (overrideDrawingMode.HasValue)
			{
				writer.WriteEnum(overrideDrawingMode.Value);
			}
			if (type != MapDrawingEventType.EndLine)
			{
				writer.WriteVector2(position, _quantizeParamsX, _quantizeParamsY);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			type = reader.ReadEnum<MapDrawingEventType>();
			if (reader.ReadBool())
			{
				overrideDrawingMode = reader.ReadEnum<DrawingMode>();
			}
			if (type != MapDrawingEventType.EndLine)
			{
				position = reader.ReadVector2(_quantizeParamsX, _quantizeParamsY);
			}
		}
	}
	/// <summary>
	/// Synchronizes our local mouse state with peers and remote peers' with ours.
	/// </summary>
	public class PeerInputSynchronizer : IDisposable
	{
		private class PeerInputState
		{
			/// <summary> The player to whom this state belongs. </summary>
			public ulong playerId;

			/// <summary> The mouse position of the player. </summary>
			public Godot.Vector2 netMousePosition;

			/// <summary> True if the player's mouse is held down, false otherwise. </summary>
			public bool isMouseDown;

			/// <summary> Which screen this player is looking at. </summary>
			public NetScreenType netScreenType;

			/// <summary> The combat model the player is hovering over. Should only be non-null in combat. </summary>
			public HoveredModelData hoveredModelData;

			/// <summary> True if the player is in combat and is currently in targeting mode (drawing the targeting arrow),
			/// false otherwise. </summary>
			public bool isTargeting;

			/// <summary>
			/// True if the player is currently using a controller.
			/// </summary>
			public bool isUsingController;

			/// <summary>
			/// Tracks the position of the current focused control. Only valid if isUsingController is true.
			/// </summary>
			public Godot.Vector2 controllerFocusPosition;
		}

		public const int minUpdateMsec = 50;

		private readonly INetGameService _netService;

		private readonly List<PeerInputState> _inputStates = new List<PeerInputState>();

		private ulong _lastSyncMsec;

		private Task? _syncMessageTask;

		private PeerInputMessage? _syncMessageToSend;

		private INetCursorPositionTranslator? _cursorTranslator;

		private MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("PeerInputSynchronizer", LogType.VisualSync);

		/// <summary>
		/// If this is unset, Time.GetTicksMsec is used to check how much time has passed.
		/// This is used to mock time passing for tests.
		/// </summary>
		public Func<ulong>? mockGetTicksMsec;

		/// <summary>
		/// If this is unset, Task.Delay is used to buffer messages.
		/// This is used to mock time passing for tests.
		/// </summary>
		public Func<int, Task>? mockDelay;

		/// <summary>
		/// If this is unset, Task.Yield is used to wait a moment before messages are sent.
		/// This is used to mock time passing for tests.
		/// </summary>
		public Func<Task>? mockWaitSmall;

		public INetGameService NetService => _netService;

		/// <summary>
		/// Event fired when we first add a PeerInputState for a player.
		/// This occurs when a player emits a <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Messages.Game.Sync.PeerInputMessage" />, or when we attempt to get the input state for a player.
		/// </summary>
		public event Action<ulong>? StateAdded;

		/// <summary>
		/// Event fired when a player disconnects, and their input state is removed.
		/// </summary>
		public event Action<ulong>? StateRemoved;

		/// <summary>
		/// Event fired when any part of a player's input state is changed.
		/// </summary>
		public event Action<ulong>? StateChanged;

		/// <summary>
		/// Event fired only when a player emits a PeerInputMessage with a new screen type.
		/// The second argument is the old screen type.
		/// </summary>
		public event Action<ulong, NetScreenType>? ScreenChanged;

		public PeerInputSynchronizer(INetGameService netService)
		{
			_netService = netService;
			_netService.RegisterMessageHandler<PeerInputMessage>(HandlePeerInputMessage);
			GetOrCreateStateForPlayer(_netService.NetId);
		}

		public void Dispose()
		{
			_netService.UnregisterMessageHandler<PeerInputMessage>(HandlePeerInputMessage);
		}

		/// <summary>
		/// Sync the local mouse position to other clients.
		/// This should be called any time the mouse position changes - the message will be buffered and sent at regular intervals.
		/// </summary>
		/// <param name="mouseScreenPos">The screen position of the mouse.</param>
		/// <param name="rootControl">The root control, used to normalize mouse coordinates across different resolutions and aspect ratios.</param>
		public void SyncLocalMousePos(Godot.Vector2 mouseScreenPos, Control? rootControl)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			Godot.Vector2 vector = _cursorTranslator?.GetNetPositionFromScreenPosition(mouseScreenPos) ?? NetCursorHelper.GetNormalizedPosition(mouseScreenPos, rootControl);
			_syncMessageToSend.netMousePos = vector;
			orCreateStateForPlayer.netMousePosition = vector;
			StateChanged?.Invoke(_netService.NetId);
			TrySendSyncMessage();
		}

		/// <summary>
		/// Sync the position of the currently focused control node with other clients.
		/// </summary>
		/// <param name="focusPosition">the screen position of the currently focused control node</param>
		/// <param name="rootControl">The root control, used to normalize mouse coordinates across different resolutions and aspect ratios.</param>
		public void SyncLocalControllerFocus(Godot.Vector2 focusPosition, Control? rootControl)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			Godot.Vector2 vector = _cursorTranslator?.GetNetPositionFromScreenPosition(focusPosition) ?? NetCursorHelper.GetNormalizedPosition(focusPosition, rootControl);
			_syncMessageToSend.controllerFocusPosition = vector;
			orCreateStateForPlayer.controllerFocusPosition = vector;
			StateChanged?.Invoke(_netService.NetId);
			TrySendSyncMessage();
		}

		/// <summary>
		/// Sync whether or not the local player is using a controller.
		/// </summary>
		public void SyncLocalIsUsingController(bool isUsingController)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			_syncMessageToSend.isUsingController = isUsingController;
			orCreateStateForPlayer.isUsingController = isUsingController;
			StateChanged?.Invoke(_netService.NetId);
			TrySendSyncMessage();
		}

		/// <summary>
		/// Sync the local mouse down state with other clients (so they show the correct cursor).
		/// </summary>
		/// <param name="mouseDown">True if the mouse is down, false otherwise.</param>
		public void SyncLocalMouseDown(bool mouseDown)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			orCreateStateForPlayer.isMouseDown = mouseDown;
			orCreateStateForPlayer.isUsingController = false;
			StateChanged?.Invoke(_netService.NetId);
			TrySendSyncMessage();
		}

		/// <summary>
		/// Sync the topmost overlay/capstone on the local player's screen to other peers.
		/// </summary>
		/// <param name="netScreenType">The topmost overlay/capstone on the local player's screen.</param>
		public void SyncLocalScreen(NetScreenType netScreenType)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			if (orCreateStateForPlayer.netScreenType != netScreenType)
			{
				_logger.Debug($"Local screen changed: {orCreateStateForPlayer.netScreenType}->{netScreenType}");
				orCreateStateForPlayer.netScreenType = netScreenType;
				TrySendSyncMessage();
				StateChanged?.Invoke(_netService.NetId);
			}
		}

		/// <summary>
		/// ONLY the HoveredModelTracker should call this! You likely want to call one of the HoveredModelTracker methods instead.
		/// Sync the model that the player is currently hovering.
		/// </summary>
		/// <param name="model">The model that the local player is hovering.</param>
		public void SyncLocalHoveredModel(AbstractModel? model)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			HoveredModelData hoveredModelData = HoveredModelData.FromModel(model);
			if (!hoveredModelData.Equals(orCreateStateForPlayer.hoveredModelData))
			{
				orCreateStateForPlayer.hoveredModelData = hoveredModelData;
				TrySendSyncMessage();
				StateChanged?.Invoke(_netService.NetId);
			}
		}

		/// <summary>
		/// Sync whether or not the player is currently in targeting mode.
		/// </summary>
		/// <param name="isTargeting">True if we're currently displaying the targeting arrow locally, false otherwise.</param>
		public void SyncLocalIsTargeting(bool isTargeting)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
			if (_syncMessageToSend == null)
			{
				_syncMessageToSend = new PeerInputMessage();
			}
			if (orCreateStateForPlayer.isTargeting != isTargeting)
			{
				orCreateStateForPlayer.isTargeting = isTargeting;
				TrySendSyncMessage();
				StateChanged?.Invoke(_netService.NetId);
			}
		}

		/// <summary>
		/// Sends a sync message if enough time has passed since the last one, or buffers it to be sent otherwise.
		/// </summary>
		private void TrySendSyncMessage()
		{
			if (_syncMessageTask == null)
			{
				int num = (int)(_lastSyncMsec + 50 - GetTicksMsec());
				if (num <= 0)
				{
					_syncMessageTask = TaskHelper.RunSafely(SendSyncMessageAfterSmallDelay());
				}
				else
				{
					_syncMessageTask = TaskHelper.RunSafely(QueueSyncMessage(num));
				}
			}
		}

		private async Task QueueSyncMessage(int delayMsec)
		{
			await (mockDelay?.Invoke(delayMsec) ?? Task.Delay(delayMsec));
			SendSyncMessage();
		}

		private async Task SendSyncMessageAfterSmallDelay()
		{
			if (mockWaitSmall == null)
			{
				await Task.Yield();
			}
			else
			{
				await mockWaitSmall();
			}
			SendSyncMessage();
		}

		private void SendSyncMessage()
		{
			if (_netService.IsConnected)
			{
				PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(_netService.NetId);
				_syncMessageToSend.mouseDown = orCreateStateForPlayer.isMouseDown;
				_syncMessageToSend.screenType = orCreateStateForPlayer.netScreenType;
				_syncMessageToSend.isTargeting = orCreateStateForPlayer.isTargeting;
				_syncMessageToSend.hoveredModelData = orCreateStateForPlayer.hoveredModelData;
				_syncMessageToSend.isUsingController = orCreateStateForPlayer.isUsingController;
				_syncMessageToSend.controllerFocusPosition = orCreateStateForPlayer.controllerFocusPosition;
				_netService.SendMessage(_syncMessageToSend);
				_lastSyncMsec = GetTicksMsec();
				_syncMessageToSend = null;
				_syncMessageTask = null;
			}
		}

		private PeerInputState? GetStateForPlayer(ulong playerId)
		{
			int num = _inputStates.FindIndex((PeerInputState s) => s.playerId == playerId);
			if (num >= 0)
			{
				return _inputStates[num];
			}
			return null;
		}

		private PeerInputState GetOrCreateStateForPlayer(ulong playerId)
		{
			PeerInputState peerInputState = GetStateForPlayer(playerId);
			if (peerInputState == null)
			{
				peerInputState = new PeerInputState
				{
					playerId = playerId
				};
				_inputStates.Add(peerInputState);
				StateAdded?.Invoke(playerId);
			}
			return peerInputState;
		}

		/// <summary>
		/// Override the normalization calculation for the mouse cursor position.
		/// On screens like the Map screen, synchronizing cursor position based on screen position is not correct. This
		/// method allows you to override the translation from net position to screen position and vice versa.
		/// </summary>
		/// <param name="positionTranslator">The object to use when translating cursor positions.</param>
		public void StartOverridingCursorPositioning(INetCursorPositionTranslator positionTranslator)
		{
			_cursorTranslator = positionTranslator;
		}

		/// <summary>
		/// Stop overriding the normalization calculation for the mouse cursor position.
		/// Should be called after StartOverridingCursorPositioning when the screen is exited.
		/// </summary>
		public void StopOverridingCursorPositioning()
		{
			_cursorTranslator = null;
		}

		private void HandlePeerInputMessage(PeerInputMessage message, ulong senderId)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(senderId);
			if (orCreateStateForPlayer.isMouseDown != message.mouseDown)
			{
				_logger.Debug($"Mouse down state for {senderId} changed: {orCreateStateForPlayer.isMouseDown}->{message.mouseDown}");
			}
			if (orCreateStateForPlayer.netScreenType != message.screenType)
			{
				_logger.Debug($"Remote screen for {senderId} changed: {orCreateStateForPlayer.netScreenType}->{message.screenType}");
			}
			if (orCreateStateForPlayer.isTargeting != message.isTargeting)
			{
				_logger.Debug($"Targeting state for {senderId} changed: {orCreateStateForPlayer.isTargeting}->{message.isTargeting}");
			}
			if (!orCreateStateForPlayer.hoveredModelData.Equals(message.hoveredModelData))
			{
				_logger.Debug($"Hovered model for {senderId} changed: {orCreateStateForPlayer.hoveredModelData}->{message.hoveredModelData}");
			}
			if (!orCreateStateForPlayer.controllerFocusPosition.Equals(message.controllerFocusPosition))
			{
				_logger.Debug($"Controller focus position for {senderId} changed: {orCreateStateForPlayer.controllerFocusPosition}->{message.controllerFocusPosition}");
			}
			if (!orCreateStateForPlayer.isUsingController.Equals(message.isUsingController))
			{
				_logger.Debug($"Using controller state state for {senderId} changed: {orCreateStateForPlayer.isUsingController}->{message.isUsingController}");
			}
			NetScreenType netScreenType = orCreateStateForPlayer.netScreenType;
			orCreateStateForPlayer.netMousePosition = message.netMousePos ?? orCreateStateForPlayer.netMousePosition;
			orCreateStateForPlayer.isMouseDown = message.mouseDown;
			orCreateStateForPlayer.netScreenType = message.screenType;
			orCreateStateForPlayer.isTargeting = message.isTargeting;
			orCreateStateForPlayer.hoveredModelData = message.hoveredModelData;
			orCreateStateForPlayer.isUsingController = message.isUsingController;
			orCreateStateForPlayer.controllerFocusPosition = message.controllerFocusPosition ?? orCreateStateForPlayer.controllerFocusPosition;
			StateChanged?.Invoke(senderId);
			if (netScreenType != orCreateStateForPlayer.netScreenType)
			{
				ScreenChanged?.Invoke(senderId, netScreenType);
			}
		}

		/// <summary>
		/// Returns the control-space position of a given player within the given control.
		/// If the player is using a mouse, then this would be the mouse's position
		/// If the player is using the controller, then this would be the position of the control node that that player is
		/// currently focused on.
		/// Different resolutions and aspect ratios are all mapped to the same 1920x1080 reference resolution in control-
		/// space. Essentially, the position returned by this method can be used set the position property on a Control with
		/// a cursor image as rootControl's child and have it look approximately the same across all peers.
		/// </summary>
		/// <param name="playerId">Player for which the mouse cursor position should be obtained.</param>
		/// <param name="rootControl">The root control to position the mouse cursor relative to. Should only be null in tests.</param>
		/// <returns></returns>
		public Godot.Vector2 GetControlSpaceFocusPosition(ulong playerId, Control? rootControl)
		{
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(playerId);
			Godot.Vector2 vector = (orCreateStateForPlayer.isUsingController ? orCreateStateForPlayer.controllerFocusPosition : orCreateStateForPlayer.netMousePosition);
			if (_cursorTranslator == null)
			{
				return NetCursorHelper.GetControlSpacePosition(vector, rootControl);
			}
			Godot.Vector2 screenPositionFromNetPosition = _cursorTranslator.GetScreenPositionFromNetPosition(vector);
			if (rootControl == null)
			{
				if (TestMode.IsOn)
				{
					return screenPositionFromNetPosition;
				}
				throw new InvalidOperationException("Root node should only be null in tests!");
			}
			return rootControl.GetGlobalTransformWithCanvas() * screenPositionFromNetPosition;
		}

		/// <returns>True if the given player is holding the mouse down, false otherwise.</returns>
		public bool GetMouseDown(ulong playerId)
		{
			return GetOrCreateStateForPlayer(playerId).isMouseDown;
		}

		/// <returns>The top-most overlay or capstone that the given player is looking at.</returns>
		public NetScreenType GetScreenType(ulong playerId)
		{
			return GetOrCreateStateForPlayer(playerId).netScreenType;
		}

		/// <summary> WARNING: You probably want HoveredModelTracker methods instead! </summary>
		/// <returns>Info about what model the player is hovering.</returns>
		public HoveredModelData GetHoveredModelData(ulong playerId)
		{
			return GetOrCreateStateForPlayer(playerId).hoveredModelData;
		}

		/// <returns>True if the player is currently in combat targeting mode, false otherwise.</returns>
		public bool GetIsTargeting(ulong playerId)
		{
			return GetOrCreateStateForPlayer(playerId).isTargeting;
		}

		/// <summary>
		/// Removes the player state from the synchronizer if it exists and notifies listeners.
		/// Note that, if the player is still connected to the session and sends a PeerInputMessage, the state will be
		/// re-created, so this method should be called as late as possible in the disconnection flow.
		/// </summary>
		/// <param name="playerId">The player that left the game.</param>
		public void OnPlayerDisconnected(ulong playerId)
		{
			_logger.Debug($"Disconnected player {playerId}, removing PeerInputState");
			_inputStates.RemoveAll((PeerInputState p) => p.playerId == playerId);
			StateRemoved?.Invoke(playerId);
		}

		private ulong GetTicksMsec()
		{
			return mockGetTicksMsec?.Invoke() ?? Time.GetTicksMsec();
		}
	}
	/// <summary>
	/// Keeps track of the local player's screen state and synchronizes it to remote peers via the PeerInputSynchronizer.
	/// </summary>
	public class ScreenStateTracker
	{
		private NetScreenType _capstoneScreen;

		private NetScreenType _overlayScreen;

		private bool _mapScreenVisible;

		private bool _isInSharedRelicPicking;

		/// <summary>
		/// Callable.From() creates a new delegate each call, so we store it to ensure IsConnected() can match the same
		/// instance used to Connect(). This prevents Godot's "signal already connected" error when the rewards screen
		/// re-emerges as the top overlay after another overlay is pushed on top and later popped.
		/// </summary>
		private readonly Callable _onRewardsScreenCompleted;

		public ScreenStateTracker(NMapScreen mapScreen, NCapstoneContainer capstoneContainer, NOverlayStack overlayStack)
		{
			_onRewardsScreenCompleted = Callable.From(SyncLocalScreen);
			capstoneContainer.Connect(NCapstoneContainer.SignalName.Changed, Callable.From(OnCapstoneScreenChanged));
			overlayStack.Connect(NOverlayStack.SignalName.Changed, Callable.From(OnOverlayStackChanged));
			mapScreen.Connect(CanvasItem.SignalName.VisibilityChanged, Callable.From(OnMapScreenVisibilityChanged));
		}

		private void OnCapstoneScreenChanged()
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer)
			{
				_capstoneScreen = NCapstoneContainer.Instance.CurrentCapstoneScreen?.ScreenType ?? NetScreenType.None;
				SyncLocalScreen();
			}
		}

		private void OnOverlayStackChanged()
		{
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer)
			{
				IOverlayScreen overlayScreen = NOverlayStack.Instance.Peek();
				if (overlayScreen is NRewardsScreen nRewardsScreen && !nRewardsScreen.IsConnected(NRewardsScreen.SignalName.Completed, _onRewardsScreenCompleted))
				{
					nRewardsScreen.Connect(NRewardsScreen.SignalName.Completed, _onRewardsScreenCompleted);
				}
				_overlayScreen = overlayScreen?.ScreenType ?? NetScreenType.None;
				SyncLocalScreen();
			}
		}

		private void SyncLocalScreen()
		{
			RunManager.Instance.InputSynchronizer.SyncLocalScreen(GetCurrentScreen());
		}

		/// <summary>
		/// The map is not an overlay or a capstone, it's part of <see cref="T:MegaCrit.Sts2.Core.Nodes.NRun" />.
		/// </summary>
		private void OnMapScreenVisibilityChanged()
		{
			_mapScreenVisible = NMapScreen.Instance.Visible;
			RunManager.Instance.InputSynchronizer.SyncLocalScreen(GetCurrentScreen());
		}

		/// <summary>
		/// The shared relic picking screen at the treasure room is not an overlay or a capstone, it's part of the state of
		/// the room, so it needs to get synchronized manually.
		/// </summary>
		public void SetIsInSharedRelicPickingScreen(bool isInSharedRelicPicking)
		{
			_isInSharedRelicPicking = isInSharedRelicPicking;
			RunManager.Instance.InputSynchronizer.SyncLocalScreen(GetCurrentScreen());
		}

		private NetScreenType GetCurrentScreen()
		{
			if (_capstoneScreen != NetScreenType.None)
			{
				return _capstoneScreen;
			}
			if (_mapScreenVisible)
			{
				return NetScreenType.Map;
			}
			if (_overlayScreen == NetScreenType.Rewards)
			{
				if (NOverlayStack.Instance.Peek() is NRewardsScreen { IsComplete: false })
				{
					return _overlayScreen;
				}
			}
			else if (_overlayScreen != NetScreenType.None)
			{
				return _overlayScreen;
			}
			if (_isInSharedRelicPicking)
			{
				return NetScreenType.SharedRelicPicking;
			}
			return NetScreenType.Room;
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Game.Lobby
{
	/// <summary>
	/// Handles callbacks generated by the <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.LoadRunLobby" />.
	/// </summary>
	public interface ILoadRunLobbyListener
	{
		/// <summary>
		/// Called when a new player has connected. This includes the local player (even the host).
		/// If we are a client newly connecting to a host, and there are already players in the lobby, then this is called
		/// once for each player that is already in the lobby.
		/// </summary>
		void PlayerConnected(LoadRunLobbyPlayer player);

		/// <summary>
		/// Called when another player has left the lobby.
		/// </summary>
		/// <param name="playerId">The ID of the player who has left.</param>
		void RemotePlayerDisconnected(ulong playerId);

		/// <summary>
		/// Called when everyone is ready on the host. If this returns true, then the run will begin. Otherwise, the host
		/// will be un-readied and the run will not begin until the host re-readies.
		/// </summary>
		Task<bool> ShouldAllowRunToBegin();

		/// <summary>
		/// Called when the run begins, on both host and client. When calling CloseAndBeginRun on the host, you should
		/// wait for this call to actually begin the run.
		/// </summary>
		void BeginRun();

		/// <summary>
		/// Called when a player readies or un-readies.
		/// </summary>
		void PlayerReadyChanged(ulong playerId);

		/// <summary>
		/// Called when the local player has been disconnected from the lobby.
		/// <param name="info">Information about why we were disconnected.</param>
		/// </summary>
		void LocalPlayerDisconnected(NetErrorInfo info);
	}
	/// <summary>
	/// Handles callbacks generated by the <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.RunLobby" />.
	/// </summary>
	public interface IRunLobbyListener
	{
		/// <summary>
		/// Called when a player is attempting to rejoin the game.
		/// This should return a fully-filled ClientRejoinResponseMessage with the current game state.
		/// </summary>
		ClientRejoinResponseMessage GetRejoinMessage();

		/// <summary>
		/// Called when the local player has been disconnected from the lobby.
		/// </summary>
		void LocalPlayerDisconnected(NetErrorInfo info);

		/// <summary>
		/// Called when the run has been abandoned by the host.
		/// Note that LocalPlayerDisconnected will still be called in this case with NetError.Quit.
		/// </summary>
		void RunAbandoned();
	}
	/// <summary>
	/// Handles callbacks generated by the <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.StartRunLobby" />.
	/// </summary>
	public interface IStartRunLobbyListener
	{
		/// <summary>
		/// Called when a new player has connected. This includes the local player (even the host).
		/// </summary>
		/// <param name="player">The newly connected player.</param>
		void PlayerConnected(StartRunLobbyPlayer player);

		/// <summary>
		/// Called when a lobby player's state has changed (e.g. their chosen character has changed).
		/// </summary>
		/// <param name="player">The player whose state has changed.</param>
		/// <param name="isRandomCharacterResolution">This is only set to true when the player has changed due to the lobby
		/// resolving the random character to the real one when the run is beginning.</param>
		void PlayerChanged(StartRunLobbyPlayer player, bool isRandomCharacterResolution);

		/// <summary>
		/// Called when the host has changed the ascension level, on both host and client.
		/// </summary>
		void AscensionChanged();

		/// <summary>
		/// Called when the host has changed the custom seed, on both host and client.
		/// </summary>
		void SeedChanged();

		/// <summary>
		/// Called when the host has changed the modifiers, on both host and client.
		/// </summary>
		void ModifiersChanged();

		/// <summary>
		/// Called when a client joins with a lower max ascension level than the previous one, on both host and client.
		/// Also called when the character changes in a singleplayer game, changing the max ascension.
		/// </summary>
		void MaxAscensionChanged();

		/// <summary>
		/// Called when another player has left the lobby.
		/// </summary>
		/// <param name="player">The player who has left.</param>
		void RemotePlayerDisconnected(StartRunLobbyPlayer player);

		/// <summary>
		/// Called when the run begins, on both host and client. When calling CloseAndBeginRun on the host, you should wait
		/// for this call to actually begin the run.
		/// </summary>
		/// <param name="seed">The seed used to start the run.</param>
		/// <param name="acts">The acts used to start the run.</param>
		/// <param name="modifiers">The modifiers used to start the run.</param>
		void BeginRun(string seed, List<ActModel> acts, IReadOnlyList<ModifierModel> modifiers);

		/// <summary>
		/// Called when the local player has been disconnected from the lobby.
		/// <param name="info">Information about why we were disconnected.</param>
		/// </summary>
		void LocalPlayerDisconnected(NetErrorInfo info);
	}
	/// <summary>
	/// Class which handles the connection flow for players resuming a run from a save file.
	/// This exists before Run, giving players an opportunity to all join before the run is resumed.
	/// Only connections from players in the loaded save file will be accepted; all other connections will be denied.
	/// <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.RunLobby" /> handles player connection and disconnection after the run begins.
	/// </summary>
	public class LoadRunLobby
	{
		private struct ConnectingPlayer : IEquatable<ConnectingPlayer>
		{
			public ulong id;

			public CancellationTokenSource timeoutCancelToken;

			public bool Equals(ConnectingPlayer other)
			{
				if (id == other.id)
				{
					return timeoutCancelToken.Equals(other.timeoutCancelToken);
				}
				return false;
			}

			public override bool Equals(object? obj)
			{
				if (obj is ConnectingPlayer other)
				{
					return Equals(other);
				}
				return false;
			}

			public override int GetHashCode()
			{
				return HashCode.Combine(id, timeoutCancelToken);
			}
		}

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		private readonly List<ConnectingPlayer> _connectingPlayers = new List<ConnectingPlayer>();

		private bool _isBeginningRun;

		public List<LoadRunLobbyPlayer> Players { get; } = new List<LoadRunLobbyPlayer>();

		public int PlayerCount => Players.Count;

		public IEnumerable<ulong> PlayerIds => Players.Select((LoadRunLobbyPlayer p) => p.id);

		public INetGameService NetService { get; }

		public ILoadRunLobbyListener LobbyListener { get; }

		public PeerInputSynchronizer InputSynchronizer { get; }

		public SerializableRun Run { get; }

		public GameMode GameMode => Run.GameMode;

		/// <summary>
		/// If we are the host, this is the amount of time we give clients to send the initial message response in
		/// milliseconds. Public for tests.
		/// </summary>
		public int ClientResponseTimeout { get; set; } = 10000;

		/// <summary>
		/// Provides extended disconnection info to UI, but only when the local player is the host.
		/// </summary>
		public event Action<ulong, NetErrorInfo>? PlayerFailedToConnect;

		public LoadRunLobby(INetGameService netService, ILoadRunLobbyListener lobbyListener, SerializableRun runSave)
		{
			Run = runSave;
			NetService = netService;
			LobbyListener = lobbyListener;
			InputSynchronizer = new PeerInputSynchronizer(NetService);
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("LoadRunLobby", LogType.Network);
			NetService.RegisterMessageHandler<ClientLoadJoinRequestMessage>(HandleClientLoadJoinRequestMessage);
			NetService.RegisterMessageHandler<ClientLobbyJoinRequestMessage>(HandleClientLobbyJoinRequestMessage);
			NetService.RegisterMessageHandler<ClientRejoinRequestMessage>(HandleClientRejoinRequestMessage);
			NetService.RegisterMessageHandler<PlayerReconnectedMessage>(HandlePlayerReconnectedMessage);
			NetService.RegisterMessageHandler<PlayerLeftMessage>(HandlePlayerLeftMessage);
			NetService.RegisterMessageHandler<LobbyPlayerSetReadyMessage>(HandlePlayerReadyMessage);
			NetService.RegisterMessageHandler<LobbyBeginLoadedRunMessage>(HandleLobbyBeginRunMessage);
			NetService.Disconnected += OnDisconnected;
			if (NetService.Type == NetGameType.Host)
			{
				INetHostGameService netHostGameService = (INetHostGameService)netService;
				netHostGameService.ClientConnected += OnConnectedToClientAsHost;
				netHostGameService.ClientDisconnected += OnDisconnectedFromClientAsHost;
				netHostGameService.ClientConnectionFailed += OnClientConnectionFailed;
			}
		}

		public LoadRunLobby(INetGameService netService, ILoadRunLobbyListener lobbyListener, ClientLoadJoinResponseMessage message)
			: this(netService, lobbyListener, message.serializableRun)
		{
			Players = message.playersAlreadyConnected;
		}

		/// <summary>
		/// This should be called to cleanup the lobby before exiting the lobby screen.
		/// </summary>
		/// <param name="disconnectSession">
		/// If true, the net service will be disconnected. Pass true if the lobby is being closed rather than transitioning
		/// to a run.
		/// </param>
		/// <param name="error">If disconnectSession is true, this is the error that is sent to clients.</param>
		public void CleanUp(bool disconnectSession, NetError error = NetError.Quit)
		{
			NetService.UnregisterMessageHandler<ClientLoadJoinRequestMessage>(HandleClientLoadJoinRequestMessage);
			NetService.UnregisterMessageHandler<ClientLobbyJoinRequestMessage>(HandleClientLobbyJoinRequestMessage);
			NetService.UnregisterMessageHandler<ClientRejoinRequestMessage>(HandleClientRejoinRequestMessage);
			NetService.UnregisterMessageHandler<PlayerReconnectedMessage>(HandlePlayerReconnectedMessage);
			NetService.UnregisterMessageHandler<PlayerLeftMessage>(HandlePlayerLeftMessage);
			NetService.UnregisterMessageHandler<LobbyPlayerSetReadyMessage>(HandlePlayerReadyMessage);
			NetService.UnregisterMessageHandler<LobbyBeginLoadedRunMessage>(HandleLobbyBeginRunMessage);
			if (disconnectSession)
			{
				if (NetService.IsConnected)
				{
					NetService.Disconnect(error);
				}
				InputSynchronizer.Dispose();
			}
			NetService.Disconnected -= OnDisconnected;
			if (NetService.Type == NetGameType.Host)
			{
				INetHostGameService netHostGameService = (INetHostGameService)NetService;
				netHostGameService.ClientConnected -= OnConnectedToClientAsHost;
				netHostGameService.ClientDisconnected -= OnDisconnectedFromClientAsHost;
				netHostGameService.ClientConnectionFailed -= OnClientConnectionFailed;
			}
		}

		/// <summary>
		/// Should be called when the lobby opens on the host player's side to generate the host's lobby player.
		/// </summary>
		public void AddLocalHostPlayer()
		{
			if (NetService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Tried to add local host player as client!");
			}
			_logger.Context = $"Lobby ({NetService.NetId})";
			LoadRunLobbyPlayer loadRunLobbyPlayer = new LoadRunLobbyPlayer
			{
				id = NetService.NetId,
				isReady = false,
				isModded = NetService.LocalVersion.IsModded()
			};
			Players.Add(loadRunLobbyPlayer);
			LobbyListener.PlayerConnected(loadRunLobbyPlayer);
		}

		private void HandleClientLoadJoinRequestMessage(ClientLoadJoinRequestMessage message, ulong senderId)
		{
			if (NetService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientLoadJoinRequestMessage as non-host!");
			}
			INetHostGameService netHostGameService = (INetHostGameService)NetService;
			try
			{
				if (Run.Players.FindIndex((SerializablePlayer p) => p.NetId == senderId) < 0)
				{
					_logger.Warn($"Client {senderId} sent ClientLoadJoinRequestMessage but they are not in the loaded run!");
					netHostGameService.DisconnectClient(senderId, NetError.NotInSaveGame);
					return;
				}
				_logger.Info($"Received ClientLoadJoinRequestMessage for {senderId}");
				LoadRunLobbyPlayer loadRunLobbyPlayer = new LoadRunLobbyPlayer
				{
					id = senderId,
					isReady = false,
					isModded = netHostGameService.GetVersionInfoForPeer(senderId).Value.IsModded()
				};
				Players.Add(loadRunLobbyPlayer);
				LobbyListener.PlayerConnected(loadRunLobbyPlayer);
				ClientLoadJoinResponseMessage message2 = new ClientLoadJoinResponseMessage
				{
					serializableRun = Run,
					playersAlreadyConnected = Players.ToList()
				};
				_logger.Debug($"Sending ClientLoadJoinResponseMessage to {senderId}");
				netHostGameService.SendMessage(message2, senderId);
				netHostGameService.SetPeerReadyForBroadcasting(senderId);
				PlayerReconnectedMessage message3 = new PlayerReconnectedMessage
				{
					player = loadRunLobbyPlayer
				};
				foreach (LoadRunLobbyPlayer player in Players)
				{
					if (player.id != senderId && player.id != NetService.NetId)
					{
						_logger.Debug($"Sending PlayerReconnectedMessage to {player.id}");
						netHostGameService.SendMessage(message3, player.id);
					}
				}
				RemoveConnectingPlayer(senderId);
			}
			catch
			{
				netHostGameService.DisconnectClient(senderId, NetError.InternalError);
				throw;
			}
		}

		private void HandleClientLobbyJoinRequestMessage(ClientLobbyJoinRequestMessage _, ulong senderId)
		{
			if (NetService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientLobbyJoinRequestMessage as non-host!");
			}
			_logger.Info($"Received invalid ClientLobbyJoinRequestMessage for {senderId}");
			INetHostGameService netHostGameService = (INetHostGameService)NetService;
			netHostGameService.DisconnectClient(senderId, NetError.InvalidJoin);
		}

		private void HandleClientRejoinRequestMessage(ClientRejoinRequestMessage _, ulong senderId)
		{
			if (NetService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientRejoinRequestMessage as non-host!");
			}
			_logger.Info($"Received invalid ClientRejoinRequestMessage for {senderId}");
			INetHostGameService netHostGameService = (INetHostGameService)NetService;
			netHostGameService.DisconnectClient(senderId, NetError.InvalidJoin);
		}

		private void HandlePlayerReconnectedMessage(PlayerReconnectedMessage message, ulong _)
		{
			_logger.Debug($"Received PlayerReconnectedMessage with player ID {message.player.id}");
			Players.Add(message.player);
			LobbyListener.PlayerConnected(message.player);
		}

		private void HandlePlayerLeftMessage(PlayerLeftMessage message, ulong senderId)
		{
			_logger.Debug($"Received PlayerLeftMessage for {message.playerId}");
			int num = Players.RemoveAll((LoadRunLobbyPlayer p) => p.id == message.playerId);
			if (num > 0)
			{
				InputSynchronizer.OnPlayerDisconnected(message.playerId);
				LobbyListener.RemotePlayerDisconnected(message.playerId);
			}
		}

		private void HandlePlayerReadyMessage(LobbyPlayerSetReadyMessage message, ulong senderId)
		{
			_logger.Debug($"Received {"LobbyPlayerSetReadyMessage"} for player {senderId} with value {message.ready}");
			int num = Players.FindIndex((LoadRunLobbyPlayer p) => p.id == senderId);
			if (num >= 0)
			{
				LoadRunLobbyPlayer value = Players[num];
				bool isReady = value.isReady;
				value.isReady = message.ready;
				Players[num] = value;
				if (isReady != message.ready)
				{
					LobbyListener.PlayerReadyChanged(senderId);
				}
				BeginRunForAllPlayersIfAllReady();
			}
		}

		private void HandleLobbyBeginRunMessage(LobbyBeginLoadedRunMessage message, ulong senderId)
		{
			_logger.Debug("Received LobbyBeginLoadedRunMessage");
			_isBeginningRun = true;
			BeginRunLocally();
		}

		private async Task TryBeginRunForAllPlayers()
		{
			if (NetService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Can only begin run for all peers as host!");
			}
			if (_isBeginningRun)
			{
				_logger.Warn("Tried to begin run twice, ignoring second one!");
				return;
			}
			_isBeginningRun = true;
			if (!(await LobbyListener.ShouldAllowRunToBegin()))
			{
				SetReady(ready: false);
				_isBeginningRun = false;
				return;
			}
			NetService.SendMessage(default(LobbyBeginLoadedRunMessage));
			BeginRunLocally();
			if (NetService.Type == NetGameType.Host)
			{
				INetHostGameService netHostGameService = (INetHostGameService)NetService;
				netHostGameService.NetHost?.SetHostIsClosed(isClosed: true);
			}
		}

		private void BeginRunLocally()
		{
			NetService.SetBufferMessages(bufferMessages: true);
			LobbyListener.BeginRun();
		}

		public void SetReady(bool ready)
		{
			int num = Players.FindIndex((LoadRunLobbyPlayer p) => p.id == NetService.NetId);
			if (num >= 0)
			{
				LoadRunLobbyPlayer value = Players[num];
				value.isReady = ready;
				Players[num] = value;
				LobbyPlayerSetReadyMessage message = new LobbyPlayerSetReadyMessage
				{
					ready = ready
				};
				NetService.SendMessage(message);
				LobbyListener.PlayerReadyChanged(NetService.NetId);
				_logger.Info($"Local player {NetService.NetId} is ready");
				BeginRunForAllPlayersIfAllReady();
			}
		}

		/// <summary>
		/// Whether the given player has readied up. Players is only the peers currently in the lobby, but callers ask
		/// about every player in the save file, including ones who have not connected yet or who have just left. Those
		/// players are not ready, so this must answer for any id rather than only for lobby members.
		/// </summary>
		public bool IsPlayerReady(ulong playerId)
		{
			return Players.Any((LoadRunLobbyPlayer p) => p.id == playerId && p.isReady);
		}

		public bool IsAboutToBeginGame()
		{
			if (_connectingPlayers.Count > 0)
			{
				return false;
			}
			if (NetService.Type.IsMultiplayer() && Players.Count == 1)
			{
				return false;
			}
			return Players.All((LoadRunLobbyPlayer p) => p.isReady);
		}

		private void BeginRunForAllPlayersIfAllReady()
		{
			if ((NetService.Type == NetGameType.Host || NetService.Type == NetGameType.Singleplayer) && IsAboutToBeginGame())
			{
				TaskHelper.RunSafely(TryBeginRunForAllPlayers());
			}
		}

		private void OnConnectedToClientAsHost(ulong playerId)
		{
			_logger.Info($"Client {playerId} connected. Sending initial game info message");
			InitialGameInfoMessage message = new InitialGameInfoMessage
			{
				sessionState = RunSessionState.InLoadedLobby,
				gameMode = GameMode
			};
			if (_isBeginningRun)
			{
				message.connectionFailureReason = ConnectionFailureReason.RunInProgress;
				NetService.SendMessage(message, playerId);
				_logger.Warn($"Client {playerId} connected but we are already beginning the run!");
				((INetHostGameService)NetService).DisconnectClient(playerId, NetError.RunInProgress);
			}
			else if (Run.Players.FindIndex((SerializablePlayer p) => p.NetId == playerId) < 0)
			{
				message.connectionFailureReason = ConnectionFailureReason.NotInSaveGame;
				NetService.SendMessage(message, playerId);
				_logger.Warn($"Client {playerId} connected but they were not in the loaded game!");
				((INetHostGameService)NetService).DisconnectClient(playerId, NetError.NotInSaveGame);
			}
			else
			{
				ConnectingPlayer connectingPlayer = new ConnectingPlayer
				{
					id = playerId,
					timeoutCancelToken = new CancellationTokenSource()
				};
				_connectingPlayers.Add(connectingPlayer);
				NetService.SendMessage(message, playerId);
				TaskHelper.RunSafely(BeginClientResponseTimeout(connectingPlayer));
			}
		}

		private async Task BeginClientResponseTimeout(ConnectingPlayer connectingPlayer)
		{
			await Task.Delay(ClientResponseTimeout, connectingPlayer.timeoutCancelToken.Token);
			if (!connectingPlayer.timeoutCancelToken.IsCancellationRequested)
			{
				int num = _connectingPlayers.IndexOf(connectingPlayer);
				if (num >= 0)
				{
					_logger.Info($"Disconnecting player {connectingPlayer.id} because they did not respond to the initial game join message within {ClientResponseTimeout}ms");
					INetHostGameService netHostGameService = (INetHostGameService)NetService;
					netHostGameService.DisconnectClient(connectingPlayer.id, NetError.LobbyJoinTimeout);
				}
			}
		}

		private void OnDisconnectedFromClientAsHost(ulong playerId, NetErrorInfo info)
		{
			int num = Players.FindIndex((LoadRunLobbyPlayer p) => p.id == playerId);
			if (num >= 0)
			{
				_logger.Info($"Client {playerId} disconnected, reason: {info.GetReason()}");
				PlayerLeftMessage message = new PlayerLeftMessage
				{
					playerId = playerId
				};
				NetService.SendMessage(message);
				Players.RemoveAt(num);
				RemoveConnectingPlayer(playerId);
				InputSynchronizer.OnPlayerDisconnected(message.playerId);
				LobbyListener.RemotePlayerDisconnected(playerId);
				BeginRunForAllPlayersIfAllReady();
			}
		}

		private void OnClientConnectionFailed(ulong playerId, NetErrorInfo info)
		{
			PlayerFailedToConnect?.Invoke(playerId, info);
		}

		private void RemoveConnectingPlayer(ulong playerId)
		{
			for (int i = 0; i < _connectingPlayers.Count; i++)
			{
				if (_connectingPlayers[i].id == playerId)
				{
					_connectingPlayers[i].timeoutCancelToken.Cancel();
					_connectingPlayers.RemoveAt(i);
					i--;
				}
			}
		}

		private void OnDisconnected(NetErrorInfo info)
		{
			_logger.Info($"Disconnected from host, reason: {info.GetReason()}");
			Players.Clear();
			LobbyListener.LocalPlayerDisconnected(info);
		}
	}
	/// <summary>
	/// Class which handles disconnection and reconnection while a run is in progress.
	/// <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.StartRunLobby" /> or <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.LoadRunLobby" /> are used to initialize the run. Once the run is in
	/// progress, those instances go away and this class takes over their responsibilities.
	/// Connections from players that are not currently in the run will be denied. Only players that existed in the run
	/// may reconnect to the RunLobby.
	/// </summary>
	public class RunLobby
	{
		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		private readonly IPlayerCollection _playerCollection;

		private readonly IRunLobbyListener _lobbyListener;

		private readonly INetGameService _netService;

		/// <summary>
		/// <see cref="P:MegaCrit.Sts2.Core.Runs.RunState.Players" /> contains all players that have ever been connected to the session, i.e. it may
		/// contain disconnected players. This set contains only players who are currently connected to the session.
		/// </summary>
		public List<RunLobbyPlayer> Players { get; }

		public IEnumerable<ulong> PlayerIds => Players.Select((RunLobbyPlayer p) => p.id);

		/// <summary>
		/// Set to true if any player in the session was playing with mods.
		/// This cannot be derived from <see cref="F:MegaCrit.Sts2.Core.Entities.Multiplayer.RunLobbyPlayer.isModded" /> because errors that occur during
		/// disconnection are emitted after the player has already left, which means they've been removed from
		/// <see cref="P:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.RunLobby.Players" />.
		/// </summary>
		public bool AnyPlayerHadMods { get; }

		public GameMode GameMode { get; }

		public event Action<RunLobbyPlayer>? PlayerRejoined;

		public event Action<ulong>? RemotePlayerDisconnected;

		public event Action? LocalPlayerDisconnected;

		/// <summary>
		/// Creates the RunLobby.
		/// </summary>
		/// <param name="gameMode">The type of run that was started.</param>
		/// <param name="netService">Net service used to send/receive messages.</param>
		/// <param name="lobbyListener">The lobby listener which receives callbacks from this lobby.</param>
		/// <param name="playerCollection">Queryable collection of players.</param>
		/// <param name="players">The players in the game.</param>
		public RunLobby(GameMode gameMode, INetGameService netService, IRunLobbyListener lobbyListener, IPlayerCollection playerCollection, IEnumerable<RunLobbyPlayer> players)
		{
			GameMode = gameMode;
			_netService = netService;
			_lobbyListener = lobbyListener;
			_playerCollection = playerCollection;
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("RunLobby", LogType.Network);
			Players = players.ToList();
			AnyPlayerHadMods = Players.Any((RunLobbyPlayer p) => p.isModded);
			_netService.RegisterMessageHandler<ClientLobbyJoinRequestMessage>(HandleClientLobbyJoinRequestMessage);
			_netService.RegisterMessageHandler<ClientLoadJoinRequestMessage>(HandleClientLoadJoinRequestMessage);
			_netService.RegisterMessageHandler<ClientRejoinRequestMessage>(HandleClientRejoinRequestMessage);
			_netService.RegisterMessageHandler<PlayerRejoinedMessage>(HandlePlayerRejoinedMessage);
			_netService.RegisterMessageHandler<PlayerLeftMessage>(HandlePlayerLeftMessage);
			_netService.RegisterMessageHandler<RunAbandonedMessage>(HandleRunAbandonedMessage);
			_netService.Disconnected += OnDisconnected;
			if (_netService.Type == NetGameType.Host && netService is INetHostGameService netHostGameService)
			{
				netHostGameService.ClientConnected += OnConnectedToClientAsHost;
				netHostGameService.ClientDisconnected += OnDisconnectedFromClientAsHost;
			}
		}

		/// <summary>
		/// This should be called to cleanup the lobby before exiting the run.
		/// </summary>
		public void Dispose()
		{
			_netService.UnregisterMessageHandler<ClientLobbyJoinRequestMessage>(HandleClientLobbyJoinRequestMessage);
			_netService.UnregisterMessageHandler<ClientLoadJoinRequestMessage>(HandleClientLoadJoinRequestMessage);
			_netService.UnregisterMessageHandler<ClientRejoinRequestMessage>(HandleClientRejoinRequestMessage);
			_netService.UnregisterMessageHandler<PlayerRejoinedMessage>(HandlePlayerRejoinedMessage);
			_netService.UnregisterMessageHandler<PlayerLeftMessage>(HandlePlayerLeftMessage);
			_netService.UnregisterMessageHandler<RunAbandonedMessage>(HandleRunAbandonedMessage);
			_netService.Disconnected -= OnDisconnected;
			if (_netService.Type == NetGameType.Host && _netService is INetHostGameService netHostGameService)
			{
				netHostGameService.ClientConnected -= OnConnectedToClientAsHost;
				netHostGameService.ClientDisconnected -= OnDisconnectedFromClientAsHost;
			}
		}

		private void HandleClientRejoinRequestMessage(ClientRejoinRequestMessage message, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientRejoinRequestMessage as non-host!");
			}
			_logger.Info($"Received ClientRejoinRequestMessage for {senderId}");
			NetHostGameService netHostGameService = (NetHostGameService)_netService;
			if (_playerCollection.GetPlayer(senderId) == null)
			{
				netHostGameService.DisconnectClient(senderId, NetError.RunInProgress);
				return;
			}
			ClientRejoinResponseMessage rejoinMessage = _lobbyListener.GetRejoinMessage();
			netHostGameService.SendMessage(rejoinMessage, senderId);
			netHostGameService.SetPeerReadyForBroadcasting(senderId);
			RunLobbyPlayer runLobbyPlayer = new RunLobbyPlayer
			{
				id = senderId,
				isModded = netHostGameService.GetVersionInfoForPeer(senderId).Value.IsModded()
			};
			Players.Add(runLobbyPlayer);
			PlayerRejoinedMessage message2 = new PlayerRejoinedMessage
			{
				player = runLobbyPlayer
			};
			foreach (RunLobbyPlayer player in Players)
			{
				if (player.id != _netService.NetId && player.id != runLobbyPlayer.id)
				{
					netHostGameService.SendMessage(message2, player.id);
				}
			}
			PlayerRejoined?.Invoke(runLobbyPlayer);
		}

		private void HandleClientLobbyJoinRequestMessage(ClientLobbyJoinRequestMessage _, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientLobbyJoinRequestMessage as non-host!");
			}
			_logger.Info($"Received invalid ClientLobbyJoinRequestMessage for {senderId}");
			NetHostGameService netHostGameService = (NetHostGameService)_netService;
			netHostGameService.DisconnectClient(senderId, NetError.InvalidJoin);
		}

		private void HandleClientLoadJoinRequestMessage(ClientLoadJoinRequestMessage _, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientLoadJoinRequestMessage as non-host!");
			}
			_logger.Info($"Received invalid ClientLoadJoinRequestMessage for {senderId}");
			NetHostGameService netHostGameService = (NetHostGameService)_netService;
			netHostGameService.DisconnectClient(senderId, NetError.InvalidJoin);
		}

		private void HandlePlayerRejoinedMessage(PlayerRejoinedMessage message, ulong _)
		{
			_logger.Debug($"Received PlayerRejoinedMessage for {message.player.id}");
			Players.Add(message.player);
			PlayerRejoined?.Invoke(message.player);
		}

		private void HandlePlayerLeftMessage(PlayerLeftMessage message, ulong _)
		{
			_logger.Debug($"Received PlayerLeftMessage for {message.playerId}");
			Players.RemoveAll((RunLobbyPlayer p) => p.id == message.playerId);
			RemotePlayerDisconnected?.Invoke(message.playerId);
		}

		public void AbandonRun()
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Abandon run can only be called as host!");
			}
			_logger.Info("Abandoning run as host");
			NetHostGameService netHostGameService = (NetHostGameService)_netService;
			netHostGameService.SendMessage(default(RunAbandonedMessage));
			_lobbyListener.RunAbandoned();
			_netService.Disconnect(NetError.HostAbandoned);
		}

		private void HandleRunAbandonedMessage(RunAbandonedMessage message, ulong _)
		{
			_logger.Debug("Received RunAbandonedMessage");
			_lobbyListener.RunAbandoned();
			_netService.Disconnect(NetError.HostAbandoned);
		}

		private void OnConnectedToClientAsHost(ulong playerId)
		{
			_logger.Info($"Player {playerId} connected to host.");
			InitialGameInfoMessage message = new InitialGameInfoMessage
			{
				sessionState = RunSessionState.Running,
				gameMode = GameMode
			};
			if (_playerCollection.GetPlayer(playerId) == null)
			{
				_logger.Warn($"Client {playerId} connected but they are not in the run!");
				message.connectionFailureReason = ConnectionFailureReason.RunInProgress;
				_netService.SendMessage(message, playerId);
				NetHostGameService netHostGameService = (NetHostGameService)_netService;
				netHostGameService.DisconnectClient(playerId, NetError.RunInProgress);
			}
			else
			{
				_netService.SendMessage(message, playerId);
			}
		}

		private void OnDisconnectedFromClientAsHost(ulong playerId, NetErrorInfo info)
		{
			int num = Players.FindIndex((RunLobbyPlayer p) => p.id == playerId);
			_logger.Info($"Player {playerId} disconnected from host. Is in connected players: {num >= 0}. Reason: {info.GetReason()}");
			if (num >= 0)
			{
				PlayerLeftMessage message = new PlayerLeftMessage
				{
					playerId = playerId
				};
				_netService.SendMessage(message);
				Players.RemoveAt(num);
				RemotePlayerDisconnected?.Invoke(playerId);
			}
		}

		private void OnDisconnected(NetErrorInfo info)
		{
			_logger.Info($"Disconnected. Reason: {info.GetReason()}");
			Players.Clear();
			_lobbyListener.LocalPlayerDisconnected(info);
			LocalPlayerDisconnected?.Invoke();
		}
	}
	/// <summary>
	/// Class which handles the connection flow for players beginning a new run.
	/// Exists before Run does, and provides player data to start a multiplayer run.
	/// <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.RunLobby" /> handles player connection and disconnection after the run begins.
	/// </summary>
	public class StartRunLobby
	{
		private struct ConnectingPlayer : IEquatable<ConnectingPlayer>
		{
			public ulong id;

			public CancellationTokenSource timeoutCancelToken;

			public bool Equals(ConnectingPlayer other)
			{
				if (id == other.id)
				{
					return timeoutCancelToken.Equals(other.timeoutCancelToken);
				}
				return false;
			}

			public override bool Equals(object? obj)
			{
				if (obj is ConnectingPlayer other)
				{
					return Equals(other);
				}
				return false;
			}

			public override int GetHashCode()
			{
				return HashCode.Combine(id, timeoutCancelToken);
			}
		}

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		/// <summary>
		/// Contains players who are in the process of connecting, but have not yet fully connected. Only set on host.
		/// </summary>
		private readonly List<ConnectingPlayer> _connectingPlayers = new List<ConnectingPlayer>();

		/// <summary>
		/// Set to true when the run starts, but the lobby is still listening for messages
		/// </summary>
		private bool _isBeginningRun;

		private readonly int _maxPlayers;

		private readonly List<ModifierModel> _modifiers = new List<ModifierModel>();

		public INetGameService NetService { get; }

		public IStartRunLobbyListener LobbyListener { get; }

		public PeerInputSynchronizer InputSynchronizer { get; }

		public int Ascension { get; private set; }

		public int MaxAscension { get; private set; }

		public string? Seed { get; private set; }

		public TimeServerResult? DailyTime { get; private set; }

		public GameMode GameMode { get; private set; }

		public IReadOnlyList<ModifierModel> Modifiers => _modifiers;

		/// <summary>
		/// If we are the host, this is the amount of time we give clients to send the initial message response in
		/// milliseconds. Public for tests.
		/// </summary>
		public int ClientResponseTimeout { get; set; } = 10000;

		/// <summary>
		/// TEMPORARY way for the host to manually specify which ActModel they want for act 1.
		/// </summary>
		public string Act1 { get; set; } = "random";

		public List<StartRunLobbyPlayer> Players { get; } = new List<StartRunLobbyPlayer>();

		public StartRunLobbyPlayer LocalPlayer => Players.Find((StartRunLobbyPlayer p) => p.id == NetService.NetId);

		public event Action<StartRunLobbyPlayer>? PlayerConnected;

		public event Action<StartRunLobbyPlayer>? PlayerDisconnected;

		/// <summary>
		/// Provides extended disconnection info to UI, but only when the local player is the host.
		/// </summary>
		public event Action<ulong, NetErrorInfo>? PlayerFailedToConnect;

		public StartRunLobby(GameMode gameMode, INetGameService netService, IStartRunLobbyListener lobbyListener, int maxPlayers)
		{
			GameMode = gameMode;
			NetService = netService;
			LobbyListener = lobbyListener;
			_maxPlayers = maxPlayers;
			InputSynchronizer = new PeerInputSynchronizer(netService);
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("StartRunLobby", LogType.Network);
			NetService.RegisterMessageHandler<ClientLobbyJoinRequestMessage>(HandleClientLobbyJoinRequestMessage);
			NetService.RegisterMessageHandler<ClientLoadJoinRequestMessage>(HandleClientLoadJoinRequestMessage);
			NetService.RegisterMessageHandler<ClientRejoinRequestMessage>(HandleClientRejoinRequestMessage);
			NetService.RegisterMessageHandler<PlayerJoinedMessage>(HandlePlayerJoinedMessage);
			NetService.RegisterMessageHandler<PlayerLeftMessage>(HandlePlayerLeftMessage);
			NetService.RegisterMessageHandler<LobbyPlayerChangedCharacterMessage>(HandleLobbyPlayerChangedCharacterMessage);
			NetService.RegisterMessageHandler<LobbyAscensionChangedMessage>(HandleAscensionChangedMessage);
			NetService.RegisterMessageHandler<LobbySeedChangedMessage>(HandleSeedChangedMessage);
			NetService.RegisterMessageHandler<LobbyModifiersChangedMessage>(HandleModifiersChangedMessage);
			NetService.RegisterMessageHandler<LobbyPlayerSetReadyMessage>(HandlePlayerReadyMessage);
			NetService.RegisterMessageHandler<LobbyBeginRunMessage>(HandleLobbyBeginRunMessage);
			NetService.Disconnected += OnDisconnected;
			if (NetService.Type == NetGameType.Host)
			{
				INetHostGameService netHostGameService = (INetHostGameService)netService;
				netHostGameService.ClientConnected += OnConnectedToClientAsHost;
				netHostGameService.ClientDisconnected += OnDisconnectedFromClientAsHost;
				netHostGameService.ClientConnectionFailed += OnClientConnectionFailed;
			}
		}

		public StartRunLobby(GameMode gameMode, INetGameService netService, IStartRunLobbyListener lobbyListener, TimeServerResult timeServerResult, int maxPlayers)
			: this(gameMode, netService, lobbyListener, maxPlayers)
		{
			DailyTime = timeServerResult;
		}

		public void InitializeFromMessage(ClientLobbyJoinResponseMessage message)
		{
			foreach (StartRunLobbyPlayer item in message.playersInLobby)
			{
				Players.Add(item);
			}
			_modifiers.Clear();
			_modifiers.AddRange(message.modifiers.Select(ModifierModel.FromSerializable));
			Ascension = message.ascension;
			UpdateMaxMultiplayerAscension();
			Seed = message.seed;
			LobbyListener.PlayerConnected(LocalPlayer);
			PlayerConnected?.Invoke(LocalPlayer);
		}

		/// <summary>
		/// This should be called to cleanup the lobby before exiting the lobby screen.
		/// </summary>
		/// <param name="disconnectSession">
		/// If true, the net service will be disconnected. Pass true if the lobby is being closed rather than transitioning
		/// to a run.
		/// </param>
		/// <param name="error">If disconnectSession is true, this is the error that is sent to clients.</param>
		public void CleanUp(bool disconnectSession, NetError error = NetError.Quit)
		{
			NetService.UnregisterMessageHandler<ClientLobbyJoinRequestMessage>(HandleClientLobbyJoinRequestMessage);
			NetService.UnregisterMessageHandler<ClientLoadJoinRequestMessage>(HandleClientLoadJoinRequestMessage);
			NetService.UnregisterMessageHandler<ClientRejoinRequestMessage>(HandleClientRejoinRequestMessage);
			NetService.UnregisterMessageHandler<PlayerJoinedMessage>(HandlePlayerJoinedMessage);
			NetService.UnregisterMessageHandler<PlayerLeftMessage>(HandlePlayerLeftMessage);
			NetService.UnregisterMessageHandler<LobbyPlayerChangedCharacterMessage>(HandleLobbyPlayerChangedCharacterMessage);
			NetService.UnregisterMessageHandler<LobbyAscensionChangedMessage>(HandleAscensionChangedMessage);
			NetService.UnregisterMessageHandler<LobbySeedChangedMessage>(HandleSeedChangedMessage);
			NetService.UnregisterMessageHandler<LobbyModifiersChangedMessage>(HandleModifiersChangedMessage);
			NetService.UnregisterMessageHandler<LobbyPlayerSetReadyMessage>(HandlePlayerReadyMessage);
			NetService.UnregisterMessageHandler<LobbyBeginRunMessage>(HandleLobbyBeginRunMessage);
			if (disconnectSession)
			{
				if (NetService.IsConnected)
				{
					NetService.Disconnect(error);
				}
				InputSynchronizer.Dispose();
			}
			NetService.Disconnected -= OnDisconnected;
			if (NetService.Type == NetGameType.Host)
			{
				INetHostGameService netHostGameService = (INetHostGameService)NetService;
				netHostGameService.ClientConnected -= OnConnectedToClientAsHost;
				netHostGameService.ClientDisconnected -= OnDisconnectedFromClientAsHost;
				netHostGameService.ClientConnectionFailed -= OnClientConnectionFailed;
			}
		}

		/// <summary>
		/// Should be called when the lobby opens on the host player's side to generate the host's lobby player.
		/// </summary>
		public StartRunLobbyPlayer? AddLocalHostPlayer(UnlockState unlocks, int maxMultiplayerAscension)
		{
			if (NetService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Tried to add local host player as client!");
			}
			_logger.Context = $"{"StartRunLobby"} ({NetService.NetId})";
			SerializableUnlockState unlockState = unlocks.ToSerializable();
			return AddLocalHostPlayerInternal(unlockState, maxMultiplayerAscension);
		}

		/// <summary>
		/// For use in tests and internally in this class.
		/// </summary>
		public StartRunLobbyPlayer? AddLocalHostPlayerInternal(SerializableUnlockState unlockState, int maxMultiplayerAscension)
		{
			StartRunLobbyPlayer? result = TryAddPlayerInFirstAvailableSlot(unlockState, maxMultiplayerAscension, NetService.LocalVersion.IsModded(), NetService.NetId);
			if (result.HasValue)
			{
				LobbyListener.PlayerConnected(result.Value);
				PlayerConnected?.Invoke(result.Value);
			}
			UpdateMaxMultiplayerAscension();
			return result;
		}

		private void HandleClientLobbyJoinRequestMessage(ClientLobbyJoinRequestMessage message, ulong senderId)
		{
			if (NetService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientLobbyJoinRequestMessage as non-host!");
			}
			INetHostGameService netHostGameService = (INetHostGameService)NetService;
			try
			{
				if (Players.Count >= _maxPlayers)
				{
					_logger.Warn($"Client {senderId} sent ClientLobbyJoinRequestMessage but we are at maximum players!");
					netHostGameService.DisconnectClient(senderId, NetError.LobbyFull);
					return;
				}
				_logger.Info($"Received ClientLobbyJoinRequestMessage for {senderId}");
				StartRunLobbyPlayer? startRunLobbyPlayer = TryAddPlayerInFirstAvailableSlot(message.unlockState, message.maxAscensionUnlocked, netHostGameService.GetVersionInfoForPeer(senderId).Value.IsModded(), senderId);
				if (!startRunLobbyPlayer.HasValue)
				{
					return;
				}
				UpdateMaxMultiplayerAscension();
				ClientLobbyJoinResponseMessage message2 = new ClientLobbyJoinResponseMessage
				{
					playersInLobby = Players,
					ascension = Ascension,
					dailyTime = DailyTime,
					seed = Seed,
					modifiers = Modifiers.Select((ModifierModel m) => m.ToSerializable()).ToList()
				};
				_logger.Debug($"Sending ClientLobbyJoinResponseMessage length ({message2.playersInLobby.Count}) to ({startRunLobbyPlayer.Value.id})");
				netHostGameService.SendMessage(message2, senderId);
				netHostGameService.SetPeerReadyForBroadcasting(senderId);
				PlayerJoinedMessage message3 = new PlayerJoinedMessage
				{
					lobbyPlayer = startRunLobbyPlayer.Value
				};
				foreach (StartRunLobbyPlayer player in Players)
				{
					if (player.id != NetService.NetId && player.id != startRunLobbyPlayer.Value.id)
					{
						NetService.SendMessage(message3, player.id);
					}
				}
				RemoveConnectingPlayer(startRunLobbyPlayer.Value.id);
				LobbyListener.PlayerConnected(startRunLobbyPlayer.Value);
				PlayerConnected?.Invoke(startRunLobbyPlayer.Value);
			}
			catch
			{
				netHostGameService.DisconnectClient(senderId, NetError.InternalError);
				throw;
			}
		}

		private void UpdateMaxMultiplayerAscension()
		{
			int num = Players.Min((StartRunLobbyPlayer p) => p.maxMultiplayerAscensionUnlocked);
			if (num != MaxAscension)
			{
				MaxAscension = num;
				LobbyListener.MaxAscensionChanged();
				if (Ascension > MaxAscension && NetService.Type == NetGameType.Host)
				{
					SyncAscensionChange(MaxAscension);
				}
			}
		}

		private void HandleClientLoadJoinRequestMessage(ClientLoadJoinRequestMessage _, ulong senderId)
		{
			if (NetService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientLoadJoinRequestMessage as non-host!");
			}
			_logger.Info($"Received invalid ClientLoadJoinRequestMessage for {senderId}");
			NetHostGameService netHostGameService = (NetHostGameService)NetService;
			netHostGameService.DisconnectClient(senderId, NetError.InvalidJoin);
		}

		private void HandleClientRejoinRequestMessage(ClientRejoinRequestMessage _, ulong senderId)
		{
			if (NetService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received ClientRejoinRequestMessage as non-host!");
			}
			_logger.Info($"Received invalid ClientRejoinRequestMessage for {senderId}");
			NetHostGameService netHostGameService = (NetHostGameService)NetService;
			netHostGameService.DisconnectClient(senderId, NetError.InvalidJoin);
		}

		private void HandlePlayerJoinedMessage(PlayerJoinedMessage message, ulong senderId)
		{
			_logger.Debug($"Received PlayerJoinedMessage with ({message.lobbyPlayer})");
			Players.Add(message.lobbyPlayer);
			LobbyListener.PlayerConnected(message.lobbyPlayer);
			PlayerConnected?.Invoke(message.lobbyPlayer);
			UpdateMaxMultiplayerAscension();
		}

		private void HandlePlayerLeftMessage(PlayerLeftMessage message, ulong senderId)
		{
			_logger.Debug($"Received PlayerLeftMessage for {message.playerId}");
			int num = Players.FindIndex((StartRunLobbyPlayer p) => p.id == message.playerId);
			if (num >= 0)
			{
				StartRunLobbyPlayer startRunLobbyPlayer = Players[num];
				Players.RemoveAt(num);
				InputSynchronizer.OnPlayerDisconnected(startRunLobbyPlayer.id);
				LobbyListener.RemotePlayerDisconnected(startRunLobbyPlayer);
				PlayerDisconnected?.Invoke(startRunLobbyPlayer);
			}
		}

		private void HandleLobbyPlayerChangedCharacterMessage(LobbyPlayerChangedCharacterMessage message, ulong senderId)
		{
			_logger.Debug($"Received LobbyPlayerChangedCharacterMessage for {senderId} {message.character}");
			ChangeCharacter(senderId, message.character);
		}

		private void HandleAscensionChangedMessage(LobbyAscensionChangedMessage message, ulong _)
		{
			if (_isBeginningRun)
			{
				Log.Warn($"Received AscensionChangedMessage with ascension {message.ascension} while run was already starting! Ignoring");
			}
			else
			{
				_logger.Debug($"Received AscensionChangedMessage, new ascension: {message.ascension}");
				Ascension = message.ascension;
				LobbyListener.AscensionChanged();
			}
		}

		private void HandleSeedChangedMessage(LobbySeedChangedMessage message, ulong _)
		{
			if (_isBeginningRun)
			{
				Log.Warn("Received SeedChangedMessage with seed " + message.seed + " while run was already starting! Ignoring");
				return;
			}
			_logger.Debug("Received SeedChangedMessage, new seed: " + message.seed);
			Seed = message.seed;
			LobbyListener.SeedChanged();
		}

		private void HandleModifiersChangedMessage(LobbyModifiersChangedMessage message, ulong _)
		{
			_logger.Debug("Received ModifiersChangedMessage, new modifiers: " + string.Join(",", message.modifiers.Select((SerializableModifier m) => m.Id)));
			if (_isBeginningRun)
			{
				Log.Warn($"Received ModifiersChangedMessage with {message.modifiers.Count} while run was already starting! Ignoring");
			}
			else
			{
				_modifiers.Clear();
				_modifiers.AddRange(message.modifiers.Select(ModifierModel.FromSerializable));
				LobbyListener.ModifiersChanged();
			}
		}

		private void HandlePlayerReadyMessage(LobbyPlayerSetReadyMessage message, ulong senderId)
		{
			_logger.Debug($"Received LobbyPlayerSetReadyMessage for player {senderId} with value {message.ready}");
			int num = Players.FindIndex((StartRunLobbyPlayer p) => p.id == senderId);
			if (num >= 0)
			{
				StartRunLobbyPlayer startRunLobbyPlayer = Players[num];
				startRunLobbyPlayer.isReady = message.ready;
				Players[num] = startRunLobbyPlayer;
				LobbyListener.PlayerChanged(startRunLobbyPlayer, isRandomCharacterResolution: false);
				BeginRunForAllPlayersIfAllReady();
			}
		}

		private void HandleLobbyBeginRunMessage(LobbyBeginRunMessage message, ulong senderId)
		{
			_logger.Debug("Received LobbyBeginRunMessage");
			Players.Clear();
			Players.AddRange(message.playersInLobby);
			Act1 = message.act1;
			BeginRunLocally(message.seed, message.modifiers.Select(ModifierModel.FromSerializable).ToList());
		}

		private void ChangeCharacter(ulong playerId, CharacterModel character, bool isRandomCharacterResolution = false)
		{
			if (_isBeginningRun)
			{
				Log.Warn($"Player {playerId} tried to change character while run was already starting! Ignoring");
				return;
			}
			int num = Players.FindIndex((StartRunLobbyPlayer p) => p.id == playerId);
			if (num >= 0)
			{
				StartRunLobbyPlayer startRunLobbyPlayer = Players[num];
				startRunLobbyPlayer.character = character;
				Players[num] = startRunLobbyPlayer;
				LobbyListener.PlayerChanged(startRunLobbyPlayer, isRandomCharacterResolution);
			}
		}

		private void BeginRunForAllPlayers(string seed, List<ModifierModel> modifiers)
		{
			if (NetService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Can only begin run as host!");
			}
			if (_isBeginningRun)
			{
				_logger.Warn("Tried to begin run twice, ignoring second one!");
				return;
			}
			UpdatePreferredAscension();
			LobbyBeginRunMessage message = new LobbyBeginRunMessage
			{
				playersInLobby = Players,
				seed = seed,
				modifiers = modifiers.Select((ModifierModel m) => m.ToSerializable()).ToList(),
				act1 = Act1
			};
			NetService.SendMessage(message);
			BeginRunLocally(seed, modifiers);
			if (NetService.Type == NetGameType.Host)
			{
				INetHostGameService netHostGameService = (INetHostGameService)NetService;
				netHostGameService.NetHost?.SetHostIsClosed(isClosed: true);
			}
		}

		private void BeginRunLocally(string seed, List<ModifierModel> modifiers)
		{
			Rng rng = new Rng(StringHelper.GetDeterministicHashCode(seed), "act_selection");
			List<ActModel> list = ActModel.GetRandomList(rng, GetUnlockState(), NetService.Type.IsMultiplayer()).ToList();
			list[0] = GetAct(Act1) ?? list[0];
			for (int i = 0; i < Players.Count; i++)
			{
				StartRunLobbyPlayer startRunLobbyPlayer = Players[i];
				if (startRunLobbyPlayer.character is RandomCharacter)
				{
					CharacterModel character = rng.NextItem(ModelDb.AllCharacters);
					ChangeCharacter(startRunLobbyPlayer.id, character, isRandomCharacterResolution: true);
				}
			}
			if (NetService.Type == NetGameType.Singleplayer)
			{
				CharacterStats orCreateCharacterStats = SaveManager.Instance.Progress.GetOrCreateCharacterStats(Players[0].character.Id);
				int num = Math.Min(Ascension, orCreateCharacterStats.MaxAscension);
				if (Ascension != num)
				{
					Ascension = num;
					LobbyListener.AscensionChanged();
				}
				if (MaxAscension != orCreateCharacterStats.MaxAscension)
				{
					MaxAscension = orCreateCharacterStats.MaxAscension;
					LobbyListener.MaxAscensionChanged();
				}
			}
			NetService.SetBufferMessages(bufferMessages: true);
			_isBeginningRun = true;
			LobbyListener.BeginRun(seed, list, modifiers);
		}

		private static ActModel? GetAct(string act1Key)
		{
			if (!(act1Key == "overgrowth"))
			{
				if (act1Key == "underdocks")
				{
					return ModelDb.Act<Underdocks>();
				}
				return null;
			}
			return ModelDb.Act<Overgrowth>();
		}

		private void SetSingleplayerAscensionAfterCharacterChanged(ModelId characterId)
		{
			if (NetService.Type.IsMultiplayer())
			{
				return;
			}
			CharacterStats orCreateCharacterStats = SaveManager.Instance.Progress.GetOrCreateCharacterStats(characterId);
			bool flag = IsAscensionEpochRevealed(characterId);
			if (characterId == ModelDb.GetId<RandomCharacter>())
			{
				MaxAscension = GetMaxAscensionAcrossAllCharacters();
				SyncAscensionChange(Math.Min(orCreateCharacterStats.PreferredAscension, MaxAscension));
				LobbyListener.MaxAscensionChanged();
				_logger.Info($"{characterId} ascension set to Max: {Ascension}");
			}
			else if (orCreateCharacterStats == null || orCreateCharacterStats.MaxAscension <= 0 || !flag)
			{
				MaxAscension = 0;
				SyncAscensionChange(0);
				LobbyListener.MaxAscensionChanged();
				if (!flag)
				{
					_logger.Info($"{characterId} has not revealed the Ascension Epoch, disabling Ascension.");
				}
				else
				{
					_logger.Info($"{characterId} has no progress, disabling Ascension.");
				}
			}
			else
			{
				MaxAscension = orCreateCharacterStats.MaxAscension;
				SyncAscensionChange(Math.Min(orCreateCharacterStats.PreferredAscension, orCreateCharacterStats.MaxAscension));
				LobbyListener.MaxAscensionChanged();
				_logger.Info($"{characterId} ascension set to preferred: {Ascension}");
			}
			if (GameMode == GameMode.Standard && GetMaxAscensionAcrossAllCharacters() > 0 && !SaveManager.Instance.SeenPopup("ascension_singleplayer_ftue"))
			{
				NAscensionSingleplayerFtue nAscensionSingleplayerFtue = NAscensionSingleplayerFtue.Create();
				if (nAscensionSingleplayerFtue != null)
				{
					NModalContainer.Instance.Add(nAscensionSingleplayerFtue);
				}
			}
		}

		private int GetMaxAscensionAcrossAllCharacters()
		{
			int num = 0;
			foreach (CharacterStats value in SaveManager.Instance.Progress.CharacterStats.Values)
			{
				num = Math.Max(num, value.MaxAscension);
			}
			return num;
		}

		private bool IsAscensionEpochRevealed(ModelId characterId)
		{
			if (characterId == ModelDb.GetId<Ironclad>())
			{
				return SaveManager.Instance.IsEpochRevealed<Ironclad4Epoch>();
			}
			if (characterId == ModelDb.GetId<Silent>())
			{
				return SaveManager.Instance.IsEpochRevealed<Silent4Epoch>();
			}
			if (characterId == ModelDb.GetId<Regent>())
			{
				return SaveManager.Instance.IsEpochRevealed<Regent4Epoch>();
			}
			if (characterId == ModelDb.GetId<Defect>())
			{
				return SaveManager.Instance.IsEpochRevealed<Defect4Epoch>();
			}
			if (characterId == ModelDb.GetId<Necrobinder>())
			{
				return SaveManager.Instance.IsEpochRevealed<Necrobinder4Epoch>();
			}
			return true;
		}

		/// <summary>
		/// Updates the preferred Ascension.
		/// </summary>
		private void UpdatePreferredAscension()
		{
			if (GameMode == GameMode.Daily)
			{
				return;
			}
			if (NetService.Type == NetGameType.Singleplayer)
			{
				if (Players.Count != 0)
				{
					CharacterStats orCreateCharacterStats = SaveManager.Instance.Progress.GetOrCreateCharacterStats(LocalPlayer.character.Id);
					if ((orCreateCharacterStats.MaxAscension != 0 || !(orCreateCharacterStats.Id != ModelDb.Character<RandomCharacter>().Id)) && orCreateCharacterStats.PreferredAscension != Ascension)
					{
						_logger.Info($"Setting preferred Ascension for {LocalPlayer.character.Id} to {Ascension}");
						orCreateCharacterStats.PreferredAscension = Ascension;
						SaveManager.Instance.SaveProgressFile();
					}
				}
			}
			else if (NetService.Type == NetGameType.Host)
			{
				ProgressState progress = SaveManager.Instance.Progress;
				if (progress.PreferredMultiplayerAscension != Ascension)
				{
					_logger.Info($"Setting preferred multiplayer ascension to {Ascension}");
					progress.PreferredMultiplayerAscension = Ascension;
					SaveManager.Instance.SaveProgressFile();
				}
			}
		}

		/// <summary>
		/// Sets the character chosen by the local player and replicates that to all peers.
		/// </summary>
		/// <param name="character"></param>
		public void SetLocalCharacter(CharacterModel character)
		{
			ChangeCharacter(NetService.NetId, character);
			LobbyPlayerChangedCharacterMessage message = new LobbyPlayerChangedCharacterMessage
			{
				character = character
			};
			NetService.SendMessage(message);
			SetSingleplayerAscensionAfterCharacterChanged(character.Id);
		}

		/// <summary>
		/// Sets the seed to use for the run.
		/// This can only be called as host or singleplayer. Calling it on the client will throw an exception and have no
		/// effect. The seed is synced to the clients for display use, but the final seed that is used is sent in the
		/// <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Messages.Lobby.LobbyBeginRunMessage" />.
		/// </summary>
		public void SetSeed(string? seed)
		{
			NetGameType type = NetService.Type;
			if ((uint)(type - 1) > 1u)
			{
				throw new InvalidOperationException("Can only be called on host or singleplayer");
			}
			Seed = seed;
			LobbySeedChangedMessage message = new LobbySeedChangedMessage
			{
				seed = seed
			};
			NetService.SendMessage(message);
			LobbyListener.SeedChanged();
		}

		/// <summary>
		/// Sets the modifiers to use for the run.
		/// This can only be called as host or singleplayer. Calling it on the client will throw an exception and have no
		/// effect. The seed is synced to the clients for display use, but the final seed that is used is sent in the
		/// <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Messages.Lobby.LobbyBeginRunMessage" />.
		/// </summary>
		public void SetModifiers(IReadOnlyCollection<ModifierModel> modifiers)
		{
			NetGameType type = NetService.Type;
			if ((uint)(type - 1) > 1u)
			{
				throw new InvalidOperationException("Can only be called on host or singleplayer");
			}
			if (_isBeginningRun)
			{
				Log.Warn("Tried to change modifiers while run was already starting! Ignoring");
				return;
			}
			_modifiers.Clear();
			_modifiers.AddRange(modifiers);
			LobbyModifiersChangedMessage message = new LobbyModifiersChangedMessage
			{
				modifiers = modifiers.Select((ModifierModel m) => m.ToSerializable()).ToList()
			};
			NetService.SendMessage(message);
			LobbyListener.ModifiersChanged();
		}

		/// <summary>
		/// Sets the local player to be ready or unready and syncs the state to all peers.
		/// This is called for both Singleplayer and Multiplayer (singleplayer uses a local lobby).
		/// </summary>
		/// <param name="ready"></param>
		public void SetReady(bool ready)
		{
			int num = Players.FindIndex((StartRunLobbyPlayer p) => p.id == NetService.NetId);
			if (num < 0)
			{
				throw new InvalidOperationException("Tried to set local player ready, but they are not in the list of players in the lobby!");
			}
			if (_isBeginningRun)
			{
				Log.Warn("Tried to set ready while run was already starting! Ignoring");
				return;
			}
			StartRunLobbyPlayer value = Players[num];
			value.isReady = ready;
			Players[num] = value;
			LobbyPlayerSetReadyMessage message = new LobbyPlayerSetReadyMessage
			{
				ready = ready
			};
			NetService.SendMessage(message);
			LobbyListener.PlayerChanged(LocalPlayer, isRandomCharacterResolution: false);
			_logger.Info($"Local player {LocalPlayer.id} is ready");
			BeginRunForAllPlayersIfAllReady();
		}

		private void BeginRunForAllPlayersIfAllReady()
		{
			if (IsAboutToBeginGame())
			{
				NetGameType type = NetService.Type;
				if ((uint)(type - 1) <= 1u)
				{
					string seed = ((NGame.Instance?.DebugSeedOverride != null) ? NGame.Instance.DebugSeedOverride : ((Seed == null) ? SeedHelper.GetRandomSeed() : SeedHelper.CanonicalizeSeed(Seed)));
					BeginRunForAllPlayers(seed, _modifiers);
				}
			}
		}

		public bool IsAboutToBeginGame()
		{
			if (_connectingPlayers.Count > 0)
			{
				return false;
			}
			if (NetService.Type.IsMultiplayer() && Players.Count == 1)
			{
				return false;
			}
			if (!Players.All((StartRunLobbyPlayer p) => p.isReady))
			{
				return false;
			}
			return true;
		}

		/// <summary>
		/// Sets the ascension level. Should only be called on the host.
		/// </summary>
		public void SyncAscensionChange(int ascension)
		{
			if (NetService.Type == NetGameType.Client)
			{
				throw new InvalidOperationException("Client attempted to change ascension level!");
			}
			if (Ascension != ascension)
			{
				if (_isBeginningRun)
				{
					Log.Warn($"Tried to set ascension to {ascension} while run was already starting! Ignoring");
				}
				else
				{
					Ascension = ascension;
					LobbyAscensionChangedMessage message = new LobbyAscensionChangedMessage
					{
						ascension = ascension
					};
					NetService.SendMessage(message);
					UpdatePreferredAscension();
					LobbyListener.AscensionChanged();
				}
			}
		}

		private StartRunLobbyPlayer? TryAddPlayerInFirstAvailableSlot(SerializableUnlockState unlockState, int maxAscensionUnlocked, bool isModded, ulong playerId)
		{
			int num = -1;
			int i;
			for (i = 0; i < _maxPlayers; i++)
			{
				int num2 = Players.FindIndex((StartRunLobbyPlayer p) => p.slotId == i);
				if (num2 < 0)
				{
					num = i;
					break;
				}
			}
			if (num < 0)
			{
				return null;
			}
			StartRunLobbyPlayer startRunLobbyPlayer = new StartRunLobbyPlayer
			{
				character = ModelDb.Character<Ironclad>(),
				id = playerId,
				slotId = num,
				maxMultiplayerAscensionUnlocked = maxAscensionUnlocked,
				unlockState = unlockState,
				isModded = isModded
			};
			Players.Add(startRunLobbyPlayer);
			return startRunLobbyPlayer;
		}

		private void OnConnectedToClientAsHost(ulong playerId)
		{
			_logger.Info($"Client {playerId} connected. Sending initial game info message");
			InitialGameInfoMessage message = new InitialGameInfoMessage
			{
				sessionState = RunSessionState.InLobby,
				gameMode = GameMode
			};
			if (_isBeginningRun)
			{
				message.connectionFailureReason = ConnectionFailureReason.RunInProgress;
				NetService.SendMessage(message, playerId);
				_logger.Warn($"Client {playerId} connected but we are already beginning the run!");
				((NetHostGameService)NetService).DisconnectClient(playerId, NetError.RunInProgress);
			}
			else if (Players.Count >= _maxPlayers)
			{
				message.connectionFailureReason = ConnectionFailureReason.LobbyFull;
				NetService.SendMessage(message, playerId);
				_logger.Warn($"Client {playerId} connected but we are at maximum players!");
				((NetHostGameService)NetService).DisconnectClient(playerId, NetError.LobbyFull);
			}
			else
			{
				ConnectingPlayer connectingPlayer = new ConnectingPlayer
				{
					id = playerId,
					timeoutCancelToken = new CancellationTokenSource()
				};
				_connectingPlayers.Add(connectingPlayer);
				NetService.SendMessage(message, playerId);
				TaskHelper.RunSafely(BeginClientResponseTimeout(connectingPlayer));
			}
		}

		private async Task BeginClientResponseTimeout(ConnectingPlayer connectingPlayer)
		{
			await Task.Delay(ClientResponseTimeout, connectingPlayer.timeoutCancelToken.Token);
			if (!connectingPlayer.timeoutCancelToken.IsCancellationRequested)
			{
				int num = _connectingPlayers.IndexOf(connectingPlayer);
				if (num >= 0)
				{
					_logger.Info($"Disconnecting player {connectingPlayer.id} because they did not respond to the initial game join message within {ClientResponseTimeout}ms");
					INetHostGameService netHostGameService = (INetHostGameService)NetService;
					netHostGameService.DisconnectClient(connectingPlayer.id, NetError.LobbyJoinTimeout);
				}
			}
		}

		private void OnDisconnectedFromClientAsHost(ulong playerId, NetErrorInfo info)
		{
			_logger.Info($"Client {playerId} disconnected, reason: {info.GetReason()}");
			RemoveConnectingPlayer(playerId);
			int num = Players.FindIndex((StartRunLobbyPlayer p) => p.id == playerId);
			if (num < 0)
			{
				_logger.Info($"Player {playerId} not found in players list. Assuming they disconnected before sending the initial message response");
				return;
			}
			StartRunLobbyPlayer startRunLobbyPlayer = Players[num];
			PlayerLeftMessage message = new PlayerLeftMessage
			{
				playerId = playerId
			};
			NetService.SendMessage(message);
			Players.RemoveAt(num);
			InputSynchronizer.OnPlayerDisconnected(startRunLobbyPlayer.id);
			LobbyListener.RemotePlayerDisconnected(startRunLobbyPlayer);
			PlayerDisconnected?.Invoke(startRunLobbyPlayer);
			UpdateMaxMultiplayerAscension();
			BeginRunForAllPlayersIfAllReady();
		}

		private void OnClientConnectionFailed(ulong playerId, NetErrorInfo info)
		{
			PlayerFailedToConnect?.Invoke(playerId, info);
		}

		private UnlockState GetUnlockState()
		{
			if (GameMode == GameMode.Daily)
			{
				return UnlockState.all;
			}
			return new UnlockState(Players.Select((StartRunLobbyPlayer p) => UnlockState.FromSerializable(p.unlockState)));
		}

		private void RemoveConnectingPlayer(ulong playerId)
		{
			for (int i = 0; i < _connectingPlayers.Count; i++)
			{
				if (_connectingPlayers[i].id == playerId)
				{
					_connectingPlayers[i].timeoutCancelToken.Cancel();
					_logger.Info($"Cancel initial message timeout for {playerId}");
					_connectingPlayers.RemoveAt(i);
					i--;
				}
			}
		}

		private void OnDisconnected(NetErrorInfo info)
		{
			_logger.Info($"Disconnected from host, reason: {info.GetReason()}");
			LobbyListener.LocalPlayerDisconnected(info);
		}
	}
}
namespace MegaCrit.Sts2.Core.Multiplayer.Connection
{
	public class ClientConnectionFailedException : Exception
	{
		public NetErrorInfo info;

		public ClientConnectionFailedException(string message, NetErrorInfo info)
			: base(message)
		{
			this.info = info;
		}
	}
	public class ENetClientConnectionInitializer : IClientConnectionInitializer
	{
		private readonly ulong _netId;

		private readonly string _ip;

		private readonly ushort _port;

		public ENetClientConnectionInitializer(ulong netId, string ip, ushort port)
		{
			_netId = netId;
			_ip = ip;
			_port = port;
		}

		public async Task<NetErrorInfo?> Connect(INetClientGameService netService, CancellationToken cancelToken = default(CancellationToken))
		{
			if (netService.IsConnected)
			{
				throw new InvalidOperationException("NetClientGameService must not be connected when passed to ENetClientConnectionInitializer!");
			}
			ENetClient eNetClient = new ENetClient(netService);
			netService.Initialize(eNetClient, PlatformType.None);
			return await eNetClient.ConnectToHost(_netId, _ip, _port, cancelToken);
		}
	}
	public class HandshakeManager
	{
		private class HandshakeInProgress
		{
			public ulong peerId;

			public required CancellationTokenSource cts;
		}

		private const int _handshakeTimeoutMsec = 10000;

		public static TaskCompletionSource? skipTimeoutTcs;

		public static readonly byte[] magicBytes = "STS2"u8.ToArray();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		private readonly IHandshakeHandler _handler;

		private readonly PacketWriter _writer;

		private PeerVersionInfo _localVersionInfo;

		private List<HandshakeInProgress> _handshakesInProgress = new List<HandshakeInProgress>();

		public HandshakeManager(IHandshakeHandler handler, PeerVersionInfo localVersionInfo, PacketWriter writer)
		{
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("HandshakeManager", LogType.Network);
			_localVersionInfo = localVersionInfo;
			_handler = handler;
			_writer = writer;
		}

		public bool IsHandshaking(ulong senderId)
		{
			return _handshakesInProgress.Any((HandshakeInProgress h) => h.peerId == senderId);
		}

		public void HandshakeMessageReceived(ulong senderId, PacketReader reader)
		{
			HandshakeResult handshakeResult = TryReadHandshakeMessage(senderId, reader);
			if (handshakeResult.status != HandshakeStatus.InvalidHandshake)
			{
				_handshakesInProgress.RemoveAll((HandshakeInProgress h) => h.peerId == senderId);
				if (_handler.Type == NetGameType.Client)
				{
					WriteHandshakeMessage(senderId);
				}
			}
			if (handshakeResult.status == HandshakeStatus.Success)
			{
				_handler.HandshakeSucceeded(senderId, handshakeResult.remoteVersionInfo.Value);
			}
			else if (handshakeResult.status == HandshakeStatus.VersionMismatch)
			{
				_handler.HandshakeFailed(senderId, new NetErrorInfo(ConnectionFailureReason.VersionMismatch, handshakeResult.extraInfo));
			}
			else if (handshakeResult.status == HandshakeStatus.ModMismatch)
			{
				_handler.HandshakeFailed(senderId, new NetErrorInfo(ConnectionFailureReason.ModMismatch, handshakeResult.extraInfo));
			}
			else if (handshakeResult.status != HandshakeStatus.InvalidHandshake)
			{
				throw new ArgumentOutOfRangeException();
			}
		}

		private HandshakeResult TryReadHandshakeMessage(ulong senderId, PacketReader reader)
		{
			if (reader.Buffer.Length < magicBytes.Length)
			{
				return new HandshakeResult(HandshakeStatus.InvalidHandshake);
			}
			byte[] array = magicBytes;
			foreach (byte b in array)
			{
				if (reader.ReadByte() != b)
				{
					return new HandshakeResult(HandshakeStatus.InvalidHandshake);
				}
			}
			HandshakeInProgress handshakeInProgress = _handshakesInProgress.Find((HandshakeInProgress h) => h.peerId == senderId);
			if (handshakeInProgress == null)
			{
				Log.Warn($"Received handshake message for {senderId} who is not currently in the middle of a handshake!");
				return new HandshakeResult(HandshakeStatus.InvalidHandshake);
			}
			handshakeInProgress.cts.Cancel();
			PeerVersionInfo peerVersionInfo = default(PeerVersionInfo);
			if (!peerVersionInfo.TryDeserialize(reader))
			{
				Log.Warn($"Got a partial read on peer {senderId}'s handshake! Attempting to proceed");
			}
			ConnectionFailureExtraInfo connectionFailureExtraInfo = new ConnectionFailureExtraInfo
			{
				localInfo = _localVersionInfo,
				remoteInfo = peerVersionInfo,
				localIsHost = (_handler.Type != NetGameType.Client)
			};
			_logger.Info($"Got handshake from sender {senderId}. Version: {peerVersionInfo.version} Branch: {peerVersionInfo.branch} Hash: {peerVersionInfo.idDatabaseHash}");
			if (peerVersionInfo.version != _localVersionInfo.version)
			{
				Log.Error($"Version mismatch. Remote: {peerVersionInfo.version} Ours: {_localVersionInfo.version} Remote branch: {peerVersionInfo.branch}");
				return new HandshakeResult(HandshakeStatus.VersionMismatch, peerVersionInfo, connectionFailureExtraInfo);
			}
			List<string> missingModsOnRemote = connectionFailureExtraInfo.GetMissingModsOnRemote(nonGameplay: false);
			List<string> missingModsOnLocal = connectionFailureExtraInfo.GetMissingModsOnLocal(nonGameplay: false);
			if (missingModsOnLocal.Count > 0 || missingModsOnRemote.Count > 0)
			{
				_logger.Warn($"Mismatch in gameplay-relevant mods with the remote!\nMods that remote has that local does not: {string.Join(",", missingModsOnLocal)}.\nMods that local has that remote does not: {string.Join(",", missingModsOnRemote)}.");
				return new HandshakeResult(HandshakeStatus.ModMismatch, peerVersionInfo, connectionFailureExtraInfo);
			}
			if (peerVersionInfo.idDatabaseHash != _localVersionInfo.idDatabaseHash)
			{
				_logger.Warn("Our version " + _localVersionInfo.version + " matches the remote, but our Model ID hash does not!");
				return new HandshakeResult(HandshakeStatus.VersionMismatch, peerVersionInfo, connectionFailureExtraInfo);
			}
			List<string> missingModsOnRemote2 = connectionFailureExtraInfo.GetMissingModsOnRemote(nonGameplay: true);
			List<string> missingModsOnLocal2 = connectionFailureExtraInfo.GetMissingModsOnLocal(nonGameplay: true);
			if (missingModsOnRemote2.Count > 0 || missingModsOnLocal2.Count > 0)
			{
				_logger.Warn($"Mismatch in non-gameplay relevant mods. This is allowed, but it's up to the mod authors to guarantee that it doesn't break anything.\nNon-gameplay relevant mods that remote has that local does not: {string.Join(",", missingModsOnLocal2)}.\nNon-gameplay relevant mods that local has that remote does not: {string.Join(",", missingModsOnRemote2)}.");
			}
			return new HandshakeResult(HandshakeStatus.Success, peerVersionInfo, connectionFailureExtraInfo);
		}

		public void WriteHandshakeMessage(ulong peerId)
		{
			WriteHandshakeMessage(peerId, _localVersionInfo, _writer);
			_handler.SendHandshakeMessage(peerId, _writer);
		}

		public static void WriteHandshakeMessage(ulong peerId, PeerVersionInfo versionInfo, PacketWriter writer)
		{
			writer.Reset();
			writer.WriteBytes(magicBytes, magicBytes.Length);
			versionInfo.Serialize(writer);
		}

		public void BeginHandshakeFor(ulong peerId)
		{
			if (IsHandshaking(peerId))
			{
				throw new InvalidOperationException($"Tried to begin handshake for {peerId} who is already handshaking!");
			}
			CancellationTokenSource cts = new CancellationTokenSource();
			_handshakesInProgress.Add(new HandshakeInProgress
			{
				peerId = peerId,
				cts = cts
			});
			if (_handler.Type == NetGameType.Host)
			{
				WriteHandshakeMessage(peerId);
			}
			TaskHelper.RunSafely(TimeoutIfHandshakeNotReceived(peerId, cts));
		}

		public async Task TimeoutIfHandshakeNotReceived(ulong peerId, CancellationTokenSource cts)
		{
			Task task = Task.Delay(10000, cts.Token);
			if (skipTimeoutTcs == null)
			{
				await task;
			}
			else
			{
				await TaskHelper.WhenAny(task, skipTimeoutTcs.Task);
			}
			if (!cts.IsCancellationRequested)
			{
				AbortHandshake(peerId);
				_handler.HandshakeFailed(peerId, new NetErrorInfo(ConnectionFailureReason.HandshakeTimeout));
			}
		}

		public void AbortHandshake(ulong peerId)
		{
			for (int i = 0; i < _handshakesInProgress.Count; i++)
			{
				if (_handshakesInProgress[i].peerId == peerId)
				{
					_handshakesInProgress[i].cts.Cancel();
					_handshakesInProgress.RemoveAt(i);
					i--;
				}
			}
		}
	}
	public struct HandshakeResult
	{
		public HandshakeStatus status;

		public PeerVersionInfo? remoteVersionInfo;

		public ConnectionFailureExtraInfo? extraInfo;

		public HandshakeResult(HandshakeStatus status)
		{
			remoteVersionInfo = null;
			extraInfo = null;
			this.status = status;
		}

		public HandshakeResult(HandshakeStatus status, PeerVersionInfo versionInfo, ConnectionFailureExtraInfo extraInfo)
		{
			this.status = status;
			remoteVersionInfo = versionInfo;
			this.extraInfo = extraInfo;
		}
	}
	public enum HandshakeStatus
	{
		None,
		InvalidHandshake,
		VersionMismatch,
		ModMismatch,
		Success
	}
	public interface IClientConnectionInitializer
	{
		Task<NetErrorInfo?> Connect(INetClientGameService netService, CancellationToken cancelToken = default(CancellationToken));
	}
	public interface IHandshakeHandler
	{
		NetGameType Type { get; }

		void SendHandshakeMessage(ulong peerId, PacketWriter writer);

		void HandshakeFailed(ulong peerId, NetErrorInfo info);

		void HandshakeSucceeded(ulong peerId, PeerVersionInfo versionInfo);
	}
	public class SteamClientConnectionInitializer : IClientConnectionInitializer
	{
		private ulong? _playerSteamId;

		private ulong? _lobbySteamId;

		public static SteamClientConnectionInitializer FromPlayer(ulong playerSteamId)
		{
			return new SteamClientConnectionInitializer
			{
				_playerSteamId = playerSteamId
			};
		}

		public static SteamClientConnectionInitializer FromLobby(ulong lobbySteamId)
		{
			return new SteamClientConnectionInitializer
			{
				_lobbySteamId = lobbySteamId
			};
		}

		public async Task<NetErrorInfo?> Connect(INetClientGameService gameService, CancellationToken cancelToken = default(CancellationToken))
		{
			if (gameService.IsConnected)
			{
				throw new InvalidOperationException("NetClientGameService must not be connected when passed to SteamClientConnectionInitializer!");
			}
			MegaCrit.Sts2.Core.Multiplayer.Transport.Steam.SteamClient steamClient = new MegaCrit.Sts2.Core.Multiplayer.Transport.Steam.SteamClient(gameService);
			gameService.Initialize(steamClient, PlatformType.Steam);
			if (_playerSteamId.HasValue)
			{
				return await steamClient.ConnectToLobbyOwnedByFriend(_playerSteamId.Value, cancelToken);
			}
			if (_lobbySteamId.HasValue)
			{
				return await steamClient.ConnectToLobby(_lobbySteamId.Value, cancelToken);
			}
			throw new InvalidOperationException("Neither player nor lobby is set!");
		}

		public override string ToString()
		{
			return $"{"SteamClientConnectionInitializer"} player: {_playerSteamId} lobby: {_lobbySteamId}";
		}
	}
}
