	public enum MoveRepeatType
	{
		CanRepeatForever,
		CanRepeatXTimes,
		CannotRepeat,
		UseOnlyOnce
	}
}
namespace MegaCrit.Sts2.Core.MonsterMoves.MonsterMoveStateMachine
{
	public class ConditionalBranchState : MonsterState
	{
		private readonly struct ConditionalBranch(MonsterState state, Func<bool> condition)
		{
			public readonly string id = state.Id;

			private readonly Func<bool> _conditionalLambda = condition;

			public float Evaluate()
			{
				if (_conditionalLambda != null)
				{
					return _conditionalLambda() ? 1 : 0;
				}
				return 1f;
			}
		}

		public string BranchId { get; }

		public override string Id => BranchId;

		private List<ConditionalBranch> States { get; } = new List<ConditionalBranch>();

		public override bool ShouldAppearInLogs => false;

		public ConditionalBranchState(string stateId)
		{
			BranchId = stateId;
		}

		public void AddState(MonsterState move, Func<bool> condition)
		{
			States.Add(new ConditionalBranch(move, condition));
		}

		public override string GetNextState(Creature _, Rng __)
		{
			foreach (ConditionalBranch state in States)
			{
				if (state.Evaluate() > 0f)
				{
					return state.id;
				}
			}
			throw new InvalidOperationException("No valid next state found.");
		}

		public override void RegisterStates(System.Collections.Generic.Dictionary<string, MonsterState> monsterStates)
		{
			monsterStates.Add(Id, this);
		}
	}
	public class MonsterMoveStateMachine
	{
		private MonsterState _currentState;

		private readonly MonsterState _initialState;

		private bool _performedFirstMove;

		public System.Collections.Generic.Dictionary<string, MonsterState> States { get; } = new System.Collections.Generic.Dictionary<string, MonsterState>();

		public List<MonsterState> StateLog { get; } = new List<MonsterState>();

		public MonsterMoveStateMachine(IEnumerable<MonsterState> states, MonsterState initialState)
		{
			foreach (MonsterState state in states)
			{
				state.RegisterStates(States);
			}
			_initialState = initialState;
			_currentState = _initialState;
			if (_currentState.ShouldAppearInLogs)
			{
				StateLog.Add(_currentState);
			}
		}

		public MoveState RollMove(IEnumerable<Creature> targets, Creature owner, Rng rng)
		{
			FindNextMoveState(targets, owner, rng, logMove: true);
			if (!_currentState.IsMove)
			{
				throw new InvalidOperationException(_currentState.Id + " is not a valid move state");
			}
			return (MoveState)_currentState;
		}

		public void ForceCurrentState(MonsterState state)
		{
			SetCurrentState(state);
		}

		public void OnMovePerformed(MoveState _)
		{
			_performedFirstMove = true;
		}

		private void FindNextMoveState(IEnumerable<Creature> targets, Creature owner, Rng rng, bool logMove)
		{
			if (_currentState == null)
			{
				throw new InvalidOperationException("Cannot find next move state when current state is null.");
			}
			if (!_currentState.CanTransitionAway || (!_performedFirstMove && _currentState.IsMove))
			{
				return;
			}
			MonsterState monsterState = null;
			do
			{
				string nextState = _currentState.GetNextState(owner, rng);
				if (!string.IsNullOrEmpty(nextState) && !States.ContainsKey(nextState))
				{
					throw new InvalidOperationException("no valid state found: " + nextState);
				}
				SetCurrentState(string.IsNullOrEmpty(nextState) ? _initialState : States[nextState]);
				monsterState = ((monsterState == null && _currentState.ShouldAppearInLogs) ? _currentState : monsterState);
			}
			while (!_currentState.IsMove);
			if (logMove && monsterState != null)
			{
				StateLog.Add(monsterState);
			}
		}

		private void SetCurrentState(MonsterState state)
		{
			_currentState.OnExitState();
			_currentState = state;
			_currentState.OnEnterState();
		}
	}
	public abstract class MonsterState
	{
		public abstract string Id { get; }

		public virtual bool ShouldAppearInLogs => true;

		public virtual bool CanTransitionAway => true;

		public virtual bool IsMove => this is MoveState;

		public abstract string GetNextState(Creature owner, Rng rng);

		public abstract void RegisterStates(System.Collections.Generic.Dictionary<string, MonsterState> monsterStates);

		public virtual void OnEnterState()
		{
		}

		public virtual void OnExitState()
		{
		}
	}
	public class MoveState : MonsterState
	{
		private bool _performedAtLeastOnce;

		private readonly Func<IReadOnlyList<Creature>, Task> _onPerform;

		public IReadOnlyList<AbstractIntent> Intents { get; private set; }

		public string StateId { get; }

		public bool MustPerformOnceBeforeTransitioning { get; set; }

		public string? FollowUpStateId { get; init; }

		public MonsterState? FollowUpState { get; set; }

		public override bool CanTransitionAway
		{
			get
			{
				if (MustPerformOnceBeforeTransitioning)
				{
					return _performedAtLeastOnce;
				}
				return true;
			}
		}

		public override bool IsMove => true;

		public override string Id => StateId;

		public MoveState()
			: this("UNSET_MOVE", UnsetMove)
		{
		}

		public MoveState(string stateId, Func<IReadOnlyList<Creature>, Task> onPerform, params AbstractIntent[] intents)
		{
			_onPerform = onPerform;
			Intents = intents;
			StateId = stateId;
		}

		public async Task PerformMove(IEnumerable<Creature> targets)
		{
			_performedAtLeastOnce = true;
			Creature[] arg = (targets as Creature[]) ?? targets.ToArray();
			await _onPerform(arg);
		}

		public override void OnExitState()
		{
			_performedAtLeastOnce = false;
		}

		public override string GetNextState(Creature owner, Rng rng)
		{
			return (FollowUpState?.Id ?? FollowUpStateId) ?? throw new InvalidOperationException("No valid followup state.");
		}

		public override void RegisterStates(System.Collections.Generic.Dictionary<string, MonsterState> monsterStates)
		{
			monsterStates.Add(Id, this);
		}

		private static Task UnsetMove(IEnumerable<Creature> c)
		{
			throw new InvalidOperationException("No move has been set for the monster");
		}
	}
	public class RandomBranchState : MonsterState
	{
		public struct StateWeight
		{
			public string stateId;

			public MoveRepeatType repeatType;

			public int maxTimes;

			public Func<float> weightLambda;

			public int cooldown;

			public float GetWeight()
			{
				if (weightLambda != null)
				{
					return weightLambda();
				}
				throw new InvalidOperationException(stateId + " doesn't have a weight");
			}
		}

		public string StateId { get; }

		public List<StateWeight> States { get; set; } = new List<StateWeight>();

		public override bool ShouldAppearInLogs => false;

		public override string Id => StateId;

		public RandomBranchState(string id)
		{
			StateId = id;
		}

		public void AddBranch(MonsterState state, int cooldown, MoveRepeatType repeatType, Func<float> weight)
		{
			if (repeatType.Equals(MoveRepeatType.CanRepeatXTimes))
			{
				throw new ArgumentException("Use other constructor to specify number of repeats");
			}
			StateWeight item = new StateWeight
			{
				repeatType = repeatType,
				stateId = state.Id,
				weightLambda = weight,
				cooldown = cooldown
			};
			States.Add(item);
		}

		public void AddBranch(MonsterState state, int cooldown, int maxRepeats, Func<float> weight)
		{
			StateWeight item = new StateWeight
			{
				maxTimes = maxRepeats,
				repeatType = MoveRepeatType.CanRepeatXTimes,
				stateId = state.Id,
				weightLambda = weight,
				cooldown = cooldown
			};
			States.Add(item);
		}

		public void AddBranch(MonsterState state, int maxRepeats, Func<float> weight)
		{
			AddBranch(state, 0, maxRepeats, weight);
		}

		public void AddBranch(MonsterState state, int cooldown, MoveRepeatType repeatType, float weight)
		{
			AddBranch(state, cooldown, repeatType, () => weight);
		}

		public void AddBranch(MonsterState state, MoveRepeatType repeatType, float weight)
		{
			AddBranch(state, repeatType, () => weight);
		}

		public void AddBranch(MonsterState state, MoveRepeatType repeatType, Func<float> weight)
		{
			AddBranch(state, 0, repeatType, weight);
		}

		public void AddBranch(MonsterState state, int maxRepeats, float weight)
		{
			AddBranch(state, maxRepeats, () => weight);
		}

		public void AddBranch(MonsterState state, int cooldown, MoveRepeatType repeatType)
		{
			AddBranch(state, cooldown, repeatType, 1f);
		}

		public void AddBranch(MonsterState state, int maxRepeats)
		{
			AddBranch(state, maxRepeats, 1f);
		}

		public void AddBranch(MonsterState state, MoveRepeatType repeatType)
		{
			AddBranch(state, repeatType, 1f);
		}

		public override string GetNextState(Creature owner, Rng rng)
		{
			float max = States.Sum((StateWeight x) => GetStateWeight(x, owner));
			float num = rng.NextFloat(max);
			foreach (StateWeight state in States)
			{
				num -= GetStateWeight(state, owner);
				if (num <= 0f)
				{
					return state.stateId;
				}
			}
			throw new InvalidOperationException("No valid state found in RandomBranchState " + Id + "!");
		}

		private static float GetStateWeight(StateWeight stateWeight, Creature owner)
		{
			MonsterMoveStateMachine moveStateMachine = owner.Monster.MoveStateMachine;
			float num = 1f;
			if (stateWeight.repeatType.Equals(MoveRepeatType.UseOnlyOnce))
			{
				MonsterState item = moveStateMachine.States[stateWeight.stateId];
				if (moveStateMachine.StateLog.Contains(item))
				{
					num = 0f;
				}
			}
			else if (!stateWeight.repeatType.Equals(MoveRepeatType.CanRepeatForever))
			{
				float num2 = (stateWeight.repeatType.Equals(MoveRepeatType.CannotRepeat) ? 1 : stateWeight.maxTimes);
				num = (((float)moveStateMachine.StateLog.Count < num2) ? 1 : 0);
				int num3 = 0;
				while ((float)moveStateMachine.StateLog.Count >= num2 && (float)num3 < num2 && moveStateMachine.StateLog.Count - num3 > 0)
				{
					MonsterState monsterState = moveStateMachine.States[stateWeight.stateId];
					if (moveStateMachine.StateLog[moveStateMachine.StateLog.Count - 1 - num3] != monsterState)
					{
						num = 1f;
						break;
					}
					num3++;
				}
			}
			if (stateWeight.cooldown > 0)
			{
				IEnumerable<MonsterState> source = moveStateMachine.StateLog.Where((MonsterState state) => state.IsMove).Reverse().Take(stateWeight.cooldown);
				if (source.Any((MonsterState move) => move.Id == stateWeight.stateId))
				{
					return 0f;
				}
			}
			return num * stateWeight.GetWeight();
		}

		public override void RegisterStates(System.Collections.Generic.Dictionary<string, MonsterState> monsterStates)
		{
			monsterStates.Add(Id, this);
		}
	}
}
