			CurrentTarget = null;
			CurrentPlayIndex = 0;
			DeckVersion = null;
			HasBeenRemovedFromState = false;
			AfflictionChanged = null;
			Drawn = null;
			EnchantmentChanged = null;
			EnergyCostChanged = null;
			Forged = null;
			KeywordsChanged = null;
			Played = null;
			ReplayCountChanged = null;
			StarCostChanged = null;
			Upgraded = null;
		}

