		public string IconPath
		{
			get
			{
				if (_iconPath == null)
				{
					if (ResourceLoader.Exists(IntendedIconPath))
					{
						_iconPath = IntendedIconPath;
					}
					else if (ResourceLoader.Exists(BetaIconPath))
					{
						_iconPath = BetaIconPath;
					}
					else
					{
						_iconPath = MissingIconPath;
					}
