		/// </summary>
		public CardModel Card
		{
			get
			{
				AssertMutable();
				return _card;
			}
			set
			{
				AssertMutable();
				value.AssertMutable();
				if (_card != null)
				{
					throw new InvalidOperationException("Enchantments cannot be moved from one card to another.");
				}
				_card = value;
			}
		}

