		public DynamicVarSet DynamicVars
		{
			get
			{
				if (_dynamicVars != null)
				{
					return _dynamicVars;
				}
				_dynamicVars = new DynamicVarSet(CanonicalVars);
				_dynamicVars.InitializeWithOwner(this);
				return _dynamicVars;
			}
