		/// For example, Corrupted causes the card to glow red if it will kill you.
		/// </summary>
		public virtual bool ShouldGlowRed => false;

		public EnchantmentModel CanonicalInstance
		{
			get
			{
				if (!base.IsMutable)
				{
					return this;
