		/// These relics provide diminishing value late in a run.
		/// </summary>
		protected static bool IsBeforeAct3TreasureChest(IRunState runState)
		{
			int num = ((runState.Players.Count > 1) ? 38 : 41);
			return runState.TotalFloor < num;
		}

