		protected override void AfterCloned()
		{
			base.AfterCloned();
			if (_canonicalInstance == null)
			{
				CanonicalInstance = ModelDb.GetById<RelicModel>(base.Id);
			}
			HasBeenRemovedFromState = false;
			Flashed = null;
			DisplayAmountChanged = null;
			StatusChanged = null;
		}

		public void RemoveInternal()
		{
			HasBeenRemovedFromState = true;
		}

		public void IncrementStackCount()
		{
			AssertMutable();
			if (!IsStackable)
			{
				throw new InvalidOperationException($"Cannot increment stack count on {base.Id} because it is not a stackable relic.");
			}
			StackCount++;
		}

		public virtual Task AfterObtained()
		{
			return Task.CompletedTask;
		}

		public virtual Task AfterRemoved()
		{
			return Task.CompletedTask;
		}

		public SerializableRelic ToSerializable()
		{
			AssertMutable();
			return new SerializableRelic
			{
				Id = base.Id,
				Props = SavedProperties.From(this),
				FloorAddedToDeck = FloorAddedToDeck
			};
		}

		public static RelicModel FromSerializable(SerializableRelic save)
		{
			RelicModel relicModel = SaveUtil.RelicOrDeprecated(save.Id).ToMutable();
			save.Props?.Fill(relicModel);
			if (save.FloorAddedToDeck.HasValue)
			{
				relicModel.FloorAddedToDeck = save.FloorAddedToDeck.Value;
			}
			return relicModel;
		}

		/// <summary>
		/// This should be called when the relic icon changes so the icon paths are uncached.
		/// </summary>
		protected void RelicIconChanged()
		{
			_resolvedBigIconPath = null;
		}

		protected static LocString L10NLookup(string entryName)
		{
			return new LocString("relics", entryName);
		}
	}
	public abstract class RelicPoolModel : AbstractModel, IPoolModel
	{
		private IEnumerable<RelicModel>? _relics;

		private HashSet<ModelId>? _allRelicIds;

		public abstract string EnergyColorName { get; }

		public virtual Color LabOutlineColor => StsColors.halfTransparentBlack;

		/// <summary>
		/// Get every relic in this pool (ignores Unlocks/Epoch state).
		/// </summary>
		public IEnumerable<RelicModel> AllRelics
		{
			get
			{
				if (_relics == null)
				{
					_relics = GenerateAllRelics();
					_relics = ModHelper.ConcatModelsFromMods(this, _relics);
				}
				return _relics;
			}
		}

		/// <summary>
		/// Get the ID of every relic in this pool (ignores Unlocks/Epoch state).
		/// </summary>
		public HashSet<ModelId> AllRelicIds => _allRelicIds ?? (_allRelicIds = AllRelics.Select((RelicModel c) => c.Id).ToHashSet());

		public override bool ShouldReceiveCombatHooks => false;

		/// <summary>
		/// Generates every relic in this pool (ignores Unlocks/Epoch state).
		/// Overridden in subclasses, but should only be called once by <see cref="P:MegaCrit.Sts2.Core.Models.RelicPoolModel.AllRelics" /> so it can be cached.
		/// </summary>
		protected abstract IEnumerable<RelicModel> GenerateAllRelics();

		/// <summary>
		/// Returns every relic in this pool that the player has unlocked.
		/// By default, this is just AllRelics, but can be overriden in subclasses to remove relics that should be locked
		/// under certain conditions.
		/// </summary>
		public virtual IEnumerable<RelicModel> GetUnlockedRelics(UnlockState unlockState)
		{
			return AllRelics;
		}
	}
	/// <summary>
	/// A model which is instantiated once for an entire run.
	/// Currently only one for multiplayer scaling.
	/// </summary>
	public abstract class SingletonModel : AbstractModel
	{
	}
