namespace MegaCrit.Sts2.Core.Models.Singleton
{
	/// <summary>
	/// Scales block gained by enemies.
	/// </summary>
	public class MultiplayerScalingModel : SingletonModel
	{
		/// <summary>
		/// The <see cref="T:MegaCrit.Sts2.Core.Runs.RunState" /> that this model is scaling.
		/// Should always be set when creating a run, so we mark it as non-nullable.
		/// </summary>
		private RunState _runState;

		/// <summary>
		/// The CombatState that this model is scaling.
		/// Only set when we are in combat.
		/// </summary>
		private CombatState? _combatState;

		public override bool ShouldReceiveCombatHooks => true;

		/// <summary>
		/// Initialize with the specified <see cref="T:MegaCrit.Sts2.Core.Runs.RunState" />.
		/// </summary>
		public void Initialize(RunState state)
		{
			if (_runState != null)
			{
				throw new InvalidOperationException("Already initialized");
			}
			_runState = state;
		}

		public void OnCombatEntered(CombatState combatState)
		{
			_combatState = combatState;
		}

		public void OnCombatFinished()
		{
			_combatState = null;
		}

		public override decimal ModifyBlockMultiplicative(Creature target, decimal block, ValueProp props, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target != null && !target.IsPrimaryEnemy && !target.IsSecondaryEnemy)
			{
				return 1m;
			}
			if (!props.IsPoweredCardOrMonsterMoveBlock())
			{
				return 1m;
			}
			int count = _runState.Players.Count;
			if (count <= 2)
			{
				return count;
			}
			return (decimal)count * GetMultiplayerScaling(_combatState.Encounter, _runState.CurrentActIndex);
		}

		public static decimal GetMultiplayerScaling(EncounterModel? encounter, int actIndex)
		{
			switch (actIndex)
			{
			case 0:
				return 1.1m;
			case 1:
				return 1.2m;
			case 2:
				if (encounter != null && encounter.RoomType == RoomType.Boss)
				{
					return 1.3m;
				}
				return 1.2m;
			default:
				throw new ArgumentOutOfRangeException("actIndex", actIndex, "Invalid act index for HP scaling");
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Models.Relics
{
	public sealed class Akabeko : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Uncommon;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new PowerVar<VigorPower>(8m));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromPower<VigorPower>());

		public override async Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (participants.Contains(base.Owner.Creature) && base.Owner.PlayerCombatState.TurnNumber <= 1)
			{
				Flash();
				await PowerCmd.Apply<VigorPower>(new ThrowingPlayerChoiceContext(), base.Owner.Creature, base.DynamicVars["VigorPower"].IntValue, base.Owner.Creature, null);
			}
		}
	}
	public sealed class AlchemicalCoffer : RelicModel
	{
		private const string _potionSlotsKey = "PotionSlots";

		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool HasUponPickupEffect => true;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("PotionSlots", 4m));

		public override async Task AfterObtained()
		{
			int originalSlotCount = base.Owner.MaxPotionCount;
			await PlayerCmd.GainMaxPotionCount(base.DynamicVars["PotionSlots"].IntValue, base.Owner);
			IEnumerable<PotionModel> enumerable = PotionFactory.CreateRandomPotionsOutOfCombat(base.Owner, base.DynamicVars["PotionSlots"].IntValue, base.Owner.RunState.Rng.CombatPotionGeneration);
			int i = 0;
			foreach (PotionModel item in enumerable)
			{
				await PotionCmd.TryToProcure(item.ToMutable(), base.Owner, originalSlotCount + i);
				i++;
			}
		}
	}
	public sealed class AmethystAubergine : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Common;

		public override bool IsAllowedInShops => false;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new GoldVar(15));

		public override bool IsAllowed(IRunState runState)
		{
			return RelicModel.IsBeforeAct3TreasureChest(runState);
		}

		public override bool TryModifyRewards(Player player, List<Reward> rewards, AbstractRoom? room)
		{
			if (player != base.Owner)
			{
				return false;
			}
			if (room == null)
			{
				return false;
			}
			if (!room.RoomType.IsCombatRoom())
			{
				return false;
			}
			if (room.RoomType == RoomType.Boss && player.RunState.CurrentActIndex >= player.RunState.Acts.Count - 1)
			{
				return false;
			}
			rewards.Add(new GoldReward(base.DynamicVars.Gold.IntValue, player));
			return true;
		}

		public override Task AfterModifyingRewards()
		{
			Flash();
			return Task.CompletedTask;
		}
	}
	public sealed class Anchor : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Common;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new BlockVar(10m, ValueProp.Unpowered));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

