	public sealed class BoneTea : RelicModel
	{
		private const string _combatsKey = "Combats";

		private int _combatsLeft = 1;

		public override RelicRarity Rarity => RelicRarity.Event;

		public override bool IsUsedUp => CombatsLeft <= 0;

		public override bool ShowCounter => false;

		public override int DisplayAmount => Math.Max(0, CombatsLeft);

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("Combats", CombatsLeft));

		[SavedProperty]
		public int CombatsLeft
		{
			get
			{
				return _combatsLeft;
			}
			set
			{
				AssertMutable();
				_combatsLeft = value;
				base.DynamicVars["Combats"].BaseValue = _combatsLeft;
				InvokeDisplayAmountChanged();
				if (IsUsedUp)
				{
					base.Status = RelicStatus.Disabled;
				}
			}
		}

		public override Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)
		{
			if (IsUsedUp)
			{
				return Task.CompletedTask;
			}
			if (player != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (base.Owner.PlayerCombatState.TurnNumber > 1)
			{
				return Task.CompletedTask;
			}
			foreach (CardModel card in PileType.Hand.GetPile(base.Owner).Cards)
			{
				CardCmd.Upgrade(card);
			}
			CombatsLeft--;
			Flash();
			return Task.CompletedTask;
		}
	}
	public sealed class Bookmark : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Rare;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Retain));

		public override Task AfterFlush(PlayerChoiceContext choiceContext, Player player, IReadOnlyCollection<CardModel> flushedCards, IReadOnlyCollection<CardModel> retainedCards)
		{
			if (player != base.Owner)
			{
				return Task.CompletedTask;
			}
			List<CardModel> list = retainedCards.Where((CardModel c) => !c.EnergyCost.CostsX && c.EnergyCost.GetWithModifiers(CostModifiers.Local) > 0).ToList();
			if (list.Count == 0)
			{
				return Task.CompletedTask;
			}
			Flash();
			base.Owner.RunState.Rng.CombatCardSelection.NextItem(list)?.EnergyCost.AddUntilPlayed(-1);
			return Task.CompletedTask;
		}
	}
	public sealed class BookOfFiveRings : RelicModel
	{
		private bool _isActivating;

		private int _cardsAdded;

		public override RelicRarity Rarity => RelicRarity.Common;

		public override bool ShowCounter => true;

		public override int DisplayAmount
		{
			get
			{
				if (!IsActivating)
				{
					return CardsAddedSinceLastTrigger;
				}
				return base.DynamicVars.Cards.IntValue;
			}
		}

		private bool IsActivating
		{
			get
			{
				return _isActivating;
			}
			set
			{
				AssertMutable();
				_isActivating = value;
				InvokeDisplayAmountChanged();
			}
		}

		[SavedProperty]
		public int CardsAdded
		{
			get
			{
				return _cardsAdded;
			}
			set
			{
				AssertMutable();
				_cardsAdded = value;
				InvokeDisplayAmountChanged();
			}
		}

		private int CardsAddedSinceLastTrigger => CardsAdded % base.DynamicVars.Cards.IntValue;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(5),
			new HealVar(20m)
		});

		public override bool IsAllowed(IRunState runState)
		{
			return RelicModel.IsBeforeAct3TreasureChest(runState);
		}

		public override async Task AfterCardChangedPiles(CardModel card, PileType oldPileType, AbstractModel? clonedBy)
		{
			if (base.Owner.Creature.IsDead || card.Owner != base.Owner)
			{
				return;
			}
			CardPile? pile = card.Pile;
			if (pile != null && pile.Type == PileType.Deck)
			{
				CardsAdded++;
				if (CardsAddedSinceLastTrigger == 0)
				{
					TaskHelper.RunSafely(DoActivateVisuals());
					await CreatureCmd.Heal(base.Owner.Creature, base.DynamicVars.Heal.BaseValue);
				}
			}
		}

		private async Task DoActivateVisuals()
		{
			IsActivating = true;
			Flash();
			await Cmd.Wait(1f);
			IsActivating = false;
		}
	}
