			{
				AbstractRoom? currentRoom = combatState.RunState.CurrentRoom;
				if (currentRoom != null && currentRoom.RoomType == RoomType.Elite)
				{
					Flash();
					await PlayerCmd.GainEnergy(base.DynamicVars.Energy.BaseValue, base.Owner);
				}
			}
		}
