	public sealed class FurCoat : RelicModel
	{
		private const string _combatsKey = "Combats";

		private int _furCoatActIndex = -1;

		public static LocString HistoryEntry
		{
			get
			{
				FurCoat furCoat = ModelDb.Relic<FurCoat>();
				LocString locString = new LocString("relics", furCoat.Id.Entry + ".historyEntry");
				locString.Add("Title", furCoat.Title);
				return locString;
			}
		}

		public override RelicRarity Rarity => RelicRarity.Ancient;

		[SavedProperty]
		public int FurCoatActIndex
		{
			get
			{
				return _furCoatActIndex;
			}
			set
			{
				AssertMutable();
				_furCoatActIndex = value;
			}
		}

		[SavedProperty]
		private int[] FurCoatCoordCols { get; set; } = System.Array.Empty<int>();

		[SavedProperty]
		private int[] FurCoatCoordRows { get; set; } = System.Array.Empty<int>();

		[SavedProperty]
		private bool FurCoatCoordsSet { get; set; }

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("Combats", 8m));

		public override Task AfterObtained()
		{
			FurCoatActIndex = base.Owner.RunState.CurrentActIndex;
			AddMarkedRooms(base.Owner.RunState.Map);
			return Task.CompletedTask;
		}

		public override ActMap ModifyGeneratedMapLate(IRunState runState, ActMap map, int actIndex)
		{
			return AddMarkedRooms(map);
		}

		private ActMap AddMarkedRooms(ActMap map)
		{
			if (base.Owner.RunState.CurrentActIndex != FurCoatActIndex)
			{
				return map;
			}
			List<MapCoord> markedCoords = GetMarkedCoords();
			bool flag = markedCoords == null;
			if (!flag)
			{
				flag = !markedCoords.TrueForAll((MapCoord c) => map.HasPoint(c) && (map.GetPoint(c).PointType == MapPointType.Monster || map.GetPoint(c).PointType == MapPointType.Elite));
			}
			if (flag)
			{
				Rng rng = new Rng(base.Owner, base.Id, 0uL);
				List<MapPoint> list = map.GetAllMapPoints().Where(delegate(MapPoint p)
				{
					MapPointType pointType = p.PointType;
					return (uint)(pointType - 5) <= 1u && !p.Quests.Any((AbstractModel q) => q is FurCoat);
				}).ToList();
				list.UnstableShuffle(rng);
				int intValue = base.DynamicVars["Combats"].IntValue;
				List<MapPoint> list2 = list.Take(intValue).ToList();
				FurCoatCoordCols = new int[list2.Count];
				FurCoatCoordRows = new int[list2.Count];
				for (int num = 0; num < list2.Count; num++)
				{
					FurCoatCoordCols[num] = list2[num].coord.col;
					FurCoatCoordRows[num] = list2[num].coord.row;
				}
				FurCoatCoordsSet = true;
				foreach (MapPoint item in list2)
				{
					item.AddQuest(this);
				}
			}
			else
			{
				foreach (MapCoord item2 in markedCoords)
				{
					MapPoint point = map.GetPoint(item2);
					if (point == null)
					{
						throw new InvalidOperationException($"Loaded a fur coat map with coordinate {item2}, but the generated map does not contain that coordinate!");
					}
					point.AddQuest(this);
				}
			}
			return map;
		}

		public override async Task BeforeCombatStart()
		{
			List<MapCoord> markedCoords = GetMarkedCoords();
			if (markedCoords == null || !markedCoords.Contains(base.Owner.RunState.CurrentMapPoint.coord))
			{
				return;
			}
			MapPointHistoryEntry currentMapPointHistoryEntry = base.Owner.RunState.CurrentMapPointHistoryEntry;
			if (currentMapPointHistoryEntry != null)
			{
				currentMapPointHistoryEntry.GetEntry(base.Owner.NetId).IsAffectedByFurCoat = true;
			}
			Flash();
			IReadOnlyList<Creature> hittableEnemies = base.Owner.Creature.CombatState.HittableEnemies;
			VfxCmd.PlayOnCreatureCenters(hittableEnemies, "vfx/vfx_bite");
			foreach (Creature item in hittableEnemies)
			{
				await CreatureCmd.SetCurrentHp(item, 1m);
			}
		}

		public override async Task AfterCreatureAddedToCombat(Creature creature)
		{
			if (creature.Side == CombatSide.Enemy)
			{
				List<MapCoord> markedCoords = GetMarkedCoords();
				if (markedCoords != null && markedCoords.Contains(base.Owner.RunState.CurrentMapPoint.coord))
				{
					Flash();
					VfxCmd.PlayOnCreatureCenter(creature, "vfx/vfx_bite");
					await CreatureCmd.SetCurrentHp(creature, 1m);
				}
			}
		}

		public List<MapCoord>? GetMarkedCoords()
		{
			if (!FurCoatCoordsSet)
			{
				return null;
			}
			List<MapCoord> list = new List<MapCoord>();
			for (int i = 0; i < FurCoatCoordCols.Length; i++)
			{
				list.Add(new MapCoord
				{
					col = FurCoatCoordCols[i],
					row = FurCoatCoordRows[i]
				});
			}
			return list;
		}
	}
	public sealed class GalacticDust : RelicModel
	{
		private bool _isActivating;

		private int _starsSpent;

		public override bool ShowCounter => true;

		public override int DisplayAmount
		{
			get
			{
				if (!IsActivating)
				{
					return StarsSpent % base.DynamicVars.Stars.IntValue;
				}
				return base.DynamicVars.Stars.IntValue;
			}
		}

		private bool IsActivating
		{
			get
			{
				return _isActivating;
			}
			set
			{
				AssertMutable();
				_isActivating = value;
				UpdateDisplay();
			}
		}

		[SavedProperty]
		public int StarsSpent
		{
			get
			{
				return _starsSpent;
			}
			set
			{
				AssertMutable();
				_starsSpent = value;
				UpdateDisplay();
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

		public override RelicRarity Rarity => RelicRarity.Uncommon;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new StarsVar(10),
			new BlockVar(10m, ValueProp.Unpowered)
		});

		private void UpdateDisplay()
		{
			if (IsActivating)
			{
				base.Status = RelicStatus.Normal;
			}
			else
			{
				int intValue = base.DynamicVars.Stars.IntValue;
				base.Status = ((StarsSpent == intValue - 1) ? RelicStatus.Active : RelicStatus.Normal);
			}
			InvokeDisplayAmountChanged();
		}

		public override async Task AfterStarsSpent(int amount, Player spender)
		{
			if (spender == base.Owner)
			{
				StarsSpent += amount;
				if (StarsSpent >= base.DynamicVars.Stars.IntValue)
				{
					TaskHelper.RunSafely(DoActivateVisuals());
					await CreatureCmd.GainBlock(base.Owner.Creature, Mathf.FloorToInt((float)StarsSpent / (float)base.DynamicVars.Stars.IntValue) * base.DynamicVars.Block.IntValue, ValueProp.Unpowered, null);
					StarsSpent %= base.DynamicVars.Stars.IntValue;
				}
				InvokeDisplayAmountChanged();
			}
		}

		private async Task DoActivateVisuals()
		{
			IsActivating = true;
			Flash();
			await Cmd.Wait(1f);
			IsActivating = false;
		}
	}
