	public sealed class GhostSeed : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Shop;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Ethereal));

		public override Task AfterCardEnteredCombat(CardModel card)
		{
			if (!CanAffect(card))
			{
				return Task.CompletedTask;
			}
			if (card.Owner != base.Owner)
			{
				return Task.CompletedTask;
			}
			CardCmd.ApplyKeyword(card, CardKeyword.Ethereal);
			return Task.CompletedTask;
		}

		public override Task AfterRoomEntered(AbstractRoom room)
		{
			if (!(room is CombatRoom))
			{
				return Task.CompletedTask;
			}
			IEnumerable<CardModel> allCards = base.Owner.PlayerCombatState.AllCards;
			foreach (CardModel item in allCards)
			{
				if (CanAffect(item))
				{
					CardCmd.ApplyKeyword(item, CardKeyword.Ethereal);
				}
			}
			return Task.CompletedTask;
		}

		private static bool CanAffect(CardModel card)
		{
			if (card.Rarity == CardRarity.Basic && (card.Tags.Contains(CardTag.Strike) || card.Tags.Contains(CardTag.Defend)))
			{
				return !card.GetKeywordsWithSources(KeywordSources.Local).Contains(CardKeyword.Ethereal);
			}
			return false;
		}
	}
