	public sealed class MummifiedHand : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Rare;

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (!CombatManager.Instance.IsInProgress)
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card.Owner != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card.Type != CardType.Power)
			{
				return Task.CompletedTask;
			}
			Rng combatCardSelection = base.Owner.RunState.Rng.CombatCardSelection;
			IReadOnlyList<CardModel> cards = PileType.Hand.GetPile(base.Owner).Cards;
			List<CardModel> list = cards.Where((CardModel c) => c.EnergyCost.GetWithModifiers(CostModifiers.None) > 0 || c.BaseStarCost > 0).ToList();
			CardModel cardModel = combatCardSelection.NextItem(list.Where((CardModel c) => c.CostsEnergyOrStars(includeGlobalModifiers: true)));
			if (cardModel == null)
			{
				cardModel = combatCardSelection.NextItem(cards.Where((CardModel c) => c.CostsEnergyOrStars(includeGlobalModifiers: true)));
			}
			if (cardModel == null)
			{
				cardModel = combatCardSelection.NextItem(list);
			}
			if (cardModel == null)
			{
				cardModel = combatCardSelection.NextItem(cards);
			}
			cardModel?.SetToFreeThisTurn();
			return Task.CompletedTask;
		}
	}
	public sealed class MusicBox : RelicModel
	{
		private bool _wasUsedThisTurn;

		private CardModel? _cardBeingPlayed;

		public override RelicRarity Rarity => RelicRarity.Ancient;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Ethereal));

		private bool WasUsedThisTurn
		{
			get
			{
				return _wasUsedThisTurn;
			}
			set
			{
				AssertMutable();
				_wasUsedThisTurn = value;
			}
		}

		private CardModel? CardBeingPlayed
		{
			get
			{
				return _cardBeingPlayed;
			}
			set
			{
				AssertMutable();
				_cardBeingPlayed = value;
			}
		}

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (CardBeingPlayed != null)
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card.Owner != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (WasUsedThisTurn)
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card.Type != CardType.Attack)
			{
				return Task.CompletedTask;
			}
			CardBeingPlayed = cardPlay.Card;
			return Task.CompletedTask;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card == CardBeingPlayed)
			{
				Flash();
				CardModel card = cardPlay.Card.CreateClone();
				CardCmd.ApplyKeyword(card, CardKeyword.Ethereal);
				await CardPileCmd.AddGeneratedCardToCombat(card, PileType.Hand, base.Owner);
				WasUsedThisTurn = true;
				CardBeingPlayed = null;
			}
		}

		public override Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner.Creature))
			{
				return Task.CompletedTask;
			}
			WasUsedThisTurn = false;
			CardBeingPlayed = null;
			return Task.CompletedTask;
		}

		public override Task AfterCombatEnd(CombatRoom _)
		{
			WasUsedThisTurn = false;
			CardBeingPlayed = null;
			return Task.CompletedTask;
		}
	}
