	public sealed class Orichalcum : RelicModel
	{
		private bool _shouldTrigger;

		public override RelicRarity Rarity => RelicRarity.Uncommon;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new BlockVar(6m, ValueProp.Unpowered));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

		private bool ShouldTrigger
		{
			get
			{
				return _shouldTrigger;
			}
			set
			{
				AssertMutable();
				_shouldTrigger = value;
			}
		}

		/// <summary>
		/// This uses the _very early_ hook because it needs to check the player's block before <see cref="T:MegaCrit.Sts2.Core.Models.Powers.PlatingPower" />
		/// triggers (otherwise, <see cref="T:MegaCrit.Sts2.Core.Models.Powers.PlatingPower" /> will prevent this relic's block gain), and
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Powers.PlatingPower" /> in turn needs to run early so it can give you block before you take damage from
		/// another end-of-turn effect.
		/// </summary>
		public override Task BeforeSideTurnEndVeryEarly(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (!participants.Contains(base.Owner.Creature))
			{
				return Task.CompletedTask;
			}
			if (base.Owner.Creature.Block > 0)
			{
				return Task.CompletedTask;
			}
			ShouldTrigger = true;
			return Task.CompletedTask;
		}

		public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (ShouldTrigger)
			{
				ShouldTrigger = false;
				Flash();
				await CreatureCmd.GainBlock(base.Owner.Creature, base.DynamicVars.Block, null);
			}
		}

		public override Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner.Creature))
			{
				return Task.CompletedTask;
			}
			ShouldTrigger = false;
			return Task.CompletedTask;
		}
	}
	public sealed class OrnamentalFan : RelicModel
	{
		private bool _isActivating;

		private int _attacksPlayedThisTurn;

		public override RelicRarity Rarity => RelicRarity.Uncommon;

		public override bool ShowCounter => CombatManager.Instance.IsInProgress;

		public override int DisplayAmount
		{
			get
			{
				if (!IsActivating)
				{
					return AttacksPlayedThisTurn % base.DynamicVars.Cards.IntValue;
				}
				return base.DynamicVars.Cards.IntValue;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(3),
			new BlockVar(4m, ValueProp.Unpowered)
		});

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

		private bool IsActivating
		{
			get
			{
				return _isActivating;
			}
			set
			{
				AssertMutable();
				_isActivating = value;
				UpdateDisplay();
			}
		}

		private int AttacksPlayedThisTurn
		{
			get
			{
				return _attacksPlayedThisTurn;
			}
			set
			{
				AssertMutable();
				_attacksPlayedThisTurn = value;
				UpdateDisplay();
			}
		}

		private void UpdateDisplay()
		{
			if (IsActivating || !CombatManager.Instance.IsInProgress)
			{
				base.Status = RelicStatus.Normal;
			}
			else
			{
				int intValue = base.DynamicVars.Cards.IntValue;
				base.Status = ((AttacksPlayedThisTurn % intValue == intValue - 1) ? RelicStatus.Active : RelicStatus.Normal);
			}
			InvokeDisplayAmountChanged();
		}

		public override Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner.Creature))
			{
				return Task.CompletedTask;
			}
			AttacksPlayedThisTurn = 0;
			base.Status = RelicStatus.Normal;
			return Task.CompletedTask;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner == base.Owner && CombatManager.Instance.IsInProgress && cardPlay.Card.Type == CardType.Attack)
			{
				AttacksPlayedThisTurn++;
				int intValue = base.DynamicVars.Cards.IntValue;
				if (AttacksPlayedThisTurn % intValue == 0)
				{
					TaskHelper.RunSafely(DoActivateVisuals());
					await CreatureCmd.GainBlock(base.Owner.Creature, base.DynamicVars.Block, null);
				}
			}
		}

		private async Task DoActivateVisuals()
		{
			IsActivating = true;
			Flash();
			await Cmd.Wait(1f);
			IsActivating = false;
		}

		public override Task AfterCombatEnd(CombatRoom _)
		{
			IsActivating = false;
			return Task.CompletedTask;
		}
	}
