	public sealed class PaelsTooth : RelicModel
	{
		public const int cardsCount = 5;

		private const string _cardTitlesKey = "CardTitles";

		private List<SerializableCard> _serializableCards = new List<SerializableCard>();

		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool ShowCounter
		{
			get
			{
				if (base.IsMutable)
				{
					return _serializableCards.Count > 0;
				}
				return false;
			}
		}

		public override int DisplayAmount
		{
			get
			{
				if (!base.IsMutable)
				{
					return 0;
				}
				return _serializableCards.Count;
			}
		}

		public override bool HasUponPickupEffect => true;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(5),
			new StringVar("CardTitles")
		});

		[SavedProperty]
		public List<SerializableCard> SerializableCards
		{
			get
			{
				return _serializableCards;
			}
			private set
			{
				AssertMutable();
				_serializableCards.Clear();
				_serializableCards.AddRange(value);
				UpdateCardList();
			}
		}

		protected override void AfterCloned()
		{
			base.AfterCloned();
			_serializableCards = new List<SerializableCard>();
		}

		public override async Task AfterObtained()
		{
			IEnumerable<CardModel> enumerable = (await CardSelectCmd.FromDeckForRemoval(prefs: new CardSelectorPrefs(CardSelectorPrefs.RemoveSelectionPrompt, base.DynamicVars.Cards.IntValue), player: base.Owner, filter: (CardModel c) => c.IsUpgradable)).OrderBy<CardModel, string>((CardModel c) => c.Id.Entry, StringComparer.Ordinal);
			foreach (CardModel item in enumerable)
			{
				CardModel cardModel = (CardModel)item.MutableClone();
				SerializableCards.Add(cardModel.ToSerializable());
				await CardPileCmd.RemoveFromDeck(item);
			}
			UpdateCardList();
		}

		public override async Task AfterCombatEnd(CombatRoom room)
		{
			if (!base.Owner.Creature.IsDead && SerializableCards.Count != 0)
			{
				Flash();
				await Cmd.CustomScaledWait(0.1f, 1f);
				SerializableCard serializableCard = base.Owner.PlayerRng.Rewards.NextItem(SerializableCards);
				CardModel cardModel = CardModel.FromSerializable(serializableCard);
				if (!base.Owner.RunState.ContainsCard(cardModel))
				{
					base.Owner.RunState.AddCard(cardModel, base.Owner);
				}
				if (cardModel.IsUpgradable)
				{
					CardCmd.Upgrade(cardModel, CardPreviewStyle.MessyLayout);
				}
				CardCmd.PreviewCardPileAdd(await CardPileCmd.Add(cardModel, PileType.Deck));
				base.Status = ((SerializableCards.Count <= 0) ? RelicStatus.Disabled : RelicStatus.Normal);
				SerializableCards.Remove(serializableCard);
				UpdateCardList();
			}
		}

		private void UpdateCardList()
		{
			base.Status = ((SerializableCards.Count <= 0) ? RelicStatus.Disabled : RelicStatus.Normal);
			StringVar stringVar = (StringVar)base.DynamicVars["CardTitles"];
			if (SerializableCards.Count == 0)
			{
				stringVar.StringValue = string.Empty;
			}
			else
			{
				stringVar.StringValue = string.Join('\n', SerializableCards.Select((SerializableCard c) => "- " + SaveUtil.CardOrDeprecated(c.Id).Title));
			}
			InvokeDisplayAmountChanged();
		}

		/// <summary>
		/// DO NOT USE, this is only public for tests.
		/// </summary>
		public void DebugAddCard(SerializableCard card)
		{
			SerializableCards.Add(card);
		}
	}
	public sealed class PaelsWing : RelicModel
	{
		public const string sacrificeAlternativeKey = "SACRIFICE";

		private const string _sacrificesKey = "Sacrifices";

		private bool _isActivating;

		private int _rewardsSacrificed;

		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool ShowCounter => true;

		public override int DisplayAmount
		{
			get
			{
				if (!IsActivating)
				{
					return RewardsSacrificed % base.DynamicVars["Sacrifices"].IntValue;
				}
				return base.DynamicVars["Sacrifices"].IntValue;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("Sacrifices", 2m));

		private bool IsActivating
		{
			get
			{
				return _isActivating;
			}
			set
			{
				AssertMutable();
				_isActivating = value;
				InvokeDisplayAmountChanged();
			}
		}

		[SavedProperty]
		public int RewardsSacrificed
		{
			get
			{
				return _rewardsSacrificed;
			}
			set
			{
				AssertMutable();
				_rewardsSacrificed = value;
				InvokeDisplayAmountChanged();
			}
		}

		public override bool TryModifyCardRewardAlternatives(Player player, CardReward cardReward, List<CardRewardAlternative> alternatives)
		{
			if (base.Owner != player)
			{
				return false;
			}
			alternatives.Add(new CardRewardAlternative("SACRIFICE", OnSacrifice, PostAlternateCardRewardAction.EndSelectionAndCompleteReward));
			return true;
		}

		public async Task OnSacrifice()
		{
			RewardsSacrificed++;
			Flash();
			if (RewardsSacrificed % base.DynamicVars["Sacrifices"].IntValue == 0)
			{
				TaskHelper.RunSafely(DoActivateVisuals());
				await RelicCmd.Obtain(RelicFactory.PullNextRelicFromFront(base.Owner).ToMutable(), base.Owner);
			}
		}

		private async Task DoActivateVisuals()
		{
			IsActivating = true;
			await Cmd.Wait(1f);
			IsActivating = false;
		}
	}
	public sealed class PandorasBox : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool HasUponPickupEffect => true;

		public override async Task AfterObtained()
		{
			List<CardModel> source = PileType.Deck.GetPile(base.Owner).Cards.Where((CardModel c) => c != null && c.IsBasicStrikeOrDefend && c.IsRemovable).ToList();
			IEnumerable<CardTransformation> transformations = source.Select((CardModel c) => new CardTransformation(c, CardFactory.CreateRandomCardForTransform(c, isInCombat: false, base.Owner.RunState.Rng.Niche)));
			List<CardPileAddResult> list = (await CardCmd.Transform(transformations, null, CardPreviewStyle.None)).ToList();
			if (list.Count > 0 && LocalContext.IsMe(base.Owner))
			{
				NSimpleCardsViewScreen.ShowScreen(list, new LocString("relics", "PANDORAS_BOX.infoText"));
			}
		}
	}
