	public sealed class Pendulum : RelicModel
	{
		private const string _turnsKey = "Turns";

		private bool _isActivating;

		private int _turnsSeen;

		public override string FlashSfx => "event:/sfx/ui/relic_activate_draw";

		public override RelicRarity Rarity => RelicRarity.Common;

		public override bool ShowCounter => true;

		public override int DisplayAmount
		{
			get
			{
				if (!IsActivating)
				{
					return TurnsSeen;
				}
				return base.DynamicVars["Turns"].IntValue;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(1),
			new DynamicVar("Turns", 3m)
		});

		private bool IsActivating
		{
			get
			{
				return _isActivating;
			}
			set
			{
				AssertMutable();
				_isActivating = value;
				InvokeDisplayAmountChanged();
			}
		}

		[SavedProperty]
		public int TurnsSeen
		{
			get
			{
				return _turnsSeen;
			}
			set
			{
				AssertMutable();
				_turnsSeen = value;
				InvokeDisplayAmountChanged();
			}
		}

		public override Task BeforeHandDraw(Player player, PlayerChoiceContext choiceContext, ICombatState combatState)
		{
			if (player != base.Owner)
			{
				return Task.CompletedTask;
			}
			TurnsSeen = (TurnsSeen + 1) % base.DynamicVars["Turns"].IntValue;
			base.Status = ((TurnsSeen == base.DynamicVars["Turns"].IntValue - 1) ? RelicStatus.Active : RelicStatus.Normal);
			if (TurnsSeen == 0)
			{
				TaskHelper.RunSafely(DoActivateVisuals());
			}
			return Task.CompletedTask;
		}

		public override decimal ModifyHandDraw(Player player, decimal count)
		{
			if (player != base.Owner)
			{
				return count;
			}
			if (TurnsSeen != 0)
			{
				return count;
			}
			return count + base.DynamicVars.Cards.BaseValue;
		}

		private async Task DoActivateVisuals()
		{
			IsActivating = true;
			Flash();
			await Cmd.Wait(1f);
			IsActivating = false;
		}

