	public sealed class SilkenTress : RelicModel
	{
		private bool _isUsed;

		public override bool IsUsedUp => IsUsed;

		public override RelicRarity Rarity => RelicRarity.Ancient;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => HoverTipFactory.FromEnchantment<Glam>();

		[SavedProperty]
		private bool IsUsed
		{
			get
			{
				return _isUsed;
			}
			set
			{
				AssertMutable();
				_isUsed = value;
				if (IsUsedUp)
				{
					base.Status = RelicStatus.Disabled;
				}
			}
		}

		public override async Task AfterObtained()
		{
			await PlayerCmd.LoseGold(base.Owner.Gold, base.Owner);
		}

		public override bool TryModifyCardRewardOptionsLate(Player player, List<CardCreationResult> cardRewards, CardCreationOptions options)
		{
			if (player != base.Owner)
			{
				return false;
			}
			if (!options.Flags.HasFlag(CardCreationFlags.IsCardReward))
			{
				return false;
			}
			if (IsUsed)
			{
				return false;
			}
			Glam glam = ModelDb.Enchantment<Glam>();
			foreach (CardCreationResult cardReward in cardRewards)
			{
				CardModel card = cardReward.Card;
				if (glam.CanEnchant(card))
				{
					CardModel card2 = base.Owner.RunState.CloneCard(card);
					CardCmd.Enchant<Glam>(card2, 1m);
					cardReward.ModifyCard(card2, this);
				}
			}
			return true;
		}

		public override Task AfterModifyingCardRewardOptions()
		{
			if (IsUsed)
			{
				return Task.CompletedTask;
			}
			IsUsed = true;
			return Task.CompletedTask;
		}
	}
	public sealed class SilverCrucible : RelicModel
	{
		private int _timesUsed;

		private int _treasureRoomsEntered;

		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool IsUsedUp
		{
			get
			{
				if (TimesUsed >= base.DynamicVars.Cards.IntValue)
				{
					return TreasureRoomsEntered > 0;
				}
				return false;
			}
		}

		public override bool ShowCounter
		{
			get
			{
				if (base.DynamicVars.Cards.IntValue > 0)
				{
					return TimesUsed < base.DynamicVars.Cards.IntValue;
				}
				return false;
			}
		}

		public override int DisplayAmount => base.DynamicVars.Cards.IntValue - TimesUsed;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new CardsVar(3));

		[SavedProperty]
		public int TimesUsed
		{
			get
			{
				return _timesUsed;
			}
			set
			{
				AssertMutable();
				_timesUsed = value;
				InvokeDisplayAmountChanged();
				CheckIfUsedUp();
			}
		}

		[SavedProperty]
		public int TreasureRoomsEntered
		{
			get
			{
				return _treasureRoomsEntered;
			}
			set
			{
				AssertMutable();
				_treasureRoomsEntered = value;
				CheckIfUsedUp();
			}
		}

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.Count == 1;
		}

		private void CheckIfUsedUp()
		{
			if (IsUsedUp)
			{
				base.Status = RelicStatus.Disabled;
			}
		}

		public override bool TryModifyCardRewardOptionsLate(Player player, List<CardCreationResult> cardRewards, CardCreationOptions options)
		{
			if (player != base.Owner)
			{
				return false;
			}
			if (TimesUsed >= base.DynamicVars.Cards.IntValue)
			{
				return false;
			}
			if (!options.Flags.HasFlag(CardCreationFlags.IsCardReward))
			{
				return false;
			}
			foreach (CardCreationResult cardReward in cardRewards)
			{
				CardModel card = cardReward.Card;
				if (card.IsUpgradable)
				{
					CardModel card2 = base.Owner.RunState.CloneCard(card);
					CardCmd.Upgrade(card2);
					cardReward.ModifyCard(card2, this);
				}
			}
			return true;
		}

		public override Task AfterModifyingCardRewardOptions()
		{
			if (TimesUsed >= base.DynamicVars.Cards.IntValue)
			{
				return Task.CompletedTask;
			}
			TimesUsed++;
			return Task.CompletedTask;
		}

		public override Task AfterRoomEntered(AbstractRoom room)
		{
			if (room is TreasureRoom)
			{
				TreasureRoomsEntered++;
			}
			return Task.CompletedTask;
		}

		public override bool ShouldGenerateTreasure(Player player)
		{
			if (player != base.Owner)
			{
				return true;
			}
			return TreasureRoomsEntered > 1;
		}
	}
