		public override bool TryModifyCardBeingAddedToDeck(CardModel card, out CardModel? newCard)
		{
			newCard = null;
			if (card.Owner != base.Owner)
			{
				return false;
			}
			if (card.Type != CardType.Skill)
			{
				return false;
			}
			if (!card.IsUpgradable)
			{
