	public sealed class TuningFork : RelicModel
	{
		private bool _isActivating;

		private int _skillsPlayed;

		public override RelicRarity Rarity => RelicRarity.Uncommon;

		public override bool ShowCounter => true;

		public override int DisplayAmount
		{
			get
			{
				if (!IsActivating)
				{
					return SkillsPlayed;
				}
				return base.DynamicVars.Cards.IntValue;
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(10),
			new BlockVar(7m, ValueProp.Unpowered)
		});

		private bool IsActivating
		{
			get
			{
				return _isActivating;
			}
			set
			{
				AssertMutable();
				_isActivating = value;
				UpdateDisplay();
			}
		}

		[SavedProperty]
		public int SkillsPlayed
		{
			get
			{
				return _skillsPlayed;
			}
			private set
			{
				AssertMutable();
				if (_skillsPlayed != value)
				{
					_skillsPlayed = value;
					UpdateDisplay();
				}
			}
		}

		private int SkillsThreshold => base.DynamicVars.Cards.IntValue;

		private void UpdateDisplay()
		{
			if (IsActivating)
			{
				base.Status = RelicStatus.Normal;
			}
			else
			{
				base.Status = ((SkillsPlayed == SkillsThreshold - 1) ? RelicStatus.Active : RelicStatus.Normal);
			}
			InvokeDisplayAmountChanged();
		}

		public void NotifySkillPlayed()
		{
			SkillsPlayed++;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner == base.Owner && cardPlay.Card.Type == CardType.Skill)
			{
				SkillsPlayed++;
				if (SkillsPlayed >= SkillsThreshold)
				{
					TaskHelper.RunSafely(DoActivateVisuals());
					await CreatureCmd.GainBlock(base.Owner.Creature, base.DynamicVars.Block, null);
					SkillsPlayed -= SkillsThreshold;
				}
			}
		}

		private async Task DoActivateVisuals()
		{
			IsActivating = true;
			Flash();
			await Cmd.Wait(1f);
			IsActivating = false;
		}
	}
	public sealed class TwistedFunnel : RelicModel
	{
		public override RelicRarity Rarity => RelicRarity.Uncommon;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new PowerVar<PoisonPower>(4m));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromPower<PoisonPower>());

		public override async Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner.Creature) || base.Owner.PlayerCombatState.TurnNumber > 1)
			{
				return;
			}
			Flash();
			foreach (Creature hittableEnemy in base.Owner.Creature.CombatState.HittableEnemies)
			{
				NCombatRoom.Instance?.CombatVfxContainer.AddChildSafely(NSmokePuffVfx.Create(hittableEnemy, NSmokePuffVfx.SmokePuffColor.Green));
			}
			await Cmd.CustomScaledWait(0.2f, 0.4f);
			foreach (Creature hittableEnemy2 in base.Owner.Creature.CombatState.HittableEnemies)
			{
				await PowerCmd.Apply<PoisonPower>(choiceContext, hittableEnemy2, base.DynamicVars["PoisonPower"].IntValue, base.Owner.Creature, null);
			}
		}
	}
	public sealed class UnceasingTop : RelicModel
	{
		public override string FlashSfx => "event:/sfx/ui/relic_activate_draw";

		public override RelicRarity Rarity => RelicRarity.Rare;

		public override async Task AfterHandEmptied(PlayerChoiceContext choiceContext, Player player)
		{
			if (player == base.Owner && IsValidPhase(player.PlayerCombatState.Phase))
			{
				Flash();
				await CardPileCmd.Draw(choiceContext, player);
			}
		}

		/// <remarks>
		/// Don't trigger before hand draw or after hand flush, because if a card is autoplayed during this time, the
		/// player's hand will always be empty, so Unceasing Top will always draw.
		/// </remarks>
		private static bool IsValidPhase(PlayerTurnPhase phase)
		{
			if ((uint)(phase - 2) <= 2u)
			{
				return true;
			}
			return false;
		}
	}
	/// <summary>
	/// This relic doesn't actually _do_ anything; Doom checks for its existence and makes enemy Doom trigger at the
	/// start of the enemy's turn instead of the end of the enemy's turn (so enemies die before they can attack).
	/// </summary>
	public sealed class UndyingSigil : RelicModel
	{
		private const string _damageDecrease = "DamageDecrease";

		public override RelicRarity Rarity => RelicRarity.Shop;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("DamageDecrease", 0.5m));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromPower<DoomPower>());

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (dealer == null)
			{
				return 1m;
			}
			if (!props.IsPoweredAttack())
			{
				return 1m;
			}
			if (target != base.Owner.Creature)
			{
				return 1m;
			}
			if (dealer == base.Owner.Creature)
			{
				return 1m;
			}
			if (dealer.CurrentHp > dealer.GetPowerAmount<DoomPower>())
			{
				return 1m;
			}
			return base.DynamicVars["DamageDecrease"].BaseValue;
		}
	}
	public sealed class UnsettlingLamp : RelicModel
	{
		private CardModel? _triggeringCard;

		private List<PowerModel>? _doubledPowers;

		private bool _isFinishedTriggering;

		public override RelicRarity Rarity => RelicRarity.Rare;

		private CardModel? TriggeringCard
		{
			get
			{
				return _triggeringCard;
			}
			set
			{
				AssertMutable();
				_triggeringCard = value;
			}
		}

		private List<PowerModel> DoubledPowers
		{
			get
			{
				AssertMutable();
				if (_doubledPowers == null)
				{
					_doubledPowers = new List<PowerModel>();
				}
				return _doubledPowers;
			}
		}

		private bool IsFinishedTriggering
		{
			get
			{
				return _isFinishedTriggering;
			}
			set
			{
				AssertMutable();
				_isFinishedTriggering = value;
			}
		}

		public override Task BeforeCombatStart()
		{
			TriggeringCard = null;
			DoubledPowers.Clear();
			IsFinishedTriggering = false;
			base.Status = RelicStatus.Active;
			return Task.CompletedTask;
		}

		public override Task BeforePowerAmountChanged(PowerModel power, decimal amount, Creature target, Creature? applier, CardModel? cardSource)
		{
			if (TriggeringCard != null)
			{
				return Task.CompletedTask;
			}
			if (IsFinishedTriggering)
			{
				return Task.CompletedTask;
			}
			if (cardSource == null)
			{
				return Task.CompletedTask;
			}
			if (applier != base.Owner.Creature)
			{
				return Task.CompletedTask;
			}
			if (target.Side == base.Owner.Creature.Side)
			{
				return Task.CompletedTask;
			}
			if (!power.IsVisible)
			{
				return Task.CompletedTask;
			}
			if (power.GetTypeForAmount(amount) != PowerType.Debuff)
			{
				return Task.CompletedTask;
			}
			if (target.HasPower<ArtifactPower>())
			{
				return Task.CompletedTask;
			}
			TriggeringCard = cardSource;
			DoubledPowers.Add(power);
			return Task.CompletedTask;
		}

		public override decimal ModifyPowerAmountGivenMultiplicative(PowerModel power, Creature giver, decimal amount, Creature? target, CardModel? cardSource)
		{
			if (TriggeringCard == null)
			{
				return 1m;
			}
			if (cardSource != TriggeringCard)
			{
				return 1m;
			}
			if (IsFinishedTriggering)
			{
				return 1m;
			}
			if (HasDoubledTemporaryPowerSource(power))
			{
				return 1m;
			}
			if (power.GetTypeForAmount(amount) != PowerType.Debuff)
			{
				return 1m;
			}
			return 2m;
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card != TriggeringCard)
			{
				return Task.CompletedTask;
			}
			if (IsFinishedTriggering)
			{
				return Task.CompletedTask;
			}
			Flash();
			IsFinishedTriggering = true;
			base.Status = RelicStatus.Normal;
			return Task.CompletedTask;
		}

		public override Task AfterCombatEnd(CombatRoom room)
		{
			TriggeringCard = null;
			DoubledPowers.Clear();
			IsFinishedTriggering = false;
			base.Status = RelicStatus.Normal;
			return Task.CompletedTask;
		}

		/// <summary>
		/// If we've doubled an <see cref="T:MegaCrit.Sts2.Core.Models.ITemporaryPower" /> and now we're trying to double its internal debuff,
		/// skip it so we don't double-dip.
		/// </summary>
		/// <example>
		/// If we've doubled <see cref="T:MegaCrit.Sts2.Core.Models.Powers.PiercingWailPower" />, we don't also want to double negative <see cref="T:MegaCrit.Sts2.Core.Models.Powers.DexterityPower" />,
		/// because that'll end up quadrupling it.
		/// </example>
		private bool HasDoubledTemporaryPowerSource(PowerModel power)
		{
			return DoubledPowers.OfType<ITemporaryPower>().Any((ITemporaryPower p) => p.InternallyAppliedPower.GetType() == power.GetType());
		}
	}
	public sealed class Vajra : RelicModel
	{
