			Swift canonicalSwift = ModelDb.Enchantment<Swift>();
			List<CardCreationResult> list = cardRewards.Where((CardCreationResult r) => canonicalSwift.CanEnchant(r.Card)).ToList();
			if (list.Count == 0)
			{
