			CardModel card = base.Owner.RunState.CloneCard(cardCreationResult.Card);
			CardCmd.Enchant<Swift>(card, base.DynamicVars["SwiftAmount"].BaseValue);
			cardCreationResult.ModifyCard(card, this);
			return true;
		}
