	public sealed class WongosMysteryTicket : RelicModel
	{
		private const string _remainingCombatsKey = "RemainingCombats";

		public const int combatsToActivate = 5;

		public const int relicCount = 3;

		private int _combatsFinished;

		private bool _gaveRelic;

		public override RelicRarity Rarity => RelicRarity.Event;

		public override bool IsUsedUp => GaveRelic;

		public override bool ShowCounter => DisplayAmount > 0;

		public override int DisplayAmount => 5 - CombatsFinished;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new RepeatVar(3),
			new DynamicVar("RemainingCombats", 5m)
		});

		[SavedProperty]
		public int CombatsFinished
		{
			get
			{
				return _combatsFinished;
			}
			set
			{
				AssertMutable();
				_combatsFinished = value;
				InvokeDisplayAmountChanged();
			}
		}

		[SavedProperty]
		public bool GaveRelic
		{
			get
			{
				return _gaveRelic;
			}
			set
			{
				AssertMutable();
				_gaveRelic = value;
				InvokeDisplayAmountChanged();
				if (_gaveRelic)
				{
					base.Status = RelicStatus.Disabled;
				}
			}
		}

		public override Task AfterCombatEnd(CombatRoom _)
		{
			CombatsFinished++;
			int num = 5 - CombatsFinished;
			base.DynamicVars["RemainingCombats"].BaseValue = decimal.Max(num, 0m);
			return Task.CompletedTask;
		}

		public override bool TryModifyRewards(Player player, List<Reward> rewards, AbstractRoom? room)
		{
			if (player != base.Owner)
			{
				return false;
			}
			if (!(room is CombatRoom))
			{
				return false;
			}
			if (GaveRelic)
			{
				return false;
			}
			int num = 5 - CombatsFinished;
			if (num > 0)
			{
				return false;
			}
			for (int i = 0; i < base.DynamicVars.Repeat.IntValue; i++)
			{
				rewards.Add(new RelicReward(player));
			}
			return true;
		}

		public override Task AfterModifyingRewards()
		{
			Flash();
			GaveRelic = true;
			return Task.CompletedTask;
		}
	}
	public sealed class YummyCookie : RelicModel
	{
		private static CharacterModel? _cachedRandomCharacter;

		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool HasUponPickupEffect => true;

		protected override string IconBaseName
		{
			get
			{
				CharacterModel characterModel;
				if (base.IsCanonical || base.Owner == null)
				{
					if (_cachedRandomCharacter == null)
					{
						_cachedRandomCharacter = Rng.Chaotic.NextItem(ModelDb.AllCharacters);
					}
					characterModel = _cachedRandomCharacter;
				}
				else
				{
					characterModel = base.Owner.Character;
				}
				if (!(characterModel is Ironclad))
				{
					if (!(characterModel is Silent))
					{
						if (!(characterModel is Regent))
						{
							if (!(characterModel is Necrobinder))
							{
								if (characterModel is Defect)
								{
									return "yummy_cookie_defect";
								}
								return "yummy_cookie_ironclad";
							}
							return "yummy_cookie_necro";
						}
						return "yummy_cookie_regent";
					}
					return "yummy_cookie_silent";
				}
				return "yummy_cookie_ironclad";
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new CardsVar(4));

		protected override void AfterCloned()
		{
			base.AfterCloned();
			RelicIconChanged();
		}

		public override async Task AfterObtained()
		{
			List<CardModel> list = (await CardSelectCmd.FromDeckForUpgrade(prefs: new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, base.DynamicVars.Cards.IntValue), player: base.Owner)).ToList();
			foreach (CardModel item in list)
			{
				CardCmd.Upgrade(item);
			}
		}
	}
