namespace MegaCrit.Sts2.Core.Models.Powers
{
	/// <summary>
	/// This power doesn't actually do anything on its own. Instead, the Poison power checks for this power and
	/// re-triggers itself if it's there.
	/// </summary>
	public sealed class AccelerantPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromPower<PoisonPower>());
	}
	public sealed class AccuracyPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override decimal ModifyDamageAdditive(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? card, CardPlay? cardPlay)
		{
			if (base.Owner != dealer)
			{
				return 0m;
			}
			if (!props.IsPoweredAttack())
			{
				return 0m;
			}
			if (card == null)
			{
				return 0m;
			}
			if (!card.Tags.Contains(CardTag.Shiv))
			{
				return 0m;
			}
			return base.Amount;
		}
	}
	public sealed class AdaptablePower : PowerModel
	{
		private class Data
		{
			public bool isReviving;
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		private bool IsReviving => GetInternalData<Data>().isReviving;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public void DoRevive()
		{
			GetInternalData<Data>().isReviving = false;
		}

		public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (!wasRemovalPrevented && creature == base.Owner && creature.Monster is TestSubject testSubject)
			{
				GetInternalData<Data>().isReviving = true;
				await testSubject.TriggerDeadState();
			}
		}

		/// <summary>
		/// This is so the Test Subject doesn't receive powers while it is reviving
		/// </summary>
		public override bool ShouldAllowHitting(Creature creature)
		{
			if (creature != base.Owner)
			{
				return true;
			}
			return !IsReviving;
		}

		public override bool ShouldStopCombatFromEnding()
		{
			return true;
		}

		public override bool ShouldCreatureBeRemovedFromCombatAfterDeath(Creature creature)
		{
			if (creature != base.Owner)
			{
				return true;
			}
			return false;
		}

		public override bool ShouldPowerBeRemovedAfterOwnerDeath()
		{
			return false;
		}
	}
	public sealed class AfterimagePower : PowerModel
	{
		private class Data
		{
			/// <summary>
			/// Keep track of the cards we've seen played and the power amount at the time they were played.
			/// This lets After Image avoid triggering on cards that started play before it was applied, and avoid gaining
			/// extra block on multiple plays of After Image.
			/// </summary>
			public readonly System.Collections.Generic.Dictionary<CardModel, int> amountsForPlayedCards = new System.Collections.Generic.Dictionary<CardModel, int>();
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner.Creature != base.Owner)
			{
				return Task.CompletedTask;
			}
			GetInternalData<Data>().amountsForPlayedCards.Add(cardPlay.Card, base.Amount);
			return Task.CompletedTask;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner.Creature == base.Owner && GetInternalData<Data>().amountsForPlayedCards.Remove(cardPlay.Card, out var value) && value > 0)
			{
				await CreatureCmd.GainBlock(base.Owner, value, ValueProp.Unpowered, null, fast: true);
			}
		}
	}
	public sealed class AggressionPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override async Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner))
			{
				return;
			}
			CardPile pile = PileType.Discard.GetPile(base.Owner.Player);
			IEnumerable<CardModel> source = pile.Cards.Where((CardModel c) => c.Type == CardType.Attack);
			IEnumerable<CardModel> enumerable = source.ToList().UnstableShuffle(base.Owner.Player.RunState.Rng.CombatCardSelection).Take(base.Amount);
			foreach (CardModel card in enumerable)
			{
				await CardPileCmd.Add(card, PileType.Hand);
				if (card.IsUpgradable)
				{
					CardCmd.Upgrade(card);
				}
			}
		}
	}
