	public sealed class CallOfTheVoidPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Ethereal));

		public override async Task BeforeHandDraw(Player player, PlayerChoiceContext choiceContext, ICombatState combatState)
		{
			if (player != base.Owner.Player)
			{
				return;
			}
			IReadOnlyList<CardModel> readOnlyList = base.Owner.Player.Character.CardPool.GetUnlockedCards(player.UnlockState, player.RunState.CardMultiplayerConstraint).Where(delegate(CardModel c)
			{
				CardRarity rarity = c.Rarity;
				bool flag = ((rarity == CardRarity.Basic || rarity == CardRarity.Ancient) ? true : false);
				return !flag;
			}).ToList();
			if (readOnlyList.Count > 0)
			{
				CardModel[] array = new CardModel[base.Amount];
				Rng combatCardGeneration = base.Owner.Player.RunState.Rng.CombatCardGeneration;
				for (int num = 0; num < base.Amount; num++)
				{
					CardCmd.ApplyKeyword(array[num] = CardFactory.GetDistinctForCombat(player, readOnlyList, 1, combatCardGeneration).First(), CardKeyword.Ethereal);
				}
				Flash();
				await CardPileCmd.AddGeneratedCardsToCombat(array, PileType.Hand, base.Owner.Player);
			}
		}
	}
	public sealed class ChainsOfBindingPower : PowerModel
	{
		private class Data
		{
			public bool boundCardPlayed;
		}

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => HoverTipFactory.FromAffliction<Bound>();

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override async Task AfterCardDrawn(PlayerChoiceContext choiceContext, CardModel card, bool fromHandDraw)
		{
			if (card.Owner == base.Owner.Player && base.CombatState.CurrentSide == base.Owner.Side && ModelDb.Affliction<Bound>().CanAfflict(card))
			{
				int num = CombatManager.Instance.History.Entries.OfType<CardAfflictedEntry>().Count((CardAfflictedEntry e) => e.HappenedThisTurn(base.CombatState) && e.Actor == base.Owner && e.Affliction is Bound);
				if (num < base.Amount)
				{
					await CardCmd.AfflictAndPreview<Bound>(new global::<>z__ReadOnlySingleElementList<CardModel>(card), base.Amount, CardPreviewStyle.None);
				}
			}
		}

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			CardModel card = cardPlay.Card;
			if (card.IsDupe)
			{
				return Task.CompletedTask;
			}
			if (card.Owner.Creature != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (!(card.Affliction is Bound))
			{
				return Task.CompletedTask;
			}
			GetInternalData<Data>().boundCardPlayed = true;
			return Task.CompletedTask;
		}

		public override bool ShouldPlay(CardModel card, AutoPlayType autoPlayType)
		{
			if (card.Owner.Creature != base.Owner)
			{
				return true;
			}
			if (!(card.Affliction is Bound))
			{
				return true;
			}
			return !GetInternalData<Data>().boundCardPlayed;
		}

		public override Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (!participants.Contains(base.Owner))
			{
				return Task.CompletedTask;
			}
			GetInternalData<Data>().boundCardPlayed = false;
			IEnumerable<CardModel> enumerable = base.Owner.Player?.PlayerCombatState?.AllCards ?? System.Array.Empty<CardModel>();
			foreach (CardModel item in enumerable)
			{
				if (item.Affliction is Bound)
				{
					CardCmd.ClearAffliction(item);
				}
			}
			return Task.CompletedTask;
		}
	}
