	public sealed class CuriousPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override bool TryModifyEnergyCostInCombat(CardModel card, decimal originalCost, out decimal modifiedCost)
		{
			modifiedCost = originalCost;
			if (card.Owner.Creature != base.Owner)
			{
				return false;
			}
			if (card.Type != CardType.Power)
			{
				return false;
			}
			if (originalCost <= 0m)
			{
				return false;
			}
			modifiedCost = originalCost - (decimal)base.Amount;
			if (modifiedCost < 0m)
			{
				modifiedCost = 0m;
			}
			return true;
		}
	}
	public sealed class CurlUpPower : PowerModel
	{
		private class Data
		{
			public CardModel? playedCard;
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override bool ShouldScaleInMultiplayer => true;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Block));

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult _, ValueProp props, Creature? dealer, CardModel? cardSource)
		{
			if (target != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (!props.IsPoweredAttack())
			{
				return Task.CompletedTask;
			}
			if (cardSource == null)
			{
				return Task.CompletedTask;
			}
			if (GetInternalData<Data>().playedCard != null && cardSource != GetInternalData<Data>().playedCard)
			{
				return Task.CompletedTask;
			}
			GetInternalData<Data>().playedCard = cardSource;
			return Task.CompletedTask;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card == GetInternalData<Data>().playedCard)
			{
				GetInternalData<Data>().playedCard = null;
				SfxCmd.Play("event:/sfx/enemy/enemy_attacks/giant_louse/giant_louse_curl");
				await CreatureCmd.TriggerAnim(base.Owner, "Curl", 0.25f);
				await CreatureCmd.GainBlock(base.Owner, base.Amount, ValueProp.Unpowered, null);
				if (base.Owner.Monster is LouseProgenitor louseProgenitor)
				{
					louseProgenitor.Curled = true;
				}
				await PowerCmd.Remove(this);
			}
		}
	}
	public sealed class DampenPower : PowerModel
	{
		private class Data
		{
			public readonly HashSet<Creature> casters = new HashSet<Creature>();

			public readonly System.Collections.Generic.Dictionary<CardModel, int> downgradedCardsToOldUpgradeLevels = new System.Collections.Generic.Dictionary<CardModel, int>();
		}

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.None;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task AfterApplied(Creature? applier, CardModel? cardSource)
		{
			IEnumerable<CardModel> enumerable = base.Owner.Player.PlayerCombatState.AllCards.Where((CardModel c) => c.IsUpgraded);
			foreach (CardModel item in enumerable)
			{
				GetInternalData<Data>().downgradedCardsToOldUpgradeLevels.Add(item, item.CurrentUpgradeLevel);
				CardCmd.Downgrade(item);
			}
			Flash();
			return Task.CompletedTask;
		}

		public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (wasRemovalPrevented)
			{
				return;
			}
			Data internalData = GetInternalData<Data>();
			if (internalData.casters.Contains(creature))
			{
				internalData.casters.Remove(creature);
				if (internalData.casters.Count == 0)
				{
					await PowerCmd.Remove(this);
				}
			}
		}

		public override Task AfterRemoved(Creature oldOwner)
		{
			foreach (var (card, num2) in GetInternalData<Data>().downgradedCardsToOldUpgradeLevels)
			{
				for (int i = 0; i < num2; i++)
				{
					CardCmd.Upgrade(card);
				}
			}
			return Task.CompletedTask;
		}

		public void AddCaster(Creature creature)
		{
			GetInternalData<Data>().casters.Add(creature);
		}
	}
