	public sealed class GigantificationPower : PowerModel
	{
		private class Data
		{
			public AttackCommand? commandToModify;
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task BeforeAttack(AttackCommand command)
		{
			if (!(command.ModelSource is CardModel cardModel))
			{
				return Task.CompletedTask;
			}
			if (cardModel.Owner.Creature != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (cardModel.Type != CardType.Attack)
			{
				return Task.CompletedTask;
			}
			if (!command.DamageProps.IsPoweredAttack())
			{
				return Task.CompletedTask;
			}
			Data internalData = GetInternalData<Data>();
			if (internalData.commandToModify != null)
			{
				return Task.CompletedTask;
			}
			internalData.commandToModify = command;
			return Task.CompletedTask;
		}

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (cardSource == null)
			{
				return 1m;
			}
			if (cardSource.Owner.Creature != base.Owner)
			{
				return 1m;
			}
			if (!props.IsPoweredAttack())
			{
				return 1m;
			}
			Data internalData = GetInternalData<Data>();
			if (internalData.commandToModify == null || cardSource == internalData.commandToModify.ModelSource)
			{
				return 3m;
			}
			return 1m;
		}

		public override async Task AfterAttack(PlayerChoiceContext choiceContext, AttackCommand command)
		{
			Data internalData = GetInternalData<Data>();
			if (command == internalData.commandToModify)
			{
				internalData.commandToModify = null;
				await PowerCmd.Decrement(this);
			}
		}
	}
	public sealed class GravityPower : PowerModel
	{
		private class Data
		{
			/// <summary>
			/// Keep track of the cards we've seen played and the power amount at the time they were played.
			/// This lets Gravity avoid triggering on cards that started play before it was applied, and avoid applying
			/// extra damage on multiple plays of Gravity Well.
			/// </summary>
			public readonly System.Collections.Generic.Dictionary<CardModel, int> amountsForPlayedCards = new System.Collections.Generic.Dictionary<CardModel, int>();
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner != base.Owner.Player)
			{
				return Task.CompletedTask;
			}
			GetInternalData<Data>().amountsForPlayedCards.Add(cardPlay.Card, base.Amount);
			return Task.CompletedTask;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			GetInternalData<Data>().amountsForPlayedCards.Remove(cardPlay.Card, out var value);
			if (value > 0)
			{
				await CreatureCmd.Damage(choiceContext, base.Owner.CombatState.HittableEnemies, value, ValueProp.Unpowered, base.Owner);
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (participants.Contains(base.Owner))
			{
				Flash();
				await PowerCmd.Remove(this);
			}
		}
	}
