	public sealed class ImitationLearningPower : PowerModel
	{
		private class Data
		{
			public readonly List<(CardModel Card, CardModel Clone)> cardsAndClones = new List<(CardModel, CardModel)>();
		}

		private const string _targetPlayerKey = "TargetPlayer";

		private Player? _playerTarget;

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;

		/// <summary>
		/// The player whose powers we are copying.
		/// This is different than <see cref="P:MegaCrit.Sts2.Core.Models.PowerModel.Target" />, which is used specifically for the case in which an
		/// enemy has multiple of the same power targeting different players. If this kind of concept becomes common, we
		/// can make it first class in PowerModel, or combine it with Target in some way.
		/// </summary>
		public Player PlayerTarget
		{
			get
			{
				return _playerTarget ?? throw new InvalidOperationException();
			}
			set
			{
				AssertMutable();
				_playerTarget = value;
				((StringVar)base.DynamicVars["TargetPlayer"]).StringValue = PlatformUtil.GetPlayerName(RunManager.Instance.NetService.Platform, _playerTarget.NetId);
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new StringVar("TargetPlayer"));

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (_playerTarget == null)
			{
				throw new InvalidOperationException("ImitationLearningPower applied without a player target!");
			}
			if (cardPlay.Card.Owner != _playerTarget)
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card.Type != CardType.Power)
			{
				return Task.CompletedTask;
			}
			if (!cardPlay.IsFirstInSeries)
			{
				return Task.CompletedTask;
			}
			CardModel item = cardPlay.Card.CreateCloneForPlayer(base.Owner.Player);
			GetInternalData<Data>().cardsAndClones.Add((cardPlay.Card, item));
			return Task.CompletedTask;
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			Data internalData = GetInternalData<Data>();
			int num = internalData.cardsAndClones.FindIndex(((CardModel Card, CardModel Clone) p) => p.Card == cardPlay.Card);
			if (num >= 0)
			{
				CardModel clone = internalData.cardsAndClones[num].Clone;
				internalData.cardsAndClones.RemoveAt(num);
				Flash();
				await PowerCmd.Decrement(this);
				await CardCmd.AutoPlay(choiceContext, clone, null);
			}
		}
	}
	public sealed class ImprovementPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override Task AfterCombatEnd(CombatRoom room)
		{
			List<CardModel> list = PileType.Deck.GetPile(base.Owner.Player).Cards.Where((CardModel c) => c.IsUpgradable).ToList();
			for (int num = 0; num < base.Amount; num++)
			{
				if (list.Count == 0)
				{
					break;
				}
				CardModel cardModel = base.Owner.Player.RunState.Rng.CombatCardSelection.NextItem(list);
				list.Remove(cardModel);
				CardCmd.Upgrade(cardModel);
			}
			return Task.CompletedTask;
		}
	}
	public sealed class InfernoPower : PowerModel
	{
		private const string _selfDamageKey = "SelfDamage";

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DamageVar("SelfDamage", 0m, ValueProp.Unblockable | ValueProp.Unpowered));

		public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)
		{
			if (player == base.Owner.Player)
			{
				NCombatRoom.Instance?.CombatVfxContainer.AddChildSafely(NFireSmokePuffVfx.Create(base.Owner));
				await Cmd.CustomScaledWait(0.2f, 0.4f);
				DamageVar damageVar = (DamageVar)base.DynamicVars["SelfDamage"];
				await CreatureCmd.Damage(choiceContext, base.Owner, damageVar.BaseValue, damageVar.Props, base.Owner);
			}
		}

		public override async Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult result, ValueProp props, Creature? dealer, CardModel? cardSource)
		{
			if (target != base.Owner || result.UnblockedDamage <= 0 || base.Owner.CombatState.CurrentSide != base.Owner.Side)
			{
				return;
			}
			foreach (Creature hittableEnemy in base.CombatState.HittableEnemies)
			{
				NFireBurstVfx child = NFireBurstVfx.Create(hittableEnemy, 0.75f);
				NCombatRoom.Instance?.CombatVfxContainer.AddChildSafely(child);
			}
			await CreatureCmd.Damage(choiceContext, base.CombatState.HittableEnemies, base.Amount, ValueProp.Unpowered, base.Owner);
		}

		public void IncrementSelfDamage()
		{
			AssertMutable();
			base.DynamicVars["SelfDamage"].BaseValue++;
		}
	}
	public sealed class InfestedPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature target, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (!wasRemovalPrevented && base.Owner == target)
			{
				List<Creature> wrigglers = new List<Creature>();
				for (int i = 0; i < 4; i++)
				{
					Wriggler wriggler = (Wriggler)ModelDb.Monster<Wriggler>().ToMutable();
					wriggler.StartStunned = true;
					Creature creature = await CreatureCmd.Add(wriggler, base.CombatState, base.Owner.Side, PhrogParasiteElite.GetWrigglerSlotName(i));
					creature.SetNodeVisible(visible: false);
					wrigglers.Add(creature);
				}
				TaskHelper.RunSafely(RevealWrigglersAfterDeathAnim(wrigglers, deathAnimLength));
			}
		}

		private static async Task RevealWrigglersAfterDeathAnim(List<Creature> wrigglers, float deathAnimLength)
		{
			await Cmd.CustomScaledWait(deathAnimLength, deathAnimLength);
			if (TestMode.IsOff)
			{
				NRunMusicController.Instance.TriggerEliteSecondPhase();
			}
			foreach (Creature wriggler in wrigglers)
			{
				wriggler.SetNodeVisible(visible: true);
			}
		}

		public override bool ShouldStopCombatFromEnding()
		{
			return true;
		}
	}
