	public sealed class PlowPower : PowerModel
	{
		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlyArray<IHoverTip>(new IHoverTip[2]
		{
			HoverTipFactory.Static(StaticHoverTip.Stun),
			HoverTipFactory.FromPower<StrengthPower>()
		});

		public override bool ShouldScaleInMultiplayer => true;

		public override async Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult result, ValueProp props, Creature? dealer, CardModel? cardSource)
		{
			if (target != base.Owner || result.UnblockedDamage <= 0 || target.CurrentHp > base.Amount)
			{
				return;
			}
			Flash();
			List<TemporaryStrengthPower> list = base.Owner.GetPowerInstances<TemporaryStrengthPower>().ToList();
			foreach (TemporaryStrengthPower item in list)
			{
				await PowerCmd.Remove(item);
			}
			await PowerCmd.Remove<StrengthPower>(base.Owner);
			MonsterModel monster = base.Owner.Monster;
			if (monster is CeremonialBeast ceremonialBeast)
			{
				await ceremonialBeast.SetStunned();
				await CreatureCmd.Stun(base.Owner, ceremonialBeast.StunnedMove, ceremonialBeast.BeastCryState.StateId);
			}
			else
			{
				await CreatureCmd.Stun(base.Owner);
			}
			await PowerCmd.Remove(this);
		}
	}
	public sealed class PoisonPower : PowerModel
	{
		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override Color AmountLabelColor => PowerModel._normalAmountLabelColor;

		/// <summary>
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Powers.AccelerantPower" /> makes Poison trigger extra times, but it should never trigger more times than the
		/// amount of Poison we have.
		/// Since the power is applied to players, enemy creatures need to look to them (their opponents) to figure out the
		/// trigger count.
		/// </summary>
		private int TriggerCount
		{
			get
			{
				IEnumerable<Creature> source = from c in base.Owner.CombatState.GetOpponentsOf(base.Owner)
					where c.IsAlive
					select c;
				return Math.Min(base.Amount, 1 + source.Sum((Creature a) => a.GetPowerAmount<AccelerantPower>()));
			}
		}

		public int CalculateTotalDamageNextTurn()
		{
			decimal num = 0m;
			int num2 = Math.Min(base.Amount, TriggerCount);
			for (int i = 0; i < num2; i++)
			{
				decimal damage = base.Amount - i;
				damage = Hook.ModifyDamage(base.Owner.CombatState.RunState, base.Owner.CombatState, base.Owner, null, damage, ValueProp.Unblockable | ValueProp.Unpowered, null, null, ModifyDamageHookType.All, CardPreviewMode.None, out IEnumerable<AbstractModel> _);
				num += damage;
			}
			return (int)num;
		}

		public override async Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (participants.Contains(base.Owner))
			{
				await Trigger();
			}
		}

		/// <summary>
		/// Deals the Poison damage and decrements the stacks, once per <see cref="P:MegaCrit.Sts2.Core.Models.Powers.PoisonPower.TriggerCount" />.
		/// </summary>
		public async Task Trigger()
		{
			int iterations = TriggerCount;
			for (int i = 0; i < iterations; i++)
			{
				await CreatureCmd.Damage(new ThrowingPlayerChoiceContext(), base.Owner, base.Amount, ValueProp.Unblockable | ValueProp.Unpowered, null, null);
				if (base.Owner.IsAlive)
				{
					await PowerCmd.Decrement(this);
				}
				else
				{
					await Cmd.CustomScaledWait(0.1f, 0.25f);
				}
			}
		}
	}
	public sealed class PossessSpeedPower : PowerModel
	{
		private class Data
		{
			public System.Collections.Generic.Dictionary<Creature, decimal> stolenDexterity = new System.Collections.Generic.Dictionary<Creature, decimal>();
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromPower<DexterityPower>());

		private System.Collections.Generic.Dictionary<Creature, decimal> StolenDexterity => GetInternalData<Data>().stolenDexterity;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (applier != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (!power.Owner.IsPlayer)
			{
				return Task.CompletedTask;
			}
			if (!(power is DexterityPower))
			{
				return Task.CompletedTask;
			}
			if (amount >= 0m)
			{
				return Task.CompletedTask;
			}
			if (!StolenDexterity.ContainsKey(power.Owner))
			{
				StolenDexterity.Add(power.Owner, 0m);
			}
			StolenDexterity[power.Owner] += amount;
			return Task.CompletedTask;
		}

		public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (wasRemovalPrevented || creature != base.Owner)
			{
				return;
			}
			foreach (KeyValuePair<Creature, decimal> item in StolenDexterity)
			{
				await PowerCmd.Apply<DexterityPower>(choiceContext, item.Key, -item.Value, null, null);
			}
		}
	}
