	public sealed class SlipperyPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override bool ShouldScaleInMultiplayer => true;

		public override decimal ModifyHpLostAfterOsty(Creature target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource)
		{
			if (target != base.Owner)
			{
				return amount;
			}
			if (amount < 1m)
			{
				return amount;
			}
			return 1m;
		}

		public override async Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult result, ValueProp props, Creature? dealer, CardModel? cardSource)
		{
			if (target == base.Owner && result.UnblockedDamage >= 1)
			{
				Flash();
				await PowerCmd.Decrement(this);
			}
		}

		public override decimal GetScaledAmountForMultiplayer(ICombatState combatState, Creature? applier, decimal amount, Creature target, CardModel? cardSource)
		{
			return amount * (decimal)combatState.Players.Count;
		}
	}
	public sealed class SlothPower : PowerModel
	{
		private int _cardsPlayedThisTurn;

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override int DisplayAmount => _cardsPlayedThisTurn;

		public override bool ShouldPlay(CardModel card, AutoPlayType _)
		{
			if (card.Owner.Creature != base.Owner)
			{
				return true;
			}
			return _cardsPlayedThisTurn < base.Amount;
		}

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner != base.Owner.Player)
			{
				return Task.CompletedTask;
			}
			_cardsPlayedThisTurn++;
			InvokeDisplayAmountChanged();
			return Task.CompletedTask;
		}

		public override Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner))
			{
				return Task.CompletedTask;
			}
			_cardsPlayedThisTurn = 0;
			InvokeDisplayAmountChanged();
			return Task.CompletedTask;
		}
	}
	public sealed class SlowPower : PowerModel
	{
		private const string _slowAmountKey = "SlowAmount";

		private const string _displayAmountKey = "DisplayAmount";

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override int DisplayAmount => base.DynamicVars["SlowAmount"].IntValue * 10;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DynamicVar("SlowAmount", 0m),
			new DynamicVar("DisplayAmount", 0m)
		});

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			base.DynamicVars["SlowAmount"].BaseValue++;
			base.DynamicVars["DisplayAmount"].BaseValue = base.DynamicVars["SlowAmount"].BaseValue * 10m;
			InvokeDisplayAmountChanged();
			return Task.CompletedTask;
		}

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target != base.Owner)
			{
				return 1m;
			}
			if (!props.IsPoweredAttack())
			{
				return 1m;
			}
			return 1m + 0.1m * base.DynamicVars["SlowAmount"].BaseValue;
		}

		public override Task AfterModifyingDamageAmount(CardModel? cardSource)
		{
			Flash();
			return Task.CompletedTask;
		}

		public override Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner))
			{
				return Task.CompletedTask;
			}
			base.DynamicVars["SlowAmount"].BaseValue = 0m;
			base.DynamicVars["DisplayAmount"].BaseValue = 0m;
			InvokeDisplayAmountChanged();
			return Task.CompletedTask;
		}
	}
	public sealed class SlumberPower : PowerModel
	{
