	public sealed class SurprisePower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature target, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (wasRemovalPrevented || base.Owner != target)
			{
				return;
			}
			Creature fatGremlin = base.CombatState.CreateCreature(ModelDb.Monster<FatGremlin>().ToMutable(), CombatSide.Enemy, "fat");
			int totalStolen = 0;
			foreach (ThieveryPower powerInstance in base.Owner.GetPowerInstances<ThieveryPower>())
			{
				int intValue = powerInstance.DynamicVars.Gold.IntValue;
				totalStolen += intValue;
				HeistPower heistPower = (HeistPower)ModelDb.Power<HeistPower>().ToMutable();
				heistPower.Target = powerInstance.Target;
				await PowerCmd.Apply(choiceContext, heistPower, fatGremlin, intValue, base.Owner, null);
			}
			await CreatureCmd.Add<SneakyGremlin>(base.CombatState, "sneaky");
			await CreatureCmd.Add(fatGremlin);
			if (totalStolen > 0 && base.CombatState.Encounter is GremlinMercNormal gremlinMercNormal)
			{
				gremlinMercNormal.MarkGoldStolen();
			}
		}

		public override bool ShouldStopCombatFromEnding()
		{
			return true;
		}
	}
	public sealed class SurroundedPower : PowerModel
	{
		public enum Direction
		{
			Right,
			Left
		}

		private const string _kaiserCrabDirectionCustomTrackName = "kaiser_crab_direction";

		private Direction _facing;

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Single;

		public Direction Facing
		{
			get
			{
				return _facing;
			}
			private set
			{
				AssertMutable();
				_facing = value;
			}
		}

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (dealer == null)
			{
				return 1m;
			}
			if (target != base.Owner)
			{
				return 1m;
			}
			switch (Facing)
			{
			case Direction.Right:
				if (!dealer.HasPower<BackAttackLeftPower>())
				{
					return 1m;
				}
				break;
			case Direction.Left:
				if (!dealer.HasPower<BackAttackRightPower>())
				{
					return 1m;
				}
				break;
			}
			return 1.5m;
		}

		public override async Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (cardPlay.Target != null && cardPlay.Card.Owner == base.Owner.Player)
			{
				await UpdateDirection(cardPlay.Target);
			}
		}

		public override async Task BeforePotionUsed(PotionModel potion, Creature? target)
		{
			if (CombatManager.Instance.IsInProgress && target != null && potion.Owner == base.Owner.Player)
			{
				await UpdateDirection(target);
			}
		}

		public override async Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (!wasRemovalPrevented && creature.Side != base.Owner.Side)
			{
				IReadOnlyList<Creature> hittableEnemies = base.Owner.CombatState.HittableEnemies;
				if (hittableEnemies.Count != 0 && (hittableEnemies.All((Creature e) => e.HasPower<BackAttackLeftPower>()) || hittableEnemies.All((Creature e) => e.HasPower<BackAttackRightPower>())))
				{
					await UpdateDirection(hittableEnemies[0]);
				}
			}
		}

		private async Task UpdateDirection(Creature target)
		{
			switch (Facing)
			{
			case Direction.Right:
				if (target.HasPower<BackAttackLeftPower>())
				{
					await FaceDirection(Direction.Left);
				}
				break;
			case Direction.Left:
				if (target.HasPower<BackAttackRightPower>())
				{
					await FaceDirection(Direction.Right);
				}
				break;
			}
		}

		private async Task FaceDirection(Direction direction)
		{
			Facing = direction;
			Creature owner = base.Owner;
			IReadOnlyList<Creature> pets = base.Owner.Pets;
			int num = 0;
			Creature[] array = new Creature[1 + pets.Count];
			array[num] = owner;
			num++;
			foreach (Creature item in pets)
			{
				array[num] = item;
				num++;
			}
			IEnumerable<Creature> source = new global::<>z__ReadOnlyArray<Creature>(array);
			IEnumerable<Node2D> enumerable = source.Select((Creature c) => NCombatRoom.Instance?.GetCreatureNode(c)?.Body);
			IEnumerable<Control?> formVfxHolders = source.Select((Creature c) => NCombatRoom.Instance?.GetCreatureNode(c)?.Visuals.FormVfxHolder);
			foreach (Node2D item2 in enumerable)
			{
				await FlipScale(item2);
			}
			foreach (Control item3 in formVfxHolders)
			{
				await FlipScale(item3);
			}
			if (LocalContext.GetMe(base.Owner.CombatState) == base.Owner.Player)
			{
				NRunMusicController.Instance?.UpdateMusicParameter("kaiser_crab_direction", (Facing == Direction.Left) ? 1 : 2);
			}
		}

		private Task FlipScale(Node2D? body)
		{
			if (body == null)
			{
				return Task.CompletedTask;
			}
			float x = body.Scale.X;
			if ((Facing == Direction.Right && x < 0f) || (Facing == Direction.Left && x > 0f))
			{
				body.Scale *= new Godot.Vector2(-1f, 1f);
			}
			return Task.CompletedTask;
		}

		private Task FlipScale(Control? body)
		{
			if (body == null)
			{
				return Task.CompletedTask;
			}
			float x = body.Scale.X;
			if ((Facing == Direction.Right && x < 0f) || (Facing == Direction.Left && x > 0f))
			{
				body.Scale *= new Godot.Vector2(-1f, 1f);
			}
			return Task.CompletedTask;
		}
	}
	public sealed class SwipePower : PowerModel
	{
		private CardModel? _stolenCard;

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;

		public CardModel? StolenCard
		{
			get
			{
				return _stolenCard;
			}
			set
			{
				AssertMutable();
				_stolenCard = value;
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips
		{
			get
			{
				if (StolenCard == null)
				{
					return System.Array.Empty<IHoverTip>();
				}
				return new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromCard(StolenCard));
			}
		}

		public override Task BeforeDeath(Creature target)
		{
			if (base.Owner != target)
			{
				return Task.CompletedTask;
			}
			if (StolenCard?.DeckVersion == null)
			{
				return Task.CompletedTask;
			}
			IRunState runState = base.CombatState.RunState;
			runState.AddCard(StolenCard.DeckVersion, base.Target.Player);
			SpecialCardReward specialCardReward = new SpecialCardReward(StolenCard.DeckVersion, base.Target.Player);
			specialCardReward.SetCustomDescriptionEncounterSource(ModelDb.Encounter<ThievingHopperWeak>().Id);
			((CombatRoom)runState.CurrentRoom).AddExtraReward(base.Target.Player, specialCardReward);
			runState.CurrentMapPointHistoryEntry?.GetEntry(base.Target.Player.NetId).MarkLootReturned();
			return Task.CompletedTask;
		}

		public async Task Steal(CardModel card)
		{
			base.Target = card.Owner.Creature;
			StolenCard = card;
			if (card.DeckVersion != null)
			{
				await CardPileCmd.RemoveFromDeck(card.DeckVersion, showPreview: false);
				card.Owner.RunState.CurrentMapPointHistoryEntry?.GetEntry(card.Owner.NetId).MarkLootStolen();
			}
		}
	}
	public sealed class SwordSagePower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips
		{
			get
			{
				List<IHoverTip> list = new List<IHoverTip>();
				list.AddRange(HoverTipFactory.FromCardWithCardHoverTips<SovereignBlade>());
				list.Add(HoverTipFactory.Static(StaticHoverTip.ReplayStatic));
				return new <>z__ReadOnlyList<IHoverTip>(list);
			}
		}

		public override Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (!(power is SwordSagePower))
			{
				return Task.CompletedTask;
			}
			if (power.Owner != base.Owner)
			{
				return Task.CompletedTask;
			}
			IEnumerable<CardModel> enumerable = base.Owner.Player?.PlayerCombatState?.AllCards ?? System.Array.Empty<CardModel>();
			foreach (CardModel item in enumerable)
			{
				TryAddReplays(item, (int)amount);
			}
			return Task.CompletedTask;
		}

		public override Task AfterCardEnteredCombat(CardModel card)
		{
			if (card.IsClone)
			{
				return Task.CompletedTask;
			}
			TryAddReplays(card, base.Amount);
			return Task.CompletedTask;
		}

		public override Task AfterRemoved(Creature oldOwner)
		{
			IEnumerable<CardModel> enumerable = oldOwner.Player?.PlayerCombatState?.AllCards ?? System.Array.Empty<CardModel>();
			foreach (CardModel item in enumerable)
			{
				if (item is SovereignBlade sovereignBlade)
				{
					sovereignBlade.BaseReplayCount -= base.Amount;
				}
			}
			return Task.CompletedTask;
		}

		private void TryAddReplays(CardModel card, int amount)
		{
			if (card.Owner == base.Owner.Player && card is SovereignBlade sovereignBlade)
			{
				sovereignBlade.BaseReplayCount += amount;
			}
		}
	}
