	public sealed class TagTeamPower : PowerModel
	{
		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;

		public override int DisplayAmount => 1;

		public override int ModifyCardPlayCount(CardModel card, Creature? target, int playCount)
		{
			if (card.Type != CardType.Attack)
			{
				return playCount;
			}
			if (card.Owner.Creature == base.Applier)
			{
				return playCount;
			}
			if (card.TargetType == TargetType.AnyEnemy && target != base.Owner)
			{
				return playCount;
			}
			TargetType targetType = card.TargetType;
			if ((uint)(targetType - 2) > 1u)
			{
				return playCount;
			}
			return playCount + base.Amount;
		}

		public override async Task AfterModifyingCardPlayCount(CardModel card)
		{
			await PowerCmd.Remove(this);
		}
	}
	public sealed class TaintedPower : PowerModel
	{
		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override decimal ModifyDamageAdditive(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target != base.Owner)
			{
				return 0m;
			}
			if (!props.IsPoweredAttack())
			{
				return 0m;
			}
			return base.Amount;
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (side == CombatSide.Enemy)
			{
				Flash();
				await PowerCmd.Remove(this);
			}
		}
	}
	public sealed class TangledPower : PowerModel
	{
		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new EnergyVar(1));

		public override async Task AfterApplied(Creature? applier, CardModel? cardSource)
		{
			IEnumerable<CardModel> enumerable = base.Owner.Player.PlayerCombatState.AllCards.Where((CardModel c) => c.Type == CardType.Attack);
			foreach (CardModel item in enumerable)
			{
				await CardCmd.Afflict<Entangled>(item, 1m);
			}
		}

		public override async Task AfterCardEnteredCombat(CardModel card)
		{
			if (card.Owner == base.Owner.Player && card.Affliction == null && card.Type == CardType.Attack)
			{
				await CardCmd.Afflict<Entangled>(card, 1m);
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (participants.Contains(base.Owner))
			{
				Flash();
				await PowerCmd.Remove(this);
			}
		}

		public override Task AfterRemoved(Creature oldOwner)
		{
			IEnumerable<CardModel> enumerable = oldOwner.Player.PlayerCombatState.AllCards.Where((CardModel c) => c.Affliction is Entangled);
			foreach (CardModel item in enumerable)
			{
				CardCmd.ClearAffliction(item);
			}
			return Task.CompletedTask;
		}

		public override bool TryModifyEnergyCostInCombat(CardModel card, decimal originalCost, out decimal modifiedCost)
		{
			if (!(card.Affliction is Entangled) || card.Owner != base.Owner.Player)
			{
				modifiedCost = originalCost;
				return false;
			}
			modifiedCost = originalCost + (decimal)base.Amount;
			return true;
		}
	}
	public sealed class TankPower : PowerModel
	{
		private const string _damageIncreaseKey = "DamageIncrease";

		private const string _damageDecreaseKey = "DamageDecrease";

		public const decimal damageIncrease = 1.5m;

		public const decimal damageDecrease = 0.5m;

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DynamicVar("DamageIncrease", 1.5m),
			new DynamicVar("DamageDecrease", 0.5m)
		});

		public override async Task AfterApplied(Creature? applier, CardModel? cardSource)
		{
			foreach (Creature item in base.CombatState.GetTeammatesOf(base.Owner))
			{
				if (item.IsAlive && item.IsPlayer && item != base.Owner)
				{
					await PowerCmd.Apply<GuardedPower>(new ThrowingPlayerChoiceContext(), item, base.Amount, base.Owner, null);
				}
			}
		}

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target != base.Owner)
			{
				return 1m;
			}
			if (!props.IsPoweredAttack())
			{
				return 1m;
			}
			return base.DynamicVars["DamageIncrease"].BaseValue;
		}
	}
	/// <summary>
	/// This class represents a buff/debuff that gives/takes dexterity.
	/// We never instantiate this directly. See <see cref="T:MegaCrit.Sts2.Core.Models.Powers.TemporaryStrengthPower" /> for context around how this is used.
	/// </summary>
	public abstract class TemporaryDexterityPower : PowerModel, ITemporaryPower
	{
		public override PowerType Type
		{
			get
			{
				if (!IsPositive)
				{
					return PowerType.Debuff;
				}
				return PowerType.Buff;
			}
		}

		public override PowerStackType StackType => PowerStackType.Counter;

		/// <summary>
		/// The canonical model that applies this power. For example, <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Anticipate" />.
		/// </summary>
		public abstract AbstractModel OriginModel { get; }

		public PowerModel InternallyAppliedPower => ModelDb.Power<DexterityPower>();

		/// <summary>
		/// If this power is supposed to apply negative dexterity, make this false
		/// </summary>
		protected virtual bool IsPositive => true;

		/// <summary>
		/// Shorthand indicating the sign of the amount to apply
		/// </summary>
		private int Sign
		{
			get
			{
				if (!IsPositive)
				{
					return -1;
				}
				return 1;
			}
		}

		public override LocString Title
		{
			get
			{
				AbstractModel originModel = OriginModel;
				if (!(originModel is CardModel cardModel))
				{
					if (!(originModel is PotionModel potionModel))
					{
						if (originModel is RelicModel relicModel)
						{
							return relicModel.Title;
						}
						throw new InvalidOperationException();
					}
					return potionModel.Title;
				}
				return cardModel.TitleLocString;
			}
		}

		public override LocString Description => new LocString("powers", IsPositive ? "TEMPORARY_DEXTERITY_POWER.description" : "TEMPORARY_DEXTERITY_DOWN.description");

		protected override string SmartDescriptionLocKey
		{
			get
			{
				if (!IsPositive)
				{
					return "TEMPORARY_DEXTERITY_DOWN.smartDescription";
				}
				return "TEMPORARY_DEXTERITY_POWER.smartDescription";
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips
		{
			get
			{
				List<IHoverTip> list = new List<IHoverTip>();
				List<IHoverTip> list2 = list;
				AbstractModel originModel = OriginModel;
				IEnumerable<IHoverTip> collection;
				if (!(originModel is CardModel card))
				{
					if (!(originModel is PotionModel))
					{
						if (!(originModel is RelicModel relic))
						{
							throw new InvalidOperationException();
						}
						collection = HoverTipFactory.FromRelic(relic);
					}
					else
					{
						collection = System.Array.Empty<IHoverTip>();
					}
				}
				else
				{
					collection = new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromCard(card));
				}
				list2.AddRange(collection);
				list.Add(HoverTipFactory.FromPower<DexterityPower>());
				return new <>z__ReadOnlyList<IHoverTip>(list);
			}
		}

		public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)
		{
			await PowerCmd.Apply<DexterityPower>(new ThrowingPlayerChoiceContext(), target, (decimal)Sign * amount, applier, cardSource, silent: true);
		}

		public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (!(amount == (decimal)base.Amount) && power == this)
			{
				await PowerCmd.Apply<DexterityPower>(choiceContext, base.Owner, (decimal)Sign * amount, applier, cardSource, silent: true);
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (participants.Contains(base.Owner))
			{
				Flash();
				await PowerCmd.Remove(this);
				await PowerCmd.Apply<DexterityPower>(choiceContext, base.Owner, -Sign * base.Amount, base.Owner, null);
			}
		}
	}
