	/// <summary>
	/// This class represents a buff/debuff that gives/takes strength.
	/// This class is never instantiated directly. Instead, it is subclassed and those classes represent the buff/debuff.
	/// Every model that grants a temporary strength power creates an associated power that subclasses this. For example,
	/// FlexPotion has FlexPotionPower which grants strength and then takes it away at the end of the turn.
	/// This used to be called Strength Down (or Restore Strength for negative strength) and be its own power. We switched
	/// to this model so make the UX more clear for players; both Strength and Temporary Strength are a buff.
	/// </summary>
	public abstract class TemporaryStrengthPower : PowerModel, ITemporaryPower
	{
		public override PowerType Type
		{
			get
			{
				if (!IsPositive)
				{
					return PowerType.Debuff;
				}
				return PowerType.Buff;
			}
		}

		public override PowerStackType StackType => PowerStackType.Counter;

		/// <summary>
		/// The canonical model that applies this power. For example, <see cref="T:MegaCrit.Sts2.Core.Models.Potions.FlexPotion" />.
		/// </summary>
		public abstract AbstractModel OriginModel { get; }

		public PowerModel InternallyAppliedPower => ModelDb.Power<StrengthPower>();

		/// <summary>
		/// If this power is supposed to apply negative strength, make this false
		/// </summary>
		protected virtual bool IsPositive => true;

		/// <summary>
		/// Shorthand indicating the sign of the amount to apply
		/// </summary>
		private int Sign
		{
			get
			{
				if (!IsPositive)
				{
					return -1;
				}
				return 1;
			}
		}

		public override LocString Title
		{
			get
			{
				AbstractModel originModel = OriginModel;
				if (!(originModel is CardModel cardModel))
				{
					if (!(originModel is PotionModel potionModel))
					{
						if (originModel is RelicModel relicModel)
						{
							return relicModel.Title;
						}
						throw new InvalidOperationException();
					}
					return potionModel.Title;
				}
				return cardModel.TitleLocString;
			}
		}

		public override LocString Description => new LocString("powers", IsPositive ? "TEMPORARY_STRENGTH_POWER.description" : "TEMPORARY_STRENGTH_DOWN.description");

		protected override string SmartDescriptionLocKey
		{
			get
			{
				if (!IsPositive)
				{
					return "TEMPORARY_STRENGTH_DOWN.smartDescription";
				}
				return "TEMPORARY_STRENGTH_POWER.smartDescription";
			}
		}

		protected override IEnumerable<IHoverTip> ExtraHoverTips
		{
			get
			{
				List<IHoverTip> list = new List<IHoverTip>();
				List<IHoverTip> list2 = list;
				AbstractModel originModel = OriginModel;
				IEnumerable<IHoverTip> collection;
				if (!(originModel is CardModel card))
				{
					if (!(originModel is PotionModel))
					{
						if (!(originModel is RelicModel relic))
						{
							throw new InvalidOperationException();
						}
						collection = HoverTipFactory.FromRelic(relic);
					}
					else
					{
						collection = System.Array.Empty<IHoverTip>();
					}
				}
				else
				{
					collection = new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromCard(card));
				}
				list2.AddRange(collection);
				list.Add(HoverTipFactory.FromPower<StrengthPower>());
				return new <>z__ReadOnlyList<IHoverTip>(list);
			}
		}

		public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)
		{
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), target, (decimal)Sign * amount, applier, cardSource, silent: true);
		}

		public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (!(amount == (decimal)base.Amount) && power == this)
			{
				await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, (decimal)Sign * amount, applier, cardSource, silent: true);
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (participants.Contains(base.Owner))
			{
				Flash();
				await PowerCmd.Remove(this);
				await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, -Sign * base.Amount, base.Owner, null);
			}
		}
	}
	public sealed class TenderPower : PowerModel
	{
		private int _cardsPlayedThisTurn;

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override int DisplayAmount => CardsPlayedThisTurn;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlyArray<IHoverTip>(new IHoverTip[2]
		{
			HoverTipFactory.FromPower<StrengthPower>(),
			HoverTipFactory.FromPower<DexterityPower>()
		});

		private int CardsPlayedThisTurn
		{
			get
			{
				return _cardsPlayedThisTurn;
			}
			set
			{
				AssertMutable();
				_cardsPlayedThisTurn = value;
				InvokeDisplayAmountChanged();
			}
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner == base.Owner.Player)
			{
				CardsPlayedThisTurn++;
				Flash();
				await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, -1m, base.Applier, null, silent: true);
				await PowerCmd.Apply<DexterityPower>(choiceContext, base.Owner, -1m, base.Applier, null, silent: true);
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (participants.Contains(base.Owner))
			{
				await PowerCmd.Apply<StrengthPower>(choiceContext, base.Owner, CardsPlayedThisTurn, base.Applier, null, silent: true);
				await PowerCmd.Apply<DexterityPower>(choiceContext, base.Owner, CardsPlayedThisTurn, base.Applier, null, silent: true);
				CardsPlayedThisTurn = 0;
			}
		}
	}
