		public override decimal ModifyBlockMultiplicative(Creature target, decimal block, ValueProp props, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target.IsMonster)
			{
				return 1m;
			}
			if (!props.IsCardOrMonsterMove())
			{
				return 1m;
			}
			if (cardSource != null && cardSource.Owner.Creature != base.Owner)
			{
				return 1m;
			}
			int num = CombatManager.Instance.History.Entries.OfType<BlockGainedEntry>().Count((BlockGainedEntry e) => e.HappenedThisTurn(base.CombatState) && e.CardPlay != null && e.CardPlay.Player.Creature == base.Owner && e.Props.IsCardOrMonsterMove() && e.CardPlay != cardPlay);
			if (num >= base.Amount)
			{
				return 1m;
			}
			return 2m;
		}
	}
	public sealed class VeilpiercerPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Ethereal));

		public override bool TryModifyEnergyCostInCombatLate(CardModel card, decimal originalCost, out decimal modifiedCost)
		{
			modifiedCost = originalCost;
			if (card.Owner.Creature != base.Owner)
			{
				return false;
			}
			if (!card.Keywords.Contains(CardKeyword.Ethereal))
			{
				return false;
			}
			bool flag;
			switch (card.Pile?.Type)
			{
			case PileType.Hand:
			case PileType.Play:
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			if (!flag)
			{
				return false;
			}
			modifiedCost = 0m;
			return true;
		}

		public override async Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner.Creature == base.Owner && cardPlay.Card.Keywords.Contains(CardKeyword.Ethereal))
			{
				bool flag;
				switch (cardPlay.Card.Pile?.Type)
				{
				case PileType.Hand:
				case PileType.Play:
					flag = true;
					break;
				default:
					flag = false;
					break;
				}
				if (flag)
				{
					await PowerCmd.Decrement(this);
				}
			}
		}
	}
