	public sealed class VigorPower : PowerModel
	{
		private class Data
		{
			public AttackCommand? commandToModify;

			public int amountWhenAttackStarted;
		}

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task BeforeAttack(AttackCommand command)
		{
			if (command.Attacker != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (!command.DamageProps.IsPoweredAttack())
			{
				return Task.CompletedTask;
			}
			Data internalData = GetInternalData<Data>();
			if (internalData.commandToModify != null)
			{
				return Task.CompletedTask;
			}
			if (command.ModelSource != null && !(command.ModelSource is CardModel))
			{
				return Task.CompletedTask;
			}
			if (!command.DamageProps.IsPoweredAttack())
			{
				return Task.CompletedTask;
			}
			internalData.commandToModify = command;
			internalData.amountWhenAttackStarted = base.Amount;
			return Task.CompletedTask;
		}

		public override decimal ModifyDamageAdditive(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (base.Owner != dealer)
			{
				return 0m;
			}
			if (!props.IsPoweredAttack())
			{
				return 0m;
			}
			Data internalData = GetInternalData<Data>();
			if (internalData.commandToModify != null && cardSource != null && cardSource != internalData.commandToModify.ModelSource)
			{
				return 0m;
			}
			if (internalData.commandToModify != null && internalData.commandToModify.Attacker != dealer)
			{
				return 0m;
			}
			return base.Amount;
		}

		public override async Task AfterAttack(PlayerChoiceContext choiceContext, AttackCommand command)
		{
			Data internalData = GetInternalData<Data>();
			if (command == internalData.commandToModify)
			{
				await PowerCmd.ModifyAmount(choiceContext, this, -internalData.amountWhenAttackStarted, null, null);
			}
		}
	}
	public sealed class VitalSparkPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new StringVar("AfflictionTitle", ModelDb.Affliction<Tainted>().Title.GetFormattedText()));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => HoverTipFactory.FromAffliction<Tainted>(base.Amount);

		public override async Task BeforeCombatStart()
		{
			foreach (Creature item in base.Owner.CombatState.Allies.ToList())
			{
				if (!item.IsPlayer)
				{
					continue;
				}
				IEnumerable<CardModel> enumerable = item.Player.PlayerCombatState.AllCards.Where((CardModel c) => c.Type == CardType.Skill);
				foreach (CardModel item2 in enumerable)
				{
					await CardCmd.Afflict<Tainted>(item2, base.Amount);
				}
			}
		}

		public override async Task AfterCardEnteredCombat(CardModel card)
		{
			if (card.Affliction == null && card.Type == CardType.Skill)
			{
				await CardCmd.Afflict<Tainted>(card, base.Amount);
			}
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Affliction is Tainted)
			{
				Flash();
				await PowerCmd.Apply<TaintedPower>(choiceContext, cardPlay.Card.Owner.Creature, base.Amount, null, null);
			}
		}

		public override Task AfterRemoved(Creature oldOwner)
		{
			if (oldOwner.CombatState == null)
			{
				return Task.CompletedTask;
			}
			foreach (Creature item in oldOwner.CombatState.Allies.ToList())
			{
				if (!item.IsPlayer)
				{
					continue;
				}
				IEnumerable<CardModel> enumerable = item.Player.PlayerCombatState.AllCards.Where((CardModel c) => c.Affliction is Tainted);
				foreach (CardModel item2 in enumerable)
				{
					CardCmd.ClearAffliction(item2);
				}
			}
			return Task.CompletedTask;
		}

		public override Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (power != this)
			{
				return Task.CompletedTask;
			}
			foreach (Creature item in base.Owner.CombatState.Allies.ToList())
			{
				if (!item.IsPlayer)
				{
					continue;
				}
				IEnumerable<CardModel> enumerable = item.Player.PlayerCombatState.AllCards.Where((CardModel c) => c.Affliction is Tainted);
				foreach (CardModel item2 in enumerable)
				{
					item2.Affliction.Amount = base.Amount;
				}
			}
			return Task.CompletedTask;
		}
	}
	public sealed class VoidFormPower : PowerModel
	{
		private class Data
		{
			public int cardsPlayedThisTurn;
		}

		private NVoidFormVfx? _vfx;

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		private NVoidFormVfx? Vfx
		{
			get
			{
				if (_vfx == null)
				{
					return _vfx;
				}
				if (!_vfx.IsValid())
				{
					return null;
				}
				return _vfx;
			}
			set
			{
				AssertMutable();
				_vfx = value;
			}
		}

		public override Task AfterApplied(Creature? applier, CardModel? cardSource)
		{
			Vfx = NVoidFormVfx.Create(base.Owner);
			return Task.CompletedTask;
		}

		public override Task AfterRemoved(Creature oldOwner)
		{
			Vfx?.SetActive(isActive: false);
			return Task.CompletedTask;
		}

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override Task BeforePowerAmountChanged(PowerModel power, decimal amount, Creature target, Creature? applier, CardModel? cardSource)
		{
			if (power != this)
			{
				return Task.CompletedTask;
			}
			HideTemporaryZeroCostVisual();
			return Task.CompletedTask;
		}

		public override Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)
		{
			HideTemporaryZeroCostVisual();
			return Task.CompletedTask;
		}

		public override bool TryModifyEnergyCostInCombatLate(CardModel card, decimal originalCost, out decimal modifiedCost)
		{
			modifiedCost = originalCost;
			if (ShouldSkip(card))
			{
				return false;
			}
			modifiedCost = 0m;
			return true;
		}

		public override bool TryModifyStarCost(CardModel card, decimal originalCost, out decimal modifiedCost)
		{
			modifiedCost = originalCost;
			if (ShouldSkip(card))
			{
				return false;
			}
			modifiedCost = 0m;
			return true;
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner.Creature == base.Owner && cardPlay != null && !cardPlay.IsAutoPlay && cardPlay.IsLastInSeries)
			{
				GetInternalData<Data>().cardsPlayedThisTurn++;
			}
			if (GetInternalData<Data>().cardsPlayedThisTurn >= base.Amount)
			{
				Vfx?.SetActive(isActive: false);
			}
			return Task.CompletedTask;
		}

		public override Task BeforeSideTurnStart(PlayerChoiceContext choiceContext, CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (!participants.Contains(base.Owner))
			{
				return Task.CompletedTask;
			}
			GetInternalData<Data>().cardsPlayedThisTurn = 0;
			Vfx?.SetActive(isActive: true);
			return Task.CompletedTask;
		}

		private bool ShouldSkip(CardModel card)
		{
			bool flag = card.Owner.Creature != base.Owner;
			bool flag2 = flag;
			if (!flag2)
			{
				bool flag3;
				switch (card.Pile?.Type)
				{
				case PileType.Hand:
				case PileType.Play:
					flag3 = true;
					break;
				default:
					flag3 = false;
					break;
				}
				flag2 = !flag3;
			}
			if (!flag2)
			{
				return GetInternalData<Data>().cardsPlayedThisTurn >= base.Amount;
			}
			return true;
		}

		/// <summary>
		/// HACK: If Void Form is the first card played in a turn, there's a brief period before the turn is auto-ended
		/// where we show a zero energy cost on all cards.
		/// To avoid this, we max out cardsPlayedThisTurn, which doesn't matter anyways since the turn is ending.
		/// </summary>
		private void HideTemporaryZeroCostVisual()
		{
			GetInternalData<Data>().cardsPlayedThisTurn = 999999999;
		}
	}
	public sealed class VulnerablePower : PowerModel
	{
		private const string _damageIncrease = "DamageIncrease";

		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("DamageIncrease", 1.5m));

		/// <summary>
		/// Multiplies damage received by 1.5x.
		/// </summary>
		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target != base.Owner)
			{
				return 1m;
			}
			if (!props.IsPoweredAttack())
			{
				return 1m;
			}
			decimal num = base.DynamicVars["DamageIncrease"].BaseValue;
			if (dealer != null)
			{
				PaperPhrog paperPhrog = dealer.Player?.GetRelic<PaperPhrog>();
				if (paperPhrog != null)
				{
					num = paperPhrog.ModifyVulnerableMultiplier(target, num, props, dealer, cardSource);
				}
				CrueltyPower crueltyPower = dealer.GetPower<CrueltyPower>() ?? dealer.PetOwner?.Creature.GetPower<CrueltyPower>();
				if (crueltyPower != null)
				{
					num = crueltyPower.ModifyVulnerableMultiplier(target, num, props, dealer, cardSource);
				}
			}
			DebilitatePower power = target.GetPower<DebilitatePower>();
			if (power != null)
			{
				num = power.ModifyVulnerableMultiplier(target, num, props, dealer, cardSource);
			}
			return num;
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (side == CombatSide.Enemy)
			{
				await PowerCmd.TickDownDuration(this);
			}
		}
	}
