		private decimal _evokeVal = 6m;

		protected override string ChannelSfx => "event:/sfx/characters/defect/defect_dark_channel";

		public override Color DarkenedColor => new Color("9001d3");

		public override decimal PassiveVal => ModifyOrbValue(6m);

		public override decimal EvokeVal => _evokeVal;

		public override async Task BeforeTurnEndOrbTrigger(PlayerChoiceContext choiceContext)
		{
			await TriggerPassive(choiceContext, null);
		}

		public override Task Passive(PlayerChoiceContext choiceContext, Creature? target)
		{
			if (target != null)
			{
				throw new InvalidOperationException("Dark orbs cannot target creatures.");
			}
			ActivatePassive();
			_evokeVal += PassiveVal;
			NCombatRoom.Instance?.GetCreatureNode(base.Owner.Creature)?.OrbManager?.UpdateVisuals(OrbEvokeType.None);
			return Task.CompletedTask;
		}

		public override async Task<IEnumerable<Creature>> Evoke(PlayerChoiceContext playerChoiceContext)
		{
			IReadOnlyList<Creature> hittableEnemies = base.CombatState.HittableEnemies;
			if (hittableEnemies.Count == 0)
			{
				return System.Array.Empty<Creature>();
			}
			PlayEvokeSfx();
			Creature weakestEnemy = hittableEnemies.MinBy((Creature c) => c.CurrentHp);
			ActivateEvoke(new Creature[1] { weakestEnemy });
			await CreatureCmd.Damage(playerChoiceContext, weakestEnemy, EvokeVal, ValueProp.Unpowered, base.Owner.Creature);
			return new global::<>z__ReadOnlySingleElementList<Creature>(weakestEnemy);
		}
	}
	public class FrostOrb : OrbModel
	{
		protected override string ChannelSfx => "event:/sfx/characters/defect/defect_frost_channel";

		public override Color DarkenedColor => new Color("7860a7");

		public override decimal PassiveVal => ModifyOrbValue(2m);

		public override decimal EvokeVal => ModifyOrbValue(5m);

		public override async Task BeforeTurnEndOrbTrigger(PlayerChoiceContext choiceContext)
		{
			await TriggerPassive(choiceContext, null);
		}

		public override async Task Passive(PlayerChoiceContext choiceContext, Creature? target)
		{
			if (target != null)
			{
				throw new InvalidOperationException("Frost orbs cannot target creatures.");
			}
			ActivatePassive();
			PlayPassiveSfx();
			await CreatureCmd.GainBlock(base.Owner.Creature, PassiveVal, ValueProp.Unpowered, null);
			if (!base.Owner.Creature.HasPower<HibernatePower>())
			{
				return;
			}
			foreach (Player player in base.CombatState.Players)
			{
				if (player != base.Owner)
				{
					await CreatureCmd.GainBlock(player.Creature, PassiveVal, ValueProp.Unpowered, null);
				}
			}
		}

		public override async Task<IEnumerable<Creature>> Evoke(PlayerChoiceContext playerChoiceContext)
		{
			PlayEvokeSfx();
			ActivateEvoke(new Creature[1] { base.Owner.Creature });
			await CreatureCmd.GainBlock(base.Owner.Creature, EvokeVal, ValueProp.Unpowered, null);
			if (base.Owner.Creature.HasPower<HibernatePower>())
			{
				foreach (Player player in base.CombatState.Players)
				{
					if (player != base.Owner)
					{
						await CreatureCmd.GainBlock(player.Creature, EvokeVal, ValueProp.Unpowered, null);
					}
				}
				return base.CombatState.Players.Select((Player p) => p.Creature);
			}
			return new global::<>z__ReadOnlySingleElementList<Creature>(base.Owner.Creature);
		}
	}
	public class GlassOrb : OrbModel
	{
		private decimal _passiveVal = 4m;

		protected override string ChannelSfx => "event:/sfx/characters/defect/defect_glass_channel";

		public override Color DarkenedColor => new Color("008585");

		public override decimal PassiveVal => ModifyOrbValue(_passiveVal);

		public override decimal EvokeVal => PassiveVal * 2m;

		public override async Task BeforeTurnEndOrbTrigger(PlayerChoiceContext choiceContext)
		{
			await TriggerPassive(choiceContext, null);
		}

		public override async Task Passive(PlayerChoiceContext choiceContext, Creature? target)
		{
			List<Creature> targets = base.CombatState.HittableEnemies.Where((Creature e) => e.IsHittable).ToList();
			decimal passiveVal = PassiveVal;
			if (!(passiveVal <= 0m))
			{
				ActivatePassive();
				PlayPassiveSfx();
				_passiveVal = Math.Max(0m, _passiveVal - 1m);
				await CreatureCmd.Damage(choiceContext, targets, passiveVal, ValueProp.Unpowered, base.Owner.Creature);
			}
		}

		public override async Task<IEnumerable<Creature>> Evoke(PlayerChoiceContext playerChoiceContext)
		{
			List<Creature> enemies = base.CombatState.HittableEnemies.Where((Creature e) => e.IsHittable).ToList();
			if (EvokeVal <= 0m)
			{
				return System.Array.Empty<Creature>();
			}
			ActivateEvoke(enemies.ToArray());
			await CreatureCmd.Damage(playerChoiceContext, enemies, EvokeVal, ValueProp.Unpowered, base.Owner.Creature);
			return enemies;
		}
	}
	public class LightningOrb : OrbModel
	{
		protected override string PassiveSfx => "event:/sfx/characters/defect/defect_lightning_passive";

		protected override string EvokeSfx => "event:/sfx/characters/defect/defect_lightning_evoke";

		protected override string ChannelSfx => "event:/sfx/characters/defect/defect_lightning_channel";

		public override Color DarkenedColor => new Color("796606");

		public override decimal PassiveVal => ModifyOrbValue(3m);

		public override decimal EvokeVal => ModifyOrbValue(8m);

		public override async Task BeforeTurnEndOrbTrigger(PlayerChoiceContext choiceContext)
		{
			await TriggerPassive(choiceContext, null);
		}

		public override async Task Passive(PlayerChoiceContext choiceContext, Creature? target)
		{
			ActivatePassive();
			await ApplyLightningDamage(PassiveVal, target, choiceContext, isEvoke: false);
		}

		public override async Task<IEnumerable<Creature>> Evoke(PlayerChoiceContext playerChoiceContext)
		{
			return await ApplyLightningDamage(EvokeVal, null, playerChoiceContext, isEvoke: true);
		}

		private async Task<IEnumerable<Creature>> ApplyLightningDamage(decimal value, Creature? target, PlayerChoiceContext choiceContext, bool isEvoke)
		{
			List<Creature> list = (from e in base.CombatState.GetOpponentsOf(base.Owner.Creature)
				where e.IsHittable
				select e).ToList();
			if (list.Count == 0)
			{
				return System.Array.Empty<Creature>();
			}
			IReadOnlyList<Creature> targets = ((target == null) ? new global::<>z__ReadOnlySingleElementList<Creature>(base.Owner.RunState.Rng.CombatTargets.NextItem(list)) : new global::<>z__ReadOnlySingleElementList<Creature>(target));
			if (isEvoke)
			{
				ActivateEvoke(targets.ToArray());
			}
			foreach (Creature item in targets)
			{
				VfxCmd.PlayOnCreature(item, "vfx/vfx_attack_lightning");
			}
			PlayEvokeSfx();
			await CreatureCmd.Damage(choiceContext, targets, value, ValueProp.Unpowered, base.Owner.Creature);
			return targets;
		}
	}
