		{
			IEnumerable<CorpseSlug> enumerable = monsters.OfType<CorpseSlug>();
			int num = rng.NextInt(3);
			foreach (CorpseSlug item in enumerable)
			{
				item.StarterMoveIdx = num % 3;
				num++;
			}
		}

