	/// <summary>
	/// Represents a monster that has been removed from the game. Mostly used for the run history.
	/// </summary>
	public sealed class DeprecatedMonster : MonsterModel
	{
		public override int MinInitialHp => 0;

		public override int MaxInitialHp => 0;

		public override bool HasDeathSfx => false;

		public override IEnumerable<string> AssetPaths => System.Array.Empty<string>();

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			MoveState moveState = new MoveState("STUB", (IReadOnlyList<Creature> _) => Task.CompletedTask, new HiddenIntent());
			moveState.FollowUpState = moveState;
			return new MonsterMoveStateMachine(new global::<>z__ReadOnlySingleElementList<MonsterState>(moveState), moveState);
		}
	}
	public sealed class DevotedSculptor : MonsterModel
	{
		private static readonly LocString _forbiddenIncantationDialogue = new LocString("monsters", "DEVOTED_SCULPTOR.moves.FORBIDDEN_INCANTATION.banter");

		private readonly int _ritualGain = 9;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 172, 162);

		public override int MaxInitialHp => MinInitialHp;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Fur;

		private int SavageDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 15, 12);

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("FORBIDDEN_INCANTATION_MOVE", ForbiddenIncantationMove, new BuffIntent());
			MoveState moveState2 = (MoveState)(moveState.FollowUpState = new MoveState("SAVAGE_MOVE", SavageMove, new SingleAttackIntent(SavageDamage)));
			moveState2.FollowUpState = moveState2;
			list.Add(moveState);
			list.Add(moveState2);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task ForbiddenIncantationMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play(CastSfx);
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0f);
			await Cmd.Wait(0.3f);
			VfxCmd.PlayOnCreatureCenter(base.Creature, "vfx/vfx_scream");
			TalkCmd.Play(_forbiddenIncantationDialogue, base.Creature, VfxColor.Blue);
			await Cmd.CustomScaledWait(0.75f, 1f);
			await PowerCmd.Apply<RitualPower>(new ThrowingPlayerChoiceContext(), base.Creature, _ritualGain, null, null);
		}

		private async Task SavageMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SavageDamage).FromMonster(this).WithAttackerAnim("Attack", 0.3f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}
	}
	public sealed class Entomancer : MonsterModel
	{
		private const string _rangedAttackMove = "attack_ranged";

		private const string _attackRangedSfx = "event:/sfx/enemy/enemy_attacks/entomancer/entomancer_attack_ranged";

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 165, 145);

		public override int MaxInitialHp => MinInitialHp;

		private int SpearMoveDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 20, 18);

		private int BeesRepeat => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 8, 7);

		private int BeesDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 3, 3);

		public override string DeathSfx => "event:/sfx/enemy/enemy_attacks/entomancer/entomancer_die";

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			await PowerCmd.Apply<PersonalHivePower>(new ThrowingPlayerChoiceContext(), base.Creature, 1m, base.Creature, null);
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("PHEROMONE_SPIT_MOVE", SpitMove, new BuffIntent());
			MoveState moveState2 = new MoveState("BEES_MOVE", BeesMove, new MultiAttackIntent(BeesDamage, BeesRepeat));
			MoveState moveState3 = (MoveState)(moveState2.FollowUpState = new MoveState("SPEAR_MOVE", SpearMove, new SingleAttackIntent(SpearMoveDamage)));
			moveState3.FollowUpState = moveState;
			moveState.FollowUpState = moveState2;
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			return new MonsterMoveStateMachine(list, moveState2);
		}

		private async Task SpitMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play(CastSfx);
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.5f);
			PersonalHivePower personalHivePower = base.Creature.Powers.OfType<PersonalHivePower>().FirstOrDefault();
			if (personalHivePower == null || personalHivePower.Amount >= 3)
			{
				await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, 2m, base.Creature, null);
				return;
			}
			await PowerCmd.Apply<PersonalHivePower>(new ThrowingPlayerChoiceContext(), base.Creature, 1m, base.Creature, null);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, 1m, base.Creature, null);
		}

		private async Task BeesMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(BeesDamage).WithHitCount(BeesRepeat).FromMonster(this)
				.WithAttackerAnim("attack_ranged", 0.3f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/entomancer/entomancer_attack_ranged")
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task SpearMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SpearMoveDamage).FromMonster(this).WithAttackerAnim("Attack", 0.25f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/entomancer/entomancer_attack_ranged")
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("cast");
			AnimState animState3 = new AnimState("attack");
			AnimState animState4 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			AnimState animState5 = new AnimState("attack_ranged");
			animState2.NextState = animState;
			animState3.NextState = animState;
			animState5.NextState = animState;
			animState4.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Cast", animState2);
			creatureAnimator.AddAnyState("Attack", animState3);
			creatureAnimator.AddAnyState("attack_ranged", animState5);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", animState4);
			return creatureAnimator;
		}
	}
	public sealed class Exoskeleton : MonsterModel
	{
		private const string _buffTrigger = "Buff";

		private const int _buffAmount = 2;

		private const string _heavyAttackTrigger = "HeavyAttack";

		private const string _attackHeavySfx = "event:/sfx/enemy/enemy_attacks/roaches/roaches_attack_heavy";

		private const string _buffSfx = "event:/sfx/enemy/enemy_attacks/roaches/roaches_buff";

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 26, 24);

		public override int MaxInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 30, 28);

		private int SkitterDamage => 1;

		private int SkitterRepeats => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 4, 3);

		private int MandiblesDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 9, 8);

		protected override string AttackSfx => "event:/sfx/enemy/enemy_attacks/roaches/roaches_attack";

		public override string DeathSfx => "event:/sfx/enemy/enemy_attacks/roaches/roaches_die";

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Insect;

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			await PowerCmd.Apply<HardToKillPower>(new ThrowingPlayerChoiceContext(), base.Creature, 9m, base.Creature, null);
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("SKITTER_MOVE", SkitterMove, new MultiAttackIntent(SkitterDamage, SkitterRepeats));
			MoveState moveState2 = new MoveState("MANDIBLES_MOVE", MandiblesMove, new SingleAttackIntent(MandiblesDamage));
			MoveState moveState3 = new MoveState("ENRAGE_MOVE", EnrageMove, new BuffIntent());
			RandomBranchState randomBranchState = new RandomBranchState("RAND");
			randomBranchState.AddBranch(moveState, MoveRepeatType.CannotRepeat, 1f);
			randomBranchState.AddBranch(moveState2, MoveRepeatType.CannotRepeat, 1f);
			ConditionalBranchState conditionalBranchState = new ConditionalBranchState("INIT_MOVE");
			conditionalBranchState.AddState(moveState, () => base.Creature.SlotName == "first");
			conditionalBranchState.AddState(moveState2, () => base.Creature.SlotName == "second");
			conditionalBranchState.AddState(moveState3, () => base.Creature.SlotName == "third");
			conditionalBranchState.AddState(randomBranchState, () => base.Creature.SlotName == "fourth");
			moveState.FollowUpState = randomBranchState;
			moveState2.FollowUpState = moveState3;
			moveState3.FollowUpState = randomBranchState;
			list.Add(conditionalBranchState);
			list.Add(randomBranchState);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			return new MonsterMoveStateMachine(list, conditionalBranchState);
		}

		private async Task SkitterMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SkitterDamage).WithHitCount(SkitterRepeats).FromMonster(this)
				.OnlyPlayAnimOnce()
				.WithAttackerAnim("Attack", 0.15f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task MandiblesMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(MandiblesDamage).FromMonster(this).WithAttackerAnim("HeavyAttack", 0.3f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/roaches/roaches_attack_heavy")
				.WithHitFx("vfx/vfx_bite")
				.Execute(null);
		}

		private async Task EnrageMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/roaches/roaches_buff");
			await CreatureCmd.TriggerAnim(base.Creature, "Buff", 0.3f);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, 2m, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState state = new AnimState("die");
			AnimState animState2 = new AnimState("hurt");
			AnimState animState3 = new AnimState("cast");
			AnimState animState4 = new AnimState("buff");
			AnimState animState5 = new AnimState("attack");
			AnimState animState6 = new AnimState("attack_heavy");
			animState5.NextState = animState;
			animState3.NextState = animState;
			animState4.NextState = animState;
			animState2.NextState = animState;
			animState6.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Hit", animState2);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Cast", animState3);
			creatureAnimator.AddAnyState("Attack", animState5);
			creatureAnimator.AddAnyState("HeavyAttack", animState6);
			creatureAnimator.AddAnyState("Buff", animState4);
			return creatureAnimator;
		}
	}
