		private async Task CurlAndGrowMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/giant_louse/giant_louse_curl");
			await CreatureCmd.TriggerAnim(base.Creature, "Curl", 0.25f);
			await CreatureCmd.GainBlock(base.Creature, CurlBlock, ValueProp.Move, null);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, GrowStrength, base.Creature, null);
			Curled = true;
		}

		private async Task PounceMove(IReadOnlyList<Creature> targets)
		{
			if (Curled)
			{
				SfxCmd.Play("event:/sfx/enemy/enemy_attacks/giant_louse/giant_louse_uncurl");
				await CreatureCmd.TriggerAnim(base.Creature, "Uncurl", 0.9f);
				Curled = false;
			}
			await DamageCmd.Attack(PounceDamage).FromMonster(this).WithAttackerAnim("Attack", 0.2f)
				.WithAttackerFx(null, AttackSfx)
				.Execute(null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("curl");
			AnimState animState3 = new AnimState("uncurl");
			AnimState animState4 = new AnimState("curled_loop", isLooping: true);
			AnimState animState5 = new AnimState("attack");
			AnimState animState6 = new AnimState("attack_web");
			AnimState animState7 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			AnimState state2 = new AnimState("die_curled");
			animState.AddBranch("Curl", animState2);
			animState.AddBranch("Attack", animState5);
			animState.AddBranch("Web", animState6);
			animState.AddBranch("Hit", animState7);
			animState.AddBranch("Dead", state);
			animState2.NextState = animState4;
			animState4.AddBranch("Uncurl", animState3);
			animState4.AddBranch("Dead", state2);
			animState5.NextState = animState;
			animState5.AddBranch("Hit", animState7);
			animState5.AddBranch("Dead", state);
			animState6.NextState = animState;
			animState6.AddBranch("Hit", animState7);
			animState6.AddBranch("Dead", state);
			animState7.NextState = animState;
			animState7.AddBranch("Hit", animState7);
			animState7.AddBranch("Dead", state);
			animState7.AddBranch("Curl", animState2);
			animState3.NextState = animState;
			return new CreatureAnimator(animState, controller);
		}
	}
	public sealed class MagiKnight : MonsterModel
	{
		private static readonly LocString _dampenDialogue = new LocString("powers", "DAMPEN_POWER.banter");

		private const string _prepMove = "PREP_MOVE";

		private const string _bombTrigger = "BombCast";

		private const string _ramAttackTrigger = "RamAttack";

		private const string _shieldTrigger = "ShieldAttack";

		private const string _ramSfx = "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_attack_ram";

		private const string _bombSfx = "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_attack_bomb";

		private const string _castShieldSfx = "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_cast_shield";

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 89, 82);

		public override int MaxInitialHp => MinInitialHp;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Armor;

		private int PowerShieldDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 7, 6);

		private int PowerShieldBlock => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 9, 5);

		private int SpearDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 11, 10);

		private int BombDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 40, 35);

		public override string HurtSfx => "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_hurt";

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("POWER_SHIELD_MOVE", PowerShieldMove, new SingleAttackIntent(PowerShieldDamage), new DefendIntent());
			MoveState moveState2 = new MoveState("DAMPEN_MOVE", DampenMove, new DebuffIntent());
			MoveState moveState3 = new MoveState("PREP_MOVE", PrepMove, new DefendIntent());
			MoveState moveState4 = new MoveState("MAGIC_BOMB", MagicBombMove, new SingleAttackIntent(BombDamage));
			MoveState moveState5 = new MoveState("RAM_MOVE", SpearMove, new SingleAttackIntent(SpearDamage));
			moveState.FollowUpState = moveState2;
			moveState2.FollowUpState = moveState5;
			moveState5.FollowUpState = moveState3;
			moveState3.FollowUpState = moveState4;
			moveState4.FollowUpState = moveState5;
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState5);
			list.Add(moveState3);
			list.Add(moveState4);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task DampenMove(IReadOnlyList<Creature> targets)
		{
			foreach (Creature target in targets)
			{
				DampenPower dampenPower = target.GetPower<DampenPower>();
				bool flag = dampenPower == null;
				if (flag)
				{
					dampenPower = (DampenPower)ModelDb.Power<DampenPower>().ToMutable();
				}
				dampenPower.AddCaster(base.Creature);
				if (flag)
				{
					await PowerCmd.Apply(new ThrowingPlayerChoiceContext(), dampenPower, target, 1m, base.Creature, null);
				}
			}
			TalkCmd.Play(_dampenDialogue, base.Creature, VfxColor.Orange, VfxDuration.Long);
			await Cmd.Wait(0.5f);
		}

		private async Task PowerShieldMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(PowerShieldDamage).FromMonster(this).WithAttackerAnim("ShieldAttack", 0.6f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_cast_shield")
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
			await CreatureCmd.GainBlock(base.Creature, PowerShieldBlock, ValueProp.Move, null);
		}

		private async Task PrepMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_cast_shield");
			await CreatureCmd.TriggerAnim(base.Creature, "ShieldAttack", 0.6f);
			await CreatureCmd.GainBlock(base.Creature, PowerShieldBlock, ValueProp.Move, null);
		}

		private async Task MagicBombMove(IReadOnlyList<Creature> targets)
		{
			if (TestMode.IsOff && base.CombatState.IsLiveCombat())
			{
				NCreature nCreature = null;
				foreach (Creature target in targets)
				{
					NCreature creatureNode = target.GetCreatureNode();
					if (creatureNode != null && (nCreature == null || nCreature.GlobalPosition.X > creatureNode.GlobalPosition.X))
					{
						nCreature = creatureNode;
					}
				}
				NCreature creatureNode2 = base.Creature.GetCreatureNode();
				Node2D node2D = creatureNode2?.GetSpecialNode<Node2D>("Visuals/AttackDistanceControl");
				if (creatureNode2 != null && node2D != null && nCreature != null)
				{
					float num = 600f * creatureNode2.Visuals.Scale.X;
					node2D.GlobalPosition = new Godot.Vector2(nCreature.GlobalPosition.X + num, node2D.GlobalPosition.Y);
				}
			}
			await DamageCmd.Attack(BombDamage).FromMonster(this).WithAttackerAnim("BombCast", 1.2f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_attack_bomb")
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}

		private async Task SpearMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SpearDamage).FromMonster(this).WithAttackerAnim("RamAttack", 1.2f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/magi_knight/magi_knight_attack_ram")
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("attack_bomb");
			AnimState animState3 = new AnimState("attack_ram");
			AnimState animState4 = new AnimState("cast_shield");
			AnimState animState5 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			animState2.NextState = animState;
			animState4.NextState = animState;
			animState3.NextState = animState;
			animState5.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", animState5);
			creatureAnimator.AddAnyState("Cast", animState2);
			creatureAnimator.AddAnyState("BombCast", animState2);
			creatureAnimator.AddAnyState("RamAttack", animState3);
			creatureAnimator.AddAnyState("ShieldAttack", animState4);
			return creatureAnimator;
		}

		protected override bool ShouldShowMoveInBestiary(string moveStateId)
		{
			return moveStateId != "PREP_MOVE";
		}
	}
	public sealed class Mawler : MonsterModel
	{
		private const int _clawRepeat = 2;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 76, 72);

		public override int MaxInitialHp => MinInitialHp;

		private int RipAndTearDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 16, 14);

		private int ClawDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 5, 4);

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("RIP_AND_TEAR_MOVE", RipAndTearMove, new SingleAttackIntent(RipAndTearDamage));
			MoveState moveState2 = new MoveState("ROAR_MOVE", RoarMove, new DebuffIntent());
			MoveState moveState3 = new MoveState("CLAW_MOVE", ClawMove, new MultiAttackIntent(ClawDamage, 2));
			RandomBranchState randomBranchState = (RandomBranchState)(moveState3.FollowUpState = (moveState2.FollowUpState = (moveState.FollowUpState = new RandomBranchState("RAND"))));
			randomBranchState.AddBranch(moveState, MoveRepeatType.CannotRepeat, 1f);
			randomBranchState.AddBranch(moveState2, MoveRepeatType.UseOnlyOnce, 1f);
			randomBranchState.AddBranch(moveState3, MoveRepeatType.CannotRepeat, 1f);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			list.Add(randomBranchState);
			return new MonsterMoveStateMachine(list, moveState3);
		}

		private async Task RipAndTearMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(RipAndTearDamage).FromMonster(this).WithAttackerAnim("Attack", 0.35f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
