			MoveState moveState3 = new MoveState("SUCK_MOVE", SuckMove, new SingleAttackIntent(SuckDamage), new BuffIntent());
			ConditionalBranchState conditionalBranchState = new ConditionalBranchState("INIT_MOVE");
			conditionalBranchState.AddState(moveState, () => base.Creature.SlotName == "first");
			conditionalBranchState.AddState(moveState3, () => base.Creature.SlotName == "second");
			moveState.FollowUpState = moveState2;
			moveState2.FollowUpState = moveState3;
			moveState3.FollowUpState = moveState;
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			return new MonsterMoveStateMachine(list, conditionalBranchState);
		}

		private async Task ToxicMove(IReadOnlyList<Creature> targets)
		{
			if (TestMode.IsOff)
			{
				NCreature creatureNode = base.Creature.GetCreatureNode();
				if (creatureNode != null)
				{
					Creature target = LocalContext.GetMe(base.CombatState)?.Creature;
					creatureNode.GetSpecialNode<NMyteVfx>("%NMyteVfx")?.SetTarget(target);
				}
			}
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/mite/mite_cast");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.6f);
			await CardPileCmd.AddToCombatAndPreview<Toxic>(targets, PileType.Hand, 2, null);
		}

		private async Task BiteMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(BiteDamage).FromMonster(this).WithAttackerAnim("Attack", 0.5f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/mite/mite_attack")
				.WithHitFx("vfx/vfx_bite")
				.Execute(null);
		}

		private async Task SuckMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SuckDamage).FromMonster(this).WithAttackerAnim("Suck", 0.4f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/mite/mite_suck")
				.WithHitFx("vfx/vfx_bite")
				.Execute(null);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, SuckStrength, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("cast");
			AnimState animState3 = new AnimState("attack");
			AnimState animState4 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			AnimState animState5 = new AnimState("suck");
			animState2.NextState = animState;
			animState3.NextState = animState;
			animState4.NextState = animState;
			animState5.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Cast", animState2);
			creatureAnimator.AddAnyState("Attack", animState3);
			creatureAnimator.AddAnyState("Suck", animState5);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", animState4);
			return creatureAnimator;
		}
	}
	public sealed class Nibbit : MonsterModel
	{
		private const string _sliceMove = "SLICE_MOVE";

		private bool _isFront;

		private bool _isAlone;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 44, 42);

		public override int MaxInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 48, 46);

		private int ButtDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 13, 12);

		private int SliceBlock => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 6, 5);

		private int SliceDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 7, 6);

		private int HissStrengthGain => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 3, 2);

		public override string DeathSfx => "event:/sfx/enemy/enemy_attacks/nibbit/nibbit_die";

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Slime;

		public bool IsFront
		{
			get
			{
				return _isFront;
			}
			set
			{
				AssertMutable();
				_isFront = value;
			}
		}

		public bool IsAlone
		{
			get
			{
				return _isAlone;
			}
			set
			{
				AssertMutable();
				_isAlone = value;
			}
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("BUTT_MOVE", ButtMove, new SingleAttackIntent(ButtDamage));
			MoveState moveState2 = new MoveState("SLICE_MOVE", SliceMove, new SingleAttackIntent(SliceDamage), new DefendIntent());
			MoveState moveState3 = new MoveState("HISS_MOVE", HissMove, new BuffIntent());
			ConditionalBranchState conditionalBranchState = new ConditionalBranchState("INIT_MOVE");
			if (_isAlone)
			{
				conditionalBranchState.AddState(moveState, () => ((Nibbit)base.Creature.Monster).IsAlone);
			}
			else
			{
				conditionalBranchState.AddState(moveState3, () => !((Nibbit)base.Creature.Monster).IsFront);
				conditionalBranchState.AddState(moveState2, () => ((Nibbit)base.Creature.Monster).IsFront);
			}
			moveState2.FollowUpState = moveState3;
			moveState.FollowUpState = moveState2;
			moveState3.FollowUpState = moveState;
			list.Add(conditionalBranchState);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			return new MonsterMoveStateMachine(list, conditionalBranchState);
		}

		private async Task ButtMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(ButtDamage).FromMonster(this).WithAttackerAnim("Attack", 0.15f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task SliceMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SliceDamage).FromMonster(this).WithAttackerAnim("Attack", 0.15f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
			await CreatureCmd.GainBlock(base.Creature, SliceBlock, ValueProp.Move, null);
		}

		private async Task HissMove(IReadOnlyList<Creature> targets)
		{
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.6f);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, HissStrengthGain, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("hiss");
			AnimState animState3 = new AnimState("attack");
			AnimState animState4 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			animState2.AddNextState(animState);
			animState3.AddNextState(animState);
			animState4.AddNextState(animState);
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Cast", animState2);
			creatureAnimator.AddAnyState("Attack", animState3);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", animState4);
			return creatureAnimator;
		}

		protected override bool ShouldShowMoveInBestiary(string moveStateId)
		{
			return moveStateId != "SLICE_MOVE";
		}
	}
	public sealed class Noisebot : MonsterModel
	{
		private const int _noiseStatusCount = 2;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 19, 18);

		public override int MaxInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 24, 23);

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Armor;

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			if (TestMode.IsOff)
			{
				NCreature creatureNode = NCombatRoom.Instance.GetCreatureNode(base.Creature);
				FabricatorNormal.SetBotFallPosition(creatureNode);
			}
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("NOISE_MOVE", NoiseMove, new StatusIntent(2));
			moveState.FollowUpState = moveState;
			list.Add(moveState);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task NoiseMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play(CastSfx);
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.6f);
			foreach (Creature target in targets)
			{
				Player player = target.Player ?? target.PetOwner;
				CardPileAddResult[] statusCards = new CardPileAddResult[2];
				CardModel card = base.CombatState.CreateCard<Dazed>(player);
				CardPileAddResult[] array = statusCards;
				array[0] = await CardPileCmd.AddGeneratedCardToCombat(card, PileType.Discard, null);
				CardModel card2 = base.CombatState.CreateCard<Dazed>(player);
				array = statusCards;
				array[1] = await CardPileCmd.AddGeneratedCardToCombat(card2, PileType.Draw, null, CardPilePosition.Random);
				if (LocalContext.IsMe(player))
				{
					CardCmd.PreviewCardPileAdd(statusCards);
					await Cmd.Wait(1f);
				}
			}
		}
	}
