		private async Task FadeMove(IReadOnlyList<Creature> targets)
		{
			IsInvisible = true;
			NRunMusicController.Instance?.UpdateMusicParameter("soulfysh_progress", 1f);
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/soul_fysh/soul_fysh_intangible");
			await CreatureCmd.TriggerAnim(base.Creature, "IntangibleStart", 0.8f);
			await PowerCmd.Apply<IntangiblePower>(new ThrowingPlayerChoiceContext(), base.Creature, 2m, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("cast");
			AnimState animState3 = new AnimState("attack_heavy");
			AnimState animState4 = new AnimState("attack_beckon");
			AnimState animState5 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			AnimState animState6 = new AnimState("beckon");
			AnimState nextState = new AnimState("intangible_loop", isLooping: true);
			AnimState animState7 = new AnimState("intangible_start");
			AnimState animState8 = new AnimState("intangible_end");
			AnimState animState9 = new AnimState("hurt_intangible");
			AnimState state2 = new AnimState("die_intangible");
			AnimState animState10 = new AnimState("attack_debuff");
			animState2.NextState = animState;
			animState3.NextState = animState;
			animState4.NextState = animState;
			animState5.NextState = animState;
			animState6.NextState = animState;
			animState7.NextState = nextState;
			animState9.NextState = nextState;
			animState10.NextState = animState8;
			animState8.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Cast", animState2);
			creatureAnimator.AddAnyState("Attack", animState3);
			creatureAnimator.AddAnyState("AttackBeckon", animState4);
			creatureAnimator.AddAnyState("Beckon", animState6);
			creatureAnimator.AddAnyState("IntangibleStart", animState7);
			creatureAnimator.AddAnyState("AttackDebuffTrigger", animState10);
			creatureAnimator.AddAnyState("Dead", state, () => !IsInvisible);
			creatureAnimator.AddAnyState("Hit", animState5, () => !IsInvisible);
			creatureAnimator.AddAnyState("Dead", state2, () => IsInvisible);
			creatureAnimator.AddAnyState("Hit", animState9, () => IsInvisible);
			return creatureAnimator;
		}
	}
	public sealed class SoulNexus : MonsterModel
	{
		private const string _maelstromMove = "MAELSTROM_MOVE";

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 254, 234);

		public override int MaxInitialHp => MinInitialHp;

		private int SoulBurnDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 31, 29);

		private int MaelstromDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 7, 6);

		private int MaelstromRepeat => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 4, 4);

		private int DrainLifeDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 19, 18);

		public override bool ShouldFadeAfterDeath => false;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Magic;

		public override void SetupSkins(MegaSprite spine, MegaSkeleton skeleton)
		{
			spine.GetAnimationState().SetAnimation("tracks/writhe", loop: true, 1);
		}

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			base.Creature.Died += AfterDeath;
		}

		private void AfterDeath(Creature _)
		{
			base.Creature.Died -= AfterDeath;
			NCombatRoom.Instance.GetCreatureNode(base.Creature)?.SpineAnimation.SetAnimation("tracks/empty", loop: true, 1);
		}

		public override void BeforeRemovedFromRoom()
		{
			if (!base.CombatState.RunState.IsGameOver)
			{
				NCombatRoom.Instance?.GetCreatureNode(base.Creature)?.SpineAnimation.SetAnimation("tracks/empty", loop: true, 1);
			}
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("SOUL_BURN_MOVE", SoulBurnMove, new SingleAttackIntent(SoulBurnDamage));
			MoveState moveState2 = new MoveState("MAELSTROM_MOVE", MaelstromMove, new MultiAttackIntent(MaelstromDamage, MaelstromRepeat));
			MoveState moveState3 = new MoveState("DRAIN_LIFE_MOVE", DrainLifeMove, new SingleAttackIntent(DrainLifeDamage), new DebuffIntent(strong: true));
			RandomBranchState randomBranchState = (RandomBranchState)(moveState3.FollowUpState = (moveState2.FollowUpState = (moveState.FollowUpState = new RandomBranchState("RAND"))));
			randomBranchState.AddBranch(moveState, MoveRepeatType.CannotRepeat, 1f);
			randomBranchState.AddBranch(moveState2, MoveRepeatType.CannotRepeat, 1f);
			randomBranchState.AddBranch(moveState3, MoveRepeatType.CannotRepeat, 1f);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			list.Add(randomBranchState);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task SoulBurnMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SoulBurnDamage).FromMonster(this).WithAttackerAnim("Attack", 0.6f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task MaelstromMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(MaelstromDamage).WithHitCount(MaelstromRepeat).FromMonster(this)
				.OnlyPlayAnimOnce()
				.WithAttackerAnim("Attack", 0.2f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task DrainLifeMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(DrainLifeDamage).FromMonster(this).WithAttackerAnim("Cast", 1f)
				.WithAttackerFx(null, CastSfx)
				.Execute(null);
			await PowerCmd.Apply<VulnerablePower>(new ThrowingPlayerChoiceContext(), targets, 2m, base.Creature, null);
			await PowerCmd.Apply<WeakPower>(new ThrowingPlayerChoiceContext(), targets, 2m, base.Creature, null);
		}

		protected override bool ShouldShowMoveInBestiary(string moveStateId)
		{
			return moveStateId != "MAELSTROM_MOVE";
		}
	}
