		{
			IsSpiny = false;
			await DamageCmd.Attack(ExplosionDamage).FromMonster(this).WithAttackerAnim("Unspiked", 0.7f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/spiny_toad/spiny_toad_explode")
