	public class BigGameHunter : ModifierModel
	{
		public override ActMap ModifyGeneratedMap(IRunState runState, ActMap map, int actIndex)
		{
			Rng mapRng = new Rng(runState.Rng.Seed, $"act_{runState.CurrentActIndex + 1}_map");
			MapPointTypeCounts mapPointTypeCountsOverride = new MapPointTypeCounts(map)
			{
				NumOfElites = (int)Math.Round((float)map.GetAllMapPoints().Count((MapPoint p) => p.PointType == MapPointType.Elite) * 2.5f),
				PointTypesThatIgnoreRules = new HashSet<MapPointType> { MapPointType.Elite }
			};
			if (map is StandardActMap)
			{
				bool shouldReplaceTreasureWithElites = map is StandardActMap standardActMap && standardActMap.ShouldReplaceTreasureWithElites;
				return new StandardActMap(mapRng, runState.Act, runState.Players.Count > 1, shouldReplaceTreasureWithElites, runState.Act.HasSecondBoss, mapPointTypeCountsOverride);
			}
			if (map is SpoilsActMap)
			{
				return new SpoilsActMap(runState, mapPointTypeCountsOverride);
			}
			return map;
		}

		public override CardCreationOptions ModifyCardRewardCreationOptions(Player player, CardCreationOptions options)
		{
			if (options.Source != CardCreationSource.Encounter)
			{
				return options;
			}
			if (options.RarityOdds != CardRarityOddsType.EliteEncounter)
			{
				return options;
			}
			if (options.Flags.HasFlag(CardCreationFlags.NoCardPoolModifications))
			{
				return options;
			}
			if (options.Flags.HasFlag(CardCreationFlags.NoRarityModification))
			{
				return options;
			}
			options = options.WithRarityOdds(CardRarityOddsType.Uniform).WithFilter((CardModel c) => c.Rarity == CardRarity.Rare);
			List<CardModel> list = options.GetPossibleCards(player).ToList();
			if (list.Count <= 0)
			{
				options = options.WithCardPools(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(player.Character.CardPool));
			}
			return options;
		}
	}
	public class CharacterCards : ModifierModel
	{
		private ModelId? _characterModel;

		public override LocString Title => ModelDb.GetById<CharacterModel>(CharacterModel).CardsModifierTitle;

		public override LocString Description => ModelDb.GetById<CharacterModel>(CharacterModel).CardsModifierDescription;

		[SavedProperty]
		public ModelId CharacterModel
		{
			get
			{
				return _characterModel ?? throw new InvalidOperationException("CharacterCards modifier used without CharacterModel set!");
			}
			set
			{
				AssertMutable();
				_characterModel = value;
			}
		}

		private CardPoolModel CharacterCardPool => ModelDb.GetById<CharacterModel>(CharacterModel).CardPool;

		public override IEnumerable<CardModel> ModifyMerchantCardPool(Player player, IEnumerable<CardModel> options)
		{
			CardPoolModel cardPool = player.Character.CardPool;
			CardModel[] array = options.ToArray();
			if (array.Any((CardModel c) => c.Pool != cardPool))
			{
				return array;
			}
			return array.Concat(CharacterCardPool.GetUnlockedCards(player.UnlockState, player.RunState.CardMultiplayerConstraint));
		}

		public override CardCreationOptions ModifyCardRewardCreationOptions(Player player, CardCreationOptions options)
		{
			if (options.Flags.HasFlag(CardCreationFlags.NoCardPoolModifications))
			{
				return options;
			}
			if (!options.Flags.HasFlag(CardCreationFlags.IsCardReward))
			{
				return options;
			}
			return options.WithCardPools(options.CardPools.Union(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(CharacterCardPool)));
		}

		public override bool IsEquivalent(ModifierModel other)
		{
			if (base.IsEquivalent(other))
			{
				return ((CharacterCards)other)._characterModel == _characterModel;
			}
			return false;
		}
	}
