		public override IReadOnlyList<LocString> ModifyExtraRestSiteHealText(Player player, IReadOnlyList<LocString> currentExtraText)
		{
			LocString additionalRestSiteHealText = base.AdditionalRestSiteHealText;
			additionalRestSiteHealText.Add("Heal", player.Creature.MaxHp);
			additionalRestSiteHealText.Add("MaxHpLoss", 5m);
			int num = 0;
			LocString[] array = new LocString[1 + currentExtraText.Count];
			foreach (LocString item in currentExtraText)
			{
				array[num] = item;
				num++;
			}
			array[num] = additionalRestSiteHealText;
			return new global::<>z__ReadOnlyArray<LocString>(array);
		}
	}
	public class SealedDeck : ModifierModel
	{
		public override bool ClearsPlayerDeck => true;

		public override Func<Task> GenerateNeowOption(EventModel eventModel)
		{
			return () => ChooseCards(eventModel.Owner);
		}

		private static async Task ChooseCards(Player player)
		{
			CardCreationOptions options = new CardCreationOptions(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(player.Character.CardPool), CardCreationSource.Other, CardRarityOddsType.RegularEncounter).WithFlags(CardCreationFlags.NoUpgradeRoll | CardCreationFlags.ForceRarityOddsChange | CardCreationFlags.IsCardReward);
			IEnumerable<CardCreationResult> source = CardFactory.CreateForReward(player, 30, options).ToList();
			CardSelectorPrefs prefs = new CardSelectorPrefs(new LocString("modifiers", "SEALED_DECK.selectionPrompt"), 10)
			{
				Cancelable = false,
				RequireManualConfirmation = true,
				Comparison = CompareCards
			};
			List<CardModel> cards = (await CardSelectCmd.FromSimpleGridForRewards(new BlockingPlayerChoiceContext(), source.ToList(), player, prefs)).ToList();
			CardCmd.PreviewCardPileAdd(await CardPileCmd.Add(cards, PileType.Deck), 1.2f, CardPreviewStyle.GridLayout);
			foreach (Player player2 in player.RunState.Players)
			{
				player2.RelicGrabBag.Remove<PandorasBox>();
			}
			player.RunState.SharedRelicGrabBag.Remove<PandorasBox>();
		}

		private static int CompareCards(CardModel card1, CardModel card2)
		{
			if (card1.Rarity != card2.Rarity)
			{
				return card1.Rarity.CompareTo(card2.Rarity);
			}
			return string.Compare(card1.Title, card2.Title, LocManager.Instance.CultureInfo, CompareOptions.None);
		}
	}
