	public sealed class AbyssalBaths : EventModel
	{
		private const int _baseDamage = 3;

		private const int _damageScaling = 1;

		private int _lingerCount;

		private int LingerCount
		{
			get
			{
				return _lingerCount;
			}
			set
			{
				AssertMutable();
				_lingerCount = value;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[3]
		{
			new MaxHpVar(2m),
			new DamageVar(3m, ValueProp.Unblockable | ValueProp.Unpowered),
			new HealVar(10m)
		});

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, Immerse, "ABYSSAL_BATHS.pages.INITIAL.options.IMMERSE").ThatDoesDamage((decimal)base.DynamicVars.Damage.IntValue - base.DynamicVars.MaxHp.BaseValue),
				new EventOption(this, Abstain, "ABYSSAL_BATHS.pages.INITIAL.options.ABSTAIN")
			});
		}

		private async Task Immerse()
		{
			await OnImmerse();
			SetEventState(L10NLookup("ABYSSAL_BATHS.pages.IMMERSE.description"), new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, Linger, "ABYSSAL_BATHS.pages.ALL.options.LINGER").ThatDoesDamage((decimal)base.DynamicVars.Damage.IntValue - base.DynamicVars.MaxHp.BaseValue),
				new EventOption(this, ExitBaths, "ABYSSAL_BATHS.pages.ALL.options.EXIT_BATHS")
			}));
		}

		private async Task Abstain()
		{
			await CreatureCmd.Heal(base.Owner.Creature, base.DynamicVars.Heal.IntValue);
			SetEventFinished(L10NLookup("ABYSSAL_BATHS.pages.ABSTAIN.description"));
		}

		private async Task Linger()
		{
			LingerCount++;
			if (LingerCount > 9)
			{
				LingerCount = 9;
			}
			await OnImmerse();
			decimal damage = (decimal)base.DynamicVars.Damage.IntValue - base.DynamicVars.MaxHp.BaseValue;
			if (WillKillPlayer(damage))
			{
				SetEventState(L10NLookup("ABYSSAL_BATHS.pages.DEATH_WARNING.description"), new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
				{
					new EventOption(this, Linger, "ABYSSAL_BATHS.pages.ALL.options.LINGER").ThatDoesDamage(damage),
					new EventOption(this, ExitBaths, "ABYSSAL_BATHS.pages.ALL.options.EXIT_BATHS")
				}));
				return;
			}
			SetEventState(L10NLookup($"ABYSSAL_BATHS.pages.LINGER{LingerCount}.description"), new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, Linger, "ABYSSAL_BATHS.pages.ALL.options.LINGER").ThatDoesDamage(damage),
				new EventOption(this, ExitBaths, "ABYSSAL_BATHS.pages.ALL.options.EXIT_BATHS")
			}));
		}

		private bool WillKillPlayer(decimal damage)
		{
			return (decimal)base.Owner.Creature.CurrentHp <= damage;
		}

		private Task ExitBaths()
		{
			SetEventFinished(L10NLookup("ABYSSAL_BATHS.pages.EXIT_BATHS.description"));
			return Task.CompletedTask;
		}

		private async Task OnImmerse()
		{
			await CreatureCmd.GainMaxHp(base.Owner.Creature, base.DynamicVars.MaxHp.BaseValue);
			await CreatureCmd.Damage(new ThrowingPlayerChoiceContext(), base.Owner.Creature, base.DynamicVars.Damage, null, null, null);
			base.DynamicVars.Damage.BaseValue += 1m;
		}
	}
	public sealed class Amalgamator : EventModel
	{
		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new StringVar("Card1", ModelDb.Card<UltimateStrike>().Title),
			new StringVar("Card2", ModelDb.Card<UltimateDefend>().Title)
		});

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.All((Player p) => p.Deck.Cards.Count((CardModel c) => IsValid(CardTag.Strike, c)) >= 2 && p.Deck.Cards.Count((CardModel c) => IsValid(CardTag.Defend, c)) >= 2);
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, CombineStrikes, InitialOptionKey("COMBINE_STRIKES"), HoverTipFactory.FromCardWithCardHoverTips<UltimateStrike>()),
				new EventOption(this, CombineDefends, InitialOptionKey("COMBINE_DEFENDS"), HoverTipFactory.FromCardWithCardHoverTips<UltimateDefend>())
			});
		}

		private async Task CombineStrikes()
		{
			List<CardModel> cards = (await CardSelectCmd.FromDeckForRemoval(prefs: new CardSelectorPrefs(CardSelectorPrefs.RemoveSelectionPrompt, 2), player: base.Owner, filter: (CardModel c) => IsValid(CardTag.Strike, c))).ToList();
			await CardPileCmd.RemoveFromDeck(cards);
			NDebugAudioManager.Instance?.Play("card_smith.mp3", 1f, PitchVariance.Small);
			NGame.Instance.ScreenShakeTrauma(ShakeStrength.Strong);
			await Task.Delay(300);
			NDebugAudioManager.Instance?.Play("card_smith.mp3", 1f, PitchVariance.Small);
			NGame.Instance.ScreenShakeTrauma(ShakeStrength.Strong);
			CardModel card = base.Owner.RunState.CreateCard<UltimateStrike>(base.Owner);
			CardCmd.PreviewCardPileAdd(await CardPileCmd.Add(card, PileType.Deck), 2f);
			SetEventFinished(L10NLookup("AMALGAMATOR.pages.COMBINE_STRIKES.description"));
		}

		private async Task CombineDefends()
		{
			List<CardModel> cards = (await CardSelectCmd.FromDeckForRemoval(prefs: new CardSelectorPrefs(CardSelectorPrefs.RemoveSelectionPrompt, 2), player: base.Owner, filter: (CardModel c) => IsValid(CardTag.Defend, c))).ToList();
			await CardPileCmd.RemoveFromDeck(cards);
			NDebugAudioManager.Instance?.Play("card_smith.mp3", 1f, PitchVariance.Small);
			NGame.Instance.ScreenShakeTrauma(ShakeStrength.Strong);
			await Task.Delay(300);
			NDebugAudioManager.Instance?.Play("card_smith.mp3", 1f, PitchVariance.Small);
			NGame.Instance.ScreenShakeTrauma(ShakeStrength.Strong);
			CardModel card = base.Owner.RunState.CreateCard<UltimateDefend>(base.Owner);
			CardCmd.PreviewCardPileAdd(await CardPileCmd.Add(card, PileType.Deck), 2f);
			SetEventFinished(L10NLookup("AMALGAMATOR.pages.COMBINE_DEFENDS.description"));
		}

		private static bool IsValid(CardTag tag, CardModel card)
		{
			if (card.Tags.Contains(tag))
			{
				if (card != null && card.Rarity == CardRarity.Basic)
				{
					return card.IsRemovable;
				}
				return false;
			}
			return false;
		}
	}
