	public sealed class ColorfulPhilosophers : EventModel
	{
		private static IEnumerable<CardPoolModel> CardPoolColorOrder => new global::<>z__ReadOnlyArray<CardPoolModel>(new CardPoolModel[5]
		{
			ModelDb.CardPool<NecrobinderCardPool>(),
			ModelDb.CardPool<IroncladCardPool>(),
			ModelDb.CardPool<RegentCardPool>(),
			ModelDb.CardPool<SilentCardPool>(),
			ModelDb.CardPool<DefectCardPool>()
		});

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new CardsVar(3));

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.All((Player p) => p.UnlockState.CharacterCardPools.Count() > 1);
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			List<EventOption> list = new List<EventOption>();
			CharacterModel character = base.Owner.Character;
			List<CardPoolModel> list2 = base.Owner.UnlockState.CharacterCardPools.ToList();
			foreach (CardPoolModel cardPool in CardPoolColorOrder)
			{
				if (character.CardPool != cardPool && list2.Contains(cardPool))
				{
					list.Add(new EventOption(this, () => OfferRewards(cardPool), "COLORFUL_PHILOSOPHERS.pages.INITIAL.options." + cardPool.EnergyColorName.ToUpperInvariant()));
				}
			}
			int num = Mathf.Min(3, list.Count);
			while (list.Count > num)
			{
				list.RemoveAt(base.Rng.NextInt(list.Count));
			}
			return list;
		}

		private async Task OfferRewards(CardPoolModel pool)
		{
			CardCreationOptions options = new CardCreationOptions(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(pool), CardCreationSource.Other, CardRarityOddsType.Uniform, (CardModel c) => c.Rarity == CardRarity.Common).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			CardCreationOptions options2 = new CardCreationOptions(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(pool), CardCreationSource.Other, CardRarityOddsType.Uniform, (CardModel c) => c.Rarity == CardRarity.Uncommon).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			CardCreationOptions options3 = new CardCreationOptions(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(pool), CardCreationSource.Other, CardRarityOddsType.Uniform, (CardModel c) => c.Rarity == CardRarity.Rare).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			await RewardsCmd.OfferCustom(base.Owner, new List<Reward>(3)
			{
				new CardReward(options, base.DynamicVars.Cards.IntValue, base.Owner),
				new CardReward(options2, base.DynamicVars.Cards.IntValue, base.Owner),
				new CardReward(options3, base.DynamicVars.Cards.IntValue, base.Owner)
			});
			SetEventFinished(L10NLookup("COLORFUL_PHILOSOPHERS.pages.DONE.description"));
		}
	}
	public sealed class ColossalFlower : EventModel
	{
		private static readonly string[] _prizeKeys = new string[3] { "Prize1", "Prize2", "Prize3" };

		private static readonly int[] _prizeCosts = new int[3] { 35, 75, 135 };

		private static readonly int[] _prizeDamage = new int[3] { 5, 6, 7 };

		private int _numberOfDigs;

		private int NumberOfDigs
		{
			get
			{
				return _numberOfDigs;
			}
			set
			{
				AssertMutable();
				_numberOfDigs = value;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[3]
		{
			new GoldVar(_prizeKeys[0], _prizeCosts[0]),
			new GoldVar(_prizeKeys[1], _prizeCosts[1]),
			new GoldVar(_prizeKeys[2], _prizeCosts[2])
		});

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.All((Player p) => p.Creature.CurrentHp >= 19);
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, ExtractCurrentPrize, $"COLOSSAL_FLOWER.pages.INITIAL.options.EXTRACT_CURRENT_PRIZE_{NumberOfDigs + 1}"),
				new EventOption(this, ReachDeeper, $"COLOSSAL_FLOWER.pages.INITIAL.options.REACH_DEEPER_{NumberOfDigs + 1}").ThatDoesDamage(_prizeDamage[NumberOfDigs])
			});
		}

		private async Task ReachDeeper()
		{
			await DealReachDeeperDamage();
			NumberOfDigs++;
			if (NumberOfDigs < 2)
			{
				SetEventState(L10NLookup($"COLOSSAL_FLOWER.pages.REACH_DEEPER_{NumberOfDigs}.description"), new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
				{
					new EventOption(this, ExtractCurrentPrize, $"COLOSSAL_FLOWER.pages.REACH_DEEPER_{NumberOfDigs}.options.EXTRACT_CURRENT_PRIZE_{NumberOfDigs + 1}"),
					new EventOption(this, ReachDeeper, $"COLOSSAL_FLOWER.pages.REACH_DEEPER_{NumberOfDigs}.options.REACH_DEEPER_{NumberOfDigs + 1}").ThatDoesDamage(_prizeDamage[NumberOfDigs])
				}));
			}
			else
			{
				SetEventState(L10NLookup("COLOSSAL_FLOWER.pages.REACH_DEEPER_2.description"), new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
				{
					new EventOption(this, ExtractInstead, "COLOSSAL_FLOWER.pages.REACH_DEEPER_2.options.EXTRACT_INSTEAD"),
					new EventOption(this, ObtainPollinousCore, "COLOSSAL_FLOWER.pages.REACH_DEEPER_2.options.POLLINOUS_CORE", HoverTipFactory.FromRelic<PollinousCore>()).ThatDoesDamage(_prizeDamage[NumberOfDigs])
				}));
			}
		}

