		/// <summary>
		/// Generates a list of possible dishes and uses a weighted roll to determine a dish.
		/// Lots of exceptions and info here.
		/// </summary>
		private void RollDish()
		{
			NumOfGrabs++;
			if (NumOfGrabs % 5 == 0)
			{
				_lastDishId = "SEAPUNK_SALAD";
				_currentDish = new Dish("SEAPUNK_SALAD", SeapunkSalad, HoverTipFactory.FromCardWithCardHoverTips<FeedingFrenzy>(), 0f);
				return;
			}
			int num = 4;
			List<Dish> list = new List<Dish>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<Dish> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = new Dish("CAVIAR", Caviar, System.Array.Empty<IHoverTip>(), 6f);
			num2++;
			span[num2] = new Dish("SPICY_SNAPPY", SpicySnappy, System.Array.Empty<IHoverTip>(), 3f);
			num2++;
			span[num2] = new Dish("JELLY_LIVER", JellyLiver, new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.Transform)), 3f);
			num2++;
			span[num2] = new Dish("FRIED_EEL", FriedEel, System.Array.Empty<IHoverTip>(), 3f);
			List<Dish> list2 = list;
			if (base.Owner.HasOpenPotionSlots)
			{
				list2.Add(new Dish("SUSPICIOUS_CONDIMENT", SuspiciousCondiment, System.Array.Empty<IHoverTip>(), 3f));
			}
			if (base.Owner.Creature.CurrentHp != base.Owner.Creature.MaxHp)
			{
				list2.Add(new Dish("CLAM_ROLL", ClamRoll, System.Array.Empty<IHoverTip>(), 6f));
			}
			if (NumOfGrabs > 1)
			{
				list2.Add(new Dish("GOLDEN_FYSH", GoldenFysh, System.Array.Empty<IHoverTip>(), 1f));
			}
			list2.RemoveAll((Dish d) => d.id == _lastDishId);
			float num3 = 0f;
			foreach (Dish item in list2)
			{
				num3 += item.weight;
			}
			float num4 = base.Rng.NextFloat() * num3;
			float num5 = 0f;
			foreach (Dish item2 in list2)
			{
				num5 += item2.weight;
				if (num4 < num5)
				{
					_lastDishId = item2.id;
					_currentDish = item2;
					break;
				}
			}
		}

		/// <summary>
		/// Player chose not to partake in the feast. Sad.
