		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, GrabPotions, "POTION_COURIER.pages.INITIAL.options.GRAB_POTIONS", HoverTipFactory.FromPotion<FoulPotion>()),
				new EventOption(this, Ransack, "POTION_COURIER.pages.INITIAL.options.RANSACK")
			});
		}

		public override bool IsAllowed(IRunState runState)
		{
			return runState.CurrentActIndex > 0;
		}

		private async Task GrabPotions()
		{
			List<Reward> list = new List<Reward>();
			for (int i = 0; i < base.DynamicVars["FoulPotions"].IntValue; i++)
			{
				list.Add(new PotionReward(ModelDb.Potion<FoulPotion>().ToMutable(), base.Owner));
			}
			await RewardsCmd.OfferCustom(base.Owner, list);
			SetEventFinished(L10NLookup("POTION_COURIER.pages.GRAB_POTIONS.description"));
		}

		private async Task Ransack()
		{
			IEnumerable<PotionModel> items = from p in base.Owner.Character.PotionPool.GetUnlockedPotions(base.Owner.UnlockState).Concat(ModelDb.PotionPool<SharedPotionPool>().GetUnlockedPotions(base.Owner.UnlockState))
				where p.Rarity == PotionRarity.Uncommon
				select p;
			PotionModel potionModel = base.Owner.PlayerRng.Rewards.NextItem(items);
			if (potionModel != null)
			{
				await RewardsCmd.OfferCustom(base.Owner, new List<Reward>(1)
				{
					new PotionReward(potionModel.ToMutable(), base.Owner)
				});
			}
			SetEventFinished(L10NLookup("POTION_COURIER.pages.RANSACK.description"));
		}
	}
	public sealed class PunchOff : EventModel
	{
		/// <summary>
		/// Used to end the enemies punching each other.
		/// </summary>
		private CancellationTokenSource? _punchCts;

		public override EventLayoutType LayoutType => EventLayoutType.Combat;

		public override EncounterModel CanonicalEncounter => ModelDb.Encounter<PunchOffEventEncounter>();

		public override bool IsShared => true;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new GoldVar(0));

		public override bool IsAllowed(IRunState runState)
		{
			return runState.TotalFloor >= 6;
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, Nab, "PUNCH_OFF.pages.INITIAL.options.NAB", HoverTipFactory.FromCardWithCardHoverTips<Injury>()),
				new EventOption(this, TakeThem, "PUNCH_OFF.pages.INITIAL.options.I_CAN_TAKE_THEM")
			});
		}

		public override Task AfterEventStarted()
		{
			RunManager.Instance.RoomExited += OnRoomExited;
			_punchCts = new CancellationTokenSource();
			TaskHelper.RunSafely(PunchEachOther());
			return Task.CompletedTask;
		}

		private async Task PunchEachOther()
		{
			Creature leftEnemy = _combatSynchronizer.CombatStateForLayout.Enemies[0];
			Creature rightEnemy = _combatSynchronizer.CombatStateForLayout.Enemies[1];
			NCreature leftEnemyNode = NCombatRoom.Instance?.GetCreatureNode(leftEnemy);
			if (leftEnemyNode == null)
			{
				return;
			}
			Godot.Vector2 originalScale = leftEnemyNode.Scale;
			leftEnemyNode.Scale = new Godot.Vector2(0f - originalScale.X, originalScale.Y);
			Control vfxContainer = NCombatRoom.Instance?.CombatVfxContainer;
			while (!_punchCts.IsCancellationRequested)
			{
				await CreatureCmd.TriggerAnim(leftEnemy, "Attack", 0f);
				await Cmd.Wait(0.1f);
				VfxCmd.PlayOnCreatureCenter(rightEnemy, "vfx/vfx_attack_blunt");
				vfxContainer?.AddChildSafely(NHitSparkVfx.Create(rightEnemy, requireInteractable: false));
				await CreatureCmd.TriggerAnim(rightEnemy, "Hit", 0f);
				await Cmd.Wait(1.2f);
				if (_punchCts.IsCancellationRequested)
				{
					break;
				}
				await CreatureCmd.TriggerAnim(rightEnemy, "Attack", 0f);
				await Cmd.Wait(0.1f);
				VfxCmd.PlayOnCreatureCenter(leftEnemy, "vfx/vfx_attack_blunt");
				vfxContainer?.AddChildSafely(NHitSparkVfx.Create(leftEnemy, requireInteractable: false));
				await CreatureCmd.TriggerAnim(leftEnemy, "Hit", 0f);
				await Cmd.Wait(1.2f);
			}
			_punchCts = null;
			if (leftEnemyNode.IsValid())
			{
				leftEnemyNode.Scale = originalScale;
			}
		}

		public override void CalculateVars()
		{
			base.DynamicVars.Gold.BaseValue = base.Rng.NextInt(91, 99);
		}

		private async Task Nab()
		{
			await CardPileCmd.AddCurseToDeck<Injury>(base.Owner);
			NGame.Instance.ScreenShakeTrauma(ShakeStrength.Strong);
			NDebugAudioManager.Instance?.Play("blunt_attack.mp3");
			await Cmd.CustomScaledWait(0.25f, 0.5f);
			await RewardsCmd.OfferCustom(base.Owner, new List<Reward>(1)
			{
				new RelicReward(base.Owner)
			});
			SetEventFinished(L10NLookup("PUNCH_OFF.pages.NAB.description"));
		}

		private Task TakeThem()
		{
			_punchCts?.Cancel();
			SetEventState(L10NLookup("PUNCH_OFF.pages.I_CAN_TAKE_THEM.description"), new global::<>z__ReadOnlySingleElementList<EventOption>(new EventOption(this, Fight, "PUNCH_OFF.pages.I_CAN_TAKE_THEM.options.FIGHT")));
			return Task.CompletedTask;
		}

		private Task Fight()
		{
			int num = 2;
			List<Reward> list = new List<Reward>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<Reward> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = new RelicReward(base.Owner);
			num2++;
			span[num2] = new PotionReward(base.Owner);
			List<Reward> extraRewards = list;
			EnterCombatWithoutExitingEvent<PunchOffEventEncounter>(extraRewards, shouldResumeAfterCombat: false);
			return Task.CompletedTask;
		}

		private void OnRoomExited()
		{
			RunManager.Instance.RoomExited -= OnRoomExited;
			_punchCts?.Cancel();
		}
	}
	public sealed class RanwidTheElder : EventModel
	{
		private const string _potionChoiceKey = "RANWID_THE_ELDER.pages.INITIAL.options.POTION";

		private const string _potionKey = "Potion";

		private const string _relicChoiceKey = "RANWID_THE_ELDER.pages.INITIAL.options.RELIC";

		private const string _relicKey = "Relic";

		private LocString PotionChoiceTitle => new LocString("events", "RANWID_THE_ELDER.pages.INITIAL.options.POTION.title");

		private LocString PotionChoiceDescription => new LocString("events", "RANWID_THE_ELDER.pages.INITIAL.options.POTION.description");

		private LocString RelicChoiceTitle => new LocString("events", "RANWID_THE_ELDER.pages.INITIAL.options.RELIC.title");

		private LocString RelicChoiceDescription => new LocString("events", "RANWID_THE_ELDER.pages.INITIAL.options.RELIC.description");

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[3]
		{
			new GoldVar(100),
			new StringVar("Potion", "Potion"),
			new StringVar("Relic", "Relic")
		});

		protected override Task BeforeEventStarted(bool isPreFinished)
		{
			base.Owner.CanUseOrRemovePotions = false;
			return Task.CompletedTask;
		}

		protected override void OnEventFinished()
		{
			base.Owner.CanUseOrRemovePotions = true;
		}

		public override bool IsAllowed(IRunState runState)
		{
			if (runState.CurrentActIndex == 0)
			{
				return false;
			}
			if (runState.Players.Any((Player p) => !GetValidRelics(p).Any()))
			{
				return false;
			}
			if (runState.Players.Any((Player p) => p.Gold < 100))
			{
				return false;
			}
			if (runState.Players.Any((Player p) => !p.Potions.Any()))
			{
				return false;
			}
			return true;
		}

		private IEnumerable<RelicModel> GetValidRelics(Player player)
		{
			return player.Relics.Where((RelicModel r) => r.IsTradable);
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			List<EventOption> list = new List<EventOption>();
			PotionModel potion = base.Rng.NextItem(base.Owner.Potions);
			if (potion != null)
			{
				((StringVar)base.DynamicVars["Potion"]).StringValue = potion.Title.GetFormattedText();
				list.Add(new EventOption(this, async delegate
				{
					await GivePotion(potion);
				}, PotionChoiceTitle, PotionChoiceDescription, "RANWID_THE_ELDER.pages.INITIAL.options.POTION", potion.HoverTips).ThatHasDynamicTitle());
			}
			else
			{
				list.Add(new EventOption(this, null, "RANWID_THE_ELDER.pages.INITIAL.options.POTION_LOCKED"));
			}
			list.Add(new EventOption(this, GiveGold, "RANWID_THE_ELDER.pages.INITIAL.options.GOLD"));
			RelicModel relic = base.Rng.NextItem(base.Owner.Relics.Where((RelicModel r) => r.IsTradable));
			if (relic != null)
			{
				((StringVar)base.DynamicVars["Relic"]).StringValue = relic.Title.GetFormattedText();
				list.Add(new EventOption(this, async delegate
				{
					await GiveRelic(relic);
				}, RelicChoiceTitle, RelicChoiceDescription, "RANWID_THE_ELDER.pages.INITIAL.options.RELIC", relic.HoverTips).ThatHasDynamicTitle());
			}
			else
			{
				list.Add(new EventOption(this, null, "RANWID_THE_ELDER.pages.INITIAL.options.RELIC_LOCKED"));
			}
			return list;
		}

		private async Task GivePotion(PotionModel potion)
		{
			await PotionCmd.Discard(potion);
			RelicModel relic = RelicFactory.PullNextRelicFromFront(base.Owner).ToMutable();
			await RelicCmd.Obtain(relic, base.Owner);
			SetEventFinished(L10NLookup("RANWID_THE_ELDER.pages.POTION.description"));
		}

		private async Task GiveGold()
		{
			await PlayerCmd.LoseGold(base.DynamicVars.Gold.IntValue, base.Owner, GoldLossType.Spent);
			RelicModel relic = RelicFactory.PullNextRelicFromFront(base.Owner).ToMutable();
			await RelicCmd.Obtain(relic, base.Owner);
			SetEventFinished(L10NLookup("RANWID_THE_ELDER.pages.GOLD.description"));
		}

		private async Task GiveRelic(RelicModel relic)
		{
			await RelicCmd.Remove(relic);
			for (int i = 0; i < 2; i++)
			{
				await RelicCmd.Obtain(RelicFactory.PullNextRelicFromFront(base.Owner).ToMutable(), base.Owner);
			}
			SetEventFinished(L10NLookup("RANWID_THE_ELDER.pages.RELIC.description"));
		}
	}
	public sealed class Reflections : EventModel
	{
		public override void OnRoomEnter()
		{
			NEventRoom.Instance?.VfxContainer?.AddChildSafely(NMirrorVfx.Create());
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, TouchAMirror, "REFLECTIONS.pages.INITIAL.options.TOUCH_A_MIRROR"),
				new EventOption(this, Shatter, "REFLECTIONS.pages.INITIAL.options.SHATTER", HoverTipFactory.FromCardWithCardHoverTips<BadLuck>())
			});
		}

		private async Task TouchAMirror()
		{
			List<CardModel> upgradedCards = base.Owner.Deck.Cards.Where((CardModel c) => c.IsUpgraded).ToList();
			for (int i = 0; i < 2; i++)
			{
				if (upgradedCards.Count <= 0)
				{
					break;
				}
				CardModel cardModel = base.Rng.NextItem(upgradedCards);
				upgradedCards.Remove(cardModel);
				CardCmd.Downgrade(cardModel);
				CardCmd.Preview(cardModel, 1.2f, CardPreviewStyle.MessyLayout);
				await Cmd.CustomScaledWait(0.3f, 0.5f);
			}
			List<CardModel> upgradableCards = base.Owner.Deck.Cards.Where((CardModel c) => c.IsUpgradable).ToList();
			for (int i = 0; i < 4; i++)
			{
				if (upgradableCards.Count <= 0)
				{
					break;
				}
				CardModel cardModel2 = base.Rng.NextItem(upgradableCards);
				upgradableCards.Remove(cardModel2);
				CardCmd.Upgrade(cardModel2, CardPreviewStyle.MessyLayout);
				await Cmd.CustomScaledWait(0.3f, 0.5f);
			}
			await Cmd.CustomScaledWait(0.6f, 1.2f);
			SetEventFinished(L10NLookup("REFLECTIONS.pages.TOUCH_A_MIRROR.description"));
		}

		private async Task Shatter()
		{
			int originalDeckSize = base.Owner.Deck.Cards.Count;
			for (int i = 0; i < originalDeckSize; i++)
			{
				CardModel card = base.Owner.RunState.CloneCard(base.Owner.Deck.Cards[i]);
				CardCmd.PreviewCardPileAdd(await CardPileCmd.Add(card, PileType.Deck), 1.2f, CardPreviewStyle.MessyLayout);
				await Cmd.CustomScaledWait(0.1f, 0.2f);
			}
			await Cmd.CustomScaledWait(0.6f, 1.2f);
			await CardPileCmd.AddCurseToDeck<BadLuck>(base.Owner);
			SetEventFinished(L10NLookup("REFLECTIONS.pages.SHATTER.description"));
		}
	}
	public sealed class RelicTrader : EventModel
	{
		private const string _topRelicOwnedKey = "TopRelicOwned";

		private const string _topRelicNewKey = "TopRelicNew";

		private const string _middleRelicOwnedKey = "MiddleRelicOwned";

		private const string _middleRelicNewKey = "MiddleRelicNew";

		private const string _bottomRelicOwnedKey = "BottomRelicOwned";

		private const string _bottomRelicNewKey = "BottomRelicNew";

		private IReadOnlyList<RelicModel>? _ownedRelics;

		private IReadOnlyList<RelicModel>? _newRelics;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[6]
		{
			new StringVar("TopRelicOwned"),
			new StringVar("TopRelicNew"),
			new StringVar("MiddleRelicOwned"),
			new StringVar("MiddleRelicNew"),
			new StringVar("BottomRelicOwned"),
			new StringVar("BottomRelicNew")
		});

		private IReadOnlyList<RelicModel> OwnedRelics
		{
			get
			{
				AssertMutable();
				if (_ownedRelics == null)
				{
					_ownedRelics = GetValidRelics(base.Owner).ToList().StableShuffle(base.Rng).Take(3)
						.ToList();
				}
				return _ownedRelics;
			}
		}

		private IReadOnlyList<RelicModel> NewRelics
		{
			get
			{
				AssertMutable();
				if (_newRelics == null)
				{
					RelicModel[] array = new RelicModel[3];
					for (int i = 0; i < array.Length; i++)
					{
						array[i] = RelicFactory.PullNextRelicFromFront(base.Owner);
					}
					_newRelics = array;
				}
				return _newRelics;
			}
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			List<EventOption> list = new List<EventOption>();
			if (OwnedRelics.Count >= 1)
			{
				list.Add(new EventOption(this, Top, "RELIC_TRADER.pages.INITIAL.options.TOP", GetRelicHoverTips(0)));
			}
			if (OwnedRelics.Count >= 2)
			{
				list.Add(new EventOption(this, Middle, "RELIC_TRADER.pages.INITIAL.options.MIDDLE", GetRelicHoverTips(1)));
			}
			if (OwnedRelics.Count >= 3)
			{
				list.Add(new EventOption(this, Bottom, "RELIC_TRADER.pages.INITIAL.options.BOTTOM", GetRelicHoverTips(2)));
			}
			if (list.Count == 0)
			{
				list.Add(new EventOption(this, Done, "PROCEED"));
			}
			return list;
		}

		public override bool IsAllowed(IRunState runState)
		{
			if (runState.CurrentActIndex == 0)
			{
				return false;
			}
			return runState.Players.All((Player p) => GetValidRelics(p).Count() >= 5);
		}

		private IEnumerable<RelicModel> GetValidRelics(Player player)
		{
			return player.Relics.Where((RelicModel r) => r.IsTradable);
		}

		public override void CalculateVars()
		{
			if (OwnedRelics.Count > 0 && NewRelics.Count > 0)
			{
				((StringVar)base.DynamicVars["TopRelicOwned"]).StringValue = OwnedRelics[0].Title.GetFormattedText();
				((StringVar)base.DynamicVars["TopRelicNew"]).StringValue = NewRelics[0].Title.GetFormattedText();
			}
			if (OwnedRelics.Count > 1 && NewRelics.Count > 1)
			{
				((StringVar)base.DynamicVars["MiddleRelicOwned"]).StringValue = OwnedRelics[1].Title.GetFormattedText();
				((StringVar)base.DynamicVars["MiddleRelicNew"]).StringValue = NewRelics[1].Title.GetFormattedText();
			}
			if (OwnedRelics.Count > 2 && NewRelics.Count > 2)
			{
				((StringVar)base.DynamicVars["BottomRelicOwned"]).StringValue = OwnedRelics[2].Title.GetFormattedText();
				((StringVar)base.DynamicVars["BottomRelicNew"]).StringValue = NewRelics[2].Title.GetFormattedText();
			}
		}

		private async Task Top()
		{
			await Trade(0);
		}

		private async Task Middle()
		{
			await Trade(1);
		}

		private async Task Bottom()
		{
			await Trade(2);
		}

		private async Task Trade(int index)
		{
			await RelicCmd.Remove(OwnedRelics[index]);
			await RelicCmd.Obtain(NewRelics[index].ToMutable(), base.Owner);
			await Done();
		}

		private Task Done()
		{
			SetEventFinished(L10NLookup("RELIC_TRADER.pages.DONE.description"));
			return Task.CompletedTask;
		}

		private IEnumerable<IHoverTip> GetRelicHoverTips(int index)
		{
			if (OwnedRelics.Count <= index || NewRelics.Count <= index)
			{
				return System.Array.Empty<IHoverTip>();
			}
			List<IHoverTip> list = new List<IHoverTip>();
			list.AddRange(OwnedRelics.ElementAt(index).HoverTips);
			list.AddRange(NewRelics.ElementAt(index).HoverTips);
			return new <>z__ReadOnlyList<IHoverTip>(list);
		}
	}
