	public sealed class Symbiote : EventModel
	{
		private const string _enchantmentKey = "Enchantment";

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new StringVar("Enchantment", ModelDb.Enchantment<Corrupted>().Title.GetFormattedText()),
			new CardsVar(1)
		});

		public override bool IsAllowed(IRunState runState)
		{
			return runState.CurrentActIndex > 0;
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			CardPile pile = PileType.Deck.GetPile(base.Owner);
			EventOption eventOption = ((!pile.Cards.Any(CanEnchant)) ? new EventOption(this, null, "SYMBIOTE.pages.INITIAL.options.APPROACH_LOCKED") : new EventOption(this, Approach, "SYMBIOTE.pages.INITIAL.options.APPROACH", HoverTipFactory.FromEnchantment<Corrupted>()));
			EventOption eventOption2 = new EventOption(this, KillWithFire, "SYMBIOTE.pages.INITIAL.options.KILL_WITH_FIRE", HoverTipFactory.Static(StaticHoverTip.Transform));
			int num = 2;
			List<EventOption> list = new List<EventOption>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<EventOption> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = eventOption;
			num2++;
			span[num2] = eventOption2;
			return list;
		}

		private async Task Approach()
		{
			CardModel cardModel = (await CardSelectCmd.FromDeckForEnchantment(prefs: new CardSelectorPrefs(CardSelectorPrefs.EnchantSelectionPrompt, 1), player: base.Owner, enchantment: ModelDb.Enchantment<Corrupted>(), amount: 1)).FirstOrDefault();
			if (cardModel != null)
			{
				CardCmd.Enchant<Corrupted>(cardModel, 1m);
				NCardEnchantVfx nCardEnchantVfx = NCardEnchantVfx.Create(cardModel);
				if (nCardEnchantVfx != null)
				{
					NRun.Instance?.GlobalUi.CardPreviewContainer.AddChildSafely(nCardEnchantVfx);
				}
			}
			SetEventFinished(L10NLookup("SYMBIOTE.pages.APPROACH.description"));
		}

		private async Task KillWithFire()
		{
			List<CardModel> list = (await CardSelectCmd.FromDeckForTransformation(prefs: new CardSelectorPrefs(CardSelectorPrefs.TransformSelectionPrompt, base.DynamicVars.Cards.IntValue), player: base.Owner)).ToList();
			foreach (CardModel item in list)
			{
				await CardCmd.TransformToRandom(item, base.Rng, CardPreviewStyle.EventLayout);
			}
			SetEventFinished(L10NLookup("SYMBIOTE.pages.KILL_WITH_FIRE.description"));
		}

		private static bool CanEnchant(CardModel card)
		{
			return ModelDb.Enchantment<Corrupted>().CanEnchant(card);
		}
	}
	public sealed class TabletOfTruth : EventModel
	{
		private const string _smashHpGainKey = "SmashHPGain";

		private const string _decipherHpLossKey = "DecipherMaxHpLoss";

		private int _decipherCount;

		private int DecipherCount
		{
			get
			{
				return _decipherCount;
			}
			set
			{
				AssertMutable();
				_decipherCount = value;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DynamicVar("SmashHPGain", 20m),
			new DynamicVar("DecipherMaxHpLoss", 3m)
		});

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, Decipher, "TABLET_OF_TRUTH.pages.INITIAL.options.DECIPHER_1").ThatWillKillPlayerIf((Player p) => (decimal)p.Creature.MaxHp <= base.DynamicVars["DecipherMaxHpLoss"].BaseValue),
				new EventOption(this, Smash, "TABLET_OF_TRUTH.pages.INITIAL.options.SMASH")
			});
		}

		private async Task Smash()
		{
			Creature creature = base.Owner.Creature;
			await CreatureCmd.Heal(creature, base.DynamicVars["SmashHPGain"].BaseValue);
			SetEventFinished(L10NLookup("TABLET_OF_TRUTH.pages.SMASH.description"));
		}

		private async Task Decipher()
		{
			await LoseMaxHpAndUpgrade(base.DynamicVars["DecipherMaxHpLoss"].BaseValue);
			DecipherCount++;
			if (DecipherCount == 5)
			{
				SetEventFinished(L10NLookup($"TABLET_OF_TRUTH.pages.DECIPHER_{DecipherCount}.description"));
				return;
			}
			base.DynamicVars["DecipherMaxHpLoss"].BaseValue = GetDecipherCost();
			SetEventState(L10NLookup($"TABLET_OF_TRUTH.pages.DECIPHER_{DecipherCount}.description"), new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, Decipher, $"TABLET_OF_TRUTH.pages.DECIPHER_{DecipherCount}.options.DECIPHER").ThatWillKillPlayerIf((Player p) => (decimal)p.Creature.MaxHp <= base.DynamicVars["DecipherMaxHpLoss"].BaseValue),
				new EventOption(this, GiveUp, "TABLET_OF_TRUTH.pages.DECIPHER.options.GIVE_UP")
			}));
		}

		public int GetDecipherCost()
		{
			Player owner = base.Owner;
			switch (DecipherCount)
			{
			case 1:
				return 6;
			case 2:
				return 12;
			case 3:
				return 24;
			case 4:
				return owner.Creature.MaxHp - 1;
			default:
				Log.Error($"DecipherCount: {DecipherCount} should not be called.");
				return 999999999;
			}
		}

		private Task GiveUp()
		{
			SetEventFinished(L10NLookup("TABLET_OF_TRUTH.pages.GIVE_UP.description"));
			return Task.CompletedTask;
		}

		private async Task LoseMaxHpAndUpgrade(decimal hp)
		{
			if (!(hp < (decimal)base.Owner.Creature.MaxHp))
			{
				await CreatureCmd.LoseMaxHp(new ThrowingPlayerChoiceContext(), base.Owner.Creature, base.Owner.Creature.MaxHp - 1, isFromCard: false);
				await CreatureCmd.Kill(base.Owner.Creature);
				return;
			}
			await CreatureCmd.LoseMaxHp(new ThrowingPlayerChoiceContext(), base.Owner.Creature, hp, isFromCard: false);
			List<CardModel> list = PileType.Deck.GetPile(base.Owner).Cards.Where((CardModel c) => c.IsUpgradable).ToList();
			if (_decipherCount == 4)
			{
				foreach (CardModel item in list)
				{
					CardCmd.Upgrade(item, CardPreviewStyle.MessyLayout);
					await Cmd.CustomScaledWait(0.1f, 0.2f);
				}
				await Cmd.CustomScaledWait(0.6f, 1.2f);
			}
			else if (list.Count != 0)
			{
				CardModel card = base.Rng.NextItem(list);
				CardCmd.Upgrade(card, CardPreviewStyle.EventLayout);
			}
		}
	}
