		private void LoadDialogue()
		{
			int charVisits = SaveManager.Instance.Progress.GetStatsForCharacter(base.Owner.Character.Id)?.TotalWins ?? 0;
			int wins = SaveManager.Instance.Progress.Wins;
			List<AncientDialogue> items = DialogueSet.GetValidDialogues(base.Owner.Character.Id, charVisits, wins, allowAnyCharacterDialogues: false).ToList();
			Dialogue = base.Rng.NextItem(items);
		}

		private EventOption CreateOptionForCurrentLine()
		{
			AncientDialogueLine ancientDialogueLine = Dialogue.Lines[CurrentLineIndex];
			if (IsOnLastLine)
			{
				return CreateProceedOption();
			}
			return new EventOption(title: (ancientDialogueLine.NextButtonText != null) ? ancientDialogueLine.NextButtonText : ((ancientDialogueLine.Speaker != AncientDialogueSpeaker.Ancient) ? _continueLocString : _respondLocString), eventModel: this, onChosen: AdvanceDialogue, description: _emptyLocString, textKey: $"{base.Id.Entry}.dialogue.{CurrentLineIndex}", hoverTips: System.Array.Empty<IHoverTip>()).ThatWontSaveToChoiceHistory();
		}

		private EventOption CreateProceedOption()
		{
			return new EventOption(this, WinRun, "PROCEED", false, false).ThatWontSaveToChoiceHistory();
		}

		private async Task AdvanceDialogue()
		{
			CurrentLineIndex++;
			IEnumerable<EventOption> eventOptions;
			if (CurrentLineIndex < Dialogue.Lines.Count)
			{
				await PlayCurrentLine();
				eventOptions = new global::<>z__ReadOnlySingleElementList<EventOption>(CreateOptionForCurrentLine());
			}
			else
			{
				eventOptions = new global::<>z__ReadOnlySingleElementList<EventOption>(CreateProceedOption());
			}
			SetEventState(_emptyLocString, eventOptions);
		}

		private async Task WinRun()
		{
			if (LocalContext.IsMe(base.Owner))
			{
				await AnimPlayerAttackIfNecessary(Dialogue.EndAttackers);
				await AnimArchitectAttackIfNecessary(Dialogue.EndAttackers);
				await RunManager.Instance.WinRun();
			}
			SetEventState(_emptyLocString, System.Array.Empty<EventOption>());
		}

		private async Task<bool> AnimPlayerAttackIfNecessary(ArchitectAttackers attackers)
		{
			if ((attackers != ArchitectAttackers.Player && attackers != ArchitectAttackers.Both) || 1 == 0)
			{
				return false;
			}
			if (ArchitectCreature == null)
			{
				return false;
			}
			List<string> shuffledVfx = base.Owner.Character.GetArchitectAttackVfx();
			base.Rng.Shuffle(shuffledVfx);
			int[] damageParts = DivideWildly(Score, shuffledVfx.Count, base.Rng);
			Control vfxContainer = NCombatRoom.Instance?.CombatVfxContainer;
			for (int i = 0; i < shuffledVfx.Count; i++)
			{
				bool isFinalHit = i == shuffledVfx.Count - 1;
				await CreatureCmd.TriggerAnim(base.Owner.Creature, "Attack", 0.1f);
				vfxContainer?.AddChildSafely(NDamageNumVfx.Create(ArchitectCreature, damageParts[i], requireInteractable: false));
				vfxContainer?.AddChildSafely(NHitSparkVfx.Create(ArchitectCreature, requireInteractable: false));
				VfxCmd.PlayOnCreatureCenter(ArchitectCreature, shuffledVfx[i]);
				await CreatureCmd.TriggerAnim(ArchitectCreature, "Hit", 0f);
				if (isFinalHit)
				{
					NGame.Instance?.ScreenShake(ShakeStrength.Strong, ShakeDuration.Normal);
				}
				else
				{
					NGame.Instance?.ScreenShake(ShakeStrength.Weak, ShakeDuration.Short);
				}
				if (!isFinalHit)
				{
					await Cmd.Wait(0.1f);
				}
			}
			await Cmd.Wait(2f);
			return true;
		}

		private static int[] DivideWildly(int total, int parts, Rng rng)
		{
			if (parts <= 0)
			{
				return System.Array.Empty<int>();
			}
			if (parts == 1)
			{
				return new int[1] { total };
			}
			double[] array = new double[parts];
			int num = rng.NextInt(parts);
			int num2;
			do
			{
				num2 = rng.NextInt(parts);
			}
			while (num2 == num);
			for (int i = 0; i < parts; i++)
			{
				if (i == num)
				{
					array[i] = rng.NextFloat(2f, 3f);
				}
				else if (i == num2)
				{
					array[i] = rng.NextFloat(0.1f, 0.5f);
				}
				else
				{
					array[i] = rng.NextFloat(0.7f, 1.3f);
				}
			}
			double num3 = array.Sum();
			int[] array2 = new int[parts];
			int num4 = 0;
			for (int j = 0; j < parts - 1; j++)
			{
				array2[j] = Math.Max(1, (int)((double)total * array[j] / num3));
				num4 += array2[j];
			}
			array2[parts - 1] = Math.Max(1, total - num4);
			return array2;
		}

		private async Task AnimArchitectAttackIfNecessary(ArchitectAttackers attackers)
		{
			bool flag = (uint)(attackers - 2) <= 1u;
			if (flag && ArchitectCreature != null)
			{
				await CreatureCmd.TriggerAnim(ArchitectCreature, "Attack", 0.5f);
				VfxCmd.PlayOnCreature(base.Owner.Creature, "vfx/vfx_attack_lightning");
				NCombatRoom.Instance?.CombatVfxContainer.AddChildSafely(NFireBurstVfx.Create(base.Owner.Creature, 1f));
				await Cmd.Wait(0.5f);
			}
		}

		private async Task PlayCurrentLine()
		{
			if (!LocalContext.IsMe(base.Owner))
			{
				return;
			}
			if (SpeechBubble != null)
			{
				TaskHelper.RunSafely(SpeechBubble.AnimOut());
				SpeechBubble = null;
			}
			if (Dialogue == null || CurrentLineIndex >= Dialogue.Lines.Count)
			{
				return;
			}
			AncientDialogueLine line = Dialogue.Lines[CurrentLineIndex];
			if (line.LineText == null)
			{
				return;
			}
			Creature speaker = GetSpeaker(line.Speaker);
			if (speaker == null)
			{
				return;
			}
			if (CurrentLineIndex == 0)
			{
				if (Dialogue.StartAttackers != ArchitectAttackers.None || Dialogue.EndAttackers != ArchitectAttackers.None)
				{
					await Cmd.Wait(0.75f);
				}
				bool flag = await AnimPlayerAttackIfNecessary(Dialogue.StartAttackers);
				if (ArchitectCreature != null)
				{
					if (!flag)
					{
						await Cmd.Wait(1f);
					}
					MegaAnimationState state = GetArchitectAnimationState();
					state?.SetAnimation("_tracks/head_stop_reading", loop: false, 1);
					await Cmd.Wait(0.5f);
					state?.SetAnimation("_tracks/head_normal", loop: true, 1);
				}
				await AnimArchitectAttackIfNecessary(Dialogue.StartAttackers);
			}
			ShowSpeechBubble(line, speaker);
			if (CurrentLineIndex == 0)
			{
				SetEventState(_emptyLocString, new global::<>z__ReadOnlySingleElementList<EventOption>(CreateOptionForCurrentLine()));
			}
		}

		private void ShowSpeechBubble(AncientDialogueLine line, Creature speaker)
		{
			SpeechBubble = TalkCmd.Play(line.LineText, speaker, (line.Speaker == AncientDialogueSpeaker.Ancient) ? VfxColor.DarkGray : base.Owner.Character.SpeechBubbleColor, VfxDuration.Forever);
		}

		private Creature? GetSpeaker(AncientDialogueSpeaker speaker)
		{
			return speaker switch
			{
				AncientDialogueSpeaker.Ancient => ArchitectCreature, 
				AncientDialogueSpeaker.Character => base.Owner.Creature, 
				_ => null, 
			};
		}

		private MegaAnimationState? GetArchitectAnimationState()
		{
			return NCombatRoom.Instance?.GetCreatureNode(ArchitectCreature)?.SpineAnimation.GetAnimationState();
		}
	}
	public sealed class TheFutureOfPotions : EventModel
	{
		private const string _choiceKey = "THE_FUTURE_OF_POTIONS.pages.INITIAL.options.POTION";

		private const string _potionKey = "Potion";

		private const string _rarityKey = "Rarity";

		private const string _typeKey = "Type";

		private System.Collections.Generic.Dictionary<PotionModel, CardType>? _cardTypes;

		private LocString ChoiceTitle => new LocString("events", "THE_FUTURE_OF_POTIONS.pages.INITIAL.options.POTION.title");

		private LocString ChoiceDescription => new LocString("events", "THE_FUTURE_OF_POTIONS.pages.INITIAL.options.POTION.description");

		private System.Collections.Generic.Dictionary<PotionModel, CardType> PotionToCardType
		{
			get
			{
				AssertMutable();
				if (_cardTypes == null)
				{
					_cardTypes = new System.Collections.Generic.Dictionary<PotionModel, CardType>();
					foreach (PotionModel potion in base.Owner.Potions)
					{
						int num = 3;
						List<CardType> list = new List<CardType>(num);
						CollectionsMarshal.SetCount(list, num);
						Span<CardType> span = CollectionsMarshal.AsSpan(list);
						int num2 = 0;
						span[num2] = CardType.Attack;
						num2++;
						span[num2] = CardType.Skill;
						num2++;
						span[num2] = CardType.Power;
						List<CardType> list2 = list;
						if (potion.Rarity == PotionRarity.Common || potion.Rarity == PotionRarity.Token)
						{
							list2.Remove(CardType.Power);
						}
						_cardTypes.Add(potion, base.Rng.NextItem(list2));
					}
				}
				return _cardTypes;
			}
		}

		public override IEnumerable<LocString> GameInfoOptions
		{
			get
			{
				List<LocString> list = base.GameInfoOptions.ToList();
				if (list.Count != 2)
				{
					throw new InvalidOperationException("TheFutureOfPotions must've changed loc format, please update its\nGameInfoOptions method.");
				}
				LocString locString = list.First((LocString o) => o.LocEntryKey.EndsWith(".title"));
				locString.Add("Rarity", "[rarity]");
				LocString locString2 = list.First((LocString o) => o.LocEntryKey.EndsWith(".description"));
				locString2.Add("Potion", "[potion]");
				locString2.Add("Rarity", "[same-rarity]");
				locString2.Add("Type", "[card of random type]");
				return list;
			}
		}

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.All((Player p) => p.Potions.Count() >= 2);
		}

		protected override Task BeforeEventStarted(bool isPreFinished)
		{
			base.Owner.CanUseOrRemovePotions = false;
			return Task.CompletedTask;
		}

		protected override void OnEventFinished()
		{
			base.Owner.CanUseOrRemovePotions = true;
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			List<EventOption> list = new List<EventOption>();
			List<PotionModel> list2 = base.Owner.Potions.ToList();
			int num = Mathf.Min(3, list2.Count);
			for (int i = 0; i < num; i++)
			{
				PotionModel potion = list2[i];
				LocString choiceTitle = ChoiceTitle;
				choiceTitle.Add("Rarity", potion.Rarity.ToLocString().GetFormattedText());
				LocString choiceDescription = ChoiceDescription;
				choiceDescription.Add("Potion", potion.Title.GetFormattedText());
				choiceDescription.Add("Rarity", GetCardRarity(potion).ToLocString().GetFormattedText());
				choiceDescription.Add("Type", PotionToCardType[potion].ToLocString().GetFormattedText());
				list.Add(new EventOption(this, async delegate
				{
					await Trade(potion);
				}, choiceTitle, choiceDescription, "THE_FUTURE_OF_POTIONS.pages.INITIAL.options.POTION", potion.HoverTips).ThatHasDynamicTitle());
			}
			return list;
		}

		private async Task Trade(PotionModel potion)
		{
			CardRarity targetRarity = GetCardRarity(potion);
			await PotionCmd.Discard(potion);
			CardCreationOptions options = CardCreationOptions.ForNonCombatWithUniformOdds(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(base.Owner.Character.CardPool), (CardModel c) => c.Rarity == targetRarity && c.Type == PotionToCardType[potion]).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			CardReward reward = new CardReward(options, 3, base.Owner);
			reward.AfterGenerated += UpgradeCardsInReward;
			await RewardsCmd.OfferCustom(base.Owner, new List<Reward>(1) { reward });
			await Done();
			void UpgradeCardsInReward()
			{
				foreach (CardModel card in reward.Cards)
				{
					CardCmd.Upgrade(card);
				}
			}
		}

		private Task Done()
		{
			SetEventFinished(L10NLookup("THE_FUTURE_OF_POTIONS.pages.DONE.description"));
			return Task.CompletedTask;
		}

		private CardRarity GetCardRarity(PotionModel potion)
		{
			switch (potion.Rarity)
			{
			case PotionRarity.Rare:
			case PotionRarity.Event:
				return CardRarity.Rare;
			case PotionRarity.Uncommon:
				return CardRarity.Uncommon;
			case PotionRarity.Common:
			case PotionRarity.Token:
				return CardRarity.Common;
			default:
				throw new InvalidOperationException($"Potion {potion.Id.Entry} has invalid rarity {potion.Rarity}");
			}
		}
	}
