	public sealed class WarHistorianRepy : EventModel
	{
		public override bool IsShared => true;

		private bool ShouldGetSecondReward
		{
			get
			{
				if (base.Owner.Deck.Cards.Any((CardModel c) => c is LanternKey))
				{
					return base.Owner.RunState.Players.Count <= 1;
				}
				return false;
			}
		}

		public override bool IsAllowed(IRunState runState)
		{
			return false;
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			return new global::<>z__ReadOnlyArray<EventOption>(new EventOption[2]
			{
				new EventOption(this, InitialUnlockCage, "WAR_HISTORIAN_REPY.pages.INITIAL.options.UNLOCK_CAGE", HoverTipFactory.FromRelic<HistoryCourse>().Concat(HoverTipFactory.FromCardWithCardHoverTips<LanternKey>())),
				new EventOption(this, InitialUnlockChest, "WAR_HISTORIAN_REPY.pages.INITIAL.options.UNLOCK_CHEST", HoverTipFactory.FromCardWithCardHoverTips<LanternKey>())
			});
		}

		private async Task InitialUnlockCage()
		{
			await RemoveLanternKeysForInitialChoice();
			await UnlockCage();
			if (ShouldGetSecondReward)
			{
				SetEventState(L10NLookup("WAR_HISTORIAN_REPY.pages.UNLOCK_CAGE.description"), new global::<>z__ReadOnlySingleElementList<EventOption>(new EventOption(this, SecondUnlockChest, "WAR_HISTORIAN_REPY.pages.INITIAL.options.UNLOCK_CHEST", HoverTipFactory.FromCardWithCardHoverTips<LanternKey>())));
			}
			else
			{
				SetEventFinished(L10NLookup("WAR_HISTORIAN_REPY.pages.UNLOCK_CAGE.description"));
			}
		}

		private async Task InitialUnlockChest()
		{
			await RemoveLanternKeysForInitialChoice();
			await UnlockChest();
			if (ShouldGetSecondReward)
			{
				SetEventState(L10NLookup("WAR_HISTORIAN_REPY.pages.UNLOCK_CHEST.description"), new global::<>z__ReadOnlySingleElementList<EventOption>(new EventOption(this, SecondUnlockCage, "WAR_HISTORIAN_REPY.pages.INITIAL.options.UNLOCK_CAGE", HoverTipFactory.FromRelic<HistoryCourse>().Concat(HoverTipFactory.FromCardWithCardHoverTips<LanternKey>()))));
			}
			else
			{
				SetEventFinished(L10NLookup("WAR_HISTORIAN_REPY.pages.UNLOCK_CHEST.description"));
			}
		}

		private async Task SecondUnlockCage()
		{
			SetEventFinished(L10NLookup("WAR_HISTORIAN_REPY.pages.EXTRA_UNLOCK_CAGE.description"));
			await RemoveLanternKeysForSecondChoice();
			await UnlockCage();
		}

		private async Task SecondUnlockChest()
		{
			SetEventFinished(L10NLookup("WAR_HISTORIAN_REPY.pages.EXTRA_UNLOCK_CHEST.description"));
			await RemoveLanternKeysForSecondChoice();
			await UnlockChest();
		}

		private async Task UnlockChest()
		{
			List<Reward> list = new List<Reward>();
			list.Add(new PotionReward(base.Owner));
			list.Add(new PotionReward(base.Owner));
			list.Add(new RelicReward(base.Owner));
			list.Add(new RelicReward(base.Owner));
			await RewardsCmd.OfferCustom(base.Owner, list);
		}

		private async Task UnlockCage()
		{
			base.Owner.RunState.ExtraFields.FreedRepy = true;
			await RelicCmd.Obtain<HistoryCourse>(base.Owner);
		}

		private async Task RemoveLanternKeysForInitialChoice()
		{
			if (base.Owner.RunState.Players.Count > 1)
			{
				await RemoveLanternKeysForSecondChoice();
			}
			else
			{
				await RemoveFirstLanternKey();
			}
		}

		private async Task RemoveFirstLanternKey()
		{
			CardModel cardModel = base.Owner.Deck.Cards.FirstOrDefault((CardModel c) => c is LanternKey);
			if (cardModel != null)
			{
				PlayerCmd.CompleteQuest(cardModel);
				await CardPileCmd.RemoveFromDeck(cardModel);
			}
		}

		private async Task RemoveLanternKeysForSecondChoice()
		{
			List<CardModel> list = base.Owner.Deck.Cards.Where((CardModel c) => c is LanternKey).ToList();
			foreach (CardModel item in list)
			{
				PlayerCmd.CompleteQuest(item);
				await CardPileCmd.RemoveFromDeck(item);
			}
		}
	}
	public sealed class WaterloggedScriptorium : EventModel
	{
		private const int _spawnGoldRequirement = 55;

		private const string _pricklySpongeGoldKey = "PricklySpongeGold";

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[4]
		{
			new MaxHpVar(6m),
			new GoldVar(55),
			new GoldVar("PricklySpongeGold", 99),
			new CardsVar(2)
		});

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.All((Player p) => p.Gold >= 55);
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			int num = 1;
			List<EventOption> list = new List<EventOption>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<EventOption> span = CollectionsMarshal.AsSpan(list);
			int index = 0;
			span[index] = new EventOption(this, BloodyInk, "WATERLOGGED_SCRIPTORIUM.pages.INITIAL.options.BLOODY_INK");
			List<EventOption> list2 = list;
			if (base.Owner.Gold >= base.DynamicVars.Gold.IntValue)
			{
				list2.Add(new EventOption(this, TentacleQuill, "WATERLOGGED_SCRIPTORIUM.pages.INITIAL.options.TENTACLE_QUILL", HoverTipFactory.FromEnchantment<Steady>()));
			}
			else
			{
				list2.Add(new EventOption(this, null, "WATERLOGGED_SCRIPTORIUM.pages.INITIAL.options.TENTACLE_QUILL_LOCKED"));
			}
			if (base.Owner.Gold >= base.DynamicVars["PricklySpongeGold"].IntValue)
			{
				list2.Add(new EventOption(this, PricklySponge, "WATERLOGGED_SCRIPTORIUM.pages.INITIAL.options.PRICKLY_SPONGE", HoverTipFactory.FromEnchantment<Steady>()));
			}
			else
			{
				list2.Add(new EventOption(this, null, "WATERLOGGED_SCRIPTORIUM.pages.INITIAL.options.PRICKLY_SPONGE_LOCKED"));
			}
			return list2;
		}

		private async Task PricklySponge()
		{
			await PlayerCmd.LoseGold(base.DynamicVars["PricklySpongeGold"].BaseValue, base.Owner, GoldLossType.Spent);
			CardSelectorPrefs prefs = new CardSelectorPrefs(CardSelectorPrefs.EnchantSelectionPrompt, base.DynamicVars.Cards.IntValue);
			Steady enchantment = ModelDb.Enchantment<Steady>();
			foreach (CardModel item in await CardSelectCmd.FromDeckForEnchantment(base.Owner, enchantment, 1, prefs))
			{
				CardCmd.Enchant<Steady>(item, 1m);
				NCardEnchantVfx nCardEnchantVfx = NCardEnchantVfx.Create(item);
				if (nCardEnchantVfx != null)
				{
					NRun.Instance?.GlobalUi.CardPreviewContainer.AddChildSafely(nCardEnchantVfx);
				}
			}
			SetEventFinished(L10NLookup("WATERLOGGED_SCRIPTORIUM.pages.PRICKLY_SPONGE.description"));
		}

		private async Task TentacleQuill()
		{
			await PlayerCmd.LoseGold(base.DynamicVars.Gold.BaseValue, base.Owner, GoldLossType.Spent);
			CardModel cardModel = (await CardSelectCmd.FromDeckForEnchantment(prefs: new CardSelectorPrefs(CardSelectorPrefs.EnchantSelectionPrompt, 1), player: base.Owner, enchantment: ModelDb.Enchantment<Steady>(), amount: 1)).FirstOrDefault();
			if (cardModel != null)
			{
				CardCmd.Enchant<Steady>(cardModel, 1m);
				NCardEnchantVfx nCardEnchantVfx = NCardEnchantVfx.Create(cardModel);
				if (nCardEnchantVfx != null)
				{
					NRun.Instance?.GlobalUi.CardPreviewContainer.AddChildSafely(nCardEnchantVfx);
				}
			}
			SetEventFinished(L10NLookup("WATERLOGGED_SCRIPTORIUM.pages.TENTACLE_QUILL.description"));
		}

		private async Task BloodyInk()
		{
			await CreatureCmd.GainMaxHp(base.Owner.Creature, base.DynamicVars.MaxHp.BaseValue);
			SetEventFinished(L10NLookup("WATERLOGGED_SCRIPTORIUM.pages.BLOODY_INK.description"));
		}
	}
	public sealed class WelcomeToWongos : EventModel
	{
		private const int _wongoPointsForBadge = 2000;

		private const string _bargainBinCostKey = "BargainBinCost";

		private const string _featuredItemCostKey = "FeaturedItemCost";

		private const string _mysteryBoxCostKey = "MysteryBoxCost";

		private const string _mysteryBoxRelicCountKey = "MysteryBoxRelicCount";

		private const string _mysteryBoxCombatCountKey = "MysteryBoxCombatCount";

		private const string _wongoPointAmountKey = "WongoPointAmount";

		private const string _remainingWongoPointAmountKey = "RemainingWongoPointAmount";

		private const string _totalWongoBadgeAmountKey = "TotalWongoBadgeAmount";

		private const string _randomRelicKey = "RandomRelic";

		private RelicModel? _featuredItem;

		private RelicModel? FeaturedItem
		{
			get
			{
				return _featuredItem;
			}
			set
			{
				AssertMutable();
				_featuredItem = value;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[9]
		{
			new DynamicVar("BargainBinCost", 100m),
			new DynamicVar("MysteryBoxCost", 300m),
			new DynamicVar("FeaturedItemCost", 200m),
			new DynamicVar("MysteryBoxRelicCount", 3m),
			new DynamicVar("MysteryBoxCombatCount", 5m),
			new DynamicVar("WongoPointAmount", 0m),
			new DynamicVar("RemainingWongoPointAmount", 0m),
			new DynamicVar("TotalWongoBadgeAmount", 0m),
			new StringVar("RandomRelic")
		});

		public override bool IsAllowed(IRunState runState)
		{
			if (runState.CurrentActIndex == 1)
			{
				return runState.Players.All((Player p) => p.Gold >= 100);
			}
			return false;
		}

		protected override IReadOnlyList<EventOption> GenerateInitialOptions()
		{
			Player owner = base.Owner;
			FeaturedItem = RelicFactory.PullNextRelicFromFront(owner, RelicRarity.Rare, (RelicModel r) => r.IsAllowedInShops);
			((StringVar)base.DynamicVars["RandomRelic"]).StringValue = FeaturedItem.Title.GetFormattedText();
			List<EventOption> list = new List<EventOption>();
			if ((decimal)owner.Gold >= base.DynamicVars["BargainBinCost"].BaseValue)
			{
				list.Add(new EventOption(this, BuyBargainBin, "WELCOME_TO_WONGOS.pages.INITIAL.options.BARGAIN_BIN"));
			}
			else
			{
				list.Add(new EventOption(this, null, "WELCOME_TO_WONGOS.pages.INITIAL.options.BARGAIN_BIN_LOCKED"));
			}
			if ((decimal)owner.Gold >= base.DynamicVars["FeaturedItemCost"].BaseValue)
			{
				list.Add(new EventOption(this, BuyFeaturedItem, "WELCOME_TO_WONGOS.pages.INITIAL.options.FEATURED_ITEM", FeaturedItem.HoverTips));
			}
			else
			{
				list.Add(new EventOption(this, null, "WELCOME_TO_WONGOS.pages.INITIAL.options.FEATURED_ITEM_LOCKED"));
			}
			if ((decimal)owner.Gold >= base.DynamicVars["MysteryBoxCost"].BaseValue)
			{
				list.Add(new EventOption(this, BuyMysteryBox, "WELCOME_TO_WONGOS.pages.INITIAL.options.MYSTERY_BOX"));
			}
			else
			{
				list.Add(new EventOption(this, null, "WELCOME_TO_WONGOS.pages.INITIAL.options.MYSTERY_BOX_LOCKED"));
			}
			list.Add(new EventOption(this, Leave, "WELCOME_TO_WONGOS.pages.INITIAL.options.LEAVE"));
			return list;
		}

		private async Task<LocString> CheckObtainWongoBadge(int pointsEarned)
		{
			int wongoPoints = SaveManager.Instance.Progress.WongoPoints;
			int num = wongoPoints % 2000;
			int num2 = num + pointsEarned;
			int num3 = wongoPoints + pointsEarned;
			base.DynamicVars["WongoPointAmount"].BaseValue = num2;
			base.DynamicVars["RemainingWongoPointAmount"].BaseValue = 2000 - num2;
			base.DynamicVars["TotalWongoBadgeAmount"].BaseValue = num3 / 2000;
			base.Owner.ExtraFields.WongoPoints = pointsEarned;
			if (num2 >= 2000)
			{
				await RelicCmd.Obtain<WongoCustomerAppreciationBadge>(base.Owner);
				return L10NLookup("WELCOME_TO_WONGOS.pages.AFTER_BUY_RECEIVE_BADGE.description");
			}
			if (base.DynamicVars["TotalWongoBadgeAmount"].BaseValue > 0m)
			{
				return L10NLookup("WELCOME_TO_WONGOS.pages.AFTER_BUY_BADGE_COUNTER.description");
			}
			return L10NLookup("WELCOME_TO_WONGOS.pages.AFTER_BUY.description");
		}

		private async Task BuyBargainBin()
