	public sealed class Glam : EnchantmentModel
	{
		private const string _timesKey = "Times";

		private bool _usedThisCombat;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("Times", 1m));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.ReplayDynamic, base.DynamicVars["Times"]));

		private bool UsedThisCombat
		{
			get
			{
				return _usedThisCombat;
			}
			set
			{
				AssertMutable();
				_usedThisCombat = value;
			}
		}

		public override int EnchantPlayCount(int originalPlayCount)
		{
			if (UsedThisCombat)
			{
				return originalPlayCount;
			}
			return originalPlayCount + base.DynamicVars["Times"].IntValue;
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (UsedThisCombat)
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card != base.Card)
			{
				return Task.CompletedTask;
			}
			UsedThisCombat = true;
			base.Status = EnchantmentStatus.Disabled;
			return Task.CompletedTask;
		}
	}
	public sealed class Goopy : EnchantmentModel
	{
		public override bool HasExtraCardText => true;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Exhaust));

		public override bool CanEnchant(CardModel card)
		{
			if (base.CanEnchant(card))
			{
				return card.Tags.Contains(CardTag.Defend);
			}
			return false;
		}

		protected override void OnEnchant()
		{
			base.Card.AddKeyword(CardKeyword.Exhaust);
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card != base.Card)
			{
				return Task.CompletedTask;
			}
			base.Amount++;
			if (base.Card.DeckVersion != null)
			{
				base.Card.DeckVersion.Enchantment.Amount++;
			}
			return Task.CompletedTask;
		}

		public override decimal EnchantBlockAdditive(decimal originalBlock)
		{
			return base.Amount - 1;
		}
	}
