	public sealed class BansheesCry : CardModel
	{
		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Ethereal));

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DamageVar(33m, ValueProp.Move),
			new EnergyVar(2)
		});

		public BansheesCry()
			: base(9, CardType.Attack, CardRarity.Rare, TargetType.AllEnemies)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue).FromCard(this, cardPlay).TargetingAllOpponents(base.CombatState)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(choiceContext);
		}

		protected override void OnUpgrade()
		{
			base.EnergyCost.UpgradeBy(-2);
		}

		public override Task AfterCardEnteredCombat(CardModel card)
		{
			if (card != this)
			{
				return Task.CompletedTask;
			}
			if (base.IsClone)
			{
				return Task.CompletedTask;
			}
			int num = CombatManager.Instance.History.CardPlaysFinished.Count((CardPlayFinishedEntry e) => e.WasEthereal && e.CardPlay.Player == base.Owner);
			base.EnergyCost.AddThisCombat(-num * base.DynamicVars.Energy.IntValue);
			return Task.CompletedTask;
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (!cardPlay.Card.Keywords.Contains(CardKeyword.Ethereal))
			{
				return Task.CompletedTask;
			}
			base.EnergyCost.AddThisCombat(-base.DynamicVars.Energy.IntValue);
			return Task.CompletedTask;
		}
	}
