	public sealed class BeatDown : CardModel
	{
		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new CardsVar(3));

		public BeatDown()
			: base(3, CardType.Skill, CardRarity.Rare, TargetType.RandomEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			CardPile pile = PileType.Discard.GetPile(base.Owner);
			IEnumerable<CardModel> enumerable = pile.Cards.Where((CardModel c) => c.Type == CardType.Attack && !c.Keywords.Contains(CardKeyword.Unplayable)).ToList().StableShuffle(base.Owner.RunState.Rng.Shuffle)
				.Take(base.DynamicVars.Cards.IntValue);
			foreach (CardModel item in enumerable)
			{
				if (!CombatManager.Instance.IsOverOrEnding)
				{
					if (item.TargetType == TargetType.AnyEnemy)
					{
						Creature target = base.Owner.RunState.Rng.CombatTargets.NextItem(base.CombatState.HittableEnemies);
						await CardCmd.AutoPlay(choiceContext, item, target);
					}
					else
					{
						await CardCmd.AutoPlay(choiceContext, item, null);
					}
					continue;
				}
				break;
			}
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.Cards.UpgradeValueBy(1m);
		}
	}
	public sealed class BeatIntoShape : CardModel
	{
		private const string _calculatedForgeKey = "CalculatedForge";

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[4]
		{
			new DamageVar(5m, ValueProp.Move),
			new CalculationBaseVar(5m),
			new CalculationExtraVar(5m),
			new CalculatedVar("CalculatedForge").WithMultiplier((CardModel card, Creature? target) => CombatManager.Instance.History.Entries.OfType<DamageReceivedEntry>().Count((DamageReceivedEntry e) => e.Receiver == target && e.Dealer == card.Owner.Creature && e.Result.Props.IsPoweredAttack() && e.HappenedThisTurn(card.CombatState)))
		});

		protected override IEnumerable<IHoverTip> ExtraHoverTips => HoverTipFactory.FromForge();

		public BeatIntoShape()
			: base(1, CardType.Attack, CardRarity.Rare, TargetType.AnyEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
			AttackCommand attackCommand = await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue).FromCard(this, cardPlay).Targeting(cardPlay.Target)
				.WithHitFx("vfx/vfx_attack_blunt", null, "blunt_attack.mp3")
				.Execute(choiceContext);
			decimal amount = ((CalculatedVar)base.DynamicVars["CalculatedForge"]).Calculate(cardPlay.Target);
			amount -= (decimal)attackCommand.Results.Count() * base.DynamicVars.CalculationExtra.BaseValue;
			await ForgeCmd.Forge(amount, base.Owner, this);
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.Damage.UpgradeValueBy(2m);
			base.DynamicVars.CalculationBase.UpgradeValueBy(2m);
			base.DynamicVars.CalculationExtra.UpgradeValueBy(2m);
		}
	}
