	public sealed class Dirge : CardModel
	{
		protected override bool HasEnergyCostX => true;

		public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Exhaust);

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new SummonVar(3m));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlyArray<IHoverTip>(new IHoverTip[2]
		{
			HoverTipFactory.Static(StaticHoverTip.SummonDynamic, base.DynamicVars.Summon),
			HoverTipFactory.FromCard<Soul>(base.IsUpgraded)
		});

		public Dirge()
			: base(0, CardType.Skill, CardRarity.Uncommon, TargetType.Self)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			await CreatureCmd.TriggerAnim(base.Owner.Creature, "Cast", base.Owner.Character.CastAnimDelay);
			int xValue = ResolveEnergyXValue();
			for (int i = 0; i < xValue; i++)
			{
				await OstyCmd.Summon(choiceContext, base.Owner, base.DynamicVars.Summon.BaseValue, this);
			}
			List<Soul> list = Soul.Create(base.Owner, xValue, base.CombatState).ToList();
			if (base.IsUpgraded)
			{
				foreach (Soul item in list)
				{
					CardCmd.Upgrade(item);
				}
			}
			CardCmd.PreviewCardPileAdd(await CardPileCmd.AddGeneratedCardsToCombat(list, PileType.Draw, base.Owner, CardPilePosition.Random));
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.Summon.UpgradeValueBy(1m);
		}
	}
	public sealed class Discovery : CardModel
	{
		private CardModel? _mockSelectedCard;

		public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Exhaust);

		public Discovery()
			: base(1, CardType.Skill, CardRarity.Uncommon, TargetType.Self)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			CardModel cardModel;
			if (_mockSelectedCard == null)
			{
				List<CardModel> cards = CardFactory.GetDistinctForCombat(base.Owner, base.Owner.Character.CardPool.GetUnlockedCards(base.Owner.UnlockState, base.Owner.RunState.CardMultiplayerConstraint), 3, base.Owner.RunState.Rng.CombatCardGeneration).ToList();
				cardModel = await CardSelectCmd.FromChooseACardScreen(choiceContext, cards, base.Owner, canSkip: true);
			}
			else
			{
				cardModel = _mockSelectedCard;
			}
			if (cardModel != null)
			{
				cardModel.SetToFreeThisTurn();
				await CardPileCmd.AddGeneratedCardToCombat(cardModel, PileType.Hand, base.Owner);
			}
		}

		protected override void OnUpgrade()
		{
			RemoveKeyword(CardKeyword.Exhaust);
		}

		/// <summary>
		/// ONLY USE THIS IN TESTS!
		/// </summary>
		public void MockSelectedCard(CardModel card)
		{
			AssertMutable();
			_mockSelectedCard = card;
		}
	}
