	public sealed class Fetch : CardModel
	{
		protected override HashSet<CardTag> CanonicalTags => new HashSet<CardTag> { CardTag.OstyAttack };

		protected override bool ShouldGlowRedInternal => base.Owner.IsOstyMissing;

		protected override bool ShouldGlowGoldInternal => !HasBeenPlayedThisTurn;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new OstyDamageVar(3m, ValueProp.Move),
			new CardsVar(1)
		});

		private bool HasBeenPlayedThisTurn => CombatManager.Instance.History.CardPlaysFinished.Any((CardPlayFinishedEntry e) => e.CardPlay.Card == this && e.HappenedThisTurn(base.CombatState));

		public Fetch()
			: base(0, CardType.Attack, CardRarity.Uncommon, TargetType.AnyEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
			if (!Osty.CheckMissingWithAnim(base.Owner))
			{
				await DamageCmd.Attack(base.DynamicVars.OstyDamage.BaseValue).FromOsty(base.Owner.Osty, this, cardPlay).Targeting(cardPlay.Target)
					.WithHitFx("vfx/vfx_attack_blunt", null, "blunt_attack.mp3")
					.Execute(choiceContext);
				if (!HasBeenPlayedThisTurn)
				{
					await CardPileCmd.Draw(choiceContext, base.DynamicVars.Cards.BaseValue, base.Owner);
				}
			}
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.OstyDamage.UpgradeValueBy(3m);
		}
	}
	public sealed class FiendFire : CardModel
	{
		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DamageVar(7m, ValueProp.Move));

		public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Exhaust);

		protected override IEnumerable<string> ExtraRunAssetPaths => NGroundFireVfx.AssetPaths;

		public FiendFire()
			: base(2, CardType.Attack, CardRarity.Rare, TargetType.AnyEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
			List<CardModel> list = PileType.Hand.GetPile(base.Owner).Cards.ToList();
			int cardCount = list.Count;
			foreach (CardModel item in list)
			{
				await CardCmd.Exhaust(choiceContext, item);
			}
			float scale = 0.8f;
			await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue).WithHitCount(cardCount).FromCard(this, cardPlay)
				.Targeting(cardPlay.Target)
				.BeforeDamage(delegate
				{
					NGroundFireVfx nGroundFireVfx = NGroundFireVfx.Create(cardPlay.Target);
					if (nGroundFireVfx == null)
					{
						return Task.CompletedTask;
					}
					SfxCmd.Play("event:/sfx/characters/attack_fire");
					nGroundFireVfx.Scale = Godot.Vector2.One * scale;
					NCombatRoom.Instance?.CombatVfxContainer.AddChildSafely(nGroundFireVfx);
					scale += 0.1f;
					return Task.CompletedTask;
				})
				.Execute(choiceContext);
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.Damage.UpgradeValueBy(3m);
		}
	}
