	public sealed class Guilty : CardModel
	{
		public const int maxCombats = 5;

		private const string _combatsKey = "Combats";

		private int _combatsSeen;

		public override int MaxUpgradeLevel => 0;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("Combats", 5m));

		public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Unplayable);

		[SavedProperty]
		public int CombatsSeen
		{
			get
			{
				return _combatsSeen;
			}
			set
			{
				AssertMutable();
				_combatsSeen = value;
				base.DynamicVars["Combats"].BaseValue = 5 - CombatsSeen;
			}
		}

		public Guilty()
			: base(-1, CardType.Curse, CardRarity.Curse, TargetType.None)
		{
		}

		public override async Task AfterCombatEnd(CombatRoom _)
		{
			CardPile? pile = base.Pile;
			if (pile != null && pile.Type == PileType.Deck)
			{
				CombatsSeen++;
				if (CombatsSeen >= 5 && base.Pile.Type == PileType.Deck)
				{
					await CardPileCmd.RemoveFromDeck(this);
				}
			}
		}
	}
