	public sealed class KinglyPunch : CardModel
	{
		private const string _increaseKey = "Increase";

		private decimal _extraDamage;

		private decimal ExtraDamage
		{
			get
			{
				return _extraDamage;
			}
			set
			{
				AssertMutable();
				_extraDamage = value;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DamageVar(8m, ValueProp.Move),
			new DynamicVar("Increase", 4m)
		});

		public KinglyPunch()
			: base(1, CardType.Attack, CardRarity.Uncommon, TargetType.AnyEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
			await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue).FromCard(this, cardPlay).Targeting(cardPlay.Target)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(choiceContext);
		}

		public override Task AfterCardDrawn(PlayerChoiceContext choiceContext, CardModel card, bool fromHandDraw)
		{
			if (card != this)
			{
				return Task.CompletedTask;
			}
			decimal baseValue = base.DynamicVars["Increase"].BaseValue;
			base.DynamicVars.Damage.BaseValue += baseValue;
			ExtraDamage += baseValue;
			return Task.CompletedTask;
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.Damage.UpgradeValueBy(2m);
			base.DynamicVars["Increase"].UpgradeValueBy(2m);
		}

		protected override void AfterDowngraded()
		{
			base.AfterDowngraded();
			base.DynamicVars.Damage.BaseValue += ExtraDamage;
		}
	}
	public sealed class KnifeTrap : CardModel
	{
		private const string _calculatedShivsKey = "CalculatedShivs";

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromCard<Shiv>(base.IsUpgraded));

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[3]
		{
			new CalculationBaseVar(0m),
			new CalculationExtraVar(1m),
			new CalculatedVar("CalculatedShivs").WithMultiplier((CardModel card, Creature? _) => PileType.Exhaust.GetPile(card.Owner).Cards.Count((CardModel c) => c.Tags.Contains(CardTag.Shiv)))
		});

		public KnifeTrap()
			: base(2, CardType.Skill, CardRarity.Rare, TargetType.AnyEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
			IEnumerable<CardModel> enumerable = PileType.Exhaust.GetPile(base.Owner).Cards.Where((CardModel c) => c.Tags.Contains(CardTag.Shiv)).ToList();
			bool flag = true;
			foreach (CardModel item in enumerable)
			{
				if (base.IsUpgraded)
				{
					CardCmd.Upgrade(item, CardPreviewStyle.None);
				}
				await CardCmd.AutoPlay(choiceContext, item, cardPlay.Target, AutoPlayType.Default, skipXCapture: false, !flag);
				flag = false;
			}
		}
	}
