	public sealed class Regret : CardModel
	{
		private int _cardsInHand;

		public override int MaxUpgradeLevel => 0;

		public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Unplayable);

		private int CardsInHand
		{
			get
			{
				return _cardsInHand;
			}
			set
			{
				AssertMutable();
				_cardsInHand = value;
			}
		}

		public override bool HasTurnEndInHandEffect => true;

		public Regret()
			: base(-1, CardType.Curse, CardRarity.Curse, TargetType.None)
		{
		}

		public override Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (!participants.Contains(base.Owner.Creature))
			{
				return Task.CompletedTask;
			}
			if (base.Pile.Type != PileType.Hand)
			{
				return Task.CompletedTask;
			}
			CardsInHand = base.Pile.Cards.Count;
			return Task.CompletedTask;
		}

		protected override async Task OnTurnEndInHand(PlayerChoiceContext choiceContext)
		{
			await CreatureCmd.Damage(choiceContext, base.Owner.Creature, CardsInHand, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, this, null);
			CardsInHand = 0;
		}
	}
