		{
			if (creator != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (card.Owner != base.Owner)
			{
				return Task.CompletedTask;
			}
			if (card.Type != CardType.Status)
			{
				return Task.CompletedTask;
			}
			base.EnergyCost.AddUntilPlayed(-1);
			return Task.CompletedTask;
		}

