	public sealed class Spite : CardModel
	{
		protected override bool ShouldGlowGoldInternal => LostHpThisTurn(base.Owner.Creature);

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DamageVar(5m, ValueProp.Move),
			new RepeatVar(2)
		});

		public Spite()
			: base(0, CardType.Attack, CardRarity.Uncommon, TargetType.AnyEnemy)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
			int hitCount = ((!LostHpThisTurn(base.Owner.Creature)) ? 1 : base.DynamicVars.Repeat.IntValue);
			await DamageCmd.Attack(base.DynamicVars.Damage.BaseValue).WithHitCount(hitCount).FromCard(this, cardPlay)
				.Targeting(cardPlay.Target)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(choiceContext);
		}

		protected override void OnUpgrade()
		{
			base.DynamicVars.Repeat.UpgradeValueBy(1m);
		}

		private static bool LostHpThisTurn(Creature creature)
		{
			return CombatManager.Instance.History.Entries.OfType<DamageReceivedEntry>().Any((DamageReceivedEntry e) => e.HappenedThisTurn(creature.CombatState) && e.Receiver == creature && e.Result.UnblockedDamage > 0);
		}
	}
	public sealed class Splash : CardModel
	{
		private CardModel? _mockGeneratedCard;

		public Splash()
			: base(1, CardType.Skill, CardRarity.Rare, TargetType.Self)
		{
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			CardModel cardModel;
			if (_mockGeneratedCard == null)
			{
				List<CardPoolModel> list = base.Owner.UnlockState.CharacterCardPools.ToList();
				if (list.Count > 1)
				{
					list.Remove(base.Owner.Character.CardPool);
				}
				IEnumerable<CardModel> cards = from c in list.SelectMany((CardPoolModel c) => c.GetUnlockedCards(base.Owner.UnlockState, base.Owner.RunState.CardMultiplayerConstraint))
					where c.Type == CardType.Attack
					select c;
				List<CardModel> list2 = CardFactory.GetDistinctForCombat(base.Owner, cards, 3, base.Owner.RunState.Rng.CombatCardGeneration).ToList();
				if (base.IsUpgraded)
				{
					foreach (CardModel item in list2)
					{
						CardCmd.Upgrade(item);
					}
				}
				cardModel = await CardSelectCmd.FromChooseACardScreen(choiceContext, list2, base.Owner, canSkip: true);
			}
			else
			{
				cardModel = _mockGeneratedCard;
				if (base.IsUpgraded)
				{
					CardCmd.Upgrade(cardModel);
				}
			}
			if (cardModel != null)
			{
				cardModel.SetToFreeThisTurn();
				await CardPileCmd.AddGeneratedCardToCombat(cardModel, PileType.Hand, base.Owner);
			}
		}

		/// <summary>
		/// ONLY USE THIS IN TESTS!
		/// </summary>
		public void MockGeneratedCard(CardModel card)
		{
			AssertMutable();
			_mockGeneratedCard = card;
		}
	}
	public sealed class SpoilsMap : CardModel
	{
		private int _spoilsActIndex = -1;

		public override int MaxUpgradeLevel => 0;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new GoldVar(600));

		public override IEnumerable<CardKeyword> CanonicalKeywords => new global::<>z__ReadOnlySingleElementList<CardKeyword>(CardKeyword.Unplayable);

		[SavedProperty]
		public int SpoilsActIndex
		{
			get
			{
				return _spoilsActIndex;
			}
			set
			{
				AssertMutable();
				_spoilsActIndex = value;
			}
		}

		public MapCoord? SpoilsCoord { get; private set; }

		public SpoilsMap()
			: base(-1, CardType.Quest, CardRarity.Quest, TargetType.Self)
		{
		}

		public override void AfterCreated()
		{
			SpoilsActIndex = 1;
		}

		public override ActMap ModifyGeneratedMap(IRunState runState, ActMap map, int actIndex)
		{
			if (actIndex != SpoilsActIndex)
			{
				return map;
			}
			CardPile? pile = base.Pile;
			if (pile == null || pile.Type != PileType.Deck)
			{
				return map;
			}
			return new SpoilsActMap(runState);
		}

		public override ActMap ModifyGeneratedMapLate(IRunState runState, ActMap map, int actIndex)
		{
			if (actIndex != SpoilsActIndex)
			{
				return map;
			}
			CardPile? pile = base.Pile;
			if (pile == null || pile.Type != PileType.Deck)
			{
				return map;
			}
			MapPoint mapPoint = map.GetAllMapPoints().FirstOrDefault((MapPoint p) => p.PointType == MapPointType.Treasure);
			if (mapPoint != null)
			{
				SpoilsCoord = mapPoint.coord;
			}
			return map;
		}

		public override Task AfterMapGenerated(ActMap map, int actIndex)
		{
			CardPile? pile = base.Pile;
			if (pile == null || pile.Type != PileType.Deck)
			{
				return Task.CompletedTask;
			}
			if (actIndex != SpoilsActIndex)
			{
				return Task.CompletedTask;
			}
			if (SpoilsCoord.HasValue && map.HasPoint(SpoilsCoord.Value))
			{
				map.GetPoint(SpoilsCoord.Value)?.AddQuest(this);
			}
			return Task.CompletedTask;
		}

		public override Task BeforeCardRemoved(CardModel card)
		{
			if (card != this)
			{
				return Task.CompletedTask;
			}
			if (SpoilsActIndex != base.Owner.RunState.CurrentActIndex)
			{
				return Task.CompletedTask;
			}
			if (!SpoilsCoord.HasValue)
			{
				return Task.CompletedTask;
			}
			base.Owner.RunState.Map.GetPoint(SpoilsCoord.Value)?.RemoveQuest(this);
			return Task.CompletedTask;
		}

		public async Task<int> OnQuestComplete()
		{
			await PlayerCmd.GainGold(base.DynamicVars.Gold.BaseValue, base.Owner);
			PlayerCmd.CompleteQuest(this);
			await CardPileCmd.RemoveFromDeck(this);
			return base.DynamicVars.Gold.IntValue;
		}
	}
