	/// <summary>
	/// The rarity used by Badges in the Run Summary screen.
	/// The rarity is based on how hard they are to get and reward bonus points the harder they are.
	/// Used for tiebreakers amongst players who have a tied score in the Leaderboards.
	/// </summary>
	public enum BadgeRarity
	{
		None,
		Bronze,
		Silver,
		Gold
	}
	/// <summary>
	/// Won with a deck of 40, 60, or 100 or more cards.
	/// </summary>
	public class BigDeck : Badge
	{
		public override BadgeRarity Rarity
		{
			get
			{
				int count = _localPlayer.Deck.Count;
				if (count >= 60)
				{
					if (count >= 100)
					{
						return BadgeRarity.Gold;
					}
					return BadgeRarity.Silver;
				}
				if (count >= 40)
				{
					return BadgeRarity.Bronze;
				}
				return BadgeRarity.None;
			}
		}

		/// <summary>
		/// Won with a deck of 40, 60, or 100 or more cards.
		/// </summary>
		public BigDeck(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "BIG_DECK", requiresWin: true, multiplayerOnly: false)
		{
		}

		public override bool IsObtained()
		{
			return Rarity != BadgeRarity.None;
		}
	}
	/// <summary>
	/// Play 20 cards in a single turn.
	/// </summary>
	public class CccCombo : Badge
	{
		public override BadgeRarity Rarity => BadgeRarity.Bronze;

		/// <summary>
		/// Play 20 cards in a single turn.
		/// </summary>
		public CccCombo(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "CCCCOMBO", requiresWin: false, multiplayerOnly: false)
		{
		}

		public override bool IsObtained()
		{
			return _localPlayer.ExtraFields.CccomboBadgeUnlocked;
		}
	}
	/// <summary>
	/// Play 20 cards in a single turn.
	/// </summary>
	public class CccComboModel : BadgeModel
	{
		private int _cardsPlayedThisTurn;

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (!LocalContext.IsMine(cardPlay.Card))
			{
				return Task.CompletedTask;
			}
			_cardsPlayedThisTurn++;
			if (_cardsPlayedThisTurn >= 20)
			{
				Player owner = cardPlay.Card.Owner;
				if (!owner.ExtraFields.CccomboBadgeUnlocked)
				{
					Log.Info("Player played 20 cards in a single turn, ccccombo unlocked");
				}
				owner.ExtraFields.CccomboBadgeUnlocked = true;
			}
			return Task.CompletedTask;
		}

		public override Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (side != CombatSide.Player)
			{
				return Task.CompletedTask;
			}
			_cardsPlayedThisTurn = 0;
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Won with 5 or more Curses.
	/// </summary>
	public class Curses : Badge
	{
		private const int _curseRequirement = 5;

		public override BadgeRarity Rarity => BadgeRarity.Bronze;

		/// <summary>
		/// Won with 5 or more Curses.
		/// </summary>
		public Curses(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "CURSES", requiresWin: true, multiplayerOnly: false)
		{
		}

		public override bool IsObtained()
		{
			int num = 0;
			foreach (SerializableCard item in _localPlayer.Deck)
			{
				if (SaveUtil.CardOrDeprecated(item.Id).Type == CardType.Curse)
				{
					num++;
				}
			}
			return num >= 5;
		}
	}
	/// <summary>
	/// The player who dealt the most damage in a multiplayer game gets this badge.
	/// </summary>
	public class DamageLeader : Badge
	{
		public override BadgeRarity Rarity => BadgeRarity.Bronze;

		/// <summary>
		/// The player who dealt the most damage in a multiplayer game gets this badge.
		/// </summary>
		public DamageLeader(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "DAMAGE_LEADER", requiresWin: false, multiplayerOnly: true)
		{
		}

		public override bool IsObtained()
		{
			if (_run.MapPointHistory.Count < 1 || _run.MapPointHistory[0].Count < 5)
			{
				return false;
			}
			SerializablePlayer serializablePlayer = null;
			foreach (SerializablePlayer player in _run.Players)
			{
				if (serializablePlayer == null || player.ExtraFields.DamageDealt > serializablePlayer.ExtraFields.DamageDealt)
				{
					serializablePlayer = player;
				}
			}
			return serializablePlayer?.NetId == _localPlayer.NetId;
		}
	}
