	/// <summary>
	/// Keeps track of how many debuffs a player has applied.
	/// </summary>
	public class DebufferModel : BadgeModel
	{
		public override Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (power.GetTypeForAmount(amount) == PowerType.Debuff && !(power is ITemporaryPower) && applier != null && applier.Player != null && applier != power.Owner)
			{
				applier.Player.ExtraFields.DebuffsApplied++;
			}
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Obtained both fake and real Snecko Eyes.
	/// </summary>
	public class DoubleSnecko : Badge
	{
		public override BadgeRarity Rarity => BadgeRarity.Bronze;

		/// <summary>
		/// Obtained both fake and real Snecko Eyes.
		/// </summary>
		public DoubleSnecko(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "DOUBLE_SNECKO", requiresWin: false, multiplayerOnly: false)
		{
		}

		public override bool IsObtained()
		{
			if (_localPlayer.Relics.Any((SerializableRelic r) => r.Id == ModelDb.Relic<SneckoEye>().Id))
			{
				return _localPlayer.Relics.Any((SerializableRelic r) => r.Id == ModelDb.Relic<FakeSneckoEye>().Id);
			}
			return false;
		}
	}
	/// <summary>
	/// Defeat X Elites. The more you kill, the higher the rarity.
	/// </summary>
	public class EliteKiller : Badge
	{
		public override BadgeRarity Rarity
		{
			get
			{
				int elitesKilledCount = ScoreUtility.GetElitesKilledCount(_run.MapPointHistory);
				if (elitesKilledCount >= 6)
				{
					if (elitesKilledCount >= 9)
					{
						return BadgeRarity.Gold;
					}
					return BadgeRarity.Silver;
				}
				if (elitesKilledCount >= 3)
				{
					return BadgeRarity.Bronze;
				}
				return BadgeRarity.None;
			}
		}

		/// <summary>
		/// Defeat X Elites. The more you kill, the higher the rarity.
		/// </summary>
		public EliteKiller(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "ELITE", requiresWin: false, multiplayerOnly: false)
		{
		}

		public override bool IsObtained()
		{
			return Rarity != BadgeRarity.None;
		}
	}
	/// <summary>
	/// Won with Max HP reduced to less than half of your starting HP.
	/// </summary>
	public class Famished : Badge
	{
		public override BadgeRarity Rarity => BadgeRarity.Bronze;

		/// <summary>
		/// Won with Max HP reduced to less than half of your starting HP.
		/// </summary>
		public Famished(SerializableRun run, bool won, ulong playerId)
			: base(run, won, playerId, "FAMISHED", requiresWin: true, multiplayerOnly: false)
		{
		}

		public override bool IsObtained()
		{
			int num = (SaveUtil.CharacterOrDeprecated(_localPlayer.CharacterId).StartingHp + 1) / 2;
			return _localPlayer.MaxHp < num;
		}
	}
	/// <summary>
	/// Increased Max HP by a great amount and won.
	/// </summary>
	public class Glutton : Badge
	{
		public override BadgeRarity Rarity
		{
			get
			{
				int startingHp = SaveUtil.CharacterOrDeprecated(_localPlayer.CharacterId).StartingHp;
				int num = _localPlayer.MaxHp - startingHp;
				if (num >= 30)
				{
					if (num >= 50)
					{
						return BadgeRarity.Gold;
					}
					return BadgeRarity.Silver;
				}
