namespace MegaCrit.Sts2.Core.Models.Achievements
{
	public class Play20CardsSingleTurnAchievement : AchievementModel
	{
		private int _cardsPlayedThisTurn;

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (!LocalContext.IsMine(cardPlay.Card))
			{
				return Task.CompletedTask;
			}
			_cardsPlayedThisTurn++;
			if (_cardsPlayedThisTurn >= 20)
			{
				AchievementsUtil.Unlock(Achievement.Play20CardsSingleTurn, cardPlay.Card.Owner);
			}
			return Task.CompletedTask;
		}

		public override Task AfterSideTurnStart(CombatSide side, IReadOnlyList<Creature> participants, ICombatState combatState)
		{
			if (side != CombatSide.Player)
			{
				return Task.CompletedTask;
			}
			_cardsPlayedThisTurn = 0;
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when the player exhausts a large number of cards in a single turn.
	/// </summary>
	public class SkillIronclad1Achievement : AchievementModel
	{
		private const int _exhaustRequirement = 20;

		private int _cardsExhaustedThisCombat;

		public override Task AfterCardExhausted(PlayerChoiceContext choiceContext, CardModel card, bool causedByEthereal)
		{
			if (!LocalContext.IsMine(card))
			{
				return Task.CompletedTask;
			}
			_cardsExhaustedThisCombat++;
			if (_cardsExhaustedThisCombat >= 20)
			{
				AchievementsUtil.Unlock(Achievement.CharacterSkillIronclad1, card.Owner);
			}
			return Task.CompletedTask;
		}

		public override Task AfterRoomEntered(AbstractRoom room)
		{
			_cardsExhaustedThisCombat = 0;
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when a player deals a large amount of damage in a single blow.
	/// </summary>
	public class SkillIronclad2Achievement : AchievementModel
	{
		private const int _damageRequirement = 999;

		public override Task AfterDamageGiven(PlayerChoiceContext choiceContext, Creature? dealer, DamageResult result, ValueProp props, Creature target, CardModel? cardSource)
		{
			if (!LocalContext.IsMe(dealer))
			{
				return Task.CompletedTask;
			}
			if (result.UnblockedDamage < 999)
			{
				return Task.CompletedTask;
			}
			AchievementsUtil.Unlock(Achievement.CharacterSkillIronclad2, dealer.Player);
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when a player applies a large amount of Doom to a single creature.
	/// </summary>
	public class SkillNecrobinder1Achievement : AchievementModel
	{
		private const int _doomThreshold = 999;

		public override Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (!LocalContext.IsMe(applier))
			{
				return Task.CompletedTask;
			}
			if (power is DoomPower && power.Amount >= 999)
			{
				AchievementsUtil.Unlock(Achievement.CharacterSkillNecrobinder1, applier.Player);
			}
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when the player applies a large amount of Strength to Osty.
	/// </summary>
	public class SkillNecrobinder2Achievement : AchievementModel
	{
		private const int _strengthThreshold = 50;

		public override Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (!LocalContext.IsMe(applier))
			{
				return Task.CompletedTask;
			}
			if (power is StrengthPower && power.Owner.Monster is Osty && power.Amount >= 50)
			{
				AchievementsUtil.Unlock(Achievement.CharacterSkillNecrobinder2, applier.Player);
			}
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when the player forges a Sovereign Blade which deals a large amount of damage.
	/// </summary>
	public class SkillRegent1Achievement : AchievementModel
	{
		private const int _damageThreshold = 999;

		public override Task AfterForge(decimal amount, Player forger, AbstractModel? source)
		{
			if (!LocalContext.IsMe(forger))
			{
				return Task.CompletedTask;
			}
			if (AchievementsUtil.IsUnlocked(Achievement.CharacterSkillRegent1))
			{
				return Task.CompletedTask;
			}
			foreach (SovereignBlade item in forger.PlayerCombatState.AllCards.OfType<SovereignBlade>())
			{
				if (item.DynamicVars.Damage.BaseValue >= 999m)
				{
					AchievementsUtil.Unlock(Achievement.CharacterSkillRegent1, forger);
				}
			}
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when the player obtains a large number of Stars.
	/// </summary>
	public class SkillRegent2Achievement : AchievementModel
	{
		private const int _starThreshold = 20;

		public override Task AfterStarsGained(int amount, Player gainer)
		{
			if (!LocalContext.IsMe(gainer))
			{
				return Task.CompletedTask;
			}
			PlayerCombatState? playerCombatState = gainer.PlayerCombatState;
			if (playerCombatState != null && playerCombatState.Stars < 20)
			{
				return Task.CompletedTask;
			}
			AchievementsUtil.Unlock(Achievement.CharacterSkillRegent2, gainer);
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when a player plays a large number of Sly cards from a single card.
	/// </summary>
	public class SkillSilent1Achievement : AchievementModel
	{
		private CardModel? _firstCardOnStack;

		private int _slyCardsPlayed;

		public override Task BeforeCardPlayed(CardPlay cardPlay)
		{
			if (!LocalContext.IsMine(cardPlay.Card))
			{
				return Task.CompletedTask;
			}
			if (_firstCardOnStack == null)
			{
				_firstCardOnStack = cardPlay.Card;
			}
			return Task.CompletedTask;
		}

		public override Task BeforeCardAutoPlayed(CardModel card, Creature? target, AutoPlayType type)
		{
			if (!LocalContext.IsMine(card))
			{
				return Task.CompletedTask;
			}
			if (type != AutoPlayType.SlyDiscard)
			{
				return Task.CompletedTask;
			}
			if (_firstCardOnStack == null)
			{
				return Task.CompletedTask;
			}
			_slyCardsPlayed++;
			if (_slyCardsPlayed >= 5)
			{
				AchievementsUtil.Unlock(Achievement.CharacterSkillSilent1, card.Owner);
			}
			return Task.CompletedTask;
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (!LocalContext.IsMine(cardPlay.Card))
			{
				return Task.CompletedTask;
			}
			if (cardPlay.Card == _firstCardOnStack)
			{
				_firstCardOnStack = null;
				_slyCardsPlayed = 0;
			}
			return Task.CompletedTask;
		}

		public override Task AfterRoomEntered(AbstractRoom room)
		{
			_firstCardOnStack = null;
			_slyCardsPlayed = 0;
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// Grants an achievement when the player applies a large amount of poison to a single creature.
