namespace MegaCrit.Sts2.Core.Modding
{
	public class AssemblyInfo
	{
		/// <summary>
		/// Helper dictionary mapping assemblies to the mods they represent.
		/// </summary>
		public static System.Collections.Generic.Dictionary<Assembly, Mod>? ModMap { get; private set; }

		/// <summary>
		/// The base game assembly.
		/// </summary>
		public static Assembly? BaseGame { get; private set; }

		public static System.Collections.Generic.Dictionary<Type, (Mod?, bool)>? MockTypes { get; set; }

		public static void Init()
		{
			BaseGame = Assembly.GetExecutingAssembly();
			ModMap = new System.Collections.Generic.Dictionary<Assembly, Mod>();
			foreach (Mod mod in ModManager.Mods)
			{
				if (mod.state != ModLoadState.Loaded)
				{
					continue;
				}
				foreach (Assembly assembly in mod.assemblies)
				{
					ModMap[assembly] = mod;
				}
			}
		}

		public static Mod? ModForType(Type type, out bool isBaseGame)
		{
			if (MockTypes != null && MockTypes.TryGetValue(type, out (Mod, bool) value))
			{
				isBaseGame = value.Item2;
				return value.Item1;
			}
			if (ModMap == null)
			{
				throw new InvalidOperationException();
			}
			Assembly assembly = type.Assembly;
			ModMap.TryGetValue(assembly, out Mod value2);
			isBaseGame = BaseGame == assembly;
			return value2;
		}

		/// <summary>
		/// This should only be called by tests.
		/// Typically, AssemblyInfo is initialized once at the start of the game and never cleared.
		/// </summary>
		public static void ClearForTests()
		{
			BaseGame = null;
			ModMap = null;
		}
	}
	/// <summary>
	/// A file IO abstraction layer for use with ModManager.
	/// It's a little different than ISaveStore, which is scoped only to a specific directory. This class allows global access
	/// to the filesystem.
	/// </summary>
	public interface IModManagerFileIo
	{
		string[] GetFilesAt(string path);

		string[] GetDirectoriesAt(string path);

		bool FileExists(string path);

		bool DirectoryExists(string path);

		Stream OpenStream(string path, Godot.FileAccess.ModeFlags mode);

		void MakeDirRecursive(string path);

		Error CopyFile(string sourcePath, string destinationPath);
	}
	/// <summary>
	/// Information about a loaded mod.
	/// </summary>
	public class Mod
	{
		/// <summary>
		/// Where the mod originated from.
		/// </summary>
		public ModSource modSource;

		/// <summary>
		/// Path where the mod files are located.
		/// </summary>
		public required string path;

		/// <summary>
		/// Whether the mod was loaded, and if it was not loaded, why.
		/// Since there's no way to unload mods while the game is running, this value cannot change after the initial mod
		/// initialization occurs.
		/// Even if the mod is set to disabled in SettingsSave, this value is the true source of whether or not the mod was
		/// loaded into the game.
		/// </summary>
		public ModLoadState state;

		/// <summary>
		/// The mod manifest.
		/// </summary>
		public ModManifest? manifest;

		/// <summary>
		/// The version parsed from the mod manifest.
		/// Null if the version is not present or is not a valid semantic version.
		/// </summary>
		public SemanticVersion? version;

		/// <summary>
		/// The C# assemblies loaded with the mod, if any.
		/// There are usually only zero or one in the list. Mods can register more assemblies, e.g. in the situation where
		/// they create dynamic assemblies.
		/// </summary>
		public List<Assembly> assemblies = new List<Assembly>();

		/// <summary>
		/// If null, then no errors occurred while loading the mod.
		/// If this is set, then there was an error loading the mod that should be displayed. That doesn't necessarily mean
		/// the mod failed to load; see <see cref="F:MegaCrit.Sts2.Core.Modding.Mod.state" /> for that.
		/// </summary>
		public List<LocString>? errors;

		/// <summary>
		/// The ID of the workshop item, if the mod source is Steam Workshop.
		/// This can be used as the value of a PublishedFileId_t, but we use ulong here so that we don't have to guard this
		/// with DISABLESTEAMWORKS.
		/// </summary>
		public ulong? workshopId;
	}
