namespace MegaCrit.Sts2.Core.Map
{
	/// <summary>
	/// Handles the creation of map points for a map.
	/// </summary>
	public abstract class ActMap
	{
		public readonly HashSet<MapPoint> startMapPoints = new HashSet<MapPoint>();

		public abstract MapPoint BossMapPoint { get; }

		public abstract MapPoint StartingMapPoint { get; }

		/// <summary>
		/// The second boss map point for Double Boss mode (Ascension 10+).
		/// Null if not in double boss mode.
		/// </summary>
		public virtual MapPoint? SecondBossMapPoint => null;

		protected abstract MapPoint?[,] Grid { get; }

		public int GetColumnCount()
		{
			return Grid.GetLength(0);
		}

		public int GetRowCount()
		{
			return Grid.GetLength(1);
		}

		public IEnumerable<MapPoint> GetAllMapPoints()
		{
			for (int c = 0; c < GetColumnCount(); c++)
			{
				for (int r = 0; r < Grid.GetLength(1); r++)
				{
					MapPoint mapPoint = Grid[c, r];
					if (mapPoint != null)
					{
						yield return mapPoint;
					}
				}
			}
		}

		public IEnumerable<MapPoint> GetPointsInRow(int row)
		{
			if (row < 0 || row >= Grid.GetLength(1))
			{
				yield break;
			}
			for (int c = 0; c < GetColumnCount(); c++)
			{
				MapPoint mapPoint = Grid[c, row];
				if (mapPoint != null)
				{
					yield return mapPoint;
				}
			}
		}

		public virtual MapPoint? GetPoint(MapCoord coord)
		{
			return GetPoint(coord.col, coord.row);
		}

		public MapPoint? GetPoint(int col, int row)
		{
			if (col == BossMapPoint.coord.col && row == BossMapPoint.coord.row)
			{
				return BossMapPoint;
			}
			if (SecondBossMapPoint != null && col == SecondBossMapPoint.coord.col && row == SecondBossMapPoint.coord.row)
			{
				return SecondBossMapPoint;
			}
			if (col == StartingMapPoint.coord.col && row == StartingMapPoint.coord.row)
			{
				return StartingMapPoint;
			}
			if (col >= 0 && col < Grid.GetLength(0) && row >= 0 && row < Grid.GetLength(1))
			{
				return Grid[col, row];
			}
			return null;
		}

		public bool IsInMap(MapPoint mapPoint)
		{
			if (mapPoint.PointType == MapPointType.Ancient || mapPoint.PointType == MapPointType.Boss)
			{
				return true;
			}
			int col = mapPoint.coord.col;
			int row = mapPoint.coord.row;
			if (col < 0 || col >= Grid.GetLength(0) || row < 0 || row >= Grid.GetLength(1))
			{
				return false;
			}
			return Grid[col, row] != null;
		}

		public bool HasPoint(MapCoord coord)
		{
			if (coord.col == BossMapPoint.coord.col && coord.row == BossMapPoint.coord.row)
			{
				return true;
			}
			if (SecondBossMapPoint != null && coord.col == SecondBossMapPoint.coord.col && coord.row == SecondBossMapPoint.coord.row)
			{
				return true;
			}
			if (coord.col == StartingMapPoint.coord.col && coord.row == StartingMapPoint.coord.row)
			{
				return true;
			}
			if (coord.col < 0 || coord.col >= Grid.GetLength(0))
			{
				return false;
			}
			if (coord.row < 0 || coord.row >= Grid.GetLength(1))
			{
				return false;
			}
			return Grid[coord.col, coord.row] != null;
		}
	}
	public sealed class GoldenPathActMap : ActMap
	{
		private readonly MapPointType[] _defaultPointTypes = new MapPointType[16]
		{
			MapPointType.Monster,
			MapPointType.Unknown,
			MapPointType.Monster,
			MapPointType.RestSite,
			MapPointType.Monster,
			MapPointType.RestSite,
			MapPointType.Unknown,
			MapPointType.Treasure,
			MapPointType.Unknown,
			MapPointType.Treasure,
			MapPointType.Unknown,
			MapPointType.Shop,
			MapPointType.Elite,
			MapPointType.RestSite,
			MapPointType.Elite,
			MapPointType.RestSite
		};

		private const int _width = 7;

		private const int _middle = 3;

		public override MapPoint BossMapPoint { get; }

		public override MapPoint StartingMapPoint { get; }

		protected override MapPoint?[,] Grid { get; }

		public GoldenPathActMap(IRunState runState)
		{
			List<MapPointType> list = _defaultPointTypes.ToList();
			if (runState.Players.Count > 1)
			{
				list.RemoveAt(2);
			}
			Grid = new MapPoint[7, list.Count + 1];
			BossMapPoint = new MapPoint(GetColumnCount() / 2, GetRowCount())
			{
				PointType = MapPointType.Boss
			};
			StartingMapPoint = new MapPoint(GetColumnCount() / 2, 0)
			{
				PointType = MapPointType.Ancient
			};
			for (int i = 0; i < list.Count; i++)
			{
				MapPoint mapPoint = new MapPoint(3, i + 1);
				Grid[3, i + 1] = mapPoint;
				mapPoint.PointType = list[i];
				if (i > 0)
				{
					Grid[3, i].AddChildPoint(mapPoint);
				}
			}
			startMapPoints.Add(Grid[3, 1]);
			Grid[3, GetRowCount() - 1].AddChildPoint(BossMapPoint);
			StartingMapPoint.AddChildPoint(Grid[3, 1]);
		}
	}
	/// <summary>
	/// A simple struct representing the row and column that a given map point is on in the map.
	/// </summary>
	[Serializable]
	public struct MapCoord(int col, int row) : IEquatable<MapCoord>, IComparable<MapCoord>, IPacketSerializable
	{
		[JsonInclude]
		public int col = col;

		[JsonInclude]
		public int row = row;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteByte((byte)col);
			writer.WriteByte((byte)row);
		}

		public void Deserialize(PacketReader reader)
		{
			col = reader.ReadByte();
			row = reader.ReadByte();
		}

		public static bool operator ==(MapCoord first, MapCoord second)
		{
			return first.Equals(second);
		}

		public static bool operator !=(MapCoord first, MapCoord second)
		{
			return !(first == second);
		}

		public bool Equals(MapCoord other)
		{
			if (col == other.col)
			{
				return row == other.row;
			}
			return false;
		}

		public override bool Equals(object? obj)
		{
			if (obj is MapCoord other)
			{
				return Equals(other);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (col, row).GetHashCode();
		}

		public int CompareTo(MapCoord other)
		{
			return (col, row).CompareTo((other.col, other.row));
		}

		public override string ToString()
		{
			return $"MapCoord ({col}, {row})";
		}
	}
	/// <summary>
	/// Detects and removes duplicate path segments from act maps.
	/// Both StandardActMap and SpoilsActMap use this after point type assignment
	/// to eliminate redundant paths that share the same sequence of point types.
	/// </summary>
	public static class MapPathPruning
	{
		/// <summary>
		/// Prunes duplicate segments, then repairs any point types that fell below their target
		/// count. Since repair can create new duplicates, loops until stable (up to 3 iterations).
		/// </summary>
		public static void PruneAndRepair(MapPoint?[,] grid, HashSet<MapPoint> startMapPoints, ActMap map, MapPointTypeCounts pointTypeCounts, Rng rng, Func<MapPointType, MapPoint, bool> isValidPointType)
		{
			for (int i = 0; i < 3; i++)
			{
				PruneDuplicateSegments(grid, startMapPoints, map.StartingMapPoint, rng);
				if (!RepairPrunedPointTypes(map, pointTypeCounts, rng, isValidPointType))
				{
					break;
				}
			}
		}

		/// <summary>
		/// After pruning removes nodes, some point types may fall below their target count.
		/// This repairs the map by replacing monsters with the missing types.
		/// </summary>
		/// <param name="map">The map to repair.</param>
		/// <param name="pointTypeCounts">Target counts for each point type.</param>
		/// <param name="rng">Random number generator used for replacement selection.</param>
		/// <param name="isValidPointType">Validates whether a type can be placed at a given point.</param>
		/// <returns>true if any repairs were made (indicating re-pruning may be needed)</returns>
		public static bool RepairPrunedPointTypes(ActMap map, MapPointTypeCounts pointTypeCounts, Rng rng, Func<MapPointType, MapPoint, bool> isValidPointType)
		{
			bool flag = false;
			flag |= RepairPointType(map, MapPointType.Shop, pointTypeCounts.NumOfShops, rng, isValidPointType);
			flag |= RepairPointType(map, MapPointType.Elite, pointTypeCounts.NumOfElites, rng, isValidPointType);
			flag |= RepairPointType(map, MapPointType.RestSite, pointTypeCounts.NumOfRests, rng, isValidPointType);
			return flag | RepairPointType(map, MapPointType.Unknown, pointTypeCounts.NumOfUnknowns, rng, isValidPointType);
		}

		private static bool RepairPointType(ActMap map, MapPointType type, int targetCount, Rng rng, Func<MapPointType, MapPoint, bool> isValidPointType)
		{
			int num = map.GetAllMapPoints().Count((MapPoint p) => p.PointType == type);
			int num2 = targetCount - num;
			if (num2 <= 0)
			{
				return false;
			}
			bool result = false;
			List<MapPoint> list = (from p in map.GetAllMapPoints()
				where p.PointType == MapPointType.Monster && p.CanBeModified
				select p).ToList();
			list.StableShuffle(rng);
			foreach (MapPoint item in list)
			{
				if (num2 == 0)
				{
					break;
				}
				if (isValidPointType(type, item))
				{
					item.PointType = type;
					num2--;
					result = true;
				}
			}
			return result;
		}

		/// <summary>
		/// Runs the full prune loop (up to 50 iterations) to remove duplicate segments.
		/// </summary>
		public static void PruneDuplicateSegments(MapPoint?[,] grid, HashSet<MapPoint> startMapPoints, MapPoint startingMapPoint, Rng rng)
		{
			int num = 0;
			List<List<MapPoint[]>> matchingSegments = FindMatchingSegments(startingMapPoint);
			while (PrunePaths(grid, startMapPoints, matchingSegments, rng))
			{
				num++;
				if (num > 50)
				{
					throw new InvalidOperationException($"Unable to prune matching segments in {num} iterations");
				}
				matchingSegments = FindMatchingSegments(startingMapPoint);
			}
		}

		public static List<List<MapPoint[]>> FindMatchingSegments(MapPoint startingMapPoint)
		{
			List<List<MapPoint>> list = FindAllPaths(startingMapPoint);
			SortedDictionary<string, List<MapPoint[]>> segments = new SortedDictionary<string, List<MapPoint[]>>(StringComparer.Ordinal);
			foreach (List<MapPoint> item in list)
			{
				AddSegmentsToDictionary(item, segments);
			}
			return GetDuplicateSegments(segments);
		}

		public static List<List<MapPoint>> FindAllPaths(MapPoint currentMapPoint)
		{
			List<List<MapPoint>> list = new List<List<MapPoint>>();
			if (currentMapPoint.PointType == MapPointType.Boss)
			{
				int num = 1;
				List<MapPoint> list2 = new List<MapPoint>(num);
				CollectionsMarshal.SetCount(list2, num);
				Span<MapPoint> span = CollectionsMarshal.AsSpan(list2);
				int index = 0;
				span[index] = currentMapPoint;
				list.Add(list2);
				return list;
			}
			foreach (MapPoint child in currentMapPoint.Children)
			{
				List<List<MapPoint>> list3 = FindAllPaths(child);
				foreach (List<MapPoint> item in list3)
				{
					int index = 1;
					List<MapPoint> list4 = new List<MapPoint>(index);
					CollectionsMarshal.SetCount(list4, index);
					Span<MapPoint> span = CollectionsMarshal.AsSpan(list4);
					int num = 0;
					span[num] = currentMapPoint;
					List<MapPoint> list5 = list4;
					list5.AddRange(item);
					list.Add(list5);
				}
			}
			return list;
		}

		private static void AddSegmentsToDictionary(IReadOnlyList<MapPoint> path, IDictionary<string, List<MapPoint[]>> segments)
		{
			for (int i = 0; i < path.Count - 1; i++)
			{
				if (!IsValidSegmentStartMapPoint(path[i]))
				{
					continue;
				}
				for (int j = 2; j < path.Count - i; j++)
				{
					MapPoint endMapPoint = path[i + j];
					if (IsValidSegmentEndMapPoint(endMapPoint))
					{
						MapPoint[] array = path.Skip(i).Take(j + 1).ToArray();
						string key = GenerateSegmentKey(array);
						if (!segments.ContainsKey(key))
						{
							int num = 1;
							List<MapPoint[]> list = new List<MapPoint[]>(num);
							CollectionsMarshal.SetCount(list, num);
							Span<MapPoint[]> span = CollectionsMarshal.AsSpan(list);
							int index = 0;
							span[index] = array;
							segments[key] = list;
						}
						else if (!AnyOverlappingSegments(segments[key], array))
						{
							segments[key].Add(array);
						}
					}
				}
			}
		}

		private static bool IsValidSegmentStartMapPoint(MapPoint startMapPoint)
		{
			if (startMapPoint.Children.Count <= 1)
			{
				return startMapPoint.coord.row == 0;
			}
			return true;
		}

		private static bool IsValidSegmentEndMapPoint(MapPoint endMapPoint)
		{
			return endMapPoint.parents.Count >= 2;
		}

		private static string GenerateSegmentKey(IReadOnlyList<MapPoint> segment)
		{
			StringBuilder stringBuilder = new StringBuilder();
			MapPoint mapPoint = segment[0];
			MapPoint mapPoint2 = segment[segment.Count - 1];
			if (mapPoint.coord.row == 0)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(3, 3, stringBuilder2);
				handler.AppendFormatted(mapPoint.coord.row);
				handler.AppendLiteral("-");
				handler.AppendFormatted(mapPoint2.coord.col);
				handler.AppendLiteral(",");
				handler.AppendFormatted(mapPoint2.coord.row);
				handler.AppendLiteral("-");
				stringBuilder3.Append(ref handler);
			}
			else
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(4, 4, stringBuilder2);
				handler.AppendFormatted(mapPoint.coord.col);
				handler.AppendLiteral(",");
				handler.AppendFormatted(mapPoint.coord.row);
				handler.AppendLiteral("-");
				handler.AppendFormatted(mapPoint2.coord.col);
				handler.AppendLiteral(",");
				handler.AppendFormatted(mapPoint2.coord.row);
				handler.AppendLiteral("-");
				stringBuilder4.Append(ref handler);
			}
			stringBuilder.Append(string.Join(",", segment.Select((MapPoint point) => (int)point.PointType)));
			return stringBuilder.ToString();
		}

		private static bool AnyOverlappingSegments(IEnumerable<MapPoint[]> existingSegments, IReadOnlyList<MapPoint> segment)
		{
			return existingSegments.Any((MapPoint[] existingSegment) => OverlappingSegment(existingSegment, segment));
		}

		private static bool OverlappingSegment(IReadOnlyList<MapPoint> a, IReadOnlyList<MapPoint> b)
		{
			if (a.Count < 3 || b.Count < 3)
			{
				return false;
			}
			for (int i = 1; i <= a.Count - 2; i++)
			{
				if (object.Equals(a[i], b[i]))
				{
					return true;
				}
			}
			return false;
		}

		private static List<List<MapPoint[]>> GetDuplicateSegments(IDictionary<string, List<MapPoint[]>> segments)
		{
			return segments.Values.Where((List<MapPoint[]> segmentList) => segmentList.Count > 1).ToList();
		}

		private static bool PrunePaths(MapPoint?[,] grid, HashSet<MapPoint> startMapPoints, IEnumerable<List<MapPoint[]>> matchingSegments, Rng rng)
		{
			foreach (List<MapPoint[]> matchingSegment in matchingSegments)
			{
				matchingSegment.UnstableShuffle(rng);
				if (PruneAllButLast(grid, startMapPoints, matchingSegment) != 0)
				{
					return true;
				}
				if (BreakAParentChildRelationshipInAnySegment(matchingSegment))
				{
					return true;
				}
			}
			return false;
		}

		private static int PruneAllButLast(MapPoint?[,] grid, HashSet<MapPoint> startMapPoints, IReadOnlyList<MapPoint[]> matches)
		{
			int num = 0;
			foreach (MapPoint[] match in matches)
			{
				if (num == matches.Count - 1)
				{
					return num;
				}
				if (PruneSegment(grid, startMapPoints, match))
				{
					num++;
				}
			}
			return num;
		}

		private static bool PruneSegment(MapPoint?[,] grid, HashSet<MapPoint> startMapPoints, MapPoint[] segment)
		{
			bool result = false;
			for (int i = 0; i < segment.Length - 1; i++)
			{
				MapPoint mapPoint = segment[i];
				if (!IsInMap(grid, mapPoint))
				{
					return true;
				}
				if (mapPoint.Children.Count > 1 || mapPoint.parents.Count > 1 || mapPoint.parents.Any((MapPoint n) => n.Children.Count == 1 && !IsRemoved(grid, n)))
				{
					continue;
				}
				MapPoint[] source = segment.Skip(i).ToArray();
				if (!source.Any((MapPoint n) => n.Children.Count > 1 && n.parents.Count == 1))
				{
					if (segment[^1].parents.Count == 1)
					{
						return false;
					}
					if (!mapPoint.Children.Where((MapPoint c) => !Enumerable.Contains(segment, c)).Any((MapPoint c) => c.parents.Count == 1))
					{
						RemovePoint(grid, startMapPoints, mapPoint);
						result = true;
					}
				}
			}
			return result;
		}

		private static void RemovePoint(MapPoint?[,] grid, HashSet<MapPoint> startMapPoints, MapPoint mapPoint)
		{
			grid[mapPoint.coord.col, mapPoint.coord.row] = null;
			startMapPoints.Remove(mapPoint);
			foreach (MapPoint item in mapPoint.Children.ToList())
			{
				mapPoint.RemoveChildPoint(item);
			}
			foreach (MapPoint item2 in mapPoint.parents.ToList())
			{
				item2.RemoveChildPoint(mapPoint);
			}
		}

		private static bool IsInMap(MapPoint?[,] grid, MapPoint mapPoint)
		{
			if (grid[mapPoint.coord.col, mapPoint.coord.row] == null && mapPoint.PointType != MapPointType.Ancient)
			{
				return mapPoint.PointType == MapPointType.Boss;
			}
			return true;
		}

		private static bool IsRemoved(MapPoint?[,] grid, MapPoint mapPoint)
		{
			return grid[mapPoint.coord.col, mapPoint.coord.row] == null;
		}

		private static bool BreakAParentChildRelationshipInAnySegment(List<MapPoint[]> matches)
		{
			foreach (MapPoint[] match in matches)
			{
				if (BreakAParentChildRelationshipInSegment(match))
				{
					return true;
				}
			}
			return false;
		}

		private static bool BreakAParentChildRelationshipInSegment(MapPoint[] segment)
		{
			bool result = false;
			for (int i = 0; i < segment.Length - 1; i++)
			{
				MapPoint mapPoint = segment[i];
				if (mapPoint.Children.Count >= 2)
				{
					MapPoint mapPoint2 = segment[i + 1];
					if (mapPoint2.parents.Count != 1)
					{
						mapPoint.RemoveChildPoint(mapPoint2);
						result = true;
					}
				}
			}
			return result;
		}
	}
	public class MapPoint : IComparable<MapPoint>
	{
		private readonly List<AbstractModel> _quests = new List<AbstractModel>();

		public readonly HashSet<MapPoint> parents;

		public MapCoord coord;

		/// <summary>
		/// Is used to let Models that modify a map after it is generated to ensure that we don't modify this point.
		/// Is set by the ActMap if false (ie StandardActMap.AssignPointTypes).
		/// </summary>
		public bool CanBeModified { get; set; } = true;

		public MapPointType PointType { get; set; }

		public IReadOnlyList<AbstractModel> Quests => _quests;

		public HashSet<MapPoint> Children { get; }

		public event Action? NodeMarkedChanged;

		private bool Equals(MapPoint other)
		{
			return coord.Equals(other.coord);
		}

		public int CompareTo(MapPoint? other)
		{
			if (other == null)
			{
				return 1;
			}
			return coord.CompareTo(other.coord);
		}

		public MapPoint(int col, int row)
		{
			coord.row = row;
			coord.col = col;
			parents = new HashSet<MapPoint>();
			Children = new HashSet<MapPoint>();
		}

		public void AddChildPoint(MapPoint child)
		{
			Children.Add(child);
			child.parents.Add(this);
		}

		public void RemoveChildPoint(MapPoint child)
		{
			Children.Remove(child);
			child.parents.Remove(this);
		}

		public override string ToString()
		{
			return $"Point[{coord.col},{coord.row}]";
		}

		public MapPoint? LeftChild()
		{
			foreach (MapPoint child in Children)
			{
				if (child.IsAdjacentLeft(this))
				{
					return child;
				}
			}
			return null;
		}

		public MapPoint? RightChild()
		{
			foreach (MapPoint child in Children)
			{
				if (child.IsAdjacentRight(this))
				{
					return child;
				}
			}
			return null;
		}

		public bool IsAdjacentLeft(MapPoint sibling)
		{
			return coord.col - 1 == sibling.coord.col;
		}

		public bool IsAdjacentRight(MapPoint sibling)
		{
			return coord.col + 1 == sibling.coord.col;
		}

		public bool IsToTheLeft(MapPoint sibling)
		{
			return coord.col < sibling.coord.col;
		}

		public bool IsToTheRight(MapPoint sibling)
		{
			return coord.col > sibling.coord.col;
		}

		public bool IsInTheSameRow(MapPoint sibling)
		{
			return sibling.coord.row == coord.row;
		}

		public MapPoint? GetFirstCommonDescendant(MapPoint b)
		{
			if (Equals(b))
			{
				return b;
			}
			HashSet<MapPoint> allDescendants = GetAllDescendants();
			Queue<MapPoint> queue = new Queue<MapPoint>();
			queue.Enqueue(b);
			while (queue.Count > 0)
			{
				b = queue.Dequeue();
				if (allDescendants.Contains(b))
				{
					return b;
				}
				foreach (MapPoint child in b.Children)
				{
					queue.Enqueue(child);
				}
			}
			return null;
		}

		private HashSet<MapPoint> GetAllDescendants()
		{
			HashSet<MapPoint> hashSet = new HashSet<MapPoint>();
			Queue<MapPoint> queue = new Queue<MapPoint>();
			queue.Enqueue(this);
			while (queue.Count > 0)
			{
				MapPoint mapPoint = queue.Dequeue();
				if (!hashSet.Add(mapPoint))
				{
					continue;
				}
				foreach (MapPoint child in mapPoint.Children)
				{
					queue.Enqueue(child);
				}
			}
			return hashSet;
		}

		public MapPoint? GetCommonAncestor(MapPoint b)
		{
			if (coord.Equals(b.coord))
			{
				return b;
			}
			HashSet<MapPoint> allAncestors = GetAllAncestors();
			Queue<MapPoint> queue = new Queue<MapPoint>();
			queue.Enqueue(b);
			while (queue.Count > 0)
			{
				b = queue.Dequeue();
				if (allAncestors.Contains(b))
				{
					return b;
				}
				foreach (MapPoint parent in b.parents)
				{
					queue.Enqueue(parent);
				}
			}
			return null;
		}

		public int GetLastJunctionLength()
		{
			Queue<MapPoint> queue = new Queue<MapPoint>();
			queue.Enqueue(this);
			while (queue.Count > 0)
			{
				MapPoint mapPoint = queue.Dequeue();
				if (mapPoint.Children.Count > 1)
				{
					return coord.row - mapPoint.coord.row;
				}
				foreach (MapPoint parent in mapPoint.parents)
				{
					queue.Enqueue(parent);
				}
			}
			return coord.row;
		}

		public HashSet<MapPoint> GetAllAncestors()
		{
			HashSet<MapPoint> hashSet = new HashSet<MapPoint>();
			Queue<MapPoint> queue = new Queue<MapPoint>();
			queue.Enqueue(this);
			while (queue.Count > 0)
			{
				MapPoint mapPoint = queue.Dequeue();
				if (!hashSet.Add(mapPoint))
				{
					continue;
				}
				foreach (MapPoint parent in mapPoint.parents)
				{
					queue.Enqueue(parent);
				}
			}
			return hashSet;
		}

		public IEnumerable<MapPoint> BFS_FindPath(MapPoint target)
		{
			Queue<MapPoint> queue = new Queue<MapPoint>();
			System.Collections.Generic.Dictionary<MapPoint, MapPoint> dictionary = new System.Collections.Generic.Dictionary<MapPoint, MapPoint>();
			queue.Enqueue(this);
			while (queue.Count > 0)
			{
				MapPoint mapPoint = queue.Dequeue();
				if (mapPoint.Equals(target))
				{
					return BuildPath(dictionary, target);
				}
				foreach (MapPoint child in mapPoint.Children)
				{
					if (!dictionary.ContainsKey(child))
					{
						dictionary[child] = mapPoint;
						queue.Enqueue(child);
					}
				}
			}
			return new List<MapPoint>();
		}

		private IEnumerable<MapPoint> BuildPath(IReadOnlyDictionary<MapPoint, MapPoint> parentPoint, MapPoint target)
		{
			List<MapPoint> list = new List<MapPoint>();
			MapPoint mapPoint = target;
			while (!Equals(mapPoint))
			{
				list.Add(mapPoint);
				mapPoint = parentPoint[mapPoint];
			}
			list.Add(this);
			list.Reverse();
			return list;
		}

		public bool IsDescendantPathSame(MapPoint? other)
		{
			if (other == null)
			{
				return false;
			}
			MapPoint firstCommonDescendant = GetFirstCommonDescendant(other);
			if (firstCommonDescendant == null)
			{
				return false;
			}
			MapPointType[] array = (from n in BFS_FindPath(firstCommonDescendant)
				where n.PointType != MapPointType.Unassigned
				select n.PointType).ToArray();
			MapPointType[] array2 = (from n in other.BFS_FindPath(firstCommonDescendant)
				where n.PointType != MapPointType.Unassigned
				select n.PointType).ToArray();
			if (array.Length != array2.Length)
			{
				return false;
			}
			for (int num = 0; num < array.Length; num++)
			{
				if (array[num] != array2[num])
				{
					return false;
				}
			}
			return true;
		}

		public void AddQuest(AbstractModel model)
		{
			_quests.Add(model);
			NodeMarkedChanged?.Invoke();
		}

		public void RemoveQuest(AbstractModel model)
		{
			_quests.Remove(model);
			NodeMarkedChanged?.Invoke();
		}
	}
	public enum MapPointState
	{
		None,
		Travelable,
		Traveled,
		Untravelable
	}
	/// <summary>
	/// Represents a type of point that can appear on the map. This is subtly different from RoomType.
	/// Please see <see cref="T:MegaCrit.Sts2.Core.Rooms.RoomType" /> for more details.
	/// </summary>
	public enum MapPointType
	{
		Unassigned,
		Unknown,
		Shop,
		Treasure,
		RestSite,
		Monster,
		Elite,
		Boss,
		Ancient
	}
	public class MapPointTypeCounts
	{
		public HashSet<MapPointType> PointTypesThatIgnoreRules { get; init; } = new HashSet<MapPointType>();

		public int NumOfElites { get; init; } = (int)Math.Round(5f * (AscensionHelper.HasAscension(AscensionLevel.SwarmingElites) ? 1.6f : 1f));

		public int NumOfShops { get; } = 3;

		public int NumOfUnknowns { get; }

		public int NumOfRests { get; }

		/// <summary>
		/// Whether the map generation MapPointType assignment ignores the rules or follows the rules.
		/// </summary>
		public bool ShouldIgnoreMapPointRulesForMapPointType(MapPointType pointType)
		{
			return PointTypesThatIgnoreRules.Contains(pointType);
		}

		public static int StandardRandomUnknownCount(Rng rng)
		{
			return rng.NextGaussianInt(12, 1, 10, 14);
		}

		public MapPointTypeCounts(int unknownCount, int restCount)
		{
			NumOfUnknowns = unknownCount;
			NumOfRests = restCount;
		}

		public MapPointTypeCounts(ActMap existingMap)
		{
			MapPoint[] source = existingMap.GetAllMapPoints().ToArray();
			NumOfUnknowns = source.Count((MapPoint p) => p.PointType == MapPointType.Unknown);
			NumOfRests = source.Count((MapPoint p) => p.PointType == MapPointType.RestSite);
		}
	}
	/// <summary>
	/// These helper methods make the map more clean looking and less cluttered together which should help with some of the
	/// complaints. Some might look like there's a lot of looping, but I profiled them and all these public static methods
	/// run together take 0 ms on my computer.
	/// </summary>
	public static class MapPostProcessing
	{
		/// <summary>
		/// Creates a copy of the given grid that is “centered” by shifting
		/// all the nodes left or right if two of the leftmost or rightmost columns are empty.
		/// The MapPoint objects are not modified; they are simply placed into different cells.
		/// </summary>
		/// <param name="grid">The original grid to be centered.</param>
		/// <returns>A grid (modified in place) with nodes moved to center the map.</returns>
		public static MapPoint?[,] CenterGrid(MapPoint?[,] grid)
		{
			int length = grid.GetLength(0);
			int length2 = grid.GetLength(1);
			bool flag = IsColumnEmpty(grid, 0) && IsColumnEmpty(grid, 1);
			bool flag2 = IsColumnEmpty(grid, length - 1) && IsColumnEmpty(grid, length - 2);
			int num = 0;
			if (flag && !flag2)
			{
				num = -1;
			}
			else if (!flag & flag2)
			{
				num = 1;
			}
			if (num == 0)
			{
				return grid;
			}
			if (num > 0)
			{
				for (int i = 0; i < length2; i++)
				{
					for (int num2 = length - 1; num2 >= 0; num2--)
					{
						MapPoint mapPoint = grid[num2, i];
						grid[num2, i] = null;
						int num3 = num2 + num;
						if (num3 < length)
						{
							grid[num3, i] = mapPoint;
							if (mapPoint != null)
							{
								mapPoint.coord.col = num3;
							}
						}
					}
				}
			}
			else
			{
				for (int j = 0; j < length2; j++)
				{
					for (int k = 0; k < length; k++)
					{
						MapPoint mapPoint2 = grid[k, j];
						grid[k, j] = null;
						int num4 = k + num;
						if (num4 >= 0)
						{
							grid[num4, j] = mapPoint2;
							if (mapPoint2 != null)
							{
								mapPoint2.coord.col = num4;
							}
						}
					}
				}
			}
			return grid;
		}

		/// <summary>
		/// This method straightens out the path if there's a single line
		/// </summary>
		public static MapPoint?[,] StraightenPaths(MapPoint?[,] grid)
		{
			int length = grid.GetLength(0);
			int length2 = grid.GetLength(1);
			for (int i = 0; i < length2; i++)
			{
				for (int j = 0; j < length; j++)
				{
					MapPoint mapPoint = grid[j, i];
					if (mapPoint == null || mapPoint.parents.Count != 1 || mapPoint.Children.Count != 1)
					{
						continue;
					}
					MapPoint mapPoint2 = mapPoint.parents.First();
					MapPoint mapPoint3 = mapPoint.Children.First();
					bool flag = mapPoint.coord.col < mapPoint3.coord.col && mapPoint.coord.col < mapPoint2.coord.col;
					bool flag2 = mapPoint.coord.col > mapPoint3.coord.col && mapPoint.coord.col > mapPoint2.coord.col;
					if (flag && j < length - 1)
					{
						int num = j + 1;
						if (grid[num, i] != null)
						{
							continue;
						}
						mapPoint.coord.col = num;
						grid[j, i] = null;
						grid[num, i] = mapPoint;
					}
					if (flag2 && j > 0)
					{
						int num2 = j - 1;
						if (grid[num2, i] == null)
						{
							mapPoint.coord.col = num2;
							grid[j, i] = null;
							grid[num2, i] = mapPoint;
						}
					}
				}
			}
			return grid;
		}

		/// <summary>
		/// Returns true if every cell in the given column is null.
		/// </summary>
		/// <param name="grid">The grid to check.</param>
		/// <param name="col">The column index.</param>
		/// <returns>True if the column is empty; otherwise, false.</returns>
		private static bool IsColumnEmpty(MapPoint?[,] grid, int col)
		{
			int length = grid.GetLength(1);
			for (int i = 0; i < length; i++)
			{
				if (grid[col, i] != null)
				{
					return false;
				}
			}
			return true;
		}

		/// <summary>
		/// Returns a set of column indices allowed for a neighbor at the specified column.
		/// Allowed positions are the same column, one column to the left, and one column to the right.
		/// </summary>
		/// <param name="column">The reference column.</param>
		/// <param name="totalColumns">Total number of columns in the grid.</param>
		/// <returns>A set of allowed column indices.</returns>
		private static HashSet<int> GetNeighborAllowedPositions(int column, int totalColumns)
		{
			HashSet<int> hashSet = new HashSet<int>(3);
			for (int i = -1; i <= 1; i++)
			{
				int num = column + i;
				if (num >= 0 && num < totalColumns)
				{
					hashSet.Add(num);
				}
			}
			return hashSet;
		}

		/// <summary>
		/// Computes the set of allowed column indices for a given node based on its parents' and children’s positions.
		/// For each parent or child, the node must be in the same column or one column to the left or right.
		/// The final allowed set is the intersection of these constraints.
		/// </summary>
		/// <param name="node">The MapPoint to evaluate.</param>
		/// <param name="totalColumns">Total number of columns in the grid.</param>
		/// <returns>A set of allowed column indices.</returns>
		private static HashSet<int> GetAllowedPositions(MapPoint node, int totalColumns)
		{
			HashSet<int> hashSet = new HashSet<int>(Enumerable.Range(0, totalColumns));
			foreach (MapPoint parent in node.parents)
			{
				hashSet.IntersectWith(GetNeighborAllowedPositions(parent.coord.col, totalColumns));
			}
			foreach (MapPoint child in node.Children)
			{
				hashSet.IntersectWith(GetNeighborAllowedPositions(child.coord.col, totalColumns));
			}
			return hashSet;
		}

		/// <summary>
		/// Spreads adjacent MapPoints in the grid by moving nodes to positions that maximize the gap between neighbors,
		/// subject to connectivity constraints.
		/// </summary>
		/// <param name="grid">The grid containing MapPoints.</param>
		/// <returns>The transformed grid.</returns>
		public static MapPoint?[,] SpreadAdjacentMapPoints(MapPoint?[,] grid)
		{
			int length = grid.GetLength(0);
			int length2 = grid.GetLength(1);
			for (int i = 0; i < length2; i++)
			{
				List<MapPoint> list = new List<MapPoint>(length2);
				for (int j = 0; j < length; j++)
				{
					MapPoint mapPoint = grid[j, i];
					if (mapPoint != null)
					{
						list.Add(mapPoint);
					}
				}
				bool flag;
				do
				{
					flag = false;
					foreach (MapPoint item in list)
					{
						int col = item.coord.col;
						HashSet<int> allowedPositions = GetAllowedPositions(item, length);
						int num = ComputeGap(col, list, item);
						int num2 = col;
						int num3 = num;
						foreach (int item2 in allowedPositions)
						{
							if (item2 != col && (grid[item2, i] == null || grid[item2, i] == item))
							{
								int num4 = ComputeGap(item2, list, item);
								if (num4 > num3)
								{
									num2 = item2;
									num3 = num4;
								}
							}
						}
						if (num2 != col)
						{
							grid[col, i] = null;
							grid[num2, i] = item;
							item.coord.col = num2;
							flag = true;
						}
					}
				}
				while (flag);
			}
			return grid;
		}

		/// <summary>
		/// Computes the minimal horizontal gap from a candidate column to any other node in the same row.
		/// If there are no other nodes in the row, returns int.MaxValue.
		/// </summary>
		/// <param name="candidateCol">The candidate column for the node.</param>
		/// <param name="rowNodes">All nodes in the row.</param>
		/// <param name="currentNode">The node being moved.</param>
		/// <returns>The minimum column distance to any other node.</returns>
		private static int ComputeGap(int candidateCol, List<MapPoint> rowNodes, MapPoint currentNode)
		{
			int num = int.MaxValue;
			foreach (MapPoint rowNode in rowNodes)
			{
				if (rowNode != currentNode)
				{
					num = Math.Min(num, Math.Abs(candidateCol - rowNode.coord.col));
				}
			}
			if (num != int.MaxValue)
			{
				return num;
			}
			return int.MaxValue;
		}
	}
	public static class MapTravel
	{
		/// <summary>
		/// Get all the points on the map that are reachable from the specified point.
		/// </summary>
		/// <param name="runState">The state of the current run.</param>
		/// <param name="currentPoint">The current point that the players are at.</param>
		public static IEnumerable<MapPoint> GetTravelablePointsFrom(IRunState runState, MapPoint currentPoint)
		{
			if (Hook.ShouldAllowFreeTravel(runState))
			{
				return runState.Map.GetPointsInRow(currentPoint.coord.row + 1);
			}
			return currentPoint.Children;
		}
	}
