	/// <summary>
	/// An ActMap that is reconstructed from saved data rather than generated from RNG.
	/// This ensures map topology is preserved even if map generation code changes.
	///
	/// This single class handles all map types (Standard, Spoils, GoldenPath) because
	/// the concrete type only matters during generation. After generation, all maps
	/// are simply grids of MapPoints with connections. The serialization captures
	/// the complete topology, making the original generation algorithm irrelevant
	/// for restoration.
	/// </summary>
	public sealed class SavedActMap : ActMap
	{
		public override MapPoint BossMapPoint { get; }

		public override MapPoint StartingMapPoint { get; }

		public override MapPoint? SecondBossMapPoint { get; }

		protected override MapPoint?[,] Grid { get; }

		public SavedActMap(SerializableActMap saved)
		{
			Grid = new MapPoint[saved.GridWidth, saved.GridHeight];
			System.Collections.Generic.Dictionary<MapCoord, MapPoint> dictionary = new System.Collections.Generic.Dictionary<MapCoord, MapPoint>();
			foreach (SerializableMapPoint point in saved.Points)
			{
				MapPoint mapPoint = CreatePoint(point);
				Grid[point.Coord.col, point.Coord.row] = mapPoint;
				dictionary[point.Coord] = mapPoint;
			}
			BossMapPoint = CreatePoint(saved.BossPoint);
			dictionary[saved.BossPoint.Coord] = BossMapPoint;
			StartingMapPoint = CreatePoint(saved.StartingPoint);
			dictionary[saved.StartingPoint.Coord] = StartingMapPoint;
			if (saved.SecondBossPoint != null)
			{
				SecondBossMapPoint = CreatePoint(saved.SecondBossPoint);
				dictionary[saved.SecondBossPoint.Coord] = SecondBossMapPoint;
			}
			WireChildren(saved.Points, dictionary);
			WireChildren(saved.BossPoint, dictionary);
			WireChildren(saved.StartingPoint, dictionary);
			if (saved.SecondBossPoint != null)
			{
				WireChildren(saved.SecondBossPoint, dictionary);
			}
			if (saved.StartMapPointCoords == null)
			{
				return;
			}
			foreach (MapCoord startMapPointCoord in saved.StartMapPointCoords)
			{
				if (dictionary.TryGetValue(startMapPointCoord, out var value))
				{
					startMapPoints.Add(value);
				}
			}
		}

		private static MapPoint CreatePoint(SerializableMapPoint saved)
		{
			return new MapPoint(saved.Coord.col, saved.Coord.row)
			{
				PointType = saved.PointType,
				CanBeModified = saved.CanBeModified
			};
		}

		private static void WireChildren(IEnumerable<SerializableMapPoint> points, System.Collections.Generic.Dictionary<MapCoord, MapPoint> lookup)
		{
			foreach (SerializableMapPoint point in points)
			{
				WireChildren(point, lookup);
			}
		}

		private static void WireChildren(SerializableMapPoint savedPoint, System.Collections.Generic.Dictionary<MapCoord, MapPoint> lookup)
		{
			if (savedPoint.ChildCoords == null)
			{
				return;
			}
			MapPoint mapPoint = lookup[savedPoint.Coord];
			foreach (MapCoord childCoord in savedPoint.ChildCoords)
			{
				if (lookup.TryGetValue(childCoord, out MapPoint value))
				{
					mapPoint.AddChildPoint(value);
				}
			}
		}
	}
	/// <summary>
	/// An hourglass-shaped map where all paths converge through a single centered treasure node.
	/// Used when SpoilsMap card is active in Act 2.
	///
	/// This map is generated from scratch rather than post-processing StandardActMap.
	/// The hourglass structure requires fundamentally different path topology. All paths must converge
	/// through a single centered treasure node, with rows narrowing towards the treasure then widening after.
	/// Post-processing would require deleting most nodes and rewiring all edges, which is roughly as complex
	/// as generating from scratch.
	///
	/// Keeping these implementations separate makes both easier to understand. StandardActMap stays clean,
	/// and the hourglass-specific constraints live here explicitly instead of being tangled up in post-processing logic.
	/// Each can evolve independently.
	///
	/// The tradeoff is this duplicates some map generation logic (~400 lines). If StandardActMap's core rules change
	/// (adjacency constraints, parent/child limits, point type placement), we'll need to manually sync those changes here.
	/// Tests in SpoilsActMapTest verify the core map invariants hold.
	/// </summary>
	public sealed class SpoilsActMap : ActMap
	{
		private const int _mapWidth = 7;

		private const int _pathCount = 7;

		private readonly int _mapLength;

		private readonly Rng _rng;

		private readonly int _treasureRow;

		private readonly MapPointTypeCounts _pointTypeCounts;

		private static readonly HashSet<MapPointType> _lowerMapPointRestrictions = new HashSet<MapPointType>
		{
			MapPointType.RestSite,
			MapPointType.Elite
		};

		private static readonly HashSet<MapPointType> _upperMapPointRestrictions = new HashSet<MapPointType> { MapPointType.RestSite };

		private static readonly HashSet<MapPointType> _parentMapPointRestrictions = new HashSet<MapPointType>
		{
			MapPointType.Elite,
			MapPointType.RestSite,
			MapPointType.Treasure,
			MapPointType.Shop
		};

		private static readonly HashSet<MapPointType> _childMapPointRestrictions = new HashSet<MapPointType>
		{
			MapPointType.Elite,
			MapPointType.RestSite,
			MapPointType.Treasure,
			MapPointType.Shop
		};

		private static readonly HashSet<MapPointType> _siblingPointTypeRestrictions = new HashSet<MapPointType>
		{
			MapPointType.RestSite,
			MapPointType.Monster,
			MapPointType.Unknown,
			MapPointType.Elite,
			MapPointType.Shop
		};

		public override MapPoint BossMapPoint { get; }

		public override MapPoint StartingMapPoint { get; }

		protected override MapPoint?[,] Grid { get; }

		/// <summary>
		/// Creates a map used only when the player has the <see cref="T:MegaCrit.Sts2.Core.Models.Cards.SpoilsMap" />.
		/// </summary>
		/// <param name="runState">The run state for this run.</param>
		/// <param name="mapPointTypeCountsOverride">If passed, replaces the default point counts used to generate the map.</param>
		public SpoilsActMap(IRunState runState, MapPointTypeCounts? mapPointTypeCountsOverride = null)
		{
			ActModel act = runState.Act;
			bool isMultiplayer = runState.Players.Count > 1;
			_mapLength = act.GetNumberOfRooms(isMultiplayer) + 1;
			_rng = new Rng(runState.Rng.Seed, "spoils_map");
			_pointTypeCounts = mapPointTypeCountsOverride ?? act.GetMapPointTypes(_rng);
			Grid = new MapPoint[7, _mapLength];
			_treasureRow = GetRowCount() - 7;
			BossMapPoint = new MapPoint(GetColumnCount() / 2, GetRowCount());
			StartingMapPoint = new MapPoint(GetColumnCount() / 2, 0);
			GenerateHourglassMap();
			AssignPointTypes();
			MapPathPruning.PruneAndRepair(Grid, startMapPoints, this, _pointTypeCounts, _rng, IsValidPointType);
		}

		private MapPoint GetOrCreatePoint(int col, int row)
		{
			if (col >= 0 && col < GetColumnCount() && row >= 0 && row < GetRowCount())
			{
				MapPoint mapPoint = Grid[col, row];
				if (mapPoint != null)
				{
					return mapPoint;
				}
			}
			MapPoint mapPoint2 = new MapPoint(col, row);
			Grid[col, row] = mapPoint2;
			return mapPoint2;
		}

		private void GenerateHourglassMap()
		{
			int col = GetColumnCount() / 2;
			if (_treasureRow <= 0 || _treasureRow >= GetRowCount())
			{
				throw new InvalidOperationException("Treasure row is out of bounds for SpoilsActMap");
			}
			for (int i = 0; i < 7; i++)
			{
				MapPoint orCreatePoint = GetOrCreatePoint(_rng.NextInt(0, 7), 1);
				if (i == 1)
				{
					while (startMapPoints.Contains(orCreatePoint))
					{
						orCreatePoint = GetOrCreatePoint(_rng.NextInt(0, 7), 1);
					}
				}
				startMapPoints.Add(orCreatePoint);
				PathGenerate(orCreatePoint);
			}
			MapPoint orCreatePoint2 = GetOrCreatePoint(col, _treasureRow);
			orCreatePoint2.PointType = MapPointType.Treasure;
			orCreatePoint2.CanBeModified = false;
			foreach (MapPoint item in GetPointsInRow(_treasureRow).ToList())
			{
				if (item != orCreatePoint2)
				{
					RedirectToTreasure(item, orCreatePoint2);
				}
			}
			ConnectRowToBoss();
			ConnectRowToStart();
		}

		private void PathGenerate(MapPoint startingPoint)
		{
			MapPoint mapPoint = startingPoint;
			while (mapPoint.coord.row < _mapLength - 1)
			{
				MapCoord mapCoord = GenerateNextCoord(mapPoint);
				MapPoint orCreatePoint = GetOrCreatePoint(mapCoord.col, mapCoord.row);
				mapPoint.AddChildPoint(orCreatePoint);
				mapPoint = orCreatePoint;
			}
		}

		private MapCoord GenerateNextCoord(MapPoint current)
		{
			int row = current.coord.row + 1;
			(int minCol, int maxCol) allowedColumnsForRow = GetAllowedColumnsForRow(row);
			int item = allowedColumnsForRow.minCol;
			int item2 = allowedColumnsForRow.maxCol;
			int num = GetColumnCount() / 2;
			List<int> list = new List<int> { -1, 0, 1 };
			int num2 = _treasureRow - current.coord.row;
			if (num2 > 3)
			{
				list.StableShuffle(_rng);
			}
			else if (num2 > 0)
			{
				list = BuildCenteredPriorityList(current.coord.col, num);
			}
			else
			{
				list.StableShuffle(_rng);
			}
			foreach (int item3 in list)
			{
				int nextColumn = GetNextColumn(current.coord.col, item3);
				if (nextColumn < item || nextColumn > item2 || HasInvalidCrossover(current, nextColumn))
				{
					continue;
				}
				MapPoint point = GetPoint(nextColumn, row);
				if ((point == null || point.parents.Contains(current) || point.parents.Count < 3) && (current == StartingMapPoint || current.Children.Count < 3 || (point != null && current.Children.Contains(point))))
				{
					if (Math.Abs(nextColumn - current.coord.col) > 1)
					{
						throw new InvalidOperationException($"Invalid step from ({current.coord.col}, {current.coord.row}) to column {nextColumn}");
					}
					return new MapCoord
					{
						col = nextColumn,
						row = row
					};
				}
			}
			int num3 = Math.Clamp(num, item, item2);
			if (Math.Abs(num3 - current.coord.col) > 1)
			{
				num3 = Math.Clamp(current.coord.col + Math.Sign(num3 - current.coord.col), item, item2);
			}
			if (HasInvalidCrossover(current, num3))
			{
				int num4 = Math.Clamp(current.coord.col, item, item2);
				num3 = num4;
			}
			if (Math.Abs(num3 - current.coord.col) > 1)
			{
				throw new InvalidOperationException($"Fallback step from ({current.coord.col}, {current.coord.row}) to column {num3} exceeds adjacency");
			}
			return new MapCoord
			{
				col = num3,
				row = row
			};
		}

		private List<int> BuildCenteredPriorityList(int currentCol, int centerCol)
		{
			List<int> list = new List<int>();
			int num = Math.Sign(centerCol - currentCol);
			if (num != 0)
			{
				list.Add(num);
			}
			list.Add(0);
			int item = -num;
			if (num != 0)
			{
				list.Add(item);
			}
			if (!list.Contains(-1))
			{
				list.Add(-1);
			}
			if (!list.Contains(1))
			{
				list.Add(1);
			}
			return list;
		}

		private int GetNextColumn(int currentCol, int direction)
		{
			return direction switch
			{
				-1 => Math.Max(0, currentCol - 1), 
				0 => currentCol, 
				1 => Math.Min(6, currentCol + 1), 
				_ => currentCol, 
			};
		}

		private (int minCol, int maxCol) GetAllowedColumnsForRow(int row)
		{
			int num = GetColumnCount() / 2;
			int val = Math.Abs(row - _treasureRow);
			int val2 = _mapLength - 1 - row;
			int val3 = Math.Min(num, Math.Max(0, val2) + 1);
			int num2 = Math.Min(num, Math.Min(val, val3));
			int item = Math.Max(0, num - num2);
			int item2 = Math.Min(6, num + num2);
			return (minCol: item, maxCol: item2);
		}

		private bool HasInvalidCrossover(MapPoint current, int targetCol)
		{
			int num = targetCol - current.coord.col;
			if (num == 0)
			{
				return false;
			}
			MapPoint point = GetPoint(targetCol, current.coord.row);
			if (point == null)
			{
				return false;
			}
			foreach (MapPoint child in point.Children)
			{
				int num2 = child.coord.col - point.coord.col;
				if (num2 == -num)
				{
					return true;
				}
			}
			return false;
		}

		private void RedirectToTreasure(MapPoint strayNode, MapPoint treasure)
		{
			foreach (MapPoint item in strayNode.parents.ToList())
			{
				item.RemoveChildPoint(strayNode);
				item.AddChildPoint(treasure);
			}
			foreach (MapPoint item2 in strayNode.Children.ToList())
			{
				strayNode.RemoveChildPoint(item2);
				treasure.AddChildPoint(item2);
			}
			Grid[strayNode.coord.col, strayNode.coord.row] = null;
		}

		private void ConnectRowToBoss()
		{
			int num = GetRowCount() - 1;
			for (int i = 0; i < GetColumnCount(); i++)
			{
				MapPoint mapPoint = Grid[i, num];
				if (mapPoint != null && !mapPoint.Children.Contains(BossMapPoint))
				{
					mapPoint.AddChildPoint(BossMapPoint);
				}
			}
		}

		private void ConnectRowToStart()
		{
			for (int i = 0; i < GetColumnCount(); i++)
			{
				MapPoint mapPoint = Grid[i, 1];
				if (mapPoint != null && !StartingMapPoint.Children.Contains(mapPoint))
				{
					StartingMapPoint.AddChildPoint(mapPoint);
				}
			}
		}

		private void AssignPointTypes()
		{
			ForEachInRow(GetRowCount() - 1, delegate(MapPoint p)
			{
				p.PointType = MapPointType.RestSite;
				p.CanBeModified = false;
			});
			ForEachInRow(1, delegate(MapPoint p)
			{
				p.PointType = MapPointType.Monster;
				p.CanBeModified = false;
			});
			List<MapPointType> list = new List<MapPointType>();
			for (int num = 0; num < _pointTypeCounts.NumOfRests; num++)
			{
				list.Add(MapPointType.RestSite);
			}
			for (int num2 = 0; num2 < _pointTypeCounts.NumOfShops; num2++)
			{
				list.Add(MapPointType.Shop);
			}
			for (int num3 = 0; num3 < _pointTypeCounts.NumOfElites; num3++)
			{
				list.Add(MapPointType.Elite);
			}
			for (int num4 = 0; num4 < _pointTypeCounts.NumOfUnknowns; num4++)
			{
				list.Add(MapPointType.Unknown);
			}
			Queue<MapPointType> pointTypesToBeAssigned = new Queue<MapPointType>(list);
			AssignRemainingTypesToRandomPoints(pointTypesToBeAssigned);
			foreach (MapPoint item in from p in GetAllMapPoints()
				where p.PointType == MapPointType.Unassigned
				select p)
			{
				item.PointType = MapPointType.Monster;
			}
			BossMapPoint.PointType = MapPointType.Boss;
			StartingMapPoint.PointType = MapPointType.Ancient;
		}

		private void ForEachInRow(int rowIndex, Action<MapPoint> processor)
		{
			for (int i = 0; i < GetColumnCount(); i++)
			{
				MapPoint mapPoint = Grid[i, rowIndex];
				if (mapPoint != null)
				{
					processor(mapPoint);
				}
			}
		}

		private void AssignRemainingTypesToRandomPoints(Queue<MapPointType> pointTypesToBeAssigned)
		{
			for (int i = 0; i < 3; i++)
			{
				if (pointTypesToBeAssigned.Count <= 0)
				{
					break;
				}
				List<MapPoint> list = (from p in GetAllMapPoints()
					where p != BossMapPoint && p != StartingMapPoint
					where p.PointType == MapPointType.Unassigned
					select p).ToList();
				list.StableShuffle(_rng);
				foreach (MapPoint item in list)
				{
					if (pointTypesToBeAssigned.Count == 0)
					{
						break;
					}
					MapPointType nextValidPointType = GetNextValidPointType(pointTypesToBeAssigned, item);
					if (nextValidPointType != MapPointType.Unassigned)
					{
						item.PointType = nextValidPointType;
					}
				}
			}
		}

		private MapPointType GetNextValidPointType(Queue<MapPointType> pointTypesQueue, MapPoint mapPoint)
		{
			if (pointTypesQueue.Count == 0)
			{
				return MapPointType.Unassigned;
			}
			int count = pointTypesQueue.Count;
			for (int i = 0; i < count; i++)
			{
				MapPointType mapPointType = pointTypesQueue.Dequeue();
				if (_pointTypeCounts.ShouldIgnoreMapPointRulesForMapPointType(mapPointType) || IsValidPointType(mapPointType, mapPoint))
				{
					return mapPointType;
				}
				pointTypesQueue.Enqueue(mapPointType);
			}
			return MapPointType.Unassigned;
		}

		private bool IsValidPointType(MapPointType pointType, MapPoint mapPoint)
		{
			if (!IsValidForUpper(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidForLower(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidWithParents(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidWithChildren(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidWithSiblings(pointType, mapPoint))
			{
				return false;
			}
			return true;
		}

		private static bool IsValidForLower(MapPointType pointType, MapPoint mapPoint)
		{
			if (mapPoint.coord.row < 6)
			{
				return !_lowerMapPointRestrictions.Contains(pointType);
			}
			return true;
		}

		private bool IsValidForUpper(MapPointType pointType, MapPoint mapPoint)
		{
			if (mapPoint.coord.row >= _mapLength - 3)
			{
				return !_upperMapPointRestrictions.Contains(pointType);
			}
			return true;
		}

		private static bool IsValidWithParents(MapPointType pointType, MapPoint mapPoint)
		{
			if (_parentMapPointRestrictions.Contains(pointType))
			{
				return !mapPoint.parents.Concat(mapPoint.Children).Any((MapPoint p) => pointType == p.PointType);
			}
			return true;
		}

		private static bool IsValidWithChildren(MapPointType pointType, MapPoint mapPoint)
		{
			if (_childMapPointRestrictions.Contains(pointType))
			{
				return !mapPoint.Children.Any((MapPoint p) => pointType == p.PointType);
			}
			return true;
		}

		private static bool IsValidWithSiblings(MapPointType pointType, MapPoint mapPoint)
		{
			if (_siblingPointTypeRestrictions.Contains(pointType))
			{
				return !GetSiblings(mapPoint).Any((MapPoint p) => pointType == p.PointType);
			}
			return true;
		}

		private static IEnumerable<MapPoint> GetSiblings(MapPoint mapPoint)
		{
			return from x in mapPoint.parents.SelectMany((MapPoint x) => x.Children)
				where !object.Equals(x, mapPoint)
				select x;
		}
	}
	public sealed class StandardActMap : ActMap
	{
		public const int maxElites = 15;

		private const int _iterations = 7;

		private const int _mapWidth = 7;

		private readonly MapPointTypeCounts _pointTypeCounts;

		private readonly int _mapLength;

		private readonly Rng _rng;

		private static readonly HashSet<MapPointType> _lowerMapPointRestrictions = new HashSet<MapPointType>
		{
			MapPointType.RestSite,
			MapPointType.Elite
		};

		private static readonly HashSet<MapPointType> _upperMapPointRestrictions = new HashSet<MapPointType> { MapPointType.RestSite };

		/// These cannot be 2 times in a row.
		private static readonly HashSet<MapPointType> _parentMapPointRestrictions = new HashSet<MapPointType>
		{
			MapPointType.Elite,
			MapPointType.RestSite,
			MapPointType.Treasure,
			MapPointType.Shop
		};

		/// These cannot be 2 times in a row.
		private static readonly HashSet<MapPointType> _childMapPointRestrictions = new HashSet<MapPointType>
		{
			MapPointType.Elite,
			MapPointType.RestSite,
			MapPointType.Treasure,
			MapPointType.Shop
		};

		/// Only these point types are allowed to be siblings
		private static readonly HashSet<MapPointType> _siblingPointTypeRestrictions = new HashSet<MapPointType>
		{
			MapPointType.RestSite,
			MapPointType.Monster,
			MapPointType.Unknown,
			MapPointType.Elite,
			MapPointType.Shop
		};

		public override MapPoint BossMapPoint { get; }

		public override MapPoint StartingMapPoint { get; }

		public override MapPoint? SecondBossMapPoint { get; }

		/// <summary>
		/// Flags this map to generate elite nodes where the treasure nodes would be in the middle of the act map.
		/// Is set in the constructor, typically for the Warden Ascension (replace act 3 chests with elites)
		/// </summary>
		public bool ShouldReplaceTreasureWithElites { get; }

		protected override MapPoint?[,] Grid { get; }

		/// <summary>
		/// Creates a standard map used for most acts.
		/// </summary>
		/// <param name="mapRng">The rng for the map.</param>
		/// <param name="actModel">The act to generate the map for </param>
		/// <param name="isMultiplayer">In multiplayer, we remove one node from each map.</param>
		/// <param name="shouldReplaceTreasureWithElites">Replaces the treasure row with elites. This is for the Warden ascension.</param>
		/// <param name="hasSecondBoss">Whether this act has a second boss (Double Boss ascension mode)</param>
		/// <param name="mapPointTypeCountsOverride">Overrides the map point type counts from the map passed in</param>
		/// <param name="enablePruning">Used for tests, should always be true if used for gameplay logic</param>
		public StandardActMap(Rng mapRng, ActModel actModel, bool isMultiplayer, bool shouldReplaceTreasureWithElites, bool hasSecondBoss = false, MapPointTypeCounts? mapPointTypeCountsOverride = null, bool enablePruning = true)
		{
			_mapLength = actModel.GetNumberOfRooms(isMultiplayer) + 1;
			ShouldReplaceTreasureWithElites = shouldReplaceTreasureWithElites;
			Grid = new MapPoint[7, _mapLength];
			_rng = mapRng;
			_pointTypeCounts = mapPointTypeCountsOverride ?? actModel.GetMapPointTypes(mapRng);
			BossMapPoint = new MapPoint(GetColumnCount() / 2, GetRowCount());
			StartingMapPoint = new MapPoint(GetColumnCount() / 2, 0);
			if (hasSecondBoss)
			{
				SecondBossMapPoint = new MapPoint(GetColumnCount() / 2, GetRowCount() + 1);
			}
			GenerateMap();
			AssignPointTypes();
			if (enablePruning)
			{
				MapPathPruning.PruneAndRepair(Grid, startMapPoints, this, _pointTypeCounts, _rng, IsValidPointType);
			}
			Grid = MapPostProcessing.CenterGrid(Grid);
			Grid = MapPostProcessing.SpreadAdjacentMapPoints(Grid);
			Grid = MapPostProcessing.StraightenPaths(Grid);
		}

		public static StandardActMap CreateFor(RunState runState, bool replaceTreasureWithElites)
		{
			return new StandardActMap(new Rng(runState.Rng.Seed, $"act_{runState.CurrentActIndex + 1}_map"), runState.Act, runState.Players.Count > 1, replaceTreasureWithElites, runState.Act.HasSecondBoss);
		}

		private MapPoint GetOrCreateMapPoint(MapCoord coord)
		{
			return GetOrCreatePoint(coord.col, coord.row);
		}

		private MapPoint GetOrCreatePoint(int col, int row)
		{
			MapPoint point = GetPoint(col, row);
			if (point != null)
			{
				return point;
			}
			point = new MapPoint(col, row);
			Grid[col, row] = point;
			return point;
		}

		private void PathGenerate(MapPoint startingPoint)
		{
			MapPoint mapPoint = startingPoint;
			while (mapPoint.coord.row < _mapLength - 1)
			{
				MapCoord coord = GenerateNextCoord(mapPoint);
				MapPoint orCreateMapPoint = GetOrCreateMapPoint(coord);
				mapPoint.AddChildPoint(orCreateMapPoint);
				mapPoint = orCreateMapPoint;
			}
		}

		private MapCoord GenerateNextCoord(MapPoint current)
		{
			int col = current.coord.col;
			int num = Mathf.Max(0, col - 1);
			int num2 = Mathf.Min(col + 1, 6);
			int num3 = 3;
			List<int> list = new List<int>(num3);
			CollectionsMarshal.SetCount(list, num3);
			Span<int> span = CollectionsMarshal.AsSpan(list);
			int num4 = 0;
			span[num4] = -1;
			num4++;
			span[num4] = 0;
			num4++;
			span[num4] = 1;
			List<int> list2 = list;
			list2.StableShuffle(_rng);
			foreach (int item in list2)
			{
				int row = current.coord.row + 1;
				int num5 = item switch
				{
					-1 => num, 
					0 => col, 
					1 => num2, 
					_ => throw new InvalidOperationException("This isn't possible"), 
				};
				if (!HasInvalidCrossover(current, num5))
				{
					return new MapCoord
					{
						col = num5,
						row = row
					};
				}
			}
			throw new InvalidOperationException("Cannot find next node");
		}

		private bool HasInvalidCrossover(MapPoint current, int targetX)
		{
			int num = targetX - current.coord.col;
			if ((num == 0 || num == 7) ? true : false)
			{
				return false;
			}
			MapPoint mapPoint = Grid[targetX, current.coord.row];
			if (mapPoint == null)
			{
				return false;
			}
			foreach (MapPoint child in mapPoint.Children)
			{
				int num2 = child.coord.col - mapPoint.coord.col;
				if (num2 == -num)
				{
					return true;
				}
			}
			return false;
		}

		private void GenerateMap()
		{
			for (int i = 0; i < 7; i++)
			{
				MapPoint orCreatePoint = GetOrCreatePoint(_rng.NextInt(0, 7), 1);
				if (i == 1)
				{
					while (startMapPoints.Contains(orCreatePoint))
					{
						orCreatePoint = GetOrCreatePoint(_rng.NextInt(0, 7), 1);
					}
				}
				startMapPoints.Add(orCreatePoint);
				PathGenerate(orCreatePoint);
			}
			ForEachInRow(Grid, GetRowCount() - 1, delegate(MapPoint x)
			{
				x.AddChildPoint(BossMapPoint);
			});
			if (SecondBossMapPoint != null)
			{
				BossMapPoint.AddChildPoint(SecondBossMapPoint);
			}
			ForEachInRow(Grid, 1, delegate(MapPoint x)
			{
				StartingMapPoint.AddChildPoint(x);
			});
		}

		private static void ForEachInRow(MapPoint?[,] grid, int rowIndex, Action<MapPoint> processor, bool canBeModified = false)
		{
			for (int i = 0; i < grid.GetLength(0); i++)
			{
				MapPoint mapPoint = grid[i, rowIndex];
				if (mapPoint != null)
				{
					processor(mapPoint);
				}
			}
		}

		private void AssignPointTypes()
		{
			ForEachInRow(Grid, GetRowCount() - 1, delegate(MapPoint p)
			{
				p.PointType = MapPointType.RestSite;
				p.CanBeModified = false;
			});
			if (ShouldReplaceTreasureWithElites)
			{
				ForEachInRow(Grid, GetRowCount() - 7, delegate(MapPoint p)
				{
					p.PointType = MapPointType.Elite;
					p.CanBeModified = false;
				});
			}
			else
			{
				ForEachInRow(Grid, GetRowCount() - 7, delegate(MapPoint p)
				{
					p.PointType = MapPointType.Treasure;
					p.CanBeModified = false;
				});
			}
			ForEachInRow(Grid, 1, delegate(MapPoint p)
			{
				p.PointType = MapPointType.Monster;
				p.CanBeModified = false;
			});
			List<MapPointType> list = new List<MapPointType>();
			for (int num = 0; num < _pointTypeCounts.NumOfRests; num++)
			{
				list.Add(MapPointType.RestSite);
			}
			for (int num2 = 0; num2 < _pointTypeCounts.NumOfShops; num2++)
			{
				list.Add(MapPointType.Shop);
			}
			for (int num3 = 0; num3 < _pointTypeCounts.NumOfElites; num3++)
			{
				list.Add(MapPointType.Elite);
			}
			for (int num4 = 0; num4 < _pointTypeCounts.NumOfUnknowns; num4++)
			{
				list.Add(MapPointType.Unknown);
			}
			Queue<MapPointType> pointTypesToBeAssigned = new Queue<MapPointType>(list);
			AssignRemainingTypesToRandomPoints(pointTypesToBeAssigned);
			foreach (MapPoint item in from x in GetAllMapPoints()
				where x.PointType == MapPointType.Unassigned
				select x)
			{
				item.PointType = MapPointType.Monster;
			}
			BossMapPoint.PointType = MapPointType.Boss;
			StartingMapPoint.PointType = MapPointType.Ancient;
			if (SecondBossMapPoint != null)
			{
				SecondBossMapPoint.PointType = MapPointType.Boss;
			}
		}

		private void EnsureRowsContainsPointType(MapPointType pointType, List<List<MapPoint>> rows)
		{
			if (!RowsContainPointType(pointType, rows))
			{
				Queue<MapPointType> queue = new Queue<MapPointType>();
				queue.Enqueue(pointType);
				AssignPointTypesToRandomRows(queue, rows);
			}
		}

		private static bool RowsContainPointType(MapPointType pointType, IEnumerable<List<MapPoint>> rows)
		{
			return rows.SelectMany((List<MapPoint> row) => row.Where((MapPoint p) => p.PointType == pointType)).Any();
		}

		private List<List<MapPoint>> GetRows(int firstRow, int lastRow)
		{
			List<List<MapPoint>> list = new List<List<MapPoint>>();
			for (int i = firstRow; i <= lastRow; i++)
			{
				List<MapPoint> list2 = new List<MapPoint>();
				for (int j = 0; j < 7; j++)
				{
					MapPoint mapPoint = Grid[j, i];
					if (mapPoint != null)
					{
						list2.Add(mapPoint);
					}
				}
				list.Add(list2);
			}
			return list;
		}

		/// <summary>
		/// Assigns point types to the map by row to ensure that the point types are more evenly distributed.
		/// </summary>
		/// <param name="pointTypesToBeAssigned">Point types left to be assigned.</param>
		/// <param name="rows">Rows of map points to assign the types to.</param>
		private void AssignPointTypesToRandomRows(Queue<MapPointType> pointTypesToBeAssigned, List<List<MapPoint>> rows)
		{
			rows.UnstableShuffle(_rng);
			foreach (List<MapPoint> row in rows)
			{
				row.StableShuffle(_rng);
				using IEnumerator<MapPoint> enumerator2 = row.Where((MapPoint r) => r.PointType == MapPointType.Unassigned).GetEnumerator();
				if (enumerator2.MoveNext())
				{
					MapPoint current2 = enumerator2.Current;
					MapPointType nextValidPointType = GetNextValidPointType(pointTypesToBeAssigned, current2);
					current2.PointType = nextValidPointType;
				}
			}
		}

		private void AssignRemainingTypesToRandomPoints(Queue<MapPointType> pointTypesToBeAssigned)
		{
			for (int i = 0; i < 3; i++)
			{
				if (pointTypesToBeAssigned.Count <= 0)
				{
					break;
				}
				List<MapPoint> list = (from p in GetAllMapPoints()
					where p.PointType == MapPointType.Unassigned
					select p).ToList();
				list.StableShuffle(_rng);
				foreach (MapPoint item in list)
				{
					if (pointTypesToBeAssigned.Count == 0)
					{
						break;
					}
					item.PointType = GetNextValidPointType(pointTypesToBeAssigned, item);
				}
			}
		}

		private MapPointType GetNextValidPointType(Queue<MapPointType> pointTypesQueue, MapPoint mapPoint)
		{
			for (int i = 0; i < pointTypesQueue.Count; i++)
			{
				MapPointType mapPointType = pointTypesQueue.Dequeue();
				if (_pointTypeCounts.ShouldIgnoreMapPointRulesForMapPointType(mapPointType))
				{
					return mapPointType;
				}
				if (IsValidPointType(mapPointType, mapPoint))
				{
					return mapPointType;
				}
				pointTypesQueue.Enqueue(mapPointType);
			}
			return MapPointType.Unassigned;
		}

		public bool IsValidPointType(MapPointType pointType, MapPoint mapPoint)
		{
			if (!IsValidForUpper(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidForLower(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidWithParents(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidWithChildren(pointType, mapPoint))
			{
				return false;
			}
			if (!IsValidWithSiblings(pointType, mapPoint))
			{
				return false;
			}
			return true;
		}

		/// These point types cannot be in the lower part of the map
		private static bool IsValidForLower(MapPointType pointType, MapPoint mapPoint)
		{
			if (mapPoint.coord.row < 6)
			{
				return !_lowerMapPointRestrictions.Contains(pointType);
			}
			return true;
		}

		/// These point types cannot be in the upper part of the map
		private bool IsValidForUpper(MapPointType pointType, MapPoint mapPoint)
		{
			if (mapPoint.coord.row >= _mapLength - 3)
			{
				return !_upperMapPointRestrictions.Contains(pointType);
			}
			return true;
		}

		/// These cannot be 2 times in a row.
		private static bool IsValidWithParents(MapPointType pointType, MapPoint mapPoint)
		{
			if (_parentMapPointRestrictions.Contains(pointType))
			{
				return !mapPoint.parents.Concat(mapPoint.Children).Any((MapPoint p) => pointType == p.PointType);
			}
			return true;
		}

		/// Checks if a point type is valid by ensuring it doesn't appear twice in a row among children
		private static bool IsValidWithChildren(MapPointType pointType, MapPoint mapPoint)
		{
			if (_childMapPointRestrictions.Contains(pointType))
			{
				return !mapPoint.Children.Any((MapPoint p) => pointType == p.PointType);
			}
			return true;
		}

		/// These point types cannot be siblings of each other.
		private static bool IsValidWithSiblings(MapPointType pointType, MapPoint mapPoint)
		{
			if (_siblingPointTypeRestrictions.Contains(pointType))
			{
				return !GetSiblings(mapPoint).Any((MapPoint p) => pointType == p.PointType);
			}
			return true;
		}

		private static IEnumerable<MapPoint> GetSiblings(MapPoint mapPoint)
		{
			return from x in mapPoint.parents.SelectMany((MapPoint x) => x.Children)
				where !object.Equals(x, mapPoint)
				select x;
		}
	}
}
namespace MegaCrit.Sts2.Core.Logging
{
	public class ConsoleLogPrinter : ILogPrinter
	{
		public void Print(LogLevel logLevel, string text, int skipFrames)
		{
			skipFrames++;
			string text2 = logLevel.ToString().ToUpperInvariant();
			switch (logLevel)
			{
			case LogLevel.Error:
			{
				StackTrace value = new StackTrace(skipFrames, fNeedFileInfo: true);
				GD.PrintErr($"[{text2}] {text}\n{value}");
				break;
			}
			case LogLevel.Warn:
				GD.Print("[" + text2 + "] " + text);
				break;
			default:
				GD.Print("[" + text2 + "] " + text);
				break;
			}
		}
	}
	public class EditorLogPrinter : ILogPrinter
	{
		private static string GetColorCode(LogLevel level)
		{
			return level switch
			{
				LogLevel.VeryDebug => "#B180D3", 
				LogLevel.Debug => "#B180D3", 
				LogLevel.Info => "#76FF56", 
				LogLevel.Warn => "#FFCB3D", 
				LogLevel.Error => "#FF4747", 
				LogLevel.Load => "#87CEEB", 
				_ => throw new ArgumentOutOfRangeException("level", level, null), 
			};
		}

		private static bool LogFullStack(LogLevel level)
		{
			return level switch
			{
				LogLevel.VeryDebug => false, 
				LogLevel.Debug => false, 
				LogLevel.Info => false, 
				LogLevel.Warn => false, 
				LogLevel.Error => true, 
				LogLevel.Load => false, 
				_ => throw new ArgumentOutOfRangeException("level", level, null), 
			};
		}

		public void Print(LogLevel level, string text, int skipFrames)
		{
			skipFrames++;
			string value = level.ToString().ToUpperInvariant();
			string colorCode = GetColorCode(level);
			string text2 = $"[b][color={colorCode}][{value}][/color][/b] {text}";
			string text3 = "";
			if (level != LogLevel.Warn)
			{
				if (LogFullStack(level))
				{
					StackTrace value2 = new StackTrace(skipFrames, fNeedFileInfo: true);
					text3 = $"\n{value2}";
				}
				else
				{
					StackFrame stackFrame = new StackFrame(skipFrames, needFileInfo: true);
					DiagnosticMethodInfo diagnosticMethodInfo = DiagnosticMethodInfo.Create(stackFrame);
					int fileLineNumber = stackFrame.GetFileLineNumber();
					string fileName = stackFrame.GetFileName();
					string fileName2 = Path.GetFileName(fileName);
					text3 = $" line {fileLineNumber}:{diagnosticMethodInfo?.Name}() in {fileName2}";
				}
			}
			if (level == LogLevel.Error)
			{
				string text4 = $"[{value}] {text}{text3}";
				GD.PrintErr(text4);
				GD.PushError(text4);
			}
			if (level == LogLevel.Warn)
			{
				GD.PrintRich(text2 ?? "");
			}
			else
			{
				GD.PrintRich(text2 + "[color=#606060]" + text3 + "[/color]");
			}
		}
	}
	public static class IdAnonymizer
	{
		private static readonly System.Collections.Generic.Dictionary<ulong, ulong> _idToAnonymized = new System.Collections.Generic.Dictionary<ulong, ulong>();

		public static ulong Anonymize(ulong id)
		{
			if (!_idToAnonymized.TryGetValue(id, out var value))
			{
				value = Rng.Chaotic.NextUnsignedInt();
				_idToAnonymized[id] = value;
			}
			return value;
		}
	}
	public interface ILogPrinter
	{
		void Print(LogLevel logLevel, string text, int skipFrames);
	}
	public static class Log
	{
		private static readonly Logger _logger = new Logger(null, LogType.Generic);

		public static string Timestamp => DateTime.UtcNow.ToString("HH:mm:ss");

		public static event Action<LogLevel, string, int>? LogCallback;

		public static void InvokeGlobalLogCallback(LogLevel logLevel, string log, int skipFrames)
		{
			LogCallback?.Invoke(logLevel, log, skipFrames);
		}

		/// <summary>
		/// Prints to stdout. It should be used when loading operations are happening.
		/// </summary>
		/// <param name="text"></param>
		/// <param name="skipFrames"></param>
		public static void Load(string text, int skipFrames = 2)
		{
			_logger.Load(text, skipFrames);
		}

		/// <summary>
		/// Prints to stdout. Debug information which is useful for debugging. It should be used for verbose text.
		/// </summary>
		/// <param name="text"></param>
		/// <param name="skipFrames"></param>
		public static void Debug(string text, int skipFrames = 2)
		{
			_logger.Debug(text, skipFrames);
		}

		/// <summary>
		/// Prints to stdout. Debug information which is useful for debugging. It should be used for verbose text.
		/// </summary>
		/// <param name="text"></param>
		/// <param name="skipFrames"></param>
		public static void VeryDebug(string text, int skipFrames = 2)
		{
			_logger.VeryDebug(text, skipFrames);
		}

		/// <summary>
		/// Prints to stdout. It should be used for general information which is useful for debugging.
		/// </summary>
		/// <param name="text"></param>
		/// <param name="skipFrames"></param>
		public static void Info(string text, int skipFrames = 2)
		{
