	public static class FontControlUtils
	{
		/// <summary>
		/// Applies locale-specific font substitution if the current language requires it.
		/// </summary>
		public static void ApplyLocaleFontSubstitution(this Control control, FontType fontType, StringName themeFontName)
		{
			if (!Engine.IsEditorHint() && !TestMode.IsOn && LocManager.Instance != null && FontManager.NeedsFontSubstitution(LocManager.Instance.Language))
			{
				Font substituteFont = FontManager.GetSubstituteFont(LocManager.Instance.Language, fontType);
				if (substituteFont != null)
				{
					control.AddThemeFontOverride(themeFontName, substituteFont);
				}
			}
		}
	}
	/// <summary>
	/// Manages locale-specific font substitution for languages that require different fonts
	/// (e.g., CJK languages that need fonts with appropriate glyph coverage).
	/// </summary>
	public static class FontManager
	{
		private static readonly FontPathSet _russian = new RusFontPathSet();

		/// <summary>
		/// Languages that require font substitution.
		/// Key is language code, value is the set of font paths for that language.
		/// </summary>
		private static readonly IReadOnlyDictionary<string, FontPathSet> _languageFontPathSets = new System.Collections.Generic.Dictionary<string, FontPathSet>
		{
			["jpn"] = new JpnFontPathSet(),
			["kor"] = new KorFontPathSet(),
			["pol"] = _russian,
			["rus"] = _russian,
			["tha"] = new ThaFontPathSet(),
			["zhs"] = new ZhsFontPathSet(),
			["zht"] = new ZhtFontPathSet()
		};

		/// <summary>
		/// Cached font resources, keyed by language code then font type.
		/// </summary>
		private static readonly System.Collections.Generic.Dictionary<string, System.Collections.Generic.Dictionary<FontType, Font>> _localeFonts = new System.Collections.Generic.Dictionary<string, System.Collections.Generic.Dictionary<FontType, Font>>();

		/// <summary>
		/// Returns true if the given language requires font substitution.
		/// </summary>
		public static bool NeedsFontSubstitution(string language)
		{
			return _languageFontPathSets.ContainsKey(language);
		}

		/// <summary>
		/// Gets the substitute font for the given type based on the current locale.
		/// Returns null if no substitution is needed.
		/// </summary>
		public static Font? GetSubstituteFont(string language, FontType type)
		{
			if (!NeedsFontSubstitution(language))
			{
				return null;
			}
			return GetFontForLanguage(language, type);
		}

		public static void ClearCache()
		{
			_localeFonts.Clear();
		}

		/// <summary>
		/// Gets the font for the specified language and type, loading and caching if necessary.
		/// </summary>
		private static Font? GetFontForLanguage(string language, FontType type)
		{
			if (_localeFonts.TryGetValue(language, out System.Collections.Generic.Dictionary<FontType, Font> value) && value.TryGetValue(type, out var value2))
			{
				return value2;
			}
			string path = _languageFontPathSets[language].GetPath(type);
			if (path == null)
			{
				return null;
			}
			Font font = ResourceLoader.Load<Font>(path, null, ResourceLoader.CacheMode.Reuse);
			if (!_localeFonts.TryGetValue(language, out System.Collections.Generic.Dictionary<FontType, Font> value3))
			{
				value3 = new System.Collections.Generic.Dictionary<FontType, Font>();
				_localeFonts[language] = value3;
			}
			value3[type] = font;
			return font;
		}
	}
	/// <summary>
	/// A set of paths that can be used for substitution for a given language.
	/// </summary>
	public abstract class FontPathSet
	{
		/// <summary>
		/// Get the path for a given font type.
		/// </summary>
		/// <param name="type">What type of font to get the path for (Regular, Bold, etc.)</param>
		/// <returns>The path to the font, or null if not found.</returns>
		public abstract string? GetPath(FontType type);
	}
	/// <summary>
	/// Font types that can be substituted based on locale.
	/// </summary>
	public enum FontType
	{
		Regular,
		Bold,
		Italic
	}
}
