				base.BaseValue = Convert.ToDecimal(value);
			}
		}

		public BoolVar(string name)
			: base(name, 0m)
		{
		}

		public BoolVar(string name, bool value)
			: base(name, Convert.ToDecimal(value))
		{
		}
	}
	public class CalculatedBlockVar : CalculatedVar
	{
		public const string defaultName = "CalculatedBlock";

		public ValueProp Props { get; }

		/// <summary>
		/// Create a new <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculatedBlockVar" />.
		/// This will only work if the owner is a <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> whose <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVarSet" /> also has a
		/// <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculationBaseVar" /> and a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculationExtraVar" />.
		/// Note: For cards whose values are entirely dynamic and have no base value (like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Mirage" />), you
		/// should use a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculationBaseVar" /> of 0 and a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculationExtraVar" /> of 1.
		/// </summary>
		public CalculatedBlockVar(ValueProp props)
			: base("CalculatedBlock")
		{
			Props = props;
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			EnchantmentModel enchantment = card.Enchantment;
			if (enchantment != null)
			{
				decimal baseValue = GetBaseVar().BaseValue;
				baseValue += enchantment.EnchantBlockAdditive(baseValue);
				baseValue *= enchantment.EnchantBlockMultiplicative(baseValue);
				if (card.IsEnchantmentPreview)
				{
					base.PreviewValue = baseValue;
				}
				else
				{
					base.EnchantedValue = baseValue;
				}
			}
			decimal num = Calculate(target);
			if (runGlobalHooks)
			{
				base.PreviewValue = Hook.ModifyBlock(card.CombatState, card.Owner.Creature, Calculate(target), Props, card, null, out IEnumerable<AbstractModel> _);
			}
			else if (!card.IsEnchantmentPreview)
			{
				if (enchantment != null)
				{
					num += enchantment.EnchantBlockAdditive(num);
					num *= enchantment.EnchantBlockMultiplicative(num);
				}
				base.PreviewValue = num;
			}
		}
	}
	public class CalculatedDamageVar : CalculatedVar
	{
		public const string defaultName = "CalculatedDamage";

		public ValueProp Props { get; }

		public bool IsFromOsty { get; private set; }

		/// <summary>
		/// Create a new <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculatedDamageVar" />.
		/// This will only work if the owner is a <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> whose <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVarSet" /> also has a
		/// <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculationBaseVar" /> and a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.ExtraDamageVar" />.
		/// Note: For cards whose values are entirely dynamic and have no base value (like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.BodySlam" />), you
		/// should use a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculationBaseVar" /> of 0 and a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.ExtraDamageVar" /> of 1.
		/// </summary>
		public CalculatedDamageVar(ValueProp props)
			: base("CalculatedDamage")
		{
			Props = props;
		}

		/// <summary>
		/// Set this damage to come from Osty.
		/// </summary>
		public CalculatedDamageVar FromOsty()
		{
			IsFromOsty = true;
			return this;
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			EnchantmentModel enchantment = card.Enchantment;
			if (enchantment != null)
			{
				decimal baseValue = GetBaseVar().BaseValue;
				baseValue += enchantment.EnchantDamageAdditive(baseValue, Props);
				baseValue *= enchantment.EnchantDamageMultiplicative(baseValue, Props);
				baseValue = Math.Max(baseValue, 0m);
				if (card.IsEnchantmentPreview)
				{
					base.PreviewValue = baseValue;
				}
				else
				{
					base.EnchantedValue = baseValue;
				}
			}
			decimal num = Calculate(target);
			if (runGlobalHooks)
			{
				ICombatState combatState = card.CombatState ?? card.Owner.Creature.CombatState;
				base.PreviewValue = Hook.ModifyDamage(card.Owner.RunState, combatState, target, IsFromOsty ? card.Owner.Osty : card.Owner.Creature, num, Props, card, null, ModifyDamageHookType.All, previewMode, out IEnumerable<AbstractModel> _);
			}
			else if (!card.IsEnchantmentPreview)
			{
				if (enchantment != null)
				{
					num += enchantment.EnchantDamageAdditive(num, Props);
					num *= enchantment.EnchantDamageMultiplicative(num, Props);
				}
				base.PreviewValue = num;
			}
			base.PreviewValue = Math.Max(base.PreviewValue, 0m);
		}

		protected override DynamicVar GetExtraVar()
		{
			return ((CardModel)_owner).DynamicVars.ExtraDamage;
		}
	}
	/// <summary>
	/// A special type of DynamicVar that is used for cards that include a calculation in their base behavior.
	/// For example, <see cref="T:MegaCrit.Sts2.Core.Models.Cards.PerfectedStrike" /> uses a subclass of this (<see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculatedDamageVar" />) for its
	/// 6 base damage + 2 extra damage for each Strike.
	/// </summary>
	public class CalculatedVar : DynamicVar
	{
		private Func<CardModel, Creature?, decimal>? _multiplierCalc;

		public CalculatedVar(string name)
			: base(name, 0m)
		{
		}

		public override void SetOwner(AbstractModel owner)
		{
			base.SetOwner(owner);
			UpdateValues();
		}

		/// <summary>
		/// Set the function that will be used for the multiplier value of this var.
		/// This will be multiplied by the <see cref="M:MegaCrit.Sts2.Core.Localization.DynamicVars.CalculatedVar.GetExtraVar" /> value.
		/// This is the "dynamic" part of the calculation, and will often be based on something in the CombatState.
		/// </summary>
		/// <example>
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Cards.PerfectedStrike" /> says:
		/// "Deal 6 damage, plus 2 additional damage for ALL your cards containing "Strike"."
		/// In this case, the extra multiplier is the number of cards containing "Strike".
		/// </example>
		/// <param name="multiplierCalc">
		/// Function that will be used to calculate the extra multiplier value.
		/// Argument 1 is the card instance that this calculation is occurring on.
		/// Argument 2 is the creature that is being targeted for this calculation (null when there is no target).
		/// </param>
		public CalculatedVar WithMultiplier(Func<CardModel, Creature?, decimal> multiplierCalc)
		{
			if (_multiplierCalc != null)
			{
				throw new InvalidOperationException($"Tried to set extra multiplier calc on {this} twice!");
			}
			if (multiplierCalc.Target is AbstractModel)
			{
				throw new InvalidOperationException("Multiplier calc must be static!");
			}
			_multiplierCalc = multiplierCalc;
			return this;
		}

		/// <summary>
		/// Calculate this var's value based on the specified target.
		/// Effects that target multiple creatures (or no creatures) should pass null for the target.
		/// </summary>
		public decimal Calculate(Creature? target)
		{
			if (_multiplierCalc == null)
			{
				throw new InvalidOperationException("Extra multiplier calc must be specified!");
			}
			CardModel cardModel = (CardModel)_owner;
			decimal num = ((CombatManager.Instance.IsInProgress && cardModel.CombatState != null) ? _multiplierCalc(cardModel, target) : 0m);
			return GetBaseVar().BaseValue + GetExtraVar().BaseValue * num;
		}

		/// <summary>
		/// Re-run the calculations to determine if any of the dependent values have been upgraded or enchanted.
		/// </summary>
		public void RecalculateForUpgradeOrEnchant()
		{
			decimal baseValue = GetBaseVar().BaseValue;
			if (baseValue != base.BaseValue)
			{
				base.WasJustUpgraded = true;
			}
			base.BaseValue = baseValue;
		}

		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			base.PreviewValue = Calculate(target);
		}

		/// <summary>
		/// Get the DynamicVar that should be used for this calculation's base value.
		/// </summary>
		protected virtual DynamicVar GetBaseVar()
		{
			return ((CardModel)_owner).DynamicVars.CalculationBase;
		}

		/// <summary>
		/// Get the DynamicVar that should be used for this calculation's extra value.
		/// </summary>
		protected virtual DynamicVar GetExtraVar()
		{
			return ((CardModel)_owner).DynamicVars.CalculationExtra;
		}

		protected override decimal GetBaseValueForIConvertible()
		{
			return Calculate(null);
		}

		public override string ToString()
		{
			return Calculate(null).ToString();
		}

		private void UpdateValues()
		{
			if (_owner != null)
			{
				base.BaseValue = GetBaseVar().BaseValue;
			}
		}
	}
