namespace MegaCrit.Sts2.Core.Leaderboard
{
	/// <summary>
	/// A reference to a platform-specific leaderboard.
	/// </summary>
	public interface ILeaderboardHandle
	{
	}
	/// <summary>
	/// Interface for platform leaderboard implementations.
	/// Note: This is currently modeled after Steam's leaderboard API. As we add other platforms, I expect the interface to
	/// change heavily or need refactoring.
	/// For documentation on individual methods, look at LeaderboardManager, which replicates these methods exactly.
	/// </summary>
	public interface ILeaderboardStrategy
	{
		PlatformType Platform { get; }

		Task<ILeaderboardHandle> GetOrCreateLeaderboard(string name, CancellationToken cancelToken);

		Task<ILeaderboardHandle?> GetLeaderboard(string name, CancellationToken cancelToken);

		Task UploadLocalScore(ILeaderboardHandle handle, int score, IReadOnlyList<ulong> otherIds);

		Task<List<LeaderboardEntry>> QueryLeaderboard(ILeaderboardHandle handle, LeaderboardQueryType type, int startIndex, int count, CancellationToken cancelToken = default(CancellationToken));

		Task<List<LeaderboardEntry>> QueryLeaderboardForUsers(ILeaderboardHandle handle, IReadOnlyList<ulong> userIds, CancellationToken cancelToken = default(CancellationToken));

		int GetLeaderboardEntryCount(ILeaderboardHandle handle);
	}
	/// <summary>
	/// Abstracted leaderboard entry returned by querying the leaderboard API.
	/// </summary>
	public class LeaderboardEntry
	{
		/// <summary>
		/// Rank on the leaderboard reported from the API.
		/// </summary>
		public int rank;

		/// <summary>
		/// Name of the user who submitted the entry.
		/// </summary>
		public required string name;

		/// <summary>
		/// ID of the user who submitted the entry.
		/// </summary>
		public ulong id;

		/// <summary>
		/// The score of the submission.
		/// </summary>
		public int score;

		/// <summary>
		/// Other player IDs present in the run when this score was submitted.
		/// </summary>
		public List<ulong> userIds = new List<ulong>();
	}
	/// <summary>
	/// Facade for platform-specific leaderboard operations. Currently only Steam is supported in production;
	/// NullLeaderboardStrategy is used for dev/offline. The current implementation uses a sentinel score hack for
	/// multiplayer dailies (see ScoreUtility.clientScore) which is Steam-specific and will need revisiting when
	/// integrating other platforms' leaderboard APIs.
	/// </summary>
	public static class LeaderboardManager
	{
		private static ILeaderboardStrategy _strategy;

		public static PlatformType CurrentPlatform => _strategy.Platform;

		/// <summary>
		/// This should be called after all platform initialization is completed.
		/// </summary>
		public static void Initialize()
		{
			if (SteamInitializer.Initialized)
			{
				_strategy = new SteamLeaderboardStrategy();
			}
			else
			{
				_strategy = new NullLeaderboardStrategy();
			}
		}

		/// <summary>
		/// Obtains the leaderboard with the specified name. If it doesn't exist, it is created first.
		/// </summary>
		public static Task<ILeaderboardHandle> GetOrCreateLeaderboard(string name, CancellationToken cancelToken = default(CancellationToken))
		{
			return _strategy.GetOrCreateLeaderboard(name, cancelToken);
		}

		/// <summary>
		/// Obtains the leaderboard with the specified name. If it doesn't exist, null is returned.
		/// </summary>
		public static Task<ILeaderboardHandle?> GetLeaderboard(string name, CancellationToken cancelToken = default(CancellationToken))
		{
			return _strategy.GetLeaderboard(name, cancelToken);
		}

		/// <summary>
		/// Uploads a score associated with the local player.
		/// </summary>
		/// <param name="handle">The leaderboard to upload to, obtained from GetLeaderboard.</param>
		/// <param name="score">The score to upload.</param>
		/// <param name="userIds">User IDs to associate with the score. These will be returned with the leaderboard entry in
		/// future queries, but note that you can only query for the score based on the submitting player.</param>
		public static Task UploadLocalScore(ILeaderboardHandle handle, int score, IReadOnlyList<ulong> userIds)
		{
			return _strategy.UploadLocalScore(handle, score, userIds);
		}

		/// <summary>
		/// Queries the given leaderboard.
		/// </summary>
		/// <param name="handle">The leaderboard to query, obtained from GetLeaderboard.</param>
		/// <param name="type">The type of query.</param>
		/// <param name="startIndex">The index at which to start the query.</param>
		/// <param name="resultCount">The amount of results from the start index to return.</param>
		/// <param name="cancelToken">The token to use when requesting cancellation.</param>
		/// <returns>A task which will result in the entries queried.</returns>
		public static Task<List<LeaderboardEntry>> QueryLeaderboard(ILeaderboardHandle handle, LeaderboardQueryType type, int startIndex, int resultCount, CancellationToken cancelToken = default(CancellationToken))
		{
			return _strategy.QueryLeaderboard(handle, type, startIndex, resultCount, cancelToken);
		}

		/// <summary>
		/// Queries the given leaderboard, only returning entries for the passed users (if they exist).
		/// </summary>
		/// <param name="handle">The leaderboard to query, obtained from GetLeaderboard.</param>
		/// <param name="userIds">List of platform identifiers to query the leaderboard for.</param>
		/// <param name="cancelToken">The token to use when requesting cancellation.</param>
		/// <returns>A task which will result in the entries queried.</returns>
		public static Task<List<LeaderboardEntry>> QueryLeaderboardForUsers(ILeaderboardHandle handle, IReadOnlyList<ulong> userIds, CancellationToken cancelToken = default(CancellationToken))
		{
			return _strategy.QueryLeaderboardForUsers(handle, userIds, cancelToken);
		}

		/// <summary>
		/// Obtains the number of entries in the given leaderboard.
		/// </summary>
		public static int GetLeaderboardEntryCount(ILeaderboardHandle handle)
		{
			return _strategy.GetLeaderboardEntryCount(handle);
		}

		/// <summary>
		/// A method used in debugging. This will throw if the leaderboard is pointing to an actual backend.
		/// Rank is ignored. Score will be used to sort the entries.
		/// </summary>
		public static void DebugAddEntry(ILeaderboardHandle handle, LeaderboardEntry entry)
		{
			if (!(_strategy is NullLeaderboardStrategy nullLeaderboardStrategy))
			{
				throw new NotImplementedException();
			}
			nullLeaderboardStrategy.DebugAddEntry(handle, entry);
		}
	}
	public enum LeaderboardQueryType
	{
		None,
		/// <summary>
		/// Query globally. Indexes control the range of the query.
		/// </summary>
		Global,
		/// <summary>
		/// Query around the current user. Indexes are relative to the user.
		/// </summary>
		AroundUser,
		/// <summary>
		/// Query the user's friends. Indexes are ignored.
		/// </summary>
		FriendsOnly
	}
}
namespace MegaCrit.Sts2.Core.HoverTips
{
	public class CardHoverTip : IHoverTip
	{
		public CardModel Card { get; }

		public string Id { get; }

		public bool IsSmart => true;

		public bool IsDebuff => false;

		public bool IsInstanced => false;

		public AbstractModel CanonicalModel => Card.CanonicalInstance;

		public CardHoverTip(CardModel card)
		{
			if (!card.IsMutable)
			{
				Card = card.ToMutable();
			}
			else
			{
				Card = card;
			}
			Id = Card.Id.ToString();
			if (card.IsUpgraded)
			{
				Id += "+";
			}
		}
	}
	public record struct HoverTip : IHoverTip
	{
		public string? Title { get; private set; }

		public Texture2D? Icon { get; private set; }

		public string Description { get; private set; }

		public string Id { get; set; }

		public bool IsSmart { get; set; }

		public bool IsDebuff { get; set; }

		public bool IsInstanced { get; set; }

		public AbstractModel? CanonicalModel { get; private set; }

		/// <summary>
		/// Defines whether or now we want to word wrap the description text on the hover tip node
		/// or if we want the text to stretch the HoverTip horizontally. This is useful for situations
		/// like our map point entry hover tips in the run history screen, that can be pretty long.
		/// </summary>
		public bool ShouldOverrideTextOverflow { get; set; }

		public HoverTip(LocString description, Texture2D? icon = null)
		{
			Title = null;
			IsSmart = false;
			IsDebuff = false;
			IsInstanced = false;
			CanonicalModel = null;
			ShouldOverrideTextOverflow = false;
			Id = "LocString with Description=" + description.LocTable + "." + description.LocEntryKey;
			Description = description.GetFormattedText();
			Icon = icon;
		}

		public HoverTip(LocString title, LocString description, Texture2D? icon = null)
		{
			IsSmart = false;
			IsDebuff = false;
			IsInstanced = false;
			CanonicalModel = null;
			ShouldOverrideTextOverflow = false;
			Id = $"LocString with Title={title.LocTable}.{title.LocEntryKey} and Description={description.LocTable}.{description.LocEntryKey}";
			Title = title.GetFormattedText();
			Description = description.GetFormattedText();
			Icon = icon;
		}

		public HoverTip(LocString title, string description, Texture2D? icon = null)
		{
			IsSmart = false;
			IsDebuff = false;
			IsInstanced = false;
			CanonicalModel = null;
			ShouldOverrideTextOverflow = false;
			Id = "LocString with Title=" + title.LocTable + "." + title.LocEntryKey;
			Title = title.GetFormattedText();
			Description = description;
			Icon = icon;
		}

		public HoverTip(AfflictionModel affliction, LocString description)
		{
			IsSmart = false;
			IsInstanced = false;
			CanonicalModel = null;
			ShouldOverrideTextOverflow = false;
			Id = affliction.Id.ToString();
			Title = affliction.Title.GetFormattedText();
			Description = description.GetFormattedText();
			Icon = null;
			IsDebuff = true;
		}

		public HoverTip(OrbModel orb, LocString description)
		{
			IsSmart = false;
			IsDebuff = false;
			IsInstanced = false;
			CanonicalModel = null;
			ShouldOverrideTextOverflow = false;
			Id = orb.Id.ToString();
			Title = orb.Title.GetFormattedText();
			Description = description.GetFormattedText();
			Icon = orb.Icon;
		}

		/// <summary>
		/// Create a HoverTip from a PowerModel.
		/// </summary>
		/// <param name="power">Power to create the HoverTip for.</param>
		/// <param name="description">string to use in the description field.</param>
		/// <param name="isSmart">
		///     Whether or not the power description is "smart".
		///     For example, when the Strength HoverTip is displayed on the Body Slam card, it should be "dumb" because it's
		///     just referring to the concept of Strength, rather than a specific amount.
		///     On the flip side, when the Strength HoverTip is displayed when hovering over a creature with 3 Strength, it
		///     should be "smart" because it's referring to an instance of 3 Strength.
		/// </param>
		public HoverTip(PowerModel power, string description, bool isSmart)
		{
			CanonicalModel = null;
			ShouldOverrideTextOverflow = false;
			Id = power.Id.ToString();
			Title = power.Title.GetFormattedText();
			Description = description;
			Icon = power.Icon;
			IsDebuff = power.Type == PowerType.Debuff;
			IsInstanced = power.InstanceType != PowerInstanceType.None;
			IsSmart = isSmart;
		}

		public void SetCanonicalModel(AbstractModel model)
		{
			model.AssertCanonical();
			CanonicalModel = model;
		}

		/// <summary>
		/// We prefer to align HoverTips to be on the right-hand side of the hovered element. However, if we can't fit the HoverTip we left align.
		/// </summary>
		public static HoverTipAlignment GetHoverTipAlignment(Node2D node, float threshold = 0.75f)
		{
			if (!(node.GlobalPosition.X > node.GetViewport().GetVisibleRect().Size.X * threshold))
			{
				return HoverTipAlignment.Right;
			}
			return HoverTipAlignment.Left;
		}

		public static HoverTipAlignment GetHoverTipAlignment(Control node, float threshold = 0.75f)
		{
			if (!(node.GlobalPosition.X > node.GetViewport().GetVisibleRect().Size.X * threshold))
			{
				return HoverTipAlignment.Right;
			}
			return HoverTipAlignment.Left;
		}
	}
	public enum HoverTipAlignment
	{
		None,
		Left,
		Right,
		Center
	}
	public static class HoverTipFactory
	{
		private static readonly System.Collections.Generic.Dictionary<CardKeyword, HoverTip> _keywordHoverTips = new System.Collections.Generic.Dictionary<CardKeyword, HoverTip>();

		private static readonly System.Collections.Generic.Dictionary<ModelId, HoverTip> _potionHoverTips = new System.Collections.Generic.Dictionary<ModelId, HoverTip>();

		public static IEnumerable<IHoverTip> FromEnchantment<T>(int amount = 1) where T : EnchantmentModel
		{
			EnchantmentModel enchantmentModel = ModelDb.Enchantment<T>().ToMutable();
			enchantmentModel.Amount = amount;
			enchantmentModel.RecalculateValues();
			return enchantmentModel.HoverTips;
		}

		public static IEnumerable<IHoverTip> FromAffliction<T>(int amount = 1) where T : AfflictionModel
		{
			AfflictionModel afflictionModel = ModelDb.Affliction<T>().ToMutable();
			afflictionModel.Amount = amount;
			return afflictionModel.HoverTips;
		}

		public static IHoverTip FromKeyword(CardKeyword keyword)
		{
			if (!_keywordHoverTips.ContainsKey(keyword))
			{
				_keywordHoverTips[keyword] = new HoverTip(keyword.GetTitle(), keyword.GetDescription());
			}
			return _keywordHoverTips[keyword];
		}

		public static IHoverTip FromPower<T>(int? amount = null) where T : PowerModel
		{
			PowerModel model = ModelDb.Power<T>();
			return FromPower(model, amount);
		}

		public static IHoverTip FromPower(PowerModel model, int? amount = null)
		{
			return model.GetDumbHoverTip(amount);
		}

		/// <summary>
		/// Generate a HoverTip-sized preview of the specified power along with the power's hovertips.
		/// </summary>
		public static IEnumerable<IHoverTip> FromPowerWithPowerHoverTips<T>(int? amount = null) where T : PowerModel
