		public static bool ContainsBadWord(string text)
		{
			string text2 = text.ToLowerInvariant();
			string[] badWords = _badWords;
			foreach (string text3 in badWords)
			{
				if (text2.Contains(text3.ToLowerInvariant()))
				{
					return true;
				}
			}
			return false;
		}
	}
	public static class CommandLineHelper
	{
		private static readonly Godot.Collections.Dictionary<string, string?> _args;

		static CommandLineHelper()
		{
			_args = new Godot.Collections.Dictionary<string, string>();
			string[] cmdlineArgs = OS.GetCmdlineArgs();
			for (int i = 0; i < cmdlineArgs.Length; i++)
			{
				string text = cmdlineArgs[i].TrimStart('-');
				string key = text;
				string value = null;
				int num = text.IndexOf('=');
				if (num > 0)
				{
					key = text.Substring(0, num);
					value = text.Substring(num + 1);
				}
				else if (i + 1 < cmdlineArgs.Length && !cmdlineArgs[i + 1].StartsWith('-') && !cmdlineArgs[i + 1].StartsWith('+'))
				{
					value = cmdlineArgs[i + 1];
					i++;
				}
				_args[key] = value;
			}
		}

		public static bool HasArg(string key)
		{
			return _args.ContainsKey(key);
		}

		public static bool TryGetValue(string key, out string? value)
		{
			return _args.TryGetValue(key, out value);
		}

		public static string? GetValue(string key)
		{
			if (!TryGetValue(key, out string value))
			{
				return null;
			}
			return value;
		}
	}
