	public static class Ease
	{
		/// <summary>
		/// Easing function enums
		/// </summary>
		public enum Functions
		{
			QuadIn,
			QuadOut,
			QuadInOut,
			CubicIn,
			CubicOut,
			CubicInOut,
			QuartIn,
			QuartOut,
			QuartInOut,
			QuintIn,
			QuinOut,
			QuinInOut,
			SineIn,
			SineOut,
			SineInOut,
			CircIn,
			CircOut,
			CircInOut,
			ExpoIn,
			ExpoOut,
			ExpoInOut,
			ElasticIn,
			ElasticOut,
			ElasticInOut,
			BackIn,
			BackOut,
			BackInOut,
			BounceIn,
			BounceOut,
			BounceInOut
		}

		/// <summary>
		/// Used for safe floating point comparisons with pixel values on a 4K screen.
		/// </summary>
		private const float _tolerance = 0.001f;

		/// <summary>
		/// Constant Pi.
		/// </summary>
		private const float _pi = (float)Math.PI;

		/// <summary>
		/// Constant Pi / 2.
		/// </summary>
		private const float _halfPi = (float)Math.PI / 2f;

		/// <summary>
		/// Interpolate using the specified function.
		/// </summary>
		public static float Interpolate(float p, Functions function)
		{
			return function switch
			{
				Functions.QuadOut => QuadOut(p), 
				Functions.QuadIn => QuadIn(p), 
				Functions.QuadInOut => QuadInOut(p), 
				Functions.CubicIn => CubicIn(p), 
				Functions.CubicOut => CubicOut(p), 
				Functions.CubicInOut => CubicInOut(p), 
				Functions.QuartIn => QuartIn(p), 
				Functions.QuartOut => QuartOut(p), 
				Functions.QuartInOut => QuartInOut(p), 
				Functions.QuintIn => QuintIn(p), 
				Functions.QuinOut => QuintOut(p), 
				Functions.QuinInOut => QuintInOut(p), 
				Functions.SineIn => SineIn(p), 
				Functions.SineOut => SineOut(p), 
				Functions.SineInOut => SineInOut(p), 
				Functions.CircIn => CircIn(p), 
				Functions.CircOut => CircOut(p), 
				Functions.CircInOut => CircInOut(p), 
				Functions.ExpoIn => ExpoIn(p), 
				Functions.ExpoOut => ExpoOut(p), 
				Functions.ExpoInOut => ExpoInOut(p), 
				Functions.ElasticIn => ElasticIn(p), 
				Functions.ElasticOut => ElasticOut(p), 
				Functions.ElasticInOut => ElasticInOut(p), 
				Functions.BackIn => BackIn(p), 
				Functions.BackOut => BackOut(p), 
				Functions.BackInOut => BackInOut(p), 
				Functions.BounceIn => BounceIn(p), 
				Functions.BounceOut => BounceOut(p), 
				Functions.BounceInOut => BounceInOut(p), 
				_ => Linear(p), 
			};
		}

		/// <summary>
		/// Modeled after the line y = x
		/// </summary>
		public static float Linear(float p)
		{
			return p;
		}

		/// <summary>
		/// Modeled after the parabola y = x^2
		/// </summary>
		public static float QuadIn(float p)
		{
			return p * p;
		}

		/// <summary>
		/// Modeled after the parabola y = -x^2 + 2x
		/// </summary>
		public static float QuadOut(float p)
		{
			return 0f - p * (p - 2f);
		}

		/// <summary>
		/// Modeled after the piecewise quadratic
		/// y = (1/2)((2x)^2)             ; [0, 0.5)
		/// y = -(1/2)((2x-1)*(2x-3) - 1) ; [0.5, 1]
		/// </summary>
		public static float QuadInOut(float p)
		{
			if (p < 0.5f)
			{
				return 2f * p * p;
			}
			return -2f * p * p + 4f * p - 1f;
		}

		/// <summary>
		/// Modeled after the cubic y = x^3
		/// </summary>
		public static float CubicIn(float p)
		{
			return p * p * p;
		}

		/// <summary>
		/// Modeled after the cubic y = (x - 1)^3 + 1
		/// </summary>
		public static float CubicOut(float p)
		{
			float num = p - 1f;
			return num * num * num + 1f;
		}

		/// <summary>
		/// Modeled after the piecewise cubic
		/// y = (1/2)((2x)^3)       ; [0, 0.5)
		/// y = (1/2)((2x-2)^3 + 2) ; [0.5, 1]
		/// </summary>
		public static float CubicInOut(float p)
		{
			if (p < 0.5f)
			{
				return 4f * p * p * p;
			}
			float num = 2f * p - 2f;
			return 0.5f * num * num * num + 1f;
		}

		/// <summary>
		/// Modeled after the quartic x^4
		/// </summary>
		public static float QuartIn(float p)
		{
			return p * p * p * p;
		}

		/// <summary>
		/// Modeled after the quartic y = 1 - (x - 1)^4
		/// </summary>
		public static float QuartOut(float p)
		{
			float num = p - 1f;
			return num * num * num * (1f - p) + 1f;
		}

		/// <summary>
		/// Modeled after the piecewise quartic
		/// y = (1/2)((2x)^4)        ; [0, 0.5)
		/// y = -(1/2)((2x-2)^4 - 2) ; [0.5, 1]
		/// </summary>
		public static float QuartInOut(float p)
		{
			if (p < 0.5f)
			{
				return 8f * p * p * p * p;
			}
			float num = p - 1f;
			return -8f * num * num * num * num + 1f;
		}

		/// <summary>
		/// Modeled after the quintic y = x^5
		/// </summary>
		public static float QuintIn(float p)
		{
			return p * p * p * p * p;
		}

		/// <summary>
		/// Modeled after the quintic y = (x - 1)^5 + 1
		/// </summary>
		public static float QuintOut(float p)
		{
			float num = p - 1f;
			return num * num * num * num * num + 1f;
		}

		/// <summary>
		/// Modeled after the piecewise quintic
		/// y = (1/2)((2x)^5)       ; [0, 0.5)
		/// y = (1/2)((2x-2)^5 + 2) ; [0.5, 1]
		/// </summary>
		public static float QuintInOut(float p)
		{
			if (p < 0.5f)
			{
				return 16f * p * p * p * p * p;
			}
			float num = 2f * p - 2f;
			return 0.5f * num * num * num * num * num + 1f;
		}

		/// <summary>
		/// Modeled after quarter-cycle of sine wave
		/// </summary>
		public static float SineIn(float p)
		{
			return Mathf.Sin((p - 1f) * ((float)Math.PI / 2f)) + 1f;
		}

		/// <summary>
		/// Modeled after quarter-cycle of sine wave (different phase)
		/// </summary>
		public static float SineOut(float p)
		{
			return Mathf.Sin(p * ((float)Math.PI / 2f));
		}

		/// <summary>
		/// Modeled after half sine wave
		/// </summary>
		public static float SineInOut(float p)
		{
			return 0.5f * (1f - Mathf.Cos(p * (float)Math.PI));
		}

		/// <summary>
		/// Modeled after shifted quadrant IV of unit circle
		/// </summary>
		public static float CircIn(float p)
		{
			return 1f - Mathf.Sqrt(1f - p * p);
		}

		/// <summary>
		/// Modeled after shifted quadrant II of unit circle
		/// </summary>
		public static float CircOut(float p)
		{
			return Mathf.Sqrt((2f - p) * p);
		}

		/// <summary>
		/// Modeled after the piecewise circular function
		/// y = (1/2)(1 - Mathf.Sqrt(1 - 4x^2))           ; [0, 0.5)
		/// y = (1/2)(Mathf.Sqrt(-(2x - 3)*(2x - 1)) + 1) ; [0.5, 1]
		/// </summary>
		public static float CircInOut(float p)
		{
			if (p < 0.5f)
			{
				return 0.5f * (1f - Mathf.Sqrt(1f - 4f * (p * p)));
			}
			return 0.5f * (Mathf.Sqrt((0f - (2f * p - 3f)) * (2f * p - 1f)) + 1f);
		}

		/// <summary>
		/// Modeled after the exponential function y = 2^(10(x - 1))
		/// </summary>
		public static float ExpoIn(float p)
		{
			if (p != 0f)
			{
				return Mathf.Pow(2f, 10f * (p - 1f));
			}
			return p;
		}

		/// <summary>
		/// Modeled after the exponential function y = -2^(-10x) + 1
		/// </summary>
		public static float ExpoOut(float p)
		{
			if (!(Math.Abs(p - 1f) < 0.001f))
			{
				return 1f - Mathf.Pow(2f, -10f * p);
			}
			return p;
		}

		/// <summary>
		/// Modeled after the piecewise exponential
		/// y = (1/2)2^(10(2x - 1))         ; [0,0.5)
		/// y = -(1/2)*2^(-10(2x - 1))) + 1 ; [0.5,1]
		/// </summary>
		public static float ExpoInOut(float p)
		{
			if (p == 0f || Math.Abs(p - 1f) < 0.001f)
			{
				return p;
			}
			if (p < 0.5f)
			{
				return 0.5f * Mathf.Pow(2f, 20f * p - 10f);
			}
			return -0.5f * Mathf.Pow(2f, -20f * p + 10f) + 1f;
		}

		/// <summary>
		/// Modeled after the damped sine wave y = sin(13pi/2*x)*Mathf.Pow(2, 10 * (x - 1))
		/// </summary>
		public static float ElasticIn(float p)
		{
			return Mathf.Sin(20.420353f * p) * Mathf.Pow(2f, 10f * (p - 1f));
		}

		/// <summary>
		/// Modeled after the damped sine wave y = sin(-13pi/2*(x + 1))*Mathf.Pow(2, -10x) + 1
		/// </summary>
		public static float ElasticOut(float p)
		{
			return Mathf.Sin(-20.420353f * (p + 1f)) * Mathf.Pow(2f, -10f * p) + 1f;
		}

		/// <summary>
		/// Modeled after the piecewise exponentially-damped sine wave:
		/// y = (1/2)*sin(13pi/2*(2*x))*Mathf.Pow(2, 10 * ((2*x) - 1))      ; [0,0.5)
		/// y = (1/2)*(sin(-13pi/2*((2x-1)+1))*Mathf.Pow(2,-10(2*x-1)) + 2) ; [0.5, 1]
		/// </summary>
		public static float ElasticInOut(float p)
		{
			if (p < 0.5f)
			{
				return 0.5f * Mathf.Sin(20.420353f * (2f * p)) * Mathf.Pow(2f, 10f * (2f * p - 1f));
			}
			return 0.5f * (Mathf.Sin(-20.420353f * (2f * p - 1f + 1f)) * Mathf.Pow(2f, -10f * (2f * p - 1f)) + 2f);
		}

		/// <summary>
		/// Lerps an object beyond the target destination and brings it back
		/// </summary>
		public static float BackIn(float p, float strength = 1f)
		{
			float num = strength * 1.70158f;
			return p * p * ((num + 1f) * p - num);
		}

		/// <summary>
		/// Lerps an object beyond the target destination and brings it back
		/// </summary>
		public static float BackOut(float p, float strength = 1f)
		{
			float num = strength * 1.70158f;
			return 1f + num * (p - 1f) * (p - 1f) * ((num + 1f) * (p - 1f) + num);
		}

		/// <summary>
		/// Lerps an object beyond the target destination and brings it back
		/// </summary>
		public static float BackInOut(float p, float strength = 1f)
		{
			float num = strength * 1.70158f;
			p *= 2f;
			if (p < 1f)
			{
				return 0.5f * (p * p * (((num *= 1.525f) + 1f) * p - num));
			}
			return 0.5f * ((p -= 2f) * p * (((num *= 1.525f) + 1f) * p + num) + 2f);
		}

		public static float BounceIn(float p)
		{
			return 1f - BounceOut(1f - p);
		}

		public static float BounceOut(float p)
		{
			if (p < 0.36363637f)
			{
				return 121f * p * p / 16f;
			}
			if (p < 0.72727275f)
			{
				return 9.075f * p * p - 9.9f * p + 3.4f;
			}
			if (p < 0.9f)
			{
				return 12.066482f * p * p - 19.635458f * p + 8.898061f;
			}
			return 10.8f * p * p - 20.52f * p + 10.72f;
		}

		public static float BounceInOut(float p)
		{
			if (p < 0.5f)
			{
				return 0.5f * BounceIn(p * 2f);
			}
			return 0.5f * BounceOut(p * 2f - 1f) + 0.5f;
		}
	}
	public static class EnergyIconHelper
	{
		/// <summary>
		/// Get the string that should be used as the prefix for a model's energy icon path.
		///
		/// The logic here is a little more complicated than you'd expect; it's easy if it's a card in the player's deck
		/// during a run (just use the owner's card pool), but it gets trickier before the card is in the deck (like in
		/// card rewards) or outside of a run entirely (like in the card library).
		/// </summary>
		/// <param name="model">Model whose energy icon we want.</param>
		public static string GetPrefix(AbstractModel model)
		{
			return GetPool(model).EnergyColorName;
		}

		/// <summary>
		/// Get the string that should be used as the specified model's energy icon path.
		///
		/// The logic here is a little more complicated than you'd expect; it's easy if it's a card in the player's deck
		/// during a run (just use the owner's card pool), but it gets trickier before the card is in the deck (like in
		/// card rewards) or outside of a run entirely (like in the card library).
		/// </summary>
		/// <param name="model">Model whose energy icon we want.</param>
		public static string GetPath(AbstractModel model)
		{
			return GetPath(GetPrefix(model));
		}

		/// <summary>
		/// Get the string that should be used as the energy icon path for the specified prefix.
		/// </summary>
		public static string GetPath(string prefix)
		{
			return ImageHelper.GetImagePath("atlases/ui_atlas.sprites/card/energy_" + prefix.ToLowerInvariant() + ".tres");
		}

		private static IPoolModel GetPool(AbstractModel model)
		{
			if (model is IPoolModel result)
			{
				return result;
			}
			Player player = null;
			IPoolModel poolModel = null;
			if (!(model is CardModel cardModel))
			{
				if (!(model is EnchantmentModel enchantmentModel))
				{
					if (!(model is PotionModel potionModel))
					{
						if (!(model is RelicModel relicModel))
						{
							if (model is PowerModel powerModel)
							{
								if (powerModel != null && powerModel.IsMutable)
								{
									Creature owner = powerModel.Owner;
									if (owner != null && owner.IsPlayer)
									{
										player = powerModel.Owner.Player;
										goto IL_0108;
									}
								}
								poolModel = ModelDb.CardPool<ColorlessCardPool>();
							}
						}
						else
						{
							if (relicModel.IsMutable)
							{
								player = relicModel.Owner;
							}
							poolModel = relicModel.Pool;
						}
					}
					else
					{
						if (potionModel.IsMutable)
						{
							player = potionModel.Owner;
						}
						poolModel = potionModel.Pool;
					}
				}
				else if (enchantmentModel.HasCard)
				{
					player = enchantmentModel.Card.Owner;
					poolModel = enchantmentModel.Card.Pool;
				}
				else
				{
					poolModel = ModelDb.CardPool<ColorlessCardPool>();
				}
			}
			else
			{
				if (cardModel.IsMutable)
				{
					player = cardModel.Owner;
				}
				poolModel = cardModel.Pool;
			}
			goto IL_0108;
			IL_0108:
			if (player != null)
			{
				return player.Character.CardPool;
			}
			if (poolModel != null)
			{
				return poolModel;
			}
			Log.Error($"Model {model.Id} is not in any pool! It was probably deprecated without being removed.");
			return ModelDb.CardPool<IroncladCardPool>();
		}
	}
	public static class GlyphConverter
	{
		private static TextServer GetTextServer()
		{
			return TextServerManager.Singleton.GetPrimaryInterface();
		}

		public static uint CharToGlyphIdx(Rid font, char c)
		{
			return (uint)GetTextServer().FontGetGlyphIndex(font, 1L, c, 0L);
		}

		public static char GlyphIdxToChar(CharFXTransform charFx)
		{
			return (char)GetTextServer().FontGetCharFromGlyphIndex(charFx.Font, 1L, charFx.GlyphIndex);
		}
	}
	public static class GodotTreeExtensions
	{
		public static void AddChildSafely(this Node parent, Node? child)
		{
			if (child != null)
			{
				if (NGame.IsMainThread() && (parent.IsNodeReady() || !parent.IsInsideTree()))
				{
					parent.AddChild(child, forceReadableName: false, Node.InternalMode.Disabled);
					return;
				}
				parent.CallDeferred(Node.MethodName.AddChild, child);
			}
		}

		public static void AddSiblingSafely(this Node sibling, Node? child)
		{
			if (child == null)
			{
				return;
			}
			Node parent = sibling.GetParent();
			if (parent != null)
			{
				if (NGame.IsMainThread() && (parent.IsNodeReady() || !parent.IsInsideTree()))
				{
					sibling.AddSibling(child);
					return;
				}
				sibling.CallDeferred(Node.MethodName.AddSibling, child);
			}
		}

		public static void MoveChildSafely(this Node parent, Node? child, int index)
		{
			if (child != null)
			{
				if (NGame.IsMainThread() && (parent.IsNodeReady() || !parent.IsInsideTree()))
				{
					parent.MoveChild(child, index);
					return;
				}
				parent.CallDeferred(Node.MethodName.MoveChild, child, index);
			}
		}

		public static void MoveToFrontSafely(this CanvasItem node)
		{
			Node parent = node.GetParent();
			if (parent != null)
			{
				if (NGame.IsMainThread() && (parent.IsNodeReady() || !parent.IsInsideTree()))
				{
					node.MoveToFront();
					return;
				}
				parent.CallDeferred(Node.MethodName.MoveChild, node, -1);
			}
		}

		public static void RemoveChildSafely(this Node parent, Node? child)
		{
			if (child != null)
			{
				if (NGame.IsMainThread() && (parent.IsNodeReady() || !parent.IsInsideTree()))
				{
					parent.RemoveChild(child);
					return;
				}
				parent.CallDeferred(Node.MethodName.RemoveChild, child);
			}
		}

		public static void QueueFreeSafely(this Node node)
		{
			if (!GodotObject.IsInstanceValid(node))
			{
				return;
			}
			IPoolable poolable = node as IPoolable;
			if (poolable != null)
			{
				node.GetParent()?.RemoveChildSafely(node);
				Callable.From(delegate
				{
					NodePool.Free(poolable);
				}).CallDeferred();
			}
			else
			{
				node.QueueFreeSafelyNoPool();
			}
		}

		public static void QueueFreeSafelyNoPool(this Node node)
		{
			if (NGame.IsMainThread())
			{
				node.QueueFree();
			}
			else
			{
				node.CallDeferred(Node.MethodName.QueueFree);
			}
		}

		public static void FreeChildren(this Node node)
		{
			foreach (Node child in node.GetChildren())
			{
				child.QueueFreeSafely();
			}
		}
	}
	/// <summary>
	/// A generic collection that allows the caller to grab random elements with weighted probabilities.
	/// </summary>
	/// <example>
	/// Imagine the following code:
	///
	/// <code>
	/// GrabBag{string} bag = new GrabBag{string}();
	///
	/// bag.Add("dog", 1);
	/// bag.Add("cat", 1);
	/// bag.Add("fish", 2);
	/// bag.add("lion", 0.5);
	/// bag.add("tiger", 0.5);
	///
	/// string result = bag.Grab();
	/// </code>
	///
	/// In the above code, 5 elements are added to a grab bag with differing weights, then a random one is chosen.
	/// If the above code were run 100 times, the results should be:
	/// * "dog" approximately 20 times
	/// * "cat" approximately 20 times
	/// * "fish" approximately 40 times (twice as many as dog or cat, since it has a weight of 2 instead of 1)
	/// * "lion" approximately 10 times (half as many as dog or cat, since it has a weight of 0.5 instead of 1)
	/// * "tiger" approximately 10 times (half as many as dog or cat, since it has a weight of 0.5 instead of 1)
	/// </example>
	/// <typeparam name="T">Type of elements contained by GrabBag.</typeparam>
	public class GrabBag<T>
	{
		/// <summary>
		///
		/// </summary>
		private readonly List<(T, double)> _entries = new List<(T, double)>();

		private double _totalWeight;

		public int Count => _entries.Count;

		/// <summary>
		/// Add an element with a specified weight.
		/// </summary>
		/// <param name="element">Element to add.</param>
		/// <param name="weight">Amount to weight the element.</param>
		public void Add(T element, double weight)
		{
			_entries.Add((element, weight));
			_totalWeight += weight;
		}

		/// <summary>
		/// Grab a random element from the bag, respecting weights.
		/// </summary>
		/// <param name="rng">Generator to grab the random roll from.</param>
		/// <param name="predicate">Predicate that must be matched by the returned element.</param>
		/// <returns>Randomly-chosen element. Null if the bag is empty.</returns>
		public T? Grab(Rng rng, Func<T, bool>? predicate = null)
		{
			int num = GrabIndex(rng, predicate);
			if (num < 0)
			{
				return default(T);
			}
			return _entries[num].Item1;
		}

		/// <summary>
		/// Grab a random element from the bag, respecting weights. Remove it after grabbing.
		/// </summary>
		/// <param name="rng">Generator to grab the random roll from.</param>
		/// <param name="predicate">Predicate that must be matched by the returned element.</param>
		/// <returns>Randomly-chosen element. Null if the bag is empty.</returns>
		public T? GrabAndRemove(Rng rng, Func<T, bool>? predicate = null)
		{
			int num = GrabIndex(rng, predicate);
			if (num < 0)
			{
				return default(T);
			}
			T item = _entries[num].Item1;
			Remove(num);
			return item;
		}

		public bool Any()
		{
			return _entries.Any();
		}

		private int GrabIndex(Rng rng, Func<T, bool>? predicate)
		{
			if (predicate != null && !_entries.Any(((T, double) e) => predicate(e.Item1)))
			{
				return -1;
			}
			int num;
			do
			{
				num = GrabIndex(rng);
			}
			while (predicate != null && num >= 0 && !predicate(_entries[num].Item1));
			return num;
		}

		private int GrabIndex(Rng rng)
		{
			double num = rng.NextDouble() * _totalWeight;
			double num2 = 0.0;
			for (int i = 0; i < _entries.Count; i++)
			{
				num2 += _entries[i].Item2;
				if (num < num2)
				{
					return i;
				}
			}
			return -1;
		}

		private void Remove(int index)
		{
			_totalWeight -= _entries[index].Item2;
			_entries.RemoveAt(index);
		}
	}
	public static class HandLayoutHelper
	{
		/// <summary>
		/// Returns where <paramref name="target" /> belongs among <paramref name="presentCards" /> once both are ordered
		/// by <paramref name="pileOrder" />: the count of present cards (excluding the target itself) that precede the
		/// target in pile order.
		///
		/// Callers use this to turn a backend-pile position into a child index for a container that may be missing some
		/// of the pile's cards (selected, awaiting play, or being dragged). Each absent card that precedes the target
		/// inflates the raw pile index past the target's real slot; once enough precede it the index exceeds the live
		/// child count and Godot rejects the move with "Invalid new child index" (PRG-6847). The result cannot exceed
		/// the number of present cards, so when <paramref name="presentCards" /> is exactly the container's current
		/// children it is a valid child index by construction; correctness depends on the caller passing that set.
		/// </summary>
		/// <param name="pileOrder">The full backend pile order.</param>
		/// <param name="presentCards">The cards whose holders are currently in the container, in any order.</param>
		/// <param name="target">The card being (re)inserted.</param>
		/// <returns>The insert index, or -1 if the target is not in the pile (caller should skip the move).</returns>
		public static int GetInsertIndex<T>(IReadOnlyList<T> pileOrder, IEnumerable<T> presentCards, T target)
		{
			EqualityComparer<T> equalityComparer = EqualityComparer<T>.Default;
			int num = IndexOf(pileOrder, target, equalityComparer);
			if (num < 0)
			{
				return -1;
			}
			int num2 = 0;
			foreach (T presentCard in presentCards)
			{
				if (!equalityComparer.Equals(presentCard, target))
				{
					int num3 = IndexOf(pileOrder, presentCard, equalityComparer);
					if (num3 >= 0 && num3 < num)
					{
						num2++;
					}
				}
			}
			return num2;
		}

		private static int IndexOf<T>(IReadOnlyList<T> list, T item, EqualityComparer<T> comparer)
		{
			for (int i = 0; i < list.Count; i++)
			{
				if (comparer.Equals(list[i], item))
				{
					return i;
				}
			}
			return -1;
		}
	}
