	/// <summary>
	/// Contains methods that are called as part of initialization.
	/// The methods are called both in normal startup and in test mode, so only call things that need to be done in both.
	/// </summary>
	public static class OneTimeInitialization
	{
		private enum State
		{
			None,
			VeryEarly,
			Essential,
			Done
		}

		private static AtlasResourceLoader? _atlasResourceLoader;

		private static State _state;

		public static ReadSaveResult<SettingsSave> SettingsReadResult { get; private set; }

		/// <summary>
		/// Initializes stuff that has to happen very early.
		/// This gets called in both tests and in real games!! Only do stuff that needs to happen in both here.
		/// </summary>
		public static async Task ExecuteVeryEarly()
		{
			if (_state != State.None)
			{
				Log.Error($"Tried to call OneTimeInitialization.ExecuteVeryEarly in state {_state}!");
				return;
			}
			_state = State.VeryEarly;
			if (TestMode.IsOn)
			{
				SettingsReadResult = SaveManager.Instance.InitSettingsDataForTest();
			}
			else
			{
				SettingsReadResult = SaveManager.Instance.InitSettingsData();
			}
			await ModManager.Initialize(new ModManagerFileIo(), SaveManager.Instance.SettingsSave.ModSettings, ReleaseInfoManager.Instance.SemVer);
			UserDataPathProvider.IsRunningModded = ModManager.IsRunningModded();
			SentryService.DisableSentryIfModded();
		}

		/// <summary>
		/// Essential initialization needed before main menu can display.
		/// Loads only ui_atlas and core systems (settings, mods, localization, model DB init).
		/// </summary>
		public static void ExecuteEssential()
		{
			if (_state != State.VeryEarly)
			{
				Log.Error($"Tried to call OneTimeInitialization.ExecuteEssential in state {_state}!");
				return;
			}
			_state = State.Essential;
			_atlasResourceLoader = new AtlasResourceLoader();
			ResourceLoader.AddResourceFormatLoader(_atlasResourceLoader, atFront: true);
			AtlasManager.LoadEssentialAtlases();
			LocManager.Initialize();
			AssemblyInfo.Init();
			ModelDb.Init();
			ModelIdSerializationCache.Init();
			ModelDb.InitIds();
			MessageTypes.Initialize();
			ActionTypes.Initialize();
		}

		/// <summary>
		/// Deferred initialization that can run after main menu is displayed.
		/// Loads remaining atlases and runs expensive precomputation.
		/// </summary>
		public static void ExecuteDeferred()
		{
			if (_state != State.Essential)
			{
				Log.Error($"Tried to call OneTimeInitialization.ExecuteDeferred in state {_state}!");
				return;
			}
			_state = State.Done;
			AtlasManager.LoadAllAtlases();
			if (!OS.HasFeature("editor"))
			{
				ModelDb.Preload();
				PrewarmJit();
				ConditionalFormatter conditionalFormatter = new ConditionalFormatter();
			}
		}

		private static void PrewarmJit()
		{
			Type typeFromHandle = typeof(PacketWriter);
			Type typeFromHandle2 = typeof(PacketReader);
			foreach (Type subtype in ReflectionHelper.GetSubtypes<IPacketSerializable>())
			{
				RuntimeHelpers.PrepareMethod(subtype.GetMethod("Serialize").MethodHandle);
				RuntimeHelpers.PrepareMethod(subtype.GetMethod("Deserialize").MethodHandle);
				RuntimeHelpers.PrepareMethod(typeFromHandle.GetMethod("WriteList").MethodHandle, new RuntimeTypeHandle[1] { subtype.TypeHandle });
				RuntimeHelpers.PrepareMethod(typeFromHandle.GetMethod("Write").MethodHandle, new RuntimeTypeHandle[1] { subtype.TypeHandle });
				RuntimeHelpers.PrepareMethod(typeFromHandle2.GetMethod("ReadList").MethodHandle, new RuntimeTypeHandle[1] { subtype.TypeHandle });
				RuntimeHelpers.PrepareMethod(typeFromHandle2.GetMethod("Read").MethodHandle, new RuntimeTypeHandle[1] { subtype.TypeHandle });
			}
			foreach (Type subtype2 in ReflectionHelper.GetSubtypes<INetMessage>())
			{
				RuntimeHelpers.PrepareMethod(subtype2.GetMethod("get_ShouldBuffer").MethodHandle);
				RuntimeHelpers.PrepareMethod(subtype2.GetMethod("get_LogLevel").MethodHandle);
				RuntimeHelpers.PrepareMethod(subtype2.GetMethod("get_Mode").MethodHandle);
				RuntimeHelpers.PrepareMethod(subtype2.GetMethod("get_ShouldBroadcast").MethodHandle);
			}
		}
	}
	public static class Really
	{
		/// <summary>
		/// Really big for games, but not big enough to come close to overflowing int!
		/// </summary>
		public const int bigNumber = 999999999;
	}
	/// <summary>
	/// A few utility methods for accessing types via reflection.
	/// In general, you should avoid using this, as it does not work on console platforms (or anywhere that NativeAOT is
	/// required). You can check for support with SubtypesAvailable.
	/// Only use this in scenarios where it is required (e.g. for modding).
	/// </summary>
	public static class ReflectionHelper
	{
		public const BindingFlags allAccessLevels = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;

		private static Type[]? _allTypes;

		private static Type[]? _modTypes;

		public static bool SubtypesAvailable => true;

		public static Type[] AllTypes
		{
			get
			{
				if (_allTypes == null)
				{
					_allTypes = Assembly.GetAssembly(typeof(ReflectionHelper)).GetTypes();
				}
				return _allTypes;
			}
		}

		public static Type[] ModTypes
		{
			get
			{
				if (ModManager.State == ModManagerState.None)
				{
					throw new InvalidOperationException("ModManager is not finished initializing! ReflectionHelper.ModTypes cannot be called before that.");
				}
				if (_modTypes == null)
				{
					_modTypes = ModManager.GetLoadedMods().SelectMany((Mod m) => m.assemblies).SelectMany((Assembly a) => a.GetTypes())
						.ToArray();
				}
				return _modTypes;
			}
		}

		public static IEnumerable<Type> GetSubtypes(Type parentType)
		{
			return GetSubtypesFromList(AllTypes, parentType);
		}

		public static IEnumerable<Type> GetSubtypesInMods(Type parentType)
		{
			return GetSubtypesFromList(ModTypes, parentType);
		}

		public static IEnumerable<Type> GetSubtypesFromAssembly(Assembly assembly, Type parentType)
		{
			return GetSubtypesFromList(assembly.GetTypes(), parentType);
		}

		private static IEnumerable<Type> GetSubtypesFromList(IList<Type> list, Type parentType)
		{
			return list.Where((Type type) => (object)type != null && !type.IsAbstract && !type.IsInterface && InheritsOrImplements(type, parentType));
		}

		public static IEnumerable<Type> GetSubtypes<T>() where T : class
		{
			return GetSubtypes(typeof(T));
		}

		public static IEnumerable<Type> GetSubtypesInMods<T>() where T : class
		{
			return GetSubtypesInMods(typeof(T));
		}

		public static bool InheritsOrImplements([DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.Interfaces)] Type derived, Type baseType)
		{
			if (!derived.IsSubclassOf(baseType))
			{
				return Enumerable.Contains(derived.GetInterfaces(), baseType);
			}
			return true;
		}
	}
	public static class SceneHelper
	{
		/// <summary>
		/// Get the path to the scene with the specified "inner" path.
		/// </summary>
		/// <param name="innerPath">The scene's inner path. For example, for "scenes/ui/button.tscn", pass "ui/button".</param>
		/// <returns>The full path to the scene.</returns>
		public static string GetScenePath(string innerPath)
		{
			if (innerPath.StartsWith('/'))
			{
				string text = innerPath;
				innerPath = text.Substring(1, text.Length - 1);
			}
			return "res://scenes/" + innerPath + ".tscn";
		}

		/// <summary>
		/// Load the packed scene with the specified "inner" path.
		/// </summary>
		/// <param name="innerPath">The scene's inner path. For example, for "scenes/ui/button.tscn", pass "ui/button".</param>
		/// <returns>The PackedScene.</returns>
		private static PackedScene Load(string innerPath)
		{
			string scenePath = GetScenePath(innerPath);
			return ResourceLoader.Load<PackedScene>(scenePath, null, ResourceLoader.CacheMode.Reuse);
		}

		/// <summary>
		/// Instantiate the scene with the specified "inner" path.
		/// </summary>
		/// <param name="innerPath">The scene's inner path. For example, for "scenes/ui/button.tscn", pass "ui/button".</param>
		/// <typeparam name="T">The type to cast to. Should be a descendant of <see cref="T:Godot.Node" />.</typeparam>
		/// <returns>The instantiated scene.</returns>
		public static T Instantiate<T>(string innerPath) where T : Node
		{
			return Load(innerPath).Instantiate<T>(PackedScene.GenEditState.Disabled);
		}
	}
	public static class ScrollHelper
	{
		/// <summary>
		/// How much we travel per scrollWheel tick.
		/// Probably better to get the expected scroll distance from the OS.
		/// </summary>
		private const float _scrollAmount = 40f;

		/// <summary>
		/// How much we travel per touchpad gesture tick.
		/// </summary>
		private const float _panScrollSpeed = 50f;

		/// <summary>
		/// How fast we lerp to the target position when dragging.
		/// </summary>
		public const float dragLerpSpeed = 15f;

		/// <summary>
		/// How close we need to be to the target position before we snap to it.
		/// </summary>
		public const float snapThreshold = 0.5f;

		/// <summary>
		/// How fast we bounce back after scrolling past the edge of the screen.
		/// </summary>
		public const float bounceBackStrength = 12f;

		/// <summary>
		/// Get the amount of scroll drag that should be added for a given scroll event.
		/// </summary>
		public static float GetDragForScrollEvent(InputEvent inputEvent)
		{
			if (inputEvent is InputEventMouseButton { ButtonIndex: var buttonIndex })
			{
				switch (buttonIndex)
				{
				case MouseButton.WheelUp:
					return 40f;
				case MouseButton.WheelDown:
					return -40f;
				}
			}
			else if (inputEvent is InputEventPanGesture inputEventPanGesture)
			{
				return (0f - inputEventPanGesture.Delta.Y) * 50f;
			}
			return 0f;
		}
	}
	public static class SeedHelper
	{
		/// <summary>
		/// Possible characters for the seed.
		/// O and I are not included. They are replaced by 0 and 1.
		/// </summary>
		private const string _characters = "0123456789ABCDEFGHJKLMNPQRSTUVWXYZ";

		public const int seedDefaultLength = 12;

		public static string GetRandomSeed(Rng? rng = null, int length = 12)
		{
			if (rng == null)
			{
				rng = Rng.Chaotic;
			}
			string text;
			do
			{
				StringBuilder stringBuilder = new StringBuilder();
				for (int i = 0; i < length; i++)
				{
					stringBuilder.Append(rng.NextItem("0123456789ABCDEFGHJKLMNPQRSTUVWXYZ"));
				}
				text = stringBuilder.ToString();
			}
			while (BadWordChecker.ContainsBadWord(text));
			return text;
		}

		public static string CanonicalizeSeed(string seed)
		{
			seed = seed.ToUpperInvariant();
			seed = seed.Replace('O', '0');
			seed = seed.Replace('I', '1');
			seed = seed.Trim();
			return seed;
		}
	}
	public static class SpineNodeExtensions
	{
		private const int _spineReadyWarnThresholdFrames = 600;

		/// <summary>
		/// Invokes <paramref name="onReady" /> with <paramref name="sprite" />'s animation state once it
		/// exists, waiting across frames if necessary.
		///
		/// Godot runs _Ready() bottom-up (children before parents) and a SpineSprite builds its skeleton
		/// asynchronously, so a VFX node can run before the SpineSprite it drives has created its
		/// animation state. Driving the animation state in that window throws a NullReferenceException and
		/// leaves the VFX uninitialized (PRG-6982). Use this for any animation-state setup that runs from
		/// _Ready, whether <paramref name="sprite" /> is the node's parent or a child/sibling sub-sprite.
		///
		/// If the skeleton never loads (e.g. asset load failure, which NCreatureVisuals handles by
		/// disabling the spine), <paramref name="onReady" /> simply never runs, and a one-time warning is
		/// logged once the wait grows implausibly long. The wait also stops if <paramref name="host" /> or
		/// <paramref name="sprite" />'s node leaves the tree or is freed. The sprite can be freed
		/// independently of the host (e.g. NOrb frees and recreates its sprite on orb replacement while
		/// the NOrb node itself stays in the tree).
		/// </summary>
		public static void RunWhenSpineReady(this Node host, MegaSprite sprite, Action<MegaAnimationState> onReady)
		{
			TaskHelper.RunSafely(WaitForSpineReady(host, sprite, onReady));
		}

		private static async Task WaitForSpineReady(Node host, MegaSprite sprite, Action<MegaAnimationState> onReady)
		{
			int framesWaited = 0;
			while (GodotObject.IsInstanceValid(sprite.BoundObject) && !sprite.IsAnimationStateReady())
			{
				await host.AwaitProcessFrame();
				int num = framesWaited + 1;
				framesWaited = num;
				if (num == 600)
				{
					Log.Warn($"{host.Name}: still waiting for a SpineSprite skeleton after {framesWaited} " + "frames; its animation will not start until the skeleton loads (possible asset load failure).");
				}
			}
			if (GodotObject.IsInstanceValid(sprite.BoundObject))
			{
				onReady(sprite.GetAnimationState());
			}
		}
	}
