	public static class TaskHelper
	{
		/// <summary>
		/// Raised when a fire-and-forget task faults. Nothing awaits these tasks, so the fault is otherwise only a log
		/// line. The test harness subscribes to fail the owning test; see UnobservedAsyncFaultGate.
		/// </summary>
		public static event Action<Exception>? UnobservedFault;

		/// <summary>
		/// Runs a task without awaiting it.
		/// Prefer using this over calling the task-returning method and then discarding the task, as that causes exceptions
		/// not to be logged.
		/// </summary>
		public static Task RunSafely(Task task)
		{
			return LogTaskExceptions(task);
		}

		private static async Task LogTaskExceptions(Task task)
		{
			try
			{
				await task;
			}
			catch (Exception ex)
			{
				if (!(ex is OperationCanceledException))
				{
					Log.Error(ex.ToString());
					SentryService.CaptureException(ex);
					UnobservedFault?.Invoke(ex);
				}
				throw;
			}
		}

		/// <summary>
		/// Runs all the tasks at once and returns a task whose result is equivalent to the first task completed.
		/// Prefer using this over Task.WhenAny, as that returns a Task that is always successful.
		/// </summary>
		/// <param name="tasks"></param>
		/// <returns></returns>
		public static async Task WhenAny(params Task[] tasks)
		{
			await (await Task.WhenAny(tasks));
		}
	}
	public static class TimeFormatting
	{
		public static string Format(float time)
		{
			TimeSpan timeSpan = TimeSpan.FromSeconds(time);
			int num = (int)timeSpan.TotalHours;
			LocString locString;
			if (num > 0)
			{
				locString = new LocString("main_menu_ui", "RUN_TIME_FORMAT_HOURS");
				locString.Add("Hours", num.ToString());
			}
			else
			{
				locString = new LocString("main_menu_ui", "RUN_TIME_FORMAT");
			}
			locString.Add("Seconds", timeSpan.Seconds.ToString("00"));
			locString.Add("Minutes", timeSpan.Minutes.ToString("00"));
			return locString.GetFormattedText();
		}
	}
