namespace MegaCrit.Sts2.Core.Helpers.Models
{
	public static class CardCostHelper
	{
		/// <summary>
		/// Get the color that should be used for the text in a card's energy cost.
		/// Depends on a whole bunch of tricky rules, see comments and tests for details.
		/// WARNING: If you make a change to this method, you should probably make a similar change to
		/// <see cref="M:MegaCrit.Sts2.Core.Helpers.Models.CardCostHelper.GetStarCostColor(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Combat.ICombatState)" />, or write a comment explaining why the two methods are different.
		/// </summary>
		/// <param name="card">Card whose energy cost color we want.</param>
		/// <param name="state">Combat state that the color depends on. Null outside of combat (like in the Card Library).</param>
		/// <returns>Energy cost color for the specified card in the specified combat state.</returns>
		public static CardCostColor GetEnergyCostColor(CardModel card, ICombatState? state)
		{
			if (state == null)
			{
				return CardCostColor.Unmodified;
			}
			if (!card.CanPlay(out UnplayableReason reason, out AbstractModel _) && reason.HasFlag(UnplayableReason.EnergyCostTooHigh))
			{
				return CardCostColor.InsufficientResources;
			}
			if (card.EnergyCost.CostsX)
			{
				return CardCostColor.Unmodified;
			}
			if (TryModifyEnergyCostWithHooks(card, state, out var hookModifiedCost))
			{
				return GetColorForHookModifiedCost(hookModifiedCost, card.EnergyCost.GetWithModifiers(CostModifiers.None));
			}
			if (card.EnergyCost.HasLocalModifiers)
			{
				return GetColorForLocalCost(card.EnergyCost.GetWithModifiers(CostModifiers.Local), card.EnergyCost.GetWithModifiers(CostModifiers.None));
			}
			return CardCostColor.Unmodified;
		}

		/// <summary>
		/// Get the color that should be used for the text in a card's star cost.
		/// Depends on a whole bunch of tricky rules, see comments and tests for details.
		/// WARNING: If you make a change to this method, you should probably make a similar change to
		/// <see cref="M:MegaCrit.Sts2.Core.Helpers.Models.CardCostHelper.GetEnergyCostColor(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Combat.ICombatState)" />, or write a comment explaining why the two methods are different.
		/// </summary>
		/// <param name="card">Card whose star cost color we want.</param>
		/// <param name="state">Combat state that the color depends on. Null outside of combat (like in the Card Library).</param>
		/// <returns>Star cost color for the specified card in the specified combat state.</returns>
		public static CardCostColor GetStarCostColor(CardModel card, ICombatState? state)
		{
			if (state == null)
			{
				return CardCostColor.Unmodified;
			}
			if (!card.CanPlay(out UnplayableReason reason, out AbstractModel _) && reason.HasFlag(UnplayableReason.StarCostTooHigh))
			{
				return CardCostColor.InsufficientResources;
			}
			if (card.HasStarCostX)
			{
				return CardCostColor.Unmodified;
			}
			if (TryModifyStarCostWithHooks(card, state, out var hookModifiedCost))
			{
				return GetColorForHookModifiedCost(hookModifiedCost, card.BaseStarCost);
			}
			if (card.TemporaryStarCost != null)
			{
				return GetColorForLocalCost(card.TemporaryStarCost.Cost, card.BaseStarCost);
			}
			return CardCostColor.Unmodified;
		}

		private static CardCostColor GetColorForLocalCost(int localCost, int baseCost)
		{
			if (localCost > baseCost)
			{
				return CardCostColor.Increased;
			}
			if (localCost < baseCost)
			{
				return CardCostColor.Decreased;
			}
			return CardCostColor.Unmodified;
		}

		private static CardCostColor GetColorForHookModifiedCost(decimal hookModifiedCost, int baseCost)
		{
			if (hookModifiedCost > (decimal)baseCost)
			{
				return CardCostColor.Increased;
			}
			if (hookModifiedCost < (decimal)baseCost)
			{
				return CardCostColor.Decreased;
			}
			return CardCostColor.Unmodified;
		}

		private static bool TryModifyEnergyCostWithHooks(CardModel card, ICombatState state, out decimal hookModifiedCost)
		{
			hookModifiedCost = card.EnergyCost.GetWithModifiers(CostModifiers.None);
			bool flag = false;
			foreach (AbstractModel item in state.IterateHookListeners())
			{
				flag |= item.TryModifyEnergyCostInCombat(card, hookModifiedCost, out hookModifiedCost);
			}
			foreach (AbstractModel item2 in state.IterateHookListeners())
			{
				flag |= item2.TryModifyEnergyCostInCombatLate(card, hookModifiedCost, out hookModifiedCost);
			}
			return flag;
		}

		private static bool TryModifyStarCostWithHooks(CardModel card, ICombatState state, out decimal hookModifiedCost)
		{
			hookModifiedCost = card.BaseStarCost;
			bool flag = false;
			foreach (AbstractModel item in state.IterateHookListeners())
			{
				flag |= item.TryModifyStarCost(card, hookModifiedCost, out hookModifiedCost);
			}
			return flag;
		}
	}
	public static class EggRelicHelper
	{
		public static void UpgradeValidCards(List<CardCreationResult> cards, CardType cardType, RelicModel eggRelic)
		{
			foreach (CardCreationResult card3 in cards)
			{
				CardModel card = card3.Card;
				if (card.Type == cardType && card.IsUpgradable)
				{
					CardModel card2 = eggRelic.Owner.RunState.CloneCard(card);
					CardCmd.Upgrade(card2);
					card3.ModifyCard(card2, eggRelic);
				}
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.GameActions
{
	/// <summary>
	/// Responsible for pulling actions from the PlayerActionQueueSet and executing them.
	/// </summary>
	public class ActionExecutor
	{
		private readonly ActionQueueSet _actionQueueSet;

		private bool _isPaused;

		private CancellationTokenSource? _actionCancelToken;

		private TaskCompletionSource<bool>? _queueTaskCompletionSource;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		public bool IsPaused => _isPaused;

		public bool IsRunning
		{
			get
			{
				TaskCompletionSource<bool> queueTaskCompletionSource = _queueTaskCompletionSource;
				if (queueTaskCompletionSource != null)
				{
					Task<bool> task = queueTaskCompletionSource.Task;
					if (task != null)
					{
						return !task.IsCompleted;
					}
				}
				return false;
			}
		}

		public GameAction? CurrentlyRunningAction { get; private set; }

		public event Action<GameAction>? BeforeActionExecuted;

		public event Action<GameAction>? JustBeforeActionFinishedExecuting;

		public event Action<GameAction>? AfterActionExecuted;

		public ActionExecutor(ActionQueueSet actionQueueSet)
		{
			actionQueueSet.ActionQueueChanged += ActionQueueChanged;
			_actionQueueSet = actionQueueSet;
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("ActionExecutor", LogType.Actions);
		}

		/// <summary>
		/// WARNING: You probably want to use CombatManager.Pause() instead. Only use this if you want to pause player
		/// actions WITHOUT pausing the rest of combat.
		///
		/// Pause the ActionQueue.
		/// </summary>
		public void Pause()
		{
			if (!NonInteractiveMode.AutoSlayerCheck())
			{
				_logger.Debug("Pausing queue");
				_isPaused = true;
			}
		}

		/// <summary>
		/// WARNING: You probably want to use CombatManager.Unpause() instead. Only use this if you want to un-pause player
		/// actions WITHOUT un-pausing the rest of combat.
		///
		/// Unpause the ActionQueue.
		/// </summary>
		public void Unpause()
		{
			_logger.Debug("Un-pausing queue");
			_isPaused = false;
		}

		/// <summary>
		/// Returns a task which finishes execution when there are no tasks left to execute.
		/// If there is no currently executing task, then this returns a completed task.
		/// </summary>
		public Task FinishedExecutingActions()
		{
			if (_queueTaskCompletionSource == null)
			{
				return Task.CompletedTask;
			}
			return _queueTaskCompletionSource.Task;
		}

		/// <summary>
		/// Cancel the whole queue.
		/// </summary>
		public void Cancel()
		{
			_logger.Debug("Cancelling queue");
			_actionCancelToken?.Cancel();
		}

		private void ActionQueueChanged()
		{
			if (!IsRunning)
			{
				_logger.Debug("Action queue changed, beginning ExecuteActions");
				TaskHelper.RunSafely(ExecuteActions());
			}
		}

		private async Task ExecuteActions()
		{
			_queueTaskCompletionSource = new TaskCompletionSource<bool>();
			_actionCancelToken = new CancellationTokenSource();
			try
			{
				GameAction readyAction = _actionQueueSet.GetReadyAction();
				while (readyAction != null)
				{
					await WaitForUnpause();
					if (readyAction.State == GameActionState.Canceled)
					{
						readyAction = _actionQueueSet.GetReadyAction();
						continue;
					}
					_logger.Debug($"Executing action: {readyAction}");
					BeforeActionExecuted?.Invoke(readyAction);
					if (NonInteractiveMode.IsActive)
					{
						CurrentlyRunningAction = readyAction;
						await readyAction.Execute();
						AfterActionFinished(readyAction);
					}
					else
					{
						CurrentlyRunningAction = readyAction;
						readyAction.JustBeforeFinished += JustBeforeActionFinished;
						readyAction.AfterFinished += AfterActionFinished;
						Task actionTask = readyAction.Execute();
						while (!actionTask.IsCompleted && !_actionCancelToken.IsCancellationRequested)
						{
							await Engine.GetMainLoop().ToSignal(Engine.GetMainLoop(), SceneTree.SignalName.ProcessFrame);
						}
						if (actionTask.IsFaulted)
						{
							Log.Error($"GameAction {readyAction} completed with exception: {actionTask.Exception}");
						}
					}
					bool isInProgress = CombatManager.Instance.IsInProgress;
					bool flag = isInProgress;
					if (flag)
					{
						bool flag2 = ((readyAction is EndPlayerTurnAction || readyAction is ReadyToBeginEnemyTurnAction) ? true : false);
						flag = !flag2;
					}
					if (flag)
					{
						await CombatManager.Instance.CheckWinCondition();
					}
					if (readyAction.State == GameActionState.Finished)
					{
						_logger.Debug($"Completed execution of action {readyAction}, attempting to find new action");
					}
					else
					{
						_logger.Debug($"Paused execution of action {readyAction} (state is {readyAction.State}), attempting to find new action");
					}
					readyAction.JustBeforeFinished -= JustBeforeActionFinished;
					readyAction.AfterFinished -= AfterActionFinished;
					readyAction = _actionQueueSet.GetReadyAction();
				}
				_queueTaskCompletionSource?.SetResult(result: true);
			}
			catch (OperationCanceledException innerException)
			{
				InvalidOperationException ex = new InvalidOperationException("ActionExecutor.ExecuteActions should never be canceled!", innerException);
				_queueTaskCompletionSource?.SetException(ex);
				throw ex;
			}
			catch (Exception exception)
			{
				_queueTaskCompletionSource?.SetException(exception);
				throw;
			}
		}

		private void JustBeforeActionFinished(GameAction action)
		{
			if (CurrentlyRunningAction != action)
			{
				Log.Error($"Currently running action {CurrentlyRunningAction} did not match finishing action {action}!");
			}
			else if (action.State == GameActionState.Finished)
			{
				JustBeforeActionFinishedExecuting?.Invoke(action);
			}
		}

		private void AfterActionFinished(GameAction action)
		{
			if (CurrentlyRunningAction != action)
			{
				Log.Error($"Currently running action {CurrentlyRunningAction} did not match recently finished action {action}!");
			}
			else
			{
				if (action.State == GameActionState.Finished)
				{
					AfterActionExecuted?.Invoke(action);
				}
				CurrentlyRunningAction = null;
			}
		}

		private async Task WaitForUnpause()
		{
			if (NonInteractiveMode.AutoSlayerCheck())
			{
				return;
			}
			while (_isPaused)
			{
				if (TestMode.IsOn)
				{
					await Task.Delay(50);
				}
				else
				{
					await NGame.Instance.AwaitProcessFrame();
				}
			}
		}
	}
	/// <summary>
	/// This action is enqueued when the player chooses to discard a potion from their belt. It runs both in combat and
	/// outside of combat.
	/// </summary>
	public class DiscardPotionGameAction : GameAction
	{
		private readonly Player _player;

		private readonly uint _potionSlotIndex;

		public override ulong OwnerId => _player.NetId;

		public override GameActionType ActionType
		{
			get
			{
				if (!WasEnqueuedInCombat)
				{
					return GameActionType.NonCombat;
				}
				return GameActionType.CombatPlayPhaseOnly;
			}
		}

		/// <summary>
		/// True if the player discarded a potion in combat, false otherwise.
		/// The player may discard a potion at any time. However, there's a specific situation in which order of GameAction
		/// enqueues matters when out-of-combat: if the player discards a potion post-combat while another player is still
		/// executing the player turn. If the action is set to GameActionType.Any, it will be executed during combat, before
		/// the enemy turn.
		/// </summary>
		public bool WasEnqueuedInCombat { get; }

		public DiscardPotionGameAction(Player player, uint potionSlotIndex, bool isCombatInProgress)
		{
			_player = player;
			_potionSlotIndex = potionSlotIndex;
			WasEnqueuedInCombat = isCombatInProgress;
		}

		protected override async Task ExecuteAction()
		{
			if (_potionSlotIndex >= _player.PotionSlots.Count)
			{
				throw new IndexOutOfRangeException($"Tried to discard potion at slot index {_potionSlotIndex}, but player {_player.NetId} only has {_player.PotionSlots.Count} potion slots!");
			}
			PotionModel potionModel = _player.PotionSlots[(int)_potionSlotIndex];
			if (potionModel == null)
			{
				Log.Warn($"{"DiscardPotionGameAction"}: potion at slot index {_potionSlotIndex} is null for player {_player.NetId}, canceling");
				Cancel();
			}
			else
			{
				Log.Info($"Player {potionModel.Owner.NetId} discarding potion {potionModel.Id.Entry}");
				await PotionCmd.Discard(potionModel);
			}
		}

		protected override void CancelAction()
		{
			PotionModel potionAtSlotIndex = _player.GetPotionAtSlotIndex((int)_potionSlotIndex);
			if (TestMode.IsOff && NRun.Instance != null && LocalContext.IsMe(_player) && potionAtSlotIndex != null)
			{
				NRun.Instance.GlobalUi.TopBar.PotionContainer.OnPotionUseOrDiscardCanceled(potionAtSlotIndex);
			}
			potionAtSlotIndex?.AfterUsageCanceled();
		}

		public override INetAction ToNetAction()
		{
			return new NetDiscardPotionGameAction
			{
				potionSlotIndex = _potionSlotIndex,
				wasEnqueuedInCombat = WasEnqueuedInCombat
			};
		}

		public override string ToString()
		{
			return $"{"NetDiscardPotionGameAction"} for player {_player.NetId} potion slot: {_potionSlotIndex} in combat: {WasEnqueuedInCombat}";
		}
	}
	public struct NetDiscardPotionGameAction : INetAction, IPacketSerializable
	{
		public uint potionSlotIndex;

		public bool wasEnqueuedInCombat;

		public GameAction ToGameAction(Player player)
		{
			return new DiscardPotionGameAction(player, potionSlotIndex, wasEnqueuedInCombat);
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteUInt(potionSlotIndex, 4);
			writer.WriteBool(wasEnqueuedInCombat);
		}

		public void Deserialize(PacketReader reader)
		{
			potionSlotIndex = reader.ReadUInt(4);
			wasEnqueuedInCombat = reader.ReadBool();
		}

		public override string ToString()
		{
			return $"{"NetDiscardPotionGameAction"} slot {potionSlotIndex} in combat: {wasEnqueuedInCombat}";
		}
	}
	/// <summary>
	/// This action is enqueued when the player presses the "End Turn" button in the UI. It begins the process of ending a
	/// player's turn. Notes:
	/// * This action only marks the player as ready to end turn, and encapsulates only that action. It does not block
	///   the queue while turns are ending.
	/// * SwitchSidesAction is enqueued after this one, and acts as a synchronization point for players who are ready to
	///   enter phase 2 of turn ending.
	/// </summary>
	public class EndPlayerTurnAction : GameAction
	{
		private readonly Player _player;

		private readonly int _turnNumber;

		public override ulong OwnerId => _player.NetId;

		public override GameActionType ActionType => GameActionType.CombatPlayPhaseOnly;

		public EndPlayerTurnAction(Player player, int turnNumber)
		{
			_player = player;
			_turnNumber = turnNumber;
		}

		protected override Task ExecuteAction()
		{
			int turnNumber = _player.PlayerCombatState.TurnNumber;
			if (turnNumber == _turnNumber)
			{
				PlayerCmd.EndTurn(_player, canBackOut: true);
			}
			else
			{
				Log.Info($"Ignoring end turn action. Current turn number: {turnNumber} action turn number: {_turnNumber} CombatState: {RunManager.Instance.ActionQueueSynchronizer.CombatState}");
			}
			return Task.CompletedTask;
		}

		public override INetAction ToNetAction()
		{
			return new NetEndPlayerTurnAction
			{
				turnNumber = _turnNumber
			};
		}

		public override string ToString()
		{
			return $"{"EndPlayerTurnAction"} for player {_player.NetId} turn {_turnNumber}";
		}
	}
	public struct NetEndPlayerTurnAction : INetAction, IPacketSerializable
	{
		public int turnNumber;

		public GameAction ToGameAction(Player player)
		{
			return new EndPlayerTurnAction(player, turnNumber);
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(turnNumber, 16);
		}

		public void Deserialize(PacketReader reader)
		{
			turnNumber = reader.ReadInt(16);
		}

		public override string ToString()
		{
			return $"{"NetEndPlayerTurnAction"} turn: {turnNumber}";
		}
	}
	/// <summary>
	/// A GameAction is a thin wrapper around an async task that should be run in response to player input.
	/// THIS IS DIFFERENT from GameActions in STS1 (and the original Unity version of STS2).
	///
	/// In STS1, a GameAction represented a small unit of game logic, like dealing damage, gaining block, etc.
	///
	/// In STS2, these small units of logic are handled by Commands (see the MegaCrit.Sts2.Core.Commands namespace).
	/// A GameAction WRAPS these commands, and should ONLY be used for player input.
	///
	/// Examples of things that SHOULD be wrapped in a game action:
	/// * Playing a card.
	/// * Drinking a potion.
	/// * Clicking the "end player turn" button.
	///
	/// Examples of things that should NOT be wrapped in a game action:
	/// * Dealing damage (this can happen as PART of a game action, but never directly from player input).
	/// * Gaining block (same reason).
	/// * Applying a power to a creature (same reason).
	/// * A monster making a move (once the player's turn ends, monster moves are run in sequence. They wait on each other
	///   to execute, but never on player input, so no GameActions are necessary).
	/// </summary>
	public abstract class GameAction
	{
		private static readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("GameAction", LogType.Actions);

		private TaskCompletionSource? _pauseForPlayerChoiceTaskSource;

		private TaskCompletionSource? _executeAfterResumptionTaskSource;

		private TaskCompletionSource _completionSource = new TaskCompletionSource();

		private Task? _executionTask;

		public GameActionState State { get; private set; }

		public abstract ulong OwnerId { get; }

		/// <summary>
		/// The type of game action, which dictates cancellation and enqueuing timings. See comments in the enum for
		/// details.
		/// </summary>
		public abstract GameActionType ActionType { get; }

		public uint? Id { get; private set; }

		/// <summary>
		/// Use this to wait for the GameAction to be fully completed.
		/// </summary>
		public Task CompletionTask => _completionSource.Task;

		public Exception? Exception => _executionTask?.Exception;

		public virtual bool RecordableToReplay => true;

		/// <summary>
		/// Called when the GameAction is fully run to completion, but just before we complete _completionSource.
		/// This timing is important for checksum generation.
		/// </summary>
		public event Action<GameAction>? JustBeforeFinished;

		/// <summary>
		/// Called when the GameAction is fully run to completion.
		/// </summary>
		public event Action<GameAction>? AfterFinished;

		/// <summary>
		/// Called just before the GameAction begins execution for the first time.
		/// Not called when the GameAction is resumed.
		/// </summary>
		public event Action<GameAction>? BeforeExecuted;

		/// <summary>
		/// Called when the GameAction is cancelled.
		/// </summary>
		public event Action<GameAction>? BeforeCancelled;

		/// <summary>
		/// Called when the GameAction is paused for player choice.
		/// </summary>
		public event Action<GameAction>? BeforePausedForPlayerChoice;

		/// <summary>
		/// Called when the GameAction is ready to resume after player choice.
		/// </summary>
		public event Action<GameAction>? BeforeReadyToResumeAfterPlayerChoice;

		/// <summary>
		/// Called when the GameAction resumes execution after player choice.
		/// </summary>
		public event Action<GameAction>? BeforeResumedAfterPlayerChoice;

		public void OnEnqueued(Action<GameAction> afterFinished, uint id)
		{
			if (State != GameActionState.None)
			{
				throw new InvalidOperationException($"GameAction {this} was enqueued to the queue twice!");
			}
			Log.VeryDebug($"Action {this} enqueued with id {id}");
			Id = id;
			AfterFinished += afterFinished;
			State = GameActionState.WaitingForExecution;
		}

		public async Task Execute()
		{
			_pauseForPlayerChoiceTaskSource = new TaskCompletionSource();
			switch (State)
			{
			case GameActionState.WaitingForExecution:
				_logger.VeryDebug($"Action {this} began executing");
				State = GameActionState.Executing;
				BeforeExecuted?.Invoke(this);
				_executionTask = TaskHelper.RunSafely(ExecuteAction());
				break;
			case GameActionState.ReadyToResumeExecuting:
				_logger.VeryDebug($"Action {this} resumed execution");
				State = GameActionState.Executing;
				_executeAfterResumptionTaskSource.SetResult();
				break;
			default:
				throw new InvalidOperationException($"Attempted to execute GameAction {this} from invalid state {State}! Expected WaitingForExecution or ReadyToResumeExecuting");
			}
			try
			{
				await TaskHelper.WhenAny(_executionTask, _pauseForPlayerChoiceTaskSource.Task);
			}
			finally
			{
				if (_executionTask.IsCompleted)
				{
					GameActionState state = State;
					_logger.VeryDebug($"Action {this} finished execution");
					State = GameActionState.Finished;
					JustBeforeFinished?.Invoke(this);
					_completionSource.TrySetResult();
					AfterFinished?.Invoke(this);
					if (state != GameActionState.Executing)
					{
						string text = $"GameAction {this} finished execution, but was in state {state}! The task probably kept executing in a paused state without properly resuming.";
						Exception ex = new InvalidOperationException(text, Exception);
						if (NonInteractiveMode.IsActive)
						{
							throw ex;
						}
						Log.Error(text);
						SentryService.CaptureException(ex);
					}
				}
				else
				{
					_logger.VeryDebug($"Action {this} paused execution");
				}
			}
		}

		public void ResumeAfterGatheringPlayerChoice(uint newId)
		{
			if (State != GameActionState.GatheringPlayerChoice)
			{
				throw new InvalidOperationException($"Tried setting GameAction {this} ready from invalid state {State}! Expected GatheringPlayerChoice");
			}
			_logger.VeryDebug($"Action {this} finished gathering player choice, and is assigned new id {newId}");
			Id = newId;
			BeforeReadyToResumeAfterPlayerChoice?.Invoke(this);
			State = GameActionState.ReadyToResumeExecuting;
		}

		public async Task WaitForActionToResumeExecutingAfterPlayerChoice()
		{
			_logger.VeryDebug($"Action {this} waiting to resume execution after player choice");
			await _executeAfterResumptionTaskSource.Task;
			_executeAfterResumptionTaskSource = null;
			BeforeResumedAfterPlayerChoice?.Invoke(this);
		}

		public void PauseForPlayerChoice()
		{
			if (State != GameActionState.Executing)
			{
				throw new InvalidOperationException($"Tried to pause GameAction {this} from invalid state {State}! Expected Executing");
			}
			_logger.VeryDebug($"Action {this} gathering player choice");
			_executeAfterResumptionTaskSource = new TaskCompletionSource();
			BeforePausedForPlayerChoice?.Invoke(this);
			State = GameActionState.GatheringPlayerChoice;
			_pauseForPlayerChoiceTaskSource.SetResult();
		}

		protected abstract Task ExecuteAction();

		public void Cancel()
		{
			State = GameActionState.Canceled;
			BeforeCancelled?.Invoke(this);
			CancelAction();
			Callable.From(() => _completionSource.TrySetCanceled()).CallDeferred();
		}

		protected virtual void CancelAction()
		{
		}

		public abstract INetAction ToNetAction();
	}
	public class GenericHookGameAction : GameAction
	{
		private readonly TaskCompletionSource _executionStartedSource = new TaskCompletionSource();

		private readonly TaskCompletionSource _choiceContextSetSource = new TaskCompletionSource();

		private readonly GameActionType _gameActionType;

		/// <summary>
		/// See CombatManagerMultiplayerTest.
		/// </summary>
		public Task? debugArtificialDelayAfterTask;

		public override bool RecordableToReplay => false;

		public HookPlayerChoiceContext? ChoiceContext { get; private set; }

		public override ulong OwnerId { get; }

		public override GameActionType ActionType => _gameActionType;

		public uint HookId { get; }

		public Task ExecutionStartedTask => _executionStartedSource.Task;

		public GenericHookGameAction(uint hookId, ulong ownerId, GameActionType gameActionType)
		{
			_gameActionType = gameActionType;
			HookId = hookId;
			OwnerId = ownerId;
			if (_gameActionType != GameActionType.Combat && _gameActionType != GameActionType.CombatPlayPhaseOnly)
			{
				throw new InvalidOperationException($"Unexpected GameActionType {_gameActionType} received for GenericHookGameAction!");
			}
		}

		public void SetChoiceContext(HookPlayerChoiceContext choiceContext)
		{
			if (choiceContext.Owner?.NetId != OwnerId)
			{
				throw new InvalidOperationException($"Assigned choice context with owner {choiceContext.Owner?.NetId} to GenericHookGameAction with owner {OwnerId}!");
			}
			ChoiceContext = choiceContext;
			_choiceContextSetSource.SetResult();
		}

		protected override async Task ExecuteAction()
		{
			await _choiceContextSetSource.Task;
			_executionStartedSource.SetResult();
			await ChoiceContext.Task;
			if (debugArtificialDelayAfterTask != null)
			{
				await debugArtificialDelayAfterTask;
			}
		}

		public override INetAction ToNetAction()
		{
			throw new NotImplementedException();
		}

		public override string ToString()
		{
			return $"{"GenericHookGameAction"} id {HookId} owner {OwnerId} source {ChoiceContext?.Source} last involved {ChoiceContext?.LastInvolvedModel}";
		}
	}
	/// <summary>
	/// An action enqueued by the host after all players have issued a vote at the map screen.
	/// This needs to be enqueued, instead of depending on everyone picking the same map point, because a random map point
	/// may be chosen in the event that two or more map points receive the same number of votes. We do not depend on RNGs
	/// being deterministic outside of combat.
	/// </summary>
	public class MoveToMapCoordAction : GameAction
	{
		private readonly Player _player;

		private readonly MapCoord _destination;

		public override ulong OwnerId => _player.NetId;

		public override GameActionType ActionType => GameActionType.NonCombat;

		public MoveToMapCoordAction(Player player, MapCoord destination)
		{
			_player = player;
			_destination = destination;
		}

		protected override async Task ExecuteAction()
		{
			if (TestMode.IsOn)
			{
				await RunManager.Instance.FadeOut();
				await RunManager.Instance.EnterMapCoord(_destination);
				TaskHelper.RunSafely(RunManager.Instance.FadeIn());
			}
			else
			{
				await NMapScreen.Instance.TravelToMapCoord(_destination);
			}
		}

		public override INetAction ToNetAction()
		{
			return new NetMoveToMapCoordAction
			{
				destination = _destination
			};
		}

		public override string ToString()
		{
			return $"{"MoveToMapCoordAction"} {_player.NetId} {_destination}";
		}
	}
	public struct NetMoveToMapCoordAction : INetAction, IPacketSerializable
	{
		public MapCoord destination;

