	public struct NetReadyToBeginEnemyTurnAction : INetAction, IPacketSerializable
	{
		public GameAction ToGameAction(Player player)
		{
			return new ReadyToBeginEnemyTurnAction(player);
		}

		public void Serialize(PacketWriter serializer)
		{
		}

		public void Deserialize(PacketReader deserializer)
		{
		}

		public override string ToString()
		{
			return "NetReadyToBeginEnemyTurnAction";
		}
	}
	/// <summary>
	/// This action is enqueued when the player presses the "End Turn" button in the UI. It begins the process of ending a
	/// player's turn. Notes:
	/// * This action only marks the player as ready to end turn, and encapsulates only that action. It does not block
	///   the queue while turns are ending.
	/// * SwitchSidesAction is enqueued after this one, and acts as a synchronization point for players who are ready to
	///   enter phase 2 of turn ending.
	/// </summary>
	public class UndoEndPlayerTurnAction : GameAction
	{
		private readonly Player _player;

		private readonly int _turnNumber;

		public override ulong OwnerId => _player.NetId;

		public override GameActionType ActionType => GameActionType.CombatPlayPhaseOnly;

		public UndoEndPlayerTurnAction(Player player, int turnNumber)
		{
			_player = player;
			_turnNumber = turnNumber;
		}

		protected override Task ExecuteAction()
		{
			int turnNumber = _player.PlayerCombatState.TurnNumber;
			if (turnNumber == _turnNumber)
			{
				CombatManager.Instance.UndoReadyToEndTurn(_player);
			}
			else
			{
				Log.Info($"Ignoring undo end turn action. Current turn number: {turnNumber} action turn number: {_turnNumber} CombatState: {RunManager.Instance.ActionQueueSynchronizer.CombatState}");
			}
			return Task.CompletedTask;
		}

		public override INetAction ToNetAction()
		{
			return new NetUndoEndPlayerTurnAction
			{
				turnNumber = _turnNumber
			};
		}

		public override string ToString()
		{
			return $"{"UndoEndPlayerTurnAction"} for player {_player.NetId} turn {_turnNumber}";
		}
	}
	public struct NetUndoEndPlayerTurnAction : INetAction, IPacketSerializable
	{
		public int turnNumber;

		public GameAction ToGameAction(Player player)
		{
			return new UndoEndPlayerTurnAction(player, turnNumber);
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteInt(turnNumber, 16);
		}

		public void Deserialize(PacketReader reader)
		{
			turnNumber = reader.ReadInt(16);
		}

		public override string ToString()
		{
			return $"{"NetUndoEndPlayerTurnAction"} turn: {turnNumber}";
		}
	}
	public class UsePotionAction : GameAction
	{
		public override ulong OwnerId => Player.NetId;

		public override GameActionType ActionType
		{
			get
			{
				if (!WasEnqueuedInCombat)
				{
					return GameActionType.NonCombat;
				}
				return GameActionType.CombatPlayPhaseOnly;
			}
		}

		public Player Player { get; }

		public uint PotionIndex { get; }

		public uint? TargetId { get; }

		public bool WasEnqueuedInCombat { get; }

		private ulong? TargetPlayerId { get; }

		public PlayerChoiceContext? PlayerChoiceContext { get; private set; }

		/// <summary>
		/// Constructor to use for constructing the UsePotionAction outside of serialization.
		/// </summary>
		/// <param name="potion">The potion which will be used.</param>
		/// <param name="target">The target which the player is using the potion on. Pass null if the potion is not targeted.</param>
		/// <param name="isCombatInProgress">Pass true if the potion was played during combat. The GameAction will be cancelled at
		/// the end of combat if it is still enqueued.</param>
		public UsePotionAction(PotionModel potion, Creature? target, bool isCombatInProgress)
		{
			if (potion.Owner == null)
			{
				throw new InvalidOperationException($"Cannot enqueue UsePotionAction for potion {potion} without an owner!");
			}
			int potionSlotIndex = potion.Owner.GetPotionSlotIndex(potion);
			if (potionSlotIndex < 0)
			{
				throw new InvalidOperationException($"Potion {potion} has owner {Player}, but the owner's potion list does not contain it!");
			}
			Player = potion.Owner;
			PotionIndex = (uint)potionSlotIndex;
			WasEnqueuedInCombat = isCombatInProgress;
			if (target == null)
			{
				return;
			}
			if (!target.CombatId.HasValue)
			{
				if (CombatManager.Instance.IsInProgress)
				{
					throw new InvalidOperationException($"Trying to target potion {potion} at target {target} that has no combat ID assigned during combat!");
				}
				if (!target.IsPlayer)
				{
					throw new InvalidOperationException($"Trying to target potion {potion} at target {target} outside of combat that is not a player!");
				}
			}
			TargetId = target.CombatId;
			TargetPlayerId = target.Player?.NetId;
		}

		/// <summary>
		/// Constructor to use when deserializing a NetUsePotionAction. Should not be used in other circumstances.
		/// </summary>
		/// <param name="player">The player who sent us the action.</param>
		/// <param name="potionIndex">The index of the potion that will be used.</param>
		/// <param name="targetId">The combat ID of the target.</param>
		/// <param name="targetPlayerId">The NetID of the player that is targeted, if the potion was used outside of combat.</param>
		/// <param name="isCombatInProgress">Whether or not combat was in progress when the potion was used.</param>
		public UsePotionAction(Player player, uint potionIndex, uint? targetId, ulong? targetPlayerId, bool isCombatInProgress)
		{
			Player = player;
			PotionIndex = potionIndex;
			TargetId = targetId;
			TargetPlayerId = targetPlayerId;
			WasEnqueuedInCombat = isCombatInProgress;
		}

		protected override async Task ExecuteAction()
		{
			PotionModel potion = Player.GetPotionAtSlotIndex((int)PotionIndex);
			if (potion == null)
			{
				Log.Warn($"{"UsePotionAction"}: potion at index {PotionIndex} is null for player {Player.NetId}, canceling");
				Cancel();
				return;
			}
			Creature creature = null;
			if (CombatManager.Instance.IsInProgress)
			{
				creature = ((TargetId.HasValue || !potion.TargetType.IsSingleTarget()) ? (await Player.Creature.CombatState.GetCreatureAsync(TargetId, 10.0)) : Player.Creature);
			}
			else if (!TargetPlayerId.HasValue && potion.TargetType != TargetType.TargetedNoCreature)
			{
				creature = Player.Creature;
			}
			else if (TargetPlayerId.HasValue)
			{
				creature = Player.RunState.GetPlayer(TargetPlayerId.Value).Creature;
			}
			if (!potion.IsValidTarget(creature))
			{
				Cancel();
				return;
			}
			string value = ((creature != null) ? $"targeting {creature.LogName} (index {Player.Creature.CombatState?.Creatures.IndexOf(creature)})" : "no target");
			Log.Info($"Player {potion.Owner.NetId} using potion {potion.Id.Entry} ({value})");
			PlayerChoiceContext = new GameActionPlayerChoiceContext(this);
			await potion.OnUseWrapper(PlayerChoiceContext, creature);
		}

		protected override void CancelAction()
		{
			PotionModel potionAtSlotIndex = Player.GetPotionAtSlotIndex((int)PotionIndex);
			if (TestMode.IsOff && NRun.Instance != null && LocalContext.IsMe(Player) && potionAtSlotIndex != null)
			{
				NRun.Instance.GlobalUi.TopBar.PotionContainer.OnPotionUseOrDiscardCanceled(potionAtSlotIndex);
			}
			potionAtSlotIndex?.AfterUsageCanceled();
		}

		public override INetAction ToNetAction()
		{
			return new NetUsePotionAction
			{
				potionIndex = PotionIndex,
				targetId = TargetId,
				targetPlayerId = TargetPlayerId,
				enqueuedInCombat = WasEnqueuedInCombat
			};
		}

		public override string ToString()
		{
			PotionModel potionAtSlotIndex = Player.GetPotionAtSlotIndex((int)PotionIndex);
			Creature value = Player.Creature.CombatState?.GetCreature(TargetId);
			return $"{"UsePotionAction"} {Player.NetId} {potionAtSlotIndex} index: {PotionIndex} target: {TargetId} ({value}) combat: {WasEnqueuedInCombat}";
		}
	}
	public struct NetUsePotionAction : INetAction, IPacketSerializable
	{
		public uint potionIndex;

		public uint? targetId;

		public ulong? targetPlayerId;

		public bool enqueuedInCombat;

		public GameAction ToGameAction(Player player)
		{
			return new UsePotionAction(player, potionIndex, targetId, targetPlayerId, enqueuedInCombat);
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteUInt(potionIndex, 4);
			writer.WriteBool(enqueuedInCombat);
			writer.WriteBool(targetId.HasValue);
			if (targetId.HasValue)
			{
				writer.WriteUInt(targetId.GetValueOrDefault(), 6);
			}
			writer.WriteBool(targetPlayerId.HasValue);
			if (targetPlayerId.HasValue)
			{
				writer.WriteULong(targetPlayerId.Value);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			potionIndex = reader.ReadUInt(4);
			enqueuedInCombat = reader.ReadBool();
			if (reader.ReadBool())
			{
				targetId = reader.ReadUInt(6);
			}
			else
			{
				targetId = null;
			}
			if (reader.ReadBool())
			{
				targetPlayerId = reader.ReadULong();
			}
			else
			{
				targetPlayerId = null;
			}
		}

		public override string ToString()
		{
			return $"NetUsePotionAction {potionIndex} target: {targetId} player: {targetPlayerId} combat: {enqueuedInCombat}";
		}
	}
	/// <summary>
	/// An action enqueued at the map screen when the player picks/votes for a map coord to move to.
	/// Once all players have selected a map coord, the host decides which map coord to move to based on the votes. It then
	/// enqueues MoveToMapCoordAction which triggers entering the room.
	/// This action may be enqueued multiple times with the same origin location, and should overwrite which coord the owning
	/// player is voting for. If it is enqueued after MoveToMapCoordAction has already been executed, then it should be
	/// ignored.
	/// </summary>
	public class VoteForMapCoordAction : GameAction
	{
		/// <summary>
		/// The player who is voting.
		/// </summary>
		private readonly Player _player;

		/// <summary>
		/// The location that the player is currently at while casting the vote.
		/// </summary>
		private readonly MapLocation _source;

		/// <summary>
		/// The player's vote. If null, any existing votes for the player should be cancelled.
		/// </summary>
		private readonly MapVote? _destination;

		public override ulong OwnerId => _player.NetId;

		public override GameActionType ActionType => GameActionType.Any;

		public VoteForMapCoordAction(Player player, MapLocation source, MapVote? destination)
		{
			_player = player;
			_source = source;
			_destination = destination;
		}

		protected override Task ExecuteAction()
		{
			RunManager.Instance.MapSelectionSynchronizer.PlayerVotedForMapCoord(_player, _source, _destination);
			return Task.CompletedTask;
		}

		public override INetAction ToNetAction()
		{
			return new NetVoteForMapCoordAction
			{
				source = _source,
				destination = _destination
			};
		}

		public override string ToString()
		{
			return $"{"VoteForMapCoordAction"} {_player.NetId} {_source}->{_destination}";
		}
	}
	public struct NetVoteForMapCoordAction : INetAction, IPacketSerializable
	{
		public MapLocation source;

		public MapVote? destination;

		public GameAction ToGameAction(Player player)
		{
			return new VoteForMapCoordAction(player, source, destination);
		}

		public void Serialize(PacketWriter writer)
		{
			writer.Write(source);
			writer.WriteBool(destination.HasValue);
			if (destination.HasValue)
			{
				writer.Write(destination.Value);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			source = reader.Read<MapLocation>();
			if (reader.ReadBool())
			{
				destination = reader.Read<MapVote>();
			}
		}

		public override string ToString()
		{
			return $"{"NetVoteForMapCoordAction"} {source}->{destination}";
		}
	}
	/// <summary>
