namespace MegaCrit.Sts2.Core.GameActions.Multiplayer
{
	/// <summary>
	/// Contains one action queue per player.
	/// We use multiple action queues to resolve the following scenario:
	/// - One player queues up three or more card plays, the second of which requires player choice
	/// - Their queue blocks on the player choice. The third action awaits completion of the player choice
	/// - Other players may freely queue card plays to their queues and have them executed
	/// </summary>
	public class ActionQueueSet
	{
		private class ActionQueue
		{
			public List<GameAction> actions = new List<GameAction>();

			public ulong ownerId;

			public GameAction? actionCancellingPlayCardActions;

			public bool isCancellingPlayerDrivenCombatActions;

			public bool isCancellingCombatActions = true;

			public bool isPaused;

			public bool IsCancellingPlayCardActions => actionCancellingPlayCardActions != null;
		}

		private struct ActionWaitingForResumption
		{
			public uint oldId;

			public uint newId;
		}

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		private readonly List<ActionQueue> _actionQueues = new List<ActionQueue>();

		private readonly List<ActionWaitingForResumption> _actionsWaitingForResumption = new List<ActionWaitingForResumption>();

		private TaskCompletionSource? _queuesEmptyCompletionSource;

		private uint _nextId;

		private bool _isInCombat;

		/// <summary>
		/// Set to true by <see cref="M:MegaCrit.Sts2.Core.GameActions.Multiplayer.ActionQueueSet.Reset" /> and back to false by <see cref="M:MegaCrit.Sts2.Core.GameActions.Multiplayer.ActionQueueSet.CombatStarted" />.
		/// This lets <see cref="M:MegaCrit.Sts2.Core.GameActions.Multiplayer.ActionQueueSet.PopAction(MegaCrit.Sts2.Core.GameActions.GameAction)" /> no-op for actions that were orphaned mid-execution when their queue was
		/// cleared out from under them.
		/// </summary>
		private bool _wasReset;

		public bool IsEmpty
		{
			get
			{
				if (_queuesEmptyCompletionSource != null)
				{
					return _queuesEmptyCompletionSource.Task.IsCompleted;
				}
				return true;
			}
		}

		public uint NextActionId => _nextId;

		public event Action? ActionQueueChanged;

		public event Action<GameAction>? ActionEnqueued;

		public event Action<uint>? ActionResumed;

		public ActionQueueSet(IReadOnlyList<Player> players)
		{
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("ActionQueueSet", LogType.Actions);
			foreach (Player player in players)
			{
				_actionQueues.Add(new ActionQueue
				{
					actions = new List<GameAction>(),
					ownerId = player.NetId
				});
			}
		}

		/// <summary>
		/// Only use this if you really know what you're doing! Improper use can lead to state divergence.
		/// Enqueues an action directly to the owner's action queue.
		/// </summary>
		/// <param name="gameAction">The action to enqueue.</param>
		public void EnqueueWithoutSynchronizing(GameAction gameAction)
		{
			if (_queuesEmptyCompletionSource == null || _queuesEmptyCompletionSource.Task.IsCompleted)
			{
				_queuesEmptyCompletionSource = new TaskCompletionSource();
			}
			if (gameAction.Id.HasValue)
			{
				throw new InvalidOperationException($"Attempting to enqueue GameAction {gameAction} which already has an ID {gameAction.Id}, indicating it was previously enqueued to the queue!");
			}
			gameAction.OnEnqueued(PopAction, GetAndIncrementActionId());
			ActionQueue queue = GetQueue(gameAction.OwnerId);
			try
			{
				ActionEnqueued?.Invoke(gameAction);
			}
			catch (Exception ex)
			{
				Log.Error($"Exception encountered in ActionEnqueued for action {gameAction}: {ex}");
				SentryService.CaptureException(ex);
			}
			if (queue.IsCancellingPlayCardActions && gameAction is PlayCardAction)
			{
				_logger.Debug($"Attempted to enqueue PlayCardAction {gameAction} to player queue owned by {gameAction.OwnerId}, but it's currently cancelling all play card actions due to player choice");
				gameAction.Cancel();
				return;
			}
			if (queue.isCancellingPlayerDrivenCombatActions && IsGameActionPlayerDriven(gameAction) && gameAction.ActionType != GameActionType.NonCombat && gameAction.ActionType != GameActionType.Any)
			{
				_logger.Debug($"Attempted to enqueue GameAction {gameAction} to player queue owned by {gameAction.OwnerId}, but it's currently cancelling all non-hook actions due to end of turn");
				gameAction.Cancel();
				return;
			}
			bool isCancellingCombatActions = queue.isCancellingCombatActions;
			bool flag = isCancellingCombatActions;
			if (flag)
			{
				GameActionType actionType = gameAction.ActionType;
				bool flag2 = (uint)(actionType - 1) <= 1u;
				flag = flag2;
			}
			if (flag)
			{
				_logger.Debug($"Attempted to enqueue GameAction {gameAction} to player queue owned by {gameAction.OwnerId}, but it's currently cancelling all combat actions");
				gameAction.Cancel();
			}
			else
			{
				_logger.Debug($"Enqueueing action {gameAction} to player queue owned by {gameAction.OwnerId}");
				queue.actions.Add(gameAction);
				ActionQueueChanged?.Invoke();
			}
		}

		/// <summary>
		/// Returns true if a GameAction is player driven, false if it is emitted automatically.
		/// If this ends up being used in a few different places, it can be moved somewhere else; for now, it's obscure enough
		/// that it should only be used here.
		/// </summary>
		/// <returns></returns>
		public static bool IsGameActionPlayerDriven(GameAction gameAction)
		{
			if (!(gameAction is GenericHookGameAction))
			{
				return !(gameAction is ReadyToBeginEnemyTurnAction);
			}
			return false;
		}

		/// <summary>
		/// Returns the next action on top of a player's queue that should be executed.
		/// Selection works like this:
		/// - If any player's queue is awaiting a player choice, then that queue is skipped.
		/// - Otherwise, we return the action with the minimum ID (the first queued by the host) at the top of any player's queue.
		/// This method should not be called when an action is already being executed.
		/// </summary>
		public GameAction? GetReadyAction()
		{
			GameAction gameAction = null;
			_logger.VeryDebug("Attempting to find ready action");
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				if (actionQueue.actions.Count <= 0)
				{
					_logger.VeryDebug($"Queue for player {actionQueue.ownerId} is empty");
					continue;
				}
				while (actionQueue.actions.Count > 0 && actionQueue.actions[0].State == GameActionState.Canceled)
				{
					_logger.Warn($"Removing canceled action {actionQueue.actions[0]} from front of player queue {actionQueue.ownerId}");
					actionQueue.actions.RemoveAt(0);
				}
				if (actionQueue.actions.Count <= 0)
				{
					continue;
				}
				GameAction gameAction2 = actionQueue.actions[0];
				if (_isInCombat && gameAction2.ActionType == GameActionType.NonCombat)
				{
					_logger.VeryDebug($"We are currently in combat and candidate action {gameAction2} has type {gameAction2.ActionType}");
					continue;
				}
				bool flag = !_isInCombat;
				bool flag2 = flag;
				if (flag2)
				{
					GameActionType actionType = gameAction2.ActionType;
					bool flag3 = (uint)(actionType - 1) <= 1u;
					flag2 = flag3;
				}
				if (flag2)
				{
					_logger.VeryDebug($"We are currently not in combat and candidate action {gameAction2} has type {gameAction2.ActionType}");
					continue;
				}
				if (actionQueue.isPaused && gameAction2.ActionType == GameActionType.CombatPlayPhaseOnly)
				{
					_logger.VeryDebug($"Queue for player {actionQueue.ownerId} is paused and candidate action {gameAction2} has type {gameAction2.ActionType}");
					continue;
				}
				if (gameAction2.State == GameActionState.GatheringPlayerChoice)
				{
					_logger.VeryDebug($"Action {gameAction2} at front of player queue {actionQueue.ownerId} is waiting for player choice");
					continue;
				}
				if (gameAction2.State != GameActionState.WaitingForExecution && gameAction2.State != GameActionState.ReadyToResumeExecuting)
				{
					throw new InvalidOperationException($"GameAction {gameAction2} at the front of player action queue {actionQueue.ownerId} is in invalid state {gameAction2.State}!");
				}
				if (gameAction == null || gameAction2.Id < gameAction.Id)
				{
					_logger.VeryDebug($"Action {gameAction2} with id {gameAction2.Id.Value} belonging to {actionQueue.ownerId} becomes new ready action");
					gameAction = gameAction2;
				}
				else
				{
					_logger.VeryDebug($"Action {gameAction2} has id {gameAction2.Id.Value} greater than current ready action {gameAction} with ID {gameAction.Id.Value}");
				}
			}
			if (gameAction != null)
			{
				_logger.VeryDebug($"Got ready action {gameAction} ({gameAction.Id})");
			}
			else
			{
				_logger.VeryDebug("No action is ready");
			}
			return gameAction;
		}

		/// <summary>
		/// Pauses an action for player choice. The action will be removed from the ActionExecutor and a new action will be
		/// allowed to execute, if there are any actions that are ready.
		/// To resume the action after this is called, call RequestResumeActionAfterPlayerChoice.
		/// </summary>
		/// <param name="action">The GameAction to pause.</param>
		/// <param name="options">Whether to cancel card play actions that enter the queue while obtaining player choice.</param>
		/// <exception cref="T:System.InvalidOperationException">Thrown if the action is not at the front of the owner's action queue.</exception>
		public void PauseActionForPlayerChoice(GameAction action, PlayerChoiceOptions options)
		{
			ActionQueue queue = GetQueue(action.OwnerId);
			if (action != queue.actions[0])
			{
				throw new InvalidOperationException($"Attempting to pause action {action} that is not at the front of the owner {action.Id}'s queue!");
			}
			_logger.Debug($"Pausing action {action} for player choice");
			action.PauseForPlayerChoice();
			ActionWaitingForResumption? actionWaitingForResumption = null;
			for (int i = 0; i < _actionsWaitingForResumption.Count; i++)
			{
				if (_actionsWaitingForResumption[i].oldId == action.Id)
				{
					actionWaitingForResumption = _actionsWaitingForResumption[i];
					_actionsWaitingForResumption.RemoveAt(i);
					break;
				}
			}
			if (options.HasFlag(PlayerChoiceOptions.CancelPlayCardActions))
			{
				CancelNonExecutingActionsOfType<PlayCardAction>(action.OwnerId, actionWaitingForResumption?.newId);
				queue.actionCancellingPlayCardActions = action;
			}
			ActionQueueChanged?.Invoke();
			if (actionWaitingForResumption.HasValue)
			{
				_logger.Debug($"Immediately resuming action {action} - already had resumption waiting");
				action.ResumeAfterGatheringPlayerChoice(actionWaitingForResumption.Value.newId);
				queue.actionCancellingPlayCardActions = null;
				ActionQueueChanged?.Invoke();
			}
		}

		/// <summary>
		/// Returns a task which completes when all player queues are empty.
		/// Be careful of running this in tests that involve player choice! If actions are not resumed, the task will never complete.
		/// </summary>
		public Task BecameEmpty()
		{
			if (_queuesEmptyCompletionSource == null)
			{
				return Task.CompletedTask;
			}
			return _queuesEmptyCompletionSource.Task;
		}

		/// <summary>
		/// Pauses execution of all actions on all player queues, including those that are queued after this is called.
		/// Note that this does not pause execution of the currently executing action - only those that come after it.
		/// </summary>
		public void PauseAllPlayerQueues()
		{
			_logger.Debug("Pausing all player queues");
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				actionQueue.isPaused = true;
				actionQueue.isCancellingPlayerDrivenCombatActions = false;
			}
			ActionQueueChanged?.Invoke();
		}

		/// <summary>
		/// Cancels all manual combat actions that are enqueued to all queues.
		/// Manual combat actions are any GameActions that have ActionType != GameActionType.NonCombat and ActionType !=
		/// GameActionType.Any, and are manually played by the player (i.e. everything except for GenericHookGameAction and
		/// ReadyToSwitchToEnemyTurnAction). The flag becomes unset when either PauseAllPlayerQueues or UnpauseAllPlayerQueues
		/// is called.
		/// See the comments in EnqueueWithoutSynchronizing for why this is necessary.
		/// </summary>
		public void StartCancellingAllPlayerDrivenCombatActions()
		{
			_logger.Debug("Setting all player queues to cancel all non-hook actions");
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				actionQueue.isCancellingPlayerDrivenCombatActions = true;
				for (int i = 0; i < actionQueue.actions.Count; i++)
				{
					GameAction gameAction = actionQueue.actions[i];
					if (IsGameActionPlayerDriven(gameAction) && gameAction.ActionType != GameActionType.NonCombat && gameAction.ActionType != GameActionType.Any && gameAction.State == GameActionState.WaitingForExecution)
					{
						_logger.VeryDebug($"Cancelling non-hook action {actionQueue.actions[i]}");
						gameAction.Cancel();
						actionQueue.actions.RemoveAt(i);
						i--;
					}
				}
			}
		}

		/// <returns>Returns true if the action queue for the given player is paused.</returns>
		public bool ActionQueueIsPaused(ulong playerId)
		{
			return GetQueue(playerId).isPaused;
		}

		/// <summary>
		/// Resumes execution of all player queues without synchronization.
		/// It's fine to call this at the end of combat, but call this very carefully during combat, as incorrect usage
		/// can lead to state divergences.
		/// </summary>
		public void UnpauseAllPlayerQueues()
		{
			_logger.Debug("Unpausing all player queues");
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				actionQueue.isPaused = false;
				actionQueue.isCancellingPlayerDrivenCombatActions = false;
			}
			ActionQueueChanged?.Invoke();
		}

		/// <summary>
		/// Cancels all combat actions on the queue and continues cancelling them until CombatStarted is called.
		/// </summary>
		public void CombatEnded()
		{
			_logger.Debug("Combat ended. Cancelling all non-executing combat actions in all queues");
			_isInCombat = false;
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				for (int i = 0; i < actionQueue.actions.Count; i++)
				{
					GameAction gameAction = actionQueue.actions[i];
					GameActionType actionType = gameAction.ActionType;
					bool flag = (uint)(actionType - 1) <= 1u;
					if (flag && gameAction.State != GameActionState.Executing)
					{
						_logger.VeryDebug($"Cancelling action {gameAction}");
						gameAction.Cancel();
						actionQueue.actions.RemoveAt(i);
						i--;
					}
					else
					{
						_logger.VeryDebug($"Not cancelling action {gameAction}, type: {gameAction.ActionType}, state: {gameAction.State}");
					}
				}
				actionQueue.actionCancellingPlayCardActions = null;
				actionQueue.isCancellingPlayerDrivenCombatActions = false;
				actionQueue.isCancellingCombatActions = true;
			}
			CheckIfQueuesEmpty();
			ActionQueueChanged?.Invoke();
		}

		/// <summary>
		/// Allows combat actions to be added to player queues, but not be executed.
		/// </summary>
		public void SetUpForCombat()
		{
			_logger.Debug("Setting up for combat.");
			_wasReset = false;
			_isInCombat = false;
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				actionQueue.isCancellingCombatActions = false;
			}
		}

		/// <summary>
		/// Allows combat actions to start executing.
		/// </summary>
		public void CombatStarted()
		{
			_logger.Debug("Combat started.");
			_isInCombat = true;
			_wasReset = false;
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				actionQueue.isCancellingCombatActions = false;
			}
		}

		public void Reset()
		{
			_wasReset = true;
			_actionQueues.Clear();
			CheckIfQueuesEmpty();
			ActionQueueChanged?.Invoke();
		}

		/// <summary>
		/// Cancels all non-executing actions for a specific player's queue.
		/// </summary>
		public void CancelNonExecutingActionsForPlayer(ulong playerId)
		{
			_logger.Debug($"Cancelling all non-executing actions owned by {playerId}");
			ActionQueue queue = GetQueue(playerId);
			for (int i = 0; i < queue.actions.Count; i++)
			{
				if (queue.actions[i].State == GameActionState.WaitingForExecution)
				{
					_logger.VeryDebug($"Cancelling action {queue.actions[i]}");
					queue.actions[i].Cancel();
					queue.actions.RemoveAt(i);
					i--;
				}
			}
			CheckIfQueuesEmpty();
		}

		/// <summary>
		/// Cancel all queued actions of the specified type owned by a specific player.
		/// Used when we are selecting a card, e.g. for Survivor, but cards have been queued up for play.
		/// Note that this does not cancel the action at the front of the queue if it is executing.
		/// This is private because the timing must be synchronized with action enqueues across peers.
		/// </summary>
		/// <typeparam name="T">Type of actions to cancel.</typeparam>
		/// <param name="ownerId">The owner of the actions to cancel.</param>
		/// <param name="maxActionId">If non-null, only actions with ID less than this value will be cancelled.</param>
		private void CancelNonExecutingActionsOfType<T>(ulong ownerId, uint? maxActionId) where T : GameAction
		{
			_logger.Debug($"Cancelling non-executing actions of type {typeof(T)} owned by {ownerId}");
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				if (actionQueue.ownerId != ownerId)
				{
					continue;
				}
				for (int i = 0; i < actionQueue.actions.Count; i++)
				{
					GameAction gameAction = actionQueue.actions[i];
					if (gameAction is T && gameAction.State == GameActionState.WaitingForExecution && (!maxActionId.HasValue || !(gameAction.Id.Value >= maxActionId)))
					{
						_logger.VeryDebug($"Cancelling action {actionQueue.actions[i]}");
						gameAction.Cancel();
						actionQueue.actions.RemoveAt(i);
						i--;
					}
				}
			}
			CheckIfQueuesEmpty();
		}

		/// <summary>
		/// Resumes a GameAction after a player choice. This should never be called anywhere other than ActionQueueSynchronizer.
		/// </summary>
		public void ResumeActionWithoutSynchronizing(uint id)
		{
			ActionResumed?.Invoke(id);
			uint andIncrementActionId = GetAndIncrementActionId();
			if (TryGetAction(id, out GameAction gameAction, out ActionQueue queue) && gameAction.State == GameActionState.GatheringPlayerChoice)
			{
				_logger.Debug($"Resuming action {gameAction} after player choice");
				queue.actionCancellingPlayCardActions = null;
				gameAction.ResumeAfterGatheringPlayerChoice(andIncrementActionId);
				ActionQueueChanged?.Invoke();
			}
			else
			{
				_logger.Debug($"Action with id {id} is not ready to resume, enqueueing resumption");
				ActionWaitingForResumption item = new ActionWaitingForResumption
				{
					oldId = id,
					newId = andIncrementActionId
				};
				_actionsWaitingForResumption.Add(item);
			}
		}

		/// <summary>
		/// Obtains an action by its ID.
		/// </summary>
		private bool TryGetAction(uint id, out GameAction? gameAction, out ActionQueue? queue)
		{
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				foreach (GameAction action in actionQueue.actions)
				{
					if (action.Id == id)
					{
						queue = actionQueue;
						gameAction = action;
						return true;
					}
				}
			}
			queue = null;
			gameAction = null;
			return false;
		}

		/// <summary>
		/// Obtains an action queue by its owner's ID.
		/// </summary>
		private ActionQueue GetQueue(ulong playerId)
		{
			ActionQueue actionQueue = _actionQueues.FirstOrDefault((ActionQueue q) => q.ownerId == playerId);
			if (actionQueue == null)
			{
				throw new InvalidOperationException($"Tried to get local action queue for nonexistent player with ID {playerId}!");
			}
			return actionQueue;
		}

		/// <summary>
		/// Removes an action from the front of its owner's queue. Should be called when an action finishes execution.
		/// </summary>
		private void PopAction(GameAction action)
		{
			if (_wasReset)
			{
				return;
			}
			bool flag = false;
			foreach (ActionQueue actionQueue in _actionQueues)
			{
				if (actionQueue.actions.Count == 0)
				{
					continue;
				}
				if (actionQueue.actions[0] == action)
				{
					flag = true;
					actionQueue.actions.RemoveAt(0);
					if (actionQueue.actionCancellingPlayCardActions == action)
					{
						_logger.Debug($"Action {action} left the queue while still cancelling play card actions. No longer cancelling them.");
						actionQueue.actionCancellingPlayCardActions = null;
					}
					continue;
				}
				foreach (GameAction action2 in actionQueue.actions)
				{
					if (action2 == action)
					{
						throw new InvalidOperationException($"Tried to pop action {action}, but it is not the top-most action for player {actionQueue.ownerId}!");
					}
				}
			}
			if (flag)
			{
				ActionQueueChanged?.Invoke();
				if (action.Exception != null)
				{
					_queuesEmptyCompletionSource?.SetException(action.Exception);
				}
				else
				{
					CheckIfQueuesEmpty();
				}
				return;
			}
			throw new InvalidOperationException($"Tried to pop action {action}, but we didn't find it in any queue!");
		}

		/// <summary>
		/// Used in replays so that we start with the correct action ID when replaying actions.
		/// </summary>
		/// <param name="nextId">The ID to assign to the next action.</param>
		public void FastForwardNextActionId(uint nextId)
		{
			_nextId = nextId;
		}

		/// <summary>
		/// Checks if all action queues are empty and sets the completion source for tests that wait.
		/// </summary>
		private void CheckIfQueuesEmpty()
		{
			if (!_actionQueues.All((ActionQueue q) => q.actions.Count == 0))
			{
				return;
			}
			TaskCompletionSource queuesEmptyCompletionSource = _queuesEmptyCompletionSource;
			if (queuesEmptyCompletionSource != null)
			{
				Task task = queuesEmptyCompletionSource.Task;
				if (task != null && !task.IsCompleted)
				{
					_queuesEmptyCompletionSource?.SetResult();
				}
			}
		}

		/// <summary>
		/// Called when an action is enqueued or resumed.
		/// It is extremely important that this message is called deterministically across all peers. Action IDs are not
		/// synchronized across the network; since all action messages (enqueue/resume) are received in the same order that
		/// they are sent, we can trust that all peers will generate the same action IDs.
		///
		/// Note that we re-assign an ID to an action when it becomes ready. The reason we do this is to avoid subtle timing
		/// bugs with message ready timings. Re-assigning the ID to an ID that is greater than all actions currently in the
		/// queue ensures that the existing actions in the queue will execute in a deterministic fashion, and the newly ready
		/// action will execute after them.
		/// </summary>
		private uint GetAndIncrementActionId()
		{
			uint nextId = _nextId;
			_nextId++;
			return nextId;
		}
	}
	/// <summary>
	/// Responsible for synchronizing actions across all peers in a deterministically-ordered manner.
	/// </summary>
	public class ActionQueueSynchronizer
	{
		private readonly ActionQueueSet _actionQueueSet;

		private readonly INetGameService _netService;

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger;

		private readonly IPlayerCollection _playerCollection;

		private readonly RunLocationTargetedMessageBuffer _messageBuffer;

		private readonly List<GenericHookGameAction> _hookActions = new List<GenericHookGameAction>();

		private uint _nextHookId;

		/// <summary>
		/// This list contains actions that were queued during the enemy turn or draw phase, but can only be executed during
		/// the player's play phase.
		/// </summary>
		private readonly List<GameAction> _requestedActionsWaitingForPlayerTurn = new List<GameAction>();

		/// <summary>
		/// Next ID assigned to hook actions. Exposed only so the combat replay writer has access to it.
		/// </summary>
		public uint NextHookId => _nextHookId;

		/// <summary>
		/// Current combat state. Dictates the paused state of queues.
		/// </summary>
		public ActionSynchronizerCombatState CombatState { get; private set; }

		public ActionQueueSynchronizer(IPlayerCollection players, ActionQueueSet actionQueueSet, RunLocationTargetedMessageBuffer messageBuffer, INetGameService netService)
		{
			_playerCollection = players;
			_actionQueueSet = actionQueueSet;
			_netService = netService;
			_messageBuffer = messageBuffer;
			_messageBuffer.RegisterMessageHandler<RequestEnqueueActionMessage>(HandleRequestEnqueueActionMessage);
			_messageBuffer.RegisterMessageHandler<ActionEnqueuedMessage>(HandleActionEnqueuedMessage);
			_messageBuffer.RegisterMessageHandler<RequestEnqueueHookActionMessage>(HandleRequestEnqueueHookActionMessage);
			_messageBuffer.RegisterMessageHandler<HookActionEnqueuedMessage>(HandleHookActionEnqueuedMessage);
			_messageBuffer.RegisterMessageHandler<RequestResumeActionAfterPlayerChoiceMessage>(HandleRequestResumeActionAfterPlayerChoiceMessage);
			_messageBuffer.RegisterMessageHandler<ResumeActionAfterPlayerChoiceMessage>(HandleResumeActionAfterPlayerChoiceMessage);
			_logger = new MegaCrit.Sts2.Core.Logging.Logger("ActionQueueSynchronizer", LogType.Actions);
		}

		public void Dispose()
		{
			_messageBuffer.UnregisterMessageHandler<RequestEnqueueActionMessage>(HandleRequestEnqueueActionMessage);
			_messageBuffer.UnregisterMessageHandler<ActionEnqueuedMessage>(HandleActionEnqueuedMessage);
			_messageBuffer.UnregisterMessageHandler<RequestEnqueueHookActionMessage>(HandleRequestEnqueueHookActionMessage);
			_messageBuffer.UnregisterMessageHandler<HookActionEnqueuedMessage>(HandleHookActionEnqueuedMessage);
			_messageBuffer.UnregisterMessageHandler<RequestResumeActionAfterPlayerChoiceMessage>(HandleRequestResumeActionAfterPlayerChoiceMessage);
			_messageBuffer.UnregisterMessageHandler<ResumeActionAfterPlayerChoiceMessage>(HandleResumeActionAfterPlayerChoiceMessage);
		}

		/// <summary>
		/// Call this when combat begins, ends, or the turn changes within combat.
		/// Certain actions, like card plays or potion usages, should always occur after the hooks that execute at the start
		/// of the player turn. However, the player is able to queue these actions before their turn actually starts. The
		/// synchronizer holds onto those actions until the start of the player turn, and then it sends all of them out.
		/// </summary>
		/// <param name="combatState">The new combat state.</param>
		public void SetCombatState(ActionSynchronizerCombatState combatState)
		{
			if (CombatState == combatState)
			{
				return;
			}
			ActionSynchronizerCombatState combatState2 = CombatState;
			CombatState = combatState;
			bool flag = (uint)combatState2 <= 1u;
			bool flag2 = flag;
			bool flag3 = flag2;
			if (flag3)
			{
				bool flag4 = (uint)(combatState - 2) <= 2u;
				flag3 = flag4;
			}
			if (flag3)
			{
				_logger.Debug($"Combat becomes {combatState} from {combatState2}. Signaling queues that combat has begun");
				_actionQueueSet.CombatStarted();
			}
			switch (combatState)
			{
			case ActionSynchronizerCombatState.NotInCombat:
				_logger.Debug($"Combat state becomes {combatState}. Cancelling deferred actions and cancelling all remaining combat actions");
				_actionQueueSet.CombatEnded();
				_actionQueueSet.UnpauseAllPlayerQueues();
				foreach (GameAction item in _requestedActionsWaitingForPlayerTurn)
				{
					item.Cancel();
				}
				_requestedActionsWaitingForPlayerTurn.Clear();
				break;
			case ActionSynchronizerCombatState.PreCombatSetup:
				if (combatState2 == ActionSynchronizerCombatState.NotInCombat)
				{
					_logger.Debug($"Combat state becomes {combatState}. Allowing non-combat actions to execute, but not combat actions.");
					_actionQueueSet.SetUpForCombat();
				}
				break;
			case ActionSynchronizerCombatState.PlayPhase:
				_logger.Debug($"Combat state becomes {combatState}. Requesting {_requestedActionsWaitingForPlayerTurn.Count} actions and unpausing action queues");
				foreach (GameAction item2 in _requestedActionsWaitingForPlayerTurn)
				{
					RequestEnqueue(item2);
				}
				_requestedActionsWaitingForPlayerTurn.Clear();
				_actionQueueSet.UnpauseAllPlayerQueues();
				break;
			case ActionSynchronizerCombatState.EndTurnPhaseOne:
				_logger.Debug($"Combat state becomes {combatState} (from {combatState2}). Starting to cancel all player-driven actions");
				_actionQueueSet.StartCancellingAllPlayerDrivenCombatActions();
				break;
			case ActionSynchronizerCombatState.NotPlayPhase:
				_logger.Debug($"Combat state becomes {combatState}. Pausing all player queues");
				_actionQueueSet.PauseAllPlayerQueues();
				break;
			}
		}

		/// <summary>
		/// Main entry point for enqueueing a GameAction.
		/// If you are the host, the GameAction is directly enqueued, and a message is sent to notify clients about the action.
		/// If you are the client, the GameAction is not enqueued. Instead, a message is sent to the host to request that
		/// the action be enqueued. The host sends back a confirmation, preserving ordering of the action queues.
		/// </summary>
		public void RequestEnqueue(GameAction action)
		{
			if (action.ActionType == GameActionType.CombatPlayPhaseOnly && CombatState == ActionSynchronizerCombatState.NotPlayPhase)
			{
				_logger.Debug($"Attempted to request enqueue of action {action} during the enemy turn. Deferring the action until the player turn");
				_requestedActionsWaitingForPlayerTurn.Add(action);
				return;
			}
			switch (_netService.Type)
			{
			case NetGameType.Client:
			{
				_logger.Debug($"Sending message to host requesting to enqueue action {action} at {Log.Timestamp}");
				RequestEnqueueActionMessage message = new RequestEnqueueActionMessage
				{
					action = action.ToNetAction(),
					location = _messageBuffer.CurrentLocation
				};
				_netService.SendMessage(message);
				break;
			}
			case NetGameType.Singleplayer:
			case NetGameType.Host:
				EnqueueAction(action, _netService.NetId);
				break;
			}
		}

		public GenericHookGameAction GenerateHookAction(ulong ownerId, GameActionType gameActionType)
		{
			GenericHookGameAction hookActionForId = GetHookActionForId(_nextHookId, ownerId, gameActionType);
			_nextHookId++;
			return hookActionForId;
		}

		/// <summary>
		/// Requests that a GenericHookGameAction be enqueued.
		/// Hook game actions are a little different than normal game actions. They contain arbitrary logic that is executed
		/// as part of a hook. Since hooks are executed on all peers, we can identify the actions by an incrementing ID.
		/// If on host, the action is immediately enqueued and a message is sent to clients.
		/// If on client, a message is sent to the host, and the host sends a message back to confirm that the message is
		/// enqueued.
		/// </summary>
		/// <returns></returns>
		public void RequestEnqueueHookAction(GenericHookGameAction action)
		{
			switch (_netService.Type)
			{
			case NetGameType.Client:
			{
				_logger.Debug($"Sending message to host requesting to enqueue HOOK action with id {action.HookId} at {Log.Timestamp}");
				RequestEnqueueHookActionMessage message = new RequestEnqueueHookActionMessage
				{
					hookActionId = action.HookId,
					location = _messageBuffer.CurrentLocation,
					gameActionType = action.ActionType
				};
				_netService.SendMessage(message);
				break;
			}
			case NetGameType.Singleplayer:
			case NetGameType.Host:
				EnqueueHookAction(action);
				break;
			}
		}

		/// <summary>
		/// Requests that an action, paused for player choice, be resumed.
		/// If on the host, the action is immediately resumed and a message is sent to clients indicating this.
		/// If on a client, a message is sent to the host to ensure correct ordering, and the host sends a message back
		/// to confirm resumption of the action.
		/// </summary>
		/// <param name="action">The GameAction to resume.</param>
		public void RequestResumeActionAfterPlayerChoice(GameAction action)
		{
			switch (_netService.Type)
			{
			case NetGameType.Client:
			{
				_logger.Debug($"Sending message to host requesting resumption of action {action}, id {action.Id}, at {Log.Timestamp}");
				RequestResumeActionAfterPlayerChoiceMessage message = new RequestResumeActionAfterPlayerChoiceMessage
				{
					actionId = action.Id.Value,
					location = _messageBuffer.CurrentLocation
				};
				_netService.SendMessage(message);
				break;
			}
			case NetGameType.Singleplayer:
			case NetGameType.Host:
				ResumeActionAfterPlayerChoice(action.Id.Value);
				break;
			}
		}

		private void EnqueueAction(GameAction action, ulong actionOwnerId)
		{
			if (_netService.Type == NetGameType.Host)
			{
				_logger.Debug($"Sending message to clients to enqueue action {action} at {Log.Timestamp}");
				ActionEnqueuedMessage message = new ActionEnqueuedMessage
				{
					playerId = actionOwnerId,
					location = _messageBuffer.CurrentLocation,
					action = action.ToNetAction()
				};
				_netService.SendMessage(message);
			}
			_logger.Debug($"Enqueueing action {action} from owner {actionOwnerId}");
			_actionQueueSet.EnqueueWithoutSynchronizing(action);
		}

		private void EnqueueHookAction(GenericHookGameAction gameAction)
		{
			if (_netService.Type == NetGameType.Host)
			{
				_logger.Debug($"Sending message to clients to enqueue hook action {gameAction} at {Log.Timestamp}");
				HookActionEnqueuedMessage message = new HookActionEnqueuedMessage
				{
					hookActionId = gameAction.HookId,
					ownerId = gameAction.OwnerId,
					location = _messageBuffer.CurrentLocation,
					gameActionType = gameAction.ActionType
				};
				_netService.SendMessage(message);
			}
			_logger.Debug($"Enqueueing HOOK action with id {gameAction.HookId}");
			_actionQueueSet.EnqueueWithoutSynchronizing(gameAction);
		}

		/// <summary>
		/// Resumes a GameAction after a player choice. This call is synchronized, so it should only be called from the host
		/// or in response to messages.
		/// </summary>
		private void ResumeActionAfterPlayerChoice(uint id)
		{
			if (_netService.Type == NetGameType.Host)
			{
				_logger.Debug($"Sending message to clients to resume action id {id} at {Log.Timestamp}");
				ResumeActionAfterPlayerChoiceMessage message = new ResumeActionAfterPlayerChoiceMessage
				{
					actionId = id,
					location = _messageBuffer.CurrentLocation
				};
				_netService.SendMessage(message);
			}
			_logger.Debug($"Resuming action with ID {id}");
			_actionQueueSet.ResumeActionWithoutSynchronizing(id);
		}

		private void HandleRequestEnqueueActionMessage(RequestEnqueueActionMessage message, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received action enqueue request while not host!");
			}
			_logger.Debug($"Received request enqueue action for action {message.action} ({senderId}) at {Log.Timestamp}");
			GameAction action = NetActionToGameAction(message.action, senderId);
			EnqueueAction(action, senderId);
		}

		private void HandleActionEnqueuedMessage(ActionEnqueuedMessage message, ulong _)
		{
			if (_netService.Type != NetGameType.Client)
			{
				throw new InvalidOperationException("Received action enqueued message while not client!");
			}
			_logger.Debug($"Received handle action enqueued message {message} at {Log.Timestamp}");
			GameAction action = NetActionToGameAction(message.action, message.playerId);
			EnqueueAction(action, message.playerId);
		}

		private void HandleRequestEnqueueHookActionMessage(RequestEnqueueHookActionMessage message, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received hook action enqueue request while not host!");
			}
			_logger.Debug($"Received HOOK request enqueue action from {senderId}, hook id: {message.hookActionId}, at {Log.Timestamp}");
			GenericHookGameAction hookActionForId = GetHookActionForId(message.hookActionId, senderId, message.gameActionType);
			EnqueueHookAction(hookActionForId);
		}

		private void HandleHookActionEnqueuedMessage(HookActionEnqueuedMessage message, ulong _)
		{
			if (_netService.Type != NetGameType.Client)
			{
				throw new InvalidOperationException("Received hook action enqueued message while not host!");
			}
			_logger.Debug($"Received HOOK request enqueue action, hook id: {message.hookActionId}, at {Log.Timestamp}");
			GenericHookGameAction hookActionForId = GetHookActionForId(message.hookActionId, message.ownerId, message.gameActionType);
			EnqueueHookAction(hookActionForId);
		}

		/// <summary>
		/// Called on the host when a client wishes to resume an action after a player choice is made.
		/// </summary>
		private void HandleRequestResumeActionAfterPlayerChoiceMessage(RequestResumeActionAfterPlayerChoiceMessage afterPlayerChoiceMessage, ulong senderId)
		{
			if (_netService.Type != NetGameType.Host)
			{
				throw new InvalidOperationException("Received action ready request message while not host!");
			}
			_logger.Debug($"Received action ready request message for action {afterPlayerChoiceMessage.actionId}, sender {senderId}, at {Log.Timestamp}");
			ResumeActionAfterPlayerChoice(afterPlayerChoiceMessage.actionId);
		}

		/// <summary>
		/// Called on the client when a host resumes an action.
		/// </summary>
		private void HandleResumeActionAfterPlayerChoiceMessage(ResumeActionAfterPlayerChoiceMessage afterPlayerChoiceMessage, ulong _)
		{
			if (_netService.Type != NetGameType.Client)
			{
				throw new InvalidOperationException("Received action ready message while not client!");
			}
			_logger.Debug($"Received action ready message for action {afterPlayerChoiceMessage.actionId} at {Log.Timestamp}");
			ResumeActionAfterPlayerChoice(afterPlayerChoiceMessage.actionId);
		}

		private GameAction NetActionToGameAction(INetAction action, ulong actionOwnerId)
		{
			Player player = _playerCollection.GetPlayer(actionOwnerId);
			if (player == null)
			{
				throw new InvalidOperationException($"Action owner ID {actionOwnerId} for action {action} could not be mapped to a Player!");
			}
			return action.ToGameAction(player);
		}

		/// <summary>
		/// This should only ever be called outside this class in replay playback!
		/// </summary>
		public GenericHookGameAction GetHookActionForId(uint id, ulong ownerId, GameActionType gameActionType)
		{
			GenericHookGameAction action = _hookActions.Find((GenericHookGameAction a) => a.HookId == id);
			if (action == null)
			{
				action = new GenericHookGameAction(id, ownerId, gameActionType);
				TaskHelper.RunSafely(action.ExecutionStartedTask.ContinueWith(delegate
				{
					HookActionStarted(action);
				}));
				_hookActions.Add(action);
			}
			else
			{
				if (action.OwnerId != ownerId)
				{
					throw new InvalidOperationException($"Attempted to get hook for owner {ownerId} with hook ID {id}, but the hook already existed and had owner {action.OwnerId}!");
				}
				if (action.ActionType != gameActionType)
				{
					throw new InvalidOperationException($"Generating GenericHookGameAction with type {gameActionType}. Found one already enqueued, but with a mismatching game action type {action.ActionType}!");
				}
			}
			return action;
		}

		private void HookActionStarted(GenericHookGameAction action)
		{
			_hookActions.Remove(action);
		}

		public void FastForwardHookId(uint hookId)
		{
			_nextHookId = hookId;
		}
	}
	public static class ActionTypes
	{
		private static NetTypeCache<INetAction>? _cache;

		public static void Initialize()
		{
			List<Type> list = new List<Type>();
			list.AddRange(INetActionSubtypes.All);
			list.AddRange(ReflectionHelper.GetSubtypesInMods<INetAction>());
			_cache = new NetTypeCache<INetAction>(list);
		}

		public static int TypeToId<T>() where T : INetAction
		{
			return (_cache ?? throw new InvalidOperationException()).TypeToId<T>();
		}

		private static int TypeToId(Type type)
		{
			return (_cache ?? throw new InvalidOperationException()).TypeToId(type);
		}

		public static int ToId(this INetAction message)
		{
			return (_cache ?? throw new InvalidOperationException()).TypeToId(message.GetType());
		}

		public static bool TryGetActionType(int id, out Type? type)
		{
			return (_cache ?? throw new InvalidOperationException()).TryGetTypeFromId(id, out type);
		}
	}
	/// <summary>
	/// For use when we don't care if player choice blocks the task.
	/// In almost all combat-related scenarios, we use HookPlayerChoiceContext to unblock other player queues when a player
	/// choice is made. However, there are several scenarios in which we can't do so:
	///  - Relic AfterObtained callbacks. The only way these can occur during combat is via console.
	///  - Enemy turn. When it's the enemy turn, we want to block the rest of the enemy turn from executing until after the
	///    player has finished making their choice. This should only happen in very rare circumstances, like when Centennial
	///    Puzzle triggers, drawing a Seeking Strike which is then autoplayed via Hellraiser.
	///
	/// In all other circumstances, you should prefer either HookPlayerChoiceContext or ThrowingPlayerChoiceContext,
	/// depending on the situation.
	/// </summary>
	public class BlockingPlayerChoiceContext : PlayerChoiceContext
	{
		public override ulong? OwnerId => null;

		public override Task SignalPlayerChoiceBegun(Player chooser, PlayerChoiceOptions options)
		{
			return Task.CompletedTask;
		}

		public override Task SignalPlayerChoiceEnded()
		{
			return Task.CompletedTask;
		}
	}
	/// <summary>
	/// A player choice context used when there is an existing player choice context, but we might begin a player choice for
	/// a different player.
	///
	/// If there is a GameAction in progress, and we're executing within it, then a choice for the non-owning player will
	/// block the OWNING player's queue by default. For example, if I throw a Skill Potion at another player, then it will
	/// block MY actions, and not the other player's. This is undesirable for several reasons:
	///  - I can't play cards while you're making a choice.
	///  - I might open a new choice screen for you while you're already looking at one.
	///
	/// The BranchingPlayerChoiceContext exists to solve these problems. If a new choice begins, then:
	///  - If the choice is for the owning player, we continue with the existing choice context.
	///  - If the choice is for someone else, we create a new GameAction (via the HookPlayerChoiceContext) and use that new
	///    GameAction for execution of the player choice.
	///
	/// It is up to the caller to specify what the boundaries of execution for the new GameAction are, using
	/// AssignTaskAndWaitForPauseOrCompletion. For example, take Tutor:
	///  - We want everything after the player choice within OnPlay to execute on the CHOOSING player's queue...
	///  - But we want Hook.AfterCardPlayed to execute without waiting for that choice on the OWNING player's queue.
	/// Imagine if the owning player has Unceasing Top; we want that draw to take place before the choosing player makes
	/// their choice, so that the owning player is not awkwardly waiting for the choosing player. This is why the
	/// BranchingPlayerChoiceContext is passed the Task for CardModel.OnPlay, and not CardModel.OnPlayWrapper.
	///
	/// For a contrasting example, see Huddle Up. If its draws trigger an autoplay:
	///  - We want that specific set of draws to delay on the autoplay on the CHOOSING player's queue...
	///  - But we do not want that set of draws to delay other player's draws.
	///  - And if no draw triggers an autoplay, we want the entire group of draws to execute in one GameAction.
	/// It uses BranchingPlayerChoiceContext directly within its OnPlay to achieve this effect. Each CardPileCmd.Draw call
	/// creates its own BranchingPlayerChoiceContext, which surrounds only the Draw Task and not the entire CardModel.OnPlay.
	///
	/// With all that said, this API is very experimental and needs proving out in real testing. I think it's likely I have
	/// not thought through every single scenario.
	/// </summary>
	public class BranchingPlayerChoiceContext : PlayerChoiceContext
	{
		private PlayerChoiceContext _originalContext;

		private readonly GameActionType _gameActionType;

		private readonly ulong _localPlayerId;

		private HookPlayerChoiceContext? _createdContext;

		private TaskCompletionSource _pausedCompletionSource = new TaskCompletionSource();

		public AbstractModel? Source { get; }

		public override ulong? OwnerId => _originalContext.OwnerId;

		public event Action<HookPlayerChoiceContext>? AfterBranched;

		public BranchingPlayerChoiceContext(ulong localPlayerId, GameActionType gameActionType, PlayerChoiceContext existing)
		{
			_originalContext = existing;
			_gameActionType = gameActionType;
			_localPlayerId = localPlayerId;
		}

		public BranchingPlayerChoiceContext(AbstractModel source, ulong localPlayerId, GameActionType gameActionType, PlayerChoiceContext existing)
		{
			_originalContext = existing;
			_gameActionType = gameActionType;
			_localPlayerId = localPlayerId;
			Source = source;
		}

		public override async Task SignalPlayerChoiceBegun(Player chooser, PlayerChoiceOptions options)
		{
			PlayerChoiceContext playerChoiceContext;
			if (!_originalContext.OwnerId.HasValue || chooser.NetId == _originalContext.OwnerId)
			{
				if (!_originalContext.OwnerId.HasValue)
				{
					Log.LogMessage(LogLevel.Debug, LogType.GameSync, $"Branching context began choice for {chooser.NetId} and there is no owner. Using existing {_originalContext}");
				}
				playerChoiceContext = _originalContext;
			}
			else if (_createdContext != null)
			{
				Log.Warn($"{"BranchingPlayerChoiceContext"} has been used twice! We switched owners from {_originalContext.OwnerId} to {_createdContext.OwnerId}, and now we are trying to switch to {chooser.NetId}. Re-using the existing created context.");
				playerChoiceContext = _createdContext;
			}
			else
			{
				Log.LogMessage(LogLevel.Debug, LogType.GameSync, $"Branching context began choice for {chooser.NetId} who is not the owner ({_originalContext.OwnerId}). Using new {"HookPlayerChoiceContext"}");
				if (Source != null)
				{
					_createdContext = new HookPlayerChoiceContext(Source, chooser, _localPlayerId, _gameActionType);
				}
				else
				{
					_createdContext = new HookPlayerChoiceContext(chooser, _localPlayerId, _gameActionType);
				}
				AfterBranched?.Invoke(_createdContext);
				_pausedCompletionSource.SetResult();
				playerChoiceContext = _createdContext;
			}
			await playerChoiceContext.SignalPlayerChoiceBegun(chooser, options);
		}

		public async Task AssignTaskAndWaitForPauseOrCompletion(Task task)
		{
			await TaskHelper.WhenAny(task, _pausedCompletionSource.Task);
			if (_pausedCompletionSource.Task.IsCompleted)
			{
				await _createdContext.AssignTaskAndWaitForPauseOrCompletion(task);
			}
		}

		public override Task SignalPlayerChoiceEnded()
		{
			return (_createdContext ?? _originalContext).SignalPlayerChoiceEnded();
		}
	}
	public class GameActionPlayerChoiceContext : PlayerChoiceContext
	{
		private ActionQueueSynchronizer? _actionQueueSynchronizer;

		private ActionQueueSet? _actionQueueSet;

		private ActionExecutor? _actionExecutor;

		public GameAction Action { get; }

		public override ulong? OwnerId => Action.OwnerId;

		private ActionQueueSynchronizer ActionQueueSynchronizer => _actionQueueSynchronizer ?? RunManager.Instance.ActionQueueSynchronizer;

		private ActionQueueSet ActionQueueSet => _actionQueueSet ?? RunManager.Instance.ActionQueueSet;

		private ActionExecutor ActionExecutor => _actionExecutor ?? RunManager.Instance.ActionExecutor;

		public GameActionPlayerChoiceContext(GameAction action)
		{
			Action = action;
		}

		public override Task SignalPlayerChoiceBegun(Player chooser, PlayerChoiceOptions options)
		{
			if (chooser.NetId != OwnerId)
			{
				Log.Warn($"{"GameActionPlayerChoiceContext"} is executing player choice owned by {chooser.NetId}, but the player choice began with owner {OwnerId}! This will work, but will likely result in some weird-looking user experience. See {"BlockingPlayerChoiceContext"} for a resolution.");
			}
			if (ActionExecutor != null && ActionExecutor.CurrentlyRunningAction != Action)
			{
				Log.Error($"Tried to interrupt shared queue action {ActionExecutor.CurrentlyRunningAction} with a player choice context with action {Action}!");
				return Task.CompletedTask;
			}
			ActionQueueSet.PauseActionForPlayerChoice(Action, options);
			return Task.CompletedTask;
		}

		public override async Task SignalPlayerChoiceEnded()
		{
			if (Action.OwnerId == LocalContext.NetId || TestFlags.ShouldSendResumeForRemotePlayers)
			{
				ActionQueueSynchronizer.RequestResumeActionAfterPlayerChoice(Action);
			}
			await Action.WaitForActionToResumeExecutingAfterPlayerChoice();
		}

		public void MockDependenciesForTest(ActionQueueSynchronizer? actionQueueSynchronizer, ActionQueueSet? actionQueueSet, ActionExecutor? actionExecutor)
		{
			_actionQueueSet = actionQueueSet;
			_actionQueueSynchronizer = actionQueueSynchronizer;
			_actionExecutor = actionExecutor;
		}
	}
	/// <summary>
	/// A player choice context for use when a separate GameAction is required upon player choice.
	///
	/// When player choice is required, a new game action is created and enqueued directly to the player's action queue.
	/// From there, flow proceeds like a normal game action. This is necessary to synchronize execution, so that the
	/// post-player-choice effects are deterministically executed across all peers. No new game action is created if player
	/// choice is not requested.
	///
	/// Note that this is also used outside of hooks, in the <see cref="T:MegaCrit.Sts2.Core.GameActions.Multiplayer.BranchingPlayerChoiceContext" />. It's likely that
	/// we should change the name of this class, but I'm not really sure what the new name should be yet.
	/// </summary>
	public class HookPlayerChoiceContext : PlayerChoiceContext
	{
		private readonly ulong _localPlayerId;

		private GenericHookGameAction? _gameAction;

		private readonly TaskCompletionSource _taskAssignedCompletionSource = new TaskCompletionSource();

		private readonly TaskCompletionSource _pausedBeforeTaskAssignedCompletionSource = new TaskCompletionSource();

		private readonly TaskCompletionSource _pausedCompletionSource = new TaskCompletionSource();

		private ActionQueueSynchronizer? _actionQueueSynchronizer;

		private ActionQueueSet? _actionQueueSet;

		private ActionExecutor? _actionExecutor;

		/// <summary>
		/// The GameActionType to assign to the GameAction generated by this context, if any. Currently, only Combat and
		/// CombatPlayPhaseOnly are supported.
		/// Many hooks can execute outside of the player turn. For example, we allow the following:
		///  - Centennial Puzzle triggers on the enemy turn
		///  - Hellraiser triggers Seeker Strike
		///  - Seeker Strike causes a player choice
		/// However, for actions that start just before the player turn, we must wait until the player turn before executing
		/// them. Otherwise, we may run into ordering issues on remote players. For full context, see the
		/// HookPlayerChoiceContextTest.
		/// </summary>
		private GameActionType _gameActionType;

		private ActionQueueSynchronizer ActionQueueSynchronizer => _actionQueueSynchronizer ?? RunManager.Instance.ActionQueueSynchronizer;

		private ActionQueueSet ActionQueueSet => _actionQueueSet ?? RunManager.Instance.ActionQueueSet;

		private ActionExecutor ActionExecutor => _actionExecutor ?? RunManager.Instance.ActionExecutor;

		public AbstractModel? Source { get; }

		public Task? Task { get; private set; }

		public Player? Owner { get; }

		public override ulong? OwnerId => Owner?.NetId;

		public GenericHookGameAction? GameAction => _gameAction;

		public HookPlayerChoiceContext(Player owner, ulong localPlayerId, GameActionType gameActionType)
		{
			_gameActionType = gameActionType;
			_localPlayerId = localPlayerId;
			Owner = owner;
		}

		public HookPlayerChoiceContext(AbstractModel source, Player owner, ulong localPlayerId, GameActionType gameActionType)
		{
			Source = source;
			_gameActionType = gameActionType;
			_localPlayerId = localPlayerId;
			Owner = owner;
		}

		public HookPlayerChoiceContext(AbstractModel source, ulong localPlayerId, ICombatState? combatState, GameActionType gameActionType)
		{
			_localPlayerId = localPlayerId;
			Source = source;
			Owner = GetOwner(source, combatState);
			PushModel(Source);
			_gameActionType = gameActionType;
		}

		public static Player? GetOwner(AbstractModel source, ICombatState? combatState)
		{
			Player player = ((source is CardModel cardModel) ? cardModel.Owner : ((source is RelicModel relicModel) ? relicModel.Owner : ((source is PotionModel potionModel) ? potionModel.Owner : ((source is AfflictionModel afflictionModel) ? afflictionModel.Card.Owner : ((source is EnchantmentModel enchantmentModel) ? enchantmentModel.Card.Owner : ((!(source is PowerModel powerModel)) ? null : powerModel.Owner.Player))))));
			Player player2 = player;
			if (player2 == null)
			{
				player2 = combatState?.Players.FirstOrDefault();
			}
			return player2;
		}

		public void MockDependenciesForTest(ActionQueueSynchronizer? actionQueueSynchronizer, ActionQueueSet? actionQueueSet, ActionExecutor? actionExecutor)
		{
			_actionQueueSet = actionQueueSet;
			_actionQueueSynchronizer = actionQueueSynchronizer;
			_actionExecutor = actionExecutor;
		}

		/// <summary>
		/// Most hooks take a PlayerChoiceContext as an argument and return a Task. However, this player choice context must
		/// know about the task in SignalPlayerChoiceBegun, when it is time to create a GameAction. There is no way to pass
		/// the Task to this method in the constructor, as the Task is not created yet. Thus, this method should be called
		/// after the hook returns the Task, for two reasons:
		/// - To assign the Task to this context
		/// - To wait for the synchronous parts of the hook to complete
		/// </summary>
		/// <returns>True if the task was completed, false if it was paused.</returns>
		public async Task<bool> AssignTaskAndWaitForPauseOrCompletion(Task task)
		{
			if (Source != null)
			{
				Task = ExecuteTaskThenInvokeExecutionFinished(task);
			}
			else
			{
				Task = task;
			}
			_taskAssignedCompletionSource.SetResult();
			await TaskHelper.WhenAny(task, _pausedCompletionSource.Task);
			return task.IsCompleted;
		}

		/// <summary>
		/// ONLY USE THIS IF YOU KNOW WHAT YOU'RE DOING!
		/// This waits for the task to complete, _or_ for some content in the task to call SignalPlayerChoiceBegun.
		/// In most cases, AssignTaskAndWaitForPauseOrCompletion should be used. This should only be used when we don't yet
		/// have the full task to assign to the GameAction that would be generated during SignalPlayerChoiceBegun.
		/// </summary>
		/// <returns>True if the task was completed, false if it was paused.</returns>
		public async Task<bool> WaitForPauseOrCompletionWithoutAssigningTask(Task task)
		{
			await TaskHelper.WhenAny(task, _pausedBeforeTaskAssignedCompletionSource.Task);
			return task.IsCompleted;
		}

		/// <summary>
		/// At the end of all hooks that involve models, the ExecutionFinished event must be executed to update some visuals
		/// for things that are listening to changes to the model. This task wraps the hook and calls ExecutionFinished at
		/// the end of it, if a model is involved with the hook.
		/// </summary>
		private async Task ExecuteTaskThenInvokeExecutionFinished(Task task)
		{
			await task;
			Source?.InvokeExecutionFinished();
		}

		public override async Task SignalPlayerChoiceBegun(Player chooser, PlayerChoiceOptions options)
		{
			if (chooser.NetId != OwnerId)
			{
				Log.Warn($"{"HookPlayerChoiceContext"} is executing player choice owned by {chooser.NetId}, but the player choice began with owner {OwnerId}! This will work, but will likely result in some weird-looking user experience. See {"BlockingPlayerChoiceContext"} for a resolution.");
			}
			if (_gameAction != null)
			{
				if (ActionExecutor != null && ActionExecutor.CurrentlyRunningAction != _gameAction)
				{
					Log.Error($"Tried to interrupt action {_gameAction} but the currently running action is {ActionExecutor.CurrentlyRunningAction}!");
					return;
				}
			}
			else
			{
				if (Owner == null)
				{
					throw new InvalidOperationException($"HookPlayerChoiceContext is assigned a model {Source} with no owner, but the model has requested a player choice! This is not supported");
				}
				_gameAction = ActionQueueSynchronizer.GenerateHookAction(chooser.NetId, _gameActionType);
				_pausedBeforeTaskAssignedCompletionSource.SetResult();
				if (Task == null)
				{
					await _taskAssignedCompletionSource.Task;
					if (Task == null)
					{
						throw new InvalidOperationException("HookPlayerChoiceContext was never passed a task to await!");
					}
				}
				_gameAction.SetChoiceContext(this);
				if (_gameAction.OwnerId == _localPlayerId || TestFlags.ShouldSendResumeForRemotePlayers)
				{
					ActionQueueSynchronizer.RequestEnqueueHookAction(_gameAction);
				}
				_pausedCompletionSource.SetResult();
				await _gameAction.ExecutionStartedTask;
			}
			ActionQueueSet.PauseActionForPlayerChoice(_gameAction, options);
		}

		public override async Task SignalPlayerChoiceEnded()
		{
			if (_gameAction.OwnerId == _localPlayerId || TestFlags.ShouldSendResumeForRemotePlayers)
			{
				ActionQueueSynchronizer.RequestResumeActionAfterPlayerChoice(_gameAction);
			}
			await _gameAction.WaitForActionToResumeExecutingAfterPlayerChoice();
		}

		public async Task WaitForCompletion()
		{
			if (Task == null)
			{
				throw new InvalidOperationException("Tried to call WaitForCompletion before AssignTaskAndWaitForPauseOrCompletion was called!");
			}
			await Task;
			if (GameAction != null)
			{
				await GameAction.CompletionTask;
			}
		}
	}
	[GenerateSubtypes]
	public interface INetAction : IPacketSerializable
	{
		GameAction ToGameAction(Player player);
	}
	public class NetCombatCardDb
	{
		private struct Subscription
		{
			public CardPile pile;

			public Action action;
		}

		private uint _nextId;

		private readonly System.Collections.Generic.Dictionary<uint, CardModel> _idToCard = new System.Collections.Generic.Dictionary<uint, CardModel>();

		private readonly System.Collections.Generic.Dictionary<CardModel, uint> _cardToId = new System.Collections.Generic.Dictionary<CardModel, uint>();

		private readonly List<Subscription> _subscriptions = new List<Subscription>();

		public static NetCombatCardDb Instance { get; } = new NetCombatCardDb();

		public void StartCombat(IReadOnlyList<Player> players)
		{
			_nextId = 0u;
			_idToCard.Clear();
			_cardToId.Clear();
			foreach (Player player in players)
			{
				if (player.PlayerCombatState == null && TestMode.IsOn)
				{
					continue;
				}
				foreach (CardModel item in player.PlayerCombatState.AllPiles.SelectMany((CardPile p) => p.Cards))
				{
					IdCardIfNecessary(item);
				}
				foreach (CardPile allPile in player.PlayerCombatState.AllPiles)
				{
					Subscription subscription = default(Subscription);
					subscription.pile = allPile;
					subscription.action = delegate
					{
						OnPileContentsChanged(subscription.pile);
					};
					_subscriptions.Add(subscription);
					allPile.ContentsChanged += subscription.action;
				}
			}
			CombatManager.Instance.CombatEnded += OnCombatEnded;
		}

		private void OnCombatEnded(CombatRoom _)
		{
			foreach (Subscription subscription in _subscriptions)
			{
				subscription.pile.ContentsChanged -= subscription.action;
			}
			_subscriptions.Clear();
			CombatManager.Instance.CombatEnded -= OnCombatEnded;
		}

		public uint GetCardId(CardModel card)
		{
			if (!TryGetCardId(card, out var id))
			{
				throw new InvalidOperationException($"Card {card} could not be found in combat ID database!");
			}
			return id;
		}

		public CardModel GetCard(uint id)
		{
			if (!TryGetCard(id, out CardModel card))
			{
				throw new InvalidOperationException($"Could not map ID {id} to any card!");
			}
			return card;
		}

		public bool TryGetCardId(CardModel card, out uint id)
		{
			if (!card.IsMutable)
			{
				throw new InvalidOperationException($"Tried to get ID for canonical card {card}! Use the ModelId instead");
			}
			return _cardToId.TryGetValue(card, out id);
		}

		public bool TryGetCard(uint id, out CardModel? card)
		{
			return _idToCard.TryGetValue(id, out card);
		}

		private void OnPileContentsChanged(CardPile pile)
		{
			foreach (CardModel card in pile.Cards)
			{
				IdCardIfNecessary(card);
			}
		}

		private void IdCardIfNecessary(CardModel card)
		{
			if (!_cardToId.ContainsKey(card))
			{
				if (card.Owner == null)
				{
					Log.Error($"Tried to ID combat card {card} without an owner! This is not allowed");
					return;
				}
				Log.LogMessage(LogLevel.Debug, LogType.Network, $"ID card {card} owned by {card.Owner.NetId} in pile {card.Pile?.Type} with id: {_nextId}");
				_cardToId[card] = _nextId;
				_idToCard[_nextId] = card;
				_nextId++;
			}
		}

		public uint IdCardForTesting(CardModel card)
		{
			IdCardIfNecessary(card);
			return _cardToId[card];
		}

		public void ClearCardsForTesting()
		{
			_nextId = 0u;
			_idToCard.Clear();
			_cardToId.Clear();
		}
	}
	public abstract class PlayerChoiceContext
	{
		/// <summary>
		/// A stack of models that are involved with this choice context.
		/// A model can invoke other models to do some work, and those models can invoke a player choice. For example, a
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Survivor" /> may autoplay a Sly'd <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Prepared" />. In these cases, when we display the context
		/// to remote players, we want to show the <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Prepared" /> as the model that is involved in the choice, not
		/// the <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Survivor" />.
		/// </summary>
		private Stack<AbstractModel>? _modelStack;

		public IEnumerable<AbstractModel>? ModelStack => _modelStack;

		public AbstractModel? LastInvolvedModel
		{
			get
			{
				Stack<AbstractModel>? modelStack = _modelStack;
				if (modelStack == null || !modelStack.TryPeek(out AbstractModel result))
				{
					return null;
				}
				return result;
			}
		}

		public abstract ulong? OwnerId { get; }

		/// <summary>
		/// Add a new model to the top of the context stack.
		/// For example, while <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Prepared" /> is executing, it will be at the top of the context stack.
		/// If it discards a card with <see cref="F:MegaCrit.Sts2.Core.Entities.Cards.CardKeyword.Sly" />, then the Sly'd card should be pushed to the top of
		/// the context stack.
		/// </summary>
		public void PushModel(AbstractModel model)
		{
			if (_modelStack == null)
			{
				_modelStack = new Stack<AbstractModel>();
			}
			_modelStack.Push(model);
		}

		public void PopModel(AbstractModel model)
		{
			AbstractModel result = null;
			if (_modelStack == null || !_modelStack.TryPeek(out result) || result != model)
			{
				Log.Error($"Tried to pop model {model} from stack of player choice context {this} but {result} was on the top of the stack instead! (Stack size: {_modelStack?.Count})");
			}
			else
			{
				_modelStack.Pop();
			}
		}

		public abstract Task SignalPlayerChoiceBegun(Player chooser, PlayerChoiceOptions options);

		public abstract Task SignalPlayerChoiceEnded();
	}
	public delegate Task<PlayerChoiceResult> PlayerChoiceDelegate();
	public delegate Task PlayerChoiceContinuation(PlayerChoiceResult result);
	/// <summary>
	/// Synchronizes player choices that are gathered in the middle of a model's execution. Examples:
	/// * The card picked for discarding when playing Survivor
	/// * The card chosen to add to hand when playing Discovery
	/// * The card chosen to add to hand at the beginning of combat from Toolbox
	///
	/// The basic scheme here is:
	/// * All players (local and remote) generate an ID for the selection.
	/// * The owning player brings up the card selection UI on their side.
	/// * Once the owning player has made a choice, they send a message to all other players with the selection ID indicating
	///   what they chose.
	/// </summary>
	public class PlayerChoiceSynchronizer : IDisposable
	{
		private struct ReceivedChoice
		{
			public ulong senderId;

			public uint choiceId;

			public TaskCompletionSource<NetPlayerChoiceResult> completionSource;
		}

		private readonly List<uint> _choiceIds = new List<uint>();

		private readonly List<ReceivedChoice> _receivedChoices = new List<ReceivedChoice>();

		private readonly MegaCrit.Sts2.Core.Logging.Logger _logger = new MegaCrit.Sts2.Core.Logging.Logger("PlayerChoiceSynchronizer", LogType.Actions);

		private readonly INetGameService _netService;

		private readonly IPlayerCollection _players;

		public IReadOnlyList<uint> ChoiceIds => _choiceIds;

		public event Action<Player, uint, NetPlayerChoiceResult>? PlayerChoiceReceived;

		public PlayerChoiceSynchronizer(INetGameService netService, IPlayerCollection players)
		{
			_players = players;
			_netService = netService;
			netService.RegisterMessageHandler<PlayerChoiceMessage>(OnPlayerChoiceMessageReceived);
		}

		public void Dispose()
		{
			_netService.UnregisterMessageHandler<PlayerChoiceMessage>(OnPlayerChoiceMessageReceived);
		}

		/// <summary>
		/// Reserves a choice ID to be passed to SyncLocalChoice or WaitForLocalChoice.
		/// If called during combat, this must be done in a deterministic context (i.e. before a GameAction is paused) so
		/// that checksums match up after action execution. SyncLocalChoice and WaitForRemoteChoice can be called outside of
		/// deterministic contexts (i.e. while a GameAction is paused and executing locally).
		/// </summary>
		/// <param name="player">The player for which the choice ID will be reserved.</param>
		public uint ReserveChoiceId(Player player)
		{
			int playerSlotIndex = _players.GetPlayerSlotIndex(player);
			while (_choiceIds.Count <= playerSlotIndex)
			{
				_choiceIds.Add(0u);
			}
			uint num = _choiceIds[playerSlotIndex];
			_choiceIds[playerSlotIndex] = num + 1;
			_logger.VeryDebug($"Reserved choice id {num} for player {player.NetId}, next is {_choiceIds[playerSlotIndex]}");
			return num;
		}

		/// <summary>
		/// Sync a locally-chosen player choice with other peers.
		/// This should be called whenever a player choice is made by the local player. In tandem, WaitForRemoteChoice
		/// should be awaited on all remote peers.
		/// </summary>
		/// <param name="player">The player that chose the player choice. Should always be the local player.</param>
		/// <param name="choiceId">The ID of the choice, reserved through ReserveChoiceId.</param>
		/// <param name="result">The result of the player choice.</param>
		public void SyncLocalChoice(Player player, uint choiceId, PlayerChoiceResult result)
		{
			if (!ValidateChoiceId(player, choiceId))
			{
				throw new InvalidOperationException($"Tried to sync local choice with ID {choiceId} for player {player.NetId}, but player's choice ID is {GetChoiceId(player)}!");
			}
			PlayerChoiceMessage message = new PlayerChoiceMessage
			{
				result = result.ToNetData(),
				choiceId = choiceId
			};
			_logger.Debug($"Sending player choice id {choiceId} for player {player.NetId}, result {result}");
			PlayerChoiceReceived?.Invoke(player, choiceId, message.result);
			_netService.SendMessage(message);
		}

		/// <summary>
		/// Waits for a choice to be received from a remote peer.
		/// This should be called on all remote peers whenever we expect a player choice to be made.
		/// On the machine of the player who is making a choice, SyncLocalChoice should be called.
		/// </summary>
		/// <param name="player">The player for whom we are awaiting a choice.</param>
		/// <param name="choiceId">The choice ID to await, obtained through ReserveChoiceId.</param>
		/// <returns>The result of the player choice that was made.</returns>
		public async Task<PlayerChoiceResult> WaitForRemoteChoice(Player player, uint choiceId)
		{
			if (_netService.Type == NetGameType.Singleplayer)
			{
				throw new InvalidOperationException("Cannot wait for remote choice in singleplayer!");
			}
			if (!ValidateChoiceId(player, choiceId))
			{
				throw new InvalidOperationException($"Tried to wait for remote choice with ID {choiceId} for player {player.NetId}, but player's choice ID is {GetChoiceId(player)}!");
			}
			int num = _receivedChoices.FindIndex((ReceivedChoice c) => c.choiceId == choiceId && c.senderId == player.NetId);
			ReceivedChoice item;
			if (num >= 0)
			{
				_logger.Debug($"Was going to wait for remote choice {choiceId} for player {player.NetId} but we've already received it");
				item = _receivedChoices[num];
				_receivedChoices.RemoveAt(num);
			}
			else
			{
				item = new ReceivedChoice
				{
					choiceId = choiceId,
					senderId = player.NetId,
					completionSource = new TaskCompletionSource<NetPlayerChoiceResult>()
				};
				_logger.Debug($"Awaiting remote choice {choiceId} for player {player.NetId}");
				_receivedChoices.Add(item);
			}
			NetPlayerChoiceResult netData = await item.completionSource.Task;
			PlayerChoiceResult playerChoiceResult = PlayerChoiceResult.FromNetData(player, _players, netData);
			_logger.Debug($"Finished waiting for remote choice {choiceId} for player {player.NetId}: {playerChoiceResult}");
			return playerChoiceResult;
		}

		private void OnPlayerChoiceMessageReceived(PlayerChoiceMessage message, ulong senderId)
		{
			_logger.Debug($"Received choice from {senderId} for choice ID {message.choiceId}: {message.result}");
			Player player = _players.GetPlayer(senderId);
			OnReceivePlayerChoice(player, message.choiceId, message.result);
		}

		public void FastForwardChoiceIds(List<uint> choiceIds)
		{
			_logger.Debug("Fast-forwarded choice IDs to: " + string.Join(",", choiceIds));
			_choiceIds.Clear();
			_choiceIds.AddRange(choiceIds);
		}

		public void ReceiveReplayChoice(Player player, uint choiceId, NetPlayerChoiceResult result)
		{
			OnReceivePlayerChoice(player, choiceId, result);
		}

		private void OnReceivePlayerChoice(Player player, uint choiceId, NetPlayerChoiceResult result)
		{
			PlayerChoiceReceived?.Invoke(player, choiceId, result);
			int num = _receivedChoices.FindIndex((ReceivedChoice c) => c.choiceId == choiceId && c.senderId == player.NetId);
			ReceivedChoice item;
			if (num >= 0)
			{
				_logger.Debug("We are already waiting for the choice, fulfilling the task");
				item = _receivedChoices[num];
				_receivedChoices.RemoveAt(num);
			}
			else
			{
				item = new ReceivedChoice
				{
					choiceId = choiceId,
					senderId = player.NetId,
					completionSource = new TaskCompletionSource<NetPlayerChoiceResult>()
				};
				_logger.Debug("We are not yet waiting for the choice, creating a new received choice");
				_receivedChoices.Add(item);
			}
			item.completionSource.SetResult(result);
		}

		private bool ValidateChoiceId(Player player, uint choiceId)
		{
			return choiceId < GetChoiceId(player);
		}

		private uint GetChoiceId(Player player)
		{
			int playerSlotIndex = _players.GetPlayerSlotIndex(player);
			if (playerSlotIndex >= _choiceIds.Count)
			{
				return 0u;
			}
			return _choiceIds[playerSlotIndex];
		}
	}
	/// <summary>
	/// For use when we are quite certain that no path will ever result in a player choice call deeper in the callstack.
	/// This is currently used in a few scenarios:
	///  - In events, where we're out-of-combat, and so player choice cannot occur.
	///  - In tests where we are certain that calling a cmd will not trigger a player choice.
	///  - In Sleight of Flesh Power's trigger, to prevent having to pass PlayerChoiceContext to PowerCmd.Apply. (This could
	///    change if we find out that player choice can be triggered in that scenario.)
	/// </summary>
	public class ThrowingPlayerChoiceContext : PlayerChoiceContext
	{
		public override ulong? OwnerId => null;

		public override Task SignalPlayerChoiceBegun(Player chooser, PlayerChoiceOptions options)
		{
			throw new NotImplementedException();
		}

		public override Task SignalPlayerChoiceEnded()
		{
			throw new NotImplementedException();
		}
	}
