	public enum EventLayoutType
	{
		/// <summary>
		/// The standard event layout type.
		/// At the time I wrote this (10/1/2024), this layout aligns text and buttons to the right side of the screen.
		/// It shows full-screen static art in the background, with the focal point on the left side of the screen.
		/// </summary>
		Default,
		/// <summary>
		/// An event layout type that looks like a combat, with the players on one side and monsters on the other.
		/// No other elements of combat (cards, health bars, etc.) appear in these events, they just look like combat.
		/// </summary>
		Combat,
		/// <summary>
		/// The event layout type used for the Ancients at the beginning of acts.
		/// At the time I wrote this (10/1/2024), this layout aligns text and buttons to the bottom-middle of the screen.
		/// It shows a Spine animation in the background, with the focal point on the tip-middle of the screen.
		/// </summary>
		Ancient,
		/// <summary>
		/// A totally custom scene.
		/// We use this when we want to show events that don't follow any standard layout.
		/// </summary>
		Custom
	}
	public class EventOption
	{
		public string TextKey { get; private set; }

		public LocString Title { get; private set; }

		public LocString Description { get; private set; }

		private Func<Task>? OnChosen { get; }

		public IEnumerable<IHoverTip> HoverTips { get; set; }

		public bool IsLocked { get; }

		public bool IsProceed { get; private set; }

		public bool WasChosen { get; private set; }

		public RelicModel? Relic { get; private set; }

		private bool DisableOnChosen { get; }

		public Func<Player, bool>? WillKillPlayer { get; private set; }

		public bool ShouldSaveChoiceToHistory { get; private set; } = true;

		public LocString HistoryName { get; private set; }

		public bool ShouldSaveVariablesToHistory { get; private set; } = true;

		public event Func<EventOption, Task>? BeforeChosen;

		/// <summary>
		/// Create a new event option.
		/// </summary>
		/// <param name="eventModel">The event that this option belongs to.</param>
		/// <param name="onChosen">The function that will run when the option is chosen.</param>
		/// <param name="title">Option title.</param>
		/// <param name="description">Option description.</param>
		/// <param name="textKey">
		/// Localization key prefix for this option. Does not include ".title" or ".description".
		/// </param>
		/// <param name="hoverTips">HoverTips that should be shown when hovering this option.</param>
		public EventOption(EventModel eventModel, Func<Task>? onChosen, LocString title, LocString description, string textKey, IEnumerable<IHoverTip> hoverTips)
		{
			TextKey = textKey;
			OnChosen = onChosen;
			Title = title;
			Description = description;
			HoverTips = hoverTips;
			IsLocked = OnChosen == null;
			DisableOnChosen = true;
			HistoryName = title;
			AddLocVars(eventModel);
		}

		/// <summary>
		/// Create a new event option.
		/// </summary>
		/// <param name="eventModel">The event that this option belongs to.</param>
		/// <param name="onChosen">The function that will run when the option is chosen.</param>
		/// <param name="textKey">
		/// Localization key prefix for this option. Does not include ".title" or ".description".
		/// </param>
		/// <param name="hoverTips">HoverTips that should be shown when hovering this option.</param>
		public EventOption(EventModel eventModel, Func<Task>? onChosen, string textKey, IEnumerable<IHoverTip> hoverTips)
		{
			TextKey = textKey;
			OnChosen = onChosen;
			Title = eventModel.GetOptionTitle(textKey);
			Description = eventModel.GetOptionDescription(textKey);
			HoverTips = hoverTips;
			IsLocked = OnChosen == null;
			DisableOnChosen = true;
			HistoryName = Title;
			AddLocVars(eventModel);
		}

		/// <summary>
		/// Create a new event option.
		/// </summary>
		/// <param name="eventModel">The event that this option belongs to.</param>
		/// <param name="onChosen">The function that will run when the option is chosen.</param>
		/// <param name="textKey">
		/// Localization key prefix for this option. Does not include ".title" or ".description".
		/// </param>
		/// <param name="hoverTips">HoverTips that should be shown when hovering this option.</param>
		public EventOption(EventModel eventModel, Func<Task>? onChosen, string textKey, params IHoverTip[] hoverTips)
			: this(eventModel, onChosen, textKey, hoverTips.ToList())
		{
		}

		/// <summary>
		/// Create a new event option.
		/// </summary>
		/// <param name="eventModel">The event that this option belongs to.</param>
		/// <param name="onChosen">The function that will run when the option is chosen.</param>
		/// <param name="textKey">
		/// Localization key prefix for this option. Does not include ".title" or ".description".
		/// </param>
		/// <param name="disableOnChosen">
		/// Whether this option should be disabled after clicking it.
		/// Usually true, but false for options that have a confirmation dialog that can be canceled,
		/// so the option can be re-clicked after.
		/// </param>
		/// <param name="isProceed">Whether this option is a "proceed" button.</param>
		/// <param name="hoverTips">HoverTips that should be shown when hovering this option.</param>
		public EventOption(EventModel eventModel, Func<Task>? onChosen, string textKey, bool disableOnChosen = true, bool isProceed = false, params IHoverTip[] hoverTips)
			: this(eventModel, onChosen, textKey, hoverTips.ToList())
		{
			IsProceed = isProceed;
			DisableOnChosen = disableOnChosen;
		}

		public EventOption(EventOption eventOption)
		{
			TextKey = eventOption.TextKey;
			OnChosen = eventOption.OnChosen;
			Title = eventOption.Title;
			Description = eventOption.Description;
			HoverTips = eventOption.HoverTips;
			IsLocked = eventOption.IsLocked;
			DisableOnChosen = eventOption.DisableOnChosen;
			HistoryName = eventOption.HistoryName;
			IsProceed = eventOption.IsProceed;
			DisableOnChosen = eventOption.DisableOnChosen;
		}

		public static EventOption FromRelic(RelicModel relic, EventModel eventModel, Func<Task>? onChosen, string textKey)
		{
			LocString title = eventModel.GetOptionTitle(textKey) ?? relic.Title;
			LocString description = eventModel.GetOptionDescription(textKey) ?? relic.DynamicEventDescription;
			return new EventOption(eventModel, onChosen, title, description, textKey, relic.HoverTipsExcludingRelic).WithRelic(relic);
		}

		/// <summary>
		/// Associates a relic with this event option.
		/// Should be called on custom ancient event options that give relics so that they show up in the correct category
		/// in the relic library.
		/// </summary>
		public EventOption WithRelic<T>(Player? owner) where T : RelicModel
		{
			RelicModel relicModel = ModelDb.Relic<T>().ToMutable();
			if (owner != null)
			{
				relicModel.Owner = owner;
			}
			return WithRelic(relicModel);
		}

		/// <summary>
		/// Associates a relic with this event option.
		/// Should be called on custom ancient event options that give relics so that they show up in the correct category
		/// in the relic library.
		/// </summary>
		public EventOption WithRelic(RelicModel relic)
		{
			relic.AssertMutable();
			Relic = relic;
			return this;
		}

		public async Task Chosen()
		{
			if (OnChosen != null && (!DisableOnChosen || !WasChosen))
			{
				WasChosen = true;
				if (BeforeChosen != null)
				{
					await BeforeChosen(this);
				}
				await OnChosen();
			}
		}

		/// <summary>
		/// Typically, the title of the event is used for the name shown in the run history and uploaded to metrics. This
		/// method overrides the name used.
		/// </summary>
		public EventOption WithOverridenHistoryName(LocString historyName)
		{
			HistoryName = historyName;
			return this;
		}

		/// <summary>
		/// Causes the event option to flash red if the player's HP is below the damage value passed.
		/// </summary>
		public EventOption ThatDoesDamage(decimal damage)
		{
			return ThatWillKillPlayerIf((Player p) => (decimal)p.Creature.CurrentHp <= damage);
		}

		/// <summary>
		/// Causes the event option to flash red if the player's Max HP is below the value passed.
		/// </summary>
		public EventOption ThatDecreasesMaxHp(decimal value)
		{
			return ThatWillKillPlayerIf((Player p) => (decimal)p.Creature.MaxHp <= value);
		}

		/// <summary>
		/// Causes the event option to flash red when the passed function returns true.
		/// </summary>
		public EventOption ThatWillKillPlayerIf(Func<Player, bool> willKillPlayer)
		{
			WillKillPlayer = willKillPlayer;
			return this;
		}

		/// <summary>
		/// Certain event options have dynamic titles that vary based on the DynamicVars passed to the loc string. By
		/// default, LocString DynamicVars are not saved to the save file. If this is called, those variables will be saved
		/// to the run history so that the title can be correctly displayed. This should only be used with specific
		/// events, as saving variables often saves lots of unnecessary data.
		/// </summary>
		public EventOption ThatHasDynamicTitle()
		{
			ShouldSaveVariablesToHistory = true;
			return this;
		}

		public EventOption ThatWontSaveToChoiceHistory()
		{
			ShouldSaveChoiceToHistory = false;
			return this;
		}

		private void AddLocVars(EventModel eventModel)
		{
			eventModel.Owner?.Character.AddDetailsTo(Description);
			LocString description = Description;
			Player? owner = eventModel.Owner;
			description.Add("IsMultiplayer", owner != null && owner.RunState.Players.Count > 1);
		}

		public override string ToString()
		{
			return $"{"EventOption"} title: {Title.GetRawText()} description: {Description.GetRawText()} textKey: {TextKey}";
		}
	}
}
namespace MegaCrit.Sts2.Core.Events.Custom.CrystalSphereEvent
{
	/// <summary>
	/// Represents a cell on the grid for the Crystal SphereMinigame
	/// </summary>
	public class CrystalSphereCell
	{
		private bool _isHidden;

		private bool _isHighlighted;

		private bool _isHovered;

		public CrystalSphereItem? Item { get; private set; }

		public int X { get; private set; }

		public int Y { get; private set; }

		/// <summary>
		/// If true, then this cell is still obscured by fog.
		/// </summary>
		public bool IsHidden
		{
			get
			{
				return _isHidden;
			}
			set
			{
				_isHidden = value;
				FogUpdated?.Invoke();
			}
		}

		public bool IsHighlighted
		{
			get
			{
				return _isHighlighted;
			}
			set
			{
				_isHighlighted = value;
				HighlightUpdated?.Invoke();
			}
		}

		public bool IsHovered
		{
			get
			{
				return _isHovered;
			}
			set
			{
				_isHovered = value;
				HighlightUpdated?.Invoke();
			}
		}

		public event Action? FogUpdated;

		public event Action? HighlightUpdated;

		public CrystalSphereCell(int x, int y)
		{
			X = x;
			Y = y;
			IsHidden = true;
		}

		public void SetItem(CrystalSphereItem? item)
		{
			if (Item != null)
			{
				throw new InvalidOperationException("An item already occupies this cell");
			}
			Item = item;
		}
	}
	/// <summary>
	/// The items that are on the grid for the Crystal Sphere minigame
	/// </summary>
	public abstract class CrystalSphereItem
	{
		public abstract Vector2I Size { get; }

		public Vector2I Position { get; private set; }

		protected virtual string TexturePath => ImageHelper.GetImagePath("events/crystal_sphere/" + GetType().Name.ToSnakeCase() + ".png");

		public Texture2D Texture => PreloadManager.Cache.GetTexture2D(TexturePath);

		public abstract bool IsGood { get; }

		public event Action<CrystalSphereItem>? Revealed;

		/// <summary>
		/// Places an item randomly on the minigame's grid
		/// </summary>
		/// <param name="game"></param>
		/// <exception cref="T:System.InvalidOperationException"></exception>
		public bool PlaceItem(CrystalSphereMinigame game)
		{
			List<Vector2I> list = new List<Vector2I>();
			for (int i = 0; i < game.GridSize.X; i++)
			{
				for (int j = 0; j < game.GridSize.Y; j++)
				{
					if (CanPlaceHere(game.cells, i, j))
					{
						list.Add(new Vector2I(i, j));
					}
				}
			}
			if (!list.Any())
			{
				return false;
			}
			Position = game.Rng.NextItem(list);
			for (int k = 0; k < Size.X; k++)
			{
				for (int l = 0; l < Size.Y; l++)
				{
					int num = Position.X + k;
					int num2 = Position.Y + l;
					game.cells[num, num2].SetItem(this);
				}
			}
			return true;
		}

		/// <summary>
		/// Returns true if this coordinate is a valid place to put this item
		/// </summary>
		/// <param name="grid">Grid we are doing the placement on</param>
		/// <param name="x">Potential X coord we are validating</param>
		/// <param name="y">Potential Y coord we are validating</param>
		/// <returns></returns>
		private bool CanPlaceHere(CrystalSphereCell[,] grid, int x, int y)
		{
			for (int i = 0; i < Size.X; i++)
			{
				for (int j = 0; j < Size.Y; j++)
				{
					int num = x + i;
					int num2 = y + j;
					if (num < 0 || num >= grid.GetLength(0))
					{
						return false;
					}
					if (num2 < 0 || num2 >= grid.GetLength(1))
					{
						return false;
					}
					if (!grid[num, num2].IsHidden)
					{
						return false;
					}
					if (grid[num, num2].Item != null)
					{
						return false;
					}
				}
			}
			return true;
		}

		public virtual Task RevealItem(Player _)
		{
			Revealed?.Invoke(this);
			return Task.CompletedTask;
		}

		public virtual Reward? ToReward(Player owner, Rng rng)
		{
			return null;
		}

		public abstract SerializableCrystalSphereItem ToSerializable();

		public static CrystalSphereItem FromSerializable(SerializableCrystalSphereItem serializable, Player owner)
		{
			return serializable.type switch
			{
				CrystalSphereItemType.CardReward => new CrystalSphereCardReward(serializable.cardRarity, owner), 
				CrystalSphereItemType.Potion => new CrystalSpherePotion(serializable.potionRarity), 
				CrystalSphereItemType.Gold => new CrystalSphereGold(serializable.isBigGold), 
				CrystalSphereItemType.Curse => new CrystalSphereCurse(), 
				CrystalSphereItemType.Relic => new CrystalSphereRelic(), 
				_ => throw new ArgumentOutOfRangeException(), 
			};
		}
	}
	public class CrystalSphereMinigame
	{
		public enum CrystalSphereToolType
		{
			None,
			Small,
			Big
		}

		private const int _defaultWidth = 11;

		private const int _defaultHeight = 11;

		private int _divinationCount;

		private readonly TaskCompletionSource _completionSource = new TaskCompletionSource();

		private readonly Player _owner;

		public CrystalSphereCell[,] cells;

		/// <summary>
		/// Set of items on the grid
		/// </summary>
		private readonly List<CrystalSphereItem> _items = new List<CrystalSphereItem>();

		/// <summary>
		/// Items revealed by the player.
		/// Rewards for these items are given to the player once the minigame is completed
		/// </summary>
		private readonly List<CrystalSphereItem> _revealed = new List<CrystalSphereItem>();

		public Rng Rng { get; private set; }

		public int DivinationCount
		{
			get
			{
				return _divinationCount;
			}
			set
			{
				_divinationCount = value;
				DivinationCountChanged?.Invoke();
			}
		}

		public Vector2I GridSize => new Vector2I(cells.GetLength(0), cells.GetLength(1));

		public bool IsFinished => DivinationCount == 0;

		public bool PlacedAllItems { get; private set; }

		public CrystalSphereToolType CrystalSphereTool { get; private set; }

		public IReadOnlyList<CrystalSphereItem> Items => _items;

		/// <summary>
		/// The cell that we are currently hovered over.
		/// </summary>
		private CrystalSphereCell? HoveredCell { get; set; }

		/// <summary>
		/// The cells that are highlighted on the board. This is separate from HoveredCell
		/// because we can highlight multiple cells at once depending on the tool
		/// </summary>
		private List<CrystalSphereCell> HighlightedCells { get; set; } = new List<CrystalSphereCell>();

		public event Action? DivinationCountChanged;

		public event Action? Finished;

		public CrystalSphereMinigame(Player owner, Rng rng, int divinationCount)
		{
			_owner = owner;
			Rng = rng;
			cells = new CrystalSphereCell[11, 11];
			for (int i = 0; i < 11; i++)
			{
				for (int j = 0; j < 11; j++)
				{
					cells[i, j] = new CrystalSphereCell(i, j);
				}
			}
			int num = 4;
			List<Vector2I> list = new List<Vector2I>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<Vector2I> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = new Vector2I(0, 0);
			num2++;
			span[num2] = new Vector2I(cells.GetLength(0) - 1, 0);
			num2++;
			span[num2] = new Vector2I(cells.GetLength(0) - 1, cells.GetLength(0) - 1);
			num2++;
			span[num2] = new Vector2I(0, cells.GetLength(0) - 1);
			List<Vector2I> list2 = list;
			for (int k = 0; k < 2; k++)
			{
				List<Vector2I> list3 = list2.Concat(list2.SelectMany((Vector2I c) => GetHorizontalCells(c.X, c.Y))).Concat(list2.SelectMany((Vector2I c) => GetVerticalCells(c.X, c.Y))).ToList();
				list2 = list3;
			}
			foreach (Vector2I item in list2)
			{
				TaskHelper.RunSafely(ClearCell(item.X, item.Y));
			}
			int num3 = 0;
			do
			{
				PlacedAllItems = PopulateItems();
				num3++;
			}
			while (!PlacedAllItems && num3 < 10);
			DivinationCount = divinationCount;
			CrystalSphereTool = CrystalSphereToolType.Big;
		}

		/// <summary>
		/// Ends the minigames early. Used if the event is force closed via save/quit or closing the application
		/// </summary>
		public void ForceMinigameEnd()
		{
			_revealed.Clear();
			if (!_completionSource.Task.IsCompleted)
			{
				_completionSource.SetCanceled();
			}
		}

		public async Task PlayMinigame()
		{
			if (LocalContext.IsMe(_owner))
			{
				NCrystalSphereScreen.ShowScreen(this);
				await _completionSource.Task;
				await CompleteMinigame();
			}
		}

		private bool PopulateItems()
		{
			bool flag = true;
			CrystalSphereItem crystalSphereItem = new CrystalSphereRelic();
			flag = flag && crystalSphereItem.PlaceItem(this);
			_items.Add(crystalSphereItem);
			for (int i = 0; i < 2; i++)
			{
				CrystalSphereItem crystalSphereItem2 = new CrystalSpherePotion(PotionRarity.Common);
				flag = flag && crystalSphereItem2.PlaceItem(this);
				_items.Add(crystalSphereItem2);
			}
			CrystalSphereItem crystalSphereItem3 = new CrystalSpherePotion(PotionRarity.Rare);
			flag = flag && crystalSphereItem3.PlaceItem(this);
			_items.Add(crystalSphereItem3);
			CrystalSphereItem crystalSphereItem4 = new CrystalSphereCardReward(CardRarity.Common, _owner);
			flag = flag && crystalSphereItem4.PlaceItem(this);
			_items.Add(crystalSphereItem4);
			CrystalSphereItem crystalSphereItem5 = new CrystalSphereCardReward(CardRarity.Uncommon, _owner);
			flag = flag && crystalSphereItem5.PlaceItem(this);
			_items.Add(crystalSphereItem5);
			CrystalSphereItem crystalSphereItem6 = new CrystalSphereCardReward(CardRarity.Rare, _owner);
			flag = flag && crystalSphereItem6.PlaceItem(this);
			_items.Add(crystalSphereItem6);
			CrystalSphereItem crystalSphereItem7 = new CrystalSphereCurse();
			flag = flag && crystalSphereItem7.PlaceItem(this);
			_items.Add(crystalSphereItem7);
			for (int j = 0; j < 5; j++)
			{
				CrystalSphereItem crystalSphereItem8 = new CrystalSphereGold(isBig: false);
				flag = flag && crystalSphereItem8.PlaceItem(this);
				_items.Add(crystalSphereItem8);
			}
			for (int k = 0; k < 2; k++)
			{
				CrystalSphereItem crystalSphereItem9 = new CrystalSphereGold(isBig: true);
				flag = flag && crystalSphereItem9.PlaceItem(this);
				_items.Add(crystalSphereItem9);
			}
			foreach (CrystalSphereItem item in _items)
			{
				item.Revealed += OnItemRevealed;
			}
			return flag;
		}

		private void OnItemRevealed(CrystalSphereItem item)
		{
			_revealed.Add(item);
		}

		public void SetHoveredCell(CrystalSphereCell cell)
		{
			if (HoveredCell != null)
			{
				UnsetHoveredCell();
			}
			HoveredCell = cell;
			HoveredCell.IsHovered = true;
			if (CrystalSphereTool == CrystalSphereToolType.Big)
			{
				HighlightedCells = (from c in GetAdjacentCells(cell.X, cell.Y)
					select cells[c.X, c.Y]).ToList();
			}
			else
			{
				int num = 1;
				List<CrystalSphereCell> list = new List<CrystalSphereCell>(num);
				CollectionsMarshal.SetCount(list, num);
				Span<CrystalSphereCell> span = CollectionsMarshal.AsSpan(list);
				int index = 0;
				span[index] = cells[cell.X, cell.Y];
				HighlightedCells = list;
			}
			foreach (CrystalSphereCell highlightedCell in HighlightedCells)
			{
				highlightedCell.IsHighlighted = true;
			}
		}

		public void UnsetHoveredCell()
		{
			foreach (CrystalSphereCell highlightedCell in HighlightedCells)
			{
				highlightedCell.IsHighlighted = false;
				highlightedCell.IsHovered = false;
			}
			HighlightedCells = new List<CrystalSphereCell>();
			HoveredCell = null;
		}

		public void SetTool(CrystalSphereToolType tool)
		{
			CrystalSphereTool = tool;
			if (HoveredCell != null)
			{
				SetHoveredCell(HoveredCell);
			}
		}

		public async Task CellClicked(CrystalSphereCell clickedCell)
		{
			DivinationCount--;
			if (CrystalSphereTool != CrystalSphereToolType.Big)
			{
				await ClearCell(clickedCell.X, clickedCell.Y);
			}
			else
			{
				List<Vector2I> adjacentCells = GetAdjacentCells(clickedCell.X, clickedCell.Y);
				foreach (Vector2I item in adjacentCells)
				{
					await ClearCell(item.X, item.Y);
				}
			}
			if (DivinationCount == 0)
			{
				_completionSource.SetResult();
			}
		}

		/// <summary>
		/// Decreases the FogValue of a CrystalSphereCell at the given x,y coordinate by amount
		/// </summary>
		/// <param name="x">X coordinate the cell we want to affect is at</param>
		/// <param name="y">Y coordinate the cell we want to affect is at</param>
		private async Task ClearCell(int x, int y)
		{
			if (x < 0 || x >= GridSize.X)
			{
				throw new ArgumentException($"[{x},{y}] is not a valid cell on this grid");
			}
			if (y < 0 || y >= GridSize.Y)
			{
				throw new ArgumentException($"[{x},{y}] is not a valid cell on this grid");
			}
			if (!cells[x, y].IsHidden)
			{
				return;
			}
			cells[x, y].IsHidden = false;
			if (cells[x, y].Item != null)
			{
				CrystalSphereItem item = cells[x, y].Item;
				if (AreAllOccupiedCellsClear(item))
				{
					await item.RevealItem(_owner);
				}
			}
		}

		/// <summary>
		/// Returns if all the cells an item occupies are visible
		/// </summary>
		/// <param name="item">The item we are checking is fully visible</param>
		/// <returns></returns>
		private bool AreAllOccupiedCellsClear(CrystalSphereItem item)
		{
			for (int i = 0; i < item.Size.X; i++)
			{
				for (int j = 0; j < item.Size.Y; j++)
				{
					int num = item.Position.X + i;
					int num2 = item.Position.Y + j;
					if (cells[num, num2].IsHidden)
					{
						return false;
					}
				}
			}
			return true;
		}

		private async Task CompleteMinigame()
		{
			await Cmd.Wait(0.75f);
			await RunManager.Instance.OneOffSynchronizer.DoLocalCrystalSphereRewards(_owner, Rng, _revealed);
			Finished?.Invoke();
		}

		private List<Vector2I> GetAdjacentCells(int x, int y)
		{
			return GetHorizontalCells(x, y).Concat(GetVerticalCells(x, y)).Concat(GetDiagonalCells(x, y)).Concat(new global::<>z__ReadOnlySingleElementList<Vector2I>(new Vector2I(x, y)))
				.ToList();
		}

		private List<Vector2I> GetHorizontalCells(int x, int y)
		{
			List<Vector2I> list = new List<Vector2I>();
			for (int i = -1; i <= 1; i += 2)
			{
				int num = x + i;
				if (num >= 0 && num < 11)
				{
					list.Add(new Vector2I(num, y));
				}
			}
			return list;
		}

		private List<Vector2I> GetVerticalCells(int x, int y)
		{
			List<Vector2I> list = new List<Vector2I>();
			for (int i = -1; i <= 1; i += 2)
			{
				int num = y + i;
				if (num >= 0 && num < 11)
				{
					list.Add(new Vector2I(x, num));
				}
			}
			return list;
		}

		private List<Vector2I> GetDiagonalCells(int x, int y)
		{
			List<Vector2I> list = new List<Vector2I>();
			for (int i = -1; i <= 1; i += 2)
			{
				for (int j = -1; j <= 1; j += 2)
				{
					int num = x + i;
					int num2 = y + j;
					if (num >= 0 && num < 11 && num2 >= 0 && num2 < 11)
					{
						list.Add(new Vector2I(num, num2));
					}
				}
			}
			return list;
		}
	}
	public class SerializableCrystalSphereItem : IPacketSerializable
	{
		public CrystalSphereItemType type;

		public CardRarity cardRarity;

		public PotionRarity potionRarity;

		public bool isBigGold;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteEnum(type);
			if (type == CrystalSphereItemType.CardReward)
			{
				writer.WriteEnum(cardRarity);
			}
			else if (type == CrystalSphereItemType.Potion)
			{
				writer.WriteEnum(potionRarity);
			}
			else if (type == CrystalSphereItemType.Gold)
			{
				writer.WriteBool(isBigGold);
			}
		}

		public void Deserialize(PacketReader reader)
		{
			type = reader.ReadEnum<CrystalSphereItemType>();
			if (type == CrystalSphereItemType.CardReward)
			{
				cardRarity = reader.ReadEnum<CardRarity>();
			}
			else if (type == CrystalSphereItemType.Potion)
			{
				potionRarity = reader.ReadEnum<PotionRarity>();
			}
			else if (type == CrystalSphereItemType.Gold)
			{
				isBigGold = reader.ReadBool();
			}
		}
	}
	public enum CrystalSphereItemType
	{
		CardReward,
		Curse,
		Gold,
		Potion,
		Relic
	}
}
