	public class CloneRestSiteOption : RestSiteOption
	{
		public override string OptionId => "CLONE";

		public override LocString Description
		{
			get
			{
				LocString description = base.Description;
				description.Add("EnchantmentName", ModelDb.Enchantment<Clone>().Title.GetFormattedText());
				return description;
			}
		}

		public CloneRestSiteOption(Player owner)
			: base(owner)
		{
		}

		public override async Task<bool> OnSelect()
		{
			IEnumerable<CardModel> enumerable = base.Owner.Deck.Cards.Where((CardModel c) => c.Enchantment is Clone).ToList();
			List<CardPileAddResult> results = new List<CardPileAddResult>();
			foreach (CardModel item in enumerable)
			{
				CardModel card = base.Owner.RunState.CloneCard(item);
				List<CardPileAddResult> list = results;
				list.Add(await CardPileCmd.Add(card, PileType.Deck));
			}
			CardCmd.PreviewCardPileAdd(results, 1.2f, CardPreviewStyle.MessyLayout);
			return true;
		}

		public override Task DoLocalPostSelectVfx(CancellationToken ct = default(CancellationToken))
		{
			NGame.Instance?.ScreenShake(ShakeStrength.Strong, ShakeDuration.Short);
			return Task.CompletedTask;
		}

		public override Task DoRemotePostSelectVfx()
		{
			NRestSiteCharacter nRestSiteCharacter = NRestSiteRoom.Instance?.Characters.First((NRestSiteCharacter c) => c.Player == base.Owner);
			nRestSiteCharacter?.Shake();
			NRelicFlashVfx nRelicFlashVfx = NRelicFlashVfx.Create(ModelDb.Relic<PaelsGrowth>());
			if (nRelicFlashVfx == null)
			{
				return Task.CompletedTask;
			}
			nRestSiteCharacter?.AddChildSafely(nRelicFlashVfx);
			nRelicFlashVfx.Position = Godot.Vector2.Zero;
			return Task.CompletedTask;
		}
	}
	public sealed class CookRestSiteOption : RestSiteOption
	{
		private const int _cardsToRemove = 2;

		private const int _maxHpGain = 5;

		public override string OptionId => "COOK";

		public override LocString Description
		{
			get
			{
				if (IsEnabled)
				{
					LocString locString = new LocString("rest_site_ui", "OPTION_" + OptionId + ".description");
					locString.Add("Cards", 2m);
					locString.Add("MaxHp", 5m);
					return locString;
				}
				return new LocString("rest_site_ui", "OPTION_" + OptionId + ".descriptionDisabled");
			}
		}

		public override bool IsEnabled => GetRemovableCardCount(base.Owner) >= 2;

		public CookRestSiteOption(Player owner)
			: base(owner)
		{
		}

		public override async Task<bool> OnSelect()
		{
			CardSelectorPrefs prefs = new CardSelectorPrefs(CardSelectorPrefs.RemoveSelectionPrompt, 2)
			{
				Cancelable = true,
				RequireManualConfirmation = true
			};
			IEnumerable<CardModel> enumerable = await CardSelectCmd.FromDeckForRemoval(base.Owner, prefs);
			if (!enumerable.Any())
			{
				return false;
			}
			foreach (CardModel item in enumerable)
			{
				await CardPileCmd.RemoveFromDeck(item);
			}
			await CreatureCmd.GainMaxHp(base.Owner.Creature, 5m);
			return true;
		}

		private static int GetRemovableCardCount(Player player)
		{
			return PileType.Deck.GetPile(player).Cards.Count((CardModel c) => c.IsRemovable);
		}
	}
