	public sealed class MendRestSiteOption : RestSiteOption
	{
		private const string _hasTargetKey = "HasTarget";

		private const string _playerNameKey = "Name";

		private readonly HealVar _healVar = new HealVar(0m);

		private LocString? _description;

		public override string OptionId => "MEND";

		public override LocString Description
		{
			get
			{
				if (_description == null)
				{
					_description = base.Description;
					_description.Add("HasTarget", variable: false);
					_description.Add("Name", "");
					_description.Add(_healVar);
				}
				return _description;
			}
		}

		public static decimal GetHealAmount(Player player)
		{
			return Hook.ModifyRestSiteHealAmount(player.RunState, player.Creature, HealRestSiteOption.GetBaseHealAmount(player.Creature));
		}

		public MendRestSiteOption(Player owner)
			: base(owner)
		{
		}

		public override async Task<bool> OnSelect()
		{
			uint choiceId = RunManager.Instance.PlayerChoiceSynchronizer.ReserveChoiceId(base.Owner);
			Player target = null;
			if (LocalContext.IsMe(base.Owner))
			{
				NRestSiteRoom.Instance.AnimateDescriptionDown();
				NRestSiteButton buttonForOption = NRestSiteRoom.Instance.GetButtonForOption(this);
				Godot.Vector2 startPosition = buttonForOption.GlobalPosition + buttonForOption.Size / 2f;
				bool usingController = NControllerManager.Instance.IsUsingDirectionalNavigation;
				NTargetManager targetManager = NTargetManager.Instance;
				targetManager.StartTargeting(TargetType.AnyPlayer, startPosition, usingController ? TargetMode.Controller : TargetMode.ClickMouseToTarget, ShouldCancelTargeting, AllowHoveringNode);
				if (usingController)
				{
					List<NRestSiteCharacter> list = NRestSiteRoom.Instance.characterAnims.Where((NRestSiteCharacter c) => c.Player != base.Owner).ToList();
					for (int num = 0; num < list.Count; num++)
					{
						list[num].Hitbox.SetFocusMode(Control.FocusModeEnum.All);
						list[num].Hitbox.FocusNeighborTop = list[num].Hitbox.GetPath();
						list[num].Hitbox.FocusNeighborBottom = list[num].Hitbox.GetPath();
						Control hitbox = list[num].Hitbox;
						NodePath path;
						if (num <= 0)
						{
							path = list[list.Count - 1].Hitbox.GetPath();
						}
						else
						{
							path = list[num - 1].Hitbox.GetPath();
						}
						hitbox.FocusNeighborLeft = path;
						list[num].Hitbox.FocusNeighborRight = ((num < list.Count - 1) ? list[num + 1].Hitbox.GetPath() : list[0].Hitbox.GetPath());
					}
					list.FirstOrDefault()?.Hitbox.TryGrabFocus();
				}
				targetManager.Connect(NTargetManager.SignalName.NodeHovered, Callable.From<Node>(OnNodeHovered));
				targetManager.Connect(NTargetManager.SignalName.NodeUnhovered, Callable.From<Node>(OnNodeUnhovered));
				try
				{
					target = NodeToPlayer(await targetManager.SelectionFinished());
					RunManager.Instance.PlayerChoiceSynchronizer.SyncLocalChoice(base.Owner, choiceId, PlayerChoiceResult.FromPlayerId(target?.NetId));
				}
				finally
				{
					targetManager.Disconnect(NTargetManager.SignalName.NodeHovered, Callable.From<Node>(OnNodeHovered));
					targetManager.Disconnect(NTargetManager.SignalName.NodeUnhovered, Callable.From<Node>(OnNodeUnhovered));
					if (usingController)
					{
						foreach (NRestSiteCharacter characterAnim in NRestSiteRoom.Instance.characterAnims)
						{
							characterAnim.Hitbox.SetFocusMode(Control.FocusModeEnum.None);
						}
					}
				}
			}
			else
			{
				ulong? num2 = (await RunManager.Instance.PlayerChoiceSynchronizer.WaitForRemoteChoice(base.Owner, choiceId)).AsPlayerId();
				if (num2.HasValue)
				{
					target = base.Owner.RunState.GetPlayer(num2.Value);
				}
			}
			NRestSiteRoom.Instance?.AnimateDescriptionUp();
			Description.Add("HasTarget", variable: false);
			NRestSiteRoom.Instance?.GetButtonForOption(this)?.RefreshTextState();
			if (target != null)
			{
				await CreatureCmd.Heal(target.Creature, GetHealAmount(target));
				await Hook.AfterRestSiteHeal(target.RunState, target, isMimicked: false);
				if (TestMode.IsOff)
				{
					string scenePath = SceneHelper.GetScenePath("vfx/vfx_cross_heal");
					Node2D node2D = PreloadManager.Cache.GetScene(scenePath).Instantiate<Node2D>(PackedScene.GenEditState.Disabled);
					(NRestSiteRoom.Instance?.GetCharacterForPlayer(target))?.AddChildSafely(node2D);
					node2D.Position = Godot.Vector2.Zero;
				}
				return true;
			}
			return false;
		}

		/// <summary>
		/// Called when a targetable node (rest site character, player state display) is hovered.
		/// </summary>
		private void OnNodeHovered(Node node)
		{
			Player player = NodeToPlayer(node);
			if (player != null)
			{
				Description.Add("HasTarget", variable: true);
				Description.Add("Name", PlatformUtil.GetPlayerName(RunManager.Instance.NetService.Platform, player.NetId));
				_healVar.BaseValue = HealRestSiteOption.GetBaseHealAmount(player.Creature);
				_healVar.PreviewValue = GetHealAmount(player);
				NRestSiteRoom.Instance?.GetButtonForOption(this)?.RefreshTextState();
			}
		}

		/// <summary>
		/// Called when a targetable node (rest site character, player state display) is unhovered.
		/// </summary>
		private void OnNodeUnhovered(Node _)
		{
			Description.Add("HasTarget", variable: false);
			NRestSiteRoom.Instance?.GetButtonForOption(this)?.RefreshTextState();
		}

		/// <summary>
		/// Translates a node target to a player.
		/// The node target can be a character at the rest site or a remote player's state display at the top-left.
		/// </summary>
		private Player? NodeToPlayer(Node? node)
		{
			if (node == null)
			{
				return null;
			}
			if (!(node is NMultiplayerPlayerState nMultiplayerPlayerState))
			{
				if (node is NRestSiteCharacter nRestSiteCharacter)
				{
					return nRestSiteCharacter.Player;
				}
				return null;
			}
			return nMultiplayerPlayerState.Player;
		}

		private bool ShouldCancelTargeting()
		{
			if (NOverlayStack.Instance.ScreenCount <= 0)
			{
				return NCapstoneContainer.Instance.InUse;
			}
			return true;
		}

		private bool AllowHoveringNode(Node node)
		{
			return !LocalContext.IsMe(NodeToPlayer(node));
		}
	}
	/// <summary>
	/// Base config class for rest site button options.
	/// </summary>
	public abstract class RestSiteOption
	{
		public static Func<Player, List<RestSiteOption>>? generateForTests;

		public abstract string OptionId { get; }

		protected Player Owner { get; }

		public LocString Title => new LocString("rest_site_ui", "OPTION_" + OptionId + ".name");

		public virtual LocString Description => new LocString("rest_site_ui", "OPTION_" + OptionId + ".description");

		private string IconPath => ImageHelper.GetImagePath("ui/rest_site/option_" + OptionId.ToLowerInvariant() + ".png");

		public Texture2D Icon => PreloadManager.Cache.GetTexture2D(IconPath);

		public virtual IEnumerable<string> AssetPaths => new global::<>z__ReadOnlySingleElementList<string>(IconPath);

		/// <summary>
		/// Whether this option is usable or not. You can still hover it for info.
		/// </summary>
		public virtual bool IsEnabled => true;

		protected RestSiteOption(Player owner)
		{
			Owner = owner;
		}

		/// <summary>
		/// Generates a list of rest site options to use for the next rest site.
		/// This list will include extra options added by models like the Shovel relic if the player has them.
		/// Calling this may increment RNG counters and make other run state changes.
		/// </summary>
		/// <returns>List of rest site options.</returns>
		public static List<RestSiteOption> Generate(Player player)
		{
			if (TestMode.IsOn && generateForTests != null)
			{
				return generateForTests(player);
			}
			int num = 2;
			List<RestSiteOption> list = new List<RestSiteOption>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<RestSiteOption> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = new HealRestSiteOption(player);
			num2++;
			span[num2] = new SmithRestSiteOption(player);
			List<RestSiteOption> list2 = list;
			if (player.RunState.Players.Count > 1)
			{
				list2.Add(new MendRestSiteOption(player));
			}
			Hook.ModifyRestSiteOptions(player.RunState, player, list2);
			return list2;
		}

		/// <summary>
		/// Logic to run when this option is selected.
		/// </summary>
		/// <returns>
		/// Whether or not the option was "successful". Usually true, but false in certain cases (like if Smith is chosen
		/// and no upgradable cards are available).
		/// </returns>
		public abstract Task<bool> OnSelect();

		/// <summary>
		/// Runs only for the owning player after the option is selected.
		/// </summary>
		public virtual Task DoLocalPostSelectVfx(CancellationToken ct = default(CancellationToken))
		{
			return Task.CompletedTask;
		}

		/// <summary>
		/// Runs only for non-owning players after the option is selected.
		/// </summary>
		public virtual Task DoRemotePostSelectVfx()
		{
			return Task.CompletedTask;
		}

		public override bool Equals(object? obj)
		{
			if (obj is RestSiteOption restSiteOption && OptionId == restSiteOption.OptionId)
			{
				return Owner == restSiteOption.Owner;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (OptionId, Owner).GetHashCode();
		}

		public static bool operator ==(RestSiteOption? left, RestSiteOption? right)
		{
			if ((object)left == right)
			{
				return true;
			}
			if ((object)left == null)
			{
				if ((object)left == null)
				{
					return (object)right == null;
				}
				return false;
			}
			return left.Equals(right);
		}

		public static bool operator !=(RestSiteOption? left, RestSiteOption? right)
		{
			return !(left == right);
		}
	}
	public sealed class SmithRestSiteOption : RestSiteOption
	{
		private IEnumerable<CardModel>? _selection;

		public override string OptionId => "SMITH";

		public override IEnumerable<string> AssetPaths => base.AssetPaths.Concat(NCardSmithVfx.AssetPaths);

		public int SmithCount { get; set; } = 1;

		public override LocString Description
		{
			get
			{
				LocString locString;
				if (IsEnabled)
				{
					locString = new LocString("rest_site_ui", "OPTION_" + OptionId + ".description");
					locString.Add("Count", SmithCount);
				}
				else
				{
					locString = new LocString("rest_site_ui", "OPTION_" + OptionId + ".descriptionDisabled");
				}
				return locString;
			}
		}

		public override bool IsEnabled => base.Owner.Deck.UpgradableCardCount != 0;

		public SmithRestSiteOption(Player owner)
			: base(owner)
		{
		}

		public override async Task<bool> OnSelect()
		{
			CardSelectorPrefs prefs = new CardSelectorPrefs(CardSelectorPrefs.UpgradeSelectionPrompt, SmithCount)
			{
				Cancelable = true,
				RequireManualConfirmation = true
			};
			_selection = await CardSelectCmd.FromDeckForUpgrade(base.Owner, prefs);
			if (!_selection.Any())
			{
				return false;
			}
			foreach (CardModel item in _selection)
			{
				CardCmd.Upgrade(item, CardPreviewStyle.None);
			}
			await Hook.AfterRestSiteSmith(base.Owner.RunState, base.Owner);
			return true;
		}

		public override async Task DoLocalPostSelectVfx(CancellationToken ct = default(CancellationToken))
		{
			NRun.Instance?.GlobalUi.CardPreviewContainer.AddChildSafely(NCardSmithVfx.Create(_selection.ToArray()));
			await Cmd.CustomScaledWait(1f, 2f, ignoreCombatEnd: false, ct);
		}

		public override Task DoRemotePostSelectVfx()
		{
			NRestSiteCharacter nRestSiteCharacter = NRestSiteRoom.Instance?.Characters.First((NRestSiteCharacter c) => c.Player == base.Owner);
			NCardSmithVfx nCardSmithVfx = NCardSmithVfx.Create();
			if (nCardSmithVfx == null)
			{
				return Task.CompletedTask;
			}
			nRestSiteCharacter?.AddChildSafely(nCardSmithVfx);
			nCardSmithVfx.Position = Godot.Vector2.Zero;
			return Task.CompletedTask;
		}
	}
