namespace MegaCrit.Sts2.Core.Entities.Players
{
	/// <summary>
	/// Extra fields that are used for specific pieces of content per-player.
	/// </summary>
	public class ExtraPlayerFields
	{
		/// <summary>
		/// The number of times the player has removed a card from their deck in the card shop.
		/// The card removal price increases each time, so we need to track this across the whole run.
		/// </summary>
		public int CardShopRemovalsUsed { get; set; }

		/// <summary>
		/// Points earned in the <see cref="T:MegaCrit.Sts2.Core.Models.Events.WelcomeToWongos" /> event.
		/// We can't save these immediately to SerializableProgress because, otherwise, the player would be able to exit the client,
		/// reload the event, and accumulate more points. We can't write to SerializableProgress and wait for something else to save
		/// it, because it only saves at the end of a run. So, we have to save this to the run data and let SaveManager
		/// accumulate the points into SerializableProgress at the end of the run.
		/// </summary>
		public int WongoPoints { get; set; }

		/// <summary>
		/// Whether or not the player unlocked the CCCCombo badge.
		/// </summary>
		public bool CccomboBadgeUnlocked { get; set; }

		/// <summary>
		/// How much damage the player dealt, aggregated among all combats.
		/// </summary>
		public int DamageDealt { get; set; }

		/// <summary>
		/// How many debuffs the player applied to enemies, aggregated among all combats.
		/// </summary>
		public int DebuffsApplied { get; set; }

		public SerializableExtraPlayerFields ToSerializable()
		{
			return new SerializableExtraPlayerFields
			{
				CardShopRemovalsUsed = CardShopRemovalsUsed,
				WongoPoints = WongoPoints,
				CccomboBadgeUnlocked = CccomboBadgeUnlocked,
				DamageDealt = DamageDealt,
				DebuffsApplied = DebuffsApplied
			};
		}

		public static ExtraPlayerFields FromSerializable(SerializableExtraPlayerFields save)
		{
			return new ExtraPlayerFields
			{
				CardShopRemovalsUsed = save.CardShopRemovalsUsed,
				WongoPoints = save.WongoPoints,
				CccomboBadgeUnlocked = save.CccomboBadgeUnlocked,
				DamageDealt = save.DamageDealt,
				DebuffsApplied = save.DebuffsApplied
			};
		}
	}
	public class Player
	{
		public const int initialMaxPotionSlotCount = 3;

		private CardPile[]? _runPiles;

		private readonly List<RelicModel> _relics = new List<RelicModel>();

		private readonly List<PotionModel?> _potionSlots = new List<PotionModel>();

		private IRunState _runState = NullRunState.Instance;

		private int _gold;

		private bool _canUseOrRemovePotions = true;

		public int MaxPotionCount => _potionSlots.Count;

		public CharacterModel Character { get; }

		public Creature Creature { get; }

		public ulong NetId { get; }

		/// <summary>
		/// Player-scoped RNG set.
		/// Note that this state is not deterministic outside of combat, events and rest sites
		/// This is initialized with a seed of 0, but is updated to a real seed when added to a <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.RunState" />.
		/// </summary>
		public PlayerRngSet PlayerRng { get; private set; }

		/// <summary>
		/// Player-scoped odds set.
		/// Note that this state is not deterministic outside of combat, events and rest sites.
		/// This is initialized with a seed of 0, but is updated to a real seed when added to a <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.RunState" />.
		/// </summary>
		public PlayerOddsSet PlayerOdds { get; private set; }

		/// <summary>
		/// Player-scoped relic grab bag.
		/// See <see cref="P:MegaCrit.Sts2.Core.Runs.IRunState.SharedRelicGrabBag" /> for the difference between this and the shared grab bag.
		/// Note that this state is not deterministic outside of combat, events and rest sites.
		/// </summary>
		public RelicGrabBag RelicGrabBag { get; }

		/// <summary>
		/// The set of unlocks the player entered the run with.
		/// This serves several purposes:
		/// - In multiplayer, this keeps track of each player's unlocks so that we generate only cards/potions/relics that
		///   the player has unlocked.
		/// - In both singleplayer and multiplayer, unlocking epochs outside of the run does not change the unlocks in a
		///   run that you load. The unlocks are saved into the run save file.
		/// </summary>
		public UnlockState UnlockState { get; }

		/// <summary>
		/// The state of the run that the player is in.
		/// Will usually be an instance of <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.RunState" />, but will be <see cref="T:MegaCrit.Sts2.Core.Runs.NullRunState" /> in some spots
		/// for testing, debugging, or one-off combat scenarios. You should never have to check for this though, as
		/// <see cref="T:MegaCrit.Sts2.Core.Runs.NullRunState" /> should always behave appropriately.
		/// </summary>
		public IRunState RunState
		{
			get
			{
				return _runState;
			}
			set
			{
				if (!(_runState is NullRunState))
				{
					throw new InvalidOperationException("RunState has already been set.");
				}
				_runState = value;
			}
		}

		/// <summary>
		/// This is almost equivalent to Creature.IsAlive, except for a brief period of time between when the player's HP
		/// reaches zero and when DieInternal is called.
		/// It is used to allow hooks that prevent death to run before the player is fully considered dead.
		/// This is on Player and not Creature because monsters use a different mechanism for death prevention. Since
		/// creatures are always removed from combat after they are fully dead, their powers are always iterated, and we
		/// rely on creature removal to remove their powers from Hook. Players are different - they stick around after they
		/// are fully dead, and so we rely on this flag to stop model iteration.
		/// </summary>
		public bool IsActiveForHooks { get; private set; }

		public PlayerCombatState? PlayerCombatState { get; private set; }

		public ExtraPlayerFields ExtraFields { get; private set; } = new ExtraPlayerFields();

		public IReadOnlyList<RelicModel> Relics => _relics;

		public IReadOnlyList<PotionModel?> PotionSlots => _potionSlots;

		public IEnumerable<PotionModel> Potions => _potionSlots.Where((PotionModel p) => p != null).OfType<PotionModel>();

		/// <summary>
		/// Get this player's Osty pet Creature.
		/// If Osty is not in combat, this will return null.
		/// If Osty is dead, this will return the dead Osty Creature instance.
		///
		/// Note: If you want to check that Osty is both present in combat and alive, use <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.IsOstyAlive" />.
		/// If you want to check that Osty is missing from combat or dead, use <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.IsOstyMissing" />.
		/// </summary>
		public Creature? Osty => PlayerCombatState?.GetPet<Osty>();

		/// <summary>
		/// Is Osty present in combat and alive?
		/// </summary>
		public bool IsOstyAlive => Osty?.IsAlive ?? false;

		/// <summary>
		/// Is Osty missing from combat or dead?
		/// </summary>
		public bool IsOstyMissing => !IsOstyAlive;

		public int Gold
		{
			get
			{
				return _gold;
			}
			set
			{
				if (value != Gold)
				{
					_gold = value;
					GoldChanged?.Invoke();
				}
			}
		}

		/// <summary>
		/// The player's character's max ascension level when the run started.
		/// We need to keep track of this in order to properly show the "ascension unlocked" message when winning a run.
		/// </summary>
		public int MaxAscensionWhenRunStarted { get; }

		public bool HasOpenPotionSlots => _potionSlots.Any((PotionModel p) => p == null);

		/// <summary>
		/// Can this player use or remove potions?
		/// Usually true, but set to false during some sensitive timing spots.
		/// </summary>
		public bool CanUseOrRemovePotions
		{
			get
			{
				return _canUseOrRemovePotions;
			}
			set
			{
				_canUseOrRemovePotions = value;
				CanUseOrRemovePotionsChanged?.Invoke();
			}
		}

		/// <summary>
		/// Has this player's inventory been populated?
		/// A player object is initially created unpopulated, but the various populating methods should be called before
		/// the run they're in has fully been launched.
		/// </summary>
		private bool IsInventoryPopulated
		{
			get
			{
				if (!Deck.Cards.Any() && !Relics.Any())
				{
					return Potions.Any();
				}
				return true;
			}
		}

		public CardPile Deck { get; } = new CardPile(PileType.Deck);

		public int MaxEnergy { get; set; }

		public List<ModelId> DiscoveredCards { get; set; }

		public List<ModelId> DiscoveredRelics { get; set; }

		public List<ModelId> DiscoveredPotions { get; set; }

		public List<ModelId> DiscoveredEnemies { get; set; }

		public List<string> DiscoveredEpochs { get; set; }

		public int BaseOrbSlotCount { get; set; }

		public IEnumerable<CardPile> Piles
		{
			get
			{
				if (_runPiles == null)
				{
					_runPiles = new CardPile[1] { Deck };
				}
				return (PlayerCombatState?.AllPiles ?? System.Array.Empty<CardPile>()).Concat(_runPiles);
			}
		}

		public event Action<RelicModel>? RelicObtained;

		public event Action<RelicModel>? RelicRemoved;

		public event Action<int>? MaxPotionCountChanged;

		public event Action<PotionModel>? PotionProcured;

		public event Action<PotionModel>? PotionDiscarded;

		public event Action<PotionModel>? UsedPotionRemoved;

		public event Action? AddPotionFailed;

		public event Action? GoldChanged;

		public event Action? CanUseOrRemovePotionsChanged;

		public bool HasEventPet()
		{
			if (!Relics.Any((RelicModel r) => r.AddsPet))
			{
				return Deck.Cards.Any((CardModel c) => c is ByrdonisEgg);
			}
			return true;
		}

		private Player(CharacterModel character, ulong netId, int currentHp, int maxHp, int maxEnergy, int gold, int potionSlotCount, int orbSlotCount, RelicGrabBag sharedRelicGrabBag, UnlockState unlockState, List<ModelId>? discoveredCards = null, List<ModelId>? discoveredEnemies = null, List<string>? discoveredEpochs = null, List<ModelId>? discoveredPotions = null, List<ModelId>? discoveredRelics = null)
		{
			RunState = NullRunState.Instance;
			Character = character;
			NetId = netId;
			Creature = new Creature(this, currentHp, maxHp);
			MaxEnergy = maxEnergy;
			Gold = gold;
			SetMaxPotionCountInternal(potionSlotCount);
			BaseOrbSlotCount = orbSlotCount;
			RelicGrabBag = sharedRelicGrabBag;
			UnlockState = unlockState;
			PlayerRng = new PlayerRngSet(0uL);
			PlayerOdds = new PlayerOddsSet(PlayerRng);
			DiscoveredCards = discoveredCards ?? new List<ModelId>();
			DiscoveredEnemies = discoveredEnemies ?? new List<ModelId>();
			DiscoveredEpochs = discoveredEpochs ?? new List<string>();
			DiscoveredPotions = discoveredPotions ?? new List<ModelId>();
			DiscoveredRelics = discoveredRelics ?? new List<ModelId>();
			IsActiveForHooks = Creature.IsAlive;
			MaxAscensionWhenRunStarted = (SaveManager.Instance?.Progress.GetStatsForCharacter(Character.Id))?.MaxAscension ?? 0;
		}

		/// <summary>
		/// Create a new player for use at the start of a new run.
		/// The player's inventory will be populated with the chosen character's starting cards, relics, etc., but these
		/// models will not work properly until the player is added to a <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.RunState" /> and/or
		/// <see cref="T:MegaCrit.Sts2.Core.Combat.CombatState" />.
		/// </summary>
		/// <param name="unlockState">The set of unlocks the player entered the run with.</param>
		/// <param name="netId">ID for uniquely identifying this player in multiplayer games.</param>
		/// <typeparam name="T">The type of the character that the player is playing as.</typeparam>
		/// <returns>A new player with an empty inventory.</returns>
		public static Player CreateForNewRun<T>(UnlockState unlockState, ulong netId) where T : CharacterModel
		{
			return CreateForNewRun(ModelDb.Character<T>(), unlockState, netId);
		}

		/// <summary>
		/// Create a new player for use at the start of a new run.
		/// The player's inventory will be populated with the chosen character's starting cards, relics, etc., but these
		/// models will not work properly until the player is added to a <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.RunState" /> and/or
		/// <see cref="T:MegaCrit.Sts2.Core.Combat.CombatState" />.
		/// </summary>
		/// <param name="character">The character that the player is playing as.</param>
		/// <param name="unlockState">The set of unlocks the player entered the run with.</param>
		/// <param name="netId">ID for uniquely identifying this player in multiplayer games.</param>
		/// <returns>A new player with an empty inventory.</returns>
		public static Player CreateForNewRun(CharacterModel character, UnlockState unlockState, ulong netId)
		{
			Player player = new Player(character, netId, character.StartingHp, character.StartingHp, character.MaxEnergy, character.StartingGold, 3, character.BaseOrbSlotCount, new RelicGrabBag(), unlockState);
			player.PopulateStartingInventory();
			return player;
		}

		/// <summary>
		/// Load a player from a SerializablePlayer.
		/// The player's inventory will be populated with the cards, relics, etc. from the SerializablePlayer., but these
		/// models will not work properly until the player is added to a <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.RunState" /> and/or
		/// <see cref="T:MegaCrit.Sts2.Core.Combat.CombatState" />.
		/// </summary>
		public static Player FromSerializable(SerializablePlayer save)
		{
			Player player = new Player(ModelDb.GetById<CharacterModel>(save.CharacterId), save.NetId, save.CurrentHp, save.MaxHp, save.MaxEnergy, save.Gold, save.MaxPotionSlotCount, save.BaseOrbSlotCount, MegaCrit.Sts2.Core.Runs.RelicGrabBag.FromSerializable(save.RelicGrabBag), MegaCrit.Sts2.Core.Unlocks.UnlockState.FromSerializable(save.UnlockState), save.DiscoveredCards.ToList(), save.DiscoveredEnemies.ToList(), save.DiscoveredEpochs.ToList(), save.DiscoveredPotions.ToList(), save.DiscoveredRelics.ToList());
			player.PlayerRng = PlayerRngSet.FromSerializable(save.Rng);
			player.PlayerOdds = PlayerOddsSet.FromSerializable(save.Odds, player.PlayerRng);
			player.ExtraFields = ExtraPlayerFields.FromSerializable(save.ExtraFields);
			player.LoadInventory(save);
			return player;
		}

		public void InitializeSeed(string seed)
		{
			PlayerRng = new PlayerRngSet(StringHelper.GetDeterministicHashCode(seed) + (ulong)_runState.GetPlayerSlotIndex(this));
			PlayerOdds = new PlayerOddsSet(PlayerRng);
		}

		private void PopulateStartingInventory()
		{
			if (IsInventoryPopulated)
			{
				throw new InvalidOperationException("Inventory is already populated.");
			}
			if (!(RunState is NullRunState))
			{
				throw new InvalidOperationException("A player's starting inventory must be populated before being added to a run.");
			}
			PopulateStartingDeck();
			PopulateStartingRelics();
			foreach (PotionModel item in Character.StartingPotions.Select((PotionModel p) => p.ToMutable()))
			{
				AddPotionInternal(item);
			}
		}

		private void LoadInventory(SerializablePlayer save)
		{
			if (IsInventoryPopulated)
			{
				throw new InvalidOperationException("Inventory is already populated.");
			}
			if (!(RunState is NullRunState))
			{
				throw new InvalidOperationException("A player's inventory must be loaded before being added to a run.");
			}
			PopulateDeck(save.Deck.Select(CardModel.FromSerializable));
			LoadPotions(save.Potions);
			PopulateRelics(save.Relics.Select(RelicModel.FromSerializable));
		}

		public void PopulateRelicGrabBagIfNecessary(Rng rng)
		{
			if (!RelicGrabBag.IsPopulated)
			{
				RelicGrabBag.Populate(this, rng);
			}
		}

		public SerializablePlayer ToSerializable()
		{
			return new SerializablePlayer
			{
				CharacterId = Character.Id,
				CurrentHp = Creature.CurrentHp,
				MaxHp = Creature.MaxHp,
				MaxEnergy = MaxEnergy,
				MaxPotionSlotCount = MaxPotionCount,
				BaseOrbSlotCount = BaseOrbSlotCount,
				NetId = NetId,
				Gold = Gold,
				Rng = PlayerRng.ToSerializable(),
				Odds = PlayerOdds.ToSerializable(),
				RelicGrabBag = RelicGrabBag.ToSerializable(),
				Deck = Deck.Cards.Select((CardModel c) => c.ToSerializable()).ToList(),
				Relics = Relics.Select((RelicModel r) => r.ToSerializable()).ToList(),
				Potions = PotionSlots.Select((PotionModel p, int i) => p?.ToSerializable(i)).OfType<SerializablePotion>().ToList(),
				ExtraFields = ExtraFields.ToSerializable(),
				UnlockState = UnlockState.ToSerializable(),
				DiscoveredCards = DiscoveredCards.ToList(),
				DiscoveredEnemies = DiscoveredEnemies.ToList(),
				DiscoveredEpochs = DiscoveredEpochs.ToList(),
				DiscoveredPotions = DiscoveredPotions.ToList(),
				DiscoveredRelics = DiscoveredRelics.ToList()
			};
		}

		public void SyncWithSerializedPlayer(SerializablePlayer player)
		{
			if (player.NetId != NetId)
			{
				throw new InvalidOperationException($"Tried to sync player that has net ID {NetId} with SerializablePlayer that has net ID {player.NetId}!");
			}
			if (player.CharacterId != Character.Id)
			{
				throw new InvalidOperationException($"Character changed for player {NetId}! This is not allowed");
			}
			Creature.SetMaxHpInternal(player.MaxHp);
			Creature.SetCurrentHpInternal(player.CurrentHp);
			MaxEnergy = player.MaxEnergy;
			Gold = player.Gold;
			SetMaxPotionCountInternal(player.MaxPotionSlotCount);
			Deck.Clear(silent: true);
			foreach (RelicModel item in _relics.ToList())
			{
				RemoveRelicInternal(item, silent: true);
			}
			foreach (PotionModel item2 in _potionSlots.ToList())
			{
				if (item2 != null)
				{
					DiscardPotionInternal(item2, silent: true);
				}
			}
			PopulateDeck(player.Deck.Select((SerializableCard c) => RunState.LoadCard(c, this)), silent: true);
			PopulateRelics(player.Relics.Select(RelicModel.FromSerializable), silent: true);
			LoadPotions(player.Potions, silent: true);
			PlayerRng.LoadFromSerializable(player.Rng);
			PlayerOdds.LoadFromSerializable(player.Odds);
			RelicGrabBag.LoadFromSerializable(player.RelicGrabBag);
			DiscoveredCards = player.DiscoveredCards.ToList();
			DiscoveredEnemies = player.DiscoveredEnemies.ToList();
			DiscoveredEpochs = player.DiscoveredEpochs.ToList();
			DiscoveredPotions = player.DiscoveredPotions.ToList();
			DiscoveredRelics = player.DiscoveredRelics.ToList();
			ExtraFields = ExtraPlayerFields.FromSerializable(player.ExtraFields);
			IsActiveForHooks = Creature.IsAlive;
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// Only RelicCmd.Obtain and save/load stuff should be calling this.
		/// </summary>
		/// <param name="relic">Relic to add.</param>
		/// <param name="index">Index at which relic should be inserted. -1 means at the end.</param>
		/// <param name="silent">If true, RelicObtained will not be called.</param>
		public void AddRelicInternal(RelicModel relic, int index = -1, bool silent = false)
		{
			relic.AssertMutable();
			relic.Owner = this;
			if (index == -1)
			{
				_relics.Add(relic);
			}
			else
			{
				_relics.Insert(index, relic);
			}
			if (relic != null && !relic.IsMelted && relic.ShouldFlashOnPlayer)
			{
				relic.Flashed += OnRelicFlashed;
			}
			if (!silent)
			{
				RelicObtained?.Invoke(relic);
			}
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY RelicCmd.Remove should be calling this.
		/// </summary>
		/// <param name="relic">Relic to remove.</param>
		/// <param name="silent">If true, RelicRemoved will not be called.</param>
		public void RemoveRelicInternal(RelicModel relic, bool silent = false)
		{
			if (!_relics.Contains(relic))
			{
				throw new InvalidOperationException($"Player does not have relic {relic.Id}");
			}
			_relics.Remove(relic);
			relic.RemoveInternal();
			if (relic.ShouldFlashOnPlayer)
			{
				relic.Flashed -= OnRelicFlashed;
			}
			if (!silent)
			{
				RelicRemoved?.Invoke(relic);
			}
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY RelicCmd.Melt should be calling this.
		/// </summary>
		/// <param name="relic">Relic to melt.</param>
		public void MeltRelicInternal(RelicModel relic)
		{
			if (!relic.IsWax)
			{
				throw new InvalidOperationException($"{relic.Id} is not wax.");
			}
			if (relic.IsMelted)
			{
				throw new InvalidOperationException($"{relic.Id} is already melted.");
			}
			if (!_relics.Contains(relic))
			{
				throw new InvalidOperationException($"Player does not have relic {relic.Id}");
			}
			if (relic.ShouldFlashOnPlayer)
			{
				relic.Flashed -= OnRelicFlashed;
			}
			relic.IsMelted = true;
			relic.Status = RelicStatus.Disabled;
		}

		/// <summary>
		/// Get one of this player's relics.
		/// If the player has multiple of the same type of relic, just get the first one.
		/// If the player has none of this type of relic, returns null.
		/// </summary>
		/// <typeparam name="T">Type of relic to get.</typeparam>
		/// <returns>Matching relic.</returns>
		public T? GetRelic<T>() where T : RelicModel
		{
			return Relics.FirstOrDefault((RelicModel r) => r is T) as T;
		}

		public RelicModel? GetRelicById(ModelId id)
		{
			return Relics.FirstOrDefault((RelicModel r) => r.Id == id);
		}

		/// <summary>
		/// Returns the slot index of the potion in the player's belt, or -1 if it is not in the belt.
		/// </summary>
		public int GetPotionSlotIndex(PotionModel model)
		{
			return _potionSlots.IndexOf(model);
		}

		/// <summary>
		/// Returns the potion at the slot index, or throws if the index is out of range.
		/// </summary>
		public PotionModel? GetPotionAtSlotIndex(int index)
		{
			if (index < 0 || index >= _potionSlots.Count)
			{
				throw new IndexOutOfRangeException($"Index {index} is not a valid potion slot index! Player has {_potionSlots.Count} potion slots");
			}
			return _potionSlots[index];
		}

		/// <summary>
		/// Increases the maximum amount of potions the player can hold.
		/// </summary>
		/// <param name="maxPotionCountIncrease">The increased count of maximum amount of potions the player can carry.</param>
		public void AddToMaxPotionCount(int maxPotionCountIncrease)
		{
			SetMaxPotionCountInternal(_potionSlots.Count + maxPotionCountIncrease);
		}

		/// <summary>
		/// Decreases the maximum amount of potions the player can hold.
		/// </summary>
		/// <param name="maxPotionCountDecrease">The decreased count of maximum amount of potions the player can carry.</param>
		public void SubtractFromMaxPotionCount(int maxPotionCountDecrease)
		{
			SetMaxPotionCountInternal(_potionSlots.Count - maxPotionCountDecrease);
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY save/load stuff should be calling this.
		/// </summary>
		/// <param name="newMaxPotionCount">The new maximum amount of potions the player can carry.</param>
		private void SetMaxPotionCountInternal(int newMaxPotionCount)
		{
			if (newMaxPotionCount > _potionSlots.Count)
			{
				for (int i = _potionSlots.Count; i < newMaxPotionCount; i++)
				{
					_potionSlots.Add(null);
				}
				MaxPotionCountChanged?.Invoke(MaxPotionCount);
			}
			else
			{
				if (newMaxPotionCount >= _potionSlots.Count)
				{
					return;
				}
				for (int num = _potionSlots.Count - 1; num >= newMaxPotionCount; num--)
				{
					if (_potionSlots[num] != null)
					{
						int num2 = _potionSlots.IndexOf(null);
						if (num2 < newMaxPotionCount)
						{
							_potionSlots[num2] = _potionSlots[num];
						}
						else
						{
							DiscardPotionInternal(_potionSlots[num]);
						}
					}
					_potionSlots.RemoveAt(num);
				}
				MaxPotionCountChanged?.Invoke(MaxPotionCount);
			}
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY PotionCmd.Procure and save/load stuff should be calling this.
		/// </summary>
		/// <param name="potion">Potion to add.</param>
		/// <param name="slotIndex">Slot at which to add the potion. If -1, the potion will be added in the first available slot.</param>
		/// <param name="silent">If true, no events will be called.</param>
		public PotionProcureResult AddPotionInternal(PotionModel potion, int slotIndex = -1, bool silent = false)
		{
			potion.AssertMutable();
			PotionProcureResult potionProcureResult = new PotionProcureResult
			{
				potion = potion
			};
			if (slotIndex < 0)
			{
				slotIndex = _potionSlots.IndexOf(null);
			}
			if (slotIndex >= 0)
			{
				if (_potionSlots[slotIndex] != null)
				{
					Log.Warn($"Tried to add potion {potion} at slot index {slotIndex} which is already filled with potion {_potionSlots[slotIndex]}!");
					if (!silent)
					{
						AddPotionFailed?.Invoke();
					}
					potionProcureResult.success = false;
					potionProcureResult.failureReason = PotionProcureFailureReason.TooFull;
					return potionProcureResult;
				}
				potion.Owner = this;
				_potionSlots[slotIndex] = potion;
				if (!silent)
				{
					PotionProcured?.Invoke(potion);
				}
				potionProcureResult.success = true;
			}
			else
			{
				if (!silent)
				{
					AddPotionFailed?.Invoke();
				}
				potionProcureResult.success = false;
				potionProcureResult.failureReason = PotionProcureFailureReason.TooFull;
			}
			return potionProcureResult;
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY PotionModel.Discard should be calling this.
		/// </summary>
		/// <param name="potion">Potion to discard.</param>
		/// <param name="silent">If true, PotionDiscarded will not be called.</param>
		public void DiscardPotionInternal(PotionModel potion, bool silent = false)
		{
			RemovePotionInternal(potion);
			if (!silent)
			{
				PotionDiscarded?.Invoke(potion);
			}
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY PotionModel.Remove should be calling this.
		/// </summary>
		/// <param name="potion">Used potion to remove.</param>
		public void RemoveUsedPotionInternal(PotionModel potion)
		{
			RemovePotionInternal(potion);
			UsedPotionRemoved?.Invoke(potion);
		}

		private void RemovePotionInternal(PotionModel potion)
		{
			int num = _potionSlots.IndexOf(potion);
			if (num < 0)
			{
				throw new InvalidOperationException($"Tried to remove potion you don't have: {potion.Id}");
			}
			_potionSlots[num] = null;
		}

		/// <summary>
		/// Populates the character's starting deck to start a new game.
		/// </summary>
		private void PopulateStartingDeck()
		{
			List<CardModel> list = new List<CardModel>();
			foreach (CardModel item in Character.StartingDeck)
			{
				CardModel cardModel = item.ToMutable();
				cardModel.FloorAddedToDeck = 1;
				list.Add(cardModel);
			}
			PopulateDeck(list);
		}

		/// <summary>
		/// Populates a player's existing deck.
		/// This can be from a multiplayer sync or from a save file.
		/// </summary>
		/// <param name="cards">Cards to load.</param>
		/// <param name="silent">
		/// Whether or not to emit events. If loading from a multiplayer sync, we don't want to emit events.
		/// </param>
		private void PopulateDeck(IEnumerable<CardModel> cards, bool silent = false)
		{
			if (Deck.Cards.Any())
			{
				throw new InvalidOperationException("Deck has already been populated.");
			}
			foreach (CardModel card in cards)
			{
				Deck.AddInternal(card, -1, silent);
			}
		}

		private void PopulateStartingRelics()
		{
			List<RelicModel> list = Character.StartingRelics.Select((RelicModel r) => r.ToMutable()).ToList();
			foreach (RelicModel item in list)
			{
				item.FloorAddedToDeck = 1;
				SaveManager.Instance.MarkRelicAsSeen(item);
			}
			PopulateRelics(list);
		}

		/// <summary>
		/// Loads a player's existing relic set.
		/// This can be from the player's starting relics, from a multiplayer sync, or from a save file.
		/// </summary>
		/// <param name="relics">Relics to load.</param>
		/// <param name="silent">
		/// Whether or not to emit events. If loading from a multiplayer sync, we don't want to emit events.
		/// </param>
		private void PopulateRelics(IEnumerable<RelicModel> relics, bool silent = false)
		{
			if (Relics.Any())
			{
				throw new InvalidOperationException("Relics have already been populated.");
			}
			foreach (RelicModel relic in relics)
			{
				AddRelicInternal(relic, -1, silent);
			}
		}

		/// <summary>
		/// Loads a player's existing potion set.
		/// This can be from a multiplayer sync or from a save file.
		/// </summary>
		/// <param name="serializablePotions">Cards to load.</param>
		/// <param name="silent">Whether or not to emit events. If loading from a multiplayer sync, we don't want to emit events.</param>
		private void LoadPotions(List<SerializablePotion> serializablePotions, bool silent = false)
		{
			if (Potions.Any())
			{
				throw new InvalidOperationException("Potions have already been populated.");
			}
			foreach (SerializablePotion serializablePotion in serializablePotions)
			{
				AddPotionInternal(PotionModel.FromSerializable(serializablePotion), serializablePotion.SlotIndex, silent);
			}
		}

		/// <summary>
		/// Resets the player's combat state to an empty state.
		/// This will leave the player with no cards in combat, so you should usually call <see cref="M:MegaCrit.Sts2.Core.Entities.Players.Player.PopulateCombatState(MegaCrit.Sts2.Core.Random.Rng,MegaCrit.Sts2.Core.Combat.CombatState)" />
		/// after.
		/// </summary>
		public void ResetCombatState()
		{
			PlayerCombatState = new PlayerCombatState(this);
		}

		/// <summary>
		/// Populates the player's combat state with everything they should get at the start of combat.
		/// For example, this clones all the cards from their deck into their draw pile in a random order.
		/// </summary>
		public void PopulateCombatState(Rng rng, CombatState state)
		{
			foreach (CardModel item in Deck.Cards.ToList())
			{
				CardModel cardModel = state.CloneCard(item);
				cardModel.DeckVersion = item;
				PlayerCombatState.DrawPile.AddInternal(cardModel);
			}
			PlayerCombatState.DrawPile.RandomizeOrderInternal(this, rng, state);
		}

		/// <summary>
		/// Revives the player before the combat ends, in multiplayer only. Should only trigger when combat ends with other
		/// players alive.
		/// It is very important to do this _before_ combat ends instead of after. If the player is still dead during
		/// HookBus.AfterCombatEnd, their relics will not be subscribed to the HookBus, and relics which rely on AfterCombatEnd
		/// to reset state will not be reset for the next combat.
		/// See: Centennial Puzzle, Captain's Wheel, or any other relics that use AfterCombatEnd.
		/// </summary>
		public async Task ReviveBeforeCombatEnd()
		{
			if (Creature.IsDead)
			{
				await CreatureCmd.Heal(Creature, 1m);
			}
		}

		/// <summary>
		/// Called after combat ends, giving the player the opportunity to do things like clear out their combat state and
		/// other combat teardown stuff.
		/// </summary>
		public void AfterCombatEnd()
		{
			Creature.RemoveAllPowersInternalExcept();
			PlayerCombatState?.AfterCombatEnd();
			Creature.LoseBlockInternal(Creature.Block);
		}

		private void OnRelicFlashed(RelicModel relic, IEnumerable<Creature> targets)
		{
			SfxCmd.Play(relic.FlashSfx);
			foreach (Creature target in targets)
			{
				target.GetVfxContainer()?.AddChildSafely(NRelicFlashVfx.Create(relic, target));
			}
		}

		public void OnSideSwitch()
		{
		}

		/// <summary>
		/// Called from Creature when the player reaches zero health, after all hooks that prevent death are called, as well
		/// as <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.AfterDeath(MegaCrit.Sts2.Core.Runs.IRunState,MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Entities.Creatures.Creature,System.Boolean,System.Single)" />.
		/// </summary>
		public void DeactivateHooks()
		{
			IsActiveForHooks = false;
		}

		/// <summary>
		/// Called from Creature when the player changes from a dead state to a non-dead state.
		/// This is _not_ called in the scenario when death is prevented, e.g. by Fairy in a Bottle.
		/// Likely only called in multiplayer scenarios - players cannot revive in singleplayer (remember that death
		/// prevention is different).
		/// </summary>
		public void ActivateHooks()
		{
			IsActiveForHooks = true;
		}
	}
	public class PlayerCombatState
	{
		private readonly Player _player;

		private readonly List<Creature> _pets = new List<Creature>();

		private CardPile[]? _piles;

		private int _energy;

		private int _stars;

		private PlayerTurnPhase _phase;

		public IReadOnlyList<Creature> Pets => _pets;

		/// <summary>
		/// The turn number that this player is currently on.
		/// This is different from <see cref="P:MegaCrit.Sts2.Core.Combat.ICombatState.RoundNumber" />; if a player takes an extra turn after their
		/// current one, this will be incremented, while the round number will not.
		/// This number can also be different between players in multiplayer. If one player takes an extra turn (due to an
		/// effect like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.PaelsEye" />), their turn number will increment, but other players' will not.
		/// This starts at 1, so it should never be 0.
		/// </summary>
		public int TurnNumber { get; private set; } = 1;

		/// <summary>
		/// The current phase of this player's turn. <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.None" /> when combat is not in progress
		/// and during the enemy's turn. See <see cref="T:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase" /> for the meaning of each phase.
		/// Managed by <see cref="T:MegaCrit.Sts2.Core.Combat.CombatManager" /> and <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.AfterAutoPrePlayPhaseEntered(MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext,MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		public PlayerTurnPhase Phase
		{
			get
			{
				return _phase;
			}
			set
			{
				if (value != _phase)
				{
					_phase = value;
					PlayerTurnPhaseChanged?.Invoke();
				}
			}
		}

		public CardPile Hand { get; } = new CardPile(PileType.Hand);

		public CardPile DrawPile { get; } = new CardPile(PileType.Draw);

		public CardPile DiscardPile { get; } = new CardPile(PileType.Discard);

		public CardPile ExhaustPile { get; } = new CardPile(PileType.Exhaust);

		public CardPile PlayPile { get; } = new CardPile(PileType.Play);

		public IReadOnlyList<CardPile> AllPiles
		{
			get
			{
				if (_piles == null)
				{
					_piles = new CardPile[5] { Hand, DrawPile, DiscardPile, ExhaustPile, PlayPile };
				}
				return _piles;
			}
		}

		public IEnumerable<CardModel> AllCards => AllPiles.SelectMany((CardPile p) => p.Cards);

		public int Energy
		{
			get
			{
				return _energy;
			}
			set
			{
				if (_energy != value)
				{
					int energy = _energy;
					_energy = value;
					EnergyChanged?.Invoke(energy, _energy);
				}
			}
		}

		public int MaxEnergy => (int)Hook.ModifyMaxEnergy(_player.Creature.CombatState, _player, _player.MaxEnergy);

		public int Stars
		{
			get
			{
				return _stars;
			}
			set
			{
				if (_stars != value)
				{
					int stars = _stars;
					_stars = value;
					CombatManager.Instance.History.StarsModified(_player.Creature.CombatState, _stars - stars, _player);
					StarsChanged?.Invoke(stars, _stars);
				}
			}
		}

		public OrbQueue OrbQueue { get; }

		public event Action? PlayerTurnPhaseChanged;

		public event Action<int, int>? EnergyChanged;

		public event Action<int, int>? StarsChanged;

		public PlayerCombatState(Player player)
		{
			_player = player;
			CombatManager.Instance.StateTracker.Subscribe(this);
			foreach (CardPile allPile in AllPiles)
			{
				CombatManager.Instance.StateTracker.Subscribe(allPile);
			}
			OrbQueue = new OrbQueue(player);
			OrbQueue.Clear();
			OrbQueue.AddCapacity(player.BaseOrbSlotCount);
		}

		public void AfterCombatEnd()
		{
			CombatManager.Instance.StateTracker.Unsubscribe(this);
			foreach (CardPile allPile in AllPiles)
			{
				allPile.Clear();
				CombatManager.Instance.StateTracker.Unsubscribe(allPile);
			}
			_pets.Clear();
		}

		/// <summary>
		/// Increment this player's current turn number.
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState.TurnNumber" /> for details on turn number versus <see cref="P:MegaCrit.Sts2.Core.Combat.ICombatState.RoundNumber" />.
		/// </summary>
		public void IncrementTurnNumber()
		{
			TurnNumber++;
		}

		public void ResetEnergy()
		{
			Energy = MaxEnergy;
		}

		public void AddMaxEnergyToCurrent()
		{
			Energy += MaxEnergy;
		}

		public void LoseEnergy(decimal amount)
		{
			if (amount < 0m)
			{
				throw new ArgumentException("Must not be negative.", "amount");
			}
			Energy = (int)Math.Clamp((decimal)Energy - amount, 0m, 999999999m);
		}

		public void GainEnergy(decimal amount)
		{
			if (amount < 0m)
			{
				throw new ArgumentException("Must not be negative.", "amount");
			}
			Energy = (int)Math.Clamp((decimal)Energy + amount, 0m, 999999999m);
		}

		public bool HasEnoughResourcesFor(CardModel card, out UnplayableReason reason)
		{
			int num = Math.Max(0, card.EnergyCost.GetWithModifiers(CostModifiers.All));
			int num2 = Math.Max(0, card.GetStarCostWithModifiers());
			if (num > Energy && card.CombatState != null && Hook.ShouldPayExcessEnergyCostWithStars(card.CombatState, _player))
			{
				num2 += (num - Energy) * 2;
				num = Energy;
			}
			reason = UnplayableReason.None;
			if (num > Energy)
			{
				reason |= UnplayableReason.EnergyCostTooHigh;
			}
			if (num2 > Stars)
			{
				reason |= UnplayableReason.StarCostTooHigh;
			}
			return reason == UnplayableReason.None;
		}

		public void LoseStars(decimal amount)
		{
			if (amount < 0m)
			{
				throw new ArgumentException("Must not be negative.", "amount");
			}
			Stars = (int)Math.Max((decimal)Stars - amount, 0m);
		}

		public void GainStars(decimal amount)
		{
			if (amount < 0m)
			{
				throw new ArgumentException("Must not be negative.", "amount");
			}
			Stars = (int)Math.Max((decimal)Stars + amount, 0m);
		}

		/// <summary>
		/// NEVER CALL THIS!
		/// ONLY <see cref="M:MegaCrit.Sts2.Core.Commands.PlayerCmd.AddPet``1(MegaCrit.Sts2.Core.Entities.Players.Player)" /> and save/load stuff should be calling this.
		/// </summary>
		/// <param name="pet">Pet to add.</param>
		public void AddPetInternal(Creature pet)
		{
			pet.Monster.AssertMutable();
			if (!_pets.Contains(pet))
			{
				if (pet.PetOwner != _player)
				{
					pet.PetOwner = _player;
				}
				pet.Died += OnPetDied;
				_pets.Add(pet);
			}
		}

		/// <summary>
		/// Get one of this player's pets.
		/// If the player has multiple of the same type of pet, just get the first one.
		/// If the player has none of this type of pet, returns null.
		/// </summary>
		/// <typeparam name="T">Type of pet to get.</typeparam>
		/// <returns>Matching pet.</returns>
		public Creature? GetPet<T>() where T : MonsterModel
		{
			return Pets.FirstOrDefault((Creature p) => p.Monster is T);
		}

		public void RecalculateCardValues()
		{
			foreach (CardModel allCard in AllCards)
			{
				allCard.Enchantment?.RecalculateValues();
			}
		}

		public void EndOfTurnCleanup()
		{
			foreach (CardModel allCard in AllCards)
			{
				allCard.EndOfTurnCleanup();
			}
		}

		public bool HasCardsToPlay()
		{
			return Hand.Cards.Any((CardModel c) => c.CanPlay());
		}

		private void OnPetDied(Creature pet)
		{
			if (!_pets.Contains(pet))
			{
				throw new InvalidOperationException("Player does not have pet " + pet.LogName);
			}
			if (Hook.ShouldCreatureBeRemovedFromCombatAfterDeath(pet.CombatState, pet))
			{
				pet.Died -= OnPetDied;
				_pets.Remove(pet);
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Entities.Orbs
{
	public class OrbQueue
	{
		public const int maxCapacity = 10;

		private readonly Player _owner;

		private readonly List<OrbModel> _orbs = new List<OrbModel>();

		public IReadOnlyList<OrbModel> Orbs => _orbs;

		public int Capacity { get; private set; }

		public OrbQueue(Player owner)
		{
			_owner = owner;
		}

		public void Clear()
		{
			_orbs.Clear();
			Capacity = 0;
		}

		public void AddCapacity(int capacity)
		{
			Capacity += capacity;
		}

		public void RemoveCapacity(int capacity)
		{
			Capacity = Math.Max(0, Capacity - capacity);
			while (Orbs.Count > Capacity)
			{
				Remove(_orbs.Last());
			}
		}

		public async Task<bool> TryEnqueue(OrbModel orb)
		{
			if (Capacity == 0)
			{
				return false;
			}
			orb.AssertMutable();
			if (Orbs.Count >= Capacity)
			{
				throw new InvalidOperationException("OrbQueue is full");
			}
			_orbs.Add(orb);
			await SmallWait();
			return true;
		}

		public bool Remove(OrbModel orb)
		{
			return _orbs.Remove(orb);
		}

		public void Insert(int idx, OrbModel orb)
		{
			if (idx >= Capacity)
			{
				throw new InvalidOperationException("idx cannot be greater than capacity");
			}
			_orbs.Insert(idx, orb);
		}

		public async Task BeforeTurnEnd(PlayerChoiceContext choiceContext)
		{
			foreach (OrbModel item in Orbs.ToList())
			{
				if (_owner.Creature.CombatState == null)
				{
					return;
				}
				await item.BeforeTurnEndOrbTrigger(choiceContext);
			}
		}

		public async Task AfterTurnStart(PlayerChoiceContext choiceContext)
		{
			foreach (OrbModel item in Orbs.ToList())
			{
				if (_owner.Creature.CombatState == null)
				{
					return;
				}
				await item.AfterTurnStartOrbTrigger(choiceContext);
			}
		}

		private async Task SmallWait()
		{
			if (LocalContext.IsMe(_owner))
			{
				await Cmd.CustomScaledWait(0.1f, 0.25f);
			}
			else
			{
				await Cmd.Wait(0.05f);
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Entities.Multiplayer
{
	public enum ActionSynchronizerCombatState
	{
		/// <summary>
		/// We're not in combat.
		/// </summary>
		NotInCombat,
		/// <summary>
		/// We're about to be in combat, and we're draining the queue of non-combat actions.
		/// </summary>
		PreCombatSetup,
		/// <summary>
		/// We're in combat, and the player is fully in control.
		/// </summary>
		PlayPhase,
		/// <summary>
		/// We're in combat, and we're in phase one of ending the turn.
		/// Queues are unpaused during this time to allow generated hook actions (like Well-Laid Plans) to execute, but all
		/// other types of actions will be automatically canceled to prevent interleaving of actions with hooks.
		/// </summary>
		EndTurnPhaseOne,
		/// <summary>
		/// We're in combat, and the player is not fully in control. This encapsulates the enemy turn and the draw phase of
		/// the player's turn.
		/// </summary>
		NotPlayPhase
	}
	/// <summary>
	/// Class for holding extra info to display in multiplayer errors if the error is a ConnectionFailureReason.
	/// </summary>
	public record ConnectionFailureExtraInfo
	{
		public PeerVersionInfo localInfo;

		public PeerVersionInfo remoteInfo;

		public bool localIsHost;

		public List<string> GetMissingModsOnLocal(bool nonGameplay)
		{
			if (!nonGameplay)
			{
				return remoteInfo.gameplayAffectingMods?.Except(localInfo.gameplayAffectingMods ?? new List<string>()).ToList() ?? new List<string>();
			}
			return remoteInfo.otherMods?.Except(localInfo.otherMods ?? new List<string>()).ToList() ?? new List<string>();
		}

		public List<string> GetMissingModsOnRemote(bool nonGameplay)
		{
			if (!nonGameplay)
			{
				return localInfo.gameplayAffectingMods?.Except(remoteInfo.gameplayAffectingMods ?? new List<string>()).ToList() ?? new List<string>();
			}
			return localInfo.otherMods?.Except(remoteInfo.otherMods ?? new List<string>()).ToList() ?? new List<string>();
		}
	}
	/// <summary>
	/// Sent in the InitialGameInfoMessage. If a client receives this, then they will be disconnected shortly after receiving
	/// the message, and they should show a relevant error.
	/// This is used specifically during connection. See DisconnectionReason for generic disconnection reasons.
	/// </summary>
	public enum ConnectionFailureReason
	{
		None,
		/// <summary>
		/// The lobby has reached the maximum number of players.
		/// </summary>
		LobbyFull,
		/// <summary>
		/// The host loaded from a save file and the client attempting to join is not one of the players in the save.
		/// </summary>
		NotInSaveGame,
		/// <summary>
		/// The run is already in progress and the client attempting to join is not one of the players in the run.
		/// </summary>
		RunInProgress,
		/// <summary>
		/// The host's game version does not match ours.
		/// </summary>
		VersionMismatch,
		/// <summary>
		/// Either the host has mods that we don't have, or we have mods that the host doesn't have.
		/// </summary>
		ModMismatch,
		/// <summary>
		/// The version handshake timed out.
		/// </summary>
		HandshakeTimeout
	}
	public enum GameActionType
	{
		None,
		/// <summary>
		/// Canceled if in the queue when we reach the end of combat, or if it is enqueued while we are not in combat.
		/// </summary>
		Combat,
		/// <summary>
		/// Canceled if in the queue when we reach the end of combat, or if it is enqueued while we are not in combat.
		/// If it is requested to be enqueued outside of the player's play phase, the request is deferred until it becomes
		/// the play phase for the local player.
		/// This is used for things like card plays and potion uses so that they occur only after the player turn is completely
		/// set up.
		/// </summary>
		CombatPlayPhaseOnly,
		/// <summary>
		/// Not canceled at the end of combat.
		/// If the action reaches the front of queue during combat, it will not be executed until the combat ends.
		/// </summary>
		NonCombat,
		/// <summary>
		/// Not canceled at the end of combat, and can be executed at any time (in or out of combat).
		/// </summary>
		Any
	}
	public struct LoadRunLobbyPlayer : IPacketSerializable
	{
		public ulong id;

		public bool isModded;

		public bool isReady;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteULong(id);
			writer.WriteBool(isModded);
			writer.WriteBool(isReady);
		}

		public void Deserialize(PacketReader reader)
		{
			id = reader.ReadULong();
			isModded = reader.ReadBool();
			isReady = reader.ReadBool();
		}

		public override string ToString()
		{
			return $"Player {id}";
		}
	}
	public struct NetChecksumData : IPacketSerializable
	{
		public uint id;

		public uint checksum;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteUInt(id);
			writer.WriteUInt(checksum);
		}

		public void Deserialize(PacketReader reader)
		{
			id = reader.ReadUInt();
			checksum = reader.ReadUInt();
		}
	}
	public struct NetClientData
	{
		public ulong peerId;

		public bool readyForBroadcasting;

		public PeerVersionInfo versionInfo;
	}
	public struct NetCombatCard : IPacketSerializable, IEquatable<NetCombatCard>
	{
		public uint CombatCardIndex { get; private set; }

		public static NetCombatCard ForTesting(uint index)
		{
			return new NetCombatCard
			{
				CombatCardIndex = index
			};
		}

		public static NetCombatCard FromModel(CardModel card)
		{
			if (!card.IsMutable)
			{
				throw new InvalidOperationException("Immutable instances of CardModel should not be serialized through NetCombatCard! Send the ModelId instead.");
			}
			CardPile pile = card.Pile;
			if (pile != null && !pile.IsCombatPile)
			{
				throw new InvalidOperationException("Cannot use NetCombatCard to serialize a card in a non-combat pile!");
			}
			return new NetCombatCard
			{
				CombatCardIndex = NetCombatCardDb.Instance.GetCardId(card)
			};
		}

		public readonly CardModel ToCardModel()
		{
			return NetCombatCardDb.Instance.GetCard(CombatCardIndex);
		}

		public readonly CardModel? ToCardModelOrNull()
		{
			NetCombatCardDb.Instance.TryGetCard(CombatCardIndex, out CardModel card);
			return card;
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteUInt(CombatCardIndex, 16);
		}

		public void Deserialize(PacketReader reader)
		{
			CombatCardIndex = reader.ReadUInt(16);
		}

		public bool Equals(NetCombatCard other)
		{
			return CombatCardIndex == other.CombatCardIndex;
		}

		public static bool operator ==(NetCombatCard c1, NetCombatCard c2)
		{
			return c1.Equals(c2);
		}

		public static bool operator !=(NetCombatCard c1, NetCombatCard c2)
		{
			return !c1.Equals(c2);
		}

		public override bool Equals(object? obj)
		{
			if (obj is NetCombatCard other)
			{
				return Equals(other);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return CombatCardIndex.GetHashCode();
		}

		public override string ToString()
		{
			return $"{"NetCombatCard"} {CombatCardIndex}";
		}
	}
	public struct NetDeckCard : IPacketSerializable
	{
		public uint DeckIndex { get; private set; }

		public static NetDeckCard FromModel(CardModel card)
		{
			if (!card.IsMutable)
			{
				throw new InvalidOperationException("Immutable instances of CardModel should not be serialized through NetDeckCard! Send the ModelId instead.");
			}
			if (card.Pile == null)
			{
				throw new InvalidOperationException("Cannot use NetDeckCard to serialize a card without a pile!");
			}
			if (card.Pile.Type != PileType.Deck)
			{
				throw new InvalidOperationException($"Cannot use {"NetDeckCard"} to serialize card {card} that is in a non-deck pile!");
			}
			return new NetDeckCard
			{
				DeckIndex = (uint)card.Pile.Cards.IndexOf(card)
			};
		}

		public readonly CardModel ToCardModel(Player player)
		{
			return player.Deck.Cards[(int)DeckIndex];
		}

		public void Serialize(PacketWriter writer)
		{
			writer.WriteUInt(DeckIndex, 16);
		}

		public void Deserialize(PacketReader reader)
		{
			DeckIndex = reader.ReadUInt(16);
		}

		public override string ToString()
		{
			return $"{"NetDeckCard"} {DeckIndex}";
		}
	}
	/// <summary>
	/// A list of reasons for which we may be disconnected from a remote host. Each of these is associated with a particular
	/// error message that we can show to the user.
	/// It's likely that this list will expand over time.
	/// Categories advance by 100 so that we can add more errors as time goes on. The list should stay stable between
	/// versions.
	/// </summary>
	public enum NetError
	{
		/// <summary>
		/// No reason was passed.
		/// </summary>
		None = 0,
		/// <summary>
		/// Normal quit (Host save and quit or quit the application).
		/// </summary>
		Quit = 1,
		/// <summary>
		/// Normal quit at the end of the run. Signals to clients they should not also quit the run.
		/// </summary>
		QuitGameOver = 2,
		/// <summary>
		/// Host abandoned the game without saving it.
		/// </summary>
		HostAbandoned = 3,
		/// <summary>
		/// We were forcibly removed from the game.
		/// </summary>
		Kicked = 4,
		/// <summary>
		/// Tried to join a user that is not currently in a multiplayer game.
		/// </summary>
		InvalidJoin = 5,
		/// <summary>
		/// The user cancelled the join flow before it was completed.
		/// </summary>
		CancelledJoin = 6,
		/// <summary>The lobby we tried to connect to is full.</summary>
		LobbyFull = 100,
		/// <summary>
		/// The run is already in progress, and rejoining is not implemented.
		/// </summary>
		RunInProgress = 101,
		/// <summary>
		/// The run was loaded from a save file, and the player attempting to connect is not in the save.
		/// </summary>
		NotInSaveGame = 102,
		/// <summary>
		/// The host's version does not match the client's.
		/// </summary>
		VersionMismatch = 103,
		/// <summary>
		/// You are banned from the lobby, you have blocked someone in the lobby, or someone in the lobby blocked you.
		/// </summary>
		JoinBlockedByUser = 104,
		/// <summary>
		/// Our state, as a client, diverged from the host's during combat.
		/// </summary>
		StateDivergence = 105,
		/// <summary>
		/// The client did not send the net-service-level handshake response in time.
		/// Different from an internet timeout, as that is below the application layer.
		/// </summary>
		HandshakeTimeout = 106,
		/// <summary>
		/// Either the host had mods that we didn't have, or we had mods that the host didn't have.
		/// </summary>
		ModMismatch = 107,
		/// <summary>
		/// The client responded with something invalid during the version handshake.
		/// </summary>
		InvalidHandshake = 108,
		/// <summary>
		/// The client did not send the response to the lobby join message in time.
		/// Different from an internet timeout, as that is below the application layer.
		/// </summary>
		LobbyJoinTimeout = 109,
		/// <summary>
		/// Couldn't connect to the session, likely because of internet issues.
		/// </summary>
		NoInternet = 200,
		/// <summary>
		/// Connection timed out.
		/// </summary>
		Timeout = 201,
		/// <summary>
		/// Internal error, like an exception or a similar local bug.
		/// </summary>
		InternalError = 202,
		/// <summary>
		/// Network issue that we are not sure how to diagnose.
		/// </summary>
		UnknownNetworkError = 203,
		/// <summary>
		/// Too many attempts to do the same thing. Player should try again in a bit.
		/// </summary>
		RateLimited = 204,
		/// <summary>
		/// Generic transient issue. Player should try again later.
		/// </summary>
		TryAgainLater = 205,
		/// <summary>
		/// Hosting the game failed.
		/// </summary>
		FailedToHost = 206,
		/// <summary>
		/// Couldn't make secure connection (Steam BadCert and BadCrypt). Most common cause is out-of-sync clocks.
		/// </summary>
		SecureConnectionFailed = 207
	}
	/// <summary>
	/// Contains information about why a network operation failed, or why we disconnected from a multiplayer session.
	/// Prefer passing this instead of NetError, as this contains more information about the underlying error that might
	/// have been mapped to our NetError.
	/// </summary>
	public struct NetErrorInfo
	{
		/// <summary>
		/// Used for errors that occur above the platform level, in our transport layers.
		/// </summary>
		private readonly NetError? _reason;

		/// <summary>
		/// Used when the disconnection was raised from the JoinFlow.
		/// </summary>
		private readonly ConnectionFailureReason? _connectionReason;

		/// <summary>
		/// Used when the disconnection was raised from the Steam transport.
		/// </summary>
		private readonly SteamDisconnectionReason? _steamReason;

		/// <summary>
		/// Used for Steam hosting when the lobby creation fails.
		/// </summary>
		private readonly EResult? _lobbyCreationResult;

		/// <summary>
		/// Use for Steam joining when entering the lobby fails. Even though it refers to "chat room", it really means "lobby".
		/// </summary>
		private readonly EChatRoomEnterResponse? _lobbyEnterResponse;

		/// <summary>
		/// String that accompanies the disconnection. Currently only used on the Steam platform.
		/// </summary>
		private readonly string? _debugReason;

		/// <summary>
		/// Used specifically for ENet hosting when lobby creation fails.
		/// If Godot errors occur elsewhere, expand the mapping for this error.
		/// </summary>
		private readonly Error? _godotError;

		/// <summary>
		/// Set to true if the disconnection was initiated by the local peer. For example, if the reason is Quit and this is
		/// true, then the disconnection was caused by a quit initiated locally. If the reason is Quit and this is false, then
		/// the disconnection was caused by a quit initiated remotely.
		/// </summary>
		public bool SelfInitiated { get; }

		/// <summary>
		/// Extra info about the disconnection.
		/// You usually do not need to access this directly; use GetErrorString and show that to the user.
		/// </summary>
		public ConnectionFailureExtraInfo? ConnectionExtraInfo { get; }

		/// <summary>
		/// Set to true if ANYONE in the session has mods.
		/// Don't trust this value fully, it probably doesn't get set for every error.
		/// </summary>
		public bool IsModded { get; private set; }

		public NetErrorInfo(NetError reason, bool selfInitiated)
		{
			_connectionReason = null;
			_steamReason = null;
			_lobbyCreationResult = null;
			_lobbyEnterResponse = null;
			_debugReason = null;
			_godotError = null;
			ConnectionExtraInfo = null;
			IsModded = false;
			_reason = reason;
			SelfInitiated = selfInitiated;
		}

		public NetErrorInfo(ConnectionFailureReason reason, ConnectionFailureExtraInfo? extraInfo = null)
		{
			_reason = null;
			_steamReason = null;
			_lobbyCreationResult = null;
			_lobbyEnterResponse = null;
			_debugReason = null;
			_godotError = null;
			IsModded = false;
			_connectionReason = reason;
			ConnectionExtraInfo = extraInfo;
			SelfInitiated = false;
		}

		public NetErrorInfo(SteamDisconnectionReason steamReason, string? debugReason, bool selfInitiated)
		{
			_reason = null;
			_connectionReason = null;
			_lobbyCreationResult = null;
			_lobbyEnterResponse = null;
			_godotError = null;
			ConnectionExtraInfo = null;
			IsModded = false;
			_steamReason = steamReason;
			_debugReason = debugReason;
			SelfInitiated = selfInitiated;
		}

		public NetErrorInfo(EChatRoomEnterResponse lobbyEnterResponse)
		{
			_reason = null;
			_connectionReason = null;
			_steamReason = null;
			_lobbyCreationResult = null;
			_debugReason = null;
			_godotError = null;
			ConnectionExtraInfo = null;
			IsModded = false;
			_lobbyEnterResponse = lobbyEnterResponse;
			SelfInitiated = true;
		}

		public NetErrorInfo(EResult lobbyCreationResult)
		{
			_reason = null;
			_connectionReason = null;
			_steamReason = null;
			_lobbyEnterResponse = null;
			_debugReason = null;
			_godotError = null;
			ConnectionExtraInfo = null;
			IsModded = false;
			_lobbyCreationResult = lobbyCreationResult;
			SelfInitiated = true;
		}

		public NetErrorInfo(Error error)
		{
			_reason = null;
			_connectionReason = null;
			_steamReason = null;
			_lobbyCreationResult = null;
			_lobbyEnterResponse = null;
			_debugReason = null;
			ConnectionExtraInfo = null;
			IsModded = false;
			_godotError = error;
			SelfInitiated = true;
		}

		public void SetModdedFlagIfModded(RunLobby? runLobby)
		{
			IsModded = runLobby?.AnyPlayerHadMods ?? false;
		}

		/// <summary>
		/// Returns a disconnection reason mapped from the underlying transport disconnection reason.
		/// </summary>
		public NetError GetReason()
		{
			if (_reason.HasValue)
			{
				return _reason.Value;
			}
			if (_connectionReason.HasValue)
			{
				ConnectionFailureReason value = _connectionReason.Value;
				return value switch
				{
					ConnectionFailureReason.None => NetError.None, 
					ConnectionFailureReason.LobbyFull => NetError.LobbyFull, 
					ConnectionFailureReason.RunInProgress => NetError.RunInProgress, 
					ConnectionFailureReason.NotInSaveGame => NetError.NotInSaveGame, 
					ConnectionFailureReason.VersionMismatch => NetError.VersionMismatch, 
					ConnectionFailureReason.ModMismatch => NetError.ModMismatch, 
					ConnectionFailureReason.HandshakeTimeout => NetError.HandshakeTimeout, 
				};
			}
			if (_steamReason.HasValue)
			{
				return _steamReason.Value.ToApp();
			}
			if (_lobbyCreationResult.HasValue)
			{
				return NetError.FailedToHost;
			}
			if (_lobbyEnterResponse.HasValue)
			{
				EChatRoomEnterResponse value2 = _lobbyEnterResponse.Value;
				return value2 switch
				{
					EChatRoomEnterResponse.k_EChatRoomEnterResponseDoesntExist => NetError.InvalidJoin, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseNotAllowed => NetError.InternalError, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseFull => NetError.LobbyFull, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseError => NetError.UnknownNetworkError, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseBanned => NetError.JoinBlockedByUser, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseLimited => NetError.UnknownNetworkError, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseClanDisabled => NetError.JoinBlockedByUser, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseCommunityBan => NetError.JoinBlockedByUser, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseMemberBlockedYou => NetError.JoinBlockedByUser, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseYouBlockedMember => NetError.JoinBlockedByUser, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseRatelimitExceeded => NetError.RateLimited, 
					EChatRoomEnterResponse.k_EChatRoomEnterResponseSuccess => NetError.None, 
				};
			}
			if (_godotError.HasValue)
			{
				return NetError.FailedToHost;
			}
			throw new InvalidOperationException("Tried to get DisconnectionReason from DisconnectionInfo without any assigned errors");
		}

		/// <summary>
		/// Returns a string with more human-readable details about the underlying cause of the disconnection.
		/// This is suitable for displaying to users as long as platform requirements allow plain error codes in messages.
		/// </summary>
		public string GetErrorString()
		{
			bool flag = ConnectionExtraInfo?.localIsHost ?? false;
			if (_reason.HasValue)
			{
				return _reason.Value.ToString();
			}
			if (_connectionReason.HasValue)
			{
				if (_connectionReason == ConnectionFailureReason.ModMismatch)
				{
					StringBuilder stringBuilder = new StringBuilder();
					List<string> list = ConnectionExtraInfo?.GetMissingModsOnRemote(nonGameplay: false);
					List<string> list2 = ConnectionExtraInfo?.GetMissingModsOnLocal(nonGameplay: false);
					if (list != null && list.Count > 0)
					{
						string locEntryKey = "NETWORK_ERROR." + (flag ? "HOST." : "") + "MOD_MISMATCH.description.missingOnHost";
						LocString locString = new LocString("main_menu_ui", locEntryKey);
						locString.Add("mods", string.Join(", ", list));
						stringBuilder.AppendLine(locString.GetFormattedText());
					}
					if (list2 != null && list2.Count > 0)
					{
						string locEntryKey2 = "NETWORK_ERROR." + (flag ? "HOST." : "") + "MOD_MISMATCH.description.missingOnLocal";
						LocString locString2 = new LocString("main_menu_ui", locEntryKey2);
						locString2.Add("mods", string.Join(", ", list2));
						stringBuilder.AppendLine(locString2.GetFormattedText());
					}
					return stringBuilder.ToString();
				}
				if (_connectionReason == ConnectionFailureReason.VersionMismatch)
				{
					if (ConnectionExtraInfo?.remoteInfo.version != ConnectionExtraInfo?.localInfo.version)
					{
						if (ConnectionExtraInfo?.remoteInfo.branch != ConnectionExtraInfo?.localInfo.branch)
						{
							string locEntryKey3 = "NETWORK_ERROR." + (flag ? "HOST." : "") + "VERSION_MISMATCH.description.branchMismatch";
							LocString locString3 = new LocString("main_menu_ui", locEntryKey3);
							locString3.Add("remoteBranch", ConnectionExtraInfo?.remoteInfo.branch.ToName() ?? "<null>");
							locString3.Add("localBranch", ConnectionExtraInfo?.localInfo.branch.ToName() ?? "<null>");
							return locString3.GetFormattedText();
						}
						string locEntryKey4 = "NETWORK_ERROR." + (flag ? "HOST." : "") + "VERSION_MISMATCH.description.versionMismatch";
						LocString locString4 = new LocString("main_menu_ui", locEntryKey4);
						locString4.Add("remoteVersion", ConnectionExtraInfo?.remoteInfo.version ?? "<null>");
						locString4.Add("localVersion", ConnectionExtraInfo?.localInfo.version ?? "<null>");
						return locString4.GetFormattedText();
					}
					if (ConnectionExtraInfo?.remoteInfo.idDatabaseHash != ConnectionExtraInfo?.localInfo.idDatabaseHash)
					{
						string locEntryKey5 = "NETWORK_ERROR." + (flag ? "HOST." : "") + "VERSION_MISMATCH.description.modelDbMismatch";
						LocString locString5 = new LocString("main_menu_ui", locEntryKey5);
						locString5.Add("remoteHash", ConnectionExtraInfo?.remoteInfo.idDatabaseHash.ToString() ?? "<null>");
						locString5.Add("localHash", ConnectionExtraInfo?.localInfo.idDatabaseHash.ToString() ?? "<null>");
						return locString5.GetFormattedText();
					}
				}
				return _connectionReason.Value.ToString();
			}
			if (_steamReason.HasValue)
			{
				return $"{_steamReason} - {_debugReason}";
			}
			if (_lobbyCreationResult.HasValue)
			{
				return $"Lobby creation failed: {_lobbyCreationResult.Value}";
			}
			if (_lobbyEnterResponse.HasValue)
			{
				return $"Lobby join failed: {_lobbyEnterResponse.Value}";
			}
			if (_godotError.HasValue)
			{
				return _godotError.Value.ToString();
			}
			return "<null>";
		}

		/// <summary>
		/// Returns a string that should not be displayed to the user. Use this in debug logs.
		/// </summary>
		public override string ToString()
		{
			if (_reason.HasValue)
			{
				return $"DisconnectionReason {_reason.Value} {SelfInitiated}";
			}
			if (_connectionReason.HasValue)
			{
				return $"ConnectionFailureReason {_connectionReason.Value} {SelfInitiated}";
			}
			if (_steamReason.HasValue)
			{
				return $"SteamDisconnectionReason {_steamReason.Value} {_debugReason} {SelfInitiated}";
			}
			if (_lobbyCreationResult.HasValue)
			{
				return $"EResult {_lobbyCreationResult.Value} {SelfInitiated}";
			}
			if (_lobbyEnterResponse.HasValue)
			{
				return $"EChatRoomEnterResponse {_lobbyEnterResponse.Value} {SelfInitiated}";
			}
			if (_godotError.HasValue)
			{
				return $"Godot.Error {_godotError.Value} {SelfInitiated}";
			}
			return "<null>";
		}
	}
	public class NetFullCombatState : IPacketSerializable
	{
		public struct CreatureState : IPacketSerializable
		{
			public ModelId? monsterId;

			public ulong? playerId;

			public int currentHp;

			public int maxHp;

			public int block;

			public List<PowerState> powers;

			public void Serialize(PacketWriter writer)
			{
				writer.WriteBool(monsterId != null);
				if (monsterId != null)
				{
					writer.WriteModelEntry(monsterId);
				}
				writer.WriteBool(playerId.HasValue);
				if (playerId.HasValue)
				{
					writer.WriteULong(playerId.Value);
				}
				writer.WriteInt(currentHp);
				writer.WriteInt(maxHp);
				writer.WriteInt(block);
				writer.WriteList(powers);
			}

			public void Deserialize(PacketReader reader)
			{
				if (reader.ReadBool())
				{
					monsterId = reader.ReadModelIdAssumingType<MonsterModel>();
				}
				if (reader.ReadBool())
				{
					playerId = reader.ReadULong();
				}
				currentHp = reader.ReadInt();
				maxHp = reader.ReadInt();
				block = reader.ReadInt();
				powers = reader.ReadList<PowerState>();
			}

			public CreatureState Anonymized()
			{
				CreatureState result = this;
				result.playerId = (playerId.HasValue ? new ulong?(IdAnonymizer.Anonymize(playerId.Value)) : ((ulong?)null));
				return result;
			}
		}

		public struct PowerState : IPacketSerializable
		{
			public ModelId id;

			public int amount;

			public void Serialize(PacketWriter writer)
			{
				writer.WriteModelEntry(id);
				writer.WriteInt(amount);
			}

			public void Deserialize(PacketReader reader)
			{
				id = reader.ReadModelIdAssumingType<PowerModel>();
				amount = reader.ReadInt();
			}
		}

		public struct OrbState : IPacketSerializable
		{
			public ModelId id;

			public int passive;

			public int evoke;

			public void Serialize(PacketWriter writer)
			{
				writer.WriteModelEntry(id);
				writer.WriteInt(passive, 16);
				writer.WriteInt(evoke, 16);
			}

			public void Deserialize(PacketReader reader)
			{
				id = reader.ReadModelIdAssumingType<OrbModel>();
				passive = reader.ReadInt(16);
				evoke = reader.ReadInt(16);
			}

			public static OrbState From(OrbModel orb)
			{
				return new OrbState
				{
					id = orb.Id,
					passive = (int)orb.PassiveVal,
					evoke = (int)orb.EvokeVal
				};
			}
		}

		/// <summary>
		/// All the combat-relevant state from the Player class.
		/// Includes most state except:
		///  - Rewards and Shop RNG counters (stripped out in FromRun)
		///  - Rarity odds
		/// </summary>
		public struct PlayerState : IPacketSerializable
		{
			public ulong playerId;

			public ModelId characterId;

			public int turnNumber;

			public PlayerTurnPhase phase;

			public int energy;

			public int stars;

			public int maxPotionCount;

			public int gold;

			public List<CombatPileState> piles;

			public List<PotionState> potions;

			public List<RelicState> relics;

			public List<OrbState> orbs;

			public SerializablePlayerRngSet rngSet;

			public SerializableRelicGrabBag relicGrabBag;

			public void Serialize(PacketWriter writer)
			{
				writer.WriteULong(playerId);
				writer.WriteModelEntry(characterId);
				writer.WriteInt(turnNumber);
				writer.WriteEnum(phase);
				writer.WriteInt(energy);
				writer.WriteInt(stars);
				writer.WriteInt(maxPotionCount);
				writer.WriteInt(gold);
				writer.WriteList(piles);
				writer.WriteList(potions);
				writer.WriteList(relics);
				writer.WriteList(orbs);
				writer.Write(rngSet);
				writer.Write(relicGrabBag);
			}

			public void Deserialize(PacketReader reader)
			{
				playerId = reader.ReadULong();
				characterId = reader.ReadModelIdAssumingType<CharacterModel>();
				turnNumber = reader.ReadInt();
				phase = reader.ReadEnum<PlayerTurnPhase>();
				energy = reader.ReadInt();
				stars = reader.ReadInt();
				maxPotionCount = reader.ReadInt();
				gold = reader.ReadInt();
				piles = reader.ReadList<CombatPileState>();
				potions = reader.ReadList<PotionState>();
				relics = reader.ReadList<RelicState>();
				orbs = reader.ReadList<OrbState>();
				rngSet = reader.Read<SerializablePlayerRngSet>();
				relicGrabBag = reader.Read<SerializableRelicGrabBag>();
			}

			public PlayerState Anonymized()
			{
				PlayerState result = this;
				result.playerId = IdAnonymizer.Anonymize(playerId);
				return result;
			}
		}

		public struct CombatPileState : IPacketSerializable
		{
			public PileType pileType;

			public List<CardState> cards;

			public void Serialize(PacketWriter writer)
			{
				writer.WriteInt((int)pileType);
				writer.WriteList(cards);
			}

			public void Deserialize(PacketReader reader)
			{
				pileType = (PileType)reader.ReadInt();
				cards = reader.ReadList<CardState>();
			}

			public static CombatPileState From(CardPile pile)
			{
				CombatPileState result = new CombatPileState
				{
					pileType = pile.Type,
					cards = new List<CardState>()
				};
				foreach (CardModel card in pile.Cards)
				{
					result.cards.Add(CardState.From(card));
				}
				return result;
			}
		}

		public struct CardState : IPacketSerializable
		{
			public SerializableCard card;

			public ModelId? affliction;

			public int afflictionCount;

			public int? energyCost;

			public List<CardKeyword>? keywords;

			public void Serialize(PacketWriter writer)
			{
				writer.Write(card);
				writer.WriteBool(affliction != null);
				if (affliction != null)
				{
					writer.WriteModelEntry(affliction);
					writer.WriteInt(afflictionCount);
				}
				writer.WriteBool(energyCost.HasValue);
				if (energyCost.HasValue)
				{
					writer.WriteInt(energyCost.Value);
				}
				writer.WriteBool(keywords != null);
				if (keywords == null)
				{
					return;
				}
				writer.WriteInt(keywords.Count, 3);
				foreach (CardKeyword keyword in keywords)
				{
					writer.WriteEnum(keyword);
				}
			}

			public void Deserialize(PacketReader reader)
			{
				card = reader.Read<SerializableCard>();
				if (reader.ReadBool())
				{
					affliction = reader.ReadModelIdAssumingType<AfflictionModel>();
					afflictionCount = reader.ReadInt();
				}
				if (reader.ReadBool())
				{
					energyCost = reader.ReadInt();
				}
				if (reader.ReadBool())
				{
					keywords = new List<CardKeyword>();
					int num = reader.ReadInt(3);
					for (int i = 0; i < num; i++)
					{
						keywords.Add(reader.ReadEnum<CardKeyword>());
					}
				}
			}

			public static CardState From(CardModel card)
			{
				CardState result = new CardState
				{
					card = card.ToSerializable(),
					affliction = card.Affliction?.Id,
					afflictionCount = (card.Affliction?.Amount ?? 0)
				};
				IReadOnlySet<CardKeyword> readOnlySet = card.Keywords;
				if (readOnlySet.Count > 0)
				{
					result.keywords = new List<CardKeyword>();
					CardKeyword[] values = Enum.GetValues<CardKeyword>();
					foreach (CardKeyword item in values)
					{
						if (readOnlySet.Contains(item))
						{
							result.keywords.Add(item);
						}
					}
				}
				else
				{
					result.keywords = null;
				}
				int withModifiers = card.EnergyCost.GetWithModifiers(CostModifiers.All);
				if (withModifiers != card.EnergyCost.Canonical)
				{
					result.energyCost = withModifiers;
				}
				return result;
			}
		}

