namespace MegaCrit.Sts2.Core.Entities.Models
{
	/// <summary>
	/// An IComparer which sorts a collection of models into the same order.
	/// The HookBus keeps a collection of models. In multiplayer, these models may be added or removed in different orders
	/// based on the peer. However, we need these models to execute their hooks in the exact same order across all peers
	/// to maintain determinism.
	/// </summary>
	public class DeterministicModelComparer : IComparer<AbstractModel>
	{
		public static DeterministicModelComparer Instance { get; } = new DeterministicModelComparer();

		private DeterministicModelComparer()
		{
		}

		public int Compare(AbstractModel? model1, AbstractModel? model2)
		{
			if (model1 == null && model2 == null)
			{
				return 0;
			}
			if (model1 == model2)
			{
				return 0;
			}
			if (model1 == null)
			{
				return -1;
			}
			if (model2 == null)
			{
				return 1;
			}
			if (model1.CategorySortingId != model2.CategorySortingId)
			{
				return model1.CategorySortingId.CompareTo(model2.CategorySortingId);
			}
			if (model1.EntrySortingId != model2.EntrySortingId)
			{
				return model1.EntrySortingId.CompareTo(model2.EntrySortingId);
			}
			Creature owner = GetOwner(model1);
			Creature owner2 = GetOwner(model2);
			if (owner == null && owner2 == null)
			{
				return 0;
			}
			if (owner == null)
			{
				return -1;
			}
			if (owner2 == null)
			{
				return 1;
			}
			if (owner != owner2)
			{
				if (owner.IsPlayer && owner2.IsPlayer)
				{
					return owner.Player.NetId.CompareTo(owner2.Player.NetId);
				}
				if (owner.CombatId.HasValue && owner2.CombatId.HasValue)
				{
					return owner.CombatId.Value.CompareTo(owner2.CombatId.Value);
				}
				if (owner.CombatId.HasValue)
				{
					return 1;
				}
				return -1;
			}
			return CompareModelsWithSameOwnerAndId(model1, model2);
		}

		private static Creature? GetOwner(AbstractModel model)
		{
			if (!(model is CardModel cardModel))
			{
				if (!(model is RelicModel relicModel))
				{
					if (!(model is PotionModel potionModel))
					{
						if (!(model is PowerModel powerModel))
						{
							if (!(model is AfflictionModel afflictionModel))
							{
								if (model is EnchantmentModel enchantmentModel)
								{
									return enchantmentModel.Card.Owner.Creature;
								}
								return null;
							}
							return afflictionModel.Card.Owner.Creature;
						}
						return powerModel.Owner;
					}
					return potionModel.Owner.Creature;
				}
				return relicModel.Owner.Creature;
			}
			return cardModel.Owner.Creature;
		}

		private static int CompareModelsWithSameOwnerAndId(AbstractModel model1, AbstractModel model2)
		{
			if (model1 is CardModel cardModel && model2 is CardModel cardModel2)
			{
				return CompareCardModelsWithSameOwnerAndId(cardModel, cardModel2);
			}
			if (model1 is AfflictionModel afflictionModel && model2 is AfflictionModel afflictionModel2)
			{
				return CompareCardModelsWithSameOwnerAndId(afflictionModel.Card, afflictionModel2.Card);
			}
			if (model1 is EnchantmentModel enchantmentModel && model2 is EnchantmentModel enchantmentModel2)
			{
				return CompareCardModelsWithSameOwnerAndId(enchantmentModel.Card, enchantmentModel2.Card);
			}
			if (model1 is RelicModel relicModel && model2 is RelicModel relicModel2)
			{
				return relicModel.Owner.Relics.IndexOf(relicModel).CompareTo(relicModel2.Owner.Relics.IndexOf(relicModel2));
			}
			if (model1 is PotionModel potionModel && model2 is PotionModel potionModel2)
			{
				return potionModel.Owner.PotionSlots.IndexOf<PotionModel>(potionModel).CompareTo(potionModel2.Owner.PotionSlots.IndexOf<PotionModel>(potionModel2));
			}
			if (model1 is PowerModel powerModel && model2 is PowerModel powerModel2)
			{
				return powerModel.Owner.Powers.IndexOf(powerModel).CompareTo(powerModel2.Owner.Powers.IndexOf(powerModel2));
			}
			throw new InvalidOperationException($"Tried to compare equivalent models {model1} and {model2} but we can't map them to any know model types!");
		}

		private static int CompareCardModelsWithSameOwnerAndId(CardModel cardModel1, CardModel cardModel2)
		{
			if (cardModel1.Pile == null && cardModel2.Pile == null)
			{
				return 0;
			}
			if (cardModel1.Pile == null)
			{
				return 1;
			}
			if (cardModel2.Pile == null)
			{
				return -1;
			}
			if (cardModel1.Pile.Type != cardModel2.Pile.Type)
			{
				return cardModel1.Pile.Type.CompareTo(cardModel2.Pile.Type);
			}
			return cardModel1.Pile.Cards.IndexOf(cardModel1).CompareTo(cardModel2.Pile.Cards.IndexOf(cardModel2));
		}
	}
	public enum PlayerChoiceType
	{
		None,
		/// <summary>
		/// For when the player is choosing from a set of canonical cards, like the cards generated by Attack Potion.
		/// </summary>
		CanonicalCard,
		/// <summary>
		/// For when the player is choosing from a set of mutable cards in a combat pile, like the cards in your hand when
		/// you play Survivor.
		/// </summary>
		CombatCard,
		/// <summary>
		/// For when the player is choosing from a set of mutable cards in a player's deck, like when you choose the Smith
		/// option at a rest site.
		/// </summary>
		DeckCard,
		/// <summary>
		/// For when the player is choosing from a set of mutable cards.
		/// Should be used any time we want the player to choose from a set of cards that may be modified from their
		/// canonical version (like if they're upgraded or enchanted).
		/// </summary>
		MutableCard,
		/// <summary>
		/// For when the player is targeting players outside of combat, and the decision point is synced.
		/// </summary>
		Player,
		/// <summary>
		/// For when the player is choosing an option out of a deterministically generated list of options.
		/// </summary>
		Index
	}
}
namespace MegaCrit.Sts2.Core.Entities.Merchant
{
	/// <summary>
	/// Manages a buy-able card in the merchant shop.
	/// </summary>
	public sealed class MerchantCardEntry : MerchantEntry
	{
		private readonly MerchantInventory? _inventory;

		private readonly IEnumerable<CardModel> _cardPool;

		private readonly CardType? _cardType;

		private readonly CardRarity? _cardRarity;

		public CardCreationResult? CreationResult { get; private set; }

		public bool IsOnSale { get; private set; }

		public override bool IsStocked => CreationResult != null;

		private static int GetCost(CardModel card)
		{
			int num = card.Rarity switch
			{
				CardRarity.Rare => 150, 
				CardRarity.Uncommon => 75, 
				_ => 50, 
			};
			if (card.Pool is ColorlessCardPool)
			{
				num = Mathf.RoundToInt((float)num * 1.15f);
			}
			return num;
		}

		public MerchantCardEntry(Player player, MerchantInventory? inventory, IEnumerable<CardModel> cardPool, CardType cardType)
			: base(player)
		{
			_inventory = inventory;
			_cardPool = cardPool;
			_cardType = cardType;
		}

		public MerchantCardEntry(Player player, MerchantInventory? inventory, IEnumerable<CardModel> cardPool, CardRarity cardRarity)
			: base(player)
		{
			_inventory = inventory;
			_cardPool = cardPool;
			_cardRarity = cardRarity;
		}

		public void Populate()
		{
			HashSet<CardModel> second = _inventory?.CardEntries.Select((MerchantCardEntry e) => e.CreationResult?.Card.CanonicalInstance).OfType<CardModel>().ToHashSet() ?? new HashSet<CardModel>();
			if (_cardType.HasValue)
			{
				CreationResult = CardFactory.CreateForMerchant(_player, _cardPool.Except(second), _cardType.Value);
			}
			else
			{
				if (!_cardRarity.HasValue)
				{
					throw new InvalidOperationException();
				}
				CreationResult = CardFactory.CreateForMerchant(_player, _cardPool.Except(second), _cardRarity.Value);
			}
			IRunState runState = _player.RunState;
			Player player = _player;
			int num = 1;
			List<CardCreationResult> list = new List<CardCreationResult>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<CardCreationResult> span = CollectionsMarshal.AsSpan(list);
			int index = 0;
			span[index] = CreationResult;
			Hook.ModifyMerchantCardCreationResults(runState, player, list);
			CalcCost();
		}

		protected override void UpdateEntry()
		{
			if (CreationResult != null)
			{
				IRunState runState = _player.RunState;
				Player player = _player;
				int num = 1;
				List<CardCreationResult> list = new List<CardCreationResult>(num);
				CollectionsMarshal.SetCount(list, num);
				Span<CardCreationResult> span = CollectionsMarshal.AsSpan(list);
				int index = 0;
				span[index] = CreationResult;
				Hook.ModifyMerchantCardCreationResults(runState, player, list);
			}
		}

		public void SetOnSale()
		{
			IsOnSale = true;
			CalcCost();
		}

		public override void CalcCost()
		{
			if (CreationResult == null)
			{
				throw new InvalidOperationException("There is no item to purchase.");
			}
			_cost = Mathf.RoundToInt((float)GetCost(CreationResult.Card) * _player.PlayerRng.Shops.NextFloat(0.95f, 1.05f));
			if (IsOnSale)
			{
				_cost /= 2;
			}
		}

		protected override async Task<(bool, int)> OnTryPurchase(MerchantInventory? inventory, bool ignoreCost)
		{
			if (!(await CardPileCmd.Add(CreationResult.Card, PileType.Deck)).success)
			{
				InvokePurchaseFailed(PurchaseStatus.FailureSpace);
				return (false, 0);
			}
			if (!ignoreCost)
			{
				await PlayerCmd.LoseGold(base.Cost, _player, GoldLossType.Spent);
			}
			RunManager.Instance.RewardSynchronizer.SyncLocalGoldLost(base.Cost);
			RunManager.Instance.RewardSynchronizer.SyncLocalObtainedCard(CreationResult.Card);
			if (CreationResult.Card.Pool is ColorlessCardPool)
			{
				_player.RunState.CurrentMapPointHistoryEntry?.GetEntry(_player.NetId).BoughtColorless.Add(CreationResult.Card.Id);
			}
			return (true, (!ignoreCost) ? base.Cost : 0);
		}

		protected override void ClearAfterPurchase()
		{
			CreationResult = null;
		}

		protected override void RestockAfterPurchase(MerchantInventory? inventory)
		{
			IsOnSale = false;
			Populate();
		}
	}
	/// <summary>
	/// Manages the card removal option of a merchant shop
	/// </summary>
	public sealed class MerchantCardRemovalEntry : MerchantEntry
	{
		public bool Used { get; private set; }

		public override bool IsStocked => !Used;

		private static int BaseCost => AscensionHelper.GetValueIfAscension(AscensionLevel.Inflation, 100, 75);

		public static int PriceIncrease => AscensionHelper.GetValueIfAscension(AscensionLevel.Inflation, 50, 25);

		public MerchantCardRemovalEntry(Player player)
			: base(player)
		{
			CalcCost();
		}

		public override void CalcCost()
		{
			_cost = BaseCost + PriceIncrease * _player.ExtraFields.CardShopRemovalsUsed;
		}

		public async Task<bool> OnTryPurchaseWrapper(MerchantInventory? inventory, bool ignoreCost = false, bool cancelable = true)
		{
			if (!RunManager.Instance.IsInProgress)
			{
				return false;
			}
			if (!base.EnoughGold && !ignoreCost)
			{
				InvokePurchaseFailed(PurchaseStatus.FailureGold);
				return false;
			}
			var (success, goldSpent) = await OnTryPurchase(inventory, ignoreCost, cancelable);
			if (success)
			{
				await Hook.AfterItemPurchased(_player.RunState, _player, this, goldSpent);
				InvokePurchaseCompleted(this);
			}
			return success;
		}

		protected override async Task<(bool, int)> OnTryPurchase(MerchantInventory? inventory, bool ignoreCost)
		{
			return await OnTryPurchase(inventory, ignoreCost, cancelable: true);
		}

		private async Task<(bool, int)> OnTryPurchase(MerchantInventory? inventory, bool ignoreCost, bool cancelable)
		{
			if (Used)
			{
				return (false, 0);
			}
			int goldToSpend = ((!ignoreCost) ? base.Cost : 0);
			bool flag = await RunManager.Instance.OneOffSynchronizer.DoLocalMerchantCardRemoval(goldToSpend, cancelable);
			if (flag)
			{
				NRun.Instance?.MerchantRoom?.Inventory.OnCardRemovalUsed();
			}
			return (flag, goldToSpend);
		}

		protected override void ClearAfterPurchase()
		{
		}

		protected override void RestockAfterPurchase(MerchantInventory? inventory)
		{
		}

		public void SetUsed()
		{
			Used = true;
		}
	}
	public class MerchantDialogueSet
	{
		private readonly List<LocString> _welcomeLines = new List<LocString>();

		private readonly List<LocString> _openInventoryLines = new List<LocString>();

		private readonly List<LocString> _foulPotionLines = new List<LocString>();

		private readonly List<LocString> _playerDeadLines = new List<LocString>();

		private readonly List<LocString> _purchaseSuccessLines = new List<LocString>();

		private readonly List<LocString> _purchaseFailureGoldLines = new List<LocString>();

		private readonly List<LocString> _purchaseFailureSpaceLines = new List<LocString>();

		private readonly List<LocString> _purchaseFailureForbiddenLines = new List<LocString>();

		/// <summary>
		/// Lines for when the player enters the merchant room.
		/// </summary>
		public IReadOnlyList<LocString> WelcomeLines => _welcomeLines;

		/// <summary>
		/// Lines for when the player throws a <see cref="T:MegaCrit.Sts2.Core.Models.Potions.FoulPotion" /> at the merchant.
		/// </summary>
		public IReadOnlyList<LocString> FoulPotionLines => _foulPotionLines;

		/// <summary>
		/// Lines for when the player is dead.
		/// Rare, but can happen in multiplayer if one player is dead and the others go to the merchant.
		/// </summary>
		public IReadOnlyList<LocString> PlayerDeadLines => _playerDeadLines;

		/// <summary>
		/// Lines for when the player opens the merchant's inventory.
		/// </summary>
		public IReadOnlyList<LocString> OpenInventoryLines => _openInventoryLines;

		public static MerchantDialogueSet CreateFromLocStrings(IEnumerable<LocString> locStrings)
		{
			MerchantDialogueSet merchantDialogueSet = new MerchantDialogueSet();
			foreach (LocString locString in locStrings)
			{
				string text = locString.LocEntryKey.Split('.')[^2];
				(text switch
				{
					"welcome" => merchantDialogueSet._welcomeLines, 
					"openInventory" => merchantDialogueSet._openInventoryLines, 
					"foulPotion" => merchantDialogueSet._foulPotionLines, 
					"playerDead" => merchantDialogueSet._playerDeadLines, 
					"purchaseSuccess" => merchantDialogueSet._purchaseSuccessLines, 
					"purchaseFailureGold" => merchantDialogueSet._purchaseFailureGoldLines, 
					"purchaseFailureSpace" => merchantDialogueSet._purchaseFailureSpaceLines, 
					"purchaseFailureForbidden" => merchantDialogueSet._purchaseFailureForbiddenLines, 
					_ => throw new InvalidOperationException("Unexpected merchant dialogue key: " + text), 
				}).Add(locString);
			}
			return merchantDialogueSet;
		}

		/// <summary>
		/// Get all the valid lines for a given purchase status.
		/// </summary>
		public IReadOnlyList<LocString> GetPurchaseSuccessLines(PurchaseStatus status)
		{
			return status switch
			{
				PurchaseStatus.Success => _purchaseSuccessLines, 
				PurchaseStatus.FailureGold => _purchaseFailureGoldLines, 
				PurchaseStatus.FailureSpace => _purchaseFailureSpaceLines, 
				PurchaseStatus.FailureForbidden => _purchaseFailureForbiddenLines, 
				_ => throw new ArgumentOutOfRangeException("status", status, null), 
			};
		}
	}
	/// <summary>
	/// Represents purchasable entry in the merchant shop.
	/// Wrapped in an NMerchant_Node that manages the UI interactions.
	/// </summary>
	public abstract class MerchantEntry
	{
		protected readonly Player _player;

		protected int _cost;

		public int Cost
		{
			get
			{
				decimal num = _cost;
				if (_player.RunState.CurrentRoom is MerchantRoom)
				{
					num = Hook.ModifyMerchantPrice(_player.RunState, _player, this, _cost);
				}
				return (int)num;
			}
		}

		public bool EnoughGold => Cost <= _player.Gold;

		public abstract bool IsStocked { get; }

		public event Action<PurchaseStatus, MerchantEntry>? PurchaseCompleted;

		public event Action<PurchaseStatus>? PurchaseFailed;

		public event Action? EntryUpdated;

		public void InvokePurchaseCompleted(MerchantEntry entry)
		{
			PurchaseCompleted?.Invoke(PurchaseStatus.Success, entry);
		}

		public void InvokePurchaseFailed(PurchaseStatus status)
		{
			PurchaseFailed?.Invoke(status);
		}

		protected MerchantEntry(Player player)
		{
			_player = player;
		}

		protected virtual void UpdateEntry()
		{
		}

		public void OnMerchantInventoryUpdated()
		{
			UpdateEntry();
			EntryUpdated?.Invoke();
		}

		public abstract void CalcCost();

		public async Task<bool> OnTryPurchaseWrapper(MerchantInventory? inventory, bool ignoreCost = false)
		{
			if (!IsStocked)
			{
				InvokePurchaseFailed(PurchaseStatus.FailureOutOfStock);
				return false;
			}
			if (!EnoughGold && !ignoreCost)
			{
				InvokePurchaseFailed(PurchaseStatus.FailureGold);
				return false;
			}
			var (success, goldSpent) = await OnTryPurchase(inventory, ignoreCost);
			if (success)
			{
				if (_player.RunState.CurrentRoom is MerchantRoom && Hook.ShouldRefillMerchantEntry(_player.RunState, this, _player))
				{
					RestockAfterPurchase(inventory);
				}
				else
				{
					ClearAfterPurchase();
				}
				await Hook.AfterItemPurchased(_player.RunState, _player, this, goldSpent);
				InvokePurchaseCompleted(this);
			}
			return success;
		}

		/// <summary>
		/// Subclass-specific logic for purchasing the item in the entry.
		/// </summary>
		/// <param name="inventory">Inventory that the entry is being purchased in.</param>
		/// <param name="ignoreCost">Whether or not the cost should be ignored</param>
		/// <returns>Tuple containing whether or not the purchase was successful and the amount of gold spent.</returns>
		protected abstract Task<(bool, int)> OnTryPurchase(MerchantInventory? inventory, bool ignoreCost);

		/// <summary>
		/// Subclass-specific logic for clearing the entry after a purchase.
		/// </summary>
		protected abstract void ClearAfterPurchase();

		/// <summary>
		/// Subclass-specific logic for restocking the entry after a purchase if the player has an effect like
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Relics.TheCourier" />.
		/// </summary>
		protected abstract void RestockAfterPurchase(MerchantInventory? inventory);
	}
	public class MerchantInventory
	{
		private static readonly CardType[] _coloredCardTypes = new CardType[5]
		{
			CardType.Attack,
			CardType.Attack,
			CardType.Skill,
			CardType.Skill,
			CardType.Power
		};

		private static readonly CardRarity[] _colorlessCardRarities = new CardRarity[2]
		{
			CardRarity.Uncommon,
			CardRarity.Rare
		};

		private readonly List<MerchantCardEntry> _characterCardEntries = new List<MerchantCardEntry>();

		private readonly List<MerchantCardEntry> _colorlessCardEntries = new List<MerchantCardEntry>();

		private readonly List<MerchantRelicEntry> _relicEntries = new List<MerchantRelicEntry>();

		private readonly List<MerchantPotionEntry> _potionEntries = new List<MerchantPotionEntry>();

		public IReadOnlyList<MerchantCardEntry> CharacterCardEntries => _characterCardEntries;

		public IReadOnlyList<MerchantCardEntry> ColorlessCardEntries => _colorlessCardEntries;

		public IReadOnlyList<MerchantRelicEntry> RelicEntries => _relicEntries;

		public IReadOnlyList<MerchantPotionEntry> PotionEntries => _potionEntries;

		public MerchantCardRemovalEntry? CardRemovalEntry { get; private set; }

		public Player Player { get; }

		public IEnumerable<MerchantEntry> AllEntries
		{
			get
			{
				IEnumerable<MerchantEntry>[] obj = new IEnumerable<MerchantEntry>[4] { CardEntries, RelicEntries, PotionEntries, null };
				IEnumerable<MerchantEntry> enumerable2;
				if (CardRemovalEntry == null)
				{
					IEnumerable<MerchantEntry> enumerable = System.Array.Empty<MerchantEntry>();
					enumerable2 = enumerable;
				}
				else
				{
					IEnumerable<MerchantEntry> enumerable = new global::<>z__ReadOnlySingleElementList<MerchantEntry>(CardRemovalEntry);
					enumerable2 = enumerable;
				}
				obj[3] = enumerable2;
				return obj.SelectMany((IEnumerable<MerchantEntry> e) => e);
			}
		}

		public IEnumerable<MerchantCardEntry> CardEntries => CharacterCardEntries.Concat(ColorlessCardEntries);

		public MerchantInventory(Player player)
		{
			Player = player;
		}

		public static MerchantInventory CreateForNormalMerchant(Player player)
		{
			MerchantInventory merchantInventory = new MerchantInventory(player);
			merchantInventory.PopulateCharacterCardEntries();
			merchantInventory.PopulateColorlessCardEntries();
			merchantInventory.PopulateRelicEntries();
			merchantInventory.PopulatePotionEntries();
			merchantInventory.CardRemovalEntry = new MerchantCardRemovalEntry(player);
			foreach (MerchantEntry allEntry in merchantInventory.AllEntries)
			{
				allEntry.PurchaseCompleted += merchantInventory.UpdateEntries;
			}
			return merchantInventory;
		}

		public void AddRelicEntry(MerchantRelicEntry entry)
		{
			_relicEntries.Add(entry);
		}

		private void PopulateCharacterCardEntries()
		{
			int num = Player.PlayerRng.Shops.NextInt(_coloredCardTypes.Length);
			List<CardModel> cardPool = Player.Character.CardPool.GetUnlockedCards(Player.UnlockState, Player.RunState.CardMultiplayerConstraint).ToList();
			for (int i = 0; i < _coloredCardTypes.Length; i++)
			{
				MerchantCardEntry merchantCardEntry = new MerchantCardEntry(Player, this, cardPool, _coloredCardTypes[i]);
				merchantCardEntry.Populate();
				_characterCardEntries.Add(merchantCardEntry);
				if (num == i)
				{
					merchantCardEntry.SetOnSale();
				}
			}
		}

		private void PopulateColorlessCardEntries()
		{
			List<CardModel> cardPool = ModelDb.CardPool<ColorlessCardPool>().GetUnlockedCards(Player.UnlockState, Player.RunState.CardMultiplayerConstraint).ToList();
			CardRarity[] colorlessCardRarities = _colorlessCardRarities;
			foreach (CardRarity cardRarity in colorlessCardRarities)
			{
				MerchantCardEntry merchantCardEntry = new MerchantCardEntry(Player, this, cardPool, cardRarity);
				merchantCardEntry.Populate();
				_colorlessCardEntries.Add(merchantCardEntry);
			}
		}

		private void PopulateRelicEntries()
		{
			RelicRarity[] array = new RelicRarity[3]
			{
				RelicFactory.RollRarity(Player),
				RelicFactory.RollRarity(Player),
				RelicRarity.Shop
			};
			RelicRarity[] array2 = array;
			foreach (RelicRarity rarity in array2)
			{
				AddRelicEntry(new MerchantRelicEntry(rarity, Player));
			}
		}

		private void PopulatePotionEntries()
		{
			List<PotionModel> list = PotionFactory.CreateRandomPotionsOutOfCombat(Player, 3, Player.PlayerRng.Shops).ToList();
			foreach (PotionModel item in list)
			{
				_potionEntries.Add(new MerchantPotionEntry(item.ToMutable(), Player));
			}
		}

		private void UpdateEntries(PurchaseStatus _, MerchantEntry __)
		{
			foreach (MerchantEntry allEntry in AllEntries)
			{
				allEntry.OnMerchantInventoryUpdated();
			}
		}
	}
	/// <summary>
	/// Manages a purchasable potion in the merchant shop.
	///
	/// </summary>
	public sealed class MerchantPotionEntry : MerchantEntry
	{
		public PotionModel? Model { get; private set; }

		public override bool IsStocked => Model != null;

		public MerchantPotionEntry(PotionModel potion, Player player)
			: base(player)
		{
			potion.AssertMutable();
			Model = potion;
			CalcCost();
			SaveManager.Instance.MarkPotionAsSeen(Model);
		}

		public MerchantPotionEntry(Player player)
			: base(player)
		{
			FillSlot(System.Array.Empty<PotionModel>());
		}

		private void FillSlot(IEnumerable<PotionModel> blacklist)
		{
			Model = PotionFactory.CreateRandomPotionOutOfCombat(_player, _player.PlayerRng.Shops, blacklist).ToMutable();
			CalcCost();
			SaveManager.Instance.MarkPotionAsSeen(Model);
		}

		private static int GetCost(PotionRarity rarity)
		{
			return rarity switch
			{
				PotionRarity.Rare => 100, 
				PotionRarity.Uncommon => 75, 
				_ => 50, 
			};
		}

		public override void CalcCost()
		{
			if (Model == null)
			{
				throw new InvalidOperationException("There is no item to purchase.");
			}
			_cost = GetCost(Model.Rarity);
			if (TestMode.IsOff)
			{
				_cost = (int)Mathf.Round((float)_cost * _player.PlayerRng.Shops.NextFloat(0.95f, 1.05f));
			}
		}

		protected override async Task<(bool, int)> OnTryPurchase(MerchantInventory? inventory, bool ignoreCost)
		{
			if (Model == null)
			{
				throw new InvalidOperationException("There is no item to purchase.");
			}
			PotionProcureResult potionProcureResult = await PotionCmd.TryToProcure(Model, _player);
			if (!potionProcureResult.success)
			{
				InvokePurchaseFailed((potionProcureResult.failureReason == PotionProcureFailureReason.NotAllowed) ? PurchaseStatus.FailureForbidden : PurchaseStatus.FailureSpace);
				return (false, 0);
			}
			if (!ignoreCost)
			{
				await PlayerCmd.LoseGold(base.Cost, _player, GoldLossType.Spent);
			}
			_player.RunState.CurrentMapPointHistoryEntry?.GetEntry(_player.NetId).BoughtPotions.Add(Model.Id);
			RunManager.Instance.RewardSynchronizer.SyncLocalGoldLost(base.Cost);
			RunManager.Instance.RewardSynchronizer.SyncLocalObtainedPotion(Model);
			return (true, (!ignoreCost) ? base.Cost : 0);
		}

		protected override void ClearAfterPurchase()
		{
			Model = null;
		}

		protected override void RestockAfterPurchase(MerchantInventory? inventory)
		{
			HashSet<PotionModel> hashSet = inventory?.PotionEntries.Select((MerchantPotionEntry e) => e.Model?.CanonicalInstance).OfType<PotionModel>().ToHashSet() ?? new HashSet<PotionModel>();
			FillSlot(System.Array.Empty<PotionModel>());
		}
	}
	/// <summary>
	/// Manages a purchasable relic in the merchant shop
	/// </summary>
	public sealed class MerchantRelicEntry : MerchantEntry
	{
		public RelicModel? Model { get; private set; }

		public override bool IsStocked => Model != null;

		public MerchantRelicEntry(RelicRarity rarity, Player player)
			: base(player)
		{
			FillSlot(rarity);
		}

		public MerchantRelicEntry(RelicModel relic, Player player)
			: base(player)
		{
			SetModel(relic);
		}

		private void FillSlot(RelicRarity rarity, IEnumerable<RelicModel>? blacklist = null)
		{
			SetModel(RelicFactory.PullNextRelicFromBack(_player, rarity, (RelicModel r) => (blacklist == null || !blacklist.Contains(r)) && r.IsAllowedInShops).ToMutable());
		}

		public override void CalcCost()
		{
			_cost = (int)Math.Round((float)Model.MerchantCost * _player.PlayerRng.Shops.NextFloat(0.85f, 1.15f));
		}

		private void SetModel(RelicModel model)
		{
			model.AssertMutable();
			Model = model;
			CalcCost();
			SaveManager.Instance.MarkRelicAsSeen(Model);
		}

		protected override async Task<(bool, int)> OnTryPurchase(MerchantInventory? inventory, bool ignoreCost)
		{
			if (!ignoreCost)
			{
				await PlayerCmd.LoseGold(base.Cost, _player, GoldLossType.Spent);
			}
			_player.RunState.CurrentMapPointHistoryEntry?.GetEntry(_player.NetId).BoughtRelics.Add(Model.Id);
			await RelicCmd.Obtain(Model, _player);
			RunManager.Instance.RewardSynchronizer.SyncLocalGoldLost(base.Cost);
			RunManager.Instance.RewardSynchronizer.SyncLocalObtainedRelic(Model);
			return (true, (!ignoreCost) ? base.Cost : 0);
		}

		protected override void ClearAfterPurchase()
		{
			Model = null;
		}

		protected override void RestockAfterPurchase(MerchantInventory? inventory)
		{
			HashSet<RelicModel> blacklist = inventory?.RelicEntries.Select((MerchantRelicEntry e) => e.Model?.CanonicalInstance).OfType<RelicModel>().ToHashSet() ?? new HashSet<RelicModel>();
			FillSlot(RelicFactory.RollRarity(_player), blacklist);
		}
	}
	public enum PurchaseStatus
	{
		/// <summary>
		/// The purchase was successful.
		/// </summary>
		Success,
		/// <summary>
		/// The purchase failed due to lack of gold.
		/// </summary>
		FailureGold,
		/// <summary>
		/// The purchase failed due to lack of space in the player's inventory.
		/// </summary>
		FailureSpace,
		/// <summary>
		/// The purchase failed because some external effect prevented it (like <see cref="T:MegaCrit.Sts2.Core.Models.Relics.Sozu" /> for a potion purchase).
		/// </summary>
		FailureForbidden,
		/// <summary>
		/// The purchase failed because the Merchant does not have this slot stocked.
		/// </summary>
		FailureOutOfStock
	}
}
