		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Cards.LocalCostModifier.IsReduceOnly" /> for details.
		/// </param>
		public void AddUntilPlayed(int amount, bool reduceOnly = false)
		{
			if (amount != 0)
			{
				_localModifiers.Add(new LocalCostModifier(amount, LocalCostType.Relative, LocalCostModifierExpiration.WhenPlayed, reduceOnly));
			}
		}

		/// <summary>
		/// Add the specified amount to this cost until the end of the current turn OR until the card is played, whichever
		/// comes first.
		/// Note that the text of these effects will just say "this turn"; the "or until played" part is left implicit
		/// because it's wordy and rarely relevant.
		/// </summary>
		/// <example>None yet. Update this if we add one!</example>
		/// <param name="amount">Amount to add to the cost.</param>
		/// <param name="reduceOnly">
		/// Whether this modifier should only be included in the cost calculation if it would lower the current cost.
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Cards.LocalCostModifier.IsReduceOnly" /> for details.
		/// </param>
		public void AddThisTurnOrUntilPlayed(int amount, bool reduceOnly = false)
		{
			if (amount != 0)
			{
				_localModifiers.Add(new LocalCostModifier(amount, LocalCostType.Relative, LocalCostModifierExpiration.EndOfTurn | LocalCostModifierExpiration.WhenPlayed, reduceOnly));
			}
		}

		/// <summary>
		/// BE CAREFUL USING THIS! You usually want <see cref="M:MegaCrit.Sts2.Core.Entities.Cards.CardEnergyCost.AddThisTurnOrUntilPlayed(System.Int32,System.Boolean)" /> instead.
		/// Add the specified amount to this cost until the end of the current turn.
		/// Note that most effects that say "this turn" really mean "this turn or until played".
		/// This method should only be used for the few effects that should last for multiple plays in the same turn.
		/// </summary>
		/// <example>
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Pinpoint" /> says "Costs 1 less for each Skill played this turn."
		/// </example>
		/// <param name="amount">Amount to add to the cost.</param>
		/// <param name="reduceOnly">
		/// Whether this modifier should only be included in the cost calculation if it would lower the current cost.
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Cards.LocalCostModifier.IsReduceOnly" /> for details.
		/// </param>
		public void AddThisTurn(int amount, bool reduceOnly = false)
		{
			if (amount != 0)
			{
				_localModifiers.Add(new LocalCostModifier(amount, LocalCostType.Relative, LocalCostModifierExpiration.EndOfTurn, reduceOnly));
			}
		}

		/// <summary>
		/// Add the specified amount to this cost for the rest of the combat.
		/// </summary>
		/// <example>
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Cards.KinglyKick" /> says "Whenever you draw this card, lower its cost by 1 this combat."
		/// </example>
		/// <param name="amount">Amount to add to the cost.</param>
		/// <param name="reduceOnly">
		/// Whether this modifier should only be included in the cost calculation if it would lower the current cost.
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Cards.LocalCostModifier.IsReduceOnly" /> for details.
		/// </param>
		public void AddThisCombat(int amount, bool reduceOnly = false)
		{
			if (amount != 0)
			{
				_localModifiers.Add(new LocalCostModifier(amount, LocalCostType.Relative, LocalCostModifierExpiration.EndOfCombat, reduceOnly));
			}
		}

		/// <summary>
		/// Clear local cost modifiers that should last until the end of the turn.
		/// </summary>
		/// <returns>True if any modifiers were cleared and EnergyCostChanged should be invoked.</returns>
		public bool EndOfTurnCleanup()
		{
			_card.AssertMutable();
			return _localModifiers.RemoveAll((LocalCostModifier m) => m.Expiration.HasFlag(LocalCostModifierExpiration.EndOfTurn)) > 0;
		}

		/// <summary>
		/// Clear local cost modifiers that should last until the card is played.
		/// </summary>
		/// <returns>True if any modifiers were cleared and EnergyCostChanged should be invoked.</returns>
		public bool AfterCardPlayedCleanup()
		{
			_card.AssertMutable();
			return _localModifiers.RemoveAll((LocalCostModifier m) => m.Expiration.HasFlag(LocalCostModifierExpiration.WhenPlayed)) > 0;
		}

		/// <summary>
		/// Upgrade the energy cost of this card by the specified amount.
		/// </summary>
		/// <param name="addend">Amount to add to the current cost (usually negative).</param>
		public void UpgradeBy(int addend)
		{
			_card.AssertMutable();
			if (CostsX || addend == 0)
			{
				return;
			}
			int num = _base;
			int num2 = Math.Max(_base + addend, 0);
			WasJustUpgraded = true;
			if (num2 < num)
			{
				foreach (LocalCostModifier localModifier in _localModifiers)
				{
					if (localModifier.Type == LocalCostType.Absolute && localModifier.Amount > num2)
					{
						localModifier.Amount = num2;
					}
				}
			}
			SetCustomBaseCost(num2);
		}

		/// <summary>
		/// Finalize an upgrade after calling UpgradeEnergyCostBy. This clears out state that is used for displaying an upgrade
		/// preview.
		/// </summary>
		public void FinalizeUpgrade()
		{
			_card.AssertMutable();
			WasJustUpgraded = false;
		}

		/// <summary>
		/// Reset energy cost to base values during downgrade.
		/// </summary>
		public void ResetForDowngrade()
		{
			_card.AssertMutable();
			_base = Canonical;
			_card.InvokeEnergyCostChanged();
		}

		/// <summary>
		/// BE VERY CAREFUL USING THIS!
		/// This is mainly meant for internal usage. The only external usage of this should be in <see cref="T:MegaCrit.Sts2.Core.Models.Cards.MadScience" />.
		/// </summary>
		/// <param name="newBaseCost"></param>
		public void SetCustomBaseCost(int newBaseCost)
		{
			_card.AssertMutable();
			_base = newBaseCost;
			_card.InvokeEnergyCostChanged();
		}

		/// <summary>
		/// Create a deep clone of this EnergyCostInfo for the specified card.
		/// </summary>
		/// <param name="newCard">The card that will own the cloned EnergyCostInfo.</param>
		/// <returns>A deep clone of this EnergyCostInfo.</returns>
		public CardEnergyCost Clone(CardModel newCard)
		{
			List<LocalCostModifier> localModifiers = _localModifiers.Select((LocalCostModifier m) => m.Clone()).ToList();
			return new CardEnergyCost(newCard, newCard.EnergyCost.Canonical, newCard.EnergyCost.CostsX)
			{
				_base = _base,
				_capturedXValue = _capturedXValue,
				WasJustUpgraded = WasJustUpgraded,
				_localModifiers = localModifiers
			};
		}
	}
	/// <summary>
	/// Card Keywords are extra "automatic behaviors" you can add to a card, which also automatically add some extra
	/// text to the card's description.
	///
	/// Examples of things that SHOULD be CardKeywords:
	/// * Exhaust: automatically exhausts when played, puts "Exhaust" in the card description.
	/// * Unplayable: blocks the card from being played, puts "Unplayable" in the card description.
	///
	/// Examples of things that should NOT be CardKeywords:
	/// * Strike: this has no logic or extra text, just tells Perfected Strike (and some other models) that it's a
	///     Strike card.
	/// * Block: while this is used on cards that have "Block" in their descriptions, it doesn't automatically add
	///     it, nor does it automatically grant block; it's just for HoverTips and effects that care about which cards
	///     give block (like the Nimble enchantment, which should only apply to cards that give block).
	/// </summary>
	public enum CardKeyword
	{
		None,
		Exhaust,
		Ethereal,
		Innate,
		Unplayable,
		Retain,
		Sly,
		Eternal
	}
	internal static class CardKeywordExtensions
	{
		private static readonly LocString _period = new LocString("card_keywords", "PERIOD");

		public static string GetLocKeyPrefix(this CardKeyword keyword)
		{
			return StringHelper.Slugify(keyword.ToString());
		}

		public static LocString GetTitle(this CardKeyword keyword)
		{
			return new LocString("card_keywords", keyword.GetLocKeyPrefix() + ".title");
		}

		public static LocString GetDescription(this CardKeyword keyword)
		{
			return new LocString("card_keywords", keyword.GetLocKeyPrefix() + ".description");
		}

		public static string GetCardText(this CardKeyword keyword)
		{
			return "[gold]" + keyword.GetTitle().GetFormattedText() + "[/gold]" + _period.GetRawText();
		}
	}
	public static class CardKeywordOrder
	{
		/// <summary>
		/// All the keywords that should be added before the card's description.
		/// Order matters here. If a card has multiple keywords, they will appear in this order.
		/// </summary>
		public static readonly CardKeyword[] beforeDescription = new CardKeyword[5]
		{
			CardKeyword.Ethereal,
			CardKeyword.Sly,
			CardKeyword.Retain,
			CardKeyword.Innate,
			CardKeyword.Unplayable
		};

		/// <summary>
		/// All the keywords that should be added after the card's description.
		/// Order matters here. If a card has multiple keywords, they will appear in this order.
		/// </summary>
		public static readonly CardKeyword[] afterDescription = new CardKeyword[2]
		{
			CardKeyword.Exhaust,
			CardKeyword.Eternal
		};
	}
	public record struct CardLocation(Player player, PileType pileType, CardPilePosition position)
	{
		public Player player = player;

		public PileType pileType = pileType;

		public CardPilePosition position = position;
	}
	/// <summary>
	/// Manages card restrictions based on how many players there are in a run.
	/// </summary>
	public enum CardMultiplayerConstraint
	{
		None,
		MultiplayerOnly,
		SingleplayerOnly
	}
	public class CardPile(PileType type)
	{
		private readonly List<CardModel> _cards = new List<CardModel>();

		/// <summary>
		/// This is functionally a constant but is a property for modding ergonomics.
		/// </summary>
		public static int MaxCardsInHand => 10;

		public PileType Type { get; } = type;

		public IReadOnlyList<CardModel> Cards => _cards;

		public bool IsEmpty => !Cards.Any();

		public bool IsCombatPile => Type.IsCombatPile();

		public int UpgradableCardCount => _cards.Count((CardModel card) => card.IsUpgradable);

		public event Action? ContentsChanged;

		public event Action<CardModel>? CardAdded;

		public event Action<CardModel>? CardRemoved;

		public event Action? CardAddFinished;

		public event Action? CardRemoveFinished;

		public static CardPile? Get(PileType type, Player player)
		{
			return type switch
			{
				PileType.None => null, 
				PileType.Draw => player.PlayerCombatState?.DrawPile, 
				PileType.Hand => player.PlayerCombatState?.Hand, 
				PileType.Discard => player.PlayerCombatState?.DiscardPile, 
				PileType.Exhaust => player.PlayerCombatState?.ExhaustPile, 
				PileType.Play => player.PlayerCombatState?.PlayPile, 
				PileType.Deck => player.Deck, 
				_ => throw new ArgumentOutOfRangeException("type", type, null), 
			};
		}

		public static IEnumerable<CardModel> GetCards(Player player, params PileType[] piles)
		{
			return piles.SelectMany((PileType p) => p.GetPile(player).Cards);
		}

		/// <summary>
		/// Randomize the order of the cards in this pile.
		/// Do NOT call this when your intention is to do a standard shuffle action.
		/// Use <see cref="M:MegaCrit.Sts2.Core.Commands.CardPileCmd.Shuffle(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Players.Player)" /> instead.
		/// This is primarily meant for randomizing the order of the draw pile when a combat first starts.
		/// </summary>
		public void RandomizeOrderInternal(Player player, Rng rng, CombatState state)
		{
			_cards.UnstableShuffle(rng);
			TestRngInjector.ConsumeInitialShuffleOverride()?.Invoke(_cards);
			Hook.ModifyShuffleOrder(state, player, _cards, isInitialShuffle: true);
		}

		/// <summary>
		/// Add a card to the bottom of this pile.
		/// </summary>
		/// <param name="card">Card to add.</param>
		/// <param name="index">Index to insert the card into. -1 will cause it to be added to the end ("bottom").</param>
		/// <param name="silent">If true, no events will be called.</param>
		/// <exception cref="T:System.InvalidOperationException">Thrown if this specific CardModel instance is already in the pile.</exception>
		public void AddInternal(CardModel card, int index = -1, bool silent = false)
		{
			card.AssertMutable();
			if (Cards.Contains(card))
			{
				throw new InvalidOperationException($"Card pile already contains {card}.");
			}
			if (index >= 0)
			{
				_cards.Insert(index, card);
			}
			else
			{
				_cards.Add(card);
			}
			if (IsCombatPile && CombatManager.Instance.IsInProgress)
			{
				CombatManager.Instance.StateTracker.Subscribe(card);
			}
			if (!silent)
			{
				CardAdded?.Invoke(card);
				InvokeContentsChanged();
			}
		}

		/// <summary>
		/// Remove a card from this pile.
		/// </summary>
		/// <param name="card">Card to remove.</param>
		/// <param name="silent">If set to true, no events will be sent to update the UI.</param>
		/// <exception cref="T:System.InvalidOperationException">Thrown if this specific CardModel instance is not in the pile.</exception>
		public void RemoveInternal(CardModel card, bool silent = false)
		{
			if (!Cards.Contains(card))
			{
				throw new InvalidOperationException($"Card pile does not contain {card}.");
			}
			_cards.Remove(card);
			if (IsCombatPile)
			{
				CombatManager.Instance.StateTracker.Unsubscribe(card);
			}
			if (!silent)
			{
				InvokeCardRemoved(card);
				InvokeContentsChanged();
				InvokeCardRemoveFinished();
			}
		}

		/// <summary>
		/// Move a card to the bottom of this pile.
		/// The card must already be in this pile.
		/// This does not send any events to update the UI, so you should only use this in combination with other methods
		/// that do.
		/// </summary>
		/// <param name="card">Card that we're moving to the bottom.</param>
		/// <exception cref="T:System.InvalidOperationException"></exception>
		public void MoveToBottomInternal(CardModel card)
		{
			if (!Cards.Contains(card))
			{
				throw new InvalidOperationException($"Card pile does not contain {card}.");
			}
			_cards.Remove(card);
			_cards.Add(card);
		}

		/// <summary>
		/// Move a card to the top of this pile.
		/// The card must already be in this pile.
		/// This does not send any events to update the UI, so you should only use this in combination with other methods
		/// that do.
		/// </summary>
		/// <param name="card">Card that we're moving to the top.</param>
		/// <exception cref="T:System.InvalidOperationException"></exception>
		public void MoveToTopInternal(CardModel card)
		{
			if (!Cards.Contains(card))
			{
				throw new InvalidOperationException($"Card pile does not contain {card}.");
			}
			_cards.Remove(card);
			_cards.Insert(0, card);
		}

		public void Clear(bool silent = false)
		{
			foreach (CardModel item in Cards.ToList())
			{
				RemoveInternal(item, silent);
			}
			_cards.Clear();
		}

		public void InvokeCardRemoved(CardModel card)
		{
			CardRemoved?.Invoke(card);
		}

		public void InvokeCardAddFinished()
		{
			CardAddFinished?.Invoke();
		}

		public void InvokeCardRemoveFinished()
		{
			CardRemoveFinished?.Invoke();
		}

		public void InvokeContentsChanged()
		{
			ContentsChanged?.Invoke();
		}
	}
