	/// <summary>
	/// Used for determining which Card Pile. Useful when flying cards around, knowing if a card is in your Hand or
	/// in the Discard Pile and things like that.
	/// </summary>
	public enum PileType
	{
		None,
		/// <summary>
		/// Where cards are drawn from.
		/// </summary>
		Draw,
		/// <summary>
		/// Where cards are manually played from.
		/// </summary>
		Hand,
		/// <summary>
		/// Where cards are discarded/flushed to.
		/// </summary>
		Discard,
		/// <summary>
		/// Where cards are exhausted to.
		/// </summary>
		Exhaust,
		/// <summary>
		/// A temporary pile that a card lives in while it's mid-play, so that it isn't counted towards your hand or your
		/// discard pile.
		/// </summary>
		Play,
		/// <summary>
		/// Where cards live between rooms.
		/// When a new combat starts, all cards in here are cloned into your draw pile, so modifications to cards in combat
		/// won't modify cards in here.
		/// </summary>
		Deck
	}
	public static class PileTypeExtensions
	{
		public static CardPile GetPile(this PileType pileType, Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			CardPile cardPile = CardPile.Get(pileType, player);
			if (cardPile == null)
			{
				throw new InvalidOperationException($"Tried to get {pileType} pile while out of combat.");
			}
			return cardPile;
		}

		/// <summary>
		/// Is this pile a combat pile? Combat piles are:
		///
		/// Hand
		/// Draw
		/// Discard
		/// Exhaust
		/// Play
		/// </summary>
		/// <param name="pileType">Pile to check.</param>
		/// <returns>Whether or not it's a combat pile.</returns>
		public static bool IsCombatPile(this PileType pileType)
		{
			if ((uint)(pileType - 1) <= 4u)
			{
				return true;
			}
			return false;
		}

		public static Godot.Vector2 GetTargetPosition(this PileType pileType, NCard? node)
		{
			if (pileType.IsCombatPile() && !CombatManager.Instance.IsInProgress)
			{
				return Godot.Vector2.Zero;
			}
			Godot.Vector2 size = NGame.Instance.GetViewportRect().Size;
			return pileType switch
			{
				PileType.None => size, 
				PileType.Draw => NCombatRoom.Instance.Ui.DrawPile.GlobalPosition + NCombatRoom.Instance.Ui.DrawPile.Size * 0.5f, 
				PileType.Hand => new Godot.Vector2(size.X * 0.5f - node.Size.X * 0.5f, size.Y - node.Size.Y * 0.5f), 
				PileType.Discard => NCombatRoom.Instance.Ui.DiscardPile.GlobalPosition + NCombatRoom.Instance.Ui.DiscardPile.Size * 0.5f, 
				PileType.Play => NCombatRoom.Instance.Ui.PlayContainer.Size * 0.5f - node.Size * 0.5f + Godot.Vector2.Up * 100f, 
				PileType.Deck => NRun.Instance.GlobalUi.TopBar.Deck.GlobalPosition + NRun.Instance.GlobalUi.TopBar.Deck.Size * 0.5f, 
				PileType.Exhaust => NCombatRoom.Instance.Ui.ExhaustPile.GlobalPosition + NCombatRoom.Instance.Ui.ExhaustPile.Size * 0.5f, 
				_ => throw new ArgumentOutOfRangeException("pileType", pileType, "Unknown pile type"), 
			};
		}
	}
