	/// <summary>
	/// Represents a card cost that should only exist temporarily.
	/// Used for effects that set a card's cost to a specific value.
	/// For effects that modify a card's existing cost by a certain amount, see <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.TemporaryCardCostOffset" />.
	/// Used for both temporary energy and star card costs.
	/// </summary>
	public class TemporaryCardCost
	{
		/// <summary>
		/// The amount that this card's cost is set to.
		/// </summary>
		public int Cost { get; private set; }

		/// <summary>
		/// Should this temporary cost be cleared when the turn ends?
		/// This is true for effects that say something like "It costs N _this turn_" (like Attack Potion).
		/// </summary>
		public bool ClearsWhenTurnEnds { get; private set; }

		/// <summary>
		/// Should this temporary cost be cleared when the card is played?
		/// This is true for effects that say something like "It costs N _until played_" (like King's Gambit),
		/// AND for effects that say something like "It costs N _this turn_" (like Attack Potion).
		/// </summary>
		public bool ClearsWhenCardIsPlayed { get; private set; }

		/// <summary>
		/// A temporary cost that is cleared only when the card is played.
		/// </summary>
		public static TemporaryCardCost UntilPlayed(int cost)
		{
			return new TemporaryCardCost
			{
				Cost = Math.Max(cost, 0),
				ClearsWhenTurnEnds = false,
				ClearsWhenCardIsPlayed = true
			};
		}

		/// <summary>
		/// A temporary cost that is cleared when the card is played OR at the end of the current
		/// turn, whichever comes first.
		/// </summary>
		public static TemporaryCardCost ThisTurn(int cost)
		{
			return new TemporaryCardCost
			{
				Cost = Math.Max(cost, 0),
				ClearsWhenTurnEnds = true,
				ClearsWhenCardIsPlayed = true
			};
		}

		/// <summary>
		/// A temporary cost that remains for the entire combat.
		/// </summary>
		public static TemporaryCardCost ThisCombat(int cost)
		{
			return new TemporaryCardCost
			{
				Cost = Math.Max(cost, 0),
				ClearsWhenTurnEnds = false,
				ClearsWhenCardIsPlayed = false
			};
		}
	}
	/// <summary>
	/// Represents a card cost offset that should only exist temporarily.
	/// Used for effects that modify a card's cost by a certain amount.
	/// For effects that set a card's cost to a specific value, see <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.TemporaryCardCost" />.
	/// </summary>
	public class TemporaryCardCostOffset
	{
		/// <summary>
		/// The amount that this card's cost is modified by.
		/// Positive for cost increases, negative for cost decreases.
		/// </summary>
		public int Offset { get; private set; }

		/// <summary>
		/// Should this temporary cost offset be cleared when the turn ends?
		/// This is true for effects that say something like "It costs N more _this turn_".
		/// </summary>
		public bool ClearsWhenTurnEnds { get; private set; }

		/// <summary>
		/// Should this temporary cost offset be cleared when the card is played?
		/// This is true for effects that say something like "It costs N more _until played_",
		/// AND for effects that say something like "It costs N more _this turn_".
		/// </summary>
		public bool ClearsWhenCardIsPlayed { get; private set; }

		/// <summary>
		/// A temporary cost offset that is cleared only when the card is played.
		/// </summary>
		public static TemporaryCardCostOffset UntilPlayed(int offset)
		{
			return new TemporaryCardCostOffset
			{
				Offset = offset,
				ClearsWhenTurnEnds = false,
				ClearsWhenCardIsPlayed = true
			};
		}

		/// <summary>
		/// A temporary cost offset that is cleared when the card is played OR at the end of the current
		/// turn, whichever comes first.
		/// </summary>
		public static TemporaryCardCostOffset ThisTurn(int offset)
		{
			return new TemporaryCardCostOffset
			{
				Offset = offset,
				ClearsWhenTurnEnds = true,
				ClearsWhenCardIsPlayed = true
			};
		}

		/// <summary>
		/// A temporary cost offset that remains for the entire combat.
		/// </summary>
		public static TemporaryCardCostOffset ThisCombat(int offset)
		{
			return new TemporaryCardCostOffset
			{
				Offset = offset,
				ClearsWhenTurnEnds = false,
				ClearsWhenCardIsPlayed = false
			};
		}
	}
	[Flags]
	public enum UnplayableReason
	{
		None = 0,
		/// <summary>
		/// The card has the Unplayable keyword, or its UnplayableThisTurn flag is set to true.
		/// </summary>
		HasUnplayableKeyword = 2,
		/// <summary>
		/// Something like Normality is blocking the card from being played.
		/// </summary>
		BlockedByHook = 4,
		/// <summary>
		/// The card itself has a built-in reason that is blocking its play, like how Grand Finale can't be played unless
		/// your draw pile is empty.
		/// </summary>
		BlockedByCardLogic = 8,
		/// <summary>
		/// You don't have enough energy to play the card.
		/// </summary>
		EnergyCostTooHigh = 0x10,
		/// <summary>
		/// You don't have enough stars to play the card.
		/// </summary>
		StarCostTooHigh = 0x20,
		/// <summary>
		/// You have no living allies you can target.
		/// </summary>
		NoLivingAllies = 0x40
	}
	internal static class UnplayableReasonExtensions
	{
		public static bool HasResourceCostReason(this UnplayableReason reason)
		{
			if (!reason.HasFlag(UnplayableReason.EnergyCostTooHigh))
			{
				return reason.HasFlag(UnplayableReason.StarCostTooHigh);
			}
			return true;
		}

		public static LocString? GetPlayerDialogueLine(this UnplayableReason reason, AbstractModel? preventer = null)
		{
			if (reason.HasFlag(UnplayableReason.NoLivingAllies))
			{
				return new LocString("combat_messages", "NO_LIVING_ALLIES");
			}
			if (reason.HasFlag(UnplayableReason.EnergyCostTooHigh))
			{
				return new LocString("combat_messages", "NOT_ENOUGH_ENERGY");
			}
			if (reason.HasFlag(UnplayableReason.StarCostTooHigh))
			{
				return new LocString("combat_messages", "NOT_ENOUGH_STARS");
			}
			if (reason.HasFlag(UnplayableReason.BlockedByHook))
			{
				if (preventer == null)
				{
					return new LocString("combat_messages", "UNPLAYABLE");
				}
				LocString locString = new LocString("combat_messages", "BLOCKED_BY_HOOK");
				string text = ((preventer is CardModel cardModel) ? cardModel.Title : ((preventer is RelicModel relicModel) ? relicModel.Title.GetFormattedText() : ((preventer is PowerModel powerModel) ? powerModel.Title.GetFormattedText() : ((preventer is EnchantmentModel enchantmentModel) ? enchantmentModel.Title.GetFormattedText() : ((!(preventer is AfflictionModel afflictionModel)) ? null : afflictionModel.Title.GetFormattedText())))));
				string text2 = text;
				if (text2 == null)
				{
					Log.Error($"Missing case for model {preventer} in UnplayableReason.GetPlayerDialogueLine switch!");
					text2 = "<UNKNOWN>";
				}
				locString.Add("BlockingHook", text2);
				return locString;
			}
			if (reason.HasFlag(UnplayableReason.HasUnplayableKeyword) || reason.HasFlag(UnplayableReason.BlockedByCardLogic))
			{
				return new LocString("combat_messages", "UNPLAYABLE");
			}
			return null;
		}
	}
}
namespace MegaCrit.Sts2.Core.Entities.CardRewardAlternatives
{
	/// <summary>
	/// Manages the extra, non card, options in a card reward screen.
	/// i.e. Skip (default option), Sacrifice (for Pael  Wing), Heal +2 (for Dream Catcher)
	/// </summary>
	public class CardRewardAlternative
	{
		public string OptionId { get; }

		public LocString Title => new LocString("card_reward_ui", "OPTION_" + OptionId.ToUpperInvariant() + ".name");

		public string[] Hotkeys { get; }

		/// <summary>
		/// Action to perform when the alternative option is selected.
		/// </summary>
		public Func<Task> OnSelect { get; private set; }

		/// <summary>
		/// The action to take after the alternate reward is selected. See the values for more information.
		/// </summary>
		public PostAlternateCardRewardAction AfterSelected { get; private set; }

		public CardRewardAlternative(string optionId, PostAlternateCardRewardAction afterSelected)
			: this(optionId, () => Task.CompletedTask, afterSelected)
		{
		}

		public CardRewardAlternative(string optionId, Func<Task> onSelect, PostAlternateCardRewardAction afterSelected)
		{
			OptionId = optionId;
			OnSelect = onSelect;
			AfterSelected = afterSelected;
			Hotkeys = ((afterSelected != PostAlternateCardRewardAction.EndSelectionAndDoNotCompleteReward) ? new string[1] { MegaInput.viewExhaustPileAndTabRight } : new string[2]
			{
				MegaInput.cancel,
				MegaInput.pauseAndBack
			});
		}

		/// <summary>
		/// Generates a list of extra options to use for the next card reward screen.
		/// This list will include extra options added by models like the Pael Wing relic if the player has them.
		/// </summary>
		/// <param name="cardReward">The reward for which alternatives are being generated.</param>
		/// <returns>List of rest extra options options.</returns>
		public static IReadOnlyList<CardRewardAlternative> Generate(CardReward cardReward)
		{
			List<CardRewardAlternative> list = new List<CardRewardAlternative>();
			if (cardReward.CanSkip)
			{
				list.Add(new CardRewardAlternative("Skip", PostAlternateCardRewardAction.EndSelectionAndDoNotCompleteReward));
			}
			if (cardReward.CanReroll)
			{
				list.Add(new CardRewardAlternative("REROLL", delegate
				{
					cardReward.Reroll();
					return Task.CompletedTask;
				}, PostAlternateCardRewardAction.DoNothing));
			}
			Hook.ModifyCardRewardAlternatives(cardReward.Player.RunState, cardReward.Player, cardReward, list);
			if (list.Count > 2)
			{
				throw new InvalidOperationException("More than 2 card reward alternatives are not supported.");
			}
			return list;
		}
	}
}
namespace MegaCrit.Sts2.Core.Entities.Ascension
{
	public enum AscensionLevel
	{
		None,
		SwarmingElites,
		WearyTraveler,
		Poverty,
		TightBelt,
		AscendersBane,
		Inflation,
		Scarcity,
		ToughEnemies,
		DeadlyEnemies,
		DoubleBoss
	}
	/// <summary>
	/// Manages ascension logic for runs.
	/// Responsible for tracking ascension levels and applying ascension effects.
	/// </summary>
	public class AscensionManager
	{
		/// <summary>
		/// The maximum ascension level allowed in the game.
		/// </summary>
		public const int maxAscensionAllowed = 10;

		/// <summary>
		/// The current ascension level for the run.
		/// </summary>
		private readonly int _level;

		/// <summary>
		/// Create a new AscensionManager with the specified ascension level.
		/// </summary>
		/// <param name="level">The ascension level for this run.</param>
		public AscensionManager(int level)
		{
			_level = level;
		}

		/// <summary>
		/// Create a new AscensionManager with the specified ascension level.
		/// </summary>
		/// <param name="level">The ascension level enum value for this run.</param>
		public AscensionManager(AscensionLevel level)
		{
			_level = (int)level;
		}

		/// <summary>
		/// Check if a given ascension level is active in the current run.
		/// </summary>
		/// <param name="level">The ascension level to check.</param>
		/// <returns>True if the specified level is active.</returns>
		public bool HasLevel(AscensionLevel level)
		{
			return _level >= (int)level;
		}

		/// <summary>
		/// Apply ascension effects to a player based on the current ascension level.
		/// </summary>
		/// <param name="player">The player to apply effects to.</param>
		public void ApplyEffectsTo(Player player)
		{
			if (HasLevel(AscensionLevel.TightBelt))
			{
				player.SubtractFromMaxPotionCount(1);
			}
			if (HasLevel(AscensionLevel.AscendersBane))
			{
				AscendersBane ascendersBane = player.RunState.CreateCard<AscendersBane>(player);
				ascendersBane.FloorAddedToDeck = 1;
				player.Deck.AddInternal(ascendersBane, -1, silent: true);
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Entities.Ancients
{
	public class AncientDialogue
	{
		private const string _locTable = "ancients";

		public IReadOnlyList<AncientDialogueLine> Lines { get; }

		/// <summary>
		/// Should this dialogue be added to the pool of dialogues that can be repeated on future visits?
		/// Can be set manually or auto-populated from loc keys via the "r" suffix (e.g., "1-0r.ancient").
		/// </summary>
		public bool IsRepeating { get; set; }

		/// <summary>
		/// What visit should this dialogue be shown on?
		/// This can be combined with <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.IsRepeating" /> to show a dialogue on the Nth visit, and then add it to the
		/// pool of repeating dialogues for visits after that.
		/// </summary>
		/// <example>
		/// 0: Show this dialogue on this character's first visit to this ancient.
		/// 1: Show this dialogue on this character's second visit to this ancient.
		/// 4: Show this dialogue on this character's fifth visit to this ancient.
		/// null: Show this dialogue on any visit to this ancient.
		/// </example>
		public int? VisitIndex { get; init; }

		/// <summary>
		/// For Architect dialogues, who should attack at the start?
		/// </summary>
		public ArchitectAttackers StartAttackers { get; init; }

		/// <summary>
		/// For Architect dialogues, who should attack at the end?
		/// </summary>
		public ArchitectAttackers EndAttackers { get; init; }

		/// <summary>
		/// Create a new dialogue.
		/// The number of SFX you pass controls how many lines this dialogue has.
		/// </summary>
		/// <param name="sfxPaths">
		/// The paths to the SFX that should be played when this dialogue is shown.
		/// Each SFX corresponds to a line in the dialogue.
		/// Passing an empty string for a given line indicates that no dialogue should be played for it, but you must pass
		/// some string for every line.
		/// For example, if you have a single-line dialogue with no SFX, call `new AncientDialogue("")`.
		/// If you called `new AncientDialogue()`, you'd create a dialogue with 0 lines.
		/// </param>
		public AncientDialogue(params string[] sfxPaths)
		{
			if (sfxPaths.Length == 0)
			{
				throw new ArgumentException("Requires at least 1 SFX path", "sfxPaths");
			}
			Lines = sfxPaths.Select((string sfx) => new AncientDialogueLine(sfx)).ToList();
		}

		/// <summary>
		/// Populate this dialogue's lines with the correct loc keys.
		/// IsRepeating is derived from the presence of the "r" suffix in the first line's loc key.
		/// Speaker is derived from which key suffix exists in the JSON: ".ancient" or ".char".
		/// </summary>
		/// <param name="ancientEntry">The ID entry for the ancient that this line is for.</param>
		/// <param name="charEntry">
		/// The ID entry for the character that this line is for.
		/// Can also be "ANY" for character-agnostic dialogues, or "firstVisitEver" for the dialogue that should be shown the
		/// first time you ever visit this ancient (regardless of character).
		/// </param>
		/// <param name="dialogueIndex">
		/// The index of this dialogue in the list of dialogues for this ancient and character.
		/// </param>
		public void PopulateLines(string ancientEntry, string charEntry, int dialogueIndex)
		{
			string baseKey = $"{ancientEntry}.talk.{charEntry}.{dialogueIndex}-0";
			bool flag = HasRepeatingSuffix(baseKey);
			if (flag)
			{
				IsRepeating = true;
			}
			string text = (flag ? "r" : "");
			for (int i = 0; i < Lines.Count; i++)
			{
				string text2 = $"{ancientEntry}.talk.{charEntry}.{dialogueIndex}-{i}";
				bool flag2 = HasRepeatingSuffix(text2);
				if (flag && !flag2)
				{
					throw new InvalidOperationException($"Dialogue {ancientEntry}.talk.{charEntry}.{dialogueIndex}: line 0 has 'r' suffix but line {i} does not.");
				}
				if (!flag & flag2)
				{
					throw new InvalidOperationException($"Dialogue {ancientEntry}.talk.{charEntry}.{dialogueIndex}: line 0 has no 'r' suffix but line {i} does.");
				}
				string text3 = text2 + text;
				string text4 = text3 + ".ancient";
				string locEntryKey = text3 + ".char";
				if (LocString.Exists("ancients", text4))
				{
					Lines[i].LineText = new LocString("ancients", text4);
					Lines[i].Speaker = AncientDialogueSpeaker.Ancient;
				}
				else
				{
					Lines[i].LineText = new LocString("ancients", locEntryKey);
					Lines[i].Speaker = AncientDialogueSpeaker.Character;
				}
			}
		}

		private static bool HasRepeatingSuffix(string baseKey)
		{
			if (!LocString.Exists("ancients", baseKey + "r.ancient"))
			{
				return LocString.Exists("ancients", baseKey + "r.char");
			}
			return true;
		}
	}
	public class AncientDialogueLine
	{
		public const string sfxFallbackPath = "event:/sfx/ui/enchant_simple";

		/// <summary>
		/// The path to the SFX that should be played when this line of dialogue is shown.
		/// Empty string means no SFX.
		/// </summary>
		private readonly string _sfxPath;

		/// <summary>
		/// The text that should be shown for this line of dialogue.
		/// </summary>
		public LocString? LineText { get; set; }

		/// <summary>
		/// The text that should be shown on the "Next" button that goes with this line of dialogue.
		/// Null for the last line in a dialogue.
		/// </summary>
		public LocString? NextButtonText { get; set; }

		/// <summary>
		/// The speaker of this line of dialogue.
		/// </summary>
		public AncientDialogueSpeaker Speaker { get; set; }

		public AncientDialogueLine(string sfxPath)
		{
			_sfxPath = sfxPath;
		}

		/// <summary>
		/// Get the path to the SFX to play for this line of dialogue.
		/// Returns a fallback if the SFX path is empty.
		/// </summary>
		public string GetSfxOrFallbackPath()
		{
			if (!string.IsNullOrEmpty(_sfxPath))
			{
				return _sfxPath;
			}
			return "event:/sfx/ui/enchant_simple";
		}
	}
	/// <summary>
	/// Represents the complete dialogue configuration for an ancient, organized by category.
	/// Each ancient defines its dialogues explicitly in C# via <see cref="M:MegaCrit.Sts2.Core.Models.AncientEventModel.DefineDialogues" />.
	/// Keys use X-Y format where X is the dialogue index within a collection and Y is the line index within a dialogue.
	/// Each line key ends with ".ancient" or ".char" to indicate the speaker. The speaker is derived from which key
	/// exists in the JSON at PopulateLocKeys time.
	///
	/// Dialogues that should be added to the "repeating" pool encode their repeating status in the loc keys by appending
	/// "r" to the X-Y component.
	/// For example, "1-0r.ancient" indicates a repeating dialogue line. When <see cref="M:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.PopulateLines(System.String,System.String,System.Int32)" />
	/// detects the "r" suffix on the first line, it automatically sets <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.IsRepeating" /> to true.
	///
	/// For example:
	/// "DARV.talk.IRONCLAD.0-0.ancient": "Dialogue 1, line 1 (ancient speaks)",
	/// "DARV.talk.IRONCLAD.0-1.char": "Dialogue 1, line 2 (character speaks)",
	/// "DARV.talk.IRONCLAD.0-2.ancient": "Dialogue 1, line 3 (ancient speaks)",
	/// "DARV.talk.IRONCLAD.1-0r.ancient": "Dialogue 2, line 1 (ancient speaks, repeating)",
	///
	/// "Next" button text must also be supplied for every line except the last line in each dialogue.
	/// Repeating dialogues use the "r" suffix on their next keys as well.
	///
	/// For example:
	/// "DARV.talk.IRONCLAD.0-0.ancient": "Dialogue 1, line 1",
	/// "DARV.talk.IRONCLAD.0-0.next": "Respond",
	/// "DARV.talk.IRONCLAD.0-1.char": "Dialogue 1, line 2",
	/// "DARV.talk.IRONCLAD.0-1.next": "Continue",
	/// "DARV.talk.IRONCLAD.0-2.ancient": "Dialogue 1, line 3",
	/// "DARV.talk.IRONCLAD.1-0r.ancient": "Dialogue 2, line 1 (repeating)",
	/// "DARV.talk.IRONCLAD.1-0r.next": "Acknowledge",
	/// "DARV.talk.IRONCLAD.1-1r.ancient": "Dialogue 2, line 2 (repeating)",
	/// </summary>
	public class AncientDialogueSet
	{
		/// <summary>
		/// First time ANY character visits this ancient (global once-only).
		/// Shown when totalAncientVisits == 0.
		/// If null, this ancient has no first-visit-ever dialogue (for example, The Architect).
		/// Example key: "DARV.talk.firstVisitEver.0-0.ancient"
		/// </summary>
		public required AncientDialogue? FirstVisitEverDialogue { get; init; }

		/// <summary>
		/// Per-character dialogues.
		/// Each <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue" /> carries its own <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.VisitIndex" /> and
		/// <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.IsRepeating" /> metadata to determine when it should be shown.
		/// Example key: "DARV.talk.IRONCLAD.0-0.ancient"
		/// </summary>
		public required System.Collections.Generic.Dictionary<string, IReadOnlyList<AncientDialogue>> CharacterDialogues { get; init; }

		/// <summary>
		/// Character-agnostic dialogues. Used as fallback when no visit-specific dialogue applies.
		/// Example key: "DARV.talk.ANY.0-0.ancient"
		/// </summary>
		public required IReadOnlyList<AncientDialogue> AgnosticDialogues { get; init; } = System.Array.Empty<AncientDialogue>();

		/// <summary>
		/// Get every dialogue in this set.
		/// </summary>
		public IEnumerable<AncientDialogue> GetAllDialogues()
		{
			if (FirstVisitEverDialogue != null)
			{
				yield return FirstVisitEverDialogue;
			}
			foreach (IReadOnlyList<AncientDialogue> value in CharacterDialogues.Values)
			{
				foreach (AncientDialogue item in value)
				{
					yield return item;
				}
			}
			foreach (AncientDialogue agnosticDialogue in AgnosticDialogues)
			{
				yield return agnosticDialogue;
			}
		}

		/// <summary>
		/// Get valid dialogues for the specified character and visit counts.
		/// Returns a collection of dialogue sequences; the caller picks one randomly.
		///
		/// Priority order:
		/// 1. FirstVisitEverDialogue (totalVisits == 0)
		/// 2. Visit-specific dialogues for this character (matching VisitIndex)
		/// 3. Visit-specific character-agnostic dialogues (matching VisitIndex)
		/// 4. Repeating pool (character-specific + character-agnostic IsRepeating)
		/// </summary>
		/// <param name="characterId">The ID of the character visiting this ancient.</param>
		/// <param name="charVisits">Number of times this character has previously visited this ancient.</param>
		/// <param name="totalVisits">Total number of visits to this ancient across all characters.</param>
		/// <param name="allowAnyCharacterDialogues">
		/// Whether character-agnostic repeating dialogues are allowed.
		/// See <see cref="P:MegaCrit.Sts2.Core.Models.AncientEventModel.AnyCharacterDialogueBlacklist" />.
		/// </param>
		/// <returns>A collection of valid dialogue sequences to choose from.</returns>
		public IEnumerable<AncientDialogue> GetValidDialogues(ModelId characterId, int charVisits, int totalVisits, bool allowAnyCharacterDialogues)
		{
			if (totalVisits == 0 && FirstVisitEverDialogue != null)
			{
				return new global::<>z__ReadOnlySingleElementList<AncientDialogue>(FirstVisitEverDialogue);
			}
			IReadOnlyList<AncientDialogue> readOnlyList = null;
			if (CharacterDialogues.TryGetValue(characterId.Entry, out IReadOnlyList<AncientDialogue> value))
			{
				readOnlyList = value;
				List<AncientDialogue> list = readOnlyList.Where((AncientDialogue d) => d.VisitIndex == charVisits).ToList();
				if (list.Count > 0)
				{
					return list;
				}
			}
			if (allowAnyCharacterDialogues)
			{
				List<AncientDialogue> list2 = AgnosticDialogues.Where((AncientDialogue d) => d.VisitIndex == charVisits).ToList();
				if (list2.Count > 0)
				{
					return list2;
				}
			}
			List<AncientDialogue> list3 = new List<AncientDialogue>();
			if (readOnlyList != null)
			{
				AddRepeatingDialogues(readOnlyList, list3, charVisits);
			}
			if (allowAnyCharacterDialogues)
			{
				AddRepeatingDialogues(AgnosticDialogues, list3, charVisits);
			}
			return list3;
		}

		/// <summary>
		/// Auto-derives <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogueLine.LineText" /> and <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogueLine.NextButtonText" />
		/// LocStrings for every line based on its position in the dialogue structure.
		/// Keys use X-Y format where X is the dialogue index within a collection and Y is the line index within a dialogue.
		/// </summary>
		public void PopulateLocKeys(string ancientEntry)
		{
			FirstVisitEverDialogue?.PopulateLines(ancientEntry, "firstVisitEver", 0);
			foreach (var (charEntry, readOnlyList2) in CharacterDialogues)
			{
				for (int i = 0; i < readOnlyList2.Count; i++)
				{
					readOnlyList2[i].PopulateLines(ancientEntry, charEntry, i);
				}
			}
			for (int j = 0; j < AgnosticDialogues.Count; j++)
			{
				AgnosticDialogues[j].PopulateLines(ancientEntry, "ANY", j);
			}
			foreach (AncientDialogue allDialogue in GetAllDialogues())
			{
				for (int k = 0; k < allDialogue.Lines.Count - 1; k++)
				{
					AncientDialogueLine ancientDialogueLine = allDialogue.Lines[k];
					string locEntryKey = ancientDialogueLine.LineText.LocEntryKey;
					string text2 = locEntryKey.Substring(0, locEntryKey.LastIndexOf('.'));
					string locEntryKey2 = text2 + ".next";
					ancientDialogueLine.NextButtonText = new LocString("ancients", locEntryKey2);
				}
			}
		}

		private static void AddRepeatingDialogues(IEnumerable<AncientDialogue> source, List<AncientDialogue> destination, int charVisits)
		{
			foreach (AncientDialogue item in source)
			{
				if (item.IsRepeating && (!item.VisitIndex.HasValue || !(charVisits < item.VisitIndex)))
				{
					destination.Add(item);
				}
			}
		}
	}
	public enum AncientDialogueSpeaker
	{
		/// <summary>
