namespace MegaCrit.Sts2.Core.DevConsole.ConsoleCommands
{
	[GenerateSubtypes(DynamicallyAccessedMemberTypes = DynamicallyAccessedMemberTypes.PublicParameterlessConstructor)]
	public abstract class AbstractConsoleCmd
	{
		public abstract string CmdName { get; }

		public abstract string Args { get; }

		public abstract string Description { get; }

		public abstract bool IsNetworked { get; }

		public virtual bool DebugOnly => true;

		public abstract CmdResult Process(Player? issuingPlayer, string[] args);

		/// <summary>
		/// Provides argument completion candidates for console commands.
		/// Commands should override this method to provide context-aware completion suggestions.
		/// Returns an empty result by default for commands that don't require argument completion.
		/// </summary>
		/// <param name="player">The player invoking the command</param>
		/// <param name="args">Current command arguments being typed</param>
		/// <returns>Completion result containing candidates and context information</returns>
		public virtual CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName,
				ArgumentIndex = args.Length - 1,
				CommandPrefix = BuildPrefix(args)
			};
		}

		/// <summary>
		/// Creates a completion result for command arguments with explicit separation of completed vs partial arguments.
		/// This makes the completion logic clear and prevents bugs from implicit argument slicing.
		/// </summary>
		/// <param name="candidates">All possible completion candidates</param>
		/// <param name="completedArgs">Arguments that are already fully typed (e.g., ["OFFERING"] when completing second arg)</param>
		/// <param name="partialArg">The argument currently being typed (e.g., "de" when typing "deck")</param>
		/// <param name="type">The type of completion being performed</param>
		/// <param name="matchPredicate">Optional custom matching predicate (defaults to StartsWith)</param>
		/// <returns>CompletionResult with filtered candidates and completion prefix</returns>
		protected CompletionResult CompleteArgument(IEnumerable<string> candidates, string[] completedArgs, string partialArg, CompletionType type = CompletionType.Argument, Func<string, string, bool>? matchPredicate = null)
		{
			List<string> list = candidates.ToList();
			if (matchPredicate == null)
			{
				matchPredicate = (string candidate, string partial) => candidate.StartsWith(partial, StringComparison.OrdinalIgnoreCase);
			}
			List<string> list2 = ((!string.IsNullOrWhiteSpace(partialArg)) ? list.Where((string c) => matchPredicate(c, partialArg)).ToList() : list);
			string text = BuildPrefix(completedArgs);
			string commonPrefix = CalculateCommonCompletion(list2, text);
			return new CompletionResult
			{
				Candidates = list2,
				CommonPrefix = commonPrefix,
				Type = type,
				ArgumentContext = CmdName,
				ArgumentIndex = completedArgs.Length,
				CommandPrefix = text
			};
		}

		/// <summary>
		/// Builds the command prefix from completed arguments (not including the partial arg being typed).
		/// Example: BuildPrefix(["OFFERING"]) returns "card OFFERING "
		/// </summary>
		protected string BuildPrefix(string[] completedArgs)
		{
			if (completedArgs.Length == 0)
			{
				return CmdName + " ";
			}
			return CmdName + " " + string.Join(" ", completedArgs) + " ";
		}

		/// <summary>
		/// Parses a string into an enum value, rejecting numeric strings and undefined values.
		/// Use this instead of Enum.TryParse to avoid accepting raw integers as valid enum values.
		/// </summary>
		protected static bool TryParseEnum<T>(string input, out T result) where T : struct, Enum
		{
			if (Enum.TryParse<T>(input, ignoreCase: true, out result))
			{
				return Enum.IsDefined(result);
			}
			return false;
		}

		/// <summary>
		/// Calculates the common completion string from filtered candidates.
		/// Single match gets trailing space, multiple matches get longest common prefix.
		/// </summary>
		private string CalculateCommonCompletion(List<string> filtered, string prefix)
		{
			if (filtered.Count == 0)
			{
				return "";
			}
			if (filtered.Count == 1)
			{
				return prefix + filtered[0] + " ";
			}
			int num = filtered.Min((string s) => s.Length);
			string text = filtered[0];
			int num2 = 0;
			for (int i = 0; i < num; i++)
			{
				char c = text[i];
				if (!filtered.All((string s) => char.ToLowerInvariant(s[i]) == char.ToLowerInvariant(c)))
				{
					break;
				}
				num2 = i + 1;
			}
			if (num2 > 0)
			{
				return prefix + text.Substring(0, num2);
			}
			return "";
		}
	}
	public class AchievementConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "achievement";

		public override string Args => "<operation:string> [id:string]";

		public override string Description => "Unlocks or revokes an achievement. If no achievement is provided, all achievements are unlocked or revoked.";

		public override bool IsNetworked => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			int num = 3;
			List<string> list = new List<string>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<string> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = "unlock";
			num2++;
			span[num2] = "revoke";
			num2++;
			span[num2] = "check";
			List<string> list2 = list;
			if (args.Length < 1 || !list2.Contains(args[0]))
			{
				return new CmdResult(success: false, "First argument must be one of: " + string.Join(",", list2) + ".\n" + Args);
			}
			Achievement? achievement = null;
			if (args.Length >= 2)
			{
				string text = args[1].ToLowerInvariant();
				Achievement[] values = Enum.GetValues<Achievement>();
				for (int i = 0; i < values.Length; i++)
				{
					Achievement value = values[i];
					if (StringHelper.SnakeCase(value.ToString()) == text)
					{
						achievement = value;
						break;
					}
				}
				if (!achievement.HasValue)
				{
					return new CmdResult(success: false, "Achievement '" + args[1] + "' unrecognized.\n" + Args);
				}
			}
			if (args[0] == "unlock")
			{
				if (achievement.HasValue)
				{
					AchievementsUtil.Unlock(achievement.Value, issuingPlayer);
					return new CmdResult(success: true, $"Unlocked {achievement.Value}");
				}
				Achievement[] values2 = Enum.GetValues<Achievement>();
				foreach (Achievement achievement2 in values2)
				{
					AchievementsUtil.Unlock(achievement2, issuingPlayer);
				}
				return new CmdResult(success: true, "Unlocked all achievements");
			}
			if (args[0] == "revoke")
			{
				if (achievement.HasValue)
				{
					AchievementsUtil.Revoke(achievement.Value);
					return new CmdResult(success: true, $"Revoked {achievement.Value}");
				}
				Achievement[] values3 = Enum.GetValues<Achievement>();
				foreach (Achievement achievement3 in values3)
				{
					AchievementsUtil.Revoke(achievement3);
				}
				return new CmdResult(success: true, "Revoked all achievements");
			}
			if (args[0] == "check")
			{
				if (!achievement.HasValue)
				{
					return new CmdResult(success: false, "Achievement name must be provided");
				}
				if (AchievementsUtil.IsUnlocked(achievement.Value))
				{
					return new CmdResult(success: true, $"{achievement.Value} is unlocked");
				}
				return new CmdResult(success: true, $"{achievement.Value} is not unlocked");
			}
			throw new NotImplementedException();
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				List<string> candidates = new List<string> { "unlock", "revoke", "check" };
				return CompleteArgument(candidates, System.Array.Empty<string>(), args.FirstOrDefault() ?? "", CompletionType.Subcommand);
			}
			if (args.Length == 2)
			{
				List<string> list = (from a in Enum.GetValues<Achievement>()
					select StringHelper.SnakeCase(a.ToString())).ToList();
				list.Sort();
				return CompleteArgument(list, new string[1] { args[0] }, args[1]);
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
	public class ActConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "act";

		public override string Args => "<int|string: act>";

		public override string Description => "Jumps to an act. If integer, will jump to that act. Otherwise, replaces the current act with the act passed.";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length != 1)
			{
				return new CmdResult(success: false, "There must be one argument.");
			}
			if (issuingPlayer?.RunState == null)
			{
				return new CmdResult(success: false, "This command only works during a run.");
			}
			if (int.TryParse(args[0], out var result))
			{
				int count = issuingPlayer.RunState.Acts.Count;
				if (result > count || result < 1)
				{
					return new CmdResult(success: false, $"The act you are trying to navigate to does not exist. Select act indexes between: 1-{count}");
				}
				int actIndex = result - 1;
				Task task = NextAct(actIndex);
				return new CmdResult(task, success: true, $"Navigated to act '{result}'.");
			}
			string actName = args[0].ToUpperInvariant();
			ActModel actModel = ModelDb.Acts.FirstOrDefault((ActModel c) => c.Id.Entry == actName);
			if (actModel == null)
			{
				return new CmdResult(success: false, "Act named " + actName + " not found.");
			}
			RunState runState = (RunState)issuingPlayer.RunState;
			actModel = actModel.ToMutable();
			runState.SetActDebug(actModel);
			actModel.GenerateRooms(runState.Rng.UpFront, runState.UnlockState, runState.Players.Count > 1);
			Task task2 = RunManager.Instance.EnterAct(runState.CurrentActIndex);
			return new CmdResult(task2, success: true, "Replaced current act with act " + actName + ".");
		}

		private static async Task NextAct(int actIndex)
		{
			NMapScreen.Instance.SetTravelEnabled(enabled: true);
			await RunManager.Instance.EnterAct(actIndex);
		}
	}
	public class AfflictConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "afflict";

		public override string Args => "<id:string> [amount:int] [hand-index:int]";

		public override string Description => "Apply the specified affliction to a card in the player's hand";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length == 0)
			{
				return new CmdResult(success: false, "Must specify an affliction ID!");
			}
			if (!CombatManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "Combat is not currently in progress!");
			}
			ModelId modelId = new ModelId(ModelId.SlugifyCategory<AfflictionModel>(), args[0].ToUpperInvariant());
			AfflictionModel afflictionModel;
			try
			{
				afflictionModel = ModelDb.GetById<AfflictionModel>(modelId).ToMutable();
			}
			catch (ModelNotFoundException)
			{
				return new CmdResult(success: false, "Affliction '" + modelId.Entry + "' not found");
			}
			int result = 0;
			int result2 = 0;
			if (args.Length > 1 && !int.TryParse(args[1], out result))
			{
				return new CmdResult(success: false, "Arg 2 must be the affliction count (int), got '" + args[1] + "'.");
			}
			if (args.Length > 2 && !int.TryParse(args[2], out result2))
			{
				return new CmdResult(success: false, "Arg 3 must be the hand index (int), got '" + args[2] + "'.");
			}
			CardPile pile = PileType.Hand.GetPile(issuingPlayer);
			IReadOnlyList<CardModel> cards = pile.Cards;
			int count = cards.Count;
			if (result2 < 0 || result2 >= count)
			{
				return new CmdResult(success: false, $"Invalid hand index {result2}. Valid range: 0-{count - 1}.");
			}
			CardModel cardModel = pile.Cards[result2];
			Task task = CardCmd.Afflict(afflictionModel, cardModel, result);
			return new CmdResult(task, success: true, $"Afflicted card {cardModel.Title} with {result} {afflictionModel.Title.GetFormattedText()}");
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				List<string> candidates = ModelDb.DebugAfflictions.Select((AfflictionModel affliction) => affliction.Id.Entry).ToList();
				return CompleteArgument(candidates, System.Array.Empty<string>(), args.FirstOrDefault() ?? "");
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
	public class AncientConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "ancient";

		public override string Args => "<id:string> <choice:string>";

		public override string Description => "Opens an ancient event with the selected choice";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length == 0)
			{
				return new CmdResult(success: false, "No ancient ID specified.");
			}
			ModelId id = new ModelId(ModelDb.GetCategory(typeof(EventModel)), args[0].ToUpperInvariant());
			EventModel byIdOrNull = ModelDb.GetByIdOrNull<EventModel>(id);
			if (!(byIdOrNull is AncientEventModel ancientEventModel))
			{
				return new CmdResult(success: false, "Invalid ancient ID.");
			}
			string choice = null;
			if (args.Length > 1)
			{
				choice = args[1].ToUpperInvariant();
			}
			if (choice != null && !ancientEventModel.AllPossibleOptions.Any((EventOption option) => option.TextKey.Contains(choice)))
			{
				return new CmdResult(success: false, "invalid ancient choice.");
			}
			EventRoom room = new EventRoom(byIdOrNull)
			{
				OnStart = SetDebugOption
			};
			issuingPlayer.RunState.AppendToMapPointHistory(MapPointType.Ancient, RoomType.Event, byIdOrNull.Id);
			Task task = RunManager.Instance.EnterRoom(room);
			return new CmdResult(task, success: true, "Opened Ancient Event. Forced " + (choice ?? "no") + " option");
			void SetDebugOption(EventModel e)
			{
				((AncientEventModel)e).DebugOption = choice;
			}
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				List<string> candidates = ModelDb.AllAncients.Select((AncientEventModel ancient) => ancient.Id.Entry).ToList();
				return CompleteArgument(candidates, System.Array.Empty<string>(), args.FirstOrDefault() ?? "");
			}
			if (args.Length == 2)
			{
				ModelId id = new ModelId(ModelDb.GetCategory(typeof(EventModel)), args[0].ToUpperInvariant());
				EventModel byIdOrNull = ModelDb.GetByIdOrNull<EventModel>(id);
				if (byIdOrNull is AncientEventModel ancientEventModel)
				{
					List<string> candidates2 = ancientEventModel.AllPossibleOptions.Select((EventOption option) => option.TextKey.Split('.').Last()).ToList();
					return CompleteArgument(candidates2, new string[1] { args[0] }, args[1]);
				}
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
	public class ApplyPowerConsoleCmd : AbstractConsoleCmd
	{
		private static List<PowerModel>? _allPowers;

		public override string CmdName => "power";

		public override string Args => "<id:string> <amount:int> <target-index:int>";

		public override string Description => "Grant power to given target at index.";

		public override bool IsNetworked => true;

		private static IEnumerable<PowerModel> AllPowers
		{
			get
			{
				if (_allPowers == null)
				{
					_allPowers = ModelDb.AllAbstractModelSubtypes.Where((Type t) => t.IsSubclassOf(typeof(PowerModel))).Select(ModelDb.DebugPower).ToList();
				}
				return _allPowers;
			}
		}

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (!CombatManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "This doesn't appear to be a combat!");
			}
			if (args.Length < 3)
			{
				return new CmdResult(success: false, "There must be 3 args.");
			}
			if (!int.TryParse(args[1], out var result))
			{
				return new CmdResult(success: false, "Arg 1 must be the amount of power to be applied.");
			}
			string powerId = args[0].ToUpperInvariant();
			PowerModel power = AllPowers.FirstOrDefault((PowerModel c) => c.Id.Entry == powerId);
			if (power == null)
			{
				return new CmdResult(success: false, "The power id " + powerId + " does not exist.");
			}
			if (!int.TryParse(args[2], out var result2))
			{
				return new CmdResult(success: false, "Arg 2 must be the target index if specified.");
			}
			IReadOnlyList<Creature> creatures = CombatManager.Instance.DebugOnlyGetState().Creatures;
			if (result2 < 0 || result2 >= creatures.Count)
			{
				return new CmdResult(success: false, $"Invalid target index {result2}. Valid range: 0-{creatures.Count - 1}");
			}
			Creature creature = creatures[result2];
			PowerModel powerModel = creature.Powers.FirstOrDefault((PowerModel p) => p.GetType() == power.GetType());
			PlayerChoiceContext choiceContext = new BlockingPlayerChoiceContext();
			Task task = ((power.InstanceType == PowerInstanceType.None && powerModel != null) ? PowerCmd.ModifyAmount(choiceContext, powerModel, result, null, null) : PowerCmd.Apply(choiceContext, power.ToMutable(), creature, result, null, null));
			return new CmdResult(task, success: true, "AppliedPower: [" + string.Join(",", creature.IsPlayer ? "PLAYER" : creature.Monster.Id.Entry) + "]");
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				List<string> candidates = AllPowers.Select((PowerModel p) => p.Id.Entry).ToList();
				return CompleteArgument(candidates, System.Array.Empty<string>(), args.FirstOrDefault() ?? "");
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
	public class ArtConsoleCmd : AbstractConsoleCmd
	{
		private struct MissingArt
		{
			public AbstractModel Model { get; }

			public string IntendedPath { get; }

			public string Description { get; }

			public MissingArt(AbstractModel model, string intendedPath, string description)
			{
				Model = model;
				IntendedPath = intendedPath;
				Description = description;
			}
		}

		private static readonly string[] _types = new string[5] { "affliction", "card", "enchantment", "power", "relic" };

		public override string CmdName => "art";

		public override string Args => "<type:string>";

		public override string Description => "Lists all the content of the specified type that is missing art. " + TypesHint;

		public override bool IsNetworked => false;

		private static string TypesHint => "Types: " + string.Join(", ", _types) + ".";

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length < 1)
			{
				return new CmdResult(success: false, CmdName + " requires a type. " + TypesHint);
			}
			string text = args[0].ToLowerInvariant();
			if (text.EndsWith('s'))
			{
				string text2 = text;
				text = text2.Substring(0, text2.Length - 1);
			}
			List<MissingArt> list = new List<MissingArt>();
			switch (text)
			{
			case "affliction":
				foreach (AfflictionModel debugAffliction in ModelDb.DebugAfflictions)
				{
					if (!debugAffliction.HasOverlay)
					{
						list.Add(new MissingArt(debugAffliction, debugAffliction.OverlayPath, debugAffliction.DynamicDescription.GetRawText()));
					}
				}
				break;
			case "card":
				foreach (CardModel allCard in ModelDb.AllCards)
				{
					if (allCard is DeprecatedCard)
					{
						continue;
					}
					foreach (string allPortraitPath in allCard.AllPortraitPaths)
					{
						var (text5, spriteName3) = AtlasResourceLoader.ParsePath(allPortraitPath);
						if (text5 == null || !AtlasManager.HasSprite(text5, spriteName3))
						{
							list.Add(new MissingArt(allCard, allCard.PortraitPath, allCard.Description.GetRawText()));
						}
					}
				}
				break;
			case "enchantment":
				foreach (EnchantmentModel debugEnchantment in ModelDb.DebugEnchantments)
				{
					if (!(debugEnchantment is DeprecatedEnchantment) && !(debugEnchantment.IconPath == debugEnchantment.IntendedIconPath))
					{
						list.Add(new MissingArt(debugEnchantment, debugEnchantment.IntendedIconPath, debugEnchantment.DynamicDescription.GetRawText()));
					}
				}
				break;
			case "power":
				foreach (PowerModel allPower in ModelDb.AllPowers)
				{
					var (text4, spriteName2) = AtlasResourceLoader.ParsePath(allPower.PackedIconPath);
					if (text4 == null || !AtlasManager.HasSprite(text4, spriteName2))
					{
						list.Add(new MissingArt(allPower, allPower.PackedIconPath, allPower.Description.GetRawText()));
					}
				}
				break;
			case "relic":
				foreach (RelicModel allRelic in ModelDb.AllRelics)
				{
					var (text3, spriteName) = AtlasResourceLoader.ParsePath(allRelic.PackedIconPath);
					if (text3 == null || !AtlasManager.HasSprite(text3, spriteName))
					{
						list.Add(new MissingArt(allRelic, allRelic.PackedIconPath, allRelic.DynamicDescription.GetRawText()));
					}
				}
				break;
			default:
				return new CmdResult(success: false, "'" + args[0] + "' is not a valid type. " + TypesHint);
			}
			string value = ((list.Count == 1) ? "" : "s");
			StringBuilder stringBuilder = new StringBuilder($"{list.Count} {text}{value} with missing art:\n");
			foreach (MissingArt item in list.OrderBy((MissingArt m) => m.Model.Id.Entry))
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(0, 1, stringBuilder2);
				handler.AppendFormatted(item.Model.Id.Entry);
				stringBuilder3.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(17, 1, stringBuilder2);
				handler.AppendLiteral("* Intended Path: ");
				handler.AppendFormatted(item.IntendedPath);
				stringBuilder4.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder5 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(17, 1, stringBuilder2);
				handler.AppendLiteral("* Description: \"");
				handler.AppendFormatted(item.Description);
				handler.AppendLiteral("\"");
				stringBuilder5.AppendLine(ref handler);
			}
			return new CmdResult(success: true, stringBuilder.ToString());
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				List<string> candidates = _types.ToList();
				return CompleteArgument(candidates, System.Array.Empty<string>(), args.FirstOrDefault() ?? "");
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
