	public class BlockConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "block";

		public override string Args => "<int:amount> <target-index:int>";

		public override string Description => "Gives block to player, or to target creature if index is given (0 is player).";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (issuingPlayer == null)
			{
				return new CmdResult(success: false, "This command only works during a run.");
			}
			if (!CombatManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "This doesn't appear to be a combat!");
			}
			int num = args.Length;
			if ((num < 1 || num > 2) ? true : false)
			{
				return new CmdResult(success: false, "There must be 1 or 2 args.");
			}
			if (!int.TryParse(args[0], out var result))
			{
				return new CmdResult(success: false, "Arg 1 must be the amount of block.");
			}
			if (result < 0)
			{
				return new CmdResult(success: false, "Removing block is not supported.");
			}
			Creature creature = issuingPlayer.Creature;
			Creature creature2;
			if (args.Length == 1)
			{
				creature2 = creature;
			}
			else
			{
				if (!int.TryParse(args[1], out var result2))
				{
					return new CmdResult(success: false, "Arg 2 must be the target index if specified.");
				}
				IReadOnlyList<Creature> creatures = creature.CombatState.Creatures;
				if (result2 < 0 || result2 >= creatures.Count)
				{
					return new CmdResult(success: false, $"Invalid target index {result2}. Valid range: 0-{creatures.Count - 1}");
				}
				creature2 = creatures[result2];
			}
			Task task = GainBlock(creature2, result);
			return new CmdResult(task, success: true, $"Added '{result}' block to {creature2}.");
		}

		private static async Task GainBlock(Creature target, int amount)
		{
			await CreatureCmd.GainBlock(target, new BlockVar(amount, ValueProp.Unpowered), null);
		}
	}
	public class CardConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "card";

		public override string Args => "<card-id:string> [pileName:string]";

		public override string Description => "Spawns a card into a pile (hand by default). Screaming snake case ('BODY_SLAM', not 'Body Slam').";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length == 0)
			{
				return new CmdResult(success: false, "No card name specified.");
			}
			if (!RunManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "A run is currently not in progress!");
			}
			PileType result = PileType.Hand;
			if (args.Length >= 2 && !AbstractConsoleCmd.TryParseEnum<PileType>(args[1], out result))
			{
				return new CmdResult(success: false, "Unknown pile '" + args[1] + "'. Valid piles: " + string.Join(", ", Enum.GetNames<PileType>()));
			}
			if (result == PileType.Hand)
			{
				CardPile pile = PileType.Hand.GetPile(issuingPlayer);
				int count = pile.Cards.Count;
				if (count >= CardPile.MaxCardsInHand)
				{
					return new CmdResult(success: false, $"The hand is full ({count}/{CardPile.MaxCardsInHand}).");
				}
			}
			string cardName = args[0].ToUpperInvariant();
			CardModel cardModel = ModelDb.AllCards.FirstOrDefault((CardModel c) => c.Id.Entry == cardName);
			if (cardModel == null)
			{
				return new CmdResult(success: false, "Card '" + cardName + "' not found");
			}
			ICardScope cardScope2;
			if (!result.IsCombatPile())
			{
				ICardScope cardScope = RunManager.Instance.DebugOnlyGetState();
				cardScope2 = cardScope;
			}
			else
			{
				ICardScope cardScope = CombatManager.Instance.DebugOnlyGetState();
				cardScope2 = cardScope;
			}
			ICardScope cardScope3 = cardScope2;
			CardModel card = cardScope3.CreateCard(cardModel, issuingPlayer);
			Task task = CardPileCmd.Add(card, result);
			return new CmdResult(task, success: true, $"Added card '{cardModel.Id.Entry}' to '{result}'");
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				List<string> candidates = ModelDb.AllCards.Select((CardModel card) => card.Id.Entry).ToList();
				return CompleteArgument(candidates, System.Array.Empty<string>(), args.FirstOrDefault() ?? "");
			}
			if (args.Length == 2)
			{
				List<string> candidates2 = Enum.GetNames<PileType>().ToList();
				return CompleteArgument(candidates2, new string[1] { args[0] }, args[1]);
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
	public class CloudConsoleCmd : AbstractConsoleCmd
	{
		private static bool _confirmed;

		public override string CmdName => "cloud";

		public override string Args => "delete";

		public override string Description => "Deletes all save files from Steam Cloud, if you are running on Steam";

		public override bool IsNetworked => false;

		public override bool DebugOnly => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length < 1 || args[0] != "delete")
			{
				return new CmdResult(success: false, "No argument specified.\n" + Args);
			}
			if (!_confirmed)
			{
				_confirmed = true;
				return new CmdResult(success: false, "Run this command again to confirm you want to delete all your Steam cloud saves. The game will quit.");
			}
			DeleteCloudSaves();
			return new CmdResult(success: true, "Steam cloud saves deleted.");
		}

		public static void DeleteCloudSaves()
		{
			if (!SteamInitializer.Initialized)
			{
				throw new InvalidOperationException("Steam not initialized");
			}
			int fileCount = SteamRemoteStorage.GetFileCount();
			for (int num = fileCount - 1; num >= 0; num--)
			{
				string fileNameAndSize = SteamRemoteStorage.GetFileNameAndSize(num, out var pnFileSizeInBytes);
				Log.Info($"Deleting {fileNameAndSize} from Steam cloud ({pnFileSizeInBytes} bytes)");
				SteamRemoteStorage.FileDelete(fileNameAndSize);
			}
			((SceneTree)Engine.GetMainLoop()).Quit();
		}
	}
