	public class KillConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "kill";

		public override string Args => "<target-index:int>|'all'";

		public override string Description => "Will kill one target if the index is given, or all if 'all', or the first if no arguments.";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (!CombatManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "This doesn't appear to be a combat!");
			}
			List<Creature> list = new List<Creature>();
			IReadOnlyList<Creature> readOnlyList = CombatManager.Instance.DebugOnlyGetState().Enemies.ToList();
			if (args.Length == 0)
			{
				list.Add(readOnlyList[0]);
			}
			else if (args[0].Equals("all"))
			{
				foreach (Creature item in readOnlyList)
				{
					list.Add(item);
				}
			}
			else
			{
				if (!int.TryParse(args[0], out var result))
				{
					return new CmdResult(success: false, "Invalid argument '" + args[0] + "'. Use a target index or 'all'.");
				}
				if (result < 0 || result >= readOnlyList.Count)
				{
					return new CmdResult(success: false, $"Invalid target index {result}. Valid range: 0-{readOnlyList.Count - 1}");
				}
				list.Add(readOnlyList[result]);
			}
			IEnumerable<string> values = from c in list
				select c.Monster into m
				where m != null
				select m.Id.Entry.ToString();
			TaskHelper.RunSafely(DoKill(list));
			return new CmdResult(success: true, "Killed: [" + string.Join(",", values) + "]");
		}

		private async Task DoKill(List<Creature> toKill)
		{
			foreach (Creature item in toKill)
			{
				await CreatureCmd.Kill(item);
			}
			await CombatManager.Instance.CheckWinCondition();
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				int num = 1;
				List<string> list = new List<string>(num);
				CollectionsMarshal.SetCount(list, num);
				Span<string> span = CollectionsMarshal.AsSpan(list);
				int index = 0;
				span[index] = "all";
				List<string> list2 = list;
				if (CombatManager.Instance.IsInProgress)
				{
					IReadOnlyList<Creature> readOnlyList = CombatManager.Instance.DebugOnlyGetState()?.Enemies;
					if (readOnlyList != null)
					{
						for (int i = 0; i < readOnlyList.Count; i++)
						{
							list2.Add(i.ToString());
						}
					}
				}
				return CompleteArgument(list2, System.Array.Empty<string>(), args.FirstOrDefault() ?? "");
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}
	}
	public class LeaderboardConsoleCmd : AbstractConsoleCmd
	{
		private static readonly List<string> _validOptions;

		public override string CmdName => "leaderboard";

		public override string Args => "[option:string] [name:string] <score:int> [count:int]";

		public override string Description => "Adds scores to the leaderboard. Option can be upload|random. If random, <count> random scores will be uploaded to leaderboard <name>. If upload, one score will be uploaded to leaderboard <name> with <score>.";

		public override bool IsNetworked => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length == 0)
			{
				return new CmdResult(success: false, "Option must be specified (random or upload).");
			}
			string text = args[0];
			string text2 = DailyRunUtility.GetLeaderboardName(DateTimeOffset.Now, 1);
			if (args.Length > 1 && args[1] != "-")
			{
				text2 = args[1];
			}
			if (text == "random")
			{
				int result = 100;
				if (args.Length >= 3 && !int.TryParse(args[2], out result))
				{
					return new CmdResult(success: false, "Count must be a valid integer.");
				}
				TaskHelper.RunSafely(UploadRandomScores(text2, result));
				return new CmdResult(success: true, $"Adding {result} entries to leaderboard {text2}");
			}
			if (text == "upload")
			{
				if (args.Length < 3)
				{
					return new CmdResult(success: false, "Score must be specified when upload is the option.\nUse - as the leaderboard name for the default.");
				}
				if (!int.TryParse(args[2], out var result2))
				{
					return new CmdResult(success: false, "Score must be a valid integer.");
				}
				TaskHelper.RunSafely(UploadScore(text2, result2));
				return new CmdResult(success: true, $"Uploading score {result2} to leaderboard {text2}");
			}
			return new CmdResult(success: false, "Invalid option " + text + ", must be upload or random");
		}

		private async Task UploadRandomScores(string leaderboardName, int count)
		{
			ILeaderboardHandle handle = await LeaderboardManager.GetOrCreateLeaderboard(leaderboardName);
			Rng rng = new Rng(Rng.Chaotic.NextUnsignedLong());
			for (int i = 0; i < count; i++)
			{
				LeaderboardManager.DebugAddEntry(handle, new LeaderboardEntry
				{
					id = rng.NextUnsignedInt(),
					name = rng.NextUnsignedInt().ToString(),
					score = rng.NextInt()
				});
			}
		}

		private async Task UploadScore(string leaderboardName, int score)
		{
			await LeaderboardManager.UploadLocalScore(await LeaderboardManager.GetOrCreateLeaderboard(leaderboardName), score, System.Array.Empty<ulong>());
		}

		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				string partial = ((args.Length != 0) ? args[0] : "");
				List<string> candidates = ((!string.IsNullOrWhiteSpace(partial)) ? _validOptions.Where((string option) => option.Contains(partial, StringComparison.OrdinalIgnoreCase)).ToList() : _validOptions);
				return new CompletionResult
				{
					Candidates = candidates,
					Type = CompletionType.Argument,
					ArgumentContext = CmdName
				};
			}
			return new CompletionResult
			{
				Type = CompletionType.Argument,
				ArgumentContext = CmdName
			};
		}

		static LeaderboardConsoleCmd()
		{
			int num = 2;
			List<string> list = new List<string>(num);
			CollectionsMarshal.SetCount(list, num);
			Span<string> span = CollectionsMarshal.AsSpan(list);
			int num2 = 0;
			span[num2] = "upload";
			num2++;
			span[num2] = "random";
			_validOptions = list;
		}
	}
	public class LogConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "log";

		public override string Args => "[type:string] <level:string>";

		public override string Description => "Set log level for specific log types. Type can be: " + string.Join(",", Enum.GetNames<LogType>()) + ". Levels can be: " + string.Join(",", Enum.GetNames<LogLevel>());

		public override bool IsNetworked => false;

		public override bool DebugOnly => false;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length == 0)
			{
				return new CmdResult(success: false, "At least one arg must be supplied!");
			}
			LogType? enumVal2;
			if (TryParseEnumCaseInsensitive(args[0], out LogLevel? enumVal))
			{
				enumVal2 = LogType.Generic;
			}
			else
			{
				if (!TryParseEnumCaseInsensitive(args[0], out enumVal2))
				{
					return new CmdResult(success: false, "First argument '" + args[0] + "' could not be parsed as either a log level or type!");
				}
				if (args.Length <= 1)
				{
					return new CmdResult(success: false, "Must supply a log level as the second argument!");
				}
				if (!TryParseEnumCaseInsensitive(args[1], out enumVal))
				{
					return new CmdResult(success: false, "Second argument '" + args[1] + "' could not be parsed as a log level!");
				}
			}
			MegaCrit.Sts2.Core.Logging.Logger.logLevelTypeMap[enumVal2.Value] = enumVal.Value;
			return new CmdResult(success: true, $"Logging level for {enumVal2} set to {enumVal}");
		}

		public static bool TryParseEnumCaseInsensitive<T>(string str, out T? enumVal) where T : struct, Enum
		{
			T[] values = Enum.GetValues<T>();
			for (int i = 0; i < values.Length; i++)
			{
				T value = values[i];
				if (str.Equals(value.ToString(), StringComparison.OrdinalIgnoreCase))
				{
					enumVal = value;
					return true;
				}
			}
			enumVal = null;
			return false;
		}
	}
