				Span<string> span = CollectionsMarshal.AsSpan(list);
				int num2 = 0;
				span[num2] = "add";
				num2++;
				span[num2] = "remove";
				completionResult.Candidates = list;
				completionResult.Type = CompletionType.Subcommand;
				completionResult.ArgumentContext = CmdName;
				return completionResult;
			}
			if (args.Length == 1)
			{
				List<string> list2 = new List<string>();
				string text = args[0].ToLowerInvariant();
				if ("add".StartsWith(text))
				{
					list2.Add("add");
				}
				if ("remove".StartsWith(text))
				{
					list2.Add("remove");
				}
				if (list2.Count > 0)
				{
					return CompleteArgument(list2, System.Array.Empty<string>(), text, CompletionType.Subcommand);
				}
				List<string> candidates = ModelDb.AllRelics.Select((RelicModel r) => r.Id.Entry).ToList();
				return CompleteArgument(candidates, System.Array.Empty<string>(), args[0], CompletionType.Argument, (string candidate, string partialArg) => candidate.Contains(partialArg, StringComparison.OrdinalIgnoreCase));
			}
			if (args.Length == 2)
