	public static class OrbCmd
	{
		/// <summary>
		/// Add orb slots to a creature.
		/// </summary>
		/// <param name="player">Player to add orb slots to.</param>
		/// <param name="amount">Number of orb slots to add.</param>
		public static Task AddSlots(Player player, int amount)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return Task.CompletedTask;
			}
			amount = Math.Min(10 - player.PlayerCombatState.OrbQueue.Capacity, amount);
			player.PlayerCombatState.OrbQueue.AddCapacity(amount);
			NCombatRoom.Instance?.GetCreatureNode(player.Creature).OrbManager?.AddSlotAnim(amount);
			return Task.CompletedTask;
		}

		/// <summary>
		/// Remove orb slots from the creature. Starts from the back of the list.
		/// Orb slots with orbs already in them are also removed.
		/// </summary>
		/// <param name="player">Player to remove orb slots from.</param>
		/// <param name="amount">Number of orb slots to remove.</param>
		public static void RemoveSlots(Player player, int amount)
		{
			if (!CombatManager.Instance.IsOverOrEnding)
			{
				amount = Math.Min(player.PlayerCombatState.OrbQueue.Capacity, amount);
				player.PlayerCombatState.OrbQueue.RemoveCapacity(amount);
				NCombatRoom.Instance?.GetCreatureNode(player.Creature).OrbManager?.RemoveSlotAnim(amount);
			}
		}

		/// <summary>
		/// Channel an orb of the specified type.
		/// </summary>
		/// <param name="choiceContext">The context with which to handle player choices.</param>
		/// <param name="player">Player who is channeling the orb.</param>
		/// <typeparam name="T">Type of orb to channel.</typeparam>
		public static async Task Channel<T>(PlayerChoiceContext choiceContext, Player player) where T : OrbModel
		{
			await Channel(choiceContext, ModelDb.Orb<T>().ToMutable(), player);
		}

		/// <summary>
		/// Channel an orb.
		/// </summary>
		/// <param name="choiceContext">The context with which to handle player choices.</param>
		/// <param name="orb">Orb to channel.</param>
		/// <param name="player">Player who is channeling the orb.</param>
		public static async Task Channel(PlayerChoiceContext choiceContext, OrbModel orb, Player player)
		{
			if (!CombatManager.Instance.IsOverOrEnding)
			{
				ICombatState combatState = player.Creature.CombatState;
				OrbQueue orbQueue = player.PlayerCombatState.OrbQueue;
				if (player.Character.BaseOrbSlotCount == 0 && orbQueue.Capacity == 0)
				{
					await AddSlots(player, 1);
				}
				orb.AssertMutable();
				orb.Owner = player;
				if (orbQueue.Orbs.Count >= orbQueue.Capacity)
				{
					await EvokeNext(choiceContext, player);
				}
				if (await player.PlayerCombatState.OrbQueue.TryEnqueue(orb))
				{
					CombatManager.Instance.History.OrbChanneled(combatState, orb);
					orb.PlayChannelSfx();
					NCombatRoom.Instance?.GetCreatureNode(player.Creature)?.OrbManager?.AddOrbAnim();
					await Hook.AfterOrbChanneled(combatState, choiceContext, player, orb);
				}
			}
		}

		public static async Task EvokeNext(PlayerChoiceContext choiceContext, Player player, bool dequeue = true)
		{
			OrbQueue orbQueue = player.PlayerCombatState.OrbQueue;
			if (orbQueue.Orbs.Count > 0)
			{
				OrbModel orb = orbQueue.Orbs.First();
				choiceContext.PushModel(orb);
				await Evoke(choiceContext, player, orb, dequeue);
				choiceContext.PopModel(orb);
			}
		}

		public static async Task EvokeLast(PlayerChoiceContext choiceContext, Player player, bool dequeue = true)
		{
			OrbQueue orbQueue = player.PlayerCombatState.OrbQueue;
			if (orbQueue.Orbs.Count > 0)
			{
				OrbModel orb = orbQueue.Orbs.Last();
				choiceContext.PushModel(orb);
				await Evoke(choiceContext, player, orb, dequeue);
				choiceContext.PopModel(orb);
			}
		}

		/// <summary>
		/// Evoke the orb.
		/// </summary>
		/// <param name="choiceContext">The context with which to handle player choices.</param>
		/// <param name="player">Player whose next orb we're evoking.</param>
		/// <param name="evokedOrb">orb being evoked.</param>
		/// <param name="dequeue">Whether or not to dequeue the orb from the creature's orb queue after evoking (usually true).</param>
		private static async Task Evoke(PlayerChoiceContext choiceContext, Player player, OrbModel evokedOrb, bool dequeue = true)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return;
			}
			OrbQueue orbQueue = player.PlayerCombatState.OrbQueue;
			if (orbQueue.Orbs.Count <= 0)
			{
				return;
			}
			bool removed = false;
			if (dequeue)
			{
				removed = orbQueue.Remove(evokedOrb);
				NCombatRoom.Instance?.GetCreatureNode(player.Creature)?.OrbManager?.EvokeOrbAnim(evokedOrb);
			}
			choiceContext.PushModel(evokedOrb);
			IEnumerable<Creature> targets = await evokedOrb.Evoke(choiceContext);
			choiceContext.PopModel(evokedOrb);
			if (player.Creature.CombatState != null)
			{
				await Hook.AfterOrbEvoked(choiceContext, player.Creature.CombatState, evokedOrb, targets);
				if (removed)
				{
					evokedOrb.RemoveInternal();
				}
			}
		}

		public static async Task Passive(PlayerChoiceContext choiceContext, OrbModel orb, Creature? target, bool countAffectedByHooks = false)
		{
			if (!CombatManager.Instance.IsOverOrEnding)
			{
				choiceContext.PushModel(orb);
				if (!countAffectedByHooks)
				{
					await orb.Passive(choiceContext, target);
				}
				else
				{
					await orb.TriggerPassive(choiceContext, target);
				}
				choiceContext.PopModel(orb);
			}
		}
	}
	public static class OstyCmd
	{
		/// <summary>
		/// Summon Osty with the specified number of HP. If the specified creature already owns an instance of Osty, raise
		/// Osty's max HP by the specified number instead.
		/// </summary>
		/// <param name="choiceContext">The context with which to handle player choices.</param>
		/// <param name="summoner">The player who is summoning.</param>
		/// <param name="amount">
		/// The number of HP that Osty should be summoned with (or that should be added to the existing Osty instance).
		/// </param>
		/// <param name="source">
		/// The model that this Summon came from. For example, <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Bodyguard" /> and <see cref="T:MegaCrit.Sts2.Core.Models.Relics.BoundPhylactery" />
		/// pass themselves here.
		/// Null if the Summon did not come from any model (generally only relevant in tests).
		/// </param>
		/// <returns>The result of the summon.</returns>
		public static async Task<SummonResult> Summon(PlayerChoiceContext choiceContext, Player summoner, decimal amount, AbstractModel? source)
		{
			ICombatState combatState = summoner.Creature.CombatState;
			amount = Hook.ModifySummonAmount(combatState, summoner, amount, source);
			if (amount == 0m)
			{
				return new SummonResult(summoner.Osty, 0m);
			}
			if (CombatManager.Instance.IsInProgress)
			{
				SfxCmd.Play("event:/sfx/characters/necrobinder/necrobinder_summon");
			}
			Creature osty = combatState.Allies.FirstOrDefault((Creature c) => c.Monster is Osty && c.PetOwner == summoner);
			if (summoner.IsOstyAlive)
			{
				await CreatureCmd.GainMaxHp(summoner.Osty, amount);
			}
			else
			{
				bool isReviving = osty != null;
				if (isReviving)
				{
					if (osty.IsAlive)
					{
						throw new InvalidOperationException("We shouldn't make it here if Osty is still alive!");
					}
					summoner.PlayerCombatState.AddPetInternal(osty);
				}
				else
				{
					osty = await PlayerCmd.AddPet<Osty>(summoner);
					NCreature ostyNode = NCombatRoom.Instance?.GetCreatureNode(osty);
					if (ostyNode != null && source is CardModel)
					{
						ostyNode.Modulate = Colors.Transparent;
						Tween tween = ostyNode.CreateTween();
						tween.TweenProperty(ostyNode, "modulate", Colors.White, 0.3499999940395355).SetDelay(0.10000000149011612);
						ostyNode.StartReviveAnim();
					}
					await PowerCmd.Apply<DieForYouPower>(choiceContext, osty, 1m, null, null);
					ostyNode?.TrackBlockStatus(summoner.Creature);
				}
				await CreatureCmd.SetMaxHp(osty, amount);
				await CreatureCmd.Heal(osty, amount, isReviving);
				if (isReviving)
				{
					await Hook.AfterOstyRevived(combatState, osty);
				}
			}
			if (osty != null)
			{
				NCombatRoom.Instance?.GetCreatureNode(osty)?.OstyScaleToSize(osty.MaxHp, 0.75);
			}
			CombatManager.Instance.History.Summoned(combatState, (int)amount, summoner);
			await Hook.AfterSummon(combatState, choiceContext, summoner, amount);
			return new SummonResult(summoner.Osty, amount);
		}
	}
	public static class PlayerCmd
	{
		public const string goldSmallSfx = "event:/sfx/ui/gold/gold_1";

		public const string goldMediumSfx = "event:/sfx/ui/gold/gold_2";

		public const string goldLargeSfx = "event:/sfx/ui/gold/gold_3";

		/// <summary>
		/// Increase the current amount of energy that the player has.
		/// </summary>
		/// <param name="amount">Amount of energy to give.</param>
		/// <param name="player">Player to give the energy to.</param>
		public static async Task GainEnergy(decimal amount, Player player)
		{
			if (!(amount <= 0m) && !CombatManager.Instance.IsEnding)
			{
				ICombatState combatState = player.Creature.CombatState;
				decimal finalAmount = Hook.ModifyEnergyGain(combatState, player, amount, out IEnumerable<AbstractModel> modifiers);
				await Hook.AfterModifyingEnergyGain(combatState, modifiers);
				if (finalAmount > 0m)
				{
					SfxCmd.Play("event:/sfx/ui/gain_energy");
					player.PlayerCombatState.GainEnergy(finalAmount);
				}
			}
		}

		/// <summary>
		/// Decrease the current amount of energy that the player has.
		/// </summary>
		/// <param name="amount">Amount of energy to remove.</param>
		/// <param name="player">Player to remove the energy from.</param>
		public static Task LoseEnergy(decimal amount, Player player)
		{
			if (amount <= 0m)
			{
				return Task.CompletedTask;
			}
			if (CombatManager.Instance.IsEnding)
			{
				return Task.CompletedTask;
			}
			player.PlayerCombatState.LoseEnergy(amount);
			return Task.CompletedTask;
		}

		/// <summary>
		/// Set the player to have a specific amount of energy.
		/// </summary>
		/// <param name="amount">New amount of energy.</param>
		/// <param name="player">Player whose energy we're setting.</param>
		public static async Task SetEnergy(decimal amount, Player player)
		{
			if (!CombatManager.Instance.IsEnding)
			{
				int energy = player.PlayerCombatState.Energy;
				if ((decimal)energy < amount)
				{
					await GainEnergy(amount - (decimal)energy, player);
				}
				else if ((decimal)energy > amount)
				{
					await LoseEnergy((decimal)energy - amount, player);
				}
			}
		}

		/// <summary>
		/// Increase the current amount of stars that the player has.
		/// </summary>
		/// <param name="amount">Amount of stars to give.</param>
		/// <param name="player">Player to give the stars to.</param>
		public static async Task GainStars(decimal amount, Player player)
		{
			if (!CombatManager.Instance.IsEnding && Hook.ShouldGainStars(player.Creature.CombatState, amount, player))
			{
				player.PlayerCombatState.GainStars(amount);
				await Hook.AfterStarsGained(player.Creature.CombatState, (int)amount, player);
			}
		}

		/// <summary>
		/// Decrease the current amount of stars that the player has.
		/// </summary>
		/// <param name="amount">Amount of stars to remove.</param>
		/// <param name="player">Player to remove the stars from.</param>
		public static Task LoseStars(decimal amount, Player player)
		{
			if (CombatManager.Instance.IsEnding)
			{
				return Task.CompletedTask;
			}
			player.PlayerCombatState.LoseStars(amount);
			return Task.CompletedTask;
		}

		/// <summary>
		/// Set the player to have a specific amount of stars.
		/// </summary>
		/// <param name="amount">New amount of stars.</param>
		/// <param name="player">Player whose stars we're setting.</param>
		public static async Task SetStars(decimal amount, Player player)
		{
			if (!CombatManager.Instance.IsEnding)
			{
				int stars = player.PlayerCombatState.Stars;
				if ((decimal)stars < amount)
				{
					await GainStars(amount - (decimal)stars, player);
				}
				else if ((decimal)stars > amount)
				{
					await LoseStars((decimal)stars - amount, player);
				}
			}
		}

		/// <summary>
		/// Increase the current amount of gold that the player has.
		/// </summary>
		/// <param name="amount">Amount of gold to give.</param>
		/// <param name="player">Player to give the gold to.</param>
		/// <param name="wasStolenBack">Was the gold stolen back from an enemy.</param>
		public static async Task GainGold(decimal amount, Player player, bool wasStolenBack = false)
		{
			IRunState runState = player.RunState;
			amount = Hook.ModifyGoldGained(runState, player.Creature.CombatState, amount, player, out IEnumerable<AbstractModel> modifiers);
			await Hook.AfterModifyingGoldGained(runState, player.Creature.CombatState, modifiers, player, amount);
			if (!(amount > 0m))
			{
				return;
			}
			if (player == LocalContext.GetMe(runState))
			{
				string text = ((amount >= 100m) ? "event:/sfx/ui/gold/gold_3" : ((!(amount > 30m)) ? "event:/sfx/ui/gold/gold_1" : "event:/sfx/ui/gold/gold_2"));
				string sfx = text;
				SfxCmd.Play(sfx);
			}
			PlayerMapPointHistoryEntry playerMapPointHistoryEntry = runState.CurrentMapPointHistoryEntry?.GetEntry(player.NetId);
			if (playerMapPointHistoryEntry != null)
			{
				if (wasStolenBack)
				{
					playerMapPointHistoryEntry.GoldStolen -= (int)amount;
				}
				else
				{
					playerMapPointHistoryEntry.GoldGained += (int)amount;
				}
			}
			player.Gold += (int)amount;
			await Hook.AfterGoldGained(runState, player);
		}

		/// <summary>
		/// Decrease the current amount of gold that the player has.
		/// </summary>
		/// <param name="amount">Amount of gold to lose.</param>
		/// <param name="player">Player to take the gold from.</param>
		/// <param name="goldLossType">How the player lost the gold</param>
		public static Task LoseGold(decimal amount, Player player, GoldLossType goldLossType = GoldLossType.Lost)
		{
			SfxCmd.Play("event:/sfx/ui/gold/gold_1");
			PlayerMapPointHistoryEntry playerMapPointHistoryEntry = player.RunState.CurrentMapPointHistoryEntry?.GetEntry(player.NetId);
			if (playerMapPointHistoryEntry != null)
			{
				switch (goldLossType)
				{
				case GoldLossType.Spent:
					playerMapPointHistoryEntry.GoldSpent += (int)amount;
					break;
				case GoldLossType.Lost:
					playerMapPointHistoryEntry.GoldLost += (int)amount;
					break;
				case GoldLossType.Stolen:
					playerMapPointHistoryEntry.GoldStolen += (int)amount;
					playerMapPointHistoryEntry.MarkLootStolen((int)amount);
					break;
				}
			}
			player.Gold = int.Max(0, player.Gold - (int)amount);
			return Task.CompletedTask;
		}

		/// <summary>
		/// Set the player to have a specific amount of gold.
		/// </summary>
		/// <param name="amount">New amount of gold.</param>
		/// <param name="player">Player whose gold we're setting.</param>
		public static async Task SetGold(decimal amount, Player player)
		{
			int gold = player.Gold;
			if ((decimal)gold < amount)
			{
				await GainGold(amount - (decimal)gold, player);
			}
			else if ((decimal)gold > amount)
			{
				await LoseGold((decimal)gold - amount, player);
			}
		}

		public static Task GainMaxPotionCount(int amount, Player player)
		{
			player.AddToMaxPotionCount(amount);
			return Task.CompletedTask;
		}

		public static Task LoseMaxPotionCount(int amount, Player player)
		{
			player.SubtractFromMaxPotionCount(amount);
			return Task.CompletedTask;
		}

		/// <summary>
		/// Give the player a new pet (aww).
		/// </summary>
		/// <param name="player">Player to give the pet to.</param>
		/// <typeparam name="T">Type of pet to give them.</typeparam>
		public static async Task<Creature> AddPet<T>(Player player) where T : MonsterModel
		{
			Creature pet = player.Creature.CombatState.CreateCreature((T)ModelDb.Monster<T>().ToMutable(), player.Creature.Side, null);
			await AddPet(pet, player);
			return pet;
		}

		/// <summary>
		/// Give the player a new pet (aww).
		/// </summary>
		/// <param name="pet">Pet creature to give to the player.</param>
		/// <param name="player">Player to give the pet to.</param>
		public static async Task AddPet(Creature pet, Player player)
		{
			if (pet.CombatState == null)
			{
				throw new InvalidOperationException("Pet must already be added to a combat state.");
			}
			player.PlayerCombatState.AddPetInternal(pet);
			await CreatureCmd.Add(pet);
		}

		/// <summary>
		/// Heal the player as if they were resting at a rest site.
		/// </summary>
		/// <param name="player">Player to heal.</param>
		/// <param name="playSfx">If true, we'll play the default rest site SFX.</param>
		public static async Task MimicRestSiteHeal(Player player, bool playSfx = true)
		{
			if (playSfx)
			{
				HealRestSiteOption.PlayRestSiteHealSfx();
			}
			await HealRestSiteOption.ExecuteRestSiteHeal(player, isMimicked: true);
		}

		/// <summary>
		/// Ends the turn for a given player.
		/// </summary>
		/// <param name="player">Player who is ending their turn</param>
		/// <param name="canBackOut">If the player is allowed to un-end their turn, particularly in multiplayer.</param>
		/// <param name="actionDuringEnemyTurn">Optional action to execute during the enemy turn. This is useful for tests.</param>
		public static void EndTurn(Player player, bool canBackOut, Func<Task>? actionDuringEnemyTurn = null)
		{
			if (!CombatManager.Instance.IsPlayerReadyToEndTurn(player))
			{
				if (LocalContext.IsMe(player))
				{
					CombatManager.Instance.OnEndedTurnLocally();
				}
				CombatManager.Instance.SetReadyToEndTurn(player, canBackOut, actionDuringEnemyTurn);
			}
		}

		public static void CompleteQuest(CardModel questCard)
		{
			questCard.Owner.RunState.CurrentMapPointHistoryEntry?.GetEntry(questCard.Owner.NetId).CompletedQuests.Add(questCard.Id);
		}
	}
	public static class PotionCmd
	{
		public static async Task<PotionProcureResult> TryToProcure<T>(Player player) where T : PotionModel
		{
			return await TryToProcure(ModelDb.Potion<T>().ToMutable(), player);
		}

		/// <summary>
		/// We try to Procure the potion. Can fail if the potions bar is full.
		/// </summary>
		/// <param name="potion">Potion to be added</param>
		/// <param name="player">Player who is getting the potion</param>
		/// <param name="slotIndex">Slot at which to add the potion. If -1, the potion will be added in the first available slot.</param>
		/// <returns>Potion if it is added successfully. Returns null if it failed.</returns>
		public static async Task<PotionProcureResult> TryToProcure(PotionModel potion, Player player, int slotIndex = -1)
		{
			potion.AssertMutable();
			if (!Hook.ShouldProcurePotion(player.RunState, player.Creature.CombatState, potion, player))
			{
				return new PotionProcureResult
				{
					potion = potion,
					success = false,
					failureReason = PotionProcureFailureReason.NotAllowed
				};
			}
			PotionProcureResult result = player.AddPotionInternal(potion, slotIndex);
			if (result.success)
			{
				player.RunState.CurrentMapPointHistoryEntry?.GetEntry(player.NetId).PotionChoices.Add(new ModelChoiceHistoryEntry(potion.Id, wasPicked: true));
				NDebugAudioManager.Instance?.Play("gain_potion.mp3", 1f, PitchVariance.Small);
				NRun.Instance?.GlobalUi.TopBar.PotionContainer.AnimatePotion(potion);
				await Hook.AfterPotionProcured(player.RunState, player.Creature.CombatState, potion);
				if (LocalContext.IsMe(player))
				{
					SaveManager.Instance.MarkPotionAsSeen(potion);
				}
			}
			return result;
		}

		public static async Task Discard(PotionModel potion)
		{
			potion.Owner.RunState.CurrentMapPointHistoryEntry?.GetEntry(potion.Owner.NetId).PotionDiscarded.Add(potion.Id);
			potion.Discard();
			await Hook.AfterPotionDiscarded(potion.Owner.RunState, potion.Owner.Creature.CombatState, potion);
		}
	}
	public static class PowerCmd
	{
		/// <summary>
		/// Apply a power to multiple creatures.
		/// </summary>
		/// <param name="choiceContext">The context that is signalled in the event of a player choice.</param>
		/// <param name="targets">Creatures to apply the power to.</param>
		/// <param name="amount">Amount of the power to apply.</param>
		/// <param name="applier">Creature applying the power.</param>
		/// <param name="cardSource">Optional card that is applying the power.</param>
		/// <param name="silent">Pass true if no flashes should play for this power application.</param>
		/// <typeparam name="T">Type of power to apply.</typeparam>
		/// <returns>
		/// The power that was applied.
		/// Can be null if:
		/// * Combat is over.
		/// * Something blocked application (like Artifact).
		/// * The power's amount was changed to 0 (like if you had 3 Strength and applied -3 Strength).
		/// </returns>
		public static async Task<IReadOnlyList<T>> Apply<T>(PlayerChoiceContext choiceContext, IEnumerable<Creature>? targets, decimal amount, Creature? applier, CardModel? cardSource, bool silent = false) where T : PowerModel
		{
			List<T> powers = new List<T>();
			if (targets == null)
			{
				return powers;
			}
			foreach (Creature target in targets)
			{
				T val = await Apply<T>(choiceContext, target, amount, applier, cardSource, silent);
				if (val != null)
				{
					powers.Add(val);
				}
			}
			return powers;
		}

		/// <summary>
		/// Apply a power to a creature.
		/// </summary>
		/// <param name="choiceContext">The context that is signalled in the event of a player choice.</param>
		/// <param name="target">Creature to apply the power to.</param>
		/// <param name="amount">Amount of the power to apply.</param>
		/// <param name="applier">Creature applying the power.</param>
		/// <param name="cardSource">Optional card that is applying the power.</param>
		/// <param name="silent">Pass true if no flashes should play for this power application.</param>
		/// <typeparam name="T">Type of power to apply.</typeparam>
		/// <returns>
		/// The power that was applied.
		/// Can be null if:
		/// * Combat is over.
		/// * Something blocked application (like Artifact).
		/// * The power's amount was changed to 0 (like if you had 3 Strength and applied -3 Strength).
		/// </returns>
		public static async Task<T?> Apply<T>(PlayerChoiceContext choiceContext, Creature target, decimal amount, Creature? applier, CardModel? cardSource, bool silent = false) where T : PowerModel
		{
			if (CombatManager.Instance.IsEnding)
			{
				return null;
			}
			if (!target.CanReceivePowers)
			{
				return null;
			}
			PowerModel powerModel = ModelDb.Power<T>();
			PowerModel power = FindExistingInstanceForStacking(powerModel, target, applier);
			if (power == null)
			{
				power = powerModel.ToMutable();
				await Apply(choiceContext, power, target, amount, applier, cardSource, silent);
			}
			else if (await ModifyAmount(choiceContext, power, amount, applier, cardSource, silent) == 0)
			{
				power = null;
			}
			return power as T;
		}

		/// <summary>
		/// Apply a power to a creature.
		/// </summary>
		/// <param name="choiceContext">The context that is signalled in the event of a player choice.</param>
		/// <param name="power">Power to apply.</param>
		/// <param name="target">Creature to apply the power to.</param>
		/// <param name="amount">Amount of the power to apply.</param>
		/// <param name="applier">Creature applying the power.</param>
		/// <param name="cardSource">Optional card that is applying the power.</param>
		/// <param name="silent">Pass true if no flashes should play for this power application.</param>
		public static async Task Apply(PlayerChoiceContext choiceContext, PowerModel power, Creature target, decimal amount, Creature? applier, CardModel? cardSource, bool silent = false)
		{
			if (CombatManager.Instance.IsEnding || amount == 0m || !target.CanReceivePowers)
			{
				return;
			}
			ICombatState combatState = target.CombatState;
			if (combatState == null)
			{
				return;
			}
			PowerModel powerModel = FindExistingInstanceForStacking(power, target, applier);
			if (powerModel != null)
			{
				await ModifyAmount(choiceContext, powerModel, amount, applier, cardSource);
				return;
			}
			power.AssertMutable();
			power.Applier = applier;
			await Hook.BeforePowerAmountChanged(combatState, power, amount, target, applier, cardSource);
			decimal modifiedAmount = amount;
			IEnumerable<AbstractModel> givenModifiers = null;
			if (applier != null && combatState.ContainsCreature(applier))
			{
				modifiedAmount = Hook.ModifyPowerAmountGiven(combatState, power, applier, modifiedAmount, target, cardSource, out givenModifiers);
			}
			modifiedAmount = Hook.ModifyPowerAmountReceived(combatState, power, target, modifiedAmount, applier, out IEnumerable<AbstractModel> receivedModifiers);
			if (combatState.Players.Count > 1 && (target.IsPrimaryEnemy || target.IsSecondaryEnemy) && power.ShouldScaleInMultiplayer)
			{
				modifiedAmount = power.GetScaledAmountForMultiplayer(combatState, applier, modifiedAmount, target, cardSource);
			}
			await power.BeforeApplied(target, modifiedAmount, applier, cardSource);
			if (target.CanReceivePowers)
			{
				power.ApplyInternal(target, modifiedAmount, silent);
				if (modifiedAmount != 0m)
				{
					CombatManager.Instance.History.PowerReceived(combatState, power, modifiedAmount, applier);
				}
				if (power.IsVisible && CombatManager.Instance.IsInProgress)
				{
					await Cmd.CustomScaledWait(0.1f, 0.25f);
				}
				if (target.Side == CombatSide.Player && power.Type == PowerType.Debuff)
				{
					power.SkipNextDurationTick = true;
				}
				if (givenModifiers != null)
				{
					await Hook.AfterModifyingPowerAmountGiven(combatState, givenModifiers, power);
				}
				await Hook.AfterModifyingPowerAmountReceived(combatState, receivedModifiers, power);
				if (modifiedAmount != 0m)
				{
					await power.AfterApplied(applier, cardSource);
					await Hook.AfterPowerAmountChanged(combatState, choiceContext, power, modifiedAmount, applier, cardSource);
				}
			}
		}

		/// <summary>
		/// Looks for a valid existing instance for a given power within the target
		///  for the sake of adjusting the amount on them.
		/// </summary>
		public static PowerModel? FindExistingInstanceForStacking(PowerModel basePower, Creature target, Creature? applier)
		{
			return basePower.InstanceType switch
			{
				PowerInstanceType.Instanced => null, 
				PowerInstanceType.InstancedPerApplier => target.GetPowerInstances(basePower.Id).FirstOrDefault((PowerModel p) => p.Applier == applier), 
				PowerInstanceType.None => target.GetPower(basePower.Id), 
				_ => throw new ArgumentOutOfRangeException("InstanceType"), 
			};
		}

		/// <summary>
		/// Decrement the amount of a power by 1.
		/// </summary>
		/// <param name="power">Power to decrement.</param>
		public static async Task Decrement(PowerModel power)
		{
			await ModifyAmount(new ThrowingPlayerChoiceContext(), power, -1m, null, null);
		}

		/// <summary>
		/// Tick down the amount of a duration-based power (Vulnerable, Weak, etc.).
		/// Similar to Decrement, but respects some extra rules about turn ordering.
		/// </summary>
		/// <param name="power">Power to tick down.</param>
		public static async Task TickDownDuration(PowerModel power)
		{
			if (power.SkipNextDurationTick)
			{
				power.SkipNextDurationTick = false;
			}
			else
			{
				await Decrement(power);
			}
		}

		/// <summary>
		/// Modify the amount of a power.
		/// </summary>
		/// <param name="choiceContext">The context that is signalled in the event of a player choice.</param>
		/// <param name="power">Power to modify.</param>
		/// <param name="offset">Amount to modify it by (can be positive or negative).</param>
		/// <param name="applier">Creature applying the power.</param>
		/// <param name="cardSource">Optional card that is modifying the power amount.</param>
		/// <param name="silent">Pass true if no flashes should play for this power application.</param>
		/// <returns>
		/// The new amount of the power.
		/// For example, if you have 1 Strength and modify it by 3, this will return 4.
		/// </returns>
		public static async Task<int> ModifyAmount(PlayerChoiceContext choiceContext, PowerModel power, decimal offset, Creature? applier, CardModel? cardSource, bool silent = false)
		{
			if (CombatManager.Instance.IsEnding)
			{
				return 0;
			}
			Creature owner = power.Owner;
			ICombatState combatState = owner.CombatState;
			if (combatState == null)
			{
				return 0;
			}
			await Hook.BeforePowerAmountChanged(combatState, power, offset, owner, applier, cardSource);
			decimal modifiedOffset = offset;
			IEnumerable<AbstractModel> modifiers = null;
			if (applier != null && combatState.ContainsCreature(applier))
			{
				modifiedOffset = Hook.ModifyPowerAmountGiven(combatState, power, applier, modifiedOffset, owner, cardSource, out modifiers);
			}
			modifiedOffset = Hook.ModifyPowerAmountReceived(combatState, power, owner, modifiedOffset, applier, out IEnumerable<AbstractModel> receivedModifiers);
			CombatManager.Instance.History.PowerReceived(combatState, power, modifiedOffset, applier);
			int newAmount = power.Amount + (int)modifiedOffset;
			power.SetAmount(newAmount, silent);
			if (modifiers != null)
			{
				await Hook.AfterModifyingPowerAmountGiven(combatState, modifiers, power);
			}
			await Hook.AfterModifyingPowerAmountReceived(combatState, receivedModifiers, power);
			if ((int)modifiedOffset != 0)
			{
				await Hook.AfterPowerAmountChanged(combatState, choiceContext, power, modifiedOffset, applier, cardSource);
			}
			if (power.ShouldRemoveDueToAmount())
			{
				await Remove(power);
			}
			if (CombatManager.Instance.IsInProgress && owner != null && owner.IsMonster && owner.IsAlive)
			{
				NCreature nCreature = NCombatRoom.Instance?.GetCreatureNode(owner);
				if (nCreature != null)
				{
					try
					{
						await nCreature.UpdateIntent(combatState.Allies);
					}
					catch (ObjectDisposedException ex)
					{
						Log.Error(ex.ToString());
					}
				}
			}
			if (power.IsVisible && CombatManager.Instance.IsInProgress)
			{
				await Cmd.CustomScaledWait(0.1f, 0.25f);
			}
			return newAmount;
		}

		/// <summary>
		/// Remove a power.
		/// </summary>
		/// <param name="creature">Creature to remove the power from.</param>
		/// <typeparam name="T">Type of power to remove.</typeparam>
		public static async Task Remove<T>(Creature creature) where T : PowerModel
		{
			await Remove(creature.GetPower<T>());
		}

		/// <summary>
		/// Remove a power.
		/// </summary>
		/// <param name="power">Power to remove.</param>
		public static async Task Remove(PowerModel? power)
		{
			if (power != null)
			{
				power.RemoveInternal();
				await Cmd.CustomScaledWait(0.2f, 0.4f);
				await power.AfterRemoved(power.Owner);
			}
		}
	}
	public static class RelicCmd
	{
		/// <summary>
		/// Give a relic to the player.
		/// </summary>
		/// <param name="player">Player to give the relic to.</param>
		/// <typeparam name="T">Type of relic to obtain.</typeparam>
		/// <returns>RelicModel</returns>
		public static async Task<T> Obtain<T>(Player player) where T : RelicModel
		{
			return (T)(await Obtain(ModelDb.Relic<T>().ToMutable(), player));
		}

		/// <summary>
		/// Give a relic to the player.
		/// </summary>
		/// <param name="relic">Relic to obtain.</param>
		/// <param name="player">Player to give the relic to.</param>
		/// <param name="index">index in the relic list we want to add our relic to.
		/// Default of -1 means that we append it to the end of the relic list.</param>
		/// <returns>RelicModel</returns>
		public static async Task<RelicModel> Obtain(RelicModel relic, Player player, int index = -1)
		{
			relic.AssertMutable();
			IRunState runState = player.RunState;
			runState.CurrentMapPointHistoryEntry?.GetEntry(player.NetId).RelicChoices.Add(new ModelChoiceHistoryEntry(relic.Id, wasPicked: true));
			player.AddRelicInternal(relic, index);
			if (!relic.IsStackable)
			{
				player.RelicGrabBag.Remove(relic);
				runState.SharedRelicGrabBag.Remove(relic);
			}
			if (LocalContext.IsMe(player))
			{
				NRun.Instance?.GlobalUi.RelicInventory.AnimateRelic(relic);
				NDebugAudioManager.Instance?.Play("relic_get.mp3");
				SaveManager.Instance.MarkRelicAsSeen(relic);
			}
			relic.FloorAddedToDeck = runState.TotalFloor;
			await relic.AfterObtained();
			return relic;
		}

		/// <summary>
		/// Remove a relic from its owner.
		/// </summary>
		/// <param name="relic">Relic to remove.</param>
		public static async Task Remove(RelicModel relic)
		{
			relic.Owner.RunState.CurrentMapPointHistoryEntry?.GetEntry(relic.Owner.NetId).RelicsRemoved.Add(relic.Id);
			relic.Owner.RemoveRelicInternal(relic);
			await relic.AfterRemoved();
		}

		/// <summary>
		/// Replace a relic with another relic
		/// </summary>
		/// <param name="original">Relic to remove.</param>
		/// <param name="replace">Relic to obtain.</param>
		/// <returns>RelicModel</returns>
		public static async Task<RelicModel> Replace(RelicModel original, RelicModel replace)
		{
			original.AssertMutable();
			replace.AssertMutable();
			Player player = original.Owner;
			int indexOfOriginal = player.Relics.IndexOf(original);
			await Remove(original);
			return await Obtain(replace, player, indexOfOriginal);
		}

		/// <summary>
		/// Melts a relic.
		/// A melted relic remains in your inventory, but is unusable.
		/// </summary>
		/// <param name="relic">Relic to melt.</param>
		public static async Task Melt(RelicModel relic)
		{
			relic.Owner.MeltRelicInternal(relic);
			await relic.AfterRemoved();
		}
	}
	public static class RelicSelectCmd
	{
		private static bool ShouldSelectLocalRelic(Player player)
		{
			if (LocalContext.IsMe(player))
			{
				return RunManager.Instance.NetService.Type != NetGameType.Replay;
			}
			return false;
		}

		public static async Task<RelicModel?> FromChooseARelicScreen(Player player, IReadOnlyList<RelicModel> relics)
		{
			uint choiceId = RunManager.Instance.PlayerChoiceSynchronizer.ReserveChoiceId(player);
			RelicModel relicModel;
			if (ShouldSelectLocalRelic(player))
			{
				NChooseARelicSelection nChooseARelicSelection = NChooseARelicSelection.ShowScreen(relics);
				if (LocalContext.IsMe(player))
				{
					foreach (RelicModel relic in relics)
					{
						SaveManager.Instance.MarkRelicAsSeen(relic);
					}
				}
				relicModel = (await nChooseARelicSelection.RelicsSelected()).FirstOrDefault();
				int value = relics.IndexOf(relicModel);
				PlayerChoiceResult result = PlayerChoiceResult.FromIndex(value);
				RunManager.Instance.PlayerChoiceSynchronizer.SyncLocalChoice(player, choiceId, result);
			}
			else
			{
				int num = (await RunManager.Instance.PlayerChoiceSynchronizer.WaitForRemoteChoice(player, choiceId)).AsIndex();
				relicModel = ((num < 0) ? null : relics[num]);
			}
			return relicModel;
		}
	}
	public static class RewardsCmd
	{
		/// <summary>
		/// Offers rewards generated for the end of a combat or treasure room.
		/// If the player is not the local player, nothing happens.
		/// The rewards screen generated by this cmd will show the proceed button after all rewards are taken, and all input
		/// into the room will be blocked.
		/// </summary>
		/// <param name="player">The player to whom we are offering rewards.</param>
		/// <param name="room">The room to generate rewards for.</param>
		public static async Task OfferForRoomEnd(Player player, AbstractRoom room)
		{
			RewardsSet rewardsSet;
			if (room is CombatRoom combatRoom)
			{
				EncounterModel encounter = combatRoom.Encounter;
				if (encounter != null && !encounter.ShouldGiveRewards)
				{
					rewardsSet = new RewardsSet(player).EmptyForRoom(room);
					goto IL_00b4;
				}
			}
			rewardsSet = new RewardsSet(player).WithRewardsFromRoom(room);
			goto IL_00b4;
			IL_00b4:
			await rewardsSet.Offer();
		}

		/// <summary>
		/// Offers a custom set of rewards, usually from a relic or event.
		/// If the player is not the local player, nothing happens.
		/// The rewards may be changed by hooks, like Molten Egg or Ruby Earrings.
		/// The rewards screen generated by this cmd will not show the proceed button after all rewards are taken. The
		/// rewards screen will disappear and the player will be allowed to click into the room again.
		/// </summary>
		/// <param name="player">The player to whom we are offering rewards.</param>
		/// <param name="rewards">The list of rewards to offer the player.</param>
		public static async Task OfferCustom(Player player, List<Reward> rewards)
		{
			await new RewardsSet(player).WithCustomRewards(rewards).Offer();
		}

		/// <summary>
		/// Same as <see cref="M:MegaCrit.Sts2.Core.Commands.RewardsCmd.OfferForRoomEnd(MegaCrit.Sts2.Core.Entities.Players.Player,MegaCrit.Sts2.Core.Rooms.AbstractRoom)" />, except the rewards are not offered to the player.
		/// </summary>
		public static async Task<RewardsSet> GenerateForRoomEnd(Player player, AbstractRoom room)
		{
			RewardsSet set = new RewardsSet(player).WithRewardsFromRoom(room);
			await set.GenerateWithoutOffering();
			return set;
		}

		/// <summary>
		/// Same as <see cref="M:MegaCrit.Sts2.Core.Commands.RewardsCmd.OfferCustom(MegaCrit.Sts2.Core.Entities.Players.Player,System.Collections.Generic.List{MegaCrit.Sts2.Core.Rewards.Reward})" />, except the rewards are not offered to the player.
		/// </summary>
		public static async Task<RewardsSet> GenerateCustom(Player player, List<Reward> rewards)
		{
			RewardsSet set = new RewardsSet(player).WithCustomRewards(rewards);
			await set.GenerateWithoutOffering();
			return set;
		}
	}
