namespace MegaCrit.Sts2.Core.Commands.Builders
{
	/// <summary>
	/// A "builder" command that allows you to chain method calls to build up the property of an attack.
	/// This pattern is very similar to how Godot Tweens are built up.
	/// </summary>
	public class AttackCommand
	{
		private enum SourceType
		{
			None,
			Card,
			Monster
		}

		/// <summary>
		/// The amount of damage that this attack will deal on each hit.
		/// This will be ignored if <see cref="F:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand._calculatedDamageVar" /> is set.
		/// </summary>
		private readonly decimal _damagePerHit;

		/// <summary>
		/// Dynamic var that calculates how much damage each hit does.
		/// Used for cards that do dynamic amounts of damage based on combat state, like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.PerfectedStrike" />.
		/// Settings this will cause <see cref="F:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand._damagePerHit" /> to be ignored.
		/// </summary>
		private readonly CalculatedDamageVar? _calculatedDamageVar;

		/// <summary>
		/// The number of hits this attack should do.
		/// The actual number of hits may be modified by hooks.
		/// If you need to check the final number of hits, check <see cref="P:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand.Results" /> after the attack has been executed.
		/// </summary>
		private int _hitCount = 1;

		/// <summary>
		/// The source of this attack.
		/// Without this, we have to glean it from some combination of Attacker and ModelSource, which can get tricky in
		/// cases like Osty attacks.
		/// </summary>
		private SourceType _sourceType;

		private ICombatState? _combatState;

		/// <summary>
		/// Set for single target attacks. Is null for AOE attacks.
		/// </summary>
		private Creature? _singleTarget;

		private bool _spawnVfxOnEachCreature;

		private bool _spawnVfxOnCreatureCenter = true;

		private bool _doesRandomTargetingAllowDuplicates = true;

		private bool _shouldPlayAnimation = true;

		private readonly List<List<DamageResult>> _results = new List<List<DamageResult>>();

		private string? _attackerAnimName;

		private float _attackerAnimDelay;

		private Creature? _visualAttacker;

		private bool _playOnEveryHit = true;

		private string? _attackerVfx;

		private string? _attackerSfx;

		private string? _tmpAttackerSfx;

		/// <summary>
		/// fast, standard
		/// </summary>
		private readonly float[] _waitBeforeHit = new float[2] { -1f, -1f };

		private readonly List<Func<Node2D?>> _customAttackerVfxNodes = new List<Func<Node2D>>();

		private readonly List<Func<Creature, Node2D?>> _customHitVfxNodes = new List<Func<Creature, Node2D>>();

		private Func<Task>? _afterAttackerAnim;

		private Func<Task>? _beforeDamage;

		/// <summary>
		/// The creature performing this attack.
		/// It's safe to assume this is non-null once the attack is being executed.
		/// </summary>
		public Creature? Attacker { get; private set; }

		/// <summary>
		/// The model that this attack comes from, such as an attack card.
		/// </summary>
		public AbstractModel? ModelSource { get; private set; }

		/// <summary>
		/// The card play that this attack comes from, if any.
		/// </summary>
		public CardPlay? CardPlay { get; private set; }

		public CombatSide TargetSide { get; private set; }

		/// <summary>
		/// The ValueProps of the damage that this attack deals.
		/// </summary>
		public ValueProp DamageProps { get; private set; } = ValueProp.Move;

		/// <summary>
		/// Whether this attack is targeting a single creature.
		/// </summary>
		public bool IsSingleTargeted => _singleTarget != null;

		/// <summary>
		/// Whether this attack is targeting multiple creatures.
		/// </summary>
		public bool IsMultiTargeted => _combatState != null;

		/// <summary>
		/// Whether this attack is randomly targeted.
		/// </summary>
		public bool IsRandomlyTargeted { get; private set; }

		/// <summary>
		/// The resulting instances of damage from this attack.
		/// Each inner list is from an individual hit from this attack (so if we have a multi-attack, we have multiple lists)
		/// This will start out empty, and will be populated after <see cref="M:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand.Execute(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext)" /> finishes running.
		/// </summary>
		public IEnumerable<List<DamageResult>> Results => _results;

		public string? HitSfx { get; private set; }

		public string? TmpHitSfx { get; private set; }

		public string? HitVfx { get; private set; }

		/// <summary>
		/// The creatures being targeted by this attack.
		/// For random attacks, this contains all possible targets, and for custom attacks using
		/// <see cref="T:MegaCrit.Sts2.Core.Commands.Builders.AttackContext" />, this will be empty.
		/// After the attack has been executed, you can check <see cref="P:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand.Results" /> to see which targets were actually hit.
		/// </summary>
		private IReadOnlyList<Creature> GetPossibleTargets()
		{
			if (IsSingleTargeted)
			{
				return new global::<>z__ReadOnlySingleElementList<Creature>(_singleTarget);
			}
			if (IsMultiTargeted)
			{
				if (_sourceType == SourceType.Monster)
				{
					return _combatState.PlayerCreatures;
				}
				if (Attacker == null)
				{
					throw new InvalidOperationException("We require an attacker to be able to grab its opponents");
				}
				return _combatState.GetOpponentsOf(Attacker);
			}
			throw new InvalidOperationException("No targets set, a Targeting method must be called before Execute");
		}

		/// <summary>
		/// Create a new attack command.
		/// </summary>
		/// <param name="damagePerHit">The amount of damage this attack should deal on each hit.</param>
		public AttackCommand(decimal damagePerHit)
		{
			_damagePerHit = damagePerHit;
			_calculatedDamageVar = null;
		}

		/// <summary>
		/// Create a new attack command
		/// </summary>
		/// <param name="calculatedDamageVar">
		/// Dynamic var that calculates how much damage each hit does.
		/// Used for cards that do dynamic amounts of damage based on combat state, like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.PerfectedStrike" />.
		/// </param>
		public AttackCommand(CalculatedDamageVar calculatedDamageVar)
		{
			_damagePerHit = -1m;
			_calculatedDamageVar = calculatedDamageVar;
		}

		/// <summary>
		/// Set the attack to come from the specified card.
		/// This also automatically sets the attacker as the card's owner, and the attacker animation name/delay to the card
		/// owner's defaults.
		/// </summary>
		/// <param name="card">Card that the attack came from.</param>
		/// <param name="cardPlay"></param>
		public AttackCommand FromCard(CardModel card, CardPlay? cardPlay)
		{
			if (Attacker != null)
			{
				throw new InvalidOperationException("Attacker has already been set.");
			}
			if (ModelSource != null)
			{
				throw new InvalidOperationException("ModelSource has already been set.");
			}
			if (cardPlay != null && CardPlay != null)
			{
				throw new InvalidOperationException("CardPlay has already been set.");
			}
			Player owner = card.Owner;
			Attacker = owner.Creature;
			_attackerAnimName = "Attack";
			_attackerAnimDelay = owner.Character.AttackAnimDelay;
			ModelSource = card;
			CardPlay = cardPlay;
			_sourceType = SourceType.Card;
			return this;
		}

		public AttackCommand FromOsty(Creature osty, CardModel card, CardPlay? cardPlay)
		{
			if (!(osty.Monster is Osty))
			{
				throw new ArgumentException("Creature is not Osty");
			}
			Attacker = osty;
			ModelSource = card;
			CardPlay = cardPlay;
			_attackerAnimName = "Attack";
			_attackerAnimDelay = 0.3f;
			_sourceType = SourceType.Card;
			return WithAttackerFx(null, "event:/sfx/characters/osty/osty_attack");
		}

		/// <summary>
		/// Set the attack to come from the specified monster.
		/// </summary>
		/// <param name="monster">Monster that the attack came from.</param>
		public AttackCommand FromMonster(MonsterModel monster)
		{
			if (Attacker != null)
			{
				throw new InvalidOperationException("Attacker has already been set.");
			}
			Attacker = monster.Creature;
			_attackerAnimName = "Attack";
			_sourceType = SourceType.Monster;
			return TargetingAllOpponents(monster.Creature.CombatState);
		}

		/// <summary>
		/// Set the attack to target the specified creature.
		/// </summary>
		/// <param name="target">Creature for the attack to target.</param>
		public AttackCommand Targeting(Creature target)
		{
			if (_singleTarget != null)
			{
				throw new InvalidOperationException("Targets already set.");
			}
			if (_combatState != null)
			{
				throw new InvalidOperationException("Already set to target opponents of attacker");
			}
			_singleTarget = target;
			TargetSide = target.Side;
			return this;
		}

		/// <summary>
		/// Set the attack to target the opponents of the Attacker.
		/// Differs from TargetingAll because the list of targets is refreshed between every hit
		/// meaning that new creatures added to the combat will become valid targets
		/// </summary>
		/// <param name="combatState">Combat state that we will be pulling the opponents from</param>
		public AttackCommand TargetingAllOpponents(ICombatState combatState)
		{
			if (_singleTarget != null)
			{
				throw new InvalidOperationException("Targets already set.");
			}
			if (_combatState != null)
			{
				throw new InvalidOperationException("Already set to target opponents of attacker");
			}
			if (Attacker == null)
			{
				throw new InvalidOperationException("We require an attacker to be able to grab its opponents");
			}
			_combatState = combatState;
			TargetSide = ((Attacker.Side == CombatSide.Enemy) ? CombatSide.Player : CombatSide.Enemy);
			return this;
		}

		/// <summary>
		/// Sets the attack to target random opponents of the attacker.
		/// A new random target will be chosen on each hit.
		/// </summary>
		/// <param name="combatState">Combat state that we will be pulling the opponents from</param>
		/// <param name="allowDuplicates">
		/// Whether the same target can be hit multiple times.
		/// In real gameplay, we pretty much always want this to be true, but we pass false sometimes for testing.
		/// </param>
		public AttackCommand TargetingRandomOpponents(ICombatState combatState, bool allowDuplicates = true)
		{
			if (_singleTarget != null)
			{
				throw new InvalidOperationException("Targets already set.");
			}
			if (_combatState != null)
			{
				throw new InvalidOperationException("Already set to target opponents of attacker");
			}
			if (Attacker == null)
			{
				throw new InvalidOperationException("We require an attacker to be able to grab its opponents");
			}
			_combatState = combatState;
			IsRandomlyTargeted = true;
			_doesRandomTargetingAllowDuplicates = allowDuplicates;
			return this;
		}

		/// <summary>
		/// Set the attack to deal unpowered damage.
		///
		/// WARNING: 99% of the time, when unpowered damage is dealt, it shouldn't be considered an
		/// attack (like via <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Burn" />). However, occasionally we want to do a real attack
		/// that skips powers (like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Omnislice" />), so this is useful there.
		/// </summary>
		public AttackCommand Unpowered()
		{
			DamageProps |= ValueProp.Unpowered;
			return this;
		}

		/// <summary>
		/// Set the attack to play the specified animation on the attacker.
		/// </summary>
		/// <param name="animName">Name of the animation trigger.</param>
		/// <param name="delay">Amount of time to wait for the animation to complete before proceeding.</param>
		/// <param name="visualAttacker">
		/// Optional custom creature to visually display as the attacker in this animation.
		/// Good for attacks like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.ByrdSwoop" /> where we want a pet to animate for the attack, even though the
		/// actual attack is coming from the attack's owner.
		/// If this is left null, the attack's owning creature will play the animation.
		/// </param>
		public AttackCommand WithAttackerAnim(string? animName, float delay, Creature? visualAttacker = null)
		{
			if (_attackerAnimName == null)
			{
				throw new InvalidOperationException("WithAttackerAnim was called before FromCard/FromMonster/FromOsty, should be called after.");
			}
			_attackerAnimName = animName;
			_attackerAnimDelay = delay;
			_visualAttacker = visualAttacker;
			return this;
		}

		public AttackCommand WithNoAttackerAnim()
		{
			_shouldPlayAnimation = false;
			return this;
		}

		/// <summary>
		/// Logic to execute after the attacker animation plays. Good for one-offs.
		/// Note: If you find yourself calling this with the same logic in many different attacks, consider making a
		/// first-class builder method for the logic instead.
		/// </summary>
		public AttackCommand AfterAttackerAnim(Func<Task> afterAttackerAnim)
		{
			_afterAttackerAnim = afterAttackerAnim;
			return this;
		}

		/// <summary>
		/// Set the attack to play the specified VFX/SFX on attacker.
		/// </summary>
		/// <param name="vfx">File path of the VFX.</param>
		/// <param name="sfx">File path of the SFX.</param>
		/// <param name="tmpSfx">
		/// Temporary SFX file path. If the attack uses temporary non-FMOD SFX, pass this instead of sfx using keyword args.
		/// </param>
		public AttackCommand WithAttackerFx(string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			_attackerVfx = vfx;
			_attackerSfx = sfx;
			_tmpAttackerSfx = tmpSfx;
			return this;
		}

		/// <summary>
		/// Set the attack to add the specified custom VFX node to the combat VFX container when the owner attacks.
		/// </summary>
		public AttackCommand WithAttackerFx(Func<Node2D?> createAttackerVfx)
		{
			_customAttackerVfxNodes.Add(createAttackerVfx);
			return this;
		}

		/// <summary>
		/// Set a wait time before each hit and hit VFX/SFX.
		/// Uses the same wait time signature as <see cref="M:MegaCrit.Sts2.Core.Commands.Cmd.CustomScaledWait(System.Single,System.Single,System.Boolean,System.Threading.CancellationToken)" />.
		/// </summary>
		public AttackCommand WithWaitBeforeHit(float fastSeconds, float standardSeconds)
		{
			_waitBeforeHit[0] = fastSeconds;
			_waitBeforeHit[1] = standardSeconds;
			return this;
		}

		/// <summary>
		/// Set the attack to play the specified VFX/SFX on the target(s) when they're hit.
		/// </summary>
		/// <param name="vfx">File path of the VFX.</param>
		/// <param name="sfx">File path of the SFX.</param>
		/// <param name="tmpSfx">
		/// Temporary SFX file path. If the attack uses temporary non-FMOD SFX, pass this instead of sfx using keyword args.
		/// </param>
		public AttackCommand WithHitFx(string? vfx = null, string? sfx = null, string? tmpSfx = null)
		{
			HitVfx = vfx;
			HitSfx = sfx;
			TmpHitSfx = tmpSfx;
			return this;
		}

		/// <summary>
		/// If this attack hits multiple creatures, this sets the hit VFX to spawn on each creature rather than on the side.
		/// </summary>
		public AttackCommand SpawningHitVfxOnEachCreature()
		{
			_spawnVfxOnEachCreature = true;
			return this;
		}

		/// <summary>
		/// If there is a hit VFX set, this makes it spawn at the creature's base rather than its center.
		/// </summary>
		public AttackCommand WithHitVfxSpawnedAtBase()
		{
			_spawnVfxOnCreatureCenter = false;
			return this;
		}

		/// <summary>
		/// Set the attack to add the specified custom VFX node to the combat VFX container when the target(s) are hit.
		/// </summary>
		public AttackCommand WithHitVfxNode(Func<Creature, Node2D?> createHitVfxNode)
		{
			_customHitVfxNodes.Add(createHitVfxNode);
			return this;
		}

		/// <summary>
		/// Set the attack to only play animations/VFX/SFX once, even on a multi-hit.
		/// Good for situations where a single bespoke attack animation illustrates multiple hits.
		/// </summary>
		public AttackCommand OnlyPlayAnimOnce()
		{
			_playOnEveryHit = false;
			return this;
		}

		/// <summary>
		/// Set the number of hits this attack should do.
		/// </summary>
		/// <param name="hitCount">The number of times this attack should hit.</param>
		public AttackCommand WithHitCount(int hitCount)
		{
			_hitCount = hitCount;
			return this;
		}

		/// <summary>
		/// Logic to execute before each instance of damage is dealt. Good for one-offs.
		/// Note: If you find yourself calling this with the same logic in many different attacks, consider making a
		/// first-class builder method for the logic instead.
		/// </summary>
		public AttackCommand BeforeDamage(Func<Task> beforeDamage)
		{
			_beforeDamage = beforeDamage;
			return this;
		}

		/// <summary>
		/// Creates an attack context for grouping multiple damage calls as a single attack.
		/// Use with `await using` to automatically call BeforeAttack and AfterAttack hooks.
		/// </summary>
		/// <param name="combatState">The current combat state</param>
		/// <param name="choiceContext">The context that is signalled in the event of a player choice.</param>
		/// <param name="cardPlay">The card play that is the source of this attack</param>
		/// <returns>An AttackContext ready for use with await using</returns>
		public static async Task<AttackContext> CreateContextAsync(ICombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			return await AttackContext.CreateAsync(combatState, choiceContext, cardPlay);
		}

		/// <summary>
		/// Execute this attack.
		/// If you forget to set some required values (like attacker or target), this will error.
		/// </summary>
		/// <param name="choiceContext">
		/// The context that is signalled in the event of a player choice. If null, a
		/// <see cref="T:MegaCrit.Sts2.Core.GameActions.Multiplayer.BlockingPlayerChoiceContext" /> is used. This should only be done when a monster is attacking.
		/// </param>
		public async Task<AttackCommand> Execute(PlayerChoiceContext? choiceContext)
		{
			ICombatState combatState = Attacker?.CombatState;
			if (Attacker == null)
			{
				throw new InvalidOperationException("No attacker set.");
			}
			if (CombatManager.Instance.IsOverOrEnding && (combatState == null || combatState.IsLiveCombat()))
			{
				return this;
			}
			if (combatState == null)
			{
				throw new InvalidOperationException("No combat state even though combat is not over.");
			}
			if (Attacker.IsDead)
			{
				return this;
			}
			if (!IsSingleTargeted && !IsMultiTargeted)
			{
				throw new InvalidOperationException("No targets set.");
			}
			await Hook.BeforeAttack(combatState, this);
			decimal attackCount = Hook.ModifyAttackHitCount(combatState, this, _hitCount);
			for (int i = 0; (decimal)i < attackCount; i++)
			{
				if (Attacker.IsDead)
				{
					break;
				}
				List<Creature> validTargets = (from c in GetPossibleTargets()
					where c.IsAlive
					select c).ToList();
				if (validTargets.Count == 0 && combatState.IsLiveCombat())
				{
					break;
				}
				if (_playOnEveryHit || i == 0)
				{
					if (_attackerVfx != null)
					{
						VfxCmd.PlayOnCreatureCenter(Attacker, _attackerVfx);
					}
					foreach (Func<Node2D> customAttackerVfxNode in _customAttackerVfxNodes)
					{
						Attacker.GetVfxContainer()?.AddChildSafely(customAttackerVfxNode());
					}
					if (_attackerSfx != null)
					{
						SfxCmd.Play(_attackerSfx);
					}
					else if (_tmpAttackerSfx != null)
					{
						NDebugAudioManager.Instance?.Play(_tmpAttackerSfx);
					}
					if (_attackerAnimName != null && _shouldPlayAnimation)
					{
						await CreatureCmd.TriggerAnim(_visualAttacker ?? Attacker, _attackerAnimName, _attackerAnimDelay);
					}
					if (_afterAttackerAnim != null)
					{
						await _afterAttackerAnim();
					}
				}
				if (validTargets.Count > 0)
				{
					if (HitSfx != null)
					{
						SfxCmd.Play(HitSfx);
					}
					else if (TmpHitSfx != null)
					{
						NDebugAudioManager.Instance?.Play(TmpHitSfx);
					}
				}
				Creature singleTarget;
				if (!IsRandomlyTargeted)
				{
					singleTarget = ((validTargets.Count != 1) ? null : validTargets[0]);
				}
				else
				{
					if (!_doesRandomTargetingAllowDuplicates)
					{
						validTargets = validTargets.Where((Creature c) => _results.SelectMany((List<DamageResult> r) => r).All((DamageResult r) => r.Receiver != c)).ToList();
						if (validTargets.Count == 0)
						{
							throw new InvalidOperationException("No valid targets for attack with duplicates disallowed. If you're in a test, you probably need to add more enemies. If you're in real gameplay, something is wrong.");
						}
					}
					Rng combatTargets = (Attacker.Player ?? Attacker.PetOwner).RunState.Rng.CombatTargets;
					singleTarget = combatTargets.NextItem(validTargets);
				}
				if (_waitBeforeHit.Any((float w) => w > 0f))
				{
					await Cmd.CustomScaledWait(_waitBeforeHit[0], _waitBeforeHit[1]);
				}
				foreach (Func<Creature, Node2D> customHitVfxNode in _customHitVfxNodes)
				{
					if (singleTarget != null)
					{
						singleTarget.GetVfxContainer()?.AddChildSafely(customHitVfxNode(singleTarget));
						continue;
					}
					foreach (Creature item in validTargets)
					{
						item.GetVfxContainer()?.AddChildSafely(customHitVfxNode(item));
					}
				}
				if (HitVfx != null)
				{
					if (singleTarget != null)
					{
						if (_spawnVfxOnCreatureCenter)
						{
							VfxCmd.PlayOnCreatureCenter(singleTarget, HitVfx);
						}
						else
						{
							VfxCmd.PlayOnCreature(singleTarget, HitVfx);
						}
					}
					else if (_spawnVfxOnEachCreature)
					{
						if (_spawnVfxOnCreatureCenter)
						{
							VfxCmd.PlayOnCreatureCenters(validTargets, HitVfx);
						}
						else
						{
							VfxCmd.PlayOnCreatures(validTargets, HitVfx);
						}
					}
					else
					{
						VfxCmd.PlayOnSide(Attacker.Side.GetOppositeSide(), HitVfx, combatState);
					}
				}
				if (_beforeDamage != null)
				{
					await _beforeDamage();
				}
				AddResultsInternal(await CreatureCmd.Damage(amount: (_calculatedDamageVar == null) ? _damagePerHit : _calculatedDamageVar.Calculate(singleTarget), choiceContext: choiceContext ?? new BlockingPlayerChoiceContext(), targets: (singleTarget != null) ? ((IEnumerable<Creature>?)new List<Creature>(1) { singleTarget }) : ((IEnumerable<Creature>?)validTargets), props: DamageProps, dealer: Attacker, cardSource: ModelSource as CardModel, cardPlay: CardPlay));
			}
			CombatManager.Instance.History.CreatureAttacked(combatState, Attacker, _results.SelectMany((List<DamageResult> r) => r).ToList());
			await Hook.AfterAttack(combatState, choiceContext ?? new BlockingPlayerChoiceContext(), this);
			return this;
		}

		/// <summary>
		/// NEVER CALL THIS FROM MODELS, only in system code where you know exactly what you're doing.
		/// Increment the number of hits this attack should do.
		/// </summary>
		public void IncrementHitsInternal()
		{
			_hitCount++;
		}

		/// <summary>
		/// NEVER CALL THIS FROM MODELS, only in system code where you know exactly what you're doing.
		/// Add a set of DamageResults to the list of results for this attack.
		/// </summary>
		public void AddResultsInternal(IEnumerable<DamageResult> results)
		{
			_results.Add(results.ToList());
		}
	}
	/// <summary>
	/// A context for grouping multiple damage calls as a single attack for hook purposes.
	/// Use with C#'s `await using` statement to automatically call BeforeAttack and AfterAttack hooks.
	/// </summary>
	public sealed class AttackContext : IAsyncDisposable
	{
		private readonly ICombatState _combatState;

		private readonly PlayerChoiceContext _choiceContext;

		private readonly AttackCommand _attackCommand;

		private bool _disposed;

		/// <summary>
		/// Private constructor. Use <see cref="M:MegaCrit.Sts2.Core.Commands.Builders.AttackContext.CreateAsync(MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Cards.CardPlay)" /> to create instances.
		/// </summary>
		private AttackContext(ICombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			_combatState = combatState;
			_choiceContext = choiceContext;
			_attackCommand = new AttackCommand(0m).FromCard(cardPlay.Card, cardPlay).TargetingAllOpponents(combatState);
		}

		/// <summary>
		/// Creates a new AttackContext and calls the BeforeAttack hook.
		/// </summary>
		/// <param name="combatState">The current combat state</param>
		/// <param name="choiceContext">The context that is signalled in the event of a player choice.</param>
		/// <param name="cardPlay">The card play that is the source of this attack</param>
		/// <returns>An initialized AttackContext ready for use with await using</returns>
		public static async Task<AttackContext> CreateAsync(ICombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			AttackContext context = new AttackContext(combatState, choiceContext, cardPlay);
			await Hook.BeforeAttack(combatState, context._attackCommand);
			return context;
		}

		/// <summary>
		/// Add to the list of hits that have been done within the context of this attack.
		/// </summary>
		/// <param name="results">DamageResults from the hit.</param>
		public void AddHit(IEnumerable<DamageResult> results)
		{
			_attackCommand.IncrementHitsInternal();
			_attackCommand.AddResultsInternal(results);
		}

		/// <summary>
		/// Disposes the context and calls the AfterAttack hook.
		/// This is automatically called when exiting an await using block.
		/// </summary>
		public async ValueTask DisposeAsync()
		{
			if (_disposed)
			{
				return;
			}
			_disposed = true;
			try
			{
				await Hook.AfterAttack(_combatState, _choiceContext, _attackCommand);
			}
			catch (Exception ex)
			{
				Log.Error(ex.ToString());
			}
		}
	}
}
namespace MegaCrit.Sts2.Core.Combat
{
	/// <summary>
	/// Identifies one combat. Handed out by <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.CurrentCombatId" /> and captured by callers at the
	/// start of work that can outlive its combat (a card or potion effect, a kill), then passed back in so the manager
	/// can tell whether the combat that work belongs to is still the current one.
	///
	/// Deliberately an opaque value rather than the combat's state or turn state: it cannot be dereferenced, cannot go
	/// null partway through an effect the way <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.CombatState" /> can, and gives a caller outside
	/// the assembly no way to reach into combat internals.
	/// </summary>
	public readonly record struct CombatId(int Value)
	{
		public override string ToString()
		{
			return Value.ToString();
		}
	}
	public class CombatManager
	{
		public const int baseHandDrawCount = 5;

		/// <summary>
		/// The current combat's turn state: every piece of combat-scoped state (token, ready sets, signals, phase flags)
		/// lives on it, created in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.SetUpCombat(MegaCrit.Sts2.Core.Combat.CombatState)" /> and dropped wholesale in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.Reset(System.Boolean)" />. The turn loop
		/// threads its own turn state through the turn flow; everything else (deliveries, public getters) reads this
		/// field for the current combat.
		/// </summary>
		private CombatTurnState? _turnState;

		/// <summary>
		/// Set to true when the player should not be able to interact with their hand or any potions.
		/// </summary>
		private bool _playerActionsDisabled;

		private readonly System.Collections.Generic.Dictionary<Player, int> _cardOrPotionEffectDepth = new System.Collections.Generic.Dictionary<Player, int>();

		/// <summary>
		/// The most recently launched turn loop task, kept across <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.Reset(System.Boolean)" /> so the next combat's turn loop can
		/// wait for it to finish dying. This is deliberately manager-scoped: it is the one piece of state whose job
		/// is to bridge two combats.
		/// </summary>
		private Task? _turnLoopTask;

		/// <summary>
		/// Installed by <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.DebugOnlyWhenNextTurnLoopWaitsForPrevious" />, completed when a turn loop suspends inside
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.WaitForPreviousTurnLoopToFinish(System.Threading.Tasks.Task,MegaCrit.Sts2.Core.Combat.CombatTurnState)" />.
		/// </summary>
		private TaskCompletionSource? _turnLoopWaitingForPreviousSource;

		/// <summary>
		/// Watchdog for the previous turn loop wait in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.RunTurnLoopAfter(System.Threading.Tasks.Task)" />. Generous: it only elapses when the
		/// previous turn loop is genuinely stuck on a suspension that teardown could not cancel, in which case we log
		/// loudly and proceed, degrading to the unsequenced behavior instead of introducing a new hang class.
		/// </summary>
		private static readonly TimeSpan _previousTurnLoopTimeout = TimeSpan.FromSeconds(10L);

		/// <summary>
		/// Whether the previous turn loop watchdog has already reported to Sentry this session. The watchdog can fire on
		/// every combat start, so it reports once and lets the log carry the rest.
		/// </summary>
		private static bool _turnLoopWaitTimeoutReported;

		/// <summary>
		/// Whether the stale player-turn-end transition in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.AfterAllPlayersReadyToEndTurn(MegaCrit.Sts2.Core.Combat.CombatTurnState,MegaCrit.Sts2.Core.Combat.EndTurnSignal)" /> has already
		/// reported to Sentry this session. Reported once for the same reason as
		/// <see cref="F:MegaCrit.Sts2.Core.Combat.CombatManager._turnLoopWaitTimeoutReported" />.
		/// </summary>
		private static bool _staleTurnEndReported;

		public static CombatManager Instance { get; } = new CombatManager();

		/// <summary>
		/// WARNING: ONLY USE THIS IN TESTS!
		/// See <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.DebugForceTopCardOnNextShuffle(MegaCrit.Sts2.Core.Models.CardModel)" />.
		/// </summary>
		public CardModel? DebugForcedTopCardOnNextShuffle { get; private set; }

		public bool IsPaused { get; private set; }

		public bool PlayerActionsDisabled
		{
			get
			{
				return _playerActionsDisabled;
			}
			private set
			{
				if (_playerActionsDisabled != value)
				{
					_playerActionsDisabled = value;
					PlayerActionsDisabledChanged?.Invoke(_turnState.State);
				}
			}
		}

		/// <summary>
		/// The list of players in the current turn that are taking an extra turn.
		/// Normally empty; only non-empty if there are players that used extra-turn-taking effects like
		/// <see cref="T:MegaCrit.Sts2.Core.Models.Relics.PaelsEye" />.
		/// Returns a snapshot copy for thread safety.
		/// </summary>
		public IReadOnlyList<Player> PlayersTakingExtraTurn
		{
			get
			{
				CombatTurnState turnState = _turnState;
				if (turnState == null)
				{
					return System.Array.Empty<Player>();
				}
				using (turnState.ReadyLock.EnterScope())
				{
					return turnState.PlayersTakingExtraTurn.ToList();
				}
			}
		}

		/// <summary>
		/// True when the enemy turn has started (TurnStarted has fired for the enemy side).
		/// Set right before TurnStarted fires for enemy turns, cleared when switching to player turn.
		/// </summary>
		public bool IsEnemyTurnStarted => _turnState?.IsEnemyTurnStarted ?? false;

		/// <summary>
		/// Set to true in the time between when all players are ready to begin the enemy turn and when the enemy turn begins.
		/// </summary>
		public bool EndingPlayerTurnPhaseTwo => _turnState?.EndingPlayerTurnPhaseTwo ?? false;

		/// <summary>
		/// Set to true in the time during phase one of the end of the player's turn.
		/// </summary>
		public bool EndingPlayerTurnPhaseOne => _turnState?.EndingPlayerTurnPhaseOne ?? false;

		public CombatStateTracker StateTracker { get; }

		public CombatHistory History { get; }

		/// <summary>
		/// Is the combat currently in progress?
		/// True when the combat is done being initialized and has fully started.
		/// False when:
		/// * The combat is first being initialized.
		/// * The combat is ending (the last monster has been killed).
		/// * We're in a non-combat room.
		/// </summary>
		public bool IsInProgress => _turnState?.IsInProgress ?? false;

		/// <summary>
		/// The current combat's <see cref="T:MegaCrit.Sts2.Core.Combat.CombatId" />, or null outside combat. Capture this at the start of work that
		/// can outlive its combat (a card or potion effect, a kill) and pass it back to the entry point that acts on
		/// combat state, so that entry point can tell whether the work still belongs to the combat that is running.
		/// Reading <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.IsInProgress" /> there instead only answers "is some combat running", which a continuation
		/// resuming into the next combat passes.
		/// </summary>
		public CombatId? CurrentCombatId => _turnState?.Id;

		/// <summary>
		/// Is a new combat currently being set up?
		/// True from the start of <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.SetUpCombat(MegaCrit.Sts2.Core.Combat.CombatState)" /> until <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.IsInProgress" /> flips true in
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.StartCombatInternal(MegaCrit.Sts2.Core.Combat.CombatTurnState)" />. During this window <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.IsInProgress" /> is still false, so it lets
		/// callers distinguish "combat is starting" (where combat hooks that run during setup, like the initial deck
		/// shuffle, must still fire) from "combat is over or ending".
		/// </summary>
		public bool IsStarting => _turnState?.IsStarting ?? false;

		/// <summary>
		/// Is combat about to end due to player death?
		/// True when LoseCombat() has been called but the loss hasn't been processed yet.
		/// This allows effects to bail out early while still letting the current action complete.
		/// </summary>
		public bool IsAboutToLose => _turnState?.PendingLoss != null;

		/// <summary>
		/// Is the combat in the process of ending (but still in progress)?
		/// True when combat is in progress but all the enemies are dead, and there is nothing stopping combat from ending
		/// (e.g. Phrog Parasite spawning in new enemies).
		/// Also true when a pending loss is waiting to be processed.
		/// False when
		/// * Combat is in progress and 1+ primary enemies are still alive.
		/// * Combat is not in progress.
		/// </summary>
		public bool IsEnding
		{
			get
			{
				CombatTurnState turnState = _turnState;
				if (turnState != null)
				{
					return IsCombatEnding(turnState);
				}
				return false;
			}
		}

		/// <summary>
		/// Has this combat ended (or is it in the process of ending)?
		/// When you want to skip/cancel an effect because combat is not in progress, you should usually use this instead of
		/// <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.IsEnding" /> or !<see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.IsInProgress" />, because they can return unexpected results at certain
		/// boundary points.
		/// </summary>
		public bool IsOverOrEnding
		{
			get
			{
				if (!IsEnding)
				{
					return !IsInProgress;
				}
				return true;
			}
		}

		/// <summary>
		/// WARNING: ONLY USE THIS IN TESTS!
		/// The task that currently owns the turn loop. Exposed so a test can hold the outgoing turn loop across a
		/// teardown and read whether it is still alive, instead of inferring that from log output.
		/// </summary>
		internal Task? DebugOnlyCurrentTurnLoopTask => _turnLoopTask;

		/// <summary>
		/// Fired after combat is set up.
		/// Note that this happens a little bit before combat actually begins.
		/// </summary>
		public event Action<CombatState>? CombatSetUp;

		/// <summary>
		/// Fired whenever a new combat begins, after IsInProgress is set to true.
		/// </summary>
		public event Action<CombatState>? CombatBegan;

		/// <summary>
		/// Fired when combat ends.
		/// </summary>
		public event Action<CombatRoom>? CombatEnded;

		/// <summary>
		/// Fired when combat is won.
		/// </summary>
		public event Action<CombatRoom>? CombatWon;

		/// <summary>
		/// Fired whenever the arrangement of creatures in the combat changes. Specifically, when:
		/// * A creature is added.
		/// * A creature is removed.
		/// * A creature's position changes.
		/// </summary>
		public event Action<CombatState>? CreaturesChanged;

		/// <summary>
		/// Fired whenever a new turn starts.
		/// </summary>
		public event Action<CombatState>? TurnStarted;

		/// <summary>
		/// Fired whenever a turn ends.
		/// </summary>
		public event Action<CombatState>? TurnEnded;

		/// <summary>
		/// Fired whenever a player ends their turn. Remember that, in multiplayer, this is not the same as switching to the
		/// enemy's turn.
		/// </summary>
		public event Action<Player, bool>? PlayerEndedTurn;

		/// <summary>
		/// Fired whenever a player un-does the end of their turn.
		/// </summary>
		public event Action<Player>? PlayerUnendedTurn;

		/// <summary>
		/// Fired when all players have fully committed to ending turn and all player actions are done (including end of turn
		/// hooks like Well-Laid Plans), but before the player hand flush.
		/// </summary>
		public event Action<CombatState>? AboutToSwitchToEnemyTurn;

		/// <summary>
		/// Fired when the local player's actions become disabled or enabled.
		/// </summary>
		public event Action<CombatState>? PlayerActionsDisabledChanged;

		/// <summary>
		/// THIS IS TEMPORARY AND SHOULD ONLY BE USED IN TESTS
		/// </summary>
		/// <returns></returns>
		public CombatState? DebugOnlyGetState()
		{
			return _turnState?.State;
		}

		/// <summary>
		/// Sets <see cref="P:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState.Phase" /> to the same value for all players of the given combat.
		/// </summary>
		private static void SetPhaseForAllPlayers(CombatState state, PlayerTurnPhase phase)
		{
			foreach (Player player in state.Players)
			{
				if (player.PlayerCombatState != null)
				{
					player.PlayerCombatState.Phase = phase;
				}
			}
		}

		/// <summary>
		/// The live turn state, if it is in progress and owns <paramref name="combatId" />. Null when there is no combat,
		/// when that combat is not in progress, or when <paramref name="combatId" /> belongs to an earlier combat, which is
		/// the case that matters: work captured in combat A that resumes after combat B has started.
		///
		/// Deliberately does not also test <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.IsCombatEnding(MegaCrit.Sts2.Core.Combat.CombatTurnState)" />. The callers guarded on
		/// <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.IsInProgress" /> before they took a <see cref="T:MegaCrit.Sts2.Core.Combat.CombatId" />, so adding the ending check here would be
		/// a behavior change smuggled in as an id change; and the ending window is already covered where it does work,
		/// since a hand check's only effect is a hook and <c>Hook.IterateCombatHookListeners</c> drops combat hook
		/// dispatch once combat is ending.
		/// </summary>
		private CombatTurnState? LiveTurnStateFor(CombatId? combatId)
		{
			CombatTurnState turnState = _turnState;
			if (turnState == null || !turnState.IsInProgress)
			{
				return null;
			}
			if (!(combatId == turnState.Id))
			{
				return null;
			}
			return turnState;
		}

		/// <summary>
		/// Is <paramref name="combatId" /> the combat that is running right now? Use this from work that can be suspended
		/// past the end of its own combat, to drop the work rather than apply it to the next combat.
		///
		/// Testing the id alone is not enough. A combat that has ended keeps its <see cref="T:MegaCrit.Sts2.Core.Combat.CombatId" /> until
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.Reset(System.Boolean)" /> runs, because <c>EndCombatInternal</c> only clears
		/// <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.IsInProgress" />, so in that window the id still matches. This checks both.
		/// </summary>
		public bool IsCurrentLiveCombat(CombatId? combatId)
		{
			return LiveTurnStateFor(combatId) != null;
		}

		/// <summary>
		/// True while a <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.OnPlay(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Cards.CardPlay)" /> or a <see cref="M:MegaCrit.Sts2.Core.Models.PotionModel.OnUse(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Creatures.Creature)" /> effect body is currently
		/// executing for <paramref name="player" />, including nested auto-plays (e.g. a Sly card auto-played when
		/// discarded). Used to avoid premature hand-empty triggers while that player's effect is mid-resolution.
		/// </summary>
		public bool IsExecutingCardOrPotionEffect(Player player)
		{
			return _cardOrPotionEffectDepth.GetValueOrDefault(player) > 0;
		}

		/// <summary>
		/// Marks the start of a <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.OnPlay(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Cards.CardPlay)" /> or <see cref="M:MegaCrit.Sts2.Core.Models.PotionModel.OnUse(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Creatures.Creature)" /> effect body for
		/// <paramref name="player" />, incrementing their effect-nesting depth. Must be paired with a
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.EndCardOrPotionEffect(System.Nullable{MegaCrit.Sts2.Core.Combat.CombatId},MegaCrit.Sts2.Core.Entities.Players.Player)" /> in a finally block so the depth stays balanced even if the effect throws or
		/// the player dies mid-play.
		///
		/// Returns the <see cref="T:MegaCrit.Sts2.Core.Combat.CombatId" /> the effect is starting in. Hold it for the rest of the play or use, and pass
		/// it to the combat entry points called afterwards: an effect can be suspended past the end of its own combat, and
		/// those entry points need to know which combat the work belongs to rather than which one is running now. It is
		/// returned from here, rather than read at the point of use, so the capture cannot drift later than the effect's
		/// actual start.
		/// </summary>
		public CombatId? BeginCardOrPotionEffect(Player player)
		{
			_cardOrPotionEffectDepth[player] = _cardOrPotionEffectDepth.GetValueOrDefault(player) + 1;
			return CurrentCombatId;
		}

		/// <summary>
		/// Marks the end of a <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.OnPlay(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Cards.CardPlay)" /> or <see cref="M:MegaCrit.Sts2.Core.Models.PotionModel.OnUse(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext,MegaCrit.Sts2.Core.Entities.Creatures.Creature)" /> effect body for
		/// <paramref name="player" />, decrementing their effect-nesting depth (and removing the entry once it reaches
		/// zero). Pairs with <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.BeginCardOrPotionEffect(MegaCrit.Sts2.Core.Entities.Players.Player)" />; call it from a finally block.
		/// </summary>
		public async Task EndCardOrPotionEffect(CombatId? combatId, Player player)
		{
			int num = _cardOrPotionEffectDepth.GetValueOrDefault(player) - 1;
			if (num <= 0)
			{
				_cardOrPotionEffectDepth.Remove(player);
				if (player.Creature.IsDead)
				{
					await RemoveDeadPlayerCardsFromCombat(combatId, player);
				}
			}
			else
			{
				_cardOrPotionEffectDepth[player] = num;
			}
		}

		/// <summary>
		/// Turn-state-relative variant for the turn loop: evaluated against the turn loop's own combat, so a stale turn state
		/// resuming here cannot end (or fail to end) the current combat by mistake.
		/// </summary>
		private bool IsCombatEnding(CombatTurnState turnState)
		{
			if (!turnState.IsInProgress)
			{
				return false;
			}
			if (turnState.PendingLoss != null)
			{
				return true;
			}
			if (turnState.State.Enemies.Any((Creature e) => e != null && e.IsAlive && e.IsPrimaryEnemy))
			{
				return false;
			}
			if (Hook.ShouldStopCombatFromEnding(turnState.State))
			{
				return false;
			}
			return true;
		}

		private CombatManager()
		{
			History = new CombatHistory();
			StateTracker = new CombatStateTracker(this);
		}

		public void SetUpCombat(CombatState state)
		{
			if (_turnState != null)
			{
				throw new InvalidOperationException("Make sure to reset the combat before setting up a new one.");
			}
			CombatTurnState combatTurnState = (_turnState = new CombatTurnState(state));
			Log.Debug($"Combat #{combatTurnState.Id} created for encounter {state.Encounter?.Id.Entry}");
			state.MultiplayerScalingModel?.OnCombatEntered(state);
			StateTracker.SetState(state);
			foreach (Player player in state.Players)
			{
				player.ResetCombatState();
			}
			foreach (Player player2 in state.Players)
			{
				player2.PopulateCombatState(player2.RunState.Rng.Shuffle, state);
			}
			NetCombatCardDb.Instance.StartCombat(state.Players);
			foreach (Creature creature in state.Creatures)
			{
				AddCreature(creature);
			}
			CombatSetUp?.Invoke(state);
		}

		public void AfterCombatRoomLoaded()
		{
			RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.PreCombatSetup);
			Task turnLoopTask = _turnLoopTask;
			TaskHelper.RunSafely(_turnLoopTask = RunTurnLoopAfter(turnLoopTask));
		}

		/// <summary>
		/// WARNING: ONLY USE THIS IN TESTS!
		/// Returns a task that completes the next time a combat turn loop suspends inside
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.WaitForPreviousTurnLoopToFinish(System.Threading.Tasks.Task,MegaCrit.Sts2.Core.Combat.CombatTurnState)" />, for tests that need to catch a turn loop held at that wait.
		/// When that happens is not predictable from outside: a restart tears the old combat down synchronously, then
		/// loads a room before the next turn loop launches, so a test has nothing else to wait on.
		/// Call this before starting the next combat, so the signal is in place before its turn loop launches. Each call
		/// installs a fresh signal, so an earlier combat's turn loop cannot complete it.
		/// A turn loop that skips the wait never suspends, so the task never completes. That is what a missing wait
		/// looks like, so bound the wait and report the timeout as that failure.
		/// </summary>
		internal Task DebugOnlyWhenNextTurnLoopWaitsForPrevious()
		{
			return (_turnLoopWaitingForPreviousSource = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously)).Task;
		}

		/// <summary>
		/// Runs this combat's turn loop (<see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.StartCombatInternal(MegaCrit.Sts2.Core.Combat.CombatTurnState)" />) once <paramref name="previousTurnLoopTask" />,
		/// the previous combat's turn loop, has finished dying, and reports how it died in turn. Cancellation death
		/// is the normal teardown path and logs at debug; anything else while the combat is still running means the
		/// combat has lost its only turn loop and is stuck until the room is restarted, which must be loudly attributable.
		/// </summary>
		private async Task RunTurnLoopAfter(Task? previousTurnLoopTask)
		{
			CombatTurnState turnState = _turnState;
			try
			{
				await WaitForPreviousTurnLoopToFinish(previousTurnLoopTask, turnState);
				if (turnState != null)
				{
					Log.Debug($"Combat #{turnState.Id} turn loop started");
					await StartCombatInternal(turnState);
				}
			}
			catch (OperationCanceledException) when (turnState == null || !turnState.IsLive)
			{
				Log.Debug($"Combat #{turnState?.Id} turn loop died of cancellation (combat torn down)");
				throw;
			}
			catch (Exception ex2)
			{
				Exception e = ex2;
				if (turnState != null && turnState.IsLive && _turnState == turnState)
				{
					Log.Error($"Combat #{turnState.Id} turn loop died while its combat is in progress; the combat is stuck until the room is restarted: {e}");
					SentryService.CaptureException(new StuckCombatException("Combat turn loop died while its combat was in progress", e), delegate(Scope scope)
					{
						scope.SetFingerprint("StuckCombat", e.GetType().Name);
						scope.SetExtra("combatId", turnState.Id.Value);
					});
				}
				throw;
			}
		}

		/// <summary>
		/// Sequences this combat's start against the previous combat's turn loop as it finishes. The previous turn loop was
		/// cancelled when its combat was torn down and usually died synchronously inside that cancel, but a turn loop
		/// resumed by an external completion (a frame poll, a late-completing action, a test hook) can outlive teardown
		/// briefly; starting the next combat under it would let a stale turn loop continuation interleave with the new
		/// combat's setup.
		/// </summary>
		private async Task WaitForPreviousTurnLoopToFinish(Task? previousTurnLoopTask, CombatTurnState? turnState)
		{
			if (previousTurnLoopTask == null || previousTurnLoopTask.IsCompleted)
			{
				return;
			}
			Log.Debug($"Combat #{turnState?.Id} turn loop waiting for the previous combat's turn loop to die");
			_turnLoopWaitingForPreviousSource?.TrySetResult();
			try
			{
				await previousTurnLoopTask.WaitAsync(_previousTurnLoopTimeout);
			}
			catch (TimeoutException)
			{
				string text = $"The previous combat's turn loop is still running {_previousTurnLoopTimeout.TotalSeconds:0}s after its combat was torn down; starting combat #{turnState?.Id} without waiting for it.";
				Log.Error(text);
				if (!_turnLoopWaitTimeoutReported)
				{
					_turnLoopWaitTimeoutReported = true;
					SentryService.CaptureMessage("Combat turn loop wait timed out; started a combat without waiting for the previous turn loop", SentryLevel.Error, delegate(Scope scope)
					{
						scope.SetExtra("combatId", turnState?.Id.Value ?? (-1));
					});
				}
			}
			catch (Exception)
			{
			}
		}

		/// <summary>
		/// The turn loop body. Turn-state-threaded like the rest of the turn loop call graph: the turn state is the one
		/// captured when the turn loop was created, never re-read from <see cref="F:MegaCrit.Sts2.Core.Combat.CombatManager._turnState" />. A turn loop that was
		/// queued behind a slow predecessor (see <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.WaitForPreviousTurnLoopToFinish(System.Threading.Tasks.Task,MegaCrit.Sts2.Core.Combat.CombatTurnState)" />) can start after its
		/// combat was already torn down and replaced; reading the live field here would point that stale turn loop at the
		/// current combat and drive it alongside its real turn loop.
		/// </summary>
		private async Task StartCombatInternal(CombatTurnState turnState)
		{
			turnState.Ct.ThrowIfCancellationRequested();
			RunManager.Instance.ActionExecutor.Unpause();
			await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
			RunManager.Instance.ActionExecutor.Pause();
			if (turnState.State.Encounter.HasBgm)
			{
				NRunMusicController.Instance?.PlayCustomMusic(turnState.State.Encounter.CustomBgm);
			}
			foreach (Creature creature in turnState.State.Creatures)
			{
				await AfterCreatureAdded(creature, turnState.State);
				turnState.Ct.ThrowIfCancellationRequested();
			}
			RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.NotPlayPhase);
			turnState.IsInProgress = true;
			turnState.IsStarting = false;
			await Hook.BeforeCombatStart(turnState.State.RunState, turnState.State);
			turnState.Ct.ThrowIfCancellationRequested();
			CombatBegan?.Invoke(turnState.State);
			NRunMusicController.Instance?.UpdateTrack();
			NCombatRulesFtue ftue = null;
			if (SaveManager.Instance.SeenFtue("combat_rules_ftue"))
			{
				NCombatRoom.Instance?.AddChildSafely(NCombatStartBanner.Create());
			}
			else
			{
				ftue = NCombatRulesFtue.Create();
				NModalContainer.Instance?.Add(ftue, showBackstop: false);
			}
			await Cmd.CustomScaledWait(0.5f, 1f);
			turnState.Ct.ThrowIfCancellationRequested();
			await StartTurn(turnState);
			ftue?.Start();
			Func<Task> actionDuringEnemyTurn = await AwaitTurnEndAndSwitchSides(turnState);
			while (turnState.IsLive)
			{
				if (turnState.State.CurrentSide == CombatSide.Player)
				{
					await StartTurn(turnState);
					actionDuringEnemyTurn = await AwaitTurnEndAndSwitchSides(turnState);
				}
				else
				{
					await StartTurn(turnState, actionDuringEnemyTurn);
					actionDuringEnemyTurn = null;
				}
			}
		}

		/// <summary>
		/// The player-turn half of the turn loop, called by the turn loop with the player turn set up (or combat
		/// over/torn down, which the guards absorb): suspends awaiting the all-players-ready-to-end-turn signal, runs
		/// end-turn phase one, suspends awaiting the all-players-ready-to-begin-enemy-turn signal, then runs phase two,
		/// which switches sides. Returns the optional test hook carried by the local ready action, for the turn loop to
		/// run during the enemy turn.
		/// </summary>
		private async Task<Func<Task>?> AwaitTurnEndAndSwitchSides(CombatTurnState turnState)
		{
			if (!turnState.IsInProgress)
			{
				return null;
			}
			if (turnState.State.CurrentSide != CombatSide.Player)
			{
				return null;
			}
			TaskCompletionSource<EndTurnSignal> endTurnSignalSource;
			TaskCompletionSource<Func<Task>?> beginEnemyTurnSignalSource;
			using (turnState.ReadyLock.EnterScope())
			{
				endTurnSignalSource = turnState.EndTurnSignalSource;
				beginEnemyTurnSignalSource = turnState.BeginEnemyTurnSignalSource;
			}
			if (endTurnSignalSource == null || beginEnemyTurnSignalSource == null)
			{
				return null;
			}
			EndTurnSignal endTurnSignal = await endTurnSignalSource.Task;
			if (!turnState.IsInProgress)
			{
				return null;
			}
			turnState.Ct.ThrowIfCancellationRequested();
			if (endTurnSignal.RunningAction != null)
			{
				try
				{
					await endTurnSignal.RunningAction.CompletionTask.WaitAsync(turnState.Ct);
				}
				catch (OperationCanceledException) when (!turnState.Ct.IsCancellationRequested)
				{
				}
			}
			await AfterAllPlayersReadyToEndTurn(turnState, endTurnSignal);
			if (!turnState.IsInProgress)
			{
				return null;
			}
			turnState.Ct.ThrowIfCancellationRequested();
			Func<Task> actionDuringEnemyTurn = await beginEnemyTurnSignalSource.Task;
			if (!turnState.IsInProgress)
			{
				return null;
			}
			turnState.Ct.ThrowIfCancellationRequested();
			await AfterAllPlayersReadyToBeginEnemyTurn(turnState);
			return actionDuringEnemyTurn;
		}

		private async Task StartTurn(CombatTurnState turnState, Func<Task>? actionDuringEnemyTurn = null)
		{
			if (!turnState.IsInProgress)
			{
				return;
			}
			turnState.Ct.ThrowIfCancellationRequested();
			SetPhaseForAllPlayers(turnState.State, PlayerTurnPhase.None);
			bool isExtraPlayerTurn;
			List<Creature> creaturesStartingTurn;
			List<Player> playersStartingTurn;
			using (turnState.ReadyLock.EnterScope())
			{
				isExtraPlayerTurn = turnState.PlayersTakingExtraTurn.Count > 0;
				if ((turnState.State.CurrentSide == CombatSide.Player) & isExtraPlayerTurn)
				{
					creaturesStartingTurn = turnState.PlayersTakingExtraTurn.Select((Player p) => p.Creature).ToList();
					playersStartingTurn = turnState.PlayersTakingExtraTurn.ToList();
				}
				else
				{
					creaturesStartingTurn = turnState.State.CreaturesOnCurrentSide.ToList();
					playersStartingTurn = ((turnState.State.CurrentSide == CombatSide.Player) ? turnState.State.Players.ToList() : new List<Player>());
				}
			}
			foreach (Creature item in creaturesStartingTurn)
			{
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				item.BeforeTurnStart(turnState.State.CurrentSide);
			}
			await Hook.BeforeSideTurnStart(turnState.State, turnState.State.CurrentSide, creaturesStartingTurn);
			turnState.Ct.ThrowIfCancellationRequested();
			if (turnState.State.CurrentSide == CombatSide.Player)
			{
				SetPhaseForAllPlayers(turnState.State, PlayerTurnPhase.Start);
				PlayerActionsDisabled = false;
				using (turnState.ReadyLock.EnterScope())
				{
					turnState.PlayersReadyToEndTurn.Clear();
					turnState.PlayersReadyToBeginEnemyTurn.Clear();
					turnState.EndTurnSignalSource = new TaskCompletionSource<EndTurnSignal>();
					turnState.BeginEnemyTurnSignalSource = new TaskCompletionSource<Func<Task>>();
				}
				int num = LocalContext.GetMe(playersStartingTurn)?.PlayerCombatState?.TurnNumber ?? (-1);
				if (num > 1)
				{
					NCombatRoom.Instance?.AddChildSafely(NPlayerTurnBanner.Create(num));
				}
				if (!isExtraPlayerTurn)
				{
					foreach (Creature enemy in turnState.State.Enemies)
					{
						enemy.PrepareForNextTurn(turnState.State.PlayerCreatures);
					}
				}
			}
			else
			{
				NCombatRoom.Instance?.AddChildSafely(NEnemyTurnBanner.Create());
			}
			await Cmd.CustomScaledWait(0.5f, 0.8f);
			turnState.Ct.ThrowIfCancellationRequested();
			foreach (Creature item2 in creaturesStartingTurn)
			{
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				await item2.AfterTurnStart(turnState.State.CurrentSide);
				turnState.Ct.ThrowIfCancellationRequested();
			}
			foreach (Creature item3 in creaturesStartingTurn)
			{
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				await Hook.AfterBlockCleared(turnState.State, item3);
				turnState.Ct.ThrowIfCancellationRequested();
			}
			List<(HookPlayerChoiceContext, Task)> setupPlayerTurnContext = new List<(HookPlayerChoiceContext, Task)>();
			foreach (Player item4 in playersStartingTurn)
			{
				if (LocalContext.NetId.HasValue)
				{
					HookPlayerChoiceContext playerChoiceContext = new HookPlayerChoiceContext(item4, LocalContext.NetId.Value, GameActionType.CombatPlayPhaseOnly);
					Task task = SetupPlayerTurn(turnState, item4, playerChoiceContext);
					await playerChoiceContext.WaitForPauseOrCompletionWithoutAssigningTask(task);
					turnState.Ct.ThrowIfCancellationRequested();
					setupPlayerTurnContext.Add((playerChoiceContext, task));
				}
			}
			await Hook.AfterSideTurnStart(turnState.State, turnState.State.CurrentSide, creaturesStartingTurn);
			turnState.Ct.ThrowIfCancellationRequested();
			if (turnState.State.CurrentSide == CombatSide.Player)
			{
				foreach (Player item5 in playersStartingTurn)
				{
					if (item5.PlayerCombatState != null && LocalContext.NetId.HasValue)
					{
						HookPlayerChoiceContext hookPlayerChoiceContext = new HookPlayerChoiceContext(item5, LocalContext.NetId.Value, GameActionType.CombatPlayPhaseOnly);
						Task task2 = item5.PlayerCombatState.OrbQueue.AfterTurnStart(hookPlayerChoiceContext);
						await hookPlayerChoiceContext.AssignTaskAndWaitForPauseOrCompletion(task2);
						turnState.Ct.ThrowIfCancellationRequested();
					}
				}
				RunManager.Instance.ChecksumTracker.GenerateChecksum("After player turn start", null);
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				foreach (Player player2 in turnState.State.Players)
				{
					if (player2.Creature.IsDead || !playersStartingTurn.Contains(player2))
					{
						Log.Info($"Setting player {player2.NetId} to ready at start of turn. IsDead: {player2.Creature.IsDead}. IsStartingTurn: {playersStartingTurn.Contains(player2)}");
						SetReadyToEndTurn(player2, canBackOut: false);
						if (AllPlayersReadyToEndTurn(turnState))
						{
							return;
						}
					}
				}
				foreach (var (player, (hookPlayerChoiceContext2, setupPlayerTurnTask)) in playersStartingTurn.Zip(setupPlayerTurnContext))
				{
					if (turnState.Ct.IsCancellationRequested)
					{
						return;
					}
					if (!player.Creature.IsDead)
					{
						Task task3 = RunAutoPrePlayPhase(turnState, hookPlayerChoiceContext2, setupPlayerTurnTask, player);
						await hookPlayerChoiceContext2.AssignTaskAndWaitForPauseOrCompletion(task3);
						turnState.Ct.ThrowIfCancellationRequested();
					}
				}
				await CheckWinCondition(turnState);
				turnState.Ct.ThrowIfCancellationRequested();
				if (turnState.IsInProgress)
				{
					RunManager.Instance.ActionExecutor.Unpause();
					RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.PlayPhase);
					turnState.IsEnemyTurnStarted = false;
					TurnStarted?.Invoke(turnState.State);
				}
			}
			else
			{
				turnState.IsEnemyTurnStarted = true;
				TurnStarted?.Invoke(turnState.State);
				RunManager.Instance.ChecksumTracker.GenerateChecksum("After enemy turn start", null);
				await WaitForUnpause(turnState);
				turnState.Ct.ThrowIfCancellationRequested();
				await CheckWinCondition(turnState);
				turnState.Ct.ThrowIfCancellationRequested();
				if (turnState.IsInProgress)
				{
					await ExecuteEnemyTurn(turnState, actionDuringEnemyTurn);
				}
			}
		}

		/// <summary>
		/// Awaits the player's setup task, then runs the auto-pre-play hooks, transitioning the player's phase
		/// from <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.Start" /> -&gt; <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.AutoPrePlay" /> -&gt; <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.Play" />.
		/// The setup await ensures a player whose setup is paused (making a <see cref="T:MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext" />)
		/// stays in <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.Start" /> until their setup actually completes.
		/// </summary>
		private async Task RunAutoPrePlayPhase(CombatTurnState turnState, HookPlayerChoiceContext playerChoiceContext, Task setupPlayerTurnTask, Player player)
		{
			await setupPlayerTurnTask;
			player.PlayerCombatState.Phase = PlayerTurnPhase.AutoPrePlay;
			await CheckForEmptyHand(turnState, playerChoiceContext, player);
			await Hook.AfterAutoPrePlayPhaseEntered(playerChoiceContext, turnState.State, player);
			player.PlayerCombatState.Phase = PlayerTurnPhase.Play;
		}

		/// <summary>
		/// Sets up a player's turn by resetting energy, drawing cards, and firing start-of-turn hooks.
		/// If the player's turn start executes a player choice (e.g. Mayhem plays Cosmic Indifference), then the entire
		/// sequence is paused for this player. However, other players' turn start sequences may continue, and they may
		/// play cards while this is occuring.
		/// </summary>
		/// <param name="turnState">The turn state of the combat this turn belongs to.</param>
		/// <param name="player">The player whose turn to setup.</param>
		/// <param name="playerChoiceContext">The player choice context to pass to hooks that take it.</param>
		private async Task SetupPlayerTurn(CombatTurnState turnState, Player player, HookPlayerChoiceContext playerChoiceContext)
		{
			if (player.Creature.IsDead)
			{
				return;
			}
			if (player.PlayerCombatState == null)
			{
				Log.Warn($"Player combat state is null. Assuming that the run has been cleaned up. (Player: {player.NetId})");
				return;
			}
			CombatState state = turnState.State;
			if (Hook.ShouldPlayerResetEnergy(state, player))
			{
				SfxCmd.Play("event:/sfx/ui/gain_energy");
				player.PlayerCombatState.ResetEnergy();
			}
			else
			{
				player.PlayerCombatState.AddMaxEnergyToCurrent();
			}
			await Hook.AfterEnergyReset(state, player);
			turnState.Ct.ThrowIfCancellationRequested();
			await Hook.BeforeHandDraw(state, player, playerChoiceContext);
			turnState.Ct.ThrowIfCancellationRequested();
			decimal handDraw = Hook.ModifyHandDraw(state, player, 5m, out IEnumerable<AbstractModel> modifiers);
			await Hook.AfterModifyingHandDraw(state, modifiers);
			turnState.Ct.ThrowIfCancellationRequested();
			if (player.PlayerCombatState.TurnNumber == 1)
			{
				CardPile pile = PileType.Draw.GetPile(player);
				List<CardModel> list = pile.Cards.Where((CardModel c) => c.Enchantment?.ShouldStartAtBottomOfDrawPile ?? false).ToList();
				foreach (CardModel item in list)
				{
					pile.MoveToBottomInternal(item);
				}
				List<CardModel> list2 = pile.Cards.Where((CardModel c) => c.Keywords.Contains(CardKeyword.Innate)).Except(list).ToList();
				foreach (CardModel item2 in list2)
				{
					pile.MoveToTopInternal(item2);
				}
				handDraw = Math.Max(handDraw, list2.Count);
				handDraw = Math.Min(handDraw, CardPile.MaxCardsInHand);
			}
			await CardPileCmd.Draw(playerChoiceContext, handDraw, player, fromHandDraw: true);
			turnState.Ct.ThrowIfCancellationRequested();
			await Hook.AfterPlayerTurnStart(state, playerChoiceContext, player);
		}

		/// <summary>
		/// Called in EndPlayerTurnAction to indicate that the player is ready to execute end-of-turn events.
		/// </summary>
		/// <param name="player">The player that readied up.</param>
		/// <param name="canBackOut">In multiplayer, notes if the player is allowed to back out of ending their turn.</param>
		/// <param name="actionDuringEnemyTurn">Optional action to execute during the enemy turn. This is useful for tests.</param>
		public void SetReadyToEndTurn(Player player, bool canBackOut, Func<Task>? actionDuringEnemyTurn = null)
		{
			CombatTurnState turnState = _turnState;
			if (turnState == null)
			{
				return;
			}
			using (turnState.ReadyLock.EnterScope())
			{
				if (turnState.PlayersReadyToEndTurn.Contains(player))
				{
					return;
				}
				turnState.PlayersReadyToEndTurn.Add(player);
			}
			PlayerEndedTurn?.Invoke(player, canBackOut);
			if (AllPlayersReadyToEndTurn(turnState))
			{
				Log.Debug("All players ready to end turn");
				GameAction gameAction = RunManager.Instance.ActionExecutor.CurrentlyRunningAction;
				if (gameAction != null && !ActionQueueSet.IsGameActionPlayerDriven(gameAction))
				{
					gameAction = null;
				}
				int scheduledTurnNumber = player.PlayerCombatState?.TurnNumber ?? (-1);
				TaskCompletionSource<EndTurnSignal> endTurnSignalSource;
				using (turnState.ReadyLock.EnterScope())
				{
					endTurnSignalSource = turnState.EndTurnSignalSource;
				}
				endTurnSignalSource?.TrySetResult(new EndTurnSignal(gameAction, scheduledTurnNumber, player, actionDuringEnemyTurn));
			}
		}

		public void UndoReadyToEndTurn(Player player)
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null)
			{
				using (turnState.ReadyLock.EnterScope())
				{
					turnState.PlayersReadyToEndTurn.Remove(player);
				}
			}
			if (LocalContext.IsMe(player))
			{
				PlayerActionsDisabled = false;
			}
			PlayerUnendedTurn?.Invoke(player);
		}

		/// <summary>
		/// Call this when the end turn button is pressed to disable local player actions until the start of the next turn.
		/// In multiplayer, this prevents the player from playing cards after they have ended turn.
		/// In both SP and MP, this prevents the player from playing cards before the AfterTurnStart hook has run.
		/// It's important that we do this when the end turn button is pressed, instead of when the EndTurnAction is
		/// processed, because the player might try to execute actions while the end turn action is waiting in the queue.
		/// This is a little fragile; if actions do slip through in MP, it has the potential to cause a state divergence.
		/// Revisit if needed - we might need to discard actions on the host side (which ends up being way more complicated).
		/// </summary>
		public void OnEndedTurnLocally()
		{
			PlayerActionsDisabled = true;
		}

		/// <summary>
		/// Called in ReadyToBeginEnemyTurnAction to indicate that the player is ready to switch to the monster turn (or
		/// extra player turn, if necessary). Note that this is called automatically, and is not player-driven.
		/// </summary>
		/// <param name="player">The player that is ready to switch sides.</param>
		/// <param name="actionDuringEnemyTurn">Optional action to execute during the enemy turn. This is useful for tests.</param>
		public void SetReadyToBeginEnemyTurn(Player player, Func<Task>? actionDuringEnemyTurn = null)
		{
			CombatTurnState turnState = _turnState;
			if (turnState == null || !turnState.IsInProgress)
			{
				Log.Error("Trying to set player ready to begin enemy turn, but combat is over!");
				return;
			}
			bool flag2;
			TaskCompletionSource<Func<Task>> beginEnemyTurnSignalSource;
			using (turnState.ReadyLock.EnterScope())
			{
				if (!turnState.PlayersReadyToBeginEnemyTurn.Add(player))
				{
					return;
				}
				bool flag = turnState.State.CurrentSide == CombatSide.Player;
				flag2 = ((turnState.PlayersReadyToBeginEnemyTurn.Count == turnState.State.Players.Count) & flag) || (flag && RunManager.Instance.NetService.Type == NetGameType.Singleplayer);
				beginEnemyTurnSignalSource = turnState.BeginEnemyTurnSignalSource;
			}
			if (flag2 && beginEnemyTurnSignalSource != null && !beginEnemyTurnSignalSource.TrySetResult(actionDuringEnemyTurn))
			{
				Log.Warn($"Ignoring ready-to-begin-enemy-turn for player {player.NetId}: a player-to-enemy transition has already been claimed for this turn.");
			}
		}

		/// <returns>
		/// True if the passed player has hit the end turn button, and the next player turn has not yet begun.
		/// </returns>
		public bool IsPlayerReadyToEndTurn(Player player)
		{
			CombatTurnState turnState = _turnState;
			if (turnState == null)
			{
				return false;
			}
			using (turnState.ReadyLock.EnterScope())
			{
				return turnState.PlayersReadyToEndTurn.Contains(player);
			}
		}

		public bool AllPlayersReadyToEndTurn()
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null)
			{
				return AllPlayersReadyToEndTurn(turnState);
			}
			return false;
		}

		private bool AllPlayersReadyToEndTurn(CombatTurnState turnState)
		{
			bool flag;
			using (turnState.ReadyLock.EnterScope())
			{
				flag = turnState.PlayersReadyToEndTurn.Count == turnState.State.Players.Count;
			}
			if (!RunManager.Instance.IsSingleplayerOrFakeMultiplayer)
			{
				if (flag)
				{
					return turnState.State.CurrentSide == CombatSide.Player;
				}
				return false;
			}
			return true;
		}

		private async Task EndEnemyTurn(CombatTurnState turnState)
		{
			if (turnState.IsInProgress)
			{
				turnState.Ct.ThrowIfCancellationRequested();
				if (turnState.State.CurrentSide != CombatSide.Enemy)
				{
					throw new InvalidOperationException($"EndEnemyTurn called while the current side is {turnState.State.CurrentSide}!");
				}
				await WaitForUnpause(turnState);
				turnState.Ct.ThrowIfCancellationRequested();
				await EndEnemyTurnInternal(turnState);
				turnState.Ct.ThrowIfCancellationRequested();
				await CheckWinCondition(turnState);
				if (!IsCombatEnding(turnState))
				{
					SwitchSides(turnState);
					await WaitForUnpause(turnState);
					turnState.Ct.ThrowIfCancellationRequested();
				}
			}
		}

		public void AddCreature(Creature creature)
		{
			CombatState state = _turnState.State;
			if (!state.ContainsCreature(creature))
			{
				throw new InvalidOperationException("CombatState must already contain creature.");
			}
			creature.Monster?.SetUpForCombat();
			if (creature.SlotName != null)
			{
				state.SortEnemiesBySlotName();
			}
			StateTracker.Subscribe(creature);
			CreaturesChanged?.Invoke(state);
		}

		/// <summary>
		/// Called after both the Creature has been added to the room _and_ the NCreature is spawned.
		/// </summary>
		/// <param name="creature"></param>
		public Task AfterCreatureAdded(Creature creature)
		{
			return AfterCreatureAdded(creature, _turnState.State);
		}

		/// <summary>
		/// Turn-state-relative variant for the turn loop's setup loop: reads the turn loop's own combat, so a setup continuation
		/// resuming after its combat was torn down cannot observe a null state or the next combat's players.
		/// </summary>
		private static async Task AfterCreatureAdded(Creature creature, CombatState state)
		{
			await creature.AfterAddedToRoom();
			if (creature.IsEnemy && state.CurrentSide == CombatSide.Player)
			{
				creature.Monster.RollMove(state.Players.Select((Player p) => p.Creature));
			}
		}

		/// <summary>
		/// Check for the player's hand to be empty and run the appropriate hooks if it is.
		///
		/// We can't just do this check every time the hand size changes, because sometimes we're in the middle of a
		/// sequence of effects and we want to wait to check until they're all done.
		///
		/// For example, if we have <see cref="T:MegaCrit.Sts2.Core.Models.Relics.UnceasingTop" /> and the last card in our hand is <see cref="T:MegaCrit.Sts2.Core.Models.Cards.PommelStrike" />
		/// and we play it, we have to wait to check hand size until Pommel Strike is done being played, otherwise we'll
		/// draw two cards (one when your hand becomes "empty" immediately after Pommel Strike moves to the Play pile, and
		/// another after Pommel Strike's draw command executes).
		///
		/// So, instead of automatically doing this check every time the hand size changes, we manually check after a card
		/// is played, and after a potion is used, since these are the two ways a player can manually interact with combat
		/// state (besides ending turn, which should not trigger an empty hand check). We also check once at the start of
		/// the play-capable phase (see <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.RunAutoPrePlayPhase(MegaCrit.Sts2.Core.Combat.CombatTurnState,MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext,System.Threading.Tasks.Task,MegaCrit.Sts2.Core.Entities.Players.Player)" />), to catch a hand draw that ends empty because
		/// every card was auto-played as it was drawn. If we ever add more ways, we should add this check in those too,
		/// and update this comment.
		/// </summary>
		/// <param name="choiceContext">Object that keeps context of the action this is called from.</param>
		/// <param name="player">Player whose hand we want to check.</param>
		/// <param name="combatId">
		/// The combat the calling effect belongs to, from <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.BeginCardOrPotionEffect(MegaCrit.Sts2.Core.Entities.Players.Player)" />. The check is dropped if
		/// that combat is no longer the running one: a card played in a combat that ended must not empty-hand-hook into
		/// the next one.
		/// </param>
		public async Task CheckForEmptyHand(CombatId? combatId, PlayerChoiceContext choiceContext, Player player)
		{
			CombatTurnState combatTurnState = LiveTurnStateFor(combatId);
			if (combatTurnState != null)
			{
				await CheckForEmptyHand(combatTurnState, choiceContext, player);
			}
		}

		/// <summary>
		/// Turn-state-relative variant for the turn loop, which owns a turn state directly and needs no id round trip.
		/// </summary>
		private async Task CheckForEmptyHand(CombatTurnState turnState, PlayerChoiceContext choiceContext, Player player)
		{
			if (turnState.IsInProgress && !IsExecutingCardOrPotionEffect(player) && !PileType.Hand.GetPile(player).Cards.Any())
			{
				await Hook.AfterHandEmptied(turnState.State, choiceContext, player);
			}
		}

		/// <summary>
		/// Reset the combat manager to prepare for the next combat. All combat-scoped state lives on the turn state, which is
		/// dropped wholesale here; the only per-field cleanup left is manager-level state that outlives a single combat.
		/// </summary>
		/// <param name="graceful">Usually true. Only pass false if we're exiting the game completely.</param>
		public void Reset(bool graceful)
		{
			CombatTurnState turnState = _turnState;
			if (graceful && turnState != null)
			{
				SetPhaseForAllPlayers(turnState.State, PlayerTurnPhase.None);
				foreach (Creature item in turnState.State.Creatures.ToList())
				{
					item.Reset();
					RemoveCreature(item);
					turnState.State.RemoveCreature(item);
				}
			}
			_turnState = null;
			DebugForcedTopCardOnNextShuffle = null;
			History.Clear();
			_cardOrPotionEffectDepth.Clear();
			if (turnState != null)
			{
				Log.Debug($"Combat #{turnState.Id} dropped and cancelled by Reset");
				turnState.Cancel();
			}
			RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.NotInCombat);
		}

		/// <summary>
		/// Per-player death handling for one player dying in a combat the rest of the party is still fighting: their cards
		/// leave combat and their resources are zeroed. Does nothing once every player is dead, which is the run-loss path.
		/// </summary>
		/// <param name="combatId">
		/// The combat the kill belongs to. Death handling for a combat that has already ended must not run against the
		/// next one.
		/// </param>
		/// <param name="player">The player that died.</param>
		public async Task HandlePlayerDeath(CombatId? combatId, Player player)
		{
			CombatTurnState combatTurnState = LiveTurnStateFor(combatId);
			if (combatTurnState != null && !combatTurnState.State.Players.All((Player p) => p.Creature.IsDead))
			{
				Log.Info($"Player {player.NetId} died, doing death handling");
				if (!IsExecutingCardOrPotionEffect(player))
				{
					await RemoveDeadPlayerCardsFromCombat(combatId, player);
				}
				await PlayerCmd.SetEnergy(0m, player);
				await PlayerCmd.SetStars(0m, player);
			}
		}

		/// <summary>
		/// Removes a dead player's cards from combat. Runs from <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.HandlePlayerDeath(System.Nullable{MegaCrit.Sts2.Core.Combat.CombatId},MegaCrit.Sts2.Core.Entities.Players.Player)" /> when the player is not
		/// mid-effect, otherwise deferred to when their outermost card or potion effect ends.
		/// </summary>
		/// <param name="combatId">
		/// The combat the death belongs to. A removal deferred past the end of its combat must not strip the next
		/// combat's cards.
		/// </param>
		/// <param name="player">The dead player whose cards are being removed.</param>
		public async Task RemoveDeadPlayerCardsFromCombat(CombatId? combatId, Player player)
		{
			CombatTurnState combatTurnState = LiveTurnStateFor(combatId);
			if (combatTurnState != null && player.PlayerCombatState != null && !combatTurnState.State.Players.All((Player p) => p.Creature.IsDead))
			{
				List<CardModel> list = new List<CardModel>();
				list.AddRange(player.PlayerCombatState.Hand.Cards);
				list.AddRange(player.PlayerCombatState.DrawPile.Cards);
				list.AddRange(player.PlayerCombatState.DiscardPile.Cards);
				list.AddRange(player.PlayerCombatState.ExhaustPile.Cards);
				list.AddRange(player.PlayerCombatState.PlayPile.Cards);
				CardModel[] cards = list.ToArray();
				await CardPileCmd.RemoveFromCombat(cards);
			}
		}

		/// <summary>
		/// Marks combat as pending loss. The actual loss processing happens at the next safe point
		/// (in CheckWinCondition) to avoid race conditions where effects try to run after IsInProgress is false.
		/// </summary>
		public void LoseCombat()
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null && !(turnState.PendingLoss != null))
			{
				turnState.PendingLoss = new PendingLossState((CombatRoom)turnState.State.RunState.CurrentRoom);
			}
		}

		/// <summary>
		/// Processes a pending combat loss. Called from CheckWinCondition at safe points.
		/// </summary>
		private void ProcessPendingLoss(CombatTurnState turnState)
		{
			if (!(turnState.PendingLoss == null))
			{
				PendingLossState pendingLoss = turnState.PendingLoss;
				turnState.PendingLoss = null;
				turnState.IsInProgress = false;
				CombatEnded?.Invoke(pendingLoss.Room);
			}
		}

		/// <summary>
		/// Prefer ModelTest.WinCombat.
		/// </summary>
		internal async Task EndCombatInternal()
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null)
			{
				await EndCombatInternal(turnState);
			}
		}

		private async Task EndCombatInternal(CombatTurnState turnState)
		{
			CombatState combatState = turnState.State;
			Player localPlayer = LocalContext.GetMe(combatState);
			int turnsTaken = localPlayer.PlayerCombatState.TurnNumber;
			IRunState runState = combatState.RunState;
			CombatRoom room = (CombatRoom)runState.CurrentRoom;
			turnState.IsInProgress = false;
			using (turnState.ReadyLock.EnterScope())
			{
				turnState.PlayersTakingExtraTurn.Clear();
			}
			SetPhaseForAllPlayers(combatState, PlayerTurnPhase.None);
			PlayerActionsDisabled = false;
			foreach (Player player in combatState.Players)
			{
				await player.ReviveBeforeCombatEnd();
			}
			await Hook.AfterCombatEnd(runState, combatState, room);
			History.Clear();
			room.OnCombatEnded();
			if (RunManager.Instance.NetService.Type != NetGameType.Replay)
			{
				RunManager.Instance.WriteReplay(stopRecording: true);
			}
			foreach (Player player2 in combatState.Players)
			{
				player2.AfterCombatEnd();
			}
			await Hook.AfterCombatVictory(runState, combatState, room);
			NHoverTipSet.Clear();
			if (runState.CurrentMapPointHistoryEntry != null)
			{
				runState.CurrentMapPointHistoryEntry.Rooms.Last().TurnsTaken = turnsTaken;
			}
			bool flag = runState.Map.SecondBossMapPoint != null && runState.CurrentMapCoord == runState.Map.SecondBossMapPoint.coord;
			bool flag2 = runState.Map.SecondBossMapPoint == null && runState.CurrentMapCoord == runState.Map.BossMapPoint.coord;
			if (room.RoomType == RoomType.Boss && runState.CurrentActIndex == runState.Acts.Count - 1 && (flag | flag2))
			{
				RunManager.Instance.WinTime = RunManager.Instance.RunTime;
			}
			room.MarkPreFinished();
			await SaveManager.Instance.SaveRun(room, saveProgress: false);
			NMapScreen.Instance?.SetTravelEnabled(enabled: true);
			SaveManager.Instance.UpdateProgressAfterCombatWon(localPlayer, room);
			AchievementsHelper.CheckForDefeatedAllEnemiesAchievement(runState.Act, localPlayer);
			SaveManager.Instance.SaveProgressFile();
			if (room.RoomType == RoomType.Boss)
			{
				AchievementsHelper.AfterBossDefeated(localPlayer);
			}
			combatState.MultiplayerScalingModel?.OnCombatFinished();
			if (_turnState != null)
			{
				CombatWon?.Invoke(room);
			}
			RunManager.Instance.ActionExecutor.Unpause();
			RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.NotInCombat);
			NRunMusicController.Instance?.UpdateTrack();
			if (_turnState != null)
			{
				CombatEnded?.Invoke(room);
			}
		}

		public void RemoveCreature(Creature creature)
		{
			if (creature.IsMonster)
			{
				creature.Monster.BeforeRemovedFromRoom();
				creature.Monster.ResetStateMachine();
			}
			StateTracker.Unsubscribe(creature);
			CreaturesChanged?.Invoke(_turnState.State);
		}

		public async Task<bool> CheckWinCondition()
		{
			CombatTurnState turnState = _turnState;
			if (turnState == null)
			{
				return false;
			}
			return await CheckWinCondition(turnState);
		}

		/// <summary>
		/// Turn-state-relative variant for the turn loop: a stale turn state resuming here evaluates and can only end its own
		/// dead combat (a no-op), never the current one.
		/// </summary>
		private async Task<bool> CheckWinCondition(CombatTurnState turnState)
		{
			if (turnState.PendingLoss != null)
			{
				ProcessPendingLoss(turnState);
				return true;
			}
			if (IsCombatEnding(turnState))
			{
				await EndCombatInternal(turnState);
				return true;
			}
			return false;
		}

		private async Task ExecuteEnemyTurn(CombatTurnState turnState, Func<Task>? actionDuringEnemyTurn = null)
		{
			if (!turnState.IsInProgress)
			{
				return;
			}
			turnState.Ct.ThrowIfCancellationRequested();
			if (actionDuringEnemyTurn != null)
			{
				await actionDuringEnemyTurn();
				turnState.Ct.ThrowIfCancellationRequested();
			}
			foreach (Creature enemy in turnState.State.Enemies.ToList())
			{
				if (turnState.State.ContainsCreature(enemy))
				{
					NCreature nCreature = NCombatRoom.Instance?.GetCreatureNode(enemy);
					if (nCreature != null)
					{
						await nCreature.PerformIntent();
					}
					await enemy.TakeTurn();
					turnState.Ct.ThrowIfCancellationRequested();
					await WaitForUnpause(turnState);
					await CheckWinCondition(turnState);
					if (!turnState.IsInProgress)
					{
						return;
					}
				}
			}
			RunManager.Instance.ChecksumTracker.GenerateChecksum("After enemy turn end", null);
			await EndEnemyTurn(turnState);
		}

		private async Task AfterAllPlayersReadyToEndTurn(CombatTurnState turnState, EndTurnSignal signal)
		{
			if (!turnState.IsInProgress)
			{
				return;
			}
			if ((signal.ScheduledPlayer.PlayerCombatState?.TurnNumber ?? (-1)) != signal.ScheduledTurnNumber)
			{
				Log.Error($"Combat #{turnState.Id}: stale player-turn-end transition for player {signal.ScheduledPlayer.NetId}: the turn it was scheduled for has ended. Running it anyway; only the turn loop advances turns, so something has resumed a turn the turn loop did not.");
				if (!_staleTurnEndReported)
				{
					_staleTurnEndReported = true;
					SentryService.CaptureMessage("Ran a stale player-turn-end transition; the turn it was scheduled for had ended", SentryLevel.Error, delegate(Scope scope)
					{
						scope.SetExtra("combatId", turnState.Id.Value);
						scope.SetExtra("scheduledTurnNumber", signal.ScheduledTurnNumber);
						scope.SetExtra("currentTurnNumber", signal.ScheduledPlayer.PlayerCombatState?.TurnNumber ?? (-1));
					});
				}
			}
			turnState.Ct.ThrowIfCancellationRequested();
			turnState.EndingPlayerTurnPhaseOne = true;
			try
			{
				RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.EndTurnPhaseOne);
				await WaitUntilQueueIsEmptyOrWaitingOnNonPlayerDrivenAction(turnState);
				await EndPlayerTurnPhaseOneInternal(turnState);
				if (turnState.IsInProgress && RunManager.Instance.NetService.Type != NetGameType.Replay)
				{
					RunManager.Instance.ActionQueueSynchronizer.RequestEnqueue(new ReadyToBeginEnemyTurnAction(LocalContext.GetMe(turnState.State), signal.ActionDuringEnemyTurn));
				}
			}
			finally
			{
				turnState.EndingPlayerTurnPhaseOne = false;
			}
		}

		private async Task WaitUntilQueueIsEmptyOrWaitingOnNonPlayerDrivenAction(CombatTurnState turnState)
		{
			GameAction currentlyRunningAction = RunManager.Instance.ActionExecutor.CurrentlyRunningAction;
			if (currentlyRunningAction == null || !ActionQueueSet.IsGameActionPlayerDriven(currentlyRunningAction))
			{
				return;
			}
			TaskCompletionSource completionSource = new TaskCompletionSource();
			RunManager.Instance.ActionExecutor.AfterActionExecuted += AfterActionExecuted;
			try
			{
				await completionSource.Task.WaitAsync(turnState.Ct);
			}
			finally
			{
				RunManager.Instance.ActionExecutor.AfterActionExecuted -= AfterActionExecuted;
			}
			void AfterActionExecuted(GameAction action)
			{
				GameAction readyAction = RunManager.Instance.ActionQueueSet.GetReadyAction();
				if (readyAction == null || !ActionQueueSet.IsGameActionPlayerDriven(readyAction))
				{
					completionSource.TrySetResult();
				}
			}
		}

		/// <summary>
		/// Calls all end-of-turn hooks that could require player choices to be made.
		/// Prefer ModelTest.PassToEnemyTurn, whose doc comment covers when the bypass is safe.
		/// </summary>
		internal async Task EndPlayerTurnPhaseOneInternal()
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null)
			{
				await EndPlayerTurnPhaseOneInternal(turnState);
			}
		}

		private async Task EndPlayerTurnPhaseOneInternal(CombatTurnState turnState)
		{
			if (turnState.Ct.IsCancellationRequested)
			{
				return;
			}
			if (turnState.State.CurrentSide != CombatSide.Player)
			{
				throw new InvalidOperationException($"EndPlayerTurn called while the current side is {turnState.State.CurrentSide}!");
			}
			await WaitForUnpause(turnState);
			List<Player> playersEndingTurn;
			using (turnState.ReadyLock.EnterScope())
			{
				playersEndingTurn = ((turnState.PlayersTakingExtraTurn.Count > 0) ? turnState.PlayersTakingExtraTurn.ToList() : turnState.State.Players.ToList());
			}
			List<(Player, HookPlayerChoiceContext)> autoPostPlayContexts = new List<(Player, HookPlayerChoiceContext)>();
			foreach (Player player in playersEndingTurn)
			{
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				if (LocalContext.NetId.HasValue)
				{
					player.PlayerCombatState.Phase = PlayerTurnPhase.AutoPostPlay;
					HookPlayerChoiceContext playerChoiceContext = new HookPlayerChoiceContext(player, LocalContext.NetId.Value, GameActionType.CombatPlayPhaseOnly);
					Task task = Hook.AfterAutoPostPlayPhaseEntered(playerChoiceContext, turnState.State, player);
					await playerChoiceContext.AssignTaskAndWaitForPauseOrCompletion(task);
					autoPostPlayContexts.Add((player, playerChoiceContext));
				}
			}
			foreach (var (player, hookPlayerChoiceContext) in autoPostPlayContexts)
			{
				await hookPlayerChoiceContext.WaitForCompletion();
				player.PlayerCombatState.Phase = PlayerTurnPhase.End;
			}
			if (turnState.Ct.IsCancellationRequested)
			{
				return;
			}
			await Hook.BeforeSideTurnEnd(turnState.State, turnState.State.CurrentSide, playersEndingTurn.Select((Player p) => p.Creature));
			if (await CheckWinCondition(turnState))
			{
				return;
			}
			List<HookPlayerChoiceContext> playerEndContexts = new List<HookPlayerChoiceContext>();
			foreach (Player item in playersEndingTurn)
			{
				if (LocalContext.NetId.HasValue)
				{
					HookPlayerChoiceContext playerChoiceContext = new HookPlayerChoiceContext(item, LocalContext.NetId.Value, GameActionType.Combat);
					Task task2 = DoTurnEnd(turnState, item, playerChoiceContext);
					await playerChoiceContext.AssignTaskAndWaitForPauseOrCompletion(task2);
					playerEndContexts.Add(playerChoiceContext);
				}
			}
			foreach (HookPlayerChoiceContext item2 in playerEndContexts)
			{
				await item2.WaitForCompletion();
			}
			if (await CheckWinCondition(turnState))
			{
				return;
			}
			if (!turnState.Ct.IsCancellationRequested)
			{
				foreach (Player item3 in playersEndingTurn)
				{
					await Hook.BeforeFlush(turnState.State, item3);
				}
			}
			RunManager.Instance.ChecksumTracker.GenerateChecksum("After player turn phase one end", null);
			await CheckWinCondition(turnState);
		}

		/// <summary>
		/// Executes turn end hooks for a player.
		/// If player choice occurs during this method, it uses the passed choice context. This way, each player's turn end
		/// runs independently of all others.
		/// </summary>
		/// <param name="turnState">The turn state for the current combat.</param>
		/// <param name="player">The player whose turn is ending.</param>
		/// <param name="choiceContext">The context to use for any player choices.</param>
		private async Task DoTurnEnd(CombatTurnState turnState, Player player, PlayerChoiceContext choiceContext)
		{
			await player.PlayerCombatState.OrbQueue.BeforeTurnEnd(choiceContext);
			if (!turnState.IsInProgress || IsCombatEnding(turnState))
			{
				return;
			}
			CardPile pile = PileType.Hand.GetPile(player);
			List<CardModel> turnEndCards = new List<CardModel>();
			List<CardModel> list = new List<CardModel>();
			foreach (CardModel card in pile.Cards)
			{
				if (card.HasTurnEndInHandEffect)
				{
					turnEndCards.Add(card);
				}
				else if (card.Keywords.Contains(CardKeyword.Ethereal) && Hook.ShouldEtherealTrigger(player.Creature.CombatState, card))
				{
					list.Add(card);
				}
			}
			foreach (CardModel item in list)
			{
				await CardCmd.Exhaust(choiceContext, item, causedByEthereal: true);
			}
			await DoTurnEndCards(turnState, turnEndCards, choiceContext);
		}

		/// <summary>
		/// Invokes turn end effects on all cards in hand with such an effect.
		/// Does some timing trickery so that the cards don't fly in one-by-one with linear timing.
		/// Player choices can happen in between turn end resolutions. It is very rare, so I've ignored it for now, but the
		/// UX for it is a little weird. Ideally it should pause the entire sequence.
		/// </summary>
		private async Task DoTurnEndCards(CombatTurnState turnState, List<CardModel> turnEndCards, PlayerChoiceContext choiceContext)
		{
			Task task = null;
			List<Task> list = new List<Task>();
			float num = 0f;
			int num2 = 0;
			foreach (CardModel turnEndCard in turnEndCards)
			{
				Task task2 = AddTurnEndCardToPlayPileWithDelay(turnEndCard, num);
				Task waitTask = task2;
				if (task != null)
				{
					global::<>y__InlineArray2<Task> buffer = default(global::<>y__InlineArray2<Task>);
					buffer[0] = task2;
					buffer[1] = task;
					waitTask = Task.WhenAll(buffer);
				}
				Task<CardPileAddResult?> task3 = ResolveTurnEndCardEffects(turnEndCard, choiceContext, waitTask);
				Task item = TweenTurnEndCardToResultPile(turnState, task3);
				list.Add(item);
				task = task3;
				float num3 = 1f - (float)num2 / ((float)num2 + 3f);
				float num4 = (LocalContext.IsMine(turnEndCard) ? ((SaveManager.Instance.PrefsSave.FastMode == FastModeType.Fast) ? 0.4f : 0.8f) : 0.3f);
				num += num4 * num3;
				num2++;
			}
			await Task.WhenAll(list);
		}

		private async Task AddTurnEndCardToPlayPileWithDelay(CardModel card, float delay)
		{
			await Cmd.Wait(delay);
			await CardPileCmd.Add(card, PileType.Play);
		}

		private async Task<CardPileAddResult?> ResolveTurnEndCardEffects(CardModel card, PlayerChoiceContext choiceContext, Task waitTask)
		{
			await waitTask;
			await card.OnTurnEndInHandWrapper(choiceContext);
			return (!card.Keywords.Contains(CardKeyword.Ethereal)) ? new CardPileAddResult?(await CardPileCmd.Add(card, PileType.Discard.GetPile(card.Owner), CardPilePosition.Bottom, null, skipVisuals: true)) : (await CardCmd.Exhaust(choiceContext, card, causedByEthereal: true, skipVisuals: true));
		}

		private async Task TweenTurnEndCardToResultPile(CombatTurnState turnState, Task<CardPileAddResult?> resultTask)
		{
			CardPileAddResult? cardPileAddResult = await resultTask;
			if (cardPileAddResult.HasValue && cardPileAddResult.GetValueOrDefault().success)
			{
				Tween item = CardPileCmd.GetTweenForCardsChangingPiles(new global::<>z__ReadOnlySingleElementList<CardPileAddResult>(cardPileAddResult.Value), fromSilentAdd: true).Item1;
				if (item != null)
				{
					await item.AwaitFinished(turnState.Ct);
				}
			}
		}

		private async Task EndEnemyTurnInternal(CombatTurnState turnState)
		{
			List<Creature> enemies = turnState.State.CreaturesOnCurrentSide.ToList();
			await Hook.BeforeSideTurnEnd(turnState.State, turnState.State.CurrentSide, enemies);
			foreach (Player player in turnState.State.Players)
			{
				player.PlayerCombatState.EndOfTurnCleanup();
			}
			await Hook.AfterSideTurnEnd(turnState.State, turnState.State.CurrentSide, enemies);
		}

		private async Task AfterAllPlayersReadyToBeginEnemyTurn(CombatTurnState turnState)
		{
			if (!turnState.IsInProgress)
			{
				return;
			}
			turnState.Ct.ThrowIfCancellationRequested();
			turnState.EndingPlayerTurnPhaseTwo = true;
			try
			{
				RunManager.Instance.ActionQueueSynchronizer.SetCombatState(ActionSynchronizerCombatState.NotPlayPhase);
				AboutToSwitchToEnemyTurn?.Invoke(turnState.State);
				await Task.Yield();
				if (turnState.IsInProgress && !turnState.Ct.IsCancellationRequested && turnState.State.CurrentSide == CombatSide.Player)
				{
					await EndPlayerTurnPhaseTwoInternal(turnState);
					await SwitchFromPlayerToEnemySide(turnState);
				}
			}
			finally
			{
				turnState.EndingPlayerTurnPhaseTwo = false;
			}
		}

		/// <summary>
		/// Does all the player state cleanup for the end of their turn. It must not call any hooks that might cause
		/// player choices to occur.
		/// Prefer ModelTest.PassToEnemyTurn, whose doc comment covers when the bypass is safe.
		/// </summary>
		internal async Task EndPlayerTurnPhaseTwoInternal()
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null)
			{
				await EndPlayerTurnPhaseTwoInternal(turnState);
			}
		}

		private async Task EndPlayerTurnPhaseTwoInternal(CombatTurnState turnState)
		{
			turnState.Ct.ThrowIfCancellationRequested();
			if (turnState.State.CurrentSide != CombatSide.Player)
			{
				throw new InvalidOperationException($"EndPlayerTurnPhaseTwo called while the current side is {turnState.State.CurrentSide}!");
			}
			List<Player> playersEndingTurn;
			using (turnState.ReadyLock.EnterScope())
			{
				playersEndingTurn = ((turnState.PlayersTakingExtraTurn.Count > 0) ? turnState.PlayersTakingExtraTurn.ToList() : turnState.State.Players.ToList());
			}
			List<HookPlayerChoiceContext> flushPlayerHandContexts = new List<HookPlayerChoiceContext>();
			foreach (Player item in playersEndingTurn)
			{
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				if (LocalContext.NetId.HasValue)
				{
					HookPlayerChoiceContext playerChoiceContext = new HookPlayerChoiceContext(item, LocalContext.NetId.Value, GameActionType.CombatPlayPhaseOnly);
					Task task = FlushPlayerHand(turnState, item, playerChoiceContext);
					await playerChoiceContext.AssignTaskAndWaitForPauseOrCompletion(task);
					flushPlayerHandContexts.Add(playerChoiceContext);
				}
			}
			foreach (HookPlayerChoiceContext item2 in flushPlayerHandContexts)
			{
				await item2.WaitForCompletion();
			}
			if (!turnState.Ct.IsCancellationRequested)
			{
				await Hook.AfterSideTurnEnd(turnState.State, turnState.State.CurrentSide, playersEndingTurn.Select((Player p) => p.Creature));
				turnState.Ct.ThrowIfCancellationRequested();
			}
			RunManager.Instance.ChecksumTracker.GenerateChecksum("after player turn phase two end", null);
		}

		private async Task FlushPlayerHand(CombatTurnState turnState, Player player, HookPlayerChoiceContext playerChoiceContext)
		{
			if (player.Creature.IsDead)
			{
				return;
			}
			if (player.PlayerCombatState == null)
			{
				Log.Warn($"Player combat state is null. Assuming that the run has been cleaned up. (Player: {player.NetId})");
				return;
			}
			CombatState state = turnState.State;
			List<CardModel> cardsToFlush = new List<CardModel>();
			List<CardModel> cardsToRetain = new List<CardModel>();
			bool flag = Hook.ShouldFlush(state, player);
			foreach (CardModel card in PileType.Hand.GetPile(player).Cards)
			{
				if (!flag || card.ShouldRetainThisTurn)
				{
					cardsToRetain.Add(card);
				}
				else
				{
					cardsToFlush.Add(card);
				}
			}
			if (cardsToFlush.Count > 0)
			{
				await CardPileCmd.Add(cardsToFlush, PileType.Discard);
				turnState.Ct.ThrowIfCancellationRequested();
			}
			await Hook.AfterFlush(state, player, playerChoiceContext, cardsToFlush, cardsToRetain);
			turnState.Ct.ThrowIfCancellationRequested();
			player.PlayerCombatState.EndOfTurnCleanup();
		}

		/// <summary>
		/// Switches from the player side to the enemy side, handling extra player turns if necessary. It only performs the
		/// switch; the turn loop runs the turn on the new side.
		/// </summary>
		private async Task SwitchFromPlayerToEnemySide(CombatTurnState turnState)
		{
			if (turnState.Ct.IsCancellationRequested)
			{
				return;
			}
			List<Player> list;
			using (turnState.ReadyLock.EnterScope())
			{
				turnState.PlayersTakingExtraTurn.Clear();
				foreach (Player player in turnState.State.Players)
				{
					if (Hook.ShouldTakeExtraTurn(turnState.State, player))
					{
						Log.Info($"Player {player.NetId} ({player.Character.Id.Entry}) is taking an extra turn");
						turnState.PlayersTakingExtraTurn.Add(player);
					}
				}
				list = turnState.PlayersTakingExtraTurn.ToList();
			}
			SwitchSides(turnState);
			foreach (Player item in list)
			{
				if (turnState.Ct.IsCancellationRequested)
				{
					return;
				}
				await Hook.AfterTakingExtraTurn(turnState.State, item);
			}
			await WaitForUnpause(turnState);
		}

		private void SwitchSides(CombatTurnState turnState)
		{
			if (turnState.Ct.IsCancellationRequested)
			{
				return;
			}
			bool flag;
			using (turnState.ReadyLock.EnterScope())
			{
				flag = turnState.PlayersTakingExtraTurn.Count > 0;
			}
			if (turnState.State.CurrentSide == CombatSide.Player && !flag)
			{
				turnState.State.CurrentSide = CombatSide.Enemy;
			}
			else
			{
				turnState.State.CurrentSide = CombatSide.Player;
				IReadOnlyList<Player> readOnlyList;
				if (flag)
				{
					readOnlyList = turnState.PlayersTakingExtraTurn;
				}
				else
				{
					readOnlyList = turnState.State.Players;
					turnState.State.RoundNumber++;
				}
				foreach (Player item in readOnlyList)
				{
					item.PlayerCombatState.IncrementTurnNumber();
				}
			}
			foreach (Creature creature in turnState.State.Creatures)
			{
				creature.OnSideSwitch();
			}
			TurnEnded?.Invoke(turnState.State);
		}

		/// <summary>
		/// Pause combat.
		/// </summary>
		public void Pause()
		{
			if (!NonInteractiveMode.IsActive && IsInProgress)
			{
				IsPaused = true;
			}
		}

		/// <summary>
		/// Un-pause combat.
		/// </summary>
		public void Unpause()
		{
			if (!NonInteractiveMode.IsActive)
			{
				IsPaused = false;
			}
		}

		/// <summary>
		/// Returns true if the passed player is taking part in the current player turn.
		/// Returns false if some player is taking an extra turn, and it's not us.
		/// If it is not the player turn, then this returns false.
		/// </summary>
		public bool IsPartOfPlayerTurn(Player player)
		{
			CombatTurnState turnState = _turnState;
			if (turnState == null || turnState.State.CurrentSide != CombatSide.Player)
			{
				return false;
			}
			using (turnState.ReadyLock.EnterScope())
			{
				if (turnState.PlayersTakingExtraTurn.Count == 0)
				{
					return true;
				}
				return turnState.PlayersTakingExtraTurn.Contains(player);
			}
		}

		public Task WaitForUnpause()
		{
			CombatTurnState turnState = _turnState;
			if (turnState != null)
			{
				return WaitForUnpause(turnState);
			}
			return Task.CompletedTask;
		}

		/// <summary>
		/// Turn-state-relative variant for the turn loop: waits against this turn state's combat, so a stale turn state
		/// resumes (and then dies at its next token check) instead of waiting on the current combat's pause state.
		/// </summary>
		private async Task WaitForUnpause(CombatTurnState turnState)
		{
			if (!NonInteractiveMode.IsActive)
			{
				while (IsPaused && turnState.IsLive)
				{
					await NGame.Instance.AwaitProcessFrame();
				}
			}
		}

		/// <summary>
		/// WARNING: ONLY CALL THIS IN TESTS!
		/// Force the specified card to be moved to the top of the next shuffle.
		/// Useful for tests for shuffle tests where the first card drawn afterwards matters.
		/// </summary>
		/// <param name="card">Card to force to the top.</param>
		public void DebugForceTopCardOnNextShuffle(CardModel card)
		{
			card.AssertMutable();
			DebugForcedTopCardOnNextShuffle = card;
		}

		/// <summary>
		/// WARNING: ONLY CALL THIS IN TESTS!
		/// Clear the forced specified card to be moved to the top of the next shuffle.
		/// Useful for tests for shuffle tests where the first card drawn afterwards matters.
		/// </summary>
		public void DebugClearForcedTopCardOnNextShuffle()
		{
			DebugForcedTopCardOnNextShuffle = null;
		}
	}
	public enum CombatSide
	{
		None,
		Player,
		Enemy
	}
	internal static class CombatSideExtensions
	{
		public static CombatSide GetOppositeSide(this CombatSide side)
		{
			return side switch
			{
				CombatSide.None => CombatSide.None, 
				CombatSide.Player => CombatSide.Enemy, 
				CombatSide.Enemy => CombatSide.Player, 
				_ => throw new ArgumentOutOfRangeException("side", side, null), 
			};
		}
	}
	/// <summary>
	/// An object containing all of the state that represents the current combat.
	///
	/// Some state details are derived from higher-level objects. For example:
	/// * All players in the combat state are derived by checking the Player property of all the creatures.
	/// * All cards in the combat state are derived by checking the combat piles of all those players.
	/// </summary>
	public class CombatState : ICombatState, ICardScope
	{
		private readonly List<Creature> _allies = new List<Creature>();

		private readonly List<Creature> _enemies = new List<Creature>();

		/// <summary>
		/// This is the ID that will be assigned to the next spawned creature's CombatId field.
		/// If we receive an action targeting a creature with an ID less than this one, then it must either be in the creature
		/// list or it had died at some point in the past.
		/// If we receive an action targeting a creature with an ID greater than or equal to this one, then it has yet to
		/// spawn (or there is some other error).
		/// </summary>
		private uint _nextCreatureId;

		private readonly EncounterModel? _encounter;

		private readonly List<Creature> _escapedCreatures = new List<Creature>();

		/// <summary>
		/// All cards that have been created within this state.
		/// This allows us to keep track of "floating" cards that have not been added to any piles (like fake cards in
		/// upgrade previews).
		/// </summary>
		private readonly List<CardModel> _allCards = new List<CardModel>();

		/// <summary>
		/// The state of the run that this combat exists in.
		/// Will be <see cref="P:MegaCrit.Sts2.Core.Combat.CombatState.RunState" /> in gameplay and <see cref="T:MegaCrit.Sts2.Core.Runs.NullRunState" /> in some test/debug scenarios.
		/// </summary>
		public IRunState RunState { get; }

		/// <summary>
		/// Get all creatures on the Allies side.
		/// </summary>
		public IReadOnlyList<Creature> Allies => _allies;

		/// <summary>
		/// Get all creatures on the Enemies side.
		/// </summary>
		public IReadOnlyList<Creature> Enemies => _enemies;

		/// <summary>
		/// Get all creatures in the combat on all sides.
		/// </summary>
		public IReadOnlyList<Creature> Creatures => _allies.Concat(_enemies).ToList();

		/// <summary>
		/// Get all the player creatures in the combat.
		/// </summary>
		public IReadOnlyList<Creature> PlayerCreatures => Creatures.Where((Creature c) => c.IsPlayer).ToList();

		/// <summary>
		/// Get all players in the combat.
		/// </summary>
		public IReadOnlyList<Player> Players => PlayerCreatures.Select((Creature c) => c.Player).ToList();

		/// <summary>
		/// List of custom modifiers applied to this combat, usually via daily or custom runs.
		/// </summary>
		public IReadOnlyList<ModifierModel> Modifiers { get; }

		/// <summary>
		/// List badge models, used when unlocking badges.
		/// </summary>
		public IReadOnlyList<BadgeModel> BadgeModels { get; }

		/// <summary>
		/// The model used to scale various things (block, power application) in multiplayer.
		/// </summary>
		public MultiplayerScalingModel? MultiplayerScalingModel { get; private set; }

		/// <summary>
		/// The round of combat that we're on in this combat.
		/// A "round" encompasses both the player's turn and the enemy's turn.
		/// This starts at 1, so it should never be 0.
		/// </summary>
		public int RoundNumber { get; set; }

		/// <summary>
		/// The side that is active in this combat.
		/// A round starts with the player side being active, then switches to the enemy side after all players have ended
		/// their turn.
		/// When the enemy turn ends, the current side changes back to the player side, and the round number is incremented.
		/// </summary>
		public CombatSide CurrentSide { get; set; }

		public EncounterModel? Encounter
		{
			get
			{
				return _encounter;
			}
			private init
			{
				value?.AssertMutable();
				_encounter = value;
			}
		}

		/// <summary>
		/// A list of creatures that escaped (were removed without dying) during the encounter. Used when rewards are given.
		/// </summary>
		public IReadOnlyList<Creature> EscapedCreatures => _escapedCreatures;

		/// <summary>
		/// Get all the creatures on the currently-active side.
		/// </summary>
		public IReadOnlyList<Creature> CreaturesOnCurrentSide => GetCreaturesOnSide(CurrentSide);

		/// <summary>
		/// Get all hittable enemies.
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Creatures.Creature.IsHittable" /> for a definition.
		///
		/// NOTE: We shouldn't add too many methods like this, this one is just extremely common because it's used for AOE
		/// and random attack targeting.
		/// </summary>
		public IReadOnlyList<Creature> HittableEnemies => Enemies.Where((Creature e) => e.IsHittable).ToList();

		/// <summary>
		/// Fired whenever the arrangement of creatures in the combat changes. Specifically, when:
		/// * A creature is added.
		/// * A creature is removed.
		/// * A creature's index changes.
		/// </summary>
		public event Action<ICombatState>? CreaturesChanged;

		public CombatState(EncounterModel? encounter = null, IRunState? runState = null, IReadOnlyList<ModifierModel>? modifiers = null, IReadOnlyList<BadgeModel>? badgeModels = null, MultiplayerScalingModel? multiplayerScalingModel = null)
		{
			encounter?.AssertMutable();
			Encounter = encounter;
			RoundNumber = 1;
			CurrentSide = CombatSide.Player;
			RunState = runState ?? NullRunState.Instance;
			Modifiers = modifiers ?? System.Array.Empty<ModifierModel>();
			BadgeModels = badgeModels ?? System.Array.Empty<BadgeModel>();
			MultiplayerScalingModel = multiplayerScalingModel;
		}

		/// <summary>
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.CreateCard``1(MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		public T CreateCard<T>(Player owner) where T : CardModel
		{
			return (T)CreateCard(ModelDb.Card<T>(), owner);
		}

		/// <summary>
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.CreateCard(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		public CardModel CreateCard(CardModel canonicalCard, Player owner)
		{
			CardModel cardModel = canonicalCard.ToMutable();
			AddCard(cardModel, owner);
			cardModel.AfterCreated();
			return cardModel;
		}

		/// <summary>
		/// WARNING: If you're specifically intending to create a clone in combat for an effect like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.DualWield" />,
		/// you should use <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.CreateClone" /> instead.
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.CloneCard(MegaCrit.Sts2.Core.Models.CardModel)" />.
		/// </summary>
		public CardModel CloneCard(CardModel mutableCard)
		{
			CardModel cardModel = (CardModel)mutableCard.ClonePreservingMutability();
			AddCard(cardModel);
			return cardModel;
		}

		/// <summary>
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.AddCard(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		public void AddCard(CardModel card, Player owner)
		{
			card.Owner = owner;
			AddCard(card);
		}

		public void RemoveCard(CardModel card)
		{
			_allCards.Remove(card);
			card.Owner = null;
		}

		/// <summary>
		/// Does this state contain the specified card?
		/// </summary>
		public bool ContainsCard(CardModel card)
		{
			return _allCards.Contains(card);
		}

		/// <summary>
		/// Add a player's creature on the Allies side.
		/// </summary>
		public void AddPlayer(Player player)
		{
			AttachCreature(player.Creature);
			AddCreature(player.Creature);
		}

		/// <summary>
		/// Creates a new creature from a monster in this combat state.
		/// After you create the creature, you should call AddCreature to add it to combat. This can be done immediately
		/// or after some time.
		/// </summary>
		public Creature CreateCreature(MonsterModel monster, CombatSide side, string? slot)
		{
			monster.AssertMutable();
			monster.RunRng = RunState.Rng;
			Creature creature = new Creature(monster, side, slot);
			List<Creature> creaturesOnSide = ((side == CombatSide.Player) ? _allies : _enemies);
			if (side == CombatSide.Enemy)
			{
				creature.SetUniqueMonsterHpValue(creaturesOnSide, RunState.Rng.Niche);
				creature.ScaleMonsterHpForMultiplayer(Encounter, Players.Count, RunState.CurrentActIndex);
			}
			AttachCreature(creature);
			monster.Rng = new Rng((ulong)((long)RunState.Rng.Seed + (long)(RunState.CurrentMapCoord?.col ?? 0) + (RunState.CurrentMapCoord?.row ?? 0) + RunState.CurrentActIndex + creature.CombatId.Value));
			_encounter?.OnCreatureSpawned(creature);
			return creature;
		}

		/// <summary>
		/// Attaches an existing creature to this combat state without adding it to the combat.
		/// This sets up the creature to be added to combat without actually putting it into the combat (i.e. it's not
		/// targeted by cards that hit all enemies, powers don't proc on it, etc).
		/// For players and almost all monsters, this is called just before adding their creature to the combat. Currently,
		/// the Doormaker is the only creature that doesn't get added to combat immediately after this is called.
		/// </summary>
		private void AttachCreature(Creature creature)
		{
			creature.CombatState = this;
			creature.CombatId = _nextCreatureId;
			_nextCreatureId++;
		}

		/// <summary>
		/// Call this to remove a creature that escaped rather than dying.
		/// </summary>
		public void CreatureEscaped(Creature creature)
		{
			_escapedCreatures.Add(creature);
			RemoveCreature(creature);
		}

		/// <summary>
		/// Removes the creature from combat.
		/// </summary>
		/// <param name="creature">The creature that will be removed.</param>
		/// <param name="unattach">If true, then the creature cannot be re-added to the combat state.</param>
		public void RemoveCreature(Creature creature, bool unattach = true)
		{
			if (creature.CombatState == null)
			{
				return;
			}
			if (creature.CombatState != this)
			{
				throw new InvalidOperationException("Creature is in a different combat.");
			}
			if (_enemies.Contains(creature))
			{
				_enemies.Remove(creature);
			}
			else
			{
				if (!_allies.Contains(creature))
				{
					throw new InvalidOperationException($"Removed creature '{creature}' was not found.");
				}
				_allies.Remove(creature);
			}
			if (unattach)
			{
				creature.CombatState = null;
			}
			CreaturesChanged?.Invoke(this);
		}

		public bool ContainsCreature(Creature creature)
		{
			if (!_allies.Contains(creature))
			{
				return _enemies.Contains(creature);
			}
			return true;
		}

		public bool ContainsMonster<T>() where T : MonsterModel
		{
			return _enemies.Any((Creature c) => c.Monster is T);
		}

		/// <summary>
		/// Get the creature with the specified combat ID. Null if not found.
		/// </summary>
		public Creature? GetCreature(uint? combatId)
		{
			if (!combatId.HasValue)
			{
				return null;
			}
			return Creatures.FirstOrDefault((Creature c) => c.CombatId == combatId);
		}

		/// <summary>
		/// Get the creature with the specified combat ID.
		/// If the creature doesn't exist, keep checking for a while before timing out and returning null.
		/// </summary>
		/// <param name="combatId">Combat ID of the creature to get.</param>
		/// <param name="timeoutSec">How long to wait for the creature to appear.</param>
		/// <returns>Specified Creature, or null if it doesn't exist and we've waited long enough.</returns>
		public async Task<Creature?> GetCreatureAsync(uint? combatId, double timeoutSec)
		{
			if (!combatId.HasValue)
			{
				return null;
			}
			Creature creature = GetCreature(combatId);
			if (creature != null)
			{
				return creature;
			}
			if (combatId < _nextCreatureId)
			{
				return null;
			}
			TaskCompletionSource<Creature> completionSource = new TaskCompletionSource<Creature>();
			CreaturesChanged += OnCreaturesChanged;
			Task timeoutTask = GodotTimerTask(timeoutSec);
			Task task = await Task.WhenAny(completionSource.Task, timeoutTask);
			CreaturesChanged -= OnCreaturesChanged;
			if (task == timeoutTask)
			{
				throw new InvalidOperationException($"Timed out waiting for creature with target index {combatId} to spawn!");
			}
			return await completionSource.Task;
			void OnCreaturesChanged(ICombatState _)
			{
				Creature creature2 = GetCreature(combatId);
				if (creature2 != null)
				{
					completionSource.SetResult(creature2);
				}
			}
		}

		/// <summary>
		/// Get all the creatures on the specified side.
		/// </summary>
		public IReadOnlyList<Creature> GetCreaturesOnSide(CombatSide side)
		{
			if (side != CombatSide.Enemy)
			{
				return Allies;
			}
			return Enemies;
		}

		/// <summary>
		/// Get all opponents of a creature.
		/// </summary>
		public IReadOnlyList<Creature> GetOpponentsOf(Creature creature)
		{
			return GetCreaturesOnSide(creature.Side.GetOppositeSide());
		}

		/// <summary>
		/// Get all teammates of a creature, including the creature itself.
		/// </summary>
		public IReadOnlyList<Creature> GetTeammatesOf(Creature creature)
		{
			return GetCreaturesOnSide(creature.Side);
		}

		public Player? GetPlayer(ulong playerId)
		{
			return Players.FirstOrDefault((Player p) => p.NetId == playerId);
		}

		/// <summary>
		/// Get all the models that should have combat hooks called on them.
		/// </summary>
		public IEnumerable<AbstractModel> IterateHookListeners()
		{
			List<AbstractModel> list = new List<AbstractModel>(Players.Count * 50);
			for (int i = 0; i < _allies.Count + _enemies.Count; i++)
			{
				Creature creature = ((i < _allies.Count) ? _allies[i] : _enemies[i - _allies.Count]);
				list.AddRange(creature.Powers);
				Player player = creature.Player;
				if (player == null)
				{
					list.Add(creature.Monster);
				}
				else
				{
					if (!player.IsActiveForHooks)
					{
						continue;
					}
					IReadOnlyList<RelicModel> relics = player.Relics;
					for (int j = 0; j < relics.Count; j++)
					{
						if (!relics[j].IsMelted)
						{
							list.Add(relics[j]);
						}
					}
					IReadOnlyList<PotionModel> potionSlots = player.PotionSlots;
					for (int k = 0; k < potionSlots.Count; k++)
					{
						if (potionSlots[k] != null)
						{
							list.Add(potionSlots[k]);
						}
					}
					if (player.PlayerCombatState == null)
					{
						continue;
					}
					list.AddRange(player.PlayerCombatState.OrbQueue.Orbs);
					IReadOnlyList<CardPile> allPiles = player.PlayerCombatState.AllPiles;
					for (int l = 0; l < allPiles.Count; l++)
					{
						CardPile cardPile = allPiles[l];
						IReadOnlyList<CardModel> cards = cardPile.Cards;
						for (int m = 0; m < cards.Count; m++)
						{
							CardModel cardModel = cards[m];
							list.Add(cardModel);
							if (cardModel.Affliction != null)
							{
								list.Add(cardModel.Affliction);
							}
							if (cardModel.Enchantment != null)
							{
								list.Add(cardModel.Enchantment);
							}
						}
					}
				}
			}
			for (int n = 0; n < Modifiers.Count; n++)
			{
				list.Add(Modifiers[n]);
			}
			for (int num = 0; num < BadgeModels.Count; num++)
			{
				list.Add(BadgeModels[num]);
			}
			if (MultiplayerScalingModel != null)
			{
				list.Add(MultiplayerScalingModel);
			}
			foreach (AbstractModel item in list)
			{
				if (Contains(item))
				{
					yield return item;
				}
			}
			foreach (AbstractModel item2 in ModHelper.IterateAllCombatStateSubscribers(this))
			{
				yield return item2;
			}
		}

		public void SortEnemiesBySlotName()
		{
			if (Encounter != null)
			{
				_enemies.Sort((Creature a, Creature b) => Encounter.Slots.IndexOf<string>(a.SlotName) - Encounter.Slots.IndexOf<string>(b.SlotName));
			}
		}

		public void SetEnemyIndex(Creature creature, int index)
		{
			if (Encounter.Slots.Any())
			{
				throw new InvalidOperationException("Cannot modify turn order of a combat with pre-set slots");
			}
			if (!Enemies.Contains(creature))
			{
				throw new ArgumentException("Creature must be a valid enemy to change its turn order.");
			}
			_enemies.Remove(creature);
			_enemies.Insert(Math.Min(index, _enemies.Count - 1), creature);
		}

		private void AddCard(CardModel card)
		{
			card.AssertMutable();
			if (card.CombatState != null && card.CombatState != this)
			{
				throw new InvalidOperationException("Card " + card.Id.Entry + " combat state is set to a different combat.");
			}
			_allCards.Add(card);
		}

		/// <summary>
		/// Adds a creature to the combat.
		/// This should almost always be called right after CreateCreature. Until this is called, creatures cannot be targeted
		/// and their powers will not be triggered. It is separate so that creatures can be removed from combat and re-added
		/// to it later. Currently, this is only used in the Doormaker combat.
		/// </summary>
		/// <param name="creature">The creature to add to the combat.</param>
		public void AddCreature(Creature creature)
		{
			if (creature.CombatState != this)
			{
				throw new InvalidOperationException("Creature was created for a different combat.");
			}
			List<Creature> list = ((creature.Side == CombatSide.Player) ? _allies : _enemies);
			if (ContainsCreature(creature))
			{
				throw new InvalidOperationException("Creature is already in this combat, but AddCreature was called on it again.");
			}
			list.Add(creature);
			CreaturesChanged?.Invoke(this);
		}

		private bool Contains(AbstractModel model)
		{
			if (!(model is PowerModel powerModel))
			{
				if (!(model is RelicModel relicModel))
				{
					if (!(model is PotionModel potionModel))
					{
						if (!(model is CardModel cardModel))
						{
							if (!(model is AfflictionModel afflictionModel))
							{
								if (!(model is EnchantmentModel enchantmentModel))
								{
									if (!(model is OrbModel orbModel))
									{
										if (!(model is MonsterModel monsterModel))
										{
											if (!(model is AchievementModel))
											{
												if (!(model is BadgeModel))
												{
													if (!(model is ModifierModel))
													{
														if (model is MultiplayerScalingModel)
														{
															return true;
														}
														throw new ArgumentOutOfRangeException("model", model, $"Invalid model type {model.GetType()} ({model})");
													}
													return true;
												}
												return true;
											}
											return true;
										}
										return monsterModel.Creature.CombatState != null;
									}
									return !orbModel.HasBeenRemovedFromState && orbModel.Owner.IsActiveForHooks;
								}
								return enchantmentModel.HasCard && !enchantmentModel.Card.HasBeenRemovedFromState && enchantmentModel.Card.Owner.IsActiveForHooks;
							}
							return afflictionModel.HasCard && !afflictionModel.Card.HasBeenRemovedFromState && afflictionModel.Card.Owner.IsActiveForHooks;
						}
						return !cardModel.HasBeenRemovedFromState && cardModel.Owner.IsActiveForHooks;
					}
					return !potionModel.HasBeenRemovedFromState && potionModel.Owner.IsActiveForHooks;
				}
				return !relicModel.HasBeenRemovedFromState && relicModel.Owner.IsActiveForHooks;
			}
			return powerModel.Owner.CombatState != null && (powerModel.Owner.Player?.IsActiveForHooks ?? true);
		}

		private static async Task GodotTimerTask(double timeSec)
		{
			if (TestMode.IsOn)
			{
				await Task.Delay(TimeSpan.FromSeconds(timeSec));
				return;
			}
			SceneTreeTimer sceneTreeTimer = ((SceneTree)Engine.GetMainLoop()).CreateTimer(timeSec);
			await sceneTreeTimer.ToSignal(sceneTreeTimer, SceneTreeTimer.SignalName.Timeout);
		}

		public bool IsLiveCombat()
		{
			return true;
		}
	}
	public class CombatStateTracker
	{
		private readonly CombatManager _combatManager;

		private Task? _combatStateChangedDeferredTask;

		private CombatState? _state;

		/// <summary>
		/// Fired whenever any part of the combat's state changes (card changes piles, power applied/removed, damage dealt,
		/// block gained/lost, etc.).
		/// </summary>
		public event Action<CombatState>? CombatStateChanged;

		public CombatStateTracker(CombatManager combatManager)
		{
			_combatManager = combatManager;
			_combatManager.History.Changed += OnCombatHistoryChanged;
			_combatManager.CombatBegan += OnCombatBegan;
			_combatManager.CreaturesChanged += OnCreaturesChanged;
			_combatManager.TurnStarted += OnTurnStarted;
			_combatManager.TurnEnded += OnTurnEnded;
		}

		~CombatStateTracker()
		{
			_combatManager.History.Changed -= OnCombatHistoryChanged;
			_combatManager.CombatBegan -= OnCombatBegan;
			_combatManager.CreaturesChanged -= OnCreaturesChanged;
			_combatManager.TurnStarted -= OnTurnStarted;
			_combatManager.TurnEnded -= OnTurnEnded;
		}

		public void SetState(CombatState state)
		{
			_state = state;
		}

		public void Subscribe(CardModel card)
		{
			card.AfflictionChanged += OnCardValueChanged;
			card.EnchantmentChanged += OnCardValueChanged;
			card.EnergyCostChanged += OnCardValueChanged;
			card.ReplayCountChanged += OnCardValueChanged;
			card.Played += OnCardValueChanged;
			card.Drawn += OnCardValueChanged;
			card.StarCostChanged += OnCardValueChanged;
			card.Upgraded += OnCardValueChanged;
			card.Forged += OnCardValueChanged;
		}

		public void Unsubscribe(CardModel card)
		{
			card.AfflictionChanged -= OnCardValueChanged;
			card.EnchantmentChanged -= OnCardValueChanged;
			card.EnergyCostChanged -= OnCardValueChanged;
			card.ReplayCountChanged -= OnCardValueChanged;
			card.Played -= OnCardValueChanged;
			card.Drawn -= OnCardValueChanged;
			card.StarCostChanged -= OnCardValueChanged;
			card.Upgraded -= OnCardValueChanged;
			card.Forged -= OnCardValueChanged;
		}

		public void Subscribe(CardPile pile)
		{
			pile.ContentsChanged += OnCardPileContentsChanged;
		}

		public void Unsubscribe(CardPile pile)
		{
			pile.ContentsChanged -= OnCardPileContentsChanged;
		}

		public void Subscribe(Creature creature)
		{
			creature.BlockChanged += OnCreatureValueChanged;
			creature.CurrentHpChanged += OnCreatureValueChanged;
			creature.MaxHpChanged += OnCreatureValueChanged;
			creature.PowerApplied += OnPowerAppliedOrRemoved;
			creature.PowerIncreased += OnPowerIncreased;
			creature.PowerDecreased += OnPowerDecreased;
			creature.PowerRemoved += OnPowerAppliedOrRemoved;
			creature.Died += OnCreatureChanged;
		}

		public void Unsubscribe(Creature creature)
		{
			creature.BlockChanged -= OnCreatureValueChanged;
			creature.CurrentHpChanged -= OnCreatureValueChanged;
			creature.MaxHpChanged -= OnCreatureValueChanged;
			creature.PowerApplied -= OnPowerAppliedOrRemoved;
			creature.PowerIncreased -= OnPowerIncreased;
			creature.PowerDecreased -= OnPowerDecreased;
			creature.PowerRemoved -= OnPowerAppliedOrRemoved;
			creature.Died -= OnCreatureChanged;
		}

		public void Subscribe(PlayerCombatState combatState)
		{
			combatState.EnergyChanged += OnPlayerCombatStateValueChanged;
			combatState.PlayerTurnPhaseChanged += OnPlayerStateChanged;
			combatState.StarsChanged += OnPlayerCombatStateValueChanged;
		}

		public void Unsubscribe(PlayerCombatState combatState)
		{
			combatState.EnergyChanged -= OnPlayerCombatStateValueChanged;
			combatState.PlayerTurnPhaseChanged -= OnPlayerStateChanged;
			combatState.StarsChanged -= OnPlayerCombatStateValueChanged;
		}

		private void OnCombatBegan(CombatState _)
		{
			NotifyCombatStateChanged("OnCombatBegan");
		}

		private void OnCardPileContentsChanged()
		{
			NotifyCombatStateChanged("OnCardPileContentsChanged");
		}

		private void OnCardValueChanged()
		{
			NotifyCombatStateChanged("OnCardValueChanged");
		}

		private void OnCombatHistoryChanged()
		{
			NotifyCombatStateChanged("OnCombatHistoryChanged");
		}

		private void OnCreatureValueChanged(int _, int __)
		{
			NotifyCombatStateChanged("OnCreatureValueChanged");
		}

		private void OnCreaturesChanged(CombatState _)
		{
			NotifyCombatStateChanged("OnCreatureChanged");
		}

		private void OnCreatureChanged(Creature _)
		{
			NotifyCombatStateChanged("OnCreaturesChanged");
		}

		private void OnPlayerStateChanged()
		{
			NotifyCombatStateChanged("OnPlayerStateChanged");
		}

		private void OnPlayerCombatStateValueChanged(int _, int __)
		{
			NotifyCombatStateChanged("OnPlayerCombatStateValueChanged");
		}

		private void OnPowerAppliedOrRemoved(PowerModel _)
		{
			NotifyCombatStateChanged("OnPowerAppliedOrRemoved");
		}

		private void OnPowerDecreased(PowerModel _, bool __)
		{
			NotifyCombatStateChanged("OnPowerDecreased");
		}

		private void OnPowerIncreased(PowerModel _, int __, bool ___)
		{
			NotifyCombatStateChanged("OnPowerIncreased");
		}

		private void OnTurnStarted(CombatState _)
		{
			NotifyCombatStateChanged("OnTurnStarted");
		}

		private void OnTurnEnded(CombatState _)
		{
			NotifyCombatStateChanged("OnTurnEnded");
		}

		/// <summary>
		/// Notify the world that something in the combat state changed.
		/// </summary>
		/// <param name="caller">The name of the method that triggered this.</param>
		private void NotifyCombatStateChanged(string caller)
		{
			if (TestMode.IsOn)
			{
				if (CombatStateChanged != null)
				{
					throw new InvalidOperationException("Backend should not be subscribing to CombatStateChanged!");
				}
			}
			else if (_combatStateChangedDeferredTask == null || _combatStateChangedDeferredTask.IsCompleted)
			{
				_combatStateChangedDeferredTask = TaskHelper.RunSafely(CallCombatStateChangedDeferred());
			}
		}

		private async Task CallCombatStateChangedDeferred()
		{
			Node instance = NRun.Instance;
			if (instance?.GetTreeOrNull() != null)
			{
				await instance.AwaitProcessFrame();
			}
			CombatState state = _state;
			if (state != null)
			{
				IReadOnlyList<Creature> creatures = state.Creatures;
				if (creatures != null && creatures.Count > 0)
				{
					LocalContext.GetMe(_state)?.PlayerCombatState?.RecalculateCardValues();
					CombatStateChanged?.Invoke(_state);
				}
			}
		}
	}
	/// <summary>
	/// Payload of <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.EndTurnSignalSource" />: the player-driven action that triggered the end of
	/// turn (which must finish before the end-of-turn sequence begins, e.g. Void Form's card play), the turn the
	/// end-turn was scheduled for (see the stamping comment in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.SetReadyToEndTurn(MegaCrit.Sts2.Core.Entities.Players.Player,System.Boolean,System.Func{System.Threading.Tasks.Task})" />), and the
	/// optional test hook to run during the enemy turn. The combat needs no stamp: the signal lives on one combat's
	/// turn state, so it can only ever be consumed by that combat's turn loop.
	/// </summary>
	internal sealed record EndTurnSignal(GameAction? RunningAction, int ScheduledTurnNumber, Player ScheduledPlayer, Func<Task>? ActionDuringEnemyTurn);
	/// <summary>
	/// A combat loss waiting to be processed at the next safe point (see <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.CheckWinCondition" />).
	/// </summary>
	internal sealed record PendingLossState(CombatRoom Room);
	/// <summary>
	/// The turn-scoped state owned by one combat. Every combat gets a fresh instance in
	/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.SetUpCombat(MegaCrit.Sts2.Core.Combat.CombatState)" />, and <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.Reset(System.Boolean)" /> drops it wholesale, so combat-scoped
	/// state cannot leak into the next combat through a forgotten per-field reset.
	/// The turn loop threads its own turn state through the entire turn flow and checks liveness against it, never
	/// against the manager's current fields: a turn state that resumes after its combat was torn down observes its own
	/// cancelled token instead of adopting the next combat's fresh one.
	///
	/// Internal, along with the signal records above: the single-owner model depends on exactly one turn state existing
	/// per combat, so nothing outside this assembly should be able to build one and hand it to the manager. Tests get in
	/// through InternalsVisibleTo (sts2.csproj), not through public API.
	/// </summary>
	internal sealed class CombatTurnState
	{
		private static int _sequenceCounter;

		private readonly CancellationTokenSource _cts = new CancellationTokenSource();

		/// <summary>
		/// Monotonically increasing id, used to correlate turn loop log lines with the combat they belong to, and handed
		/// to callers outside the assembly (as <see cref="P:MegaCrit.Sts2.Core.Combat.CombatManager.CurrentCombatId" />) so they can capture which
		/// combat their work belongs to.
		/// </summary>
		public CombatId Id { get; }

		/// <summary>
		/// The combat this turn state owns. Code running on a turn state reads this, never the manager's current state,
		/// so a stale turn state mutates only its own dead combat.
		/// </summary>
		public CombatState State { get; }

		/// <summary>
		/// Cancelled exactly once, in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatTurnState.Cancel" />, when this turn state's combat is torn down.
		/// </summary>
		public CancellationToken Ct => _cts.Token;

		/// <summary>
		/// True while this turn state's combat is running: in progress and not torn down. At the end of a won combat
		/// <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.IsInProgress" /> is already false while the turn state is only cancelled when the room exits;
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatTurnState.Cancel" /> also clears <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.IsInProgress" />, so a torn-down turn state fails both halves.
		/// </summary>
		public bool IsLive
		{
			get
			{
				if (IsInProgress)
				{
					return !_cts.IsCancellationRequested;
				}
				return false;
			}
		}

		public Lock ReadyLock { get; } = new Lock();

		public HashSet<Player> PlayersReadyToEndTurn { get; } = new HashSet<Player>();

		public HashSet<Player> PlayersReadyToBeginEnemyTurn { get; } = new HashSet<Player>();

		public List<Player> PlayersTakingExtraTurn { get; } = new List<Player>();

		/// <summary>
		/// Completed by <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.SetReadyToEndTurn(MegaCrit.Sts2.Core.Entities.Players.Player,System.Boolean,System.Func{System.Threading.Tasks.Task})" /> once all players are ready to end the current player
		/// turn. The turn loop awaits this: ready deliveries are data, and the turn loop is the single owner of turn control
		/// flow. Because the turn loop does not consume the signal until player-turn setup has finished, an end-turn that
		/// fires during setup (e.g. Void Form auto-played by Whispering Earring during the AutoPrePlay phase) is held until
		/// setup completes. Recreated at each player turn start; cancelled in <see cref="M:MegaCrit.Sts2.Core.Combat.CombatTurnState.Cancel" /> so a turn loop suspended
		/// awaiting it dies with its combat. Assignment guarded by <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.ReadyLock" />; completed outside the lock.
		/// </summary>
		public TaskCompletionSource<EndTurnSignal>? EndTurnSignalSource { get; set; }

		/// <summary>
		/// Completed by <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.SetReadyToBeginEnemyTurn(MegaCrit.Sts2.Core.Entities.Players.Player,System.Func{System.Threading.Tasks.Task})" /> once all players' ready actions have been
		/// delivered for the current turn. Same ownership model as <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.EndTurnSignalSource" />. The payload is the
		/// optional test hook to run during the enemy turn, carried by the local player's ready action.
		/// </summary>
		public TaskCompletionSource<Func<Task>?>? BeginEnemyTurnSignalSource { get; set; }

		/// <summary>
		/// Set when this combat is lost mid-action; processed (combat ended) at the next safe point in
		/// <see cref="M:MegaCrit.Sts2.Core.Combat.CombatManager.CheckWinCondition" />. Turn-state-scoped so a loss pending at teardown dies with its
		/// combat instead of being processed against the next one.
		/// </summary>
		public PendingLossState? PendingLoss { get; set; }

		public bool IsInProgress { get; set; }

		public bool IsStarting { get; set; } = true;

		public bool IsEnemyTurnStarted { get; set; }

		public bool EndingPlayerTurnPhaseOne { get; set; }

		public bool EndingPlayerTurnPhaseTwo { get; set; }

		public CombatTurnState(CombatState state)
		{
			State = state;
			Id = new CombatId(Interlocked.Increment(ref _sequenceCounter));
		}

		/// <summary>
		/// Tears this turn state down: cancels the token, then the per-turn signals, so a turn loop suspended anywhere in
		/// the turn flow dies with its combat. Callers must not hold <see cref="P:MegaCrit.Sts2.Core.Combat.CombatTurnState.ReadyLock" />: a turn loop suspended
		/// awaiting a signal, or inside a WaitAsync, unwinds synchronously inside the cancel calls, and that unwind must
		/// not run under the lock.
		/// </summary>
		public void Cancel()
		{
			TaskCompletionSource<EndTurnSignal> endTurnSignalSource;
			TaskCompletionSource<Func<Task>> beginEnemyTurnSignalSource;
			using (ReadyLock.EnterScope())
			{
				endTurnSignalSource = EndTurnSignalSource;
				beginEnemyTurnSignalSource = BeginEnemyTurnSignalSource;
				EndTurnSignalSource = null;
				BeginEnemyTurnSignalSource = null;
			}
			IsInProgress = false;
			_cts.Cancel();
			endTurnSignalSource?.TrySetCanceled();
			beginEnemyTurnSignalSource?.TrySetCanceled();
		}
	}
	public interface ICombatState
	{
		/// <summary>
		/// The state of the run that this combat exists in.
		/// Will be <see cref="P:MegaCrit.Sts2.Core.Combat.ICombatState.RunState" /> in gameplay and <see cref="T:MegaCrit.Sts2.Core.Runs.NullRunState" /> in some test/debug scenarios.
		/// </summary>
		IRunState RunState { get; }

		/// <summary>
		/// Get all creatures on the Allies side.
		/// </summary>
		IReadOnlyList<Creature> Allies { get; }

		/// <summary>
		/// Get all creatures on the Enemies side.
		/// </summary>
		IReadOnlyList<Creature> Enemies { get; }

		/// <summary>
		/// Get all creatures in the combat on all sides.
		/// </summary>
		IReadOnlyList<Creature> Creatures { get; }

		/// <summary>
		/// Get all the player creatures in the combat.
		/// </summary>
		IReadOnlyList<Creature> PlayerCreatures { get; }

		/// <summary>
		/// Get all players in the combat.
		/// </summary>
		IReadOnlyList<Player> Players { get; }

		/// <summary>
		/// List of custom modifiers applied to this combat, usually via daily or custom runs.
		/// </summary>
		IReadOnlyList<ModifierModel> Modifiers { get; }

		/// <summary>
		/// The model used to scale various things (block, power application) in multiplayer.
		/// </summary>
		MultiplayerScalingModel? MultiplayerScalingModel { get; }

		/// <summary>
		/// BE CAREFUL! You usually want <see cref="P:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState.TurnNumber" /> instead of this.
		/// The round of combat that we're on in this combat.
		/// A "round" encompasses both the player's turn (or turns if a player takes an extra turn) and the enemy's turn.
		/// This starts at 1, so it should never be 0.
		/// </summary>
		int RoundNumber { get; set; }

		/// <summary>
		/// The side that is active in this combat.
		/// A round starts with the player side being active, then switches to the enemy side after all players have ended
		/// their turn.
		/// When the enemy turn ends, the current side changes back to the player side, and the round number is incremented.
		/// </summary>
		CombatSide CurrentSide { get; set; }

		EncounterModel? Encounter { get; }

		/// <summary>
		/// A list of creatures that escaped (were removed without dying) during the encounter. Used when rewards are given.
		/// </summary>
		IReadOnlyList<Creature> EscapedCreatures { get; }

		/// <summary>
		/// Get all the creatures on the currently-active side.
		/// </summary>
		IReadOnlyList<Creature> CreaturesOnCurrentSide { get; }

		/// <summary>
		/// Get all hittable enemies.
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Creatures.Creature.IsHittable" /> for a definition.
		///
		/// NOTE: We shouldn't add too many methods like this, this one is just extremely common because it's used for AOE
		/// and random attack targeting.
		/// </summary>
		IReadOnlyList<Creature> HittableEnemies { get; }

		/// <summary>
		/// Fired whenever the arrangement of creatures in the combat changes. Specifically, when:
		/// * A creature is added.
		/// * A creature is removed.
		/// * A creature's index changes.
		/// </summary>
		event Action<ICombatState>? CreaturesChanged;

		/// <summary>
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.CreateCard``1(MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		T CreateCard<T>(Player owner) where T : CardModel;

		/// <summary>
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.CreateCard(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		CardModel CreateCard(CardModel canonicalCard, Player owner);

		/// <summary>
		/// WARNING: If you're specifically intending to create a clone in combat for an effect like <see cref="T:MegaCrit.Sts2.Core.Models.Cards.DualWield" />,
		/// you should use <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.CreateClone" /> instead.
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.CloneCard(MegaCrit.Sts2.Core.Models.CardModel)" />.
		/// </summary>
		CardModel CloneCard(CardModel mutableCard);

		/// <summary>
		/// See <see cref="M:MegaCrit.Sts2.Core.Runs.ICardScope.AddCard(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Entities.Players.Player)" />.
		/// </summary>
		void AddCard(CardModel card, Player owner);

		void RemoveCard(CardModel card);

		/// <summary>
		/// Does this state contain the specified card?
		/// </summary>
		bool ContainsCard(CardModel card);

		/// <summary>
		/// Add a player's creature on the Allies side.
		/// </summary>
		void AddPlayer(Player player);

		/// <summary>
		/// Creates a new creature from a monster in this combat state.
		/// After you create the creature, you should call AddCreature to add it to combat. This can be done immediately
		/// or after some time.
		/// </summary>
		Creature CreateCreature(MonsterModel monster, CombatSide side, string? slot);

		/// <summary>
		/// Call this to remove a creature that escaped rather than dying.
		/// </summary>
		void CreatureEscaped(Creature creature);

		/// <summary>
		/// Removes the creature from combat.
		/// </summary>
		/// <param name="creature">The creature that will be removed.</param>
		/// <param name="unattach">If true, then the creature cannot be re-added to the combat state.</param>
		void RemoveCreature(Creature creature, bool unattach = true);

		bool ContainsCreature(Creature creature);

		bool ContainsMonster<T>() where T : MonsterModel;

		/// <summary>
		/// Get the creature with the specified combat ID. Null if not found.
		/// </summary>
		Creature? GetCreature(uint? combatId);

		/// <summary>
		/// Get the creature with the specified combat ID.
		/// If the creature doesn't exist, keep checking for a while before timing out and returning null.
		/// </summary>
		/// <param name="combatId">Combat ID of the creature to get.</param>
		/// <param name="timeoutSec">How long to wait for the creature to appear.</param>
		/// <returns>Specified Creature, or null if it doesn't exist and we've waited long enough.</returns>
		Task<Creature?> GetCreatureAsync(uint? combatId, double timeoutSec);

		/// <summary>
		/// Get all the creatures on the specified side.
		/// </summary>
		IReadOnlyList<Creature> GetCreaturesOnSide(CombatSide side);

		/// <summary>
		/// Get all opponents of a creature.
		/// </summary>
		IReadOnlyList<Creature> GetOpponentsOf(Creature creature);

		/// <summary>
		/// Get all teammates of a creature, including the creature itself.
		/// </summary>
		IReadOnlyList<Creature> GetTeammatesOf(Creature creature);

		Player? GetPlayer(ulong playerId);

		/// <summary>
		/// Get all the models that should have combat hooks called on them.
		/// </summary>
		IEnumerable<AbstractModel> IterateHookListeners();

		void SortEnemiesBySlotName();

		void SetEnemyIndex(Creature creature, int index);

		/// <summary>
		/// Adds a creature to the combat.
		/// This should almost always be called right after CreateCreature. Until this is called, creatures cannot be targeted
		/// and their powers will not be triggered. It is separate so that creatures can be removed from combat and re-added
		/// to it later. Currently, this is only used in the Doormaker combat.
		/// </summary>
		/// <param name="creature">The creature to add to the combat.</param>
		void AddCreature(Creature creature);

		/// <summary>
		/// Returns true if this represents a live combat.
		/// If this is false, then you should only trust that whatever object you retrieved this combat state from (like a
		/// Creature) exists, and not any other object, like other Creatures or the NCombatRoom.
		/// </summary>
		bool IsLiveCombat();
	}
