	/// <summary>
	/// Marks the phase of the player's turn in combat.
	/// </summary>
	public enum PlayerTurnPhase
	{
		/// <summary>
		/// No phase. Used when combat is not in progress and during the enemy's turn.
		/// </summary>
		None,
		/// <summary>
		/// The start of the turn.
		/// The player is in this phase from the moment combat switches over from the enemy's turn until the player is
		/// allowed to play cards.
		///
		/// This encompasses many things, including:
		/// - Block clear
		/// - <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.AfterSideTurnStart(MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Combat.CombatSide,System.Collections.Generic.IReadOnlyList{MegaCrit.Sts2.Core.Entities.Creatures.Creature})" />
		/// - Start-of-turn orb passive triggers
		/// - Energy reset
		/// - Hand draw
		/// </summary>
		Start,
		/// <summary>
		/// The phase of the turn where start-of-turn auto-play effects happen.
		/// This is when <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.AfterAutoPrePlayPhaseEntered(MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext,MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Entities.Players.Player)" /> is called.
		///
		/// Examples:
		/// - <see cref="T:MegaCrit.Sts2.Core.Models.Relics.HistoryCourse" />
		/// - <see cref="T:MegaCrit.Sts2.Core.Models.Enchantments.Imbued" />
		/// - <see cref="T:MegaCrit.Sts2.Core.Models.Relics.WhisperingEarring" />
		/// </summary>
		AutoPrePlay,
		/// <summary>
		/// The phase of the turn where the player is allowed to manually play cards and use potions.
		/// In this phase, hooks only happen in response to player actions.
		/// </summary>
		Play,
		/// <summary>
		/// The phase of the turn where end-of-turn auto-play effects happen.
		/// This is when <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.AfterAutoPostPlayPhaseEntered(MegaCrit.Sts2.Core.GameActions.Multiplayer.HookPlayerChoiceContext,MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Entities.Players.Player)" /> is called.
		///
		/// Examples:
		/// - <see cref="T:MegaCrit.Sts2.Core.Models.Cards.IAmInvincible" />
		/// - <see cref="T:MegaCrit.Sts2.Core.Models.Powers.StampedePower" />
		/// </summary>
		AutoPostPlay,
		/// <summary>
		/// The end of the turn.
		/// The player is in this phase from the moment all players have hit "end turn" and all queued cards have finished
		/// playing until combat switches over to the enemy's turn.
		///
		/// This encompasses many things, including:
		/// - <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.BeforeSideTurnEnd(MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Combat.CombatSide,System.Collections.Generic.IEnumerable{MegaCrit.Sts2.Core.Entities.Creatures.Creature})" />
		/// - End-of-turn orb passive triggers
		/// - Hand flush
		/// - <see cref="M:MegaCrit.Sts2.Core.Hooks.Hook.AfterSideTurnEnd(MegaCrit.Sts2.Core.Combat.ICombatState,MegaCrit.Sts2.Core.Combat.CombatSide,System.Collections.Generic.IEnumerable{MegaCrit.Sts2.Core.Entities.Creatures.Creature})" />
		/// </summary>
		End
	}
	/// <summary>
	/// Reported when a combat's turn loop dies while the combat is still in progress, leaving the player unable to act.
	///
	/// The underlying exception already reaches Sentry via <see cref="M:MegaCrit.Sts2.Core.Helpers.TaskHelper.RunSafely(System.Threading.Tasks.Task)" />, but as whatever it
	/// happened to be, with nothing marking it as having stopped a combat. This wrapper gives those their own issue, the
	/// way <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Game.StateDivergenceException" /> does for divergences.
	/// </summary>
	public class StuckCombatException : Exception
	{
		public StuckCombatException(string message, Exception innerException)
			: base(message, innerException)
		{
		}
	}
}
namespace MegaCrit.Sts2.Core.Combat.History
{
	/// <summary>
	/// A history of most events that have happened in combat.
	/// Each entry should be logged immediately after the event occurs, but before its AfterX hook is executed.
	/// For example, a CardPlayedEntry is logged immediately after the card is played, but before AfterCardPlayed is
	/// executed.
	/// </summary>
	public class CombatHistory
	{
		private readonly List<CombatHistoryEntry> _entries = new List<CombatHistoryEntry>();

		public IEnumerable<CombatHistoryEntry> Entries => _entries;

		public IEnumerable<CardPlayStartedEntry> CardPlaysStarted => Entries.OfType<CardPlayStartedEntry>();

		public IEnumerable<CardPlayFinishedEntry> CardPlaysFinished => Entries.OfType<CardPlayFinishedEntry>();

		public event Action? Changed;

		public void Clear()
		{
			_entries.Clear();
			Changed?.Invoke();
		}

		public void CardPlayStarted(ICombatState combatState, CardPlay cardPlay)
		{
			Add(combatState, new CardPlayStartedEntry(cardPlay, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void CardPlayFinished(ICombatState combatState, CardPlay cardPlay)
		{
			Add(combatState, new CardPlayFinishedEntry(cardPlay, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void CardAfflicted(ICombatState combatState, CardModel card, AfflictionModel affliction)
		{
			Add(combatState, new CardAfflictedEntry(card, affliction, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void CardDiscarded(ICombatState combatState, CardModel card)
		{
			Add(combatState, new CardDiscardedEntry(card, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void CardDrawn(ICombatState combatState, CardModel card, bool fromHandDraw)
		{
			Add(combatState, new CardDrawnEntry(card, combatState.RoundNumber, combatState.CurrentSide, fromHandDraw, this, combatState.Players));
		}

		public void CardExhausted(ICombatState combatState, CardModel card)
		{
			Add(combatState, new CardExhaustedEntry(card, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void CardGenerated(ICombatState combatState, CardModel card, Player? creator)
		{
			Add(combatState, new CardGeneratedEntry(card, creator, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void CreatureAttacked(ICombatState combatState, Creature attacker, IReadOnlyList<DamageResult> damageResults)
		{
			Add(combatState, new CreatureAttackedEntry(attacker, damageResults, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void DamageReceived(ICombatState combatState, Creature receiver, Creature? dealer, DamageResult result, CardModel? cardSource)
		{
			Add(combatState, new DamageReceivedEntry(result, receiver, dealer, cardSource, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void BlockGained(ICombatState combatState, Creature receiver, int amount, ValueProp props, CardPlay? cardPlay)
		{
			Add(combatState, new BlockGainedEntry(amount, props, cardPlay, receiver, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void EnergySpent(ICombatState combatState, int amount, Player player)
		{
			Add(combatState, new EnergySpentEntry(amount, player, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void MonsterPerformedMove(ICombatState combatState, MonsterModel monster, MoveState move, IEnumerable<Creature>? targets)
		{
			Add(combatState, new MonsterPerformedMoveEntry(monster, move, targets, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void OrbChanneled(ICombatState combatState, OrbModel orb)
		{
			Add(combatState, new OrbChanneledEntry(orb, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void PotionUsed(ICombatState combatState, PotionModel potion, Creature? target)
		{
			Add(combatState, new PotionUsedEntry(potion, target, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void PowerReceived(ICombatState combatState, PowerModel power, decimal amount, Creature? applier)
		{
			Add(combatState, new PowerReceivedEntry(power, amount, applier, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void StarsModified(ICombatState combatState, int amount, Player player)
		{
			Add(combatState, new StarsModifiedEntry(amount, player, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		public void Summoned(ICombatState combatState, int amount, Player player)
		{
			Add(combatState, new SummonedEntry(amount, player, combatState.RoundNumber, combatState.CurrentSide, this, combatState.Players));
		}

		private void Add(ICombatState combatState, CombatHistoryEntry entry)
		{
			if (combatState.IsLiveCombat())
			{
				_entries.Add(entry);
				Changed?.Invoke();
			}
		}
	}
	public abstract class CombatHistoryEntry
	{
		/// <summary>
		/// The turn numbers of all the players in combat when this action occurred.
		/// </summary>
		private readonly System.Collections.Generic.Dictionary<ulong, int> _playerTurnNumbers = new System.Collections.Generic.Dictionary<ulong, int>();

		/// <summary>
		/// Who performed this action?
		/// Even if this was a player-specific action (like drawing a card or gaining energy),
		/// this will be the player's creature.
		/// Null if the action was not performed by any creature, like when a player loses HP from Royal Poison.
		/// </summary>
		public Creature Actor { get; }

		/// <summary>
		/// What round was it when this action occurred?
		/// See <see cref="P:MegaCrit.Sts2.Core.Entities.Players.PlayerCombatState.TurnNumber" /> and <see cref="P:MegaCrit.Sts2.Core.Combat.ICombatState.RoundNumber" /> to understand the
		/// difference between the two.
		/// </summary>
		private int RoundNumber { get; }

		/// <summary>
		/// Which side's turn was it when this action occurred?
		///
		/// This will not always be the same as Actor.Side. For example, if you attack a monster with Thorns, the entry for
		/// the Thorns damage will have Actor.Side = Monster (since the monster is the one dealing damage back), but
		/// CurrentSide will be Player (since it's the player's turn).
		/// </summary>
		private CombatSide CurrentSide { get; }

		/// <summary>
		/// The history object that this entry is in.
		/// </summary>
		public CombatHistory History { get; }

		public string HumanReadableString => $"Rd {RoundNumber} ({CurrentSide} turn): {Description}.";

		public abstract string Description { get; }

		protected CombatHistoryEntry(Creature actor, int roundNumber, CombatSide currentSide, CombatHistory history, IEnumerable<Player> players)
		{
			Actor = actor;
			RoundNumber = roundNumber;
			CurrentSide = currentSide;
			History = history;
			foreach (Player player in players)
			{
				_playerTurnNumbers[player.NetId] = player.PlayerCombatState.TurnNumber;
			}
		}

		/// <summary>
		/// Did this action happen during the current turn?
		/// </summary>
		public bool HappenedThisTurn(ICombatState? state)
		{
			if (state == null)
			{
				return false;
			}
			if (RoundNumber != state.RoundNumber)
			{
				return false;
			}
			if (CurrentSide != state.CurrentSide)
			{
				return false;
			}
			foreach (KeyValuePair<ulong, int> playerTurnNumber in _playerTurnNumbers)
			{
				playerTurnNumber.Deconstruct(out var key, out var value);
				ulong playerId = key;
				int num = value;
				Player? player = state.GetPlayer(playerId);
				if (player != null)
				{
					int? num2 = player.PlayerCombatState?.TurnNumber;
					value = num;
					if (num2 == value)
					{
						continue;
					}
				}
				return false;
			}
			return true;
		}

		/// <summary>
		/// Did this action happen during the specified player's last turn?
		/// </summary>
		public bool HappenedLastPlayerTurn(Player player)
		{
			if (!_playerTurnNumbers.TryGetValue(player.NetId, out var value))
			{
				return false;
			}
			int num = value;
			PlayerCombatState? playerCombatState = player.PlayerCombatState;
			return num == ((playerCombatState != null) ? new int?(playerCombatState.TurnNumber - 1) : ((int?)null));
		}
	}
}
