namespace MegaCrit.Sts2.Core.AutoSlay
{
	/// <summary>
	/// Configuration constants for AutoSlay timeouts and settings.
	/// </summary>
	public static class AutoSlayConfig
	{
		/// <summary>Maximum time for a complete run.</summary>
		public static readonly TimeSpan runTimeout = TimeSpan.FromMinutes(25L);

		/// <summary>Default timeout for room handlers.</summary>
		public static readonly TimeSpan defaultRoomTimeout = TimeSpan.FromMinutes(2L);

		/// <summary>Default timeout for screen handlers.</summary>
		public static readonly TimeSpan defaultScreenTimeout = TimeSpan.FromSeconds(30L);

		/// <summary>Timeout for waiting for game instance to initialize.</summary>
		public static readonly TimeSpan gameInitTimeout = TimeSpan.FromSeconds(10L);

		/// <summary>Timeout for waiting for run state to initialize.</summary>
		public static readonly TimeSpan runStateTimeout = TimeSpan.FromSeconds(30L);

		/// <summary>Timeout for waiting for nodes to appear.</summary>
		public static readonly TimeSpan nodeWaitTimeout = TimeSpan.FromSeconds(10L);

		/// <summary>Timeout for waiting for map screen.</summary>
		public static readonly TimeSpan mapScreenTimeout = TimeSpan.FromSeconds(10L);

		/// <summary>
		/// Timeout for a map point to become travelable. On a post-boss act transition the new act's
		/// map opens via a fire-and-forget act change, so travel can be enabled several seconds after
		/// the run state reports the act switch. Sized to match <see cref="F:MegaCrit.Sts2.Core.AutoSlay.AutoSlayConfig.watchdogTimeout" /> so the
		/// watchdog stays the single hard backstop for genuine hangs.
		/// </summary>
		public static readonly TimeSpan mapPointEnabledTimeout = TimeSpan.FromSeconds(30L);

		/// <summary>Polling interval for condition checks.</summary>
		public static readonly TimeSpan pollingInterval = TimeSpan.FromMilliseconds(100L, 0L);

		/// <summary>Delay between button interactions.</summary>
		public static readonly TimeSpan buttonClickDelay = TimeSpan.FromMilliseconds(100L, 0L);

		/// <summary>Maximum floor to play to (floor 49 is the final boss).</summary>
		public const int maxFloor = 49;

		/// <summary>
		/// Turn at which AutoSlay starts ramping up Strength. Fights that end before this play out with
		/// no offensive buff so real combat is exercised; only dragging fights (bosses, and DPS-check
		/// encounters like The Insatiable, whose <c>SandpitPower</c> counter hard-kills the player when
		/// it expires) get forced toward a kill. Kept low so the ramp closes the fight out before such a
		/// counter runs down: in local runs The Insatiable dies around turn 4, well ahead of its kill.
		/// </summary>
		public const int combatStrengthRampStartTurn = 3;

		/// <summary>
		/// Strength added each turn once the ramp starts. Stacks additively, so a dragging fight ends
		/// within a turn or two of the ramp beginning, staying ahead of instakill counters and the turn cap.
		/// </summary>
		public const int combatStrengthRampPerTurn = 200;

		/// <summary>Watchdog timeout. If no progress for this long, dump state and fail.</summary>
		public static readonly TimeSpan watchdogTimeout = TimeSpan.FromSeconds(30L);

		/// <summary>Interval for periodic state logging when stuck detection is active.</summary>
		public static readonly TimeSpan watchdogLogInterval = TimeSpan.FromSeconds(5L);
	}
	/// <summary>
	/// Main orchestrator for AutoSlay. Runs the game automatically for smoke testing.
	/// </summary>
	public class AutoSlayer
	{
		private readonly System.Collections.Generic.Dictionary<RoomType, IRoomHandler> _roomHandlers;

		private readonly System.Collections.Generic.Dictionary<Type, IScreenHandler> _screenHandlers;

		private readonly MapScreenHandler _mapHandler;

		private CancellationTokenSource? _cts;

		private string? _seed;

		private Rng? _random;

		private Watchdog? _watchdog;

		private IDisposable? _cardSelectorScope;

		private static int _exitCode;

		/// <summary>How often to re-check a pending task while draining the screens it opens.</summary>
		private const int _drainPollIntervalMs = 50;

		/// <summary>Static flag indicating if AutoSlay is currently running.</summary>
		public static bool IsActive { get; private set; }

		/// <summary>Gets the current watchdog instance (for WaitHelper integration).</summary>
		public static Watchdog? CurrentWatchdog { get; private set; }

		static AutoSlayer()
		{
			NonInteractiveMode.AutoSlayerCheck = () => IsActive;
		}

		public AutoSlayer()
		{
			CombatRoomHandler value = new CombatRoomHandler();
			_roomHandlers = new System.Collections.Generic.Dictionary<RoomType, IRoomHandler>
			{
				[RoomType.Monster] = value,
				[RoomType.Elite] = value,
				[RoomType.Boss] = value,
				[RoomType.Event] = new EventRoomHandler(),
				[RoomType.Shop] = new ShopRoomHandler(DrainOverlayScreensUntilAsync),
				[RoomType.Treasure] = new TreasureRoomHandler(),
				[RoomType.RestSite] = new RestSiteRoomHandler()
			};
			_mapHandler = new MapScreenHandler();
			_screenHandlers = new System.Collections.Generic.Dictionary<Type, IScreenHandler>
			{
				[typeof(NRewardsScreen)] = new RewardsScreenHandler(),
				[typeof(NCardRewardSelectionScreen)] = new CardRewardScreenHandler(),
				[typeof(NDeckUpgradeSelectScreen)] = new DeckUpgradeScreenHandler(),
				[typeof(NDeckTransformSelectScreen)] = new DeckTransformScreenHandler(),
				[typeof(NDeckEnchantSelectScreen)] = new DeckEnchantScreenHandler(),
				[typeof(NDeckCardSelectScreen)] = new DeckCardSelectScreenHandler(),
				[typeof(NSimpleCardSelectScreen)] = new SimpleCardSelectScreenHandler(),
				[typeof(NChooseACardSelectionScreen)] = new ChooseACardScreenHandler(),
				[typeof(NChooseABundleSelectionScreen)] = new ChooseABundleScreenHandler(),
				[typeof(NChooseARelicSelection)] = new ChooseARelicScreenHandler(),
				[typeof(NGameOverScreen)] = new GameOverScreenHandler(),
				[typeof(NCrystalSphereScreen)] = new CrystalSphereScreenHandler()
			};
		}

		/// <summary>Starts an AutoSlay run with the given seed.</summary>
		public void Start(string seed, string? logFile = null)
		{
			if (logFile != null)
			{
				AutoSlayLog.OpenLogFile(logFile);
			}
			SentryService.SetTag("autoslay", "true");
			SentryService.SetTag("autoslay.seed", seed);
			IsActive = true;
			_cts = new CancellationTokenSource();
			Task task = RunAsync(seed, _cts.Token);
			TaskHelper.RunSafely(task);
		}

		/// <summary>Stops the current AutoSlay run.</summary>
		public void Stop()
		{
			IsActive = false;
			_cts?.Cancel();
			_cts = null;
		}

		/// <summary>Gets the current overlay screen cast to the expected type.</summary>
		/// <exception cref="T:System.InvalidOperationException">
		/// The top of the overlay stack is not a <typeparamref name="T" />, or there is no stack to peek.
		/// </exception>
		public static T GetCurrentScreen<T>() where T : Node
		{
			IOverlayScreen overlayScreen = NOverlayStack.Instance?.Peek();
			if (!(overlayScreen is T result))
			{
				throw new InvalidOperationException($"Expected {typeof(T).Name} on top of the overlay stack, found {overlayScreen?.GetType().Name ?? "nothing"}.");
			}
			return result;
		}

		private async Task RunAsync(string seed, CancellationToken ct)
		{
			AutoSlayLog.RunStarted(seed);
			try
			{
				await WaitHelper.WithTimeout((CancellationToken token) => PlayRunAsync(seed, token), AutoSlayConfig.runTimeout, ct);
				AutoSlayLog.RunCompleted(seed);
			}
			catch (Exception ex)
			{
				_exitCode = 1;
				AutoSlayLog.RunFailed(seed, ex);
				throw;
			}
			finally
			{
				IsActive = false;
				CurrentWatchdog = null;
				_watchdog = null;
				_cardSelectorScope?.Dispose();
				_cardSelectorScope = null;
				MemoryProfiler.Reset();
				AutoSlayLog.CloseLogFile();
				QuitGame(_exitCode);
			}
		}

		private async Task PlayRunAsync(string seed, CancellationToken ct)
		{
			await WaitHelper.Until(() => NGame.Instance != null, ct, AutoSlayConfig.gameInitTimeout, "Game instance not initialized");
			_seed = seed;
			NGame.Instance.DebugSeedOverride = seed;
			SaveManager.Instance.PrefsSave.FastMode = FastModeType.Fast;
			SaveManager.Instance.SetFtuesEnabled(enabled: false);
			SaveManager.Instance.MarkFtueAsComplete("ascension_singleplayer_ftue");
			SaveManager.Instance.ObtainEpochOverride(EpochModel.GetId<Silent1Epoch>(), EpochState.Revealed);
			SaveManager.Instance.ObtainEpochOverride(EpochModel.GetId<Regent1Epoch>(), EpochState.Revealed);
			SaveManager.Instance.ObtainEpochOverride(EpochModel.GetId<Defect1Epoch>(), EpochState.Revealed);
			SaveManager.Instance.ObtainEpochOverride(EpochModel.GetId<Necrobinder1Epoch>(), EpochState.Revealed);
			_random = new Rng(StringHelper.GetDeterministicHashCode(seed));
			_cardSelectorScope = CardSelectCmd.UseSelector(new AutoSlayCardSelector(_random));
			_watchdog = new Watchdog();
			CurrentWatchdog = _watchdog;
			_watchdog.Reset("Playing main menu");
			await PlayMainMenuAsync(ct);
			await WaitHelper.Until(() => RunManager.Instance.DebugOnlyGetState() != null, ct, AutoSlayConfig.runStateTimeout, "Run state not initialized");
			RunState runState = RunManager.Instance.DebugOnlyGetState();
			MemoryProfiler.SetBaseline();
			await WaitHelper.Until(() => runState.CurrentRoom != null && runState.CurrentRoom.RoomType != RoomType.Unassigned, ct, AutoSlayConfig.nodeWaitTimeout, "Room type not assigned");
			while (runState.TotalFloor < 49)
			{
				ct.ThrowIfCancellationRequested();
				RoomType roomType = runState.CurrentRoom.RoomType;
				_watchdog.Reset($"Entering {roomType} room (Act {runState.CurrentActIndex + 1}, Floor {runState.ActFloor})");
				AutoSlayLog.EnterRoom(roomType, runState.CurrentActIndex, runState.ActFloor);
				MemoryProfiler.LogSnapshot($"pre-room:{roomType}:Act{runState.CurrentActIndex + 1}:F{runState.ActFloor}");
				await HandleRoomAsync(roomType, ct);
				if ((uint)(roomType - 1) > 2u)
				{
					await Task.Delay(500, ct);
				}
				else
				{
					await WaitForRewardsScreenAsync(ct);
				}
				await DrainOverlayScreensAsync(ct);
				if (roomType == RoomType.RestSite)
				{
					await ClickRestSiteProceedIfNeeded(ct);
				}
				if (roomType == RoomType.Event)
				{
					await ClickEventProceedIfNeeded(ct);
				}
				MemoryProfiler.LogSnapshot($"post-room:{roomType}:Act{runState.CurrentActIndex + 1}:F{runState.ActFloor}");
				bool flag = roomType == RoomType.Boss && runState.Map.SecondBossMapPoint != null && runState.CurrentMapCoord == runState.Map.BossMapPoint.coord;
				if (roomType == RoomType.Boss && !flag)
				{
					_watchdog.Reset("Waiting for act transition after boss");
					RoomType postBossRoomType = RoomType.Boss;
					await WaitHelper.Until(delegate
					{
						AbstractRoom currentRoom = runState.CurrentRoom;
						if (currentRoom == null)
						{
							return false;
						}
						postBossRoomType = currentRoom.RoomType;
						return postBossRoomType != RoomType.Boss;
					}, ct, TimeSpan.FromSeconds(10L), "Act transition did not start after boss");
					AutoSlayLog.Info($"Post-boss transition: room type is now {postBossRoomType}");
					if (postBossRoomType == RoomType.Event && runState.CurrentActIndex >= runState.Acts.Count - 1)
					{
						_watchdog.Reset($"Entering {postBossRoomType} room (Act {runState.CurrentActIndex + 1}, Floor {runState.ActFloor})");
						AutoSlayLog.EnterRoom(postBossRoomType, runState.CurrentActIndex, runState.ActFloor);
						await HandleRoomAsync(postBossRoomType, ct);
						await WaitForGameOverScreenAsync(ct);
						await DrainOverlayScreensAsync(ct);
						_watchdog.Reset("Waiting for main menu after victory");
						await WaitForMainMenuAsync(ct);
						AutoSlayLog.Action("Victory! Run completed and returned to main menu");
						return;
					}
					await WaitHelper.Until(() => runState.VisitedMapCoords.Count == 0, ct, TimeSpan.FromSeconds(5L), "Act transition did not complete (VisitedMapCoords not cleared)");
					MemoryProfiler.LogSnapshot($"act-transition:Act{runState.CurrentActIndex + 1}");
				}
				_watchdog.Reset("Navigating map");
				await _mapHandler.HandleAsync(_random, ct);
			}
			AutoSlayLog.Action("Run completed (max floor reached). Abandoning");
			await AbandonRunAsync(ct);
		}

		private async Task HandleRoomAsync(RoomType roomType, CancellationToken ct)
		{
			if (!_roomHandlers.TryGetValue(roomType, out IRoomHandler handler))
			{
				AutoSlayLog.Warn($"No handler for room type: {roomType}");
			}
			else
			{
				await WaitHelper.WithTimeout((CancellationToken token) => handler.HandleAsync(_random, token), handler.Timeout, ct);
				AutoSlayLog.ExitRoom(roomType);
			}
		}

		/// <summary>
		/// Drains overlay screens until <paramref name="pending" /> completes.
		/// </summary>
		/// <remarks>
		/// A room handler that awaits something which opens a screen cannot rely on the drain
		/// between rooms: the run loop does not reach it until the room finishes, and the room is
		/// blocked on that task. Buying Orrery or Cauldron does exactly this, since both await
		/// <c>RewardsCmd.OfferCustom</c> when obtained. Driving the drain alongside the task breaks
		/// the cycle. The drain runs in fail-when-stuck mode here, because a screen it cannot close
		/// will never be closed by anyone else from this call site.
		/// </remarks>
		private async Task DrainOverlayScreensUntilAsync(Task pending, CancellationToken ct)
		{
			_ = 2;
			try
			{
				while (!pending.IsCompleted)
				{
					ct.ThrowIfCancellationRequested();
					NOverlayStack? instance = NOverlayStack.Instance;
					if (instance != null && instance.ScreenCount > 0)
					{
						await DrainOverlayScreensAsync(ct, failWhenStuck: true);
					}
					await Task.Delay(50, ct);
				}
				await pending;
			}
			finally
			{
				if (!pending.IsCompleted)
				{
					pending.ContinueWith((Task t) => t.Exception, TaskContinuationOptions.OnlyOnFaulted);
				}
			}
		}

		/// <param name="ct">Cancels the drain.</param>
		/// <param name="failWhenStuck">
		/// Throw instead of returning when the drain cannot close the screen on top. Callers that
		/// are waiting on that screen have no way to recover, so returning would spin them until an
		/// outer timeout fires with the real reason buried.
		/// </param>
		private async Task DrainOverlayScreensAsync(CancellationToken ct, bool failWhenStuck = false)
		{
			if (NOverlayStack.Instance == null)
			{
				await WaitHelper.Until(() => NOverlayStack.Instance != null, ct, AutoSlayConfig.nodeWaitTimeout, "Overlay stack not initialized");
			}
			int consecutiveNoProgress = 0;
			while (true)
			{
				NOverlayStack instance = NOverlayStack.Instance;
				if (instance == null || instance.ScreenCount == 0)
				{
					break;
				}
				ct.ThrowIfCancellationRequested();
				IOverlayScreen currentOverlay = instance.Peek();
				if (currentOverlay == null)
				{
					break;
				}
				Node node = (Node)currentOverlay;
				Type screenType = node.GetType();
				if (!_screenHandlers.TryGetValue(screenType, out IScreenHandler handler))
				{
					AutoSlayLog.Warn("No handler for screen type: " + screenType.Name);
					if (failWhenStuck)
					{
						throw new InvalidOperationException("No handler for screen " + screenType.Name + ", which is blocking a pending action");
					}
					break;
				}
				_watchdog.Reset("Handling screen: " + screenType.Name);
				int screenCountBefore = instance.ScreenCount;
				await WaitHelper.WithTimeout((CancellationToken token) => handler.HandleAsync(_random, token), handler.Timeout, ct);
				if (currentOverlay is NRewardsScreen && (NMapScreen.Instance?.IsOpen ?? false))
				{
					AutoSlayLog.Info("Rewards screen handled and map is open, exiting drain loop");
					if (failWhenStuck)
					{
						throw new InvalidOperationException("Map opened while a pending action was still waiting on the rewards screen");
					}
					break;
				}
				NOverlayStack instance2 = NOverlayStack.Instance;
				if (instance2 == null || instance2.ScreenCount != screenCountBefore || instance2.Peek() != currentOverlay)
				{
					consecutiveNoProgress = 0;
				}
				else
				{
					consecutiveNoProgress++;
					if (consecutiveNoProgress >= 3)
					{
						AutoSlayLog.Error($"Infinite loop detected: screen {screenType.Name} left the overlay stack unchanged after {3} handler attempts");
						throw new InvalidOperationException("Screen " + screenType.Name + " not closing after being handled");
					}
					AutoSlayLog.Warn($"Screen {screenType.Name} left the overlay stack unchanged after handling (attempt {consecutiveNoProgress})");
				}
				await Task.Delay(100, ct);
			}
		}

		private async Task ClickRestSiteProceedIfNeeded(CancellationToken ct)
		{
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			NProceedButton nodeOrNull = root.GetNodeOrNull<NProceedButton>("/root/Game/RootSceneContainer/Run/RoomContainer/RestSiteRoom/ProceedButton");
			if (nodeOrNull != null && nodeOrNull.IsEnabled)
			{
				AutoSlayLog.Action("Clicking rest site proceed button");
				await UiHelper.Click(nodeOrNull);
			}
		}

		private async Task ClickEventProceedIfNeeded(CancellationToken ct)
		{
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			Node eventRoom = root.GetNodeOrNull("/root/Game/RootSceneContainer/Run/RoomContainer/EventRoom");
			if (eventRoom == null)
			{
				AutoSlayLog.Info("Event room not found for proceed check");
				return;
			}
			NEventOptionButton proceedOption = null;
			await WaitHelper.Until(delegate
			{
				NMapScreen? instance = NMapScreen.Instance;
				if (instance != null && instance.IsOpen)
				{
					return true;
				}
				List<NEventOptionButton> list = (from o in UiHelper.FindAll<NEventOptionButton>(eventRoom)
					where !o.Option.IsLocked && o.Option.IsProceed
					select o).ToList();
				if (list.Count > 0)
				{
					proceedOption = list[0];
					return true;
				}
				return false;
			}, ct, TimeSpan.FromSeconds(5L), "Event proceed option or map did not appear");
			if (proceedOption != null)
			{
				AutoSlayLog.Action("Clicking event proceed option");
				await UiHelper.Click(proceedOption);
			}
			else
			{
				AutoSlayLog.Info("Map already open, no proceed needed");
			}
		}

		private async Task WaitForRewardsScreenAsync(CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for rewards screen");
			await WaitHelper.Until(() => NOverlayStack.Instance?.Peek() is NRewardsScreen || (NMapScreen.Instance?.IsOpen ?? false), ct, TimeSpan.FromSeconds(10L), "Rewards screen did not appear after combat");
		}

		private async Task WaitForGameOverScreenAsync(CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for game over screen");
			await WaitHelper.Until(() => NOverlayStack.Instance?.Peek() is NGameOverScreen, ct, TimeSpan.FromSeconds(10L), "Game over screen did not appear");
		}

		private async Task WaitForMainMenuAsync(CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for main menu");
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			await WaitHelper.Until(() => root.GetNodeOrNull<Control>("/root/Game/RootSceneContainer/MainMenu")?.IsVisibleInTree() ?? false, ct, TimeSpan.FromSeconds(30L), "Main menu did not appear after game over");
			AutoSlayLog.Action("Main menu appeared");
		}

		private async Task PlayMainMenuAsync(CancellationToken ct)
		{
			AutoSlayLog.Action("Playing main menu");
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			Control mainMenu = await WaitHelper.ForNode<Control>(root, "/root/Game/RootSceneContainer/MainMenu", ct, TimeSpan.FromSeconds(30L));
			NButton node = mainMenu.GetNode<NButton>("MainMenuTextButtons/AbandonRunButton");
			if (node.Visible)
			{
				AutoSlayLog.Action("Abandoning existing run");
				await UiHelper.Click(node);
				await WaitHelper.Until(() => NModalContainer.Instance?.OpenModal != null, ct, AutoSlayConfig.nodeWaitTimeout, "Abandon run confirmation popup did not appear");
				Node node2 = (Node)NModalContainer.Instance.OpenModal;
				NButton node3 = node2.GetNode<NButton>("VerticalPopup/YesButton");
				AutoSlayLog.Action("Confirming abandon");
				await UiHelper.Click(node3);
				await WaitHelper.Until(() => NModalContainer.Instance.OpenModal == null, ct, AutoSlayConfig.nodeWaitTimeout, "Abandon run confirmation popup did not close");
			}
			NButton node4 = mainMenu.GetNode<NButton>("MainMenuTextButtons/SingleplayerButton");
			AutoSlayLog.Action("Clicking singleplayer");
			await UiHelper.Click(node4);
			Control charSelectScreen = mainMenu.GetNodeOrNull<Control>("Submenus/CharacterSelectScreen");
			NButton standardButton = mainMenu.GetNodeOrNull<NButton>("Submenus/SingleplayerSubmenu/StandardButton");
			await WaitHelper.Until(delegate
			{
				charSelectScreen = mainMenu.GetNodeOrNull<Control>("Submenus/CharacterSelectScreen");
				standardButton = mainMenu.GetNodeOrNull<NButton>("Submenus/SingleplayerSubmenu/StandardButton");
				bool flag = charSelectScreen?.Visible ?? false;
				bool flag2 = standardButton?.Visible ?? false;
				return flag | flag2;
			}, ct, AutoSlayConfig.nodeWaitTimeout, "Neither CharacterSelectScreen nor SingleplayerSubmenu became visible");
			if (standardButton?.Visible ?? false)
			{
				Control control = charSelectScreen;
				if (control == null || !control.Visible)
				{
					AutoSlayLog.Action("Clicking standard run");
					await UiHelper.Click(standardButton);
					await WaitHelper.Until(() => mainMenu.GetNodeOrNull<Control>("Submenus/CharacterSelectScreen")?.Visible ?? false, ct, AutoSlayConfig.nodeWaitTimeout, "CharacterSelectScreen did not become visible");
					charSelectScreen = mainMenu.GetNode<Control>("Submenus/CharacterSelectScreen");
					goto IL_05e6;
				}
			}
			AutoSlayLog.Action("Skipping submenu (first run)");
			goto IL_05e6;
			IL_05e6:
			Node node5 = charSelectScreen.GetNode("CharSelectButtons/ButtonContainer");
			List<NCharacterSelectButton> list = UiHelper.FindAll<NCharacterSelectButton>(node5);
			foreach (NCharacterSelectButton item in list)
			{
				item.UnlockIfPossible();
			}
			List<NCharacterSelectButton> items = list.Where((NCharacterSelectButton b) => !b.IsLocked).ToList();
			NCharacterSelectButton nCharacterSelectButton = _random.NextItem(items);
			AutoSlayLog.Action($"Selecting character: {nCharacterSelectButton.Character.Id}");
			nCharacterSelectButton.Select();
			await Task.Delay(100, ct);
			NButton button = await WaitHelper.ForNode<NButton>(mainMenu, "Submenus/CharacterSelectScreen/ConfirmButton", ct);
			NGame.Instance.DebugSeedOverride = _seed;
			AutoSlayLog.Action("Confirming character");
			await UiHelper.Click(button);
		}

		private async Task AbandonRunAsync(CancellationToken ct)
		{
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			await Task.Delay(1000, ct);
			await UiHelper.Click(await WaitHelper.ForNode<NTopBarPauseButton>(root, "/root/Game/RootSceneContainer/Run/GlobalUi/TopBar/RightAlignedStuff/PauseButton", ct));
			NPauseMenu pauseMenu = null;
			await WaitHelper.Until(() => (pauseMenu = UiHelper.FindFirst<NPauseMenu>(root)) != null && pauseMenu.IsVisibleInTree(), ct, null, "Pause menu did not open");
			NPauseMenuButton node = pauseMenu.GetNode<Control>("%ButtonContainer").GetNode<NPauseMenuButton>("GiveUp");
			await UiHelper.Click(node);
			NAbandonRunConfirmPopup confirmPopup = null;
			await WaitHelper.Until(() => (confirmPopup = UiHelper.FindFirst<NAbandonRunConfirmPopup>(root)) != null, ct, null, "Abandon confirm popup did not appear");
			NVerticalPopup node2 = confirmPopup.GetNode<NVerticalPopup>("VerticalPopup");
			await UiHelper.Click(node2.YesButton);
			await WaitForGameOverScreenAsync(ct);
			await DrainOverlayScreensAsync(ct);
			await WaitForMainMenuAsync(ct);
		}

		private static void QuitGame(int exitCode)
		{
			AutoSlayLog.Action($"Quitting game with exit code {exitCode}");
			MegaLabel.DisposeCachedParagraph();
			MegaRichTextLabel.DisposeCachedParagraph();
			FontManager.ClearCache();
			NGame.Instance?.GetTree().Quit(exitCode);
		}
	}
	/// <summary>
	/// Structured logging for AutoSlay with consistent prefixes for easy filtering.
	/// Writes to both the standard Godot log and a dedicated autoslay.log file.
	/// </summary>
	public static class AutoSlayLog
	{
		private const string _prefix = "[AutoSlay]";

		private static StreamWriter? _fileWriter;

		private static readonly object _lock = new object();

		/// <summary>Opens the log file for writing. Call at start of autoslay run.</summary>
		public static void OpenLogFile(string path)
		{
			lock (_lock)
			{
				_fileWriter?.Dispose();
				_fileWriter = new StreamWriter(path, append: false)
				{
					AutoFlush = true
				};
			}
		}

		/// <summary>Closes the log file. Call at end of autoslay run.</summary>
		public static void CloseLogFile()
		{
			lock (_lock)
			{
				_fileWriter?.Dispose();
				_fileWriter = null;
			}
		}

		public static void Info(string message)
		{
			string text = "[AutoSlay] " + message;
			Log.Info(text);
			WriteToFile("INFO", text);
		}

		public static void Warn(string message)
		{
			string text = "[AutoSlay] " + message;
			Log.Warn(text);
			WriteToFile("WARN", text);
		}

		public static void Error(string message)
		{
			string text = "[AutoSlay] " + message;
			Log.Error(text);
			WriteToFile("ERROR", text);
		}

		public static void Error(string message, Exception ex)
		{
			string text = $"{"[AutoSlay]"} {message}: {ex.Message}\n{ex.StackTrace}";
			Log.Error(text);
			WriteToFile("ERROR", text);
		}

		private static void WriteToFile(string level, string message)
		{
			lock (_lock)
			{
				_fileWriter?.WriteLine($"{DateTime.Now:HH:mm:ss.fff} [{level}] {message}");
			}
		}

		public static void RunStarted(string seed)
		{
			string text = Path.Combine(OS.GetUserDataDir(), "logs", "godot.log");
			Info("Starting run with seed=" + seed);
			Info("Godot log: " + text);
		}

		public static void RunCompleted(string seed)
		{
			Info("Run completed successfully with seed=" + seed);
		}

		public static void RunFailed(string seed, Exception ex)
		{
			Error("Run failed with seed=" + seed, ex);
		}

		public static void EnterRoom(RoomType type, int act, int floor)
		{
			Info($"Entering {type} room (Act {act + 1}, Floor {floor})");
		}

		public static void ExitRoom(RoomType type)
		{
			Info($"Finished {type} room");
		}

		public static void EnterScreen(string screenName)
		{
			Info("Handling screen: " + screenName);
		}

		public static void ExitScreen(string screenName)
		{
			Info("Finished screen: " + screenName);
		}

		public static void Action(string action)
		{
			Info("Action: " + action);
		}

		public static void StateSnapshot(RunState? runState)
		{
			if (runState == null)
			{
				Info("State: RunState is null");
				return;
			}
			Info($"State: Floor={runState.TotalFloor}, Room={runState.CurrentRoom?.RoomType}, Act={runState.CurrentActIndex + 1}");
		}
	}
	/// <summary>
	/// Exception thrown when AutoSlay times out waiting for a condition or progress.
	/// Filtered from Sentry since these are expected during automated testing.
	/// </summary>
	public class AutoSlayTimeoutException : TimeoutException
	{
		public AutoSlayTimeoutException(string message)
			: base(message)
		{
		}
	}
	/// <summary>
	/// Captures memory and resource snapshots during AutoSlay runs, logging deltas
	/// from a baseline to detect memory/resource leaks.
	/// </summary>
	public static class MemoryProfiler
	{
		private record struct MemorySnapshot(ulong StaticMemBytes, ulong VramBytes, long GcTotalMemory, int ObjectCount, int ResourceCount, int NodeCount, int OrphanNodeCount, int CachedAssets, int MissedCacheAssets, int RootViewportSignals, int GcGen0, int GcGen1, int GcGen2);

		private static MemorySnapshot? _baseline;

		private static MemorySnapshot? _previous;

		private static int _snapshotCount;

		public static void SetBaseline()
		{
			MemorySnapshot memorySnapshot = Capture();
			_baseline = memorySnapshot;
			_previous = memorySnapshot;
			LogLine("baseline", memorySnapshot, memorySnapshot);
		}

		public static void LogSnapshot(string context)
		{
			MemorySnapshot memorySnapshot = Capture();
			MemorySnapshot baseline = _baseline ?? memorySnapshot;
			LogLine(context, memorySnapshot, baseline);
			_previous = memorySnapshot;
		}

		public static void Reset()
		{
			_baseline = null;
			_previous = null;
			_snapshotCount = 0;
		}

		private static MemorySnapshot Capture()
		{
			Window window = NGame.Instance?.GetTree()?.Root;
			int rootViewportSignals = 0;
			if (window != null)
			{
				Array<Dictionary> signalConnectionList = window.GetSignalConnectionList(Viewport.SignalName.SizeChanged);
				rootViewportSignals = signalConnectionList.Count;
			}
			return new MemorySnapshot(OS.GetStaticMemoryUsage(), RenderingServer.GetRenderingInfo(RenderingServer.RenderingInfo.VideoMemUsed), GC.GetTotalMemory(forceFullCollection: false), (int)Performance.GetMonitor(Performance.Monitor.ObjectCount), (int)Performance.GetMonitor(Performance.Monitor.ObjectResourceCount), (int)Performance.GetMonitor(Performance.Monitor.ObjectNodeCount), (int)Performance.GetMonitor(Performance.Monitor.ObjectOrphanNodeCount), PreloadManager.Cache.GetCacheKeys().Count(), PreloadManager.Cache.MissedCacheAssetCount, rootViewportSignals, GC.CollectionCount(0), GC.CollectionCount(1), GC.CollectionCount(2));
		}

		private static void LogLine(string context, MemorySnapshot current, MemorySnapshot baseline)
		{
			MemorySnapshot memorySnapshot = _previous ?? current;
			string text = $"[MemProfile] context={context} | StaticMem={Fmt(current.StaticMemBytes)}({Diff(current.StaticMemBytes, baseline.StaticMemBytes)}) VRAM={Fmt(current.VramBytes)}({Diff(current.VramBytes, baseline.VramBytes)}) GcMem={Fmt((ulong)current.GcTotalMemory)}({Diff((ulong)current.GcTotalMemory, (ulong)baseline.GcTotalMemory)}) Objects={current.ObjectCount}({Diff(current.ObjectCount, baseline.ObjectCount)}) Resources={current.ResourceCount}({Diff(current.ResourceCount, baseline.ResourceCount)}) Nodes={current.NodeCount}({Diff(current.NodeCount, baseline.NodeCount)}) Orphans={current.OrphanNodeCount}({Diff(current.OrphanNodeCount, baseline.OrphanNodeCount)}) CachedAssets={current.CachedAssets}({Diff(current.CachedAssets, baseline.CachedAssets)}) MissedCache={current.MissedCacheAssets}({Diff(current.MissedCacheAssets, baseline.MissedCacheAssets)}) RootSizeSignals={current.RootViewportSignals}({Diff(current.RootViewportSignals, baseline.RootViewportSignals)}) GC0={current.GcGen0}({Diff(current.GcGen0, baseline.GcGen0)}) GC1={current.GcGen1}({Diff(current.GcGen1, baseline.GcGen1)}) GC2={current.GcGen2}({Diff(current.GcGen2, baseline.GcGen2)})";
			if (_snapshotCount >= 2)
			{
				text += $" | room-delta: StaticMem={Diff(current.StaticMemBytes, memorySnapshot.StaticMemBytes)} VRAM={Diff(current.VramBytes, memorySnapshot.VramBytes)} GcMem={Diff((ulong)current.GcTotalMemory, (ulong)memorySnapshot.GcTotalMemory)} Objects={Diff(current.ObjectCount, memorySnapshot.ObjectCount)} Nodes={Diff(current.NodeCount, memorySnapshot.NodeCount)} Orphans={Diff(current.OrphanNodeCount, memorySnapshot.OrphanNodeCount)}";
			}
			_snapshotCount++;
			AutoSlayLog.Info(text);
		}

		private static string Fmt(ulong bytes)
		{
			return NGame.FormatBytes(bytes);
		}

		private static string Diff(ulong current, ulong baseline)
		{
			long num = (long)(current - baseline);
			if (num < 0)
			{
				return "-" + NGame.FormatBytes((ulong)(-num));
			}
			return "+" + NGame.FormatBytes((ulong)num);
		}

		private static string Diff(int current, int baseline)
		{
			int num = current - baseline;
			if (num >= 0)
			{
				return $"+{num}";
			}
			return $"{num}";
		}
	}
}
namespace MegaCrit.Sts2.Core.AutoSlay.Helpers
{
	/// <summary>
	/// Handles automatic card selection during AutoSlay runs.
	/// Randomly selects cards when the game would normally show a selection UI.
	/// </summary>
	public class AutoSlayCardSelector : MegaCrit.Sts2.Core.TestSupport.ICardSelector
	{
		private readonly Rng _random;

		public AutoSlayCardSelector(Rng random)
		{
			_random = random;
		}

		/// <summary>
		/// Randomly selects cards from the available options based on the selector preferences.
		/// </summary>
		public Task<IEnumerable<CardModel>> GetSelectedCards(IEnumerable<CardModel> options, int minSelect, int maxSelect)
		{
			List<CardModel> list = options.ToList();
			if (list.Count == 0)
			{
				return Task.FromResult((IEnumerable<CardModel>)System.Array.Empty<CardModel>());
			}
			int num = Math.Min(maxSelect, list.Count);
			if (num < minSelect)
			{
				num = Math.Min(minSelect, list.Count);
			}
			_random.Shuffle(list);
			IEnumerable<CardModel> result = list.Take(num);
			AutoSlayLog.Info($"Auto-selected {num} card(s) for selection prompt");
			return Task.FromResult(result);
		}

		/// <summary>
		/// Randomly selects a card reward from the available options.
		/// </summary>
		public CardRewardSelection GetSelectedCardReward(IReadOnlyList<CardCreationResult> options, IReadOnlyList<CardRewardAlternative> alternatives)
		{
			if (options.Count == 0)
			{
				return default(CardRewardSelection);
			}
			int index = _random.NextInt(options.Count);
			return new CardRewardSelection
			{
				card = options[index].Card,
				alternative = null
			};
		}
	}
	/// <summary>
	/// UI interaction utilities for AutoSlay.
	/// </summary>
	public static class UiHelper
	{
		/// <summary>
		/// Clicks a clickable control by directly emitting the Released signal.
		/// This bypasses hover/focus/pause checks that can fail in headless/automated testing.
		/// </summary>
		public static async Task Click(NClickableControl button, int delayMs = 100)
		{
			button.ForceClick();
			await Task.Delay(delayMs);
		}

		/// <summary>
		/// Finds all nodes of a specific type under a parent node recursively.
		/// </summary>
		public static List<T> FindAll<T>(Node start) where T : Node
		{
			List<T> list = new List<T>();
			if (GodotObject.IsInstanceValid(start))
			{
				FindAllRecursive(start, list);
			}
			return list;
		}

		private static void FindAllRecursive<T>(Node node, List<T> found) where T : Node
		{
			if (!GodotObject.IsInstanceValid(node))
			{
				return;
			}
			if (node is T item)
			{
				found.Add(item);
			}
			foreach (Node child in node.GetChildren())
			{
				FindAllRecursive(child, found);
			}
		}

		/// <summary>
		/// Finds the first node of a specific type under a parent node.
		/// </summary>
		public static T? FindFirst<T>(Node start) where T : Node
		{
			if (!GodotObject.IsInstanceValid(start))
			{
				return null;
			}
			if (start is T result)
			{
				return result;
			}
			foreach (Node child in start.GetChildren())
			{
				T val = FindFirst<T>(child);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}
	}
	/// <summary>
	/// Async waiting utilities for AutoSlay.
	/// </summary>
	public static class WaitHelper
	{
		/// <summary>
		/// Waits until a condition becomes true, with timeout.
		/// Also checks the watchdog periodically to detect stuck states.
		/// </summary>
		public static Task Until(Func<bool> condition, CancellationToken ct, TimeSpan? timeout = null, string? timeoutMessage = null)
		{
			return Until(condition, ct, timeout, (timeoutMessage == null) ? null : ((Func<string>)(() => timeoutMessage)));
		}

		/// <summary>
		/// Waits until a condition becomes true, building the timeout message only if it times out.
		/// </summary>
		/// <remarks>An interpolated string argument is evaluated when the wait starts, so it reports pre-wait state.</remarks>
		public static async Task Until(Func<bool> condition, CancellationToken ct, TimeSpan? timeout, Func<string>? timeoutMessage)
		{
			TimeSpan actualTimeout = timeout ?? AutoSlayConfig.nodeWaitTimeout;
			using CancellationTokenSource timeoutCts = new CancellationTokenSource(actualTimeout);
			using CancellationTokenSource linkedCts = CancellationTokenSource.CreateLinkedTokenSource(ct, timeoutCts.Token);
			try
			{
				while (!condition())
				{
					AutoSlayer.CurrentWatchdog?.Check();
					await Task.Delay(AutoSlayConfig.pollingInterval, linkedCts.Token);
				}
			}
			catch (OperationCanceledException) when (timeoutCts.IsCancellationRequested)
			{
				string message = timeoutMessage?.Invoke() ?? $"Condition not met after {actualTimeout.TotalSeconds}s";
				throw new AutoSlayTimeoutException(message);
			}
		}

		/// <summary>
		/// Waits for a node to exist at the given path.
		/// </summary>
		public static async Task<T> ForNode<T>(Node root, string nodePath, CancellationToken ct, TimeSpan? timeout = null) where T : Node
		{
			try
			{
				await Until(() => root.HasNode(nodePath), ct, timeout, $"Node {nodePath} of type {typeof(T).Name} not found");
			}
			catch (TimeoutException)
			{
				DumpSceneTreeContext(root, nodePath, "not found");
				throw;
			}
			T node = root.GetNode<T>(nodePath);
			Control control = node as Control;
			if (control != null)
			{
				try
				{
					await Until(() => control.Visible, ct, timeout, "Node " + nodePath + " not visible");
				}
				catch (TimeoutException)
				{
					DumpSceneTreeContext(root, nodePath, "not visible");
					throw;
				}
				NButton nButton = node as NButton;
				if (nButton != null)
				{
					try
					{
						await Until(() => nButton.IsEnabled, ct, timeout, "Button " + nodePath + " not enabled");
					}
					catch (TimeoutException)
					{
						DumpSceneTreeContext(root, nodePath, "not enabled");
						throw;
					}
				}
			}
			return node;
		}

		/// <summary>
		/// Dumps scene tree context when a wait times out, to help debug what's actually there.
		/// </summary>
		private static void DumpSceneTreeContext(Node root, string nodePath, string reason)
		{
			StringBuilder stringBuilder = new StringBuilder();
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(35, 1, stringBuilder2);
			handler.AppendLiteral("[AutoSlay] Scene tree dump (node ");
			handler.AppendFormatted(reason);
			handler.AppendLiteral("):");
			stringBuilder3.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(15, 1, stringBuilder2);
			handler.AppendLiteral("  Looking for: ");
			handler.AppendFormatted(nodePath);
			stringBuilder4.AppendLine(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder5 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(11, 2, stringBuilder2);
			handler.AppendLiteral("  Root: ");
			handler.AppendFormatted(root.Name);
			handler.AppendLiteral(" (");
			handler.AppendFormatted(root.GetType().Name);
			handler.AppendLiteral(")");
			stringBuilder5.AppendLine(ref handler);
			int num = nodePath.LastIndexOf('/');
			string text = ((num > 0) ? nodePath.Substring(0, num) : "");
			string text2;
			if (num <= 0)
			{
				text2 = nodePath;
			}
			else
			{
				int num2 = num + 1;
				text2 = nodePath.Substring(num2, nodePath.Length - num2);
			}
			string value = text2;
			Node node = (string.IsNullOrEmpty(text) ? root : root.GetNodeOrNull(text));
			if (node == null)
			{
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder6 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(32, 1, stringBuilder2);
				handler.AppendLiteral("  Parent path '");
				handler.AppendFormatted(text);
				handler.AppendLiteral("' does not exist!");
				stringBuilder6.AppendLine(ref handler);
				string[] array = text.Split('/');
				Node node2 = root;
				string text3 = "";
				string[] array2 = array;
				foreach (string text4 in array2)
				{
					if (!string.IsNullOrEmpty(text4))
					{
						text3 = text3 + ((text3.Length > 0) ? "/" : "") + text4;
						Node nodeOrNull = node2.GetNodeOrNull(text4);
						if (nodeOrNull == null)
						{
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder7 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(18, 1, stringBuilder2);
							handler.AppendLiteral("  Path broken at: ");
							handler.AppendFormatted(text3);
							stringBuilder7.AppendLine(ref handler);
							stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder8 = stringBuilder2;
							handler = new StringBuilder.AppendInterpolatedStringHandler(15, 1, stringBuilder2);
							handler.AppendLiteral("  Children of ");
							handler.AppendFormatted(node2.Name);
							handler.AppendLiteral(":");
							stringBuilder8.AppendLine(ref handler);
							DumpChildren(node2, stringBuilder, 2, 2);
							break;
						}
						node2 = nodeOrNull;
					}
				}
			}
			else
			{
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder9 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(13, 2, stringBuilder2);
				handler.AppendLiteral("  Parent: ");
				handler.AppendFormatted(node.Name);
				handler.AppendLiteral(" (");
				handler.AppendFormatted(node.GetType().Name);
				handler.AppendLiteral(")");
				stringBuilder9.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder10 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(21, 1, stringBuilder2);
				handler.AppendLiteral("  Looking for child: ");
				handler.AppendFormatted(value);
				stringBuilder10.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder11 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(15, 1, stringBuilder2);
				handler.AppendLiteral("  Children of ");
				handler.AppendFormatted(node.Name);
				handler.AppendLiteral(":");
				stringBuilder11.AppendLine(ref handler);
				DumpChildren(node, stringBuilder, 2, 3);
			}
			AutoSlayLog.Info(stringBuilder.ToString().TrimEnd());
		}

		private static void DumpChildren(Node node, StringBuilder sb, int depth, int maxDepth, string indent = "    ")
		{
			foreach (Node child in node.GetChildren())
			{
				string text = $"{child.Name} ({child.GetType().Name})";
				if (child is Control control)
				{
					text += (control.Visible ? " [visible]" : " [hidden]");
				}
				if (child is NButton nButton)
				{
					text += (nButton.IsEnabled ? " [enabled]" : " [disabled]");
				}
				StringBuilder stringBuilder = sb;
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(0, 2, stringBuilder);
				handler.AppendFormatted(indent);
				handler.AppendFormatted(text);
				stringBuilder2.AppendLine(ref handler);
				if (depth < maxDepth)
				{
					DumpChildren(child, sb, depth + 1, maxDepth, indent + "  ");
				}
				else if (child.GetChildCount() > 0)
				{
					stringBuilder = sb;
					StringBuilder stringBuilder3 = stringBuilder;
					handler = new StringBuilder.AppendInterpolatedStringHandler(17, 2, stringBuilder);
					handler.AppendFormatted(indent);
					handler.AppendLiteral("  ... (");
					handler.AppendFormatted(child.GetChildCount());
					handler.AppendLiteral(" children)");
					stringBuilder3.AppendLine(ref handler);
				}
			}
		}

		/// <summary>
		/// Waits for a task to complete while periodically checking the watchdog.
		/// </summary>
		public static async Task ForTask(Task task, CancellationToken ct, TimeSpan? timeout = null, string? timeoutMessage = null)
		{
			TimeSpan actualTimeout = timeout ?? AutoSlayConfig.nodeWaitTimeout;
			using CancellationTokenSource timeoutCts = new CancellationTokenSource(actualTimeout);
			using CancellationTokenSource linkedCts = CancellationTokenSource.CreateLinkedTokenSource(ct, timeoutCts.Token);
			_ = 1;
			try
			{
				while (!task.IsCompleted)
				{
					AutoSlayer.CurrentWatchdog?.Check();
					Task task2 = Task.Delay(AutoSlayConfig.pollingInterval, linkedCts.Token);
					await Task.WhenAny(task, task2);
				}
				await task;
			}
			catch (OperationCanceledException) when (timeoutCts.IsCancellationRequested)
			{
				string message = timeoutMessage ?? $"Task not completed after {actualTimeout.TotalSeconds}s";
				throw new AutoSlayTimeoutException(message);
			}
		}

		/// <summary>
		/// Runs a task with a timeout, combining with an existing cancellation token.
		/// </summary>
		public static async Task WithTimeout(Func<CancellationToken, Task> action, TimeSpan timeout, CancellationToken ct)
		{
			using CancellationTokenSource linkedCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
			Task task = action(linkedCts.Token);
			Task task2 = Task.Delay(timeout, linkedCts.Token);
			Task completedTask = await Task.WhenAny(task, task2);
			await linkedCts.CancelAsync();
			if (completedTask == task || ct.IsCancellationRequested)
			{
				await task;
				return;
			}
			throw new AutoSlayTimeoutException($"Operation timed out after {timeout.TotalSeconds}s");
		}
	}
	/// <summary>
	/// Watchdog that detects when AutoSlay gets stuck and dumps diagnostic state.
	/// </summary>
	public class Watchdog
	{
		private DateTime _lastProgressTime;

		private DateTime _lastLogTime;

		private string _lastActivity = "Starting";

		public Watchdog()
		{
			Reset("Initialized");
		}

		/// <summary>
		/// Resets the watchdog timer. Call this whenever meaningful progress is made.
		/// </summary>
		public void Reset(string activity)
		{
			_lastProgressTime = DateTime.UtcNow;
			_lastActivity = activity;
		}

		/// <summary>
		/// Checks if the watchdog has timed out. Call this periodically (e.g., in WaitHelper).
		/// Throws TimeoutException if no progress for too long.
		/// </summary>
		public void Check()
		{
			TimeSpan timeSpan = DateTime.UtcNow - _lastProgressTime;
			if (timeSpan > AutoSlayConfig.watchdogLogInterval && DateTime.UtcNow - _lastLogTime > AutoSlayConfig.watchdogLogInterval)
			{
				_lastLogTime = DateTime.UtcNow;
				AutoSlayLog.Info($"[Watchdog] No progress for {timeSpan.TotalSeconds:F1}s (last: {_lastActivity})");
			}
			if (timeSpan > AutoSlayConfig.watchdogTimeout)
			{
				string value = DumpState();
				AutoSlayLog.Error($"[Watchdog] Stuck detected! No progress for {timeSpan.TotalSeconds:F1}s\nLast activity: {_lastActivity}\n{value}");
				throw new AutoSlayTimeoutException($"Watchdog timeout: No progress for {timeSpan.TotalSeconds:F1}s. Last activity: {_lastActivity}");
			}
		}

		/// <summary>
		/// Dumps the current game state for debugging.
		/// </summary>
		public static string DumpState()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("=== AutoSlay State Dump ===");
			try
			{
				RunState runState = RunManager.Instance.DebugOnlyGetState();
				if (runState != null)
				{
					stringBuilder.AppendLine("Run State:");
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder3 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(24, 3, stringBuilder2);
					handler.AppendLiteral("  Floor: ");
					handler.AppendFormatted(runState.TotalFloor);
					handler.AppendLiteral(" (Act ");
					handler.AppendFormatted(runState.CurrentActIndex + 1);
					handler.AppendLiteral(", Floor ");
					handler.AppendFormatted(runState.ActFloor);
					handler.AppendLiteral(")");
					stringBuilder3.AppendLine(ref handler);
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder4 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(8, 1, stringBuilder2);
					handler.AppendLiteral("  Room: ");
					handler.AppendFormatted(runState.CurrentRoom?.RoomType.ToString() ?? "null");
					stringBuilder4.AppendLine(ref handler);
				}
				else
				{
					stringBuilder.AppendLine("Run State: Not initialized");
				}
				if (NOverlayStack.Instance != null)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder5 = stringBuilder2;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(23, 1, stringBuilder2);
					handler.AppendLiteral("Overlay Stack: ");
					handler.AppendFormatted(NOverlayStack.Instance.ScreenCount);
					handler.AppendLiteral(" screens");
					stringBuilder5.AppendLine(ref handler);
					IOverlayScreen overlayScreen = NOverlayStack.Instance.Peek();
					if (overlayScreen != null)
					{
						stringBuilder2 = stringBuilder;
						StringBuilder stringBuilder6 = stringBuilder2;
						handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
						handler.AppendLiteral("  Current: ");
						handler.AppendFormatted(overlayScreen.GetType().Name);
						stringBuilder6.AppendLine(ref handler);
					}
				}
				Node instance = NGame.Instance;
				if (instance != null)
				{
					stringBuilder.AppendLine("Scene Container:");
					Node nodeOrNull = instance.GetNodeOrNull("RootSceneContainer");
					if (nodeOrNull != null)
					{
						foreach (Node child in nodeOrNull.GetChildren())
						{
							string value = ((child is Control control) ? (control.Visible ? "visible" : "hidden") : "");
							StringBuilder stringBuilder2 = stringBuilder;
							StringBuilder stringBuilder7 = stringBuilder2;
							StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(10, 3, stringBuilder2);
							handler.AppendLiteral("  - ");
							handler.AppendFormatted(child.Name);
							handler.AppendLiteral(" (");
							handler.AppendFormatted(child.GetType().Name);
							handler.AppendLiteral(") [");
							handler.AppendFormatted(value);
							handler.AppendLiteral("]");
							stringBuilder7.AppendLine(ref handler);
						}
					}
				}
			}
			catch (Exception ex)
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder8 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(21, 1, stringBuilder2);
				handler.AppendLiteral("Error dumping state: ");
				handler.AppendFormatted(ex.Message);
				stringBuilder8.AppendLine(ref handler);
			}
			stringBuilder.AppendLine("=== End State Dump ===");
			return stringBuilder.ToString();
		}
	}
}
namespace MegaCrit.Sts2.Core.AutoSlay.Handlers
{
	/// <summary>
	/// Base interface for all AutoSlay handlers.
	/// </summary>
	public interface IHandler
	{
		/// <summary>Timeout for this handler.</summary>
		TimeSpan Timeout { get; }

		/// <summary>Executes the handler logic.</summary>
		Task HandleAsync(Rng random, CancellationToken ct);
	}
	/// <summary>
	/// Handler for a specific room type.
	/// </summary>
	public interface IRoomHandler : IHandler
	{
		/// <summary>The room types this handler can handle.</summary>
		RoomType[] HandledTypes { get; }
	}
	/// <summary>
	/// Handler for a specific overlay screen type.
	/// </summary>
	public interface IScreenHandler : IHandler
	{
		/// <summary>The screen type this handler can handle.</summary>
		Type ScreenType { get; }
	}
}
namespace MegaCrit.Sts2.Core.AutoSlay.Handlers.Screens
