			NClickableControl button = random.NextItem(list);
			AutoSlayLog.Action("Selecting relic");
			await UiHelper.Click(button);
			AutoSlayLog.ExitScreen("NChooseARelicSelection");
		}
	}
	/// <summary>
	/// Handles the Crystal Sphere minigame event screen.
	/// Uses divinations by clicking cells, then clicks proceed.
	/// Note: When divinations run out, a rewards screen opens automatically.
	/// The drain loop will handle that, then this handler runs again to click proceed.
	/// </summary>
	public class CrystalSphereScreenHandler : IScreenHandler, IHandler
	{
		public Type ScreenType => typeof(NCrystalSphereScreen);

		public TimeSpan Timeout => TimeSpan.FromSeconds(120L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NCrystalSphereScreen");
			NCrystalSphereScreen screen = AutoSlayer.GetCurrentScreen<NCrystalSphereScreen>();
			await Task.Delay(1000, ct);
			NProceedButton proceedButton = screen.GetNodeOrNull<NProceedButton>("%ProceedButton");
			if (proceedButton?.IsEnabled ?? false)
			{
				AutoSlayLog.Action("Clicking Crystal Sphere proceed button");
				await UiHelper.Click(proceedButton);
				await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree() || (NMapScreen.Instance?.IsVisibleInTree() ?? false), ct, TimeSpan.FromSeconds(10L), "Crystal Sphere screen did not close after clicking proceed");
				if (GodotObject.IsInstanceValid(screen) && screen.IsVisibleInTree())
				{
					NMapScreen instance = NMapScreen.Instance;
					if (instance != null && instance.IsVisibleInTree())
					{
						AutoSlayLog.Info("Map opened, manually removing Crystal Sphere screen from overlay stack");
						NOverlayStack.Instance?.Remove(screen);
						await Task.Delay(100, ct);
					}
				}
				AutoSlayLog.ExitScreen("NCrystalSphereScreen");
				return;
			}
			int maxClicks = 20;
			int clicks = 0;
			int lastClickableCount = int.MaxValue;
			int noProgressCount = 0;
			while (clicks < maxClicks)
			{
				ct.ThrowIfCancellationRequested();
				if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
				{
					break;
				}
				IOverlayScreen overlayScreen = NOverlayStack.Instance?.Peek();
				if (overlayScreen != null && overlayScreen != screen)
				{
					AutoSlayLog.Info("Child screen appeared (rewards), returning to drain loop");
					AutoSlayLog.ExitScreen("NCrystalSphereScreen");
					return;
				}
				proceedButton = screen.GetNodeOrNull<NProceedButton>("%ProceedButton");
				if (proceedButton?.IsEnabled ?? false)
				{
					break;
				}
				Control nodeOrNull = screen.GetNodeOrNull<Control>("%Cells");
				if (nodeOrNull == null)
				{
					await Task.Delay(100, ct);
					continue;
				}
				List<NCrystalSphereCell> list = (from c in UiHelper.FindAll<NCrystalSphereCell>(nodeOrNull)
					where c.Visible && c.Entity.IsHidden
					select c).ToList();
				if (list.Count == 0)
				{
					AutoSlayLog.Info("No more clickable cells, waiting for rewards or proceed");
					break;
				}
				if (list.Count >= lastClickableCount)
				{
					noProgressCount++;
					if (noProgressCount > 5)
					{
						AutoSlayLog.Info($"No progress after {noProgressCount} clicks, divinations likely exhausted");
						break;
					}
				}
				else
				{
					noProgressCount = 0;
				}
				lastClickableCount = list.Count;
				NCrystalSphereCell nCrystalSphereCell = random.NextItem(list);
				AutoSlayLog.Info($"Clicking crystal sphere cell at ({nCrystalSphereCell.Entity.X}, {nCrystalSphereCell.Entity.Y}), click {clicks + 1}, {list.Count} clickable");
				nCrystalSphereCell.EmitSignal(NClickableControl.SignalName.Released, nCrystalSphereCell);
				await Task.Delay(500, ct);
				clicks++;
			}
			await WaitHelper.Until(delegate
			{
				proceedButton = screen.GetNodeOrNull<NProceedButton>("%ProceedButton");
				NProceedButton nProceedButton = proceedButton;
				if (nProceedButton != null && nProceedButton.IsEnabled)
				{
					return true;
				}
				if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
				{
					return true;
				}
				IOverlayScreen overlayScreen3 = NOverlayStack.Instance?.Peek();
				return overlayScreen3 != null && overlayScreen3 != screen;
			}, ct, TimeSpan.FromSeconds(15L), "Crystal Sphere: neither proceed button nor rewards screen appeared");
			IOverlayScreen overlayScreen2 = NOverlayStack.Instance?.Peek();
			if (overlayScreen2 != null && overlayScreen2 != screen)
			{
				AutoSlayLog.Info("Rewards screen appeared, returning to drain loop");
				AutoSlayLog.ExitScreen("NCrystalSphereScreen");
				return;
			}
			if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
			{
				AutoSlayLog.ExitScreen("NCrystalSphereScreen");
				return;
			}
			proceedButton = screen.GetNodeOrNull<NProceedButton>("%ProceedButton");
			if (proceedButton != null && proceedButton.IsEnabled)
			{
				AutoSlayLog.Action("Clicking Crystal Sphere proceed button");
				await UiHelper.Click(proceedButton);
				await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree() || (NMapScreen.Instance?.IsVisibleInTree() ?? false), ct, TimeSpan.FromSeconds(10L), "Crystal Sphere screen did not close after clicking proceed");
				if (GodotObject.IsInstanceValid(screen) && screen.IsVisibleInTree())
				{
					NMapScreen instance2 = NMapScreen.Instance;
					if (instance2 != null && instance2.IsVisibleInTree())
					{
						AutoSlayLog.Info("Map opened, manually removing Crystal Sphere screen from overlay stack");
						NOverlayStack.Instance?.Remove(screen);
						await Task.Delay(100, ct);
					}
				}
			}
			AutoSlayLog.ExitScreen("NCrystalSphereScreen");
		}
	}
	/// <summary>
	/// Handles the deck card selection screen (removal, transform, etc).
	/// The screen has two confirm buttons: one for the main grid, and one in the preview container.
	/// When selecting exactly MaxSelect cards, the screen auto-shows the preview, so we need to click
	/// the preview confirm button, not the main one.
	/// </summary>
	public class DeckCardSelectScreenHandler : IScreenHandler, IHandler
	{
		public Type ScreenType => typeof(NDeckCardSelectScreen);

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NDeckCardSelectScreen");
			NDeckCardSelectScreen screen = AutoSlayer.GetCurrentScreen<NDeckCardSelectScreen>();
			List<NGridCardHolder> cards = new List<NGridCardHolder>();
			await WaitHelper.Until(delegate
			{
				cards = UiHelper.FindAll<NGridCardHolder>(screen);
				return cards.Count > 0;
			}, ct, TimeSpan.FromSeconds(5L), "No cards found in card select screen");
			await Task.Delay(300, ct);
			int maxSelections = Math.Min(cards.Count, 5);
			List<NGridCardHolder> selectedCards = new List<NGridCardHolder>();
			Control previewContainer;
			NConfirmButton nodeOrNull;
			for (int i = 0; i < maxSelections; i++)
			{
				previewContainer = screen.GetNodeOrNull<Control>("%PreviewContainer");
				nodeOrNull = screen.GetNodeOrNull<NConfirmButton>("%Confirm");
				if ((previewContainer?.Visible ?? false) || (nodeOrNull != null && nodeOrNull.IsEnabled))
				{
					break;
				}
				List<NGridCardHolder> list = cards.Where((NGridCardHolder c) => !selectedCards.Contains(c)).ToList();
				if (list.Count == 0)
				{
					break;
				}
				NGridCardHolder nGridCardHolder = random.NextItem(list);
				selectedCards.Add(nGridCardHolder);
				AutoSlayLog.Action($"Selecting card {i + 1} ({cards.Count} cards available)");
				nGridCardHolder.EmitSignal(NCardHolder.SignalName.Pressed, nGridCardHolder);
				await Task.Delay(200, ct);
			}
			previewContainer = screen.GetNodeOrNull<Control>("%PreviewContainer");
			nodeOrNull = screen.GetNodeOrNull<NConfirmButton>("%Confirm");
			Control control = previewContainer;
			if ((control == null || !control.Visible) && nodeOrNull != null && nodeOrNull.IsEnabled)
			{
				AutoSlayLog.Action("Clicking main confirm button to show preview");
				await UiHelper.Click(nodeOrNull);
				await Task.Delay(200, ct);
			}
			await WaitHelper.Until(delegate
			{
				previewContainer = screen.GetNodeOrNull<Control>("%PreviewContainer");
				return previewContainer?.Visible ?? false;
			}, ct, TimeSpan.FromSeconds(5L), "Preview container did not appear");
			await Task.Delay(500, ct);
			NConfirmButton confirmButton = previewContainer?.GetNodeOrNull<NConfirmButton>("%PreviewConfirm");
			if (confirmButton == null)
			{
				List<NConfirmButton> source = UiHelper.FindAll<NConfirmButton>(screen);
				confirmButton = source.FirstOrDefault((NConfirmButton b) => b.IsEnabled);
			}
			if (confirmButton != null)
			{
				await WaitHelper.Until(() => confirmButton.IsEnabled, ct, TimeSpan.FromSeconds(5L), "Card select confirm button did not become enabled");
				AutoSlayLog.Action("Confirming selection");
				await UiHelper.Click(confirmButton);
				await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree(), ct, TimeSpan.FromSeconds(10L), "Card select screen did not close after confirmation");
			}
			else
			{
				AutoSlayLog.Error("No confirm button found on card select screen");
			}
			AutoSlayLog.ExitScreen("NDeckCardSelectScreen");
		}
	}
