			AutoSlayLog.EnterScreen("NDeckTransformSelectScreen");
			NDeckTransformSelectScreen screen = AutoSlayer.GetCurrentScreen<NDeckTransformSelectScreen>();
			NCardGrid grid = UiHelper.FindFirst<NCardGrid>(screen);
