	/// <summary>
	/// Handles the deck upgrade selection screen.
	/// </summary>
	public class DeckUpgradeScreenHandler : IScreenHandler, IHandler
	{
		public Type ScreenType => typeof(NDeckUpgradeSelectScreen);

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NDeckUpgradeSelectScreen");
			NDeckUpgradeSelectScreen screen = AutoSlayer.GetCurrentScreen<NDeckUpgradeSelectScreen>();
			List<NGridCardHolder> cards = UiHelper.FindAll<NGridCardHolder>(screen);
			if (cards.Count == 0)
			{
				AutoSlayLog.Warn("No cards found in upgrade screen");
				return;
			}
			int maxSelections = Math.Min(cards.Count, 5);
			for (int i = 0; i < maxSelections; i++)
			{
				if (!GodotObject.IsInstanceValid(screen))
				{
					break;
				}
				if (!screen.IsVisibleInTree())
				{
					break;
				}
				Control nodeOrNull = screen.GetNodeOrNull<Control>("%UpgradeSinglePreviewContainer");
				Control nodeOrNull2 = screen.GetNodeOrNull<Control>("%UpgradeMultiPreviewContainer");
				if ((nodeOrNull != null && nodeOrNull.Visible) || (nodeOrNull2 != null && nodeOrNull2.Visible))
				{
					break;
				}
				NGridCardHolder nGridCardHolder = random.NextItem(cards);
				AutoSlayLog.Action("Selecting card to upgrade");
				nGridCardHolder.EmitSignal(NCardHolder.SignalName.Pressed, nGridCardHolder);
				cards.Remove(nGridCardHolder);
				await Task.Delay(300, ct);
			}
			Control visiblePreview = null;
			await WaitHelper.Until(delegate
			{
				Control nodeOrNull3 = screen.GetNodeOrNull<Control>("%UpgradeSinglePreviewContainer");
				Control nodeOrNull4 = screen.GetNodeOrNull<Control>("%UpgradeMultiPreviewContainer");
				if (nodeOrNull3 != null && nodeOrNull3.Visible)
				{
					visiblePreview = nodeOrNull3;
					return true;
				}
				if (nodeOrNull4 != null && nodeOrNull4.Visible)
				{
					visiblePreview = nodeOrNull4;
					return true;
				}
				return !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree();
			}, ct, TimeSpan.FromSeconds(5L), "Upgrade preview did not appear");
			if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
			{
				AutoSlayLog.ExitScreen("NDeckUpgradeSelectScreen");
				return;
			}
			NConfirmButton confirmButton = visiblePreview?.GetNodeOrNull<NConfirmButton>("Confirm");
			if (confirmButton == null)
			{
				AutoSlayLog.Error("Preview confirm button not found");
				AutoSlayLog.ExitScreen("NDeckUpgradeSelectScreen");
				return;
			}
			await WaitHelper.Until(() => confirmButton.IsEnabled, ct, TimeSpan.FromSeconds(5L), "Upgrade confirm button did not become enabled");
			AutoSlayLog.Action("Confirming upgrade");
			await UiHelper.Click(confirmButton);
			await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree(), ct, TimeSpan.FromSeconds(10L), "Upgrade screen did not close after confirmation");
			AutoSlayLog.ExitScreen("NDeckUpgradeSelectScreen");
		}
	}
	/// <summary>
	/// Handles the game over screen (shown after victory or death).
	/// Clicks through the summary to return to main menu.
	/// </summary>
	public class GameOverScreenHandler : IScreenHandler, IHandler
	{
		public Type ScreenType => typeof(NGameOverScreen);

		public TimeSpan Timeout => TimeSpan.FromMinutes(2L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NGameOverScreen");
			NGameOverScreen screen = AutoSlayer.GetCurrentScreen<NGameOverScreen>();
			NGameOverContinueButton continueButton = UiHelper.FindFirst<NGameOverContinueButton>(screen);
			if (continueButton == null)
			{
				AutoSlayLog.Error("Continue button not found on game over screen");
				return;
			}
			await WaitHelper.Until(() => continueButton.IsEnabled, ct, TimeSpan.FromSeconds(30L), "Continue button did not become enabled");
			AutoSlayLog.Action("Clicking continue button");
			await UiHelper.Click(continueButton);
			NReturnToMainMenuButton mainMenuButton = null;
			int waitCycles = 0;
			await WaitHelper.Until(delegate
			{
				if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
				{
					return true;
				}
				mainMenuButton = UiHelper.FindFirst<NReturnToMainMenuButton>(screen);
				waitCycles++;
				if (waitCycles % 20 == 0)
				{
					bool value = mainMenuButton != null;
					bool value2 = mainMenuButton?.Visible ?? false;
					bool value3 = mainMenuButton?.IsEnabled ?? false;
					AutoSlayLog.Info($"Waiting for main menu button: found={value}, visible={value2}, enabled={value3}");
					AutoSlayer.CurrentWatchdog?.Reset("Waiting for game over summary animation");
				}
				NReturnToMainMenuButton nReturnToMainMenuButton = mainMenuButton;
				return nReturnToMainMenuButton != null && nReturnToMainMenuButton.Visible && mainMenuButton.IsEnabled;
			}, ct, TimeSpan.FromSeconds(90L), "Main menu button did not become enabled");
			if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
			{
				AutoSlayLog.Action("Game over screen closed automatically");
				AutoSlayLog.ExitScreen("NGameOverScreen");
				return;
			}
			AutoSlayLog.Action("Clicking main menu button");
			await UiHelper.Click(mainMenuButton);
			await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree(), ct, TimeSpan.FromSeconds(30L), "Game over screen did not close");
			AutoSlayLog.ExitScreen("NGameOverScreen");
		}
	}
	/// <summary>
	/// Handles map screen navigation between rooms.
	/// </summary>
	public class MapScreenHandler : IScreenHandler, IHandler
	{
		private TaskCompletionSource? _roomEnteredTcs;

		public Type ScreenType => typeof(NMapScreen);

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NMapScreen");
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			NRun runNode = root.GetNode<NRun>("/root/Game/RootSceneContainer/Run");
			await WaitHelper.Until(() => runNode.GlobalUi.MapScreen.IsVisibleInTree(), ct, AutoSlayConfig.mapScreenTimeout, "Map screen not visible");
			NMapScreen mapScreen = runNode.GlobalUi.MapScreen;
			NMapPoint nextRoom = null;
			try
			{
				await WaitHelper.Until(() => (nextRoom = SelectNextRoom(mapScreen))?.IsEnabled ?? false, ct, AutoSlayConfig.mapPointEnabledTimeout, "Map point not enabled");
			}
			catch (AutoSlayTimeoutException)
			{
				AutoSlayLog.Info("[AutoSlay] Map point never became travelable: node=" + ((nextRoom == null) ? "none" : nextRoom.Point.coord.ToString()) + ", state=" + ((nextRoom == null) ? "n/a" : nextRoom.State.ToString()) + ", " + $"screenTravelEnabled={mapScreen.IsTravelEnabled}");
				throw;
			}
			AutoSlayLog.Action($"Selecting room at ({nextRoom.Point.coord.row}, {nextRoom.Point.coord.col})");
			_roomEnteredTcs = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			RunManager.Instance.RoomEntered += OnRoomEntered;
			try
			{
				await UiHelper.Click(nextRoom);
				await WaitHelper.ForTask(_roomEnteredTcs.Task, ct, AutoSlayConfig.mapScreenTimeout, "Room not entered after map click");
			}
			finally
			{
				RunManager.Instance.RoomEntered -= OnRoomEntered;
				_roomEnteredTcs = null;
			}
			AutoSlayLog.ExitScreen("NMapScreen");
		}

		/// <summary>
		/// Resolves the next room to travel to from the live map points, or null when the expected node is
		/// not present yet (for example mid act-transition while the new act's map is still being generated).
		/// Returning null keeps the caller polling instead of latching onto a stale node from the prior act.
		/// </summary>
		private static NMapPoint? SelectNextRoom(NMapScreen mapScreen)
		{
			List<NMapPoint> source = UiHelper.FindAll<NMapPoint>(mapScreen);
			RunState runState = RunManager.Instance.DebugOnlyGetState();
			if (runState.VisitedMapCoords.Count == 0)
			{
				return source.FirstOrDefault((NMapPoint mp) => mp.Point.coord.row == 0);
			}
			IReadOnlyList<MapCoord> visitedMapCoords = runState.VisitedMapCoords;
			MapCoord lastCoord = visitedMapCoords[visitedMapCoords.Count - 1];
			MapPoint child = source.FirstOrDefault((NMapPoint mp) => mp.Point.coord.Equals(lastCoord))?.Point.Children.FirstOrDefault();
			if (child != null)
			{
				return source.FirstOrDefault((NMapPoint mp) => mp.Point.coord.Equals(child.coord));
			}
			return null;
		}

		private void OnRoomEntered()
		{
			_roomEnteredTcs?.TrySetResult();
		}
	}
	/// <summary>
	/// Handles the rewards screen after combat.
	/// </summary>
	public class RewardsScreenHandler : IScreenHandler, IHandler
	{
		public Type ScreenType => typeof(NRewardsScreen);

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NRewardsScreen");
			NRewardsScreen screen = AutoSlayer.GetCurrentScreen<NRewardsScreen>();
			HashSet<NRewardButton> attemptedButtons = new HashSet<NRewardButton>();
			while (true)
			{
				ct.ThrowIfCancellationRequested();
				bool hasPotionSlots = LocalContext.GetMe(RunManager.Instance.DebugOnlyGetState())?.HasOpenPotionSlots ?? false;
				NRewardButton nRewardButton = UiHelper.FindAll<NRewardButton>(screen).FirstOrDefault((NRewardButton b) => b.IsEnabled && !attemptedButtons.Contains(b) && (!(b.Reward is PotionReward) | hasPotionSlots));
				if (nRewardButton == null)
				{
					break;
				}
				attemptedButtons.Add(nRewardButton);
				AutoSlayLog.Action("Clicking reward button: " + (nRewardButton.Reward?.GetType().Name ?? "unknown"));
				await UiHelper.Click(nRewardButton);
				await Task.Delay(500, ct);
				IOverlayScreen overlayScreen = NOverlayStack.Instance?.Peek();
				if (overlayScreen != null && overlayScreen != screen)
				{
					AutoSlayLog.Action("Child screen opened, returning to drain loop");
					AutoSlayLog.ExitScreen("NRewardsScreen");
					return;
				}
			}
			NProceedButton nProceedButton = UiHelper.FindFirst<NProceedButton>(screen);
			if (nProceedButton != null)
			{
				AutoSlayLog.Action("Clicking proceed");
				await UiHelper.Click(nProceedButton);
				await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || NOverlayStack.Instance?.Peek() != screen || (NMapScreen.Instance?.IsOpen ?? false), ct, TimeSpan.FromSeconds(10L), "Rewards screen did not close or map did not open after clicking proceed");
			}
			AutoSlayLog.ExitScreen("NRewardsScreen");
		}
	}
	/// <summary>
	/// Handles simple card selection screens.
	/// Some screens require multiple card selections and/or manual confirmation.
	/// </summary>
	public class SimpleCardSelectScreenHandler : IScreenHandler, IHandler
	{
		public Type ScreenType => typeof(NSimpleCardSelectScreen);

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.EnterScreen("NSimpleCardSelectScreen");
			NSimpleCardSelectScreen screen = AutoSlayer.GetCurrentScreen<NSimpleCardSelectScreen>();
			NCardGrid grid = UiHelper.FindFirst<NCardGrid>(screen);
			if (grid == null)
			{
				AutoSlayLog.Error("Card grid not found in simple card select screen");
				return;
			}
			NConfirmButton confirmButton = screen.GetNodeOrNull<NConfirmButton>("%Confirm");
			HashSet<NGridCardHolder> selectedCards = new HashSet<NGridCardHolder>();
			for (int i = 0; i < 10; i++)
			{
				ct.ThrowIfCancellationRequested();
				if (!GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree())
				{
					AutoSlayLog.Info("Screen auto-closed after selections");
					break;
				}
				if (confirmButton != null && confirmButton.IsEnabled)
				{
					AutoSlayLog.Action("Clicking confirm button");
					await UiHelper.Click(confirmButton);
					break;
				}
				List<NGridCardHolder> list = (from c in UiHelper.FindAll<NGridCardHolder>(screen)
					where !selectedCards.Contains(c)
					select c).ToList();
				if (list.Count == 0)
				{
					AutoSlayLog.Warn("No more cards available to select");
					break;
				}
				NGridCardHolder nGridCardHolder = random.NextItem(list);
				selectedCards.Add(nGridCardHolder);
				AutoSlayLog.Action($"Selecting card ({selectedCards.Count})");
				grid.EmitSignal(NCardGrid.SignalName.HolderPressed, nGridCardHolder);
				await Task.Delay(300, ct);
			}
			await WaitHelper.Until(() => !GodotObject.IsInstanceValid(screen) || !screen.IsVisibleInTree(), ct, TimeSpan.FromSeconds(5L), "Simple card select screen did not close");
			AutoSlayLog.ExitScreen("NSimpleCardSelectScreen");
		}
	}
}
namespace MegaCrit.Sts2.Core.AutoSlay.Handlers.Rooms
{
	/// <summary>
	/// Handles combat rooms (Monster, Elite, Boss).
	/// Applies massive defensive buffs and plays all cards each turn.
	/// </summary>
	public class CombatRoomHandler : IRoomHandler, IHandler
	{
		public RoomType[] HandledTypes => new RoomType[3]
		{
			RoomType.Monster,
			RoomType.Elite,
			RoomType.Boss
		};

		public TimeSpan Timeout => TimeSpan.FromMinutes(5L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for combat to start");
			await WaitHelper.Until(() => CombatManager.Instance.IsInProgress, ct, AutoSlayConfig.nodeWaitTimeout, "Combat not started");
			AutoSlayLog.Action("Combat started, applying defensive buffs");
			Player player = LocalContext.GetMe(RunManager.Instance.DebugOnlyGetState());
			Creature playerCreature = player.Creature;
			await PowerCmd.Apply<PlatingPower>(new ThrowingPlayerChoiceContext(), playerCreature, 999m, playerCreature, null);
			await PowerCmd.Apply<RegenPower>(new ThrowingPlayerChoiceContext(), playerCreature, 999m, playerCreature, null);
			int turnCount = 0;
			int lastPlayedTurnNumber = 0;
			while (CombatManager.Instance.IsInProgress && turnCount < 100)
			{
				ct.ThrowIfCancellationRequested();
				turnCount++;
				AutoSlayer.CurrentWatchdog?.Reset($"Waiting for a playable turn after turn {lastPlayedTurnNumber}");
				await WaitHelper.Until(() => IsPlayableTurnAfter(player, lastPlayedTurnNumber) || !CombatManager.Instance.IsInProgress, ct, TimeSpan.FromSeconds(28L), () => $"No playable turn after turn {lastPlayedTurnNumber} (phase={player.PlayerCombatState?.Phase}, turnNumber={player.PlayerCombatState?.TurnNumber})");
				if (!CombatManager.Instance.IsInProgress)
				{
					break;
				}
				int playingTurnNumber = (lastPlayedTurnNumber = player.PlayerCombatState.TurnNumber);
				AutoSlayer.CurrentWatchdog?.Reset($"Combat turn {playingTurnNumber}");
				if (playingTurnNumber >= 3)
				{
					await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), playerCreature, 200m, playerCreature, null);
				}
				AutoSlayLog.Action($"Turn {playingTurnNumber}: playing cards");
				await UseAllPotions(player, random, ct);
				int cardsPlayed = 0;
				HashSet<CardModel> attemptedCards = new HashSet<CardModel>();
				while (cardsPlayed < 50)
				{
					PlayerCombatState? playerCombatState = player.PlayerCombatState;
					if (playerCombatState == null || playerCombatState.Phase != PlayerTurnPhase.Play || player.PlayerCombatState.TurnNumber != playingTurnNumber)
					{
						break;
					}
					ct.ThrowIfCancellationRequested();
					if (cardsPlayed > 0 && cardsPlayed % 10 == 0)
					{
						AutoSlayer.CurrentWatchdog?.Reset($"Combat turn {playingTurnNumber}, played {cardsPlayed} cards");
					}
					CardPile pile = PileType.Hand.GetPile(player);
					List<CardModel> list = pile.Cards.Where((CardModel c) => c.CanPlay(out UnplayableReason _, out AbstractModel _) && !attemptedCards.Contains(c)).ToList();
					if (list.Count == 0)
					{
						AutoSlayLog.Action("No more playable cards, ending turn");
						break;
					}
					CardModel cardModel = random.NextItem(list);
					Creature randomTarget = GetRandomTarget(cardModel, random);
					attemptedCards.Add(cardModel);
					AutoSlayLog.Info("Playing " + cardModel.Id.Entry);
					await CardCmd.AutoPlay(new BlockingPlayerChoiceContext(), cardModel, randomTarget);
					cardsPlayed++;
					await Task.Delay(100, ct);
				}
				if (!CombatManager.Instance.IsInProgress)
				{
					break;
				}
				PlayerCombatState? playerCombatState2 = player.PlayerCombatState;
				if (playerCombatState2 != null && playerCombatState2.Phase == PlayerTurnPhase.Play && player.PlayerCombatState.TurnNumber == playingTurnNumber)
				{
					PlayerCmd.EndTurn(player, canBackOut: false);
					continue;
				}
				AutoSlayLog.Action($"Turn {playingTurnNumber} was ended by the game, not by AutoSlay");
			}
			AutoSlayer.CurrentWatchdog?.Reset("Waiting for combat to end");
			await WaitHelper.Until(() => !CombatManager.Instance.IsInProgress, ct, TimeSpan.FromSeconds(28L), () => $"Combat did not end after {turnCount} turns (phase={player.PlayerCombatState?.Phase}, turnNumber={player.PlayerCombatState?.TurnNumber})");
			AutoSlayLog.Action("Combat finished");
		}

		/// <summary>True when the game is ready for AutoSlay to act in a turn it has not played yet.</summary>
		/// <remarks>Greater-than, not not-equal: TurnNumber restarts at 1 each combat (Player.ResetCombatState).</remarks>
		private static bool IsPlayableTurnAfter(Player player, int lastPlayedTurnNumber)
		{
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState != null && playerCombatState.Phase == PlayerTurnPhase.Play)
			{
				return playerCombatState.TurnNumber > lastPlayedTurnNumber;
			}
			return false;
		}

		private static Creature? GetRandomTarget(CardModel card, Rng random)
		{
			if (card.TargetType != TargetType.AnyEnemy)
			{
				return null;
			}
			ICombatState combatState = card.CombatState;
			if (combatState == null)
			{
				return null;
			}
			List<Creature> list = combatState.HittableEnemies.ToList();
			if (list.Count == 0)
			{
				return null;
			}
			return random.NextItem(list);
		}

		private static async Task UseAllPotions(Player player, Rng random, CancellationToken ct)
		{
			List<PotionModel> list = player.Potions.ToList();
			if (list.Count == 0)
			{
				return;
			}
			AutoSlayLog.Action($"Using {list.Count} potion(s)");
			ICombatState combatState = player.Creature.CombatState;
			foreach (PotionModel item in list)
			{
				ct.ThrowIfCancellationRequested();
				PlayerCombatState? playerCombatState = player.PlayerCombatState;
				if (playerCombatState != null && playerCombatState.Phase == PlayerTurnPhase.Play && CombatManager.Instance.IsInProgress)
				{
					Creature potionTarget = GetPotionTarget(item, combatState, random);
					if (potionTarget == null && item.TargetType.IsSingleTarget())
					{
						AutoSlayLog.Warn("Skipping potion " + item.Id.Entry + ": no valid target");
						continue;
					}
					AutoSlayLog.Info("Using potion: " + item.Id.Entry);
					item.EnqueueManualUse(potionTarget);
					await Task.Delay(300, ct);
					continue;
				}
				break;
			}
		}

		private static Creature? GetPotionTarget(PotionModel potion, ICombatState? combatState, Rng random)
		{
			if (combatState == null)
			{
				return null;
			}
			return potion.TargetType switch
			{
				TargetType.AnyEnemy => random.NextItem(combatState.HittableEnemies.ToList()), 
				TargetType.AnyAlly => combatState.PlayerCreatures.FirstOrDefault((Creature c) => c.IsAlive), 
				TargetType.AnyPlayer => combatState.PlayerCreatures.FirstOrDefault((Creature c) => c.IsAlive), 
				TargetType.Self => combatState.PlayerCreatures.FirstOrDefault((Creature c) => c.IsAlive), 
				_ => null, 
			};
		}
	}
	/// <summary>
	/// Handles event rooms by selecting random choices.
	/// Some events trigger combat mid-event (e.g., DenseVegetation's "Rest" option).
	/// This handler detects and handles those combats before returning to the event.
	/// </summary>
	public class EventRoomHandler : IRoomHandler, IHandler
	{
		private const string _roomPath = "/root/Game/RootSceneContainer/Run/RoomContainer/EventRoom";

		private const int _maxIterations = 50;

		public RoomType[] HandledTypes => new RoomType[1] { RoomType.Event };

		public TimeSpan Timeout => TimeSpan.FromMinutes(3L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for event room");
			Node eventRoom = await WaitForEventRoom(ct);
			if (await WaitForEventOptions(eventRoom, ct))
			{
				AutoSlayLog.Action("Event room completed");
				return;
			}
			int iterations = 0;
			while (iterations < 50)
			{
				ct.ThrowIfCancellationRequested();
				if (!GodotObject.IsInstanceValid(eventRoom) || !eventRoom.IsInsideTree())
				{
					RunState runState = RunManager.Instance.DebugOnlyGetState();
					if (runState != null && runState.CurrentRoomCount > 1)
					{
						AbstractRoom? baseRoom = runState.BaseRoom;
						if (baseRoom != null && baseRoom.RoomType == RoomType.Event)
						{
							AutoSlayLog.Action("Event triggered combat, handling combat first");
							await HandleEventCombat(ct);
							AutoSlayLog.Action("Combat finished, checking if event resumes");
							Node root = ((SceneTree)Engine.GetMainLoop()).Root;
							Node nodeOrNull = root.GetNodeOrNull("/root/Game/RootSceneContainer/Run/RoomContainer/EventRoom");
							if (nodeOrNull == null)
							{
								AutoSlayLog.Action("Event ended after combat (no event room)");
								break;
							}
							eventRoom = nodeOrNull;
							await Task.Delay(500, ct);
							List<NEventOptionButton> list = (from o in UiHelper.FindAll<NEventOptionButton>(eventRoom)
								where !o.Option.IsLocked
								select o).ToList();
							if (list.Count == 0)
							{
								AutoSlayLog.Action("Event finished after combat");
								break;
							}
							iterations++;
							continue;
						}
					}
					AutoSlayLog.Action("Event room no longer valid, exiting");
					break;
				}
				List<NEventOptionButton> list2 = (from o in UiHelper.FindAll<NEventOptionButton>(eventRoom)
					where !o.Option.IsLocked
					select o).ToList();
				if (list2.Count == 0)
				{
					break;
				}
				List<NEventOptionButton> list3 = list2.Where((NEventOptionButton o) => o.Option.WillKillPlayer == null || o.Event.Owner == null || !o.Option.WillKillPlayer(o.Event.Owner)).ToList();
				if (list3.Count > 0)
				{
					list2 = list3;
				}
				NEventOptionButton choice = random.NextItem(list2);
				AutoSlayLog.Action($"Selecting event option: {choice.Event.Id.Entry} (option: {choice.Option.Title.GetFormattedText()})");
				HashSet<NEventOptionButton> previousButtons = new HashSet<NEventOptionButton>(from o in UiHelper.FindAll<NEventOptionButton>(eventRoom)
					where !o.Option.IsLocked
					select o);
				await UiHelper.Click(choice);
				if (choice.Option.IsProceed)
				{
					AutoSlayLog.Action("Clicked proceed, exiting event");
					await WaitHelper.Until(() => !GodotObject.IsInstanceValid(eventRoom) || !eventRoom.IsInsideTree() || (NMapScreen.Instance?.IsOpen ?? false), ct, TimeSpan.FromSeconds(5L), "Event room did not close after clicking proceed");
					break;
				}
				await WaitHelper.Until(delegate
				{
					NOverlayStack? instance2 = NOverlayStack.Instance;
					if (instance2 != null && instance2.ScreenCount > 0)
					{
						return true;
					}
					NMapScreen? instance3 = NMapScreen.Instance;
					if (instance3 != null && instance3.IsOpen)
					{
						return true;
					}
					if (!GodotObject.IsInstanceValid(eventRoom) || !eventRoom.IsInsideTree())
					{
						return true;
					}
					if (CombatManager.Instance.IsInProgress)
					{
						return true;
					}
					List<NEventOptionButton> list4 = (from o in UiHelper.FindAll<NEventOptionButton>(eventRoom)
						where !o.Option.IsLocked
						select o).ToList();
					return list4.Count == 0 || !previousButtons.SetEquals(list4);
				}, ct, TimeSpan.FromSeconds(5L), "Event options did not change after choice");
				NOverlayStack? instance = NOverlayStack.Instance;
				if (instance != null && instance.ScreenCount > 0)
				{
					AutoSlayLog.Action("Overlay screen opened during event, deferring to drain loop");
					break;
				}
				if (CombatManager.Instance.IsInProgress)
				{
					AutoSlayLog.Action("Combat started during event (combat layout), handling combat");
					await HandleEventCombat(ct);
					if (!GodotObject.IsInstanceValid(eventRoom) || !eventRoom.IsInsideTree())
					{
						AutoSlayLog.Action("Event room gone after combat");
						break;
					}
					await WaitHelper.Until(delegate
					{
						if (GodotObject.IsInstanceValid(eventRoom) && eventRoom.IsInsideTree())
						{
							NMapScreen? instance2 = NMapScreen.Instance;
							if (instance2 == null || !instance2.IsOpen)
							{
								NOverlayStack? instance3 = NOverlayStack.Instance;
								if (instance3 == null || instance3.ScreenCount <= 0)
								{
									return UiHelper.FindAll<NEventOptionButton>(eventRoom).Any((NEventOptionButton o) => !o.Option.IsLocked);
								}
							}
						}
						return true;
					}, ct, TimeSpan.FromSeconds(10L), "Event did not resume after combat layout combat");
					if (!GodotObject.IsInstanceValid(eventRoom) || !eventRoom.IsInsideTree())
					{
						AutoSlayLog.Action("Event room gone after combat");
						break;
					}
				}
				iterations++;
			}
			if (iterations >= 50)
			{
				AutoSlayLog.Warn($"Event room hit iteration limit ({50})");
			}
			AutoSlayLog.Action("Event room completed");
		}

		private async Task HandleEventCombat(CancellationToken ct)
		{
			await WaitHelper.Until(() => CombatManager.Instance.IsInProgress, ct, AutoSlayConfig.nodeWaitTimeout, "Event combat not started");
			AutoSlayLog.Action("Event combat started, applying buffs and killing enemies");
			Creature player = LocalContext.GetMe(RunManager.Instance.DebugOnlyGetState()).Creature;
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), player, 100m, player, null);
			await PowerCmd.Apply<PlatingPower>(new ThrowingPlayerChoiceContext(), player, 100m, player, null);
			await PowerCmd.Apply<RegenPower>(new ThrowingPlayerChoiceContext(), player, 100m, player, null);
			int killAttempts = 0;
			int noEnemyWaitLoops = 0;
			while (CombatManager.Instance.IsInProgress && killAttempts < 20)
			{
				ct.ThrowIfCancellationRequested();
				CombatState combatState = CombatManager.Instance.DebugOnlyGetState();
				if (combatState == null)
				{
					AutoSlayLog.Info("Combat state became null, exiting kill loop");
					break;
				}
				foreach (Creature creature in combatState.Enemies)
				{
					List<PowerModel> list = creature.Powers.Where((PowerModel p) => p.ShouldStopCombatFromEnding()).ToList();
					foreach (PowerModel item in list)
					{
						AutoSlayLog.Info($"Removing blocking power {item.GetType().Name} from {creature}");
						await PowerCmd.Remove(item);
					}
				}
				List<Creature> list2 = combatState.Enemies.Where((Creature e) => e.IsAlive).ToList();
				if (list2.Count > 0)
				{
					AutoSlayLog.Action($"Killing {list2.Count} event combat enemies (attempt {killAttempts + 1})");
					await CreatureCmd.Kill(list2);
					killAttempts++;
					noEnemyWaitLoops = 0;
					await Task.Delay(1000, ct);
					await CombatManager.Instance.CheckWinCondition();
				}
				else
				{
					noEnemyWaitLoops++;
					if (noEnemyWaitLoops > 100)
					{
						AutoSlayLog.Info("Event combat still in progress but no enemies for 10s, breaking loop");
						break;
					}
					await Task.Delay(100, ct);
				}
			}
			if (CombatManager.Instance.IsInProgress)
			{
				await CombatManager.Instance.CheckWinCondition();
			}
			await WaitHelper.Until(() => !CombatManager.Instance.IsInProgress, ct, TimeSpan.FromSeconds(30L), "Event combat did not end");
			AutoSlayLog.Action("Event combat finished");
		}

		private async Task<Node> WaitForEventRoom(CancellationToken ct)
		{
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			return await WaitHelper.ForNode<Node>(root, "/root/Game/RootSceneContainer/Run/RoomContainer/EventRoom", ct);
		}

		/// <summary>
		/// Waits for event options to become available.
		/// </summary>
		/// <returns>True if the event was fully handled (custom events), false if options loop should run.</returns>
		private async Task<bool> WaitForEventOptions(Node eventRoom, CancellationToken ct)
		{
			NAncientEventLayout nAncientEventLayout = UiHelper.FindFirst<NAncientEventLayout>(eventRoom);
			if (nAncientEventLayout != null)
			{
				await HandleAncientEventDialogue(nAncientEventLayout, ct);
				return false;
			}
			NFakeMerchant nFakeMerchant = UiHelper.FindFirst<NFakeMerchant>(eventRoom);
			if (nFakeMerchant != null)
			{
				AutoSlayLog.Info("Detected custom event: FakeMerchant");
				await HandleFakeMerchantEvent(nFakeMerchant, ct);
				return true;
			}
			int waitCycles = 0;
			await WaitHelper.Until(delegate
			{
				waitCycles++;
				if (waitCycles % 50 == 0)
				{
					int childCount = eventRoom.GetChildCount();
					AutoSlayLog.Info($"Waiting for event options: {childCount} children in event room");
					AutoSlayer.CurrentWatchdog?.Reset("Waiting for event options to load");
				}
				return UiHelper.FindAll<NEventOptionButton>(eventRoom).Count > 0;
			}, ct, TimeSpan.FromSeconds(30L), "Event options not loaded");
			return false;
		}

		/// <summary>
		/// Handles the FakeMerchant custom event.
		/// This event uses NProceedButton instead of NEventOptionButton.
		/// We simply click the proceed button to leave.
		/// </summary>
		private async Task HandleFakeMerchantEvent(NFakeMerchant fakeMerchant, CancellationToken ct)
		{
			AutoSlayLog.Action("Handling FakeMerchant event");
			NProceedButton proceedButton = null;
			await WaitHelper.Until(delegate
			{
				proceedButton = UiHelper.FindFirst<NProceedButton>(fakeMerchant);
				return proceedButton != null && proceedButton.IsEnabled && proceedButton.Visible;
			}, ct, TimeSpan.FromSeconds(10L), "FakeMerchant proceed button not available");
			AutoSlayLog.Action("Clicking FakeMerchant proceed button");
			await UiHelper.Click(proceedButton);
		}

		/// <summary>
		/// Handles Ancient events which require clicking through dialogue before options appear.
		/// </summary>
		private async Task HandleAncientEventDialogue(NAncientEventLayout ancientLayout, CancellationToken ct)
		{
			AutoSlayLog.Info("Detected Ancient event, clicking through dialogue");
			int clicks = 0;
			while (clicks < 50)
			{
				ct.ThrowIfCancellationRequested();
				if (!GodotObject.IsInstanceValid(ancientLayout))
				{
					break;
				}
				List<NEventOptionButton> list = (from b in UiHelper.FindAll<NEventOptionButton>(ancientLayout)
					where b.IsEnabled && !b.Option.IsLocked
					select b).ToList();
				if (list.Count > 0)
				{
					AutoSlayLog.Info($"Ancient dialogue finished, {list.Count} options available");
					break;
				}
				NButton nodeOrNull = ancientLayout.GetNodeOrNull<NButton>("%DialogueHitbox");
				if (nodeOrNull == null || !nodeOrNull.Visible || !nodeOrNull.IsEnabled)
				{
					await Task.Delay(100, ct);
					continue;
				}
				AutoSlayLog.Info($"Clicking Ancient dialogue (click {clicks + 1})");
				AutoSlayer.CurrentWatchdog?.Reset("Clicking Ancient event dialogue");
				nodeOrNull.EmitSignal(NClickableControl.SignalName.Released, nodeOrNull);
				clicks++;
				await Task.Delay(500, ct);
			}
			await WaitHelper.Until(() => UiHelper.FindAll<NEventOptionButton>(ancientLayout).Any((NEventOptionButton b) => b.IsEnabled && !b.Option.IsLocked), ct, TimeSpan.FromSeconds(10L), "Ancient event options did not become available after dialogue");
		}
	}
	/// <summary>
	/// Handles rest site rooms by selecting a random rest option.
	/// </summary>
	public class RestSiteRoomHandler : IRoomHandler, IHandler
	{
		private const string _roomPath = "/root/Game/RootSceneContainer/Run/RoomContainer/RestSiteRoom";

		public RoomType[] HandledTypes => new RoomType[1] { RoomType.RestSite };

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for rest site room");
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			NRestSiteRoom room = await WaitHelper.ForNode<NRestSiteRoom>(root, "/root/Game/RootSceneContainer/Run/RoomContainer/RestSiteRoom", ct);
			List<NRestSiteButton> list = (from b in UiHelper.FindAll<NRestSiteButton>(room)
				where b.Option.IsEnabled
				select b).ToList();
			if (list.Count == 0)
			{
				AutoSlayLog.Warn("No clickable rest site buttons found");
				return;
			}
			NRestSiteButton nRestSiteButton = random.NextItem(list);
			AutoSlayLog.Action("Selecting rest site option: " + nRestSiteButton.Option.GetType().Name);
			await UiHelper.Click(nRestSiteButton);
			NProceedButton proceedButton = room.ProceedButton;
			await WaitHelper.Until(delegate
			{
				if (!proceedButton.IsEnabled)
				{
					NOverlayStack? instance2 = NOverlayStack.Instance;
					if (instance2 == null)
					{
						return false;
					}
					return instance2.ScreenCount > 0;
				}
				return true;
			}, ct, TimeSpan.FromSeconds(10L), "Rest site option did not respond");
			NOverlayStack? instance = NOverlayStack.Instance;
			if (instance != null && instance.ScreenCount > 0)
			{
				AutoSlayLog.Action("Overlay screen detected, deferring proceed to drain loop");
				return;
			}
			AutoSlayLog.Action("Clicking proceed");
			await UiHelper.Click(proceedButton);
		}
	}
	/// <summary>
	/// Handles shop rooms by attempting to buy every affordable item.
	/// </summary>
	public class ShopRoomHandler : IRoomHandler, IHandler
	{
		private const string _roomPath = "/root/Game/RootSceneContainer/Run/RoomContainer/MerchantRoom";

		private readonly Func<Task, CancellationToken, Task> _drainOverlayScreensUntil;

		public RoomType[] HandledTypes => new RoomType[1] { RoomType.Shop };

		public TimeSpan Timeout => TimeSpan.FromSeconds(120L);

		/// <param name="drainOverlayScreensUntil">
		/// Awaits a task while draining any overlay screen it opens. Buying an item can open a
		/// screen, and the purchase does not complete until that screen is resolved, so the shop
		/// cannot wait for the drain that runs between rooms.
		/// </param>
		public ShopRoomHandler(Func<Task, CancellationToken, Task> drainOverlayScreensUntil)
		{
			_drainOverlayScreensUntil = drainOverlayScreensUntil;
		}

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for shop room");
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			NMerchantRoom room = await WaitHelper.ForNode<NMerchantRoom>(root, "/root/Game/RootSceneContainer/Run/RoomContainer/MerchantRoom", ct);
			AutoSlayLog.Action("Opening merchant inventory");
			room.OpenInventory();
			await Task.Delay(500, ct);
			int maxAttempts = 50;
			int attempts = 0;
			while (attempts < maxAttempts)
			{
				ct.ThrowIfCancellationRequested();
				attempts++;
				List<NMerchantSlot> list = (from slot in room.Inventory.GetAllSlots()
					where !(slot is NMerchantCardRemoval)
					where slot.Entry.IsStocked && slot.Entry.EnoughGold
					select slot).ToList();
				if (list.Count == 0)
				{
					AutoSlayLog.Action("No more affordable items to buy");
					break;
				}
				NMerchantSlot nMerchantSlot = random.NextItem(list);
				AutoSlayLog.Action($"Buying {nMerchantSlot.GetType().Name} (cost: {nMerchantSlot.Entry.Cost})");
				await _drainOverlayScreensUntil(nMerchantSlot.Entry.OnTryPurchaseWrapper(room.Inventory.Inventory), ct);
				await Task.Delay(300, ct);
			}
			NBackButton nBackButton = UiHelper.FindFirst<NBackButton>(room);
			if (nBackButton != null)
			{
				AutoSlayLog.Action("Closing inventory");
				await UiHelper.Click(nBackButton);
				await Task.Delay(300, ct);
			}
			NProceedButton proceedButton = room.ProceedButton;
			AutoSlayLog.Action("Clicking proceed");
			await UiHelper.Click(proceedButton);
		}
	}
	/// <summary>
	/// Handles treasure rooms by opening the chest, picking relics, and proceeding.
	/// </summary>
	public class TreasureRoomHandler : IRoomHandler, IHandler
	{
		private const string _roomPath = "/root/Game/RootSceneContainer/Run/RoomContainer/TreasureRoom";

		public RoomType[] HandledTypes => new RoomType[1] { RoomType.Treasure };

		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for treasure room");
			Node root = ((SceneTree)Engine.GetMainLoop()).Root;
			NTreasureRoom room = await WaitHelper.ForNode<NTreasureRoom>(root, "/root/Game/RootSceneContainer/Run/RoomContainer/TreasureRoom", ct);
			NClickableControl node = room.GetNode<NClickableControl>("Chest");
			AutoSlayLog.Action("Opening chest");
			await UiHelper.Click(node);
			await Task.Delay(1000, ct);
			List<NTreasureRoomRelicHolder> list = UiHelper.FindAll<NTreasureRoomRelicHolder>(room);
			foreach (NTreasureRoomRelicHolder item in list)
			{
				if (item.IsEnabled && item.Visible)
				{
					AutoSlayLog.Action("Picking up relic");
					await UiHelper.Click(item);
					await Task.Delay(500, ct);
				}
			}
			NProceedButton proceedButton = room.ProceedButton;
			await WaitHelper.Until(() => proceedButton.IsEnabled, ct, TimeSpan.FromSeconds(5L), "Proceed button not enabled after picking relics");
			AutoSlayLog.Action("Clicking proceed");
			await UiHelper.Click(proceedButton);
		}
	}
	/// <summary>
	/// Handles post-combat victory rooms where the proceed button is displayed.
	/// </summary>
	public class VictoryRoomHandler : IHandler
	{
		public TimeSpan Timeout => TimeSpan.FromSeconds(30L);

		public async Task HandleAsync(Rng random, CancellationToken ct)
		{
			AutoSlayLog.Action("Waiting for victory room");
			await WaitHelper.Until(() => NCombatRoom.Instance != null, ct, AutoSlayConfig.nodeWaitTimeout, "Victory room not ready");
			NCombatRoom instance = NCombatRoom.Instance;
			NProceedButton proceedButton = instance.ProceedButton;
			await WaitHelper.Until(() => proceedButton.IsEnabled, ct, TimeSpan.FromSeconds(10L), "Proceed button not enabled");
			AutoSlayLog.Action("Clicking proceed on victory");
			await UiHelper.Click(proceedButton);
			AutoSlayLog.Action("Victory room completed");
		}
	}
