	/// <summary>
	/// Manages texture atlases by parsing .tpsheet files and creating AtlasTextures on demand.
	/// Thread-safe via ConcurrentDictionary caching.
	/// </summary>
	public static class AtlasManager
	{
		private class AtlasData
		{
			public required TpSheetData TpSheet { get; init; }

			public required System.Collections.Generic.Dictionary<string, Texture2D> PageTextures { get; init; }

			public required System.Collections.Generic.Dictionary<string, SpriteInfo> SpriteMap { get; init; }
		}

		private record SpriteInfo(Texture2D Atlas, TpSheetSprite Sprite);

		private static readonly string[] _knownAtlases = new string[12]
		{
			"ui_atlas", "compressed", "epoch_atlas", "relic_atlas", "relic_outline_atlas", "power_atlas", "card_atlas", "potion_atlas", "potion_outline_atlas", "stats_screen_atlas",
			"intent_atlas", "era_atlas"
		};

		private static readonly JsonSerializerOptions _jsonOptions = new JsonSerializerOptions
		{
			PropertyNameCaseInsensitive = true
		};

		private static readonly ConcurrentDictionary<string, AtlasData> _atlases = new ConcurrentDictionary<string, AtlasData>();

		private static readonly ConcurrentDictionary<string, AtlasTexture> _spriteCache = new ConcurrentDictionary<string, AtlasTexture>();

		private static readonly Lock _loadLock = new Lock();

		/// <summary>
		/// Atlases needed before main menu scene loads.
		/// Their .tres files are referenced by scene ext_resources and must be loaded
		/// before Godot's scene deserializer encounters them.
		/// </summary>
		private static readonly string[] _essentialAtlases = new string[2] { "ui_atlas", "compressed" };

		/// <summary>
		/// Loads all known atlases. Call during initialization.
		/// </summary>
		public static void LoadAllAtlases()
		{
			string[] knownAtlases = _knownAtlases;
			foreach (string atlasName in knownAtlases)
			{
				LoadAtlas(atlasName);
			}
		}

		/// <summary>
		/// Loads only atlases referenced by scene ext_resources.
		/// Must be called before any scenes load.
		/// </summary>
		public static void LoadEssentialAtlases()
		{
			string[] essentialAtlases = _essentialAtlases;
			foreach (string atlasName in essentialAtlases)
			{
				LoadAtlas(atlasName);
			}
		}

		/// <summary>
		/// Loads a single atlas by parsing its .tpsheet file and loading PNG textures.
		/// Thread-safe: uses lock to prevent duplicate loading work.
		/// </summary>
		public static void LoadAtlas(string atlasName)
		{
			if (_atlases.ContainsKey(atlasName))
			{
				return;
			}
			using (_loadLock.EnterScope())
			{
				if (!_atlases.ContainsKey(atlasName))
				{
					LoadAtlasInternal(atlasName);
				}
			}
		}

		private static void LoadAtlasInternal(string atlasName)
		{
			string text = "res://images/atlases/" + atlasName + ".tpsheet";
			if (!Godot.FileAccess.FileExists(text))
			{
				Log.Warn("AtlasManager: tpsheet not found: " + text);
				return;
			}
			using Godot.FileAccess fileAccess = Godot.FileAccess.Open(text, Godot.FileAccess.ModeFlags.Read);
			if (fileAccess == null)
			{
				Log.Warn("AtlasManager: Failed to open " + text);
				return;
			}
			string asText = fileAccess.GetAsText();
			TpSheetData tpSheetData = JsonSerializer.Deserialize<TpSheetData>(asText, _jsonOptions);
			if (tpSheetData == null)
			{
				Log.Warn("AtlasManager: Failed to parse " + text);
				return;
			}
			System.Collections.Generic.Dictionary<string, Texture2D> dictionary = new System.Collections.Generic.Dictionary<string, Texture2D>();
			System.Collections.Generic.Dictionary<string, SpriteInfo> dictionary2 = new System.Collections.Generic.Dictionary<string, SpriteInfo>();
			foreach (TpSheetTexture texture in tpSheetData.Textures)
			{
				string text2 = "res://images/atlases/" + texture.Image;
				Texture2D texture2D = ResourceLoader.Load<Texture2D>(text2, null, ResourceLoader.CacheMode.Reuse);
				if (texture2D == null)
				{
					Log.Warn("AtlasManager: Failed to load texture: " + text2);
					continue;
				}
				dictionary[texture.Image] = texture2D;
				foreach (TpSheetSprite sprite in texture.Sprites)
				{
					string key = NormalizeSpriteKey(sprite.Filename);
					dictionary2[key] = new SpriteInfo(texture2D, sprite);
				}
			}
			AtlasData value = new AtlasData
			{
				TpSheet = tpSheetData,
				PageTextures = dictionary,
				SpriteMap = dictionary2
			};
			_atlases[atlasName] = value;
			Log.Info($"AtlasManager: Loaded {atlasName} with {dictionary2.Count} sprites");
		}

		/// <summary>
		/// Gets an AtlasTexture for the specified sprite, creating and caching it if needed.
		/// </summary>
		/// <param name="atlasName">Atlas name (e.g., "relic_atlas")</param>
		/// <param name="spriteName">Sprite name without extension (e.g., "anchor_small")</param>
		/// <returns>The AtlasTexture, or null if not found</returns>
		public static AtlasTexture? GetSprite(string atlasName, string spriteName)
		{
			if (!_atlases.TryGetValue(atlasName, out AtlasData value))
			{
				return null;
			}
			string key = NormalizeSpriteKey(spriteName);
			if (!value.SpriteMap.TryGetValue(key, out SpriteInfo spriteInfo))
			{
				return null;
			}
			string key2 = atlasName + "/" + spriteName;
			if (_spriteCache.TryGetValue(key2, out AtlasTexture value2))
			{
				if (GodotObject.IsInstanceValid(value2))
				{
					return value2;
				}
				_spriteCache.TryRemove(key2, out AtlasTexture _);
			}
			return _spriteCache.GetOrAdd(key2, (string _) => CreateAtlasTexture(spriteInfo));
		}

		/// <summary>
		/// Checks if a sprite exists in the specified atlas.
		/// </summary>
		public static bool HasSprite(string atlasName, string spriteName)
		{
			if (!_atlases.TryGetValue(atlasName, out AtlasData value))
			{
				return false;
			}
			string key = NormalizeSpriteKey(spriteName);
			return value.SpriteMap.ContainsKey(key);
		}

		/// <summary>
		/// Gets the number of sprites in a loaded atlas.
		/// </summary>
		public static int GetSpriteCount(string atlasName)
		{
			if (!_atlases.TryGetValue(atlasName, out AtlasData value))
			{
				return 0;
			}
			return value.SpriteMap.Count;
		}

		/// <summary>
		/// Checks if an atlas has been loaded.
		/// </summary>
		public static bool IsAtlasLoaded(string atlasName)
		{
			return _atlases.ContainsKey(atlasName);
		}

		/// <summary>
		/// Clears all loaded atlases and cached sprites. Useful for testing.
		/// </summary>
		public static void Clear()
		{
			_atlases.Clear();
			_spriteCache.Clear();
		}

		private static AtlasTexture CreateAtlasTexture(SpriteInfo spriteInfo)
		{
			TpSheetSprite sprite = spriteInfo.Sprite;
			AtlasTexture atlasTexture = new AtlasTexture
			{
				Atlas = spriteInfo.Atlas,
				Region = new Rect2(sprite.Region.X, sprite.Region.Y, sprite.Region.W, sprite.Region.H)
			};
			if (sprite.Margin.X != 0 || sprite.Margin.Y != 0 || sprite.Margin.W != 0 || sprite.Margin.H != 0)
			{
				atlasTexture.Margin = new Rect2(sprite.Margin.X, sprite.Margin.Y, sprite.Margin.W, sprite.Margin.H);
			}
			return atlasTexture;
		}

		private static string NormalizeSpriteKey(string filename)
		{
			if (filename.EndsWith(".png", StringComparison.OrdinalIgnoreCase))
			{
				return filename.Substring(0, filename.Length - 4);
			}
			return filename;
		}
	}
	/// <summary>
	/// ResourceFormatLoader that intercepts .sprites/ paths and returns AtlasTextures from AtlasManager.
	/// Handles paths like: res://images/atlases/relic_atlas.sprites/anchor.tres
	/// </summary>
	[ScriptPath("res://src/Core/Assets/AtlasResourceLoader.cs")]
	public class AtlasResourceLoader : ResourceFormatLoader
	{
		/// <summary>
		/// Cached StringNames for the methods contained in this class, for fast lookup.
		/// </summary>
		public new class MethodName : ResourceFormatLoader.MethodName
		{
			/// <summary>
			/// Cached name for the '_GetRecognizedExtensions' method.
			/// </summary>
			public new static readonly StringName _GetRecognizedExtensions = "_GetRecognizedExtensions";

			/// <summary>
			/// Cached name for the '_HandlesType' method.
			/// </summary>
			public new static readonly StringName _HandlesType = "_HandlesType";

			/// <summary>
			/// Cached name for the '_GetResourceType' method.
			/// </summary>
			public new static readonly StringName _GetResourceType = "_GetResourceType";

			/// <summary>
			/// Cached name for the '_RecognizePath' method.
			/// </summary>
			public new static readonly StringName _RecognizePath = "_RecognizePath";

			/// <summary>
			/// Cached name for the '_Exists' method.
			/// </summary>
			public new static readonly StringName _Exists = "_Exists";

			/// <summary>
			/// Cached name for the '_Load' method.
			/// </summary>
			public new static readonly StringName _Load = "_Load";

			/// <summary>
			/// Cached name for the '_GetDependencies' method.
			/// </summary>
			public new static readonly StringName _GetDependencies = "_GetDependencies";

			/// <summary>
			/// Cached name for the 'IsSpritePath' method.
			/// </summary>
			public static readonly StringName IsSpritePath = "IsSpritePath";

			/// <summary>
			/// Cached name for the 'HasFallback' method.
			/// </summary>
			public static readonly StringName HasFallback = "HasFallback";

			/// <summary>
			/// Cached name for the 'LoadFallback' method.
			/// </summary>
			public static readonly StringName LoadFallback = "LoadFallback";

			/// <summary>
			/// Cached name for the 'GetFallbackPath' method.
			/// </summary>
			public static readonly StringName GetFallbackPath = "GetFallbackPath";

			/// <summary>
			/// Cached name for the 'GetRelicFallbackPath' method.
			/// </summary>
			public static readonly StringName GetRelicFallbackPath = "GetRelicFallbackPath";

			/// <summary>
			/// Cached name for the 'GetPowerFallbackPath' method.
			/// </summary>
			public static readonly StringName GetPowerFallbackPath = "GetPowerFallbackPath";

			/// <summary>
			/// Cached name for the 'GetCardFallbackPath' method.
			/// </summary>
			public static readonly StringName GetCardFallbackPath = "GetCardFallbackPath";

			/// <summary>
			/// Cached name for the 'GetPotionFallbackPath' method.
			/// </summary>
			public static readonly StringName GetPotionFallbackPath = "GetPotionFallbackPath";

			/// <summary>
			/// Cached name for the 'GetMissingTexture' method.
			/// </summary>
			public static readonly StringName GetMissingTexture = "GetMissingTexture";
		}

		/// <summary>
		/// Cached StringNames for the properties and fields contained in this class, for fast lookup.
		/// </summary>
		public new class PropertyName : ResourceFormatLoader.PropertyName
		{
		}

		/// <summary>
		/// Cached StringNames for the signals contained in this class, for fast lookup.
		/// </summary>
		public new class SignalName : ResourceFormatLoader.SignalName
		{
		}

		private const string _atlasBasePath = "res://images/atlases/";

		private const string _spritesSuffix = ".sprites/";

		private static readonly StringName _typeAtlasTexture = new StringName("AtlasTexture");

		private static readonly StringName _typeTexture2D = new StringName("Texture2D");

		private static readonly StringName _typeResource = new StringName("Resource");

		private static readonly Regex _pathPattern = new Regex("^res://images/atlases/([^/]+)\\.sprites/(.+)\\.tres$", RegexOptions.Compiled);

		public override string[] _GetRecognizedExtensions()
		{
			return new string[1] { "tres" };
		}

		public override bool _HandlesType(StringName type)
		{
			if (!(type == _typeAtlasTexture) && !(type == _typeTexture2D))
			{
				return type == _typeResource;
			}
			return true;
		}

		public override string _GetResourceType(string path)
		{
			if (IsSpritePath(path))
			{
				return "AtlasTexture";
			}
			return "";
		}

		public override bool _RecognizePath(string path, StringName type)
		{
			return IsSpritePath(path);
		}

		public override bool _Exists(string path)
		{
			if (!IsSpritePath(path))
			{
				return false;
			}
			var (text, text2) = ParsePath(path);
			if (text == null || text2 == null)
			{
				return false;
			}
			if (!AtlasManager.IsAtlasLoaded(text))
			{
				AtlasManager.LoadAtlas(text);
			}
			if (!AtlasManager.HasSprite(text, text2))
			{
				return HasFallback(text, text2);
			}
			return true;
		}

		public override Variant _Load(string path, string originalPath, bool useSubThreads, int cacheMode)
		{
			if (!IsSpritePath(path))
			{
				return default(Variant);
			}
			var (text, text2) = ParsePath(path);
			if (text == null || text2 == null)
			{
				Log.Warn("AtlasResourceLoader: Failed to parse path: " + path);
				return 7L;
			}
			if (!AtlasManager.IsAtlasLoaded(text))
			{
				AtlasManager.LoadAtlas(text);
			}
			AtlasTexture sprite = AtlasManager.GetSprite(text, text2);
			if (sprite != null)
			{
				return sprite;
			}
			Texture2D texture2D = LoadFallback(text, text2);
			if (texture2D != null)
			{
				return texture2D;
			}
			if (!text2.StartsWith("mock_"))
			{
				Log.Warn($"AtlasResourceLoader: Missing sprite '{text2}' in {text} (requested: {path})");
			}
			return GetMissingTexture(text);
		}

		public override string[] _GetDependencies(string path, bool addTypes)
		{
			return System.Array.Empty<string>();
		}

		private static bool IsSpritePath(string path)
		{
			if (path.StartsWith("res://images/atlases/") && path.Contains(".sprites/"))
			{
				return path.EndsWith(".tres");
			}
			return false;
		}

		/// <summary>
		/// Parses a sprite path to extract atlas and sprite names.
		/// Example: res://images/atlases/relic_atlas.sprites/anchor.tres
		/// Returns: ("relic_atlas", "anchor")
		/// </summary>
		public static (string? AtlasName, string? SpriteName) ParsePath(string path)
		{
			Match match = _pathPattern.Match(path);
			if (!match.Success)
			{
				return (AtlasName: null, SpriteName: null);
			}
			return (AtlasName: match.Groups[1].Value, SpriteName: match.Groups[2].Value);
		}

		private static bool HasFallback(string atlasName, string spriteName)
		{
			string fallbackPath = GetFallbackPath(atlasName, spriteName);
			if (fallbackPath != null)
			{
				return ResourceLoader.Exists(fallbackPath);
			}
			return false;
		}

		private static Texture2D? LoadFallback(string atlasName, string spriteName)
		{
			string fallbackPath = GetFallbackPath(atlasName, spriteName);
			if (fallbackPath == null)
			{
				return null;
			}
			if (!ResourceLoader.Exists(fallbackPath))
			{
				return null;
			}
			Log.Debug($"AtlasResourceLoader: Using fallback for {atlasName}/{spriteName}: {fallbackPath}");
			return ResourceLoader.Load<Texture2D>(fallbackPath, null, ResourceLoader.CacheMode.Reuse);
		}

		/// <summary>
		/// Returns the fallback path for a sprite not found in the atlas.
		/// Different atlases have different fallback conventions.
		/// </summary>
		private static string? GetFallbackPath(string atlasName, string spriteName)
		{
			switch (atlasName)
			{
			case "relic_atlas":
			case "relic_outline_atlas":
				return GetRelicFallbackPath(spriteName);
			case "power_atlas":
				return GetPowerFallbackPath(spriteName);
			case "card_atlas":
				return GetCardFallbackPath(spriteName);
			case "potion_atlas":
			case "potion_outline_atlas":
				return GetPotionFallbackPath(spriteName);
			default:
				return null;
			}
		}

		private static string? GetRelicFallbackPath(string spriteName)
		{
			string text = "res://images/relics/" + spriteName + ".png";
			if (ResourceLoader.Exists(text))
			{
				return text;
			}
			string text2 = "res://images/relics/beta/" + spriteName + ".png";
			if (ResourceLoader.Exists(text2))
			{
				return text2;
			}
			return null;
		}

		private static string? GetPowerFallbackPath(string spriteName)
		{
			string text = "res://images/powers/" + spriteName + ".png";
			if (ResourceLoader.Exists(text))
			{
				return text;
			}
			string text2 = "res://images/powers/beta/" + spriteName + ".png";
			if (ResourceLoader.Exists(text2))
			{
				return text2;
			}
			return null;
		}

		private static string? GetCardFallbackPath(string spriteName)
		{
			string text = "res://images/packed/card_portraits/" + spriteName + ".png";
			if (ResourceLoader.Exists(text))
			{
				return text;
			}
			int num = spriteName.LastIndexOf('/');
			if (num > 0)
			{
				string value = spriteName.Substring(0, num);
				int num2 = num + 1;
				string value2 = spriteName.Substring(num2, spriteName.Length - num2);
				string text2 = $"res://images/packed/card_portraits/{value}/beta/{value2}.png";
				if (ResourceLoader.Exists(text2))
				{
					return text2;
				}
			}
			return null;
		}

		private static string? GetPotionFallbackPath(string spriteName)
		{
			string text = "res://images/potions/" + spriteName + ".png";
			if (ResourceLoader.Exists(text))
			{
				return text;
			}
			return null;
		}

		private static Variant GetMissingTexture(string atlasName)
		{
			string text;
			switch (atlasName)
			{
			case "card_atlas":
				text = "res://images/packed/card_portraits/beta.png";
				break;
			case "potion_atlas":
			case "potion_outline_atlas":
				text = "res://images/potions/missing_potion.png";
				break;
			default:
				text = "res://images/powers/missing_power.png";
				break;
			}
			string path = text;
			if (ResourceLoader.Exists(path))
			{
				Texture2D texture2D = ResourceLoader.Load<Texture2D>(path, null, ResourceLoader.CacheMode.Reuse);
				if (texture2D != null)
				{
					return texture2D;
				}
			}
			return 7L;
		}

