			_groundChunkParticles = _parent.GetNode<GpuParticles2D>("GroundPlowSlot/ChunkParticles");
			_bottomSparkParticles.OneShot = true;
			_topSparkParticles.OneShot = true;
			_witherParticles.OneShot = true;
