					return;
				}
				int pointCount = GetPointCount();
				if (pointCount > 2 && num > 48f)
				{
					Godot.Vector2 pointPosition = GetPointPosition(pointCount - 2);
					Godot.Vector2 pointPosition2 = GetPointPosition(pointCount - 1);
					for (float num2 = 48f; num2 < num - 12f; num2 += 48f)
