		public override void _Ready()
		{
			_startPosition += new Godot.Vector2(Rng.Chaotic.NextFloat(-120f, 120f), Rng.Chaotic.NextFloat(0f, 20f));
			_floorY = _startPosition.Y + Rng.Chaotic.NextFloat(0f, 64f);
			base.GlobalPosition = _startPosition;
			_velocity = new Godot.Vector2(Rng.Chaotic.NextFloat(-400f, 400f), Rng.Chaotic.NextFloat(-800f, -300f));
			float num = Rng.Chaotic.NextFloat(0.8f, 1.2f);
			base.Scale = new Godot.Vector2(num, 2f - num) * Rng.Chaotic.NextFloat(0.1f, 0.8f);
			base.Modulate = new Color(1f, Rng.Chaotic.NextFloat(0.2f, 0.8f), Rng.Chaotic.NextFloat(0f, 0.2f), 0f);
			TaskHelper.RunSafely(Animate());
		}

		public override void _Process(double delta)
		{
			float num = (float)delta;
			base.Position += _velocity * num;
			_velocity += _gravity * num;
			base.Rotation = MathHelper.GetAngle(_velocity);
			if (base.Position.Y > _floorY)
			{
				base.Position = new Godot.Vector2(base.Position.X, _floorY);
				_velocity = new Godot.Vector2(_velocity.X, (0f - _velocity.Y) * 0.5f);
			}
		}

