			await Cmd.Wait(1f, _cts.Token);
			CardModel model = _cardNode.Model;
			if (_cardNode.IsInsideTree() && model.Pile == null)
			{
				_tween = CreateTween();
				_tween.TweenProperty(this, "scale", Godot.Vector2.Zero, 0.15000000596046448);
