		{
			if (TestMode.IsOn)
			{
				return null;
			}
			NCardUpgradeVfx nCardUpgradeVfx = PreloadManager.Cache.GetScene(ScenePath).Instantiate<NCardUpgradeVfx>(PackedScene.GenEditState.Disabled);
			nCardUpgradeVfx._card = card;
