		{
			string eventName = new MegaEvent(spineEvent).GetData().GetEventName();
			if (!(eventName == "laser_start"))
			{
				if (eventName == "laser_end")
				{
					EndLaser();
				}
			}
			else
			{
				StartLaser();
			}
		}

		private void StartLaser()
		{
			_laser.Visible = true;
			_laser.ExtendLaser(new Godot.Vector2(_laser.Position.X - 3000f, _parent.Position.Y));
			Godot.Vector2 scale = _rings.Scale;
			_rings.Scale = Godot.Vector2.Zero;
			_rings.Visible = true;
			Tween tween = CreateTween();
			tween.TweenProperty(_rings, "scale", scale, 0.4000000059604645).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
		}

		private void EndLaser()
		{
			_laser.RetractLaser();
			_rings.Visible = false;
		}

