		private readonly Godot.Vector2 _particleGravity = new Godot.Vector2(0f, 300f);

		private float _particleSpeedScale = 2f;

		private Godot.Vector2 _particleVelocityMinMax = new Godot.Vector2(400f, 600f);

		[Export(PropertyHint.None, "")]
		private Node2D[] _sprayNodes;

		private Node2D _parent;

		private MegaSprite _animController;

