		{
			_timer -= delta;
			if (_timer < 0.0)
			{
				_timer += 0.25;
				if (base.GlobalPosition.DistanceSquaredTo(_target.GlobalPosition) < 1500f)
				{
					this.QueueFreeSafely();
				}
			}
			base.GlobalPosition = base.GlobalPosition.Lerp(_target.GlobalPosition, (float)((double)_speed * delta));
		}

