			NHeavyBluntVfx nHeavyBluntVfx = PreloadManager.Cache.GetScene(scenePath).Instantiate<NHeavyBluntVfx>(PackedScene.GenEditState.Disabled);
			nHeavyBluntVfx._debugPosition = debugPosition;
