		public static NSmallMagicMissileVfx? Create(Godot.Vector2 targetCenterPosition, Color tint)
		{
			if (TestMode.IsOn)
			{
				return null;
			}
			NSmallMagicMissileVfx nSmallMagicMissileVfx = PreloadManager.Cache.GetScene(scenePath).Instantiate<NSmallMagicMissileVfx>(PackedScene.GenEditState.Disabled);
			nSmallMagicMissileVfx.GlobalPosition = targetCenterPosition;
			nSmallMagicMissileVfx.Initialize();
			nSmallMagicMissileVfx.ModulateParticles(tint);
			return nSmallMagicMissileVfx;
		}

		private Godot.Vector2 GetProjectileDirection()
		{
			Godot.Vector3 vector = Godot.Quaternion.FromEuler(new Godot.Vector3(0f, 0f, Mathf.DegToRad(-30f))) * Godot.Vector3.Up;
			return new Godot.Vector2(vector.X, vector.Y).Normalized();
		}

		private Godot.Vector2 GetTopPosition(Godot.Vector2 projectileDirection)
		{
			return (Godot.Vector2)Geometry2D.LineIntersectsLine(base.GlobalPosition, projectileDirection, new Godot.Vector2(0f, 80f), Godot.Vector2.Right);
		}

