			if (nCreature == null)
			{
				this.QueueFreeSafely();
				return;
			}
			_label = GetNode<MegaLabel>("%Label");
			base.GlobalPosition = nCreature.GetTopOfHitbox();
			TaskHelper.RunSafely(StartVfx());
		}

