			{
				return null;
			}
			NStunnedVfx nStunnedVfx = PreloadManager.Cache.GetScene("res://scenes/vfx/stunned_vfx.tscn").Instantiate<NStunnedVfx>(PackedScene.GenEditState.Disabled);
