	public enum RumbleStyle
	{
		None,
		Rumble,
		Drunk
	}
	public class ScreenPunchInstance : ShakeInstance
	{
		public ScreenPunchInstance(float strength, double duration, float degAngle)
		{
			_strength = strength;
			_startDuration = duration;
			_duration = duration;
			_angle = Mathf.DegToRad(degAngle);
		}

		public override Godot.Vector2 Update(double delta)
		{
			if (base.IsDone)
			{
				return Godot.Vector2.Zero;
			}
			_duration -= delta;
			float x = (float)Math.Cos(_duration * (double)ShakeInstance.WiggleSpeed);
			_ease = Ease.CubicOut((float)(_duration / _startDuration));
			Godot.Vector2 result = new Godot.Vector2(x, 0f).Rotated(_angle) * _strength * _ease;
			if (_duration < 0.0)
			{
				base.IsDone = true;
			}
			return result;
		}

		public void Cancel()
		{
			_duration = 0.0;
			base.IsDone = true;
		}
	}
	public class ScreenRumbleInstance : ShakeInstance
	{
		private readonly FastNoiseLite _noise = new FastNoiseLite();

		private readonly float _randomOffset = Rng.Chaotic.NextFloat(99999f);

		private readonly float _speed = 10f;

		private Godot.Vector2 _targetOffset = Godot.Vector2.Zero;

		private readonly RumbleStyle _style;

		public ScreenRumbleInstance(float strength, double duration, float speedMultiplier, RumbleStyle style)
		{
			_noise.Frequency = ((style == RumbleStyle.Rumble) ? 6f : 0.1f);
			_noise.NoiseType = FastNoiseLite.NoiseTypeEnum.Perlin;
			_strength = strength * ((style == RumbleStyle.Rumble) ? 0.5f : 5f);
			_speed *= speedMultiplier;
			_startDuration = duration;
			_duration = duration;
			_style = style;
		}

		public override Godot.Vector2 Update(double delta)
		{
			if (base.IsDone)
			{
				return Godot.Vector2.Zero;
			}
			_duration -= delta;
			float num = (float)_duration;
			float noise1D = _noise.GetNoise1D(num + _randomOffset);
			float noise1D2 = _noise.GetNoise1D(num + _randomOffset + _randomOffset);
			_ease = Ease.CubicOut((float)(_duration / _startDuration));
			Godot.Vector2 result;
			if (_style == RumbleStyle.Drunk)
			{
				_targetOffset = _targetOffset.Lerp(new Godot.Vector2(noise1D, noise1D2), Mathf.Clamp((float)delta * _speed, 0f, 1f));
				result = _targetOffset * _strength * _ease;
			}
			else
			{
				result = new Godot.Vector2(noise1D, noise1D2) * _strength * _ease;
			}
			if (_duration < 0.0)
			{
				base.IsDone = true;
			}
			return result;
		}
	}
	public class ScreenTraumaRumble
	{
		private const float _rumbleAmount = 200f;

		private const float _speed = 1000f;

		private const float _decayRate = 2f;

		private const float _maxShake = 50f;

		private readonly FastNoiseLite _noise = new FastNoiseLite();

		private float _trauma;

		private double _duration;

		private float _multiplier;

		public ScreenTraumaRumble()
		{
			_noise.Frequency = 0.01f;
			_noise.Seed = Rng.Chaotic.NextInt(999999);
			_noise.NoiseType = FastNoiseLite.NoiseTypeEnum.Perlin;
		}

		public void AddTrauma(ShakeStrength amount)
		{
			float trauma = _trauma;
			_trauma = trauma + amount switch
			{
				ShakeStrength.VeryWeak => 0.07f, 
				ShakeStrength.Weak => 0.2f, 
				ShakeStrength.Medium => 0.4f, 
				ShakeStrength.Strong => 0.6f, 
				ShakeStrength.TooMuch => 1f, 
				_ => throw new ArgumentOutOfRangeException("amount", amount, null), 
			};
			_trauma = Mathf.Min(_trauma, 1f);
		}

		public Godot.Vector2 Update(double delta)
		{
			if (_trauma <= 0f)
			{
				return Godot.Vector2.Zero;
			}
			_duration += delta * 1000.0;
			float num = Mathf.Pow(_trauma, 1.5f) * 200f * _multiplier;
			float noise1D = _noise.GetNoise1D((float)_duration + 100f);
			float noise1D2 = _noise.GetNoise1D((float)_duration + 300f);
			Godot.Vector2 result = (new Godot.Vector2(noise1D, noise1D2) * num).LimitLength(50f);
			_trauma = Mathf.Max(_trauma - (float)(2.0 * delta), 0f);
			return result;
		}

		public void SetMultiplier(float multiplier)
		{
			_multiplier = multiplier;
		}
	}
	public enum ShakeDuration
	{
		None,
		Short,
		Normal,
		Long,
		Forever
	}
	public abstract class ShakeInstance
	{
		protected float _strength;

		protected double _startDuration;

		protected double _duration;

		protected float _ease;

		protected float _angle;

		protected static float WiggleSpeed => 60f;

		public bool IsDone { get; protected set; }

		public abstract Godot.Vector2 Update(double delta);
	}
	public enum ShakeStrength
	{
		None,
		VeryWeak,
		Weak,
		Medium,
		Strong,
		TooMuch
	}
}
