			NFailedJoinVfx nFailedJoinVfx = PreloadManager.Cache.GetScene(_scenePath).Instantiate<NFailedJoinVfx>(PackedScene.GenEditState.Disabled);
			nFailedJoinVfx.GetNode<MegaRichTextLabel>("%Label").SetTextAutoSize(text);
