			NCardRemoveVfx nCardRemoveVfx = PreloadManager.Cache.GetScene(scenePath).Instantiate<NCardRemoveVfx>(PackedScene.GenEditState.Disabled);
			nCardRemoveVfx._cardNode = cardNode;
			return nCardRemoveVfx;
