		public override void _Ready()
		{
			_totalPauses = Rng.Chaotic.NextInt(2, 7);
			_canPauseTimer = Rng.Chaotic.NextFloat(0.5f, 1.2f);
			_speed = Rng.Chaotic.NextFloat(3f, 5f);
