	/// Spine file.
	/// </summary>
	[GlobalClass]
	[ScriptPath("res://src/Core/Nodes/Vfx/Backgrounds/NKaiserCrabBossBackground.cs")]
	public class NKaiserCrabBossBackground : Node2D
	{
		private enum RightArmState
		{
			Default,
			Charging,
			Resting
		}

		public enum ArmSide
		{
			Left,
			Right
		}

		/// <summary>
