		private Godot.Vector2 _pos43 = new Godot.Vector2(-140f, 110f);

		private Godot.Vector2 _scale43 = new Godot.Vector2(1f, 1f);

		private Godot.Vector2 _pos169 = new Godot.Vector2(0f, 40f);

		private Godot.Vector2 _scale169 = new Godot.Vector2(0.89f, 0.89f);

