		public override void _Ready()
		{
			ConnectSignals();
			_closeLabel = GetNode<MegaLabel>("%CloseLabel");
		}

		public void SetLabel(string text)
		{
			_closeLabel.SetTextAutoSize(text);
		}

		protected override void OnFocus()
		{
			base.OnFocus();
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(this, "scale", Godot.Vector2.One * 1.05f, 0.05);
		}

		protected override void OnUnfocus()
		{
			base.OnUnfocus();
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(this, "scale", Godot.Vector2.One, 0.5).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
		}

		protected override void OnPress()
		{
			base.OnPress();
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(this, "scale", Godot.Vector2.One * 0.95f, 0.25).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
		}

		protected override void OnRelease()
		{
			base.OnRelease();
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(this, "scale", Godot.Vector2.One, 0.05);
			base.MouseFilter = MouseFilterEnum.Ignore;
			GetParent<NEpochInspectScreen>().Close();
		}

