			list.Add(new Godot.Bridge.MethodInfo(MethodName.GlowFlash, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, null, null));
			return list;
