		public static NStatEntry Create(string imgUrl)
		{
			NStatEntry nStatEntry = PreloadManager.Cache.GetScene(ScenePath).Instantiate<NStatEntry>(PackedScene.GenEditState.Disabled);
			nStatEntry._imgUrl = imgUrl;
			return nStatEntry;
		}

