		public override void _Ready()
		{
			SetPivotOffset(new Godot.Vector2(50f, base.Size.Y * 0.5f));
			_icon = GetNode<TextureRect>("%Icon");
			if (_imgUrl != null)
			{
				_icon.Texture = PreloadManager.Cache.GetTexture2D(_imgUrl);
			}
			_topLabel = GetNode<MegaRichTextLabel>("%TopLabel");
			_bottomLabel = GetNode<MegaRichTextLabel>("%BottomLabel");
			_controllerFocusReticle = GetNode<NSelectionReticle>("%SelectionReticle");
			ConnectSignals();
		}

		public void SetHoverTip(HoverTip hoverTip)
		{
			_hoverTip = hoverTip;
		}

		protected override void OnFocus()
		{
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(this, "scale", Godot.Vector2.One * 1.05f, 0.05);
			if (_hoverTip.HasValue)
			{
				if (base.GlobalPosition.X < GetViewport().GetVisibleRect().Size.X * 0.4f)
				{
					NHoverTipSet.CreateAndShow(this, _hoverTip)?.SetGlobalPosition(new Godot.Vector2(base.GlobalPosition.X - 392f, base.GlobalPosition.Y));
				}
				else
				{
					NHoverTipSet.CreateAndShow(this, _hoverTip)?.SetGlobalPosition(new Godot.Vector2(base.GlobalPosition.X + 532f, base.GlobalPosition.Y));
				}
			}
			if (NControllerManager.Instance.IsUsingDirectionalNavigation)
			{
				_controllerFocusReticle.OnSelect();
			}
		}

		protected override void OnUnfocus()
		{
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(this, "scale", Godot.Vector2.One, 0.5).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
			if (_hoverTip.HasValue)
			{
				NHoverTipSet.Remove(this);
			}
			_controllerFocusReticle.OnDeselect();
		}

