			float y = _noise.GetNoise1D((_time + 0.25f) * 0.1f) - 0.5f;
			_parent.GlobalPosition = _parent.GlobalPosition.Lerp(_targetPos + new Godot.Vector2(x, y) * 100f, (float)delta * 4f);
