		{
			ConnectSignals();
			_slider.SetValueWithoutAnimation(SaveManager.Instance.SettingsSave.VolumeAmbience * 100f);
			_slider.Connect(Godot.Range.SignalName.ValueChanged, Callable.From<double>(OnValueChanged));
