		private PackedScene _dropdownItemScene;

		private static readonly System.Collections.Generic.Dictionary<string, string> _languageCodeToName = new System.Collections.Generic.Dictionary<string, string>
		{
			{ "ARA", "العربية" },
			{ "BEN", "ব\u09be\u0982ল\u09be" },
			{ "CZE", "Čeština" },
			{ "DEU", "Deutsch" },
			{ "DUT", "Nederlands" },
