			_tween.TweenProperty(this, "position:y", _originalY - 120f, 0.25).SetTrans(Tween.TransitionType.Back).SetEase(Tween.EaseType.Out);
			_tween.TweenInterval(1.0);
			_tween.TweenProperty(this, "modulate:a", 0f, 0.5);
