		public override void _Ready()
		{
			_posOffset = new Godot.Vector2((0f - base.Size.X) / 2f, -35f);
		}

		public void Initialize(Player player)
		{
			_isEnabled = player.RunState.Players.Count == 1;
			base.Texture = player.Character.MapMarker;
			base.Visible = false;
		}

		public void ResetMapPoint()
		{
			base.Visible = false;
		}

		public void HideMapPoint()
		{
			if (_isEnabled)
			{
				_tween?.FastForwardToCompletion();
				_tween = CreateTween();
				_tween.TweenProperty(this, "scale", Godot.Vector2.Zero, 0.20000000298023224).From(Godot.Vector2.One);
				_tween.TweenCallback(Callable.From(delegate
				{
					base.Visible = false;
				}));
			}
		}

		public void SetMapPoint(NMapPoint node)
		{
			if (_isEnabled)
			{
				_tween?.FastForwardToCompletion();
				if (!base.Visible)
				{
					base.Visible = true;
					Godot.Vector2 vector = new Godot.Vector2(node.Size.X / 2f, 0f);
					base.Position = node.Position + vector + _posOffset;
					_tween = CreateTween();
					_tween.TweenProperty(this, "scale", Godot.Vector2.One, 0.20000000298023224).From(Godot.Vector2.Down);
					_tween.Parallel().TweenProperty(this, "position", base.Position + Godot.Vector2.Up * 25f, 0.20000000298023224).SetEase(Tween.EaseType.In)
						.SetTrans(Tween.TransitionType.Sine)
						.FromCurrent();
					_tween.TweenProperty(this, "position", base.Position, 0.75).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Elastic);
				}
			}
		}

