		protected override void ConnectSignals()
		{
			base.ConnectSignals();
			_bgPanel = GetNode<Control>("BgPanel");
			_hsv = (ShaderMaterial)_bgPanel.Material;
			_icon = GetNode<TextureRect>("Icon");
			_label = GetNode<MegaLabel>("Label");
