		public override void _Ready()
		{
			ConnectSignals();
			_image = GetNode<TextureRect>("Image");
			_label = GetNode<MegaLabel>("Label");
			_hsv = (ShaderMaterial)_image.Material;
			_showPosition = base.Position;
