		{
			get
			{
				List<string> list = new List<string>();
				list.Add(_scenePath);
				list.AddRange(NBestiaryEntry.AssetPaths);
				return list.ToArray();
			}
		}

		protected override Control? InitialFocusedControl => _bestiaryList.GetChildren().OfType<NBestiaryEntry>().FirstOrDefault();

