			}, null));
			list.Add(new Godot.Bridge.MethodInfo(MethodName.AddLayer, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, new List<Godot.Bridge.PropertyInfo>
			{
				new Godot.Bridge.PropertyInfo(Variant.Type.String, "layerName", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false),
				new Godot.Bridge.PropertyInfo(Variant.Type.String, "layerPath", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false)
			}, null));
