			Player.Creature.PowerRemoved += OnPowerAppliedOrRemoved;
			Player.Creature.Died += OnCreatureChanged;
			Player.RelicObtained += OnRelicObtained;
			Player.RelicRemoved += OnRelicRemoved;
			Player.PotionProcured += OnPotionProcured;
