			list.Add(new Godot.Bridge.MethodInfo(MethodName.Cleanup, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, null, null));
