		/// <summary>
		/// Lays out cards vertically, then horizontally, then sets the position and the size of the container according
		/// to the passed global start position and alignment.
		/// </summary>
		/// <param name="globalStartLocation">Where to start positioning nodes.</param>
		/// <param name="alignment">Which side of the global start location the cards should be placed on.</param>
		/// <returns></returns>
		public void LayoutResizeAndReposition(Godot.Vector2 globalStartLocation, HoverTipAlignment alignment)
		{
			Godot.Vector2 size = NGame.Instance.GetViewportRect().Size;
			Godot.Vector2 size2 = Godot.Vector2.Zero;
			Godot.Vector2 zero = Godot.Vector2.Zero;
			float b = 0f;
			foreach (Control tip in Tips)
			{
				tip.Position = zero;
				size2 = new Godot.Vector2(Mathf.Max(zero.X + tip.Size.X, size2.X), Mathf.Max(zero.Y + tip.Size.Y, size2.Y));
				zero += Godot.Vector2.Down * (tip.Size.Y + 4f);
				b = Mathf.Max(tip.Size.X, b);
			}
			switch (alignment)
			{
			case HoverTipAlignment.Right:
				base.GlobalPosition = globalStartLocation;
				break;
			case HoverTipAlignment.Left:
				base.GlobalPosition = globalStartLocation + Godot.Vector2.Left * size2.X;
				break;
			}
			base.Size = size2;
		}

