		{
			base.OnRelease();
			_loopTween?.Play();
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(_label, "scale", Godot.Vector2.One, 0.5).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
			_tween.TweenProperty(_arrow, "scale", Godot.Vector2.One, 0.5).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
		}

		protected override void OnPress()
		{
			base.OnPress();
			_loopTween?.Pause();
			_label.PivotOffset = _label.Size * 0.5f;
			_tween?.Kill();
			_tween = CreateTween().SetParallel();
			_tween.TweenProperty(_label, "scale", Godot.Vector2.One * 0.9f, 0.5).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
			_tween.TweenProperty(_arrow, "scale", Godot.Vector2.One * 0.9f, 0.5).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo);
			_isAnimating = false;
		}

