		{
			new LocString("events", "CRYSTAL_SPHERE.banter.REVEAL_BAD.1"),
			new LocString("events", "CRYSTAL_SPHERE.banter.REVEAL_BAD.2"),
			new LocString("events", "CRYSTAL_SPHERE.banter.REVEAL_BAD.3")
		};

