			if (!_beginningRun)
			{
				_lobby?.CleanUp(disconnectSession: true);
			}
		}

		private void AddGame()
		{
			Node root = GetTree().Root;
			root.AddChildSafely(_game);
			_game.RootSceneContainer.SetCurrentScene(this);
			TaskHelper.RunSafely(_game.Transition.FadeIn());
		}

