			_buttonImage.Modulate = Colors.White;
			_moveTween?.Kill();
			_moveTween = CreateTween();
			_moveTween.TweenProperty(this, "position", _showPos, 0.3499999940395355).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Back)
				.FromCurrent();
		}

