			_isEnabled = false;
			_moveTween?.Kill();
			_moveTween = CreateTween();
			_moveTween.TweenProperty(this, "position", _hidePos, 0.3499999940395355).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Expo)
