		internal static List<Godot.Bridge.MethodInfo> GetGodotMethodList()
		{
			List<Godot.Bridge.MethodInfo> list = new List<Godot.Bridge.MethodInfo>(2);
			list.Add(new Godot.Bridge.MethodInfo(MethodName.RefreshPlayerVotes, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, new List<Godot.Bridge.PropertyInfo>
