		private static readonly Godot.Vector2 _showPosRatio = new Godot.Vector2(1604f, 846f) / NGame.devResolution;

		private static readonly Godot.Vector2 _hidePosRatio = _showPosRatio + new Godot.Vector2(0f, 250f) / NGame.devResolution;

