			list.Add(new Godot.Bridge.MethodInfo(MethodName.CancelPress, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, null, null));
