		{
			base.AddCard();
			if (!base.Visible)
			{
				AnimIn();
			}
			Enable();
		}

		protected override void SetAnimInOutPositions()
		{
			_showPosition = NGame.Instance.Size - _posOffset;
			_hidePosition = _showPosition + _hideOffset;
		}

