				if (this.IsValid() && IsInsideTree())
				{
					_currentTween = CreateTween()?.SetParallel();
					_currentTween?.TweenProperty(this, "modulate:a", 0f, 0.20000000298023224).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Sine);
