			list.Add(new Godot.Bridge.MethodInfo(MethodName.Uninitialize, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, null, null));
			list.Add(new Godot.Bridge.MethodInfo(MethodName.RemoveExistingCards, new Godot.Bridge.PropertyInfo(Variant.Type.Nil, "", PropertyHint.None, "", PropertyUsageFlags.Default, exported: false), MethodFlags.Normal, null, null));
