			_tween = CreateTween();
			_tween.TweenProperty(base.CardNode, "position", base.Position, 0.15000000596046448).SetEase(Tween.EaseType.Out).SetTrans(Tween.TransitionType.Cubic);
			_tween.Play();
		}

