		private Godot.Vector2 _decimillipedeStrikeOffset = Godot.Vector2.Zero;

		private Tween? _attackTween;

		public override void _Ready()
		{
			_originPos = base.Position;
			_speed = (_leftSegment ? 0.1f : 0.05f);
			_magnitude = (_leftSegment ? 250f : 300f);
			_noise.NoiseType = FastNoiseLite.NoiseTypeEnum.Perlin;
			_noise.Frequency = 1f;
		}

		public override void _Process(double delta)
		{
			_time += (float)delta;
			float num = _time * _speed + (_leftSegment ? 0.25f : 0f);
			Godot.Vector2 vector = new Godot.Vector2(_noise.GetNoise1D(num), _noise.GetNoise1D(num + 0.25f)) * _magnitude;
			base.Position = _originPos + vector + _decimillipedeStrikeOffset;
		}

		public void AttackShake()
		{
			_attackTween?.Kill();
			_attackTween = CreateTween();
